local Text_AvgDialog = readonly({
  AvgDialog_100303_Content_1 = {
    Text = "Huff... huff... Non, ce n'est pas ça... quelque chose semble encore étrange..."
  },
  AvgDialog_100303_Content_10 = {
    Text = "Pourquoi est-ce juste devant moi, et pourtant je ne peux toujours pas le trouver..."
  },
  AvgDialog_100303_Content_11 = {
    Text = "Ne t'inquiète pas, Pickman. Puisque la Muse t'a déjà dit, la réponse doit être très proche de toi. Réfléchis bien, y a-t-il quelque chose que tu as oublié ."
  },
  AvgDialog_100303_Content_12 = {
    Text = "Avant cela, lève-toi... sss..."
  },
  AvgDialog_100303_Content_13 = {
    Text = "Tu retires brusquement ta main, voulant l'aider à se relever. Son corps brûlant semble comme si de la lave y coulait."
  },
  AvgDialog_100303_Content_14 = {
    Text = "Comme prévu, c'est encore Thais qui cause des problèmes..."
  },
  AvgDialog_100303_Content_15 = {
    Text = "Thais... Ah ! D'accord ! Comment ai-je pu ne pas penser à cela ! Comment ai-je pu le négliger !!"
  },
  AvgDialog_100303_Content_16 = {
    Text = "Il se redresse brusquement, ses yeux te fixant intensément, presque brûlants."
  },
  AvgDialog_100303_Content_17 = {
    Text = "Le désir le plus fou... C'est ça ! Je comprends, je comprends..."
  },
  AvgDialog_100303_Content_18 = {
    Text = "Il est tellement excité qu'il en oublie de se lever, rampant jusqu'à toi à quatre pattes."
  },
  AvgDialog_100303_Content_19 = {
    Text = "Gardien, peux-tu être à nouveau mon modèle ? Juste une fois ! Une seule fois !"
  },
  AvgDialog_100303_Content_2 = {Text = "Pickman ?"},
  AvgDialog_100303_Content_20 = {
    Text = "Je sais ce que tu veux faire, absolument pas..."
  },
  AvgDialog_100303_Content_21 = {
    Text = "Les yeux rouges de Pickman, pleins d'angoisse et de supplication, scintillent faiblement sous la lumière sombre. Les mots de refus ne peuvent plus sortir."
  },
  AvgDialog_100303_Content_22 = {
    Text = "...D'accord. Si c'est juste pour être modèle. Puis-je m'asseoir sur ce canapé ?"
  },
  AvgDialog_100303_Content_23 = {
    Text = "Non, non, non, Gardien ! Comment pouvez-vous créer une peinture comme celle-ci dans le studio ?!"
  },
  AvgDialog_100303_Content_24 = {Text = "新增"},
  AvgDialog_100303_Content_25 = {
    Text = "Est-ce que c'est... le monde de votre peinture ?"
  },
  AvgDialog_100303_Content_26 = {
    Text = "C'est exact ! C'est le rituel du carnaval des ghouls !"
  },
  AvgDialog_100303_Content_27 = {
    Text = "Je l'ai créé, mais je ne l'ai jamais fini. Il manque une paire de protagonistes au centre. Ils représentent les désirs les plus primitifs et sauvages de cet univers, les désirs que j'ai oubliés..."
  },
  AvgDialog_100303_Content_28 = {
    Text = "Je n'ai pas trouvé de modèle suffisant pour devenir le protagoniste jusqu'à présent..."
  },
  AvgDialog_100303_Content_29 = {
    Text = "Pickman reste à genoux, traînant ses genoux vers toi."
  },
  AvgDialog_100303_Content_3 = {
    Text = "L'atelier sombre de Pickman est plus en désordre que jamais, des feuilles de papier en cuir remplies de couleurs et de lignes éparpillées sans ordre dans chaque coin de l'atelier, comme si une étrange guerre venait de s'y dérouler."
  },
  AvgDialog_100303_Content_30 = {
    Text = "S'il vous plaît, Gardien... accordez-moi la Muse !"
  },
  AvgDialog_100303_Content_31 = {
    Text = "Tu peux me demander de faire n'importe quoi ! Une fois, juste une fois ! S'il te plaît, emporte-moi pour terminer cette œuvre..."
  },
  AvgDialog_100303_Content_32 = {
    Text = "Sans hésiter longtemps, tu soupiras doucement et t'approchas de lui."
  },
  AvgDialog_100303_Content_33 = {
    Text = "Il lève la tête, écarquillant les yeux pour te regarder. Ce sont des yeux qui appartiennent à une bête ou à un animal de compagnie, avides, désireux, dociles et fidèles. Il te supplie, suppliant une instruction qui le mène vers la muse."
  },
  AvgDialog_100303_Content_34 = {
    Text = "Tout est possible... Alors, je dois bien réfléchir..."
  },
  AvgDialog_100303_Content_35 = {
    Text = "Ta main se pose doucement sur le visage de Pickman. Sa respiration brûlante et son corps deviennent dociles. On ne sait pas si c'est toi qui le domptes, ou s'il est en train de te faire fondre."
  },
  AvgDialog_100303_Content_36 = {
    Text = "Les voix des goules commencent à s'estomper, tandis que les voix rugueuses et primitives de ce couple de protagonistes emplissent tout le monde de l'image."
  },
  AvgDialog_100303_Content_37 = {
    Text = "C'est la voix de la muse."
  },
  AvgDialog_100303_Content_4 = {
    Text = "Il est à genoux, vêtu de manière désordonnée, barbouillant frénétiquement une feuille de papier vierge, presque en train de déchirer le papier. La peinture éclaboussée recouvre son corps, comme un adepte d'un rite sauvage en cours."
  },
  AvgDialog_100303_Content_5 = {
    Text = "Que se passe-t-il..."
  },
  AvgDialog_100303_Content_6 = {
    Text = "Je l'ai entendu, Gardien ! J'ai entendu la voix de la Muse appeler ! Juste à mon oreille !"
  },
  AvgDialog_100303_Content_7 = {
    Text = "Mes yeux, mes mains, mon cœur, chaque cellule de mon corps tremble au son de cela !"
  },
  AvgDialog_100303_Content_8 = {
    Text = "Il ne reste qu'un pas ! Je suis à un pas du plus grand art !"
  },
  AvgDialog_100303_Content_9 = {
    Text = "Mais je ne peux pas le trouver... Meurtre, conquête, gourmandise, avidité, gaspi, néant... J'ai esquissé toute la folie, mais je ne l'ai toujours pas trouvée..."
  },
  AvgDialog_100588_Content_1 = {
    Text = "Une silhouette noire apparaît progressivement devant toi."
  },
  AvgDialog_100588_Content_2 = {
    Text = "[Attaque]???"
  },
  AvgDialog_100588_Content_3 = {
    Text = "Vous avez infligé 677 points de dommages ! Vous pensez avoir infligé un total de 27 188 points de dommages à lui. \n Tout le monde a infligé un total de 14 636 643 707 points de dommages, mais il ne tombe toujours pas."
  },
  AvgDialog_100588_Content_4 = {
    Text = "[Continuer]"
  },
  AvgDialog_100588_Content_5 = {
    Text = "Tu as l'impression d'être déjà venu ici…\nSous le regard de l'ombre, ta conscience devient progressivement floue."
  },
  AvgDialog_100588_Content_6 = {Text = "[Sommeil]"},
  AvgDialog_100629_Content_1 = {
    Text = "Pas longtemps après, ce monde n'était plus troublé par la dissolution, l'humanité se développait rapidement, et plus tard l'Université de Mythag intercepta un train dans le ciel étoilé…"
  },
  AvgDialog_10120_Content_1 = {
    Text = "Protégez votre appareil de commandement et méfiez-vous de la contamination par la Dissolution.\nIl sera essentiel dans la prochaine bataille."
  },
  AvgDialog_10120_Content_2 = {
    Text = "Maintenez la <Yellow:Command Card> et faites-la glisser vers la <Yellow:Central Command Zone> pour me donner un ordre d'action."
  },
  AvgDialog_10121_Content_1 = {
    Text = "<Yellow:Argent>? Je ne m'attendais pas à le trouver ici..."
  },
  AvgDialog_10121_Content_2 = {
    Text = "Fabriquez des Clés Argentées, reliez les Réveilleurs et fournissez de l'énergie spirituelle...\nTout dans Mythag tourne autour de <Yellow:Argent>."
  },
  AvgDialog_10121_Content_3 = {
    Text = "Même une petite quantité de <Yellow:Argent> a une valeur extraordinaire pour la recherche de Mythag.\nEssayez de les collecter tous."
  },
  AvgDialog_10122_Content_1 = {
    Text = "Traîner cela est désavantageux ; nous devons en venir à une conclusion rapide."
  },
  AvgDialog_10122_Content_2 = {
    Text = "Voici le <Yellow:\"Épée de la Reine\"> avec lequel je m'entraîne depuis mon enfance.\nFinissons-en avec ce coup !"
  },
  AvgDialog_10123_Content_1 = {
    Text = "Vous passez par la petite porte sous le clocher et entrez dans un passage dissimulé et clos."
  },
  AvgDialog_10123_Content_10 = {Text = "新增"},
  AvgDialog_10123_Content_11 = {
    Text = "La porte s'ouvre lentement, révélant pour la première fois la scène de l'endroit interdit"
  },
  AvgDialog_10123_Content_13 = {
    Text = "Sa moitié inférieure submergée dans la boue noire, l'obscurité dévorante accentue sa pureté radieuse, la rendant impeccablement blanche."
  },
  AvgDialog_10123_Content_14 = {
    Text = "Dans un état d'égarement, la silhouette inhumaine devant vous se superpose subtilement à celle de la jeune femme que vous avez vue dans la Tombe Clé."
  },
  AvgDialog_10123_Content_15 = {
    Text = "Cela n'a pas de visage, mais vous ressentez une certaine compassion de sa posture immobile."
  },
  AvgDialog_10123_Content_16 = {
    Text = "Suprême, Pur, Bon, Beau."
  },
  AvgDialog_10123_Content_17 = {
    Text = "<Shake:Tu... es arrivée...>"
  },
  AvgDialog_10123_Content_18 = {
    Text = "Le monstre blanc émet un son rauque, mi-roar, mi-gémissement."
  },
  AvgDialog_10123_Content_19 = {
    Text = "Ce n'est pas un langage humain, pourtant tu comprends le sens de ses mots."
  },
  AvgDialog_10123_Content_2 = {
    Text = "Doll mène le chemin devant, ses pas résonnant hollowement sur la surface métallique."
  },
  AvgDialog_10123_Content_20 = {
    Text = "Tout ce qui est devant vous devient soudainement flou. Vous clignez des yeux, et un liquide chaud coule sur votre joue."
  },
  AvgDialog_10123_Content_21 = {
    Text = "Est-ce une larme ? Mais pourquoi ? Qu'est-ce qui fait que ta poitrine se serre et que tes yeux piquent ?"
  },
  AvgDialog_10123_Content_22 = {
    Text = "......<Yellow:Tawil>？"
  },
  AvgDialog_10123_Content_23 = {
    Text = "Les mots que murmure Poupée font changer l'expression de Ramona."
  },
  AvgDialog_10123_Content_24 = {
    Text = "Tawil ? Celle qui est l'une des fondatrices, l'Éveilleuse Tawil ?"
  },
  AvgDialog_10123_Content_25 = {
    Text = "Vous vous souvenez aussi.\nDans <Blue:\"L'Histoire de Mythag\">, ce nom apparaît aux côtés de deux autres"
  },
  AvgDialog_10123_Content_26 = {
    Text = "Dans Alluvium 90, <Blue:Ward Phillips>, <Blue:Klararksh> et <Blue:Tawil> ont fondé <Blue:Mythag College>."
  },
  AvgDialog_10123_Content_27 = {
    Text = "C'est exactement là où vous êtes maintenant, le prédécesseur de <Blue:Mythag University (Mythag University)>."
  },
  AvgDialog_10123_Content_28 = {Text = "Gardien."},
  AvgDialog_10123_Content_29 = {
    Text = "Je suis ici."
  },
  AvgDialog_10123_Content_3 = {
    Text = "C'est la première fois que j'apprends qu'il y a un tel passage secret sous la tour de l'horloge..."
  },
  AvgDialog_10123_Content_30 = {
    Text = "Le fait que tu sois ici sans être expulsé par Tawil montre que ton destin est désormais inextricablement lié à l'avenir de Mythag."
  },
  AvgDialog_10123_Content_31 = {
    Text = "Alors, tu es qualifié pour entendre les informations que je suis sur le point de partager."
  },
  AvgDialog_10123_Content_32 = {
    Text = "C'est le secret le plus profond de l'Université Mythag.\nTawil—le fondateur de l'Université Mythag—n'est ni humain ni un Réveilleur."
  },
  AvgDialog_10123_Content_33 = {
    Text = "Il est un être d'une autre dimension. Au départ, il n'était qu'un murmure entendu par le premier principal, Phillips."
  },
  AvgDialog_10123_Content_34 = {
    Text = "Contrairement à la perception selon laquelle « Tawil est un Réveilleur », la technique d'extraction d'Argent et <Yellow:Éveiller les décédés qui résonnent avec la Volonté Supérieure> a émergé sous sa direction."
  },
  AvgDialog_10123_Content_35 = {
    Text = "Tawil a prophétisé l’arrivée de la Dissolution et l'avenir de la Destruction du monde, transmettant la \"Vérité\" initiale, puis s'est endormie après l'établissement du Collège de Mythag."
  },
  AvgDialog_10123_Content_36 = {
    Text = "Selon M. Phillips, Tawil a choisi une forme d'existence \"inexistante\" pour éviter \"d'être observé\"."
  },
  AvgDialog_10123_Content_37 = {
    Text = "Ce n'est que lorsque les \"Variables\" apparaissent qu'Il renaîtra sous la forme de \"Réveil\" —"
  },
  AvgDialog_10123_Content_38 = {Text = "Regarde !"},
  AvgDialog_10123_Content_39 = {
    Text = "Comme s'il annonçait l'arrivée de certains tabous et lignées, \"Tawil\" poussa un cri perçant qui brisa les tympans."
  },
  AvgDialog_10123_Content_4 = {
    Text = "Si tout le monde est au courant, je suppose que ça ne peut pas être appelé un passage secret.\nLe passage mène à la <Yellow:Black Pool>, la fondation de Mythag."
  },
  AvgDialog_10123_Content_40 = {
    Text = "Avec un tremblement semblable à celui d'un oisillon se libérant, six énormes ailes argentées se déploient de Son corps."
  },
  AvgDialog_10123_Content_41 = {
    Text = "Les pointes des ailes gouttent des gouttelettes d'argent, qui tombent dans le bassin noir avec un doux bruit."
  },
  AvgDialog_10123_Content_42 = {
    Text = "Dès que le liquide argenté fusionne avec le Lac Noir, des ondulations surgissent et des Corps Dissous tordus émergent."
  },
  AvgDialog_10123_Content_43 = {
    Text = "Les monstres déformés défient les lois physiques en éclatant de la piscine noire. Certains se précipitent vers vous, tandis que d'autres se dirigent vers la place devant la tour de l'horloge"
  },
  AvgDialog_10123_Content_44 = {
    Text = "<Shake:Enfin... trouvé... toi...>"
  },
  AvgDialog_10123_Content_45 = {
    Text = "Arrête-le ! Ce n'est qu'en l'arrêtant que nous pouvons couper la source des monstres !"
  },
  AvgDialog_10123_Content_5 = {
    Text = "Sans le <Yellow:giant Silver> appelé <Yellow:Core> au fond du Black Pool, compter uniquement sur les esprits humains faibles pour soutenir les Réveilleurs retarderait la technologie des Réveilleurs de Mythag de plusieurs décennies."
  },
  AvgDialog_10123_Content_6 = {
    Text = "Alors, ne pas permettre aux Réveilleurs non liés de quitter Mythag, c'est aussi par souci que nous pourrions sombrer dans la folie ?"
  },
  AvgDialog_10123_Content_7 = {
    Text = "Pas tout à fait.\nSi seulement chaque Réveilleur était aussi facile à gérer que toi, Ogier."
  },
  AvgDialog_10123_Content_8 = {
    Text = "D'accord, nous y sommes."
  },
  AvgDialog_10123_Content_9 = {
    Text = "Alors qu'elle parlait, Doll appuya sur un bouton peu visible sur le mur latéral du passage.\nAvec un ding, la porte s'ouvrit, et tu entra dans l'espace étroit faiblement éclairé."
  },
  AvgDialog_10124_Content_1 = {
    Text = "On dirait que vous avez trouvé votre État. Le prochain ordre est à vous, Gardien !"
  },
  AvgDialog_10125_Content_1 = {
    Text = "Ouf. Désolée, il n'y a pas le temps de vous acclimater à tout cela correctement."
  },
  AvgDialog_10125_Content_10 = {
    Text = "Ramona semble terrifiée ; vous ne l'avez jamais vue aussi déstabilisée."
  },
  AvgDialog_10125_Content_11 = {
    Text = "La jeune fille, assaillie de questions, parle d'une voix tremblante, sa fatigue évidente."
  },
  AvgDialog_10125_Content_12 = {
    Text = "Vous la reconnaissez. Elle s'appelle Professeur Poupée, connue pour être difficile à communiquer, et elle appartient à l'<Blue:Institut de Recherche du Réveil>. En d'autres termes, elle est non combattante."
  },
  AvgDialog_10125_Content_13 = {
    Text = "Évidemment. Vous pensiez que j'étais venue ici pour une promenade de santé ?"
  },
  AvgDialog_10125_Content_14 = {
    Text = "Elle ferme les yeux, reprenant rapidement contenance."
  },
  AvgDialog_10125_Content_15 = {
    Text = "Le Coffre de Clé a-t-il été attaqué ? Cet endroit est près de la porte arrière ; dépêchez-vous de partir."
  },
  AvgDialog_10125_Content_16 = {
    Text = "Nous pouvons aider ! %player% peut lier chacun d'entre nous et ensuite commander—"
  },
  AvgDialog_10125_Content_17 = {
    Text = "Ramona.\nCe sont nos responsabilités, %player% n'est qu'un nouvel arrivant qui vient de terminer l'école préparatoire."
  },
  AvgDialog_10125_Content_18 = {
    Text = "%player% a déjà établi un lien avec moi, et je sais que {Male=he,Female=she} est à la hauteur. Je crois en {Male=him,Female=her} !"
  },
  AvgDialog_10125_Content_19 = {
    Text = "Doll vous scrute du regard, puis se tourne vers Ramona avec une expression sévère."
  },
  AvgDialog_10125_Content_2 = {
    Text = "Ces Mutants ont atteint le Keygrave avant que l'alarme ne retentisse. La <Blue:Barrière de brume> autour du Mizag a dû tomber."
  },
  AvgDialog_10125_Content_20 = {
    Text = "Si ma mémoire est bonne, la cérémonie de serment a été interrompue. {Male=He,Female=She} n'a pas encore reçu sa {Male=his,Female=her} Clé d'argent, n'est–ce pas ?"
  },
  AvgDialog_10125_Content_21 = {
    Text = "Ensuite, nous entrerons dans la Zone Interdite de Mythag. L'entrée non autorisée est une infraction sérieuse, et je pensais que vous en étiez conscient depuis que vous avez grandi ici."
  },
  AvgDialog_10125_Content_22 = {
    Text = "C'est une urgence ! Nous n'avons pas le choix, n'est–ce pas ? Et puis, %player% n'est pas un simple première année. {Male=He's,Female=She's} notre seul Gardien."
  },
  AvgDialog_10125_Content_23 = {
    Text = "Vous ne vous souvenez pas de l'<Yellow:Explosion d'Akute> il y a un an ? Sans {Male=him,Female=her} qui a établi seul un lien avec tous les Corps éveillés à l'époque, je ne serais pas là à discuter avec vous en ce moment."
  },
  AvgDialog_10125_Content_24 = {
    Text = "La fille aux cheveux roses ne répond pas et se tourne plutôt vers vous."
  },
  AvgDialog_10125_Content_25 = {
    Text = "Je sais que vous avez entrevu ce qui se trouve au–delà de la <Yellow:Porte> ; mais la réalité, qu'il s'agisse des fondements du Mizag ou du destin du monde, n'est peut–être pas aussi idéale que vous l'imaginez."
  },
  AvgDialog_10125_Content_26 = {
    Text = "Nous faisons face à un phénomène qui détruit l'existence matérielle elle-même. Une fois que vous êtes contaminé par <Yellow:Dissolution>, tout ce qui vous concerne disparaîtra."
  },
  AvgDialog_10125_Content_27 = {
    Text = "Le nom que vous avez gravé sur la pierre tombale lors de la cérémonie de serment se dissoudra également dans une mare de boue noire, oublié de tous."
  },
  AvgDialog_10125_Content_28 = {
    Text = "Répondez–moi. Êtes–vous vraiment prêt pour cela ?"
  },
  AvgDialog_10125_Content_29 = {
    Text = "Le regard glacial de Doll croise le vôtre, sa voix est neutre."
  },
  AvgDialog_10125_Content_3 = {
    Text = "Nous avons informé <Blue:William, l'Aîné> de la cérémonie d'aujourd'hui, mais aucun renfort n'est venu à notre aide. La cloche... nous devrions nous regrouper et <Yellow:éliminer la source de l'anomalie> !"
  },
  AvgDialog_10125_Content_30 = {
    Text = "Son visage ne trahit rien, mais au plus profond de ses pupilles glacées, vous apercevez un feu ardent."
  },
  AvgDialog_10125_Content_31 = {
    Text = "Ta réponse est—"
  },
  AvgDialog_10125_Content_32 = {
    Text = "Ma pierre tombale fait désormais partie du Keygrave."
  },
  AvgDialog_10125_Content_33 = {
    Text = "Tu es membre du Mizag. Peut–être l'étais–tu déjà à Akute."
  },
  AvgDialog_10125_Content_34 = {
    Text = "Il y a des choses que moi seule peux accomplir."
  },
  AvgDialog_10125_Content_35 = {
    Text = "Cette décision est peut–être hâtive, mais peut–on jamais être véritablement préparé à tout dans la vie ?"
  },
  AvgDialog_10125_Content_36 = {Text = "Bien."},
  AvgDialog_10125_Content_37 = {
    Text = "Par l'autorité du 6ᵉ Directeur du Mizag, <Blue:Oliver Elsie>, je te confère par la présente la Clé d'argent K–0617."
  },
  AvgDialog_10125_Content_39 = {
    Text = "Doll récupère la Clé d'argent d'un écrin ouvragé et la dépose sur ta poitrine. Elle émet une faible lueur, te submergeant d'un vague sentiment de familiarité."
  },
  AvgDialog_10125_Content_4 = {
    Text = "Est-ce... ?!"
  },
  AvgDialog_10125_Content_40 = {
    Text = "Désormais, tu te tiens en tant que Gardien parmi la multitude d'étudiants et d'érudits du Mizag."
  },
  AvgDialog_10125_Content_41 = {Text = "新增"},
  AvgDialog_10125_Content_42 = {
    Text = "Bien, à présent, établis un lien avec moi."
  },
  AvgDialog_10125_Content_43 = {
    Text = "Vous activez prudemment la clé argentée.\nUne lumière argentée scintille, et le lien spirituel connecte vos sens à ceux de la Poupée comme des milliers de fils invisibles."
  },
  AvgDialog_10125_Content_44 = {
    Text = "Comme si un courant électrique se connectait avec un \"clic\", d'innombrables messages de lumière et d'ombre inondèrent ton esprit.\nSecoué par des palpitations intenses, tu peux à peine te tenir debout."
  },
  AvgDialog_10125_Content_45 = {
    Text = "Doll, toi..."
  },
  AvgDialog_10125_Content_46 = {
    Text = "Vous êtes arrivé juste à temps, Gardien.\nTous deux, Ogier et moi, sommes à nos limites."
  },
  AvgDialog_10125_Content_47 = {
    Text = "Vous restez ici et reposez-vous. Ramona et moi allons rejoindre la bataille pour soutenir Ogier."
  },
  AvgDialog_10125_Content_48 = {
    Text = "Calme-toi. Même si ton esprit peut le supporter, les blessures de Ramona ne sont pas adaptées pour un combat immédiat."
  },
  AvgDialog_10125_Content_49 = {
    Text = "L'enfant peut tenir un moment. Suis-moi d'abord."
  },
  AvgDialog_10125_Content_6 = {
    Text = "À la périphérie de votre vision, un jeune homme blond brandit un immense bouclier noir, repoussant à grand-peine l'assaut d'une épéiste à deux lames."
  },
  AvgDialog_10125_Content_7 = {
    Text = "Il protège une fille aux cheveux roses derrière lui, chaque attaque déviée le forçant à reculer d'un pas supplémentaire."
  },
  AvgDialog_10125_Content_8 = {
    Text = "Attendez... celui qui lance l'attaque... est <Yellow:Réveiller> Lotan?!"
  },
  AvgDialog_10125_Content_9 = {
    Text = "Dor ? La <Blue:Tour de l'horloge> est compromise ?!"
  },
  AvgDialog_10126_Content_1 = {
    Text = "Lorsque la Vie tombe à 0, le Pouvoir spirituel peinera à maintenir l'instrument pour continuer à détecter <Yellow:Domain>. Pour assurer la sécurité du personnel de combat, l'instrument te retirera de force du combat."
  },
  AvgDialog_10126_Content_2 = {
    Text = "La situation est urgente. J'ai ajusté la puissance de sortie de l'appareil en fonction des signes vitaux sains du Gardien et d'une charge complète d'Aliemus."
  },
  AvgDialog_10126_Content_3 = {
    Text = "Cette méthode est extrêmement périlleuse, mais nous n'avons pas d'autre choix que de prendre le risque. Maintenant, utilisez Exalter pour mettre fin à cette bataille !"
  },
  AvgDialog_10127_Content_1 = {
    Text = "Quelle chaleur... la connexion est parfaite. Ton esprit et ta force vitale n'ont jamais brillé aussi intensément."
  },
  AvgDialog_10127_Content_2 = {
    Text = "Vous ne pouvez pas tomber facilement, <Yellow:celui et l'unique au monde> Gardien.\nNous comptons sur vous pour enquêter et documenter toute l'histoire effacée par la Dissolution."
  },
  AvgDialog_10127_Content_3 = {
    Text = "L'inquiétude dans ses yeux s'estompe tandis que Ramona esquisse un demi-sourire rassurant."
  },
  AvgDialog_10127_Content_4 = {
    Text = "Le son de la pluie qui tombe remplit le monde."
  },
  AvgDialog_10127_Content_5 = {
    Text = "<Red:L'inquiétude, la douleur, l'étouffement> remplissaient ma poitrine quand une goutte de pluie est tombée."
  },
  AvgDialog_10127_Content_7 = {Text = "Ramona !"},
  AvgDialog_10127_Content_9 = {
    Text = "La cloche sonne."
  },
  AvgDialog_10128_Content_1 = {
    Text = "Faites attention, l'adversaire a adopté une forte posture offensive !"
  },
  AvgDialog_10128_Content_2 = {
    Text = [[
De quoi avez-vous peur ? Je suis encore ici.
Gardien, laissez-moi effectuer <Yellow:"Chirurgie Externe">.]]
  },
  AvgDialog_10129_Content_1 = {
    Text = "Activez la Clé d'Argent, %player%."
  },
  AvgDialog_10129_Content_2 = {
    Text = "La Clé d'Argent scintille, et une vision fugace apparaît soudainement, se mélangeant progressivement à la réalité sous vos yeux."
  },
  AvgDialog_10129_Content_3 = {
    Text = "Des vertiges, des pensées floues, une sirène hurlant dans la tête, et la voix de la Poupée commençait à s'estomper..."
  },
  AvgDialog_10129_Content_4 = {
    Text = "Vous luttez pour calmer votre esprit, discernant l'information fournie par la Poupée parmi les bavardages chaotiques."
  },
  AvgDialog_10129_Content_5 = {
    Text = "Vous le voyez ? Devant vous se trouve le Domaine—une zone spéciale formée par <Yellow:Rêve Dimension> et <Yellow:Réalité Dimension>."
  },
  AvgDialog_10129_Content_6 = {
    Text = "Mythag a projeté une partie de <Blue:Jonction> dans le Domaine pour stabiliser les esprits de plus en plus fous des Enquêteurs et soigner les Éveilleurs."
  },
  AvgDialog_10129_Content_7 = {
    Text = "Cependant, l'interférence humaine a des effets limités dans le domaine, donc nous ne pouvons pas garantir la position de <Blue:Junction>. Tout dépend de votre capacité d'adaptation."
  },
  AvgDialog_10129_Content_8 = {
    Text = "Allez au <Blue:Junction> le plus proche et aidez à soigner les blessures de Ramona."
  },
  AvgDialog_10130_Content_10 = {
    Text = "Tant que nos noms sont gravés sur le monument, notre existence ne sera pas effacée par @2."
  },
  AvgDialog_10130_Content_11 = {
    Text = "Une douce voix entrelacée de cris distordus résonne dans votre esprit."
  },
  AvgDialog_10130_Content_12 = {
    Text = "Je serai votre assistant, vous accompagnant jusqu'à la fin de ce chemin... <Yellow:Que la Clé d'Argent éclaire votre chemin.>"
  },
  AvgDialog_10130_Content_13 = {
    Text = "Tu vas bien, %player% ? Tu es un peu pâle. On devrait passer à l'infirmerie ?"
  },
  AvgDialog_10130_Content_14 = {
    Text = "Sa voix claire apporta de la clarté à l'esprit, et les vertiges se calmèrent progressivement."
  },
  AvgDialog_10130_Content_15 = {
    Text = "Pas de soucis, juste un peu de vertige, mais ça va mieux maintenant."
  },
  AvgDialog_10130_Content_16 = {
    Text = "Hmm, juste pour être sûr, restons liés.\nEn tant que ton assistant et partenaire, c’est mon devoir de toujours vérifier ton État."
  },
  AvgDialog_10130_Content_17 = {
    Text = "Maintenant ? Ici, dehors ?"
  },
  AvgDialog_10130_Content_18 = {
    Text = "C'est peut-être un peu plus tôt que prévu, mais ça ne devrait pas poser de problème, non ?"
  },
  AvgDialog_10130_Content_19 = {
    Text = "Et puis, j'attends ce jour avec impatience depuis plus d'un an maintenant."
  },
  AvgDialog_10130_Content_2 = {
    Text = "Bienvenue à l'Université Mythag, %player%."
  },
  AvgDialog_10130_Content_21 = {
    Text = "Des gouttes de pluie se glissent dans tes gants, mouillant le bout de tes doigts. Un faible courant s'infiltre à travers le tissu, circulant secrètement entre ta peau et la sienne."
  },
  AvgDialog_10130_Content_22 = {
    Text = "Des émotions inexplicables déferlent à travers tes nerfs — joie, excitation, inquiétude, et..."
  },
  AvgDialog_10130_Content_23 = {
    Text = "...<Yellow:Espoir>."
  },
  AvgDialog_10130_Content_3 = {
    Text = "Ou plutôt... bienvenue, tu as officiellement pénétré le côté caché du monde."
  },
  AvgDialog_10130_Content_4 = {
    Text = "Je suis de retour."
  },
  AvgDialog_10130_Content_5 = {
    Text = "Votre arrivée est ce que tout le monde espérait. Dans deux jours, William nous assignera une <Yellow:Task d'Investigation Clades>."
  },
  AvgDialog_10130_Content_6 = {
    Text = "Il ne t'épargnera pas, un Gardien qui se présente une fois par siècle."
  },
  AvgDialog_10130_Content_7 = {
    Text = "J'espère que ta mission sur le terrain @1 n'est pas aussi dépendante de moi, le <Blue:>, qu'un cours de calcul."
  },
  AvgDialog_10130_Content_8 = {
    Text = "Je n'aurais jamais pensé que j'assisterais à mes propres funérailles."
  },
  AvgDialog_10130_Content_9 = {
    Text = "Embrassez la mort, afin que nous n'en ayons plus peur."
  },
  AvgDialog_10131_Content_1 = {
    Text = "Maintenant, Ogier et moi entrons dans la bataille."
  },
  AvgDialog_10131_Content_2 = {
    Text = "Je peux sentir à travers le lien que ton état et celui d'Ogier ne sont pas encore suffisants pour"
  },
  AvgDialog_10131_Content_3 = {
    Text = "C'est bon, Gardien.\nLes chevaliers existent pour protéger tout le monde, et Ogier peut tenir le coup !"
  },
  AvgDialog_10131_Content_4 = {
    Text = "Ne t'inquiète pas. Avec toi ici pour stabiliser nos esprits, nous ne perdrons pas le contrôle et pourrons tirer le meilleur parti d'Aliemus."
  },
  AvgDialog_10131_Content_5 = {
    Text = "Tant que je rassemble suffisamment d'Aliemus, je peux récupérer mon État."
  },
  AvgDialog_10131_Content_6 = {
    Text = "Ne hésitez plus, Gardien.\nQue nous puissions percer l'encerclement dépend de votre commande."
  },
  AvgDialog_10131_Content_7 = {
    Text = "Laissez-moi juger par moi-même de la valeur de ce prodige sur lequel les Mizags misent leur avenir !"
  },
  AvgDialog_10132_Content_1 = {
    Text = "Hmph, tu penses que tu peux détruire cette planète ?"
  },
  AvgDialog_10132_Content_2 = {
    Text = "Bien loin d'être suffisant ! Vas-y, peu importe combien il y en a encore !"
  },
  AvgDialog_10133_Content_1 = {
    Text = "Est-ce que c'est... fini... ?"
  },
  AvgDialog_10133_Content_10 = {
    Text = "Elle tendit la main et toucha légèrement la Clé d'Argent sur ta poitrine"
  },
  AvgDialog_10133_Content_11 = {
    Text = "La Clé en Argent émet une faible réponse."
  },
  AvgDialog_10133_Content_12 = {
    Text = "Vous êtes la variable, la réponse à la fois au début et à la fin."
  },
  AvgDialog_10133_Content_13 = {
    Text = "Espérons que tu es le tournant..."
  },
  AvgDialog_10133_Content_15 = {
    Text = "Des monstres blancs à six ailes, une femme avec une expression indifférente, des monstres de boue éparpillés dans une attaque, des formes d'Éveilleurs tordues et ombragées..."
  },
  AvgDialog_10133_Content_16 = {
    Text = "Ils se sont tous transformés en une mare d'eau noire puis ont disparu sans laisser de trace."
  },
  AvgDialog_10133_Content_17 = {
    Text = "En ignorant les appels de Ramona et de la Poupée, vous levez les yeux en tenant la clé en argent, regardant vers la \"porte\" menant à \"Tawil.\""
  },
  AvgDialog_10133_Content_18 = {
    Text = "Vous vous souvenez clairement du visage que vous venez de voir.\nL'expression indifférente, les contours des sourcils et des yeux, et la courbe des lèvres ressemblent toutes à Ramona—"
  },
  AvgDialog_10133_Content_19 = {
    Text = "—Identique."
  },
  AvgDialog_10133_Content_2 = {
    Text = "\"Tawil\" reste debout, mais plus avec le même calme."
  },
  AvgDialog_10133_Content_20 = {
    Text = "Deux jours plus tard\n\nTombeau des clés"
  },
  AvgDialog_10133_Content_21 = {
    Text = "...L'Université Mythag est un pionnier dans la lutte contre la Dissolution, servant de ligne de défense cruciale pour l'avenir de l'humanité."
  },
  AvgDialog_10133_Content_22 = {
    Text = "Depuis 300 ans, l'Université de Mythag a payé un lourd tribut pour protéger la paix de l'humanité contre la Dissolution."
  },
  AvgDialog_10133_Content_23 = {
    Text = "Ce cimetière est notre lieu de repos préparé, et aussi la résolution des enseignants et des étudiants de Mythag à sacrifier leur vie pour la survie de l'humanité."
  },
  AvgDialog_10133_Content_24 = {
    Text = "Le discours continua. Czort ferma les yeux et soupira, la brume blanche de son souffle se dissipant sous la pluie."
  },
  AvgDialog_10133_Content_25 = {
    Text = "...Je crois que, parmi tous les nouveaux étudiants, aucun ne peut saisir le poids de ces mots mieux que toi."
  },
  AvgDialog_10133_Content_26 = {
    Text = "Au cours des 300 dernières années, des anomalies telles que les Argents et les Mutants de Dissolution ont occasionnellement émergé dans le Bassin Noir, mais une mutation de cette ampleur est sans précédent."
  },
  AvgDialog_10133_Content_27 = {
    Text = "Beaucoup ne sont jamais revenus."
  },
  AvgDialog_10133_Content_28 = {
    Text = "Le locuteur est Czort, le Doyen par intérim des Sciences de la Vie de Mythag. On dit qu'elle peut voir des êtres d'autres mondes et qu'elle était l'élève favorite de l'ancien doyen."
  },
  AvgDialog_10133_Content_29 = {
    Text = "Les événements liés à la Dissolution viennent toujours avec des surprises, de la folie et la mort. C'est une expérience inévitable sur notre chemin."
  },
  AvgDialog_10133_Content_3 = {
    Text = "Avant que quiconque puisse réagir, il déploie soudainement ses ailes d'argent et se jette sur Ramona."
  },
  AvgDialog_10133_Content_30 = {
    Text = [[
Vous comprenez le sens des mots de Czort.
Il n'y a personne sous la pierre tombale devant vous.]]
  },
  AvgDialog_10133_Content_31 = {
    Text = "La boue noire coule lentement sur la pierre tombale."
  },
  AvgDialog_10133_Content_32 = {Text = "新增"},
  AvgDialog_10133_Content_33 = {
    Text = "Après la cérémonie, le Noble Dexter vous a invité dans son bureau."
  },
  AvgDialog_10133_Content_34 = {
    Text = "Le nom \"Dexter\" vous est familier ; c'est le nom de famille de Ramona.\nCe \"Noble Dexter\" est votre professeur et aussi le père adoptif de Ramona."
  },
  AvgDialog_10133_Content_35 = {
    Text = "J'ai vu cette partie dans le rapport, et je dois vous demander une faveur."
  },
  AvgDialog_10133_Content_36 = {
    Text = "À propos de l'apparence de Tawil... pourrais-tu garder ça secret pour Ramona ?"
  },
  AvgDialog_10133_Content_37 = {Text = "Pourquoi ?"},
  AvgDialog_10133_Content_38 = {
    Text = "Comment devrais-je le dire... la causalité derrière cela est plutôt complexe et difficile à expliquer brièvement."
  },
  AvgDialog_10133_Content_39 = {
    Text = "Cependant, je lui ferai savoir tôt ou tard, juste pas à ce moment."
  },
  AvgDialog_10133_Content_4 = {
    Text = "Le temps semble s'être arrêté."
  },
  AvgDialog_10133_Content_40 = {
    Text = "Ce n'est pas en raison des considérations de confidentialité de Mythag, mais d'une demande de père pour protéger sa fille."
  },
  AvgDialog_10133_Content_41 = {
    Text = "S'il vous plaît, donnez-nous un peu de temps, d'accord ?"
  },
  AvgDialog_10133_Content_42 = {
    Text = "Même si tu souhaites connaître la vérité, tu hoches toujours la tête en signe d'accord."
  },
  AvgDialog_10133_Content_43 = {
    Text = "Merci pour votre compréhension.\nÀ propos, un lot de whisky royal vient d'arriver récemment. J'ai réussi à faire mettre de côté deux bouteilles secrètement."
  },
  AvgDialog_10133_Content_44 = {
    Text = "Ici, prends-le et invite Ramona à goûter à la saveur de l'âge adulte — considère cela comme ton rituel d'initiation exclusif, qu'en dis-tu ?"
  },
  AvgDialog_10133_Content_45 = {
    Text = "J'ai peur que ce ne soit pas approprié, Noble Dexter.\nDissolution ne cessera pas de se répandre pendant que nous reposons."
  },
  AvgDialog_10133_Content_46 = {
    Text = "Oh non, William a trouvé son chemin jusqu'ici.\nJ'ai bien peur de ne pas pouvoir te sauver maintenant, petit."
  },
  AvgDialog_10133_Content_47 = {
    Text = "Le dossier a été organisé. Vous pouvez vous préparer pour votre mission maintenant, nouveau Gardien."
  },
  AvgDialog_10133_Content_48 = {
    Text = "Que la Clé d'argent éclaire mon chemin."
  },
  AvgDialog_10133_Content_5 = {
    Text = "Vous avez sprinté à votre vitesse maximale, parvenant à peine à protéger Ramona."
  },
  AvgDialog_10133_Content_6 = {
    Text = "Le monstre blanc vous fixe directement."
  },
  AvgDialog_10133_Content_7 = {
    Text = "Il vous regarde silencieusement avec son corps pâle et sans visage."
  },
  AvgDialog_10133_Content_9 = {
    Text = "Devant vous se trouve le visage d'une femme avec une expression indifférente."
  },
  AvgDialog_10134_Content_1 = {
    Text = "Hé, toi ! Dépêche-toi et laisse-moi libérer <Yellow:\"Lame de Défiance\">."
  },
  AvgDialog_10134_Content_2 = {
    Text = "Attendez, Gardien.\nD'abord, libérez \"Frappe\", enflammant la soif de sang de Lotan, ce qui peut réduire la consommation d'Arithmetica de <Yellow:\"Lame de Défi\">."
  },
  AvgDialog_10134_Content_3 = {
    Text = "La bonne combinaison de commandes peut doubler l'efficacité de nos attaques.\nLes tactiques sont cachées dans les commandes, Gardien. Réfléchissez soigneusement."
  },
  AvgDialog_10135_Content_1 = {
    Text = "Faites attention, ne vous approchez pas ! Mon bouclier est sur le point de se briser !"
  },
  AvgDialog_10135_Content_10 = {
    Text = "Vous savez, personne d'autre ne peut le faire sauf moi."
  },
  AvgDialog_10135_Content_11 = {
    Text = "Lorsque ils me louent, c'est \"une fois par siècle\", mais quand une réelle crise arrive, je suis traité comme un vase. Ce n'est pas juste."
  },
  AvgDialog_10135_Content_12 = {
    Text = "Certaines risques doivent être affrontés."
  },
  AvgDialog_10135_Content_13 = {
    Text = "Nous n'avons pas le choix. Trop de personnes ici ont perdu le contrôle. Si nous ne résistons pas, nous serons consumés par la folie."
  },
  AvgDialog_10135_Content_14 = {
    Text = "De plus, nous deux seuls ne pouvons pas briser l'encerclement autour de l'horloge.\nNous avons besoin d'aide. Nous avons besoin du pouvoir de contrôler les Réveilleurs."
  },
  AvgDialog_10135_Content_15 = {
    Text = "Ramona, soutiens-moi."
  },
  AvgDialog_10135_Content_16 = {
    Text = "Puisque tu es si déterminé... en tant que \"partenaire\", je n'ai plus de raison de t'arrêter."
  },
  AvgDialog_10135_Content_17 = {
    Text = "Ramona, toujours prête à la bataille !"
  },
  AvgDialog_10135_Content_2 = {
    Text = "Avec un \"clang\", les épées jumelles de Lotan brisèrent à nouveau le gigantesque bouclier formé de boue noire."
  },
  AvgDialog_10135_Content_3 = {
    Text = "Pas assez, pas assez ! Déclenche la tempête ! Donne-moi une bataille exaltante !"
  },
  AvgDialog_10135_Content_4 = {
    Text = "L'Éveillé nommé Lotan manié ses lames jumelles, attaquant sans relâche Ogier. La puissance de ses attaques révélait une dure réalité—elle avait complètement perdu le contrôle."
  },
  AvgDialog_10135_Content_5 = {
    Text = "Étant donné la situation, nous ne pouvons qu'..."
  },
  AvgDialog_10135_Content_6 = {
    Text = "Ramona, aide-moi à maîtriser Lotan !"
  },
  AvgDialog_10135_Content_7 = {
    Text = "Vous ne pouvez pas être en train de penser à..."
  },
  AvgDialog_10135_Content_8 = {
    Text = "Je vais la lier !"
  },
  AvgDialog_10135_Content_9 = {
    Text = "Ne rigolez pas, la perte de contrôle d'un Réveilleur résonne avec l'Enquêteur à travers le Lien, même vous—"
  },
  AvgDialog_10136_Content_1 = {
    Text = "C'est... la fière <Yellow:\"Lame de Défiance\"> de Lotan, capable de lancer plusieurs attaques instantanément !"
  },
  AvgDialog_10136_Content_2 = {
    Text = "Pour contrer ce mouvement... utilisez <Yellow:\"Analyse Offensive\"> pour éviter les points faibles critiques. C'est plus sûr."
  },
  AvgDialog_10137_Content_1 = {
    Text = "Vous ne pouvez pas m'arrêter ! ...Des humains sans scrupules..."
  },
  AvgDialog_10137_Content_2 = {
    Text = "Vous touchez la Clé Argent nouvellement acquise, ressentant une légère vibration vous incitant à compléter la Résonance avec Lotan."
  },
  AvgDialog_10137_Content_4 = {
    Text = "<Shake:Si seulement j'avais su... Je n'aurais jamais accepté un pacte avec toi...>"
  },
  AvgDialog_10137_Content_5 = {
    Text = "Ramona s'approcha de Lotan et tendit la main."
  },
  AvgDialog_10137_Content_6 = {
    Text = "Je sais, quand tu as été éveillé, Mythag a promis de se battre à tes côtés... Combattre jusqu'à la fin de cette planète."
  },
  AvgDialog_10137_Content_7 = {
    Text = "Nous n'avons jamais eu l'intention de rompre notre promesse. Pendant les 300 dernières années et les 300 prochaines années, nous continuerons à porter ce fardeau."
  },
  AvgDialog_10137_Content_8 = {
    Text = "Lotan, la bataille intense que vous attendiez est juste devant vos yeux."
  },
  AvgDialog_10138_Content_1 = {
    Text = "Restez alerte, il est sur le point d'attaquer. Ce dégât pourrait être fatal pour moi en ce moment."
  },
  AvgDialog_10138_Content_2 = {
    Text = "Faites confiance à votre choix. Pour l'action de ce tour, choisissez <Yellow:\"Défense\">."
  },
  AvgDialog_10139_Content_1 = {
    Text = "Merci, Gardien. Vous m'avez sauvé encore une fois.\nSi ce n'était pas pour ce Lien, je serais probablement en grand danger en ce moment."
  },
  AvgDialog_10139_Content_2 = {
    Text = "Ce n'est pas le moment d'en parler —"
  },
  AvgDialog_10139_Content_3 = {
    Text = "Alors que vous parlez, l'anomalie noire jette se propage autour de vous.\nDes cris résonnent continuellement alors que vos camarades de classe de la veille se transforment en boue noire un par un."
  },
  AvgDialog_10139_Content_4 = {
    Text = "J'ai partagé l'<Yellow:intention> de l'ennemi détectée par la Clé argentée via le lien. Fais attention, il est sur le point d'attaquer !"
  },
  AvgDialog_10140_Content_1 = {
    Text = "Sens-tu l'Aliemus circulant en moi, Gardien ?\nGrâce à ta suppression avec le pouvoir spirituel, cela ne m'aurait pas plongé dans la Folie comme Lotan."
  },
  AvgDialog_10140_Content_2 = {
    Text = "Cependant, cela peut maintenant nous être utile."
  },
  AvgDialog_10140_Content_3 = {
    Text = "Regarde dans la direction où coule Aliemus... Oui, regarde le <Blue:coin supérieur gauche> de l'appareil de commande."
  },
  AvgDialog_10140_Content_4 = {
    Text = "Libérez Exalt et embrassez mon <Yellow:\"Mundus Deduction\">! \nPendant la bataille contre la Dissolution, <Yellow:seule une réponse rationnelle à l'offensive peut garantir la plus grande chance de survie>."
  },
  AvgDialog_10141_Content_1 = {
    Text = "Damn, Lotan est sur le point de lâcher <Yellow:Exalt>... Avec juste ces commandes..."
  },
  AvgDialog_10141_Content_2 = {
    Text = "La Clé en Argent se connecte à votre esprit, résonnant de manière unique avec vos fortes perceptions et souvenirs, générant une puissance distinctive."
  },
  AvgDialog_10141_Content_3 = {
    Text = "Regarde le <Blue:coin inférieur gauche> du dispositif de commande ! La clé en argent est complètement chargée, et le <Yellow:posse> est prêt."
  },
  AvgDialog_10141_Content_4 = {
    Text = "Saisissez la Clé d'Argent, chantez le texte secret... libérez <Yellow:Posse>, et donnez-moi plus d'espace tactique !"
  },
  AvgDialog_10142_Content_2 = {
    Text = "Ne te déconcentre pas pendant une cérémonie si importante, <Yellow:Gardien>, tu seras récompensé avec la Clé d'Argent ensuite."
  },
  AvgDialog_10142_Content_3 = {
    Text = "Érigez votre pierre tombale pour prouver notre détermination à lutter <Yellow:contre la Dissolution>—une tradition de Mythag, marquant la fin de la pré-étude et devenant des Enquêteurs officiels."
  },
  AvgDialog_10142_Content_4 = {
    Text = "Si vous êtes prêt, gravez votre nom sur la pierre tombale."
  },
  AvgDialog_116003_Content_1 = {
    Text = "Alors que le peintre de l'arbre de ta maison s'effondre, tout autour de toi se dissout dans la distorsion."
  },
  AvgDialog_116003_Content_10 = {
    Text = "Mais je ne souhaite pas que ce ne soit qu'un rêve."
  },
  AvgDialog_116003_Content_11 = {
    Text = "Je veux retourner à Mizag, je veux les revoir."
  },
  AvgDialog_116003_Content_12 = {
    Text = "...Réponse attendue."
  },
  AvgDialog_116003_Content_13 = {
    Text = "Mais cette fois, après que tu aies montré ta détermination, je peux enfin être tranquille."
  },
  AvgDialog_116003_Content_14 = {
    Text = "%player%, ta volonté est plus résiliente et plus puissante que je ne l'imaginais... suffisante pour lutter contre Lui et le chaos et la folie de ce monde."
  },
  AvgDialog_116003_Content_15 = {
    Text = "Tu secoues la tête, regardant Clémentine dans ce rêve magnifique sur le point de se briser complètement."
  },
  AvgDialog_116003_Content_16 = {
    Text = "Non, tu as tort, la volonté d'une personne a toujours des limites."
  },
  AvgDialog_116003_Content_17 = {
    Text = "Je peux tenir jusqu'à présent grâce au soutien de chacun à Mizag."
  },
  AvgDialog_116003_Content_18 = {
    Text = "«Cet univers» qu'ils ont ensemble construit pour toi ce rêve merveilleux, et toi, tu as la résolution de transformer ce rêve en réalité dans ce monde."
  },
  AvgDialog_116003_Content_19 = {
    Text = "En entendant tes mots et en voyant ton expression sérieuse, Clémentine sourit, affichant un sourire détendu."
  },
  AvgDialog_116003_Content_2 = {
    Text = "Tu as brisé de tes propres mains ton beau rêve."
  },
  AvgDialog_116003_Content_20 = {
    Text = "Oui, tu as encore « eux », tu as encore Tawil... et moi."
  },
  AvgDialog_116003_Content_21 = {
    Text = "C'est vrai. Je n'ai jamais été seul."
  },
  AvgDialog_116003_Content_22 = {
    Text = "Dans le paysage en constante fusion, un hurlement retentit, c'était la réponse de Tawil à tes mots.\nElle a toujours été là."
  },
  AvgDialog_116003_Content_23 = {
    Text = "Alors, maintenant, %player%, ton beau rêve est vraiment terminé."
  },
  AvgDialog_116003_Content_24 = {
    Text = "En guise de remerciement pour ta coopération lors de ce traitement, je t'offre un petit cadeau, j'espère que cela te plaira."
  },
  AvgDialog_116003_Content_25 = {
    Text = "Avec les dernières paroles de Clémentine, le rêve se brise complètement —"
  },
  AvgDialog_116003_Content_26 = {
    Text = "Un ciel de soleil noir se dresse devant toi, apportant une brume grise et la cruauté de ce monde."
  },
  AvgDialog_116003_Content_27 = {
    Text = "Et ta paume, pose tranquillement une photo. \n Une photo prise dans « un beau rêve illusoire », qui ne devrait pas exister dans la réalité cruelle."
  },
  AvgDialog_116003_Content_28 = {
    Text = "Plage, volley-ball, réjouissance, la seule différence avec mes souvenirs est Ramona."
  },
  AvgDialog_116003_Content_29 = {
    Text = "Un visage familier sourit tranquillement, comme s'il avait traversé le temps et l'espace pour croiser ton regard. \n Comme si c'était juste devant toi."
  },
  AvgDialog_116003_Content_3 = {
    Text = "Depuis que j'ai décidé de m'appuyer sur leur force pour construire ce rêve, je savais que ce jour finirait par arriver."
  },
  AvgDialog_116003_Content_30 = {
    Text = "<Small:Ramona…>"
  },
  AvgDialog_116003_Content_31 = {
    Text = "Tu mets ta main sur la photo, un mélange d'émotion et de doute envahissant ton cœur."
  },
  AvgDialog_116003_Content_32 = {
    Text = "<Shake:Pourquoi ce serait Ramona…>"
  },
  AvgDialog_116003_Content_33 = {
    Text = "Tes questions restent sans réponse. \n Dans ce monde enveloppé de brouillard gris, seul le soleil noir silencieux demeure inchangé."
  },
  AvgDialog_116003_Content_34 = {
    Text = "Quoi qu'il en soit..."
  },
  AvgDialog_116003_Content_35 = {
    Text = "Tu mets la photo sur ta poitrine, à l'endroit où se trouve ton cœur, et tu fermes les yeux."
  },
  AvgDialog_116003_Content_36 = {
    Text = "Quoi qu'il en soit, je ne suis pas seul."
  },
  AvgDialog_116003_Content_37 = {
    Text = "Puis, tu ouvres les yeux et regardes ce soleil noir suspendu, marchant résolument vers lui."
  },
  AvgDialog_116003_Content_38 = {
    Text = "Ce monde continue de s'effondrer, épie par une horreur indescriptible, en danger, mais…"
  },
  AvgDialog_116003_Content_39 = {
    Text = "<Big:Tu finiras par trouver un moyen de le sauver>"
  },
  AvgDialog_116003_Content_4 = {
    Text = "Je ne m'attendais pas à ce que cela arrive si vite, ni à ce que tu sois si déterminé."
  },
  AvgDialog_116003_Content_5 = {
    Text = "En fait... J'ai hésité et fui, quand j'étais au bord de la mer."
  },
  AvgDialog_116003_Content_6 = {
    Text = "Alors pourquoi ne pas continuer à sombrer ici ? N'est-ce pas un endroit assez beau, assez heureux ?"
  },
  AvgDialog_116003_Content_7 = {
    Text = "Tu restes silencieux, te remémorant ta peinture de l'arbre-maison."
  },
  AvgDialog_116003_Content_8 = {
    Text = "Il est indéniable que c'est vraiment un beau rêve. Mais..."
  },
  AvgDialog_116003_Content_9 = {
    Text = "Peu à peu, les scènes dans ton esprit ne sont plus des peintures, mais la véritable Mizag, la véritable Doll, Ramona, Lotan et Ogier."
  },
  AvgDialog_117499_Content_1 = {
    Text = "<Shake:Trop, trop...>"
  },
  AvgDialog_117499_Content_2 = {
    Text = "Sous le ciel assombri, la tempête de banc de poissons semble sans fin. Tu regardes autour de toi, une échelle en métal rouillé pend dans un coin, tu te faufiles prudemment vers la plateforme du deuxième étage le long de celle-ci."
  },
  AvgDialog_117499_Content_3 = {
    Text = "Ici, on peut se cacher temporairement."
  },
  AvgDialog_117499_Content_4 = {
    Text = "Une odeur de tromperie, accompagnée d'un bruit de frottement désagréable, attire votre attention."
  },
  AvgDialog_117499_Content_5 = {
    Text = "Attends, c'est là-bas..."
  },
  AvgDialog_117500_Content_1 = {Text = "Menottes"},
  AvgDialog_117500_Content_10 = {Text = "新增"},
  AvgDialog_117500_Content_100 = {
    Text = "Murphy secoua la tête avec désespoir, ses yeux vides cherchant ton emplacement. \n Elle se tourna vers toi, serrant ses lèvres gercées par le manque de sang, forçant un sourire pâle."
  },
  AvgDialog_117500_Content_101 = {
    Text = "Tu es là... Je pensais que... il m'était impossible de te voir..."
  },
  AvgDialog_117500_Content_102 = {
    Text = "Le navire a soudainement basculé violemment, des vagues salées et glacées se sont déversées dans la cabine."
  },
  AvgDialog_117500_Content_103 = {
    Text = "Que se passe-t-il ?!"
  },
  AvgDialog_117500_Content_104 = {
    Text = "Le bateau a-t-il heurté un récif ?"
  },
  AvgDialog_117500_Content_105 = {
    Text = "C'est impossible, la coque du Parades est trop enfoncée dans l'eau ; même si la cabine heurte un récif et fuit, elle ne pourrait pas inonder complètement en si peu de temps..."
  },
  AvgDialog_117500_Content_106 = {
    Text = "À moins que..."
  },
  AvgDialog_117500_Content_107 = {
    Text = "William se précipita vers le hublot, et le spectacle devant lui ressemblait à un délire des plus absurdes. Le Parades coulait à une vitesse incroyable."
  },
  AvgDialog_117500_Content_108 = {
    Text = "Comme si un grand cachalot tirait le petit bateau, une force énorme et irrésistible entraînait le Parades, le faisant plonger rapidement vers le fond de la mer."
  },
  AvgDialog_117500_Content_109 = {Text = "Ah—"},
  AvgDialog_117500_Content_11 = {
    Text = "Tu ouvres à nouveau les yeux. Doux, chaud, comme un souvenir familier."
  },
  AvgDialog_117500_Content_110 = {
    Text = "Dans une violente secousse, la chaîne perçante à travers la paume de Murphy se brisa soudainement."
  },
  AvgDialog_117500_Content_111 = {
    Text = "Sa paume douce et humide explore ton dos de la main, elle supporte la douleur de la blessure perçante et te saisit doucement la main, croisant ton regard."
  },
  AvgDialog_117500_Content_112 = {
    Text = "Elle murmure, ses paroles empreintes d'une odeur de rouille, incertaine si c'est à cause de l'eau de mer ou du sang."
  },
  AvgDialog_117500_Content_113 = {
    Text = "Sauve-moi… Si c'est toi, tu peux le faire…"
  },
  AvgDialog_117500_Content_114 = {
    Text = "Les dernières paroles, emportées par l'eau qui envahit la cabine, sombrent dans les ténèbres."
  },
  AvgDialog_117500_Content_12 = {
    Text = "<Small:Zut, nous devons vraiment garder ce gars jusqu'à ce qu'il se réveille ?>"
  },
  AvgDialog_117500_Content_13 = {
    Text = "<Small:Goliath, tu ne dois pas douter de l'ordre de la Mère divine.>"
  },
  AvgDialog_117500_Content_14 = {
    Text = "<Small:Sois plus discret, Seigneur Goliath, ce matin, la Mère divine a appelé Maître à la réprimander pendant un bon moment...>"
  },
  AvgDialog_117500_Content_15 = {
    Text = "Des disputes à voix basse viennent de l'extérieur des rideaux."
  },
  AvgDialog_117500_Content_16 = {
    Text = "*Tousse, tousse...*"
  },
  AvgDialog_117500_Content_17 = {
    Text = "Tu es réveillé ? Tout le monde t'attend."
  },
  AvgDialog_117500_Content_18 = {
    Text = "Faros fit lever le rideau."
  },
  AvgDialog_117500_Content_19 = {
    Text = "C'est quoi ça... Je suis encore sauvé ?"
  },
  AvgDialog_117500_Content_2 = {
    Text = "……Une araignée ?"
  },
  AvgDialog_117500_Content_20 = {
    Text = "Un gars qui a survécu à de grandes épreuves. Nous n'avons aucune obligation de répondre à toutes tes questions."
  },
  AvgDialog_117500_Content_21 = {
    Text = "À l'ordre de la Mère divine, les Marcheurs des mers attendent votre Réveil depuis longtemps."
  },
  AvgDialog_117500_Content_22 = {
    Text = "C'est le jus de citron que la Mère divine m'a ordonné de presser. Bois-le avec gratitude, humain."
  },
  AvgDialog_117500_Content_23 = {
    Text = "Puisqu'Il est en sécurité, je vais retourner à mon poste de navigateur. Le Royaume Divin m'appelle."
  },
  AvgDialog_117500_Content_24 = {Text = "新增"},
  AvgDialog_117500_Content_25 = {Text = "新增"},
  AvgDialog_117500_Content_26 = {
    Text = "Est-ce quelque chose de réel ou un cauchemar que j'ai eu quand j'étais submergé par l'eau... ?"
  },
  AvgDialog_117500_Content_27 = {
    Text = "(Il faut trouver un moyen de vérifier cela.)"
  },
  AvgDialog_117500_Content_28 = {
    Text = "Si je ne me trompe pas, la dernière personne que j'ai vue..."
  },
  AvgDialog_117500_Content_29 = {
    Text = "Tu es monté sur le pont."
  },
  AvgDialog_117500_Content_3 = {
    Text = "Une petite araignée d'un violet sombre te fixe avec de grands yeux. En te voyant te réveiller, elle lève ses pattes avant et te salue."
  },
  AvgDialog_117500_Content_30 = {
    Text = "<Shake:Hé——William, l'Aîné——>"
  },
  AvgDialog_117500_Content_31 = {
    Text = "<Shake:Ne te cache pas——je sais que tu es ici——>"
  },
  AvgDialog_117500_Content_32 = {
    Text = "Il n'y a que le bruit calme des vagues sur le pont, ton cri se diffuse dans le brouillard du matin."
  },
  AvgDialog_117500_Content_33 = {
    Text = "(Quoi qu'il en soit, ce n'était que mon rêve...)"
  },
  AvgDialog_117500_Content_34 = {Text = "Oh !"},
  AvgDialog_117500_Content_35 = {
    Text = "Le pont sous tes pieds cache une porte qui s'ouvre soudainement, et tu tombes avec un bruit sourd dans une obscurité totale."
  },
  AvgDialog_117500_Content_36 = {
    Text = "Un tas de paille a atténué l'impact de ta chute."
  },
  AvgDialog_117500_Content_37 = {
    Text = "Ça fait longtemps, gardien des secrets."
  },
  AvgDialog_117500_Content_38 = {
    Text = "Tu me connais... tu es William, l'Aîné de l'ancien monde..."
  },
  AvgDialog_117500_Content_39 = {
    Text = "William ignora ton ton surpris, son visage se ferma au contraire."
  },
  AvgDialog_117500_Content_4 = {
    Text = "Des couches de mousseline et de velours s'entassent sur le pont rouillé. La femme tenant le rouet te regarde fixement."
  },
  AvgDialog_117500_Content_40 = {
    Text = "Je ne me souviens pas de t'avoir enseigné à agir de manière aussi ostentatoire dans le quartier général de l'ennemi à Mizag."
  },
  AvgDialog_117500_Content_41 = {
    Text = "Même le doyen Czort, connu pour son impulsivité, ne soutiendrait probablement pas votre choix."
  },
  AvgDialog_117500_Content_42 = {
    Text = "Le souffle familier du cèdre, la posture droite familière, le ton sévère familier."
  },
  AvgDialog_117500_Content_43 = {
    Text = "William, l'Aîné..."
  },
  AvgDialog_117500_Content_44 = {
    Text = "Je n'avais pas l'intention de me montrer devant tes yeux avant de résoudre les problèmes clés."
  },
  AvgDialog_117500_Content_45 = {
    Text = "Cependant, ta précipitation m'oblige à changer de stratégie."
  },
  AvgDialog_117500_Content_46 = {
    Text = "Tu sais que je te poursuis depuis toujours ?"
  },
  AvgDialog_117500_Content_47 = {
    Text = "William ne répondit pas à cette question, il vous lança simplement un regard perçant qui disait « Me prends-tu pour un idiot ? »."
  },
  AvgDialog_117500_Content_48 = {
    Text = "Nous sommes déjà sur le même bateau, il est peu probable que nous puissions éviter cela. Mieux vaut que je clarifie la situation directement pour éviter tout malentendu."
  },
  AvgDialog_117500_Content_49 = {
    Text = "Avant cela, pourrais-tu partager les informations que tu as ?"
  },
  AvgDialog_117500_Content_5 = {
    Text = "Cette fois, elle n'a pas soupiré, elle n'a pas parlé, elle est simplement restée silencieuse."
  },
  AvgDialog_117500_Content_50 = {Text = "新增"},
  AvgDialog_117500_Content_51 = {Text = "新增"},
  AvgDialog_117500_Content_52 = {
    Text = "De devenir un bocal à cerveaux par Doll : Dissoute, à être piégé dans le sanatorium de Clémentine, en passant par le paysage de Nekropolis, et enfin à vivre des « cauchemars » à bord du Parades."
  },
  AvgDialog_117500_Content_53 = {
    Text = "Tu raconteras tout au long du chemin, William tourne la tête pour écouter attentivement, hochant la tête de temps en temps pour montrer qu'il reste concentré."
  },
  AvgDialog_117500_Content_54 = {
    Text = "En parlant de William dans son enfance que vous avez vu, vous hésitez un instant, mais William lève simplement la main pour vous faire signe de continuer."
  },
  AvgDialog_117500_Content_55 = {
    Text = "Les informations que vous avez fournies sont très utiles."
  },
  AvgDialog_117500_Content_56 = {
    Text = "William, l'Aîné, peux-tu maintenant me dire ce que tu poursuis exactement ?"
  },
  AvgDialog_117500_Content_57 = {
    Text = "William réfléchit un moment."
  },
  AvgDialog_117500_Content_58 = {
    Text = "Laisse-moi réfléchir par où commencer."
  },
  AvgDialog_117500_Content_59 = {
    Text = "Depuis que je suis tombé dans ce monde, je me pose deux questions : pourquoi suis-je ici et comment puis-je retourner dans mon monde d'origine ?"
  },
  AvgDialog_117500_Content_6 = {
    Text = "Pourquoi, je me souviens très bien d'avoir été attaqué par d'innombrables Marcheurs des mers, puis..."
  },
  AvgDialog_117500_Content_60 = {
    Text = "William sortit solennellement une clé en argent précieusement gardée de sa poitrine, et un regard de nostalgie brillait dans ses yeux."
  },
  AvgDialog_117500_Content_61 = {
    Text = "Cette clé d'argent, je l'ai restaurée de mes propres mains, elle vient de mon ancien partenaire Fingal… On dit souvent que je suis l'enquêteur le plus légendaire de Mizag, mais pour moi, c'est seulement parce qu'il est mort prématurément."
  },
  AvgDialog_117500_Content_62 = {
    Text = "Jusqu'à tomber dans cette dimension, j'ai compris qu'il n'était rien d'autre qu'une personne qui avait compris plus tôt la véritable nature du monde et qui se battait en tant que pionnier sur les lignes de front contre la Fusion."
  },
  AvgDialog_117500_Content_63 = {
    Text = "Il a déjà suivi le secret de la connexion entre les deux mondes et a laissé une piste clé—— une statue en ivoire."
  },
  AvgDialog_117500_Content_64 = {
    Text = "Comme d'habitude, il est toujours en avance sur moi."
  },
  AvgDialog_117500_Content_65 = {
    Text = "William, l'expression sombre, secoue la tête et remet la clé en argent dans son sein."
  },
  AvgDialog_117500_Content_66 = {
    Text = "... As-tu vu la statue en ivoire que Miryam ou Murphy tient ?"
  },
  AvgDialog_117500_Content_67 = {
    Text = "Tu hoches la tête."
  },
  AvgDialog_117500_Content_68 = {
    Text = "Si tout se déroule comme la dernière fois, sur le pont au-dessus de nous, Murphy est en train de tenir une cérémonie avec cette statue."
  },
  AvgDialog_117500_Content_69 = {
    Text = "Cette statue en ivoire semble avoir des liens étroits avec l'essence de ce monde."
  },
  AvgDialog_117500_Content_7 = {
    Text = "Tu ressens ton corps. Bien que la douleur fantôme soit encore présente, il n'y a aucune cicatrice sur ta peau, et la grande bataille que tu as vécue avant de sombrer dans l'inconscience ne semble jamais avoir eu lieu."
  },
  AvgDialog_117500_Content_70 = {
    Text = "Donc, pour rentrer, il nous faudra probablement obtenir la statue en ivoire et l'analyser et l'étudier."
  },
  AvgDialog_117500_Content_71 = {
    Text = "Après la fin du rituel, la statue en ivoire devrait retourner dans la pièce de Murphy..."
  },
  AvgDialog_117500_Content_72 = {
    Text = "Il fait très calme à l'intérieur, normalement tout le monde n'est pas dedans..."
  },
  AvgDialog_117500_Content_73 = {
    Text = "Il vaut mieux être prudent, nous devons éviter les conflits inutiles autant que possible."
  },
  AvgDialog_117500_Content_74 = {
    Text = "D'accord, alors jetons un coup d'œil."
  },
  AvgDialog_117500_Content_75 = {
    Text = "Tu pousses doucement la porte avec précaution."
  },
  AvgDialog_117500_Content_76 = {Text = "新增"},
  AvgDialog_117500_Content_77 = {
    Text = "Un courant d'air mêlé à une odeur étrange pénètre dans tes narines, et tu réalises que tu as involontairement pris une profonde inspiration."
  },
  AvgDialog_117500_Content_78 = {
    Text = "Quel est le problème ?"
  },
  AvgDialog_117500_Content_79 = {Text = "Voix."},
  AvgDialog_117500_Content_8 = {
    Text = "C'était... un cauchemar ?"
  },
  AvgDialog_117500_Content_80 = {
    Text = "Un bruit est enfin apparu dans la pièce silencieuse."
  },
  AvgDialog_117500_Content_81 = {
    Text = "Le son des gouttes d'eau."
  },
  AvgDialog_117500_Content_82 = {
    Text = "Tic-tac, tic-tac, le son des gouttes d'eau tombant dans la petite flaque d'eau fraîchement formée."
  },
  AvgDialog_117500_Content_83 = {
    Text = "Huit chaînes de fer tendues s'étendent des membres de Murphy, la liant fermement. \n Sa poitrine a été percée d'un immense trou sanglant."
  },
  AvgDialog_117500_Content_84 = {
    Text = "Le sang coule le long de la blessure choquante, tombant dans la flaque de sang qui se forme lentement, c'est la source du tic-tac qui résonne à tes oreilles."
  },
  AvgDialog_117500_Content_85 = {
    Text = "Murphy... !"
  },
  AvgDialog_117500_Content_86 = {
    Text = "Tu es arrivé trop tard."
  },
  AvgDialog_117500_Content_87 = {
    Text = "Le cœur semble être fermement saisi par une main invisible, cette douleur familière et étouffante, accompagnée de fragments de souvenirs, transperce violemment."
  },
  AvgDialog_117500_Content_88 = {
    Text = "Une lumière trop éblouissante blesse les yeux, provoquant des larmes incontrôlables"
  },
  AvgDialog_117500_Content_89 = {
    Text = "Le liquide trouble s'est écoulé, les yeux peuvent enfin se concentrer à nouveau sur la jeune fille"
  },
  AvgDialog_117500_Content_9 = {
    Text = "La femme hoche silencieusement la tête, sa silhouette se dissipe dans la brume vaporeuse."
  },
  AvgDialog_117500_Content_90 = {
    Text = "La lame s'enfonce profondément dans la poitrine, la jeune fille baignée de lumière lunaire ouvre les yeux"
  },
  AvgDialog_117500_Content_91 = {
    Text = "La pleine lune symbolisant la mort est proche, mais le visage jeune ne montre aucune peur"
  },
  AvgDialog_117500_Content_92 = {
    Text = "Je l'ai fait... Je l'ai vraiment fait."
  },
  AvgDialog_117500_Content_93 = {
    Text = "Je... l'ai percé... Il ne naîtra pas..."
  },
  AvgDialog_117500_Content_94 = {Text = "Ainsi"},
  AvgDialog_117500_Content_95 = {
    Text = "La main serrant le manche du couteau tomba mollement, un liquide rouge, visqueux et noir s'écoulant de la lame et se répandant dans la mer"
  },
  AvgDialog_117500_Content_96 = {
    Text = "*Tousse, tousse...*"
  },
  AvgDialog_117500_Content_97 = {
    Text = "Tu es... la personne dans le rêve..."
  },
  AvgDialog_117500_Content_98 = {
    Text = "Ne parle pas pour l'instant ! Je vais t'aider..."
  },
  AvgDialog_117500_Content_99 = {
    Text = "Tes efforts désespérés n'ont abouti à rien, les chaînes émettent des gémissements fragiles en raison des tremblements douloureux de Murphy."
  },
  AvgDialog_117501_Content_10 = {
    Text = "Pourquoi la Mère divine pose-t-elle une telle question ?"
  },
  AvgDialog_117501_Content_11 = {
    Text = "La nuit dernière, j'ai fait un rêve."
  },
  AvgDialog_117501_Content_12 = {
    Text = "Dans le rêve, j'utilise ce poignard rituel..."
  },
  AvgDialog_117501_Content_13 = {
    Text = "Elle pointa du doigt la dague que Miryam ne quittait jamais. \n La lame brillait de mille feux, dégageant une lueur diabolique comme si elle était empoisonnée."
  },
  AvgDialog_117501_Content_14 = {
    Text = "a transpercé sa propre poitrine."
  },
  AvgDialog_117501_Content_15 = {
    Text = "«Il ne naîtra pas...»"
  },
  AvgDialog_117501_Content_16 = {
    Text = "Murphy murmure, ses doigts effleurant la cicatrice ensanglantée de sa poitrine."
  },
  AvgDialog_117501_Content_17 = {
    Text = "C'est un cauchemar illusoire."
  },
  AvgDialog_117501_Content_18 = {
    Text = "Miryam s'approche, s'agenouille devant les genoux de Murphy, caressant doucement le dos de sa main pour la réconforter."
  },
  AvgDialog_117501_Content_19 = {
    Text = "Rassurez-vous, le souhait des Marcheurs des mers a été exaucé, Il existe, Il est descendu dans ce monde."
  },
  AvgDialog_117501_Content_2 = {Text = "rêve"},
  AvgDialog_117501_Content_20 = {
    Text = "Et toi et moi finirons par atteindre le royaume éternel, partageant la gloire divine devant Son trône."
  },
  AvgDialog_117501_Content_21 = {
    Text = "Ses mots étaient comme une prière devant l'autel, remplis de révérence et de piété."
  },
  AvgDialog_117501_Content_22 = {
    Text = "Et si nous ne pouvons pas atteindre le Royaume Divin ? Je veux dire si..."
  },
  AvgDialog_117501_Content_23 = {
    Text = "Miryam a immédiatement interrompu la question hésitante de Murphy."
  },
  AvgDialog_117501_Content_24 = {
    Text = "La prédiction du Roi divin n'a jamais transmis de telles informations. \n Le prochain moment de la position normale est demain, son sang nous guidera vers la terre promise."
  },
  AvgDialog_117501_Content_25 = {
    Text = "Murphy fronça les sourcils."
  },
  AvgDialog_117501_Content_26 = {
    Text = "Je vais me reposer, Miryam, retourne aussi te reposer."
  },
  AvgDialog_117501_Content_27 = {
    Text = "Je prierai la Mère divine jusqu'à l'aube, demandant pour vous une nuit de sommeil paisible."
  },
  AvgDialog_117501_Content_28 = {
    Text = "Murphy ne répondit pas, son regard profond suivant la silhouette de Miryam jusqu'à ce que le grincement de la porte se fasse entendre."
  },
  AvgDialog_117501_Content_29 = {
    Text = "Elle se tourna déprimée vers l'autel dans l'ombre, les yeux fermés en prière."
  },
  AvgDialog_117501_Content_3 = {
    Text = "Ô Mère divine, tu es ici encore à regarder la lumière."
  },
  AvgDialog_117501_Content_30 = {
    Text = "Demain, le jour de la position normale…"
  },
  AvgDialog_117501_Content_31 = {
    Text = "Les étranges offrandes sur l'autel ne lui ont donné aucune réponse, silencieuses comme des fossiles sous la glace. \n Murphy ouvrit les yeux, comme si elle avait pris une décision."
  },
  AvgDialog_117501_Content_32 = {
    Text = "Pour la continuité de ce rêve..."
  },
  AvgDialog_117501_Content_33 = {
    Text = "Elle tendit son bras fin, lourdement voilé de noir, levant haut le poignard rituel—"
  },
  AvgDialog_117501_Content_34 = {
    Text = "À la lumière des bougies, l'ombre de la dague plonge violemment vers le berceau endormi sur l'autel."
  },
  AvgDialog_117501_Content_35 = {
    Text = "Un bruit de plop retentit, un son étrange de chair visqueuse percée. \n Le liquide noir s'étend progressivement, humidifiant les runes de Marcheur des mers sur le berceau en velours."
  },
  AvgDialog_117501_Content_36 = {
    Text = "Une autre nuit, va descendre..."
  },
  AvgDialog_117501_Content_37 = {
    Text = "Elle poussa un soupir de soulagement, ferma les yeux, mais ce n'était pas les ténèbres sans fond qui l'assaillaient, mais le rêve d'hier."
  },
  AvgDialog_117501_Content_38 = {Text = "新增"},
  AvgDialog_117501_Content_39 = {
    Text = "(Le moment où j'ai été transpercé au cœur, la personne qui est apparue à mes côtés...)"
  },
  AvgDialog_117501_Content_4 = {
    Text = "Reposez-vous tôt, demain c'est le Jour de la position normale, vous devez encore indiquer le chemin aux Marcheurs des mers avec le Sang sacré."
  },
  AvgDialog_117501_Content_40 = {
    Text = "(Je n'ai jamais vu, mais cela me rappelle quelque chose…)"
  },
  AvgDialog_117501_Content_41 = {
    Text = "……Une araignée ?"
  },
  AvgDialog_117501_Content_42 = {
    Text = "Une petite araignée de couleur violet foncé te fixe avec de grands yeux depuis le mât. En te voyant te réveiller, elle lève une patte avant et te salue."
  },
  AvgDialog_117501_Content_43 = {
    Text = "Dans un rêve, il me semble que j'ai entendu une chanson..."
  },
  AvgDialog_117501_Content_44 = {
    Text = "Une voix éthérée et douce, semblable à celle d'une sirène chantant des poèmes, résonne inlassablement à tes oreilles."
  },
  AvgDialog_117501_Content_45 = {
    Text = "Enfants tragiques, le tissage du destin est déjà fait, vous entreprendrez finalement un voyage destiné."
  },
  AvgDialog_117501_Content_46 = {
    Text = "Et vous, invité d'un autre monde——"
  },
  AvgDialog_117501_Content_47 = {
    Text = "Au moment du retour de l'heure de la position correcte des étoiles, veuillez marquer la fin du cycle tragique."
  },
  AvgDialog_117501_Content_48 = {
    Text = "Accompagnée d'un long soupir, l'illusion de la femme disparaît."
  },
  AvgDialog_117501_Content_49 = {Text = "?!"},
  AvgDialog_117501_Content_5 = {
    Text = "Murphy regardait fixement la flamme vacillante de la lanterne, le voile noir oscillant avec ses mouvements, projetant une illusion de rideau sur les murs de la cabine."
  },
  AvgDialog_117501_Content_50 = {
    Text = "Une fois la peur fugace dissipée, tu peux enfin te concentrer pour observer l'environnement autour de toi."
  },
  AvgDialog_117501_Content_51 = {
    Text = "Où suis-je... ?"
  },
  AvgDialog_117501_Content_52 = {
    Text = "Matelas doux. Un espace tranquille couvert de voile noir. Une odeur de sauge et d'encens flotte légèrement dans l'air."
  },
  AvgDialog_117501_Content_53 = {
    Text = "Avant... je..."
  },
  AvgDialog_117501_Content_54 = {
    Text = "Doll ! Peux-tu recevoir le signal ? Doll ?"
  },
  AvgDialog_117501_Content_55 = {
    Text = "Ne crie pas, tu perturbes mon récepteur de forme d'onde vocale."
  },
  AvgDialog_117501_Content_56 = {
    Text = "J'ai rattrapé le bateau sur lequel William a embarqué selon les pêcheurs ! Mais il est entré dans la tempête !"
  },
  AvgDialog_117501_Content_57 = {
    Text = "La phrase suivante est..."
  },
  AvgDialog_117501_Content_58 = {
    Text = "Je vais y aller en courant !"
  },
  AvgDialog_117501_Content_59 = {
    Text = "Avec ce petit bateau de pêche ? Foncer dans la fosse des Bermudes ? Tu n'as pas peur de chavirer là-dedans ?"
  },
  AvgDialog_117501_Content_6 = {
    Text = "Miryam, as-tu rêvé ?"
  },
  AvgDialog_117501_Content_60 = {
    Text = "Nous ne pouvons plus perdre d'indices, c'est la seule information réelle et valable que nous avons rencontrée depuis des mois !"
  },
  AvgDialog_117501_Content_61 = {
    Text = "Que la clé d'argent montre le chemin !"
  },
  AvgDialog_117501_Content_62 = {
    Text = "De l'autre côté de la communication, vous n'entendez pas le « Que la clé d'argent nous guide » que vous devriez entendre, mais plutôt le bruit statique d'une connexion interrompue."
  },
  AvgDialog_117501_Content_63 = {
    Text = "Ce qui vous attend, ce sont des vagues tonitruantes de mille coudées de haut, suivies d'une obscurité infinie engloutissante——"
  },
  AvgDialog_117501_Content_64 = {
    Text = "Il y a trois mois, suite à des nouvelles concernant un mystérieux homme blond partant du port d'Innsmouth, vous avez suivi la trace de William."
  },
  AvgDialog_117501_Content_65 = {
    Text = "Récemment, vous avez enfin aperçu le pavillon des pêcheurs décrit, mais une tempête soudaine vous a enlevé votre direction."
  },
  AvgDialog_117501_Content_66 = {
    Text = "Lorsque tu ouvres à nouveau les yeux, c'est le spectacle devant toi."
  },
  AvgDialog_117501_Content_67 = {
    Text = "Tu es réveillé ? Tout le monde t'attend."
  },
  AvgDialog_117501_Content_68 = {
    Text = "Le voile noir est délicatement soulevé, une voix féminine à la fois familière et étrangère se fait entendre."
  },
  AvgDialog_117501_Content_69 = {
    Text = "Tout le monde… ? Qui… ?"
  },
  AvgDialog_117501_Content_7 = {
    Text = "Bien sûr, j'en ai fait. Parmi des milliers de rêves, la grande Lémuria émerge des profondeurs de l'Aequor, se reproduisant sous la lumière du soleil."
  },
  AvgDialog_117501_Content_70 = {
    Text = "Quatre visages familiers tournent étrangement autour de ton lit."
  },
  AvgDialog_117501_Content_71 = {
    Text = "Par ordre de la Mère divine, le Marcheur des mers attend votre Réveil depuis longtemps. Venez, buvez cette potion que la Mère divine a préparée pour vous."
  },
  AvgDialog_117501_Content_72 = {
    Text = "Caecus présente un verre en cristal finement taillé, le liquide jaune trouble qui s'y trouve est inquiétant."
  },
  AvgDialog_117501_Content_73 = {
    Text = "Dedans, c'est... ?"
  },
  AvgDialog_117501_Content_74 = {
    Text = "Espèce de chanceux, ne pose plus de questions."
  },
  AvgDialog_117501_Content_75 = {
    Text = "C'est la Mère divine qui me l'a pressé. Bois-le avec gratitude, humain."
  },
  AvgDialog_117501_Content_76 = {
    Text = "Sous le regard de tous, tu as soigneusement pris une gorgée."
  },
  AvgDialog_117501_Content_77 = {
    Text = "Pff——c'est tellement acide—— ! C'est du jus de citron pur ?!"
  },
  AvgDialog_117501_Content_78 = {
    Text = "Tu te redresses brusquement à cause de l'acidité, les sourcils froncés en un tas."
  },
  AvgDialog_117501_Content_79 = {
    Text = "Puisqu'Il est en sécurité, je souhaite me rendre sur le pont pour recevoir l'inspiration. Le royaume divin m'appelle."
  },
  AvgDialog_117501_Content_8 = {
    Text = "La lumière éternelle se répand sur les mers lointaines, nous indiquant une nouvelle trajectoire."
  },
  AvgDialog_117501_Content_80 = {
    Text = "(Ce monde et moi, l'un de nous doit être devenu fou...)"
  },
  AvgDialog_117501_Content_81 = {
    Text = "Mmm... ici, c'est ?…"
  },
  AvgDialog_117501_Content_82 = {
    Text = "Le paquebot Parades, le seul et le plus important « paradis » maritime pour les Marcheurs des mers."
  },
  AvgDialog_117501_Content_83 = {
    Text = "Nous naviguons vers le Royaume Divin éternel, Lémurie."
  },
  AvgDialog_117501_Content_9 = {
    Text = "Miryam répond presque instinctivement, et la question qui suit trahit une surprise difficile à dissimuler."
  },
  AvgDialog_117502_Content_1 = {Text = "新增"},
  AvgDialog_117502_Content_10 = {
    Text = "Dans les dernières lueurs avant que le champ de vision ne plonge dans l'obscurité absolue, tu aperçois une silhouette passer en un éclair."
  },
  AvgDialog_117502_Content_11 = {
    Text = "Une chevelure dorée éclatante, un bras mécanique précis scintille d'un éclat métallique."
  },
  AvgDialog_117502_Content_12 = {
    Text = "William... l'Aîné..."
  },
  AvgDialog_117502_Content_2 = {Text = "新增"},
  AvgDialog_117502_Content_3 = {
    Text = "Combien de temps as-tu combattu au milieu de ce banc de poissons nauséabonds ?"
  },
  AvgDialog_117502_Content_4 = {
    Text = "Une heure ? Un jour ? Ou un temps qui ne peut tout simplement pas être compté ?"
  },
  AvgDialog_117502_Content_5 = {
    Text = "(La fête est le moment où les Marcheurs des mers se rassemblent. Intervenir à ce moment-là... c'est vraiment une décision impulsive et erronée.)"
  },
  AvgDialog_117502_Content_6 = {
    Text = "La sensation glissante est devenue si habituelle qu'elle en est devenue insensible, et la boue nauséabonde ne dérange plus les narines encombrées."
  },
  AvgDialog_117502_Content_7 = {
    Text = "(Si je pouvais encore revenir une fois… Quel dommage…)"
  },
  AvgDialog_117502_Content_8 = {
    Text = "Tu t'efforces de lever la clé en argent, le noyau autrefois brillant commence déjà à trembler.\nTu es précaire, crachant du sang."
  },
  AvgDialog_117502_Content_9 = {
    Text = "(Ça y est... à la limite... désolé... je n'ai pas pu m'échapper...)"
  },
  AvgDialog_117503_Content_1 = {
    Text = "Un voyageur"
  },
  AvgDialog_117503_Content_10 = {
    Text = "Le cœur se met soudainement à battre avec agitation, tu ouvres instinctivement la bouche, car tu sais déjà qui est le maître derrière ce visage voilé de noir."
  },
  AvgDialog_117503_Content_100 = {
    Text = "Le banc de poissons brise les contraintes de la surface liquide, se débat et se contorsionne dans l'air collant, s'abattant sur toi en une pluie nauséabonde et visqueuse."
  },
  AvgDialog_117503_Content_101 = {
    Text = "Accompagné d'un bruit étrange et désagréable, un corps à demi pourri rebondit vainement sur le pont, tandis que la matière putride qui s'écoule des impacts dégage une odeur nauséabonde et suffocante."
  },
  AvgDialog_117503_Content_102 = {
    Text = "Des tentacules fins et fragiles déchirent un ventre blême, s'approchant de toi en rampant à moitié——"
  },
  AvgDialog_117503_Content_11 = {
    Text = "<Shake:Murphy...>"
  },
  AvgDialog_117503_Content_12 = {
    Text = "Entre les mailles du voile, sa peau pâle et verdâtre est exposée, blanche comme la poussière de cadavre qui est sur le point de se désagréger."
  },
  AvgDialog_117503_Content_13 = {
    Text = "Audacieux ! Comment oses-tu appeler la Mère divine par son nom !"
  },
  AvgDialog_117503_Content_14 = {
    Text = "Aucun souci, Caecus, {Male=il,Female=elle} est un invité du Paradis et se joindra à notre grand voyage."
  },
  AvgDialog_117503_Content_15 = {
    Text = "Cinq yeux te fixent intensément, réprimant tous les mots que tu souhaitais exprimer au fond de ton ventre."
  },
  AvgDialog_117503_Content_16 = {
    Text = "… Murphy, puis-je te parler en privé ?"
  },
  AvgDialog_117503_Content_17 = {Text = "新增"},
  AvgDialog_117503_Content_18 = {Text = "新增"},
  AvgDialog_117503_Content_19 = {Text = "Murphy..."},
  AvgDialog_117503_Content_2 = {
    Text = "La jeune fille qui te parle est assise tranquillement au pied de ton lit, un voile noir flou cachant son visage."
  },
  AvgDialog_117503_Content_20 = {
    Text = "Si tu n'as pas encore organisé tes idées, j'ai une question à te poser."
  },
  AvgDialog_117503_Content_21 = {
    Text = "Pourquoi es-tu venu sur le Paradis ? D'après ce que je sais, pour s'approcher du Paradis, il faut d'abord pénétrer dans la tempête."
  },
  AvgDialog_117503_Content_22 = {
    Text = "Être prêt à prendre de tels risques, tu dois avoir quelque chose à demander."
  },
  AvgDialog_117503_Content_23 = {
    Text = "Cela dit... avez-vous vu un homme qui mesure une demi-tête de plus que moi, avec des cheveux blonds ?"
  },
  AvgDialog_117503_Content_24 = {
    Text = "Murphy te lança un regard noir et laisse échapper un ricanement."
  },
  AvgDialog_117503_Content_25 = {
    Text = "Vu votre taille, il doit y avoir pas mal de gens comme ça parmi l'équipage."
  },
  AvgDialog_117503_Content_26 = {
    Text = "Non, tu peux le reconnaître d'un seul coup d'œil... Il a un bras mécanique, il est très beau, et il dégage une légère odeur de cèdre."
  },
  AvgDialog_117503_Content_27 = {
    Text = "… alors je peux le confirmer, je ne l'ai jamais vu. \n Les matelots dégagent toujours une odeur de poisson sale et nauséabonde."
  },
  AvgDialog_117503_Content_28 = {
    Text = "Alors, Murphy, il y a une chose clé."
  },
  AvgDialog_117503_Content_29 = {Text = "Hmm?"},
  AvgDialog_117503_Content_3 = {
    Text = "(Quelle voix familière... qui est-ce...)"
  },
  AvgDialog_117503_Content_30 = {
    Text = "Veux-tu t'échapper avec moi ?"
  },
  AvgDialog_117503_Content_31 = {Text = "Haah ?!"},
  AvgDialog_117503_Content_32 = {
    Text = "Murphy fut surprise par tes paroles, puis la colère monta sur son visage.\nElle s'efforça de maîtriser ses émotions et laissa échapper un ricanement provocateur."
  },
  AvgDialog_117503_Content_33 = {
    Text = "Échapper, qu'est-ce que ça veut dire ?"
  },
  AvgDialog_117503_Content_34 = {
    Text = "Au sens littéral, nous devons trouver un moyen de quitter ce navire et de nous échapper du contrôle des Marcheurs des mers."
  },
  AvgDialog_117503_Content_35 = {
    Text = "Pourquoi devrais-je m'enfuir avec toi ?"
  },
  AvgDialog_117503_Content_36 = {
    Text = "Parce que tu n'aimes pas la vie ici."
  },
  AvgDialog_117503_Content_37 = {
    Text = "Tu n'aimes pas la doctrine fictive de Miryam, tu n'aimes pas l'adoration hypocrite des croyants, et tu n'es pas intéressé par ces honneurs illusoires."
  },
  AvgDialog_117503_Content_38 = {
    Text = "La tête de Murphy s'est lentement abaissée."
  },
  AvgDialog_117503_Content_39 = {
    Text = "Voyant qu'elle reste silencieuse, tu as rapidement ajouté du bois au feu."
  },
  AvgDialog_117503_Content_4 = {
    Text = "Tu te redresses en t'appuyant sur tes bras endoloris, essayant de prendre conscience de l'état de l'environnement."
  },
  AvgDialog_117503_Content_40 = {
    Text = "Dans un autre monde, je t'ai déjà vu, je te connais, nous avons traversé des situations similaires, et tu as finalement réussi à échapper à la tanière du mal..."
  },
  AvgDialog_117503_Content_41 = {Text = "Hmph..."},
  AvgDialog_117503_Content_42 = {
    Text = "Faux, faux ! Tu as vraiment tort !"
  },
  AvgDialog_117503_Content_43 = {Text = "Murphy...?"},
  AvgDialog_117503_Content_44 = {
    Text = "La réaction de Murphy dépasse complètement tes attentes, elle se mit à rire doucement."
  },
  AvgDialog_117503_Content_45 = {
    Text = "Ce rire devint progressivement effréné, jusqu'à ce que la pièce ne résonne que de son éclat de rire excessif."
  },
  AvgDialog_117503_Content_46 = {
    Text = "Après un moment, elle semble enfin être fatiguée de rire, son rire s'arrête brusquement.\nElle lève la tête et te fixe avec colère."
  },
  AvgDialog_117503_Content_47 = {
    Text = "L'embryon divin grandit dans ma poitrine ; je suis la vénérable mère des dieux, chérie de tous. Pourquoi devrais-je me conformer à votre «évasion» de simples mortels ?"
  },
  AvgDialog_117503_Content_48 = {
    Text = "Mais lorsque le dieu naîtra, tu mourras..."
  },
  AvgDialog_117503_Content_49 = {
    Text = "Plus besoin d'attendre, êtres stupides."
  },
  AvgDialog_117503_Content_5 = {
    Text = "Idiot, ne bouge pas."
  },
  AvgDialog_117503_Content_50 = {
    Text = "Murphy tendit un berceau de forme étrange, la partie destinée à la tête du bébé, figée avec une masse gélatineuse violette-bleue familière."
  },
  AvgDialog_117503_Content_51 = {
    Text = "Enfant Saint ?!"
  },
  AvgDialog_117503_Content_52 = {
    Text = "D'après le contour, vous reconnaissez qu'il s'agit du faux dieu déformé que le rituel de descente du Sona-Nyl a tenté d'invoquer."
  },
  AvgDialog_117503_Content_53 = {
    Text = "Dans ce monde, le saint enfant est déjà né ? Mais pourquoi est-il... si petit ?!"
  },
  AvgDialog_117503_Content_54 = {
    Text = "Pourquoi est-ce si petit... c'est vraiment une question ridicule."
  },
  AvgDialog_117503_Content_55 = {
    Text = "Si cela reste aussi petit, il ne sera pas comme un ballon d'hydrogène gonflé par la force musculaire, extrayant avidement l'énergie de sa mère, se remplissant, s'étendant et comprimant sans relâche dans ma poitrine..."
  },
  AvgDialog_117503_Content_56 = {
    Text = "Puis au moment où le corps maternel meurt, crash, écrasement, réduction en cendres..."
  },
  AvgDialog_117503_Content_57 = {
    Text = "Tu as déjà vu, c'est l'Enfant Saint que j'ai donné naissance."
  },
  AvgDialog_117503_Content_58 = {
    Text = "Tu appelles ça... un dieu ?"
  },
  AvgDialog_117503_Content_59 = {
    Text = "Alors quoi ? Qui a déjà vu à quoi ressemble la naissance des dieux selon les marins ?"
  },
  AvgDialog_117503_Content_6 = {
    Text = "La jeune fille, énervée, se leva, le voile noir qui la couvrait tremblant nerveusement."
  },
  AvgDialog_117503_Content_60 = {
    Text = "Qui peut affirmer que cette masse de chair putride entre nos mains n'est pas le véritable « dieu » ?"
  },
  AvgDialog_117503_Content_61 = {
    Text = "Des voix de questionnement résonnent comme des tonnerres dans ton esprit."
  },
  AvgDialog_117503_Content_62 = {
    Text = "Je ne suis pas la Murphy que vous connaissez, je suis la Mère divine des Marcheurs des mers, la seule personne dont le sang est compatible avec Lui."
  },
  AvgDialog_117503_Content_63 = {
    Text = "Quant à toi... ne me fais pas regretter de t'avoir intégré au Paradis.\n Maintenant, laisse-moi tranquille et sors de cette pièce avec tes pensées ridicules."
  },
  AvgDialog_117503_Content_64 = {
    Text = "Tu erres à bord du Parades, suivant les souvenirs du passé, tandis que les petits matelots poisson-nageurs s'affairent, te considérant comme invisible."
  },
  AvgDialog_117503_Content_65 = {
    Text = "Jusqu'à ce que vous voyiez deux silhouettes familières à côté de la salle de puissance."
  },
  AvgDialog_117503_Content_66 = {
    Text = "Gamin, sois plus généreux, attaque !"
  },
  AvgDialog_117503_Content_67 = {Text = "Oui !"},
  AvgDialog_117503_Content_68 = {
    Text = "Ding clang——!"
  },
  AvgDialog_117503_Content_69 = {
    Text = "Encore une fois, ça a été bloqué... Mince, si ça continue comme ça, jusqu'à quand pourrai-je aider Lord Goliath à conquérir..."
  },
  AvgDialog_117503_Content_7 = {
    Text = "Le Parades a vu de nombreux patients sensibles à l'environnement océanique ; avant leur adaptation au Paradis, ne les ébranlez pas trop spirituellement."
  },
  AvgDialog_117503_Content_70 = {
    Text = "Calme-toi, gamin, les murs ont des oreilles. Si tu te fais attraper, toi et moi, nous ne pourrons pas nous échapper."
  },
  AvgDialog_117503_Content_71 = {
    Text = "Seigneur Goliath, vous avez clairement dit que notre sang provient des puissants, nous ne devrions avoir peur de rien..."
  },
  AvgDialog_117503_Content_72 = {
    Text = "Espèce de petit, même les puissants doivent parfois se soumettre. Sur ce bateau, nous devons prétendre écouter ces folles."
  },
  AvgDialog_117503_Content_73 = {Text = "Mais..."},
  AvgDialog_117503_Content_74 = {
    Text = "Moins de bavardages, quelqu'un arrive."
  },
  AvgDialog_117503_Content_75 = {
    Text = "Le corps du géant émerge de l'ombre de la salle de puissance, le crissement de la grande lame dentée traînant sur le sol couvre presque le rugissement de la cabine."
  },
  AvgDialog_117503_Content_76 = {
    Text = "Nous nous revoyons, petit."
  },
  AvgDialog_117503_Content_77 = {
    Text = "Goliath… comment suis-je arrivé sur ce bateau ?"
  },
  AvgDialog_117503_Content_78 = {
    Text = "Tu devrais te demander, dans le territoire de Miryam, les voyageurs ordinaires ne sont pas les bienvenus, sans parler des petits bateaux qui arrivent soudainement."
  },
  AvgDialog_117503_Content_79 = {
    Text = "Je ne sais pas quelle chance tu as, mais en tout cas, la petite fille a changé d'attitude ces derniers jours, il est hors de question que nous te touchions."
  },
  AvgDialog_117503_Content_8 = {
    Text = "Tu es face à une paire d'yeux rouges qui te semblent familiers."
  },
  AvgDialog_117503_Content_80 = {
    Text = "Sinon, cette femme risque de t'emmener pour raffiner des cœurs d'argent, après tout, dans un monde où les gens sont déjà tous morts, le cœur d'argent peut se considérer comme quelque chose qu'on utilise au fur et à mesure."
  },
  AvgDialog_117503_Content_81 = {
    Text = "Et ta position ? Le Goliath que je connais n'est pas un faible manipulable."
  },
  AvgDialog_117503_Content_82 = {
    Text = "Petit, tu viens juste de monter sur ce bateau, il y a beaucoup de choses que tu ne sais pas encore."
  },
  AvgDialog_117503_Content_83 = {
    Text = "Tu dois seulement te souvenir d'une chose : cette folle est maintenant complètement soumise à la Mère divine. Tout sur ce bateau est décidé par cette petite fille."
  },
  AvgDialog_117503_Content_84 = {
    Text = "Ne tente pas de contrecarrer sa volonté — au moins, ne te fais pas remarquer."
  },
  AvgDialog_117503_Content_85 = {
    Text = "Pour le reste, je te le dirai quand nous nous retrouverons ailleurs, si le destin le permet."
  },
  AvgDialog_117503_Content_86 = {
    Text = "Je dois bien réfléchir... Allons sur le pont pour profiter de la brise marine."
  },
  AvgDialog_117503_Content_87 = {
    Text = "Tu te tiens seul à la proue, scrutant l'horizon."
  },
  AvgDialog_117503_Content_88 = {
    Text = "La surface de la mer est enveloppée dans une légère brume blanche, le paquebot fend les bruits tumultueux de la mer et le fonctionnement mécanique avec calme et stabilité."
  },
  AvgDialog_117503_Content_89 = {
    Text = "Tu inspires profondément l'air marin mélangé à une odeur salée et métallique, essayant de clarifier tes pensées confuses."
  },
  AvgDialog_117503_Content_9 = {
    Text = "——Dong dong, dong dong——"
  },
  AvgDialog_117503_Content_90 = {
    Text = "Je poursuivais le bateau de William dans la tempête, j'ai eu un accident et j'ai été sauvé par le Marcheur des mers..."
  },
  AvgDialog_117503_Content_91 = {
    Text = "L'Enfant Saint est déjà né, Murphy est devenue la Mère Sainte des Marcheurs des mers, Miryam collecte des Cœurs d'argent, et Goliath prépare quelque chose dans l'ombre..."
  },
  AvgDialog_117503_Content_92 = {
    Text = "<Shake:Clic——>"
  },
  AvgDialog_117503_Content_93 = {
    Text = "Eh, quel bruit ?"
  },
  AvgDialog_117503_Content_94 = {
    Text = "Tu te retournes pour chercher l'origine du son, mais le pont est silencieux, sans aucune trace humaine."
  },
  AvgDialog_117503_Content_95 = {
    Text = "(Est-ce une illusion ?)"
  },
  AvgDialog_117503_Content_96 = {
    Text = "<Shake:Ploc Ploc Ploc—>"
  },
  AvgDialog_117503_Content_97 = {Text = "Hein ?!"},
  AvgDialog_117503_Content_98 = {
    Text = "Au fond de l'eau, d'innombrables petits corps se répandent densément à la surface de la mer, avec un halo trouble flottant évoquant des images d'éruptions cutanées humaines."
  },
  AvgDialog_117503_Content_99 = {
    Text = "Ce sont des... poissons ?"
  },
  AvgDialog_117504_Content_1 = {
    Text = "Cérémonie de pilotage"
  },
  AvgDialog_117504_Content_10 = {
    Text = "Je prépare le rituel de navigation avec Faros, les êtres spirituels se rassemblent naturellement, se transformant en nutriments pour le rituel."
  },
  AvgDialog_117504_Content_100 = {
    Text = "Cette voix t'appelle——"
  },
  AvgDialog_117504_Content_101 = {
    Text = "<Italic:<Red:Sauvez-moi>>"
  },
  AvgDialog_117504_Content_102 = {
    Text = "L'impulsion incontrôlable te pousse à sauter du mât."
  },
  AvgDialog_117504_Content_103 = {
    Text = "Tu dois tenir sa main et la libérer de ce rituel sanglant."
  },
  AvgDialog_117504_Content_104 = {
    Text = "Murphy, ne continue pas le rituel ! Tu vas mourir ! Échappe-toi avec moi !"
  },
  AvgDialog_117504_Content_105 = {
    Text = "Es-tu fou ? Oser profaner la Mère divine !"
  },
  AvgDialog_117504_Content_106 = {
    Text = "Je ne suis pas le Murphy que tu connais, j'ai fait mon choix !"
  },
  AvgDialog_117504_Content_107 = {
    Text = "Bien que tu ne sois pas le Murphy que je connais, j'ai vu de nombreux Éveilleurs de l'Origine : Ramona : Vétuste, Helot : Enchaînée, Doll : Dissoute…"
  },
  AvgDialog_117504_Content_108 = {
    Text = "Ils sont tombés dans la folie simplement parce qu'ils ont subi plus de malheurs sur le chemin ici. Les épreuves ne changeront pas la couleur de leurs cœurs."
  },
  AvgDialog_117504_Content_109 = {
    Text = "Ne t'attarde plus sur ce chemin perdu, fuyons ensemble !"
  },
  AvgDialog_117504_Content_11 = {
    Text = "Rituel de pilotage ?"
  },
  AvgDialog_117504_Content_110 = {
    Text = "Fuir... ? Où pouvons-nous encore fuir ?"
  },
  AvgDialog_117504_Content_111 = {
    Text = "Ici, c'est déjà le monde parfait, toute tentative d'évasion ne fera que plonger dans une chute plus profonde et dans une boucle plus désespérée."
  },
  AvgDialog_117504_Content_112 = {
    Text = "Regarde derrière toi, la gigantesque vague qui déferle derrière toi."
  },
  AvgDialog_117504_Content_113 = {
    Text = "Accompagnée de l'agitation intense de la surface de la mer, des milliers de Marcheurs des mers et de serpents d'eau entourent la statue en ivoire d'une blancheur macabre, s'élevant avec un sentiment d'oppression sans fin."
  },
  AvgDialog_117504_Content_114 = {
    Text = "Mère divine... je vous demande pardon, je ne peux plus suivre vos instructions, je ne peux plus tolérer cette profanation envers le divin."
  },
  AvgDialog_117504_Content_115 = {
    Text = "Miryam s'agenouille à la proue du bateau, rendant un hommage respectueux dans la direction où l'horizon marin se divise."
  },
  AvgDialog_117504_Content_116 = {
    Text = "Ô divin, ô croyants au cœur sincère. Les profanateurs qui tentent d'entraver le rituel sont déjà apparus."
  },
  AvgDialog_117504_Content_117 = {
    Text = "Veuillez châtier les impies qui osent offenser la Mère divine."
  },
  AvgDialog_117504_Content_118 = {
    Text = "Elles montent silencieusement sur le pont du paquebot, marchant avec des pas humides et étranges sur une échelle invisible formée par les vagues."
  },
  AvgDialog_117504_Content_119 = {
    Text = "<Big:<Shake:Va, mords-les, déchire-les !!>>"
  },
  AvgDialog_117504_Content_12 = {
    Text = "La Mère divine nous guidera pour atteindre la Lémurie qui émerge."
  },
  AvgDialog_117504_Content_13 = {
    Text = "Voyant ton air perplexe, le visage de Miryam devient étonnamment doux."
  },
  AvgDialog_117504_Content_14 = {
    Text = "Tu dois avoir beaucoup de doutes, ne t'inquiète pas, par ordre de la Mère divine, je vais te répondre un par un."
  },
  AvgDialog_117504_Content_15 = {
    Text = "…Pour être honnête, ton changement d'attitude est déjà assez surprenant."
  },
  AvgDialog_117504_Content_16 = {
    Text = "En repensant à votre parcours, il n'y avait aucune raison pour le conflit entre vous et les Marcheurs des mers."
  },
  AvgDialog_117504_Content_17 = {
    Text = "Comment est-ce possible ? J'ai déjà été témoin de rituels païens des Marcheurs des mers..."
  },
  AvgDialog_117504_Content_18 = {
    Text = "C'était un malentendu. Les Marcheurs des mers tiennent un rituel secret pour collecter l'énergie nécessaire au fonctionnement de ce navire."
  },
  AvgDialog_117504_Content_19 = {
    Text = "Alors que la plupart des humains se sont transformés en cendres, les noyaux d'argent accumulés ici et là suffisent à satisfaire nos besoins."
  },
  AvgDialog_117504_Content_2 = {
    Text = "Dans l'odeur de poisson, la femme en robe violette fronça les sourcils et se tourna vers Faros."
  },
  AvgDialog_117504_Content_20 = {
    Text = "Par conséquent, les Marcheurs des mers s'enfoncent dans Nekropolis, collectant les Cœurs d'argent exsudés par les défunts. Cet acte, cependant, contredit l'habitude du maître de Nekropolis, Doresain, de consommer des cadavres."
  },
  AvgDialog_117504_Content_21 = {
    Text = "D'après ce que nous savons sur l'Université de Misargh, vous utilisez également des Cœurs d'argent raffinés comme source d'énergie, n'est-ce pas ?"
  },
  AvgDialog_117504_Content_22 = {
    Text = "La clé en argent que tu as sur ta poitrine est fabriquée avec la technique du cœur d'argent."
  },
  AvgDialog_117504_Content_23 = {
    Text = "Tu n'arrives pas à reconnaître cela pour l'instant, mais tu ne peux pas non plus le contredire, alors tu changes de sujet."
  },
  AvgDialog_117504_Content_24 = {
    Text = "Miryam... quel est ton but avec les Marcheurs des mers ?"
  },
  AvgDialog_117504_Content_25 = {
    Text = "Il est naturel de reconstruire le Royaume divin et de revitaliser Lémuria."
  },
  AvgDialog_117504_Content_26 = {
    Text = "En ce moment où mon maître est déjà descendu, rien n'est plus urgent que le retour au Royaume Divin et la renaissance de la grande Lémuria."
  },
  AvgDialog_117504_Content_27 = {
    Text = "Tu parles de la descente… Tulu ?"
  },
  AvgDialog_117504_Content_28 = {
    Text = "Son esprit est encore à moitié endormi, mais il tiendra finalement sa promesse et nous guidera vers le Royaume Divin."
  },
  AvgDialog_117504_Content_29 = {
    Text = "Lémurie... où est-ce ?"
  },
  AvgDialog_117504_Content_3 = {
    Text = "Rassemblez la spiritualité ici."
  },
  AvgDialog_117504_Content_30 = {
    Text = "Au-dessus des cieux, en dessous des mers. L'oracle n'a pas révélé davantage."
  },
  AvgDialog_117504_Content_31 = {
    Text = "Après avoir prononcé cette phrase codée, Miryam tomba dans le silence."
  },
  AvgDialog_117504_Content_32 = {
    Text = "Faros, qui a rassemblé tous les cœurs d'argent, se tient à côté de Miryam, tenant une boîte en bois remplie de perles d'argent."
  },
  AvgDialog_117504_Content_33 = {
    Text = "Faros, pourquoi as-tu rejoint les Marcheurs des mers ?"
  },
  AvgDialog_117504_Content_34 = {
    Text = "Cela a-t-il besoin d'être demandé ? Parce que le royaume marin est juste là. Le royaume marin m'appelle."
  },
  AvgDialog_117504_Content_35 = {
    Text = "Peu importe où je vais, j'entends son appel, comme le ressac des vagues jour après jour."
  },
  AvgDialog_117504_Content_36 = {
    Text = "Elle regarde au loin, ses paroles ne sont qu'un vide."
  },
  AvgDialog_117504_Content_37 = {
    Text = "Ça dépend, aujourd'hui devrait faire beau. Regarde, le soleil est sur le point de se lever."
  },
  AvgDialog_117504_Content_38 = {Text = "soleil…"},
  AvgDialog_117504_Content_39 = {
    Text = "Vous suivez son regard——"
  },
  AvgDialog_117504_Content_4 = {
    Text = "Oui, Grand Prêtre."
  },
  AvgDialog_117504_Content_40 = {
    Text = "Gronde, gronde. Le battement de ton cœur semble presque briser tes tympans."
  },
  AvgDialog_117504_Content_41 = {
    Text = "<Shake:Attendez, où est le... soleil dans le ciel?>"
  },
  AvgDialog_117504_Content_42 = {
    Text = "Soleil ? Le soleil n'est-il pas là-bas ?"
  },
  AvgDialog_117504_Content_43 = {
    Text = "Non, non, ce n'est pas ce soleil !"
  },
  AvgDialog_117504_Content_44 = {
    Text = "À l'horizon, se lève un soleil que tu aurais dû désirer en rêve, diffusant une lumière douce à travers le brouillard léger comme une étoffe."
  },
  AvgDialog_117504_Content_45 = {
    Text = "Ce n'est pas ce soleil ? Il y a quel autre soleil ?"
  },
  AvgDialog_117504_Content_46 = {
    Text = "Cette lumière chaude semble émettre une chaleur anormale, te laissant sans raison, la gorge sèche, et les mots qui sortent de ta bouche sont d'une grande difficulté à comprendre."
  },
  AvgDialog_117504_Content_47 = {
    Text = "Cela devrait être un soleil noir et sans lumière !"
  },
  AvgDialog_117504_Content_48 = {
    Text = "Je n'ai jamais entendu parler ni vu de soleil noir..."
  },
  AvgDialog_117504_Content_49 = {
    Text = "Faros, quelle année est-ce cette année ?"
  },
  AvgDialog_117504_Content_5 = {
    Text = "Faros était à genoux, ramassant les débris puants un par un."
  },
  AvgDialog_117504_Content_50 = {
    Text = "L'an 1920. Y a-t-il quelque chose qui ne va pas ?"
  },
  AvgDialog_117504_Content_51 = {
    Text = "Ce n'est pas l'ère Aluviion... Je suis en effet dans un nouveau monde..."
  },
  AvgDialog_117504_Content_52 = {
    Text = "Ne vous laissez pas distraire, la Mère divine est arrivée."
  },
  AvgDialog_117504_Content_53 = {
    Text = "En tant qu'invité approuvé par la Mère divine, je te permettrai d'observer ici la cérémonie d'initiation la plus solennelle."
  },
  AvgDialog_117504_Content_54 = {
    Text = "Mais ne vous éloignez pas d'ici, sinon je ferai décapiter le profanateur et l'exposerai au public."
  },
  AvgDialog_117504_Content_55 = {
    Text = "Une petite équipe noir-violette vient de l'arrière du bateau de croisière, leurs pas synchronisés de manière étrange, se glissant sur le pont sous vos pieds."
  },
  AvgDialog_117504_Content_56 = {
    Text = "La fille en tête portait une robe blanche morne et dénudée, tenant dans ses bras un fardeau obèse et gonflé, son expression étant indistincte sous le voile noir."
  },
  AvgDialog_117504_Content_57 = {Text = "新增"},
  AvgDialog_117504_Content_58 = {
    Text = "La file se stabilise rapidement à l'avant du navire, chaque pion noir semble déjà bien connaître son point de chute."
  },
  AvgDialog_117504_Content_59 = {
    Text = "Une paire de pieds nus s'enfonce dans le chemin étroit laissé pour elle au milieu de la formation, derrière elle, d'innombrables petits morceaux argentés tombent en cascade."
  },
  AvgDialog_117504_Content_6 = {
    Text = "Son front irradiait une douce lueur, et après quelques secondes, le banc de poissons ne laissa que des restes argentés."
  },
  AvgDialog_117504_Content_60 = {
    Text = "Merci, Mère, pour le sang ombilical ! Nous allons engloutir le feu spirituel, boire la prière de sang, et laisser des milliers d'âmes pieuses se transformer en balises !"
  },
  AvgDialog_117504_Content_61 = {
    Text = "Les monstres se traînent au sol, se disputant les perles argentées sur le sol."
  },
  AvgDialog_117504_Content_62 = {
    Text = "……Miryam……"
  },
  AvgDialog_117504_Content_63 = {
    Text = "Miryam se penche humblement au sol, les mains soutenant un plateau en argent recouvert de velours noir, au centre duquel repose une dague scintillante."
  },
  AvgDialog_117504_Content_64 = {
    Text = "Chère Mère divine, veuillez guider la lignée du Roi Dieu, conduire le Marcheur des mers égaré et nous montrer l'emplacement de Lémuria."
  },
  AvgDialog_117504_Content_65 = {
    Text = "La fille prend la dague."
  },
  AvgDialog_117504_Content_66 = {
    Text = "Ô roi divin…"
  },
  AvgDialog_117504_Content_67 = {
    Text = "La dague s'enfonce dans le berceau, une goutte de sang visqueux semble avoir une conscience propre, flottant et seCondensation."
  },
  AvgDialog_117504_Content_68 = {
    Text = "<Change>Je me guide par le sang des dieux."
  },
  AvgDialog_117504_Content_69 = {
    Text = "Tous les croyants s'agenouillent au sol, les deux mains levées vers le ciel, et tranchent leur poignet gauche recouvert d'écailles avec un petit couteau fin."
  },
  AvgDialog_117504_Content_7 = {
    Text = "Miryam... ces poissons volants... c'est toi et Faros qui les avez invoqués ?"
  },
  AvgDialog_117504_Content_70 = {
    Text = "D'innombrables fils argentés s'entrelacent autour des perles de sang, s'étendant des poignets de centaines de croyants, suivant une trajectoire indéfinissable vers un même point."
  },
  AvgDialog_117504_Content_71 = {
    Text = "<Change>En tant que sacrifice des esprits de toutes choses."
  },
  AvgDialog_117504_Content_72 = {
    Text = "Des gouttes de sang noir tournent, seNingrent, et sautent dans une statue en ivoire laiteux, formant un réseau de filaments sanguins serrés."
  },
  AvgDialog_117504_Content_73 = {
    Text = "La statue en ivoire semble avoir été activée par une vitalité, survolant la bête d'acier avant de plonger directement dans l'océan silencieux."
  },
  AvgDialog_117504_Content_74 = {
    Text = "<Change>Veuillez déchirer l'abîme illusoire et nous guider directement vers votre royaume."
  },
  AvgDialog_117504_Content_75 = {
    Text = "Soudain, la mer et le ciel tremblent, l'immense océan déchaîné se déferle, émettant un cri de douleur semblable à celui d'une bête en travail."
  },
  AvgDialog_117504_Content_76 = {
    Text = "Les vagues dansent follement, gémissant, se solidifiant en un mur de tremblements."
  },
  AvgDialog_117504_Content_77 = {
    Text = "Mère divine, il semble que la quantité de ces esprits soit légèrement insuffisante…"
  },
  AvgDialog_117504_Content_78 = {
    Text = "Pas de problème."
  },
  AvgDialog_117504_Content_79 = {
    Text = "La jeune fille lève le voile, se retournant vers les êtres agenouillés."
  },
  AvgDialog_117504_Content_8 = {
    Text = "Miryam semble enfin remarquer ta présence, inclinant légèrement la tête dans ta direction."
  },
  AvgDialog_117504_Content_80 = {
    Text = "Veuillez, Mère divine, accorder votre sang sacré !"
  },
  AvgDialog_117504_Content_81 = {
    Text = "<Big:<Shake:Veuillez, Mère divine, accorder votre sang sacré !>>"
  },
  AvgDialog_117504_Content_82 = {
    Text = "Les vagues de voix s'élevaient de plus en plus, et au milieu de ces cris, les doigts de la jeune fille se dirigeaient vers sa poitrine."
  },
  AvgDialog_117504_Content_83 = {
    Text = "Ses ongles étaient aussi aigus que des lames, déchirant sa poitrine le long de la cicatrice violette, révélant le seul cœur restant."
  },
  AvgDialog_117504_Content_84 = {
    Text = "<Shake:Capture, chasse ! Si j'offre la chair et le sang de la Mère divine, tu forgeras pour moi un escalier inversé reliant le Royaume Divin !>"
  },
  AvgDialog_117504_Content_85 = {
    Text = "Les fidèles se précipitèrent en avant. Leurs pieds palmés et leurs pinces étranges atteignaient avec impatience le corps frêle de la Mère divine."
  },
  AvgDialog_117504_Content_86 = {
    Text = "Ils aspirent son sang, dévorent sa chair. Des fils rouges prolifèrent violemment, se précipitant dans l'Aequor."
  },
  AvgDialog_117504_Content_87 = {
    Text = "L'Écarlate prolifère follement à partir du point d'impact de la statue, les vagues se solidifiant en des millions de coraux de sang."
  },
  AvgDialog_117504_Content_88 = {
    Text = "La cérémonie est terminée ! Reculez !"
  },
  AvgDialog_117504_Content_89 = {
    Text = "Elle marcha sur le corps des Marcheurs des mers qui se pressaient devant la jeune fille, enroulant le corps de Murphy dans une robe de prêtre noire. Sous la robe, le sang coulait encore à flots."
  },
  AvgDialog_117504_Content_9 = {
    Text = "Tu n'es pas censé être dans la chambre de la Mère divine ? Pourquoi..."
  },
  AvgDialog_117504_Content_90 = {
    Text = "Lémurie ! Lémurie ! Le sang de la Mère divine a désigné le chemin de Lémurie !"
  },
  AvgDialog_117504_Content_91 = {
    Text = "Parmi des milliers de lignes de sang, tu aperçois un fil argenté anormal. Ce fil argenté naît de ta poitrine et s'étend vers le haut, s'étendant..."
  },
  AvgDialog_117504_Content_92 = {
    Text = "Jusqu'au-delà du ciel, à un endroit inconnu."
  },
  AvgDialog_117504_Content_93 = {
    Text = "La jeune fille semble également réaliser l'existence de ce fil argenté, elle lève la tête, ses pupilles tremblent soudainement, son regard horrifié te transperce."
  },
  AvgDialog_117504_Content_94 = {Text = "新增"},
  AvgDialog_117504_Content_95 = {
    Text = "Au moment où vos regards se croisent, une force immense et invisible te tire, indifférente à ta résistance, te plongeant dans une illusion terrifiante semblable à un cauchemar."
  },
  AvgDialog_117504_Content_96 = {
    Text = "…c'était le soleil noir impur que tu avais vu."
  },
  AvgDialog_117504_Content_97 = {
    Text = "Son de tambourin ?"
  },
  AvgDialog_117504_Content_98 = {
    Text = "Non, c'est le battement de cœur."
  },
  AvgDialog_117504_Content_99 = {
    Text = "long, haletant, aux portes de la mort, déjà disparu depuis des éons mais ressuscité après un long rêve..."
  },
  AvgDialog_118123_Content_1 = {
    Text = "Chevalier du moulin à vent"
  },
  AvgDialog_118123_Content_10 = {
    Text = "C'est en ayant de telles aspirations que j'ai accordé une chance à ce type."
  },
  AvgDialog_118123_Content_11 = {
    Text = "(Résultat, ça n'a toujours aucune utilité...)"
  },
  AvgDialog_118123_Content_12 = {
    Text = "Comme prévu... Il faut encore que je donne un coup de main."
  },
  AvgDialog_118123_Content_13 = {
    Text = "Tu cours comme une mouche sans tête ! Où comptes-tu aller !"
  },
  AvgDialog_118123_Content_14 = {
    Text = "Comme vient de le dire William, l'Aîné, les canots de sauvetage vont de la pont au fond du navire !"
  },
  AvgDialog_118123_Content_15 = {
    Text = "Le champ de vision sur le pont est si vaste, je vois que tu veux te servir de toi-même pour nourrir les poisson-nageurs !"
  },
  AvgDialog_118123_Content_16 = {
    Text = "Dans le cycle précédent, c'est toi-même qui es allé nourrir les hommes-poissons !"
  },
  AvgDialog_118123_Content_17 = {
    Text = "Mince alors, ne contredisez pas la Mère divine ! Maintenant, courez immédiatement au poste de pilotage, il y a une structure qui mène à la capsule de sauvetage !"
  },
  AvgDialog_118123_Content_18 = {
    Text = "Lâchez-moi, mes cheveux sont en désordre comme un nid d'oiseau !"
  },
  AvgDialog_118123_Content_19 = {
    Text = "Tu es mon otage important, ce n'est pas le moment de penser à l'image ! Alors, je te prie de faire preuve de patience, Mère divine !"
  },
  AvgDialog_118123_Content_2 = {
    Text = "Tu sautes et sens le vent tranchant couper tes joues, puis la corde à ta taille se resserre soudainement, interrompant ta chute."
  },
  AvgDialog_118123_Content_20 = {
    Text = "<Shake:Faites attention, les poursuivants de Miryam sont arrivés !>"
  },
  AvgDialog_118123_Content_3 = {
    Text = "Hé ! Que fais-tu au juste !"
  },
  AvgDialog_118123_Content_4 = {
    Text = "Tu dégaines un petit couteau, coupe la corde, puis atterris en sautant."
  },
  AvgDialog_118123_Content_5 = {
    Text = "Tu comptes vraiment courir avec moi sur le dos ? Ils vont bientôt nous rattraper, n'est-ce pas !"
  },
  AvgDialog_118123_Content_6 = {
    Text = "Ah ah, c'est vraiment idiot à mourir !"
  },
  AvgDialog_118123_Content_7 = {
    Text = "Qu'est-ce que je pensais, d'avoir un peu d'espoir pour cet idiot."
  },
  AvgDialog_118123_Content_8 = {
    Text = "Cette fuite de {Male=il,Female=elle} est plus imprudente que chacune de celles que j'ai entreprises par le passé."
  },
  AvgDialog_118123_Content_9 = {
    Text = "Si ce monde existe aussi <Jaune:%player%>, alors la direction de l'histoire serait-elle différente ?"
  },
  AvgDialog_118124_Content_1 = {
    Text = "Tu déchires le rideau et attaches Murphy aux griffes déchaînées."
  },
  AvgDialog_118124_Content_10 = {
    Text = "Si tu observes attentivement nous trois, tu sauras que la princesse a quelqu'un d'autre."
  },
  AvgDialog_118124_Content_11 = {
    Text = "William attacha fermement la corde autour de votre taille et celle de Murphy."
  },
  AvgDialog_118124_Content_12 = {
    Text = "Prends bien soin de la princesse, ne la perds pas ! Il y a des canots de sauvetage dans la cale, nous nous retrouverons là-bas !"
  },
  AvgDialog_118124_Content_13 = {
    Text = "Trois, deux, un, saute !"
  },
  AvgDialog_118124_Content_2 = {
    Text = "C'est fait ! Ne bouge pas, fais attention à ne pas te blesser !"
  },
  AvgDialog_118124_Content_3 = {
    Text = "C'est vraiment insupportable ! Si tu continues comme ça, je vais te mordre !"
  },
  AvgDialog_118124_Content_4 = {
    Text = "C'est toujours mieux que tu ne fasses pas de manières, Murphy."
  },
  AvgDialog_118124_Content_5 = {
    Text = "Moins de bavardages ! Je te ferai payer pour l'humiliation de la Mère divine lorsque je retrouverai ma liberté !"
  },
  AvgDialog_118124_Content_6 = {
    Text = "Cependant, est-ce que les bruits de pas dehors deviennent de plus en plus fréquents ?"
  },
  AvgDialog_118124_Content_7 = {
    Text = "Le bruit des pas « pouf pouf » se rassemble en une mer, des corps petits et robustes s'écrasent constamment contre la porte du salon, produisant un bruit sourd de « bang bang »."
  },
  AvgDialog_118124_Content_8 = {
    Text = "Allons, sortons par la fenêtre ! Prends ça, puis saute sur le pont !"
  },
  AvgDialog_118124_Content_9 = {
    Text = "Utiliser le drap pour faire des nœuds...? William, tu ressembles à une princesse fugitive d'un conte de fées."
  },
  AvgDialog_118125_Content_1 = {
    Text = "Princesse de la tour"
  },
  AvgDialog_118125_Content_10 = {
    Text = "Tu observes attentivement, il y a deux fils de fil déchirés au total, et il reste encore quatre tours de fil sur le rouet."
  },
  AvgDialog_118125_Content_11 = {
    Text = "J'ai encore quatre chances... n'est-ce pas ?"
  },
  AvgDialog_118125_Content_12 = {
    Text = "Elle hocha la tête, puis secoua la tête."
  },
  AvgDialog_118125_Content_13 = {
    Text = "J'ai entendu ta voix, tu n'es pas censé ne pas parler... tu n'es pas autorisé à dire quoi que ce soit... ?"
  },
  AvgDialog_118125_Content_14 = {
    Text = "Elle ouvrit la bouche, mais seul un silence éternel en sortit."
  },
  AvgDialog_118125_Content_15 = {
    Text = "Elle regarda en arrière vers le ciel lointain, tu suivis son regard et regardas au loin."
  },
  AvgDialog_118125_Content_16 = {
    Text = "Il n'y a qu'un soleil noir immergé dans l'eau."
  },
  AvgDialog_118125_Content_17 = {
    Text = "Ahem, ahem... !"
  },
  AvgDialog_118125_Content_18 = {
    Text = "Tu te réveilles brusquement de ton lit, toussant bruyamment à cause de la douleur de la noyade."
  },
  AvgDialog_118125_Content_19 = {
    Text = "Encore une fois... le cycle..."
  },
  AvgDialog_118125_Content_2 = {
    Text = "Le vent marin est salé et poisseux, laissant une amertume persistante lorsque vous l'avalez."
  },
  AvgDialog_118125_Content_20 = {
    Text = "Les habitants du royaume marin soit te surprennent, soit restent indifférents ; leur attention, qu'elle soit sincère ou fausse, est désormais séparée de toi par des couches de barrières. Le seul visage qui persiste dans ton esprit est celui de Murphy, juste avant la fin du dernier cycle."
  },
  AvgDialog_118125_Content_21 = {
    Text = "Sauve-moi... Si c'est toi, tu peux certainement le faire..."
  },
  AvgDialog_118125_Content_22 = {
    Text = "Puis l'obscurité a englouti tout, se transformant en un doute indélébile dans l'esprit."
  },
  AvgDialog_118125_Content_23 = {
    Text = "De toute façon, tu dois d'abord te retrouver avec William."
  },
  AvgDialog_118125_Content_24 = {
    Text = "Goliath et Miryam marchent dans un couloir vide, les pas résonnant devant et derrière eux."
  },
  AvgDialog_118125_Content_25 = {
    Text = "Passant devant des fresques baroques de la Madone, de petites lanternes remplaçant les appliques en laiton, et un groupe de chambres silencieuses et vides."
  },
  AvgDialog_118125_Content_26 = {
    Text = "Ils n'ont pas de contact, pas de paroles, une atmosphère tendue plane entre les deux."
  },
  AvgDialog_118125_Content_27 = {
    Text = "Miryam s'arrête à la porte de la cabine du capitaine et pousse la porte."
  },
  AvgDialog_118125_Content_28 = {
    Text = "Goliath fit quelques pas et se stoppa derrière elle."
  },
  AvgDialog_118125_Content_29 = {
    Text = "Hé, Miryam. Cette petite fille te ment."
  },
  AvgDialog_118125_Content_3 = {Text = "新增"},
  AvgDialog_118125_Content_30 = {
    Text = "Que se passe-t-il ? À cette heure-ci, vous devriez être en train de surveiller la cabine de pilotage, non ?"
  },
  AvgDialog_118125_Content_31 = {
    Text = "Si la femme qui maintient la salle de puissance a le moindre écart, je ne m'adresserai qu'à toi."
  },
  AvgDialog_118125_Content_32 = {
    Text = "Moins de bavardages inutiles, Caecus est là, ces matelots idiots ne peuvent pas soulever de vagues."
  },
  AvgDialog_118125_Content_33 = {
    Text = "Il n'y a qu'un seul problème, cette petite fille te trompe."
  },
  AvgDialog_118125_Content_34 = {
    Text = "Philistin, parler des droits de la Mère divine n'est pas votre habitude."
  },
  AvgDialog_118125_Content_35 = {
    Text = "Tu sais que ce bateau n'atteindra jamais cette Lémuria, n'est-ce pas ?"
  },
  AvgDialog_118125_Content_36 = {
    Text = "… Goliath."
  },
  AvgDialog_118125_Content_37 = {
    Text = "Tu n'es qu'un chien de chasse que j'élève, tant que je ne t'ai pas ordonné de brandir ta grande lame contre un ennemi, il n'y a pas de place ici pour tes discours grandiloquents."
  },
  AvgDialog_118125_Content_38 = {
    Text = "Avant d'accoster, tu n'as qu'à bien gérer les matelots à bord pour ne pas perturber le sommeil de la Mère divine."
  },
  AvgDialog_118125_Content_39 = {
    Text = "S'il y a quelque chose que tu dois savoir..."
  },
  AvgDialog_118125_Content_4 = {
    Text = "La femme tenant le rouet te regarde avec tristesse."
  },
  AvgDialog_118125_Content_40 = {
    Text = "<Shake:Si ce navire a la moindre chance d'atteindre Lémuria, c'est grâce à la lumière de la Mère divine.>"
  },
  AvgDialog_118125_Content_41 = {
    Text = "Tsk, sale femme obstinée..."
  },
  AvgDialog_118125_Content_42 = {
    Text = "J'ai déjà dit les bonnes et les mauvaises choses."
  },
  AvgDialog_118125_Content_43 = {
    Text = "Pour ce qui est de la suite, je ne pourrai pas en être tenu responsable."
  },
  AvgDialog_118125_Content_44 = {
    Text = "Caecus, exécute le plan."
  },
  AvgDialog_118125_Content_45 = {Text = "Ici !"},
  AvgDialog_118125_Content_46 = {
    Text = "Avant que le rituel ne soit terminé, prenez le contrôle du navire."
  },
  AvgDialog_118125_Content_47 = {
    Text = "Tu erres sur le pont, cherchant désespérément des indices pouvant mener à la cachette de William."
  },
  AvgDialog_118125_Content_48 = {
    Text = "Si je ne me trompe pas, c'est à cet endroit..."
  },
  AvgDialog_118125_Content_49 = {
    Text = "Tu soulèves la trappe le long de la fente sur le pont, puis tu grises les dents et sautes en bas."
  },
  AvgDialog_118125_Content_5 = {
    Text = "As-tu quelque chose à me dire ?"
  },
  AvgDialog_118125_Content_50 = {
    Text = "<Shake:Pouah, pff...>"
  },
  AvgDialog_118125_Content_51 = {
    Text = "Tu craches le roseau que tu as mis dans ta bouche, regrettant d'avoir choisi la méthode de chute en avant."
  },
  AvgDialog_118125_Content_52 = {
    Text = "William, l'Aîné, ne te cache pas, je sais que tu es ici !"
  },
  AvgDialog_118125_Content_53 = {
    Text = "Après un moment, un léger bruissement se fit entendre derrière la botte de paille."
  },
  AvgDialog_118125_Content_54 = {
    Text = "C'est irrationnel."
  },
  AvgDialog_118125_Content_55 = {
    Text = "… si tu as une telle capacité à me localiser avec précision, tu m'aurais déjà rattrapé dans les rues de Londres."
  },
  AvgDialog_118125_Content_56 = {
    Text = "Parle-moi bien... Qu'est-ce que tu as vécu depuis que tu es monté à bord de ce navire ?"
  },
  AvgDialog_118125_Content_57 = {Text = "新增"},
  AvgDialog_118125_Content_58 = {
    Text = "Tu as brièvement résumé l'histoire du cycle."
  },
  AvgDialog_118125_Content_59 = {
    Text = "Désolé, il sera trop tard quand la cérémonie commencera. \n William, l'Aîné, nous devons lever l'embuscade dans la chambre de Murphy avant cela."
  },
  AvgDialog_118125_Content_6 = {
    Text = "La femme hocha la tête."
  },
  AvgDialog_118125_Content_60 = {
    Text = "Va, par ce chemin, il n'y a pas d'œil ici."
  },
  AvgDialog_118125_Content_61 = {
    Text = "Tu veux dire que Goliath complote une rébellion et que je dois me cacher avec toi."
  },
  AvgDialog_118125_Content_62 = {
    Text = "Et tout cela, c'est parce que tu as vécu un retour en arrière dans le temps, n'est-ce pas ?"
  },
  AvgDialog_118125_Content_63 = {
    Text = "Trop absurde, trop ridicule... à moins que ma raison ne s'effondre...<Shake:Hmm...>"
  },
  AvgDialog_118125_Content_64 = {
    Text = "Désolé, il n'y a plus d'espace pour tes caprices ici."
  },
  AvgDialog_118125_Content_65 = {
    Text = "Aîné William !"
  },
  AvgDialog_118125_Content_66 = {
    Text = "Rassure-toi, je me doutais que ce ne serait pas si facile, j'ai déjà coupé les bruits venant du salon."
  },
  AvgDialog_118125_Content_67 = {
    Text = "Emmène-la d'abord !"
  },
  AvgDialog_118125_Content_7 = {
    Text = "Cela a-t-il un rapport avec la réincarnation ?"
  },
  AvgDialog_118125_Content_8 = {
    Text = "La femme secoue la tête, ses doigts effleurent le fil du rouet, effectuant un tour dans le sens des aiguilles d'une montre, s'arrêtant au point de départ."
  },
  AvgDialog_118125_Content_9 = {
    Text = "Avec la rotation du rouet, le fil initial se désintègre et se casse."
  },
  AvgDialog_118699_Content_1 = {
    Text = "Notre souhait"
  },
  AvgDialog_118699_Content_10 = {
    Text = "Plus de force spirituelle intense ?... Je comprends, je vais envoyer une notification à tous les éveilleurs."
  },
  AvgDialog_118699_Content_11 = {
    Text = "Sur le terrain de jeu au crépuscule, Ogier a terminé comme d'habitude sa journée d'entraînement régulier, sans aucune réduction par rapport aux fois précédentes."
  },
  AvgDialog_118699_Content_12 = {
    Text = "Aujourd'hui, j'ai encore battu un peu mon précédent record..."
  },
  AvgDialog_118699_Content_13 = {
    Text = "Essuyant la sueur qui coulait, la lance lourde touchant le sol, Ogier se retourna, ne voyant plus la silhouette souriante qui l'avait encouragé, seulement son ombre solitaire s'étirant sur le sol."
  },
  AvgDialog_118699_Content_14 = {
    Text = "La rapière de Lotan a fait voler au-delà des deux armes standard des enquêteurs dans l'afterimage, mettant fin à une autre bataille qui n'a duré qu'une minute."
  },
  AvgDialog_118699_Content_15 = {
    Text = "Que se passe-t-il avec les nouveaux-nés d'aujourd'hui ? Leur qualité est vraiment trop mauvaise, encore une fois !"
  },
  AvgDialog_118699_Content_16 = {
    Text = "Avant qu'elle n'ait eu le temps de brandir son épée pour continuer à maltraiter les gens, les deux nouveaux-nés devant elle, essoufflés, avaient déjà commencé à joindre les mains en suppliant."
  },
  AvgDialog_118699_Content_17 = {
    Text = "Tsk, ennui…"
  },
  AvgDialog_118699_Content_18 = {
    Text = "En pensant à un gars qui pourrait lui offrir un combat exaltant, Lotan regarda le coucher de soleil et soupira, se retournant avec ennui pour s'éloigner."
  },
  AvgDialog_118699_Content_19 = {
    Text = "Aigis coupa un morceau de fil, déplia soigneusement le pull qu'elle venait de tricoter et le mit à plat, puis se mit sur la pointe des pieds pour le suspendre dans l'armoire pleine de tissus."
  },
  AvgDialog_118699_Content_2 = {
    Text = [[
Monde de Kadath
maintenant]]
  },
  AvgDialog_118699_Content_20 = {
    Text = "Des motifs torsadés, des losanges, des ondulations, de petites fleurs et des motifs animaliers, Aigis tisse de plus en plus de styles."
  },
  AvgDialog_118699_Content_21 = {
    Text = "Grand{Male=M. Gardien,Female=Mlle Gardienne}, qu'est-ce que tu aimerais..."
  },
  AvgDialog_118699_Content_22 = {
    Text = "La petite souris grise astucieuse se faufila à travers l'ouverture de la porte, plaçant fidèlement une bague brillante dans la main de son partenaire."
  },
  AvgDialog_118699_Content_23 = {
    Text = "Eh bien, bien joué, Brun."
  },
  AvgDialog_118699_Content_24 = {
    Text = "La petite souris regardait son partenaire bâiller d'ennui, lançant négligemment l'anneau dans une boîte en bois ouverte à côté d'eux, la boîte débordant déjà d'un mélange chaotique de « collectibles »."
  },
  AvgDialog_118699_Content_25 = {Text = "Cric..."},
  AvgDialog_118699_Content_26 = {
    Text = "Cette personne n'est pas venue au dortoir pour fouiller dans son coffre au trésor depuis longtemps, ordonnant au patron de lui rendre chaque objet un par un, mais pourquoi, après cela, le patron est-il toujours aussi sombre ?"
  },
  AvgDialog_118699_Content_27 = {
    Text = "La fille obéissante est assise sagement devant le bureau, ouvrant un autre livre d'histoires."
  },
  AvgDialog_118699_Content_28 = {
    Text = "Un empilement de livres pour enfants déjà lus s'est accumulé dans le coin de la table, et sur le carnet à côté de la fille, elle a noté les idées d'histoires qui lui sont venues à l'esprit."
  },
  AvgDialog_118699_Content_29 = {
    Text = "En pensant à l'excitation, un léger sourire est apparu sur le visage paisible de la fille, tandis que ses pieds se balançaient doucement sous la table."
  },
  AvgDialog_118699_Content_3 = {
    Text = "Le tunnel flou, encore indistinct, s'effondre sous l'assaut soudain de la corrosion terrifiante. Le corps de Ramona émet un grognement, alors qu'elle reprend conscience sous l'appel urgent de l'appareil."
  },
  AvgDialog_118699_Content_30 = {
    Text = "Cette histoire, tout le monde va l'aimer..."
  },
  AvgDialog_118699_Content_31 = {
    Text = "Le crayon faisait un bruit de frottement, enregistrant les fantasmes de l'enfance. Mais bientôt, la fille s'arrêta d'écrire et regarda fixement par la fenêtre."
  },
  AvgDialog_118699_Content_32 = {
    Text = "Mais, Grand{Male=M. Gardien,Female=Mlle Gardienne}, quand pourra-t-il revenir pour emmener Lily tourner un film ?"
  },
  AvgDialog_118699_Content_33 = {Text = "新增"},
  AvgDialog_118699_Content_34 = {
    Text = "Le guerrier versa le sac de vin sur le sol devant la tombe."
  },
  AvgDialog_118699_Content_35 = {
    Text = "Après avoir bu d'un trait le reste de la demi-bouteille de vin, le soldat s'est tu et est parti, ne laissant qu'une couronne de laurier suspendue silencieusement sur la tombe."
  },
  AvgDialog_118699_Content_36 = {
    Text = "Sur la somptueuse nappe en velours, le thé de l'après-midi de la dame est aussi copieux que d'habitude."
  },
  AvgDialog_118699_Content_37 = {
    Text = "Les couteaux et les fourchettes émettent un son de maîtrise en s'entrechoquant avec les assiettes, tandis que le gâteau à la crème délicieuse est porté à la bouche."
  },
  AvgDialog_118699_Content_38 = {
    Text = "Dans un silence excessif, la demoiselle fixe silencieusement la chaise vide en face d'elle, ainsi que la vaisselle réservée à cette personne."
  },
  AvgDialog_118699_Content_39 = {
    Text = "Laisser le maître seul ici, c'est vraiment un serviteur incompétent..."
  },
  AvgDialog_118699_Content_4 = {
    Text = "Ramona ! Pollux ! Comment ça va ?"
  },
  AvgDialog_118699_Content_40 = {
    Text = "Dans un dortoir délibérément laissé vacant, les meubles propres et tout neufs semblaient inhabités, à l'exception d'un pot de jeunes plants fraîchement germés placé près de la fenêtre."
  },
  AvgDialog_118699_Content_41 = {
    Text = "À de rares moments, quelqu'un peut apercevoir derrière cette fenêtre, une femme à la peau couleur miel, penchée sur le rebord, berçant délicatement un jeune plant dans un pot."
  },
  AvgDialog_118699_Content_42 = {
    Text = "Même maintenant, alors que les activités du club reprennent progressivement et deviennent actives, personne n'ose encore déranger cette salle de musique appartenant au maître de l'exécution."
  },
  AvgDialog_118699_Content_43 = {Text = "新增"},
  AvgDialog_118699_Content_44 = {
    Text = "Le rideau est doucement soulevé par le vent nocturne, Hameln se tient devant le piano, regardant au loin dans la direction du clocher."
  },
  AvgDialog_118699_Content_45 = {
    Text = "Devant les touches du piano où nous avons autrefois joué ensemble, il n'y a personne, seulement le son de la flûte qui se répète jour après jour, flottant silencieusement sous la lumière de la lune, sans personne pour l'écouter."
  },
  AvgDialog_118699_Content_46 = {
    Text = "Au fond de la piscine noire, le prisonnier de l'éternelle solitude derrière la porte a maintenant un compagnon endormi."
  },
  AvgDialog_118699_Content_47 = {
    Text = "Ces yeux empreints de compassion s'ouvrent silencieusement, observant cette âme dérivant dans le corps au loin."
  },
  AvgDialog_118699_Content_48 = {
    Text = "Dans le laboratoire du département de recherche, Ramona, qui continue de s'entraîner jour et nuit à la puissance spirituelle, a trempé son uniforme d'entraînement de sueur."
  },
  AvgDialog_118699_Content_49 = {
    Text = "Doll regardait cette silhouette qui se battait, buvant silencieusement une autre tasse de café noir, feuilletant la nouvelle page du rapport d'expérience et continuant à ajuster les données de l'instrument."
  },
  AvgDialog_118699_Content_5 = {
    Text = "Euh... je vais bien, ça a été coupé à temps."
  },
  AvgDialog_118699_Content_50 = {
    Text = "<Small:Ah, le café de Winkle est en effet un peu trop fort...>"
  },
  AvgDialog_118699_Content_51 = {
    Text = "Sur le communicateur qu'elle venait de lâcher, brillait une notification envoyée à tous les éveillés."
  },
  AvgDialog_118699_Content_52 = {
    Text = "Tous les Éveilleurs sur le campus se sont tournés en même temps vers le communicateur qui a soudain sonné, regardant à l'intérieur du communicateur, ce nom qu'ils avaient attendu si longtemps."
  },
  AvgDialog_118699_Content_53 = {
    Text = "À tous les Éveilleurs :\n\nDans un passé récent, nous étions encore en train de lutter contre la catastrophe noire qui dévore tout, et sur la pierre tombale de la Keygrave, de nombreux noms flous sont encore gravés, ainsi que le nom du Gardien qui nous a apporté la paix finale.\nC'était notre ami, notre camarade, l'étudiant qui a le plus séché les cours à Mizag, de nombreux amis proches, notre Guide unique, et aussi le héros qui a sauvé chacun d'entre nous."
  },
  AvgDialog_118699_Content_54 = {
    Text = "Après la perte de {Male= lui,Female= elle}, Mizag a perdu une couleur intense. Tout en partageant la même tristesse, le département de recherche n'a pas abandonné l'espoir fragile et continue de chercher des traces de la conscience du Gardien. \n Avant de confirmer le succès, je ne voulais pas vous apporter un espoir inconnu, augmentant ainsi la douleur de l'attente prolongée. Mais maintenant, nous avons vérifié qu'il est possible de trouver <Jaune:%player%> et nous lancerons bientôt la tentative finale."
  },
  AvgDialog_118699_Content_55 = {
    Text = "Cette bataille pour accueillir {Male: lui, Female: elle} nécessite vous, nécessite nous tous ensemble, pour transformer notre nostalgie pour {Male: lui, Female: elle} en un guide pour le retrouver. \n Au nom de Mizag, je vous invite sincèrement à venir ensemble avant la piscine noire, comme lors de la dernière bataille, pour combattre à nouveau aux côtés de <Yellow:%player%>. \n\n Votre camarade Doll"
  },
  AvgDialog_118699_Content_56 = {
    Text = "Jour de l'accord dans le monde de Kadath"
  },
  AvgDialog_118699_Content_57 = {
    Text = "Sous le clocher interdit, devant l'eau noire silencieuse, se tient une foule silencieuse."
  },
  AvgDialog_118699_Content_58 = {
    Text = "Après que Doll a expliqué le principe du voyage dimensionnel, les éveilleurs qui voulaient initialement y aller ensemble se sont également tenus silencieusement à côté de l'instrument de résonance mentale."
  },
  AvgDialog_118699_Content_59 = {
    Text = "En raison des caractéristiques spirituelles de l'espace dimensionnel, plus il y a de corps spirituels apparaissant ensemble, plus ils attireront l'attention des êtres supérieurs, rendant encore plus difficile la résistance des Gardiens du secret de ce côté."
  },
  AvgDialog_118699_Content_6 = {
    Text = "Pourquoi... J'ai clairement entendu la voix de {Male=his,Female=her} à l'instant. Pourquoi est-ce que je ne trouve pas {Male=him,Female=her} ?"
  },
  AvgDialog_118699_Content_60 = {
    Text = "Devant la foule, Ramona tenait un bouquet de roses fanées, regardant silencieusement la piscine noire, tandis que dans l'autre main, elle serrait fermement la clé en argent portant le numéro 0617."
  },
  AvgDialog_118699_Content_61 = {
    Text = "Les instruments sont prêts à démarrer, concentrez-vous."
  },
  AvgDialog_118699_Content_62 = {
    Text = "Les pinces appuyèrent sur le bouton, envoyant des ondulations au niveau spirituel qui rassemblèrent les esprits de chacun en fils, tissant un immense réseau de connexion."
  },
  AvgDialog_118699_Content_63 = {
    Text = "Ramona ouvre solennellement la paume de sa main, la clé d'argent s'élève lentement sous une étrange gravité, flottant au centre d'un immense filet invisible, scintillant d'une lumière respirante."
  },
  AvgDialog_118699_Content_64 = {
    Text = "Tout le monde regarde la clé, priant silencieusement dans leur cœur."
  },
  AvgDialog_118699_Content_65 = {
    Text = "Cette école, ces gens ont besoin de toi. Peu importe un an, deux ans, dix ans... Tant que la recherche a un sens, nous te reprendrons."
  },
  AvgDialog_118699_Content_66 = {
    Text = "Seigneur, je peux déjà tenir quarante secondes sans connexion, et maintenant je peux mieux vous protéger. J'aimerais vraiment que vous voyiez les résultats de mon entraînement..."
  },
  AvgDialog_118699_Content_67 = {
    Text = "Il n'y a plus de nouveau-né à Mizag aussi résistant que toi. Quand pourrai-je revivre une bataille sous ta direction ?"
  },
  AvgDialog_118699_Content_68 = {
    Text = "Aigis est bien obéissante et mange bien. J'ai tricoté plein de écharpes, bonnets, gants et toutes sortes de pulls pour Grand{Male=M. Gardien,Female=Mlle Gardienne}. Est-ce que Grand{Male=M. Gardien,Female=Mlle Gardienne} va aimer ?"
  },
  AvgDialog_118699_Content_69 = {
    Text = "West Whelp, tu n'as pas encore terminé d'apprendre les secrets de survie du District de l'Est que je t'avais promis d'enseigner, et j'ai déjà perçu les frais de scolarité—dépêche-toi de revenir, ne laisse pas ma réputation de voleur être endommagée..."
  },
  AvgDialog_118699_Content_7 = {
    Text = "En effet, « Cœur sacré » ne peut percevoir que la {Male=sa,Female=sa} direction générale, mais ne peut pas trouver des coordonnées plus détaillées."
  },
  AvgDialog_118699_Content_70 = {
    Text = "Gardien {Male=monsieur,Female=madame}, je crois que les personnes bienveillantes seront toujours protégées par la chance, et quelqu'un comme vous aura certainement une fin heureuse."
  },
  AvgDialog_118699_Content_71 = {
    Text = "Grand{Male=M. Gardien,Female=Mlle Gardienne}, Lily peut déjà lire beaucoup de livres d'histoires. Quand tu reviendras, pouvons-nous tourner un film sur Grand{Male=M. Gardien,Female=Mlle Gardienne} et Lily ?"
  },
  AvgDialog_118699_Content_72 = {
    Text = "Le guerrier triomphant doit retourner chez {Male=son,Female=sa} patrie."
  },
  AvgDialog_118699_Content_73 = {
    Text = "Dépêche-toi de revenir, idiot de serviteur, tu me dois tant de thés de l'après-midi, il faut que tu me les compenses tous correctement !"
  },
  AvgDialog_118699_Content_74 = {
    Text = "Tu m'as déjà demandé quel était mon souhait... maintenant j'ai enfin mon propre souhait, c'est que j'espère que tu pourras revenir sain et sauf."
  },
  AvgDialog_118699_Content_75 = {
    Text = "Petit semis qui ne tient pas ses promesses, dans le nouveau monde que tu m'as promis, tu ne peux pas être absent..."
  },
  AvgDialog_118699_Content_76 = {
    Text = "Notre tribu ne laissera aucun membre isolé derrière."
  },
  AvgDialog_118699_Content_77 = {
    Text = "Mon son de flûte, gardera toujours pour vous."
  },
  AvgDialog_118699_Content_78 = {
    Text = "Tous les éveilleurs murmurent ce nom familier, un flot de pouvoir spirituel s'engouffre comme des lucioles dans la clé d'argent flottante, le centre de la clé commence à briller comme des étoiles."
  },
  AvgDialog_118699_Content_79 = {
    Text = "Pollux et Castor échangèrent un regard et hochèrent la tête en signe d'accord. Le corps de Castor se transforma en un éclat lumineux et s'intégra dans la poitrine de Pollux."
  },
  AvgDialog_118699_Content_8 = {
    Text = "Mais le désir intense de Mademoiselle Ramona à la dernière seconde a rendu les sentiments de « Cœur sacré » envers <Jaune:%player%> encore plus clairs."
  },
  AvgDialog_118699_Content_80 = {
    Text = "Une lueur verdoyante tourbillonne au sein du Saint-Cœur. Derrière Pollux, une paire de magnifiques ailes bleu-noir se déploie soudainement. Il tend un doigt, et le Saint-Cœur s'illumine en résonance avec la lumière de la clé en argent."
  },
  AvgDialog_118699_Content_81 = {
    Text = "Mademoiselle Ramona."
  },
  AvgDialog_118699_Content_82 = {
    Text = "Face au regard solennel de Pollux, Ramona serre la rose qui commence à briller dans sa main, un signal convenu avec le Gardien."
  },
  AvgDialog_118699_Content_83 = {
    Text = "La puissance spirituelle, répétée mille fois, commence à se concentrer selon des indications familières. Elle lève la tête et fixe la clé en argent, jetant sa voix intérieure au centre de la clé avec tout le monde."
  },
  AvgDialog_118699_Content_84 = {
    Text = "(<Jaune:%player%, attends-moi, j'arrive pour te ramener chez toi.)"
  },
  AvgDialog_118699_Content_9 = {
    Text = "Si l'on rassemble plus de puissance spirituelle fortement dirigée vers <Jaune:%player%>, il se pourrait que l'on puisse détecter avec plus de précision la position de %player%."
  },
  AvgDialog_118700_Content_1 = {
    Text = "Un instant d'étreinte"
  },
  AvgDialog_118700_Content_10 = {
    Text = "Le bruit environnant s'est estompé. Au fond de son esprit, Ramona contemplait ce lointain reflet d'elle-même."
  },
  AvgDialog_118700_Content_11 = {
    Text = "Ta force est plus puissante que la mienne... Peut-être que cette fois, la mission devrait être la tienne, ce serait plus sûr..."
  },
  AvgDialog_118700_Content_12 = {
    Text = "Ressentant ce que Ramona avait en tête, Ramona : Vétuste secoue la tête et lève ses yeux masqués pour contempler silencieusement cet abîme."
  },
  AvgDialog_118700_Content_13 = {
    Text = "Je suis juste venu dire au revoir. Dans ce long voyage à travers les dimensions, il n'y a pas de différence entre toi et moi, et encore moins..."
  },
  AvgDialog_118700_Content_14 = {
    Text = "C'est toi qui es le partenaire {Male=son,Female=sa}, c'est votre destin, pas le mien."
  },
  AvgDialog_118700_Content_15 = {
    Text = "Va, ramène {Male=le, Female=la} «Ramona»."
  },
  AvgDialog_118700_Content_16 = {
    Text = "Ramona saisit la rose et la serra fortement, puis, après un moment, elle hocha la tête sérieusement et s'installa dans l'appareil de séparation mentale sous le regard de son autre moi."
  },
  AvgDialog_118700_Content_17 = {
    Text = "Les yeux du corps sont fermés, tandis qu'une autre paire d'yeux s'ouvre lentement. Une âme solide se détache du corps, enveloppée d'une lueur blanche vaporeuse, comme un voile, par l'éclat du « Cœur sacré » de Pollux."
  },
  AvgDialog_118700_Content_18 = {
    Text = "Sous le regard de dizaines de regards, Ramona se retourna et échangea un à un des regards avec ses camarades, portant sur ses épaules ces lourdes espérances."
  },
  AvgDialog_118700_Content_19 = {
    Text = "Guidée par ces souvenirs, elle se retourna et sauta dans le vaste vortex. L'entrée ressemblant à la porte de l'enfer engloutit instantanément l'âme fragile."
  },
  AvgDialog_118700_Content_2 = {
    Text = "L'ange suspendu fait descendre la lumière sacrée, attendant d'accompagner les âmes égarées auprès de Dieu."
  },
  AvgDialog_118700_Content_3 = {
    Text = "Doll et Ramona échangèrent un regard et activèrent un immense dispositif qui couvrait presque la moitié de la piscine noire. Au milieu de la forte agitation de l'eau, un énorme vortex s'effondra, formant un abîme qui semblait dévorer tout."
  },
  AvgDialog_118700_Content_4 = {Text = "C'est..."},
  AvgDialog_118700_Content_5 = {
    Text = "L'immense étendue d'eau semble s'écouler vers un autre monde, dans un vortex sans fond, l'existence du monde commence à devenir floue."
  },
  AvgDialog_118700_Content_6 = {
    Text = "Le bord de ce monde, l'entrée vers l'espace dimensionnel."
  },
  AvgDialog_118700_Content_7 = {
    Text = "Derrière l'abîme, {Male=il,Female=elle} t'attend."
  },
  AvgDialog_118700_Content_8 = {
    Text = "Ramona hocha la tête. Avant de s'engager dans l'abîme, elle s'arrêta soudain et regarda la foule."
  },
  AvgDialog_118700_Content_9 = {
    Text = "Une silhouette vide, se tenant silencieusement derrière la foule de prières. C'était une présence profondément enfouie dans sa conscience, visible uniquement par elle."
  },
  AvgDialog_118701_Content_1 = {Text = "En attente"},
  AvgDialog_118701_Content_10 = {
    Text = "La brume se condense et se dissipe, une personne régulière de Mizag apparaît à l'entrée de la piscine noire, se tenant silencieusement à côté de la marionnette, regardant ensemble la silhouette assise devant la « Porte »."
  },
  AvgDialog_118701_Content_11 = {
    Text = "Un contact prolongé avec l'eau de la piscine n'est pas très bon pour la santé, tu ne l'empêches pas un peu ?"
  },
  AvgDialog_118701_Content_12 = {
    Text = "Je lui ai donné des dispositifs de protection de base, et en plus, je peux traiter les blessures corporelles, mais les blessures psychologiques sont plus difficiles à guérir."
  },
  AvgDialog_118701_Content_13 = {
    Text = "Le professeur rationnel soupira et se retourna avec curiosité."
  },
  AvgDialog_118701_Content_14 = {
    Text = "Tu viens ici très rarement, qu'est-ce que tu as apporté cette fois ?"
  },
  AvgDialog_118701_Content_15 = {
    Text = "Ah, une bonne nouvelle qui peut justement guérir son âme."
  },
  AvgDialog_118701_Content_16 = {
    Text = "Partenaire, grâce à ton exploit, il y a beaucoup moins de fissures de fusion dans le monde récemment."
  },
  AvgDialog_118701_Content_17 = {
    Text = "Les enquêteurs de l'école sont devenus plus détendus, chacun n'ayant plus qu'à assister aux cours et aux examens, Mizag ressemble de plus en plus à une université ordinaire."
  },
  AvgDialog_118701_Content_18 = {
    Text = "Quelqu'un a proposé de te faire construire une statue, juste à côté du principal Ward, et l'administration est encore en train d'y réfléchir."
  },
  AvgDialog_118701_Content_19 = {
    Text = "J'ai soumis des suggestions non prises en charge ; tu es manifestement toujours ici, pourquoi te transformer en statue comme le principal ."
  },
  AvgDialog_118701_Content_2 = {
    Text = "Kadath\navant les funérailles du Gardien"
  },
  AvgDialog_118701_Content_20 = {
    Text = "De plus, quand tu reviendras et que tu verras ton énorme moi à côté du directeur, tu seras sûrement tellement gêné que tu ne pourras pas dire un mot."
  },
  AvgDialog_118701_Content_21 = {
    Text = "Ton expression est si paisible, je ne peux pas y croire... Tu es sûrement perdu dans un autre monde, ayant oublié comment revenir..."
  },
  AvgDialog_118701_Content_22 = {
    Text = "Tu as raison, {Male=il,Female=elle} est effectivement entré dans d'autres dimensions, une dimension très lointaine."
  },
  AvgDialog_118701_Content_23 = {
    Text = "À l'entente de la voix de Daffodil qui surgit soudain derrière elle, Ramona se leva presque de manière désordonnée, manquant de maîtriser son impulsion de saisir le bras de la propriétaire du magasin."
  },
  AvgDialog_118701_Content_24 = {
    Text = "Que dites-vous ? Vous avez trouvé {Male=il,Female=elle} ? Dimension... je me souviens que vous pouviez voyager entre les dimensions !"
  },
  AvgDialog_118701_Content_25 = {
    Text = "Comment puis-je ramener {Male=il,Female=elle} ? Je suis prêt à payer n'importe quel prix !"
  },
  AvgDialog_118701_Content_26 = {
    Text = "Après avoir supplié avec une excitation difficile à cacher, Ramona remarqua enfin le visage sans sourire de Doll à ses côtés."
  },
  AvgDialog_118701_Content_27 = {
    Text = "…Pourquoi ?"
  },
  AvgDialog_118701_Content_28 = {
    Text = "Bien que ta détermination soit touchante, je crains que ce soit une dimension qui n'est pas reliée à ce monde, et de plus, je n'ai pas les moyens d'emmener le Gardien à travers l'espace dimensionnel inconnu."
  },
  AvgDialog_118701_Content_29 = {
    Text = "Si un chemin défini ne peut être trouvé, traverser librement à travers la turbulence dimensionnelle ne mènera qu'à un seul résultat : être perdu."
  },
  AvgDialog_118701_Content_3 = {
    Text = "Avec un bourdonnement indiquant que le test est terminé, de nombreux instruments affichent à nouveau des résultats sans réaction. Doll agite silencieusement la main, et les chercheurs échangent un regard complice avant de commencer à démonter les appareils."
  },
  AvgDialog_118701_Content_30 = {
    Text = "Avec la technologie actuelle de Mizag, cela n'est pas possible."
  },
  AvgDialog_118701_Content_31 = {
    Text = "Que cela signifie... Nous avons essayé si longtemps, et enfin nous avons des nouvelles de {Male=lui,Female=elle}—allons-nous vraiment laisser {Male=lui,Female=elle} là-bas seul ?!"
  },
  AvgDialog_118701_Content_32 = {
    Text = "Je pourrais peut-être discuter de la technique du voyage dimensionnel avec le professeur Doll, comme un cadeau offert gratuitement à nos vieux clients."
  },
  AvgDialog_118701_Content_33 = {
    Text = "Mais pour ramener <Jaune:%player%>, le plus difficile est de trouver le chemin vers ce monde, même dans ma collection, il n'y a pas de trésor transcendant ce univers."
  },
  AvgDialog_118701_Content_34 = {
    Text = "Je vais faire en sorte que le département de recherche s'investisse pleinement dans l'étude de la dimension à partir d'aujourd'hui."
  },
  AvgDialog_118701_Content_35 = {
    Text = "Entre les dimensions, il n'y a parfois jamais d'intersection, et ce n'est pas par épuisement que l'on peut les trouver."
  },
  AvgDialog_118701_Content_36 = {
    Text = "Ce à quoi vous êtes confrontés pourrait être une tentative si longue qu'elle semble sans espoir."
  },
  AvgDialog_118701_Content_37 = {
    Text = "Nous ne laisserons pas tomber."
  },
  AvgDialog_118701_Content_38 = {Text = "新增"},
  AvgDialog_118701_Content_39 = {
    Text = "Je sais, peu importe combien de temps cela prendra, j'attendrai {Male=il,Female=elle}."
  },
  AvgDialog_118701_Content_4 = {
    Text = "Pourquoi ranger les instruments ? Réessayons, il doit y avoir d'autres méthodes de test auxquelles nous n'avons pas pensé..."
  },
  AvgDialog_118701_Content_40 = {
    Text = "Kadath\ndix mois après les funérailles du Gardien\npiscine noire"
  },
  AvgDialog_118701_Content_41 = {
    Text = "Des pas résonnants traversent les portes scellées, foulant les vagues visqueuses, tandis que la piscine noire silencieuse accueille son deuxième visiteur du jour."
  },
  AvgDialog_118701_Content_42 = {
    Text = "Je savais que tu étais encore ici."
  },
  AvgDialog_118701_Content_43 = {
    Text = "L'interlocuteur du professeur ne répond pas, son ombre immobile faisant face à la silhouette flottante devant la «Porte», telle une statue contemplative."
  },
  AvgDialog_118701_Content_44 = {
    Text = "Aujourd'hui, une autre lettre de suggestion a été déposée chez moi ; c'est votre 7ème fois que vous refusez d'être assigné à un partenaire de tâche et insistez pour mener l'enquête en duo seul."
  },
  AvgDialog_118701_Content_45 = {Text = "新增"},
  AvgDialog_118701_Content_46 = {
    Text = "Ce n'est pas grave, je ne suis pas là pour te critiquer ou te donner des ordres, encore moins pour te conseiller, même si Sylvia dit que ton évaluation psychologique a effectivement quelques problèmes."
  },
  AvgDialog_118701_Content_47 = {
    Text = "Mais dans cette université, combien de personnes n'ont vraiment aucun problème ?"
  },
  AvgDialog_118701_Content_48 = {
    Text = "Les pinces roses se tenaient à côté de la sculpture, regardant cette silhouette toujours endormie avec elle."
  },
  AvgDialog_118701_Content_49 = {
    Text = "Y a-t-il une mission spéciale que je dois exécuter ?"
  },
  AvgDialog_118701_Content_5 = {
    Text = "Le nombre de tests et de bandes est déjà suffisant ; votre cours d'utilisation de l'instrument à cœur d'argent est à pleine note, ne vous trompez plus, Ramona."
  },
  AvgDialog_118701_Content_50 = {
    Text = "La statue qui avait perdu sa réaction a enfin pris la parole, son ton aussi calme qu'une machine."
  },
  AvgDialog_118701_Content_51 = {Text = "Il y a."},
  AvgDialog_118701_Content_52 = {
    Text = "Exigences de la mission ?"
  },
  AvgDialog_118701_Content_53 = {
    Text = "Tu dois aller dans un endroit très dangereux pour récupérer ton partenaire."
  },
  AvgDialog_118701_Content_54 = {
    Text = "Je n'en ai pas besoin..."
  },
  AvgDialog_118701_Content_55 = {
    Text = "La personne d'avant."
  },
  AvgDialog_118701_Content_56 = {
    Text = "Ramona se retourna brusquement, fixant les yeux inorganiques de la poupée."
  },
  AvgDialog_118701_Content_57 = {
    Text = "Cette mission est un pari, et le niveau de danger est sans précédent. Je crains que les renforts de l'école ne puissent pas t'accompagner..."
  },
  AvgDialog_118701_Content_58 = {
    Text = "Le département de recherche a-t-il des résultats ? Quand ?"
  },
  AvgDialog_118701_Content_59 = {
    Text = "Doll a souri et a tendu le rapport de recherche fraîchement sorti de ses mains à l'autre personne."
  },
  AvgDialog_118701_Content_6 = {
    Text = "Ce n'est qu'une coquille vide, sans aucun signe de vie. La conscience du Gardien... s'est peut-être déjà dissipée."
  },
  AvgDialog_118701_Content_60 = {
    Text = "Depuis que Daffodil nous a informés des nouvelles concernant le Gardien, le département de recherche a déjà essayé tous les moyens techniques disponibles, et il s'avère que la dernière percée se trouve du côté des Éveilleurs."
  },
  AvgDialog_118701_Content_61 = {
    Text = "Nous avons découvert que le « Cœur sacré » de Pollux peut attirer cette existence ; l'Église de la Lanterne a initialement fabriqué le « Cœur sacré » pour créer des âmes pures et répandre le Sang divin."
  },
  AvgDialog_118701_Content_62 = {
    Text = "Sacrifice final du Fils Saint, invocation de la prétendue terre pure."
  },
  AvgDialog_118701_Content_63 = {
    Text = "En fait, le principe est d'attirer l'attention de cette personne, ce qui provoque une dissolution. Après un traitement directionnel, le « Cœur sacré » est très susceptible de nous guider spécifiquement vers l'emplacement du Gardien."
  },
  AvgDialog_118701_Content_64 = {
    Text = "L'école prévoit d'envoyer une conscience avec un excellent pouvoir spirituel dans l'espace dimensionnel, suivant les instructions du « Cœur sacré » pour traverser les dimensions et établir un tunnel reliant les deux mondes."
  },
  AvgDialog_118701_Content_65 = {
    Text = "Si toutes les données de test avancent bien, nous pourrons commencer les essais dans un mois."
  },
  AvgDialog_118701_Content_66 = {
    Text = "Ensuite, ta tâche comprendra une partie sur l'entraînement de la force spirituelle, j'espère que tu... ne seras pas trop assidu, pour éviter de blesser ton cerveau."
  },
  AvgDialog_118701_Content_67 = {
    Text = "Kadath\nfunérailles du Gardien un an après\npiscine noire"
  },
  AvgDialog_118701_Content_68 = {
    Text = "Le dispositif de séparation mentale, fonctionnant à grande vitesse, émet une alerte rouge insupportable, et la poupée qui observe attentivement à côté appuie immédiatement sur le bouton d'arrêt."
  },
  AvgDialog_118701_Content_69 = {
    Text = "La porte contenant l'utilisateur s'ouvrit instantanément, et Ramona, déjà épuisée, bougea légèrement un doigt, tandis que les chercheurs des deux côtés l'aidaient rapidement à sortir."
  },
  AvgDialog_118701_Content_7 = {
    Text = "Le verdict cruel tomba enfin de la bouche de la marionnette, et en voyant les larmes couler des yeux égarés de Ramona, même le professeur, habitué aux sacrifices, ne put se résoudre à fermer les yeux."
  },
  AvgDialog_118701_Content_70 = {
    Text = "Soutiens-la, entre rapidement dans le liquide de refroidissement spirituel !"
  },
  AvgDialog_118701_Content_71 = {
    Text = "L'eau du bassin vert pâle inondait sa poitrine, la température de Ramona, qui était aussi élevée qu'une fièvre, avait enfin baissé, et ses yeux, qui avaient été rationnels autrefois, semblaient maintenant paranoïaques, s'ouvrirent lentement."
  },
  AvgDialog_118701_Content_72 = {
    Text = "Même si après-demain est la date de la première tentative formelle, tu ne peux pas prendre de risques avec ton corps comme ça."
  },
  AvgDialog_118701_Content_73 = {
    Text = "Ce n'est pas grave, je peux tenir..."
  },
  AvgDialog_118701_Content_74 = {
    Text = "Pollux, sortant silencieusement de l'instrument à côté, s'approcha également des deux, interrompant davantage les conseils de Doll."
  },
  AvgDialog_118701_Content_75 = {
    Text = "Je peux comprendre la douleur de perdre une personne importante, cette haine de soi face à son impuissance... Ne t'inquiète pas, Mademoiselle Ramona."
  },
  AvgDialog_118701_Content_76 = {
    Text = "Maintenant que le « Cœur sacré » peut ressentir l'Invocation de cette lampe lumineuse, Castor et moi ferons tout notre possible pour retrouver notre bienfaiteur avec toi."
  },
  AvgDialog_118701_Content_8 = {
    Text = "Préparez-vous à organiser des funérailles pour <Jaune:%player%>, cette lettre d'adieu... c'est à vous de la lire pour {Male=il,Female=elle}."
  },
  AvgDialog_118701_Content_9 = {
    Text = "Kadath\nTrois mois après les funérailles du Gardien"
  },
  AvgDialog_118702_Content_1 = {
    Text = "Transmission lointaine"
  },
  AvgDialog_118702_Content_10 = {
    Text = "Tu agites les bras comme une personne aveugle, luttant pour avancer, tel un voyageur qui traverse les eaux, avançant péniblement dans les ténèbres visqueuses à la recherche de quelque chose."
  },
  AvgDialog_118702_Content_100 = {
    Text = "Il n'y a pas de température brûlante ici, seulement une obscurité visqueuse et infinie. Alors que vous vous déplacez en avant, les distinctions entre avancée et retraite commencent à s'estomper, comme si l'existence elle-même se transformait en néant."
  },
  AvgDialog_118702_Content_101 = {
    Text = "Continuez d'avancer, ne vous retournez pas."
  },
  AvgDialog_118702_Content_102 = {
    Text = "Tu fais confiance à cette voix, essayant de vider ton esprit, avançant sans cesse, jusqu'à ce qu'une série de couleurs hallucinantes te plonge dans un intense étourdissement."
  },
  AvgDialog_118702_Content_103 = {Text = "…C'est !"},
  AvgDialog_118702_Content_104 = {
    Text = "À part dans la Mer des Principes de Daffodil, tu te tiens pour la première fois en dehors de l'univers, regardant le monde."
  },
  AvgDialog_118702_Content_105 = {
    Text = "On dirait qu'on entre dans un monde microscopique sous un microscope, avec une qualité spatiale gélatineuse, d'innombrables lignes ondulantes, des formes bizarres de corps spirituels, et des galaxies scintillant au loin…"
  },
  AvgDialog_118702_Content_106 = {
    Text = "et les limites du monde sans fin."
  },
  AvgDialog_118702_Content_107 = {
    Text = "Sans suffisamment de points d'ancrage spirituels, il est facile de se perdre rapidement dans un espace aussi chaotique et infini, mais il n'y a pas beaucoup de peur dans ton cœur."
  },
  AvgDialog_118702_Content_108 = {
    Text = "Es-tu prêt ? Une fois que tu as commencé à te lier, je vais essayer de faire du bruit pour l'attirer, le reste, c'est ton combat."
  },
  AvgDialog_118702_Content_109 = {
    Text = "Tu serres la clé en argent à ta poitrine, étendant avec sérieux et affection les antennes de ton esprit vers la rose épanouie dans ta main."
  },
  AvgDialog_118702_Content_11 = {
    Text = "Enfin... je t'ai trouvé ! Nous @3... à travers le tunnel @2..."
  },
  AvgDialog_118702_Content_110 = {
    Text = "Commencer ."
  },
  AvgDialog_118702_Content_111 = {
    Text = "Une grande onde de puissance spirituelle éclate dans l'espace dimensionnel, et à la limite de ta perception spirituelle, une fissure soudainement apparue déchire l'espace."
  },
  AvgDialog_118702_Content_112 = {
    Text = "Une pupille gigantesque apparaît soudainement derrière la fissure, comme l'œil d'un géant qui s'ouvre brusquement."
  },
  AvgDialog_118702_Content_12 = {
    Text = "Tu ne peux pas voir son ombre, seulement entendre des voix fragmentées. La personne que tu connais est également émue, exprimant la joie d'une rencontre tant attendue."
  },
  AvgDialog_118702_Content_13 = {
    Text = "Tu peux sentir qu'une corde réelle vous relie, et il semble qu'en suivant cette corde, tu pourras trouver le chemin de retour chez toi."
  },
  AvgDialog_118702_Content_14 = {
    Text = "Alors que tu avancais sans cesse en suivant le fil de la corde, un bruit de rupture soudain retentit, et tout l'espace commença à trembler sous une forte secousse."
  },
  AvgDialog_118702_Content_15 = {
    Text = "Il y a quelque chose qui attaque @2, le cœur sacré ne tient plus !"
  },
  AvgDialog_118702_Content_16 = {
    Text = "Ramona, romps le lien !"
  },
  AvgDialog_118702_Content_17 = {Text = "Mais !"},
  AvgDialog_118702_Content_18 = {
    Text = "Gardien, va chercher Daffodil ! Nous n'abandonnerons pas——"
  },
  AvgDialog_118702_Content_19 = {
    Text = "Toute la lumière a disparu. Au loin, une immense entité inconnue change de direction et s'enfonce progressivement dans le chaos du vide."
  },
  AvgDialog_118702_Content_2 = {
    Text = "Gardien@2… Gardien…"
  },
  AvgDialog_118702_Content_20 = {Text = "!!!"},
  AvgDialog_118702_Content_21 = {
    Text = "Tu te redresses brusquement sur ton lit, entouré par la pièce de la base de Doll : Dissoute, avec ces murs en briques rouge foncé familiers et une légère odeur de désinfectant."
  },
  AvgDialog_118702_Content_22 = {
    Text = "Tu me demandes ce qui se passe ? Depuis quand mon domaine de recherche s'est-il étendu à l'analyse des rêves ? Ne devrais-tu pas aller voir Clémentine pour ce genre de choses ?"
  },
  AvgDialog_118702_Content_23 = {
    Text = "Cependant, tu as raison. Étant donné la particularité de ton esprit, je penche également pour le fait que ce n'est pas une illusion de ta part, ni un simple rêve."
  },
  AvgDialog_118702_Content_24 = {
    Text = "Quant à la réponse au mystère de la vérité, je ne te l'ai pas déjà dit, moi dans le Rêve ?"
  },
  AvgDialog_118702_Content_25 = {
    Text = "Un cœur d'argent que tu avais volé a été sorti par Doll : Dissoute et jeté dans le Dispositif de réveil, une légère fumée violette s'élevant dans le bourdonnement mécanique."
  },
  AvgDialog_118702_Content_26 = {
    Text = "Ah, encore une fois, mes vieux clients ?"
  },
  AvgDialog_118702_Content_27 = {
    Text = "Daffodil ! Je..."
  },
  AvgDialog_118702_Content_28 = {
    Text = "Chut, pas besoin de parler, un marchand compétent saura naturellement comprendre les désirs du client."
  },
  AvgDialog_118702_Content_29 = {
    Text = "J'ai effectivement déjà vu tes amis."
  },
  AvgDialog_118702_Content_3 = {
    Text = "On dirait que tu es masqué et recouvert par d'énormes rideaux de scène, des couches de velours épais s'accumulent sur toi, te rendant invisible et immobile."
  },
  AvgDialog_118702_Content_30 = {Text = "?!"},
  AvgDialog_118702_Content_31 = {
    Text = "Voyant l'expression choquée sur ton visage, Fondu·poupée a levé les yeux au ciel."
  },
  AvgDialog_118702_Content_32 = {
    Text = "Je pensais qu'avec ton intelligence, tu devrais être capable de comprendre la clé de sa force."
  },
  AvgDialog_118702_Content_33 = {
    Text = "La force de... clé ?"
  },
  AvgDialog_118702_Content_34 = {
    Text = "Tu te souviens de cette mer grise remplie de têtes."
  },
  AvgDialog_118702_Content_35 = {
    Text = "Dimension spatiale ? Vous voulez dire que Daffodil peut naviguer à travers différents mondes... elles sont la même personne ?"
  },
  AvgDialog_118702_Content_36 = {
    Text = "C'est très proche, enfant intelligent, ici je suis le même « être » que là-bas, mais tu as oublié que nous ne sommes pas humains."
  },
  AvgDialog_118702_Content_37 = {
    Text = "Daffodil plisse les yeux avec approbation et secoue sa pipe en retournant le poignet."
  },
  AvgDialog_118702_Content_38 = {
    Text = "Nous ne sommes que des visages émergeant à la surface de la mer ; l'océan gris brumeux qui coule entre toutes les dimensions est notre véritable forme."
  },
  AvgDialog_118702_Content_39 = {
    Text = "Nous pouvons ainsi nous comprendre spirituellement, mais nous ne sommes pas la même « personne »."
  },
  AvgDialog_118702_Content_4 = {
    Text = "Dans un rêve noir de vide, une voix étouffée résonne comme des ondulations d'eau, se dissipant soudainement."
  },
  AvgDialog_118702_Content_40 = {
    Text = "C'est-à-dire, tu peux voyager entre différents mondes à travers la Mer des Principes ? Dans le rêve que je viens d'avoir, Doll m'a demandé de te trouver, ce qui signifie que tu as maintenant un moyen de me ramener dans ce monde ?"
  },
  AvgDialog_118702_Content_41 = {
    Text = "Ne t'inquiète pas, je t'ai dit, même moi, je ne peux pas facilement traverser les dimensions entre deux mondes."
  },
  AvgDialog_118702_Content_42 = {
    Text = "Si j'avais vraiment une telle méthode, pourquoi la garderais-je égoïstement jusqu'à maintenant ?"
  },
  AvgDialog_118702_Content_43 = {
    Text = "Tu restes figé, la tête baissée lentement."
  },
  AvgDialog_118702_Content_44 = {
    Text = "Mais cette fois, ce sont vos amis courageux qui ont trouvé une nouvelle solution."
  },
  AvgDialog_118702_Content_45 = {
    Text = "Vous relevez brusquement la tête, vos yeux retrouvent leur éclat. Cela provoque un léger rire de Daffodil et un ricanement de Doll : Dissoute."
  },
  AvgDialog_118702_Content_46 = {
    Text = "Depuis la dernière fois que nous nous sommes rencontrés dans ce monde, j'ai transmis tes nouvelles à eux."
  },
  AvgDialog_118702_Content_47 = {
    Text = "Après avoir appris la particularité de cette dimension, Doll a travaillé jour et nuit avec les chercheurs de Mizag pour tenter de localiser ce monde. Récemment, ils ont trouvé un moyen de lier deux dimensions."
  },
  AvgDialog_118702_Content_48 = {
    Text = "Ce que tu viens de ressentir, c'est le résultat de leur lien réussi."
  },
  AvgDialog_118702_Content_49 = {
    Text = "Alors ce n'était pas un rêve ? Ce lien spirituel est réel ?!"
  },
  AvgDialog_118702_Content_5 = {
    Text = "Qui ? Quelqu'un m'appelle ? Une voix si familière..."
  },
  AvgDialog_118702_Content_50 = {
    Text = "Oui, mais l'effondrement du lien vient aussi d'arriver. Tu as dû remarquer cette personne qui est soudainement apparue."
  },
  AvgDialog_118702_Content_51 = {
    Text = "Le voyage dimensionnel est extrêmement dangereux ; même si je peux vous aider à échapper à la traque des chiens de chasse, il y a trop d'entités de haut niveau dans l'espace dimensionnel."
  },
  AvgDialog_118702_Content_52 = {
    Text = "Ils ont généralement leurs propres domaines d'activité, tout comme les empereurs dominent leurs propres royaumes."
  },
  AvgDialog_118702_Content_53 = {
    Text = "Il aurait peut-être été possible d'éviter cela avec prudence par divers moyens, mais malheureusement, celui qui a ciblé le tunnel est ton adversaire le plus familier."
  },
  AvgDialog_118702_Content_54 = {
    Text = "Si familier... Cette sensation d'être observé, Tohuwabohu ? Il s'est réveillé ?!"
  },
  AvgDialog_118702_Content_55 = {
    Text = "Ne sois pas si nerveux, les résultats de ton sacrifice ne disparaîtront pas si facilement. Il est toujours plongé dans le sommeil."
  },
  AvgDialog_118702_Content_56 = {
    Text = "Cependant, Il reste Lui-même. Ton « Cœur sacré » et celui de Pollux sont trop éclatants, même plongé dans le Sommeil, son subconscient vous a remarqués."
  },
  AvgDialog_118702_Content_57 = {
    Text = "L'expression de Daffodil devient exceptionnellement sérieuse, vous restez silencieux, repensant à ce combat où tout a été sacrifié."
  },
  AvgDialog_118702_Content_58 = {
    Text = "Heureusement, cette fois, le tumulte du voyage dimensionnel était bien moins important que le désordre que Juliette avait créé la dernière fois. Le regard projeté de son subconscient n'a pas détruit le monde entier."
  },
  AvgDialog_118702_Content_59 = {
    Text = "Cependant, un tel pouvoir n'est pas supportable par l'Éveilleur venu te chercher. Par conséquent, établir un lien dimensionnel complet ne peut réussir uniquement avec les personnes de ce côté."
  },
  AvgDialog_118702_Content_6 = {
    Text = "Gardien… partenaire !"
  },
  AvgDialog_118702_Content_60 = {
    Text = "J'ai besoin de toi, <Jaune:%player%>, pour attirer son attention ici et le repousser, protégeant ainsi ceux qui se trouvent loin dans un autre monde en ouvrant un tunnel entre les deux mondes."
  },
  AvgDialog_118702_Content_61 = {
    Text = "Le regard de Touva Wave… C'est encore Lui…"
  },
  AvgDialog_118702_Content_62 = {
    Text = "Cette bataille semble si lointaine, si lointaine qu'elle paraît être un événement d'une vie antérieure."
  },
  AvgDialog_118702_Content_63 = {
    Text = "Cette bataille était si proche, si proche que tu pouvais facilement te souvenir de chaque détail."
  },
  AvgDialog_118702_Content_64 = {
    Text = "Chaque blessure cruelle, chaque victoire brutale, chaque frisson de peur, chaque cri désespéré aux portes de la mort..."
  },
  AvgDialog_118702_Content_65 = {
    Text = "Regarder Dieu en face a jadis coûté tout votre courage et votre vie. En repensant à ces regards qui transcendaient les règles, votre voix a commencé à trembler de manière incontrôlable."
  },
  AvgDialog_118702_Content_66 = {
    Text = "Même la projection du regard subconscient, sa force n'est probablement pas quelque chose que je peux arrêter..."
  },
  AvgDialog_118702_Content_67 = {
    Text = "Je ne peux pas actuellement invoquer complètement la puissance des trois plasmides, et je n'ai pas l'aide de mes compagnons d'autres dimensions, si je veux l'arrêter..."
  },
  AvgDialog_118702_Content_68 = {
    Text = "Quoi, notre courageux Gardien du Secret, a-t-il peur ?"
  },
  AvgDialog_118702_Content_69 = {
    Text = "Tu serres le poing, secoues la tête et regardes Daffodil sérieusement."
  },
  AvgDialog_118702_Content_7 = {Text = "Ramona ?!"},
  AvgDialog_118702_Content_70 = {
    Text = "Tant que je peux rentrer, aucune peur ne pourra m'arrêter. Je suis juste inquiet, inquiet de mes capacités actuelles."
  },
  AvgDialog_118702_Content_71 = {
    Text = "Si j'échoue, Il risque même d'être réveillé à nouveau... Une telle catastrophe est quelque chose que personne ne peut supporter."
  },
  AvgDialog_118702_Content_72 = {
    Text = "Très bien. Il semble que notre Gardien du Secret n'ait pas encore perdu le courage d'affronter les divinités."
  },
  AvgDialog_118702_Content_73 = {
    Text = "Ne t'inquiète pas, <Jaune:%player%>. Cette fois, je vais aussi t'aider à ouvrir l'intervalle entre les différentes dimensions et à disperser sa force dans les différentes dimensions."
  },
  AvgDialog_118702_Content_74 = {
    Text = "La dernière fois, les Gardiens du secret des autres dimensions ont combattu à tes côtés. Cette fois, ils seront également là, dans des endroits invisibles pour toi, menant la même bataille à tes côtés."
  },
  AvgDialog_118702_Content_75 = {
    Text = "Vraiment ?! Si c'est le cas, nous, nous serons certainement capables de le repousser à nouveau !"
  },
  AvgDialog_118702_Content_76 = {
    Text = "Même ainsi, des batailles à ce niveau pourraient détruire tout ce monde ici, et à part <Jaune:%player%>, aucun survivant dans ce monde n'a la capacité de lui faire face."
  },
  AvgDialog_118702_Content_77 = {
    Text = "C'est ça, donc cette bataille doit avoir lieu dans l'espace dimensionnel, et comment maintenir <Jaune:%player%> dans l'espace dimensionnel pendant longtemps nécessite également l'aide d'un génie."
  },
  AvgDialog_118702_Content_78 = {
    Text = "S'il te plaît ! Fondu·Poupée !"
  },
  AvgDialog_118702_Content_79 = {
    Text = "… Hum, un ou deux sont plutôt bien organisés."
  },
  AvgDialog_118702_Content_8 = {
    Text = "Avec la révélation de ce nom, une barrière invisible a été instantanément brisée, un lien tendre et chaud a traversé d'innombrables espaces-temps, se transformant en un fil argenté qui s'est rapproché de ta poitrine."
  },
  AvgDialog_118702_Content_80 = {
    Text = "Tant pis, qui m'a demandé de te promettre de t'aider à rentrer chez toi ? En ce qui concerne la promesse faite au petit chien, je la tiendrai."
  },
  AvgDialog_118702_Content_81 = {Text = "Merci !"},
  AvgDialog_118702_Content_82 = {
    Text = "Ne te précipite pas pour me remercier. Pour commencer, je peux seulement maintenir ta conscience dans l'espace dimensionnel et garantir autant que possible de te ramener dans ce monde à tout moment."
  },
  AvgDialog_118702_Content_83 = {
    Text = "Quant à ton combat avec cette personne, il y a toujours la possibilité d'échec voire de mort."
  },
  AvgDialog_118702_Content_84 = {
    Text = "Je ne suis pas optimiste quant à un plan aussi impulsif, même ainsi, tu choisis de prendre un tel risque pour parier sur une issue inconnue ?"
  },
  AvgDialog_118702_Content_85 = {
    Text = "Je suis prêt, ils ont également pris les mêmes risques pour moi, je n'ai aucune raison de ne pas leur répondre. Quoi qu'il en soit, même dans deux mondes éloignés, nous combattrons ensemble comme avant."
  },
  AvgDialog_118702_Content_86 = {
    Text = "Fusion·Poupée hocha la tête sans surprise, et Daffodil vous regarda en souriant, comme si elle n'avait jamais pensé que vous pourriez reculer."
  },
  AvgDialog_118702_Content_87 = {
    Text = "D'accord, un serment aussi ringard est mieux réservé à tes bons camarades. J'ai besoin d'un certain temps pour me préparer, quant à la manière de convenir du moment du début de l'action, j'imagine que tu as déjà une méthode ?"
  },
  AvgDialog_118702_Content_88 = {
    Text = "Face à la question de Doll : Dissoute, Daffodil tourna plutôt son regard vers toi."
  },
  AvgDialog_118702_Content_89 = {
    Text = "Bien sûr, ton partenaire m'a demandé de te faire un cadeau."
  },
  AvgDialog_118702_Content_9 = {
    Text = "C'est... un lien mental ?! Ramona, c'est toi ? Où es-tu ?"
  },
  AvgDialog_118702_Content_90 = {
    Text = "Dans un nuage de fumée, une rose, sortie de nulle part, t'est tendue."
  },
  AvgDialog_118702_Content_91 = {
    Text = "C'est... la fleur que m'a offerte Ramona... ?!!"
  },
  AvgDialog_118702_Content_92 = {
    Text = "Je suis désolé, je n'ai pas encore la capacité de projeter des objets réels à travers les dimensions."
  },
  AvgDialog_118702_Content_93 = {
    Text = "Cependant, dans ces deux dimensions, chaque chose aura son équivalent."
  },
  AvgDialog_118702_Content_94 = {
    Text = "Cette rose correspond à celle que Ramona t'a offerte dans cette dimension."
  },
  AvgDialog_118702_Content_95 = {
    Text = "J'ai déjà fait un petit traitement sur cette fleur, quand tu seras prêt, établis le lien spirituel sur cette fleur, les gens là-bas recevront le message."
  },
  AvgDialog_118702_Content_96 = {
    Text = "Elle a dit que lorsqu'elle vous verrait, elle mettrait cette fleur sur votre poitrine."
  },
  AvgDialog_118702_Content_97 = {Text = "新增"},
  AvgDialog_118702_Content_98 = {
    Text = "C'est la première fois que vous savez que le passage utilisé par Fondu·poupée pour quitter le monde est le soleil qui a déjà disparu au-dessus de votre tête."
  },
  AvgDialog_118702_Content_99 = {
    Text = "Le trou noir du soleil ressemble à une plaie que le monde ne peut guérir, et lorsque ta conscience y pénètre lentement, c'est comme si tu rampais dans la poitrine vide d'un géant."
  },
  AvgDialog_118703_Content_1 = {
    Text = "Doigts recourbés"
  },
  AvgDialog_118703_Content_10 = {
    Text = "Un cri perçant, n'appartenant à aucune créature et à aucune dimension, résonne directement au plus profond de ta conscience, presque déchirant ton cerveau."
  },
  AvgDialog_118703_Content_100 = {
    Text = "Mmm—ma tête... ça fait mal..."
  },
  AvgDialog_118703_Content_101 = {
    Text = "Les instruments connectés sont presque complètement endommagés, le fait que tu sois encore en vie et que tu sois revenu est presque un miracle."
  },
  AvgDialog_118703_Content_102 = {
    Text = "Cependant, cet endroit a déjà vu trop de miracles. Peut-être que pour la piscine noire, la théorie des probabilités elle-même est une illusion."
  },
  AvgDialog_118703_Content_103 = {
    Text = "Bien fait, Ramona. Ne refais plus ça la prochaine fois."
  },
  AvgDialog_118703_Content_104 = {
    Text = "Rassurez-vous, professeur Doll... je sais ce que je fais."
  },
  AvgDialog_118703_Content_105 = {
    Text = "Pour %player%, pouvoir te revoir peut être plus important que bien des choses."
  },
  AvgDialog_118703_Content_106 = {
    Text = "Le seul regret est que la dernière phrase de {Male=il,Female=elle} n'a pas pu être entendue."
  },
  AvgDialog_118703_Content_107 = {
    Text = "Non, Madame Daffodil. {Male=sa, Female=son} parole, je l'ai déjà entendue..."
  },
  AvgDialog_118703_Content_108 = {
    Text = "Ramona se leva faiblement, souriant, et s'avança vers le vide de la piscine noire qui disparaissait."
  },
  AvgDialog_118703_Content_109 = {
    Text = "L'abîme s'est effondré dans ses yeux, passant d'un géant qui dévore tout à une porte isolant les dimensions, puis à une fissure vide, jusqu'à disparaître complètement."
  },
  AvgDialog_118703_Content_11 = {
    Text = "Tu t'agenouilles au sol, te bouchant fermement les deux oreilles, sentant le sang déborder de tes yeux sans pouvoir l'arrêter..."
  },
  AvgDialog_118703_Content_110 = {
    Text = "La main de Ramona caresse doucement l'endroit où le gouffre avait autrefois existé, effleurant ce corps meurtri."
  },
  AvgDialog_118703_Content_111 = {
    Text = "Elle sourit, comme si elle voyait le futur proche, le maître de son corps se tenant devant elle, comme une journée d'une banalité incomparable de l'ancien Mizag."
  },
  AvgDialog_118703_Content_112 = {
    Text = "J'ai entendu, Gardien... nous y parviendrons."
  },
  AvgDialog_118703_Content_113 = {
    Text = "Je t'attends, %player% ."
  },
  AvgDialog_118703_Content_12 = {
    Text = "<Shake:Hou... Hou...>"
  },
  AvgDialog_118703_Content_13 = {
    Text = "On dirait que... c'est fini ?"
  },
  AvgDialog_118703_Content_14 = {
    Text = "Le cri perçant a disparu sans que l'on sache quand. Tu lèves la tête. Dans cette dimension fragile et illusoire, l'atmosphère terrifiante qui faisait frissonner a depuis longtemps disparu."
  },
  AvgDialog_118703_Content_15 = {
    Text = "Tu as triomphé. Son subconscient est coupé d'ici, la dernière énorme pupille s'est dissipée dans la dimension."
  },
  AvgDialog_118703_Content_16 = {
    Text = "Tu as du mal à stabiliser ton esprit épuisé, te retournant presque instinctivement."
  },
  AvgDialog_118703_Content_17 = {Text = "Craquement"},
  AvgDialog_118703_Content_18 = {
    Text = "Un son illusoire de cristal brisé parvient à tes oreilles, et ce que tu vois, c'est un tunnel dimensionnel fissuré comme une toile d'araignée, avec Ramona, dont le corps spirituel commence à scintiller comme une vieille télévision."
  },
  AvgDialog_118703_Content_19 = {
    Text = "<Big:<Shake:Ramona !!!>>"
  },
  AvgDialog_118703_Content_2 = {
    Text = "Il manque encore... un dernier petit détail... !"
  },
  AvgDialog_118703_Content_20 = {
    Text = "Ton corps, déjà épuisé, semble guérir en un instant. Tu ne peux plus te soucier de rien d'autre et tu te précipites vers elle, tremblant en saisissant ses mains."
  },
  AvgDialog_118703_Content_21 = {
    Text = "Moi, je vais bien…"
  },
  AvgDialog_118703_Content_22 = {
    Text = "Ton partenaire sourit comme d'habitude, elle serre plus fort ta main, comme si rien ne s'était passé, et continue les plans initiaux."
  },
  AvgDialog_118703_Content_23 = {
    Text = "Tu l'as déjà vaincu, viens, suis-moi, je vais te ramener."
  },
  AvgDialog_118703_Content_24 = {
    Text = "Elle te tire, comme elle le fait d'habitude pendant les missions.\n Juste, une voix plus rationnelle résonne presque de manière froide."
  },
  AvgDialog_118703_Content_25 = {
    Text = "Ramona, le tunnel dimensionnel a été brisé par lui. Ton corps spirituel ne peut plus supporter la charge de maintenir le tunnel. Si cela continue ainsi, tu ne feras que sombrer dans la mort cérébrale."
  },
  AvgDialog_118703_Content_26 = {
    Text = "Cette fois, le sauvetage a déjà... échoué, tu dois revenir tout de suite, je vais activer le mode de rappel de l'appareil de séparation pour faire revenir ton esprit dans ton corps."
  },
  AvgDialog_118703_Content_27 = {
    Text = "<Big:Je ne pars pas !>"
  },
  AvgDialog_118703_Content_28 = {
    Text = "C'est la première fois que tu vois cette personne, habituellement si calme, crier de manière si désordonnée. Elle semble avoir légèrement froncé les narines, puis t'a rapidement offert un sourire plus naturel."
  },
  AvgDialog_118703_Content_29 = {
    Text = "Je vais bien, <Jaune:%player%>, j'ai récemment fait beaucoup d'entraînement, ma force mentale a augmenté, Doll ne connaît pas ma véritable limite."
  },
  AvgDialog_118703_Content_3 = {
    Text = "Alors que votre esprit est au bord de l'épuisement, les pupilles de la divinité commencent également à trembler de faiblesse."
  },
  AvgDialog_118703_Content_30 = {
    Text = "N'abandonne pas, essayons encore une fois, juste un petit essai, d'accord ?"
  },
  AvgDialog_118703_Content_31 = {
    Text = "Elle te supplie."
  },
  AvgDialog_118703_Content_32 = {Text = "新增"},
  AvgDialog_118703_Content_33 = {
    Text = "Tu ne peux pas parler."
  },
  AvgDialog_118703_Content_34 = {
    Text = "Pourquoi se torturer ainsi ? Laisse-moi capturer son esprit dans ce monde et le mettre dans le corps de poupée que j'ai soigneusement fabriqué, ainsi elle pourra de nouveau être à côté de <Jaune:%player%>."
  },
  AvgDialog_118703_Content_35 = {
    Text = "Fondu·Poupée, qui regardait le spectacle avec beaucoup de plaisir, a également rejoint le canal de communication, émettant un rire amusé."
  },
  AvgDialog_118703_Content_36 = {
    Text = "N'importe quoi. Tu sais que tout le monde ne peut pas exister dans un état de détachement spirituel de son corps comme le gardien du secret pendant longtemps, sinon nous n'aurions pas besoin de porter le fardeau d'un cerveau rose chaque jour."
  },
  AvgDialog_118703_Content_37 = {
    Text = "Pas de problème, Ramona, la prochaine fois, j'attendrai que tu sois reposée pour que tu viennes me chercher."
  },
  AvgDialog_118703_Content_38 = {
    Text = "Tu regardes cette silhouette translucide qui semble sur le point de se dissiper, souriant légèrement, cachant tous tes désirs de nostalgie."
  },
  AvgDialog_118703_Content_39 = {
    Text = "Ce n'est pas si simple, cette « route » a déjà été découverte par Lui. L'utiliser la prochaine fois n'attirera qu'un regard plus sévère."
  },
  AvgDialog_118703_Content_4 = {
    Text = "C'est le champ de bataille de la volonté. Tu es comme une bête mourante, utilisant toutes tes forces pour extraire ce dernier peu de puissance de ton monde spirituel asséché."
  },
  AvgDialog_118703_Content_40 = {
    Text = "Fusion·Doll a brisé sans pitié tes illusions, tandis que l'autre Doll restait silencieuse."
  },
  AvgDialog_118703_Content_41 = {
    Text = "<Shake:Nous sommes arrivés ici, cette fois, maintenant, je veux te ramener.>"
  },
  AvgDialog_118703_Content_42 = {
    Text = "Ramona commence également à trembler des mains. Tu prends une profonde inspiration et lui tapotes la main d'un air détendu."
  },
  AvgDialog_118703_Content_43 = {
    Text = "Ramona, tu te souviens de notre première rencontre ?"
  },
  AvgDialog_118703_Content_44 = {
    Text = "Ramona hocha la tête, puis la secoua, te regardant avec un regard presque suppliant. Tu n'avais d'autre choix que de fermer les yeux et de continuer à parler avec détermination."
  },
  AvgDialog_118703_Content_45 = {
    Text = "C'était vraiment une catastrophe horrible. Après le grand bang, je me souviens vaguement que tout autour de moi s'est transformé en ruines avec une explosion assourdissante, et quand j'ai ouvert les yeux, j'ai pensé être arrivé au paradis."
  },
  AvgDialog_118703_Content_46 = {
    Text = "Dans la lumière aveuglante du soleil qui pénètre entre les briques creusées, puis ta main s'étend devant moi."
  },
  AvgDialog_118703_Content_47 = {
    Text = "À ce moment-là, je me demandais si la tenue d'un ange était si étrange ? C'était un uniforme si rigide, je ne savais pas que bientôt, un tel uniforme serait aussi sur moi."
  },
  AvgDialog_118703_Content_48 = {
    Text = "Ramona voulait encore dire quelque chose, mais tu l'as interrompue, et tu as commencé à radoter comme un vieillard plongé dans ses souvenirs."
  },
  AvgDialog_118703_Content_49 = {
    Text = "Depuis que vous m'avez sorti de là, je t'ai toujours considéré comme la personne la plus gentille, mais en arrivant à Mizag, j'ai réalisé que j'avais été victime d'une énorme fraude."
  },
  AvgDialog_118703_Content_5 = {
    Text = "Tu lèves la clé en argent haut, avec des mains tremblantes."
  },
  AvgDialog_118703_Content_50 = {
    Text = "Au début de ma classe préparatoire, tu as dit que tu serais mon partenaire et que tu m'aiderais à résoudre tous mes problèmes de vie et d'étude, et j'y ai cru."
  },
  AvgDialog_118703_Content_51 = {
    Text = "En fait, tu as vraiment résolu mon problème, en utilisant la méthode qui s'attaque à la source du problème — <Shake:Résous-moi>."
  },
  AvgDialog_118703_Content_52 = {
    Text = "Le soi-disant partenaire est en réalité le plus grand surveillant. Cette année-là, dans la classe préparatoire, c'est toi qui me surveillais le plus strictement."
  },
  AvgDialog_118703_Content_53 = {
    Text = "Non seulement je dois te gérer en classe quand tu es assis à côté de moi, mais aussi te surveiller lorsque tu fais tes devoirs après. Parfois, après l'entraînement physique, ils ne me laissent même pas manger une assiette de poisson-frites, c'est vraiment trop détestable."
  },
  AvgDialog_118703_Content_54 = {
    Text = "L'expression silencieuse et triste de Ramona se fendit un instant, ses lèvres s'étirant involontairement."
  },
  AvgDialog_118703_Content_55 = {
    Text = "Mais, mon cher partenaire, tu es aussi la personne qui prend le plus soin de moi."
  },
  AvgDialog_118703_Content_56 = {
    Text = "Le langage universel de Leo qui ne peut être parlé, le stress des examens qui conduit à un effondrement, les devoirs qui ne peuvent pas être faits... Chaque fois que je me sens abattu, je peux toujours me tourner vers mon partenaire polyvalent."
  },
  AvgDialog_118703_Content_57 = {
    Text = "Je me souviens encore de la première fois où j'ai vu l'étudiant qui s'est sacrifié lors d'une mission, je n'ai pas pu dormir et j'ai discrètement frappé à ta porte au milieu de la nuit."
  },
  AvgDialog_118703_Content_58 = {
    Text = "Puis, tu me prends la main et nous courons jusqu'au sommet du clocher. Je grimpe péniblement sur le toit en te suivant, et nous nous asseyons côte à côte pour regarder les étoiles."
  },
  AvgDialog_118703_Content_59 = {
    Text = "Tu as beaucoup parlé avec moi, pendant très longtemps. C'était la première fois que je savais que tu ne savais pas non plus à quoi ressemblait ta mère, ton enfance."
  },
  AvgDialog_118703_Content_6 = {
    Text = "C'est fini... !——"
  },
  AvgDialog_118703_Content_60 = {
    Text = "Mon cœur, qui a toujours été un peu seul et un peu perdu, est soudainement tombé."
  },
  AvgDialog_118703_Content_61 = {
    Text = "Je pense que, bien que je n'aie pas de famille, c'est peut-être la seule personne dans le monde en ce moment qui me traite si bien, qui me ressemble tant, comme un membre de ma famille."
  },
  AvgDialog_118703_Content_62 = {
    Text = "Je te fais la promesse solennelle de m'engager, je garantirai à l'avenir de faire mes devoirs sérieusement, d'assister aux cours sérieusement et de rendre mes tâches sérieusement."
  },
  AvgDialog_118703_Content_63 = {
    Text = "Depuis lors, j'ai considéré Mizag comme ma véritable maison. Ainsi, au fil des missions, j'ai rencontré tant d'Éveilleurs et découvert un à un de nouveaux membres de ma famille."
  },
  AvgDialog_118703_Content_64 = {
    Text = "<Yellow:%player%>..."
  },
  AvgDialog_118703_Content_65 = {
    Text = "Alors, merci, merci à vous de m'avoir accueilli, ma famille."
  },
  AvgDialog_118703_Content_66 = {
    Text = "Je sais que vous avez essayé pendant très longtemps et que vous avez mis beaucoup d'efforts."
  },
  AvgDialog_118703_Content_67 = {
    Text = "Alors viens avec moi, je te ramènerai sûrement."
  },
  AvgDialog_118703_Content_68 = {
    Text = "En regardant les larmes couler du coin de l'œil de Ramona, tu continues à sourire, mais un liquide chaud s'écoule également incontrôlablement sur ta joue."
  },
  AvgDialog_118703_Content_69 = {
    Text = "Tu la regardes, son ombre devenant floue et scintillante à cause de la limite de sa force mentale, puis tu secoues doucement la tête."
  },
  AvgDialog_118703_Content_7 = {
    Text = "Une lumière argentée éblouissante s'ouvre dans ta main, illuminant toute la dimension illusoire."
  },
  AvgDialog_118703_Content_70 = {
    Text = "C'est tout pour le moment, Ramona."
  },
  AvgDialog_118703_Content_71 = {
    Text = "Non, non..."
  },
  AvgDialog_118703_Content_72 = {
    Text = "Ramona semblait avoir pressenti quelque chose. Elle secoue la tête avec force, tenant fermement ton corps spirituel avec ses mains floues."
  },
  AvgDialog_118703_Content_73 = {
    Text = "Je te promets, je reviendrai..."
  },
  AvgDialog_118703_Content_74 = {
    Text = "Je te promets, nous nous reverrons certainement."
  },
  AvgDialog_118703_Content_75 = {
    Text = "Tu retires doucement ta main de cette paume familière, lâchant prise."
  },
  AvgDialog_118703_Content_76 = {
    Text = "Doll, de l'autre côté de la communication, a reçu le signal, et une sensation familière d'équipement s'est transmise à l'esprit de Ramona, elle savait qu'elle devait partir."
  },
  AvgDialog_118703_Content_77 = {
    Text = "«Certain», «absolument», comme les mots que tu as prononcés la première fois que tu as franchi la porte… En fait, tu ne crois même pas en cela, n'est-ce pas ?"
  },
  AvgDialog_118703_Content_78 = {
    Text = "Tu es vraiment une personne impitoyable..."
  },
  AvgDialog_118703_Content_79 = {
    Text = "Ramona, je..."
  },
  AvgDialog_118703_Content_8 = {
    Text = "<Shake:Hmm@2@4@3!!!——>"
  },
  AvgDialog_118703_Content_80 = {
    Text = "Code de l'enquêteur... Ce que l'on a promis, il faut le faire."
  },
  AvgDialog_118703_Content_81 = {
    Text = "Je crois en toi. Même si tu ne te crois pas, même si tu m'as menti des milliers de fois, je crois en toi."
  },
  AvgDialog_118703_Content_82 = {
    Text = "Sur ce visage entre pleurs et sourires, les pupilles de Ramona te fixent, semblant vouloir graver ton visage dans sa mémoire."
  },
  AvgDialog_118703_Content_83 = {
    Text = "À la dernière seconde où le corps spirituel est rappelé dans le corps, elle tend à nouveau la main vers toi avec toutes ses forces."
  },
  AvgDialog_118703_Content_84 = {
    Text = "Comme ce moment d'il y a longtemps sous le ciel étoilé de la nuit, elle tendit son petit doigt et effleura doucement le bout de ton doigt."
  },
  AvgDialog_118703_Content_85 = {
    Text = "Tu réussiras certainement, n'est-ce pas ?"
  },
  AvgDialog_118703_Content_86 = {
    Text = "Sans attendre ta réponse. La seconde suivante, cette silhouette fantomatique se désintègre avec le tunnel dimensionnel, se transformant en des ombres éparses qui disparaissent lentement, sans laisser de traces."
  },
  AvgDialog_118703_Content_87 = {Text = "新增"},
  AvgDialog_118703_Content_88 = {Text = "新增"},
  AvgDialog_118703_Content_89 = {
    Text = "Respiration normale. Fréquence cardiaque normale. L'intensité mentale est inférieure au seuil d'alerte... en train de récupérer."
  },
  AvgDialog_118703_Content_9 = {Text = "Ah—"},
  AvgDialog_118703_Content_90 = {
    Text = "Même après avoir épuisé sa force spirituelle à ce point, il parvient à survivre, la vie d'un chiot est vraiment précieuse."
  },
  AvgDialog_118703_Content_91 = {
    Text = "J'ai regardé une bonne performance. C'est dommage que je n'aie pas vu les dieux que vous avez invoqués détruire ce monde ; la fin n'était pas assez excitante."
  },
  AvgDialog_118703_Content_92 = {
    Text = "Ne vous inquiétez pas… J'ai promis de L'arrêter dans un autre espace. Une promesse que je ne peux pas tenir… il n'y aura pas de deuxième fois."
  },
  AvgDialog_118703_Content_93 = {
    Text = "Ces mots, mieux vaut les garder pour lui parler en personne après être rentré."
  },
  AvgDialog_118703_Content_94 = {
    Text = "Puisque je marche sur ce chemin avec vous, je veux aussi voir jusqu'où tu peux aller."
  },
  AvgDialog_118703_Content_95 = {
    Text = "Après avoir bien reposé, reprends la route, petit chien."
  },
  AvgDialog_118703_Content_96 = {
    Text = "Tu sens le résidu de chaleur laissé par ses doigts, et tu serres lentement le petit doigt qui vient de s'entrelacer avec le sien, le pressant fortement contre ta poitrine."
  },
  AvgDialog_118703_Content_97 = {
    Text = "Vers cet espace dimensionnel vaste et désert, vers cette silhouette lointaine qui a déjà disparu, tu murmures doucement, racontant la promesse que tu vas certainement tenir."
  },
  AvgDialog_118703_Content_98 = {
    Text = "Bien que tu ne puisses pas entendre maintenant, je le ferai. Attends-moi, Ramona !"
  },
  AvgDialog_118703_Content_99 = {Text = "新增"},
  AvgDialog_118944_Content_1 = {
    Text = "En tranchant le dernier Poisson-nageur déformé, tu avances tout en te défendant vers la jeune fille dans le coin."
  },
  AvgDialog_118944_Content_10 = {
    Text = "William essaie de soulever la trappe menant à la cale, mais peu importe la force qu'il y met, la trappe ne bouge pas d'un pouce."
  },
  AvgDialog_118944_Content_11 = {
    Text = "Non, la porte est déjà scellée par le bas !"
  },
  AvgDialog_118944_Content_12 = {
    Text = "La coque du navire émet un gémissement glaçant, et dans des vagues gigantesques, elle commence à virer avec difficulté et détermination, se dirigeant vers des eaux encore plus sombres, où les tempêtes sont plus denses."
  },
  AvgDialog_118944_Content_13 = {
    Text = "Miryam ouvre les bras, embrassant cette direction destructrice, un sourire d'une douceur presque maternelle se dessine sur son visage."
  },
  AvgDialog_118944_Content_14 = {
    Text = "Le rituel va se terminer !"
  },
  AvgDialog_118944_Content_15 = {
    Text = "As-tu trouvé la réponse ?"
  },
  AvgDialog_118944_Content_16 = {
    Text = "Dans la lutte entre la tempête et le chaos, personne ne peut distinguer la position de chacun..."
  },
  AvgDialog_118944_Content_17 = {
    Text = "Tant qu'il y a un autre petit bateau..."
  },
  AvgDialog_118944_Content_18 = {
    Text = "Aucun indice ne s'illumine dans votre esprit…"
  },
  AvgDialog_118944_Content_19 = {
    Text = "Garde du salon."
  },
  AvgDialog_118944_Content_2 = {
    Text = "Murphy, viens avec moi !"
  },
  AvgDialog_118944_Content_20 = {
    Text = "La cérémonie de pilotage sur le pont."
  },
  AvgDialog_118944_Content_21 = {
    Text = "L'explosion de la salle de puissance."
  },
  AvgDialog_118944_Content_22 = {
    Text = "Canot de sauvetage dans la cale inférieure."
  },
  AvgDialog_118944_Content_23 = {
    Text = "Les points lumineux se relient, s'entrelacent, s'étendent... jusqu'à finalement former une ligne d'évasion cohérente et claire."
  },
  AvgDialog_118944_Content_24 = {
    Text = "William hocha la tête."
  },
  AvgDialog_118944_Content_25 = {
    Text = "Puisque tu as déjà obtenu la réponse, l'objectif de ce cycle est donc essentiellement accompli, il n'est pas nécessaire d'avoir des regrets."
  },
  AvgDialog_118944_Content_26 = {
    Text = "Selon la tendance que vous avez décrite, le bateau va commencer à sombrer."
  },
  AvgDialog_118944_Content_27 = {
    Text = "Es-tu prêt ?"
  },
  AvgDialog_118944_Content_28 = {
    Text = "La marée a déjà englouti vos poitrines, tu serres doucement la clé en argent contre ta poitrine, murmurant des mots d'adieu."
  },
  AvgDialog_118944_Content_29 = {
    Text = "À la prochaine réincarnation."
  },
  AvgDialog_118944_Content_3 = {
    Text = "Elle tressaillit comme effrayée, son regard flou peinant à se fixer sur ton visage."
  },
  AvgDialog_118944_Content_30 = {
    Text = "Que la Clé d'argent éclaire mon chemin."
  },
  AvgDialog_118944_Content_4 = {
    Text = "Non, c'est inutile, tout n'est qu'illusion... Que ce soit avancer ou reculer, tout..."
  },
  AvgDialog_118944_Content_5 = {
    Text = "Tant que ce n'est pas la dernière minute, ne renonce pas à essayer ! Même si je échoue encore cette fois, je te prendrai à nouveau la main !"
  },
  AvgDialog_118944_Content_6 = {Text = "新增"},
  AvgDialog_118944_Content_7 = {
    Text = "Murphy te regarde fixement."
  },
  AvgDialog_118944_Content_8 = {
    Text = "Tu lui saisis le poignet avec une force douce mais inébranlable, la tirant hors de ce coin désespéré."
  },
  AvgDialog_118944_Content_9 = {
    Text = "William, l'Aîné, y a-t-il un chemin d'évasion ?"
  },
  AvgDialog_118945_Content_1 = {
    Text = "Petit, tu as retenu tes coups pendant le combat."
  },
  AvgDialog_118945_Content_10 = {
    Text = "Certaines personnes commettent des actes malveillants pour chercher leur propre survie à la fin."
  },
  AvgDialog_118945_Content_11 = {
    Text = "Certaines personnes filtrent les autres selon leurs propres idées, dans le but de construire le nouveau monde de leurs rêves."
  },
  AvgDialog_118945_Content_12 = {
    Text = "Il y a aussi des gens qui, simplement pour s'amuser, peuvent provoquer des bouleversements et créer d'innombrables problèmes."
  },
  AvgDialog_118945_Content_13 = {
    Text = "Tu attends, tu espères sa réponse. Car tu as déjà vu le chemin qu'elle a emprunté dans un rêve lointain."
  },
  AvgDialog_118945_Content_14 = {
    Text = "Aujourd'hui, la folle Miryam était autrefois cette jeune fille qui, au milieu du fléau, s'est sacrifiée pour protéger sa seule famille, en accomplissant la mission du prêtre."
  },
  AvgDialog_118945_Content_15 = {
    Text = "Miryam ne répond pas directement à votre question. Elle joint ses mains et prie vers l'horizon lointain."
  },
  AvgDialog_118945_Content_16 = {
    Text = "«Toute dévotion, le Maître la bénira…»"
  },
  AvgDialog_118945_Content_17 = {
    Text = "\"À tous ceux qui désirent, mon Seigneur accordera.\""
  },
  AvgDialog_118945_Content_18 = {
    Text = "Comme si elle avait reçu l'approbation de la mer, elle ouvrit à moitié ses yeux violet-noir, perdus."
  },
  AvgDialog_118945_Content_19 = {
    Text = "Je viens pour la renaissance du Royaume Divin, pour que la gloire des dieux se manifeste à nouveau dans ce monde."
  },
  AvgDialog_118945_Content_2 = {
    Text = "Pour moi, cette conversation avec Miryam est beaucoup plus cruciale qu'une victoire."
  },
  AvgDialog_118945_Content_20 = {
    Text = "Alors, lorsque Lémuria réapparaîtra dans le monde, quel genre de monde espères-tu voir ?"
  },
  AvgDialog_118945_Content_21 = {
    Text = "«Dans le long rêve des dieux, toi et moi partageons une paix et un bonheur éternels.»"
  },
  AvgDialog_118945_Content_22 = {
    Text = "La renaissance de la prospérité de Lémuria, comme vous l'avez été inculqué de votre vivant."
  },
  AvgDialog_118945_Content_23 = {
    Text = "Tu n'as jamais vu un tel âge d'or, même pas un jour, sais-tu vraiment comment le créer ?"
  },
  AvgDialog_118945_Content_24 = {
    Text = "«La volonté de Dieu montrera le chemin vers Lémuria aux croyants.»"
  },
  AvgDialog_118945_Content_25 = {
    Text = "Toi dans ce monde, en effet, ne diffères en rien de ce que je connais."
  },
  AvgDialog_118945_Content_26 = {
    Text = "Alors, au moment où le dieu est né, pourquoi tiens-tu fermement Murphy dans ta main ?"
  },
  AvgDialog_118945_Content_3 = {
    Text = "Tant que vous pouvez induire un léger ébranlement chez Miryam, le labyrinthe révélera sa fissure, son « noyau » caché..."
  },
  AvgDialog_118945_Content_4 = {
    Text = "Vous avez l'espoir de mettre fin à ce rêve artificiel obstiné."
  },
  AvgDialog_118945_Content_5 = {
    Text = "Veuillez expliquer votre intention."
  },
  AvgDialog_118945_Content_6 = {
    Text = "Je viens avec une question."
  },
  AvgDialog_118945_Content_7 = {
    Text = "Miryam, pourquoi veux-tu faire renaître le Royaume Divin ?"
  },
  AvgDialog_118945_Content_8 = {
    Text = "Tu as posé une question très intéressante."
  },
  AvgDialog_118945_Content_9 = {
    Text = "J'ai rencontré beaucoup de gens dans mon voyage contre la fusion."
  },
  AvgDialog_118946_Content_1 = {
    Text = "Saut et liberté"
  },
  AvgDialog_118946_Content_10 = {
    Text = "Elle leva ses doigts pâles et tourna à nouveau le rouet."
  },
  AvgDialog_118946_Content_100 = {
    Text = "Jusqu'à ce que les ténèbres engloutissent le monde."
  },
  AvgDialog_118946_Content_11 = {
    Text = "Bien que je ne connaisse pas encore ton nom, s'il te plaît, bénis-moi, étranger."
  },
  AvgDialog_118946_Content_12 = {
    Text = "Un nuage d'oiseaux s'envole, soulevant des vagues de plumes blanches. \n Après que les vagues se soient retirées, la femme a également disparu."
  },
  AvgDialog_118946_Content_13 = {
    Text = "Tu as rapidement résumé le plan global à William."
  },
  AvgDialog_118946_Content_14 = {
    Text = "Cela ressemble à un plan qui cherche à triompher dans le chaos."
  },
  AvgDialog_118946_Content_15 = {
    Text = "La cérémonie terminée, la rébellion éclate, c'est le moment où l'Église des Marins est la plus fragile."
  },
  AvgDialog_118946_Content_16 = {
    Text = "Selon les indices fournis par Faros, peut-être que nous n'avons besoin que de maîtriser la statue en ivoire pour sortir du labyrinthe."
  },
  AvgDialog_118946_Content_17 = {
    Text = "Emmener Murphy, est-ce trop compliqué ?"
  },
  AvgDialog_118946_Content_18 = {
    Text = "William, l'Aîné, c'est toi qui m'as dit que les événements dans le Labyrinthe pourraient affecter le monde réel à l'extérieur du Labyrinthe."
  },
  AvgDialog_118946_Content_19 = {
    Text = "Puisque c'est le cas, je ne peux pas rester les bras croisés face à Murphy…"
  },
  AvgDialog_118946_Content_2 = {
    Text = "Encore un cycle."
  },
  AvgDialog_118946_Content_20 = {
    Text = "Goliath visait à s'emparer du navire, il ne se soucierait pas de l'évasion de Murphy ; Miryam était trop épuisée pour faire face à Goliath et aussi trop faible pour poursuivre."
  },
  AvgDialog_118946_Content_21 = {
    Text = "C'est une occasion exceptionnelle."
  },
  AvgDialog_118946_Content_22 = {
    Text = "William ferma les yeux, ajusta ses lunettes et soupira, semblant impuissant."
  },
  AvgDialog_118946_Content_23 = {
    Text = "Je t'écoute."
  },
  AvgDialog_118946_Content_24 = {
    Text = "Comme dans le dernier cycle, toi et William êtes en embuscade sur la plateforme du mât."
  },
  AvgDialog_118946_Content_25 = {
    Text = "Profitant de la rébellion de Goliath, tu sautes et saisis le poignet de Murphy."
  },
  AvgDialog_118946_Content_26 = {
    Text = "Vite, suis-moi, saute dans le bateau !"
  },
  AvgDialog_118946_Content_27 = {
    Text = "Es-tu fou ? Pourquoi reviens-tu encore ? Nous ne pouvons pas nous échapper, pourquoi ne pas laisser les choses continuer tranquillement ?"
  },
  AvgDialog_118946_Content_28 = {
    Text = "Murphy essaie de se libérer de toi, mais ta détermination est inébranlable. Un cercle rouge pâle apparaît sur son poignet."
  },
  AvgDialog_118946_Content_29 = {
    Text = "Murphy, la tranquillité que tu souhaitais n'existe plus depuis longtemps."
  },
  AvgDialog_118946_Content_3 = {
    Text = "Des oiseaux volants au-dessus de la femme sur la mer, leurs cris mélancoliques ressemblent à des chants."
  },
  AvgDialog_118946_Content_30 = {
    Text = "Goliath et Caecus planifient de prendre le navire, Faros complote pour le pouvoir de la statue en ivoire, et l'ensemble des Marcheurs des mers est déjà en morceaux."
  },
  AvgDialog_118946_Content_31 = {
    Text = "Crois-moi, crois-moi encore une fois. Je te ferai certainement échapper."
  },
  AvgDialog_118946_Content_32 = {
    Text = "Échapper, et ensuite ?"
  },
  AvgDialog_118946_Content_33 = {
    Text = "Ensuite, nous trouverons un moyen de retourner à Mizag, et tu feras partie de Mizag avec tout le monde."
  },
  AvgDialog_118946_Content_34 = {
    Text = "On dit souvent que mes rêves sont des rêves prémonitoires, dans un rêve lointain, j'ai vu de telles visions..."
  },
  AvgDialog_118946_Content_35 = {
    Text = "Tu sens que la force de la résistance a légèrement diminué."
  },
  AvgDialog_118946_Content_36 = {
    Text = "Venez, avec moi, vers le côté droit du bastingage... Trois, deux, un, sautez !"
  },
  AvgDialog_118946_Content_37 = {
    Text = "Plouf, plouf."
  },
  AvgDialog_118946_Content_38 = {
    Text = "Deux poissons libres et sautants sont revenus à leur loyauté, l'océan, les mains toujours fermement entrelacées."
  },
  AvgDialog_118946_Content_39 = {
    Text = "Le soleil pénètre à la surface de la mer, illuminant ses mèches flottantes et son voile dans l'eau cristalline.\n Ses pupilles rose regardent fixement vers toi, comme un rêve silencieux."
  },
  AvgDialog_118946_Content_4 = {
    Text = "Ne t'inquiète pas, cette fois, nos préparatifs sont infaillibles."
  },
  AvgDialog_118946_Content_40 = {
    Text = "Vous êtes libres."
  },
  AvgDialog_118946_Content_41 = {
    Text = "Éclaboussure—"
  },
  AvgDialog_118946_Content_42 = {
    Text = "Une rame plonge dans l'eau cristalline devant moi."
  },
  AvgDialog_118946_Content_43 = {
    Text = "Tu hoches la tête vers Murphy, et tous deux vous agrippez à la pagaie."
  },
  AvgDialog_118946_Content_44 = {
    Text = "Tu as bien attrapé ?"
  },
  AvgDialog_118946_Content_45 = {
    Text = "Il vous a tirés hors de l'eau, et vous vous accrochez au bord du petit bateau pour monter."
  },
  AvgDialog_118946_Content_46 = {
    Text = "Hé, viens m'aider !"
  },
  AvgDialog_118946_Content_47 = {
    Text = "Qu'est-ce qui se passe, tu ne peux pas monter tout seul ?"
  },
  AvgDialog_118946_Content_48 = {
    Text = "Assez de paroles, nous n'avons même pas encore abordé votre crime d'avoir laissé la Mère divine tomber dans l'eau !"
  },
  AvgDialog_118946_Content_49 = {
    Text = "Tu tires doucement sur l'épaule de Murphy qui flotte, la relevant de l'eau avec juste ce qu'il faut de force."
  },
  AvgDialog_118946_Content_5 = {
    Text = "Nous savons qu'après la fin du rituel de pilotage, le navire chavirera ; nous savons que la statue en ivoire a le pouvoir de manipuler les rêves."
  },
  AvgDialog_118946_Content_50 = {Text = "Ouf—"},
  AvgDialog_118946_Content_51 = {
    Text = "Bien, maintenant nous pouvons en parler sérieusement. Où allons-nous ?"
  },
  AvgDialog_118946_Content_52 = {
    Text = "Profiter de la mêlée entre Goliath et Miryam, nous trois prenons ensemble le contrôle de ce navire pour sortir des frontières du Labyrinthe."
  },
  AvgDialog_118946_Content_53 = {
    Text = "Ensuite, ensemble, nous trouverons le chemin de retour vers le monde d'origine, où tu rencontreras le toi de cet univers, en compétition pour de petits gâteaux dans la cafétéria chaque jour..."
  },
  AvgDialog_118946_Content_54 = {
    Text = "Pfft, ce sera un long voyage."
  },
  AvgDialog_118946_Content_55 = {
    Text = "Puisque c'est comme ça, parle-moi bien de cet endroit appelé Mizag..."
  },
  AvgDialog_118946_Content_56 = {Text = "新增"},
  AvgDialog_118946_Content_57 = {Text = "新增"},
  AvgDialog_118946_Content_58 = {
    Text = "Ensuite, et ensuite ?"
  },
  AvgDialog_118946_Content_59 = {
    Text = "Puis, Ramona découvrit le vin caché de Seigneur Dexter dans le coin de sa bibliothèque. Pour cacher ces vins, il avait creusé quelques pages des livres."
  },
  AvgDialog_118946_Content_6 = {
    Text = "Nous savons aussi qu'il y a un seul canot de sauvetage dans la cale inférieure, tant que nous nous éloignons de ce paquebot, nous ne serons plus soumis à la contrainte de Miryam."
  },
  AvgDialog_118946_Content_60 = {
    Text = "Vous apercevez William qui baisse la tête, fronce les sourcils et se frotte les tempes."
  },
  AvgDialog_118946_Content_61 = {
    Text = "Elle était en colère et entra directement dans le salon de Madame Sorel avec son épée fine !"
  },
  AvgDialog_118946_Content_62 = {Text = "Et alors ?"},
  AvgDialog_118946_Content_63 = {
    Text = "Murphy serre nerveusement ta manche, son appétit aiguisé par les histoires intrigantes."
  },
  AvgDialog_118946_Content_64 = {
    Text = "Les rires et les plaisanteries dans le salon se sont soudainement figés, tout le monde a écarquillé les yeux en fixant cet invité indésirable !"
  },
  AvgDialog_118946_Content_65 = {
    Text = "C'est exact, comme William, l'Aîné, maintenant !"
  },
  AvgDialog_118946_Content_66 = {Text = "Il y a..."},
  AvgDialog_118946_Content_67 = {
    Text = "Il y a des assassins, des assassins ! Des cris se font entendre partout !"
  },
  AvgDialog_118946_Content_68 = {
    Text = "Ton sourire est figé sur ton visage."
  },
  AvgDialog_118946_Content_69 = {
    Text = "Derrière Murphy, à la bordure du petit bateau, un monstre colossal composé de millions de cadavres s'élève brusquement de la surface de la mer."
  },
  AvgDialog_118946_Content_7 = {
    Text = "Notre plan est que je pénètre dans la cérémonie de pilotage et que, profitant de la faiblesse de Murphy, je l'entraîne dans la mer."
  },
  AvgDialog_118946_Content_70 = {
    Text = "<Big:......>"
  },
  AvgDialog_118946_Content_71 = {
    Text = "Il ouvre silencieusement sa grande bouche composée d'os et de crânes en mouvement—"
  },
  AvgDialog_118946_Content_72 = {
    Text = "<Red:Avalez Murphy entièrement>"
  },
  AvgDialog_118946_Content_73 = {
    Text = "<Shake:Non... la Marionnette de la Vague Putride... ne devrait-elle pas déjà être dans la Nekropolis...>"
  },
  AvgDialog_118946_Content_74 = {
    Text = "Dans ce Labyrinthe, Goliath continue de manipuler la Marionnette de la Vague Putride."
  },
  AvgDialog_118946_Content_75 = {
    Text = "Ses forces principales sont en train de lutter contre Miryam, donc il a envoyé cette escouade extérieure pour la poursuite..."
  },
  AvgDialog_118946_Content_76 = {
    Text = "Nous... avons mal calculé."
  },
  AvgDialog_118946_Content_77 = {
    Text = "<Big:<Shake:......!!!>>"
  },
  AvgDialog_118946_Content_78 = {
    Text = "Le monstre qui a dévoré Murphy leva sa tête étrange, émettant un bruit de satisfaction dans sa gorge."
  },
  AvgDialog_118946_Content_79 = {
    Text = "La brume souillée se diffuse à la surface de la mer, le Parades au loin est déjà invisible, seules les cimes des ossements écrasent le ciel et le soleil."
  },
  AvgDialog_118946_Content_8 = {
    Text = "William, l'Aîné, conduira la chaloupe pour me récupérer, moi et Murphy, sur le côté du navire. Après avoir embarqué, je déchiffrerai rapidement le mystère de la statue en ivoire et échapperai au Labyrinthe."
  },
  AvgDialog_118946_Content_80 = {
    Text = "Éloigne-toi vite !"
  },
  AvgDialog_118946_Content_81 = {
    Text = "William te prit dans ses bras, te tenant fermement alors que vous rouliez sur le côté du bateau, échappant de justesse au premier coup violent de la griffe osseuse."
  },
  AvgDialog_118946_Content_82 = {
    Text = "William, l'Aîné, ton dos..."
  },
  AvgDialog_118946_Content_83 = {
    Text = "Sang, du sang qui goutte."
  },
  AvgDialog_118946_Content_84 = {
    Text = "Ne vous occupez pas de moi, montez et tranchez la colonne vertébrale de la Marionnette de la Vague Putride !"
  },
  AvgDialog_118946_Content_85 = {Text = "新增"},
  AvgDialog_118946_Content_86 = {
    Text = "<Big:......>"
  },
  AvgDialog_118946_Content_87 = {
    Text = "La Marionnette de la Vague Putride s'effondre comme une haute tour, une pluie d'os pâles tombe dans l'immensité de l'océan infini."
  },
  AvgDialog_118946_Content_88 = {
    Text = "Comme tu l'as dit... la force de Goliath a été considérablement affaiblie dans le Labyrinthe."
  },
  AvgDialog_118946_Content_89 = {
    Text = "Donc, nous pouvons à peine résister…"
  },
  AvgDialog_118946_Content_9 = {
    Text = "La femme baissa la tête, des mèches de frange fines cachant son expression."
  },
  AvgDialog_118946_Content_90 = {
    Text = "Peut-être en raison de la gravité de sa blessure, tu n'entends plus les paroles de William."
  },
  AvgDialog_118946_Content_91 = {
    Text = "Au milieu des marées de cadavres effondrées et des ossements, la silhouette de cette jeune fille est introuvable."
  },
  AvgDialog_118946_Content_92 = {
    Text = "Murphy... Murphy !"
  },
  AvgDialog_118946_Content_93 = {
    Text = "Tu te précipites vers les os flottants, en creusant un à un les crânes entassés à l'emplacement du tube digestif."
  },
  AvgDialog_118946_Content_94 = {
    Text = "<Yellow:%player%>..."
  },
  AvgDialog_118946_Content_95 = {
    Text = "On ne trouve pas Murphy nulle part."
  },
  AvgDialog_118946_Content_96 = {
    Text = "Au centre des os disposés de manière chaotique, il n'y a qu'un fin et léger voile noir."
  },
  AvgDialog_118946_Content_97 = {
    Text = "Vous soulevez doucement le morceau de voile noir, une douleur aigüe vous envahit."
  },
  AvgDialog_118946_Content_98 = {
    Text = "Je pensais qu cette fois, je pourrais vraiment l'emmener avec moi..."
  },
  AvgDialog_118946_Content_99 = {
    Text = "Tu laisses échapper un sanglot sourd. Puis les pleurs deviennent progressivement plus forts."
  },
  AvgDialog_118947_Content_1 = {
    Text = "«ParadisN°»"
  },
  AvgDialog_118947_Content_10 = {
    Text = "Tu sors la plaque de cuisson avec des pinces en fer, et Murphy tend immédiatement la main pour prendre un petit gâteau qui dégage de la chaleur."
  },
  AvgDialog_118947_Content_11 = {
    Text = "Ne t'inquiète pas, ça brûle, ça brûle, ça brûle, ça brûle !"
  },
  AvgDialog_118947_Content_12 = {
    Text = "Murphy semblait totalement réticente à lâcher prise, se brûlant les mains en les alternant plusieurs fois, elle attendit enfin que le gâteau atteigne une température convenable."
  },
  AvgDialog_118947_Content_13 = {
    Text = "Goûte un peu... Il semble que je n'ai pas besoin de le dire."
  },
  AvgDialog_118947_Content_14 = {
    Text = "Avant même que tu aies fini de parler, Murphy avait déjà mordu."
  },
  AvgDialog_118947_Content_15 = {
    Text = "Alors, c'était bon ?"
  },
  AvgDialog_118947_Content_16 = {
    Text = "La recette repose entièrement sur ta mémoire. Pour prendre soin de la jeune dame qui crie de faim au milieu de la nuit, tu as emprunté plusieurs fois la cuisine de Mizag."
  },
  AvgDialog_118947_Content_17 = {
    Text = "Hum, les ingrédients sont trop basiques, rien à voir avec ce que Miryam me sert d'habitude."
  },
  AvgDialog_118947_Content_18 = {
    Text = "Murphy avala prudemment les résidus dans sa bouche et parla sérieusement."
  },
  AvgDialog_118947_Content_19 = {
    Text = "Cependant, qui a dit que le talent culinaire de cette Mère divine est incroyable, capable de transformer la pourriture en miracle ."
  },
  AvgDialog_118947_Content_2 = {Text = "新增"},
  AvgDialog_118947_Content_20 = {
    Text = "Chaud et moelleux... c'est la nourriture la plus délicieuse que j'aie jamais goûtée."
  },
  AvgDialog_118947_Content_21 = {
    Text = "Je vais aussi essayer un morceau."
  },
  AvgDialog_118947_Content_22 = {
    Text = "William, avec précaution, utilise un petit couteau argenté pour en piquer un morceau et le porter à sa bouche."
  },
  AvgDialog_118947_Content_23 = {
    Text = "Aîné, si je ne me trompe pas, est-ce que ce scalpel que tu as utilisé pour couper le gâteau est celui qui a précédemment disséqué Nubia ?"
  },
  AvgDialog_118947_Content_24 = {
    Text = "Il a été entièrement désinfecté. Les couteaux et fourchettes grossiers utilisés par les matelots sont vraiment difficiles à utiliser pour manger."
  },
  AvgDialog_118947_Content_25 = {
    Text = "J'aurais dû demander à Doresain deux ensembles de couverts à Nekropolis…\n Laisse tomber, en y réfléchissant, c'est encore plus difficile de dire avec quoi les couverts de Doresain ont été contaminés..."
  },
  AvgDialog_118947_Content_26 = {
    Text = "Vous vous régalez en riant en vous étalant de la crème sur le visage des uns et des autres."
  },
  AvgDialog_118947_Content_27 = {
    Text = "(Si c'est son dernier souvenir...)"
  },
  AvgDialog_118947_Content_28 = {Text = "Bang—"},
  AvgDialog_118947_Content_29 = {
    Text = "Un bruit assourdissant brise le rare calme, et la cuisine où vous vous trouvez commence soudainement à trembler de manière incontrôlable."
  },
  AvgDialog_118947_Content_3 = {
    Text = "Dans une trentaine de minutes."
  },
  AvgDialog_118947_Content_30 = {Text = "Quoi ?!"},
  AvgDialog_118947_Content_31 = {
    Text = "Goliath a pillé la salle de puissance, Miryam a résisté avec acharnement, et une explosion s'est produite dans la salle de puissance."
  },
  AvgDialog_118947_Content_32 = {
    Text = "Tu réponds avec désinvolture."
  },
  AvgDialog_118947_Content_33 = {
    Text = "En d'autres termes, le bateau va couler."
  },
  AvgDialog_118947_Content_34 = {
    Text = "Le bateau va couler, tu n'as aucune réaction ?"
  },
  AvgDialog_118947_Content_35 = {
    Text = "Murphy, j'ai quelque chose à te dire.\nCe bateau doit sombrer."
  },
  AvgDialog_118947_Content_36 = {
    Text = "J'ai traversé cinq cycles, et à chaque cycle, Goliath planifie des raids."
  },
  AvgDialog_118947_Content_37 = {
    Text = "Ce processus provoquera une explosion dans la salle de puissance, puis le bateau sera aspiré au fond de la mer par un vortex."
  },
  AvgDialog_118947_Content_38 = {Text = "Donc ?"},
  AvgDialog_118947_Content_39 = {
    Text = "J'ai toujours cherché à empêcher la destruction de ce bateau, c'était une erreur de ma part."
  },
  AvgDialog_118947_Content_4 = {
    Text = "Vous fixez le four, la pâte pétrie gonfle peu à peu, et votre cœur plein d'attente se dilate également avec la courbure moelleuse."
  },
  AvgDialog_118947_Content_40 = {
    Text = "Ce bateau devrait sombrer... Ce n'est qu'en coulant qu'il pourra te dégager un chemin vers la liberté."
  },
  AvgDialog_118947_Content_41 = {Text = "Boum——"},
  AvgDialog_118947_Content_42 = {
    Text = "La coque tremble et se convulse comme si elle avait été frappée par la foudre, comme si une bête géante se débattait dans une douleur explosive."
  },
  AvgDialog_118947_Content_43 = {
    Text = "C'est bon, maintenant pas besoin d'expliquer autant, suis-moi vite."
  },
  AvgDialog_118947_Content_44 = {
    Text = "Encore un peu plus tard, il sera trop tard pour tout."
  },
  AvgDialog_118947_Content_45 = {
    Text = "Tu tires Murphy et avances le long du chemin indiqué par William."
  },
  AvgDialog_118947_Content_46 = {
    Text = "Hé, tu veux vraiment faire grimper la dame sur l'échelle ? C'est vraiment trop embarrassant de se débattre devant les étrangers ?!"
  },
  AvgDialog_118947_Content_47 = {
    Text = "Descends d'abord et attends-moi, je ne baisserai absolument pas la tête pour te regarder."
  },
  AvgDialog_118947_Content_48 = {
    Text = "Les yeux s'adaptent progressivement aux ténèbres, dans un coin de la cale, une petite barque est arrêtée, seule."
  },
  AvgDialog_118947_Content_49 = {
    Text = "C'est le chemin de fuite que Goliath a préparé pour lui-même, que nous avons trouvé."
  },
  AvgDialog_118947_Content_5 = {
    Text = "L'odeur de crème anglaise se répand partout, les glandes salivaires réagissent plus vite que le cerveau, et le ver de l'appétit fait gargouiller votre ventre."
  },
  AvgDialog_118947_Content_50 = {
    Text = "Ce rusé a détruit presque tous les canots de sauvetage avant la rébellion, s'assurant qu'il était le seul à pouvoir s'échapper."
  },
  AvgDialog_118947_Content_51 = {
    Text = "Voici la clé de secours, que j'ai fait préparer par William. Maintenant, embarquez."
  },
  AvgDialog_118947_Content_52 = {
    Text = "Attends, de quoi parles-tu, je n'ai jamais accepté de fuir avec toi——"
  },
  AvgDialog_118947_Content_53 = {
    Text = "Je n'ai jamais dit que je monterais à bord avec toi. Il y a ici, et seulement un canot de sauvetage. Monte dedans tout seul, puis débarque."
  },
  AvgDialog_118947_Content_54 = {Text = "!"},
  AvgDialog_118947_Content_55 = {
    Text = "Si nous partons ainsi, Miryam ne restera pas les bras croisés. Un jour, l'ombre des Marcheurs des mers te rattrapera."
  },
  AvgDialog_118947_Content_56 = {
    Text = "Je dois rester ici pour m'assurer que le Marcheur des mers et le Fœtus Sacré sombrent à jamais dans l'Aequor."
  },
  AvgDialog_118947_Content_57 = {
    Text = "C'est aussi ce qu'ils souhaitent, retourner dans leur patrie éternelle et dans le Royaume divin, n'est-ce pas ?"
  },
  AvgDialog_118947_Content_58 = {
    Text = "Pchit——"
  },
  AvgDialog_118947_Content_59 = {
    Text = "Murphy sourit en larmes."
  },
  AvgDialog_118947_Content_6 = {
    Text = "Le bruit des pas anormaux et humides du Marcheur des mers se fait entendre de temps en temps sur le plancher en bois, mais la fine porte sépare deux mondes. Cet espace est rempli d'un bonheur et d'une chaleur excessivement simples, comme une illusion."
  },
  AvgDialog_118947_Content_60 = {
    Text = "Avant de partir, j'avais déjà tout planifié."
  },
  AvgDialog_118947_Content_61 = {
    Text = "Si je peux t'aider à t'échapper, alors ce sera le meilleur dénouement."
  },
  AvgDialog_118947_Content_62 = {
    Text = "Si je ne peux pas... au moins, j'ai essayé de te restituer une journée que le Murphy que je connais aimerait."
  },
  AvgDialog_118947_Content_63 = {
    Text = "Nous ne nous connaissons pas depuis longtemps et je ne te connais pas encore très bien. J'espère que cela te plaît aussi."
  },
  AvgDialog_118947_Content_64 = {
    Text = "Murphy se mit sur la pointe des pieds et te fit un doux câlin."
  },
  AvgDialog_118947_Content_65 = {
    Text = "Je me souviens que tu as dit auparavant que tu vivrais la réincarnation encore et encore."
  },
  AvgDialog_118947_Content_66 = {
    Text = "Cette fois-ci, ce ne sera pas la fin."
  },
  AvgDialog_118947_Content_67 = {
    Text = "La prochaine fois, emmène-moi avec toi pour m'échapper, d'accord ?"
  },
  AvgDialog_118947_Content_68 = {
    Text = "<Red:Il n'y aura pas de prochaine fois.>\n Une sensation âcre monte à ton nez."
  },
  AvgDialog_118947_Content_69 = {
    Text = "Je te le promets. Nous nous échappons ensemble."
  },
  AvgDialog_118947_Content_7 = {
    Text = "Regarde, la peau a déjà changé de couleur, elle peut être servie !"
  },
  AvgDialog_118947_Content_70 = {
    Text = "Des nuages sombres s'amoncellent, et à l'avant du navire, Miryam fait face à Goliath à distance."
  },
  AvgDialog_118947_Content_71 = {
    Text = "Remets-moi cette petite fille et la statue en ivoire, je peux, comme tu l'as déjà menacé, t'accorder une mort glorieuse."
  },
  AvgDialog_118947_Content_72 = {
    Text = "Arrête de dire des absurdités ici, n'est-ce pas vous qui avez enlevé la Mère divine et provoqué cette révolte ?"
  },
  AvgDialog_118947_Content_73 = {
    Text = "Vous n'avez plus besoin de vous disputer, Murphy n'est plus sur ce bateau. \n Elle a échappé aux griffes de la magie, loin du tourbillon."
  },
  AvgDialog_118947_Content_74 = {
    Text = "Une inexplicable consolation m'envahit."
  },
  AvgDialog_118947_Content_75 = {
    Text = "C'est toi qui l'as envoyée dehors ? Tu as du courage, en effet."
  },
  AvgDialog_118947_Content_76 = {
    Text = "Si vous êtes prêts à vous battre ici, cela ne me dérange pas de profiter de la situation."
  },
  AvgDialog_118947_Content_77 = {
    Text = "C'est donc toi, cet étranger sans nom..."
  },
  AvgDialog_118947_Content_78 = {
    Text = "Pensez-vous qu'avec la protection de la Mère divine, vous pouvez agir à votre guise ?"
  },
  AvgDialog_118947_Content_79 = {
    Text = "Miryam, je veux te parler."
  },
  AvgDialog_118947_Content_8 = {
    Text = "...D'accord !"
  },
  AvgDialog_118947_Content_80 = {
    Text = "Il ne s'agit pas de déclarer la guerre de manière impolie directement ; il s'agit de commencer par la conversation, n'est-ce pas ?"
  },
  AvgDialog_118947_Content_81 = {
    Text = "Je suis aussi très curieux de savoir quel genre de vaurien tu es, pour avoir été appelé par la Mère divine et être capable d'agir de manière imprudente et téméraire jusqu'à présent."
  },
  AvgDialog_118947_Content_82 = {
    Text = "Si tu demandes sincèrement une réponse à l'Apôtre de Dieu, je ne manquerai pas de te donner la volonté divine."
  },
  AvgDialog_118947_Content_83 = {
    Text = "<Red:<Shake:Mais maintenant, subissez d'abord la colère du Marcheur des Mers !>>"
  },
  AvgDialog_118947_Content_9 = {
    Text = "Un parfum de crème et d'œufs s'échappe."
  },
  AvgDialog_118948_Content_1 = {Text = "Vortex"},
  AvgDialog_118948_Content_10 = {
    Text = "«Clac», le fil argenté se brisa instantanément."
  },
  AvgDialog_118948_Content_11 = {
    Text = "Caecus n'en est pas conscient, il te regarde simplement avec suspicion."
  },
  AvgDialog_118948_Content_12 = {
    Text = "Ami, que dis-tu, ami ?"
  },
  AvgDialog_118948_Content_13 = {
    Text = "C'est sûrement la technique qui trouble le cœur ! N'écoute pas {Male=il,Female=elle}, Maître Caecus !"
  },
  AvgDialog_118948_Content_14 = {
    Text = "Mot de passe, oui, mot de passe…"
  },
  AvgDialog_118948_Content_15 = {
    Text = "Caecus prit une profonde inspiration, comme si le courage se réinjectait dans son corps, puis il leva brusquement la tête."
  },
  AvgDialog_118948_Content_16 = {
    Text = "Je sais seulement que le Marcheur des mers t'a temporairement installé ici, cela ne signifie pas que tu peux entrer et sortir librement des lieux clés."
  },
  AvgDialog_118948_Content_17 = {
    Text = "Conformément aux ordres de Seigneur Goliath, aucune personne non autorisée ne doit entrer dans la salle de puissance !"
  },
  AvgDialog_118948_Content_2 = {
    Text = "Regarde là-bas, il semble que quelqu'un surveille la salle de puissance."
  },
  AvgDialog_118948_Content_3 = {
    Text = "Plusieurs corps voûtés errent, parmi eux, un jeune homme au dos droit tient fermement une lance membraneuse, attentif aux mouvements des vents et de l'herbe environnants."
  },
  AvgDialog_118948_Content_4 = {
    Text = "Soyez tous prudents ! La mission importante confiée par Seigneur Goliath ne doit pas comporter d'erreurs..."
  },
  AvgDialog_118948_Content_5 = {Text = "Caecus !"},
  AvgDialog_118948_Content_6 = {
    Text = "Hein, tu es..."
  },
  AvgDialog_118948_Content_7 = {
    Text = "Vous essayez d'activer la clé d'argent, de vous connecter à sa conscience, réveillant vos souvenirs passés."
  },
  AvgDialog_118948_Content_8 = {
    Text = "Des tentacules d'illusion argentée s'étendent, grimpant le long de son corps recouvert d'écailles, pénétrant dans sa moelle épinière…"
  },
  AvgDialog_118948_Content_9 = {
    Text = "Caecus, je suis ton ami, peux-tu me laisser entrer derrière toi..."
  },
  AvgDialog_118949_Content_1 = {
    Text = "Désolé, Seigneur Goliath..."
  },
  AvgDialog_118949_Content_10 = {
    Text = "Mais maintenant, c'est un moment clé du plan, les variables devraient être le moins nombreuses possible."
  },
  AvgDialog_118949_Content_11 = {
    Text = "Ferme-la ici pour toujours, petit."
  },
  AvgDialog_118949_Content_12 = {
    Text = "Seigneur Goliath, je me bats à vos côtés !"
  },
  AvgDialog_118949_Content_13 = {
    Text = "Pas besoin, des choses fragiles comme ça, ici l'espace ne nous permet pas de nous déployer."
  },
  AvgDialog_118949_Content_14 = {
    Text = "<Small:Mais je……>"
  },
  AvgDialog_118949_Content_15 = {
    Text = "Caecus murmura doucement, mais la défaite récente au combat lui fait réaliser qu'il n'a pas la position de continuer à se plaindre, il se tait donc et recule d'un pas."
  },
  AvgDialog_118949_Content_16 = {
    Text = "Caecus le petit."
  },
  AvgDialog_118949_Content_17 = {Text = "Hmm?"},
  AvgDialog_118949_Content_18 = {
    Text = "Goliath ne se retourna pas."
  },
  AvgDialog_118949_Content_19 = {
    Text = "Ne te décourage pas, tu es la personne que j'ai choisie. Une fois que cette affaire sera réglée, je te donnerai 500 séances d'entraînement supplémentaires."
  },
  AvgDialog_118949_Content_2 = {
    Text = "Hum, évite de faire des histoires."
  },
  AvgDialog_118949_Content_20 = {
    Text = "Ah... Oui !"
  },
  AvgDialog_118949_Content_21 = {
    Text = "Faros, es-tu prêt ?"
  },
  AvgDialog_118949_Content_22 = {
    Text = "Tant que c'est pour bâtir l'escalier menant au royaume divin... Faros est toujours à l'écoute de vos ordres."
  },
  AvgDialog_118949_Content_3 = {
    Text = "Goliath sort lentement, tenant son épée à l'envers, la lame dentée traînant sur le sol en émettant un bruit strident."
  },
  AvgDialog_118949_Content_4 = {
    Text = "Avec un tel bruit, vous ne pouvez même pas gérer cela, c'est vraiment une honte pour l'ethnie philistine."
  },
  AvgDialog_118949_Content_5 = {
    Text = "Désolé, je..."
  },
  AvgDialog_118949_Content_6 = {
    Text = "Grr... Maître Goliath, ne blame pas Maître Caecus, cet inconnu peut invoquer des monstres invisibles !"
  },
  AvgDialog_118949_Content_7 = {
    Text = "Un autre... Hé, petit, c'est toi."
  },
  AvgDialog_118949_Content_8 = {
    Text = "Nekropolis, ce n'est pas l'endroit pour que tu fasses des ravages."
  },
  AvgDialog_118949_Content_9 = {
    Text = "Si nous nous rencontrons un peu plus tard, peut-être pourrions-nous prendre un moment pour discuter."
  },
  AvgDialog_118950_Content_1 = {
    Text = "Le ciel est en feu."
  },
  AvgDialog_118950_Content_10 = {
    Text = "Une traînée de sang écarlate s'étend derrière lui, se mêlant aux veines du bois du pont."
  },
  AvgDialog_118950_Content_11 = {
    Text = "<Red:Meurs, bâtard, hérétique !>"
  },
  AvgDialog_118950_Content_12 = {
    Text = "Le prêtre aux yeux exorbités leva haut la lance qui appartenait au jeune homme et la plongea avec précision et cruauté dans son dos. La pointe acérée de la lance transperça son corps, clouant le jeune homme fermement sur le pont."
  },
  AvgDialog_118950_Content_13 = {
    Text = "Le jeune homme eut un spasme, puis s'arrêta à un pas de distance de l'homme."
  },
  AvgDialog_118950_Content_14 = {
    Text = "Haha, hahaha !"
  },
  AvgDialog_118950_Content_15 = {
    Text = "Ô mon maître, grand mon maître, l'avez-vous vu ? Voici le sacrement que moi et la Mère divine vous offrons !"
  },
  AvgDialog_118950_Content_16 = {
    Text = "Miryam, le visage couvert de sang, regardait de loin cette scène infernale, riant follement en levant les yeux au ciel, sa robe déchirée flottant dans les flammes."
  },
  AvgDialog_118950_Content_17 = {
    Text = "<Shake:Que votre royaume divin remonte à nouveau des profondeurs, que votre volonté soit bientôt rétablie sur terre !>"
  },
  AvgDialog_118950_Content_18 = {
    Text = "Le regard du Grand Prêtre scrute son territoire, balayant les Faros fendus en deux par une énorme lame, croisant les deux enquêteurs gravement blessés et incapables de bouger, et se posant sur la jeune fille trempée de sang et de poison sous le voile noir."
  },
  AvgDialog_118950_Content_19 = {
    Text = "Ô Mère divine, viens, viens à mes côtés. J'ai sanctionné tous les traîtres qui ont abandonné la lumière et les déchus qui ont profané le divin !"
  },
  AvgDialog_118950_Content_2 = {
    Text = "La mer est en feu."
  },
  AvgDialog_118950_Content_20 = {
    Text = "La coque endommagée a perdu son équilibre à cause de l'infiltration d'eau, une moitié du navire est déjà immergée, mais elle ne s'en rend pas compte."
  },
  AvgDialog_118950_Content_21 = {
    Text = "<Red:<Shake:À partir de maintenant, c'est à nous deux de hériter de l'immortalité du Royaume Divin, jusqu'au prochain moment de la position correcte des étoiles, que Son saint nom soit proclamé dans l'univers !>>"
  },
  AvgDialog_118950_Content_22 = {
    Text = "Au sommet de la proue inclinée comme une guillotine, Miryam tend la main couverte de sang."
  },
  AvgDialog_118950_Content_23 = {
    Text = "<Shake:Non, ce n'est pas... ce n'est pas...>"
  },
  AvgDialog_118950_Content_24 = {
    Text = "Les jambes de Murphy fléchirent, et elle tomba à genoux. \n Son petit corps avait complètement perdu son élégance d'antan, tremblant à la lumière du feu."
  },
  AvgDialog_118950_Content_25 = {
    Text = "<Shake:Je suis désolé, je ne devrais pas... je ne devrais pas vouloir fuir...>"
  },
  AvgDialog_118950_Content_26 = {
    Text = "Des larmes roulent, laissant des traces mouillées sur le pont, qui sont ensuite léchées sèches par la chaleur des flammes."
  },
  AvgDialog_118950_Content_27 = {
    Text = "<Red:<Shake:Je aurais dû le savoir, c'est un destin que je ne peux pas éviter, ni fuir...>>"
  },
  AvgDialog_118950_Content_28 = {
    Text = "Murphy... ce n'est pas comme ça, Murphy, il y a encore une chance..."
  },
  AvgDialog_118950_Content_29 = {
    Text = "Tu es impatient de vouloir réconforter cette jeune fille, mais ton corps trahit ta volonté."
  },
  AvgDialog_118950_Content_3 = {
    Text = "Non, ce n'est pas ça... juste ton champ de vision qui brûle. \n La mort et le désespoir enveloppent cette terre sans maître au-dessus de l'immensité."
  },
  AvgDialog_118950_Content_30 = {
    Text = "Une douleur intense à la cheville déchire chaque parcelle de ta perception, la corruption subie lors du combat te cloue au sol, rendant chaque mouvement impossible."
  },
  AvgDialog_118950_Content_31 = {Text = "Désolé."},
  AvgDialog_118950_Content_32 = {
    Text = "Ignorant la plaie qui saignait sur sa poitrine, la jeune fille se leva calmement."
  },
  AvgDialog_118950_Content_33 = {
    Text = "La douleur ne peut plus l'arrêter, sans hésitation, sans illusion et sans regrets."
  },
  AvgDialog_118950_Content_34 = {
    Text = "Franchissant des montagnes de cadavres et des mers de feu. \n Elle avançait d'un pas solennel, s'approchant pas à pas du prêtre."
  },
  AvgDialog_118950_Content_35 = {
    Text = "Non... ça ne peut pas se terminer ici..."
  },
  AvgDialog_118950_Content_36 = {
    Text = "William... William, l'Aîné... ! Tu peux encore bouger ?"
  },
  AvgDialog_118950_Content_37 = {
    Text = "Que veux-tu... faire ?"
  },
  AvgDialog_118950_Content_38 = {
    Text = "William était allongé dans une mare de sang, haletant."
  },
  AvgDialog_118950_Content_39 = {
    Text = "<Red:<Big:…Tuez-moi, redémarrez le cycle.>>"
  },
  AvgDialog_118950_Content_4 = {
    Text = "Des explosions en chaîne ont déchiré la salle de puissance, le pont enflammé s'est élevé dans une distorsion."
  },
  AvgDialog_118950_Content_40 = {
    Text = "Non, pourquoi…"
  },
  AvgDialog_118950_Content_41 = {
    Text = "Je ne peux pas laisser ce monde devenir une fin... Je ne peux pas accepter une telle conclusion..."
  },
  AvgDialog_118950_Content_42 = {
    Text = "Dépêche-toi, je ne peux plus bouger..."
  },
  AvgDialog_118950_Content_43 = {
    Text = "Le bras mécanique de William s'était détaché de son corps. Il parvint à tendre l'un de ses bras encore capables de bouger et saisit la dague que Miryam avait jetée à côté."
  },
  AvgDialog_118950_Content_44 = {
    Text = "Désolé, je ne peux pas te montrer mon expression à ce moment-là…"
  },
  AvgDialog_118950_Content_45 = {
    Text = "Puis une douleur perçante est venue de mon dos gauche."
  },
  AvgDialog_118950_Content_46 = {
    Text = "N'y pense même pas !"
  },
  AvgDialog_118950_Content_47 = {
    Text = "Grand Prêtre, capturez ce type vivant, ne laissez pas {Male=il,Female=elle} mourir !"
  },
  AvgDialog_118950_Content_48 = {
    Text = "Miryam donna l'ordre, et une autre trident perça la poitrine de William. Tu te retournas, choqué, et tu ne vis qu'une chevelure dorée, tombant doucement."
  },
  AvgDialog_118950_Content_49 = {
    Text = "Le poisson-nageur prêtre fit une étrange pirouette sur place, riant aux éclats."
  },
  AvgDialog_118950_Content_5 = {
    Text = "Les compagnons avec qui tu as combattu côte à côte, les ennemis avec qui tu t'es battu désespérément, sont étendus sans distinction dans une mare de sang écarlate et bouillant."
  },
  AvgDialog_118950_Content_50 = {
    Text = "Grr, hé hé, quoi que tu veuilles faire, tu ne peux plus le faire maintenant !"
  },
  AvgDialog_118950_Content_51 = {
    Text = "Le cœur fait plus mal que les coups de couteau, les membres perdant du sang sont glacés et douloureux."
  },
  AvgDialog_118950_Content_52 = {
    Text = "<Red:Tu dois mourir>,tu dois te rendre au prochain cycle."
  },
  AvgDialog_118950_Content_53 = {
    Text = "<Red:<Shake:Je... je peux...>>"
  },
  AvgDialog_118950_Content_54 = {
    Text = "Utilisez la planche du navire pour bloquer la dague"
  },
  AvgDialog_118950_Content_55 = {
    Text = "La dague pénètre peu à peu dans ton corps, suivie d'une douleur pénétrante jusqu'à la moelle."
  },
  AvgDialog_118950_Content_56 = {
    Text = "tombé en arrière avec force"
  },
  AvgDialog_118950_Content_57 = {
    Text = "La lame aiguisée transperce ta poitrine, un sentiment de vide envahit ton champ de vision alors que ta conscience s'évanouit."
  },
  AvgDialog_118950_Content_58 = {
    Text = "<Shake:Murphy... William... s'il vous plaît, attendez-moi dans le prochain cycle.>"
  },
  AvgDialog_118950_Content_59 = {
    Text = "<Yellow:Nous allons certainement... nous échapper.>"
  },
  AvgDialog_118950_Content_6 = {
    Text = "<Shake:Seigneur Goliath, je suis désolé, si je devenais un peu plus fort...>"
  },
  AvgDialog_118950_Content_7 = {
    Text = "Le jeune homme gravement blessé traîne son corps mutilé, s'accrochant désespérément au sol rugueux avec ses dix doigts, rampent laborieusement vers l'homme endormi."
  },
  AvgDialog_118950_Content_8 = {
    Text = "<Shake:Maître Goliath…>"
  },
  AvgDialog_118950_Content_9 = {
    Text = "Peu importe combien il l'appelle, l'homme sans vie reste immobile."
  },
  AvgDialog_118951_Content_1 = {
    Text = "Alors, tu m'as amené ici, que comptes-tu faire au juste ?"
  },
  AvgDialog_118951_Content_10 = {
    Text = "Fais quelque chose qui n'a rien à voir avec la Mère divine, la doctrine ou les rituels."
  },
  AvgDialog_118951_Content_11 = {
    Text = "Je sais que, même si tu parles souvent de ces choses en ce moment, ce que tu aimes vraiment, ce n'est pas ça."
  },
  AvgDialog_118951_Content_12 = {
    Text = "Ne dis pas tant de choses, prends ça vite !"
  },
  AvgDialog_118951_Content_13 = {
    Text = "Ça... c'est ?"
  },
  AvgDialog_118951_Content_14 = {
    Text = "Bats rapidement, dans une seule direction !"
  },
  AvgDialog_118951_Content_15 = {Text = "新增"},
  AvgDialog_118951_Content_16 = {
    Text = "Ensuite, ajoutez de la farine ! De la levure chimique ! Un peu de sel !"
  },
  AvgDialog_118951_Content_17 = {
    Text = "William, l'Aîné, ne reste pas inactif non plus ? Va aider à faire fondre le beurre !"
  },
  AvgDialog_118951_Content_18 = {
    Text = "……D'accord."
  },
  AvgDialog_118951_Content_19 = {
    Text = "William s'éloigna, jouant patiemment le rôle du chef affolé mais dévoué dans la cuisine en désordre."
  },
  AvgDialog_118951_Content_2 = {
    Text = "Viens, laisse William, l'Aîné, te faire un tour de magie !"
  },
  AvgDialog_118951_Content_20 = {
    Text = "Enfin, vous avez mis la pâte mélangée au four."
  },
  AvgDialog_118951_Content_21 = {
    Text = "Murphy regardait le four, perdue dans ses pensées."
  },
  AvgDialog_118951_Content_22 = {
    Text = "Je me souviens de certaines choses d'il y a très longtemps..."
  },
  AvgDialog_118951_Content_23 = {Text = "Hmm?"},
  AvgDialog_118951_Content_24 = {
    Text = "C'était à l'époque où nous étions encore à la base antarctique. J'ai découvert un autel dans le col de montagne, avec de nombreuses petites sculptures en pierre dessus."
  },
  AvgDialog_118951_Content_25 = {
    Text = "J'ai demandé à maman... Miryam de me donner un petit couteau et quelques morceaux de bois, je veux faire des sculptures sur bois."
  },
  AvgDialog_118951_Content_26 = {
    Text = "Après longtemps, elle ne m'a donné qu'un petit couteau sans lame, disant qu'elle craignait que « le corps sacré de la Mère divine ne soit endommagé »."
  },
  AvgDialog_118951_Content_27 = {
    Text = "J'ai l'impression que mon corps ne m'appartient pas, et qu'il n'appartient pas non plus à elle. Nous semblons tous deux être comme des briques du Royaume Divin, enfermés à notre place, incapables de bouger."
  },
  AvgDialog_118951_Content_28 = {
    Text = "J'ai vu quelques sculptures en bois à côté de ton lit."
  },
  AvgDialog_118951_Content_29 = {
    Text = "Eh bien, j'ai discrètement demandé à Goliath de m'aider à trouver un morceau d'huile."
  },
  AvgDialog_118951_Content_3 = {
    Text = "Tout a été récupéré selon la liste, peux-tu confirmer ."
  },
  AvgDialog_118951_Content_30 = {
    Text = "J'ai dépensé beaucoup d'efforts pour aiguiser la lame au point de pouvoir couper du bois."
  },
  AvgDialog_118951_Content_31 = {
    Text = "J'ai sculpté pendant de nombreux jours, m'efforçant de restituer les détails que j'imagine."
  },
  AvgDialog_118951_Content_32 = {
    Text = "Lorsque j'ai enfin été satisfait, je l'ai offert à Miryam..."
  },
  AvgDialog_118951_Content_33 = {
    Text = "Sais-tu ce qu'elle a dit ?"
  },
  AvgDialog_118951_Content_34 = {
    Text = "Miryam... elle a dit que tu ne sculptais pas bien, profanation des divinités ?"
  },
  AvgDialog_118951_Content_35 = {
    Text = "Tu t'efforces de comprendre l'état d'esprit de Miryam et tu proposes prudemment une hypothèse."
  },
  AvgDialog_118951_Content_36 = {Text = "Non."},
  AvgDialog_118951_Content_37 = {
    Text = "Elle n'y a même pas jeté un coup d'œil et a simplement dit que si j'aimais une telle statue, elle pouvait ordonner aux meilleurs artisans de la sculpter pour moi chaque jour."
  },
  AvgDialog_118951_Content_38 = {
    Text = "Murphy riait de manière folle, une douleur indicible et une provocation débordant de son sourire rigide."
  },
  AvgDialog_118951_Content_39 = {
    Text = "Je suis l'enfant des dieux, et aussi leur mère, tout ce que je désire, il suffit de lever la main pour l'obtenir."
  },
  AvgDialog_118951_Content_4 = {
    Text = "William ouvrit successivement une dizaine de poches de différentes tailles sur sa poitrine, son dos et ses bras."
  },
  AvgDialog_118951_Content_40 = {
    Text = "Puisque je possède déjà tout, il va de soi qu'une petite chose comme sculpter une statue en bois n'a aucune importance."
  },
  AvgDialog_118951_Content_41 = {
    Text = "Elle riait, riait, sans s'en rendre compte, des larmes lui échappèrent. Des larmes inattendues glissèrent rapidement le long de ses joues déformées par un rire incontrôlable."
  },
  AvgDialog_118951_Content_42 = {
    Text = "J'ai vu tes œuvres exposées à côté de ton lit, tu as vraiment du talent."
  },
  AvgDialog_118951_Content_43 = {
    Text = "Bien ou mal, qu'est-ce que ça peut faire..."
  },
  AvgDialog_118951_Content_44 = {
    Text = "Murphy, à partir de maintenant, sculpte comme tu le souhaites."
  },
  AvgDialog_118951_Content_45 = {
    Text = "Ensuite, allons faire des petits gâteaux ensemble et étudier l'art floral."
  },
  AvgDialog_118951_Content_46 = {
    Text = "Je trouverai un moyen de retourner dans mon monde, je te présenterai le Murphy que je connais, vous pourrez ensemble faire tout ce que vous désirez."
  },
  AvgDialog_118951_Content_47 = {
    Text = "Murphy s'essuya le visage pour enlever les traces de larmes, puis leva la tête et t'offrit un sourire radieux que tu n'avais jamais vu auparavant."
  },
  AvgDialog_118951_Content_48 = {
    Text = "D'accord, c'est tout ce que tu m'avais promis."
  },
  AvgDialog_118951_Content_49 = {
    Text = "Absolument, il ne faut surtout pas manquer un rendez-vous."
  },
  AvgDialog_118951_Content_5 = {
    Text = "Merci au grand dieu de la magie, William, l'Aîné, pour les ingrédients volés dans la cuisine."
  },
  AvgDialog_118951_Content_50 = {
    Text = "C'est une histoire qui n'a rien à voir avec la Mère divine."
  },
  AvgDialog_118951_Content_51 = {
    Text = "Mais elle n'a jamais semblé aussi heureuse de sa vie."
  },
  AvgDialog_118951_Content_6 = {
    Text = "Il y a de la farine, des œufs, du citron, du miel, du sucre, de la levure chimique et du beurre."
  },
  AvgDialog_118951_Content_7 = {
    Text = "C'est plutôt complet ! C'est bien d'avoir beaucoup de poches sur la tenue de marin."
  },
  AvgDialog_118951_Content_8 = {
    Text = "Je ne comprends toujours pas… pourquoi ?"
  },
  AvgDialog_118951_Content_9 = {
    Text = "Tu ne veux pas essayer de faire toi-même le gâteau que tu manges d'habitude ?"
  },
  AvgDialog_118952_Content_1 = {
    Text = "Sept jours de la naissance divine"
  },
  AvgDialog_118952_Content_10 = {
    Text = "Je prie Dieu de me donner une réponse."
  },
  AvgDialog_118952_Content_11 = {
    Text = "J'ai posé des questions sur l'avenir du royaume divin, sur sa connexion avec moi, sur tout ce que je voulais savoir et sur ce que Miryam cherchait à explorer."
  },
  AvgDialog_118952_Content_12 = {
    Text = "Dieu reste silencieux."
  },
  AvgDialog_118952_Content_13 = {
    Text = "<color=#E6E6E6>Le cinquième jour de la naissance de Dieu</color>"
  },
  AvgDialog_118952_Content_14 = {
    Text = "Miryam me demande le résultat de ma rencontre avec le dieu."
  },
  AvgDialog_118952_Content_15 = {
    Text = "Dans l'urgence, j'ai inventé la réponse de Dieu : « Le royaume divin va bientôt émerger »."
  },
  AvgDialog_118952_Content_16 = {
    Text = "Elle a de nouveau posé des questions sur le temps, je n'ai eu d'autre choix que de répondre «L'heure de la position correcte des étoiles»."
  },
  AvgDialog_118952_Content_17 = {
    Text = "Miryam est folle de joie, c'est une expression de bonheur que je n'ai jamais vue auparavant, ni lorsque je lui ai offert la sculpture en bois, ni lorsque j'ai donné naissance au Fœtus Sacré."
  },
  AvgDialog_118952_Content_18 = {
    Text = "<color=#E1E1E1>Le sixième jour de la naissance de Dieu.</color>"
  },
  AvgDialog_118952_Content_19 = {
    Text = "Miryam demande où se trouve Lémuria, et je ne peux que répondre au hasard, son expression est pleine de doutes."
  },
  AvgDialog_118952_Content_2 = {
    Text = "Premier jour de la naissance des dieux"
  },
  AvgDialog_118952_Content_20 = {
    Text = "Elle a déjà vu le dieu qui n'est pas encore mort, mes mensonges ne fonctionneront peut-être pas."
  },
  AvgDialog_118952_Content_21 = {
    Text = "<Shake:Mon Dieu, s'il vous plaît, sauvez-moi, ne serait-ce qu'un mot, répondez à ma prière.>"
  },
  AvgDialog_118952_Content_22 = {
    Text = "<Red:Le septième jour de la naissance divine>"
  },
  AvgDialog_118952_Content_23 = {
    Text = "Dieu est mort. Dieu n'est jamais né."
  },
  AvgDialog_118952_Content_24 = {
    Text = "Ce qui repose sur ma poitrine n'est qu'une image hypocrite, une masse de chair morte, mal appelée <Yellow:«dieu»>."
  },
  AvgDialog_118952_Content_25 = {
    Text = "Miryam n'a aimé personne. Elle ne s'est souciée de personne."
  },
  AvgDialog_118952_Content_26 = {
    Text = "Après avoir maîtrisé le pouvoir de la Mère divine, j'ai lu tous les enregistrements des Marcheurs des mers."
  },
  AvgDialog_118952_Content_27 = {
    Text = "Tous les soixante ans, un moment de l'alignement des étoiles se produit tous les quelques milliers d'années."
  },
  AvgDialog_118952_Content_28 = {
    Text = "Le corps maternel sacrifié, je ne suis pas le premier, ni le dernier."
  },
  AvgDialog_118952_Content_29 = {
    Text = "Vouloir survivre, vouloir rester en vie..."
  },
  AvgDialog_118952_Content_3 = {
    Text = "L'embryon divin naît dans le corps consumé par les cendres."
  },
  AvgDialog_118952_Content_30 = {
    Text = "Il faut tuer celui qui..."
  },
  AvgDialog_118952_Content_31 = {
    Text = "Ce moi faible et naïf..."
  },
  AvgDialog_118952_Content_4 = {
    Text = "Je suis épuisé d'avoir mon esprit vidé, pourtant, les visages de chacun sont empreints d'une joie fervente."
  },
  AvgDialog_118952_Content_5 = {
    Text = "<color=#F7F7F7>Le lendemain de la naissance de Dieu</color>"
  },
  AvgDialog_118952_Content_6 = {
    Text = "Je baptise le Fœtus Sacré. Il dort paisiblement, les yeux fermés, dans son berceau."
  },
  AvgDialog_118952_Content_7 = {
    Text = "<color=#F2F2F2>Le troisième jour de la naissance de Dieu</color>"
  },
  AvgDialog_118952_Content_8 = {
    Text = "Le fœtus sacré n'a toujours pas ouvert les yeux. Je peux clairement sentir son battement de cœur, comme s'il pulsait devant ma poitrine."
  },
  AvgDialog_118952_Content_9 = {
    Text = "<color=#F0F0F0>Quatrième jour de la naissance de Dieu</color>"
  },
  AvgDialog_118953_Content_1 = {
    Text = "Le rideau dans le ciel se balance et se déchaîne, comme une tempête dans un petit monde."
  },
  AvgDialog_118953_Content_10 = {
    Text = "Le vent souffle et les nuages s'agitent, le ciel sombre et couvert de nuages commence à changer."
  },
  AvgDialog_118953_Content_11 = {
    Text = "le soleil... dans le ciel..."
  },
  AvgDialog_118953_Content_12 = {
    Text = "La fausse lumière se dissipe, sous le ciel lointain, un voile noir qui obscurcit le jour ondulant doucement au rythme de la respiration."
  },
  AvgDialog_118953_Content_13 = {
    Text = "C'était un soleil noir."
  },
  AvgDialog_118953_Content_2 = {
    Text = "Une brise légère qui passe soulève le voile noir qui floute son visage, et en dessous se trouvent des yeux déjà asséchés par les larmes."
  },
  AvgDialog_118953_Content_3 = {
    Text = "Il y a une faille !"
  },
  AvgDialog_118953_Content_4 = {Text = "Oh !"},
  AvgDialog_118953_Content_6 = {
    Text = "Dans un instant d'ébranlement du ciel, la grande lame dentée tranche brutalement vers la fissure ondulante."
  },
  AvgDialog_118953_Content_7 = {
    Text = "La statue en ivoire a explosé d'une violente lumière blanche, comme une résistance désespérée."
  },
  AvgDialog_118953_Content_8 = {
    Text = "Quelques secondes plus tard, la lumière blanche s'éteint brusquement, la statue en ivoire se brise et une pluie de morceaux blancs tombe dans un rayon de vingt centimètres."
  },
  AvgDialog_118953_Content_9 = {
    Text = "C'est fini..."
  },
  AvgDialog_118954_Content_1 = {
    Text = "Cycle du temps"
  },
  AvgDialog_118954_Content_10 = {Text = "Gardien..."},
  AvgDialog_118954_Content_11 = {Text = "Ramona !"},
  AvgDialog_118954_Content_12 = {
    Text = "Calmez-vous et écoutez-moi."
  },
  AvgDialog_118954_Content_13 = {
    Text = "J'ai vécu d'innombrables sauts temporels, retournant dans le cycle."
  },
  AvgDialog_118954_Content_14 = {
    Text = "Je suis donc certain que ce qui t'est arrivé n'est pas un «Cycle du temps»."
  },
  AvgDialog_118954_Content_15 = {
    Text = "Le temps que tu as vécu continue de s'écouler naturellement."
  },
  AvgDialog_118954_Content_16 = {
    Text = "Non «Cycle du temps»…"
  },
  AvgDialog_118954_Content_17 = {
    Text = "Puis les visions bizarres que je rencontre chaque fois que je me réveille, la croisière qui coule et repart à nouveau, la jeune fille morte revenant indemne..."
  },
  AvgDialog_118954_Content_18 = {
    Text = "Pourquoi donc ?"
  },
  AvgDialog_118954_Content_19 = {
    Text = "Je ne peux pas te répondre."
  },
  AvgDialog_118954_Content_2 = {
    Text = "Tu perçois que tu es en train de rêver."
  },
  AvgDialog_118954_Content_20 = {
    Text = "Et le soleil dans le ciel..."
  },
  AvgDialog_118954_Content_21 = {
    Text = "Ramona ne dit plus rien. Elle ne sait pas non plus la réponse à la question."
  },
  AvgDialog_118954_Content_22 = {
    Text = "La surface de l'eau devient progressivement agitée, son ombre commence à osciller depuis le bord, se transformant finalement en un éclat de mémoire insaisissable, se diffusant dans les reflets scintillants."
  },
  AvgDialog_118954_Content_23 = {
    Text = "Brûlant. Douleur. La langue de feu lèche chaque centimètre de ta peau."
  },
  AvgDialog_118954_Content_24 = {
    Text = "Les terminaisons nerveuses se ratatinent sous les douleurs, carbonisées par la déshydratation.\nTu deviens si léger, assez léger pour te transformer en un squelette carbonisé."
  },
  AvgDialog_118954_Content_25 = {
    Text = "Tu tousses violemment."
  },
  AvgDialog_118954_Content_26 = {
    Text = "Es-tu réveillé ?"
  },
  AvgDialog_118954_Content_27 = {
    Text = "<Shake:... encore une fois... boucle?>"
  },
  AvgDialog_118954_Content_28 = {
    Text = "Si ta santé est rétablie, je vais préparer le rituel."
  },
  AvgDialog_118954_Content_29 = {
    Text = "Ne pars pas, attends un instant, Murphy..."
  },
  AvgDialog_118954_Content_3 = {
    Text = "Les rêves sont la concrétisation des désirs et des peurs intérieurs, le domaine des rêves est une série d'îles isolées flottant dans le vide."
  },
  AvgDialog_118954_Content_30 = {
    Text = "Ils... et tout le monde ?"
  },
  AvgDialog_118954_Content_31 = {
    Text = "Murphy prit une profonde inspiration, puis la relâcha lentement."
  },
  AvgDialog_118954_Content_32 = {
    Text = "Chacun a ses propres affaires à gérer. Repose-toi bien ici."
  },
  AvgDialog_118954_Content_33 = {
    Text = "Lorsque le prochain moment de la position normale des étoiles arrivera, ce navire atteindra Lémuria, et tout ira bien."
  },
  AvgDialog_118954_Content_34 = {
    Text = "Un grincement, la porte se ferme.\nTu es laissé seul dans le salon."
  },
  AvgDialog_118954_Content_35 = {
    Text = "Tu ne peux pas rester là, tu dois agir."
  },
  AvgDialog_118954_Content_36 = {
    Text = "Après avoir traversé trois cycles, as-tu une conclusion ?"
  },
  AvgDialog_118954_Content_37 = {
    Text = "Puisque le nombre de réincarnations est déterminé, l'information est bien plus importante que l'évasion."
  },
  AvgDialog_118954_Content_38 = {
    Text = "Lors du premier cycle, j'ai d'abord compris les Marcheurs des mers ; bien que le troisième cycle se soit terminé par un échec dévastateur, j'ai acquis une compréhension de base des mouvements des autres sur le navire."
  },
  AvgDialog_118954_Content_39 = {
    Text = "Au contraire, le temps du deuxième cycle est gaspillé en vain."
  },
  AvgDialog_118954_Content_4 = {
    Text = "Dans des rêves chaotiques, des milliers de lames colorées percent ta poitrine, reflétant les ombres les unes des autres comme des bulles."
  },
  AvgDialog_118954_Content_40 = {
    Text = "L'urgence est de recueillir plus d'informations sur le Parades et les Marcheurs des mers."
  },
  AvgDialog_118954_Content_41 = {
    Text = "Bien que ce mystérieux individu ait insinué qu'il y a en tout six cycles..."
  },
  AvgDialog_118954_Content_42 = {
    Text = "Mais as-tu considéré que si c'était le dernier cycle, aurais-tu gaspillé une chance ?"
  },
  AvgDialog_118954_Content_43 = {
    Text = "Si maintenant c'est le dernier cycle..."
  },
  AvgDialog_118954_Content_44 = {
    Text = "Tu secoues la tête, chassant toutes les conjectures sinistres."
  },
  AvgDialog_118954_Content_45 = {
    Text = "Dans le rêve au début de ce cycle, Ramona : Vétuste m'a fourni une information : <Yellow: elle peut sentir que le temps sur moi continue de s'écouler en séquence>."
  },
  AvgDialog_118954_Content_46 = {
    Text = "Et tu as dit que tu avais déjà rencontré des événements de boucle…"
  },
  AvgDialog_118954_Content_47 = {Text = "!"},
  AvgDialog_118954_Content_48 = {
    Text = "Il semble que William, l'Aîné, ait aussi compris."
  },
  AvgDialog_118954_Content_49 = {
    Text = "Ce n'est pas un « Cycle du temps », mais plutôt « la répétition des mêmes événements »..."
  },
  AvgDialog_118954_Content_5 = {
    Text = "Tu as besoin d'une méthode pour mettre fin au rêve."
  },
  AvgDialog_118954_Content_50 = {
    Text = "À Mizag, je me retrouve souvent contraint de tomber dans des situations similaires."
  },
  AvgDialog_118954_Content_51 = {
    Text = "«Donjon artificiel»…"
  },
  AvgDialog_118954_Content_52 = {
    Text = "C'est exact, c'est probablement un « donjon artificiel » ici."
  },
  AvgDialog_118954_Content_53 = {
    Text = "Le donjon artificiel n'est qu'un vecteur d'information, notre véritable moi est peut-être en train d'être emporté par une tempête de vent et d'orage, tournoyant dans les airs."
  },
  AvgDialog_118954_Content_54 = {
    Text = "Comment ce donjon artificiel a-t-il été créé ? Pourquoi le labyrinthe redémarre-t-il sans cesse ? Quel est le déclencheur pour y mettre fin ?"
  },
  AvgDialog_118954_Content_55 = {
    Text = "Sans comprendre tout cela, nos tentatives dans le labyrinthe ne sont rien d'autre qu'une course en rond."
  },
  AvgDialog_118954_Content_56 = {
    Text = "Raison. Depuis trois cents ans, la raison aide Mizag à lutter contre la folie appelée Fusion."
  },
  AvgDialog_118954_Content_57 = {
    Text = "Je crois que William, l'Aîné, a également remarqué que le soleil que nous avons observé ces derniers jours n'est pas le soleil noir qui émerge de la diffusion de la brume noire, mais le véritable soleil du monde normal."
  },
  AvgDialog_118954_Content_58 = {
    Text = "La date de naissance du labyrinthe, avant l'arrivée des brumes noires dans le monde."
  },
  AvgDialog_118954_Content_59 = {Text = "新增"},
  AvgDialog_118954_Content_6 = {
    Text = "En tant que tisseur de destin, je dois garder le silence et ne peux révéler la vérité."
  },
  AvgDialog_118954_Content_60 = {
    Text = "Ai-je dit quelque chose de mal ? Pourquoi tu me regardes comme ça ?"
  },
  AvgDialog_118954_Content_61 = {
    Text = "… non, je viens juste de penser à l'époque où j'étais à Mizag, quand je sortais en mission, il y avait toujours toi et Ramona à mes côtés, libérant au maximum mon esprit."
  },
  AvgDialog_118954_Content_62 = {
    Text = "La réflexion est une partie essentielle de l'enquête."
  },
  AvgDialog_118954_Content_63 = {
    Text = "Alors, William, l'Aîné, qui penses-tu être le maître du Labyrinthe ?"
  },
  AvgDialog_118954_Content_64 = {
    Text = "D'après les principes de formation du domaine et les informations connues, j'estime que le domaine appartient à Miryam ou Faros."
  },
  AvgDialog_118954_Content_65 = {
    Text = "Le <Yellow:«noyau»> du Labyrinthe est le «Rituel d'invocation divine», suivre les traces de Lémuria devrait être l'Obsession du maître du Labyrinthe."
  },
  AvgDialog_118954_Content_66 = {
    Text = "Selon les registres d'enquête du Sonanir, l'objectif de Goliath est la force, l'obsession de Caecus est le sang, seuls Miryam et Faros aspirent à la gloire du Royaume Divin."
  },
  AvgDialog_118954_Content_67 = {
    Text = "Ensuite, verrouillez le maître du domaine, et après ?"
  },
  AvgDialog_118954_Content_68 = {
    Text = "Lorsque le maître du labyrinthe commence à ébranler la cause du labyrinthe, des fissures apparaissent, et c'est alors que le « cataclysme » se manifeste."
  },
  AvgDialog_118954_Content_69 = {
    Text = "Mais puisque c'est un donjon artificiel, la sécurité de notre corps peut être garantie."
  },
  AvgDialog_118954_Content_7 = {
    Text = "Ainsi, je t'ai extradé la personne capable de donner une Révélation."
  },
  AvgDialog_118954_Content_70 = {
    Text = "Ne sous-estimez pas la situation. Ne parlons même pas du fait que le donjon artificiel en est encore au stade de nos conjectures…"
  },
  AvgDialog_118954_Content_71 = {
    Text = "En l'an 306 de l'ère Aluviion, l'enquêteur Jude Bright s'est aventuré profondément dans le Labyrinthe, où il s'est cassé la jambe droite après avoir mis le pied dans un piège de chasseur. En revenant à la réalité, sa jambe droite a également commencé à nécroser progressivement."
  },
  AvgDialog_118954_Content_72 = {
    Text = "La manière dont le Labyrinthe influence la réalité reste incertaine, mais la prudence n'est jamais de trop."
  },
  AvgDialog_118954_Content_73 = {Text = "Compris."},
  AvgDialog_118954_Content_74 = {
    Text = "Après la fin du rituel, je vais m'occuper de Miryam, et Faros sera entre tes mains."
  },
  AvgDialog_118954_Content_75 = {
    Text = "Que la Clé d'argent éclaire mon chemin."
  },
  AvgDialog_118954_Content_76 = {
    Text = "Un ton familier te fige un instant, mais tu affiches rapidement un sourire sincère."
  },
  AvgDialog_118954_Content_77 = {
    Text = ": Que la clé d'argent nous guide"
  },
  AvgDialog_118954_Content_78 = {
    Text = "La femme intellectuelle occupe seule un coin de la cabine du capitaine, la lumière au-dessus de sa tête scintillant imperceptiblement avec sa respiration."
  },
  AvgDialog_118954_Content_79 = {Text = "Faros…"},
  AvgDialog_118954_Content_8 = {
    Text = "Dans le reflet ondulant du rêve, une silhouette se dessine, se tenant droite."
  },
  AvgDialog_118954_Content_80 = {
    Text = "Au moment où tu as ouvert la bouche, tu t'es soudainement arrêté. Tu as essayé de te souvenir des informations concernant Faros, et tu as réalisé qu'il y avait peu d'enregistrements à son sujet dans Mizag."
  },
  AvgDialog_118954_Content_81 = {
    Text = "Elle désire retourner au Royaume Divin, elle égarera les voyageurs."
  },
  AvgDialog_118954_Content_82 = {
    Text = "À part cela, les autres dossiers sont complètement vides."
  },
  AvgDialog_118954_Content_83 = {
    Text = "Qu'est-ce qui se passe ? À te voir, tu sembles perdu, non ?"
  },
  AvgDialog_118954_Content_84 = {
    Text = "Peut-être... puis-je te donner quelques conseils ?"
  },
  AvgDialog_118954_Content_85 = {
    Text = "Je crains que..."
  },
  AvgDialog_118954_Content_86 = {
    Text = "Je sais qui est le maître du domaine."
  },
  AvgDialog_118954_Content_9 = {
    Text = "L'ombre vacille, se brise et se regroupe, stabilisant progressivement le visage froid et familier de ta mémoire."
  },
  AvgDialog_118955_Content_1 = {Text = "L'outsider"},
  AvgDialog_118955_Content_10 = {Text = "William..."},
  AvgDialog_118955_Content_11 = {
    Text = "Mais tu ne devrais pas rester ici, les innombrables jours et nuits qu'il a passés ici ne pourront prendre fin que si tu trouves le maître du rêve."
  },
  AvgDialog_118955_Content_12 = {
    Text = "Au bout du bateau, tu as vu une jeune fille."
  },
  AvgDialog_118955_Content_13 = {
    Text = "D'innombrables Marcheurs des mers en robes noires gisent éparpillés autour d'elle, tandis qu'elle est tranquillement adossée à l'autel, tenant dans ses mains un morceau de chair en décomposition puant de L'Écarlate."
  },
  AvgDialog_118955_Content_14 = {Text = "Murphy..."},
  AvgDialog_118955_Content_15 = {
    Text = "Comme tu l'avais promis, tu es venu."
  },
  AvgDialog_118955_Content_16 = {
    Text = "Le maître du domaine des rêves, c'est toi."
  },
  AvgDialog_118955_Content_17 = {
    Text = "Oui, tout sur ce bateau n'est qu'un rêve. Y compris tout ce que tu vois maintenant, ce n'est que la « réalité dans le rêve »."
  },
  AvgDialog_118955_Content_18 = {Text = "Pourquoi ?"},
  AvgDialog_118955_Content_19 = {
    Text = "Pourquoi fabriquer un tel domaine de rêve ? Ou pourquoi suis-je devenu ce que je suis maintenant ?"
  },
  AvgDialog_118955_Content_2 = {
    Text = "Ahem, ahem, hé…"
  },
  AvgDialog_118955_Content_20 = {
    Text = "C'était un jour très lointain."
  },
  AvgDialog_118955_Content_21 = {
    Text = "Une petite silhouette avance dans la neige."
  },
  AvgDialog_118955_Content_22 = {
    Text = "Huff... Huff..."
  },
  AvgDialog_118955_Content_23 = {
    Text = "Depuis son arrivée en Antarctique, Murphy a acquis une liberté absurde."
  },
  AvgDialog_118955_Content_24 = {
    Text = "Elle peut aller seule n'importe où. Mais peu importe où elle va, elle ne voit qu'un champ de neige pâle."
  },
  AvgDialog_118955_Content_25 = {
    Text = "Ne parlons même pas des humains, il n'y a même pas de trace de leur existence passée."
  },
  AvgDialog_118955_Content_26 = {
    Text = "Est-ce que je suis... perdu ?"
  },
  AvgDialog_118955_Content_27 = {
    Text = "La fille se retourne pour regarder les empreintes de ses pas. Dans le vaste champ de neige, une ligne presque droite de pas mène vers un endroit inconnu."
  },
  AvgDialog_118955_Content_28 = {
    Text = "Peu importe, tant que nous continuons d'avancer, nous finirons par arriver quelque part."
  },
  AvgDialog_118955_Content_29 = {
    Text = "La fille a compté ses provisions, s'assurant qu'elle pourrait atteindre la distance la plus éloignée en se serrant la ceinture pendant un certain temps."
  },
  AvgDialog_118955_Content_3 = {
    Text = "Tu tousses fortement, essayant de chasser l'eau de mer qui s'est infiltrée dans tes poumons."
  },
  AvgDialog_118955_Content_30 = {
    Text = "Allez, Murphy. C'est un voyage vers la liberté, avoir un peu faim n'est pas si grave."
  },
  AvgDialog_118955_Content_31 = {Text = "新增"},
  AvgDialog_118955_Content_32 = {Text = "新增"},
  AvgDialog_118955_Content_33 = {
    Text = "Non, dans une tempête de neige comme celle-ci, il est impossible de distinguer le chemin."
  },
  AvgDialog_118955_Content_34 = {
    Text = "Le pain sec avec de l'eau de neige, c'est vraiment très mauvais."
  },
  AvgDialog_118955_Content_35 = {
    Text = "Parfois, elle réside dans une grotte de neige, capable d'entendre les hurlements des bêtes. Elle ne l'avait jamais vu, sachant seulement que c'était une sorte de loup blanc."
  },
  AvgDialog_118955_Content_36 = {
    Text = "Au secours !"
  },
  AvgDialog_118955_Content_37 = {
    Text = "Murphy s'enfuit sans réfléchir, sortant de la grotte. Cette paire d'yeux verts brillants resta dans la grotte, ne poursuivant pas ses pas."
  },
  AvgDialog_118955_Content_38 = {
    Text = "Dans une telle impasse, j'ai vu une ligne de traces de pas."
  },
  AvgDialog_118955_Content_39 = {
    Text = "Ce sont des empreintes humaines... !"
  },
  AvgDialog_118955_Content_4 = {
    Text = "Mais rien ne sort, il ne reste que des nerfs spasmodiques et une douleur fantôme de noyade dans les poumons."
  },
  AvgDialog_118955_Content_40 = {
    Text = "Tant que quelqu'un est là, il y a de l'espoir. Je l'ai suivi sans hésiter."
  },
  AvgDialog_118955_Content_41 = {Text = "新增"},
  AvgDialog_118955_Content_42 = {
    Text = "Peu après, les empreintes se sont transformées en deux rangées."
  },
  AvgDialog_118955_Content_43 = {
    Text = "Trois lignes."
  },
  AvgDialog_118955_Content_44 = {
    Text = "Les empreintes se multiplient, mais le propriétaire des empreintes reste introuvable."
  },
  AvgDialog_118955_Content_45 = {
    Text = "Moi, trop fatigué, je suis enfin tombé dans l'inconscience."
  },
  AvgDialog_118955_Content_46 = {
    Text = "Plus tard, j'ai appris qu'en raison de la différence de longueur entre le pied gauche et le pied droit, chacun dévie légèrement vers une direction en marchant sans pouvoir déterminer son chemin."
  },
  AvgDialog_118955_Content_47 = {
    Text = "En d'autres termes... à ce moment-là, ma trajectoire de marche était un anneau."
  },
  AvgDialog_118955_Content_48 = {
    Text = "Les traces que j'appelle espoir viennent de mon moi passé, menant à une boucle sans fin."
  },
  AvgDialog_118955_Content_49 = {
    Text = "À cause d'une petite déviation, presque insignifiante...\n ma vie a toujours été enchaînée par un cercle vicieux."
  },
  AvgDialog_118955_Content_5 = {
    Text = "Pourquoi... cela ne devrait-il pas être le dernier cycle ?"
  },
  AvgDialog_118955_Content_50 = {
    Text = "Le centre de ce cercle s'appelle le destin."
  },
  AvgDialog_118955_Content_51 = {
    Text = "C'est la boucle que j'ai construite, qui me piège moi-même."
  },
  AvgDialog_118955_Content_52 = {
    Text = "En d'autres termes ?"
  },
  AvgDialog_118955_Content_53 = {
    Text = "Depuis le premier soulèvement de Goliath, le temps s'est arrêté."
  },
  AvgDialog_118955_Content_54 = {
    Text = "Tout le monde s'est enfoncé dans des rêves, entamant un rêve cyclique. \n Le cycle des rêves commence avec la naissance du fœtus sacré et se termine par le naufrage du paquebot."
  },
  AvgDialog_118955_Content_55 = {
    Text = "Tant que Goliath n'a pas encore déclenché la rébellion, tout peut rester en paix comme auparavant."
  },
  AvgDialog_118955_Content_56 = {
    Text = "Mais je l'ai déjà vu, Goliath, dans la Nekropolis..."
  },
  AvgDialog_118955_Content_57 = {
    Text = "Pour maintenir le royaume des rêves, je vais envoyer un groupe de personnes de temps en temps pour recueillir de l'énergie pour la statue en ivoire."
  },
  AvgDialog_118955_Content_58 = {
    Text = "Tant que vous retournerez dans le domaine des rêves, ils oublieront cette expérience et deviendront les habitants du domaine des rêves."
  },
  AvgDialog_118955_Content_59 = {
    Text = "C'est dommage que depuis que tu as empêché notre absorption d'énergie de Nekropolis, le Domaine des Rêves soit devenu de plus en plus instable."
  },
  AvgDialog_118955_Content_6 = {
    Text = "Tu regardes autour de toi, le pont vaste est désert, sans araignées violettes ni fidèles des mers autour de toi."
  },
  AvgDialog_118955_Content_60 = {
    Text = "Pourquoi veux-tu que je te voie ?"
  },
  AvgDialog_118955_Content_61 = {
    Text = "Je t'ai initialement invoqué dans l'espoir d'éliminer tous les facteurs d'instabilité, de t'étrangler dans ce domaine de rêve..."
  },
  AvgDialog_118955_Content_62 = {
    Text = "Juste avant cela, mon cœur d'argent semblait résonner avec ta clé d'argent, j'ai connecté ton rêve, ta note."
  },
  AvgDialog_118955_Content_63 = {
    Text = "J'ai vu une autre possibilité dans le rêve… un autre moi-même."
  },
  AvgDialog_118955_Content_64 = {
    Text = "Je l'ai vue en train de concourir avec ses camarades pendant le cours de sculpture ;"
  },
  AvgDialog_118955_Content_65 = {
    Text = "Je l'ai vue se battre avec des chats errants sous la fontaine ;"
  },
  AvgDialog_118955_Content_66 = {
    Text = "Je l'ai vue être cajolée par ses amis pour porter une petite jupe de diable, portant une lanterne en citrouille, allant de porte en porte distribuant des bonbons..."
  },
  AvgDialog_118955_Content_67 = {
    Text = "Dans un monde où le Saint Fœtus n'est pas encore né, elle est vraiment... trop heureuse."
  },
  AvgDialog_118955_Content_68 = {
    Text = "Enviable, jalousant."
  },
  AvgDialog_118955_Content_69 = {
    Text = "Cela donne également envie de devenir."
  },
  AvgDialog_118955_Content_7 = {
    Text = "Tu fuis partout, à la recherche."
  },
  AvgDialog_118955_Content_70 = {
    Text = "<Jaune:%player%>, jusqu'à ce que je te rencontre, je ne savais pas qu'il existait encore un mode de vie si simple et joyeux dans ce monde..."
  },
  AvgDialog_118955_Content_71 = {
    Text = "Je n'ai pas besoin de la couronne vaniteuse de la Mère divine, ni de l'honneur admiré par la foule, ni de faire face jour après jour aux visages ennuyeux des fidèles..."
  },
  AvgDialog_118955_Content_72 = {
    Text = "Quelle responsabilité, quel héritage, pourquoi tant de gens donnent-ils leur vie pour une flaque de chair pourrie ?"
  },
  AvgDialog_118955_Content_73 = {
    Text = "Tu restes silencieux, tu ne peux que te taire."
  },
  AvgDialog_118955_Content_74 = {
    Text = "Murphy nie son passé."
  },
  AvgDialog_118955_Content_75 = {
    Text = "J'ai une dernière question à te poser."
  },
  AvgDialog_118955_Content_76 = {
    Text = "Dans ton monde, tu l'emmènes aussi faire des petits gâteaux comme ça ?"
  },
  AvgDialog_118955_Content_77 = {
    Text = "Dans ce monde… ce ne sera pas seulement moi, mais beaucoup de gens seront prêts à t'aider et à te tenir compagnie pour faire tout ce que tu veux, même les choses capricieuses."
  },
  AvgDialog_118955_Content_78 = {
    Text = "Murphy, parce que tu aimes le monde, tu aimes tout le monde."
  },
  AvgDialog_118955_Content_79 = {
    Text = "À cause de toi, j'ai ouvert mon cœur, tout le monde en a été témoin."
  },
  AvgDialog_118955_Content_8 = {
    Text = "Sommeil, sommeil, tout le monde dort."
  },
  AvgDialog_118955_Content_80 = {
    Text = "Ce cœur palpitant."
  },
  AvgDialog_118955_Content_81 = {
    Text = "Murphy sourit, un sourire aussi éclatant que tes souvenirs d'autrefois."
  },
  AvgDialog_118955_Content_82 = {
    Text = "Tu sais ? Ce bateau est un rêve."
  },
  AvgDialog_118955_Content_83 = {
    Text = "Je pensais que c'était un beau rêve…\nJe suis la sublime Mère des Dieux, et cette masse de chair qui se tord est le soi-disant dieu."
  },
  AvgDialog_118955_Content_84 = {
    Text = "Nuit et jour, je vis dans la peur, angoissé et tourmenté."
  },
  AvgDialog_118955_Content_85 = {
    Text = "En réalité, ce rêve n'est pas un doux rêve, mais un cauchemar dont je n'étais même pas conscient, profondément enliséré dans la panique."
  },
  AvgDialog_118955_Content_86 = {
    Text = "Alors, maintenant, lève le rideau sur le mensonge et réveille le rêve."
  },
  AvgDialog_118955_Content_9 = {
    Text = "William est allongé sur le pont, son uniforme est en désordre, comme s'il avait été malmené par des tempêtes et un soleil ardent, des taches d'huile et de sel formant une carte éraflée."
  },
  AvgDialog_118956_Content_1 = {
    Text = "Vous combattez tout en reculent, de la salle de puissance au couloir, du couloir au pont, jusqu'à ce qu'il ne vous sépare de l'immensité de l'océan qu'une barrière."
  },
  AvgDialog_118956_Content_10 = {
    Text = "Le géant à la force incroyable recule rapidement sous ton impact, prêt à s'écraser violemment contre le panneau de la cabine."
  },
  AvgDialog_118956_Content_11 = {
    Text = "Dans un éclair, il enfonça la grande lame droit dans le sol, réussissant à peine à stabiliser sa posture."
  },
  AvgDialog_118956_Content_12 = {
    Text = "Qu'as-tu rencontré, petit malin ? Tu as encore progressé depuis notre dernière rencontre."
  },
  AvgDialog_118956_Content_13 = {
    Text = "Non, ce n'est pas ça."
  },
  AvgDialog_118956_Content_14 = {
    Text = "Ce n'est pas que tu sois devenu plus fort, c'est Goliath qui est devenu plus faible."
  },
  AvgDialog_118956_Content_15 = {
    Text = "Même avec Faros à ses côtés, la force de Goliath est bien inférieure à celle de votre dernière rencontre."
  },
  AvgDialog_118956_Content_16 = {
    Text = "Chaque coup de lame est léger comme une plume, complètement différent de la main d'un géant doté d'une force monstrueuse."
  },
  AvgDialog_118956_Content_17 = {
    Text = "Goliath, dès le début du combat, j'ai réalisé que la force surhumaine en toi... s'affaiblit rapidement."
  },
  AvgDialog_118956_Content_18 = {
    Text = "Hum, même si je devenais dix fois plus faible, je ne serais pas un adversaire que ce petit gars pourrait égaler."
  },
  AvgDialog_118956_Content_19 = {
    Text = "Est-ce en rapport avec l'apparition de Faros ici ?"
  },
  AvgDialog_118956_Content_2 = {
    Text = "Tu as vraiment tenu bon... Tu as réussi à te battre jusqu'ici."
  },
  AvgDialog_118956_Content_20 = {
    Text = "Est-ce que cela a un rapport avec le phénomène sur ce bateau ?"
  },
  AvgDialog_118956_Content_21 = {
    Text = "C'est parce que ta propre force s'est affaiblie que tu es pressé d'exécuter ce qu'on appelle un arrangement ?"
  },
  AvgDialog_118956_Content_22 = {
    Text = "Hum, des choses que tu ne devrais pas savoir, peu importe comment tu questionnes, ne pense pas obtenir un mot de ma part."
  },
  AvgDialog_118956_Content_23 = {
    Text = "Si nos objectifs sont les mêmes, je ne suis pas nécessairement l'option que tu dois exclure."
  },
  AvgDialog_118956_Content_24 = {
    Text = "Faisons chacun un pas en arrière, je n'interférerai pas avec tes intentions de trahison envers le Marcheur des mers, et ne me mets pas dans l'embarras."
  },
  AvgDialog_118956_Content_25 = {
    Text = "Goliath n'a pas encore répondu, alors que deux ombres serpentine se précipitent vers vous comme des éclairs !"
  },
  AvgDialog_118956_Content_27 = {
    Text = "Vous reculez soudainement, l'ombre du serpent éclate sur le pont, créant instantanément deux grands trous effrayants qui fument."
  },
  AvgDialog_118956_Content_28 = {
    Text = "Deux traîtres sans aucune gratitude, il n'y a pas de place ici pour votre accord."
  },
  AvgDialog_118956_Content_29 = {
    Text = "Quant aux étrangers... Il semble que tu aies oublié quelque chose de crucial en fuyant."
  },
  AvgDialog_118956_Content_3 = {
    Text = "Cependant, vous n'avez plus d'issue."
  },
  AvgDialog_118956_Content_30 = {
    Text = "La statue en ivoire flotte dans la main de Miryam.\nElle prie avec dévouement, des paroles de profanation s'échappent de sa bouche comme des asticots."
  },
  AvgDialog_118956_Content_31 = {
    Text = "<Change>Vos corps et vos âmes auraient dû appartenir aux ombres des abysses depuis longtemps."
  },
  AvgDialog_118956_Content_32 = {
    Text = "Attendez une seconde, Miryam, ne—"
  },
  AvgDialog_118956_Content_33 = {
    Text = "Désolé, Mère divine, je dois châtier ces profanateurs à votre place."
  },
  AvgDialog_118956_Content_34 = {
    Text = "La statue en ivoire émet un cri silencieux, des filaments argentés se propagent alors, parasitant le cœur des citoyens de la mer comme des créatures étranges."
  },
  AvgDialog_118956_Content_35 = {
    Text = "C'est... femme folle, que fais-tu ?!"
  },
  AvgDialog_118956_Content_36 = {
    Text = "Que suis-je en train de faire ? Naturellement, je vous accorde la miséricorde divine, la compassion divine et la suprême puissance divine."
  },
  AvgDialog_118956_Content_37 = {
    Text = "Les fils s'entrelacent fermement et se resserrent brusquement——"
  },
  AvgDialog_118956_Content_38 = {
    Text = "Seigneur Goliath... j'ai l'impression que je ne peux plus respirer..."
  },
  AvgDialog_118956_Content_39 = {
    Text = "<Shake:Ah ah... je ressens... les veines du divin... j'ai touché... son âme...>"
  },
  AvgDialog_118956_Content_4 = {
    Text = "Tu prends une profonde inspiration, te calmes et te prépares à affronter à nouveau la grande lame de Goliath."
  },
  AvgDialog_118956_Content_40 = {Text = "Paf."},
  AvgDialog_118956_Content_41 = {
    Text = "Le cœur explose à répétition, et la souillure écarlate éclate en fleurs de sang sur le pont."
  },
  AvgDialog_118956_Content_42 = {
    Text = "Peu importe le temps qui passe, il est impossible de changer la stupidité des incroyants."
  },
  AvgDialog_118956_Content_43 = {
    Text = "<Shake:Alors, avec votre sang et votre esprit, forgez l'escalier vers le Royaume Divin !>"
  },
  AvgDialog_118956_Content_44 = {
    Text = "<Shake:Arrêtez-la... <Big:Avec moi, arrêtez-la !>>"
  },
  AvgDialog_118956_Content_6 = {
    Text = "Le chemin sans retour dans tes yeux est en réalité le champ de bataille que j'ai choisi pour toi."
  },
  AvgDialog_118956_Content_7 = {
    Text = "Tu as toujours gaspillé ta force, et maintenant, c'est le moment de ma contre-attaque."
  },
  AvgDialog_118956_Content_8 = {
    Text = "Un éclat argenté jaillit soudainement, chargé d'une force dévastatrice, s'abattant sur Goliath. \n Goliath lève immédiatement son épée pour résister, mais il est déjà trop tard."
  },
  AvgDialog_118957_Content_1 = {Text = "Épilogue"},
  AvgDialog_118957_Content_10 = {
    Text = "C'était vraiment un rêve très long."
  },
  AvgDialog_118957_Content_11 = {
    Text = "Mort, trahison, naufrage, plus tu essaies de retenir quelque chose, plus cela s'échappe inévitablement entre tes doigts."
  },
  AvgDialog_118957_Content_12 = {
    Text = "Peut-être que c'est le destin. Irréversible, il n'est pas nécessaire de le retenir."
  },
  AvgDialog_118957_Content_13 = {
    Text = "Lâchez prise tôt, et vous pourriez rencontrer des compagnons plus compatibles."
  },
  AvgDialog_118957_Content_14 = {
    Text = "Par exemple... Mizag ?"
  },
  AvgDialog_118957_Content_15 = {
    Text = "Les gens de Mizag semblent très doués pour la tolérance... ou pour aplanir le mauvais caractère de tout le monde."
  },
  AvgDialog_118957_Content_16 = {
    Text = "Je me souviens qu'une année, Murphy a insisté pour essayer toutes les saveurs de bonbons, et en conséquence, il a fini avec un mal de dents."
  },
  AvgDialog_118957_Content_17 = {
    Text = "Sylvia a finalement fait voler tout le stock de la dame par Jenkin."
  },
  AvgDialog_118957_Content_18 = {
    Text = "Plouf. Ensuite ?"
  },
  AvgDialog_118957_Content_19 = {
    Text = "Puis elle a commencé à organiser une grande opération pour attraper les voleurs, oubliant complètement les bonbons."
  },
  AvgDialog_118957_Content_2 = {
    Text = "Le Parades est accosté, maintenant…"
  },
  AvgDialog_118957_Content_20 = {
    Text = "Encore une fois…"
  },
  AvgDialog_118957_Content_21 = {
    Text = "Bien, combien veux-tu que je sois jaloux d'elle ?"
  },
  AvgDialog_118957_Content_22 = {
    Text = "Lorsque nous reviendrons à Mizag, tout cela t'appartiendra aussi."
  },
  AvgDialog_118957_Content_23 = {
    Text = "Souhaitons-nous un jour nous retrouver à Mizag."
  },
  AvgDialog_118957_Content_24 = {
    Text = "Murphy ouvrit les mains vers le ciel lointain, comme si elle voulait toucher le soleil dans les hauteurs."
  },
  AvgDialog_118957_Content_25 = {
    Text = "Une ombre noire et ronde roule entre ses doigts."
  },
  AvgDialog_118957_Content_26 = {
    Text = "Il y a encore une chose que je dois te dire."
  },
  AvgDialog_118957_Content_27 = {
    Text = "Le regard de Murphy te perça droit au cœur."
  },
  AvgDialog_118957_Content_28 = {
    Text = "Ce monde est déjà détruit, irrécupérable, recouvert d'un désespoir plus profond que celui des boucles que j'ai vécues."
  },
  AvgDialog_118957_Content_29 = {
    Text = "Si possible, je peux essayer de te ramener."
  },
  AvgDialog_118957_Content_3 = {
    Text = "Ils savent déjà tout sur les dieux de ce monde, et ils feront bientôt leurs propres choix."
  },
  AvgDialog_118957_Content_30 = {
    Text = "Emmène-moi... retourner ?"
  },
  AvgDialog_118957_Content_31 = {
    Text = "Tu sais comment traverser deux mondes ?"
  },
  AvgDialog_118957_Content_32 = {
    Text = "On ne peut pas dire qu'on sait, mais tant que l'on connaît l'essence de ce monde, on peut naturellement comprendre les nœuds de connexion du monde."
  },
  AvgDialog_118957_Content_33 = {
    Text = "Ce navire est un rêve, mais lorsque le voile du mensonge se lève..."
  },
  AvgDialog_118957_Content_34 = {
    Text = "Le monde entier est aussi le rêve de quelqu'un, c'est juste que ce rêve est plus grand, plus illusoire et plus lointain..."
  },
  AvgDialog_118957_Content_35 = {
    Text = "Même le soleil, la lune et les étoiles sont nés de sa fiction ; seuls les êtres enchevêtrés avec son esprit peuvent…"
  },
  AvgDialog_118957_Content_36 = {
    Text = "Soleil, lune, étoiles..."
  },
  AvgDialog_118957_Content_37 = {
    Text = "Le voile noir tremble, s'étendant en un chemin sinueux vers le ciel."
  },
  AvgDialog_118957_Content_38 = {
    Text = "Va, retourne dans le monde qui t'appartient ! Il n'est pas nécessaire d'être nostalgique pour ce monde qui est déjà mort."
  },
  AvgDialog_118957_Content_39 = {
    Text = "Et toi, Murphy ?"
  },
  AvgDialog_118957_Content_4 = {
    Text = "À mon avis, Miryam et Faros devraient reprendre la mer pour explorer le sort de Lémuria."
  },
  AvgDialog_118957_Content_40 = {
    Text = "Tu réprimes l'envie de poser le pied sur le chemin de soie et te retournes pour interroger la silencieuse Murphy."
  },
  AvgDialog_118957_Content_41 = {
    Text = "Qui sait ? Ce monde est un monde déjà détruit."
  },
  AvgDialog_118957_Content_42 = {
    Text = "Prends-le. Peut-être qu'un jour, tu pourras ressentir mon Cœur d'argent dans ce monde."
  },
  AvgDialog_118957_Content_43 = {
    Text = "Une gemme formée d'une goutte de sang tombe dans ta paume, provenant de cette étrange blessure qui transperce sa poitrine."
  },
  AvgDialog_118957_Content_44 = {
    Text = "Celui que tu as invoqué à cette époque, je ne sais pas de quelle période c'est « Je »."
  },
  AvgDialog_118957_Content_45 = {
    Text = "Mais lorsque tu m'appelles, souviens-toi de mon apparence actuelle..."
  },
  AvgDialog_118957_Content_46 = {
    Text = "Sa naissance n'est qu'illusion... façonner des rêves illusoires n'est qu'illusion..."
  },
  AvgDialog_118957_Content_47 = {
    Text = "Appelle-moi… «<Yellow:Délire : Murphy>» !"
  },
  AvgDialog_118957_Content_48 = {
    Text = "Tu progresses lentement le long du chemin de soie, des pensées innombrables traversent ton esprit."
  },
  AvgDialog_118957_Content_49 = {
    Text = "Le voyage contre la corrosion, deux mondes enchevêtrés par des cauchemars noirs, de nombreux visages similaires ou identiques se superposent..."
  },
  AvgDialog_118957_Content_5 = {
    Text = "Goliath et Caecus partiront probablement, même dans un monde devenu aussi désolé, ils auront leur propre voyage."
  },
  AvgDialog_118957_Content_50 = {
    Text = "deux poupées…"
  },
  AvgDialog_118957_Content_51 = {
    Text = "Deux Clémentines…"
  },
  AvgDialog_118957_Content_52 = {
    Text = "deux Murphy..."
  },
  AvgDialog_118957_Content_53 = {
    Text = "Se fige finalement sur le visage souriant de Ramona."
  },
  AvgDialog_118957_Content_54 = {
    Text = "Je... peux rentrer ?"
  },
  AvgDialog_118957_Content_55 = {
    Text = "Dans un rêve, tu te découvres déjà à une distance d'un bras du soleil noir, sans ressentir aucune chaleur."
  },
  AvgDialog_118957_Content_56 = {
    Text = "Cette obscurité infinie engloutit toute la lumière, attendant de te dévorer complètement."
  },
  AvgDialog_118957_Content_57 = {
    Text = "Ramona... Tu vas m'attendre juste après ça ?"
  },
  AvgDialog_118957_Content_58 = {
    Text = "Tu fermes les yeux, tends doucement le bout des doigts et touches le passage noir."
  },
  AvgDialog_118957_Content_59 = {
    Text = "Si possible, tiens ma main."
  },
  AvgDialog_118957_Content_6 = {
    Text = "Quant à «ce» Murphy…"
  },
  AvgDialog_118957_Content_60 = {
    Text = "Sous tes pieds, au sein de milliers de rêves profonds."
  },
  AvgDialog_118957_Content_61 = {
    Text = "À partir du soleil noir, le voile noir se dissipe progressivement, couche par couche."
  },
  AvgDialog_118957_Content_62 = {
    Text = "Tu tombes du haut du ciel."
  },
  AvgDialog_118957_Content_63 = {
    Text = "<Yellow:Tomber dans le vortex appelé «Destin».>"
  },
  AvgDialog_118957_Content_64 = {
    Text = "J'ai entrevu le destin de cette fille dans un Rêve Profond."
  },
  AvgDialog_118957_Content_65 = {
    Text = "Il est regrettable que je l'aie d'abord envoyée loin de Lémuria, que j'aie confié la statue en ivoire à elle dans un rêve, ce n'était pas pour une telle fin."
  },
  AvgDialog_118957_Content_66 = {
    Text = "Ne devrais-tu pas me remercier pour mon intervention ?"
  },
  AvgDialog_118957_Content_67 = {
    Text = "La lumière de l'espoir de ce monde a déjà été annihilée, tu devrais le savoir, n'est-ce pas ?"
  },
  AvgDialog_118957_Content_68 = {
    Text = "La femme caressant le rouet ne dit rien, laissant simplement le fil qu'elle tient s'étendre sous le ciel, parmi toutes choses."
  },
  AvgDialog_118957_Content_69 = {
    Text = "Tant qu'il reste une graine."
  },
  AvgDialog_118957_Content_7 = {
    Text = "Je pense qu'elle a quelque chose à te dire."
  },
  AvgDialog_118957_Content_70 = {
    Text = "Peu importe le temps de silence, peu importe le sol, un jour, il germera."
  },
  AvgDialog_118957_Content_71 = {
    Text = "Quant à moi…"
  },
  AvgDialog_118957_Content_72 = {
    Text = "La femme baisse les yeux."
  },
  AvgDialog_118957_Content_73 = {
    Text = "Je ne suis pas semeur, je ne suis pas éleveur, et je ne suis pas récolteur."
  },
  AvgDialog_118957_Content_74 = {
    Text = "Je ne fais que tirer les fils, suivant le principe céleste, dessinant le Tisseur de destin."
  },
  AvgDialog_118957_Content_75 = {
    Text = "Je tirerai les fils du fuseau pour en tirer le sol le plus approprié."
  },
  AvgDialog_118957_Content_76 = {
    Text = "Je patienterai silencieusement."
  },
  AvgDialog_118957_Content_8 = {
    Text = "Tu es là ?"
  },
  AvgDialog_118957_Content_9 = {Text = "Bien."},
  AvgDialog_118958_Content_1 = {Text = "noyau"},
  AvgDialog_118958_Content_10 = {
    Text = "Je me suis un jour allié à Goliath, mais le barbare qui ne connaît que la guerre et la violence ne comprend évidemment pas comment respecter un contrat, ni comment mener vers Lémuria."
  },
  AvgDialog_118958_Content_11 = {
    Text = "Comment ? Tant que tu hoches la tête, je te révélerai l'identité du maître du labyrinthe."
  },
  AvgDialog_118958_Content_12 = {
    Text = "Le cœur de la jeune fille était monté dans sa gorge."
  },
  AvgDialog_118958_Content_13 = {Text = "Je refuse."},
  AvgDialog_118958_Content_14 = {
    Text = "Je ne peux pas accepter à la hâte de prendre la vie de quelqu'un sans savoir qui est l'autre."
  },
  AvgDialog_118958_Content_15 = {
    Text = "De plus, puisque tu as déjà formulé une telle demande, il est évident que le maître du Labyrinthe n'est pas entre toi, Goliath et Caecus."
  },
  AvgDialog_118958_Content_16 = {
    Text = "Et tu as déjà révélé que le pouvoir du rêve est lié à cette statue en ivoire."
  },
  AvgDialog_118958_Content_17 = {
    Text = "Alors le seul suspect qui reste, c'est elle..."
  },
  AvgDialog_118958_Content_18 = {
    Text = "Le choix de votre place pour admirer la vue est vraiment digne d'éloges."
  },
  AvgDialog_118958_Content_19 = {
    Text = "Tu tends la corde, laissant la voile du mât cacher ta silhouette et celle de William."
  },
  AvgDialog_118958_Content_2 = {
    Text = "<Shake:Tac, tac, tac, tac, tac.>"
  },
  AvgDialog_118958_Content_20 = {
    Text = "La dernière fois que j'ai remarqué lors de la cérémonie, par rapport au Sona-Nyl, le Parades a conservé une structure de mât relativement ancienne."
  },
  AvgDialog_118958_Content_21 = {
    Text = "C'est équivalent à une tour d'observation, permettant de surplomber la situation sur le site de la cérémonie de pilotage."
  },
  AvgDialog_118958_Content_22 = {
    Text = "Au début de la cérémonie de pilotage, Miryam remettra la statue en ivoire à Murphy, c'est aussi la seule occasion où nous pourrons toucher la statue en ivoire."
  },
  AvgDialog_118958_Content_23 = {
    Text = "Prenez la statue et parsez-la, peut-être que nous pourrons maîtriser la méthode pour lever le labyrinthe."
  },
  AvgDialog_118958_Content_24 = {
    Text = "Chut, elles arrivent."
  },
  AvgDialog_118958_Content_25 = {
    Text = "William te tapota l'épaule, t'indiquant de te retourner."
  },
  AvgDialog_118958_Content_26 = {
    Text = "Faites attention à l'emplacement de la statue en ivoire… c'est notre ligne de vie."
  },
  AvgDialog_118958_Content_27 = {
    Text = "Il n'y a aucune différence avec votre mémoire, la cérémonie de navigation se déroule de manière ordonnée."
  },
  AvgDialog_118958_Content_28 = {
    Text = "Chère Mère divine, veuillez guider la lignée du Roi Dieu, conduire le Marcheur des mers égaré et nous montrer la direction de Lémuria."
  },
  AvgDialog_118958_Content_29 = {
    Text = "Murphy mordit ses lèvres et prit la dague lumineuse des mains de Miryam."
  },
  AvgDialog_118958_Content_3 = {
    Text = "La jeune fille court dans le couloir."
  },
  AvgDialog_118958_Content_30 = {
    Text = "Elle leva le couteau bien haut—— puis elle ne l'enfonça pas pendant longtemps."
  },
  AvgDialog_118958_Content_31 = {
    Text = "Grande Mère divine, n'avez-vous pas déjà pris votre décision depuis longtemps ? Lémuria repose encore au fond de l'abîme, attendant votre arrivée."
  },
  AvgDialog_118958_Content_32 = {
    Text = "… Je vais…"
  },
  AvgDialog_118958_Content_33 = {
    Text = "La fin de la phrase fut avalée."
  },
  AvgDialog_118958_Content_34 = {
    Text = "Elle prit la statue en ivoire imbibée de sang, laissant ce monstre déformé lui extirper sa spiritualité."
  },
  AvgDialog_118958_Content_35 = {
    Text = "Le fleuve de sang s'étend le long du bastingage, allant vers la gauche."
  },
  AvgDialog_118958_Content_36 = {
    Text = "À tribord ! Timonier du Marin, écoute l'oracle, tourne à gauche à fond !"
  },
  AvgDialog_118958_Content_37 = {
    Text = "Ce qui lui répondit fut un sifflement perçant."
  },
  AvgDialog_118958_Content_38 = {
    Text = "Je pense que ce n'est pas nécessaire."
  },
  AvgDialog_118958_Content_39 = {
    Text = "Le harpon aiguisé jaillit de la nuit noire tel les dents acérées d'un requin géant, perçant précisément la gorge du barreur."
  },
  AvgDialog_118958_Content_4 = {
    Text = "En passant devant la cabine du capitaine, une voix calme lui parvint à l'oreille."
  },
  AvgDialog_118958_Content_40 = {
    Text = "La grande lame lourde crée des étincelles sur le pont, le géant émerge des ténèbres de la nuit, écrasant le crâne du timonier, affichant un sourire cruel à la sorcière devant lui."
  },
  AvgDialog_118958_Content_41 = {
    Text = "Derrière lui, des barbares vêtus de capes en toile bleu-gris tiennent des lames, attendant avec soif l'ordre de tuer."
  },
  AvgDialog_118958_Content_42 = {
    Text = "Goliath... tu ne veux toujours pas lâcher prise ?"
  },
  AvgDialog_118958_Content_43 = {
    Text = "Rassemblez les matelots, semez le chaos... tentant de briser la tranquillité du paradis..."
  },
  AvgDialog_118958_Content_44 = {
    Text = "Je suis désolé, je ne fais pas partie de cette tranquillité. Cette fois, la prochaine fois, la fois suivante... les Philistins ne se contenteront jamais de rester éternellement en dessous des autres."
  },
  AvgDialog_118958_Content_45 = {
    Text = "Viens, Philistin !"
  },
  AvgDialog_118958_Content_46 = {
    Text = "Dans la voix maléfique, les barbares vêtus de capes en toile cirée brandissent des lames, apparaissant en masse des ombres."
  },
  AvgDialog_118958_Content_47 = {
    Text = "Un rugissement profond tremble d'excitation. Ils attendent avec soif, attendant le moment de retrouver leur gloire, attendant l'ordre de massacrer tout."
  },
  AvgDialog_118958_Content_48 = {
    Text = "<Big:Tuez-les !>"
  },
  AvgDialog_118958_Content_49 = {
    Text = "Le chant de guerre rude déchire le ciel nocturne de la mer, et les tribus sauvages lancent les cordes, s'écrasant dans la foule sur le pont à une vitesse inattendue."
  },
  AvgDialog_118958_Content_5 = {
    Text = "Je sais qui est le maître du labyrinthe, et je peux vous aider à franchir les limites du labyrinthe et à revenir dans le monde réel."
  },
  AvgDialog_118958_Content_50 = {
    Text = "Les Philistins, vivant de raids côtiers depuis longtemps, se ruent vers leur proie comme des requins attirés par l'odeur du sang, affamés et brutaux, mordant dans les corps de leurs ennemis avec leurs lames courbes semblables à des dents."
  },
  AvgDialog_118958_Content_51 = {
    Text = "Mon Seigneur, écoute l'appel de tes fidèles... accorde tes bénédictions à tes enfants..."
  },
  AvgDialog_118958_Content_52 = {
    Text = "Miryam ouvre les bras, une lumière noire s'étend progressivement."
  },
  AvgDialog_118958_Content_53 = {
    Text = "Les Marcheurs des mers vêtus de robes noires étranges ne faisaient aucun bruit, tels un groupe de fantômes noirs dévoués, se baignant silencieusement dans la profonde grâce divine, plongeant silencieusement des dagues dans la poitrine de leurs ennemis."
  },
  AvgDialog_118958_Content_54 = {
    Text = "Le bleu-gris et le noir-violet, deux groupes aux distinctions nettes, s'affrontent dans ce purgatoire en mouvement."
  },
  AvgDialog_118958_Content_55 = {
    Text = "Tuez, mes membres de la famille... ici même, reproduisez la gloire des Philistins !"
  },
  AvgDialog_118958_Content_56 = {
    Text = "La grande lame tranche sans obstacle le crâne du croyant Marcheur des mers qui se tenait devant, le sang salé et frais jaillissant teignant la majeure partie du visage de Goliath en L'Écarlate."
  },
  AvgDialog_118958_Content_57 = {
    Text = "Il lèche le sang sur son visage, brandissant la grande lame qu'il tient à la main sous l'éclat des éclairs, abattant chaque croyant qui se dresse devant lui."
  },
  AvgDialog_118958_Content_58 = {
    Text = "Le sang vient de jaillir de ce corps chaud, immédiatement dilué par la pluie battante, se mélangeant à l'eau de mer, formant sur le pont secoué des ruisseaux écarlates et glissants."
  },
  AvgDialog_118958_Content_59 = {
    Text = "<Shake:Mon Seigneur, j'ai entendu votre oracle. Votre croyant, retournera avec vous dans le royaume divin…>"
  },
  AvgDialog_118958_Content_6 = {
    Text = "La jeune fille feignit de rester calme et ralentit ses pas."
  },
  AvgDialog_118958_Content_60 = {
    Text = "Rituel, tempête, combat…"
  },
  AvgDialog_118958_Content_61 = {
    Text = "Au centre de ce chaos, sous la sinistre statue en ivoire à la proue du navire, Miryam se tient debout, chuchotant avec dévouement dans la tempête."
  },
  AvgDialog_118958_Content_62 = {
    Text = "Elle ignore la mer de sang et les montagnes de cadavres qui l'entourent, la dague passe près de son oreille, les vagues la trempent entièrement, mais elle ne s'en rend pas compte."
  },
  AvgDialog_118958_Content_63 = {
    Text = "Que votre oracle nous guide, que votre corps nous enveloppe."
  },
  AvgDialog_118958_Content_64 = {
    Text = "Miryam... Lâche prise ! Nous ne pouvons pas atteindre Lémuria !"
  },
  AvgDialog_118958_Content_65 = {
    Text = "Non... Il m'a promis, vous avez aussi entendu Son Orácle, n'est-ce pas ?"
  },
  AvgDialog_118958_Content_66 = {
    Text = "Miryam regarde pieusement l'horizon."
  },
  AvgDialog_118958_Content_67 = {
    Text = "La tempête est votre souffle, le tonnerre est votre tambour de guerre !"
  },
  AvgDialog_118958_Content_68 = {
    Text = "Veuillez guider cette brebis égarée, <Big:montrez-lui le chemin vers votre royaume !>"
  },
  AvgDialog_118958_Content_69 = {
    Text = "Un éclair blafard déchire le ciel, illuminant instantanément ses yeux fervents et dévoués."
  },
  AvgDialog_118958_Content_7 = {
    Text = "Cependant, mon aide est conditionnelle."
  },
  AvgDialog_118958_Content_70 = {
    Text = "La jeune fille en gaze noire se recroqueville silencieusement dans un coin de la proue, son regard vide fixant désespérément le champ de bataille du massacre, comme une poupée de chiffon jetée dans une décharge."
  },
  AvgDialog_118958_Content_71 = {
    Text = "Allons, descendons !"
  },
  AvgDialog_118958_Content_72 = {
    Text = "Je suis responsable de prendre la statue en ivoire !"
  },
  AvgDialog_118958_Content_73 = {
    Text = "Je vais en profiter pendant qu'ils sont dans le chaos pour sauver Murphy !"
  },
  AvgDialog_118958_Content_8 = {
    Text = "Tes conditions sont... ?"
  },
  AvgDialog_118958_Content_9 = {
    Text = "Tuez le maître du Labyrinthe, prenez la Statue en ivoire et remettez-moi le pouvoir du Labyrinthe."
  },
  AvgDialog_118959_Content_1 = {
    Text = "J'ai tué mon moi, j'ai pris la couronne. À part la liberté, j'ai obtenu tout ce que je désirais."
  },
  AvgDialog_118959_Content_10 = {
    Text = "Parce que tu es différent."
  },
  AvgDialog_118959_Content_11 = {
    Text = "Qu'est-ce qui me différencie d'elles ? Ce ne sont que des offrandes à tes yeux, ce ne sont que de la nourriture pour cette viande avariée."
  },
  AvgDialog_118959_Content_12 = {
    Text = "Murphy tenait dans ses mains un morceau sale, le sang frais s'écoulant en gouttes."
  },
  AvgDialog_118959_Content_13 = {
    Text = "Non, tu es différent d'elles."
  },
  AvgDialog_118959_Content_14 = {
    Text = "Parce que..."
  },
  AvgDialog_118959_Content_15 = {
    Text = "Nous avons marché ensemble, tout au long du chemin."
  },
  AvgDialog_118959_Content_16 = {
    Text = "Je me souviens du jour où tu as implanté le fœtus sacré dans ta poitrine ; tu as dit que tu voulais manger des churros."
  },
  AvgDialog_118959_Content_17 = {
    Text = "Tu réalises soudain que c'est tellement bon qu'il n'est pas approprié de le déguster seul, alors tu me donnes timidement la moitié."
  },
  AvgDialog_118959_Content_18 = {
    Text = "Plus tard, le fœtus sacré a commencé à grandir, et tu as eu une forte fièvre que nous n'avons pas pu abaisser peu importe nos tentatives. En fin de compte, nous avons dû te transporter dans une cave à glace en Antarctique."
  },
  AvgDialog_118959_Content_19 = {
    Text = "Cela nous a vraiment causé pas mal de tracas."
  },
  AvgDialog_118959_Content_2 = {
    Text = "Mais moi qui ai donné naissance à l'Enfant Saint, je n'ai pas reçu la faveur de l'oracle, je n'ai pas pu indiquer le chemin vers Lémuria..."
  },
  AvgDialog_118959_Content_20 = {
    Text = "Même dans un environnement aussi difficile, tu continues à remplir tes devoirs en tant que Mère divine."
  },
  AvgDialog_118959_Content_21 = {
    Text = "La plupart des prêtres endurent le froid, accompagnant, attendant et priant dans l'autel de l'Antarctique."
  },
  AvgDialog_118959_Content_22 = {
    Text = "Et tu as également répondu aux attentes en devenant le premier réceptacle à donner naissance à l'Enfant Saint."
  },
  AvgDialog_118959_Content_23 = {
    Text = "Nous sommes arrivés ensemble à ce moment-là."
  },
  AvgDialog_118959_Content_24 = {
    Text = "Nous naviguerons ensemble vers le royaume divin éternel."
  },
  AvgDialog_118959_Content_25 = {
    Text = "Miryam s'approche lentement et avec détermination de Murphy, puis se penche."
  },
  AvgDialog_118959_Content_26 = {
    Text = "Tu es la vénérable Mère divine, je suis prêt à me prosterner à tes pieds pour l'éternité, et à t'offrir ma dévotion tout au long de ma vie."
  },
  AvgDialog_118959_Content_27 = {
    Text = "Je suis prêt à te regarder éternellement avec l'attitude réservée à cette « divinité »."
  },
  AvgDialog_118959_Content_28 = {
    Text = "Murphy regarde fixement Miryam."
  },
  AvgDialog_118959_Content_29 = {
    Text = "Miryam est à genoux, prenant le dos de sa main et y déposant un baiser de dévouement."
  },
  AvgDialog_118959_Content_3 = {
    Text = "Alors tu as fabriqué ce rêve sans fin..."
  },
  AvgDialog_118959_Content_30 = {
    Text = "Reviens à mes côtés, d'accord, « Mère divine » ?"
  },
  AvgDialog_118959_Content_31 = {
    Text = "Murphy baissa la tête. Le vent s'était calmé, et le petit univers était silencieux dans l'espace vide."
  },
  AvgDialog_118959_Content_32 = {
    Text = "Toutes tes histoires parlent du Fœtus Sacré. Tous tes titres sont liés à la Mère divine."
  },
  AvgDialog_118959_Content_33 = {
    Text = "Tu ne comprends toujours pas... et tu ne comprendras jamais..."
  },
  AvgDialog_118959_Content_34 = {
    Text = "Entre les dents, quelques murmures s'échappent."
  },
  AvgDialog_118959_Content_35 = {
    Text = "Seulement en sachant prier, des rituels, le royaume divin, Lémuria, la naissance des dieux..."
  },
  AvgDialog_118959_Content_36 = {
    Text = "Je ne comprendrai jamais."
  },
  AvgDialog_118959_Content_37 = {
    Text = "Tout ce que j'ai fait, ce point d'arrivée que j'ai atteint en serrant les dents, cette illusion que je maintiens de toutes mes forces..."
  },
  AvgDialog_118959_Content_38 = {
    Text = "Je veux juste t'appeler d'une manière où tu me traiterais sincèrement..."
  },
  AvgDialog_118959_Content_39 = {Text = "Mère..."},
  AvgDialog_118959_Content_4 = {
    Text = "Si je ne le fais pas, elle va sûrement me retirer le cœur de ses propres mains..."
  },
  AvgDialog_118959_Content_40 = {
    Text = "La tempête sur la mer couvre le murmure déjà flou."
  },
  AvgDialog_118959_Content_41 = {
    Text = "Quel dommage, quel dommage."
  },
  AvgDialog_118959_Content_42 = {
    Text = "Murphy essuya ses larmes."
  },
  AvgDialog_118959_Content_43 = {
    Text = "Toutes mes attentes envers toi ne sont que du délire, et l'équilibre maintenu par des mensonges n'est qu'une illusion éternelle."
  },
  AvgDialog_118959_Content_44 = {
    Text = "Tu ne seras jamais ma mère."
  },
  AvgDialog_118959_Content_45 = {
    Text = "La Murphy que vous connaissez est déjà morte. Sa mort est survenue avec la naissance de Dieu."
  },
  AvgDialog_118959_Content_46 = {
    Text = "Ici se tient un Éveilleur, né des cendres de la vie et de l'esprit en argent..."
  },
  AvgDialog_118959_Content_47 = {
    Text = "Celui qui m'a réveillé des décombres... Non, peut-on l'appeler humain ?"
  },
  AvgDialog_118959_Content_48 = {
    Text = "Mon lien est juste devant vous."
  },
  AvgDialog_118959_Content_49 = {
    Text = "Elle souleva doucement le berceau, et sur son visage, tu captas une douceur étrange et presque horrifique que tu n'avais jamais vue auparavant."
  },
  AvgDialog_118959_Content_5 = {
    Text = "Offrez-moi en sacrifice au roi qu'elle honore."
  },
  AvgDialog_118959_Content_50 = {
    Text = "Je l'ai amené dans ce monde... il m'a de nouveau amené dans ce monde..."
  },
  AvgDialog_118959_Content_51 = {
    Text = "Le destin dévié s'entrelace sans fin, la boucle inversée ne se termine jamais."
  },
  AvgDialog_118959_Content_52 = {
    Text = "Un père donne naissance à des enfants, la fille porte le père, le père réveille à nouveau la fille…"
  },
  AvgDialog_118959_Content_53 = {
    Text = "Personne ne vient rompre ce lien pesant, personne ne vient entraver le désordre de cette éternelle connexion de sang."
  },
  AvgDialog_118959_Content_54 = {
    Text = "Penses-tu que tu es le premier à être tombé dans la boucle ?"
  },
  AvgDialog_118959_Content_55 = {
    Text = "Avant cela, j'avais déjà franchi des milliers de boucles, chaque fin de boucle étant un cauchemar indicible."
  },
  AvgDialog_118959_Content_56 = {
    Text = "Parce qu'elle a refusé Lémuria, le résultat d'être percée dans la poitrine par Miryam."
  },
  AvgDialog_118959_Content_57 = {
    Text = "Emprisonné par Goliath avec des chaînes, dépouillé de la statue en ivoire, rencontrant le destin du naufrage de tout le navire."
  },
  AvgDialog_118959_Content_58 = {
    Text = "Et dans le rêve, une silhouette maigre mais puissante ouvre un chemin d'évasion pour moi."
  },
  AvgDialog_118959_Content_59 = {
    Text = "J'ai toujours cru qu'aucun de ceux-ci ne pouvait être la vraie fin.\nJ'attends la fin qui appartient uniquement à « ce moi »."
  },
  AvgDialog_118959_Content_6 = {
    Text = "Alors tu dis qu'elle m'attend toujours... Je ne comprends pas."
  },
  AvgDialog_118959_Content_60 = {
    Text = "La véritable fin peut enfin arriver."
  },
  AvgDialog_118959_Content_61 = {
    Text = "Faites chavirer ce bateau."
  },
  AvgDialog_118959_Content_62 = {
    Text = "Le rideau noir, tel un satin déversé du ciel, obscurcit le corps du navire du monde extérieur alors que le soleil noir sans lumière descend."
  },
  AvgDialog_118959_Content_63 = {
    Text = "L'immensité de l'eau de mer a submergé le Nautilus, l'enterrant dans l'obscurité insondable des abysses."
  },
  AvgDialog_118959_Content_64 = {
    Text = "Encore une fois, tu es plongé dans l'obscurité infinie."
  },
  AvgDialog_118959_Content_7 = {
    Text = "<Shake:Pourquoi ? Miryam, pourquoi ?>"
  },
  AvgDialog_118959_Content_8 = {
    Text = "Si je ne suis pas une Mère divine qualifiée, alors il te suffit de m'abandonner comme d'habitude, non ?"
  },
  AvgDialog_118959_Content_9 = {
    Text = "<Red:Abandonne-moi... donne-moi la liberté...>"
  },
  AvgDialog_118960_Content_1 = {
    Text = "Voile éternel"
  },
  AvgDialog_118960_Content_10 = {
    Text = "Non, j'ai toujours pu manipuler tout dans mes rêves, je peux décider de la fin et du début de la boucle, je…"
  },
  AvgDialog_118960_Content_11 = {
    Text = "Le dieu vous a accordé le pouvoir de rêver, mais vous êtes piégé dans votre propre obsession, gaspillant Sa bonne volonté."
  },
  AvgDialog_118960_Content_12 = {
    Text = "Emprunter... ?"
  },
  AvgDialog_118960_Content_13 = {
    Text = "Te souviens-tu d'où vient cette statue ?"
  },
  AvgDialog_118960_Content_14 = {
    Text = "Statue... Son image..."
  },
  AvgDialog_118960_Content_15 = {
    Text = "Donner naissance... au saint enfant..."
  },
  AvgDialog_118960_Content_16 = {
    Text = "Non, je n'ai jamais vu cette statue pendant les sept jours qui ont suivi la première naissance de l'Enfant Saint."
  },
  AvgDialog_118960_Content_17 = {
    Text = "Son image... est..."
  },
  AvgDialog_118960_Content_18 = {
    Text = "Pas étonnant que je sente toujours qu'il manque une pièce au puzzle de la réponse complète."
  },
  AvgDialog_118960_Content_19 = {
    Text = [[
%player%, vous vous souvenez de notre raisonnement ?
Le temps de naissance du labyrinthe, avant que la fusion n'engloutisse le monde et que le soleil ne se transforme en jour noir.]]
  },
  AvgDialog_118960_Content_2 = {
    Text = "<Red:Ne devrait pas se terminer>"
  },
  AvgDialog_118960_Content_20 = {
    Text = "Cependant, le rituel de naissance de l'Enfant Saint, le sacrifice et la résurrection de Murphy se déroulent clairement après la naissance du Soleil déchu."
  },
  AvgDialog_118960_Content_21 = {
    Text = "En d'autres termes, à ce moment-là, Murphy n'était qu'un humain plein d'esprit, insuffisant pour construire ce rêve."
  },
  AvgDialog_118960_Content_22 = {
    Text = "Celui qui avait le pouvoir avant cela… devrait être…"
  },
  AvgDialog_118960_Content_23 = {
    Text = "Le roi divin de ce monde est déjà né... Non, on pourrait dire qu'il n'est jamais mort."
  },
  AvgDialog_118960_Content_24 = {
    Text = "Tu ne peux pas réveiller sa conscience, car sa conscience est encore plongée dans un sommeil profond."
  },
  AvgDialog_118960_Content_25 = {
    Text = "Il ne peut pas supporter de te voir mourir à cause du sacrifice, il a donc séparé un fil de sa force pour te créer un rêve dans le rêve."
  },
  AvgDialog_118960_Content_26 = {
    Text = "C'est dommage que tu désires tant de choses... Ainsi, les rêves se brisent et redémarrent sans cesse ; c'est l'essence du Paradis."
  },
  AvgDialog_118960_Content_27 = {
    Text = "Il est né de ton souhait, mais ce n'est pas ton esclave…"
  },
  AvgDialog_118960_Content_28 = {
    Text = "<Yellow:Alors, maintenant, Il va exécuter la mission que le Créateur lui a assignée.>"
  },
  AvgDialog_118960_Content_29 = {
    Text = "Le ciel commence à tourbillonner, un voile noir obscurcit le champ de vision, un énorme corps s'élève comme une montagne."
  },
  AvgDialog_118960_Content_3 = {Text = "?!"},
  AvgDialog_118960_Content_30 = {
    Text = "Ce n'est pas de l'Abîme qu'il est sorti, mais plutôt la «volonté» elle-même qui a brisé la coquille des dimensions."
  },
  AvgDialog_118960_Content_31 = {
    Text = "Sous le dôme étouffant, Ses membres se révèlent silencieusement : pâles, fins, articulations tordues, comme les squelettes de saints torturés jusqu'à la déformation."
  },
  AvgDialog_118960_Content_32 = {
    Text = "<Big:<Shake:......!!!>>"
  },
  AvgDialog_118960_Content_33 = {Text = "Murphy..."},
  AvgDialog_118960_Content_34 = {
    Text = "La silhouette massive est clairement celle de la jeune fille que tu connais si bien."
  },
  AvgDialog_118960_Content_35 = {
    Text = "<Red:Rêve... doit... se poursuivre...>"
  },
  AvgDialog_118960_Content_4 = {
    Text = "<Red:Ne pas finir>"
  },
  AvgDialog_118960_Content_5 = {
    Text = "Le ciel commence à se recoudre, un voile noir obscurcit le jour, se rassemblant pour former un ciel illusoire."
  },
  AvgDialog_118960_Content_6 = {
    Text = "cric crac, tu entends le son du rouet qui recommence à tourner."
  },
  AvgDialog_118960_Content_7 = {
    Text = "Pourquoi ? Pourquoi ? J'avais pourtant décidé de mettre fin à ce rêve..."
  },
  AvgDialog_118960_Content_8 = {
    Text = "Parce que... ô respectueuse Mère divine, le maître de ce rêve n'est pas vous."
  },
  AvgDialog_118960_Content_9 = {Text = "??!!"},
  AvgDialog_118961_Content_1 = {Text = "Délire"},
  AvgDialog_118961_Content_10 = {
    Text = "Es-tu surpris ? Le seul chemin de fuite sur ce bateau est entre mes mains."
  },
  AvgDialog_118961_Content_11 = {
    Text = "Goliath saisit Murphy d'une main, la grande lame pressée contre sa gorge.\nLe sang coule de son cou, se mêlant à la cicatrice sur sa poitrine qui ne guérira jamais."
  },
  AvgDialog_118961_Content_12 = {Text = "Murphy !"},
  AvgDialog_118961_Content_13 = {
    Text = "Mère divine !"
  },
  AvgDialog_118961_Content_14 = {
    Text = "Désolé, je ne peux toujours pas me sentir à l'aise..."
  },
  AvgDialog_118961_Content_15 = {
    Text = "Ce n'est pas que Miryam ne veuille pas lâcher cette petite fille, mais c'est cette petite fille qui contraint Miryam."
  },
  AvgDialog_118961_Content_16 = {
    Text = "C'est elle qui ne veut pas, n'ose pas laisser Miryam découvrir la vérité."
  },
  AvgDialog_118961_Content_17 = {
    Text = "Quelle est la vérité que tu dis ?"
  },
  AvgDialog_118961_Content_18 = {
    Text = "Elle ne savait pas non plus où se trouvait cette Lémuria, elle n'avait jamais vu la véritable forme d'un dieu."
  },
  AvgDialog_118961_Content_19 = {
    Text = "Parce qu'elle ne sait pas, ce bateau ne peut que dériver sur la mer, continuant à dériver ainsi."
  },
  AvgDialog_118961_Content_2 = {
    Text = "Alors, au moment où le dieu est déjà né, pourquoi tiens-tu fermement Murphy dans ta main ?"
  },
  AvgDialog_118961_Content_20 = {
    Text = "Je ne sais pas avec quels mots cette petite fille vous a charmés, vous deux..."
  },
  AvgDialog_118961_Content_21 = {
    Text = "Un Grand Prêtre des Marcheurs des mers, un mystérieux être tombé du ciel, est tourné en dérision par une petite fille."
  },
  AvgDialog_118961_Content_22 = {
    Text = "As-tu déjà oublié quand elle s'est échappée ?"
  },
  AvgDialog_118961_Content_23 = {Text = "Courir."},
  AvgDialog_118961_Content_24 = {
    Text = "La jeune fille court."
  },
  AvgDialog_118961_Content_25 = {
    Text = "Elle ne sait pas où finit le voyage, ni si elle pourra échapper à l'œil de la marraine."
  },
  AvgDialog_118961_Content_26 = {
    Text = "<Shake:Ha, ha...>"
  },
  AvgDialog_118961_Content_27 = {
    Text = "Personne ne l'attendait devant elle, tandis que le bruit étrange et un peu comique des palmes frappant le sol derrière elle devenait de plus en plus intense."
  },
  AvgDialog_118961_Content_28 = {
    Text = "La nouvelle de la disparition de la Sainte s'est répandue, les Marcheurs des mers se rassemblent."
  },
  AvgDialog_118961_Content_29 = {
    Text = "Merde, ces types ennuyeux."
  },
  AvgDialog_118961_Content_3 = {
    Text = "Ta voix d'interrogation résonne avec force."
  },
  AvgDialog_118961_Content_30 = {
    Text = "Derrière l'éclat, la silhouette en robe violette, symbole de son échec, apparaît lentement..."
  },
  AvgDialog_118961_Content_31 = {Text = "新增"},
  AvgDialog_118961_Content_32 = {
    Text = "Murphy de ce monde n'a pas pu s'échapper."
  },
  AvgDialog_118961_Content_33 = {
    Text = "Parce que c'est celui qui l'a envoyée chez les Marcheurs des mers, puis qui a réalisé son erreur et l'a renvoyée..."
  },
  AvgDialog_118961_Content_34 = {
    Text = "a disparu à jamais dans la catastrophe de fusion de la grande détonation."
  },
  AvgDialog_118961_Content_35 = {
    Text = "Cette petite fille n'est pas devenue Mère divine de son plein gré, tout comme je ne suis pas devenu ton esclave de mon plein gré."
  },
  AvgDialog_118961_Content_36 = {
    Text = "Nous sommes tous là pour... ce que nous voulons."
  },
  AvgDialog_118961_Content_37 = {
    Text = "<Shake:Non, je n'ai rien de ce que je veux.>Je... je ne veux rien."
  },
  AvgDialog_118961_Content_38 = {
    Text = "Tu ne veux rien ? Non, tu veux beaucoup de choses."
  },
  AvgDialog_118961_Content_39 = {
    Text = "Tu veux profiter de la vie confortable de la Mère divine, tout en évitant les obligations d'un guide."
  },
  AvgDialog_118961_Content_4 = {
    Text = "Tenue dans la main, tu veux dire... ?"
  },
  AvgDialog_118961_Content_40 = {
    Text = "Tu as peur d'être abandonné, alors tu traites les autres comme des marionnettes dans ta vie, des jouets pour tes jeux de société."
  },
  AvgDialog_118961_Content_41 = {
    Text = "À intervalles réguliers, tu effaces la mémoire de tous les membres du navire, puis tu déclenches un nouveau cycle."
  },
  AvgDialog_118961_Content_42 = {
    Text = "Petite fille, laisse-moi te dire : ne fais pas le malin, tout ce que tu obtiens dans ce monde a un prix."
  },
  AvgDialog_118961_Content_43 = {
    Text = "Pensais-tu que personne ne découvrirait jamais ton petit tour ? Croiais-tu qu'avec cette statue en ivoire, tu pourrais accomplir quoi que ce soit ?"
  },
  AvgDialog_118961_Content_44 = {
    Text = "Murphy serra la statue en ivoire dans sa main."
  },
  AvgDialog_118961_Content_45 = {
    Text = "Ne sois pas idiot, enfant stupide."
  },
  AvgDialog_118961_Content_46 = {
    Text = "Tu penses que je ne sais rien de tes actions ? Je ne suis simplement pas encore prêt à m'opposer à toi de front."
  },
  AvgDialog_118961_Content_47 = {
    Text = "À chaque réincarnation, j'essaie de changer la méthode de raub du navire. Te menacer, menacer Miryam, faire sauter la salle de puissance..."
  },
  AvgDialog_118961_Content_48 = {
    Text = "Plus tard, j'ai découvert que tant que cette maudite statue en ivoire était là, je n'avais aucune marge de manœuvre pour te résister."
  },
  AvgDialog_118961_Content_49 = {
    Text = "Le ricanement de Goliath résonne sur le pont."
  },
  AvgDialog_118961_Content_5 = {
    Text = "C'est toi qui as construit ce rêve, en enfermant Murphy dans une boucle de rêves, n'est-ce pas ?"
  },
  AvgDialog_118961_Content_50 = {
    Text = "Jusqu'à quelques mois auparavant, l'action de la Nekropolis qui a été sabotée par cette petite chose devant moi."
  },
  AvgDialog_118961_Content_51 = {
    Text = "N'ayant pas réussi à capturer suffisamment de cœurs d'argent, le pouvoir divin de la statue en ivoire s'est épuisé, et les souvenirs de l'éveilleur sur le navire se sont depuis longtemps assouplis."
  },
  AvgDialog_118961_Content_52 = {
    Text = "Tu te souviens de tout... Ils se souviennent de tout ?..."
  },
  AvgDialog_118961_Content_53 = {
    Text = "Alors, William ne se souvient de rien parce qu'il vient d'un autre monde."
  },
  AvgDialog_118961_Content_54 = {
    Text = "D'autres êtres spirituels ne sont pas différents de moi... ils connaissent l'inversion du ciel et de la terre, et le flux du temps."
  },
  AvgDialog_118961_Content_55 = {
    Text = "<Small:<Shake:Tout le monde que tu as dit... y compris... elle ?>>"
  },
  AvgDialog_118961_Content_56 = {
    Text = "Murphy baissa la tête, sa voix était si légère qu'elle semblait presque s'évanouir. Son regard était instable, flottant souvent vers la femme à ses côtés, mais avant même de toucher son regard, il se retirait immédiatement."
  },
  AvgDialog_118961_Content_57 = {
    Text = "Petite fille stupide à ce point, je parle de tous les éveillés."
  },
  AvgDialog_118961_Content_58 = {
    Text = "Cela inclut naturellement cette stupide femme qu'est Miryam."
  },
  AvgDialog_118961_Content_59 = {
    Text = "Tu veux dire..."
  },
  AvgDialog_118961_Content_6 = {
    Text = "Miryam hésite à prendre la parole, un rire profond résonne derrière toi."
  },
  AvgDialog_118961_Content_60 = {
    Text = "Miryam se souvient de ce qui se passe à chaque cycle, elle t'attend encore et encore."
  },
  AvgDialog_118961_Content_61 = {
    Text = "Je peux connecter aux rêves de ce gars-là, j'ai témoigné de la fin de ce monde. Je parie que Miryam peut aussi le faire."
  },
  AvgDialog_118961_Content_62 = {
    Text = "Mais dans tous les cycles que je connais, elle n'a fait aucune tentative, elle attendait simplement passivement."
  },
  AvgDialog_118961_Content_63 = {
    Text = "Goliath leva le menton et désigna Miryam, qui était silencieuse à ses côtés."
  },
  AvgDialog_118961_Content_64 = {
    Text = "Tu pensais qu'elle était heureuse d'être piégée dans cette citadelle que tu avais construite de tes propres mains."
  },
  AvgDialog_118961_Content_65 = {
    Text = "Miryam répond en silence aux conjectures de Goliath."
  },
  AvgDialog_118961_Content_66 = {
    Text = "<Shake:Pourquoi ? Je ne comprends pas pourquoi ?>"
  },
  AvgDialog_118961_Content_67 = {
    Text = "Pour toi, je ne devrais pas être un produit défectueux, un outil obsolète ?"
  },
  AvgDialog_118961_Content_68 = {
    Text = "Tu n'es pas censé m'abandonner comme tu les as abandonnées ?"
  },
  AvgDialog_118961_Content_7 = {
    Text = "Laisse-moi te dire."
  },
  AvgDialog_118961_Content_8 = {
    Text = "<Shake:Parce que cette petite fille appelée Murphy est une menteuse.>"
  },
  AvgDialog_118961_Content_9 = {
    Text = "Mené par un Philistin, la foule ouvre une petite brèche, à travers laquelle un matelot pousse le malheureux Murphy dehors."
  },
  AvgDialog_118962_Content_1 = {
    Text = "Tu fermes la porte de la cabine de pilotage, engages le verrous, et écoutes le bruit des pas de la poursuite se diriger dans une autre direction, puis tu te retournes pour observer ton petit otage."
  },
  AvgDialog_118962_Content_10 = {
    Text = "Si ils n'ont pas rempli leurs devoirs... où seraient-ils ?"
  },
  AvgDialog_118962_Content_11 = {
    Text = "Selon le tempérament de Goliath, il ne devrait pas aller paresser dans un casino souterrain."
  },
  AvgDialog_118962_Content_12 = {
    Text = "Il doit comploter quelque chose en secret..."
  },
  AvgDialog_118962_Content_13 = {
    Text = "William est en poste dans la chambre de Murphy."
  },
  AvgDialog_118962_Content_14 = {
    Text = "Même si je suis seul, je peux au moins les retenir pendant vingt minutes... C'est suffisant..."
  },
  AvgDialog_118962_Content_15 = {
    Text = "Les pas deviennent soudainement plus sporadiques."
  },
  AvgDialog_118962_Content_16 = {
    Text = "Bienvenue, Grand Prêtre !"
  },
  AvgDialog_118962_Content_17 = {
    Text = "Grand Prêtre, nous avons encerclé les intrus dans la chambre de la Mère divine ! Il vous suffit de donner l'ordre..."
  },
  AvgDialog_118962_Content_18 = {
    Text = "Pas besoin, la Mère divine n'est plus ici."
  },
  AvgDialog_118962_Content_19 = {
    Text = "(J'ai été découvert ?!)"
  },
  AvgDialog_118962_Content_2 = {Text = "Hmph..."},
  AvgDialog_118962_Content_20 = {
    Text = "Les personnes dans la pièce... pourquoi ne pas en parler ?"
  },
  AvgDialog_118962_Content_21 = {
    Text = "De quoi veux-tu parler ?"
  },
  AvgDialog_118962_Content_22 = {
    Text = "Que ce soit toi ou tes amis, depuis que vous êtes montés à bord, tous les Marcheurs des mers vous traitent avec respect."
  },
  AvgDialog_118962_Content_23 = {
    Text = "Vous, en revanche, rendez le mal pour le bien en enlevant la Mère Divine, empêchant ainsi la cérémonie de navigation cruciale de se tenir à temps."
  },
  AvgDialog_118962_Content_24 = {
    Text = "Si nous manquons ce moment d'alignement des étoiles, nos grands vœux devront attendre soixante cycles d'étoiles."
  },
  AvgDialog_118962_Content_25 = {
    Text = "Il doit y avoir une raison, et j'aimerais entendre vos deux explications."
  },
  AvgDialog_118962_Content_26 = {
    Text = "Parce que le Gardien du Secret a vécu une boucle ? Parce que cette fille était autrefois membre de Mizag ?"
  },
  AvgDialog_118962_Content_27 = {
    Text = "William n'a pas encore clarifié les tenants et aboutissants de sa réponse, lorsque derrière lui, un bruit de glissement humide et nauséabond se fit entendre."
  },
  AvgDialog_118962_Content_28 = {
    Text = "Il se retourne brusquement — ses pupilles se contractent instantanément. Plusieurs Poisson-nageurs ont déjà rempli la fenêtre comme un flot de boue débordant."
  },
  AvgDialog_118962_Content_29 = {
    Text = "Des membres tordus se précipitent dans la pièce, un flot nauséabond et visqueux de fluides corporels déferle, imprégnant instantanément le tapis en un marécage glissant."
  },
  AvgDialog_118962_Content_3 = {
    Text = "Elle sortit de nulle part un petit miroir et commença à arranger soigneusement les mèches de cheveux éparses sur son front."
  },
  AvgDialog_118962_Content_30 = {
    Text = "Il était comme un clou, enfoncé fermement au point de mort où deux flots maléfiques allaient se rencontrer."
  },
  AvgDialog_118962_Content_31 = {
    Text = "Comment as-tu fait..."
  },
  AvgDialog_118962_Content_32 = {
    Text = "Les hublots sont situés à plus de dix mètres du pont, et le Gardien du Secret a également coupé la longue corde à temps après être sorti."
  },
  AvgDialog_118962_Content_33 = {
    Text = "Comment ont-elles réussi à se glisser silencieusement à travers le mur lisse par la fenêtre ?"
  },
  AvgDialog_118962_Content_34 = {
    Text = "Le Royaume Divin nous accorde la Force suffisante pour résister au Fléau, ces obstacles dérisoires ne peuvent naturellement pas retenir le Marcheur des mers."
  },
  AvgDialog_118962_Content_35 = {
    Text = "Créatures marines... des ventouses sur vos pieds ?"
  },
  AvgDialog_118962_Content_36 = {
    Text = "À part les Marcheurs des mers stationnés sur le paquebot, toutes les créatures marines qui entourent le navire sont venues sous l'invitation spirituelle de notre Seigneur, se soumettant à notre volonté."
  },
  AvgDialog_118962_Content_37 = {
    Text = "Même si ce n'est pas de cette façon, tu devrais savoir que tu ne peux pas combattre toute l'église des Marcheurs des mers avec juste cette petite pièce..."
  },
  AvgDialog_118962_Content_38 = {
    Text = "L'enquêteur de Mizag n'est pas si imprudent... Dis-moi, que sais-tu d'autre ?"
  },
  AvgDialog_118962_Content_39 = {
    Text = "<Big:<Shake:Boumboum——>>"
  },
  AvgDialog_118962_Content_4 = {
    Text = "Cette structure dont tu parles... où est-elle ?"
  },
  AvgDialog_118962_Content_40 = {
    Text = "Un bruit strident de métal déchirant le ciel, accompagné d'une forte secousse, a semblé saisir la coque du navire d'une main géante invisible, la tordant violemment !"
  },
  AvgDialog_118962_Content_41 = {
    Text = "Qu'est-ce qui se passe ?!"
  },
  AvgDialog_118962_Content_42 = {
    Text = "Quelqu'un force le changement de cap !"
  },
  AvgDialog_118962_Content_43 = {
    Text = "Le cargo de dix mille tonnes se débat comme une bête enragée et incontrôlable, se tordant et se heurtant dans les vagues géantes de la mer nocturne, chaque tremblement violent semblant déchirer le navire !"
  },
  AvgDialog_118962_Content_44 = {
    Text = "Salle de puissance... c'est la salle de puissance !"
  },
  AvgDialog_118962_Content_45 = {
    Text = "Goliath a pris des otages et a pris d'assaut la salle de puissance !"
  },
  AvgDialog_118962_Content_46 = {
    Text = "Ça recommence..."
  },
  AvgDialog_118962_Content_47 = {
    Text = "Des tremblements violents viennent par vagues."
  },
  AvgDialog_118962_Content_48 = {Text = "Murphy..."},
  AvgDialog_118962_Content_49 = {
    Text = "Je sais que tu ne peux pas te passer de ton aîné, n'est-ce pas ?"
  },
  AvgDialog_118962_Content_5 = {
    Text = "Juste en dessous du siège du capitaine, voilà."
  },
  AvgDialog_118962_Content_50 = {
    Text = "Je comprends tout, chacun dit que je suis la personne la plus importante, mais au moment du choix, ils me jettent facilement."
  },
  AvgDialog_118962_Content_51 = {Text = "Je..."},
  AvgDialog_118962_Content_52 = {
    Text = "D'accord, d'accord, ce ne sont que des plaintes inutiles sous couvert de métaphores. On n'est pas vraiment proches, n'est-ce pas ?"
  },
  AvgDialog_118962_Content_53 = {
    Text = "De plus, si la salle de puissance explose, la cale inférieure risque également d'être touchée."
  },
  AvgDialog_118962_Content_54 = {
    Text = "Allons-y, nous n'avons pas d'autre choix."
  },
  AvgDialog_118962_Content_6 = {
    Text = "Elle marcha sur la plaque de fer sous ses pieds."
  },
  AvgDialog_118962_Content_7 = {
    Text = "Cependant, c'est un peu étrange ici..."
  },
  AvgDialog_118962_Content_8 = {
    Text = "À cette époque, Goliath et Caecus devraient être en train de surveiller la cabine."
  },
  AvgDialog_118962_Content_9 = {
    Text = "Avant le rituel, les créatures sous-marines seront en agitation, nous devons empêcher le banc de poissons frénétiques de perturber la direction du navire..."
  },
  AvgDialog_118963_Content_1 = {
    Text = "Vacances de la Mère divine"
  },
  AvgDialog_118963_Content_10 = {
    Text = "Vous voulez dire..."
  },
  AvgDialog_118963_Content_11 = {
    Text = "Oui, tu peux toujours être ta Mère divine. Cependant, aujourd'hui, c'est les Vacances de la Mère divine."
  },
  AvgDialog_118963_Content_12 = {
    Text = "Tu racontes des mensonges sans changer de visage."
  },
  AvgDialog_118963_Content_13 = {
    Text = "Vacances de la Mère divine ?"
  },
  AvgDialog_118963_Content_14 = {
    Text = "Oui, aujourd'hui, j'ai été chargé de t'emmener jouer sur le bateau toute la journée."
  },
  AvgDialog_118963_Content_15 = {
    Text = "Après être monté à bord, tu n'as pas encore expérimenté la vie réelle des matelots, n'est-ce pas ?"
  },
  AvgDialog_118963_Content_16 = {
    Text = "Sans possibilité de refus, tu as «invité» Murphy à sortir de la chambre."
  },
  AvgDialog_118963_Content_17 = {
    Text = "Nous devons vraiment grimper à des endroits comme ça ?"
  },
  AvgDialog_118963_Content_18 = {
    Text = "Monte vite, c'est le seul endroit avec un bon champ de vision pour observer la situation des marcheurs des mers en patrouille."
  },
  AvgDialog_118963_Content_19 = {
    Text = "Si tu traînes encore, tu vas te faire découvrir !"
  },
  AvgDialog_118963_Content_2 = {
    Text = "Tu ouvres les yeux. Le soleil éclatant te fait mal aux yeux."
  },
  AvgDialog_118963_Content_20 = {
    Text = "Quoi, c'est devenu un vrai bazar !"
  },
  AvgDialog_118963_Content_21 = {
    Text = "Cela dit, elle saisit docilement ta main, et tu la tires facilement sur la scène."
  },
  AvgDialog_118963_Content_22 = {Text = "Pouf—"},
  AvgDialog_118963_Content_23 = {
    Text = "Murphy éclata de rire soudainement."
  },
  AvgDialog_118963_Content_24 = {
    Text = "De quoi ris-tu ?"
  },
  AvgDialog_118963_Content_25 = {
    Text = "On dirait un singe quand tu grimpes dans le gréement !"
  },
  AvgDialog_118963_Content_26 = {
    Text = "Espèce de gars, si je devais garder le volume bas, je frapperais sûrement ton front avec force..."
  },
  AvgDialog_118963_Content_27 = {
    Text = "Ne ris plus ! Tu ne peux pas t'échapper non plus !"
  },
  AvgDialog_118963_Content_28 = {
    Text = "Tu saisis la main de Murphy et la rapproches de toi."
  },
  AvgDialog_118963_Content_29 = {
    Text = "Hé, comment oses-tu !"
  },
  AvgDialog_118963_Content_3 = {
    Text = "Mais tu ne détournes pas le regard."
  },
  AvgDialog_118963_Content_30 = {Text = "Chut !"},
  AvgDialog_118963_Content_31 = {
    Text = "Vous retenez votre souffle alors qu'une équipe de Marcheurs des mers, vêtus de vieilles capes en paille sales, titube à travers le pont."
  },
  AvgDialog_118963_Content_32 = {
    Text = "Vite, il faut rapidement retrouver la Mère divine ! Elle doit être sur ce bateau !"
  },
  AvgDialog_118963_Content_33 = {
    Text = "Nous sommes juste au-dessus de leur tête, et ils ne nous voient pas du tout ?"
  },
  AvgDialog_118963_Content_34 = {
    Text = "Depuis l'Antiquité, les patrouilleurs ne regardent pas en haut."
  },
  AvgDialog_118963_Content_35 = {
    Text = "Ne t'inquiète pas, tant que nous restons ici, personne ne pourra nous découvrir."
  },
  AvgDialog_118963_Content_36 = {
    Text = "Regarde, là-haut, il y a quelqu'un !"
  },
  AvgDialog_118963_Content_37 = {
    Text = "Ta langue de corbeau est vraiment trop précise, non !"
  },
  AvgDialog_118963_Content_38 = {
    Text = "Soyez discrets, après avoir éliminé cette petite équipe, nous nous faufilerons immédiatement vers la salle des matelots !"
  },
  AvgDialog_118963_Content_4 = {
    Text = "Bruissement, bruissement, le bruit des araignées grimpantes est comme l'encouragement doux de ma mère."
  },
  AvgDialog_118963_Content_5 = {
    Text = "Pas besoin de me rappeler. Je sais, c'est le dernier cycle."
  },
  AvgDialog_118963_Content_6 = {
    Text = "Tu essuies les larmes qui coulent au coin de tes yeux et te retournes vers la direction d'où la voix d'appel va bientôt venir, sans te retourner pour vérifier l'origine de la chanson."
  },
  AvgDialog_118963_Content_7 = {
    Text = "Parce que tu sais que la femme tenant le métier à tisser te regarde avec compassion."
  },
  AvgDialog_118963_Content_8 = {
    Text = "Que fais-tu encore ici ? La navigation de ce bateau a repris, il n'y a plus de place pour toi ici."
  },
  AvgDialog_118963_Content_9 = {
    Text = "Peu importe, tu es la Mère divine des Marcheurs des mers, la capitaine du Parades, la maîtresse du Paradis. Cela n'a rien à voir avec le fait que je vais te donner des vacances."
  },
  AvgDialog_119922_Content_1 = {
    Text = "Bon retour, partenaire."
  },
  AvgDialog_119922_Content_10 = {
    Text = "Pas de souci, mon seigneur, peu importe combien de temps vous devez courir, Ogier sera toujours avec vous. Je souhaite seulement…"
  },
  AvgDialog_119922_Content_11 = {
    Text = "Le jeune chevalier te regarde attentivement, ses yeux remplis de sincérité et d'une supplication cachée sous cette sincérité."
  },
  AvgDialog_119922_Content_12 = {
    Text = "Je souhaite seulement que… la prochaine fois que mon seigneur prévoit de « se détendre » et qu'il s'absente aussi longtemps, il doit absolument m'emmener. Ogier jure de vous protéger jusqu'à la mort."
  },
  AvgDialog_119922_Content_13 = {
    Text = "Ou je peux aussi."
  },
  AvgDialog_119922_Content_14 = {
    Text = "Lotan te regarde aussi, ses yeux d'habitude flamboyants remplis de sérieux. En cet instant, il n'y a vraiment ni victoire ni défaite dans son esprit, ni combat, seulement de l'inquiétude pour toi."
  },
  AvgDialog_119922_Content_15 = {
    Text = "……je savais que cela arriverait. Vous deux, n'oubliez pas l'objectif de cette rencontre. Nous célébrons le « Retour » de %player%."
  },
  AvgDialog_119922_Content_16 = {
    Text = "J'espère qu'après ce « retour », tu ne partiras plus."
  },
  AvgDialog_119922_Content_17 = {
    Text = "Ce n'est qu'une petite sortie, ne le prends pas si au sérieux... Et puis, je suis déjà de retour, n'est-ce pas ?"
  },
  AvgDialog_119922_Content_18 = {
    Text = "En entendant tes paroles, Doll te regarda. Elle semblait vouloir dire quelque chose, mais finit par juste soupirer doucement."
  },
  AvgDialog_119922_Content_19 = {
    Text = "Oui, tu es revenu, ceux qui cherchaient ton ombre sur le campus ne peuvent que décevoir, ces jours où ceux qui se tenaient silencieusement devant ta porte n'osaient pas frapper sont également révolus."
  },
  AvgDialog_119922_Content_2 = {
    Text = "On ne sait pas quand, la place de Mizag a été aménagée en une petite fête du thé, et Ramona se tenait à côté d'une petite table pleine de muffins, de confiture et de thé, souriant et tendant la main vers toi."
  },
  AvgDialog_119922_Content_20 = {
    Text = "%player%, je l'ai dit maintes et maintes fois, et je continuerai à le dire à l'avenir, ta présence est d'une importance capitale."
  },
  AvgDialog_119922_Content_21 = {
    Text = "Que ce soit pour ce monde ou pour nous. Alors…"
  },
  AvgDialog_119922_Content_22 = {
    Text = "Tu attends la suite de Doll, mais Doll ferme juste les yeux et ne dit plus rien."
  },
  AvgDialog_119922_Content_23 = {
    Text = "À ce moment-là, une paire de mains douces mais déterminées se posa sur le dos de ta main, c'était Ramona."
  },
  AvgDialog_119922_Content_24 = {
    Text = "Partenaire, je sais qu'en tant que Gardien du Secret, tu portes beaucoup de pression, nous le comprenons tous et nous le respectons. Donc, nous ne te demanderons pas trop."
  },
  AvgDialog_119922_Content_25 = {
    Text = "Je veux juste que tu saches que peu importe combien de fois tu pars, peu importe combien de temps tu es parti, quand tu reviendras, nous serons ici."
  },
  AvgDialog_119922_Content_26 = {
    Text = "En disant cela, la voix de la jeune fille s'est interrompue un instant, et elle t'a lentement souri."
  },
  AvgDialog_119922_Content_27 = {
    Text = "Encore une fois, bon retour, partenaire. Maintenant, profite de ce goûter qui a été préparé pour toi."
  },
  AvgDialog_119922_Content_28 = {
    Text = "C'est exact. Aujourd'hui, il n'y a pas d'évaluation, pas de devoirs supplémentaires. Ta seule tâche est de te rendre heureux."
  },
  AvgDialog_119922_Content_29 = {
    Text = "Si vous ne vous souciez pas des caries et d'une consommation excessive de sucre, vous pouvez manger tous ces desserts. Après tout, ils sont préparés pour vous."
  },
  AvgDialog_119922_Content_3 = {
    Text = "Je ne sais pas si j'ai l'honneur de t'inviter à notre tea-time de retour préparé pour toi ?"
  },
  AvgDialog_119922_Content_30 = {
    Text = "Pas nécessaire de faire cela…"
  },
  AvgDialog_119922_Content_31 = {
    Text = "Bien que tu dises cela, tu as tout de même goûté un rouleau au beurre recouvert de sucre glace. Le goût est exactement comme tu l'imaginais, excessivement sucré, mais pas désagréable."
  },
  AvgDialog_119922_Content_32 = {
    Text = "Parce qu'au milieu du regard bienveillant de tous, ton cœur a trouvé satisfaction. Peut-être que la vie, c'est goûter à une telle douceur émouvante dans les intervalles amers de la réalité."
  },
  AvgDialog_119922_Content_4 = {
    Text = "Tu acquiesces, alors la jeune fille te prend doucement par la main et t'emmène vers cette table triangulaire pleine de plats, où les Éveilleurs attendent depuis longtemps."
  },
  AvgDialog_119922_Content_5 = {
    Text = "Si tu veux mon avis, un combat n'est-il pas plus « excitant » qu'un goûter ? Mais en effet... cette fois, c'est un peu différent."
  },
  AvgDialog_119922_Content_6 = {
    Text = "Cette fois, cela n'a rien à voir avec la victoire ou la défaite, rien à voir avec le combat. Cela ne concerne que toi."
  },
  AvgDialog_119922_Content_7 = {
    Text = "%player%, tu es la vedette de ce tea time."
  },
  AvgDialog_119922_Content_8 = {
    Text = "Lotan dit en poussant le plateau rempli de rouleaux au beurre glacé devant vous. \n En un coup d'œil, vous savez qu'il est terriblement calorique."
  },
  AvgDialog_119922_Content_9 = {
    Text = "J'ai l'impression que… tant que je prends une bouchée, il me faudra un semestre pour digérer…"
  },
  AvgDialog_119923_Content_1 = {
    Text = "Dans le marais noir de l'esprit, une douleur perçante atteignant l'âme se fit entendre, accompagnée de paroles glaciales."
  },
  AvgDialog_119923_Content_10 = {
    Text = "En repensant à la sensation d'une opération à crâne ouvert, ton cerveau s'engourdit. Pour échapper à ce sentiment, tu as délibérément changé de sujet."
  },
  AvgDialog_119923_Content_11 = {
    Text = "Ce monde...... Quelle est la situation maintenant ?"
  },
  AvgDialog_119923_Content_12 = {
    Text = "C'est toujours la même chose. À chaque instant, nous nous rapprochons du crash et de la destruction. Mais au moins, il y a une bonne nouvelle pour toi."
  },
  AvgDialog_119923_Content_13 = {
    Text = "En disant cela, Doll : Dissoute a ouvert le communicateur, et bientôt, une silhouette familière est apparue devant vous. C'était un message enregistré précédemment."
  },
  AvgDialog_119923_Content_14 = {
    Text = "Fusion·Doll, si %player% réussit son Retour ou a des nouvelles, souviens-toi de me le dire. De plus, je pense que ta suggestion de planter une suggestion psychologique était très raisonnable."
  },
  AvgDialog_119923_Content_15 = {
    Text = "En tant que psychologue professionnel, je ne peux pas trop céder aux désirs du patient en ce qui concerne le maintien de %player%..."
  },
  AvgDialog_119923_Content_16 = {
    Text = "La communication s'est interrompue ici, coupée par la Fusion·poupée. Elle a doucement tapoté la table, indiquant que tu devais porter ton attention sur elle."
  },
  AvgDialog_119923_Content_17 = {
    Text = "Les politesses inutiles peuvent s'arrêter là. Si j'ai Lâcher tout cela, c'est Seulement pour vous montrer ce que vous avez manqué pendant votre «départ»."
  },
  AvgDialog_119923_Content_18 = {
    Text = "Le plus important, c'est que mon expérience n'est pas encore terminée..."
  },
  AvgDialog_119923_Content_19 = {
    Text = "Fondu·poupée s'approche de vous avec un scalpel à la main. Son expression est calme, mais elle cache une certaine folie."
  },
  AvgDialog_119923_Content_2 = {
    Text = "Jusqu'à quand vas-tu faire semblant de dormir ? Mon adorable chiot."
  },
  AvgDialog_119923_Content_20 = {
    Text = "Toi, que veux-tu faire ?"
  },
  AvgDialog_119923_Content_21 = {
    Text = "Je compte fixer ton esprit de façon permanente dans cette tête, dans ce corps. Ainsi, tu ne pourras plus «partir»."
  },
  AvgDialog_119923_Content_22 = {
    Text = "Tu recules d'un pas, effrayé, mais tu te ressaisis rapidement, car tu te rappelles que tu as encore des choses à accomplir——"
  },
  AvgDialog_119923_Content_23 = {
    Text = "Fusion·Doll, il n'est pas nécessaire de faire cela. Tant que ce monde n'est pas revenu à la normale, je ne partirai pas vraiment."
  },
  AvgDialog_119923_Content_24 = {
    Text = "La silhouette tenant le scalpel s'arrête, te regardant silencieusement, comme si elle jugeait la véracité de tes paroles."
  },
  AvgDialog_119923_Content_25 = {
    Text = "Je suis sérieux. En tant que Gardien, je ne renoncerai jamais à sauver ce monde, donc peu importe combien de temps je « lâche », je reviendrai toujours."
  },
  AvgDialog_119923_Content_26 = {
    Text = "Doll : Dissoute a lâché le scalpel. Profitant de cette occasion, tu as touché ta poitrine. \n Lorsque tes doigts ont effleuré la clé d'argent familière, ton cœur s'est enfin apaisé."
  },
  AvgDialog_119923_Content_27 = {
    Text = "Maintenant, je suis de retour. L'enquête qui avait été interrompue peut également reprendre."
  },
  AvgDialog_119923_Content_28 = {
    Text = "En disant cela, tu te diriges vers la porte. Fondu·poupée te jette un coup d'œil et te suit également."
  },
  AvgDialog_119923_Content_29 = {
    Text = "Il semble que tu comprennes bien l'importance de ton existence pour ce monde."
  },
  AvgDialog_119923_Content_3 = {
    Text = "Doll : Dissoute ?"
  },
  AvgDialog_119923_Content_30 = {
    Text = "Bien sûr, parce que comme Tawil l'a dit, je suis la variable de ce monde, l'avenir de ce monde."
  },
  AvgDialog_119923_Content_31 = {
    Text = "Avec tes paroles, la grande porte du laboratoire s'ouvre lentement. L'air et la lumière du soleil de l'extérieur se déposent doucement sur toi, comme un accueil silencieux, ou une réponse."
  },
  AvgDialog_119923_Content_32 = {
    Text = "Ce monde t'attend, attendant le changement que tu es sur le point d'apporter et l'avenir que tu es sur le point de créer."
  },
  AvgDialog_119923_Content_4 = {
    Text = "Tu as reconnu le propriétaire de cette voix, tu ouvres lentement les yeux. Très vite, les ténèbres s'estompent, et la lumière apparaît——"
  },
  AvgDialog_119923_Content_5 = {
    Text = "«Partir» comment se sent-on dans ce monde ?"
  },
  AvgDialog_119923_Content_6 = {
    Text = "Peut-être que la prochaine fois, je devrais aussi enfermer ton « esprit », ainsi je n'aurais plus besoin de le retrouver."
  },
  AvgDialog_119923_Content_7 = {
    Text = "Fondu·poupée plisse les yeux, affichant une expression qui semble sourire sans vraiment l'être, tout en jouant lentement avec le scalpel brillant de lumière froide dans sa main."
  },
  AvgDialog_119923_Content_8 = {
    Text = "…Comment suis-je ici ?"
  },
  AvgDialog_119923_Content_9 = {
    Text = "Bien sûr, c'est parce que lorsque ton « Esprit » s'en va, le vaisseau perd sa fonction, c'est pourquoi j'ai dû effectuer à nouveau la chirurgie pour récupérer ton « Esprit »."
  },
  AvgDialog_120290_Content_1 = {
    Text = "Pot de chair doré"
  },
  AvgDialog_120290_Content_10 = {
    Text = "La porte s'ouvre et tu tombes dans ses bras. Elle te soulève sur le lit, enroulant les couvertures autour de toi, puis s'incline et touche son front au tien, te rapprochant d'elle."
  },
  AvgDialog_120290_Content_11 = {
    Text = "Mūmā...? Mūmā!"
  },
  AvgDialog_120290_Content_12 = {
    Text = "Papa ne s'occupe plus de moi depuis longtemps. Il n'y a personne dans la maison pour m'aider, et il n'y a pas d'eau... J'ai tellement mal à la tête, et tout mon corps me fait mal."
  },
  AvgDialog_120290_Content_13 = {
    Text = "...Mūmā est bon Nānnān, ne pleure pas."
  },
  AvgDialog_120290_Content_14 = {
    Text = "Ne t'inquiète pas, tout ira bien bientôt, Mūmā te le promet."
  },
  AvgDialog_120290_Content_15 = {
    Text = "Tu t'enfonces dans la couverture chaude, attrapant d'un air groggy le parfum qui devient progressivement plus fort, ne ressemblant plus au parfum habituel de jasmin de ta mère, mais comme..."
  },
  AvgDialog_120290_Content_16 = {
    Text = "À quoi cela sent-il ? Comme les ruelles les plus profondes et sinueuses de Shencheng, où de grandes fleurs de magnolia tombent et fermentent dans la chaleur étouffante—une étrange douceur écoeurante et sucrée."
  },
  AvgDialog_120290_Content_17 = {
    Text = "Maman, ton odeur a-t-elle changé ? Ça sent si bon, et... c'est aussi un peu étrange."
  },
  AvgDialog_120290_Content_18 = {
    Text = "La voix douce ne répondit pas à ta question. Avec ses caresses délicates, le parfum devint plus fort, presque tangible."
  },
  AvgDialog_120290_Content_19 = {
    Text = "Tu veux voir son visage clairement, mais seule une brume sans fin tourbillonne devant tes yeux, t'enveloppant finalement."
  },
  AvgDialog_120290_Content_2 = {
    Text = "Une légère brume porte le parfum du jasmin, s'enroulant autour de tes membres et t'enchevêtrant dans une étreinte invisible et humide."
  },
  AvgDialog_120290_Content_20 = {
    Text = "Dors, mon bon bébé, dors. Maman sera bientôt à tes côtés."
  },
  AvgDialog_120290_Content_21 = {
    Text = "...Je lui ai déjà promis."
  },
  AvgDialog_120290_Content_22 = {
    Text = "Dans l'obscurité, la soif te ronge encore comme la patte d'un chat, puis un liquide chaud et visqueux semble s'écouler dans ta gorge par tes narines ou le coin de ta bouche."
  },
  AvgDialog_120290_Content_23 = {
    Text = "Tes paupières deviennent de plus en plus lourdes, et au milieu des parfums et des murmures, tu perds progressivement complètement connaissance."
  },
  AvgDialog_120290_Content_24 = {
    Text = "...jusqu'à ce que le son des pas se rassemble doucement devant la porte, te réveillant de ton lourd et lancinant engourdissement avec les sons de conversation."
  },
  AvgDialog_120290_Content_25 = {
    Text = "Oh là là, Mademoiselle Die, chaque jour vous vous réveillez et voulez immédiatement du thé. C'est tellement ennuyeux ! Pensez-vous vraiment que vous êtes toujours la dame gâtée que vous étiez de votre vivant ?"
  },
  AvgDialog_120290_Content_26 = {
    Text = "Baissez le ton ! ... Le maître ne s'occupe même pas de sa propre fille. Il y a combien de belles concubines dans la cour ? Regardez, n'est-elle pas encore en train de filer à la Quatrième Rue aujourd'hui ?"
  },
  AvgDialog_120290_Content_27 = {
    Text = "Regarde, ça ne prendra pas longtemps. Bientôt, toutes les concubines de la maison auront les petits maîtres et maîtresses qui sortiront..."
  },
  AvgDialog_120290_Content_28 = {
    Text = "...Mon Seigneur ?"
  },
  AvgDialog_120290_Content_29 = {
    Text = "Tu relèves la tête, et un bassin en cuivre légèrement sale sur le cadre en bois reflète faiblement les traits délicats et juvéniles d'une personne d'origine orientale. Tu clignes des yeux, et la petite fille dans le reflet cligne des yeux en retour."
  },
  AvgDialog_120290_Content_3 = {
    Text = "La somnolence après la fièvre te rend incapable de résister à l'envie de te pencher vers cette brume..."
  },
  AvgDialog_120290_Content_30 = {
    Text = "Ta conscience s'éclaircit progressivement, et des fragments concernant ton identité émergent dans ton esprit."
  },
  AvgDialog_120290_Content_31 = {
    Text = "...Monsieur, Ho Fong, Papa... Je suis au manoir de la famille He, je suis la fille de Ho Fong, je m'appelle..."
  },
  AvgDialog_120290_Content_32 = {
    Text = "Oh non, tu ne peux pas t'allonger par terre comme ça. Le maître va me gronder s'il te voit."
  },
  AvgDialog_120290_Content_33 = {
    Text = "La porte s'est ouverte soudainement, interrompant tes pensées alors que quelqu'un se précipitait en avant et t'aidait impatiemment à te relever."
  },
  AvgDialog_120290_Content_34 = {
    Text = "Tout à l'heure, comment ai-je fini par terre ? Où est maman ?"
  },
  AvgDialog_120290_Content_35 = {
    Text = "Madame ? Mademoiselle, vous devez être claire ; la dame est partie depuis plus d'un mois."
  },
  AvgDialog_120290_Content_36 = {
    Text = "Elle s'écria, te voyant là, perdu dans tes pensées, avec une expression de réticence sur le visage."
  },
  AvgDialog_120290_Content_37 = {
    Text = "<Small:C'est seulement si petit, il ne sait probablement même pas ce que signifie partir.>"
  },
  AvgDialog_120290_Content_38 = {
    Text = "<LightGray:Oui, maman a fait ça il y a plus d'un mois...>"
  },
  AvgDialog_120290_Content_39 = {
    Text = "Tu as encore rêvé ? Soupir. Tiens, je t'ai apporté de l'eau."
  },
  AvgDialog_120290_Content_4 = {
    Text = "Puis il tomba directement sur le sol."
  },
  AvgDialog_120290_Content_40 = {
    Text = "Eau... tu réalises soudain que tu n'as plus soif ; le liquide qui a coulé plus tôt, accompagné de son parfum."
  },
  AvgDialog_120290_Content_41 = {
    Text = "Le parfum doux, presque en décomposition, de magnolia persiste encore dans vos dents et vos narines !\nSoudain, vous reprenez conscience et vous précipitez dehors."
  },
  AvgDialog_120290_Content_42 = {
    Text = "Hé, hé ! Où penses-tu aller, mademoiselle !"
  },
  AvgDialog_120290_Content_43 = {
    Text = "Le festival de l'Extrême-Orient est arrivé, les lumières commencent à s'allumer, et les lanternes rouges et les néons modernes se complètent. Cependant, les personnes qui auraient dû rentrer chez elles tôt ce jour-là affluent toutes dans la même direction."
  },
  AvgDialog_120290_Content_44 = {
    Text = "L'air est rempli de l'odeur de poudre, de kérosène, de l'odeur grasse des stands de collations et des restaurants, et d'un..."
  },
  AvgDialog_120290_Content_45 = {
    Text = "Ma Mūmā. C'est son odeur. Ce n'était pas un rêve ! Ce n'était pas !"
  },
  AvgDialog_120290_Content_46 = {
    Text = "Tu l'as trouvé, la source de cette étrange, intense, familière, intime et tendre odeur métallique sucrée."
  },
  AvgDialog_120290_Content_47 = {
    Text = "Le signe du Bâtiment des Ventes d'Or pend haut au-dessus de la porte ornée."
  },
  AvgDialog_120290_Content_48 = {
    Text = "Monsieur Xu !"
  },
  AvgDialog_120290_Content_49 = {
    Text = "Écarte-toi, Monsieur Xu, tu me bloques le chemin, regarde là-bas !"
  },
  AvgDialog_120290_Content_5 = {
    Text = "Aïe ! Ça fait mal... Maman... Eau..."
  },
  AvgDialog_120290_Content_50 = {Text = "Tsk"},
  AvgDialog_120290_Content_51 = {
    Text = "La silhouette sur la haute plateforme jouait distraitement avec un éventail noir, la moitié de son visage caché derrière la surface de l'éventail."
  },
  AvgDialog_120290_Content_52 = {
    Text = "Les gens se bousculaient, te submergeant presque, une vague d'enthousiasme et d'anxiété se glissant dans leurs yeux, mais cela ne semblait avoir aucun effet sur elle."
  },
  AvgDialog_120290_Content_53 = {
    Text = "Tu as trouvé la source de cette fragrance, ou plutôt, un certain désir et un frisson que tu ne pouvais pas comprendre t'ont captivé. Tu as désespérément levé la tête et regardé en haut."
  },
  AvgDialog_120290_Content_54 = {Text = "...yeah."},
  AvgDialog_120290_Content_55 = {
    Text = "Ressentant quelque chose, elle baissa les yeux, et tout ce que vous pouviez voir, c'était une paire d'yeux très, très beaux."
  },
  AvgDialog_120290_Content_56 = {
    Text = "Le ventilateur noir s'est lentement écarté avec une élégance à couper le souffle."
  },
  AvgDialog_120290_Content_57 = {
    Text = "<color=#C6C4C6>MistMISTMiST</color>\n<color=#817D81>MISTmIsT</color><color=#B9B7B9>Elle... ÇA ? ÇA...Elle... Mère...</color>MÈRESesYEUX\n<color=#C6C4C6>MISTmIsT</color><color=#B9B7B9>MIST</color><color=#817D81>mIsTMISTmIsTMISTmIsTMIST</color><color=#C6C4C6>MIST</color> <color=#757175>MIST</color>       <color=#817D81>ELLEELLEELLEELLEELLE</color>                         <color=#757175>mIsTMISTmIsT</color><color=#C6C4C6>MISTMISTMÈREmIsTMIST</color> <color=#C6C4C6>mIsTMISTmIsT</color>      <color=#B9B7B9>ELLEELLEELLEELLEELLE</color>         <color=#817D81> mIsTMISTmIsT</color><color=#D7D7D7>MISTmIsTMISTmIsTMISTmIsTMISTmIsT</color> <color=#D7D7D7>MISTmIsTMISTmIsT</color><color=#B9B7B9>MIsTMIST</color><color=#757175>mIsTMISTmIsT</color><color=#ACAAAC>MISTmIsTMISTmIsTMISTmIsTMISTmIsTMIST</color> <color=#B9B7B9>sYEUXmIsTMISTmIsT</color><color=#817D81>BEAUXYEUX</color><color=#B9B7B9>mIsTMISTmIsTMISTmIsT</color><color=#757175>BEAUXYEUX</color><color=#D7D7D7>MISTmIsT MISTmIsTMISTmIsTMISTmIsTMISTMISTmIsTMISTmIsT</color> <color=#5F5D5F>MÈRESMÈREMAmIsT</color><color=#817D81>MISTmIsTMISTMAMANmA</color><color=#757175>YEUMAMANEYEUXŒIL mIsTMISTmIsT</color><color=#B9B7B9>ELLEELLEELLEELLEmIsTMIST</color> <color=#757175>mIsTMISTmIsTYEUXBEAUMIST</color><color=#B9B7B9>mIsTMISTmIsTMISTmIsTMISTMÈRESmIsTMISTmIsT</color> <color=#C6C4C6>MÈRESMèRESMÈRES</color><color=#D7D7D7>MAMÈRESMÈRESÈRE</color><color=#ACAAAC>MÈRESÈREBEAUX</color>"
  },
  AvgDialog_120290_Content_58 = {
    Text = "Des pleurs, des cris, des hurlements explosent soudain dans vos oreilles, alors que des couches de personnes se ruent vers vous !"
  },
  AvgDialog_120290_Content_59 = {
    Text = "Je l'ai vu, je l'ai vu, elle me regarde !"
  },
  AvgDialog_120290_Content_6 = {
    Text = "Tes membres sont si faibles que tu ne peux rassembler aucune force ; la mémoire n'est pas encore revenue, et tu as une soif incroyable, prononçant instinctivement le nom le plus familier."
  },
  AvgDialog_120290_Content_60 = {
    Text = "Elle me regarde !"
  },
  AvgDialog_120290_Content_61 = {
    Text = "<Change>Tellement... tellement beau !! Quel visage c'est, si charmant, si... extraordinaire... si terrifiant !!!"
  },
  AvgDialog_120290_Content_62 = {
    Text = "Monsieur Xu ! Monsieur Xu... S'il vous plaît, s'il vous plaît !!"
  },
  AvgDialog_120290_Content_63 = {
    Text = "Regarde-moi !"
  },
  AvgDialog_120290_Content_64 = {
    Text = "<Shake:<Red:AAAAHHHHH!!!!>>"
  },
  AvgDialog_120290_Content_65 = {
    Text = "L'homme bien habillé poussa soudain un cri et se jeta sur l'homme en costume qui se tenait entre lui et Xu, tandis que ce dernier fixait directement la position de Xu, jusqu'à ce que son œil soit soudainement arraché."
  },
  AvgDialog_120290_Content_66 = {
    Text = "L'homme, dont les yeux avaient été crevés, criait de douleur tout en riant de manière maniaque. Les cristaux sphériques pendaient doucement de ses orbites alors qu'il s'essuyait le visage avec désinvolture et, de toutes ses forces, tendait la main vers la haute plateforme, ses veines saillantes."
  },
  AvgDialog_120290_Content_67 = {
    Text = "Comme si un signal avait été donné, la foule se transforme en une marée enragée. Au milieu des rires et des cris, elle se précipite en avant, désespérée de toucher la haute scène."
  },
  AvgDialog_120290_Content_68 = {
    Text = "<Change>Xu!! Xu!!!"
  },
  AvgDialog_120290_Content_69 = {
    Text = "<Change>Xu——!!!!!"
  },
  AvgDialog_120290_Content_7 = {
    Text = "Une voix douce et chantante s'approchait au loin, et une silhouette féminine passa devant la porte, familière et chaleureuse. Tu sentis ton bas du corps s'affaiblir alors que tu essayais de te lever..."
  },
  AvgDialog_120290_Content_70 = {
    Text = "Le son aigu et perçant est sur le point de briser vos tympans. La foule pousse et bouscule, et ce jeune corps gémit sous la pression, tandis que les traits sous le ventilateur deviennent plus clairs mais aussi plus indistincts."
  },
  AvgDialog_120290_Content_71 = {
    Text = "Finalement, cela s'est regroupé en une brume abyssale qui a englouti toute la lumière."
  },
  AvgDialog_120290_Content_72 = {
    Text = "Et un rire délicieusement léger qui traversait la brume."
  },
  AvgDialog_120290_Content_73 = {
    Text = "Tu es là, ma petite jasmin."
  },
  AvgDialog_120290_Content_74 = {
    Text = "Juste avant d'être englouti par l'obscurité et l'étouffement, vous apercevez la foule, également prise dans la frénésie, abandonnant toute dignité alors qu'elle pousse en avant..."
  },
  AvgDialog_120290_Content_75 = {
    Text = "La silhouette de ton père, qui ne t'a même pas jeté un regard pendant un instant."
  },
  AvgDialog_120290_Content_8 = {
    Text = "<Shake:Creak—Yaa—>"
  },
  AvgDialog_120290_Content_9 = {
    Text = "Oh là là, pauvre chose, comment as-tu fini dans un endroit comme celui-ci ?"
  },
  AvgDialog_120291_Content_1 = {
    Text = "Apparition soudaine"
  },
  AvgDialog_120291_Content_10 = {
    Text = "Un morceau de pâtisserie poudreux et écoeurant, clairement pas raffiné, fut fourré dans ta bouche. Alors que le gâteau commençait à à peine se dissoudre, ta salive commença à couler sauvagement dans ta bouche."
  },
  AvgDialog_120291_Content_11 = {
    Text = "Tu suis de près l'autre personne, mâchant la pâtisserie. Juste au moment où ton estomac commence à se calmer, une pression plus forte saisit ton cœur."
  },
  AvgDialog_120291_Content_12 = {
    Text = "Ne restez pas là, mademoiselle, dépêchez-vous d'entrer, M. Xu vous attend depuis longtemps."
  },
  AvgDialog_120291_Content_13 = {
    Text = "Père était, comme toujours, entouré de nombreuses concubines dont vous ne pouvez pas vraiment vous souvenir des visages. Les concubines de la cour vont et viennent, chacune avec sa propre silhouette et son charme, vibrantes et vivantes."
  },
  AvgDialog_120291_Content_14 = {
    Text = "Mais maintenant, son regard est extrêmement confus, fixé sur une seule personne."
  },
  AvgDialog_120291_Content_15 = {
    Text = "La propriétaire de ces yeux d'une beauté déroutante jouait clairement un rôle distant mais poli par ennui, jusqu'à ce que son regard se pose doucement sur vous."
  },
  AvgDialog_120291_Content_16 = {
    Text = "Bien que je savais que tu descendrais après la cérémonie, je ne m'attendais pas à ce que tu sois si charmant."
  },
  AvgDialog_120291_Content_17 = {
    Text = "Je n'aurais pas dû t'envoyer au bordel, n'est-ce pas ! J'aurais dû te garder à mes côtés. Tout cela n'a plus de sens maintenant ; rien n'a d'importance sauf toi !"
  },
  AvgDialog_120291_Content_18 = {
    Text = "Monsieur He, s'il vous plaît ne soyez pas si formel. Nous pouvons discuter plus tard ; je suis venu aujourd'hui pour m'excuser."
  },
  AvgDialog_120291_Content_19 = {
    Text = "Que sait une fille stupide ? Aujourd'hui, je vais préparer des cadeaux pour le bordel encore une fois. Si tu les aimes, garde-les près de toi et enseigne-lui personnellement comment en prendre soin ?"
  },
  AvgDialog_120291_Content_2 = {Text = "新增"},
  AvgDialog_120291_Content_20 = {
    Text = "M. He a une attitude extraordinaire. Si nous sommes destinés à nous rencontrer, cela me procurera sûrement une grande joie."
  },
  AvgDialog_120291_Content_21 = {
    Text = "Je ressens une forte connexion avec cet enfant au premier regard, malgré nos conflits précédents... Si vous et moi devons nous rapprocher, elle doit également être en paix."
  },
  AvgDialog_120291_Content_22 = {
    Text = "La femme connue sous le nom de M. Xu s'approche de vous et se penche doucement."
  },
  AvgDialog_120291_Content_23 = {
    Text = "Je ne me suis pas encore présenté ; je m'appelle Xu. Alors, que pensez-vous, chère jeune dame de la famille He ?"
  },
  AvgDialog_120291_Content_24 = {
    Text = "Xu est parvenu devant vous d'une manière ou d'une autre. Instinctivement, vous saisissez la main de la femme qui vous a amené ici, souhaitant vous cacher derrière elle."
  },
  AvgDialog_120291_Content_25 = {
    Text = "Ses doigts jade caressent ton menton, le soulevant doucement, et tu revois ces yeux encore une fois.\nSi semblables à ta mère, mais si beaux qu'ils te remplissent d'effroi."
  },
  AvgDialog_120291_Content_26 = {
    Text = "Je... Je..."
  },
  AvgDialog_120291_Content_27 = {
    Text = "<Shake:Tout le monde qui t'a vu dans la rue est devenu fou. L'oncle en costume avait les yeux arrachés ! J'ai peur !>"
  },
  AvgDialog_120291_Content_28 = {
    Text = "Les mots enfantins qui ont échappé à ta bouche ont en fait stupéfié Xu un moment, puis il a ri si fort qu'il a presque perdu son calme."
  },
  AvgDialog_120291_Content_29 = {
    Text = "Quelle coïncidence. Du Langjun, juste à temps, pourrais-tu m'aider ? Petite Jasmine, regarde, est-ce ce gentleman dont nous parlons ?"
  },
  AvgDialog_120291_Content_3 = {
    Text = "Le choc d'être au centre d'une frénésie inconnue aurait dû détruire votre esprit, ou du moins votre volonté."
  },
  AvgDialog_120291_Content_30 = {
    Text = "En suivant son doigt qui s'éloigne de ton menton, tu remarques qu'il y a derrière les tantes jalouses un autre homme toujours vêtu de ce costume."
  },
  AvgDialog_120291_Content_31 = {
    Text = "C'est lui. Hein ? Pourquoi ses yeux sont-ils encore là ?"
  },
  AvgDialog_120291_Content_32 = {
    Text = "Son visage n'est plus ensanglanté, et ses yeux sont à leur place ; tu l'as vraiment reconnu."
  },
  AvgDialog_120291_Content_33 = {
    Text = "Quand mère était encore là, toi et père alliez à des banquets. Père a essayé de lui parler plusieurs fois, mais chaque fois il a été confronté à un rejet et est rentré dans une colère noire."
  },
  AvgDialog_120291_Content_34 = {
    Text = "Est-ce la petite fille qui avait peur ce jour-là ? Vaut-elle vraiment tous tes efforts, m'envoyant tout ce chemin pour lui acheter de la nourriture ?"
  },
  AvgDialog_120291_Content_35 = {
    Text = "La famille He ne peut même pas gérer sa propre fille hystérique, et pourtant elle veut s'immiscer dans le commerce d'import-export de Haicheng. Quelle absurdité."
  },
  AvgDialog_120291_Content_36 = {
    Text = "Ma fille est alitée et de mauvaise humeur depuis le décès de ma femme, ce qui a dû amuser M. Du. Je vais m'en occuper tout de suite..."
  },
  AvgDialog_120291_Content_37 = {
    Text = "Voyant l'expression sombre de ton père, tu es resté figé sur place, mais bientôt, tu as senti un parfum de magnolia. Tu étais tenu dans les bras de Xu, te pinçant et te pétrissant sans précaution."
  },
  AvgDialog_120291_Content_38 = {
    Text = "Du Langjun, j'ai dit que j'aimais cette jeune fille de la famille He. Si tu te disputes avec elle et que tu prends les choses au sérieux, je ne serai pas content—si je ne suis pas content, que feras-tu ?"
  },
  AvgDialog_120291_Content_39 = {
    Text = "En entendant cela, le regard auparavant dédaigneux de l'homme qui te scrutait de haut en bas perdit soudainement son intensité. Puis, il balança son bras et commença à se frapper le visage à plusieurs reprises."
  },
  AvgDialog_120291_Content_4 = {
    Text = "Mais cette conscience est encore trop petite, comme une éphémère. Non, simplifions encore davantage. Un paramécie, ou un autre organisme unicellulaire. Tu sais seulement que tu dois être rassasié, rester au chaud et rechercher des avantages tout en évitant les dangers."
  },
  AvgDialog_120291_Content_40 = {
    Text = "Son visage enfla instantanément, mais il semblait ne ressentir aucune douleur, ouvrant la bouche de manière engourdie pour révéler un sourire semblable à celui d'un mannequin que l'on pourrait voir dans une foire occidentale."
  },
  AvgDialog_120291_Content_41 = {
    Text = "J'ai mal parlé !"
  },
  AvgDialog_120291_Content_42 = {
    Text = "Je dis quelque chose de mal, je dis quelque chose de mal !"
  },
  AvgDialog_120291_Content_43 = {
    Text = "Avec le bruit d'une claque, Xu a joyeusement sorti un sachet de bonbons de sa poche, en a pris un morceau et l'a fourré dans ta bouche."
  },
  AvgDialog_120291_Content_44 = {
    Text = "Comme c'est étrange ! Mademoiselle He aime-t-elle jeter un coup d'œil ?"
  },
  AvgDialog_120291_Content_45 = {
    Text = "Le doux nectar fond, et tu regardes fixement tout ce qui est devant toi. Enfin, tu relèves la tête pour regarder Xu."
  },
  AvgDialog_120291_Content_46 = {
    Text = "...Le bonbon au sirop de poire du Temple du Dieu de la Ville, ma mère l'achetait pour moi."
  },
  AvgDialog_120291_Content_47 = {
    Text = "Monsieur Xu, es-tu Maman ?"
  },
  AvgDialog_120291_Content_48 = {
    Text = "Xu ne vous a pas répondu, souriant sans cesse, tandis que les concubines et le père se tenaient là comme s'ils étaient ensorcelés, silencieux et immobiles."
  },
  AvgDialog_120291_Content_49 = {
    Text = "Du Langjun, regarde-toi. Je faisais juste un petit caprice. Tu m'as frappé si fort que ça me fait mal au cœur."
  },
  AvgDialog_120291_Content_5 = {
    Text = "Alors tu es de nouveau bercé par cette cage de brume, ouvrant les yeux sans dommage."
  },
  AvgDialog_120291_Content_50 = {
    Text = "Dès que l'homme s'arrêta, les concubines semblèrent sortir d'un état d'abrutissement, regardant M. Du, dont les joues avaient pris une teinte bleuâtre-violette, avec choc et confusion."
  },
  AvgDialog_120291_Content_51 = {
    Text = "Je me souviens que M. He avait quelque chose à discuter avec le Seigneur Du, alors j'ai pris la liberté d'apporter ce cadeau de visite."
  },
  AvgDialog_120291_Content_52 = {
    Text = "Jeune dame de la famille He, lorsque vous discutez des affaires, seriez-vous disposée à m'emmener faire une promenade ?"
  },
  AvgDialog_120291_Content_53 = {
    Text = "Avant de sortir de la pièce, vous ne pouviez pas vous empêcher de jeter un coup d'œil à votre père. Son visage ne portait pas l'expression vide et étrange de M. Du et des tantes, mais il tolérait silencieusement tout."
  },
  AvgDialog_120291_Content_54 = {
    Text = "M. Xu, vous..."
  },
  AvgDialog_120291_Content_55 = {
    Text = "Tu as beaucoup de questions à poser, n'est-ce pas ?"
  },
  AvgDialog_120291_Content_56 = {
    Text = "Ne te précipite pas... mon cher bébé, mon bon bébé."
  },
  AvgDialog_120291_Content_57 = {
    Text = "Ma petite jasmin... viens, regarde-moi."
  },
  AvgDialog_120291_Content_58 = {
    Text = "L'obscurité pesante s'abat, et sous la lune argentée aussi blanche que l'os, Xu déplace l'éventail, tandis que la brume vaporeuse se précipite vers toi, t'enveloppant et t'engloutissant."
  },
  AvgDialog_120291_Content_59 = {
    Text = "Vaguement, Mère te regarde à la lumière chaude, souriant doucement alors qu'elle s'incline avec les bras grands ouverts."
  },
  AvgDialog_120291_Content_6 = {
    Text = "Le ciel est complètement assombri, et les fenêtres des autres chambres reflètent une lueur de bougie lointaine, alors que des pas faibles et éparpillés se rapprochent à nouveau."
  },
  AvgDialog_120291_Content_60 = {
    Text = "Comme une corde qui se rompt soudainement, une vague d'émotion te submerge et les larmes floutent complètement ta vision. Sans hésitation, tu la tiens fermement dans tes bras."
  },
  AvgDialog_120291_Content_61 = {
    Text = "Maman, peux-tu s'il te plaît ne pas repartir."
  },
  AvgDialog_120291_Content_62 = {
    Text = "Waaah, waaahhh, mon esprit est si confus, j'ai si peur. Tu me manques tellement ! Maman."
  },
  AvgDialog_120291_Content_63 = {
    Text = "La femme t'enlace doucement, caressant doucement ton dos."
  },
  AvgDialog_120291_Content_64 = {
    Text = "La précieuse petite fille de maman, la gentille petite fille de maman."
  },
  AvgDialog_120291_Content_65 = {
    Text = "Mon cher bébé, mon bon bébé."
  },
  AvgDialog_120291_Content_66 = {
    Text = "Que serais-tu prêt à sacrifier pour être avec maman pour toujours ?"
  },
  AvgDialog_120291_Content_67 = {
    Text = "Le brouillard semble vous envelopper à nouveau, et vous entendez le son de votre propre murmure."
  },
  AvgDialog_120291_Content_68 = {
    Text = "Tout va... Tout va bien."
  },
  AvgDialog_120291_Content_69 = {
    Text = "La maison entière est-elle disponible ?"
  },
  AvgDialog_120291_Content_7 = {
    Text = "Oh là là, mademoiselle, vous m'avez fait peur à mort. Courir dans la rue dans un accès de colère, essayez-vous de nous faire tuer, nous les gens ordinaires ?"
  },
  AvgDialog_120291_Content_70 = {
    Text = "Je ne veux pas de la maison, je veux juste maman."
  },
  AvgDialog_120291_Content_71 = {
    Text = "Toute la maison, toute la ville de Haicheng, et ton père, est-ce qu'on peut tous les faire ?"
  },
  AvgDialog_120291_Content_72 = {
    Text = "Père... Papa..."
  },
  AvgDialog_120291_Content_73 = {
    Text = "Tu as été distrait un instant, te rappelant soudain les nuits où ta mère attendait patiemment avec toi, et la main qui se posait sur ta tête lorsque ton père rentrait à la maison."
  },
  AvgDialog_120291_Content_74 = {
    Text = "Pas de soucis, il y a encore beaucoup de temps, petite Jasmine."
  },
  AvgDialog_120291_Content_75 = {
    Text = "On dirait que quelqu'un te soulève, te faisant tomber dans un lit doux, où quelque chose d'encore plus chaud et plus tendre t'enlace intimement."
  },
  AvgDialog_120291_Content_76 = {
    Text = "Il est déjà tard dans la nuit, alors dors. Je serai à tes côtés très bientôt, très bientôt."
  },
  AvgDialog_120291_Content_77 = {
    Text = "Après le départ de ta mère, tu as ressenti pour la première fois une sensation de soulagement sans pareille, accompagnée de la somnolence qui a suivi, s'enfonçant dans un rêve profond et doux."
  },
  AvgDialog_120291_Content_8 = {
    Text = "<Shake:Glug—>"
  },
  AvgDialog_120291_Content_9 = {
    Text = "...Sigh, je me sens vraiment désolé pour toi. Dépêche-toi de mâcher. Le maître attend déjà dans le hall, ne me cause pas plus de problèmes, compris ?"
  },
  AvgDialog_120296_Content_1 = {
    Text = "Oh, mon cher"
  },
  AvgDialog_120296_Content_10 = {
    Text = "D'accord, mets de côté tes petites pensées. Ne dis pas que je te fais peur ; ce manoir n'est pas sûr. Toutes les femmes que le seigneur aimait ont disparu à la fin."
  },
  AvgDialog_120296_Content_11 = {
    Text = "Même son ex-femme, son amour d'enfance, qui aurait été décédée d'une maladie, qui sait que c'était..."
  },
  AvgDialog_120296_Content_12 = {
    Text = "Oh non ! Pourquoi tu me pousses !"
  },
  AvgDialog_120296_Content_13 = {
    Text = "Madame, je suis vraiment... je suis vraiment désolé. Ma sœur a tendance à parler sans réfléchir, s'il vous plaît, ne prêtez pas attention à ses absurdités. Nous ne voulons absolument pas vous offenser, je vous en prie, ne dites pas cela au maître."
  },
  AvgDialog_120296_Content_14 = {
    Text = "Tirée brusquement en arrière par sa sœur, la concubine aux sourcils finement dessinés et au maquillage exquis reprit ses esprits, son visage devenant instantanément pâle de peur alors qu'elle se couvrait rapidement la bouche pour se taire."
  },
  AvgDialog_120296_Content_15 = {
    Text = "Puisque cette maison n'est pas sûre, pourquoi n'as-tu pas pensé à trouver un autre endroit ?"
  },
  AvgDialog_120296_Content_16 = {
    Text = "...Où d'autre pouvons-nous aller ? Si nous pouvions être chéris comme des bijoux par la noblesse, alors nous pourrions vraiment aller n'importe où."
  },
  AvgDialog_120296_Content_17 = {
    Text = "Hehe, le tenir comme un bijou précieux ?"
  },
  AvgDialog_120296_Content_18 = {
    Text = "Xu éclata soudainement de rire, et à ce moment-là, plusieurs concubines dans le couloir entendirent un genre de rire chuchoté plus insaisissable."
  },
  AvgDialog_120296_Content_19 = {
    Text = "Leurs regards devinrent flous alors qu'ils levaient les yeux, perplexes, observant la femme s'enfoncer plus profondément dans le couloir."
  },
  AvgDialog_120296_Content_2 = {
    Text = "Le nouvel arrivant a quelques tours dans son sac."
  },
  AvgDialog_120296_Content_20 = {
    Text = "Ma petite jasmin dort ; ne la réveillons pas. Suis-moi."
  },
  AvgDialog_120296_Content_21 = {
    Text = "Je vais vous faire comprendre, mon seigneur, qu'une personne noble, tout comme un objet précieux, n'est intéressante que lorsqu'elle est délicatement tenue entre les doigts."
  },
  AvgDialog_120296_Content_22 = {
    Text = "Les concubines arboraient un sourire stupide sur leurs visages, puis la brume obscurcit leurs lèvres, tandis que les éventails couvraient leurs visages."
  },
  AvgDialog_120296_Content_23 = {
    Text = "Le parfum sucré et riche de magnolia se répandait doucement dans tout le manoir."
  },
  AvgDialog_120296_Content_24 = {Text = "新增"},
  AvgDialog_120296_Content_25 = {
    Text = "Après que Xu a été amenée dans la résidence de He en tant que belle-mère, tu n'as plus jamais eu faim. Tout le monde t'a traité chaleureusement et gentiment, comme si tu étais encore cette jeune dame de l'époque où ta mère était présente."
  },
  AvgDialog_120296_Content_26 = {
    Text = "Mais père n'est jamais sorti de sa chambre, et Xu n'y était jamais entré ; au lieu de cela, les concubines semblaient être attirées par des fils invisibles, venant et allant fréquemment de la chambre de Xu."
  },
  AvgDialog_120296_Content_27 = {
    Text = "Oh là là, mademoiselle, pourriez-vous s'il vous plaît aider ? Le maître a spécifiquement ordonné que personne ne doit s'approcher de sa chambre."
  },
  AvgDialog_120296_Content_28 = {
    Text = "Ça fait si longtemps que je n'ai pas vu papa. Je vais juste jeter un coup d'œil de loin, je promets que je ne vais pas le déranger."
  },
  AvgDialog_120296_Content_29 = {
    Text = "Cependant, avant que tu ne puisses t'approcher, tu as entendu un grognement rauque, frénétique et anormalement excité venant de l'intérieur de la pièce."
  },
  AvgDialog_120296_Content_3 = {
    Text = "Tu as une langue acérée, mais tu ne peux pas te résoudre à te séparer du éventail qu'elle t'a donné, n'est-ce pas ?"
  },
  AvgDialog_120296_Content_30 = {
    Text = "Xu... mon très cher, mon sauveur, mon cœur, je ne peux plus te laisser partir, tu es à moi, tu ne peux être qu'à moi."
  },
  AvgDialog_120296_Content_31 = {
    Text = "Leur sang et leurs os ne sont rien... Peu importe combien, ah ! Tant que cela peut te ramener, tant que cela peut te ramener, cela en vaut la peine !"
  },
  AvgDialog_120296_Content_32 = {
    Text = "Je comprends, je vois ! Haha, hahahaha !!!"
  },
  AvgDialog_120296_Content_33 = {
    Text = "Le bruit glissant et serpentant semblait glisser sur le sol, jusqu'à ce qu'enfin, un souffle provenant de quelque part se transforme en un court et vif halètement semblable à celui d'un soufflet étouffé, comme si quelque chose l'enveloppait, rendant la respiration difficile."
  },
  AvgDialog_120296_Content_34 = {Text = "Dad!"},
  AvgDialog_120296_Content_35 = {
    Text = "Tu as été surpris par sa voix semblable à la mort et tu as couru pour pousser la porte."
  },
  AvgDialog_120296_Content_36 = {
    Text = "À l'intérieur, seul He Fang était frénétiquement adossé au bord du lit, s'effondrant sur la literie sombre, qui était humide comme si elle avait été trempée, tout comme la cabine entière."
  },
  AvgDialog_120296_Content_37 = {
    Text = "Des fragments brisés d'objets et de tissus étaient horriblement éparpillés autour. Il revint à la réalité, son visage couvert d'une teinte anormale et malsaine, et il saisit un coussin en bois pour le frapper sur vous."
  },
  AvgDialog_120296_Content_38 = {
    Text = "Qui t'a laissé entrer !"
  },
  AvgDialog_120296_Content_39 = {
    Text = "Personne ne peut troubler notre solitude, sors ! Va-t'en !"
  },
  AvgDialog_120296_Content_4 = {
    Text = "Ge Mei est belle, a bon goût et ses cadeaux sont impressionnants. Ne te sens-tu pas aussi en train de te rafraîchir d'un côté à l'autre, souhaitant pouvoir lui ressembler, avec un éventail sur le visage ?"
  },
  AvgDialog_120296_Content_40 = {
    Text = "La femme te suivit rapidement, fermant la porte à la hâte au milieu du rugissement venant de quelque part."
  },
  AvgDialog_120296_Content_41 = {
    Text = "Je t'ai dit de ne pas déranger mon seigneur, il va se fâcher. Ne cours pas partout, ma petite tante."
  },
  AvgDialog_120296_Content_42 = {
    Text = "Père... Père, que se passe-t-il ? Pourquoi continue-t-il d'appeler le nom de M. Xu ?"
  },
  AvgDialog_120296_Content_43 = {
    Text = "<Shake:M. Xu est clairement sorti tôt ce matin. À qui parle-t-il ? Son expression est si effrayante...>"
  },
  AvgDialog_120296_Content_44 = {
    Text = "Les affaires concernant mon seigneur ne sont pas à gérer par nous, serviteurs humbles."
  },
  AvgDialog_120296_Content_45 = {
    Text = "Tu titubes vers l'endroit que tu connais le mieux, espérant trouver quelqu'un pour t'aider."
  },
  AvgDialog_120296_Content_46 = {
    Text = "La chambre de la dame, maintenant la chambre de Xu, est aussi la chambre où ma mère est restée une fois."
  },
  AvgDialog_120296_Content_47 = {
    Text = "La porte, qui s'est ternie depuis le départ de Maman, est à nouveau ornée de sculptures dorées, comme si elle était devenue une sorte d'entrée, chaque ouverture et fermeture libérant un parfum endormissant et d'un autre monde."
  },
  AvgDialog_120296_Content_48 = {
    Text = "Haha, hihihi... Wuwuwuwu... Il s'avère que j'avais tort depuis le début, complètement dans l'erreur !"
  },
  AvgDialog_120296_Content_49 = {
    Text = "Coupe, frappe, ouvre-le ! Ouvre-le simplement, il est encore fumant, offert à Lui, et ils obéiront. Je n'aurai plus à souffrir dans la mer de souffrance !"
  },
  AvgDialog_120296_Content_5 = {
    Text = "Tu parles de moi ?"
  },
  AvgDialog_120296_Content_50 = {
    Text = "<Change>Xu... notre Sauveur, notre @3 !"
  },
  AvgDialog_120296_Content_51 = {
    Text = "Le brouillard intangible remplissait toute la pièce alors qu'ils levaient avec révérence les éventails qui leur avaient été offerts le jour où Xu était entré dans la maison, pleurant et riant, se transformant progressivement en un gémissement bizarre."
  },
  AvgDialog_120296_Content_52 = {
    Text = "Tu ne comprends pas un mot de ce que disent les servantes dans la pièce ; tes oreilles sont remplies de bourdonnement et des battements de ton cœur. Tu recules à nouveau, heurtant accidentellement la balustrade et faisant du bruit."
  },
  AvgDialog_120296_Content_53 = {
    Text = "...ouais, il y a un bruit."
  },
  AvgDialog_120296_Content_54 = {
    Text = "<Shake:<Red:Est-ce une autre offrande de sang qui peut être présentée?>>"
  },
  AvgDialog_120296_Content_55 = {
    Text = "Leurs voix portent un léger rire, et tous les cris ont disparu, une inexplicable et glaciale sensation de terreur vous envahit !"
  },
  AvgDialog_120296_Content_56 = {Text = "Run!!!!"},
  AvgDialog_120296_Content_57 = {
    Text = "C'est la terreur d'être la proie, la peur qui réside profondément dans les lignées de sang de toutes les créatures depuis la nuit des temps !"
  },
  AvgDialog_120296_Content_58 = {
    Text = "Oh ? Une simple boîte de crackers en forme de papillon, et ma Petite Jasmine se précipite dans mes bras avec tant de joie ?"
  },
  AvgDialog_120296_Content_59 = {
    Text = "Les bras semblables à du jade t'ont attrapé juste avant que tu ne tombes. Si tu regardes à travers les interstices de la clôture de la cour, le célèbre inspecteur Huang de Haicheng ferme la porte de la voiture pour elle."
  },
  AvgDialog_120296_Content_6 = {
    Text = "*Exclaim Ah ! Désolé, madame !"
  },
  AvgDialog_120296_Content_60 = {
    Text = "La boîte de pâtisserie vous est remise, et les motifs en couches en forme d'œil sur le papier fleuri vous effraient complètement. Vous prenez une profonde inspiration, rassemblant votre courage, et la renversez sur le sol."
  },
  AvgDialog_120296_Content_61 = {
    Text = "Qui es-tu ?! Pourquoi es-tu dans notre maison ?! Que s'est-il passé avec ma famille, mon père, ma tante, ces oncles ? Depuis que tu es arrivé, tout le monde agit de manière étrange..."
  },
  AvgDialog_120296_Content_62 = {
    Text = "Oups... ce n'est qu'une petite chose, regarde, ma petite jasmin pleure même."
  },
  AvgDialog_120296_Content_63 = {
    Text = "Elle n'était pas en colère à propos du goûter que tu as renversé ; au contraire, elle s'est penchée affectueusement et a doucement touché le coin de ton œil où des larmes s'étaient formées par la peur."
  },
  AvgDialog_120296_Content_64 = {
    Text = "Ma petite jasmin, est-ce vraiment chez toi, un endroit où même une goutte d'eau ne peut être trouvée ?"
  },
  AvgDialog_120296_Content_65 = {
    Text = "Mademoiselle ! Juste un instant sans regarder, comment avez-vous pu... Madame, je suis désolé, c'est entièrement ma faute de ne pas avoir gardé un œil sur la jeune dame."
  },
  AvgDialog_120296_Content_66 = {
    Text = "Xu ignora les personnes qui se précipitaient et te serra plus fort, comme toujours, caressant ton dos comme on le ferait pour un petit animal, sa voix douce et délicate."
  },
  AvgDialog_120296_Content_67 = {
    Text = "Petit jasmin, réfléchis bien. Qu'est-ce qui se passe avec cette affaire, et qu'en est-il de celle-là ? Quel est le lien entre elles ?"
  },
  AvgDialog_120296_Content_68 = {
    Text = "Tant que tu te comportes bien et que tu m'écoutes obéissamment tout le temps."
  },
  AvgDialog_120296_Content_69 = {
    Text = "Tout peut être à toi, et tout le monde peut devenir ton jouet."
  },
  AvgDialog_120296_Content_7 = {
    Text = "Tch, quelle dame ? Juste une femme aux longs cheveux d'une librairie, de quoi a-t-elle peur ? Peut-elle vraiment te manger ?"
  },
  AvgDialog_120296_Content_70 = {
    Text = "Elle te caresse du dos jusqu'aux cheveux, et après avoir enfin joué suffisamment avec tes cheveux, elle lâche prise, dégageant une sensation de joie."
  },
  AvgDialog_120296_Content_71 = {
    Text = "Voilà. Emmène ma petite jasmin au lit... elle a besoin de se reposer."
  },
  AvgDialog_120296_Content_72 = {
    Text = "Vous avez marché loin dans le brouillard, et dans la brume grise, vous voyez une vaste étendue d'eau sombre."
  },
  AvgDialog_120296_Content_73 = {
    Text = "D'innombrables membres visqueux et serpentinés, couverts de ventouses, reposent à la frontière de l'eau et de la brume, tandis qu'une silhouette douce est assise, le dos tourné vers toi, au bord de l'eau."
  },
  AvgDialog_120296_Content_74 = {
    Text = "Maman ? C'est toi ?"
  },
  AvgDialog_120296_Content_75 = {
    Text = "<Shake:...Faux... tout... cours...>"
  },
  AvgDialog_120296_Content_76 = {
    Text = "Maman, que dis-tu ? Je ne t'entends pas clairement."
  },
  AvgDialog_120296_Content_77 = {
    Text = "Tu t'es approché et as soudain réalisé qu'elle n'était pas assise près de l'eau ; au lieu de cela, sa moitié inférieure s'était transformée en d'innombrables tentacules, se fondant dans l'eau grise."
  },
  AvgDialog_120296_Content_78 = {
    Text = "<Shake:Faux. Tout est faux.>"
  },
  AvgDialog_120296_Content_79 = {
    Text = "<Shake:Elle n'est pas... Ce n'est pas...>"
  },
  AvgDialog_120296_Content_8 = {
    Text = "Regardez-vous tous, vous ressemblez à une bande de chats duveteux ; c'est tellement mignon."
  },
  AvgDialog_120296_Content_80 = {
    Text = "La femme se retourna, son visage familier strié de larmes grises, hurlant et criant vers vous."
  },
  AvgDialog_120296_Content_81 = {
    Text = "<Red:Elle a le visage de sa mère.>"
  },
  AvgDialog_120296_Content_82 = {
    Text = "<Change>Il n'est pas ! Il n'est pas ! Il n'est pas ! Il n'est pas !!"
  },
  AvgDialog_120296_Content_83 = {
    Text = "<Red:<Shake:Faux ! Tout faux !! Nānnān !!! Courez !! VITE !! COUREZ !!!>>"
  },
  AvgDialog_120296_Content_9 = {
    Text = "Ne vous inquiétez pas, je suis juste nouveau ici. Je vous ai tous vus discuter si joyeusement et j'ai pensé venir et partager un petit murmure."
  },
  AvgDialog_120297_Content_1 = {
    Text = "Sang du Sire"
  },
  AvgDialog_120297_Content_10 = {
    Text = "Parfois, c'étaient eux-mêmes, et parfois, c'étaient leurs épouses. À ces moments-là, le sourire sur le visage de Xu devenait plus prononcé. Lorsqu'ils revenaient une deuxième fois, les mêmes fans noirs que ceux de la cour apparaissaient dans leurs mains."
  },
  AvgDialog_120297_Content_100 = {
    Text = "Cependant, le redoutable et menaçant He Fang avait étonnamment adouci son expression."
  },
  AvgDialog_120297_Content_101 = {
    Text = "Le penses-tu vraiment ?"
  },
  AvgDialog_120297_Content_102 = {
    Text = "He Lang sait que bien que je possède un pouvoir divin, je suis toujours lié à celui qui m'éveille. Quoi que He Lang me commande de faire, je ne peux que m'y conformer ; il n'y a aucune possibilité de te tromper ?"
  },
  AvgDialog_120297_Content_103 = {
    Text = "Tout comme dans la ruelle, tu ne peux ni parler ni bouger. On dirait que cette étrange « déesse » est déterminée à faire de toi un spectateur de cette farce."
  },
  AvgDialog_120297_Content_104 = {
    Text = "Il s'éloigna joyeusement, tout comme ce jour-là devant le Pavillon d'Or, sans même te jeter un autre regard."
  },
  AvgDialog_120297_Content_105 = {
    Text = "Au moment où tu peux émettre un son, tu te retournes et sautes sur Xu, poussant un cri bestial. Pieds, poings, dents—malgré le fait que tu saches que c'est vain, tu utilises toutes les méthodes d'attaque que tu connais."
  },
  AvgDialog_120297_Content_106 = {
    Text = "Rends-le-moi, rends-moi maman, rends-moi papa !"
  },
  AvgDialog_120297_Content_107 = {
    Text = "Xu Zhi Shan reste immobile, te permettant de te défouler sans bouger. Le sourire dans ses yeux te fait oublier ta peur, ne laissant que de la colère et du désespoir."
  },
  AvgDialog_120297_Content_108 = {
    Text = "Tout est à cause de toi ; tu n'es pas une déesse du tout, tu es un monstre !"
  },
  AvgDialog_120297_Content_109 = {
    Text = "La femme devant moi... hocha la tête."
  },
  AvgDialog_120297_Content_11 = {
    Text = "Si nous attendons plus longtemps, nous ne verrons même plus l'ombre de M. Xu. Dépêche-toi."
  },
  AvgDialog_120297_Content_110 = {
    Text = "C'est vrai, ma petite jasmin, je suis un monstre."
  },
  AvgDialog_120297_Content_111 = {
    Text = "Mais la mort de ta mère n'a rien à voir avec moi ; c'est lui qui a tué d'innombrables femmes, y compris elle, juste pour m'invoquer en échange de sa richesse et de son pouvoir."
  },
  AvgDialog_120297_Content_112 = {
    Text = "Tout à l'heure, il voulait te tuer. Tu ne veux pas mourir, et je t'ai répondu. Si je t'abandonnais, tu mourrais sans aucun doute, n'est-ce pas ?"
  },
  AvgDialog_120297_Content_113 = {Text = "新增"},
  AvgDialog_120297_Content_114 = {
    Text = "Tu restais sans voix, sa voix pleine d'enthousiasme, et ses beaux yeux brillaient de joie."
  },
  AvgDialog_120297_Content_115 = {
    Text = "Alors, ma petite jasmin, comment vas-tu choisir ?"
  },
  AvgDialog_120297_Content_116 = {
    Text = "Tu ouvris la bouche en vain, te contentant finalement de la regarder, perdu dans tes pensées, le bourdonnement aigu dans tes oreilles agitant tes nerfs. Elle te donna simplement une tape dans le dos avant de s'engager dans la cour."
  },
  AvgDialog_120297_Content_117 = {
    Text = "Hehe... Bientôt. Très, très bientôt... le moment viendra pour toi de faire le choix final."
  },
  AvgDialog_120297_Content_118 = {Text = "新增"},
  AvgDialog_120297_Content_119 = {
    Text = "Des scènes de la journée se rejouent dans tes rêves. Tu te réveilles en criant au milieu de la nuit, et la maison est étrangement silencieuse. Personne ne te répond, et cette voix perçante n'existe plus."
  },
  AvgDialog_120297_Content_12 = {
    Text = "La rickshaw a été secouée violemment. Bien que cela soit passé inaperçu, après avoir tourné et viré, elle a perdu la poursuite lorsque le véhicule est entré dans un bosquet d'arbres."
  },
  AvgDialog_120297_Content_120 = {
    Text = "La faim vous ronge les entrailles, et après vous être recroquevillé pendant longtemps, vous vous levez enfin et, guidé par la mémoire, vous trouvez la boîte de pâtisseries brisées. Silencieusement, vous vous tenez sous la lumière de la lune et les mangez toutes."
  },
  AvgDialog_120297_Content_121 = {
    Text = "Alors que tu t'endormais à nouveau, tu es revenu au bord de l'eau grise, où ta mère tendait ses bras semblables à des tentacules, te tendant la main. Derrière elle, une autre forme massive pouvait être vaguement aperçue."
  },
  AvgDialog_120297_Content_122 = {
    Text = "Maman, elle est toujours là ?"
  },
  AvgDialog_120297_Content_123 = {
    Text = "Maman sera toujours avec toi."
  },
  AvgDialog_120297_Content_124 = {
    Text = "Je serai toujours, toujours aux côtés de ma petite jasmin."
  },
  AvgDialog_120297_Content_125 = {
    Text = "Deux voix résonnèrent dans tes oreilles en même temps, et tu n'as pas posé d'autres questions. Tu étais juste trop fatigué et trop effrayé."
  },
  AvgDialog_120297_Content_126 = {
    Text = "Tu plonges sans hésitation dans cette étreinte terrifiante, collante mais incroyablement douce."
  },
  AvgDialog_120297_Content_13 = {
    Text = "On t'a conduit loin, et pour une raison quelconque, ton cœur s'accélérait de plus en plus. La seule chose qui te faisait te sentir un peu mieux était de tenir fermement la main de la femme."
  },
  AvgDialog_120297_Content_14 = {
    Text = [[
Le ciel s'assombrissait progressivement, et la lune gravissait silencieusement les cimes des arbres.
Soudain, la femme te fit un geste de silence.]]
  },
  AvgDialog_120297_Content_15 = {Text = "Chut—"},
  AvgDialog_120297_Content_16 = {
    Text = "Au loin, la silhouette de Xu est apparue, la voiture blanche s'éloignant à toute vitesse, tandis que M. Du se tenait silencieusement à ses côtés. Dans un coin, plusieurs longues ombres passaient à travers les arbres et étaient projetées sur le sol par la lumière de la lune."
  },
  AvgDialog_120297_Content_17 = {
    Text = "M. Du, l'inspecteur Huang, le chef de l'École du Transport Fluvial du Nord, et sur la route principale, oh là là, M. Xu est vraiment remarquable..."
  },
  AvgDialog_120297_Content_18 = {
    Text = "Au loin, les visages des hommes apparaissaient avec une rougeur anormale, semblable à celle du père ce jour-là. Cela a commencé par de doux murmures, qui ont ensuite dégénéré en cris sifflants rapides et excités, presque comme des chants."
  },
  AvgDialog_120297_Content_19 = {
    Text = "<Shake:Elle... ne peut pas... rester...>"
  },
  AvgDialog_120297_Content_2 = {
    Text = "Toutes les concubines deviennent de plus en plus comme Xu, et père n'est pas sorti de la maison depuis."
  },
  AvgDialog_120297_Content_20 = {
    Text = "<Shake:Tuer... seulement alors...>"
  },
  AvgDialog_120297_Content_21 = {
    Text = "<Shake:Tuez... Tuez... TUEZ !! Tuez-la—Hachez-la en morceaux !!!>"
  },
  AvgDialog_120297_Content_22 = {
    Text = "<Change>À moi, à moi, à moi, à moi, à moi, à moi, elle est à moi !!"
  },
  AvgDialog_120297_Content_23 = {
    Text = "La lumière pâle perça vos yeux, et ce n'est qu'alors que vous réalisâtes qu'un fauchon se cachait derrière chaque homme, maintenant levé haut à l'unisson—"
  },
  AvgDialog_120297_Content_24 = {
    Text = "Ha—hahaha, ahhahahahahaha !!!"
  },
  AvgDialog_120297_Content_25 = {
    Text = "Les hommes s'approchèrent progressivement, et Xu éclata soudainement de rire, comme s'il avait vu la chose la plus ridicule au monde, pointant du doigt leurs visages un par un."
  },
  AvgDialog_120297_Content_26 = {
    Text = "À la seconde suivante, des faux acérées s'abattirent de toutes parts, le bruit sourd de la chair déchirée, le craquement des os sectionnés, et une main aussi blanche que du jade fut projetée en l'air."
  },
  AvgDialog_120297_Content_27 = {
    Text = "Cui cui, craque."
  },
  AvgDialog_120297_Content_28 = {
    Text = "Mmm, hmm hmm hmm hmm hmm hmm !"
  },
  AvgDialog_120297_Content_29 = {
    Text = "Tu es fermement tenu dans ses bras, ses mains couvrant fortement ta bouche, étouffant les cris agonisants qui menacent de s'échapper."
  },
  AvgDialog_120297_Content_3 = {
    Text = "La mère n'apparaît plus dans tes rêves. Parfois, tu rêves du visage de Xu sous chaque ventilateur, et parfois, tu rêves de ton père dévoré par un monstre, te réveillant en sueur froide à la fin."
  },
  AvgDialog_120297_Content_30 = {
    Text = "<Change>Tête, cou, poitrine, bras, abdomen..."
  },
  AvgDialog_120297_Content_31 = {
    Text = "<Shake:Percez le crâne, percez le cou, percez la cavité thoracique, percez les bras, percez l'abdomen...>"
  },
  AvgDialog_120297_Content_32 = {
    Text = "<Change>Foret des crânes, foret du cou, foret de la cavité thoracique, foret de..."
  },
  AvgDialog_120297_Content_33 = {Text = "Monsieur."},
  AvgDialog_120297_Content_34 = {
    Text = "Doux, flirtatious et sucré."
  },
  AvgDialog_120297_Content_35 = {
    Text = "Si loin, comme une brume, cela tourbillonne autour des contours de ton oreille et pénètre dans ton esprit."
  },
  AvgDialog_120297_Content_36 = {
    Text = "La brume de sang s'assombrit progressivement, et une à une, des silhouettes émergèrent des cadavres, leurs bras aussi blancs que le jade s'écoulant de boue noire, levés haut."
  },
  AvgDialog_120297_Content_37 = {
    Text = "Ça fait tellement mal, s'il te plaît, embrasse-moi—"
  },
  AvgDialog_120297_Content_38 = {
    Text = "<Change>Je, @3, donne-moi un baiser..."
  },
  AvgDialog_120297_Content_39 = {
    Text = "<Change>Je, @3, donne @4 à moi !"
  },
  AvgDialog_120297_Content_4 = {
    Text = "Mademoiselle, s'il vous plaît, arrêtez de faire des caprices. M. Xu est si bon avec vous, il vous apporte tant de nourriture fraîche et de jouets chaque jour."
  },
  AvgDialog_120297_Content_40 = {
    Text = "<Change>Ça fait tellement mal, s'il te plaît, donne-moi un baiser !"
  },
  AvgDialog_120297_Content_41 = {
    Text = "Xu... un monstre ressemblant à Xu, leurs corps inférieurs fusionnés avec des cadavres brisés, la boue recouvrant entièrement leur visage, seules les contours de leurs lèvres étant exposés."
  },
  AvgDialog_120297_Content_42 = {
    Text = "Sur chaque visage de \"Xu\", il y avait des dizaines de lèvres charnues et belles, en forme de pétales, aspirant vers les hommes qui riaient follement comme s'ils étaient sous un sort."
  },
  AvgDialog_120297_Content_43 = {
    Text = "<Change>Moulin—Moulin—"
  },
  AvgDialog_120297_Content_44 = {
    Text = "Le bruit des crânes écrasés, le bruit des crânes se brisant."
  },
  AvgDialog_120297_Content_45 = {
    Text = "<Change>Slurp—Glug—"
  },
  AvgDialog_120297_Content_46 = {
    Text = "Des bruits de succion, des bruits de mastication."
  },
  AvgDialog_120297_Content_47 = {
    Text = "Vous regardez, impuissant, alors que leurs têtes se brisent puis retrouvent une condition parfaite. Le \"Xu\" laisse échapper des soupirs de contentement et se regroupe au milieu des murmures satisfaits."
  },
  AvgDialog_120297_Content_48 = {
    Text = "M. Du, inspecteur Huang, le chef de l'École du Transport Fluvial du Nord..."
  },
  AvgDialog_120297_Content_49 = {
    Text = "Ils se sont levés silencieusement, comme si rien ne s'était jamais passé, s'éparpillant d'un air hébété, tandis que Xu avait depuis longtemps disparu sans laisser de trace."
  },
  AvgDialog_120297_Content_5 = {
    Text = "La femme soupira et utilisa un mouchoir pour essuyer la sueur surprise de ton front."
  },
  AvgDialog_120297_Content_50 = {
    Text = "Cette main a finalement lâché prise, et dans le silence suffocant, tes larmes ont coulé de manière incontrôlable. Au moment où tu t'es retourné, tes pupilles ont tremblé violemment."
  },
  AvgDialog_120297_Content_51 = {Text = "Oops!..."},
  AvgDialog_120297_Content_52 = {
    Text = "J'ai réfléchi à comment être honnête avec ma petite jasmin."
  },
  AvgDialog_120297_Content_53 = {
    Text = "Tes pupilles se contractent au maximum, et au final, il ne reste que la femme devant toi. En un instant, ton cerveau déjà submergé envoie une décharge de douleur intense."
  },
  AvgDialog_120297_Content_54 = {
    Text = "À quoi ressemble-t-elle, la femme à la voix aiguë ?"
  },
  AvgDialog_120297_Content_55 = {
    Text = "Les serviteurs dans votre chambre ont été renvoyés depuis longtemps lorsque votre mère est décédée."
  },
  AvgDialog_120297_Content_56 = {
    Text = "Personne ne s'est jamais soucier de ta vie ou de ta mort, et tu n'as jamais vraiment vu à quoi elle ressemblait, mais pourquoi tout le monde trouve-t-il son apparence si naturelle ?"
  },
  AvgDialog_120297_Content_57 = {
    Text = "Je me suis attaché à cette peau... J'aimais le parfum de jasmin qu'elle portait. Dès le tout début, je me suis demandé... à quoi ressemblerait ma \"Petite Jasmin\"—ma Petite Jasmin ?"
  },
  AvgDialog_120297_Content_58 = {
    Text = "Alors, cela fait longtemps, très longtemps que je ne peux plus résister à l'envie de venir voir mon petit jasmin."
  },
  AvgDialog_120297_Content_59 = {
    Text = "Tu fuis pour ta vie. Elle ne t'arrête pas, se contentant de t'observer avec un sourire depuis derrière la porte, comme si elle regardait un petit félin sauvage effrayé s'enfuir."
  },
  AvgDialog_120297_Content_6 = {
    Text = "Mademoiselle, si vous avez vraiment si peur, j'ai une idée."
  },
  AvgDialog_120297_Content_60 = {
    Text = "Papa ! Xu est un monstre, elle..."
  },
  AvgDialog_120297_Content_61 = {
    Text = "Tu ne te souviens pas depuis combien de temps tu cours ni combien de mauvais tournants tu as pris. Dans le regard ébahi du portier, tu te précipites vers la chambre de ton père, presque enfonçant la porte, et tu saisis anxieusement l'ourlet des vêtements de ton père."
  },
  AvgDialog_120297_Content_62 = {
    Text = "Mais dès que le nom de Xu quitte vos lèvres, vous recevez une violente gifle au visage."
  },
  AvgDialog_120297_Content_63 = {
    Text = "Je t'ai dit, tu dois l'appeler<Red:\"Mère\">."
  },
  AvgDialog_120297_Content_64 = {
    Text = "Le visage de père était anormalement alerte et grave, le chaos des derniers jours avait complètement disparu. Il saisit l'arrière de ton col et te tira loin de son côté."
  },
  AvgDialog_120297_Content_65 = {
    Text = "Non, papa, elle est devenue quelqu'un de proche pour moi. Elle interagit avec beaucoup de gens et en a même amené—"
  },
  AvgDialog_120297_Content_66 = {Text = "Assez !"},
  AvgDialog_120297_Content_67 = {
    Text = "À cette époque, c'était Xu qui t'aimait, c'est pourquoi je t'ai gardé à la maison, mais tu t'es révélé aussi ingrat que ta mère éphémère."
  },
  AvgDialog_120297_Content_68 = {
    Text = "Tu mets tout en désordre, tu dis des absurdités et tu parles disrespectueusement à ta mère ! Va dans le hall et mets-toi à genoux en punition, et ne te lève pas avant l'heure du coq !"
  },
  AvgDialog_120297_Content_69 = {
    Text = "Ce n'est pas ma mère, c'est un monstre mangeur d'hommes !"
  },
  AvgDialog_120297_Content_7 = {
    Text = "Tu as tellement peur de M. Xu. Pourquoi ne pas simplement le suivre et voir ce qu'il fait chaque jour ? S'il est vraiment un monstre, nous irons voir le vieil homme ensemble et il le mettra dehors, d'accord ?"
  },
  AvgDialog_120297_Content_70 = {
    Text = "Tu as crié de toutes tes forces, et la pièce est tombée dans un moment de silence. Puis, tu as entendu..."
  },
  AvgDialog_120297_Content_71 = {
    Text = "<Red:Le rire bas et froid de votre père.>"
  },
  AvgDialog_120297_Content_72 = {
    Text = "<Shake:Un monstre?>"
  },
  AvgDialog_120297_Content_73 = {
    Text = "Xu, c'est la «Déesse» que j'ai personnellement sélectionnée comme sacrifice une par une, et que j'ai ouvertes de mes propres mains, payant d'innombrables prix et épuisant tous mes efforts, que j'ai enfin invoquée <Red:\"Déesse\">!"
  },
  AvgDialog_120297_Content_74 = {
    Text = "J'ai essayé tant de fois, mais ces personnes superficielles et ordinaires ne méritent pas son attention. Tu crois que mon cœur ne souffre pas ? Je ne peux pas non plus supporter de voir ta mère."
  },
  AvgDialog_120297_Content_75 = {
    Text = "Comme un coup de tonnerre, il t'est difficile de comprendre le sens des mots de ton père, alors que ta conscience est complètement envahie par le son aigu de la cloche."
  },
  AvgDialog_120297_Content_76 = {
    Text = "<Shake:Tu devrais te sentir honoré ; sa chair constitue la forme terrestre de la Divine Jeune Fille.>"
  },
  AvgDialog_120297_Content_77 = {
    Text = "La voix du père émane un froid glacial, et tu réalises avec un frisson qu'il s'est ominieusement placé entre toi et la porte, avançant vers toi pas à pas."
  },
  AvgDialog_120297_Content_78 = {
    Text = "Puisque tu sais déjà tout, tu ne peux pas rester dans cette maison, et je ne te laisserai jamais sortir et parler trop."
  },
  AvgDialog_120297_Content_79 = {
    Text = "Avant que ton cri ne puisse échapper, ta gorge fut saisie par ton père, dont le visage était rempli de folie, et ta vision devint rapidement teintée de rouge sang."
  },
  AvgDialog_120297_Content_8 = {
    Text = "Faire partir Monsieur Xu ?"
  },
  AvgDialog_120297_Content_80 = {
    Text = "La <Red:Déesse> est descendue. À partir de maintenant, elle m'appartiendra <Red:pour toujours>. La renommée, la fortune... cela ne signifie plus rien maintenant. Tant que la <Red:Déesse> est avec moi, chaque sacrifice en valait la peine !"
  },
  AvgDialog_120297_Content_81 = {
    Text = "<Shake:Maman, aide...>"
  },
  AvgDialog_120297_Content_82 = {
    Text = "Je... ne veux pas mourir, je veux vivre, Maman..."
  },
  AvgDialog_120297_Content_83 = {
    Text = "<Change><Shake:Je ne veux pas mourir ça fait mal ça fait mal ÇA FAIT MAL Mūmā sauve-moi SAUVE-MOI SAUVE-MOI AIDE @4 !!>"
  },
  AvgDialog_120297_Content_84 = {
    Text = "Au secours, quelqu'un, sauvez-moi..."
  },
  AvgDialog_120297_Content_85 = {
    Text = "Personne ne répond à tes prières silencieuses."
  },
  AvgDialog_120297_Content_86 = {
    Text = "Chaos. Suffocation. Douleur. Tranquillité... L'odeur familière, sucrée et poissonneuse de la magnolia."
  },
  AvgDialog_120297_Content_87 = {
    Text = "<Red:<Shake:Creeeeak—>>"
  },
  AvgDialog_120297_Content_88 = {
    Text = "Dans un état second, une tentacule noire a jailli à travers la porte, balançant avec une immense force et le projetant directement sur le lit."
  },
  AvgDialog_120297_Content_89 = {
    Text = "He Lang, comment peux-tu rivaliser avec un enfant."
  },
  AvgDialog_120297_Content_9 = {
    Text = "Le son des klaxons de voiture venait du portail d'entrée, et chaque jour, différents visages attendaient devant le manoir de la famille He, tous des figures éminentes avec lesquelles le propriétaire de ce domaine avait un jour souhaité s'associer."
  },
  AvgDialog_120297_Content_90 = {
    Text = "Une étreinte douce t'attrape, l'air remplissant à nouveau tes poumons presque dégonflés, alors que tu soulèves doucement ton éventail de queue, soutenu invisiblement d'un endroit."
  },
  AvgDialog_120297_Content_91 = {
    Text = "C'est juste qu'elle a vu quelque chose qu'elle n'aurait pas dû voir. Je ne veux pas qu'elle s'en souvienne, donc naturellement, elle ne le fera pas."
  },
  AvgDialog_120297_Content_92 = {
    Text = "Son ton est aussi joyeux et discret que jamais, même la pression de sa main reposant sur ta tête."
  },
  AvgDialog_120297_Content_93 = {
    Text = "Dehors de la porte, on peut entendre la voix d'un serviteur faisant un rapport."
  },
  AvgDialog_120297_Content_94 = {
    Text = "Mon seigneur, plusieurs messieurs vous attendent dans le hall d'entrée."
  },
  AvgDialog_120297_Content_95 = {
    Text = "Le visage de He Fang a radicalement changé, paraissant même pire que lorsqu'il était sur le point de te tuer tout à l'heure."
  },
  AvgDialog_120297_Content_96 = {
    Text = "Qingqing, pourquoi as-tu recommencé ? J'ai dit que les possessions matérielles ne signifient plus rien pour moi ; seulement toi, seulement toi dois être à moi."
  },
  AvgDialog_120297_Content_97 = {
    Text = "Depuis que j'ai été éveillé par toi, He Lang, les autres ne sont que des ombres fugaces. Cependant, je me souviens encore du grand projet que tu prépares et je suis prêt à contribuer de mes modestes efforts."
  },
  AvgDialog_120297_Content_98 = {
    Text = "Ce que je fais, c'est simplement chercher plus de soutien tout en restant avec toi, He Lang, dans ce monde."
  },
  AvgDialog_120297_Content_99 = {
    Text = "Il n'y avait clairement aucune trace de sincérité dans les yeux de Xu, quelque chose que même toi, en tant qu'enfant, pouvais voir. Sans parler du fait qu'elle venait de jeter sans pitié la personne à qui elle avait montré tant de tendresse."
  },
  AvgDialog_120298_Content_1 = {
    Text = "Celui sans rêve"
  },
  AvgDialog_120298_Content_10 = {
    Text = "Quand je leur parle, ton odeur continue de percer mes narines, et rien que de penser à toi te rapprochant d'autres hommes me rend complètement fou !"
  },
  AvgDialog_120298_Content_11 = {
    Text = "Je te l'ai dit, tout ce dont j'ai besoin, c'est que tu sois à mes côtés. Pourquoi ne m'appartiens-tu pas seulement à moi ? Pourquoi flirtes-tu encore avec d'autres hommes !"
  },
  AvgDialog_120298_Content_12 = {
    Text = "Tu n'as jamais vu une expression aussi troublée sur le visage de Xu ; elle semble chercher un moyen de s'échapper, son regard se déplaçant frénétiquement, atterrissant de manière surprenante sur toi, caché derrière la fenêtre et inaperçu par quiconque."
  },
  AvgDialog_120298_Content_13 = {
    Text = "Tu te cachas instinctivement sous le rebord de la fenêtre, remarquant le regard de Xu. Tu regardas en arrière puis tes yeux revinrent vers elle."
  },
  AvgDialog_120298_Content_14 = {
    Text = "Tu penses encore à la façon de courir ? Abandonne. Je suis ton <Red:Éveillé>, ton pouvoir est connecté à moi, et ton pouvoir divin n'a aucun effet sur moi."
  },
  AvgDialog_120298_Content_15 = {
    Text = "<Red:<Shake:Je comprends maintenant parfaitement. Tant que je te tue, c'est seulement en te tuant... que nous pourrons vraiment être ensemble pour toujours.>>"
  },
  AvgDialog_120298_Content_16 = {
    Text = "Tu retiens ta respiration et te retournes, puis tu te précipites rapidement d'une chambre à l'autre, essayant de trouver quelqu'un qui puisse les arrêter."
  },
  AvgDialog_120298_Content_17 = {
    Text = "Non, non, non. La vaste résidence He est vide, même pas un portier en vue."
  },
  AvgDialog_120298_Content_18 = {
    Text = "Même la porte de la cour est verrouillée avec un lourd cadenas, et une brume grise sans fond tourbillonne à l'extérieur."
  },
  AvgDialog_120298_Content_19 = {
    Text = "Si cela continue, M. Xu finira comme maman..."
  },
  AvgDialog_120298_Content_2 = {
    Text = "Le lendemain, avant l'aube, un cri frénétique résonna dans la cour."
  },
  AvgDialog_120298_Content_20 = {
    Text = "<Shake:Tu devrais te cacher. Tu devrais rester caché jusqu'à ce que tout soit terminé.>"
  },
  AvgDialog_120298_Content_21 = {
    Text = "Mais tu n'as nulle part où aller. Tu as trouvé cette chose, caché tes mains derrière ton dos et t'es dirigé à nouveau vers la vieille chambre de maman."
  },
  AvgDialog_120298_Content_22 = {
    Text = "<Red:<Shake:Ma femme... ma chérie... tu ne peux être que la mienne.>>"
  },
  AvgDialog_120298_Content_23 = {
    Text = "Au moment où la faux brillante fut levée, tu échangeas des regards avec Xu ; ses yeux s'illuminèrent soudainement, pétillants d'une supplication."
  },
  AvgDialog_120298_Content_24 = {
    Text = "Mais ensuite, elle secoua subtilement la tête—"
  },
  AvgDialog_120298_Content_25 = {
    Text = "<Red:Fuis.>"
  },
  AvgDialog_120298_Content_26 = {
    Text = "Ces beaux yeux se sont fermés, et son maître est prêt à l'abattage."
  },
  AvgDialog_120298_Content_27 = {Text = "新增"},
  AvgDialog_120298_Content_28 = {Text = "ARGH !!"},
  AvgDialog_120298_Content_29 = {
    Text = "Espèce de misérable, comment oses-tu !"
  },
  AvgDialog_120298_Content_3 = {
    Text = "Son rugissement est tordu, venimeux et rempli de malveillance. Vous n'avez pas le temps de réfléchir ; un sentiment d'effroi immense vous pousse à vous précipiter vers la source du bruit."
  },
  AvgDialog_120298_Content_30 = {
    Text = "La faux tomba avec fracas au sol, et He Fang, le visage marqué par la douleur, se tenait le bas du dos où un petit couteau que tu avais trouvé était profondément enfoncé dans son corps."
  },
  AvgDialog_120298_Content_31 = {
    Text = "Dans un accès de rage, He Fang se retourna et tendit la main vers toi. Soudain, tu entendis une série de rires, pas juste un, alors que la source des sons affluait dans le compartiment."
  },
  AvgDialog_120298_Content_32 = {
    Text = "Au milieu des sourires en coin, un éclat de rire incontrôlable éclata. Xu, derrière He Fang, riait si fort qu'il se plia en deux, les larmes coulant sur son visage."
  },
  AvgDialog_120298_Content_33 = {
    Text = "AHAHA ! AHAHAHAHAHAHA ! Petite Jasmine... ma chère, ma plus aimée Petite Jasmine. Tu ne m'as vraiment pas déçu—tu es aussi intéressante que je l'avais imaginé !"
  },
  AvgDialog_120298_Content_34 = {
    Text = "Des femmes en qipaos jaunes et noirs sont entrées, leurs éventails pliants dissimulant leurs nez et leurs lèvres. Chacune d'entre elles avait une paire d'yeux très, très beaux."
  },
  AvgDialog_120298_Content_35 = {
    Text = "Dans un moment de terreur pure, avant que ses cris ne résonnent, une étreinte froide et douce t'avait déjà enveloppé."
  },
  AvgDialog_120298_Content_36 = {
    Text = "<Red:Chose dégoûtante. Tu ne saliras pas les yeux de ma petite jasmin.>"
  },
  AvgDialog_120298_Content_37 = {
    Text = "<Shake:Mon Seigneur...>"
  },
  AvgDialog_120298_Content_38 = {
    Text = "<Shake:Mon Seigneur...>"
  },
  AvgDialog_120298_Content_39 = {
    Text = "Que fais-tu ? Es-tu fou ! Sortez, tous, sortez."
  },
  AvgDialog_120298_Content_4 = {
    Text = "Xu était acculé par Ho Fong contre le lit, les yeux injectés de sang et les cheveux en désordre, comme s'il n'avait pas dormi de la nuit."
  },
  AvgDialog_120298_Content_40 = {
    Text = "Les concubines devant moi écartèrent lentement les surfaces des éventails, révélant le même visage sous chaque éventail."
  },
  AvgDialog_120298_Content_41 = {
    Text = "Pourquoi le seigneur nous a-t-il transformés en sacrifices ?"
  },
  AvgDialog_120298_Content_42 = {
    Text = "Pourquoi le seigneur a-t-il coupé nos membres ?"
  },
  AvgDialog_120298_Content_43 = {
    Text = "D'innombrables Xu ignorent les cris tremblants de colère de He Fang, l'entourant joyeusement au milieu, tandis que des éventails noirs et des faux forment alternativement un cercle autour de lui."
  },
  AvgDialog_120298_Content_44 = {
    Text = "<Change>Sommes-nous assez beaux maintenant ?"
  },
  AvgDialog_120298_Content_45 = {
    Text = "<Change>Pouvons-nous maintenant rester ensemble avec mon seigneur pour toujours ?"
  },
  AvgDialog_120298_Content_46 = {
    Text = "Un fantôme massif s'envola dans le ciel depuis le dos de Xu, un, deux, trois... d'innombrables bouches en forme de dents de dragon s'échappèrent de la peau enflée, dégoulinant de salive, désireuses de choisir et de dévorer,"
  },
  AvgDialog_120298_Content_47 = {
    Text = "Les filaments semblables à des plumes s'étendent dans toute la cour de la famille He, enveloppant toute lumière et réduisant au silence tous les bruits."
  },
  AvgDialog_120298_Content_48 = {
    Text = "Votre vision est enveloppée de brouillard, et tout ce que vous pouvez percevoir est le parfum étrange émanant de Xu et les bruits lents et étranges de la dévoration."
  },
  AvgDialog_120298_Content_49 = {Text = "新增"},
  AvgDialog_120298_Content_5 = {
    Text = "Ma fille stupide n'a pas dit une seule chose fausse... Je peux le sentir."
  },
  AvgDialog_120298_Content_50 = {
    Text = "Après que le bruit continu de succion se soit arrêté, He Fang s'est levé silencieusement et est sorti, se tenant parmi un groupe d'hommes qui attendaient également en silence."
  },
  AvgDialog_120298_Content_51 = {
    Text = "Inspecteurs, présidents, présidents de séance... Leurs épouses se tiennent aux côtés des hommes, le soleil levant vous éblouissant, et vous voyez le même sourire mystérieux sur leurs visages que celui de Xu."
  },
  AvgDialog_120298_Content_52 = {Text = "新增"},
  AvgDialog_120298_Content_53 = {
    Text = "Partout où tu dis que ton pouvoir est connecté à lui, maintenant qu'il est devenu comme ça, vas-tu disparaître ?"
  },
  AvgDialog_120298_Content_54 = {
    Text = "C'est la première chose que ma petite jasmin demande ? Vraiment... je suis tellement ému."
  },
  AvgDialog_120298_Content_55 = {
    Text = "Ses doigts effleurent ton front, s'arrêtant enfin au bout de ton nez."
  },
  AvgDialog_120298_Content_56 = {
    Text = "Peut-être oui, peut-être... non, mais aimeriez-vous être mon maître ?"
  },
  AvgDialog_120298_Content_57 = {
    Text = "Xu saisit légèrement l'air, tirant un mouchoir en soie aussi fin qu'une aile de cigale. Trempant le pinceau argenté dans l'encre, il se déplia devant toi."
  },
  AvgDialog_120298_Content_58 = {
    Text = "Je te donnerai tout ce qui n'a pas été obtenu, ainsi que le meilleur du monde."
  },
  AvgDialog_120298_Content_59 = {
    Text = "Quand ma mère était vivante, Haicheng était balayé par une nouvelle tendance, et tu avais lu des livres et pratiqué l'écriture."
  },
  AvgDialog_120298_Content_6 = {
    Text = "<Shake:<Red:Ces hommes...>>"
  },
  AvgDialog_120298_Content_60 = {
    Text = "Xu a pris ta main, attendant que tu commences à écrire, et toi... quel était encore ton nom ?"
  },
  AvgDialog_120298_Content_61 = {
    Text = "Le miroir en cuivre éclaboussé de liquide rouge frais reflète les traits délicats et jeunes d'une personne d'origine orientale, ressemblant à un groupe de jasmins pâles et fragiles."
  },
  AvgDialog_120298_Content_62 = {
    Text = "Tu clignes des yeux, confus, et la petite fille dans le reflet te renvoie le regard. \n Tu te souviens, le tissu en soie portait ton écriture enfantine, et ton nom était—"
  },
  AvgDialog_120298_Content_63 = {Text = "He Fang."},
  AvgDialog_120298_Content_64 = {Text = "新增"},
  AvgDialog_120298_Content_65 = {
    Text = "Alors, le chef de cette société secrète qui est ensuite apparue à Haicheng est une petite fille à peu près de la taille de Jenkins ?!"
  },
  AvgDialog_120298_Content_66 = {
    Text = "Ta tête te fait horriblement mal à cause des séquelles du rêve, et tu es surpris par la femme qui apparaît silencieusement après ton réveil."
  },
  AvgDialog_120298_Content_67 = {
    Text = "Le dortoir de Mythag devrait vraiment mettre en place des mesures de sécurité. Cela dit, tu commences à réfléchir à ce qui pourrait te protéger de cette femme qui n'épargne même pas les enfants."
  },
  AvgDialog_120298_Content_68 = {
    Text = "...Selon les archives, dans les légendes de l'Extrême-Orient, il existe un ancien dieu maléfique connu sous le nom de <Red:\"La Matriarche Obsidienne des Mille Fans\">. Il se plaît à manipuler les cœurs des hommes et se régale de la matière cérébrale de ceux qui nourrissent des désirs pour lui."
  },
  AvgDialog_120298_Content_69 = {
    Text = "Même si tu ne peux voir que ses yeux, il est clair que la femme devant toi sourit joyeusement. Elle repose paresseusement son menton sur sa main, et tu ne peux t'empêcher de te demander si son regard pourrait même rendre un balai affectueux."
  },
  AvgDialog_120298_Content_7 = {
    Text = "Penses-tu que tu peux me tromper ? N'oublie pas, c'est moi qui t'ai personnellement convoqué avec le <Red:\"cadavre\"> de ma femme ; comment pourrais-je confondre cette odeur ?"
  },
  AvgDialog_120298_Content_70 = {
    Text = "Tu me comprends si bien, cela me rend vraiment très heureux."
  },
  AvgDialog_120298_Content_71 = {
    Text = "Cet homme stupide a mis la main sur un ancien rouleau, cherchant à m'invoquer pour jeter des sorts de tromperie, tuant d'innombrables personnes, et à la fin, même sa femme bien-aimée qui l'aimait de tout son cœur n'a pas été épargnée."
  },
  AvgDialog_120298_Content_72 = {
    Text = "À l'origine, c'était simplement que la haine de sa femme me faisait rire, souhaitant lui faire goûter à son ennemi."
  },
  AvgDialog_120298_Content_73 = {
    Text = "Mais à ce moment-là, Shencheng était rempli de l'odeur écrasante de la décomposition et de la malice, me rendant... réticent à partir."
  },
  AvgDialog_120298_Content_74 = {
    Text = "...En fait, tu n'as pas besoin d'un Linker, n'est-ce pas ?"
  },
  AvgDialog_120298_Content_75 = {
    Text = "J'ai lu les « enregistrements de stockage en argent ». Tu es parfaitement capable de réaliser le Rituel d'Éveil par toi-même. Maintenir ta santé mentale sera un jeu d'enfant pour toi."
  },
  AvgDialog_120298_Content_76 = {
    Text = "Quel est votre but en vous liant activement avec He Fang à Haicheng ?"
  },
  AvgDialog_120298_Content_77 = {
    Text = "Xu resta silencieuse, un filet de brume tourbillonnant autour de toi, allégeant délicatement la pression dans ta tête. Elle te fit un clin d'œil depuis derrière l'écran."
  },
  AvgDialog_120298_Content_78 = {
    Text = "Je pensais à l'origine que dans ce monde, il n'y avait pas de différence entre les adultes, mais chaque enfant est différent d'un autre."
  },
  AvgDialog_120298_Content_79 = {
    Text = "Je la nourris de brume et je l'arrose de puissance et de désir. Je l'aime, alors pourquoi viens-tu encore me punir ?"
  },
  AvgDialog_120298_Content_8 = {
    Text = "S'ils n'avaient pas d'intimité avec vous, pourquoi émettraient-ils une odeur qui appartient à <Red:votre parfum> ?"
  },
  AvgDialog_120298_Content_80 = {
    Text = "Ce n'est pas de l'amour"
  },
  AvgDialog_120298_Content_81 = {Text = "新增"},
  AvgDialog_120298_Content_82 = {
    Text = "Hehe, je ne comprends vraiment pas ce qu'est l'amour humain. Je vais offrir les meilleurs cadeaux de ce monde : de la nourriture, des jouets et le pouvoir d'appeler un cerf un cheval."
  },
  AvgDialog_120298_Content_83 = {
    Text = "Et bien sûr... je recevrai le paiement que je désire en retour. Et le jour où vous vous trouverez dans le besoin, mon Petit Jasmin... comment <Italic:vous> choisirez-vous ?"
  },
  AvgDialog_120298_Content_84 = {
    Text = "Dans mon pays des rêves, je suis toujours prêt à attendre ton arrivée, à tout moment, n'importe où."
  },
  AvgDialog_120298_Content_85 = {
    Text = "Doucement, au milieu des rires délicats et espiègles, la brume s'étendit—dans le moment suivant, il ne resta que le parfum de magnolia dans le dortoir."
  },
  AvgDialog_120298_Content_9 = {
    Text = "Il a soudainement ri nerveusement, se penchant en avant et saisissant le poignet de Xu tenant l'éventail."
  },
  AvgDialog_120313_Content_1 = {
    Text = "En ce moment\n à l'extérieur du Soleil noir"
  },
  AvgDialog_120313_Content_10 = {
    Text = "Dans le monde au-delà de milliards d'éclats étoilés, cette silhouette lutte pour percer à travers les courants tumultueux, s'approchant de toi pas à pas."
  },
  AvgDialog_120313_Content_11 = {Text = "Ramona !!!"},
  AvgDialog_120313_Content_12 = {
    Text = "Tu as discerné son contour, son visage, ses yeux brillants de joie, ce n'est plus une illusion trompeuse, il n'y a plus seulement des voix étouffées."
  },
  AvgDialog_120313_Content_13 = {
    Text = "Les vagues d'énergie connectées par le tunnel sifflaient en soulevant tes cheveux, enfin, vos doigts se touchèrent, puis vous vous étreignîtes fermement."
  },
  AvgDialog_120313_Content_14 = {
    Text = "Les pensées provenant d'un autre monde se transforment en une aura blanche, tourbillonnant à travers ton âme."
  },
  AvgDialog_120313_Content_15 = {
    Text = "<Shake:<color=#DEDEDE>Enfin... je t'ai... trouvé.</color>>"
  },
  AvgDialog_120313_Content_16 = {
    Text = "Vos têtes se touchent, ses deux mains t'enlacent tendrement dans le dos, sa voix tremble de joie et de larmes."
  },
  AvgDialog_120313_Content_17 = {
    Text = "Toute la fatigue, la solitude et la douleur se dissipent en ce moment, vous savez que votre âme est revenue à son véritable foyer."
  },
  AvgDialog_120313_Content_18 = {
    Text = "C'est dangereux de naviguer entre les dimensions, tu es blessé ?"
  },
  AvgDialog_120313_Content_19 = {
    Text = "Tu te souviens de quelque chose, examinant à plusieurs reprises l'âme qui a tant cheminé devant toi, ne voyant qu'une silhouette un peu émaciée. Ramona secoue la tête et caresse doucement ton visage."
  },
  AvgDialog_120313_Content_2 = {
    Text = "Descendre, destruction, renaissance… Résistance, combat, ténacité…"
  },
  AvgDialog_120313_Content_20 = {
    Text = "Et toi ? Tu as dû beaucoup souffrir, seul dans ce monde étranger pendant si longtemps."
  },
  AvgDialog_120313_Content_21 = {
    Text = "Une douleur sourde se fit sentir au bout de ton nez, et tu secouas également la tête. Dans ce regard échangé, au milieu des larmes suspendues dans tes yeux, vous avez tous deux souri."
  },
  AvgDialog_120313_Content_22 = {
    Text = "Pourquoi tu ris, comme un idiot ."
  },
  AvgDialog_120313_Content_23 = {
    Text = "Tu ne ris pas aussi... ?"
  },
  AvgDialog_120313_Content_24 = {
    Text = "Dans une immense bonheur, tu ne peux t'empêcher de prendre sa main, désireux de rentrer immédiatement."
  },
  AvgDialog_120313_Content_25 = {Text = "!!!"},
  AvgDialog_120313_Content_26 = {
    Text = "Soudain, tu vois ses pupilles se rétrécir brusquement, puis en un instant, elle se jette sur toi et te pousse violemment sur le côté."
  },
  AvgDialog_120313_Content_27 = {
    Text = "Au moment où tu es projeté en arrière, tu vois qu'à l'endroit où se trouvait à l'origine Ramona derrière toi, une nouvelle fissure dimensionnelle s'ouvre, et un autre œil tourne et s'ouvre, regardant Ramona restée sur place."
  },
  AvgDialog_120313_Content_28 = {
    Text = "En un instant, la boue noire l'a engloutie."
  },
  AvgDialog_120313_Content_29 = {
    Text = "<Shake:<Big:Non!!!>>"
  },
  AvgDialog_120313_Content_3 = {
    Text = "Sous l'intimidation de la volonté suprême, tout semble si familier."
  },
  AvgDialog_120313_Content_4 = {
    Text = "Les énormes pupilles pâles dans cette dimension alternative se dissipent une à une, ton esprit s'épuise progressivement, et la seule chose qui te soutient est la rose rouge sang que tu tiens dans ta main."
  },
  AvgDialog_120313_Content_5 = {
    Text = "Ouf... Je ne peux pas tomber, ils m'attendent encore..."
  },
  AvgDialog_120313_Content_6 = {
    Text = "Dans un état d'égarement, ton cœur commence soudainement à battre avec force, et tu te retournes en suivant cette intuition."
  },
  AvgDialog_120313_Content_7 = {
    Text = "Comme si une étoile filante passait, et comme si des cristaux de glace se formaient, un tunnel en forme de faisceau lumineux s'étend avec une voix étrange et éthérée."
  },
  AvgDialog_120313_Content_8 = {
    Text = "Une voix qui a résonné des centaines de fois dans ta mémoire traverse les lointaines dimensions derrière toi et résonne dans ton esprit grâce au lien de tes antennes spirituelles."
  },
  AvgDialog_120313_Content_9 = {
    Text = "<Yellow:%player%> !!!"
  },
  AvgDialog_121232_Content_1 = {
    Text = "L'éclat de ma patrie brille devant mes yeux, Seigneur Goliath, je vous laisse la suite..."
  },
  AvgDialog_121232_Content_2 = {
    Text = "La puissance divine qui jaillit... ressemble en effet à celle de cette femme folle."
  },
  AvgDialog_121232_Content_3 = {
    Text = "Bien, petit là-bas, prépare-toi à découvrir la force des Philistins, qui surpasse la bénédiction !"
  },
  AvgDialog_121369_Content_1 = {
    Text = "Dans la salle vide, seuls vos pas et ceux de Murphy résonnent."
  },
  AvgDialog_121369_Content_10 = {
    Text = "Avant que tu ne puisses comprendre la situation, des membres glacés s'enroulent autour de ton mollet, une force musculaire te pousse à t'agenouiller."
  },
  AvgDialog_121369_Content_11 = {
    Text = "Tu essaies de résister, mais la toxine paralysante s'infiltre dans tes nerfs, te rendant incapable d'agir."
  },
  AvgDialog_121369_Content_12 = {
    Text = "Murphy, que fais-tu ?!"
  },
  AvgDialog_121369_Content_13 = {
    Text = "Je ne sais pas pourquoi, mais je me sens très en colère."
  },
  AvgDialog_121369_Content_14 = {
    Text = "Il y a un feu qui brûle en moi, et le voir ne fait qu'attiser les flammes."
  },
  AvgDialog_121369_Content_15 = {
    Text = "(Reste calme, reste calme. Ne fais rien qui puisse nuire à la majesté de la Mère divine.)"
  },
  AvgDialog_121369_Content_16 = {
    Text = "Alors... que veux-tu que je fasse ici en me faisant mettre à genoux ?"
  },
  AvgDialog_121369_Content_17 = {
    Text = "Agenouille-toi sans poser de questions !"
  },
  AvgDialog_121369_Content_18 = {
    Text = "Le ton de Murphy semblait encore en colère, les tentacules du pieuvre frappant nerveusement contre ta jambe. Il semble que tu devras te débrouiller seul."
  },
  AvgDialog_121369_Content_19 = {
    Text = "Tu luttes contre la force de la toxine paralysante en levant la tête, touchant sa joue rougie."
  },
  AvgDialog_121369_Content_2 = {
    Text = "Depuis tout à l'heure, tu refuses de dire quoi que ce soit."
  },
  AvgDialog_121369_Content_20 = {
    Text = "Murphy, tu... es perturbé par la force de la rivière sacrée ?"
  },
  AvgDialog_121369_Content_21 = {
    Text = "Lâcher ! Je suis la Mère des Dieux, comment pourrais-je être affectée par une telle stupidité..."
  },
  AvgDialog_121369_Content_22 = {
    Text = "Les tentacules de l'anneau bleu grimpent le long de ton dos, laissant derrière eux une sensation de démangeaison."
  },
  AvgDialog_121369_Content_23 = {
    Text = "Reste bien ici avant qu'il ne fasse jour."
  },
  AvgDialog_121369_Content_24 = {
    Text = "Ne bouge pas !"
  },
  AvgDialog_121369_Content_25 = {
    Text = "Mais tu sens que le tentacule qui te lie s'est assoupli un peu, comme si un nuage te portait, mais quand tu essaies de te libérer, il t'empêche de bouger d'un pouce."
  },
  AvgDialog_121369_Content_26 = {
    Text = "Remercie-le, tu auras l'honneur d'accueillir l'aube avec la Mère divine."
  },
  AvgDialog_121369_Content_27 = {
    Text = "En guise de récompense…"
  },
  AvgDialog_121369_Content_28 = {
    Text = "Son souffle erre à ton oreille. Puis un baiser doux et léger se pose sur ton front."
  },
  AvgDialog_121369_Content_29 = {
    Text = "Vous recevrez également les bienfaits de la Mère divine."
  },
  AvgDialog_121369_Content_3 = {
    Text = "Que s'est-il passé, Murphy ?"
  },
  AvgDialog_121369_Content_4 = {
    Text = "Murphy ne répondit pas, avançant directement vers le sommet des marches, là où se trouvait le trône."
  },
  AvgDialog_121369_Content_5 = {
    Text = "Tu la suis pas à pas, jusqu'à ce qu'elle s'asseye enfin sur le trône, son regard légèrement irrité te transperçant."
  },
  AvgDialog_121369_Content_6 = {
    Text = "Qui t'a permis de te tenir à mes côtés ? Baisse-toi, ne me regarde pas de haut."
  },
  AvgDialog_121369_Content_7 = {
    Text = "Tu es perplexe, mais tu recules de deux pas, tes yeux s'alignant parfaitement avec ceux de la jeune fille sur le trône."
  },
  AvgDialog_121369_Content_8 = {Text = "Genou."},
  AvgDialog_121369_Content_9 = {Text = "Ha ?"},
  AvgDialog_121741_Content_1 = {
    Text = "Énorme, pourri, vide... maintenir l'illusion au-dessus du « rideau » avec une fantaisie absurde..."
  },
  AvgDialog_121741_Content_2 = {
    Text = "Quelle stupidité et ridicule de me laisser aller dans le «paradis»..."
  },
  AvgDialog_121741_Content_3 = {
    Text = "%player%, aide-moi à mettre fin à ce rêve."
  },
  AvgDialog_121741_Content_4 = {
    Text = "Aide-moi à reprendre... mon destin."
  },
  AvgDialog_121742_Content_1 = {
    Text = "Les chaînes tremblent, le monstre derrière le rideau scrute l'ensemble du navire, poussant des cris de désespoir."
  },
  AvgDialog_121742_Content_10 = {
    Text = "Au revoir, le « Hier » fragile et impuissant... !"
  },
  AvgDialog_121742_Content_2 = {
    Text = "Je comprends… Je comprends tout… ton attachement, ce à quoi tu n'arrives pas à renoncer…"
  },
  AvgDialog_121742_Content_3 = {
    Text = "Mais j'ai pris ma décision."
  },
  AvgDialog_121742_Content_4 = {
    Text = "Murphy se tourna vers lui, puis, après un moment de réflexion, elle te fit un sourire doux, comme si elle avait pris une décision."
  },
  AvgDialog_121742_Content_5 = {
    Text = "Regardez donc... ce cœur dans ma poitrine..."
  },
  AvgDialog_121742_Content_6 = {
    Text = "Même aujourd'hui, cela palpite encore de vie."
  },
  AvgDialog_121742_Content_7 = {
    Text = "Comme lors de la cérémonie de pilotage, Murphy s'est ouvert la poitrine."
  },
  AvgDialog_121742_Content_8 = {
    Text = "Pour quitter cet endroit, pour le jour où je te reverrai à Mizag."
  },
  AvgDialog_121742_Content_9 = {
    Text = "Le sang spirituel s'écoule de la poitrine de Murphy, des fils argentés s'entrelacent, désireux de déchirer le voile au-dessus du ciel."
  },
  AvgDialog_121743_Content_1 = {
    Text = "Tu ne sais pas combien de temps tu as combattu, tu sens seulement que ton cerveau commence à tourner et que tes bras deviennent lourds, tandis que ce monstre énorme, pâle et mince, agite sans relâche ses bras brisés et régénérés."
  },
  AvgDialog_121743_Content_10 = {
    Text = "La promesse de William semble ériger une barrière invisible derrière lui, cette confiance forgée au fil des ans fait jaillir à nouveau une force presque épuisée des profondeurs de sa moelle osseuse."
  },
  AvgDialog_121743_Content_11 = {
    Text = "Nous avons convenu de rentrer ensemble."
  },
  AvgDialog_121743_Content_12 = {
    Text = "Que la Clé d'argent éclaire mon chemin."
  },
  AvgDialog_121743_Content_13 = {
    Text = ": Que la clé d'argent nous guide"
  },
  AvgDialog_121743_Content_2 = {
    Text = "La sueur glisse de ton front, brouillant ta vision, et tu as du mal même à lever la main pour essuyer."
  },
  AvgDialog_121743_Content_3 = {Text = "Maudit..."},
  AvgDialog_121743_Content_4 = {
    Text = "%player%, tiens bon."
  },
  AvgDialog_121743_Content_5 = {
    Text = "Une cape noir et rouge vole devant toi, tandis qu'un bras mécanique précis bloque les assauts répétés des squelettes pâles."
  },
  AvgDialog_121743_Content_6 = {
    Text = "Des membres longs et minces frappent à nouveau avec fureur, mais sont à nouveau bloqués, des éclats s'écrasant à vos côtés, soulevant un nuage de fumée."
  },
  AvgDialog_121743_Content_7 = {Text = "William ?"},
  AvgDialog_121743_Content_8 = {
    Text = "Concentre-toi, regarde-Le. \n Laisse-moi gérer tes arrières."
  },
  AvgDialog_121743_Content_9 = {
    Text = "Dans ce nouveau monde... je vais temporairement assumer les tâches de ton partenaire. \n Jusqu'au jour où nous retournerons ensemble à Mizag."
  },
  AvgDialog_121744_Content_1 = {
    Text = "Le monstre rugit et pleure, le rideau dissimulé se déchire, son corps émerge des profondeurs de l'Aequor."
  },
  AvgDialog_121744_Content_10 = {
    Text = "Ne pas savoir utiliser la force et confier son destin à d'autres n'est pas le style des Philistins."
  },
  AvgDialog_121744_Content_11 = {
    Text = "Le géant manie son arme, pointant la pointe de la grande lame vers la gigantesque masse de chair en train de se transformer."
  },
  AvgDialog_121744_Content_12 = {
    Text = "Alors, ne perdons plus de temps, préparez-vous à combattre !"
  },
  AvgDialog_121744_Content_13 = {
    Text = "Les gagnants sont les seuls à avoir le droit de survivre."
  },
  AvgDialog_121744_Content_2 = {
    Text = "Mince... ! Il est toujours en train d'expansionner !"
  },
  AvgDialog_121744_Content_3 = {
    Text = "Un éclair a déchiré le ciel nocturne obscur, et la grande lame assoiffée de sang s'est abattue avec une rapide lumière violet-noir sur les membres pâles et frêles du rideau."
  },
  AvgDialog_121744_Content_4 = {
    Text = "… Miryam ? Goliath ? Pourquoi êtes-vous ici ?"
  },
  AvgDialog_121744_Content_5 = {
    Text = "La résolution de la Mère divine est prise, nous devons nous-mêmes trancher ce « rideau » sans raison."
  },
  AvgDialog_121744_Content_6 = {Text = "Miryam..."},
  AvgDialog_121744_Content_7 = {
    Text = "Rassurez-vous, Mère divine. Peu importe vos projets futurs, les Marcheurs des mers seront toujours la pierre angulaire la plus solide derrière vous."
  },
  AvgDialog_121744_Content_8 = {
    Text = "Ne fais pas de chichis, allons-nous rester là à regarder ces deux petits se battre contre ce type ?"
  },
  AvgDialog_121744_Content_9 = {
    Text = "Une voix familière est soudainement apparue, interrompant les paroles de Murphy. C'était Goliath et Caecus."
  },
  AvgDialog_121745_Content_1 = {
    Text = "Le monstre se dresse fièrement, levant la tête, « regardant » chacun d'entre vous depuis le rideau sombre."
  },
  AvgDialog_121745_Content_10 = {
    Text = "Je te prie de t'enterrer, comme moi... à jamais dans l'immensité des profondeurs !"
  },
  AvgDialog_121745_Content_2 = {Text = "...!!!"},
  AvgDialog_121745_Content_3 = {
    Text = "Un lien invisible et réel perçait entre elle et Lui, inévitable, permettant à la jeune fille de voir Ses blessures, Ses sanglots, et même Ses doutes…"
  },
  AvgDialog_121745_Content_4 = {
    Text = "Comme un bébé blessé, interrogeant la « trahison » de sa mère."
  },
  AvgDialog_121745_Content_5 = {
    Text = "Ne me regarde pas, ne m'interroge pas... J'ai pris ma décision. C'est ma dernière « trahison »."
  },
  AvgDialog_121745_Content_6 = {
    Text = "Autrefois, j'ai fait un vœu au « Paradis », un « rêve » que je désirais tant dans mon enfance."
  },
  AvgDialog_121745_Content_7 = {
    Text = "Je pensais que le « pouvoir » pouvait me procurer « le bonheur », mais ce n'était finalement qu'une illusion vaine..."
  },
  AvgDialog_121745_Content_8 = {
    Text = "Murphy sourit en essuyant les larmes qui coulaient au coin de ses yeux. Elle essuya lentement et délicatement, jusqu'à ce que la dernière trace de larme disparaisse complètement, puis elle leva la tête et fixa ce « soi » immense."
  },
  AvgDialog_121745_Content_9 = {
    Text = "Je n'ai pas besoin de Paradis, je n'ai pas besoin de me tromper avec de beaux rêves. Je n'en ai plus besoin."
  },
  AvgDialog_121858_Content_1 = {
    Text = "Des milliers de monstres débordent de ses pieds, et vous les abattez un par un. \n Marchant sur des milliers de cadavres, vous atteignez le pied de la gigantesque silhouette."
  },
  AvgDialog_121858_Content_10 = {
    Text = "Cette fois, je ne permettrai pas que la vie de qui que ce soit soit échangée contre la victoire."
  },
  AvgDialog_121858_Content_11 = {
    Text = "Préparez-vous à la bataille, le « voile » qui finira par flétrir !"
  },
  AvgDialog_121858_Content_2 = {
    Text = "C'est ma volonté, la volonté du « paradis »…"
  },
  AvgDialog_121858_Content_3 = {
    Text = "«L'enfant» n'appartient jamais à «la Mère», et après sa naissance, Il a également développé son propre «désir»."
  },
  AvgDialog_121858_Content_4 = {
    Text = "<Red:Rêve... doit... se poursuivre...>"
  },
  AvgDialog_121858_Content_5 = {
    Text = "Tu as dit qu'il suffisait de tuer le maître des rêves pour te transférer le pouvoir..."
  },
  AvgDialog_121858_Content_6 = {
    Text = "Oui. As-tu déjà fait ton éveil ?"
  },
  AvgDialog_121858_Content_7 = {
    Text = "Non, elle n'a pas besoin de faire un tel sacrifice."
  },
  AvgDialog_121858_Content_8 = {
    Text = "...%player%!"
  },
  AvgDialog_121858_Content_9 = {
    Text = "Le « noyau » du labyrinthe, le « cataclysme » qui se manifeste, à une telle échelle, je ne me souviens plus combien de fois j'ai déjà combattu cela."
  },
  AvgDialog_121859_Content_1 = {
    Text = "Il impose sa force derrière le rideau... en train de changer..."
  },
  AvgDialog_121859_Content_2 = {
    Text = "Abandonné, laissé de côté... Il est dans le dédain, dans la colère, dans le chagrin..."
  },
  AvgDialog_121859_Content_3 = {
    Text = "Sa rancœur s'abattra sur vous... !"
  },
  AvgDialog_121864_Content_1 = {
    Text = "C'est surprenant, n'est-ce pas ? Parce que l'oracle m'appelle, au-delà du rideau..."
  },
  AvgDialog_121865_Content_1 = {
    Text = "Mon sang s'active, les abysses chantent ensemble et m'invitent !"
  },
  AvgDialog_121866_Content_1 = {
    Text = "Ô divin éloigné, votre dévoué serviteur vous offrira un modeste soutien..."
  },
  AvgDialog_121867_Content_1 = {
    Text = "Sorteux, voici la puissance des Philistins !"
  },
  AvgDialog_122640_Content_1 = {
    Text = "<Shake:Boom !——>"
  },
  AvgDialog_122640_Content_2 = {
    Text = "Le regard fou fait trembler toute la dimension, le lien entre Ramona et toi est obscurci par la fusion, disparaissant sans laisser de trace."
  },
  AvgDialog_122640_Content_3 = {
    Text = "Tu prends une profonde inspiration, réprimant de force l'agitation causée par la folie."
  },
  AvgDialog_122640_Content_4 = {
    Text = "Garde cette folie pour toi…<Big:Je ne laisserai pas ta folie blesser qui que ce soit !>"
  },
  AvgDialog_122641_Content_1 = {
    Text = "...@3 !! ..."
  },
  AvgDialog_122641_Content_2 = {
    Text = "Intimidation familière. Regard familier. Une douleur presque déchirante qui t'assaillit le cerveau."
  },
  AvgDialog_122641_Content_3 = {
    Text = "Ah… encore toi, Touva Wave, dieu suprême… bien que tu ne puisses pas m'entendre, je dois te remercier."
  },
  AvgDialog_122641_Content_4 = {
    Text = "Tu m'as fait mourir une fois, et dans cette mort, j'ai compris une vérité fondamentale..."
  },
  AvgDialog_122641_Content_5 = {
    Text = "Vous serrez fermement la Clé d'argent, fixant le regard projeté par Sa volonté — et ce n'est que plus tard que vous réaliserez que vous <Italic:souriiez.>"
  },
  AvgDialog_122641_Content_6 = {
    Text = "Tu m'as fait savoir que dans ton grand rêve, rien n'est immuable, rien n'est invincible."
  },
  AvgDialog_122641_Content_7 = {
    Text = "Pour nous revoir, nous avons attendu longtemps... Même toi, tu ne peux pas nous barrer le chemin !"
  },
  AvgDialog_122642_Content_1 = {
    Text = "...@2... @2... @1@3... !!"
  },
  AvgDialog_122642_Content_2 = {
    Text = "Un impact fort fait commencer à briser toute la dimension. Tu ouvres les yeux rouges et regardes cet œil qui se rapproche de plus en plus de l'entité."
  },
  AvgDialog_122642_Content_3 = {
    Text = "Ta conscience a également atteint ses limites, Tohu Wabohu... Maintenant, continue à dormir paisiblement !"
  },
  AvgDialog_122642_Content_4 = {
    Text = "Tu rassembles presque toute ta force spirituelle et injectes tes dernières réserves dans la clé en argent."
  },
  AvgDialog_122642_Content_5 = {
    Text = "Tu tiens la lumière argentée comme une lame, et tu la plantes vers la divinité devant toi——"
  },
  AvgDialog_122643_Content_1 = {
    Text = "<Big:<Shake:Ramona !!!>>"
  },
  AvgDialog_122643_Content_2 = {
    Text = "Une silhouette familière est engloutie par la fusion apportée par le regard, des incantations anciennes et maléfiques apparaissent et disparaissent dans ce regard."
  },
  AvgDialog_122643_Content_3 = {
    Text = "Ces chants s'arrêtent ici... !"
  },
  AvgDialog_122644_Content_1 = {
    Text = "Le monde s'effondre et se reconstruit devant toi, des proches meurent et renaissent devant toi. Ce regard chaotique apporte tout le désordre de l'univers dans ton esprit."
  },
  AvgDialog_122644_Content_2 = {
    Text = "Désordre, confusion, perplexité… ce que ton pouvoir apporte, ce sont toujours ces choses."
  },
  AvgDialog_122644_Content_3 = {
    Text = "Ton regard ne m'a jamais troublé, Touva Wave. Cela a été vrai autrefois, et c'est toujours le cas aujourd'hui."
  },
  AvgDialog_122644_Content_4 = {
    Text = "La lumière argentée brille. Parmi ces illusions infinies, tu as trouvé le chemin pour l'affronter——"
  },
  AvgDialog_122645_Content_1 = {
    Text = "Dans une dimension lointaine, un point lumineux scintille faiblement."
  },
  AvgDialog_122645_Content_2 = {
    Text = "C'est... le « Cœur sacré » de Pollux ?"
  },
  AvgDialog_122645_Content_3 = {
    Text = "Leur recherche a déjà commencé... Ils sont certainement en danger maintenant."
  },
  AvgDialog_122645_Content_4 = {
    Text = "Je me souviens de la peur que j'ai ressentie la première fois que je t'ai affronté, Tohuwabohu. Cette fois, je ne les ferai pas attendre longtemps !"
  },
  AvgDialog_122646_Content_1 = {
    Text = "Une douleur aiguë s'abat sur chacun de tes os, chaque centimètre de ta chair. Tu endures cette douleur lancinante et parviens à sourire avec difficulté."
  },
  AvgDialog_122646_Content_2 = {
    Text = "Dieu insensé, tu ne sais pas qu'il y a beaucoup de souffrances dans tes rêves qui dépassent de loin le corps..."
  },
  AvgDialog_122646_Content_3 = {
    Text = "Je ne laisserai plus jamais cette douleur réapparaître !"
  },
  AvgDialog_122694_Content_1 = {
    Text = "La porte à mi-chemin du couloir est déjà couverte de givre blanc, et le givre semble se propager."
  },
  AvgDialog_122694_Content_10 = {
    Text = "S'il vous plaît, Gardien du secret, tenez-moi juste — un peu, juste un peu de chaleur, c'est tout ce dont j'ai besoin~ La Fée se souviendra de votre gentillesse pour toujours."
  },
  AvgDialog_122694_Content_11 = {
    Text = "C'est la première fois que vous voyez cette petite escroc arborer une telle expression, mais une méfiance persistante vous cloue sur place, votre souffle formant des nuages blancs, vous contentant de bouger les membres pour rester au chaud."
  },
  AvgDialog_122694_Content_12 = {
    Text = "J'ai déjà prévenu le bureau administratif. Ils seront là pour aider bientôt. Reste où tu es, ne bouge pas, ne fais rien."
  },
  AvgDialog_122694_Content_13 = {
    Text = "Mais je me sens si mal en ce moment... Le pouvoir de cette rivière m'a ramenée dans cet endroit pâle... glacial... terrible..."
  },
  AvgDialog_122694_Content_14 = {
    Text = "Sans prévenir, les larmes de Caraboo tombent droit vers le bas, comme si elle venait réellement de voir quelque chose d'horrifiant."
  },
  AvgDialog_122694_Content_15 = {
    Text = "Je ne pense pas tenir jusqu'à l'arrivée des secours, Gardien du secret. Je suis désolée... de vous avoir toujours menti avant..."
  },
  AvgDialog_122694_Content_16 = {
    Text = "Des cristaux de glace se répandent vers l'extérieur avec elle en leur centre, et elle semble impuissante, fragile, les yeux rouges tandis qu'elle vous fixe — vacillante, comme si elle pouvait s'effondrer à tout instant."
  },
  AvgDialog_122694_Content_17 = {Text = "Caraboo !"},
  AvgDialog_122694_Content_18 = {
    Text = "À l'instant où elle allait toucher le sol, vous vous élancez et la rattrapez malgré tout — et la seconde suivante, vous le regrettez."
  },
  AvgDialog_122694_Content_19 = {
    Text = "Ces bras glacés s'enroulent autour de vous avec la souplesse désossée d'un invertébré, et un souffle saupoudré de cristaux de neige se déverse dans le creux de votre cou et la courbe de votre oreille."
  },
  AvgDialog_122694_Content_2 = {
    Text = "Vous vous armez de courage et, luttant contre un froid si violent que vos dents claquent à vous en mordre la langue, vous poussez la porte de la chambre de Caraboo."
  },
  AvgDialog_122694_Content_20 = {
    Text = "Hi hi~ Oh là là, je le savais. %player% est vraiment trop sensible."
  },
  AvgDialog_122694_Content_21 = {
    Text = "Derrière elle, quelque chose de plus doux et de plus froid encore s'enroule lentement et langoureusement autour de vous, vous entraînant à travers couche après couche de neige profonde."
  },
  AvgDialog_122694_Content_22 = {
    Text = "Vous vous débattez, des sons étouffés restant coincés dans votre gorge, et juste avant de perdre complètement connaissance, vous entendez ce petit rire malicieux."
  },
  AvgDialog_122694_Content_23 = {
    Text = "Tout va bien. Votre Fée sera très, très douce avec son précieux petit agneau~"
  },
  AvgDialog_122694_Content_3 = {
    Text = "Caraboo, qu'est-ce que tu as encore fa— sss, il fait un froid glacial ici."
  },
  AvgDialog_122694_Content_4 = {
    Text = "Mais cette petite silhouette espiègle ne surgit pas de façon spectaculaire pour exhiber son dernier tour, comme elle le fait toujours."
  },
  AvgDialog_122694_Content_5 = {
    Text = "Un rouge inhabituel colore son visage. Elle a l'air, eh bien, presque... pitoyable."
  },
  AvgDialog_122694_Content_6 = {
    Text = "Gardien du secret, qu'est-ce que je fais~ ? Je me sens vraiment bizarre. Mon corps se sent étrange, ma tête aussi."
  },
  AvgDialog_122694_Content_7 = {
    Text = "J'ai tellement froid. Je suis presque en train de mourir de froid ici."
  },
  AvgDialog_122694_Content_8 = {
    Text = "Et j'ai aussi tellement chaud — assez chaud pour que mes jambes flanchent, je ne peux pas faire un seul pas."
  },
  AvgDialog_122694_Content_9 = {
    Text = "Elle mord sa lèvre inférieure et, les yeux débordant de larmes, ouvre grand les bras vers vous — la posture d'un enfant qui supplie d'être tenu."
  },
  AvgDialog_122696_Content_1 = {
    Text = "Dans la salle vide, seuls vos pas et ceux de Murphy résonnent."
  },
  AvgDialog_122697_Content_1 = {
    Text = "Aujourd'hui, le ciel s'assombrit plus rapidement que d'habitude, et il fait gris, indiquant clairement qu'il va pleuvoir."
  },
  AvgDialog_122697_Content_10 = {
    Text = "Mouchette leva la tête, son visage teinté d'un rougissement anormal, révélant un sourire mêlé de confusion et de ferveur."
  },
  AvgDialog_122697_Content_11 = {
    Text = "Bats-moi, tout de suite, immédiatement !"
  },
  AvgDialog_122697_Content_13 = {
    Text = "Avant que vous puissiez prononcer un mot, sa hache se balance. Elle effleure votre joue avec une précision terrifiante, ne laissant derrière elle qu'un sifflement d'air glacé."
  },
  AvgDialog_122697_Content_14 = {
    Text = "Le vent s'infiltre dans ton col sans permission, inondant ta poitrine et provoquant une réaction instinctive de chair de poule sur ton corps."
  },
  AvgDialog_122697_Content_15 = {
    Text = "Pourquoi cela a-t-il dégénéré en bagarre à cause d'un désaccord !?"
  },
  AvgDialog_122697_Content_16 = {
    Text = "Votre question a été ignorée par la hache et son propriétaire."
  },
  AvgDialog_122697_Content_17 = {
    Text = "<Shake:Mouchette?>"
  },
  AvgDialog_122697_Content_18 = {
    Text = "Mouchette !?"
  },
  AvgDialog_122697_Content_19 = {
    Text = "Sous tes questions incessantes, la hache finit par s'arrêter. Elle appuyait contre ton épaule, profondément enfoncée dans le mur."
  },
  AvgDialog_122697_Content_2 = {
    Text = "Pour éviter de se faire tremper, tu as couru rapidement vers le dortoir, mais une silhouette a barré ton chemin."
  },
  AvgDialog_122697_Content_20 = {
    Text = "Et le maître de la hache se tient juste devant vous, le visage rouge, serrant les poings et attrapant fermement votre col."
  },
  AvgDialog_122697_Content_21 = {
    Text = "<Shake:Ferme-la... Ça fait mal... Je souffre... Seule une bataille pourra arrêter ça...>"
  },
  AvgDialog_122697_Content_22 = {
    Text = "Les doigts qui agrippent votre col continuent d'exercer une pression, passant de la couleur chair à un teint pâle, signifiant l'entêtement et le refus de céder de leur propriétaire."
  },
  AvgDialog_122697_Content_23 = {
    Text = "Je déteste quand les autres imposent leurs idées aux autres..."
  },
  AvgDialog_122697_Content_24 = {
    Text = "Ce n'est que la Rivière sacrée, et tu penses qu'elle peut m'influencer ? <Shake: Tu me sous-estimes...>"
  },
  AvgDialog_122697_Content_25 = {
    Text = "Mouchette exhala avec force en parlant, essayant de calmer l'influence de la Sainte Rivière sur elle, mais tu pouvais sentir la chaleur bouillonnante en elle, le désir errant et le conflit intérieur."
  },
  AvgDialog_122697_Content_26 = {
    Text = "Remarquant les émotions de Mouchette, vous ne pouviez vous empêcher de soupirer, prenant sa main et guidant la fille à saisir à nouveau le manche de la hache."
  },
  AvgDialog_122697_Content_27 = {
    Text = "<Shake:Que fais-tu?>"
  },
  AvgDialog_122697_Content_28 = {
    Text = "Tu ne veux pas te battre ? Alors battons-nous."
  },
  AvgDialog_122697_Content_29 = {
    Text = "Peu importe comment tu veux te battre, peu importe combien de temps tu veux te battre, je serai à tes côtés jusqu'à la fin."
  },
  AvgDialog_122697_Content_3 = {
    Text = "Mouchette ? Qu'est-ce qui ne va pas ?"
  },
  AvgDialog_122697_Content_30 = {Text = "新增"},
  AvgDialog_122697_Content_31 = {
    Text = "Les yeux de la fille s'agrandissent soudainement, te regardant avec surprise."
  },
  AvgDialog_122697_Content_32 = {
    Text = "À ce moment-là, la pluie tant attendue tomba enfin, des gouttes atterrissant sur le visage de Mouchette, glissant le long de son menton et disparaissant dans ton col, s'écoulant le long de ta poitrine."
  },
  AvgDialog_122697_Content_33 = {
    Text = "Puis, plus de gouttes de pluie sont arrivées, frappant sauvagement le sol, fouettant vos joues et celles de la fille, apportant une sensation de démangeaison."
  },
  AvgDialog_122697_Content_34 = {
    Text = "<Shake:Hahaha ! Maintenant, c'est la réponse que je voulais.>"
  },
  AvgDialog_122697_Content_35 = {
    Text = "Les choses commencent à devenir intéressantes, n'est-ce pas ?"
  },
  AvgDialog_122697_Content_36 = {
    Text = "Mouchette saisit le manche de la hache et tira la hache du mur, mais elle ne la balança pas à nouveau ; au lieu de cela, elle vous regarda, vous fixant directement."
  },
  AvgDialog_122697_Content_37 = {
    Text = "D'habitude, je ne me bats pas à mains nues avec les autres, mais parfois il faut essayer de nouvelles choses, non ?"
  },
  AvgDialog_122697_Content_38 = {
    Text = "La vie est si longue, et certaines choses intéressantes doivent être vécues personnellement et progressivement."
  },
  AvgDialog_122697_Content_39 = {
    Text = "Mouchette dit, s'avançant lentement vers toi. Et cette hache était silencieusement appuyée contre le mur, recevant le baptême humide du monde."
  },
  AvgDialog_122697_Content_4 = {
    Text = "Elle garde la tête baissée, silencieuse. Tu peux seulement sentir son tourment intérieur par la façon dont ses jointures sont devenues blanches, serrant sa hache avec une force tremblante."
  },
  AvgDialog_122697_Content_5 = {
    Text = "<Shake:Mouchette !?>"
  },
  AvgDialog_122697_Content_6 = {
    Text = "Enfin, la fille parla, mais sa voix portait une nuance d'hésitation et d'incertitude."
  },
  AvgDialog_122697_Content_7 = {
    Text = "%player%, j'ai... j'ai besoin de votre aide..."
  },
  AvgDialog_122697_Content_8 = {
    Text = "Besoin d'aide ? Pas de problème. Que voulez-vous ?"
  },
  AvgDialog_122697_Content_9 = {
    Text = "<Shake:J'ai besoin de toi...>"
  },
  AvgDialog_122700_Content_1 = {
    Text = "Bienvenue dans mon théâtre. Vous arrivez juste à temps, {Male=M., Female=Mlle} Gardien."
  },
  AvgDialog_122700_Content_10 = {
    Text = "Se propager... renaître... ne me dites pas que vous aussi—"
  },
  AvgDialog_122700_Content_11 = {
    Text = "Ah, en fait... je viens de me rappeler que le devoir du Professeur Dor n'est pas encore terminé... je ferais mieux de—"
  },
  AvgDialog_122700_Content_12 = {
    Text = "Tu te retournes pour partir, mais tes pas te mènent sans que tu ne t'en rendes compte devant Arachne."
  },
  AvgDialog_122700_Content_13 = {
    Text = "Oui, je suis sous l'influence de la rivière... et vous êtes sous l'emprise du Destin. Cette nuit est une nuit qui n'appartient qu'à nous deux."
  },
  AvgDialog_122700_Content_14 = {
    Text = "Une pièce qui devait toujours être jouée — et enfin, son acteur principal prédestiné est arrivé."
  },
  AvgDialog_122700_Content_15 = {
    Text = "Le souffle d'Arachne s'est déjà posé sur ton oreille, chaud et subtil."
  },
  AvgDialog_122700_Content_16 = {
    Text = "Son sourire reste aussi serein que toujours. Mais au plus profond de ces yeux insondables, quelque chose brûle : une flamme que vous n'avez jamais vue auparavant, comme si elle pouvait consumer tout ce qu'elle touche."
  },
  AvgDialog_122700_Content_17 = {
    Text = "Non, non, ça ne va pas... Arachne... je..."
  },
  AvgDialog_122700_Content_18 = {
    Text = "Inutile de fuir, %player%. La toile a tissé chaque possibilité en place. Elle nous guidera tous les deux à travers la représentation de ce soir."
  },
  AvgDialog_122700_Content_19 = {
    Text = "Une toile invisible se referme autour de vous, drainant jusqu'à la dernière once de vos forces, engloutissant toute velléité de résistance."
  },
  AvgDialog_122700_Content_2 = {
    Text = "Tu pousses la lourde porte du théâtre, la lumière de la lune filtre à travers les hautes fenêtres, la fraîcheur de la rosée nocturne et la douce voix d'Arachne dans le théâtre te réveille brusquement."
  },
  AvgDialog_122700_Content_20 = {
    Text = "Les fils se tendent. Vous regardez ce visage si proche du vôtre, et votre cœur se serre, votre souffle s'accélère."
  },
  AvgDialog_122700_Content_21 = {
    Text = "Le Destin dicte que vous n'avez jamais voulu fuir. Vous vouliez cela : <Italic:Vous> vouliez venir ici, vouliez voir cette représentation jusqu'au bout, sans autre public que vous deux."
  },
  AvgDialog_122700_Content_22 = {
    Text = "Vous... vous avez réécrit mon Destin?!"
  },
  AvgDialog_122700_Content_23 = {
    Text = "Il n'y a rien que j'aie jamais réécrit, {Male=M., Female=Mlle} Gardien. J'ai simplement remis votre Destin sur le chemin qu'il était toujours censé emprunter."
  },
  AvgDialog_122700_Content_24 = {
    Text = "Arachne... tu... tu peux complètement changer le cours du destin, éviter l'influence de la Rivière sacrée... pourquoi ne pas le faire ?"
  },
  AvgDialog_122700_Content_25 = {
    Text = "Pourquoi l'aurais-je fait?"
  },
  AvgDialog_122700_Content_26 = {
    Text = "Pour une actrice qui connaît le script par cœur depuis longtemps, l'inattendu est le plus rare des cadeaux que le Destin ait jamais daigné offrir..."
  },
  AvgDialog_122700_Content_27 = {
    Text = "Les mots doux d'Arachne flottent à tes oreilles. Elle n'est plus paisible et lointaine, sa respiration tremble doucement, son sourire est à portée de main."
  },
  AvgDialog_122700_Content_28 = {
    Text = "Et il se trouve... qu›il n›y a aucune objection à une fin où personne n›est blessé."
  },
  AvgDialog_122700_Content_29 = {
    Text = "La toile de fils est froide, souple, s›accrochant avec une proximité qui ne laisse aucune place pour respirer, se resserrant, traversant le tissu, contre la peau."
  },
  AvgDialog_122700_Content_3 = {
    Text = "Attendez ! Je devrais être endormi dans mon dortoir. Comment ai–je atterri ici... c›est vous qui avez fait ça ?"
  },
  AvgDialog_122700_Content_30 = {
    Text = "Puis des chélicères se referment autour de vous, et de froids pédipalpes écartent vos lèvres, scellant toute résistance qui n›avait pas encore trouvé ses mots."
  },
  AvgDialog_122700_Content_31 = {
    Text = "Les fils commencent à guider vos membres. Doucement, et sans appel."
  },
  AvgDialog_122700_Content_32 = {
    Text = "N›ayez crainte, Gardien. Il n›est nul besoin de résister à ce que le destin a choisi de vous offrir."
  },
  AvgDialog_122700_Content_33 = {
    Text = "Parce que... c›est aussi ce que vous désirez, n›est-ce pas ?"
  },
  AvgDialog_122700_Content_34 = {
    Text = "... c'est ça, Arachne... c'est... ce que je veux..."
  },
  AvgDialog_122700_Content_35 = {
    Text = "Bien sûr. Vous n›avez jamais été la marionnette du destin. Vous êtes le Gardien de Mizag, celui qui tient son destin entre ses propres mains."
  },
  AvgDialog_122700_Content_36 = {
    Text = "C›est exactement ce que vous voulez. C›est le destin qui se plie à votre volonté. C›est votre corps qui répond à votre propre appel."
  },
  AvgDialog_122700_Content_37 = {
    Text = "Les fils frémissent, comme le destin tirant un archet sur des cordes. Vous tendez la main, effleurant les pattes d›araignée oscillant doucement dans l›air, effleurant les mains qui n›ont jamais cessé de tourner le fuseau, effleurant les lignes de ce visage doux."
  },
  AvgDialog_122700_Content_38 = {
    Text = "Ce visage familier. La compassion qu›il porte toujours, la sérénité qui ne le quitte jamais. Et maintenant, à peine perceptible, autre chose — une chaleur remontant à la surface, sans défense, que vous n›avez jamais vue auparavant."
  },
  AvgDialog_122700_Content_39 = {
    Text = "Accueillons ensemble ce que le destin nous a apporté... {Male=M., Female=Mlle} Gardien."
  },
  AvgDialog_122700_Content_4 = {
    Text = "Vous avez suivi votre propre volonté. Vous <Italic:vouliez> venir ici. L›aviez–vous oublié ?"
  },
  AvgDialog_122700_Content_40 = {
    Text = "Deux fils du destin s›enroulent l›un autour de l›autre, tirant, cédant, sans cesse. Les ondulations tremblantes se propagent le long de la toile invisible, se dissolvant vers un bord sans limites, inaccessible."
  },
  AvgDialog_122700_Content_41 = {Text = "新增"},
  AvgDialog_122700_Content_5 = {
    Text = "Elle vous sourit. Une pression, semblable au poids du destin lui–même, se referme de toutes parts."
  },
  AvgDialog_122700_Content_6 = {
    Text = "Le monde a toujours vu le destin comme un carcan inéluctable, la source de toutes ses souffrances."
  },
  AvgDialog_122700_Content_7 = {
    Text = "Mais vous et moi, qui avons touché les fils du destin de nos propres mains, savons mieux que quiconque — il n›est que ce que nous avons nous–mêmes choisi d›en faire."
  },
  AvgDialog_122700_Content_8 = {
    Text = "Se propager, afin d'être détruites. Être détruites, afin de renaître."
  },
  AvgDialog_122700_Content_9 = {
    Text = "Encore et encore, sans fin... C'est tout ce qu'est le Destin, n'est-ce pas?"
  },
  AvgDialog_122780_Content_1 = {
    Text = "Transmission lointaine"
  },
  AvgDialog_122780_Content_2 = {
    Text = "C'est un document de test"
  },
  AvgDialog_122780_Content_3 = {
    Text = "C'est un document de test"
  },
  AvgDialog_122780_Content_4 = {
    Text = "C'est un document de test"
  },
  AvgDialog_122780_Content_5 = {
    Text = "C'est un document de test"
  },
  AvgDialog_122780_Content_6 = {
    Text = "C'est un document de test"
  },
  AvgDialog_122780_Content_7 = {Text = "Terminé"},
  AvgDialog_123116_Content_1 = {
    Text = "L'Agneau Perdu"
  },
  AvgDialog_123116_Content_10 = {
    Text = "Mais chaque prêtre qui est arrivé à Hawick — John, James, Anderson — a complètement perdu contact en peu de temps."
  },
  AvgDialog_123116_Content_11 = {
    Text = "Bons enfants... Après le Cataclysme, ils ont suivi les enseignements du Tout-Père, prenant l'initiative d'aller dans diverses paroisses pour répandre l'évangile du Tout-Père."
  },
  AvgDialog_123116_Content_12 = {
    Text = "Même dans une grande ville comme Londres, les gens ordinaires ont souvent du mal à prendre soin d'eux-mêmes après une catastrophe, et la situation à Hawick ne sera que pire. Pourquoi font-ils—"
  },
  AvgDialog_123116_Content_13 = {
    Text = "Tout comme ce que tu as fait pour ce monde et les mondes passés, messager pâle."
  },
  AvgDialog_123116_Content_14 = {
    Text = "Salvador joignit les mains, son expression dévouée et pleine de compassion alors qu'il priait."
  },
  AvgDialog_123116_Content_15 = {
    Text = "Parce que nos frères et sœurs souffrent."
  },
  AvgDialog_123116_Content_16 = {
    Text = "L'éradication de la souffrance sur cette terre est le devoir des Émissaires du Tout-Père ; ils ne peuvent abandonner les autres dans le désespoir à cause de la distance du voyage."
  },
  AvgDialog_123116_Content_17 = {
    Text = "...Je vois."
  },
  AvgDialog_123116_Content_18 = {
    Text = "Père Salvador, je vais t'aider à les trouver ensemble. \n Peu importe la vie ou la mort."
  },
  AvgDialog_123116_Content_19 = {
    Text = "À ce moment"
  },
  AvgDialog_123116_Content_2 = {
    Text = "Howick, une ville éloignée en périphérie de Londres"
  },
  AvgDialog_123116_Content_20 = {
    Text = "Salvador, il semble y avoir une lumière devant..."
  },
  AvgDialog_123116_Content_21 = {
    Text = "Votre voix s'arrête brusquement en raison d'une découverte inattendue : une cage rudimentaire apparaît soudainement à l'intérieur de la grotte vide."
  },
  AvgDialog_123116_Content_22 = {
    Text = "D'après l'inspection visuelle, au moins une douzaine de personnes sont enfermées dans la cage, chacune ayant l'air épuisée, plusieurs ayant le visage contusionné et des blessures sur tout le corps."
  },
  AvgDialog_123116_Content_23 = {
    Text = "<Shake:Henry... est mort ? Ils ont tiré sur Henry, tiré sur Henry mort... !>"
  },
  AvgDialog_123116_Content_24 = {
    Text = "La femme se tient la tête, murmurant pour elle-même, son regard sauvage et ses tremblements intenses révélant son instabilité."
  },
  AvgDialog_123116_Content_25 = {
    Text = "Soudain, elle lève la tête et vous remarque tous à proximité."
  },
  AvgDialog_123116_Content_26 = {
    Text = "<Shake:Non, ils arrivent, emmenez-nous d'ici vite !>"
  },
  AvgDialog_123116_Content_27 = {
    Text = "Son mouvement attira plus d'attention, et un homme dans une cage se précipita soudainement vers les barres, tendant la main pour saisir ton bras."
  },
  AvgDialog_123116_Content_28 = {
    Text = "Sauvez-moi ! Je ne veux pas devenir un sacrifice humain, je ne veux pas être sacrifié…"
  },
  AvgDialog_123116_Content_29 = {
    Text = "Aaaaaah——Emmenez-nous d'ici !"
  },
  AvgDialog_123116_Content_3 = {
    Text = "Si les informations fournies par \"Doll\" sont correctes, elles devraient être juste ici."
  },
  AvgDialog_123116_Content_30 = {
    Text = "Fermez-la tous *effacé* !"
  },
  AvgDialog_123116_Content_31 = {
    Text = "Un rugissement fort interrompit les cris des victimes, et les prisonniers semblaient extraordinairement terrifiés par le propriétaire de ce rugissement, effrayés à en perdre l'esprit."
  },
  AvgDialog_123116_Content_32 = {
    Text = "Le sacrifice n'a pas encore commencé, vous ce groupe de porcs, vous êtes déjà pressés de mourir !?"
  },
  AvgDialog_123116_Content_33 = {
    Text = "Des pas urgents suivirent."
  },
  AvgDialog_123116_Content_34 = {
    Text = "Cela devrait être le culte qui emprisonne ces gens, %player%, nous..."
  },
  AvgDialog_123116_Content_35 = {
    Text = "Restez cachés et pensez à un moyen de les secourir plus tard. Ils ont des armes, et dans le chaos, nous ne pouvons pas garantir la sécurité de ces personnes."
  },
  AvgDialog_123116_Content_36 = {
    Text = "Mais l'homme te tient toujours fermement, avec une telle force que cela menace presque de casser ton bras."
  },
  AvgDialog_123116_Content_37 = {
    Text = "Sauvez-nous, sauvez-nous d'abord ! Si vous ne nous sauvez pas, mourrez avec nous !!"
  },
  AvgDialog_123116_Content_38 = {
    Text = "Les pas se rapprochent, et l'état mental de l'autre partie ne peut clairement pas comprendre de raisonnement."
  },
  AvgDialog_123116_Content_39 = {
    Text = "Tu grattes les dents et le mets hors de combat d'un coup rapide."
  },
  AvgDialog_123116_Content_4 = {
    Text = "Je fais confiance à ton jugement, %player%."
  },
  AvgDialog_123116_Content_40 = {Text = "Ha..."},
  AvgDialog_123116_Content_41 = {
    Text = "Un léger rire résonna soudainement depuis le coin de la cellule."
  },
  AvgDialog_123116_Content_42 = {
    Text = "Tu tournes instinctivement la tête pour regarder, et dans la cage, une jeune fille étrangement vêtue te fixe, son léger sourire contrastant fortement avec l'environnement chaotique et fou de ce moment."
  },
  AvgDialog_123116_Content_43 = {
    Text = "Comme c'est intéressant ! Une seconde, on dit qu'on va sauver quelqu'un, la seconde d'après, on les met hors de combat..."
  },
  AvgDialog_123116_Content_44 = {
    Text = "L'état actuel de détachement t'a laissé momentanément figé sur place."
  },
  AvgDialog_123116_Content_45 = {
    Text = "Ne t'occupe pas de moi, continue."
  },
  AvgDialog_123116_Content_46 = {
    Text = "Tu ne te dépêches pas ? Les adeptes de l'Aube des Étoiles arriveront bientôt."
  },
  AvgDialog_123116_Content_47 = {Text = "...?"},
  AvgDialog_123116_Content_48 = {
    Text = "Le temps est essentiel, et il n'y a pas de place pour des bavardages inutiles. Vous n'avez d'autre choix que de laisser la fille derrière vous et de vous cacher avec Salvador dans l'ombre."
  },
  AvgDialog_123116_Content_49 = {
    Text = "Bientôt, deux cultistes armés de fusils à pompe sont apparus devant la cage. Ils se sont tenus de chaque côté, levant leurs armes et visant les canons à l'intérieur de la cage de prison."
  },
  AvgDialog_123116_Content_5 = {
    Text = "Que le Père de tous les bénisse et les protège des ombres, leur permettant de vivre en paix."
  },
  AvgDialog_123116_Content_50 = {
    Text = "Qui faisait tout ce bruit tout à l'heure ? Montre-toi !"
  },
  AvgDialog_123116_Content_51 = {
    Text = "Personne ne répondit. Les prisonniers se blottissaient dans les coins, tremblants, ou regardaient dans le vide, engourdis et silencieux.\nSauf pour cette étrange fille."
  },
  AvgDialog_123116_Content_52 = {
    Text = "Elle arborait toujours un sourire décontracté, observant avec désinvolture les fidèles armés de fusils."
  },
  AvgDialog_123116_Content_53 = {
    Text = "Ce type est-il un fou ? Il est si détendu même lorsque la mort est imminente."
  },
  AvgDialog_123116_Content_54 = {
    Text = "Dans ce monde maudit, où sont les gens normaux, ha ! Si nous étions aussi fous, ce serait peut-être beaucoup plus facile."
  },
  AvgDialog_123116_Content_55 = {
    Text = "J'espère que ce rituel réussira. J'en ai vraiment assez de ces brumes étranges..."
  },
  AvgDialog_123116_Content_56 = {
    Text = "Quand commence le rituel dont vous parlez ?"
  },
  AvgDialog_123116_Content_57 = {
    Text = "Le membre de la secte était visiblement stupéfait."
  },
  AvgDialog_123116_Content_58 = {
    Text = "De qui parlez-vous, de nous ?"
  },
  AvgDialog_123116_Content_59 = {
    Text = "Quoi d'autre ? Arrête de dire des bêtises et réponds à ma question."
  },
  AvgDialog_123116_Content_6 = {
    Text = "Salvador baissa la tête dévotement, murmura une prière, puis mena le chemin plus profondément dans la grotte."
  },
  AvgDialog_123116_Content_60 = {
    Text = "Le fidèle du culte était complètement enragé par la fille, ricanant alors qu'il levait la main et visait la jambe de celle-ci avec son arme."
  },
  AvgDialog_123116_Content_61 = {
    Text = "Folle, tout ce que tu as à faire est d'attendre docilement d'être sacrifiée. Je peux voir que tu n'as aucune idée de ce qui se passe."
  },
  AvgDialog_123116_Content_62 = {Text = "Bang—"},
  AvgDialog_123116_Content_63 = {
    Text = "Une force invisible a fait perdre son objectif à la balle, frappant la grotte au-dessus et suscitant une faible flamme—"
  },
  AvgDialog_123116_Content_64 = {
    Text = "Toi et Salvador êtes sortis de l'obscurité, lançant une embuscade sur les adeptes du culte."
  },
  AvgDialog_123116_Content_66 = {
    Text = "Tu as bien géré ton temps, il semble que tu n'es pas idiot après tout."
  },
  AvgDialog_123116_Content_67 = {
    Text = "Merci d'avoir distrait les cultistes pour nous, chère madame."
  },
  AvgDialog_123116_Content_68 = {
    Text = "Que le Père Dieu vous bénisse."
  },
  AvgDialog_123116_Content_69 = {
    Text = "Salvador traça le symbole sacré du Père Dieu dans l'air. \n Vous avez confisqué toutes les armes des cultistes, leur avez ordonné de s'agenouiller devant la cage et avez commencé l'interrogatoire."
  },
  AvgDialog_123116_Content_7 = {
    Text = "trois jours auparavant"
  },
  AvgDialog_123116_Content_70 = {
    Text = "Dis, quand a lieu le rituel ? Où a-t-il lieu ? La disparition des prêtres du Sanctuaire de Vie est-elle liée à vous !?"
  },
  AvgDialog_123116_Content_71 = {
    Text = "Sanctuaire de Vie…prêtre…?"
  },
  AvgDialog_123116_Content_72 = {
    Text = "C'est ça, John, James, Anderson, où sont-ils ?"
  },
  AvgDialog_123116_Content_73 = {
    Text = "Entendant cela, l'adepte de culte resta un moment figé, puis éclata de rire."
  },
  AvgDialog_123116_Content_74 = {
    Text = "<Shake:Nous nous racheterons selon la volonté du Tout-Père ! Oui, le Royaume Serein Libéré de la Dissolution est à portée de main !>"
  },
  AvgDialog_123116_Content_75 = {
    Text = "<Shake:<Big:Il est descendu ! Vous, malheureux, pourrirez ici pendant que le monde s'effondre !>>"
  },
  AvgDialog_123116_Content_76 = {
    Text = "Alors, la cérémonie est sur le point de commencer ? <Small:Je suppose que je dois me dépêcher.>"
  },
  AvgDialog_123116_Content_77 = {
    Text = "Qu'est-ce que ça veut dire de se dépêcher...? Tu sais quelque chose ?"
  },
  AvgDialog_123116_Content_78 = {
    Text = "La jeune fille ne répondit pas ; elle jeta un coup d'œil à vous et Salvador, révélant un sourire innocent et bien élevé.\nPour une raison quelconque, vous ressentiez une pointe de malice."
  },
  AvgDialog_123116_Content_79 = {
    Text = "Ah, au fait, je m'appelle Mouchette, quant à vos noms, eh bien — je ne suis pas intéressée."
  },
  AvgDialog_123116_Content_8 = {
    Text = "Tous les Prêtres envoyés par la Chantrie de la Vie à Hawick sont portés disparus ?"
  },
  AvgDialog_123116_Content_80 = {
    Text = "Je sais où se déroule la cérémonie, et je peux t'y emmener, mais..."
  },
  AvgDialog_123116_Content_81 = {
    Text = "J'ai besoin que tu me rendes un petit service."
  },
  AvgDialog_123116_Content_82 = {
    Text = "Quel service ? J'espère que tu pourras être clair."
  },
  AvgDialog_123116_Content_83 = {
    Text = "Elle ne répondit toujours pas, la jeune fille ne laissa qu'une phrase avant de partir en fredonnant un air entrecoupé."
  },
  AvgDialog_123116_Content_84 = {
    Text = "Hum☆hum ! Je vais d'abord faire quelques affaires. Dans dix minutes, on se retrouve dehors~"
  },
  AvgDialog_123116_Content_85 = {Text = "新增"},
  AvgDialog_123116_Content_86 = {
    Text = "C'est aussi bien ; nous pouvons d'abord contacter la Chantrie de la Vie pour envoyer des renforts afin d'aider ces personnes souffrantes."
  },
  AvgDialog_123116_Content_87 = {
    Text = "Il n'y a que ça à faire."
  },
  AvgDialog_123116_Content_88 = {
    Text = "En regardant dans la direction où la jeune fille était partie, le sentiment croissant d'inquiétude te faisait sentir comme si quelque chose remontait le long de ta colonne vertébrale."
  },
  AvgDialog_123116_Content_89 = {
    Text = "Sa source est le sentiment de déconnexion qui se cache sous l'extérieur naïf de l'autre, un extérieur qui est extrêmement proche de l'humanité mais terriblement faux..."
  },
  AvgDialog_123116_Content_9 = {
    Text = "Oui, après avoir perdu le contact avec le Père White, qui est responsable de la paroisse de Howick, le Vatican a décidé d'envoyer des renforts."
  },
  AvgDialog_123117_Content_1 = {
    Text = "Dans l'argent et le sang"
  },
  AvgDialog_123117_Content_10 = {
    Text = "…Je n'aurais pas dû discuter de ça avec toi."
  },
  AvgDialog_123117_Content_100 = {
    Text = "Mouchette… si tu es encore là… sors, s'il te plaît…"
  },
  AvgDialog_123117_Content_101 = {
    Text = "Pourtant, le vide reste vide. La fille nommée Mouchette est partie."
  },
  AvgDialog_123117_Content_102 = {Text = "新增"},
  AvgDialog_123117_Content_103 = {
    Text = "Tu fermes les yeux et laisses échapper un profond soupir. Il n'y a plus de temps. \n Salvador est toujours dehors, et la porte invisible est toujours là. Tu dois revenir en arrière."
  },
  AvgDialog_123117_Content_104 = {
    Text = "Désolé de t'avoir amené dans un monde aussi cruel... Je suis aussi désolé de ne pas avoir pu te ramener chez toi..."
  },
  AvgDialog_123117_Content_105 = {
    Text = "Dans la prochaine seconde, tu as coupé le lien avec la dimension mentale de Mouchette——"
  },
  AvgDialog_123117_Content_106 = {
    Text = "Après un bref moment de vertige, ton esprit est revenu dans la coquille, et tout est revenu au point de départ :"
  },
  AvgDialog_123117_Content_107 = {
    Text = "La porte invisible est toujours hors de contrôle, et la hache de Mo Xia repose tranquillement dans ta main."
  },
  AvgDialog_123117_Content_108 = {
    Text = "<Shake:Mouchette...J'ai...>"
  },
  AvgDialog_123117_Content_109 = {
    Text = "Tu saisis le manche, regardant la fille silencieuse. Elle se tient là dans les ruines de sa santé mentale, attendant le coup fatal."
  },
  AvgDialog_123117_Content_11 = {
    Text = "Tu pousses un soupir, le visage plein de déception. Salvador observe tout cela et ne peut s'empêcher de sourire légèrement."
  },
  AvgDialog_123117_Content_110 = {
    Text = "Peut-être est-ce un effet psychologique, mais vous avez toujours l'impression que ces yeux n'ont pas perdu toute leur raison.\nParce que vous avez déjà vu ces yeux sourire auparavant."
  },
  AvgDialog_123117_Content_111 = {
    Text = "<Shake:Combien de temps... vas-tu... juste me regarder...?>"
  },
  AvgDialog_123117_Content_112 = {
    Text = "Mouchette ! Tu es de retour ?!"
  },
  AvgDialog_123117_Content_113 = {
    Text = "<Shake:Je n'ai pas... mais j'ai... entendu... tes mots...>"
  },
  AvgDialog_123117_Content_114 = {
    Text = "Tu as raison... Les choses ne devraient pas être comme ça... Je ne peux pas abandonner sans même essayer..."
  },
  AvgDialog_123117_Content_115 = {
    Text = "Mouchette utilise ses dernières forces pour te saisir et toucher la clé en argent sur ta poitrine."
  },
  AvgDialog_123117_Content_116 = {
    Text = "Peu importe le résultat, la porte invisible disparaîtra..."
  },
  AvgDialog_123117_Content_117 = {
    Text = "Je ne laisserai jamais... cet endroit devenir un autre monde de désastre de brouillard..."
  },
  AvgDialog_123117_Content_118 = {
    Text = "Surtout après avoir appris à quel point vous avez travaillé dur pour sauver ce monde"
  },
  AvgDialog_123117_Content_119 = {
    Text = "Ensuite, la clé en argent à ta poitrine s'active automatiquement, émettant une lumière qui teint ta vue en blanc."
  },
  AvgDialog_123117_Content_12 = {
    Text = "Mouchette, c'est vraiment un enfant spécial... juste spécial, mais c'est toujours un très bon enfant."
  },
  AvgDialog_123117_Content_120 = {
    Text = "Tu as entendu un cri perçant, un gémissement douloureux, la distorsion d'une flûte et le bruit de quelque chose qui se brise."
  },
  AvgDialog_123117_Content_121 = {
    Text = "Ou peut-être, ce ne sont que des hallucinations causées par ta tension, car dans cette étendue de pure blancheur, tu as perdu le contrôle de tes sens et de ta perception du temps."
  },
  AvgDialog_123117_Content_122 = {
    Text = "Après une période de temps indéterminée, lorsque toutes les hallucinations auditives s'estompent, vos différents sens reviennent enfin —"
  },
  AvgDialog_123117_Content_123 = {
    Text = "Le brouillard a disparu. La Porte est partie. Il ne reste que l'autel ensanglanté, et Salvador, te regardant avec des yeux vides et inquiets."
  },
  AvgDialog_123117_Content_124 = {
    Text = "L'Envoyé Pâle, nous... avons échoué ?"
  },
  AvgDialog_123117_Content_125 = {Text = "新增"},
  AvgDialog_123117_Content_126 = {
    Text = "À ce moment-là, un léger rire résonna derrière vous."
  },
  AvgDialog_123117_Content_127 = {
    Text = "%player%, Salvador, qu'est-ce que vous attendez ? La mission est terminée."
  },
  AvgDialog_123117_Content_128 = {
    Text = "<Big:MOUCHETTE— !!>"
  },
  AvgDialog_123117_Content_129 = {
    Text = "Sous le choc, tu as crié, mais la seconde d'après, tu n'as pas pu t'empêcher de sourire."
  },
  AvgDialog_123117_Content_13 = {
    Text = "Bon enfant ? S'il te plaît, ne utilise pas ce mot pour décrire... Attendez, avez-vous entendu quelque chose ?"
  },
  AvgDialog_123117_Content_130 = {
    Text = "Pas besoin de crier, je peux entendre clairement. De toute façon, la bataille excitante est terminée, il ne reste plus que la vie quotidienne ennuyeuse."
  },
  AvgDialog_123117_Content_131 = {
    Text = "Après être rentré, j'aimerais vraiment prendre une tasse de thé au cacao de noisette, oh… il n'y en a pas ici, alors prenons un petit gâteau."
  },
  AvgDialog_123117_Content_132 = {
    Text = "Nous pouvons discuter en dégustant des cupcakes, par exemple, qui est Murphy, qui est Liz, qui est Dole, et quelles aventures intéressantes avez-vous vécues avec le Corps de l'Éveil ?"
  },
  AvgDialog_123117_Content_133 = {
    Text = "De toute façon, je ne peux pas revenir, je dois juste en apprendre davantage sur ce monde."
  },
  AvgDialog_123117_Content_134 = {
    Text = "Je pense que cette demande %player% ne sera pas refusée."
  },
  AvgDialog_123117_Content_135 = {
    Text = "Salvador te regarde avec un sourire, et toi, tu souris aussi en regardant Mouchette.\n La brume se dissipe, la lumière de la lune dans le ciel nocturne tombe sur vous, projetant une lueur douce."
  },
  AvgDialog_123117_Content_136 = {
    Text = "Tu as encore beaucoup de questions à poser à Mouchette, mais tu les as gardées pour toi —"
  },
  AvgDialog_123117_Content_137 = {
    Text = "Peut-être à cause de cette belle lumière lunaire, ou peut-être à cause de quelque chose que tu ne peux pas expliquer, une sensation proche de celle de « renaître » après avoir échappé à la mort."
  },
  AvgDialog_123117_Content_138 = {
    Text = "Laisse tomber, le rapport peut être rédigé à tout moment, mais célébrer l'arrivée de visiteurs d'un autre monde, la chance de renaître dans ce nouveau monde ne se présente pas souvent."
  },
  AvgDialog_123117_Content_139 = {
    Text = "Félicitations, tu es devenu un Éveilleur, Mouchette. À partir de maintenant, cet endroit n'est plus seulement notre monde, c'est aussi le tien..."
  },
  AvgDialog_123117_Content_14 = {
    Text = "Il semble que quelqu'un pleure... et les pleurs deviennent de plus en plus forts..."
  },
  AvgDialog_123117_Content_140 = {
    Text = "Réveilleur Mouchette\nBienvenue dans notre monde"
  },
  AvgDialog_123117_Content_15 = {
    Text = "Vous écoutiez attentivement, mais vous n'entendiez rien. \n Vous regardiez à nouveau Salvador, et il secouait doucement la tête."
  },
  AvgDialog_123117_Content_16 = {
    Text = "À ce moment-là, Mouchette poussa soudainement un cri perçant, s'inclina et se tenant les oreilles de douleur."
  },
  AvgDialog_123117_Content_17 = {
    Text = "<Shake:Attendez une seconde... Quelqu'un, non, beaucoup de gens, crient et hurlent dans ma tête...>"
  },
  AvgDialog_123117_Content_18 = {
    Text = "Tu sens que quelque chose ne va pas et tu vérifies l'état de Mouchette, mais tu ne vois qu'elle tremble de douleur sans cesse, avec ses pupilles qui se dilatent constamment."
  },
  AvgDialog_123117_Content_19 = {
    Text = "Dérapage ? Serait-ce à cause du liquide de cœur d'argent... ?"
  },
  AvgDialog_123117_Content_2 = {
    Text = "Sous un ciel infini d'argent et de sang, la brume épaisse se déchaîne, la porte invisible rayonne de lumière, mais elle ne semble plus invincible maintenant——"
  },
  AvgDialog_123117_Content_20 = {
    Text = "Liquide de Cœur d'argent !?"
  },
  AvgDialog_123117_Content_21 = {
    Text = "Vous avez soigneusement examiné les taches de sang sur Mouchette, et au milieu du rouge sombre, le liquide argenté s'écoulait lentement, s'infiltrant dans son corps à travers sa peau exposée."
  },
  AvgDialog_123117_Content_22 = {
    Text = "Mouchette est venue dans notre monde à travers un rituel de sacrifice, et ces liquides de cœur d'argent ont servi d'offrandes, la rendant probablement également une «partie» du rituel..."
  },
  AvgDialog_123117_Content_23 = {
    Text = "Non, il y a trop de liquide de cœur d'argent ici, c'est trop mélangé, il faut le traiter immédiatement, sinon elle, en tant que personne ordinaire, va devenir folle !"
  },
  AvgDialog_123117_Content_24 = {
    Text = "Vous et Salvador avez immédiatement commencé à nettoyer le liquide argenté sur Mouchette, mais il était déjà trop tard—"
  },
  AvgDialog_123117_Content_25 = {
    Text = "<Red:<Shake:AAAAHHH—!>>"
  },
  AvgDialog_123117_Content_26 = {
    Text = "Avec un cri de douleur, les pupilles de Mouchette se dilatent et se fendent, son corps se brise et se déforme, projetant une grande quantité de chair, se mutant en une existence difficile à décrire."
  },
  AvgDialog_123117_Content_27 = {
    Text = "Ces chairs éclatées giclent sur vous et Salvador, ainsi que sur la porte invisible, provoquant des ondulations à la surface de cette dernière, inconnue et sinistre."
  },
  AvgDialog_123117_Content_28 = {
    Text = "Quelque chose cloche, «Porte» est en train de changer…"
  },
  AvgDialog_123117_Content_29 = {
    Text = "Avant même d'avoir terminé, un puissant impact se propage à travers le lien entre la porte invisible et la clé en argent, te laissant soudain sans voix."
  },
  AvgDialog_123117_Content_3 = {
    Text = "La clé en argent dans ta main émet une lueur éblouissante et résolue, fermant progressivement la déchirure dans le temps et l'espace, tout en éliminant lentement toutes les anomalies causées par la cérémonie."
  },
  AvgDialog_123117_Content_30 = {
    Text = "Sous un trauma mental insupportable, tu saignes du nez sans arrêt, perdant toute ta force, à genoux."
  },
  AvgDialog_123117_Content_31 = {
    Text = "<Red:<Shake:Tuez, tuez, tuez ! Tuez tout le monde !>>"
  },
  AvgDialog_123117_Content_32 = {
    Text = "<Red:<Shake:Hahaha ! Regardez ce monde brûler !>>"
  },
  AvgDialog_123117_Content_33 = {
    Text = "La hache qui a autrefois dégagé un chemin pour vous est maintenant levée haut, pointée vers votre tête. Et vous êtes vidé de toute énergie par un étrange lien mental, perdant connaissance et incapable de bouger."
  },
  AvgDialog_123117_Content_34 = {
    Text = "<Shake:Mouchette...>"
  },
  AvgDialog_123117_Content_35 = {
    Text = "Tu luttent pour parler, mais ta voix est rauque et faible, incapable d'éveiller la raison de Mouchette."
  },
  AvgDialog_123117_Content_37 = {
    Text = "Finalement, la hache tomba lourdement, s'enfonçant profondément dans la chair—\n au dernier moment, Salvador se mit devant vous, prenant le coup."
  },
  AvgDialog_123117_Content_38 = {
    Text = "Le sang coule le long de l'épaule de Salvador, mais son expression ne montre aucune rancœur, seulement de la compassion et de la bonté."
  },
  AvgDialog_123117_Content_39 = {
    Text = "Enfant, je sais que ce n'est pas de ta volonté. Tu es juste perdu."
  },
  AvgDialog_123117_Content_4 = {
    Text = "Longtemps après, l'argent et le sang flottants commencèrent à tomber, se posant sur le sol, sur vous, et la brume épaisse autour de vous devenait visiblement plus claire, se rétractant. Tout allait mieux."
  },
  AvgDialog_123117_Content_40 = {
    Text = "<Red:<Shake:TUEZ ! DÉTRUISEZ TOUT !>>"
  },
  AvgDialog_123117_Content_41 = {
    Text = "La folie a complètement consumé Mouchette ; en ce moment, elle est poussée uniquement par un impulsion violente de destruction et de massacre."
  },
  AvgDialog_123117_Content_42 = {
    Text = "<Shake:Salvador, inutile, elle...>"
  },
  AvgDialog_123117_Content_43 = {
    Text = "Tu as jeté un œil à Mouchette, qui ne pouvait plus être considérée comme une « personne », ta voix tremblait. \n Il est évident qu'à l'instant précédent, elle était si vivante."
  },
  AvgDialog_123117_Content_44 = {
    Text = "Non, Messager pâle. Elle est juste perdue."
  },
  AvgDialog_123117_Content_45 = {
    Text = "Salvador s'avança, se dirigeant vers la hache tranchante levée à nouveau par Mouchette."
  },
  AvgDialog_123117_Content_46 = {
    Text = "Du sang éclaboussa de la lame de la hache sur son visage, mais Salvador ne montra aucun signe de peur."
  },
  AvgDialog_123117_Content_47 = {
    Text = "Je suis désolé de ne pas avoir été là lorsque l'Aube des Étoiles a sacrifié des humains et vous a invoqué."
  },
  AvgDialog_123117_Content_48 = {
    Text = "La goutte de sang de la hache de Mouchette glissa sur la joue de Salvador, comme une larme."
  },
  AvgDialog_123117_Content_49 = {
    Text = "Salvador n'a pas essuyé cette « larme », il a simplement tenu fermement la lame de la hache de Mouchette, tout en levant l'autre main——"
  },
  AvgDialog_123117_Content_5 = {
    Text = "Bientôt, les anomalies de la Porte de la Dimension s'affaibliront à leur niveau le plus bas, Mouchette, ce sera ta meilleure chance de rentrer chez toi."
  },
  AvgDialog_123117_Content_50 = {
    Text = "Mais en ce moment, je suis ici, je vais te sauver."
  },
  AvgDialog_123117_Content_51 = {
    Text = "La main ensanglantée du Prêtre toucha le front de la Jeune Fille. En un instant, une lumière brillante et résolue irradia du point de contact entre eux."
  },
  AvgDialog_123117_Content_52 = {
    Text = "C'est un Prêtre d'un monde, conférant une bénédiction au Agneau d'un autre monde."
  },
  AvgDialog_123117_Content_53 = {
    Text = "Alors que cette lumière s'illumine, la vive douleur dans ta tête s'est soudainement atténuée, comme si quelqu'un avait pris en charge toute ta souffrance..."
  },
  AvgDialog_123117_Content_54 = {
    Text = "Salvador, arrête, c'est une connexion dimensionnelle que personne ne peut supporter !"
  },
  AvgDialog_123117_Content_55 = {Text = "Je sais."},
  AvgDialog_123117_Content_56 = {
    Text = "La voix de Salvador trembla et se brisa. Ce niveau de lien était, même pour lui, un tourment qui transcendait toutes les limites."
  },
  AvgDialog_123117_Content_57 = {
    Text = "Bientôt, il ne pouvait plus le supporter et des larmes de sang coulèrent de lui."
  },
  AvgDialog_123117_Content_58 = {
    Text = "Mais étant l'Exécuteur du Père Dieu, je dois donner tout ce que j'ai."
  },
  AvgDialog_123117_Content_59 = {
    Text = "D'autres larmes de sang coulent de sous le bandeau de Salvador, mais cette couleur est contaminée par la forte lumière de «Bénédiction», comme si ce qui coulait de ses yeux n'était pas du sang, mais de l'or fondu."
  },
  AvgDialog_123117_Content_6 = {
    Text = "Je vais toujours régler l'énergie de la clé d'argent au maximum, suffisamment pour que tu puisses traverser la dimension en toute sécurité."
  },
  AvgDialog_123117_Content_60 = {
    Text = "Cet or tombe, gouttant sur le dos de la main de Mouchette, laissant tomber sa coque dorée, révélant sa couleur rouge sang, se fusionnant avec le sang humain éclaboussé sur Mouchette et le sang de Mouchette elle-même."
  },
  AvgDialog_123117_Content_61 = {
    Text = "Au nom du Père Dieu, Mouchette, je ne te laisserai pas emprunter le chemin de l'égarement."
  },
  AvgDialog_123117_Content_62 = {
    Text = "Avec cet appel, le front de Mouchette s'illumine d'une lumière intense, cette lumière est si brûlante qu'elle écrase complètement le sang qui couvre Mouchette et la lumière de la Porte invisible."
  },
  AvgDialog_123117_Content_63 = {
    Text = "C'est l'éclat que Salvador a émis en donnant toute sa vie."
  },
  AvgDialog_123117_Content_64 = {
    Text = "<Shake:Ugh...>"
  },
  AvgDialog_123117_Content_65 = {
    Text = "Dans cette lumière qui éclaire tout, les yeux fissurés obtiennent un moment de clarté, regardant le dos de leur main avec le peu de raison qui leur reste."
  },
  AvgDialog_123117_Content_66 = {
    Text = "Il n'y a plus aucun signe du sang de Salvador là-bas, car tout le sang s'est déjà mélangé."
  },
  AvgDialog_123117_Content_67 = {
    Text = "Le sang de la victime et de l'auteur, le sang du coupable et du rédempteur, s'entrelacent dans la même rivière de sang."
  },
  AvgDialog_123117_Content_68 = {
    Text = "J'ai... dit..."
  },
  AvgDialog_123117_Content_69 = {
    Text = "<Shake:Je déteste... sacrifier les autres... pour me sauver...>"
  },
  AvgDialog_123117_Content_7 = {
    Text = "Ce serait bien de pouvoir prendre une douche avant de traverser. Revenir couvert de sang, je me demande si cela effraierait l'enquêteur."
  },
  AvgDialog_123117_Content_70 = {
    Text = [[
Mo Xia repoussa Salvador avec le dernier reste de sa raison et te regarda. 
 Tu la vis soulever la hache de toutes ses forces, et tu vis aussi ses larmes couler sur son visage.]]
  },
  AvgDialog_123117_Content_71 = {
    Text = "À partir de maintenant... ne le laisse plus jamais faire ça... Ceux qui méritent vraiment de vivre sont des gens comme lui..."
  },
  AvgDialog_123117_Content_72 = {
    Text = "À cause du rituel... la porte invisible fait de moi une partie de cela..."
  },
  AvgDialog_123117_Content_73 = {
    Text = "<Shake:Si tu me tues, cela se dissipera... Ces gens... seront également libérés...>"
  },
  AvgDialog_123117_Content_74 = {
    Text = "Et... ce n'est pas une désertion... c'est entraîner l'ennemi... avec vous..."
  },
  AvgDialog_123117_Content_75 = {
    Text = "Mouchette a utilisé ses dernières forces pour te passer la hache, tandis que toi, prenant la hache, tu ne pouvais que rester figé sur place."
  },
  AvgDialog_123117_Content_76 = {
    Text = "En fait... pourquoi ai-je fait... un choix que je ne peux même pas comprendre..."
  },
  AvgDialog_123117_Content_77 = {
    Text = "De toute évidence, détruire le monde est plus dans mon style..."
  },
  AvgDialog_123117_Content_78 = {
    Text = "Mouchette sanglote, et la seconde d'après, une goutte de larme tombe sans avertir de son œil, glissant le long de sa hache, se brisant dans la paume de ta main."
  },
  AvgDialog_123117_Content_79 = {
    Text = "Rapidement, ces yeux baignés de larmes commencèrent à devenir flous, lentement en train de sombrer dans la folie.\nMouchette va à nouveau perdre la raison."
  },
  AvgDialog_123117_Content_8 = {
    Text = "Avons-nous besoin de préparer une table et d'avoir quelques petits gâteaux pour le thé de l'après-midi ?"
  },
  AvgDialog_123117_Content_80 = {
    Text = "Messager pâle, s'il te plaît, ne... je la sauverai à nouveau."
  },
  AvgDialog_123117_Content_81 = {
    Text = "Salvador lutte pour se lever, sa voix un appel désespéré. Vous regardez la hache, votre esprit étant un orage de chagrin et de conflit."
  },
  AvgDialog_123117_Content_82 = {
    Text = "Ce n'était pas qu'une hache ; c'était une confiance en la vie et un adieu."
  },
  AvgDialog_123117_Content_83 = {
    Text = "<Shake:Donnez-moi un moment... Il doit y avoir une autre façon... il doit y avoir...>"
  },
  AvgDialog_123117_Content_84 = {
    Text = "Soudain, une méthode cruelle est apparue dans ton esprit —"
  },
  AvgDialog_123117_Content_85 = {
    Text = "Sans trop réfléchir, tu as saisi la Clé en Argent d'une main et la main de Mouchette de l'autre, plongeant dans les profondeurs troubles de la conscience."
  },
  AvgDialog_123117_Content_86 = {
    Text = "La seule méthode à laquelle vous pouvez penser pour forcer Mouchette à se transformer d'humain en Éveilleur est de passer par le lien de la clé d'argent."
  },
  AvgDialog_123117_Content_87 = {
    Text = "Au moment où tu t'immerges dans l'esprit de Mouchette, d'innombrables points lumineux se tordent et déferlent dans ta vision. \n Ils criaient tous et hurlaient, mais aucun d'eux n'était Mouchette."
  },
  AvgDialog_123117_Content_88 = {
    Text = "Dans le monde spirituel de Mouchette, il n'y a pas de Mouchette."
  },
  AvgDialog_123117_Content_89 = {
    Text = "Mouchette ! Mouchette, où es-tu…"
  },
  AvgDialog_123117_Content_9 = {
    Text = "C'est encore mieux. En regardant ce monde ennuyeux dans son désordre, les petits gâteaux doivent être encore plus délicieux."
  },
  AvgDialog_123117_Content_90 = {
    Text = "Aucune réponse. En tant que personne ordinaire, cette dernière « demande » était déjà la limite de ce qu'elle pouvait faire sous la folie et l'effondrement."
  },
  AvgDialog_123117_Content_91 = {
    Text = "Mouchette ? Tu as abandonné ? Ouais, tu as dit un jour qu'il y aurait quelques fois chaque semaine où tu ne voudrais pas vivre, et tu avais toujours le mot «mort» sur les lèvres..."
  },
  AvgDialog_123117_Content_92 = {
    Text = "Mais ce n'est pas comme ça... Salvador, moi, et cet enquêteur que tu mentionnes toujours, nous ne voulons pas que cela se produise..."
  },
  AvgDialog_123117_Content_93 = {
    Text = "Alors, Mouchette, sors..."
  },
  AvgDialog_123117_Content_94 = {
    Text = "Cependant, peu importe combien vous criez ou cherchez, tout ce qui vous entoure ce sont les hurlements fous et les cris."
  },
  AvgDialog_123117_Content_95 = {
    Text = "Mouchette a « disparu »"
  },
  AvgDialog_123117_Content_96 = {
    Text = "…en fait, j'ai pensé à une solution…"
  },
  AvgDialog_123117_Content_97 = {
    Text = "C'est en utilisant le Cœur d'argent qui s'est infiltré dans ton corps que je te transformerai en Éveilleur. Le risque d'échec est très élevé, mais c'est pour l'instant la seule solution à laquelle je peux penser."
  },
  AvgDialog_123117_Content_98 = {
    Text = "<Small:Je pensais que la partie la plus difficile était de « réveiller », mais je ne savais pas que je ne pouvais même pas trouver ton corps spirituel…>"
  },
  AvgDialog_123117_Content_99 = {
    Text = "Tu es tombé dans un long silence, sentant que chaque respiration était extrêmement difficile. \n En tant que Gardien, tu es bien conscient des conséquences pour les gens ordinaires lorsqu'ils sont exposés à un excès d'Argent."
  },
  AvgDialog_123118_Content_1 = {
    Text = "Dans le brouillard dense et infini, les gémissements glacials d'angoisse résonnent continuellement."
  },
  AvgDialog_123118_Content_10 = {
    Text = "L'amour du Père ne peut pas sauver tout le monde, mais nous ferons de notre mieux pour tendre la main à chaque victime."
  },
  AvgDialog_123118_Content_11 = {
    Text = "<Shake:Ne... ne crie plus...>"
  },
  AvgDialog_123118_Content_12 = {
    Text = "Sous le poids du traumatisme psychique, elle commença à saigner du nez de manière incontrôlable."
  },
  AvgDialog_123118_Content_13 = {
    Text = "<Shake:J'ai dit, <Big:ne rappelle plus...>>"
  },
  AvgDialog_123118_Content_15 = {
    Text = "Mouchette cria de colère, et dans son agitation, elle brandit sa hache pour frapper ces monstres en forme de brume, mais elle vit que la brume se divisait silencieusement puis se rassemblait rapidement."
  },
  AvgDialog_123118_Content_16 = {
    Text = "C'est inutile. Tant que le brouillard existe, ces monstres ne disparaîtront pas."
  },
  AvgDialog_123118_Content_17 = {
    Text = "Alors c'est pour cela que tu nous as demandé de « vous aider » à attirer les monstres, n'est-ce pas ?"
  },
  AvgDialog_123118_Content_18 = {
    Text = "Vous voulez maintenant régler vos comptes avec moi ? Il faut faire la queue, reculez un peu..."
  },
  AvgDialog_123118_Content_19 = {
    Text = "Mouchette essuie le sang qui coule de son nez et continue à balancer sa hache. La sensation du combat la fait vibrer de passion, elle ne peut tout simplement pas s'arrêter."
  },
  AvgDialog_123118_Content_2 = {
    Text = "@2I... sauvegarder @2..."
  },
  AvgDialog_123118_Content_20 = {
    Text = "Puisqu'il n'y a plus moyen de reculer maintenant, autant d'abord repousser cette vague !"
  },
  AvgDialog_123118_Content_21 = {
    Text = "Mouchette, sois raisonnable ! Si ça continue comme ça, tu vas…"
  },
  AvgDialog_123118_Content_22 = {
    Text = "Tu vas mourir, n'est-ce pas ?"
  },
  AvgDialog_123118_Content_23 = {
    Text = "De toute façon, il y a quelques fois par semaine où je ne veux plus vivre, justement..."
  },
  AvgDialog_123118_Content_24 = {
    Text = "Les mots de Mouchette s'arrêtèrent soudain. Une lumière brilla devant ses yeux, puis une certaine chaleur se répandit sur elle, affluant vers ses membres et son corps."
  },
  AvgDialog_123118_Content_25 = {
    Text = "Salvador a «bénit» Elle."
  },
  AvgDialog_123118_Content_26 = {
    Text = "<Shake:Que fais-tu ?!>"
  },
  AvgDialog_123118_Content_27 = {
    Text = "Mouchette recule d'un pas sans s'en rendre compte.\nCette sensation de chaleur est trop étrangère. Elle ne devrait pas apparaître en elle."
  },
  AvgDialog_123118_Content_28 = {
    Text = "Nous, nous sommes ennemis, pourquoi..."
  },
  AvgDialog_123118_Content_29 = {
    Text = "J'ai dit que nous ne sommes pas ennemis."
  },
  AvgDialog_123118_Content_3 = {
    Text = "Sauvegarder @2... @2 moi..."
  },
  AvgDialog_123118_Content_30 = {
    Text = "Ne pas être un ennemi ne signifie pas être un partenaire !"
  },
  AvgDialog_123118_Content_31 = {
    Text = "Je ne serais pas assez naïf pour considérer quelqu'un que je n'ai rencontré que quelques fois comme un compagnon..."
  },
  AvgDialog_123118_Content_32 = {
    Text = "Mais nous avons déjà combattu ensemble contre ces cultistes, n'est-ce pas ? Ceux qui se battent côte à côte sont des partenaires."
  },
  AvgDialog_123118_Content_33 = {
    Text = "Au fait, je ne pense pas que ce soit ma théorie ennuyeuse de l'amour où tout le monde m'aime et j'aime tout le monde, je préfère..."
  },
  AvgDialog_123118_Content_34 = {
    Text = "Je préfère le comprendre comme la sagesse de survie dans ce monde cruel."
  },
  AvgDialog_123118_Content_35 = {
    Text = "La radiance du Tout-Père brille sur toute la terre ; même dans les terres désolées, frères et sœurs s'entraideront."
  },
  AvgDialog_123118_Content_36 = {
    Text = "Mouchette serre les lèvres, silencieuse. Son regard demeure méfiant et sceptique, mais finalement, cette méfiance et ce scepticisme s'estompent lentement, se transformant en une confusion et une légère nostalgie."
  },
  AvgDialog_123118_Content_37 = {
    Text = "Ses lèvres bougèrent, comme si elle murmurait quelque chose, mais à cause du volume trop bas, tu n'as pu entendre que les mots «enquêteur»."
  },
  AvgDialog_123118_Content_38 = {
    Text = "Nous pourrons discuter des morts la prochaine fois, j'ai encore des gens à rencontrer en rentrant."
  },
  AvgDialog_123118_Content_39 = {
    Text = "Tu fais référence à... l'enquêteur ?"
  },
  AvgDialog_123118_Content_4 = {
    Text = "<Shake:Arrête d'appeler ! Pourquoi ces brumes... hurlent-elles toujours ? !>"
  },
  AvgDialog_123118_Content_40 = {
    Text = "Sans attendre la réponse de Mouchette, un impact invisible surgit soudainement, te faisant dresser les cheveux sur la nuque tout en rendant le monstre dans la brume encore plus fou."
  },
  AvgDialog_123118_Content_41 = {
    Text = "Ce sentiment...<Shake:<Big:Le rituel a commencé !>>"
  },
  AvgDialog_123118_Content_42 = {
    Text = "La cérémonie commence ? Mais nous avons clairement sauvé ces humains."
  },
  AvgDialog_123118_Content_43 = {
    Text = "Et, Messager pâle, il n'y avait pas de Prêtres de la Chantrie de la Vie parmi les captifs tout à l'heure..."
  },
  AvgDialog_123118_Content_44 = {
    Text = "Les personnes que nous avons sauvées ne sont-elles que des sauvegardes ? Ou bien le timing du rituel est-il fixe, si bien qu'il doit être effectué même s'il n'y a pas assez de sacrifices ?"
  },
  AvgDialog_123118_Content_45 = {
    Text = "Ce n'est pas le moment de jouer au détective."
  },
  AvgDialog_123118_Content_46 = {
    Text = "Vas-tu continuer à papoter ici, ou viendras-tu avec moi ? Prends ta décision rapidement !"
  },
  AvgDialog_123118_Content_47 = {
    Text = "Mouchette affichait une expression impatiente, se retourna, faisant face à vous, et entra dans le brouillard épais."
  },
  AvgDialog_123118_Content_48 = {
    Text = "Mouchette !"
  },
  AvgDialog_123118_Content_49 = {
    Text = "Je sais ce qui t'inquiète. Cette fois, je ne ferai aucun tour de passe-passe."
  },
  AvgDialog_123118_Content_5 = {
    Text = "À cause de ce brouillard dense, il se peut que ce ne soit pas le « Désastre de Brouillard » de votre monde, et ces monstres ne sont pas les « Objets Anciens » dont vous parlez."
  },
  AvgDialog_123118_Content_50 = {
    Text = "Mouchette balança sa hache pour disperser la brume humanoïde qui l'attaquait en répondant."
  },
  AvgDialog_123118_Content_51 = {
    Text = "Bien que votre optimisme soit plutôt problématique et que certaines de vos paroles soient empreintes d'un idéalisme irréaliste qui doivent être mises en lumière, ..."
  },
  AvgDialog_123118_Content_52 = {
    Text = "Mais il y a toujours des gens qui insistent pour sauver ce monde ennuyeux.\n<Small:Tu en fais partie, tout comme l'enquêteur...>"
  },
  AvgDialog_123118_Content_53 = {
    Text = "Peut-être que vous vous entendez bien ?"
  },
  AvgDialog_123118_Content_54 = {
    Text = "Le sujet s'est-il un peu trop éloigné... Ces gens nous attendent toujours..."
  },
  AvgDialog_123118_Content_55 = {
    Text = "Alors pourquoi tu ne cours pas encore ? J'espère que cela pourra se terminer bientôt ; je veux rentrer chez moi."
  },
  AvgDialog_123118_Content_56 = {
    Text = "Allez, reste avec moi, ne reste pas derrière. Je suis le vanguard le plus rapide de l'équipe d'investigation du Royaume de la Brume !"
  },
  AvgDialog_123118_Content_57 = {
    Text = "La silhouette de Mouchette sprinta à travers le brouillard épais, et tu échangèrent un regard avec Salvador avant de la suivre."
  },
  AvgDialog_123118_Content_6 = {
    Text = "<Shake:Ils... qu'est-ce qu'ils sont ?>"
  },
  AvgDialog_123118_Content_7 = {
    Text = "Mouchette ne pouvait s'empêcher de se couvrir les oreilles, mais malheureusement, c'était futile."
  },
  AvgDialog_123118_Content_8 = {
    Text = "Cette douleur et ce désespoir s'infiltrent lentement dans la chair et les os de l'auditeur avec la brume épaisse, atteignant profondément l'âme."
  },
  AvgDialog_123118_Content_9 = {
    Text = "Je peux discerner que leurs âmes... sont les humains sacrifiés lors du dernier rituel."
  },
  AvgDialog_123119_Content_1 = {
    Text = "Entre les dimensions"
  },
  AvgDialog_123119_Content_10 = {
    Text = "Mouchette haussant les épaules, leva la main pour désigner la Porte de la Dimension qui crachait sans cesse de la brume épaisse, érodant ce monde."
  },
  AvgDialog_123119_Content_100 = {
    Text = "Non, %player%, attends..."
  },
  AvgDialog_123119_Content_101 = {
    Text = "Mouchette veut empêcher ton sauvetage. Après avoir pris connaissance de l'« expérience » te concernant, elle est remplie de doutes et de questions."
  },
  AvgDialog_123119_Content_102 = {
    Text = "Mais il n'y a plus de temps. Une sensation de tiraillement venant de l'âme l'entraîne, la conduisant obstinément hors de ce monde étrange rempli de taches de lumière."
  },
  AvgDialog_123119_Content_103 = {
    Text = "Et cette tache lumineuse qui lui a donné l'inspiration était là, ni trop près ni trop loin, dégagée d'une douceur chaleureuse, lui faisant ses derniers adieux."
  },
  AvgDialog_123119_Content_104 = {
    Text = "Montre les informations @4 à @3 « Je », et tu pourras rentrer chez @1 @2."
  },
  AvgDialog_123119_Content_105 = {
    Text = "@2, au revoir, Mouchette, @2… un autre « Je »."
  },
  AvgDialog_123119_Content_106 = {
    Text = "Très vite, le bourdonnement insaisissable se distord, se dissipe et disparaît complètement, emportant avec lui la vision, l'audition et les différentes sensations de Mouchette."
  },
  AvgDialog_123119_Content_107 = {
    Text = "Lorsque Mouchette a de nouveau retrouvé la vue et l'ouïe, revenant à la réalité, elle a vu à nouveau cette silhouette familière, cette personne qu'elle ne pouvait pas comprendre."
  },
  AvgDialog_123119_Content_108 = {
    Text = "Mouchette, pars d'ici, Salvador et moi nous occuperons du reste."
  },
  AvgDialog_123119_Content_109 = {
    Text = "L'«invasion» de la Porte s'intensifie, moi et L'Envoyé Pâle devons nous préparer au pire..."
  },
  AvgDialog_123119_Content_11 = {
    Text = "Donc, je dois y aller, seul moi peux y aller."
  },
  AvgDialog_123119_Content_110 = {Text = "新增"},
  AvgDialog_123119_Content_111 = {
    Text = "Mouchette ? Tu es dans la lune ? Pars vite d'ici."
  },
  AvgDialog_123119_Content_112 = {
    Text = "Regardant vers toi, la colère, la rage, la compassion et tant d'autres émotions se mêlaient dans la poitrine de Mouchette, l'empêchant de prononcer un mot."
  },
  AvgDialog_123119_Content_113 = {
    Text = "Finalement, elle expira avec colère, serra les poings et, à contrecœur, prit la parole :"
  },
  AvgDialog_123119_Content_114 = {
    Text = "Depuis la première fois que nous nous sommes rencontrés, j'aurais dû savoir que tu es ce genre de « protagoniste » enthousiaste et envahissant, un type de personne que je ne comprendrais jamais."
  },
  AvgDialog_123119_Content_115 = {
    Text = "Même après cent ans, je ne pourrai toujours pas comprendre tes circuits cérébraux. Alors, j'ai abandonné."
  },
  AvgDialog_123119_Content_116 = {Text = "Quoi ?"},
  AvgDialog_123119_Content_117 = {
    Text = "Je sais quelle valeur de vibration tu parles, c'est un autre @4@3…"
  },
  AvgDialog_123119_Content_118 = {
    Text = "Une douleur familière l'assaillit, déformant les mots prononcés par Mouchette. Après plusieurs tentatives infructueuses pour exprimer la réalité de ces éclats lumineux, Mouchette abandonna."
  },
  AvgDialog_123119_Content_119 = {
    Text = "La jeune fille remplaça les mots par des actions, serrant fermement ta main, son visage affichant une détermination inébranlable."
  },
  AvgDialog_123119_Content_12 = {
    Text = "En d'autres termes, c'est... oh, la sagesse de survie dans ce monde cruel."
  },
  AvgDialog_123119_Content_120 = {
    Text = "Je vais résoudre ce gros problème avec toi."
  },
  AvgDialog_123119_Content_121 = {
    Text = "Moi, Mouchette, l'avant-garde très remarquée de l'équipe d'enquête, je ne mettrai pas fin à cette bataille en tant que « déserteur »."
  },
  AvgDialog_123119_Content_13 = {
    Text = "En écoutant les paroles de Mouchette, vous et Salvador ne pouvez vous empêcher de tomber dans le silence, puis vous ouvrez la bouche en même temps——"
  },
  AvgDialog_123119_Content_14 = {
    Text = "Je ne suis pas d'accord, mon enfant. C'est moi qui devrais faire le sacrifice."
  },
  AvgDialog_123119_Content_15 = {
    Text = "Je suis d'accord. Je te promets que je te ramènerai, ou que je te ramènerai chez toi, peu importe le prix à payer."
  },
  AvgDialog_123119_Content_16 = {
    Text = "À ce moment-là, en exprimant des opinions complètement opposées, toi et Salvador ne pouvez vous empêcher de vous regarder."
  },
  AvgDialog_123119_Content_17 = {
    Text = "%player%, pourquoi..."
  },
  AvgDialog_123119_Content_18 = {
    Text = "C'est décidé, je compte sur toi pour rentrer, %player%."
  },
  AvgDialog_123119_Content_19 = {
    Text = "Mouchette vous interrompt avant que vous ou Salvador puissiez réagir, marchant droit vers la Porte inconnue et menaçante."
  },
  AvgDialog_123119_Content_2 = {
    Text = "Mouchette, tu veux dire que tu vas entrer dans cette « Porte » inconnue... ?"
  },
  AvgDialog_123119_Content_20 = {
    Text = "Tu tiens fermement la clé en argent d'une main, de l'autre main, tu tires fortement sur Salvador, fixant la silhouette de Mouchette, complètement concentré, n'osant même pas cligner des yeux."
  },
  AvgDialog_123119_Content_21 = {
    Text = "Salvador, écoute-moi, peut-être que... Mouchette est différente."
  },
  AvgDialog_123119_Content_22 = {
    Text = "C'est la porte qui relie une autre dimension, et Mouchette vient de cette dimension, elle a même été invoquée par le même rituel."
  },
  AvgDialog_123119_Content_23 = {
    Text = "Mais… si…"
  },
  AvgDialog_123119_Content_24 = {
    Text = "Si quelque chose ne va pas, je déclencherai la clé en argent pour transférer la connexion sur moi."
  },
  AvgDialog_123119_Content_25 = {
    Text = "Salvador te regarde, les yeux fermés pour feindre le calme, et voit que tu tiens fermement la clé d'argent, puis finit par soupirer."
  },
  AvgDialog_123119_Content_26 = {
    Text = "Si c'est le cas, n'hésitez pas à me laisser partager le fardeau."
  },
  AvgDialog_123119_Content_27 = {
    Text = "L'Envoyé Pâle, je ne te laisserai jamais tomber avant moi."
  },
  AvgDialog_123119_Content_28 = {
    Text = "Ton réponse est un sourire de compréhension."
  },
  AvgDialog_123119_Content_29 = {
    Text = "En attendant, Mouchette lève la main, essayant de toucher cette porte intangible."
  },
  AvgDialog_123119_Content_3 = {
    Text = "Ce n'est pas seulement toi, même Salvador est resté figé."
  },
  AvgDialog_123119_Content_30 = {
    Text = "<Shake:C'est...>"
  },
  AvgDialog_123119_Content_31 = {
    Text = "Au moment où Mo Xia toucha la Porte Invisible, elle émit soudainement une lumière brillante comme auparavant."
  },
  AvgDialog_123119_Content_32 = {
    Text = "En même temps, vous avez également activé la clé en argent."
  },
  AvgDialog_123119_Content_33 = {
    Text = "La lumière éclatante de la clé d'argent résonne avec l'éclat de la porte invisible, tandis que l'immensité d'argent et de sang semble être guidée par une force invisible, bouillonnant et sursautant."
  },
  AvgDialog_123119_Content_34 = {
    Text = "Sous cette combinaison, un bourdonnement inconnu capable de corroder les âmes résonne, mêlé à une brume épaisse et infinie, frappant tout ce qui l'entoure, plongeant tous les présents dans une sorte d'illusion de séparation entre l'esprit et le corps..."
  },
  AvgDialog_123119_Content_35 = {
    Text = "Le monde@2 est vide, comme@2@1 une brume épaisse, @3, quelque chose@2 est en train de naître dans ce vide@3."
  },
  AvgDialog_123119_Content_36 = {
    Text = "@1Juste une grande @4Songe inattendue, cette petite @2se débat, se tortille, évolue et devient une race @4."
  },
  AvgDialog_123119_Content_37 = {
    Text = "Dans les ténèbres résonne un son de flûte chaotique et déformé, ravageant la volonté de Mouchette. Bien que ce soit une mélodie, elle entrevoit vaguement son sens terrifiant."
  },
  AvgDialog_123119_Content_38 = {
    Text = "Humains, c'est ainsi que @3 se désigne. @2 est @4 minuscule et éphémère par rapport à l'infini univers @1."
  },
  AvgDialog_123119_Content_39 = {
    Text = "@3 n'est pas que @3 n'a pas laissé de traces, le sang et l'argent @1 coulent de génération en génération, @4 @2 des preuves @1."
  },
  AvgDialog_123119_Content_4 = {
    Text = "C'est ça. J'entre pour t'aider à clarifier cette onde de vibration."
  },
  AvgDialog_123119_Content_40 = {
    Text = "Le son de flûte distordu par le chaos devient de plus en plus aigu et terrifiant, comme s'il torturait l'âme de Mouchette. Elle ne peut plus supporter, et ouvre brusquement les yeux."
  },
  AvgDialog_123119_Content_41 = {
    Text = "Après avoir ouvert les yeux, Mouchette n'entendait pas le son de la flûte, ni ne voyait de musiciens. Tout autour d'elle était étrange et coloré, seules de grandes taches de lumière l'entouraient, maintenant une distance ni trop proche ni trop éloignée."
  },
  AvgDialog_123119_Content_42 = {
    Text = "Ravi de te voir, Mouchette, « Je » mon amie."
  },
  AvgDialog_123119_Content_43 = {
    Text = "La tache lumineuse émettait un bourdonnement, et de manière étrange, elle pouvait parfaitement comprendre. \n Ou plutôt, en ce moment, elle était aussi la tache lumineuse."
  },
  AvgDialog_123119_Content_44 = {
    Text = "Je suis mort ? Alors c'est ça, ressentir la mort..."
  },
  AvgDialog_123119_Content_45 = {
    Text = "Non, tu es encore en vie. Tu as simplement été amené ici par moi. Il y a l'essence de « Je » en toi."
  },
  AvgDialog_123119_Content_46 = {
    Text = "Si je ne fais pas cela, tu souffriras de l'échec de la traversée dimensionnelle @4, car tu as déjà été @3."
  },
  AvgDialog_123119_Content_47 = {
    Text = "Mouchette n'a pas entendu les dernières paroles des éclats de lumière, car au moment où les syllabes chaotiques se sont élevées, sa tête a commencé à lui faire mal violemment, presque prête à éclater."
  },
  AvgDialog_123119_Content_48 = {
    Text = "<Shake:Arrête ! Arrête ! Dis quelque chose que je peux entendre... Si ça continue, ma tête va exploser.>"
  },
  AvgDialog_123119_Content_49 = {
    Text = "Elle semblait avoir entendu le soupir des éclats de lumière, ou peut-être pas, car d'innombrables informations étranges affluaient dans l'esprit de Mouchette, attirant toute son attention."
  },
  AvgDialog_123119_Content_5 = {
    Text = "Enfant, tu ne comprends pas le danger, le trauma de la dimension mentale affectera également le monde réel, tu vas..."
  },
  AvgDialog_123119_Content_50 = {
    Text = "Qu'est-ce que c'est ?"
  },
  AvgDialog_123119_Content_51 = {
    Text = "Ce dont vous avez besoin en ce moment. Montrez-le à « Je », {Male=il,Female=elle} comprendra."
  },
  AvgDialog_123119_Content_52 = {
    Text = "Ce que je, à vous, ne peux pas comprendre—"
  },
  AvgDialog_123119_Content_53 = {
    Text = "Attends, tu es... %player% ?"
  },
  AvgDialog_123119_Content_54 = {
    Text = "C'est impossible, je viens de te voir en pleine forme, on dirait que tu pourrais vivre encore 100 ans sans problème."
  },
  AvgDialog_123119_Content_55 = {
    Text = "Des taches de lumière bourdonnent et émettent un léger rire, Mouchette ne sait pas si cela peut être appelé « rire », car il n'y a pas de joie. Pour être précis, il n'y a aucune émotion."
  },
  AvgDialog_123119_Content_56 = {
    Text = "Tu peux comprendre que c'est un « Je » d'une autre dimension, et moi, le vrai moi——"
  },
  AvgDialog_123119_Content_57 = {
    Text = "Avec les paroles des éclats de lumière, d'innombrables informations ont afflué dans l'esprit de Mouchette. Ces informations se divisent et se regroupent sans cesse, formant des images instables."
  },
  AvgDialog_123119_Content_58 = {
    Text = "Au début, ces images étaient abstraites et marbrées, vagues et indistinctes, mais bientôt—"
  },
  AvgDialog_123119_Content_59 = {
    Text = "Ces lumières et ombres étranges se sont regroupées en une figure, une figure qu'elle reconnaissait."
  },
  AvgDialog_123119_Content_6 = {
    Text = "Ici, je suis le seul qui convient. Bien que j'aie un esprit simple, je ne suis pas bête."
  },
  AvgDialog_123119_Content_60 = {
    Text = "La silhouette familière s'éveille au milieu d'une explosion, regardant ce monde avec confusion."
  },
  AvgDialog_123119_Content_61 = {
    Text = "Des années plus tard, les gens désigneront cette explosion comme l'« explosion d'Akutsk »"
  },
  AvgDialog_123119_Content_62 = {
    Text = "Ensuite, {Male=il,Female=elle} est entré(e) dans Mizag, a obtenu la Clé d'argent, est devenu(e) un « Gardien » et a commencé à entreprendre des missions avec des compagnons connus sous le nom de « Éveilleurs », enquêtant sur ce monde étrange et horrifiant."
  },
  AvgDialog_123119_Content_63 = {
    Text = "Tout comme elle et l'enquêteur, l'équipe d'enquête du brouillard."
  },
  AvgDialog_123119_Content_64 = {Text = "新增"},
  AvgDialog_123119_Content_65 = {
    Text = "En se remémorant les personnes et le passé familiers, Mouchette soupira avec nostalgie. Quant à la vie de %player%, elle continue toujours —"
  },
  AvgDialog_123119_Content_66 = {
    Text = "Elle vit %player% traverser la ville enneigée, faisant face au chien de chasse qui traverse le temps et l'espace dans le sanatorium rempli de secrets, témoignant de l'éternité de l'amour familial."
  },
  AvgDialog_123119_Content_67 = {
    Text = "J'ai également suivi %player% pour explorer la Cité, remplie de poésie et de fleurs, écoutant les soupirs des flammes et pleurant le flétrissement des roses."
  },
  AvgDialog_123119_Content_68 = {
    Text = "Et il y a des navires fantômes dérivant sur la mer. Foi, divinités et sacrifices—avec %player%, elle a fini par comprendre les distorsions, la cruauté et la folie de ce monde."
  },
  AvgDialog_123119_Content_69 = {
    Text = "Peu importe la profondeur des ténèbres, %player% et les Éveilleurs n'ont jamais abandonné."
  },
  AvgDialog_123119_Content_7 = {
    Text = "Mouchette intervient pour interrompre Salvador, vous regardant avec sérieux."
  },
  AvgDialog_123119_Content_70 = {
    Text = "Tout comme dans ce monde, le Désastre de Brouillard, les Restes Cendreux et les Objets Anciens n'ont pu vaincre ni elle ni l'enquêteur, pas plus qu'ils n'ont pu vaincre l'Équipe d'Enquête sur le Royaume de la Brume."
  },
  AvgDialog_123119_Content_71 = {
    Text = "C'est beaucoup mieux !"
  },
  AvgDialog_123119_Content_72 = {
    Text = "Je me demande comment vont ces petits gars dans le brouillard maintenant ?"
  },
  AvgDialog_123119_Content_73 = {
    Text = "Ah, j'ai vraiment envie d'une tasse fumante de thé kava aux noisettes !"
  },
  AvgDialog_123119_Content_74 = {
    Text = "Mouchette sourit. \n Elle pensait que %player% se battrait aux côtés des Éveilleurs pour toujours—"
  },
  AvgDialog_123119_Content_75 = {
    Text = "C'est tout à fait naturel, car elle n'a jamais pensé à quitter l'équipe d'enquête sur le brouillard, et ces Éveilleurs ne penseraient naturellement pas à quitter leurs Gardiens."
  },
  AvgDialog_123119_Content_76 = {
    Text = "Ils se battront et se battront jusqu'à ce que les problèmes du monde soient résolus, ou jusqu'à ce qu'ils soient résolus par le monde.\nTout comme dans toutes les histoires."
  },
  AvgDialog_123119_Content_77 = {
    Text = "Mais ce monde est bien plus cruel qu'elle ne l'imaginait, bien plus que celui dans lequel elle vit."
  },
  AvgDialog_123119_Content_78 = {
    Text = "<Shake:Comment est-ce possible !!>"
  },
  AvgDialog_123119_Content_79 = {
    Text = "Alors, toi... !?"
  },
  AvgDialog_123119_Content_8 = {
    Text = "Salvador, ta capacité est la base de notre sécurité dans le brouillard épais, et %player%, il est évident que ta clé d'argent est également très importante."
  },
  AvgDialog_123119_Content_80 = {
    Text = "Toi, je ne devrais pas m'attendre à ce que tu abandonnes de sauver ce monde ennuyeux."
  },
  AvgDialog_123119_Content_81 = {
    Text = "Sacrifier pour sauver les autres... ce genre de chose..."
  },
  AvgDialog_123119_Content_82 = {
    Text = "Mouchette ne peut plus continuer à parler, car que ce soit de la colère ou de l'irritation, cela ne sert plus à rien."
  },
  AvgDialog_123119_Content_83 = {
    Text = "%player% est en effet l'ami de Mouchette, mais Mouchette n'est qu'un simple passant dans ce monde."
  },
  AvgDialog_123119_Content_84 = {
    Text = "Ce qui sépare les deux n'est pas seulement une \"dimension\", mais aussi deux \"mondes\" complètement différents"
  },
  AvgDialog_123119_Content_85 = {
    Text = "En fait, mon rêve est de m'asseoir avec la personne que j'aime près d'une cheminée confortable, à gaspiller nos vies sans valeur."
  },
  AvgDialog_123119_Content_86 = {
    Text = "Dehors, la neige tombe lentement, année après année, jusqu'à ce que nous mourions de vieillesse. Ensuite, ma pierre tombale dira : {Male=il,Female=elle} était un bon à rien qui a vécu longtemps et heureusement."
  },
  AvgDialog_123119_Content_87 = {
    Text = "Jusqu'à présent, mes rêves n'ont jamais changé."
  },
  AvgDialog_123119_Content_88 = {
    Text = "Alors réalise ce rêve, peu importe si le monde est détruit ! Quel que soit ce monde ennuyeux, qu'il soit détruit ou non, qu'est-ce que ça change !?"
  },
  AvgDialog_123119_Content_89 = {
    Text = "Cela vaut mieux que de laisser un regret éternel, d'être piégé ici, seul et pour toujours !"
  },
  AvgDialog_123119_Content_9 = {
    Text = "Si quelque chose t'arrivait, personne ne pourrait résoudre ce problème."
  },
  AvgDialog_123119_Content_90 = {
    Text = "La lumière éclatante rit doucement à nouveau, mais Mouchette ne pouvait plus distinguer si cette voix contenait de l'humour. \n Car son cœur était rempli d'amertume."
  },
  AvgDialog_123119_Content_91 = {
    Text = "Je veux aussi réaliser ce rêve, je le veux tellement, mais..."
  },
  AvgDialog_123119_Content_92 = {
    Text = "Dans ce monde cruel, nous finissons toujours par faire des « choix », des choix que même nous ne pouvons pas comprendre."
  },
  AvgDialog_123119_Content_93 = {
    Text = "Peut-être que ce n'est pas complètement incompréhensible. Bien que je n'aie pas eu de tasse fumante de thé kava aux noisettes, j'ai mes propres favoris."
  },
  AvgDialog_123119_Content_94 = {
    Text = "Le petit gâteau de Murphy, la danse de Liz, même les devoirs supplémentaires que Doll donne à chaque fois, maintenant que j'y pense, cela semble plein d'intérêt..."
  },
  AvgDialog_123119_Content_95 = {
    Text = "Ça suffit, n'en dis plus. Tu es vraiment un cas désespéré..."
  },
  AvgDialog_123119_Content_96 = {
    Text = "Mouchette ! Mouchette !"
  },
  AvgDialog_123119_Content_97 = {
    Text = "Soudainement, une voix résonna dans l'esprit de Mouchette. Et elle, au premier instant, reconnut l'autre personne."
  },
  AvgDialog_123119_Content_98 = {
    Text = "Après avoir vu les luttes et les sacrifices de « {Male=il,Female=elle} » pour sauver le monde, elle pense qu'il lui sera difficile d'oublier cette voix, cette personne."
  },
  AvgDialog_123119_Content_99 = {
    Text = "Tiens bon, Salvador et moi allons bientôt te sauver ! Je te l'ai promis."
  },
  AvgDialog_123120_Content_1 = {
    Text = "L'auto-offrande"
  },
  AvgDialog_123120_Content_10 = {
    Text = "Père Salvador... ?"
  },
  AvgDialog_123120_Content_100 = {
    Text = "Je ne sais pas jusqu'où cette saleté va se répandre, si cela devient vraiment comme dans mon monde..."
  },
  AvgDialog_123120_Content_101 = {
    Text = "Mouchette ne continua pas, mais tu compris son sous-texte—"
  },
  AvgDialog_123120_Content_102 = {
    Text = "La catastrophe de brouillard est une calamité qui peut affecter un monde entier."
  },
  AvgDialog_123120_Content_103 = {
    Text = "Il faut mettre fin à ce rituel, à tout prix…<Shake:Salvador !>"
  },
  AvgDialog_123120_Content_104 = {
    Text = "Je suis là. Je veillerai à votre sécurité... et je ferai en sorte que ces égarés obtiennent la véritable Rédemption..."
  },
  AvgDialog_123120_Content_105 = {
    Text = "Puis, une lumière chaude et douce apparaît soudainement sur Salvador, se répandant autour de vous et de Mouchette, isolant les dommages du Fléau de brouillard."
  },
  AvgDialog_123120_Content_106 = {
    Text = "Mouchette, pour fermer cette fissure spatiale, je devrai mesurer et déterminer les ondes de vibration de la dimension mentale ; le combat dépend de toi."
  },
  AvgDialog_123120_Content_107 = {
    Text = "Bataille ? Pas de problème. Avec moi, tu ne perdras pas un seul poil !"
  },
  AvgDialog_123120_Content_108 = {
    Text = "Après avoir retenu tout ça si longtemps, je peux enfin me défouler——"
  },
  AvgDialog_123120_Content_109 = {
    Text = "Tout le monde l'adore, jeunes et vieux !\n<Big:Tornade☆brillante——!!>"
  },
  AvgDialog_123120_Content_11 = {
    Text = "Salvador prit une profonde inspiration en silence, puis expira lourdement."
  },
  AvgDialog_123120_Content_111 = {
    Text = "Une hache vole et fend une série de silhouettes de brume, ouvrant ainsi un chemin temporaire de sécurité pour te rapprocher de cette porte inconnue qui dévore continuellement la brume épaisse."
  },
  AvgDialog_123120_Content_112 = {
    Text = "Et toi, tu manipules sans cesse les instruments de mesure, essayant de capter les ondes de vibration des dimensions différentes."
  },
  AvgDialog_123120_Content_113 = {
    Text = "Une minute s'est écoulée en silence.\nDeux minutes se sont écoulées en silence."
  },
  AvgDialog_123120_Content_114 = {
    Text = "Puis vinrent trois minutes, cinq minutes, dix minutes..."
  },
  AvgDialog_123120_Content_115 = {
    Text = "La sueur tombe de ton front, tu n'as jamais ressenti le temps aussi long."
  },
  AvgDialog_123120_Content_116 = {
    Text = "Combien de temps encore ? J'ai l'impression que ces monstres semblent devenir plus forts, il faut plusieurs coups pour les disperser..."
  },
  AvgDialog_123120_Content_117 = {
    Text = "C'est une manifestation d'une autre dimension essayant d'envahir et de dévorer notre monde, n'est-ce pas, L'Envoyé Pâle ?"
  },
  AvgDialog_123120_Content_118 = {
    Text = "Une autre goutte de sueur tombe de ton front, sous la tension, tu as même oublié de hocher la tête."
  },
  AvgDialog_123120_Content_119 = {
    Text = "Onde de vibration... qui change sans cesse..."
  },
  AvgDialog_123120_Content_12 = {
    Text = "Pas besoin de chercher plus, Père White... est juste ici."
  },
  AvgDialog_123120_Content_120 = {
    Text = "Cela peut être dû à la brume elle-même, ou peut-être à la perturbation des âmes coincées dans le brouillard... J'ai besoin de temps pour enquêter."
  },
  AvgDialog_123120_Content_121 = {
    Text = "Tu lèves les yeux vers le ciel, et à ce moment-là, tu ne peux plus voir aucune «Étoiles». \n Le monde entier semble n'être composé que de brouillard épais et de la Porte de la Dimension qui continue de cracher ce brouillard."
  },
  AvgDialog_123120_Content_122 = {
    Text = "Mais nous n'avons plus de temps."
  },
  AvgDialog_123120_Content_123 = {
    Text = "...Tu as absolument raison."
  },
  AvgDialog_123120_Content_124 = {
    Text = "Tu ranges l'instrument de mesure et tu saisis la clé en argent."
  },
  AvgDialog_123120_Content_125 = {
    Text = "Il semble que nous n'ayons d'autre choix que de parier..."
  },
  AvgDialog_123120_Content_126 = {
    Text = "L'Envoyé Pâle, souhaites-tu te connecter... ?"
  },
  AvgDialog_123120_Content_127 = {
    Text = "Salvador fronce les sourcils et te regarde avec désaccord. Et toi, tu restes silencieux."
  },
  AvgDialog_123120_Content_128 = {
    Text = "Hé, hé, il y a aussi un « invité d'un autre monde » ici. Peux-tu dire quelque chose que je puisse comprendre ?"
  },
  AvgDialog_123120_Content_129 = {
    Text = "Le sens de %player% est... de connecter cette porte inconnue pour déterminer l'onde de vibration des dimensions."
  },
  AvgDialog_123120_Content_13 = {
    Text = "Le Grand Prêtre sur l'autel... est le Père White."
  },
  AvgDialog_123120_Content_130 = {
    Text = "Quoi ? Cette chose est très étrange, qui sait quel en sera le résultat, ne fais pas de bêtises."
  },
  AvgDialog_123120_Content_131 = {
    Text = "Tu tiens fermement la clé en argent et te diriges vers la porte de lumière invisible avec une expression grave. En ce moment, l'action prime sur les mots."
  },
  AvgDialog_123120_Content_132 = {
    Text = "Je suis vraiment impressionné par vous qui croyez que ce monde ennuyeux a encore de la valeur à sauver..."
  },
  AvgDialog_123120_Content_133 = {
    Text = "Inattendu, Mouchette tendit la main pour te stopper. Son expression était complexe alors qu'elle te regardait, comme si elle te voyait, mais en même temps, comme si elle regardait à travers toi, voyant quelqu'un d'autre."
  },
  AvgDialog_123120_Content_134 = {
    Text = "Au final, tous les enchevêtrements se sont transformés en un sourire sur son visage, et Mouchette s'efforça de rendre sa voix détendue."
  },
  AvgDialog_123120_Content_135 = {
    Text = "Oublie ça, qui m'a dit que j'étais à l'avant-garde de l'équipe d'enquête ? C'est tout à fait normal d'être à l'avant—"
  },
  AvgDialog_123120_Content_136 = {
    Text = "Alors, laisse-moi y aller."
  },
  AvgDialog_123120_Content_137 = {
    Text = "Mouchette vous regarde, son expression sérieuse et résolue."
  },
  AvgDialog_123120_Content_138 = {
    Text = "À partir du coin de la cage, c'est la première fois qu'elle montre une expression aussi sérieuse."
  },
  AvgDialog_123120_Content_14 = {Text = "Quoi ?!"},
  AvgDialog_123120_Content_15 = {
    Text = "Dans l'incrédulité, tu ne pouvais pas t'empêcher de te tourner vers White, voyant l'ancien prêtre de l'Église de la Vie, maintenant le chef d'un culte, parler avec passion."
  },
  AvgDialog_123120_Content_16 = {
    Text = "En ce moment, nous avons fait un choix au prix de l'argent et du sang, et nous ne le regretterons jamais."
  },
  AvgDialog_123120_Content_17 = {
    Text = "Pour se rendre au « royaume paisible sans souffrance de la dissipation », pour se racheter dans ce monde enflammé —"
  },
  AvgDialog_123120_Content_18 = {
    Text = "Pour se rendre au « royaume paisible sans souffrance de la dissipation », pour se racheter dans ce monde enflammé —"
  },
  AvgDialog_123120_Content_19 = {
    Text = "Une douzaine de croyants de l'Aube Étoilée jurèrent à l'unisson—"
  },
  AvgDialog_123120_Content_2 = {
    Text = "<Shake:Ce monde est en feu, ce monde s'effondre, ce monde est destiné à la destruction.>"
  },
  AvgDialog_123120_Content_20 = {
    Text = "Une douzaine de croyants de l'Aube Étoilée levèrent leurs dagues plaquées argent à l'unisson—"
  },
  AvgDialog_123120_Content_21 = {Text = "Arrête !"},
  AvgDialog_123120_Content_22 = {
    Text = "Dans votre cri, la dague plaquée argent plonge simultanément dans le cœur du bétail humain, s'enfonçant profondément et s'agitant violemment."
  },
  AvgDialog_123120_Content_23 = {
    Text = "Un sang aveuglant jaillit de la poitrine de la victime sacrificielle, teintant l'autel en rouge."
  },
  AvgDialog_123120_Content_24 = {
    Text = "Au milieu d'une mer de sang, vous émergez des ombres cachées, fixant directement White, affrontant la source de toute cette tragédie."
  },
  AvgDialog_123120_Content_25 = {
    Text = "Un autre imbécile ignorant vient interrompre le rituel du Tout-Père ?"
  },
  AvgDialog_123120_Content_26 = {
    Text = "Ha, tu étais indifférent lorsque le Cataclysme est descendu, et maintenant que je suis sur le point de mener mes frères et sœurs vers la Rédemption, tu oses m'arrêter—"
  },
  AvgDialog_123120_Content_27 = {
    Text = "Le chef de L'aube des étoiles rit avec mépris en vous regardant, puis ses yeux se sont soudainement écarquillés, figés sur place."
  },
  AvgDialog_123120_Content_28 = {
    Text = "<Shake:Évêque Salvador !?>"
  },
  AvgDialog_123120_Content_29 = {
    Text = "L'expression de Salvador était enveloppée de tristesse, et vous remarquiez qu'en dessous de sa large robe, sa silhouette grande et élancée tremblait légèrement."
  },
  AvgDialog_123120_Content_3 = {
    Text = "<Shake:Le seul chemin vers la rédemption est de voyager vers <Yellow:« un royaume paisible sans la douleur de la dispersion »>, qui est juste au-dessus de nous, dans l'univers où brillent les étoiles.>"
  },
  AvgDialog_123120_Content_30 = {
    Text = "White… mon enfant égaré…"
  },
  AvgDialog_123120_Content_31 = {
    Text = "Oh, je vois, l'enfant que Votre Excellence, l'évêque, est venu sauver est en réalité le chef d'un culte ! Quelle intéressante révélation !"
  },
  AvgDialog_123120_Content_32 = {
    Text = "Mouchette !"
  },
  AvgDialog_123120_Content_33 = {
    Text = "D'accord, d'accord, je ne dirai rien. Même si je ne dis rien, les faits ne changeront pas, n'est-ce pas ?"
  },
  AvgDialog_123120_Content_34 = {
    Text = "Ainsi, le silence s'installa sur les lieux, seul le sang du sacrifice humain coulait lentement sur l'autel, imprégnant le sol."
  },
  AvgDialog_123120_Content_35 = {
    Text = "John, James, Anderson... ils étaient tous vos collègues."
  },
  AvgDialog_123120_Content_36 = {
    Text = "En tant que prêtre de la Chantrie de la Vie... vous devriez comprendre pourquoi ils sont venus à Hawick."
  },
  AvgDialog_123120_Content_37 = {
    Text = "……Je le sais bien."
  },
  AvgDialog_123120_Content_38 = {
    Text = "Parce que je suis venu ici avec des idéaux nobles, tout comme eux !"
  },
  AvgDialog_123120_Content_39 = {
    Text = "La voix de White s'est soudainement animée, regardant avec ardeur Salvador, tel un enfant en quête de reconnaissance."
  },
  AvgDialog_123120_Content_4 = {
    Text = "<Shake:<Big:Trouvez-le, embrassez-le, consacrezz-vous à lui ! Ce n'est qu'alors que nos vies accueilleront l'aube éternelle——>>"
  },
  AvgDialog_123120_Content_40 = {
    Text = "Et j'ai tenu ma promesse en trouvant le seul moyen de sauver mes frères et sœurs."
  },
  AvgDialog_123120_Content_41 = {Text = "新增"},
  AvgDialog_123120_Content_42 = {
    Text = "La mort n'est pas l'enseignement du Tout-Père, White. Tu t'es écarté du chemin."
  },
  AvgDialog_123120_Content_43 = {
    Text = "<Shake:Non ! Je suis toujours les conseils du Père Dieu !>"
  },
  AvgDialog_123120_Content_44 = {
    Text = "Le Tout-Père proclame : <Italic: « Nous sommes tous Ses enfants, dignes de Son amour »>, <Italic: « Aimez-vous les uns les autres comme vous vous aimez vous-même »>."
  },
  AvgDialog_123120_Content_45 = {
    Text = "Le Tout-Père conseille <Italic:«Ceux d'entre vous qui sont nobles seront mes Émissaires, exécutant ma volonté d'éradiquer la souffrance de cette Terre.»>."
  },
  AvgDialog_123120_Content_46 = {
    Text = "……pas faux. Tout cela est la volonté du Père Dieu."
  },
  AvgDialog_123120_Content_47 = {
    Text = "Et j'ai réussi. Je vais sauver mes frères et sœurs et éliminer la souffrance qui pèse sur eux."
  },
  AvgDialog_123120_Content_48 = {
    Text = "Je les mènerai loin de cette terre de souffrance, les guidant vers l'aube qui brille parmi les étoiles, vers cela—"
  },
  AvgDialog_123120_Content_49 = {
    Text = "<Yellow:<Big:Le royaume paisible sans souffrance de la dissipation>>."
  },
  AvgDialog_123120_Content_5 = {
    Text = "Dans la grotte remplie de symboles blasphématoires, le chef de L'aube des étoiles faisait un discours passionné. Alors que ses mots tombaient, les sacrifices humains étaient traînés au centre de l'autel."
  },
  AvgDialog_123120_Content_50 = {
    Text = "Pour aller au « royaume paisible sans souffrance de la dissipation », pour nous racheter dans ce monde enflammé —"
  },
  AvgDialog_123120_Content_51 = {
    Text = "Pour se rendre au « royaume paisible sans souffrance de la dissipation », pour se racheter dans ce monde enflammé —"
  },
  AvgDialog_123120_Content_52 = {
    Text = "À ce moment-là, un ricanement glacial perça les cris fervents et ordonnés des croyants tel un poignard aiguisé."
  },
  AvgDialog_123120_Content_53 = {
    Text = "Un royaume tranquille sans la douleur de la dispersion ? Parles-tu du monde au-delà de la porte ?"
  },
  AvgDialog_123120_Content_54 = {
    Text = "Quelle blague. Mon monde n'est pas si merveilleux."
  },
  AvgDialog_123120_Content_55 = {
    Text = "Fléau de brouillard, Antiquité, Cendres, et toutes sortes de monstres mutants, et peu importe lequel vous rencontrez, cela suffira pour vous faire boire une bouteille."
  },
  AvgDialog_123120_Content_56 = {
    Text = "Alors, ne parlez plus de ces balivernes sur la rédemption, vous ne faites qu sacrifier les autres pour sauver vos propres vies."
  },
  AvgDialog_123120_Content_57 = {
    Text = "<Shake:Ce n'est pas comme ça ! Parce que—>"
  },
  AvgDialog_123120_Content_58 = {
    Text = "White fait un pas en avant, s'approchant de Mouchette, levant avec émotion la dague en argent."
  },
  AvgDialog_123120_Content_59 = {
    Text = "Tu protèges instinctivement Mouchette, mais la frappe attendue ne vient pas."
  },
  AvgDialog_123120_Content_6 = {
    Text = "Tu te caches dans l'ombre non loin, confirmant soigneusement le nombre de sacrifices humains."
  },
  AvgDialog_123120_Content_60 = {
    Text = "La cible du poignard était son maître depuis le tout début—"
  },
  AvgDialog_123120_Content_61 = {
    Text = "Le sang jaillit du cœur de White, s'écoulant et se mêlant au sang des sacrifices humains sur l'autel écarlate."
  },
  AvgDialog_123120_Content_62 = {
    Text = "<Shake:Maintenant... l'argent et le sang suffisent...>"
  },
  AvgDialog_123120_Content_63 = {
    Text = "Avec le murmure de Blanc, un impact invisible jaillit de l'autel."
  },
  AvgDialog_123120_Content_64 = {
    Text = "Le sang s'écoulant sur la surface de l'autel commença à onduler et à s'élever, tandis que le corps du sacrifice flottait dans les airs."
  },
  AvgDialog_123120_Content_65 = {
    Text = "<Shake:Ah ah ah—— Évêque Salvador…>"
  },
  AvgDialog_123120_Content_66 = {
    Text = "<Shake:Tu vois... je n'ai pas trahi... ma promesse envers le Père Dieu...>"
  },
  AvgDialog_123120_Content_67 = {
    Text = "White hurlait, son corps mourant se tordant sans cesse, l'argent et le sang en lui étaient extraits par une force invisible, dessinant des motifs étranges dans le ciel."
  },
  AvgDialog_123120_Content_68 = {
    Text = "<Shake:Monseigneur, je sais que j'ai péché... Je suis prêt à porter mes péchés, ainsi que les leurs.>"
  },
  AvgDialog_123120_Content_69 = {
    Text = "<Shake:Mais je ne regrette absolument pas... car j'ai sauvé mes frères et sœurs... dans cette terre de souffrance...>"
  },
  AvgDialog_123120_Content_7 = {
    Text = "John, James, Anderson... ils sont tous ici."
  },
  AvgDialog_123120_Content_70 = {
    Text = "Le regard de White était fixé sur Salvador. Et Salvador, l'évêque qui s'était jadis consacré à le nourrir, traça lentement le symbole sacré du Tout-Père dans l'air."
  },
  AvgDialog_123120_Content_71 = {
    Text = "La main marquée du symbole sacré tremblait, réprimant l'envie de « bénir ». Car Salvador savait que l'enfant perdu avait fait son propre choix."
  },
  AvgDialog_123120_Content_72 = {
    Text = "Je ne suis toujours pas d'accord avec ta méthode, White, mais tu appliques effectivement les enseignements du Père Dieu. Donc..."
  },
  AvgDialog_123120_Content_73 = {
    Text = "Que le Père Dieu te pardonne, que tu... puisses retourner dans les bras du Père Dieu... te libérer de la souffrance et obtenir la rédemption..."
  },
  AvgDialog_123120_Content_74 = {
    Text = "Salvador soupira et fit sa dernière prière."
  },
  AvgDialog_123120_Content_75 = {
    Text = "Mais White n'entendait plus rien. \n Son expression oscillait entre un sourire béat et une douleur extrême, son cœur cessa de battre."
  },
  AvgDialog_123120_Content_76 = {
    Text = "Puis, l'argent et le sang flottant dans les airs commencèrent à tourbillonner soudainement, comme d'innombrables «Étoiles» bouillonnantes, illuminant le ciel nocturne."
  },
  AvgDialog_123120_Content_77 = {
    Text = "Dans cette lumière éblouissante et grandiose, d'innombrables taches de lumière inconnues se recomposent et s'assemblent, formant une porte invisible dont on ne sait où elle mène."
  },
  AvgDialog_123120_Content_78 = {
    Text = "Est-ce ce qu'ils appellent la \"Porte\" ?"
  },
  AvgDialog_123120_Content_79 = {
    Text = "Avec cela, puis-je retourner dans mon propre monde ?"
  },
  AvgDialog_123120_Content_8 = {
    Text = "Alors, nous avons juste besoin du Père Blanc... ?"
  },
  AvgDialog_123120_Content_80 = {
    Text = "C'est difficile à dire. En théorie, nous pouvons relier la même dimension plusieurs fois en simulant les mêmes ondes de vibration, mais en pratique, des accidents peuvent facilement se produire."
  },
  AvgDialog_123120_Content_81 = {
    Text = "Surtout avec ce genre de rituel sacrificiel, qui est rempli de nombreuses variables et peut entraîner plus de problèmes—"
  },
  AvgDialog_123120_Content_82 = {
    Text = "Attends, ne t'approche pas là-bas !"
  },
  AvgDialog_123120_Content_83 = {
    Text = "Tu élèves la voix pour arrêter les adeptes du culte qui avancent en unisson vers la porte intangible, mais ils semblent ne pas t'entendre et continuent d'avancer d'un pas calme."
  },
  AvgDialog_123120_Content_84 = {
    Text = "Pour aller au « royaume paisible sans souffrance de la dissipation », pour nous racheter dans ce monde enflammé——"
  },
  AvgDialog_123120_Content_85 = {
    Text = "Pour se rendre au « royaume paisible sans souffrance de la dissipation », pour se racheter dans ce monde enflammé——"
  },
  AvgDialog_123120_Content_86 = {
    Text = "Enfin, le premier croyant leva la main et toucha cette porte intangible, entrant dans le nouveau monde qu'il désirait tant."
  },
  AvgDialog_123120_Content_87 = {
    Text = "<Shake:Aaaah——>"
  },
  AvgDialog_123120_Content_88 = {
    Text = "Dans des cris de désespoir, les mains des croyants touchant la porte lumineuse commencent à se déformer, à fusionner, se dissolvant dans la forte lumière émise soudainement par la porte invisible."
  },
  AvgDialog_123120_Content_89 = {
    Text = "Puis, une brume épaisse et infinie jaillit de cette porte immatérielle, dévorant la chair et l'âme des croyants, transformant ceux qui aspiraient à rejoindre les étoiles en une partie des «Étoiles»."
  },
  AvgDialog_123120_Content_9 = {Text = "新增"},
  AvgDialog_123120_Content_90 = {
    Text = "Le communicateur spécial recommence à émettre un bruit électrique de panne, diffusant ce murmure familier de la mort imminente."
  },
  AvgDialog_123120_Content_91 = {
    Text = "@2I... sauvegarder @2..."
  },
  AvgDialog_123120_Content_92 = {
    Text = "Sauvegarder @2... @2 moi..."
  },
  AvgDialog_123120_Content_93 = {
    Text = "C'est... <Shake:Le rituel a mal tourné !>"
  },
  AvgDialog_123120_Content_94 = {
    Text = "Salvador, fais attention aux monstres dans le brouillard !"
  },
  AvgDialog_123120_Content_95 = {
    Text = "À peine ses mots prononcés, d'innombrables brumes humanoïdes se condensent dans le brouillard environnant, rugissant en se précipitant vers vous."
  },
  AvgDialog_123120_Content_96 = {
    Text = "Les choses commencent enfin à devenir amusantes."
  },
  AvgDialog_123120_Content_97 = {
    Text = "Mouchette——"
  },
  AvgDialog_123120_Content_98 = {
    Text = "D'accord, je ne dirai plus rien, mais je dois te rappeler que le fléau de brouillard continue de s'étendre."
  },
  AvgDialog_123120_Content_99 = {
    Text = "… Messager pâle, je pouvais encore voir clairement les environs tout à l'heure, mais maintenant je ne vois plus rien."
  },
  AvgDialog_123121_Content_1 = {
    Text = "Étoiles éteintes"
  },
  AvgDialog_123121_Content_10 = {
    Text = "Avec ta force, tu ne devrais certainement pas être emprisonné par quelques pitoyables adeptes d'un culte."
  },
  AvgDialog_123121_Content_11 = {
    Text = "Et je pense que nous avons tous les deux remarqué que cette dame a demandé plusieurs fois l'heure de la cérémonie, et son expression... est clairement celle de l'anticipation."
  },
  AvgDialog_123121_Content_12 = {
    Text = "Ah, c'est donc ici que j'ai été exposé... J'ai été imprudent."
  },
  AvgDialog_123121_Content_13 = {
    Text = "Alors, qui es-tu vraiment ? Quel est ce rituel ? Que sais-tu d'autre ?"
  },
  AvgDialog_123121_Content_14 = {
    Text = "Mouchette affiche un sourire désinvolte et répond par une question —"
  },
  AvgDialog_123121_Content_15 = {
    Text = "Et vous ? Pourquoi êtes-vous venus dans cet endroit où l'ordre séculier s'est complètement effondré, ne laissant que des croyances ennuyeuses ?"
  },
  AvgDialog_123121_Content_16 = {
    Text = "Salvador ne poursuivit pas l'offense contre la foi dans les paroles de Mouchette, affichant seulement un air de pitié."
  },
  AvgDialog_123121_Content_17 = {
    Text = "Je viens pour la rédemption."
  },
  AvgDialog_123121_Content_18 = {
    Text = "Rédemption ? Rédemption de qui ? Ces sacrifices humains ? Permettez-moi d'être franc, parfois, il vaut mieux mourir joyeusement que de vivre dans la souffrance."
  },
  AvgDialog_123121_Content_19 = {
    Text = "Surtout dans un monde comme ça... euh, excitant et amusant."
  },
  AvgDialog_123121_Content_2 = {
    Text = "Après avoir envoyé un signal au Saint-Siège de la Vie, vous et Salvador avez attendu à l'extérieur de la grotte la mystérieuse fille qui s'appelle « Mouchette »"
  },
  AvgDialog_123121_Content_20 = {
    Text = "La bénédiction du Tout-Père sera répandue dans chaque recoin qui aspire à la rédemption."
  },
  AvgDialog_123121_Content_21 = {
    Text = "Ces prisonniers crient vers moi et l'Église de la Vie pour obtenir de l'aide dans leur souffrance, et nous répondrons sûrement à leurs supplications."
  },
  AvgDialog_123121_Content_22 = {
    Text = "En tant qu'Exécuteur du Père Dieu, je ferai de mon mieux pour éliminer la souffrance sur cette Terre."
  },
  AvgDialog_123121_Content_23 = {
    Text = "Salvador baissa la tête et fit une révérence dévote avec les mains jointes.\nCe qui lui répondit, c'était le léger rire de Mouchette."
  },
  AvgDialog_123121_Content_24 = {
    Text = "Je parie que vous êtes tous ces gens bien sous tous rapports, croyant à des banalités ennuyeuses comme « j'aime les gens et les gens m'aiment », n'est-ce pas ?"
  },
  AvgDialog_123121_Content_25 = {
    Text = "C'est pourquoi tu m'as cru si facilement et m'as suivi ici..."
  },
  AvgDialog_123121_Content_26 = {
    Text = "C'est vraiment naïf au point de donner mal à la tête."
  },
  AvgDialog_123121_Content_27 = {
    Text = "Tu ne peux pas discerner si l'expression de Mouchette est un défi ou de la nostalgie, alors qu'un voile de brume venant de nulle part obscurcit son visage."
  },
  AvgDialog_123121_Content_28 = {
    Text = "Tu te trompes, nous ne voulons simplement pas mal juger un étranger."
  },
  AvgDialog_123121_Content_29 = {
    Text = "Eh, peu importe, car vous ne comprenez tout simplement pas..."
  },
  AvgDialog_123121_Content_3 = {
    Text = "Et quand Mouchette apparut au bord de votre vision, elle avait soudainement une hache élégante à la main."
  },
  AvgDialog_123121_Content_30 = {
    Text = "Juste à ce moment-là, un bruit soudain d'interrupteur interrompit les paroles de Mouchette."
  },
  AvgDialog_123121_Content_31 = {
    Text = "Le communicateur a détecté des fluctuations spirituelles... La source est... du brouillard ?!"
  },
  AvgDialog_123121_Content_32 = {
    Text = "Inconsciemment, ce fil de brume continuait de s'étendre, obscurcissant non seulement la majeure partie de la silhouette de Mouchette mais aussi le paysage environnant."
  },
  AvgDialog_123121_Content_33 = {
    Text = "Fluctuation spirituelle ? C'est ainsi que vous expliquez le « fléau de brouillard »..."
  },
  AvgDialog_123121_Content_34 = {
    Text = "«Catastrophe de brouillard» ?"
  },
  AvgDialog_123121_Content_35 = {
    Text = "Bien sûr, ce monde en crash ne pourrait pas avoir quelque chose d'aussi intéressant, il vient de moi—"
  },
  AvgDialog_123121_Content_36 = {
    Text = "De <Yellow:mon monde>."
  },
  AvgDialog_123121_Content_37 = {
    Text = "Ton monde... ?"
  },
  AvgDialog_123121_Content_38 = {
    Text = "Ces fous de l'Aube des Étoiles ont ouvert la porte interdite qui ne devrait pas être ouverte."
  },
  AvgDialog_123121_Content_39 = {
    Text = "Puis le rituel a échoué avec un \"craquement—\", ne laissant que moi, le malheureux, et les choses entremêlées—"
  },
  AvgDialog_123121_Content_4 = {
    Text = "Alors ? C'est pas mal, non ?"
  },
  AvgDialog_123121_Content_40 = {
    Text = "Juste un petit rappel, vous pouvez maintenant envisager de commencer à fuir."
  },
  AvgDialog_123121_Content_41 = {
    Text = "Ils ? Échapper ?"
  },
  AvgDialog_123121_Content_42 = {
    Text = "Hum☆hum, ces petits gars dans le brouillard arrivent bientôt——"
  },
  AvgDialog_123121_Content_43 = {
    Text = "Amusez-vous bien."
  },
  AvgDialog_123121_Content_44 = {
    Text = "En disant cela, Mouchette recula, se cachant dans le brouillard épais, ne laissant que sa voix s'éloigner de plus en plus dans la brume."
  },
  AvgDialog_123121_Content_45 = {
    Text = "Aussi, merci pour votre aide. Je vous dois une, donc cette fois, vous devez tous me donner assez de temps~"
  },
  AvgDialog_123121_Content_46 = {
    Text = "… Mouchette, attends !?"
  },
  AvgDialog_123121_Content_47 = {
    Text = "Tu veux l'arrêter, mais le brouillard épais te laisse complètement dans le flou sur où commencer à la poursuivre."
  },
  AvgDialog_123121_Content_48 = {
    Text = "Vous réfléchissez un moment, saisissez la clé en argent, vous préparant à activer « Traçage des Esprits », lorsque le communicateur émet à nouveau un son."
  },
  AvgDialog_123121_Content_49 = {
    Text = "C'était un bruit strident de courant défectueux, de plus en plus fort et clair dans le brouillard dense en constante agitation."
  },
  AvgDialog_123121_Content_50 = {
    Text = "@2I... sauvegarder @2..."
  },
  AvgDialog_123121_Content_51 = {Text = "...?!"},
  AvgDialog_123121_Content_52 = {
    Text = "Salvador, tu as entendu ?"
  },
  AvgDialog_123121_Content_53 = {
    Text = "C'est... une voix humaine ?"
  },
  AvgDialog_123121_Content_54 = {
    Text = "En entendant cela, tu prends le communicateur et attends le prochain bruit, et le communicateur te répond——"
  },
  AvgDialog_123121_Content_55 = {
    Text = "Un cri de désespoir, suffisamment perçant pour déchirer les tympans, s'enfonce dans ta tête comme une lame, te plongeant instantanément dans un vertige."
  },
  AvgDialog_123121_Content_56 = {
    Text = "Dans le même temps, une multitude de brumes humanoïdes surgissent de la brume épaisse, hurlant en se précipitant sur toi et Salvador."
  },
  AvgDialog_123121_Content_57 = {
    Text = "Attention !"
  },
  AvgDialog_123121_Content_58 = {
    Text = "L'ardoise se faufile à travers le brouillard, dispersant les monstres formés par la brume, mais ce cri perçant persiste, ininterrompu, frappant ton âme."
  },
  AvgDialog_123121_Content_59 = {
    Text = "Le sang tombe sans interruption de ta cavité nasale, éclaboussant le sol, mais tu ne peux pas voir clairement à cause du vertige."
  },
  AvgDialog_123121_Content_6 = {
    Text = "Mo Xia balança la hache plusieurs fois, ses mouvements étaient nets et rapides, comme si cette énorme arme faisait partie d'elle."
  },
  AvgDialog_123121_Content_60 = {
    Text = "Ton esprit semble se détacher de ton corps, s'étendant sans cesse dans un état invisible et chaotique, ressentant le village dans lequel tu te trouves."
  },
  AvgDialog_123121_Content_61 = {
    Text = "Tu ressens une brume épaisse et omniprésente dévorant sans aucune retenue la terre, les bâtiments, et toute trace de vie humaine ou non humaine."
  },
  AvgDialog_123121_Content_62 = {
    Text = "Et dans cette brume épaisse et infinie, d'innombrables étoiles brûlent silencieusement et froidement, manifestement mortes depuis longtemps."
  },
  AvgDialog_123121_Content_63 = {Text = "%player% !"},
  AvgDialog_123121_Content_64 = {
    Text = "La voix de Salvador résonne dans votre esprit, mais le désespoir et la douleur qui émanent des profondeurs de votre âme vous paralysent."
  },
  AvgDialog_123121_Content_65 = {
    Text = "@2I... sauvegarder @2..."
  },
  AvgDialog_123121_Content_66 = {
    Text = "Sauvegarder @2... @2 moi..."
  },
  AvgDialog_123121_Content_67 = {
    Text = "Les étoiles mortes, chargées d'un désespoir et d'une douleur infinie, t'entourent, fondant de manière obstinée en toi, te corrodant, cherchant à te plonger dans le Repos Éternel."
  },
  AvgDialog_123121_Content_68 = {
    Text = "...Je ne peux pas m'endormir comme ça, Thrall..."
  },
  AvgDialog_123121_Content_69 = {
    Text = "Sal...vador... aide-moi..."
  },
  AvgDialog_123121_Content_7 = {
    Text = "Réaliser cela, vous avez lancé une offensive."
  },
  AvgDialog_123121_Content_70 = {
    Text = "À cet instant, une douce lumière brilla dans ton monde, comme le soleil le plus chaleureux, t'enveloppant doucement et dissipant toute froideur et le sentiment de mort."
  },
  AvgDialog_123121_Content_71 = {
    Text = "C'est la radiance de Salvador."
  },
  AvgDialog_123121_Content_72 = {
    Text = "Il a entendu ta demande."
  },
  AvgDialog_123121_Content_73 = {
    Text = "Il a répondu à votre demande."
  },
  AvgDialog_123121_Content_74 = {
    Text = "<Shake:Tousse tousse...>"
  },
  AvgDialog_123121_Content_75 = {
    Text = "Avec l'aide de Salvador, tu as enfin émergé de ce brouillard vertigineux. Tu as haleté, te sentant enfin retrouver un peu de lucidité."
  },
  AvgDialog_123121_Content_76 = {
    Text = "Salvador, tu peux arrêter de bénir, je vais beaucoup mieux."
  },
  AvgDialog_123121_Content_77 = {
    Text = "Salvador hocha la tête, se plongeant complètement dans la bataille contre la menace inconnue dans le brouillard."
  },
  AvgDialog_123121_Content_78 = {
    Text = "Ces monstres dans le brouillard ne mourront pas. Même s'ils sont dispersés, ils réapparaîtront rapidement."
  },
  AvgDialog_123121_Content_79 = {
    Text = "J'ai peur que tant que ce brouillard existera, ces monstres vivront éternellement."
  },
  AvgDialog_123121_Content_8 = {
    Text = "Mouchette, tu es volontairement capturée par des adeptes de culte."
  },
  AvgDialog_123121_Content_80 = {
    Text = "Père Salvador, crois-tu... que ce que Mouchette a dit est vrai ?"
  },
  AvgDialog_123121_Content_81 = {
    Text = "Depuis le moment où nous nous sommes rencontrés, le feu de l'âme de Lady Mouchette est resté constant. À mon avis, elle n'a montré ni le comportement d'un menteur ni le motif de mentir."
  },
  AvgDialog_123121_Content_82 = {
    Text = "Eh bien, j'ai quelques hypothèses. Cependant, nous devons d'abord trouver Mouchette."
  },
  AvgDialog_123121_Content_83 = {
    Text = "Je respecte ta décision, messager pâle."
  },
  AvgDialog_123121_Content_84 = {
    Text = "Pas besoin de s'inquiéter pour ces monstres dans la brume, je garantirai ta sécurité."
  },
  AvgDialog_123121_Content_85 = {
    Text = "Tu regardes Salvador avec gratitude, puis tu déplaces ta main vers la clé d'argent."
  },
  AvgDialog_123121_Content_86 = {
    Text = "Le sang tombe à nouveau de ta joue, mais tu restes impassible, l'angoisse terrifiante de l'évanouissement précédent envahit tout ton esprit."
  },
  AvgDialog_123121_Content_87 = {
    Text = "@2I... sauvegarder @2..."
  },
  AvgDialog_123121_Content_88 = {
    Text = "Sauvegarder @2... @2 moi..."
  },
  AvgDialog_123121_Content_89 = {
    Text = "Enfin, alors que le communicateur émettait à nouveau du bruit, tu as traversé d'innombrables étoiles froides et mortes et as touché l'esprit de Mouchette."
  },
  AvgDialog_123121_Content_9 = {
    Text = "Hein ? Tu rigoles ? Une personne normale ne deviendrait pas volontairement prisonnière d'un culte, enfermée dans une cage sans nourriture ni eau."
  },
  AvgDialog_123122_Content_1 = {
    Text = "À travers ton regard"
  },
  AvgDialog_123122_Content_10 = {
    Text = "Je suis occupé en ce moment et je n'ai pas le temps de jouer à des jeux de rôle ennuyeux, encore moins d'avoir de l'intérêt à jouer le rôle de la fille éduquée."
  },
  AvgDialog_123122_Content_11 = {
    Text = "Tu ne comprends pas ce monde, et tu ne connais pas le véritable coût et les effets du rituel de l'Aube des Étoiles."
  },
  AvgDialog_123122_Content_12 = {
    Text = "En d'autres termes, les prisonniers avec qui tu viens d'être enfermé sont tous des sacrifices essentiels pour le prochain rituel."
  },
  AvgDialog_123122_Content_13 = {
    Text = "De plus, même si le rituel est refait, tu ne sais pas si les portes entre les deux mondes vont se rouvrir, et si tu pourras retourner dans ton propre monde à travers elles."
  },
  AvgDialog_123122_Content_14 = {
    Text = "Le mouvement de Mouchette s'est arrêté, puis elle se mordit les lèvres avec force."
  },
  AvgDialog_123122_Content_15 = {Text = "新增"},
  AvgDialog_123122_Content_16 = {
    Text = "Mon enfant, je sais que tu n'es pas venu ici de ton plein gré dans ce monde cruel, et je comprends ton désir de retourner."
  },
  AvgDialog_123122_Content_17 = {
    Text = "Nous espérons simplement pouvoir t'aider à éviter de prendre de mauvais chemins."
  },
  AvgDialog_123122_Content_18 = {
    Text = "Tu veux dire que vouloir revenir dans mon propre monde par le rituel de L'aube des étoiles est un chemin erroné ?"
  },
  AvgDialog_123122_Content_19 = {
    Text = "L'attitude récemment adoucie de Mouchette semblait se durcir à nouveau, son ton étant rempli de sarcasme acéré."
  },
  AvgDialog_123122_Content_2 = {
    Text = "Comment vous avez tous fait pour me trouver ?!"
  },
  AvgDialog_123122_Content_20 = {
    Text = "Le brouillard dense environnant commence à tourbillonner et à déferler."
  },
  AvgDialog_123122_Content_21 = {
    Text = "Alors, qu'est-ce que le droit chemin ? Qui détermine ce qui est le droit chemin ? Toi, ou ton dieu ?"
  },
  AvgDialog_123122_Content_22 = {
    Text = "Le masque est enfin tombé. Mouchette ne cache plus son mépris et son dédain pour Salvador."
  },
  AvgDialog_123122_Content_23 = {
    Text = "Qu'importe si tu as jugé juste ou faux ? Je vois ce monde comme encore plus stérile et désolé que Taimuran."
  },
  AvgDialog_123122_Content_24 = {
    Text = "Où est le « Tout-Père » dont vous parlez quand ces gens souffrent ?"
  },
  AvgDialog_123122_Content_25 = {
    Text = "Le brouillard s'épaissit de plus en plus, cachant le visage de Mouchette et l'expression de Salvador."
  },
  AvgDialog_123122_Content_26 = {
    Text = "La seule chose que vous pouvez entendre dans ce brouillard est le soupir de Salvador et les bruits étranges qui signalent l'approche du danger."
  },
  AvgDialog_123122_Content_27 = {Text = "Je..."},
  AvgDialog_123122_Content_28 = {
    Text = "Exprimez-vous librement, prêtre, de toute façon, vous ne faites rien."
  },
  AvgDialog_123122_Content_29 = {
    Text = "À peine Mouchette a-t-elle terminé de parler qu'innombrables brumes humanoïdes émergent de la brume environnante, se dirigeant vers vous."
  },
  AvgDialog_123122_Content_3 = {
    Text = "Quelque chose a-t-il mal tourné avec le brouillard tout à l'heure ? Ou avez-vous aussi la capacité de voir à travers le brouillard comme l'enquêteur ?"
  },
  AvgDialog_123122_Content_30 = {
    Text = "Mais les mouvements de Mouchette sont plus rapides que ceux de ces brumes humanoïdes. Voyant qu'elle s'apprête à s'échapper, tu ne peux t'empêcher de crier."
  },
  AvgDialog_123122_Content_31 = {
    Text = "Salvador, arrête-la !"
  },
  AvgDialog_123122_Content_4 = {
    Text = "L'étonnement de Mouchette ne dura pas longtemps; en un instant, son expression devint calme."
  },
  AvgDialog_123122_Content_5 = {
    Text = "Tu as certains moyens d'échapper aux artefacts dans le brouillard. Mais—"
  },
  AvgDialog_123122_Content_6 = {
    Text = "<Big:<Shake:Ne m'empêche pas de faire mon travail !>>"
  },
  AvgDialog_123122_Content_7 = {
    Text = "Mouchette dit, serrant fermement la hache, son regard rempli de vigilance et d'hostilité."
  },
  AvgDialog_123122_Content_8 = {
    Text = "Mouchette, tu n'as pas besoin de faire ça, nous ne sommes pas ennemis. Du moins pas pour le moment."
  },
  AvgDialog_123122_Content_9 = {
    Text = "Mais avant que tu ne prennes ta décision, j'ai un conseil que je dois te transmettre."
  },
  AvgDialog_125040_Content_1 = {
    Text = "Les inondations de la Rivière sacrée ont apporté des ennuis sans précédent à Mythag. Inattendu, la Chambre de Xu est devenue l'un des rares endroits où vous pouvez chercher refuge."
  },
  AvgDialog_125040_Content_10 = {
    Text = "Je peux être un mensonge, une pensée fugace, mais quand il s'agit de moi-même... c'est totalement ennuyeux."
  },
  AvgDialog_125040_Content_11 = {
    Text = "...Euh ? Xu ?"
  },
  AvgDialog_125040_Content_12 = {Text = "Fog."},
  AvgDialog_125040_Content_13 = {
    Text = "Une brume fine et diaphane t'enveloppe en couches."
  },
  AvgDialog_125040_Content_14 = {
    Text = "<Gray:Attendez, vous n'étiez pas insensible ? On ne faisait pas que discuter et jouer au Weiqi ?! Pourquoi est-ce que vous autres Éveilleurs dites toujours une chose et en faites une autre ?!>"
  },
  AvgDialog_125040_Content_15 = {
    Text = "Alors qu'un fantôme doré vacillant traverse l'afterglow, un toucher satiné lie tes bras et ton dos, te guidant à soulever le voile fait de brume."
  },
  AvgDialog_125040_Content_16 = {
    Text = "Ah, parce que je suis vraiment, vraiment curieux."
  },
  AvgDialog_125040_Content_17 = {
    Text = "Quand ils me touchaient, ils touchaient un phantasme. Quand ils me regardaient, c'était à travers moi, voyant ce qu'ils \"pensent\" être leur bien-aimé."
  },
  AvgDialog_125040_Content_18 = {
    Text = "Mais tu es différent. As-tu l'ombre de quelqu'un ? Si tu regardes de près, quel visage verras-tu sous mon éventail... ?"
  },
  AvgDialog_125040_Content_19 = {
    Text = "La brume se dissipe, et sous l'éventail, quelque chose de chaud effleure doucement ton nez. Les plumes sur l'épaule de la femme tombent, frôlant doucement ta peau inexplicablement tremblante."
  },
  AvgDialog_125040_Content_2 = {
    Text = "La Rivière sacrée ne t'a pas du tout affecté ?"
  },
  AvgDialog_125040_Content_20 = {
    Text = "<Gray:Parfait. Brûlant — encore quelqu'un affecté par la Rivière sacrée.>"
  },
  AvgDialog_125040_Content_21 = {
    Text = "Xu, si je me souviens bien, ce que tu viens de dire était plutôt : « pas de distractions »."
  },
  AvgDialog_125040_Content_22 = {
    Text = "En effet, dans l'Extrême-Orient, lorsqu'un monarque a des affaires importantes à discuter avec quelqu'un, il invite cette personne sous le rideau, d'où le terme—invité au théâtre."
  },
  AvgDialog_125040_Content_23 = {
    Text = "Cependant, pour les femmes, être une invitée au théâtre a une autre signification."
  },
  AvgDialog_125040_Content_24 = {Text = "Toc."},
  AvgDialog_125040_Content_25 = {
    Text = "Une goutte de cire de bougie est tombée sur la table, dispersant les pièces d'échecs."
  },
  AvgDialog_125040_Content_26 = {
    Text = "La lumière s'est éteinte."
  },
  AvgDialog_125040_Content_27 = {
    Text = "J'ai toujours eu besoin de rester à l'écart, mais peut-être que tu peux enfin me voir."
  },
  AvgDialog_125040_Content_28 = {
    Text = "Seul toi me rends prêt à être derrière le rideau, face peut-être à l'invité le plus important de ma vie. Comment pourrais-je avoir des « distractions » ?"
  },
  AvgDialog_125040_Content_29 = {
    Text = "Les chaînes disparaissent, et cette divinité ancienne et mystérieuse vous a clairement laissé un moyen de sortir."
  },
  AvgDialog_125040_Content_3 = {
    Text = "Que ce soit parce que la source de pouvoir vient des trois Aeons ou en raison de ma maîtrise des voies du plaisir, il semble que je n'aie aucune distraction."
  },
  AvgDialog_125040_Content_30 = {
    Text = "Et son invitation, remplie de joie, à peine audible, est difficile à distinguer entre le vrai et le faux."
  },
  AvgDialog_125040_Content_31 = {
    Text = "Je suis tombé dans la mer noire, cherchant le rivage mais incapable de le trouver..."
  },
  AvgDialog_125040_Content_4 = {
    Text = "Ces beaux yeux brillaient de joie alors que plusieurs pièces blanches tapotaient légèrement l'échiquier. Leur propriétaire était très désireux de passer le temps avec ce jeu ancien venu de l'Est."
  },
  AvgDialog_125040_Content_5 = {
    Text = "Les humains sont une espèce étrange ; ils perdent leur calme pour une joie éphémère, et une fois qu'ils l'obtiennent, ils montrent immédiatement un manque d'intérêt."
  },
  AvgDialog_125040_Content_6 = {
    Text = "Année après année, ils se lassent les uns des autres. Ce n'est qu'en tissant des illusions pour eux, en les conduisant à abandonner la vie et la mort, à déchirer leurs cœurs et à creuser leurs foies, qu'ils peuvent jamais oublier."
  },
  AvgDialog_125040_Content_7 = {
    Text = "La lumière vacillante des bougies dessine la silhouette assise de la femme sur le lit, projetant une ombre faible et floue."
  },
  AvgDialog_125040_Content_8 = {
    Text = "Le ciel s'était complètement assombri à un moment donné, et elle laissa échapper un léger rire."
  },
  AvgDialog_125040_Content_9 = {
    Text = "Forcer de bonnes familles à entrer dans le commerce, persuader @2 de revenir à une vie vertueuse. Je suis plutôt doué pour ce genre d'acte, tissant un récit qui est à moitié vrai et à moitié faux, puis leur laissant voir ce visage qui porte soit la culpabilité, soit un amour non réciproque."
  },
  AvgDialog_126907_Content_1 = {
    Text = "Feu d'antan"
  },
  AvgDialog_126907_Content_10 = {
    Text = "Alors, vas-y."
  },
  AvgDialog_126907_Content_11 = {
    Text = "Les yeux d'Elsa brillaient alors qu'elle te tirait vers elle et, en un clin d'œil, commença la danse qui était censée être dirigée par toi."
  },
  AvgDialog_126907_Content_12 = {
    Text = "Sa force est si grande qu'elle te pousse presque dehors, et dans un tourbillon, elle te tire en arrière avec une pure puissance."
  },
  AvgDialog_126907_Content_13 = {
    Text = "<Shake:Oui, désolé>, Seigneur, la prochaine fois, je vais bien me contrôler..."
  },
  AvgDialog_126907_Content_14 = {
    Text = "Tu te sens comme un toupie en train d'être balancée, tournant sans fin, et tes pas de danse déjà maladroits semblent encore plus maladroits."
  },
  AvgDialog_126907_Content_15 = {Text = "Pfft."},
  AvgDialog_126907_Content_16 = {
    Text = "Voyant ton embarras, Ramona ne peut s'empêcher de laisser échapper un léger rire."
  },
  AvgDialog_126907_Content_17 = {
    Text = "Vous croisez son regard, sentant ses yeux souriants vous chuchoter—"
  },
  AvgDialog_126907_Content_18 = {
    Text = "Seigneur Dexter, aujourd'hui c'est à votre tour."
  },
  AvgDialog_126907_Content_19 = {Text = "新增"},
  AvgDialog_126907_Content_2 = {
    Text = "Sur la piste de danse, un jeune homme et une jeune fille en uniformes scolaires tournent gracieusement. La musique coule comme de l'eau, tissant à travers leurs mains entrelacées, les jupes légèrement soulevées et les regards échangés."
  },
  AvgDialog_126907_Content_20 = {
    Text = "À la fin de la chanson, tu as rapidement déposé un baiser sur la main pour dire au revoir à ton partenaire de danse et tu t'es dirigé droit vers Ramona."
  },
  AvgDialog_126907_Content_21 = {
    Text = "Je me souviens que vous étiez appelé le professeur le plus élégant de tout Mythag en ce qui concerne la danse de salon, Seigneur Dexter."
  },
  AvgDialog_126907_Content_22 = {
    Text = "Tu fouilles dans ton esprit, essayant de reproduire la réponse fluide et astucieuse de Lord Dexter."
  },
  AvgDialog_126907_Content_23 = {
    Text = "Je pense que si un concours « Danse avec Elsa » devait être organisé, je serais quand même le gagnant."
  },
  AvgDialog_126907_Content_24 = {
    Text = "Ramona détourna le regard, balançant doucement le verre de vin dans sa main."
  },
  AvgDialog_126907_Content_25 = {
    Text = "Elsa t'admire. Même si cette danse n'est pas parfaite, elle peut être considérée comme l'accomplissement de son vœu pour le Festival du Printemps."
  },
  AvgDialog_126907_Content_26 = {
    Text = "Malheureusement, celui qui danse avec elle n'est pas le véritable Lord Dexter."
  },
  AvgDialog_126907_Content_27 = {
    Text = "Ce qui est encore plus infernal, c'est que, même sans votre acte de possession, la personne qu'elle connaît n'est pas le véritable Lord Dexter."
  },
  AvgDialog_126907_Content_28 = {
    Text = "Mais ce n'est pas le sujet que tu veux aborder."
  },
  AvgDialog_126907_Content_29 = {
    Text = "Ramona, as-tu des vœux pour le Festival du Printemps ?"
  },
  AvgDialog_126907_Content_3 = {
    Text = "Tu remarques Ramona debout seule près d'une petite table en dehors de la piste de danse, sirotant une boisson mystérieuse."
  },
  AvgDialog_126907_Content_30 = {
    Text = "Le jeu de rôle a changé de direction ? Au lieu de saluer votre dame et cette madame, vous êtes venu vérifier votre fille adoptive ?"
  },
  AvgDialog_126907_Content_31 = {
    Text = "Je vois que tu n'es pas allé danser ; est-ce parce que tu n'as pas de partenaire qui te plaît ?"
  },
  AvgDialog_126907_Content_32 = {
    Text = "Pas besoin de te fatiguer."
  },
  AvgDialog_126907_Content_33 = {
    Text = "Auriez-vous l'honneur de danser avec mon vieux père solitaire ?"
  },
  AvgDialog_126907_Content_34 = {
    Text = "Ramona se tait. Tu sais qu'elle cherche des raisons dans le couloir de ses pensées."
  },
  AvgDialog_126907_Content_35 = {
    Text = "La personne que vous attendez espère également que vous accepterez cette invitation à danser."
  },
  AvgDialog_126907_Content_36 = {
    Text = "Comment sais-tu ?"
  },
  AvgDialog_126907_Content_37 = {
    Text = "Je le sais."
  },
  AvgDialog_126907_Content_38 = {
    Text = "Un silence encore plus long."
  },
  AvgDialog_126907_Content_39 = {
    Text = "Oublie ça, je te fais confiance cette fois."
  },
  AvgDialog_126907_Content_4 = {
    Text = "Alors que tu réfléchis à la raison de commencer la conversation, une voix timide se fait entendre à côté de toi."
  },
  AvgDialog_126907_Content_40 = {
    Text = "Elle s'avance gracieusement sur la piste de danse, ses doigts délicats reposant sur ta paume."
  },
  AvgDialog_126907_Content_41 = {
    Text = "Allez, je n'ai pas encore dansé avec toi."
  },
  AvgDialog_126907_Content_42 = {Text = "新增"},
  AvgDialog_126907_Content_43 = {
    Text = "Les pas de danse de Ramona ressemblent à sa personnalité — rationnelle, réservée, précise et méticuleuse."
  },
  AvgDialog_126907_Content_44 = {
    Text = "Tu peux te détendre un peu ; on dirait que tu considères la piste de danse comme un champ de bataille."
  },
  AvgDialog_126907_Content_45 = {
    Text = "Et vous pourriez être un peu plus sérieux, noble seigneur. Depuis que vous avez commencé à danser, vous avez failli écraser mon pied trois fois."
  },
  AvgDialog_126907_Content_46 = {
    Text = "Ce n'est pas comme Lord Dexter, qui s'est plongé dans les cercles sociaux pendant des décennies."
  },
  AvgDialog_126907_Content_47 = {
    Text = "Peut-être que parfois je veux jouer un rôle différent ?"
  },
  AvgDialog_126907_Content_48 = {
    Text = "C'est ça ?"
  },
  AvgDialog_126907_Content_49 = {
    Text = "Tu sais quoi ? Tu es un peu trop calme aujourd'hui."
  },
  AvgDialog_126907_Content_5 = {
    Text = "<Shake:<Small:Seigneur Dexter…… puis-je danser avec vous ?>>"
  },
  AvgDialog_126907_Content_50 = {
    Text = "<LightGray:Je pensais l'avoir restauré plutôt bien...>"
  },
  AvgDialog_126907_Content_51 = {
    Text = "Est-ce vrai ? Peut-être que c'est parce que le temps est trop froid, ce qui fait que les gens perdent l'envie de parler."
  },
  AvgDialog_126907_Content_52 = {
    Text = "Si c'était le noble Dexter, il dirait : C'est tout à fait tabou de flirter avec sa propre fille adoptive, vous savez."
  },
  AvgDialog_126907_Content_53 = {
    Text = "<Yellow:Qui es-tu vraiment ?>"
  },
  AvgDialog_126907_Content_54 = {
    Text = "Ramona, le temps que nous avons pour nous rencontrer est trop court ; je ne veux pas..."
  },
  AvgDialog_126907_Content_55 = {
    Text = "Un léger toussotement de Xu parvient à vos oreilles."
  },
  AvgDialog_126907_Content_56 = {
    Text = "Ça suffit, regarde !"
  },
  AvgDialog_126907_Content_59 = {Text = "新增"},
  AvgDialog_126907_Content_6 = {
    Text = "Oh ? Pourquoi est-ce ?"
  },
  AvgDialog_126907_Content_62 = {
    Text = "Des fleurs enflammées et continues fleurissent au sommet de la tête."
  },
  AvgDialog_126907_Content_64 = {
    Text = "Tout comme le jour de la Cérémonie de Remise des Clés, tu as pris la main de Ramona."
  },
  AvgDialog_126907_Content_66 = {
    Text = "Tu fermes les yeux devant son expression de choc."
  },
  AvgDialog_126907_Content_68 = {
    Text = "Dans une obscurité, d'innombrables cris de joie ou d'anticipation se superposent :"
  },
  AvgDialog_126907_Content_69 = {
    Text = "<Big:<Shake:«Joyeuse Fête de l'An !>>"
  },
  AvgDialog_126907_Content_7 = {
    Text = "Ils refusent tous de danser avec moi... disant qu'ils trouvent cela dangereux."
  },
  AvgDialog_126907_Content_70 = {
    Text = "Joyeuse Fête de l'An, Ramona."
  },
  AvgDialog_126907_Content_71 = {
    Text = "Minuit est arrivé, le vent siffle, et toutes les histoires qui étaient censées t'appartenir s'éloignent de toi."
  },
  AvgDialog_126907_Content_72 = {
    Text = "Mais tu sais, le jour de la rencontre à nouveau n'est plus très loin."
  },
  AvgDialog_126907_Content_8 = {
    Text = "Mais ne t'inquiète pas ! Je vais m'assurer de contrôler ma force !"
  },
  AvgDialog_126907_Content_9 = {
    Text = "Ton regard balaie la petite silhouette frémissante de haut en bas."
  },
  AvgDialog_126908_Content_1 = {
    Text = "La Salle des Ombres"
  },
  AvgDialog_126908_Content_10 = {
    Text = "Son sourire et sa silhouette disparurent de manière ambiguë, se dissipant dans le vent qui se transforma en cendres."
  },
  AvgDialog_126908_Content_11 = {
    Text = "Vas-y, va réclamer ton butin."
  },
  AvgDialog_126908_Content_12 = {
    Text = "Derrière la brume et les cendres, il y a une porte—menant au poste de pilotage du train."
  },
  AvgDialog_126908_Content_13 = {
    Text = "Pas de tours de passe-passe, pas de gadgets, pas d'existence superflue."
  },
  AvgDialog_126908_Content_14 = {
    Text = "C'était juste une porte ordinaire, comme toutes les autres dans le monde, remplissant la fonction d'« entrée et sortie », vous attendant au bout du puzzle."
  },
  AvgDialog_126908_Content_15 = {
    Text = "Tu as pris une profonde inspiration, as serré la clé en argent dans ta main et as poussé la porte."
  },
  AvgDialog_126908_Content_16 = {Text = "新增"},
  AvgDialog_126908_Content_17 = {
    Text = "<LightGray:Je suis un peu peu habitué à l'absence de plus de corps ou même de quelques membres disloqués.>"
  },
  AvgDialog_126908_Content_18 = {Text = "Hmm?"},
  AvgDialog_126908_Content_19 = {
    Text = "Un fil de brouillard cascade du dessus de table, dépliant doucement un mouchoir en soie qui brille doucement, inscrivant avec réflexion les mots de Londinium, qui sont complètement en désaccord avec son style."
  },
  AvgDialog_126908_Content_2 = {
    Text = "Voiture n° 1"
  },
  AvgDialog_126908_Content_20 = {
    Text = "Cher Gardien :\n\nJ'espère que cette lettre vous trouve en bonne santé.\nMaintenant que vous êtes arrivé ici, vous devez avoir découvert le secret de ce train : c'est un Domaine Artificiel construit par N. La concubine de ce train est désormais décédée.\nJ'ai été témoin de toutes vos discussions sur vos destinations. Winkle et Tinct, leurs villes natales ont depuis longtemps disparu ; j'avais également porté mon regard sur Miryam, mais après un examen plus attentif, la Lemuria décrite par Miryam est aussi une chose du passé qui ne peut être récupérée."
  },
  AvgDialog_126908_Content_21 = {
    Text = "Mais où veux-je retourner ? Je pense que c'est probablement vers la véritable Terre sans Rêve. \n Tous, chacun d'entre nous, avons depuis longtemps perdu les lieux auxquels nous pouvons revenir. \n Mais toi, seulement toi, %player%, l'Université Mythag que tu désires et chéris existe encore, et il y a encore des gens qui t'attendent pour revenir. \n Donc, tu dois devenir le dernier gagnant de ce jeu. \n\n Par conséquent, je dédie cette victoire à toi, la marquant par ma mort. \n Tire simplement le levier de ta main, et il te conduira vers l'endroit où ces gens t'attendent."
  },
  AvgDialog_126908_Content_22 = {
    Text = "Puissiez-vous et moi voir nos souhaits réalisés. \n\n Xu"
  },
  AvgDialog_126908_Content_23 = {
    Text = "C'est une étrange blague qui correspond à la personnalité désagréable de ce type N..."
  },
  AvgDialog_126908_Content_24 = {
    Text = "Tu marmonnes doucement, essayant de chasser cette impulsion de ton esprit."
  },
  AvgDialog_126908_Content_25 = {
    Text = "Mais cette tentation est tout simplement trop grande, alors que des compagnons familiers apparaissent dans ton esprit, jusqu'à ce que cette silhouette émerge..."
  },
  AvgDialog_126908_Content_26 = {Text = "Ramona..."},
  AvgDialog_126908_Content_27 = {
    Text = "Le battement de ton cœur remplit ta perception, et ton corps agit avant que ton esprit puisse rattraper ; tu pousses le levier du train."
  },
  AvgDialog_126908_Content_28 = {
    Text = "Le train accélère soudainement, fonçant vers le trou noir lointain."
  },
  AvgDialog_126908_Content_29 = {
    Text = "Quelques secondes plus tard, à l'extrémité du tunnel, à plus de cent mètres, une falaise imposante est soudainement apparue."
  },
  AvgDialog_126908_Content_3 = {
    Text = "Au bout du premier wagon, une silhouette gracieuse avec un éventail couvrant son visage t'attend silencieusement."
  },
  AvgDialog_126908_Content_30 = {
    Text = "Quelle blague..."
  },
  AvgDialog_126908_Content_31 = {
    Text = "Tu tires anxieusement sur le levier avec force, mais il semble coincé et sans réponse, tandis que le mur de la montagne se précipite vers toi à plus de cent kilomètres à l'heure."
  },
  AvgDialog_126908_Content_32 = {
    Text = "<Red:Ça va s'écraser...>"
  },
  AvgDialog_126908_Content_33 = {
    Text = "Tu fermes les yeux sans espoir, attendant que le moment de l'impact arrive."
  },
  AvgDialog_126908_Content_34 = {
    Text = "<Shake:C'est si horrible... Pourquoi ai-je été assez stupide pour croire à l'un des avatars de N ?...>"
  },
  AvgDialog_126908_Content_35 = {
    Text = "Boumboum——!!"
  },
  AvgDialog_126908_Content_36 = {
    Text = "La seconde suivante de l'impact du train, une sensation d'apesanteur te tire droit vers le bas."
  },
  AvgDialog_126908_Content_37 = {Text = "!!! Mmm !"},
  AvgDialog_126908_Content_38 = {
    Text = "Le temps ne sait pas depuis combien de temps il s'écoule."
  },
  AvgDialog_126908_Content_39 = {Text = "新增"},
  AvgDialog_126908_Content_4 = {
    Text = "Veuillez me permettre de me présenter. Je suis Thais dans ce train, ou vous pouvez également m'appeler la taupe de N."
  },
  AvgDialog_126908_Content_40 = {
    Text = "Ici c'est ?<Shake:Mizag?!>"
  },
  AvgDialog_126908_Content_41 = {
    Text = "La structure architecturale à l'extérieur de la fenêtre est si familière que la grande joie te fait ignorer quelques étrangetés, te faisant presque bondir de ce fauteuil coûteux."
  },
  AvgDialog_126908_Content_42 = {
    Text = "Jusqu'à ce que tu voies de manière évidente un miroir placé avec un angle extrêmement soigné et délibéré."
  },
  AvgDialog_126908_Content_43 = {
    Text = "dedans a reflété le visage du Seigneur Dexter."
  },
  AvgDialog_126908_Content_44 = {Text = "???"},
  AvgDialog_126908_Content_45 = {
    Text = "Tu touches ton visage avec méfiance, tandis que dans le miroir, les doigts de Dexter effleurent sa joue creuse."
  },
  AvgDialog_126908_Content_46 = {
    Text = "Oh là là, la récompense pour avoir survécu aux luttes internes est de « retourner à Mizag », mais il n'y a aucune promesse sur la manière de revenir, n'est-ce pas ?"
  },
  AvgDialog_126908_Content_47 = {
    Text = "La limite de ce que je peux faire, c'est de te prêter un instant ma double conscience."
  },
  AvgDialog_126908_Content_48 = {
    Text = "Même ainsi, cette opération viole les lois de l'univers. Tu dois faire preuve de maîtrise et ne pas laisser quelqu'un découvrir que tu n'es pas le Seigneur Dexter lui-même~"
  },
  AvgDialog_126908_Content_49 = {
    Text = "Je suppose que tu es sur le point de dire : « Sinon »…"
  },
  AvgDialog_126908_Content_5 = {
    Text = "Dans une vie qui s'étend sur des milliers, voire des dizaines de milliers d'années, je suis plus habitué au nom \"Xu\". Il est assez ordinaire, suffisamment commun et suffisamment familier pour être considéré comme n'importe qui."
  },
  AvgDialog_126908_Content_50 = {
    Text = "Sinon, clang clang ! La cloche de minuit sonnera tôt, et la calèche en citrouille et la pantoufle de verre retrouveront leur forme d'origine."
  },
  AvgDialog_126908_Content_51 = {
    Text = "Chérissez les moments avant l'arrivée de minuit ; c'est le temps que vous avez gagné avec la vie de vos compagnons."
  },
  AvgDialog_126908_Content_6 = {
    Text = "J'ai beaucoup de choses à te dire, mais pas ici."
  },
  AvgDialog_126908_Content_7 = {
    Text = "Si le destin le permet, retrouvons-nous à l'avenir, ailleurs."
  },
  AvgDialog_126908_Content_8 = {
    Text = "Elle leva la main, puis écrasa le Cœur d'argent dans sa paume."
  },
  AvgDialog_126908_Content_9 = {
    Text = "Vous êtes le vainqueur ultime, Gardien."
  },
  AvgDialog_126909_Content_1 = {
    Text = "Train des vœux"
  },
  AvgDialog_126909_Content_10 = {
    Text = "<Shake:Clang, clang, clang—>"
  },
  AvgDialog_126909_Content_11 = {
    Text = "<Shake:Hum… je suis tellement fatigué.>\n Je dors dans le train, peu importe combien de temps je dors, je ne suis jamais assez reposé."
  },
  AvgDialog_126909_Content_12 = {
    Text = "<LightGray:On dirait que mon cerveau est embrouillé dans un fouillis de glu, oubliant quelque chose de crucial...>"
  },
  AvgDialog_126909_Content_13 = {
    Text = "<LightGray:<Shake:Peu importe, sous prétexte des congés obligatoires pour la Fête de l'An, je vais d'abord retourner à mon dortoir pour faire le mort. Même si Doll me presse pour les devoirs et Ramona pour le rapport, je vais résister jusqu'au bout...>>"
  },
  AvgDialog_126909_Content_14 = {
    Text = "Oh mon dieu, quel petit plant endormi. Tu peux t'appuyer sur mon épaule jusqu'à ce que le train atteigne sa destination, d'accord ?"
  },
  AvgDialog_126909_Content_15 = {Text = "Whoa ?!"},
  AvgDialog_126909_Content_16 = {
    Text = "Vous regardez autour de vous et comptez le nombre de passagers."
  },
  AvgDialog_126909_Content_17 = {
    Text = "Wanda agita à moitié un verre de vin rouge, baissant la tête pour admirer ses ongles pointus soigneusement polis."
  },
  AvgDialog_126909_Content_18 = {
    Text = "Tinct tenait silencieusement une partition de musique, ses lèvres fines bougeant comme si elle s'exerçait doucement dans son esprit."
  },
  AvgDialog_126909_Content_19 = {
    Text = "Winkle était penchée à côté de la petite lampe faiblement éclairée, son regard semblant collé à la mèche comme si elle craignait qu'un souffle de lumière ne s'échappe."
  },
  AvgDialog_126909_Content_2 = {
    Text = "Tada ! Mesdames et messieurs dans le public, joyeux Festival de Printemps ! Enfin, c'est mon tour, petit N, de briller !"
  },
  AvgDialog_126909_Content_20 = {
    Text = "Miryam penche la tête en arrière et ferme les yeux, semblant inconsciente des changements qui l'entourent."
  },
  AvgDialog_126909_Content_21 = {
    Text = "<LightGray:Tout le monde, l'atmosphère de ne pas se déranger est si confortable...>"
  },
  AvgDialog_126909_Content_22 = {Text = "新增"},
  AvgDialog_126909_Content_23 = {Text = "新增"},
  AvgDialog_126909_Content_24 = {
    Text = "<LightGray:Mais ce train ne met-il pas un peu trop de temps?>"
  },
  AvgDialog_126909_Content_25 = {
    Text = "Le train spécial de Mythag est configuré pour traverser la barrière de brouillard à l'extérieur du campus ; c'est un train de courte ligne. Cependant, depuis que vous vous êtes endormi et que vous vous êtes réveillé, au moins une heure s'est déjà écoulée."
  },
  AvgDialog_126909_Content_26 = {
    Text = "Après un moment de réflexion, vous vous approchez du seul enseignant dans le véhicule."
  },
  AvgDialog_126909_Content_27 = {
    Text = "Winkle… pourquoi le <Yellow:Mizag spécial> est-il si lent aujourd'hui ?"
  },
  AvgDialog_126909_Content_28 = {
    Text = "Winkle sauta comme un lapin effrayé."
  },
  AvgDialog_126909_Content_29 = {
    Text = "Quel train spécial de Mythag ? Ce train ne se dirige pas vers la planète d'origine de @1 ?"
  },
  AvgDialog_126909_Content_3 = {
    Text = "Même si tu es mon double, je dois critiquer le fait que ton stratagème cette fois-ci manque de niveau et semble un peu absurde."
  },
  AvgDialog_126909_Content_30 = {
    Text = "Tous les regards sont fixés sur Winkle comme un projecteur."
  },
  AvgDialog_126909_Content_31 = {
    Text = "Ne plaisante pas, petite fille. Ce n'est pas le train pour Aram ?"
  },
  AvgDialog_126909_Content_32 = {
    Text = "Euh, mais Aram est profondément dans le désert, et il est impossible d'avoir un train ici..."
  },
  AvgDialog_126909_Content_33 = {
    Text = "D'après ce que je sais, la destination finale de ce train devrait être Isalaw."
  },
  AvgDialog_126909_Content_34 = {
    Text = "C'est encore plus absurde. Isarau n'est-il pas depuis longtemps détruit ?"
  },
  AvgDialog_126909_Content_35 = {
    Text = "Les paroles sont bon marché ; j'ai les reçus comme preuve."
  },
  AvgDialog_126909_Content_36 = {
    Text = "Wanda a sorti un ticket en métal et l'a montré à tout le monde."
  },
  AvgDialog_126909_Content_37 = {
    Text = "À la station de débarquement sur le billet, le nom Isarawu est écrit en lettres majuscules."
  },
  AvgDialog_126909_Content_38 = {
    Text = "Miryam, Tinct, vous deux..."
  },
  AvgDialog_126909_Content_39 = {
    Text = "Sans plus tarder, Sa volonté me guidera sur le chemin du retour à Lémurie."
  },
  AvgDialog_126909_Content_4 = {
    Text = "Ce n'est pas encore le Festival de Printemps, donc nous devons offrir au public un divertissement différent, n'est-ce pas ?"
  },
  AvgDialog_126909_Content_40 = {
    Text = "Je... Je veux profiter des vacances du Nouvel An chinois pour retourner à Wild Star et passer du temps avec ma sœur..."
  },
  AvgDialog_126909_Content_41 = {
    Text = "<LightGray:Étoile Sauvage... Tinct a erré pendant d'innombrables âges pour atteindre Kadath. Cette distance est totalement inaccessibile pour un train...>"
  },
  AvgDialog_126909_Content_42 = {
    Text = "Lémurie a sombré au fond de la mer il y a mille ans."
  },
  AvgDialog_126909_Content_43 = {
    Text = "Et Isaraul... a longtemps été détruit."
  },
  AvgDialog_126909_Content_44 = {
    Text = "Petit, tu as désigné le paysage pendant si longtemps. Quel est le nom de la planète d'origine vers laquelle tu souhaites retourner, et où se trouve-t-elle ?"
  },
  AvgDialog_126909_Content_45 = {
    Text = "L'expression de Winkle a changé radicalement."
  },
  AvgDialog_126909_Content_46 = {
    Text = "<Shake:La planète d'origine... est la planète d'origine ! Le nom de la planète d'origine... est... <Small:@1...>>"
  },
  AvgDialog_126909_Content_47 = {
    Text = "Hein ? Je dois avoir des hallucinations ; tu ne te souviens même pas du nom de ta planète d'origine ?"
  },
  AvgDialog_126909_Content_48 = {
    Text = "Tout le monde, calmez-vous et écoutez-moi."
  },
  AvgDialog_126909_Content_49 = {
    Text = "La destination de chacun semble très irréaliste. Mais chaque personne détient effectivement un billet pour sa propre patrie."
  },
  AvgDialog_126909_Content_5 = {
    Text = "Après tout, n'est-ce pas trop incroyable d'avoir une seule scène du début à la fin ?"
  },
  AvgDialog_126909_Content_50 = {
    Text = "Donc, ce que nous devons le plus trouver, c'est le<Yellow:conducteur>, pour obtenir des informations sur ce train, plutôt que de nous disputer en vain ici."
  },
  AvgDialog_126909_Content_51 = {
    Text = "Ahem, ahem."
  },
  AvgDialog_126909_Content_52 = {
    Text = "Un bruit étrange et quelque peu drôle vient du coin."
  },
  AvgDialog_126909_Content_53 = {
    Text = "Est-ce la fin de l'excitation ? Je veux regarder le spectacle un peu plus longtemps~"
  },
  AvgDialog_126909_Content_54 = {Text = "Petit N ?!"},
  AvgDialog_126909_Content_55 = {
    Text = "Qu'est-ce qui ne va pas ? Pas d'accueil chaleureux pour moi ? J'ai même préparé un gros cadeau pour tout le monde pour le Festival du Printemps !"
  },
  AvgDialog_126909_Content_56 = {
    Text = "Le maître caché dans l'ombre est lui-même monté sur la scène centrale, ses intentions malveillantes sont évidentes—— il doit encore planifier un complot plus grand."
  },
  AvgDialog_126909_Content_57 = {
    Text = "Que fais-tu ici ?"
  },
  AvgDialog_126909_Content_58 = {
    Text = "N'est-il pas évident ? Moi, attentionné, désintéressé et généreux, j'ai lancé ce train express pour rentrer chez moi pour le Festival du Printemps, permettant à tous ceux qui manquent leur patrie de profiter de la chaleur des fêtes."
  },
  AvgDialog_126909_Content_59 = {
    Text = "Tu n'es pas si bienveillant. Alors, qu'est-ce que tu caches d'autre ?"
  },
  AvgDialog_126909_Content_6 = {
    Text = "<Shake:Ouh ouh, ce n'est pas le moment pour vous de gérer le théâtre et d'affronter cette dame, l'équipe du projet de cette activité de prière est dans une situation désespérée et ne peut fournir qu'une décoration de scène aussi pauvre...>"
  },
  AvgDialog_126909_Content_60 = {
    Text = "Oh, ne me presse pas. Laisse-moi finir de parler petit à petit."
  },
  AvgDialog_126909_Content_61 = {
    Text = "Beaucoup de gens veulent rentrer chez eux, mais il n'y a qu'un seul train. Donc, une seule personne peut retourner dans sa ville natale tant désirée, n'est-ce pas ?"
  },
  AvgDialog_126909_Content_62 = {
    Text = "Oh mon Dieu, en tant que N prévenant, désintéressé et bienveillant, je dois utiliser les moyens les plus équitables pour déterminer qui peut obtenir cette qualification, n'est-ce pas ?"
  },
  AvgDialog_126909_Content_63 = {Text = "Alors..."},
  AvgDialog_126909_Content_64 = {
    Text = "<Big:Alors, <Shake:<Red:Commençons le massacre mutuel !>> !>"
  },
  AvgDialog_126909_Content_65 = {
    Text = "Tuez tout le monde, la dernière personne en vie pourra décider de la destination de ce train et obtenir l'opportunité de <Yellow:Visite d'une journée de la terre natale> !"
  },
  AvgDialog_126909_Content_66 = {
    Text = "Impossible ! Personne ne prendrait la vie d'une autre personne pour quelque chose comme ça... n'est-ce pas ?!"
  },
  AvgDialog_126909_Content_67 = {
    Text = "C'est vrai, même si Faint me manque beaucoup... Je ne peux pas participer à une compétition aussi cruelle..."
  },
  AvgDialog_126909_Content_68 = {
    Text = "Hmph, rester ici à savourer du bon vin et des serviteurs n'est pas si mal. Isaraul n'est qu'un chapitre de mon passé."
  },
  AvgDialog_126909_Content_69 = {
    Text = "Bien qu'il soit difficile de quitter cet endroit... mes petits plants sont ici, et les Aramites ne dépendent plus de moi pour diriger la tribu. Je suppose que je n'ai plus de motivation à participer à ce massacre mutuel."
  },
  AvgDialog_126909_Content_7 = {
    Text = "Il semble que je n'ai d'autre choix que d'attendre et de voir."
  },
  AvgDialog_126909_Content_70 = {
    Text = "Tous les regards se sont tournés vers la dernière personne."
  },
  AvgDialog_126909_Content_71 = {Text = "新增"},
  AvgDialog_126909_Content_72 = {
    Text = "Ton regard ne la dérangea pas le moins du monde ; Miryam resta silencieuse."
  },
  AvgDialog_126909_Content_73 = {
    Text = "Tu es conscient de son obsession, sachant la signification et la valeur du mot Lémurie pour elle."
  },
  AvgDialog_126909_Content_74 = {
    Text = "Sigh, je savais que ce ne serait pas si simple..."
  },
  AvgDialog_126909_Content_75 = {
    Text = "Pour éviter cette situation délicate, j'ai spécifiquement affiné les règles — vous devez m'apporter 5 défunts pour échanger contre le dernier ticket."
  },
  AvgDialog_126909_Content_76 = {
    Text = "Vous devez collecter les sept billets pour commencer le train !"
  },
  AvgDialog_126909_Content_77 = {
    Text = "En d'autres termes, personne ne peut partir d'ici tant qu'il ne reste qu'une seule personne après le massacre dans le train."
  },
  AvgDialog_126909_Content_78 = {
    Text = "Et aussi, parmi vous, il y a un <Yellow:traître> que j'ai placé, qui est devenu grâce à moi, le clone de la petite N aux mille visages !"
  },
  AvgDialog_126909_Content_79 = {
    Text = "Si tu ne fais rien, cela te tuera un par un ! À ce moment-là, personne ne pourra revenir en arrière !"
  },
  AvgDialog_126909_Content_8 = {
    Text = "Sans plus tarder, petit N vous apporte <Shake:les dernières et les plus chaudes <Red:Fête de l'An interprétations exclusives>> !"
  },
  AvgDialog_126909_Content_81 = {
    Text = "À peine N avait-il fini de parler qu'une vigne a soudainement transpercé la brume noire."
  },
  AvgDialog_126909_Content_82 = {
    Text = "D'accord, tout le monde. N'écoutez pas les mots trompeurs de ce gars."
  },
  AvgDialog_126909_Content_83 = {
    Text = "Nous sommes six, y compris le Gardien le plus remarquable de Mythag. Ne pouvons-nous vraiment pas échapper à ce petit compartiment ?"
  },
  AvgDialog_126909_Content_9 = {
    Text = "Des applaudissements et des acclamations résonnent !"
  },
  AvgDialog_126910_Content_1 = {
    Text = "Deuxième mort"
  },
  AvgDialog_126910_Content_10 = {
    Text = "N'est-ce pas plus urgent de trouver le tueur parmi nous ?"
  },
  AvgDialog_126910_Content_11 = {
    Text = "Non, je ne pense pas... Nous ne sommes que si peu, et si nous tombons dans la méfiance mutuelle, cela ne fera qu'aggraver les choses."
  },
  AvgDialog_126910_Content_12 = {
    Text = "Plus important encore, nous devons assurer la sécurité des personnes restantes. Que diriez-vous de rester tous dans la voiture 2 ?"
  },
  AvgDialog_126910_Content_13 = {
    Text = "Tu regardas le Winkle épuisé et hochas la tête."
  },
  AvgDialog_126910_Content_14 = {
    Text = "Le petit jeune arbre a pris une décision, et je ne vais certainement pas m'y opposer."
  },
  AvgDialog_126910_Content_15 = {
    Text = "...toutes les trois heures, j'ai besoin de trouver un coin tranquille pour prier seul."
  },
  AvgDialog_126910_Content_16 = {
    Text = "Pas question ! Qui sait quelles mauvaises choses tu pourrais faire pendant que tu pries !"
  },
  AvgDialog_126910_Content_17 = {
    Text = "De plus, lorsque tout le monde discutait de l'idée d'abandonner le fait de s'entretuer, tu étais le seul à ne pas exprimer ton opinion. Qui sait si tu es l'un des sbires de N ?"
  },
  AvgDialog_126910_Content_18 = {
    Text = "Il n'y a qu'un seul Seigneur que je sers, et c'est la divinité de Lémurie."
  },
  AvgDialog_126910_Content_19 = {
    Text = "Cependant, si tu prononces encore des mots blasphématoires, je n'hésiterai pas à infliger une punition divine au nom de mon Seigneur."
  },
  AvgDialog_126910_Content_2 = {
    Text = "Trois heures plus tard, dans la voiture"
  },
  AvgDialog_126910_Content_20 = {
    Text = "En voyant que Miryam a déjà dégainé le poignard, tu essaies rapidement de jouer les médiateurs."
  },
  AvgDialog_126910_Content_21 = {
    Text = "Nous n'avons actuellement aucune preuve pour accuser qui que ce soit, Tinct... Tout le monde dormait à ce moment-là."
  },
  AvgDialog_126910_Content_22 = {
    Text = "De plus, ce que l'on appelle une taupe pourrait bien être l'un des tours de N, nous attirant à nous tuer les uns les autres selon son plan."
  },
  AvgDialog_126910_Content_23 = {
    Text = "Comment peux-tu dire ça à mon sujet ? Boohoo, j'essayais vraiment de te rappeler tout ça —"
  },
  AvgDialog_126910_Content_24 = {
    Text = "<LightGray:Couteau à œil...>"
  },
  AvgDialog_126910_Content_25 = {
    Text = "D'accord, d'accord, je disparais, waaah..."
  },
  AvgDialog_126910_Content_26 = {
    Text = "Avec un bruit sec, la silhouette du petit N a disparu dans les airs."
  },
  AvgDialog_126910_Content_27 = {
    Text = "Dans ce cas... Miryam, pourrais-tu prier seule dans la voiture numéro 1 et ne pas partir sans permission ?"
  },
  AvgDialog_126910_Content_28 = {
    Text = "Nous nous retrouverons à la porte arrière de la voiture 1, tandis que les autres sont tous dans la même pièce, donc il n'y aura aucun danger."
  },
  AvgDialog_126910_Content_29 = {
    Text = "N'est-ce pas un peu injuste pour Miryam... ?"
  },
  AvgDialog_126910_Content_3 = {
    Text = "<Shake:Glou glou glou—>"
  },
  AvgDialog_126910_Content_30 = {
    Text = "Je n'ai aucune objection."
  },
  AvgDialog_126910_Content_31 = {
    Text = "Miryam ne prêta pas attention à ton obstruction et se leva directement pour quitter la voiture numéro 2, n'oubliant pas de faire attention en se retournant pour verrouiller la porte de séparation."
  },
  AvgDialog_126910_Content_32 = {
    Text = "Les personnes restantes devraient pouvoir se détendre maintenant..."
  },
  AvgDialog_126910_Content_33 = {
    Text = "J'ai toujours l'impression que cette affaire n'est pas si simple..."
  },
  AvgDialog_126910_Content_34 = {
    Text = "Une heure plus tard, dans le wagon n° 2"
  },
  AvgDialog_126910_Content_35 = {
    Text = "Hmm hmm hmm..."
  },
  AvgDialog_126910_Content_36 = {
    Text = "Je vais partir un moment..."
  },
  AvgDialog_126910_Content_37 = {
    Text = "Winkle se dandine vers le carrefour du compartiment de la voiture."
  },
  AvgDialog_126910_Content_38 = {
    Text = "<LightGray:Ai-je trop bu de café...?>"
  },
  AvgDialog_126910_Content_39 = {
    Text = "Une heure plus tard, dans le wagon n° 2"
  },
  AvgDialog_126910_Content_4 = {
    Text = "Arrête de boire."
  },
  AvgDialog_126910_Content_40 = {
    Text = "<LightGray:Bizarre, pourquoi Winkle n'est-il pas encore revenu...>"
  },
  AvgDialog_126910_Content_41 = {
    Text = "Es-tu très inquiet ? Veux-tu que je t'accompagne pour un examen ?"
  },
  AvgDialog_126910_Content_42 = {Text = "Allons-y."},
  AvgDialog_126910_Content_43 = {
    Text = "Un sentiment d'inquiétude se répand dans votre poitrine, les pas creux et les ombres occupant tout le wagon."
  },
  AvgDialog_126910_Content_44 = {
    Text = "Vous comprenez ce nom sombre—"
  },
  AvgDialog_126910_Content_45 = {Text = "Mort."},
  AvgDialog_126910_Content_46 = {
    Text = "Tu frappes à plusieurs reprises à la porte de la salle de bain en appelant le nom de Winkle, mais il n'y a pas de réponse."
  },
  AvgDialog_126910_Content_47 = {
    Text = "Vous commencez à essayer de défoncer la porte."
  },
  AvgDialog_126910_Content_48 = {
    Text = "Boum, boum, boum !"
  },
  AvgDialog_126910_Content_49 = {
    Text = "Que s'est-il passé ?"
  },
  AvgDialog_126910_Content_5 = {
    Text = "<Shake:Glou glou glou—>"
  },
  AvgDialog_126910_Content_50 = {
    Text = "Wanda a également été attirée par le bruit inhabituel."
  },
  AvgDialog_126910_Content_51 = {
    Text = "Winkle est dans la salle de bain depuis une heure. Nous avons frappé à la porte, mais il n'y a pas eu de réponse."
  },
  AvgDialog_126910_Content_52 = {
    Text = "La porte ne peut pas non plus être brisée. C'est étrange, un groupe d'Éveilleurs peut invoquer des vents et des pluies, et est capable de tout contre des créatures mythiques, pourtant ils ne peuvent pas ouvrir une seule porte !"
  },
  AvgDialog_126910_Content_53 = {
    Text = "Avez-vous entendu parler du nouveau genre ?"
  },
  AvgDialog_126910_Content_54 = {
    Text = "En parlant du nouveau genre, nous ne pouvons pas oublier le genre classique."
  },
  AvgDialog_126910_Content_56 = {
    Text = "Dans le contexte du raisonnement, les œuvres classiques font référence à des histoires de détectives avec des mystères clairs et un raisonnement logique, tandis que le nouveau classique ajoute des points de vue uniques à cette base."
  },
  AvgDialog_126910_Content_57 = {
    Text = "Néanmoins, le nouveau classique doit respecter les lecteurs et l'équité, et doit poser des questions dans le cadre des paramètres connus pour les lecteurs, sans permettre des ajouts arbitraires d'éléments surnaturels."
  },
  AvgDialog_126910_Content_58 = {
    Text = "Autrement dit, si vous n'avez pas la compétence pour déverrouiller, vous ne pouvez pas simplement ouvrir la porte qui est verrouillée de l'intérieur."
  },
  AvgDialog_126910_Content_59 = {
    Text = "Le petit N a grimpé sur le porte-bagages pendant un moment, puis s'est caché derrière le dossier de la chaise, évitant toutes les épines et les vignes tout en terminant son discours long et ennuyeux."
  },
  AvgDialog_126910_Content_6 = {Text = "Winkle..."},
  AvgDialog_126910_Content_60 = {
    Text = "Donc, tu veux dire... que c'est un meurtre dans une pièce verrouillée, et à l'intérieur se trouve la scène de crime ?"
  },
  AvgDialog_126910_Content_61 = {
    Text = "Qui sait ! Et si Winkle avait fui par peur de la punition et avait sauté de la voiture par la fenêtre des toilettes ?"
  },
  AvgDialog_126910_Content_62 = {
    Text = "Tu n'as pas dit que nous ne pouvions pas quitter le train ?"
  },
  AvgDialog_126910_Content_63 = {
    Text = "Oh là là, il y avait une erreur dans la déduction !"
  },
  AvgDialog_126910_Content_64 = {
    Text = "Avant l'apparition du vrai détective, il doit toujours y avoir un gars responsable de la déduction incorrecte."
  },
  AvgDialog_126910_Content_65 = {
    Text = "Si personne ne veut jouer le rôle du fou, alors laissez-moi, le grand et dévoué petit N, le jouer !"
  },
  AvgDialog_126910_Content_66 = {
    Text = "Arrête de discuter avec ce type."
  },
  AvgDialog_126910_Content_67 = {
    Text = "Bien que ce soit un peu impoli... il y a une petite fenêtre à persiennes sur la porte de la salle de bain, et la structure est très fragile."
  },
  AvgDialog_126910_Content_68 = {
    Text = "Wanda a levé le spike."
  },
  AvgDialog_126910_Content_69 = {
    Text = "Craquement, les stores ont été enlevés."
  },
  AvgDialog_126910_Content_7 = {
    Text = "Peu importe combien de café est consommé, Tinct ne reviendra pas, n'est-ce pas ?"
  },
  AvgDialog_126910_Content_70 = {
    Text = "Laisse le reste à moi."
  },
  AvgDialog_126910_Content_71 = {
    Text = "Les vignes s'étirèrent et déverrouillèrent la porte, puis vous l'avez poussée ouverte."
  },
  AvgDialog_126910_Content_72 = {
    Text = "Plus de temps."
  },
  AvgDialog_126910_Content_73 = {
    Text = "Winkle s'est recroquevillé silencieusement dans le coin de la salle de bain."
  },
  AvgDialog_126910_Content_74 = {Text = "Winkle!"},
  AvgDialog_126910_Content_75 = {
    Text = "Tu as couru précipitamment vers Winkle, ses lèvres suintant d'un sang rouge profond, et elle avait déjà perdu son souffle."
  },
  AvgDialog_126910_Content_76 = {
    Text = "Pour être franc, Winkle... au moment de ton décès, ni toi, ni moi, ni Wanda n'avons jamais quitté le Wagon No. 2."
  },
  AvgDialog_126910_Content_77 = {
    Text = "Le seul meurtrier... ne peut être que Miryam."
  },
  AvgDialog_126910_Content_78 = {
    Text = "Mon seigneur ne m'a pas guidé à prendre de telles actions. Cependant, si vous insistez, je peux prononcer le jugement au nom des dieux."
  },
  AvgDialog_126910_Content_79 = {
    Text = "Oh non, nous sommes dans une impasse !"
  },
  AvgDialog_126910_Content_8 = {
    Text = "<Shake:tu——>"
  },
  AvgDialog_126910_Content_80 = {
    Text = "Puisqu›on parle de jugement divin, j›aimerais vous offrir un moyen facile de l›emporter !"
  },
  AvgDialog_126910_Content_81 = {
    Text = "Nous pouvons maintenant procéder à un vote, et la personne ayant le plus de voix sera personnellement expulsée du train par mes soins, perdant ainsi sa chance de rentrer chez elle !"
  },
  AvgDialog_126910_Content_82 = {
    Text = "Sans aucun doute, je vais choisir Miryam."
  },
  AvgDialog_126910_Content_83 = {Text = "Thais."},
  AvgDialog_126910_Content_84 = {
    Text = "Petit gars, qu'en penses-tu ? Étant donné la situation actuelle, je choisirais également de voter pour Miryam."
  },
  AvgDialog_126910_Content_85 = {
    Text = "Miryam 2 votes ! Thais 1 vote !"
  },
  AvgDialog_126910_Content_86 = {
    Text = "N, comment calculons-nous le résultat en cas d'égalité ?"
  },
  AvgDialog_126910_Content_87 = {
    Text = "S'il y a égalité, alors on considère que personne n'est éliminé~"
  },
  AvgDialog_126910_Content_88 = {
    Text = "Mais réfléchis bien, il ne reste maintenant que quatre personnes. Si tu abandonnes cette chance, et qu'un traître tue encore une personne, tes chances de gagner vont—vraiment—augmenter!"
  },
  AvgDialog_126910_Content_89 = {
    Text = "Je ne veux pas faire du mal aux gens bien. Je vote pour Thais."
  },
  AvgDialog_126910_Content_9 = {
    Text = "C'est ça, ce qui est plus crucial, c'est de trouver un moyen de descendre du train."
  },
  AvgDialog_126910_Content_90 = {
    Text = "Tu ne vas vraiment pas reconsidérer ? C'est la seule chance de voter ?"
  },
  AvgDialog_126910_Content_91 = {
    Text = "Non, plus tu dis cela, plus je sens que j'ai fait le bon choix."
  },
  AvgDialog_126910_Content_92 = {
    Text = "D'accord, donc le résultat du vote pour ce tour est : une égalité, et personne n'est éliminé~"
  },
  AvgDialog_126910_Content_93 = {
    Text = "Sigh~ Si déçu~ Petit N doit trouver un coin pour se calmer. À plus tard tout le monde~"
  },
  AvgDialog_126911_Content_1 = {
    Text = "Le jeu commence"
  },
  AvgDialog_126911_Content_10 = {
    Text = "Si tu continues à divaguer, cela ne me dérangerait pas de t'utiliser pour te faire ressentir à nouveau la sensation d'être transpercé au cœur, tu sais ?"
  },
  AvgDialog_126911_Content_11 = {
    Text = "Wanda caressa la pointe dans sa paume."
  },
  AvgDialog_126911_Content_12 = {
    Text = "Oh là là, quelle déclaration déchirante c'est."
  },
  AvgDialog_126911_Content_13 = {
    Text = "Le programme de la Fête de l'An que j'ai préparé avec tant de soin est vraiment si impopulaire ? <Italic:Snif...>"
  },
  AvgDialog_126911_Content_14 = {
    Text = "Faisant semblant de pleurer pendant moins d'une seconde, N éclata immédiatement en un sourire éclatant."
  },
  AvgDialog_126911_Content_15 = {
    Text = "En bref, veuillez donner le meilleur de vous-mêmes et vous battre entre vous ! Petit N attendra vos performances avec impatience !"
  },
  AvgDialog_126911_Content_16 = {
    Text = "«Whoosh», le petit N a de nouveau disparu. \n Le train est retombé dans le silence troublant une fois de plus."
  },
  AvgDialog_126911_Content_17 = {
    Text = "Puis vient un long silence, l'obscurité devant sur les rails semble sans fin."
  },
  AvgDialog_126911_Content_18 = {
    Text = "Combien de temps le train va-t-il encore voyager ? Quelle est la destination ?"
  },
  AvgDialog_126911_Content_19 = {
    Text = "Dans le cœur des gens, il se peut qu'il n'y ait pas de réponse, ou qu'il y ait une réponse qui ne peut être dite."
  },
  AvgDialog_126911_Content_2 = {
    Text = "...Impossible de sortir."
  },
  AvgDialog_126911_Content_20 = {
    Text = "Euh, tout le monde..."
  },
  AvgDialog_126911_Content_21 = {
    Text = "Une voix claire rompit le silence."
  },
  AvgDialog_126911_Content_22 = {
    Text = "C'est assez ennuyeux de rester ici... Si personne ne se dérange, que diriez-vous que je chante une chanson pour tout le monde ?"
  },
  AvgDialog_126911_Content_23 = {
    Text = "Hmm ?! J'adore ça ! Puis-je demander une chanson ?"
  },
  AvgDialog_126911_Content_24 = {
    Text = "Va-t'en, qu'est-ce que ça te fait ?"
  },
  AvgDialog_126911_Content_25 = {
    Text = "Puisque c'est le Festival du Printemps de l'Empire Panlong, je me souviens d'une ballade orientale que j'ai entendue interprétée par le Chœur des Ombres."
  },
  AvgDialog_126911_Content_26 = {
    Text = "Je ne suis pas sûr d'avoir maîtrisé assez de pièces orientales..."
  },
  AvgDialog_126911_Content_27 = {
    Text = "Le nom de cette chanson est « Fleur de jasmin »."
  },
  AvgDialog_126911_Content_28 = {
    Text = "Oh ? C'est vraiment ce style ?"
  },
  AvgDialog_126911_Content_29 = {
    Text = "Quelle coïncidence, j'étais aussi dans le public pour cette performance du Chœur des Ombres."
  },
  AvgDialog_126911_Content_3 = {
    Text = "Winkle a prononcé la conclusion avec désespoir."
  },
  AvgDialog_126911_Content_30 = {
    Text = "Si je me souviens bien, je suis aussi tombé sur... dans le public."
  },
  AvgDialog_126911_Content_31 = {
    Text = "Le regard de Wanda est fixé sur Miryam, tandis que Miryam hoche simplement la tête en silence."
  },
  AvgDialog_126911_Content_32 = {
    Text = "Puisque personne ne s'y oppose... je vais commencer à chanter."
  },
  AvgDialog_126911_Content_33 = {
    Text = "Tinct a dégagé sa gorge."
  },
  AvgDialog_126911_Content_34 = {
    Text = "<Shake:Quelle fleur de jasmin, quelle fleur de jasmin♪~ Aucune fleur dans tout le jardin ne peut lui comparer♪~>"
  },
  AvgDialog_126911_Content_35 = {
    Text = "<Shake:La-la-la~ la-la-la~ la-la-la♪~>"
  },
  AvgDialog_126911_Content_36 = {
    Text = "Un chant éthéré et mélodieux résonne dans la voiture vide."
  },
  AvgDialog_126911_Content_37 = {
    Text = "Sous la mélodie apaisante, les cordes tendues de votre esprit se détendent progressivement, et vous ressentez étonnamment un léger sommeil."
  },
  AvgDialog_126911_Content_38 = {
    Text = "Je suppose que tout le monde est fatigué, n'est-ce pas ? J'ai l'habitude de rester éveillé, donc je peux veiller sur tout le monde."
  },
  AvgDialog_126911_Content_39 = {
    Text = "Tu as hoché la tête et puis tu as plongé profondément dans le rêve qui s'approchait lentement."
  },
  AvgDialog_126911_Content_4 = {
    Text = "À part le poste de pilotage, ce train se compose de trois voitures. Nous sommes actuellement dans la voiture n° 2, qui est la voiture du milieu."
  },
  AvgDialog_126911_Content_40 = {Text = "新增"},
  AvgDialog_126911_Content_41 = {
    Text = "Après un long moment, Tinct a également fini de chanter."
  },
  AvgDialog_126911_Content_42 = {
    Text = "Tout le monde dort, donc tu devrais aussi te reposer un peu, n'est-ce pas ?"
  },
  AvgDialog_126911_Content_43 = {
    Text = "Vraiment... ça va ?"
  },
  AvgDialog_126911_Content_44 = {
    Text = "Quoi, as-tu peur que je sois la taupe ?"
  },
  AvgDialog_126911_Content_45 = {
    Text = "Cela ne se produira pas. C'est juste qu'autrefois, j'attendais que Faint s'endorme avant d'aller me reposer..."
  },
  AvgDialog_126911_Content_46 = {
    Text = "Alors aujourd'hui, c'est à ton tour de bien te reposer ! Vas-y, vas-y."
  },
  AvgDialog_126911_Content_47 = {
    Text = "Sous l'insistance de Winkle, Tinct prit également une couverture, s'appuyant contre le dossier de la chaise et fermant les yeux."
  },
  AvgDialog_126911_Content_48 = {
    Text = "Pas étonnant que tout le monde soit endormi ; c'est une atmosphère si relaxante..."
  },
  AvgDialog_126911_Content_49 = {Text = "新增"},
  AvgDialog_126911_Content_5 = {
    Text = "Le wagon 1 et le wagon 3 sont tous deux vides, avec toutes les fenêtres et les portes complètement verrouillées, impossibles à franchir par des moyens physiques ou par la Technologie Argent."
  },
  AvgDialog_126911_Content_50 = {Text = "新增"},
  AvgDialog_126911_Content_51 = {Text = "Mmm ?"},
  AvgDialog_126911_Content_52 = {
    Text = "La première chose qui attire votre attention est le visage paisible et serein de Winkle en train de dormir."
  },
  AvgDialog_126911_Content_53 = {
    Text = "Les lumières dans le train se sont éteintes à un moment donné, et l'environnement environnant a été englouti dans l'obscurité, avec seulement une douce lumière brillant à travers la connexion entre les wagons."
  },
  AvgDialog_126911_Content_54 = {
    Text = "Winkle... comment as-tu pu t'endormir... ?"
  },
  AvgDialog_126911_Content_55 = {
    Text = "Winkle laissa échapper un souffle doux."
  },
  AvgDialog_126911_Content_56 = {
    Text = "...Hmm ? Ai-je... pu m'endormir ?"
  },
  AvgDialog_126911_Content_57 = {
    Text = "Hé hé hé ?!!! Est-ce que je me suis endormi !!!"
  },
  AvgDialog_126911_Content_58 = {
    Text = "L'appel de Winkle était comme une tempête soudaine, réveillant instantanément tous les passagers endormis."
  },
  AvgDialog_126911_Content_59 = {
    Text = "Les lumières se sont soudainement allumées, illuminant toute la voiture."
  },
  AvgDialog_126911_Content_6 = {
    Text = "Je te l'ai dit ! Pas besoin de s'agiter ! Personne ne peut sortir tant qu'il n'y a qu'un seul gagnant dans la voiture !"
  },
  AvgDialog_126911_Content_60 = {
    Text = "Chers passagers, reposez-vous bien à bord de l'Express du retour ?"
  },
  AvgDialog_126911_Content_61 = {
    Text = "Après avoir détecté que tous les passagers sont entrés dans un état de sommeil, le petit N a spécialement préparé un environnement calme et bloquant la lumière pour vous !"
  },
  AvgDialog_126911_Content_62 = {
    Text = "Désolé, je compte généralement sur le fait de boire beaucoup de café pour rester éveillé..."
  },
  AvgDialog_126911_Content_63 = {
    Text = "Attends, l'un d'entre nous est-il manquant ?"
  },
  AvgDialog_126911_Content_64 = {Text = "新增"},
  AvgDialog_126911_Content_65 = {
    Text = "Hein ? Le petit plant me regarde ? Je suis ici."
  },
  AvgDialog_126911_Content_66 = {
    Text = "Donc, la personne disparue est..."
  },
  AvgDialog_126911_Content_67 = {
    Text = "Tous les regards se tournèrent vers l'extrémité du wagon—"
  },
  AvgDialog_126911_Content_68 = {
    Text = "Un grand trou a été percé dans la gorge de Tinct par un objet tranchant, et le plasma sanguin coulait le long de son cou gracieux de cygne depuis la blessure, imbibant l'avant de sa robe."
  },
  AvgDialog_126911_Content_69 = {
    Text = "Le rossignol qui saigne ne peut plus chanter."
  },
  AvgDialog_126911_Content_7 = {
    Text = "Pourquoi es-tu encore là... Thais n'a-t-il pas juste... ?"
  },
  AvgDialog_126911_Content_70 = {
    Text = "<Shake:yīyā————!!!>"
  },
  AvgDialog_126911_Content_71 = {
    Text = "Bigorneau poussa un cri perçant qui déchira le ciel nocturne, glissant le long du mur jusqu'au coin, enroulant ses bras autour de lui-même, tremblant de manière incontrôlable."
  },
  AvgDialog_126911_Content_72 = {
    Text = "<Shake:Désolé, je ne devrais pas être si confiant en moi-même, je ne devrais pas veiller seul, je ne devrais pas penser que je ne vais pas m'endormir sans café…>"
  },
  AvgDialog_126911_Content_73 = {
    Text = "Winkle mordait anxieusement ses ongles, des larmes de panique jaillissaient continuellement et tombaient sur le tapis."
  },
  AvgDialog_126911_Content_74 = {
    Text = "Clang ! Que a entendu le petit N compréhensif ? <Shake:les besoins des passagers> !"
  },
  AvgDialog_126911_Content_75 = {
    Text = "Nous offrons maintenant un service attentionné à nos précieux passagers—<Yellow:machine à café illimitée> !"
  },
  AvgDialog_126911_Content_76 = {
    Text = "Tant que tu presses ce bouton rouge, un flot ininterrompu de chaleur américaine profonde et intense jaillira de la buse !"
  },
  AvgDialog_126911_Content_77 = {
    Text = "Tu avances en silence, levant la main—"
  },
  AvgDialog_126911_Content_78 = {
    Text = "Puis j'ai frappé ce petit N devant moi avec force, le mettant à plat."
  },
  AvgDialog_126911_Content_79 = {
    Text = "<Shake:Désolé, désolé, désolé…>"
  },
  AvgDialog_126911_Content_8 = {
    Text = "Hmph, si mourir était aussi facile, je ne serais pas mon petit N !"
  },
  AvgDialog_126911_Content_80 = {
    Text = "Les sanglots de Winkle résonnaient à travers la voiture."
  },
  AvgDialog_126911_Content_81 = {
    Text = "Peu importe comment vous résistez, l'ouverture sera marquée par la mort de Tinct—"
  },
  AvgDialog_126911_Content_82 = {
    Text = "Le massacre mutuel a commencé."
  },
  AvgDialog_126911_Content_9 = {
    Text = "Alors, comment ça va tout le monde ? Tout le monde a-t-il décidé dans son cœur de la cible à tuer ce soir ?"
  },
  AvgDialog_126912_Content_1 = {
    Text = "Technique cachée"
  },
  AvgDialog_126912_Content_10 = {
    Text = "Pour une raison quelconque, vous avez toujours l'impression que sous ce sourire se cache une certaine émotion que vous n'avez pas encore découverte."
  },
  AvgDialog_126912_Content_11 = {
    Text = "Allons-y, Miryam. Nous allons au wagon numéro 1."
  },
  AvgDialog_126912_Content_12 = {
    Text = "Au moment où la porte de connexion est sur le point de se fermer, Wanda tourne la tête pour regarder en arrière."
  },
  AvgDialog_126912_Content_13 = {
    Text = "Joyeux Festival du Printemps, Gardien."
  },
  AvgDialog_126912_Content_14 = {Text = "新增"},
  AvgDialog_126912_Content_15 = {
    Text = "Wagon n° 2"
  },
  AvgDialog_126912_Content_16 = {
    Text = "Après le départ de Wanda et Miryam, il ne restait que toi et Thais dans la voiture."
  },
  AvgDialog_126912_Content_17 = {
    Text = "Alors, que devrions-nous faire de ce rare moment de solitude, ma petite pousse ?"
  },
  AvgDialog_126912_Content_18 = {
    Text = "Thais s'approche soudainement avec de mauvaises intentions, te faisant reculer d'un pas pour maintenir une distance de sécurité."
  },
  AvgDialog_126912_Content_19 = {
    Text = "Je peux me dépêcher de rédiger le rapport..."
  },
  AvgDialog_126912_Content_2 = {
    Text = "Wagon n° 2"
  },
  AvgDialog_126912_Content_20 = {
    Text = "C'est déjà le Festival du Printemps, alors détends-toi un peu et arrête de penser à ton rapport tout le temps."
  },
  AvgDialog_126912_Content_21 = {
    Text = "Ses bras couleur de miel s'enroulent doucement autour de tes épaules, ses souffles ambigus t'enlaçant comme la brume nocturne."
  },
  AvgDialog_126912_Content_22 = {Text = "Cela..."},
  AvgDialog_126912_Content_23 = {
    Text = "L'expression sérieuse de la poupée, le soupir de Ramona et le bâton d'enseignement de Czort défilent instantanément devant vos yeux."
  },
  AvgDialog_126912_Content_24 = {
    Text = "Je ne peux toujours pas le faire..."
  },
  AvgDialog_126912_Content_25 = {
    Text = "Tu souris de manière obséquieuse, semblant éviter par hasard l'affection de Thais."
  },
  AvgDialog_126912_Content_26 = {
    Text = "D'accord, que diriez-vous de nous asseoir tranquillement et de discuter un moment ?"
  },
  AvgDialog_126912_Content_27 = {
    Text = "Dis-moi, Gardien... Dans ce moment fugace où ton regard a vacillé, à qui pensais-tu ?"
  },
  AvgDialog_126912_Content_28 = {Text = "新增"},
  AvgDialog_126912_Content_29 = {Text = "新增"},
  AvgDialog_126912_Content_3 = {
    Text = "Au milieu du grondement du train, Wanda fut la première à rompre le silence."
  },
  AvgDialog_126912_Content_30 = {
    Text = "Tu ne te souviens pas combien de temps tu as raconté, seulement que les événements passés sont clairement ancrés dans ton esprit."
  },
  AvgDialog_126912_Content_31 = {
    Text = "Et puis il y a la salle à manger de Mythag, qui est un endroit beaucoup plus animé que le laboratoire."
  },
  AvgDialog_126912_Content_32 = {
    Text = "Surtout quand les cupcakes sont disponibles, les enfants se précipitent au comptoir, ignorant complètement l'élégance et la vertu de la grâce et de la modestie d'une dame..."
  },
  AvgDialog_126912_Content_33 = {
    Text = "Certains petits fauteurs de troubles trichent en faisant tenir les tickets de repas par leurs amis animaux et en occupant de l'espace à la zone de service, puis ils donnent les gâteaux qu'ils ont volés à leurs amis timides."
  },
  AvgDialog_126912_Content_34 = {
    Text = "<Shake:Et... Hein?>"
  },
  AvgDialog_126912_Content_35 = {
    Text = "Tu découvres que ta voix est devenue étouffée, et des larmes coulent sans contrôle de tes yeux."
  },
  AvgDialog_126912_Content_36 = {
    Text = "Il y a plus..."
  },
  AvgDialog_126912_Content_37 = {
    Text = "Les larmes s'accumulent de plus en plus, rendant ma vision de plus en plus floue."
  },
  AvgDialog_126912_Content_38 = {
    Text = "<Shake:Je veux vraiment retourner à Mythag, être à nouveau avec tout le monde...>"
  },
  AvgDialog_126912_Content_39 = {
    Text = "C'est étrange. Je ne suis parti de Mythag que <Yellow:il y a trois jours> pour mener des recherches sur le terrain. Cela ne devrait pas être..."
  },
  AvgDialog_126912_Content_4 = {
    Text = "J'ai une suggestion."
  },
  AvgDialog_126912_Content_40 = {
    Text = "Mais l'angoisse du désir fait mal à ton nez, comme si une corde tendue dans ton esprit était sur le point de céder."
  },
  AvgDialog_126912_Content_41 = {
    Text = "Ne t'inquiète pas, ne t'inquiète pas, Gardien."
  },
  AvgDialog_126912_Content_42 = {
    Text = "Tu es enveloppé dans une douce étreinte. L'étreinte d'une mère."
  },
  AvgDialog_126912_Content_43 = {
    Text = "@2 Je te promets, tu retournes à l'endroit que tu désires."
  },
  AvgDialog_126912_Content_44 = {
    Text = "Les traits de Thais sont devenus flous."
  },
  AvgDialog_126912_Content_45 = {
    Text = "La brume vaporeuse vous enveloppa tous les deux, et tu te blottis silencieusement dans ses bras, devenant un être très petit."
  },
  AvgDialog_126912_Content_46 = {
    Text = "Vous sentez le parfum. <Yellow:L'odeur de magnolia>."
  },
  AvgDialog_126912_Content_47 = {
    Text = "<Red:Le parfum des grandes fleurs de magnolia.>"
  },
  AvgDialog_126912_Content_48 = {
    Text = "Tu te trouves enveloppé dans cet arôme parfumé, tombant dans un sommeil semblable à celui d'un bébé qui te fait oublier toutes tes inquiétudes et tes peurs."
  },
  AvgDialog_126912_Content_49 = {
    Text = "Avant que la conscience ne s'évanouisse, tout ce dont tu te souviens, ce sont les <Yellow:yeux dorés et pleins de désir> de Mère."
  },
  AvgDialog_126912_Content_5 = {
    Text = "Nous pouvons nous associer et rester dans les wagons 1 et 2, afin de veiller les uns sur les autres."
  },
  AvgDialog_126912_Content_50 = {Text = "新增"},
  AvgDialog_126912_Content_51 = {Text = "Alors—"},
  AvgDialog_126912_Content_52 = {
    Text = "Un fort « clang » est venu de la voiture numéro un."
  },
  AvgDialog_126912_Content_53 = {
    Text = "Tu sais, le jeu de l'abattage mutuel est toujours en cours, et le rêve devrait s'éveiller."
  },
  AvgDialog_126912_Content_54 = {
    Text = "Voiture n° 1"
  },
  AvgDialog_126912_Content_55 = {
    Text = "Dans la voiture n° 1, les corps gravement blessés de Wanda et Miryam étaient entremêlés, un poignard enfoncé jusqu'au fond dans la poitrine de Wanda, tandis que Miryam était transpercée par d'innombrables piques."
  },
  AvgDialog_126912_Content_56 = {
    Text = "Wanda entrou ouvrit les yeux, à moitié éblouie, et vous les révéla par intermittence."
  },
  AvgDialog_126912_Content_57 = {
    Text = "Je savais que Miryam frapperait, alors j'étais prêt pour un « Contre »..."
  },
  AvgDialog_126912_Content_58 = {
    Text = "Maintenant, N n'a absolument aucun moyen d'atteindre sa victoire..."
  },
  AvgDialog_126912_Content_59 = {
    Text = "Vous devez tous..."
  },
  AvgDialog_126912_Content_6 = {
    Text = "N'est-il pas dangereux pour ceux qui restent à côté du meurtrier ?"
  },
  AvgDialog_126912_Content_60 = {
    Text = "Les derniers mots de Wanda s'estompèrent. La bénédiction de ses derniers mots fut également engloutie par le silence."
  },
  AvgDialog_126912_Content_61 = {
    Text = "Après un long silence, Thais parla enfin avec une tremblement dans la voix."
  },
  AvgDialog_126912_Content_62 = {
    Text = "Il semble que le meurtrier soit en effet Miryam. Elle savait qu'en vertu de la règle de protection mutuelle entre les deux, elle devait d'abord tuer Wanda ; sinon, ses actions provoqueraient sûrement l'hostilité des autres personnes restantes, alors elle est passée à l'action."
  },
  AvgDialog_126912_Content_63 = {
    Text = "Wanda... précisément parce qu'elle sait qu'elle excelle dans le « Contre », elle a pris l'initiative de partager une chambre avec la traîtresse Miryam."
  },
  AvgDialog_126912_Content_64 = {
    Text = "Elle a échangé son propre sacrifice pour la victoire des « bonnes personnes »"
  },
  AvgDialog_126912_Content_65 = {
    Text = "Le ton de Thais, lourd mais empreint d'un certain respect.\n Si seulement cela pouvait venir du cœur."
  },
  AvgDialog_126912_Content_66 = {
    Text = "Quel dommage, ce n'est pas le cas."
  },
  AvgDialog_126912_Content_67 = {
    Text = "Non... Miryam... ce n'est pas N qui a infiltré nos rangs."
  },
  AvgDialog_126912_Content_68 = {
    Text = "<Shake:Ce n'est pas elle ? Alors pourquoi elle ? …>"
  },
  AvgDialog_126912_Content_69 = {
    Text = "Pour la victoire, pour gagner, pour le « Lémurie » promis par N, la Miryam que je connais irait en effet jusqu'à prendre les choses en main."
  },
  AvgDialog_126912_Content_7 = {
    Text = "Mais au moins, cela garantit que N n'atteindra pas la victoire finale."
  },
  AvgDialog_126912_Content_70 = {
    Text = "Alors... pourquoi est–ce que tu..."
  },
  AvgDialog_126912_Content_71 = {
    Text = "Le véritable traître, c'est toi. Thais, ou plutôt, <Yellow:quelqu'un se faisant passer pour Thais>."
  },
  AvgDialog_126912_Content_72 = {
    Text = "Peut-être que votre préparation a été suffisante ; Thais montra peu d'étonnement, se contentant de regarder vos yeux avec un air calme et un léger sourire."
  },
  AvgDialog_126912_Content_73 = {
    Text = "Oh ? Quand l'as-tu découvert ? J'aimerais en savoir plus."
  },
  AvgDialog_126912_Content_74 = {
    Text = "Après que Winkle... est parti, Wanda a suggéré de diviser les deux compartiments."
  },
  AvgDialog_126912_Content_75 = {
    Text = "Vraiment... si tôt ? Je pensais que les méthodes que j'avais choisies étaient suffisamment prudentes et ne laissaient pas beaucoup de traces."
  },
  AvgDialog_126912_Content_76 = {
    Text = "Les blessures perçantes sur Tinct pourraient provenir des épines de Thais, des pointes de Wanda, ou du poignard que porte Miryam."
  },
  AvgDialog_126912_Content_77 = {
    Text = "Quant à la mort de Bigorneau... Thais, Wanda et Miryam ont tous la capacité d'infliger du poison."
  },
  AvgDialog_126912_Content_78 = {
    Text = "Considérant la consommation de café de Winkle, tant que du poison est ajouté à la machine à café, la mort arrivera inévitablement à un moment donné."
  },
  AvgDialog_126912_Content_79 = {
    Text = "Donc, oui, en ce qui concerne les méthodes de commission du crime, ta déguisement a été très réussi."
  },
  AvgDialog_126912_Content_8 = {
    Text = "Je vais garder un œil sur Miryam. Ne t'inquiète pas, j'ai une carte maîtresse que l'autre partie ne s'attendrait jamais à voir."
  },
  AvgDialog_126912_Content_80 = {
    Text = "Alors, quelle est la base de votre raisonnement... ?"
  },
  AvgDialog_126912_Content_81 = {
    Text = "Avez-vous entendu parler d'un jeu de société appelé \"Nuit de la Lune Sanglante\" ? Chaque Lune Sanglante, les loups-garous ouvrent les yeux et commencent à chasser, pour se fondre parmi les gens bien d'ici le lendemain."
  },
  AvgDialog_126912_Content_82 = {
    Text = "Pour identifier les loups-garous cachés, la clé est d'inférer les motivations de chacun pendant la phase de discussion. Les loups-garous connaissent les identités des bons joueurs, donc leurs accusations sont souvent plus confiantes."
  },
  AvgDialog_126912_Content_83 = {
    Text = "La véritable Thaïs est la reine qui a été en dormance pendant mille ans à Aram. Sa véritable nature est complètement opposée à son apparence ; elle agit avec prudence et n'est certainement pas quelqu'un qui soupçonne facilement les autres."
  },
  AvgDialog_126912_Content_84 = {
    Text = "Alors vous avez voté pour moi, pas pour Miryam."
  },
  AvgDialog_126912_Content_85 = {
    Text = "J'ai choisi d'être dans la même pièce que le meurtrier."
  },
  AvgDialog_126912_Content_86 = {
    Text = "J'étais prêt à te prendre la main dans le sac quand tu as frappé, mais malheureusement, les actions de Miryam étaient plus rapides que les tiennes..."
  },
  AvgDialog_126912_Content_87 = {
    Text = "Avant que tu ne termines mon hypnose, elle avait déjà attaqué Wanda."
  },
  AvgDialog_126912_Content_88 = {
    Text = "Merveilleux, merveilleux raisonnement. Cela me fascine vraiment."
  },
  AvgDialog_126912_Content_89 = {
    Text = "Non, pas du tout... Après tout, je ne prévois pas de jouer le rôle d'un détective dans cette histoire selon l'arrangement de petit N."
  },
  AvgDialog_126912_Content_9 = {
    Text = "Wanda plissa les yeux et révéla un sourire rassurant."
  },
  AvgDialog_126912_Content_90 = {
    Text = "J'aurais préféré arrêter votre conspiration avant que l'incident ne se produise. Mais il est déjà trop tard."
  },
  AvgDialog_126912_Content_91 = {
    Text = "De nos jours, tout ce que je peux faire, c'est te demander... quelle est vraiment ta vraie forme ?"
  },
  AvgDialog_126912_Content_92 = {
    Text = "Une lumière argentée jaillit de la clé en argent sur ta poitrine, semblant transpercer toutes les illusions et déguisements."
  },
  AvgDialog_126912_Content_93 = {
    Text = "Hehe, hehehehe~"
  },
  AvgDialog_126912_Content_94 = {
    Text = "Votre attaque semble avoir frappé dans le vide."
  },
  AvgDialog_126912_Content_95 = {
    Text = "Elle se transforma en un fil de fumée, un fil de brume, une présence insaisissable et indescriptible."
  },
  AvgDialog_126912_Content_96 = {
    Text = "Viens, suis-moi."
  },
  AvgDialog_126912_Content_97 = {
    Text = "La brume rit doucement, te lançant une invitation ambiguë et inexplicable."
  },
  AvgDialog_126912_Content_98 = {
    Text = "Venez avec moi pour découvrir la vérité de l'histoire."
  },
  AvgDialog_128696_Content_1 = {
    Text = "BANG ! BANG ! BANG !"
  },
  AvgDialog_128696_Content_10 = {Text = "Nautila !"},
  AvgDialog_128696_Content_11 = {
    Text = "Mosk se précipita et se pencha sur la poitrine de Nautila, découvrant que Nautila était simplement trop fatigué et s'était endormi profondément."
  },
  AvgDialog_128696_Content_12 = {
    Text = "Mosk poussa un soupir de soulagement et éclata de rire."
  },
  AvgDialog_128696_Content_13 = {
    Text = "Pouf, hahahaha !"
  },
  AvgDialog_128696_Content_14 = {
    Text = "Elle prit Nautila et l'emporta au lit, ignorant tes résistances, elle roula avec toi sur le sol pendant plusieurs tours."
  },
  AvgDialog_128696_Content_15 = {
    Text = "Fuyons, nous n'avons pas besoin de nous séparer !"
  },
  AvgDialog_128696_Content_16 = {
    Text = "C'est la première fois que Mosk se sent aussi souple depuis ce jour-là, ses yeux brillent d'espoir, et elle a joyeusement frotté son nez contre le doux pelage de ta poitrine."
  },
  AvgDialog_128696_Content_17 = {
    Text = "Dormir... juste un peu... demain matin... demain matin..."
  },
  AvgDialog_128696_Content_18 = {
    Text = "Mosk, qui n'a pas fermé l'œil depuis plusieurs jours, te serre fermement dans ses bras, s'appuyant contre le coin du lit de Nautila, et s'est également endormie profondément."
  },
  AvgDialog_128696_Content_19 = {Text = "新增"},
  AvgDialog_128696_Content_2 = {
    Text = "Boom——Boom boom——Boom !"
  },
  AvgDialog_128696_Content_20 = {
    Text = "@2, Mosk, @4..."
  },
  AvgDialog_128696_Content_21 = {
    Text = "@4 proche..."
  },
  AvgDialog_128696_Content_22 = {Text = "新增"},
  AvgDialog_128696_Content_23 = {
    Text = "Le bateau n'a navigué que pendant une demi-journée, lorsqu'une immense tempête est survenue sans avertissement."
  },
  AvgDialog_128696_Content_24 = {
    Text = "La direction est complètement perdue, la pluie tombe en rideaux, ne laissant aucune chance de se rétracter aux challengers présomptueux."
  },
  AvgDialog_128696_Content_25 = {
    Text = "Le gouvernail dévie de manière étrange, et peu importe combien le Nautila et le Mosk essaient de trouver une solution, même en risquant de l'endommager, il n'y a aucune tendance à revenir sur la bonne voie."
  },
  AvgDialog_128696_Content_26 = {
    Text = "Comment est-ce possible, ça ne devrait pas se passer ainsi ! Aucun signe avant-coureur, la pression atmosphérique était tout à fait normale... il n'y avait aucun problème jusqu'à ce qu'on s'approche de ces eaux."
  },
  AvgDialog_128696_Content_27 = {
    Text = "C'est tout simplement... comme si ce vortex avait généré un vent pour nous tendre un piège."
  },
  AvgDialog_128696_Content_28 = {
    Text = "Un piège ?"
  },
  AvgDialog_128696_Content_29 = {
    Text = "C'est précisément au moment où nous étions le plus près du vortex, qu'il suffisait de cinq, non, même trois milles marins de plus, pour nous éloigner de l'influence du vortex."
  },
  AvgDialog_128696_Content_3 = {
    Text = "La bête d'acier, endormie depuis longtemps, émet un rugissement rauque, la sirène retentit, et au son des battements d'ailes des mouettes, tout le navire semble lentement reprendre vie."
  },
  AvgDialog_128696_Content_30 = {
    Text = "Ton esprit est déjà en chaos, tu essaies désespérément de produire un son, mais quel son…"
  },
  AvgDialog_128696_Content_31 = {
    Text = "Ah, ah——!"
  },
  AvgDialog_128696_Content_32 = {
    Text = "Tu ne peux que pousser des cris de confusion, tu ne comprends pas, elles ne peuvent pas ressentir cela ?"
  },
  AvgDialog_128696_Content_33 = {
    Text = "(Ne t'approche pas du vortex, grand, ne t'approche pas du vortex !)"
  },
  AvgDialog_128696_Content_34 = {
    Text = "Cette énorme et terrifiante présence a vu Mosk."
  },
  AvgDialog_128696_Content_35 = {
    Text = "<Red:Il n'a pas l'intention de laisser partir qui que ce soit.>"
  },
  AvgDialog_128696_Content_36 = {Text = "新增"},
  AvgDialog_128696_Content_37 = {
    Text = "Pas de souci, petit charbon, Mosk, ici."
  },
  AvgDialog_128696_Content_38 = {
    Text = "Oui, fais-moi confiance, petit charbon, Mosk. Il y a une solution, je suis sûr que je vais trouver une solution !"
  },
  AvgDialog_128696_Content_39 = {Text = "Nautila…"},
  AvgDialog_128696_Content_4 = {
    Text = "Moteur. Dernière étape..."
  },
  AvgDialog_128696_Content_40 = {
    Text = "C'est moi qui dois faire partir le navire, c'est moi qui vous ai amenés ici, je trouverai un moyen, je vous ramènerai en sécurité !"
  },
  AvgDialog_128696_Content_41 = {
    Text = "<change:Creusez la coque à cet endroit pour ajouter du poids avec l'eau...>"
  },
  AvgDialog_128696_Content_42 = {
    Text = "<Change>Non... @2la propulsion, oui, si, Tant Que l'on surcharge l'un des moteurs, échapper à la force d'attraction de @1"
  },
  AvgDialog_128696_Content_43 = {
    Text = "La jeune fille te conduit, ainsi que Mosk, à travers les différentes cabines, essayant sans cesse diverses méthodes, tandis qu'une écarlate de folie envahit progressivement son regard."
  },
  AvgDialog_128696_Content_44 = {
    Text = "Ting——Bam !"
  },
  AvgDialog_128696_Content_45 = {
    Text = "Nautila……"
  },
  AvgDialog_128696_Content_46 = {
    Text = "Accompagnée d'une faiblesse, la clé à molette heurta le mur, puis s'écrasa violemment sur le pied de Nautila, mais elle semblait totalement insensible à la douleur, murmurant qu'elle voulait continuer à ramasser la clé à molette."
  },
  AvgDialog_128696_Content_47 = {
    Text = "<change>Trop tard, le vortex se rapproche de plus en plus... Pourquoi, pourquoi, pourquoi, POURQUOI !! Je dois vous sauver tous les deux, je le ferai... je le ferai... !"
  },
  AvgDialog_128696_Content_48 = {
    Text = "Crac——Boum—— !"
  },
  AvgDialog_128696_Content_49 = {
    Text = "La tempête et l'attaque ont finalement dépassé les limites de la cabine, et après un bruit sec de rupture, des planches usées sont tombées à grande vitesse du dessus de Nautila——"
  },
  AvgDialog_128696_Content_5 = {
    Text = "Super ! Mosk, petit charbon, nous avons réussi !"
  },
  AvgDialog_128696_Content_50 = {
    Text = "<Big:Nautila ! Arrête !>"
  },
  AvgDialog_128696_Content_51 = {
    Text = "Ouvrant les yeux fermés par la peur, Nautila se retrouve face à une scène inattendue."
  },
  AvgDialog_128696_Content_52 = {
    Text = "Mosk s'appuya d'une main contre le mur pour se protéger en dessous, tandis que l'autre main soutenait tout le plafond."
  },
  AvgDialog_128696_Content_53 = {Text = "Ugh..."},
  AvgDialog_128696_Content_54 = {Text = "Ha !"},
  AvgDialog_128696_Content_55 = {
    Text = "Mosk poussa violemment le plafond ailleurs, puis saisit Nautila, qui frôlait la folie, et lui prit le visage entre ses mains, fixant son regard sur elle."
  },
  AvgDialog_128696_Content_56 = {
    Text = "Tout va bien, retourne, la prochaine fois."
  },
  AvgDialog_128696_Content_57 = {
    Text = "Retourner… mais…"
  },
  AvgDialog_128696_Content_58 = {
    Text = "Nautila regarda autour d'elle, perdue, laissant la pluie torrentielle s'abattre sur elle."
  },
  AvgDialog_128696_Content_59 = {
    Text = "La tempête fait rage avec tonnerre et éclairs, stimulant chaque nerf, comme la musique ininterrompue d'un festin démoniaque."
  },
  AvgDialog_128696_Content_6 = {
    Text = "Après cela, Nautila a commencé à réparer la coque sans relâche. Il reste trois jours avant l'arrivée prévue de la tempête, et toutes les pièces clés sont revenues à leur place."
  },
  AvgDialog_128696_Content_60 = {
    Text = "La gravité du vortex est trop forte, nous ne pouvons plus faire demi-tour..."
  },
  AvgDialog_128696_Content_61 = {
    Text = "Mosk ignora les paroles de Nautila et traîna la combinaison de plongée hors de la cale, essayant de l'enfiler sur Nautila de manière désordonnée et maladroite."
  },
  AvgDialog_128696_Content_62 = {
    Text = "Une combinaison de plongée ? Non, si je la mets, que vas-tu faire ?"
  },
  AvgDialog_128696_Content_63 = {
    Text = "À ce moment-là, la coque du bateau a commencé à s'incliner complètement et de manière incontrôlable vers le vortex."
  },
  AvgDialog_128696_Content_64 = {
    Text = "<Shake:Craquement — Cui cui —>"
  },
  AvgDialog_128696_Content_7 = {
    Text = "Tant Que je remets l'ancre... souf... tellement sommeil..."
  },
  AvgDialog_128696_Content_8 = {Text = "Plouf."},
  AvgDialog_128696_Content_9 = {
    Text = "Cui ?! Cui—— ? (Humain ?! Humain—— ?)"
  },
  AvgDialog_128697_Content_1 = {
    Text = "Bien. Mieux. Le mieux du mieux !"
  },
  AvgDialog_128697_Content_10 = {Text = "新增"},
  AvgDialog_128697_Content_11 = {
    Text = "*acclamation"
  },
  AvgDialog_128697_Content_12 = {
    Text = "Bien que la puissance de destruction soit effectivement un peu forte."
  },
  AvgDialog_128697_Content_13 = {
    Text = "Gardien ! Mosk ! Vaincre les devoirs maléfiques ! Génial !"
  },
  AvgDialog_128697_Content_14 = {
    Text = "Hein... Gardien... petit charbon ?!"
  },
  AvgDialog_128697_Content_15 = {
    Text = "L'instinct bestial de Mosk a immédiatement perçu quelque chose de différent, elle a bondi comme un animal et s'est jetée sur toi pour te prendre dans ses bras."
  },
  AvgDialog_128697_Content_16 = {
    Text = "Aïe ! Mosk, ça fait mal !"
  },
  AvgDialog_128697_Content_17 = {
    Text = "Elle te frappa également le pauvre nez avec sa bouche."
  },
  AvgDialog_128697_Content_18 = {
    Text = "cage buccal, dispositif de contrainte, acier Mosk, bien ! Hihi, Mosk, en sécurité."
  },
  AvgDialog_128697_Content_19 = {
    Text = "Le dispositif spécialement conçu par Mizag contrôle bien l'excès de force, et la puissance de destruction maximale de Mosk équivaut maintenant seulement à celle d'un humain un peu plus fort."
  },
  AvgDialog_128697_Content_2 = {
    Text = "Bonjour, Gardien. Concernant l'Éveilleur O-1841, étant donné qu'il vient de se réveiller, il présente occasionnellement des signes de Fureur et ne peut pas contrôler complètement ses capacités. Il est conseillé de rester en état de prudence lors des contacts avec lui."
  },
  AvgDialog_128697_Content_20 = {
    Text = "Amis, plus tard, une aventure parfaitement parfaite, il y en a ? Non ?"
  },
  AvgDialog_128697_Content_21 = {
    Text = "Tu as dû déployer beaucoup d'efforts pour décoller le grand chien fou de toi. Elle semble enfin prête à se calmer un moment, assise en face de toi à la table, les yeux brillant fixés sur toi."
  },
  AvgDialog_128697_Content_22 = {Text = "Hmm..."},
  AvgDialog_128697_Content_23 = {Text = "En fait..."},
  AvgDialog_128697_Content_24 = {
    Text = "Il existe une immense Fissure de fusion sous le Moskstraumen M - Mosk ; Nautila et moi avons bien échappé à l'influence du Moskstraumen, mais nous présentons tous deux des signes d'amnésie."
  },
  AvgDialog_128697_Content_25 = {
    Text = "Tu fais juste une brève pause, puis choisis d'utiliser « Je » comme un substitut pour cette conscience dans le Rêve."
  },
  AvgDialog_128697_Content_26 = {
    Text = "Nautila a toujours voulu te retrouver après cela. Elle a fondé une équipe d'aventure, mais a rencontré un autre désastre lors de son voyage de retour..."
  },
  AvgDialog_128697_Content_27 = {
    Text = "Elle ne s'en souvient probablement plus, mais... elle a fait le même choix que toi."
  },
  AvgDialog_128697_Content_28 = {
    Text = "C'est ainsi..."
  },
  AvgDialog_128697_Content_29 = {
    Text = "Mais, c'est super."
  },
  AvgDialog_128697_Content_3 = {
    Text = "Merci, Erica. Mais ça va, je pense que je connais assez bien mon... ami."
  },
  AvgDialog_128697_Content_30 = {Text = "Bien sûr"},
  AvgDialog_128697_Content_31 = {
    Text = "Bien sûr qu'il y en a ! Plus tard, moi et Nautila..."
  },
  AvgDialog_128697_Content_32 = {
    Text = "En attendant, jusqu'à ce que Nautila et moi soyons trop vieux pour bouger, nous avons vécu toutes sortes d'aventures."
  },
  AvgDialog_128697_Content_33 = {
    Text = "Tu as épuisé toutes tes idées et intégré dans ton récit à Mosk toutes les histoires d'aventure que tu as entendues durant ta courte année de vie consciente."
  },
  AvgDialog_128697_Content_34 = {
    Text = "Après tout, mon Dieu, tu ne peux vraiment pas dire quoi que ce soit de cruel en regardant ces yeux."
  },
  AvgDialog_128697_Content_35 = {
    Text = "L'histoire deLu@2, Mosk, je l'ai entendue."
  },
  AvgDialog_128697_Content_36 = {
    Text = "<Gray:Oh non, j'ai oublié que c'était la lecture du cours général...>"
  },
  AvgDialog_128697_Content_37 = {
    Text = "Ce n'est rien."
  },
  AvgDialog_128697_Content_38 = {Text = "Eh ?"},
  AvgDialog_128697_Content_39 = {
    Text = "Mosk baissa la tête, comme quand tu étais encore petit charbon, posant son visage dans la paume de ta main."
  },
  AvgDialog_128697_Content_4 = {
    Text = "Contrairement à ce que l'académie avait prévu, ton premier lien avec cet Éveilleur aux capacités de fureur s'est déroulé de manière exceptionnellement fluide."
  },
  AvgDialog_128697_Content_40 = {
    Text = "Ami, petit charbon, nous nous revoyons."
  },
  AvgDialog_128697_Content_41 = {
    Text = "petit charbon, expérience dans l'obscurité, note Mosk, bien."
  },
  AvgDialog_128697_Content_42 = {
    Text = "Elle a ouvert la bouche et t'a offert un sourire extrêmement heureux."
  },
  AvgDialog_128697_Content_43 = {
    Text = "Bien que, le bracelet, soit perdu."
  },
  AvgDialog_128697_Content_44 = {
    Text = "Mais, nous nous retrouvons, mieux, mieux que mieux !"
  },
  AvgDialog_128697_Content_45 = {Text = "Mosk…"},
  AvgDialog_128697_Content_46 = {Text = "Cric ?"},
  AvgDialog_128697_Content_47 = {
    Text = "??Pourquoi y a-t-il une loutre portant un chapeau de Mizag ici ?"
  },
  AvgDialog_128697_Content_48 = {
    Text = "Désolé, Gardien, il semble que de nombreux étudiants aiment beaucoup ce loutre de mer exotique et lui ont fait quelques décorations inutiles."
  },
  AvgDialog_128697_Content_49 = {
    Text = "Erica lancera le programme d'expulsion dès que possible, 1, 2——"
  },
  AvgDialog_128697_Content_5 = {
    Text = "Après cet accident dans le Rêve, tu penses que tu as trouvé la réponse."
  },
  AvgDialog_128697_Content_50 = {
    Text = "Ah, loutre de mer ! Mignonne, joue avec Mosk !"
  },
  AvgDialog_128697_Content_51 = {
    Text = "Bang. Boum. Clang—"
  },
  AvgDialog_128697_Content_52 = {Text = "Bang !"},
  AvgDialog_128697_Content_53 = {
    Text = "Sss, Mosk !"
  },
  AvgDialog_128697_Content_54 = {
    Text = "Nautila venait d'entrer dans la salle de classe lorsqu'elle a vu son nouvel ami, poursuivant un loutre portant un chapeau de Mizag, qui se déchaînait et détruisait les équipements pédagogiques."
  },
  AvgDialog_128697_Content_55 = {
    Text = "Gardien, dis à l'enseignante Erica que je vais réparer tout ce qui est dans la salle de classe !"
  },
  AvgDialog_128697_Content_56 = {
    Text = "Mosk, arrête vite !"
  },
  AvgDialog_128697_Content_57 = {
    Text = "Ah——ah !"
  },
  AvgDialog_128697_Content_58 = {Text = "Aïe !!"},
  AvgDialog_128697_Content_59 = {
    Text = "*Acclamations"
  },
  AvgDialog_128697_Content_6 = {
    Text = "Elle aime la viande grillée, elle aime la mer, elle est très timide, déteste le froid, l'obscurité et la solitude, et elle pleure en silence quand elle est confrontée à eux."
  },
  AvgDialog_128697_Content_60 = {
    Text = "Si je ne me trompe pas, ce loutre de mer dit « joue avec moi », n'est-ce pas... Comment communiquent-ils avec Mosk ?"
  },
  AvgDialog_128697_Content_61 = {
    Text = "Eh, ce n'est pas vrai, pourquoi est-ce que je peux aussi comprendre ce que dit le loutre de mer ?!"
  },
  AvgDialog_128697_Content_62 = {
    Text = "Attends, si c'est le cas…"
  },
  AvgDialog_128697_Content_63 = {
    Text = "Ahem, mystérieux loutre de Mizag, maintenant je te confie le titre de petit charbon."
  },
  AvgDialog_128697_Content_64 = {
    Text = "Tu hériteras du nom de petit charbon et deviendras le grand et glorieux petit charbon II !"
  },
  AvgDialog_128697_Content_65 = {Text = "!"},
  AvgDialog_128697_Content_66 = {
    Text = "petit charbon, deuxième génération ! petit charbon, deuxième génération !"
  },
  AvgDialog_128697_Content_67 = {
    Text = "Tic—— (Impact de l'otarie de mer !)"
  },
  AvgDialog_128697_Content_68 = {
    Text = "Nautila——"
  },
  AvgDialog_128697_Content_69 = {
    Text = "C'est super, c'est devenu un vrai fouillis——"
  },
  AvgDialog_128697_Content_7 = {
    Text = "L'après-midi, le soleil de Mizag est magnifique, le soleil passe à travers le vitrail, projetant la lumière sur le visage de la jeune fille qui se bat avec son livre de cours de langue."
  },
  AvgDialog_128697_Content_70 = {
    Text = "Alors, en tant que mon héritier légitime, <Small:tu as le devoir solennel de gérer ce qui déplaît à moi, petit charbon de première génération...>"
  },
  AvgDialog_128697_Content_71 = {
    Text = "Tu as sifflé d'un air détendu, doucement, doucement——"
  },
  AvgDialog_128697_Content_72 = {
    Text = "J'ai profité du désordre pour lancer mon devoir de calcul intégral sur les griffes de l'otarie."
  },
  AvgDialog_128697_Content_73 = {
    Text = "En un clin d'œil, les devoirs sont devenus des papiers froissés, reposant tranquillement dans la pile de déchets."
  },
  AvgDialog_128697_Content_74 = {
    Text = "Quelle belle journée, n'est-ce pas, Nautila, Mosk ?"
  },
  AvgDialog_128697_Content_75 = {Text = "Ah—!"},
  AvgDialog_128697_Content_76 = {
    Text = "Aujourd'hui, Mizag est également très amical et pacifique."
  },
  AvgDialog_128697_Content_77 = {
    Text = "Félicitations, félicitations."
  },
  AvgDialog_128697_Content_8 = {
    Text = "Mais elle est aussi très courageuse, prête à se mettre devant toutes les choses qu'elle déteste pour ses amis."
  },
  AvgDialog_128697_Content_9 = {
    Text = "Sss— Le manuel s'est déchiré en deux dans l'atmosphère récemment émotive."
  },
  AvgDialog_128698_Content_1 = {
    Text = "Plouf～Plouf～"
  },
  AvgDialog_128698_Content_10 = {
    Text = "La propulsion et le carburant ne posent pas de problème, mais la coque est vraiment trop fragile... Mosk, y a-t-il un moyen de contourner ce grand Moskstraumen ? C'est près de lui que la flotte précédente a eu des ennuis."
  },
  AvgDialog_128698_Content_11 = {
    Text = "……Impossible de sortir."
  },
  AvgDialog_128698_Content_12 = {
    Text = "Mosk secoue la tête, te prend à nouveau dans ses bras, et ensemble, avec quatre mains et quatre pieds, ils s'efforcent de gesticuler."
  },
  AvgDialog_128698_Content_13 = {
    Text = "Méchants, attrapé Maman et Papa. Mosk, mordu, emmenée. Petit charbon, sur bateau, rencontré."
  },
  AvgDialog_128698_Content_14 = {
    Text = "La mer, appel—— ici, Mosk, trouve une solution, ça ne va pas."
  },
  AvgDialog_128698_Content_15 = {
    Text = "Tu as été emmené ici par des méchants, et après avoir été séparé de papa et maman, tu n'as plus pu sortir ?"
  },
  AvgDialog_128698_Content_16 = {
    Text = "Absent, papa et maman."
  },
  AvgDialog_128698_Content_17 = {
    Text = "Désolé..."
  },
  AvgDialog_128698_Content_18 = {
    Text = "À propos, papa et maman, comme, viens !"
  },
  AvgDialog_128698_Content_19 = {
    Text = "Mosk ! Où m'emmènes-tu ?!"
  },
  AvgDialog_128698_Content_2 = {
    Text = "Tant que le roulement de cette partie est complètement réparé, le gouvernail..."
  },
  AvgDialog_128698_Content_20 = {Text = "新增"},
  AvgDialog_128698_Content_21 = {
    Text = "Ouf... Ouf, tu es un monstre ?! Pourquoi tu nages si vite en me portant ?!"
  },
  AvgDialog_128698_Content_22 = {
    Text = "Eh, quel est cet endroit ici ?"
  },
  AvgDialog_128698_Content_23 = {Text = "Ah—!"},
  AvgDialog_128698_Content_24 = {
    Text = "Tu as joyeusement sauté dans l'eau en premier, faisant sursauter tous les poissons autour."
  },
  AvgDialog_128698_Content_25 = {
    Text = "Avec les cris de joie de toi et de Mosk qui avez plongé l'un après l'autre, des ondulations montent des profondeurs, comme pour répondre à vos appels."
  },
  AvgDialog_128698_Content_26 = {
    Text = "Maman, papa, comme eux ! Nautila, Mosk, pareil !"
  },
  AvgDialog_128698_Content_27 = {
    Text = "Plusieurs magnifiques dauphins blancs émergent du fond de l'eau et se rassemblent autour de vous, frottant affectueusement leurs nez et leurs nageoires contre toi et Mosk."
  },
  AvgDialog_128698_Content_28 = {
    Text = "Elles nagent autour de vous avec légèreté, jaillissant même hors de l'eau pour projeter quelques jets vers Nautila, comme si elles l'invitaient."
  },
  AvgDialog_128698_Content_29 = {
    Text = "Ce sont... des dauphins ? Mosk, tu dis que tes parents sont aussi des dauphins ?"
  },
  AvgDialog_128698_Content_3 = {
    Text = "Usurpation de navire ?"
  },
  AvgDialog_128698_Content_30 = {
    Text = "Oui. Petit Mosk, perdu. Dauphins, nourrir petit Mosk. Mosk, grandir !"
  },
  AvgDialog_128698_Content_31 = {
    Text = "Mosk, Hé, petit charbon, petit charbon, grandis !"
  },
  AvgDialog_128698_Content_32 = {
    Text = "Mosk rit aux éclats, évitant les éclaboussures d'eau que tu lui as jetées par colère, puis vous tendez tous deux la main vers Nautila."
  },
  AvgDialog_128698_Content_33 = {
    Text = "Crois en moi, mon ami."
  },
  AvgDialog_128698_Content_34 = {
    Text = "...D'accord !"
  },
  AvgDialog_128698_Content_35 = {
    Text = "Nautila vous serre fermement les mains. L'un devant, l'autre derrière, vous et Mosk guidez Nautila vers une grotte cachée."
  },
  AvgDialog_128698_Content_36 = {
    Text = "Après un bref instant de ténèbres, une touffe, deux touffes... d'innombrables lueurs vaporeuses et féeriques s'éveillèrent, les méduses se précipitèrent vers la surface, puis furent doucement repoussées par le vortex, jusqu'à ce qu'une lumière plus vive se déverse depuis la voûte céleste."
  },
  AvgDialog_128698_Content_37 = {
    Text = "... Je... ne suis pas en train de Rêver, si ?"
  },
  AvgDialog_128698_Content_38 = {
    Text = "La lumière du soleil pénètre à travers les couches rocheuses, révélant des nuances de bleu sur la surface de la mer sans fond. Les coraux multicolores tranchent à nouveau avec le bleu, créant une image si saisissante aux côtés de nombreuses créatures marines qu'elle laisse sans voix."
  },
  AvgDialog_128698_Content_39 = {
    Text = "Les anémones de mer traînent leurs tentacules venimeux dans une danse lente et hypnotique. Les coquillages s'accrochent tout près, vivant en harmonie silencieuse avec elles. Les prédateurs rôdent dans l'obscurité des abysses, attendant leur heure. Cet endroit est dangereux et magnifique, sombre et éblouissant — un monde en soi, un océan en miniature."
  },
  AvgDialog_128698_Content_4 = {
    Text = "Le gouvernail est comme un volant, c'est un dispositif qui contrôle la direction. Sais-tu ce qu'est un volant ?"
  },
  AvgDialog_128698_Content_40 = {Text = "Nautila ?"},
  AvgDialog_128698_Content_41 = {
    Text = "Cela, c'est beau, je te le donne."
  },
  AvgDialog_128698_Content_42 = {
    Text = "Mosk a sorti à un moment donné une perle émettant une lueur irisée, et avec une expression très, très sérieuse, elle l'a mise dans la paume de Nautila."
  },
  AvgDialog_128698_Content_43 = {
    Text = "Mosk, ici, aime. Mosk, trésor, aime. Nautila, ami, pour toi."
  },
  AvgDialog_128698_Content_44 = {
    Text = "(Je t'ai demandé tant de fois sans que tu me donnes, grand, méchant !)"
  },
  AvgDialog_128698_Content_45 = {
    Text = "Bien que tu te murmures cela dans ton cœur, en pensant aux délicieux poissons grillés et aux fruits de mer que tu as mangés récemment, tu fais preuve de générosité et pousses les perles dans la main de Nautila avec Mosk."
  },
  AvgDialog_128698_Content_46 = {
    Text = "Oh — merci ! Eh bien, j'ai aussi un cadeau pour Mosk."
  },
  AvgDialog_128698_Content_47 = {Text = "Li ? ?"},
  AvgDialog_128698_Content_48 = {
    Text = "Nautila détache le petit bracelet de son poignet — celui qu'elle porte toujours, orné d'un petit pendentif en forme de nautile."
  },
  AvgDialog_128698_Content_49 = {
    Text = "Ce qu'un ami donne à un ami s'appelle un «cadeau». La perle est ton cadeau pour moi. Et ceci... ceci est mon cadeau pour toi."
  },
  AvgDialog_128698_Content_5 = {Text = "Mmm... ?"},
  AvgDialog_128698_Content_50 = {
    Text = "Ma mère m'a donné un collier et un bracelet, et j'ai convenu avec elle de devenir un grand aventurier."
  },
  AvgDialog_128698_Content_51 = {
    Text = "Mosk, je vais bientôt réparer le bateau. Nous partirons ensemble et irons retrouver tes parents."
  },
  AvgDialog_128698_Content_52 = {
    Text = "Et après ça... est-ce que tu accepterais de porter ce bracelet, d'emmener petit charbon, et de partir à l'aventure avec moi ?"
  },
  AvgDialog_128698_Content_53 = {Text = "新增"},
  AvgDialog_128698_Content_54 = {
    Text = "Nautila, Mosk, petit charbon, aventure !"
  },
  AvgDialog_128698_Content_55 = {Text = "Ahou !"},
  AvgDialog_128698_Content_56 = {
    Text = "Après un bref silence, presque illusoire, Mosk a de nouveau levé son sourire éclatant et t'a pris dans ses bras en poussant un cri de joie."
  },
  AvgDialog_128698_Content_57 = {
    Text = "Cui ! (Aventure !)"
  },
  AvgDialog_128698_Content_58 = {
    Text = "Que peux-tu percevoir ? Tu n'es qu'une loutre de mer, même si tu sens quelque chose avec acuité, ton petit cerveau ne te permet pas d'en faire plus, tu te laisses rapidement emporter par l'ambiance joyeuse."
  },
  AvgDialog_128698_Content_59 = {
    Text = "Super, petit charbon, j'ai aussi préparé un cadeau pour toi !"
  },
  AvgDialog_128698_Content_6 = {
    Text = "Le volant est l'élément qui contrôle la direction de tous ces gros engins. Où que le volant indique le chemin, le bateau et la voiture iront dans cette direction."
  },
  AvgDialog_128698_Content_60 = {Text = "新增"},
  AvgDialog_128698_Content_61 = {Text = "!"},
  AvgDialog_128698_Content_62 = {
    Text = "Le compartiment du navire, autrefois en ruine, a désormais complètement changé. Entre deux lits identiques, simples mais propres et solides, se trouve une caisse en bois remplie de coussins moelleux."
  },
  AvgDialog_128698_Content_63 = {
    Text = "Hé hé, maintenant tout le monde a un lit."
  },
  AvgDialog_128698_Content_64 = {
    Text = "À peine Nautila a-t-elle terminé sa phrase que tu as plongé tête la première dans ton parfait petit nid — Nautila t'a même laissé une place spéciale pour tes précieuses petites coquilles !"
  },
  AvgDialog_128698_Content_65 = {
    Text = "La soupe de fruits de mer du dîner est encore chaude dans ton ventre, et au rythme des respirations paisibles des jeunes filles, tu t'endors rapidement."
  },
  AvgDialog_128698_Content_66 = {
    Text = "Mais quand la nuit est réellement arrivée, ce fil de malheur s'est répandu comme le brouillard épais de la mer."
  },
  AvgDialog_128698_Content_67 = {
    Text = "<Shake:Mosk, @3...>"
  },
  AvgDialog_128698_Content_68 = {
    Text = "<Shake:Retourne à moi, soumets-toi à moi, @4...@4 !>"
  },
  AvgDialog_128698_Content_69 = {
    Text = "La mer, dans l'obscurité, devient terrifiante et mystérieuse. La lumière du soleil ne brille plus à la surface de l'eau, et dans les profondeurs de l'abîme, une certaine existence remue avec un murmure sourd et guttural."
  },
  AvgDialog_128698_Content_7 = {
    Text = "Ohhhhh ! Un volant ! C'est trop cool !"
  },
  AvgDialog_128698_Content_70 = {
    Text = "Tu te débats dans un vide infini et glacé, essayant désespérément de te rapprocher de cette silhouette qui pleure doucement au loin."
  },
  AvgDialog_128698_Content_71 = {
    Text = "Ah—(grand—)"
  },
  AvgDialog_128698_Content_72 = {
    Text = "Ah ! (Grand !)"
  },
  AvgDialog_128698_Content_73 = {
    Text = "Tu te réveilles brusquement, sans le souffle apaisé des filles endormies, tout est silencieux. Tu sors de ton nid et te diriges vers le pont en suivant l'odeur de Mosk."
  },
  AvgDialog_128698_Content_74 = {
    Text = "Elle regarde le vortex au loin."
  },
  AvgDialog_128698_Content_75 = {
    Text = "(Ah, encore ce rêve, depuis que ces humains détestables sont morts, combien de fois cela s'est-il déjà produit depuis que nous avons établi notre foyer ici ?)"
  },
  AvgDialog_128698_Content_76 = {
    Text = "Appel, Mosk, là-bas."
  },
  AvgDialog_128698_Content_77 = {
    Text = "Effrayant... non..."
  },
  AvgDialog_128698_Content_78 = {
    Text = "Eh, petit charbon, Mosk, que faites-vous dehors ?"
  },
  AvgDialog_128698_Content_79 = {
    Text = "La voix de Nautila interrompit le murmure rêveur de Mosk, et la seconde d'après, Nautila poussa avec excitation une série de plaques de fer pour vous les montrer."
  },
  AvgDialog_128698_Content_8 = {Text = "新增"},
  AvgDialog_128698_Content_80 = {
    Text = "Mosk, tu n'as pas dit auparavant que plonger trop profondément serait inconfortable, mais que tu voulais quand même aller voir ?"
  },
  AvgDialog_128698_Content_81 = {
    Text = "J'ai réparé la combinaison de plongée que j'ai trouvée sur le bateau, tant que tu as ça, tu pourras plonger plus longtemps sans te sentir mal."
  },
  AvgDialog_128698_Content_82 = {
    Text = "Dommage que je doive réparer le navire avant la prochaine tempête. Après la tempête, je m'en fabriquerai une aussi."
  },
  AvgDialog_128698_Content_83 = {
    Text = "Un jour, nous pourrons explorer la mer ensemble !"
  },
  AvgDialog_128698_Content_84 = {
    Text = "Mosk se calma exceptionnellement, puis après un moment, elle hocha vigoureusement la tête, te prit dans ses bras et fit un énorme câlin à Nautila."
  },
  AvgDialog_128698_Content_85 = {Text = "Fuir."},
  AvgDialog_128698_Content_86 = {
    Text = "Mosk, Nautila, petit charbon, Fuir ! Ensemble !"
  },
  AvgDialog_128698_Content_9 = {
    Text = "D'après les données des instruments, il y a au maximum une semaine avant qu'une tempête n'arrive— une qui durera au moins quinze jours. Ce navire est déjà en mauvais état... Je ne sais même pas s'il tiendra le coup après la tempête."
  },
  AvgDialog_128699_Content_1 = {
    Text = "Plic, ploc."
  },
  AvgDialog_128699_Content_10 = {
    Text = "Mosk, écoute-moi, c'est moi qui ai proposé de prendre la mer, et c'est moi qui n'ai pas bien évalué la météo, donc j'ai l'obligation de te sauver, toi et petit charbon."
  },
  AvgDialog_128699_Content_11 = {
    Text = "Je vais immédiatement enlever la combinaison de plongée pour toi. Maintenant, le bateau peut encore bouger, je vais faire de mon mieux pour le contrôler et le diriger vers le bord du Vortex, à ce moment-là, tu..."
  },
  AvgDialog_128699_Content_12 = {Text = "Vous..."},
  AvgDialog_128699_Content_13 = {
    Text = "Nautila resta figée sur place, elle vit la jeune fille qui était auparavant naïve, vive et insouciante, afficher une rare expression de préoccupation complexe."
  },
  AvgDialog_128699_Content_14 = {
    Text = "Nautila, désolé."
  },
  AvgDialog_128699_Content_15 = {
    Text = "Mosk tendit la main. Bien qu›elle ne comprenne pas comment l›appareil fonctionne, poussée par un instinct bestial, elle finit de force d›habiller Nautila avec la combinaison de plongée."
  },
  AvgDialog_128699_Content_16 = {
    Text = "Mosk, danger, pressentiment."
  },
  AvgDialog_128699_Content_17 = {
    Text = "Mais, espérer, cela ne se produira pas."
  },
  AvgDialog_128699_Content_18 = {
    Text = "L'eau de pluie s'infiltre par le trou du toit et frappe les deux personnes."
  },
  AvgDialog_128699_Content_19 = {
    Text = "Le silence se répand dans la pièce, et finalement, c'est Mosk qui brisa ce poids."
  },
  AvgDialog_128699_Content_2 = {
    Text = "<Shake:Craquement — Cui cui —>"
  },
  AvgDialog_128699_Content_20 = {
    Text = "Mosk, venir ici, rêve."
  },
  AvgDialog_128699_Content_21 = {
    Text = "Mosk rêve de… quelque chose, qui s'appelle Mosk…"
  },
  AvgDialog_128699_Content_22 = {
    Text = "Mais, ne pas vouloir y aller. Froid, personne autour, solitude..."
  },
  AvgDialog_128699_Content_23 = {
    Text = "Nautila réalisa soudain pourquoi la pluie torrentielle était tombée en avance, pourquoi la tornade était apparue sans prévenir. Elle se mit à trembler de manière incontrôlable."
  },
  AvgDialog_128699_Content_24 = {
    Text = "Cette chose... juste là..."
  },
  AvgDialog_128699_Content_25 = {
    Text = "Suivant le doigt de Mosk, Nautila ressentit une peur qui se propageait dans son subconscient."
  },
  AvgDialog_128699_Content_26 = {
    Text = "La peur venant du fond du vortex de Merscus, transcendant les choses mortelles."
  },
  AvgDialog_128699_Content_27 = {Text = "新增"},
  AvgDialog_128699_Content_28 = {
    Text = "Non, non, non — je sais ce que tu vas faire, pas question !"
  },
  AvgDialog_128699_Content_29 = {
    Text = "Fais-moi confiance, il y a sûrement un autre moyen !"
  },
  AvgDialog_128699_Content_3 = {
    Text = "Un tourbillon furieux est comme une énorme main, prête à tordre le bateau comme une serviette."
  },
  AvgDialog_128699_Content_30 = {
    Text = "Nautila appuyait anxieusement sur Mosk. Bien que, compte tenu de sa force, Mosk puisse se libérer à tout moment, la jeune fille semblable à une bête ne le fit pas."
  },
  AvgDialog_128699_Content_31 = {
    Text = "Elle te soulève simplement et se frotte affectueusement contre toi."
  },
  AvgDialog_128699_Content_32 = {
    Text = "Ami, fort, mais, non. Seulement, Mosk, peut."
  },
  AvgDialog_128699_Content_33 = {
    Text = "Seulement, Mosk, peut."
  },
  AvgDialog_128699_Content_34 = {
    Text = "…Pourquoi, pourquoi est-ce ainsi."
  },
  AvgDialog_128699_Content_35 = {
    Text = "Ami, ne pleure pas, souris, Mosk, j'aime ça !"
  },
  AvgDialog_128699_Content_36 = {
    Text = "Euh, désolé, j'ai vu que vous mangiez tous du poisson cru, alors je l'ai un peu préparé... Même sans assaisonnement, vous voulez Goûter ?"
  },
  AvgDialog_128699_Content_37 = {Text = "Awoo !"},
  AvgDialog_128699_Content_38 = {Text = "Awoo !"},
  AvgDialog_128699_Content_39 = {Text = "Délicieux"},
  AvgDialog_128699_Content_4 = {
    Text = "La coque émettait des bruits de torsion insupportables, Mosk hurlait presque dans la tempête, tandis qu'elle s'efforçait de fourrer Nautila dans sa combinaison de plongée, tout en te serrant contre elle pour t'empêcher d'être projeté."
  },
  AvgDialog_128699_Content_40 = {
    Text = "Aventure, j'attends avec impatience !"
  },
  AvgDialog_128699_Content_41 = {
    Text = "Mosk, je vais réparer le navire bientôt et vous emmener d'ici pour retrouver votre maman et votre papa."
  },
  AvgDialog_128699_Content_42 = {
    Text = "Après cela, aimeriez-vous prendre ce bracelet, prendre Coalsie et partir à l'aventure avec moi ?"
  },
  AvgDialog_128699_Content_43 = {
    Text = "Nautila, Mosk, petit charbon, aventure !"
  },
  AvgDialog_128699_Content_44 = {
    Text = "Ami, j'aime !"
  },
  AvgDialog_128699_Content_45 = {
    Text = "Ami, a donné à Mosk, tant de choses !"
  },
  AvgDialog_128699_Content_46 = {
    Text = "Alors, maintenant, Mosk doit donner beaucoup, beaucoup à ses amis !"
  },
  AvgDialog_128699_Content_47 = {
    Text = "Elle semblait s'être construite en un mur au milieu de la tempête, te tenant fermement, toi et Nautila, au centre, puis elle prit une profonde inspiration, ouvrit la bouche et dévoila le sourire apaisant et caractéristique de Mosk."
  },
  AvgDialog_128699_Content_48 = {
    Text = "Mosk, c'est sûr, je reviendrai !"
  },
  AvgDialog_128699_Content_49 = {
    Text = "... D'accord, je fais confiance à Mosk. Quand tu reviendras, je préparerai le meilleur navire du monde, puis j'emmènerai toi et petit charbon pour la plus belle des aventures."
  },
  AvgDialog_128699_Content_5 = {
    Text = "Danger ! Attrape !"
  },
  AvgDialog_128699_Content_50 = {
    Text = "Nautila essuie ses larmes, se ressaisit et esquisse un sourire un peu laid."
  },
  AvgDialog_128699_Content_51 = {
    Text = "Voyant Nautila enfin la laisser partir, Mosk prend doucement, tout doucement ta patte dans la sienne et presse son visage contre tes coussinets."
  },
  AvgDialog_128699_Content_52 = {
    Text = "Non, n'aie pas peur."
  },
  AvgDialog_128699_Content_53 = {
    Text = "Ah... Ah ! (Tu vas m'abandonner...)"
  },
  AvgDialog_128699_Content_54 = {
    Text = "Ah !! Ah—(Tu vas me laisser !!)"
  },
  AvgDialog_128699_Content_55 = {
    Text = "Tu es placé dans les bras de Nautila au milieu des cris perçants, et au moment suivant, Mosk se retourne sans hésiter et se précipite vers la direction du vortex lorsque le bateau penche à nouveau."
  },
  AvgDialog_128699_Content_56 = {Text = "...Plouf."},
  AvgDialog_128699_Content_57 = {
    Text = "Comme un poisson qui entre dans son océan."
  },
  AvgDialog_128699_Content_58 = {Text = "Mosk !!"},
  AvgDialog_128699_Content_59 = {
    Text = "La tempête a couvert tous les cris, d'énormes vagues ont déferlé sur le pont, vous entraînant également dans la mer."
  },
  AvgDialog_128699_Content_6 = {Text = "Boom—"},
  AvgDialog_128699_Content_60 = {
    Text = "Sous l'eau noirâtre et bleue, d'innombrables filaments de mucus noir s'ouvrent vers Mosk, ses mains se transformant en un grand vortex, son visage serein et paisible, dans le fond de ses yeux profonds et calmes, comme au centre du vortex."
  },
  AvgDialog_128699_Content_61 = {
    Text = "Mosk, tourbillon. Mosk, gouvernail."
  },
  AvgDialog_128699_Content_62 = {
    Text = "petit charbon, Nautila, ici, toujours."
  },
  AvgDialog_128699_Content_63 = {
    Text = "Mosk ne peut finalement s›empêcher de fondre en larmes, pressant sa main contre sa propre poitrine."
  },
  AvgDialog_128699_Content_64 = {
    Text = "Puis elle lève la main. Un tourbillon portant une force destructrice, mais anormalement doux, vous repousse tous les deux loin, très loin du tourbillon."
  },
  AvgDialog_128699_Content_65 = {
    Text = "Un fil, puis un autre, le mucus s'est collé au corps de Mosk, rampant en un instant sur tout son corps."
  },
  AvgDialog_128699_Content_66 = {
    Text = "Le vortex commence à se resserrer vers le centre, emportant avec lui ce qu'il désire, la jeune fille est comme enroulée et tirée par d'innombrables algues noires, s'enfonçant lentement dans les profondeurs sombres de la mer."
  },
  AvgDialog_128699_Content_67 = {Text = "新增"},
  AvgDialog_128699_Content_68 = {
    Text = "Tout est apaisé, le ciel est d'un bleu pur, les bateaux flottent tranquillement sur la mer sereine."
  },
  AvgDialog_128699_Content_69 = {
    Text = "Eh, où suis-je, pourquoi suis-je sur l'eau ? Ouf, c'est étouffant !"
  },
  AvgDialog_128699_Content_7 = {
    Text = "Une violente secousse a projeté Nautila, la faisant s'écraser sur le tonneau roulant au sol."
  },
  AvgDialog_128699_Content_70 = {
    Text = "Tu regardes d'un air étrange cet humain flottant sur l'eau, vêtu de vêtements bizarres."
  },
  AvgDialog_128699_Content_71 = {
    Text = "(Comment suis-je arrivé ici, qui est ce type ?)"
  },
  AvgDialog_128699_Content_72 = {
    Text = "Ploc. Ploc."
  },
  AvgDialog_128699_Content_73 = {
    Text = "Ploc. Ploc."
  },
  AvgDialog_128699_Content_74 = {
    Text = "(Ah oui, je suis une loutre de mer ! Et les loutres de mer cherchent des coquillages. Coquillages, coquillages, coquillages !)"
  },
  AvgDialog_128699_Content_75 = {
    Text = "Tu plonges joyeusement dans l'eau chaude, nageant à l'opposé de cet humain qui lutte pour rejoindre le bateau."
  },
  AvgDialog_128699_Content_76 = {
    Text = "Tu ne réalises pas que tu es devenu une larme dans la mer."
  },
  AvgDialog_128699_Content_8 = {Text = "Ugh..."},
  AvgDialog_128699_Content_9 = {
    Text = "Nautila, endurant la douleur, se leva en titubant et se précipita vers Mosk."
  },
  AvgDialog_128700_Content_1 = {
    Text = "Glou... Glou..."
  },
  AvgDialog_128700_Content_10 = {
    Text = "Tu es un loutre de un an et demi, en train de chercher de la nourriture avec ton grand copain préféré."
  },
  AvgDialog_128700_Content_100 = {
    Text = "La salive s'écoule de manière incontrôlable, sous l'attrait des plats cuisinés, toi et Mosk vous vous êtes presque jetés en même temps, mordant tous les deux le poisson grillé."
  },
  AvgDialog_128700_Content_101 = {
    Text = "Délicieux—— !"
  },
  AvgDialog_128700_Content_102 = {
    Text = "Hein, ah... Nautila, la main ?"
  },
  AvgDialog_128700_Content_103 = {
    Text = "Ce n'est qu'une luxation, je l'ai déjà remise en place moi-même, pour un aventurier, ce n'est rien de grave, merci pour ton médicament !"
  },
  AvgDialog_128700_Content_104 = {
    Text = "<Small:(Bien que ce soit amer et fort, l'effet est vraiment bon.)>"
  },
  AvgDialog_128700_Content_105 = {
    Text = "Ahou ! Heureux, serre…"
  },
  AvgDialog_128700_Content_106 = {
    Text = "Hihi, Mosk, attention."
  },
  AvgDialog_128700_Content_107 = {
    Text = "Hé ? Hé ! Ne t'inquiète pas, Mosk, la prochaine fois, je crierai fort que ça fait mal pour te prévenir."
  },
  AvgDialog_128700_Content_108 = {Text = "Cui !"},
  AvgDialog_128700_Content_11 = {
    Text = "(Qu'est–ce qu'on a là ? Algue, herbe marine, petits cailloux...)"
  },
  AvgDialog_128700_Content_12 = {
    Text = "(Et Pierre, la tante de Pierre, le grand–père de Pierre... ?)"
  },
  AvgDialog_128700_Content_13 = {
    Text = "(PIERRE ! Dis à ta famille de ne plus nager dans les parages !!)"
  },
  AvgDialog_128700_Content_14 = {
    Text = "<Shake:ROAARRR—>"
  },
  AvgDialog_128700_Content_15 = {
    Text = "(Hélas...)"
  },
  AvgDialog_128700_Content_16 = {
    Text = "La mer se soulève en un immense tourbillon. Une silhouette familière fonce vers toi, traînant quelque chose de volumineux sur son dos !"
  },
  AvgDialog_128700_Content_17 = {
    Text = "petit charbon ! Viande ! Mosk, trouvé !"
  },
  AvgDialog_128700_Content_18 = {
    Text = "Heureux ! À la maison ! Ensemble !"
  },
  AvgDialog_128700_Content_19 = {
    Text = "Avant que tu ne protestes, la jeune fille te saisit et te hisse sur son dos également, filant vers la surface comme un poisson."
  },
  AvgDialog_128700_Content_2 = {
    Text = "<Shake:Glouglou... Grrrr...>"
  },
  AvgDialog_128700_Content_20 = {Text = "新增"},
  AvgDialog_128700_Content_21 = {
    Text = "BOUM—! Un éclair zèbre le ciel, le tonnerre gronde, et les nuages de pluie gonflés éclatent enfin, déversant leur eau dans la mer."
  },
  AvgDialog_128700_Content_22 = {
    Text = "Mosk et toi vous réfugiez dans la cabine sûre, vous regardant dans les yeux."
  },
  AvgDialog_128700_Content_23 = {
    Text = "Ah ? Ah, ah ! (C'est de la viande ? Grand, ça te ressemble !)"
  },
  AvgDialog_128700_Content_24 = {
    Text = "Mosk, pareil ?"
  },
  AvgDialog_128700_Content_25 = {
    Text = "Mosk inclina la tête, affichant son expression de confusion emblématique, puis baissa sérieusement les yeux vers la « viande » qu'elle avait laissée sur le sol."
  },
  AvgDialog_128700_Content_26 = {
    Text = "Pouf— Urgh."
  },
  AvgDialog_128700_Content_27 = {
    Text = "Qu'est-ce qui vient de se passer ? Ma tête semble être sous l'eau depuis un moment. Où suis-je ? Suis-je mort ?"
  },
  AvgDialog_128700_Content_28 = {
    Text = "Un inconnu a toussé plusieurs fois et a craché une grande gorgée d'eau de mer."
  },
  AvgDialog_128700_Content_29 = {
    Text = "Ami ? Ami !! Comme Mosk !"
  },
  AvgDialog_128700_Content_3 = {
    Text = "<Shake:Glou glou glou—>"
  },
  AvgDialog_128700_Content_30 = {
    Text = "Hein... Quoi ?"
  },
  AvgDialog_128700_Content_31 = {
    Text = "<LightGray:C'est une population primitive à proximité ? Étrange... Et quel est cet endroit exactement ?>"
  },
  AvgDialog_128700_Content_32 = {
    Text = "Tu sens qu'elle est méfiante, mais pas hostile. Discrètement, tu t'approches pour mieux observer ce nouveau venu."
  },
  AvgDialog_128700_Content_33 = {
    Text = "On dirait une cabine de bateau. Un peu vieille, mais globalement intacte..."
  },
  AvgDialog_128700_Content_34 = {
    Text = "Attendez— ce sont des rivets de la Corporation Northdrey ?! Des jauges de niveau d'eau, des vannes à tiroir annulaires—"
  },
  AvgDialog_128700_Content_35 = {
    Text = "Voyons voir, dans ce cas..."
  },
  AvgDialog_128700_Content_36 = {
    Text = "L'inconnu fouille avec excitation la cabine bondée. Pendant ce temps, Mosk se tient à côté, clignant des yeux avec une curiosité joyeuse."
  },
  AvgDialog_128700_Content_37 = {
    Text = "Brillant, joli. Mosk, apporte. Ami, ça te plaît ?"
  },
  AvgDialog_128700_Content_38 = {
    Text = "Mosk, avec ces pièces, je peux remettre ce navire en marche. Tu pourrais me les donner ?"
  },
  AvgDialog_128700_Content_39 = {
    Text = "Quand on arrivera à Aglo, je te promets de te rapporter encore plus de jolies choses brillantes."
  },
  AvgDialog_128700_Content_4 = {
    Text = "Tu flottes sur le dos dans l'eau de mer chaude, déployant agréablement tes courts petits membres et effectuant un cercle parfait."
  },
  AvgDialog_128700_Content_40 = {
    Text = "COUIC—!! (Pas question ! Ma jolie petite balle est encore dedans !!)"
  },
  AvgDialog_128700_Content_41 = {
    Text = "Tu cries de colère, désireux de reprendre ta petite balle, mais ton regard est immédiatement attiré par Mosk."
  },
  AvgDialog_128700_Content_42 = {
    Text = "Chut. Mosk, te donne. Coquillages."
  },
  AvgDialog_128700_Content_43 = {
    Text = "Mosk te glisse discrètement deux coquillages que tu avais déjà repérés, puis pousse les composants vers l'inconnu, lui faisant signe de les lui donner."
  },
  AvgDialog_128700_Content_44 = {
    Text = "Ami, aime, Mosk donne !"
  },
  AvgDialog_128700_Content_45 = {
    Text = "Tu ne sais pas comment ces choses peuvent rendre des étrangers si excités, puis, avec un visage radieux, enfouir son petit nez dans ces deux magnifiques coquillages que Mosk n'aurait jamais voulu que tu touches."
  },
  AvgDialog_128700_Content_46 = {
    Text = "C'est super ! Merci... mon ami."
  },
  AvgDialog_128700_Content_47 = {
    Text = "Réchauffée par la gentillesse ouverte et sincère de Mosk, l'étrangère se détend enfin un peu et vous adresse un sourire à tous les deux."
  },
  AvgDialog_128700_Content_48 = {
    Text = "Au fait, je m'appelle Nautila."
  },
  AvgDialog_128700_Content_49 = {
    Text = "Youpi !! Nautila, Mosk, amis, heureux !"
  },
  AvgDialog_128700_Content_5 = {
    Text = "(Attends, des membres courts ?)"
  },
  AvgDialog_128700_Content_50 = {
    Text = "Mosk acclame et ouvre grand les bras, prête à offrir un énorme câlin à sa toute nouvelle amie."
  },
  AvgDialog_128700_Content_51 = {
    Text = "Ah ! (Zut... le grand...)"
  },
  AvgDialog_128700_Content_52 = {
    Text = "Ami, étreindre !"
  },
  AvgDialog_128700_Content_53 = {
    Text = "Attends, Mosk... Aïe ! Ça fait mal !"
  },
  AvgDialog_128700_Content_54 = {
    Text = "Les tourbillons d'air se sont soudainement rassemblés, et dans la pression du vent qui s'est intensifiée, un bruit clair de crissement s'est fait entendre."
  },
  AvgDialog_128700_Content_55 = {Text = "Aïe !!"},
  AvgDialog_128700_Content_56 = {
    Text = "Mosk reprend soudainement conscience et lâche rapidement Nautila, mais Nautila a déjà le visage déformé par la douleur, son bras étant clairement tordu dans un angle anormal."
  },
  AvgDialog_128700_Content_57 = {
    Text = "Désolé, désolé... je..."
  },
  AvgDialog_128700_Content_58 = {
    Text = "Voyant Mosk figée de panique, tu mords le bas de son pantalon et la tires vers quelque chose."
  },
  AvgDialog_128700_Content_59 = {
    Text = "Ah, ah ! (Big: par ici !)"
  },
  AvgDialog_128700_Content_6 = {
    Text = "<Shake:Plic ploc.>"
  },
  AvgDialog_128700_Content_60 = {
    Text = "Ah oui, ça ! Nautila—bois !"
  },
  AvgDialog_128700_Content_61 = {
    Text = "Ne me touche pas !"
  },
  AvgDialog_128700_Content_62 = {
    Text = "Nautila repousse instinctivement la main de Mosk, tout son corps se penchant en arrière."
  },
  AvgDialog_128700_Content_63 = {
    Text = "[@Tonique composé]"
  },
  AvgDialog_128700_Content_64 = {
    Text = "Glou, glou—La bouteille de médicament tombe au sol et roule jusqu'aux pieds de Mosk."
  },
  AvgDialog_128700_Content_65 = {
    Text = "La jeune fille, qui était tout à l'heure pleine d'orgueil, a rapidement perçu la peur de l'autre et a lentement laissé tomber sa main."
  },
  AvgDialog_128700_Content_66 = {Text = "新增"},
  AvgDialog_128700_Content_67 = {
    Text = "Désolé, mais... y a-t-il un autre endroit sur le bateau ? J'aurais peut-être besoin d'un moment de solitude."
  },
  AvgDialog_128700_Content_68 = {
    Text = "Mosk resta silencieuse un moment, puis traîna la plus grande et la plus douce couverture du bateau et l'étala loin sur le sol."
  },
  AvgDialog_128700_Content_69 = {
    Text = "Mosk, imprudent, force brute, blesse."
  },
  AvgDialog_128700_Content_7 = {
    Text = "Ploc ploc～"
  },
  AvgDialog_128700_Content_70 = {
    Text = "Mosk, mauvais, désolé. Maison, chaud, Nautila."
  },
  AvgDialog_128700_Content_71 = {
    Text = "Le corps se retrouve soudainement en l'air, Mosk te tend délicatement et avec un peu d'appréhension comme un trésor à Nautila."
  },
  AvgDialog_128700_Content_72 = {
    Text = "Dehors, Mosk. Petit charbon, chaud, Nautila, ici."
  },
  AvgDialog_128700_Content_73 = {
    Text = "Elle leva le menton, pointa vers l'extérieur, puis vers la couverture, se tenant obstinément entre Nautila et la porte."
  },
  AvgDialog_128700_Content_74 = {
    Text = "... Bien, merci."
  },
  AvgDialog_128700_Content_75 = {
    Text = "Ah, ah ? (Hé, hé, grand ?)"
  },
  AvgDialog_128700_Content_76 = {Text = "新增"},
  AvgDialog_128700_Content_77 = {
    Text = "La pluie ne cesse pas de toute la nuit. À minuit, Nautila se dirige vers l'entrée de la cabine et regarde la jeune fille endormie sur le pont."
  },
  AvgDialog_128700_Content_78 = {
    Text = "Recroquevillée dans un coin du bateau, elle s'abrite du vent et de la pluie."
  },
  AvgDialog_128700_Content_79 = {
    Text = "...Dormir si profondément dans un endroit pareil. Tu es vraiment comme un petit animal..."
  },
  AvgDialog_128700_Content_8 = {
    Text = "(Oui, c'est vrai ! Je suis une loutre de mer !)"
  },
  AvgDialog_128700_Content_80 = {
    Text = "Désolé, je n'aurais pas dû être si dur avec toi, Mosk."
  },
  AvgDialog_128700_Content_81 = {
    Text = "Mosk a une couverture supplémentaire sur elle. Elle claque des lèvres dans son sommeil et s'enfonce dans un rêve encore plus profond et plus doux."
  },
  AvgDialog_128700_Content_82 = {Text = "Cui !"},
  AvgDialog_128700_Content_83 = {
    Text = "Le lendemain matin, après la pluie, c'est le bon moment pour pêcher. \n Tu mords fièrement le plus gros poisson d'aujourd'hui et le lances vers Mosk, mais…"
  },
  AvgDialog_128700_Content_84 = {Text = "Paf !"},
  AvgDialog_128700_Content_85 = {Text = "新增"},
  AvgDialog_128700_Content_86 = {
    Text = "Mosk a attrapé le poisson directement avec son visage, une fissure apparaissant dans l'engourdissement qui durait depuis le matin. Elle te regarda, les coins de ses lèvres se courbant vers le bas, puis de grosses larmes commencèrent à tomber."
  },
  AvgDialog_128700_Content_87 = {
    Text = "Ouh… Ah ah ah ah…"
  },
  AvgDialog_128700_Content_88 = {
    Text = "Puis, sans tenir compte de rien, elle enfouit complètement son visage dans ton ventre et se mit à pleurer à chaudes larmes."
  },
  AvgDialog_128700_Content_89 = {
    Text = "Mosk, maudit !"
  },
  AvgDialog_128700_Content_9 = {
    Text = "Ta petite tête, qui n'est pas plus grande qu'un dixième, se rappelle joyeusement de la situation actuelle."
  },
  AvgDialog_128700_Content_90 = {
    Text = "Iik !! Couic ! COUIC !! (Grande !! TA MORVE !! Attention à ta morve !!)"
  },
  AvgDialog_128700_Content_91 = {
    Text = "<Italic:Snif>— parler, pareil, ami, jamais... ouah ouah..."
  },
  AvgDialog_128700_Content_92 = {
    Text = "Mosk pleurait à chaudes larmes, tu t'efforçais de dégager ton ventre de sous son visage, mais tu ne pouvais qu'émettre un soupir, la laissant étaler ses morves."
  },
  AvgDialog_128700_Content_93 = {
    Text = "(Je voulais dire que j'ai enfin trouvé un ami qui parle comme moi, mais ça a mal tourné, n'est-ce pas ? Mais est-ce que le grand peut vraiment être considéré comme quelqu'un qui parle ?)"
  },
  AvgDialog_128700_Content_94 = {
    Text = "(Bon, attends, ça sent si bon !)"
  },
  AvgDialog_128700_Content_95 = {Text = "新增"},
  AvgDialog_128700_Content_96 = {
    Text = "Dans la cabine, Nautila perce plusieurs poissons marins avec un fil de fer fin, les flammes ayant déjà grillé la surface des poissons, faisant couler la graisse sur le sol, dégageant un parfum suffisant pour éveiller les instincts animaux."
  },
  AvgDialog_128700_Content_97 = {
    Text = "Euh, désolé, j'ai vu que vous mangiez tous du poisson cru, alors je l'ai un peu préparé... Même sans assaisonnement, vous voulez Goûter ?"
  },
  AvgDialog_128700_Content_98 = {Text = "Awoo !"},
  AvgDialog_128700_Content_99 = {Text = "Awoo !"},
  AvgDialog_130451_Content_1 = {
    Text = "La nuit est sombre et pesante. Tu viens de terminer une mission de terrain, et l'Éveilleur qui t'accompagnait — le petit chevalier d'un autre monde, Serment brisé·Ogier — te suit silencieusement."
  },
  AvgDialog_130451_Content_10 = {
    Text = "Attends, ne t'approche pas !"
  },
  AvgDialog_130451_Content_11 = {
    Text = "Avant même que ses mots ne s'éteignent, ton champ de vision plonge soudainement dans l'obscurité totale."
  },
  AvgDialog_130451_Content_12 = {
    Text = "Les entités invisibles qui coexistaient depuis toujours avec Serment brisé·Ogier se ruent soudain vers toi, s'enroulent autour de tes membres, voilent tes yeux, t'enserrent étroitement, te faisant ressentir une sensation de froid glacial."
  },
  AvgDialog_130451_Content_13 = {Text = "Ogier !"},
  AvgDialog_130451_Content_14 = {
    Text = "Tu cries, mais cette boue noire se resserre encore davantage, comme si elle cherchait à t'emprisonner complètement. Tu tends les mains pour t'en arracher, mais elle revient t'envelopper, aussi tenace que des lianes."
  },
  AvgDialog_130451_Content_15 = {Text = "Ugh..."},
  AvgDialog_130451_Content_16 = {
    Text = "La voix floue et faible du jeune homme te parvient par bribes, manifestement en train de réprimer quelque chose de toutes ses forces."
  },
  AvgDialog_130451_Content_17 = {
    Text = "Ogier ? Tu m'entends ?"
  },
  AvgDialog_130451_Content_18 = {
    Text = "L'étreinte qui t'enserre frémit légèrement, puis se resserre à nouveau, comme tiraillée entre deux volontés opposées."
  },
  AvgDialog_130451_Content_19 = {
    Text = "C'est à cause de mon impuissance que vous avez quand même été blessé. Si seulement je pouvais trouver un meilleur moyen de vous protéger…"
  },
  AvgDialog_130451_Content_2 = {
    Text = "Cette mission n'avait rien de difficile. En tant que Gardien du secret expérimenté, toi et Serment brisé·Ogier avez aisément éliminé tous les ennemis. Cependant, par un moment d'inattention de ta part, tu t'es tout de même retrouvé avec une petite cicatrice au poignet."
  },
  AvgDialog_130451_Content_20 = {
    Text = "Tu ne perçois que quelques mots confus, comme un murmure adressé à lui-même."
  },
  AvgDialog_130451_Content_21 = {
    Text = "Bien que cette boue t'enserre étroitement, elle ne te cause pas la moindre douleur ni la moindre suffocation. Tu réalises soudain que ce n'est sans doute pas pour te blesser — cela ressemble plutôt à une tentative de te cacher dans un endroit absolument sûr, à l'abri de tout."
  },
  AvgDialog_130451_Content_22 = {
    Text = "Ça va, je n'ai rien du tout, n'aie pas peur."
  },
  AvgDialog_130451_Content_23 = {
    Text = "Tes paroles semblent avoir eu de l'effet. Cette fois, l'étreinte de la boue se relâche enfin peu à peu. Tu en profites pour l'écarter."
  },
  AvgDialog_130451_Content_24 = {
    Text = "Vous voyez Parjure·Ogier la tête basse, le front légèrement plissé, une expression abattue sur le visage. Ses yeux restent voilés de confusion, comme une statue pénitente portant le poids d'un péché immense."
  },
  AvgDialog_130451_Content_25 = {Text = "Ça va ?"},
  AvgDialog_130451_Content_26 = {
    Text = "J'ai osé déployer une telle force incontrôlée contre vous…"
  },
  AvgDialog_130451_Content_27 = {
    Text = "Non, je dois… reprendre mes esprits."
  },
  AvgDialog_130451_Content_28 = {
    Text = "Il ferme les yeux et murmure, façonnant la petite masse de boue noire qui tourbillonnait autour de sa main en une lame de poignard. La lumière de la lune se pose sur le tranchant froid qui en émane, et ce tranchant est dirigé vers son propre autre bras."
  },
  AvgDialog_130451_Content_29 = {
    Text = "Cependant, cet objet acéré ne parvient pas à s'abattre — vous vous précipitez à temps pour arrêter son geste. Vous réalisez alors, avec un temps de retard, que les forces invisibles qui vous enserraient si étroitement un instant plus tôt se sont entièrement dissipées."
  },
  AvgDialog_130451_Content_3 = {
    Text = "Tout est calme alentour. La fatigue te plonge dans un état de légère torpeur, quand une voix surgissant dans ton dos te fait sursauter."
  },
  AvgDialog_130451_Content_30 = {
    Text = ": Mon seigneur... ?"
  },
  AvgDialog_130451_Content_31 = {
    Text = "Vous vous accroupissez légèrement et le prenez doucement dans vos bras, lui tapotant le dos pour le réconforter."
  },
  AvgDialog_130451_Content_32 = {
    Text = "Contrairement à son habitude, il ne se dérobe pas, mais reste figé sur place, laissant vos bras l'enlacer."
  },
  AvgDialog_130451_Content_33 = {
    Text = "Ne vous pressez pas, détendez-vous. Vous voyez, Il a été maîtrisé avec succès par vous. Mais que s'est-il passé, au juste ?"
  },
  AvgDialog_130451_Content_34 = {
    Text = "Pardonnez-moi, mon Seigneur. Je ne sais pourquoi, mais aujourd'hui la présence qui réside en moi était d'une agitation inhabituelle, et mes pensées sont devenues très confuses."
  },
  AvgDialog_130451_Content_35 = {
    Text = "Pourtant, vous étiez à mes côtés, et au lieu de se replier comme à l'ordinaire, Il s'est montré encore plus actif… C'est pourquoi j'ai voulu utiliser la douleur pour me calmer."
  },
  AvgDialog_130451_Content_36 = {
    Text = "Vous tenez Ogier dans vos bras et percevez la chaleur anormale qui émane de lui — une conclusion se forme dans votre esprit. Vous n'auriez pas imaginé que l'influence de la Rivière sacrée interfère directement avec l'autre force qui réside en Ogier."
  },
  AvgDialog_130451_Content_37 = {
    Text = "Ce n'est pas votre faute, mais l'effet de… certaines autres choses."
  },
  AvgDialog_130451_Content_38 = {
    Text = "Et puis, même si cette boue noire m'a retenu un moment, elle ne m'a absolument pas blessé… C'est sans doute parce que vous contrôliez Il, n'est-ce pas ? C'est vraiment remarquable."
  },
  AvgDialog_130451_Content_39 = {
    Text = "Après un bref silence, vous entendez enfin la voix étouffée du jeune homme."
  },
  AvgDialog_130451_Content_4 = {
    Text = "…Ça suffit ! Comment pourrais-je jamais faire du mal à mon seigneur —"
  },
  AvgDialog_130451_Content_40 = {
    Text = "… Merci, vous m'avez encore une fois réconforté."
  },
  AvgDialog_130451_Content_41 = {
    Text = "Il se fait tard. Permettez-moi d'abord de soigner vos blessures, puis de vous raccompagner jusqu'à votre chambre."
  },
  AvgDialog_130451_Content_5 = {
    Text = "Tu sais que depuis longtemps, Serment brisé·Ogier lutte contre les entités invisibles qui s'accrochent à lui, mais sa réaction aujourd'hui semble étrangement excessive."
  },
  AvgDialog_130451_Content_6 = {
    Text = "Alors, tu te retournes et marches vers lui."
  },
  AvgDialog_130451_Content_7 = {
    Text = "Ogier ? Tu vas bien ? Elle cherche encore à te contrôler ?"
  },
  AvgDialog_130451_Content_8 = {Text = "!"},
  AvgDialog_130451_Content_9 = {
    Text = "Serment brisé·Ogier relève brusquement la tête — qu'il gardait fixée sur la pointe de ses chaussures — et recule d'un pas en tremblant."
  },
  AvgDialog_130453_Content_1 = {
    Text = "Étant donné les capacités spéciales de Saya, tout le monde est sur le qui-vive quant à la façon dont elle pourrait réagir à l'influence de la Rivière sacrée."
  },
  AvgDialog_130453_Content_10 = {
    Text = "Tout ce que j'ai traversé fait de moi ce que je suis, mais il y a encore tant de choses que je n'ai pas encore apprises."
  },
  AvgDialog_130453_Content_11 = {
    Text = "«L'instinct, c'est la reproduction», hein. Ah... je vois..."
  },
  AvgDialog_130453_Content_12 = {
    Text = "Tout en parlant, elle vous tend un coussin."
  },
  AvgDialog_130453_Content_13 = {
    Text = "Vous laissez échapper un long soupir de soulagement, vous adossant tout comme elle."
  },
  AvgDialog_130453_Content_14 = {
    Text = "Je vois... alors après tout ce que vous avez traversé, la raison l›emporte sur l›instinct..."
  },
  AvgDialog_130453_Content_15 = {
    Text = "<Small: Même après être devenue un Corps éveillé, Saya reste vraiment unique...>"
  },
  AvgDialog_130453_Content_16 = {
    Text = "Saya — si ce n›est pas trop demander, est-ce que je peux utiliser votre logement comme refuge ?!"
  },
  AvgDialog_130453_Content_17 = {
    Text = "Vos yeux se remplissent de larmes de pur soulagement tandis que vous formulez votre requête désespérée."
  },
  AvgDialog_130453_Content_18 = {
    Text = "En cet instant, ce qui compte le plus, c›est que le pauvre Gardien des Mizags dispose enfin d›un refuge fiable."
  },
  AvgDialog_130453_Content_19 = {
    Text = "Hein ? Je ne comprends pas très bien..."
  },
  AvgDialog_130453_Content_2 = {
    Text = "Pourtant, à la surprise générale, elle se tient simplement près de la fenêtre en silence. Sa peau pâle est presque translucide, comme si elle était scellée dans un autre monde."
  },
  AvgDialog_130453_Content_20 = {
    Text = "Saya fronça les sourcils en feignant d'être embarrassée, et ne sourit à nouveau qu'après avoir vu l'expression déçue sur votre visage, satisfaite d'avoir obtenu ce qu'elle voulait."
  },
  AvgDialog_130453_Content_21 = {
    Text = "Saya fronce les sourcils dans une hésitation feinte et espiègle, ne souriant qu›après avoir vu l›air déçu sur votre visage."
  },
  AvgDialog_130453_Content_22 = {
    Text = "Bien sûr que vous pouvez. Mais... %player%, en échange, pourriez-vous me dire :"
  },
  AvgDialog_130453_Content_23 = {
    Text = "Qui est la personne qui compte le plus pour vous ?"
  },
  AvgDialog_130453_Content_24 = {
    Text = "Comme deux amis proches qui partagent tout, vous vous laissez aller à une conversation détendue et légère."
  },
  AvgDialog_130453_Content_25 = {
    Text = "Une silhouette apparaît dans ta conscience, tu fermes les yeux avec sérénité, offrant toi aussi ta Bénédiction pour l'avenir de Saya — puisse cette existence traverser les âges."
  },
  AvgDialog_130453_Content_26 = {
    Text = "Une silhouette familière surgit dans votre esprit. Vous fermez les yeux, détendu, offrant une bénédiction silencieuse pour l›avenir de Saya — tant que ces sentiments ne provoquent pas réellement la fin du monde. Mais qui sait ?"
  },
  AvgDialog_130453_Content_27 = {
    Text = "Le pouvoir de la Rivière sacrée coule entre vous comme une marée douce, silencieuse et paisible."
  },
  AvgDialog_130453_Content_3 = {
    Text = "Bonjour, Gardien."
  },
  AvgDialog_130453_Content_4 = {
    Text = "Saya... vous vous sentez bien ? Est-ce que quelque chose... ne va pas ?"
  },
  AvgDialog_130453_Content_5 = {
    Text = "Comme si elle percevait votre inquiétude, la jeune fille pivote légèrement sur ses talons —"
  },
  AvgDialog_130453_Content_6 = {
    Text = "pas de fièvre, pas de battements de cœur accélérés, pas d'euphorie étrange. Rien d'anormal."
  },
  AvgDialog_130453_Content_7 = {
    Text = "Ne vous inquiétez pas pour moi. Il semble que rien de particulier ne me soit arrivé."
  },
  AvgDialog_130453_Content_8 = {
    Text = "Alors l'instinct de l'espèce de Dame Thais est la reproduction... mais cela pourrait-il m'affecter aussi ?"
  },
  AvgDialog_130453_Content_9 = {
    Text = "Elle s'assoit plus près de vous, se blottissant dans un coussin moelleux et souriant comme un petit animal inoffensif."
  },
  AvgDialog_130454_Content_1 = {
    Text = "Dans la salle vide, seuls vos pas et ceux de Murphy résonnent."
  },
  AvgDialog_13049_Content_1 = {
    Text = "Ogier tenait fermement son arme, alerte à chaque bruissement autour de lui. À ses yeux, chaque mouvement pouvait être une embuscade des troupes ennemies."
  },
  AvgDialog_13049_Content_10 = {
    Text = "Le son de l'eau ? C'est probablement l'horloge à eau là-bas."
  },
  AvgDialog_13049_Content_11 = {
    Text = "On dirait que ça vient de l'extérieur. Je vais aller voir !"
  },
  AvgDialog_13049_Content_12 = {
    Text = "Ne vous précipitez pas ! Allons-y ensemble !"
  },
  AvgDialog_13049_Content_13 = {
    Text = "Avant que quiconque ne puisse l'arrêter, Ogier prit son arme et se précipita vers la porte du palais."
  },
  AvgDialog_13049_Content_14 = {Text = "C'est—?!"},
  AvgDialog_13049_Content_15 = {
    Text = "L'ennemi attaque !"
  },
  AvgDialog_13049_Content_2 = {
    Text = "Vous ne trouvez pas les mots pour le réconforter. Les mots du dossier de l'Éveillé flashent devant vous—"
  },
  AvgDialog_13049_Content_3 = {
    Text = "Déclaration de l'Éveilleur : Ogier Danske, @2 Chevalier du Duché\nTombe lors de la Nuit de la Défense de la Patrie..."
  },
  AvgDialog_13049_Content_4 = {
    Text = "Seigneur Chambellan, veuillez évacuer vers la périphérie pour votre sécurité. Nous pouvons gérer les choses ici..."
  },
  AvgDialog_13049_Content_5 = {
    Text = "Vous deux chevaliers ne pouvez même pas distinguer l'aconitume des orchids. Et si vous donniez accidentellement du poison à la princesse ?"
  },
  AvgDialog_13049_Content_6 = {
    Text = "Un refus franc a apaisé la tension. Ogier a rougi, le chevalier garde étouffait un rire, et même un râle de rire étouffé est venu de derrière la porte."
  },
  AvgDialog_13049_Content_7 = {
    Text = "Vous ne pouvez pas partir—piégé dans le mystère centré autour des Ogier, partir à la hâte peut entraîner des conséquences inconnues."
  },
  AvgDialog_13049_Content_8 = {
    Text = "Tick-tock—"
  },
  AvgDialog_13049_Content_9 = {
    Text = "As-tu entendu des sons ?"
  },
  AvgDialog_13050_Content_1 = {
    Text = "Enfin, la Bataille fut terminée. Vous et Ogier restiez au pied des escaliers pour nettoyer la salle du palais, tandis que les chevaliers de la garde étaient déjà retournés devant la chambre de la princesse."
  },
  AvgDialog_13050_Content_10 = {
    Text = "Brusquement..."
  },
  AvgDialog_13050_Content_11 = {
    Text = "Cependant... la peste peut-elle se transformer en monstres que les gens ordinaires ne peuvent pas voir ?"
  },
  AvgDialog_13050_Content_12 = {
    Text = "C'est vraiment absurde. Même si les poètes de la cour en parlaient, peu y croiraient."
  },
  AvgDialog_13050_Content_13 = {
    Text = "Au début, mon père et moi pensions que c'était une malédiction des sorciers du pays voisin, mais... bientôt, eux aussi signalèrent la peste ravageant."
  },
  AvgDialog_13050_Content_14 = {
    Text = "Même moi... *tousse, tousse*..."
  },
  AvgDialog_13050_Content_15 = {
    Text = "En parlant, une toux déchirante résonna de derrière la porte."
  },
  AvgDialog_13050_Content_16 = {
    Text = "Princesse, veuillez vous abstenir de parler pour le moment. Retournez d'abord au lit."
  },
  AvgDialog_13050_Content_17 = {
    Text = "Brusquement..."
  },
  AvgDialog_13050_Content_18 = {
    Text = "Préposée ! Préposée, reviens et aide ! La princesse—"
  },
  AvgDialog_13050_Content_19 = {Text = "Ugh!"},
  AvgDialog_13050_Content_2 = {
    Text = "C'est notre première fois à lutter contre des ennemis invisibles. Quand tout cela sera terminé, que dirais-tu de trouver un barde pour écrire notre histoire et la transformer en chanson ?"
  },
  AvgDialog_13050_Content_20 = {
    Text = "Le bruit aigu des os qui se brisent résonnait alors que quelque chose déchirait violemment le tissu musculaire étroitement lié, provoquant des éclaboussures de liquide rouge vif."
  },
  AvgDialog_13050_Content_21 = {Text = "Quoi... ?"},
  AvgDialog_13050_Content_22 = {
    Text = "Monsieur Fernando !!!"
  },
  AvgDialog_13050_Content_23 = {
    Text = "Le Gardien Chevalier a toussé, du sang mêlé à des morceaux de chair jaillissant de sa gorge. Ses yeux se sont agrandis, remplis d'incrédulité, de confusion et de peur."
  },
  AvgDialog_13050_Content_3 = {
    Text = "J'ai déjà décidé du nom : \"L'Œil de Dansk, l'Épée de Fernando\" !"
  },
  AvgDialog_13050_Content_4 = {
    Text = "Ogier, appelé par son nom, a levé les yeux vers le chevalier de garde. Ses mains étaient couvertes de beaucoup de D-Slime. Il a hésité, ne sachant pas comment les nettoyer, se sentant extrêmement gêné."
  },
  AvgDialog_13050_Content_5 = {
    Text = "Vas-tu aussi écrire mon nom dans la chanson ? Que fait Ogier pour mériter cela"
  },
  AvgDialog_13050_Content_6 = {
    Text = "Heh heh... Le chambellan et moi ne pouvons pas au moins avoir nos noms dessus ?"
  },
  AvgDialog_13050_Content_7 = {
    Text = "Bien sûr ! Absolument ! Votre nom sera en première ligne de cette chanson !"
  },
  AvgDialog_13050_Content_8 = {
    Text = "Brusquement..."
  },
  AvgDialog_13050_Content_9 = {
    Text = "@1 Suite de la Princesse... Que pensez-vous ? Ai-je un talent pour la poésie ?"
  },
  AvgDialog_13051_Content_1 = {
    Text = "Qu'est-ce que... qu'est-ce qui se passe ?"
  },
  AvgDialog_13051_Content_10 = {
    Text = "Sir Fernando... I remember he was the only child in his family. -> Sir Fernando... Je me souviens qu'il était l'enfant unique de sa famille."
  },
  AvgDialog_13051_Content_11 = {
    Text = "Si seulement j'avais été plus vigilant..."
  },
  AvgDialog_13051_Content_12 = {
    Text = "Ne te blame pas pour sa mort. Ces monstres @1 sont insaisissables. Nous avons fait de notre mieux."
  },
  AvgDialog_13051_Content_13 = {
    Text = "Ogier secoua la tête ; votre pâle réconfort ne semblait clairement pas le consoler.\nJuste à ce moment, un léger coup se fit entendre par derrière."
  },
  AvgDialog_13051_Content_14 = {
    Text = "Chancelier, emmène Ogier avec toi."
  },
  AvgDialog_13051_Content_15 = {Text = "Pourquoi !"},
  AvgDialog_13051_Content_16 = {
    Text = "Tu... tu n'as plus besoin de moi ? Je sais que j'ai échoué à sauver Lord Fernando, mais..."
  },
  AvgDialog_13051_Content_17 = {
    Text = "La peste apporte la maladie, la guerre et la douleur... Rester ici ne fait que faire de vous son prochain repas."
  },
  AvgDialog_13051_Content_18 = {
    Text = "Sa voix tremblait, pourtant elle parlait d'un ton espiègle. Confrontée à la menace imminente de la mort, elle ne montrait aucune trace de peur."
  },
  AvgDialog_13051_Content_19 = {
    Text = ": Je suppose que... Lord Fernando ne voudrait pas se réunir avec toi si tôt, n'est-ce pas ?"
  },
  AvgDialog_13051_Content_2 = {
    Text = "Un faible bruit de pas provenait de l'intérieur, suivi du glissement du verrou de la porte—"
  },
  AvgDialog_13051_Content_20 = {
    Text = "Mais... cela... est ma responsabilité..."
  },
  AvgDialog_13051_Content_21 = {
    Text = "Maintenant... c'est juste moi... Je poursuivrai la volonté du Seigneur Fernando... Je vais hériter..."
  },
  AvgDialog_13051_Content_22 = {
    Text = "Un long soupir résigné est venu de derrière la porte. Après un moment, la princesse t'a parlé."
  },
  AvgDialog_13051_Content_23 = {
    Text = "Intendant, promets-moi... quand ma voix sera complètement partie, tu devras emporter Ogier, même si tu dois l'assommer, d'accord ?"
  },
  AvgDialog_13051_Content_24 = {
    Text = "...Comme tu le souhaites."
  },
  AvgDialog_13051_Content_25 = {
    Text = "Ogier tenait son arme fermement, ses mains devenant blanches d’effort. On aurait dit que la lance dans ses bras était sa famille dont le destin était incertain, une princesse mourante, ou le Fernando à jamais parti."
  },
  AvgDialog_13051_Content_26 = {
    Text = "Il fixait la porte du palais, son esprit dérivant très loin. Même le fort coup de la porte frappée ne pouvait pas le ramener à la réalité."
  },
  AvgDialog_13051_Content_27 = {
    Text = "Ogier ? Ogier ?"
  },
  AvgDialog_13051_Content_28 = {
    Text = "Quelqu'un arrive."
  },
  AvgDialog_13051_Content_29 = {
    Text = "Quelqu'un... arrive ? Les chevaliers sont-ils de retour !?"
  },
  AvgDialog_13051_Content_3 = {
    Text = "Ne sors pas !"
  },
  AvgDialog_13051_Content_30 = {
    Text = "La porte s'est ouverte violemment, mais le drapeau flottant dans le vent n'était pas de la couleur que vous attendiez."
  },
  AvgDialog_13051_Content_4 = {
    Text = "Princesse... s'il vous plaît, ne sortez pas..."
  },
  AvgDialog_13051_Content_5 = {
    Text = "Ogier s'efforça de repousser le corps du Chevalier Fernando loin de la porte, puis tira le rideau pour couvrir le sang qui s'accumulait à travers l'espace."
  },
  AvgDialog_13051_Content_6 = {
    Text = "Les piquants du mutant ont transpercé l'armure de la poitrine et la chair, laissant la poitrine dans un désordre sanglant comme si elle avait explosé. Le chevalier Fernando était déjà mort dans l'angoisse."
  },
  AvgDialog_13051_Content_7 = {
    Text = "...D'accord."
  },
  AvgDialog_13051_Content_8 = {
    Text = "S'il vous plaît, faites de votre mieux pour lui donner une sépulture convenable."
  },
  AvgDialog_13051_Content_9 = {
    Text = "Vous et Ogier échangez un regard, enroulez silencieusement le corps du chevalier dans un tapis, et vous asseyez par terre devant la porte de la chambre. La douleur et l'anxiété remplissent l'air."
  },
  AvgDialog_13052_Content_1 = {
    Text = "Que se passe-t-il ? Où sont les ennemis ?"
  },
  AvgDialog_13052_Content_10 = {
    Text = "Votre Excellence, pouvez-vous le voir aussi ?"
  },
  AvgDialog_13052_Content_11 = {
    Text = "Vous lui faites un regard réconfortant et continuez à négocier avec le chevalier."
  },
  AvgDialog_13052_Content_12 = {
    Text = "Ogier n'a jamais été le genre à agir de manière déraisonnable, et tu le sais mieux grâce à l'entraînement avec lui, n'est-ce pas ?"
  },
  AvgDialog_13052_Content_13 = {
    Text = "Même si vous dites cela, je n'ai vraiment rien fait..."
  },
  AvgDialog_13052_Content_14 = {
    Text = "...Attendez un moment, Seigneur Fernando."
  },
  AvgDialog_13052_Content_15 = {
    Text = "Un coup est venu de la direction de la porte de la chambre, ramenant tout le monde à l'avant avec une faible voix féminine."
  },
  AvgDialog_13052_Content_16 = {
    Text = "Ils avaient raison... C'était l'ennemi invisible qui a répandu la peste."
  },
  AvgDialog_13052_Content_17 = {
    Text = "Depuis que la princesse a dit cela..."
  },
  AvgDialog_13052_Content_18 = {
    Text = "Le Gardien Chevalier a grincé des dents, a levé son arme et s'est tenu à vos côtés."
  },
  AvgDialog_13052_Content_19 = {
    Text = "Dis-moi la position de l'ennemi, et je ferai de mon mieux pour aider dans la bataille!"
  },
  AvgDialog_13052_Content_2 = {
    Text = "Le chevalier de garde se précipita également dans les escaliers à tes côtés, complètement perplexe."
  },
  AvgDialog_13052_Content_3 = {
    Text = "Maintenant n'est pas le moment de s'amuser. Reste vigilent."
  },
  AvgDialog_13052_Content_4 = {
    Text = "Je ne rigole pas ! Tu ne peux pas voir ?!"
  },
  AvgDialog_13052_Content_5 = {
    Text = "Ogier se défend avec anxiété, mais le chevalier garde reste sceptique."
  },
  AvgDialog_13052_Content_6 = {
    Text = "Ce n'est pas de sa faute ; après tout, les ennemis que toi et Ogier avez vaincus n'étaient que des aberrations dérivées de la Dissolution."
  },
  AvgDialog_13052_Content_7 = {
    Text = "Observer visuellement le D-phénomène est extrêmement rare.\nOgier est l'un des rares malheureux considérés comme chanceux."
  },
  AvgDialog_13052_Content_8 = {
    Text = "S'il vous plaît, faites-nous confiance."
  },
  AvgDialog_13052_Content_9 = {
    Text = "S'il vous plaît, faites-nous confiance et croyez en l'intégrité d'Ogier."
  },
  AvgDialog_13053_Content_1 = {
    Text = "Rideau final"
  },
  AvgDialog_13053_Content_10 = {Text = "新增"},
  AvgDialog_13053_Content_11 = {
    Text = "Faisons garder le palais par Ogier ensemble.\nAprès tout, il est un Chevalier Gardien désigné par le Grand Duc, n'est-ce pas ?"
  },
  AvgDialog_13053_Content_12 = {
    Text = "Le Chevalier Gardien n'a pas trouvé d'autre raison de refuser. Après avoir hoché la tête en accord, vous êtes tous deux retournés au palais"
  },
  AvgDialog_13053_Content_13 = {
    Text = "Le palais est vide ; même la servante bruyante est partie.\nÀ part vous trois, seule la princesse reste."
  },
  AvgDialog_13053_Content_14 = {
    Text = "Vous avez frappé à la porte de la luxueuse chambre, le son résonnant dans le hall silencieux, étrangement étouffé."
  },
  AvgDialog_13053_Content_15 = {
    Text = "Princesse? Ça va?"
  },
  AvgDialog_13053_Content_16 = {
    Text = "Il n'y a pas eu de réponse de l'intérieur. Après avoir attendu un moment, tu frappas à la porte à nouveau."
  },
  AvgDialog_13053_Content_17 = {
    Text = "Princesse, le chevalier garde, Ogier, et moi sommes tous ici."
  },
  AvgDialog_13053_Content_18 = {
    Text = "À travers la lourde porte en bois, le bruit du tissu froissé se fit entendre, alors que quelqu'un luttait pour se redresser dans le lit."
  },
  AvgDialog_13053_Content_19 = {Text = "...Folie."},
  AvgDialog_13053_Content_2 = {Text = "\"Rêve\""},
  AvgDialog_13053_Content_20 = {
    Text = "Tu... vas y aller et rejoindre les autres. Il n'est pas nécessaire de rester avec un cadavre."
  },
  AvgDialog_13053_Content_21 = {
    Text = "La respiration de la fille est faible, sa voix aussi douce qu'un moustique. Il semble que répondre à vous ait drainé toute sa force."
  },
  AvgDialog_13053_Content_22 = {
    Text = "La peste s'est propagée de manière chaotique dans le duché, n'épargnant personne, même pas la noblesse. La princesse est tombée malade avant le début de la guerre, et jusqu'à ce jour, elle n'a pas la force de quitter son lit."
  },
  AvgDialog_13053_Content_23 = {
    Text = "Le médecin royal a déclaré franchement que la princesse ne peut plus supporter la pression d'être déplacée du palais. Même de légers tremblements pourraient lui coûter la vie."
  },
  AvgDialog_13053_Content_24 = {
    Text = "Princesse..."
  },
  AvgDialog_13053_Content_25 = {
    Text = [[
Peu importe ce que vous dites, je ne partirai pas. Veuillez me permettre de vous garder...
remplissant mes fonctions de chevalier.]]
  },
  AvgDialog_13053_Content_26 = {Text = "新增"},
  AvgDialog_13053_Content_27 = {
    Text = "...Ne t'approche pas trop de ma chambre. La peste est irrécupérable, au moins... ne laissez pas vous infecter."
  },
  AvgDialog_13053_Content_28 = {
    Text = "Quand le sablier est écoulé, viens me parler, d'accord ?\nQuand je ne réponds plus... tu devrais partir."
  },
  AvgDialog_13053_Content_3 = {
    Text = "Des conspirations s'agitent dans l'obscurité, allumant la mèche posée par la peste. La guerre éclate du jour au lendemain."
  },
  AvgDialog_13053_Content_4 = {
    Text = "La maladie incurable <Yellow:peste> s'est déjà répandue dans tout le duché, et les gardes de la ville, affligés par la maladie, ne peuvent pas résister à l'avancée des envahisseurs."
  },
  AvgDialog_13053_Content_5 = {
    Text = "Même les chevaliers royaux ont franchi le fossé sur les ordres du Grand Duc, rejoignant la dernière ligne de défense de la capitale."
  },
  AvgDialog_13053_Content_6 = {
    Text = "Ogier, pourquoi es-tu encore ici ?"
  },
  AvgDialog_13053_Content_7 = {
    Text = "Je... Je veux te rejoindre dans la mission d'escorte."
  },
  AvgDialog_13053_Content_8 = {
    Text = "Tu es trop jeune ; la guerre... ne te concerne pas encore.\nRentre chez toi et trouve un endroit sûr avec ta famille."
  },
  AvgDialog_13053_Content_9 = {
    Text = "La maison d'Ogier, Dansk Estate... devrait être en dehors de la ligne de défense, n'est-ce pas ?"
  },
  AvgDialog_13054_Content_1 = {
    Text = "Rêve ou idéal"
  },
  AvgDialog_13054_Content_10 = {
    Text = "Agent, pourriez-vous agir en mon nom ?"
  },
  AvgDialog_13054_Content_100 = {
    Text = "Les choses dont nous venons de discuter... Tu ne diras vraiment pas à la princesse, n'est-ce pas ?"
  },
  AvgDialog_13054_Content_101 = {
    Text = "Quoi ? Je n'ai vraiment aucun crédit avec toi ?"
  },
  AvgDialog_13054_Content_102 = {
    Text = "Comment cela pourrait-il être ! Je ne... !"
  },
  AvgDialog_13054_Content_103 = {
    Text = "D'accord, je vais utiliser ce qui s'est passé aujourd'hui pour te menacer."
  },
  AvgDialog_13054_Content_104 = {Text = "Menace ?"},
  AvgDialog_13054_Content_105 = {
    Text = "Vous vous agenouillez devant Ogier, établissant un contact visuel avec le chiot anxieux, et lui tendez la main."
  },
  AvgDialog_13054_Content_106 = {
    Text = "Aujourd'hui, la conversation restera à jamais enfouie dans nos cœurs. Mais en échange de la préservation de ce secret, vous devez me promettre une chose."
  },
  AvgDialog_13054_Content_107 = {
    Text = "Dans cette ère, il n'y a pas de coutume de jurer sur le petit doigt, mais Ogier a quand même innocemment accroché votre petit doigt étendu."
  },
  AvgDialog_13054_Content_108 = {
    Text = "Tant que c'est dans ma capacité..."
  },
  AvgDialog_13054_Content_109 = {
    Text = "Très bien, je me réserve le droit de faire un vœu. Un jour dans le futur, je pourrai venir le réclamer. N'oubliez pas, \"Monsieur le Chevalier.\""
  },
  AvgDialog_13054_Content_11 = {
    Text = "Si c'est le dernier, réveiller le propriétaire du rêve devrait nous permettre de nous échapper d'ici, n'est-ce pas ?"
  },
  AvgDialog_13054_Content_12 = {
    Text = "Hé ! Seigneur Préposé ? Réveille-toi !"
  },
  AvgDialog_13054_Content_13 = {
    Text = "Vos pensées s'éloignèrent, suivant les indices. Juste au moment où le plan \"Réveiller le Maître des Rêves\" commençait à prendre forme, vos ongles s'enfoncèrent brutalement dans votre bras, et la douleur vous ramena à la réalité."
  },
  AvgDialog_13054_Content_14 = {
    Text = "Hiss—Ça fait mal !"
  },
  AvgDialog_13054_Content_15 = {
    Text = "Alors tu peux ressentir la douleur ! Nous t'avons appelé pendant des siècles, et tu n'as pas du tout répondu, comme un cadavre. Est-ce qu'il y a un problème avec tes oreilles ?"
  },
  AvgDialog_13054_Content_16 = {
    Text = "Tu as été distrait dernièrement. Es-tu trop fatigué ? Que dirais-tu de prendre un break dans le fief de ta famille ? Ça fait longtemps que tu n'as pas eu de vacances."
  },
  AvgDialog_13054_Content_17 = {
    Text = "Ne—je suis vraiment désolé, j'ai juste quelque chose en tête..."
  },
  AvgDialog_13054_Content_18 = {
    Text = "La clé pour échapper au \"Rêve\" réside avec Ogier. Bien que tu sois curieux de savoir à quoi ressemble le monde au-delà du centre de rêve, ce n'est pas le moment de s'éloigner trop."
  },
  AvgDialog_13054_Content_19 = {
    Text = "Quelque chose sur ton esprit ? Qu'est-ce que c'est ? Est-ce à propos de quelqu'un que tu aimes et que cela te cause des problèmes ?"
  },
  AvgDialog_13054_Content_2 = {
    Text = "\"Rêve\"\nPalais de la Princesse"
  },
  AvgDialog_13054_Content_20 = {
    Text = "Vous avez peur que l'autre personne ne partage pas vos sentiments ? Princesse, pourquoi ne feriez-vous pas une petite divination pour notre cher serviteur ? Ou mieux encore, donnez-lui simplement un philtre d'amour à {Male=him,Female=her} —"
  },
  AvgDialog_13054_Content_21 = {
    Text = "Allez, comment peux-tu utiliser la magie et des potions pour maintenir une relation ?"
  },
  AvgDialog_13054_Content_22 = {
    Text = "La princesse a souri et a habilement changé le sujet soulevé par la servante, en vous faisant signe."
  },
  AvgDialog_13054_Content_23 = {
    Text = "Ogier s'entraîne actuellement avec les chevaliers. S'il te plaît, vérifie qu'il ne se blesse pas."
  },
  AvgDialog_13054_Content_24 = {
    Text = "À vos ordres !"
  },
  AvgDialog_13054_Content_25 = {
    Text = "Lorsque la princesse vous a apporté un coussin alors que vous vous sentiez somnolent, cela vous a donné une raison légitime de vous approcher d'Ogier."
  },
  AvgDialog_13054_Content_26 = {
    Text = "Cependant, si vous avez vraiment besoin de potions, vous pouvez toujours venir me les demander."
  },
  AvgDialog_13054_Content_27 = {
    Text = "\"Rêve\"\nTerrain d'entraînement des Chevaliers"
  },
  AvgDialog_13054_Content_28 = {
    Text = "Guidé par d'autres serviteurs, vous vous frayez un chemin à travers le château labyrinthique et les jardins jusqu'aux terrains d'entraînement."
  },
  AvgDialog_13054_Content_29 = {
    Text = "Le tintement croquant des armes et les acclamations continues des autres montrent clairement que quelqu'un pratique sous le soleil brûlant."
  },
  AvgDialog_13054_Content_3 = {
    Text = "Après une troisième tentative de réveil qui ne résulta qu'en un changement inexplicable de la scène, vous acceptiez enfin que vous étiez piégé dans les souvenirs d'Ogier."
  },
  AvgDialog_13054_Content_30 = {
    Text = "—Tu ne savais pas qu'un des partenaires d'entraînement était Ogier."
  },
  AvgDialog_13054_Content_32 = {Text = "Hmm...!"},
  AvgDialog_13054_Content_33 = {
    Text = "Face à un écart de pouvoir absolu, la persistance et la foi sont vaines. Le chevalier adulte n'a même pas utilisé toute sa force, et pourtant la résonance métallique a déjà affaibli la prise d'Ogier."
  },
  AvgDialog_13054_Content_34 = {
    Text = "La lance fut renversée, et le jeune homme, trempé de sueur, s'agenouilla sur le sol rugueux en haletant."
  },
  AvgDialog_13054_Content_35 = {
    Text = "Gamin, retourne pour l’instant. Si tu continues à pratiquer comme ça, tu finiras par te casser la main."
  },
  AvgDialog_13054_Content_36 = {
    Text = "C'est exact, vous êtes encore trop jeune.\nRevenez pour l'entraînement dans quelques années. Vous ne pouvez même pas soulever une arme en ce moment."
  },
  AvgDialog_13054_Content_37 = {Text = "Non..."},
  AvgDialog_13054_Content_38 = {
    Text = "Ogier trembla, se pencha pour ramasser la lance tombée, et avec un grand effort, ajusta sa position, pointant la tête de la lance vers le chevalier d'entraînement."
  },
  AvgDialog_13054_Content_39 = {
    Text = "Je peux... tenir bon !"
  },
  AvgDialog_13054_Content_4 = {
    Text = "Vous vous tenez dans un coin de la Chambre de la Princesse, faisant semblant d'écouter et jouant docilement le rôle d'un attendant."
  },
  AvgDialog_13054_Content_40 = {
    Text = "Enfant têtu..."
  },
  AvgDialog_13054_Content_41 = {
    Text = "Le visage du garçon devient rouge d'épuisement et de privation d'oxygène. La personne qui avait prévu de faire abandonner Ogier par l'entraînement finit par parler, face à une volonté si forte."
  },
  AvgDialog_13054_Content_42 = {
    Text = "Pas mal du tout. Les étrangers convoitent notre duché avec avidité. Nous avons besoin de plus d'enfants loyaux comme le Jeune Maître Danske."
  },
  AvgDialog_13054_Content_43 = {
    Text = "Dois-je être sérieux ?"
  },
  AvgDialog_13054_Content_44 = {
    Text = "Ne sois pas si imprudent ! Si cet enfant s'effondre à cause de l'entraînement, comment expliqueras-tu cela au Grand Duc et à la Princesse ?"
  },
  AvgDialog_13054_Content_45 = {
    Text = "Commencez avec un entraînement physique de base. Gardez un œil sur lui et assurez-vous qu'il ne se blesse pas avec les armes."
  },
  AvgDialog_13054_Content_46 = {
    Text = "Les mots du leader ont enflammé Ogier. Les yeux du jeune homme se sont illuminés instantanément, débordant d'excitation."
  },
  AvgDialog_13054_Content_47 = {
    Text = "As-tu accepté que je rejoigne les Chevaliers ?!"
  },
  AvgDialog_13054_Content_48 = {
    Text = "Même sans la blague du Grand Duc, avec ce niveau de volonté, vous êtes qualifié pour être un apprenti chevalier."
  },
  AvgDialog_13054_Content_49 = {
    Text = "Voyant les abrasions et les taches de sang sur le garçon, le capitaine a hésité, se sentant quelque peu réticent."
  },
  AvgDialog_13054_Content_5 = {
    Text = "Princesse, princesse! J'ai entendu que le jeune maître de Dansk a encore signalé aux chevaliers. C'est le troisième jour!"
  },
  AvgDialog_13054_Content_50 = {
    Text = "Rentre pour aujourd'hui. À partir de demain, je te donnerai un plan d'entraînement personnalisé - Et vous tous ! Arrêtez de spectatoriser et faites deux séries supplémentaires d'exercices avec poids !"
  },
  AvgDialog_13054_Content_51 = {
    Text = "Épargnez-nous, Capitaine—"
  },
  AvgDialog_13054_Content_52 = {
    Text = "Avant que le leader ait fini de parler, la rare atmosphère légère a déclenché de petits actes de rébellion, les jeunes chevaliers relâchant leur stress de cette manière."
  },
  AvgDialog_13054_Content_53 = {
    Text = "Trois tours !"
  },
  AvgDialog_13054_Content_54 = {
    Text = "Au milieu des pleurs incessants, Ogier a finalement relâché la pression et s'est écroulé au sol avec un bruit sourd."
  },
  AvgDialog_13054_Content_55 = {
    Text = "Superbe... Enfin..."
  },
  AvgDialog_13054_Content_56 = {
    Text = "Ogier, pouvons-nous parler ?"
  },
  AvgDialog_13054_Content_57 = {
    Text = "Vous êtes... Seigneur Chambellan ! Vous me voyez dans un état aussi embarrassant, je..."
  },
  AvgDialog_13054_Content_58 = {
    Text = "Ogier se redressa instantanément, son genou éraflé frottant contre le sable, la douleur tordant son expression tendue."
  },
  AvgDialog_13054_Content_59 = {
    Text = "Vous lui avez fait un signe de la main et avez sorti la potion de guérison que la princesse avait glissée dans votre poche à un moment donné."
  },
  AvgDialog_13054_Content_6 = {
    Text = "Il a en fait pris les paroles de son père à cœur... Comment quelqu'un d'aussi jeune peut-il supporter l'entraînement des Chevaliers ?"
  },
  AvgDialog_13054_Content_60 = {
    Text = "Hein... Ça ne fait pas mal ? N'est-ce pas un médicament de guérison ?"
  },
  AvgDialog_13054_Content_61 = {
    Text = "Ceci est un médicament préparé personnellement par la princesse, vraisemblablement avec un traitement spécial."
  },
  AvgDialog_13054_Content_62 = {
    Text = "\"La princesse que vous servez est une fille mystérieuse. Elle quitte rarement ses quartiers, mais possède une compréhension et un talent uniques pour la médecine. À votre époque, elle serait une pharmacienne renommée.\""
  },
  AvgDialog_13054_Content_63 = {
    Text = "C'est dommage que ses talents aient été mal compris au cours de ces siècles perdus. Vous avez entendu d'autres assistants l'appeler secrètement \"sorcière\" plus d'une fois."
  },
  AvgDialog_13054_Content_64 = {
    Text = "Potion de la Princesse?! Elle est trop précieuse pour être utilisée sur moi—Aïe!"
  },
  AvgDialog_13054_Content_65 = {
    Text = "Ne bouge pas, ou tu vas gaspiller la miséricorde de la princesse.\nAssieds-toi d'abord et laisse-moi finir de traiter la blessure."
  },
  AvgDialog_13054_Content_66 = {
    Text = "Craignant de gaspiller le précieux médicament, Ogier finit par s'asseoir tranquillement.\nLes autres chevaliers quittèrent progressivement la zone, profitant de cette rare occasion."
  },
  AvgDialog_13054_Content_67 = {
    Text = "Ogier, peux-tu sentir que tu es en train de rêver ?"
  },
  AvgDialog_13054_Content_68 = {
    Text = "En effet, c'est comme un rêve..."
  },
  AvgDialog_13054_Content_69 = {
    Text = "Le jeune homme tordit vos mots pour les adapter à la situation actuelle. Il ferma les yeux et soupira, sa voix remplie de satisfaction et de désir."
  },
  AvgDialog_13054_Content_7 = {
    Text = "Non... non, attends... peut-être qu'il y a une autre possibilité."
  },
  AvgDialog_13054_Content_70 = {
    Text = "Invoqué, choisi et reconnu par les chevaliers... On a vraiment l'impression de rêver."
  },
  AvgDialog_13054_Content_71 = {
    Text = "<LightGray:(Devrais-je lui dire directement que c'est un rêve ? Mais je n'ai pas encore compris l'essence ici. Est-ce un souvenir ou un rêve...?)>"
  },
  AvgDialog_13054_Content_72 = {
    Text = "Votre hésitation a attiré l'attention d'Ogier. Il est soudain devenu un peu mal à l'aise, frottant nerveusement l'ourlet de ses vêtements."
  },
  AvgDialog_13054_Content_73 = {
    Text = "Monsieur le Chambellan, est... est-ce que la princesse n'est pas satisfaite de moi ?"
  },
  AvgDialog_13054_Content_74 = {Text = "新增"},
  AvgDialog_13054_Content_75 = {
    Text = "Ogier est l'enfant d'un noble qui aurait pu mener une vie de luxe. Pourquoi insiste-t-il pour devenir chevalier ?"
  },
  AvgDialog_13054_Content_76 = {
    Text = "Parce que... parce que..."
  },
  AvgDialog_13054_Content_77 = {
    Text = "La voix d'Ogier est devenue plus silencieuse et sa tête s'est abaissée davantage par embarras. La réponse à la question lui a clairement fait ressentir trop de honte pour parler."
  },
  AvgDialog_13054_Content_78 = {
    Text = "Je jure, notre conversation restera inconnue de tout tiers."
  },
  AvgDialog_13054_Content_79 = {
    Text = "Parce que... mon père est aussi malade, tout comme tante Merlyn dans la cuisine et frère Pedro, le jardinier..."
  },
  AvgDialog_13054_Content_8 = {
    Text = "D'après la description de la femme de chambre, Ogier suit une formation avec l'ordre des chevaliers. Étant donné qu'Ogier n'a pas participé à cette conversation, l'hypothèse concernant « les souvenirs d'Ogier » ne peut pas être établie."
  },
  AvgDialog_13054_Content_80 = {
    Text = "Il y a beaucoup, beaucoup d'autres qui ont contracté la même maladie."
  },
  AvgDialog_13054_Content_81 = {
    Text = "Mon père ne peut plus quitter son lit, et je n'ai pas encore grandi... En tant qu'enfant unique, je..."
  },
  AvgDialog_13054_Content_82 = {
    Text = "Si le Père décède, tout le monde dans le manoir sera renvoyé.\nIls sont tous encore malades... sans endroit où aller."
  },
  AvgDialog_13054_Content_83 = {
    Text = "Je dois... Je dois prendre la responsabilité de tout le monde... Ce n'est qu'en devenant chevalier et en obtenant la protection du Duc..."
  },
  AvgDialog_13054_Content_84 = {
    Text = "En disant cela, le visage d'Ogier devint pâle. Il te regarda anxieusement, comme s'il avait peur que tu l'accuses de \"motifs impurs\" ou que tu le punisses au nom de la princesse."
  },
  AvgDialog_13054_Content_85 = {
    Text = "Innocence similaire, volonté identique et inébranlable.\nSans aucun doute, il est l'Ogier que vous connaissez."
  },
  AvgDialog_13054_Content_86 = {
    Text = "Désolé, Votre Excellence... Si, si vous souhaitez que la princesse me remplace... je-je n'ai aucune objection..."
  },
  AvgDialog_13054_Content_87 = {
    Text = "La nuit où tu as été choisi par le Grand Duc, tu as juré sur l'honneur de ta famille devant tous les invités, n'est-ce pas ?"
  },
  AvgDialog_13054_Content_88 = {
    Text = "Jure d'accomplir tes devoirs de chevalier avec ta vie... Étais-tu sincère lorsque tu as récité le serment avec les autres ?"
  },
  AvgDialog_13054_Content_89 = {
    Text = "<Big:Bien sûr ! Je ne rigole pas !>"
  },
  AvgDialog_13054_Content_9 = {
    Text = "Ce n'est pas juste une \"mémoire.\" Peut-être es-tu entré dans un morceau d'histoire réelle, ou peut-être est-ce un rêve complété par ton subconscient ?"
  },
  AvgDialog_13054_Content_90 = {
    Text = "\"Je serai toujours loyal, toujours dévoué\"... Mon père s'attendrait à la même chose de moi."
  },
  AvgDialog_13054_Content_91 = {
    Text = "D'accord, je ne dirai rien à la princesse à ce sujet.\nNe t'inquiète pas tant, tu es sur le point de pleurer."
  },
  AvgDialog_13054_Content_92 = {
    Text = "Y a-t-il... vraiment ?! Excusez-moi !"
  },
  AvgDialog_13054_Content_93 = {
    Text = "Ugh... Ugh?! Mes yeux... ils me font mal..."
  },
  AvgDialog_13054_Content_94 = {
    Text = "Ogier s'est frotté maladroitement les yeux, mais son mouchoir était déjà devenu poussiéreux pendant l'entraînement, ajoutant à son embarras."
  },
  AvgDialog_13054_Content_95 = {
    Text = "Je ne peux pas croire que le Chambellan m'ait vu dans un état aussi embarrassant..."
  },
  AvgDialog_13054_Content_96 = {
    Text = "Ce n'est rien, je t'ai déjà vu dans un état pire.\nRetournons au palais et rafraîchissons-toi. Tu ne peux pas rentrer chez toi comme ça."
  },
  AvgDialog_13054_Content_97 = {Text = "新增"},
  AvgDialog_13054_Content_98 = {
    Text = "Votre Excellence, puis-je vous demander un service ?"
  },
  AvgDialog_13054_Content_99 = {
    Text = "J'aimerais entendre plus de détails."
  },
  AvgDialog_13055_Content_1 = {
    Text = "Fils du passé"
  },
  AvgDialog_13055_Content_10 = {
    Text = "Reconnecter"
  },
  AvgDialog_13055_Content_11 = {
    Text = "Voyant Ogier s'approcher de la perte de contrôle, vous choisissez de ne plus attendre et saisissez fermement ses mains, maintenant couvertes de boue noire."
  },
  AvgDialog_13055_Content_12 = {
    Text = "La Clé d'Argent scintille alors que vous guidez vos tentacules mentaux à travers la tempête de Gnose, à travers des couches d'obscurité, et vous reconnectez avec l'Ogier."
  },
  AvgDialog_13055_Content_13 = {
    Text = "Accompagné d'une douleur aiguë semblable à un choc électrique, des scènes défilent devant vos yeux puis disparaissent instantanément."
  },
  AvgDialog_13055_Content_14 = {
    Text = "Les signes de perte de contrôle se sont retirés comme une marée, et l'état d'Ogier s'est stabilisé. Son visage juvénile montrait un soupçon de fatigue."
  },
  AvgDialog_13055_Content_15 = {
    Text = "Mon seigneur, cette fois... combien de temps ai-je tenu ?"
  },
  AvgDialog_13055_Content_16 = {
    Text = "Le minuteur n’a effectué que la moitié d'une rotation ; après avoir déconnecté le lien, Ogier ne pouvait plus durer plus longtemps que lors de la session d'entraînement précédente."
  },
  AvgDialog_13055_Content_17 = {
    Text = "Hmm... 30 secondes, plus 200 millisecondes."
  },
  AvgDialog_13055_Content_18 = {
    Text = "Comment... comment cela a-t-il pu arriver... !"
  },
  AvgDialog_13055_Content_19 = {
    Text = "Son ton était inquiet, après tout, c'était son idée de proposer la <Yellow:Formation de Rupture de Chaîne>."
  },
  AvgDialog_13055_Content_2 = {
    Text = "Terrains d'Entraînement de l'Université Mythag\nCrépuscule"
  },
  AvgDialog_13055_Content_20 = {
    Text = "Il reste hanté par l'anomalie du jour de la cérémonie de remise de clé, craignant de perdre un jour le contrôle et de tourner sa lance contre toi. Ainsi, il cherche à renforcer sa capacité à rester rationnel sans lien"
  },
  AvgDialog_13055_Content_21 = {
    Text = "Mon seigneur, essayons à nouveau !"
  },
  AvgDialog_13055_Content_22 = {
    Text = "Nous nous entraînons depuis longtemps. Un trop-plein d'entraînement se retournera contre nous."
  },
  AvgDialog_13055_Content_23 = {
    Text = "Les yeux d'Ogier ont vacillé, mais se sont finalement éteints, son ton teinté de reproche."
  },
  AvgDialog_13055_Content_24 = {
    Text = "C'était ma négligence..."
  },
  AvgDialog_13055_Content_25 = {Text = "新增"},
  AvgDialog_13055_Content_26 = {
    Text = "À demain après le déjeuner. Je n'ai aucune tâche d'enquête non plus."
  },
  AvgDialog_13055_Content_27 = {
    Text = "Mon Seigneur !"
  },
  AvgDialog_13055_Content_28 = {
    Text = "Sous le regard excité du chiot, vous traînez votre corps également épuisé jusqu'au dortoir."
  },
  AvgDialog_13055_Content_29 = {
    Text = "Un simple momie lavée repose sur un lit doux, reconnaissante du choix de matériel de literie de Mythag, alors que la conscience s'évanouit lentement..."
  },
  AvgDialog_13055_Content_3 = {
    Text = "La clé argentée scintille alors que vous contrôlez le fil argenté invisible et délicat dans votre esprit, le retirant de la lumière éclatante."
  },
  AvgDialog_13055_Content_30 = {Text = "新增"},
  AvgDialog_13055_Content_31 = {
    Text = "Des mélodies étranges résonnent dans l'obscurité, accompagnées du tintement de coupes en argent. Une atmosphère animée mais élégante emplit le Rêve."
  },
  AvgDialog_13055_Content_32 = {
    Text = "Quel bruit... Qui fait la fête dans les dortoirs en pleine nuit...?"
  },
  AvgDialog_13055_Content_33 = {
    Text = "Vous vous êtes retourné et avez atteint la couverture qui avait été chassée du lit."
  },
  AvgDialog_13055_Content_34 = {
    Text = "Une main s'est tendue dans la Brume, saisissant un nuage lourd d'inconnues, se sentant à la fois réel et irréel."
  },
  AvgDialog_13055_Content_35 = {
    Text = "Oh, te voilà ! Je te cherchais juste."
  },
  AvgDialog_13055_Content_36 = {Text = "Quoi... ?"},
  AvgDialog_13055_Content_37 = {
    Text = "Mes jambes se sentent de nouveau faibles. Pourrais-tu aller voir mon père et ramener mon chevalier ?"
  },
  AvgDialog_13055_Content_38 = {
    Text = "Chevalier... ?"
  },
  AvgDialog_13055_Content_39 = {
    Text = "Que fais-tu à attendre ? Tu n'as pas entendu ce que la princesse a dit ?"
  },
  AvgDialog_13055_Content_4 = {Text = "Hmm...!"},
  AvgDialog_13055_Content_40 = {
    Text = "La femme vous tapa soudainement sur l'épaule. Les ténèbres se dissipèrent, révélant un endroit inconnu."
  },
  AvgDialog_13055_Content_41 = {
    Text = "Un grand hall, un groupe jouant des suites anciennes au loin, des desserts exquis et tentants, et des nobles dames qui vous regardent."
  },
  AvgDialog_13055_Content_42 = {
    Text = "Et la fille allongée sur le canapé moelleux, entourée par eux."
  },
  AvgDialog_13055_Content_43 = {
    Text = "Ce n'est rien, ne soyez pas trop sévère envers {Male=him,Female=her}. Mon intendant·e s'est affairé·e toute la nuit sans repos pour offrir un banquet parfait à tout le monde."
  },
  AvgDialog_13055_Content_44 = {
    Text = "La fille, souvent appelée princesse par les autres en raison de son statut noble, t'a aidé doucement à sortir de la situation."
  },
  AvgDialog_13055_Content_45 = {
    Text = "Pourrais-tu amener le \"chevalier\" que mon père a désigné pour me rencontrer ? Ensuite, tu pourras te reposer pour la journée, d'accord ?"
  },
  AvgDialog_13055_Content_46 = {
    Text = "Un flot de souvenirs fragmentés se précipite dans votre esprit. Ils sont disjoints et incomplets, mais suffisants pour vous permettre d'assumer le rôle de cette coquille — le seul attendant de la princesse."
  },
  AvgDialog_13055_Content_47 = {
    Text = "...Merci pour ta gentillesse, Princesse."
  },
  AvgDialog_13055_Content_48 = {
    Text = "L'instinct de votre corps vous a poussé à lui faire une révérence. Au milieu des regards envieux ou dédaigneux, vous avez traversé le groupe de nobles vers le hall bondé."
  },
  AvgDialog_13055_Content_49 = {
    Text = "Vous regardez vos mains. La peau est quelques nuances plus foncées que ce que vous gardez normalement caché sous des gants, marquée de légères cicatrices qui indiquent clairement une vie loin du luxe."
  },
  AvgDialog_13055_Content_5 = {
    Text = "Ne vous forcez pas trop. Quand vous ne pouvez plus tenir, Liez-vous avec le Bassin Noir !"
  },
  AvgDialog_13055_Content_50 = {
    Text = "Le vase en métal orné qui passe confirme davantage la sombre suspicion—"
  },
  AvgDialog_13055_Content_51 = {
    Text = "Le reflet montré là n'est pas votre visage."
  },
  AvgDialog_13055_Content_52 = {
    Text = "Votre Excellence ! Êtes-vous venu ici au nom de la Princesse ?"
  },
  AvgDialog_13055_Content_53 = {
    Text = "La femme de chambre qui est sortie de la foule avait des yeux plus perçants que les vôtres, repérant instantanément le \"vous\" familier au milieu de la foule animée."
  },
  AvgDialog_13055_Content_54 = {
    Text = "<Small:Le Duc a choisi un si jeune chevalier ! Vont-ils vraiment permettre à un enfant si jeune de rejoindre l'entraînement des chevaliers ? Je doute qu'il puisse même soulever une arme.>"
  },
  AvgDialog_13055_Content_55 = {
    Text = "<BigItalic:Excusez-moi, veuillez vous écarter. Nous sommes ici par ordre de la Princesse @1 pour demander audience—>"
  },
  AvgDialog_13055_Content_56 = {
    Text = "<Small:Vous ne l'avez pas vu tout à l'heure, mais quand le Duc l'a amené devant tout le monde, son visage est devenu rouge vif de gêne.>"
  },
  AvgDialog_13055_Content_57 = {
    Text = "<BigItalic:Désolé, désolé! L'escorte de la princesse est arrivée!!>"
  },
  AvgDialog_13055_Content_58 = {
    Text = "<Small:Combien de temps faudra-t-il à un enfant comme ça pour devenir un vrai chevalier... Le Duc doit plaisanter, non ?>"
  },
  AvgDialog_13055_Content_59 = {
    Text = "La femme de chambre a habilement ouvert la voie dans la foule par ses mots tout en chuchotant des remarques enjouées à votre attention, vous menant vers le trône."
  },
  AvgDialog_13055_Content_6 = {
    Text = "Je peux... encore... tenir bon..."
  },
  AvgDialog_13055_Content_60 = {
    Text = "Bonjour. Êtes-vous le chambellan ?"
  },
  AvgDialog_13055_Content_61 = {Text = "Tu es... !"},
  AvgDialog_13055_Content_62 = {
    Text = "Je suis le fils aîné de la famille Danske. Éperdument reconnaissant au Grand-Duc pour sa faveur, je suis extrêmement honoré de servir en tant que chevalier de la princesse @1."
  },
  AvgDialog_13055_Content_7 = {
    Text = "Ogier s'est agenouillé ; sans le soutien du lien, il a soutenu son corps avec sa lance pour ne pas tomber"
  },
  AvgDialog_13055_Content_8 = {Text = "Maître..."},
  AvgDialog_13055_Content_9 = {
    Text = "Un liquide noir s'est échappé des coins de ses yeux, des bords de ses lèvres et de ses canaux auditifs. Ses organes avaient été écrasés par une boue noire amorphe, démontrant à quel point la douleur que le garçon endurait était inimaginable."
  },
  AvgDialog_13056_Content_1 = {
    Text = "Nouvelle ballade"
  },
  AvgDialog_13056_Content_10 = {
    Text = "Ne t'approche pas ! Je ne ferai aucune pitié !"
  },
  AvgDialog_13056_Content_100 = {
    Text = "Allons-y. C'est un jour de repos aujourd'hui, et le Marché de l'Est sera animé. Nous pouvons aussi visiter l'orphelinat et prendre des nouvelles des enfants..."
  },
  AvgDialog_13056_Content_101 = {
    Text = "Tu murmurais délibérément ton emploi du temps et quittais le terrain d'entraînement sans souci dans ton cœur."
  },
  AvgDialog_13056_Content_102 = {
    Text = "Maître ! Maître ! S'il vous plaît, dites-moi comment vous le saviez—"
  },
  AvgDialog_13056_Content_103 = {
    Text = "Parce que, vous savez, il va suivre."
  },
  AvgDialog_13056_Content_11 = {
    Text = "Ogier leva sa lance et bloqua les escaliers."
  },
  AvgDialog_13056_Content_12 = {
    Text = "C'est votre dernier avertissement. Quittez le palais maintenant !"
  },
  AvgDialog_13056_Content_13 = {
    Text = "Hé, as-tu entendu ça ? Que disait-il ? \"Veuillez nous demander de partir\" ?"
  },
  AvgDialog_13056_Content_14 = {
    Text = "Hahahaha, c'est hilarant ! Pas étonnant que le duché soit si faible — ils jouent à être des chevaliers avec des enfants."
  },
  AvgDialog_13056_Content_15 = {
    Text = "Parle plus bas, mes oreilles me font mal."
  },
  AvgDialog_13056_Content_16 = {
    Text = "L'officier a ignoré l'avertissement d'Ogier, s'est dirigé vers la porte de la chambre et a regardé Ogier."
  },
  AvgDialog_13056_Content_17 = {
    Text = "Écartez-vous."
  },
  AvgDialog_13056_Content_18 = {
    Text = "Ogier s'efforça de tenir la lance à l'horizontale, tentant de bloquer l'avance de l'officier."
  },
  AvgDialog_13056_Content_19 = {
    Text = "Veuillez partir !"
  },
  AvgDialog_13056_Content_2 = {
    Text = "Des bottes, étincelantes et couvertes de poussière, ont foulé le tapis du palais."
  },
  AvgDialog_13056_Content_20 = {
    Text = "Savais-tu qu'une arme de chevalier ne te convient pas ?"
  },
  AvgDialog_13056_Content_22 = {
    Text = "La résistance est futile face à un pouvoir écrasant.\nL'officier a facilement dévié la lance de l'Ogier et a enfoncé une dague dans sa poitrine."
  },
  AvgDialog_13056_Content_23 = {
    Text = "*Tousse—!*"
  },
  AvgDialog_13056_Content_24 = {
    Text = "Tu vois ça ? C'est la compétence que tu devrais apprendre.\nAprès tout, avec ton pays détruit, tu ne mérites que de rester dans les ruelles sombres, ne voyant jamais la lumière du jour."
  },
  AvgDialog_13056_Content_25 = {
    Text = "Vol, faim et haine mutuelle... tel est votre destin.\nLa lance, symbole de l'honneur chevaleresque, ne vous sera naturellement plus d'aucune utilité à l'avenir."
  },
  AvgDialog_13056_Content_26 = {
    Text = "Le sang a afflué dans la trachée, causant une douleur sourde, comme se noyer sur terre. Chaque respiration était entrecoupée de l'odeur du sang."
  },
  AvgDialog_13056_Content_27 = {
    Text = "Vous voulez sauter par-dessus la table basse, pousser le sergent dans les escaliers et protéger Ogier agenouillé près de la porte. \nMais votre corps tremble soudainement, se raidir et n'obéit plus à vos ordres."
  },
  AvgDialog_13056_Content_28 = {
    Text = "Non... *toux*..."
  },
  AvgDialog_13056_Content_29 = {
    Text = "Je me suis mal exprimé ; vous ne verrez plus cet avenir — vous deviendrez le carburant de ce palais, tout comme lui."
  },
  AvgDialog_13056_Content_3 = {
    Text = "C'est votre tapis préféré dans \"Rêves de souvenirs.\" Vous et la bonne bruyante avez passé tout un après-midi à le choisir dans l'entrepôt du Grand Duc et une autre demi-journée à l'aplatir."
  },
  AvgDialog_13056_Content_30 = {
    Text = "La botte blindée a écrasé le corps de Fernando, accompagnée du cliquetis du métal et du bruit aigü des os qui se brisent."
  },
  AvgDialog_13056_Content_31 = {
    Text = "...Juste..."
  },
  AvgDialog_13056_Content_33 = {
    Text = "Chaque muscle poussé par l'adrénaline, il lève soudainement sa lance et charge vers l'ennemi !"
  },
  AvgDialog_13056_Content_34 = {
    Text = "<Big:Ne le touche pas !>"
  },
  AvgDialog_13056_Content_36 = {Text = "Hngh—!"},
  AvgDialog_13056_Content_37 = {
    Text = "La résistance était futile. Son attaque n'a pas seulement échoué à ébranler l'officier mais aussi laissé son dos exposé au scout."
  },
  AvgDialog_13056_Content_38 = {
    Text = "Cet enfant est vraiment têtu. S'il avait fui dès le début, nous n'aurions pas eu le temps de le poursuivre, n'est-ce pas ?"
  },
  AvgDialog_13056_Content_39 = {
    Text = "Petit frère, tu sembles si résolu. Protèges-tu quelque chose ?\nLa princesse est-elle derrière la porte ?"
  },
  AvgDialog_13056_Content_4 = {
    Text = "La princesse quitte rarement sa chambre. S'appuyant sur la balustrade du couloir du deuxième étage, elle vous regarde tous occuper dans le hall avec une attitude détendue. Ogier, ici pour une audience, est si nerveux qu'il ne sait pas où poser ses pieds."
  },
  AvgDialog_13056_Content_40 = {
    Text = "Le sang coulait des oreilles d'Ogier. Il ne pouvait pas entendre chaque mot, mais il a quand même saisi la prononciation la plus cruciale."
  },
  AvgDialog_13056_Content_41 = {
    Text = "Non... ne pars pas..."
  },
  AvgDialog_13056_Content_42 = {
    Text = "La vision commence à blanchir sur les bords, et une certaine force tire la conscience hors du corps juvénile."
  },
  AvgDialog_13056_Content_43 = {
    Text = "Il a rampé en avant, au-dessus du corps de Fernando, passant devant les bottes des officiers et des éclaireurs, jusqu'à ce que ses doigts touchent enfin la lourde porte en bois."
  },
  AvgDialog_13056_Content_44 = {
    Text = "Chaud au toucher, avec un arôme boisé légèrement piquant, une voix douce et attentionnée vient souvent de derrière la porte.\nÀ ce moment, à part le tic-tac de l'horloge à eau, il n'y a aucun son provenant de derrière la porte."
  },
  AvgDialog_13056_Content_45 = {
    Text = "Partir... de cet endroit..."
  },
  AvgDialog_13056_Content_46 = {
    Text = "<Big: Ah——!>"
  },
  AvgDialog_13056_Content_47 = {
    Text = "Cette fois, c'était sa longue lance qui a pénétré profondément dans la chair."
  },
  AvgDialog_13056_Content_48 = {
    Text = "L'arme qui a été moquée par d'innombrables personnes, méprisée par les ennemis, mais jamais abandonnée par son porteur."
  },
  AvgDialog_13056_Content_49 = {
    Text = "La lance perça son corps, le clouant à la porte, l'empêchant de bouger."
  },
  AvgDialog_13056_Content_5 = {
    Text = "Pas un chevalier de duché... Vite, cache-toi !"
  },
  AvgDialog_13056_Content_50 = {
    Text = "Ow—ne sois pas si cruel.\nQue se passera-t-il si la \"Princesse Sorcière\" nous maudit pour avoir tourmenté son chevalier ainsi ?"
  },
  AvgDialog_13056_Content_51 = {
    Text = "Une sorcière ? Ridicule."
  },
  AvgDialog_13056_Content_52 = {
    Text = "<Small:@1Princesse... pas...>"
  },
  AvgDialog_13056_Content_53 = {
    Text = "Ogier ouvrit la bouche, le nom de la princesse au bout de sa langue, pourtant il ne put tout simplement pas se résoudre à le dire."
  },
  AvgDialog_13056_Content_54 = {
    Text = "<Small:@1...>"
  },
  AvgDialog_13056_Content_55 = {
    Text = "Il a entendu le son de l'eau qui coule. L'horloge à eau avait-elle été renversée ? Cela signifiait-il...@1 que la princesse était encore en vie ?"
  },
  AvgDialog_13056_Content_56 = {
    Text = "<Small:Non... ne... non... n'entre pas...>"
  },
  AvgDialog_13056_Content_57 = {
    Text = "Assez... Ogier... Merci..."
  },
  AvgDialog_13056_Content_58 = {
    Text = "Merci... mon..."
  },
  AvgDialog_13056_Content_59 = {
    Text = "Des ruisseaux noirs ont d'abord infiltré sous la porte, se mêlant au sang d'Ogier, comme des larmes pleurées pour quelqu'un."
  },
  AvgDialog_13056_Content_6 = {
    Text = "Attends ! Et toi ?!"
  },
  AvgDialog_13056_Content_60 = {
    Text = "Puis, une vague massive, semblable à un déluge, éclata à travers les fissures de la porte, rugissant et déferlant, engloutissant instantanément le palais."
  },
  AvgDialog_13056_Content_61 = {
    Text = "<Shake:Ouf—Ouf !>"
  },
  AvgDialog_13056_Content_62 = {
    Text = "La peste, invisible aux gens ordinaires, a déferlé sur les deux alors qu'une boue noire inondait leurs sens et les noyait dans l'air."
  },
  AvgDialog_13056_Content_63 = {
    Text = "<Shake: Malédiction, c'est une malédiction—>"
  },
  AvgDialog_13056_Content_65 = {
    Text = "Gardien ? Réveille-toi, Gardien ? %player% ?"
  },
  AvgDialog_13056_Content_66 = {Text = "Ogier !"},
  AvgDialog_13056_Content_67 = {
    Text = "Avoir un cauchemar ? Regardez de plus près. Qui suis-je ?"
  },
  AvgDialog_13056_Content_68 = {
    Text = "...Poupée ? Que fais-tu dans ma chambre ?"
  },
  AvgDialog_13056_Content_69 = {
    Text = "Je me fous du contenu de ton cauchemar, mais la nuit dernière, tes ondes spirituelles étaient actives comme si elles dansaient."
  },
  AvgDialog_13056_Content_7 = {
    Text = "Ogier vous pousse violemment, vous forçant sous la table basse.\nVotre vision tourne, et tout ce que vous pouvez voir est le luxuriant tapis persan se courbant sur les bords à cause des flammes."
  },
  AvgDialog_13056_Content_70 = {
    Text = "Les Réveilleurs liés à vous, y compris moi, ont plus ou moins ressenti quelque chose d'anormal."
  },
  AvgDialog_13056_Content_71 = {
    Text = "La nuit dernière ? ...Il n'y a qu'une seule nuit qui s'est écoulée. Cela aurait-il vraiment pu être juste un rêve ?"
  },
  AvgDialog_13056_Content_72 = {
    Text = "Tu décris tout dans le rêve absurde à la Poupée.\nDes princesses, des chevaliers, des fléaux..."
  },
  AvgDialog_13056_Content_73 = {
    Text = "Parmi les Enquêteurs liés aux Réveilleurs, les instants de résonance mémoire et émotionnelle sont rares. Mais ce que vous avez décrit... Je n'en ai jamais entendu parler."
  },
  AvgDialog_13056_Content_74 = {
    Text = "Il semble que cette \"entrée de rêve\" ne t'ait causé aucun effet supplémentaire. Je vais continuer à surveiller de près ta forme d'onde mentale."
  },
  AvgDialog_13056_Content_75 = {
    Text = "...Peut-être, voudrais-tu rencontrer Ogier maintenant ?"
  },
  AvgDialog_13056_Content_76 = {
    Text = "La sensation d'être dévoré par D-boue était trop réelle. La lumière du matin réchauffait les couvertures, mais le corps avait l'impression d'être tombé dans un abîme glacé."
  },
  AvgDialog_13056_Content_77 = {
    Text = "Ogier... Oui, j'ai organisé plus d'entraînements avec lui aujourd'hui..."
  },
  AvgDialog_13056_Content_78 = {
    Text = "Terrain d'Entraînement de l'Université Mythag\nMatin"
  },
  AvgDialog_13056_Content_79 = {
    Text = "Whoa—Non, non, non, je vais mourir—"
  },
  AvgDialog_13056_Content_8 = {
    Text = "Est-ce juste cet enfant ? Sommes-nous arrivés au bon endroit ?"
  },
  AvgDialog_13056_Content_80 = {
    Text = "Épargne-moi, épargne cette pauvre petite journaliste, Monsieur Ogier—"
  },
  AvgDialog_13056_Content_81 = {
    Text = "Miss Hannah, tiens bon un peu plus longtemps. Il reste seulement un tour. \nTu vas certainement réussir ce test de condition physique !"
  },
  AvgDialog_13056_Content_82 = {
    Text = "Bouhou... D'accord..."
  },
  AvgDialog_13056_Content_83 = {
    Text = "La courtière du campus, avec des sacs de sable attachés à ses mollets, pleurait tout en faisant du jogging autour du terrain d’entraînement.\nOgier joggait à ses côtés, l'encourageant et maintenant son rythme sans effort, sans transpirer."
  },
  AvgDialog_13056_Content_84 = {Text = "Ogier"},
  AvgDialog_13056_Content_85 = {Text = "Gardien !"},
  AvgDialog_13056_Content_86 = {
    Text = "Il a assigné la supervision des tâches de Hannah à d'autres employés et a couru vers vous."
  },
  AvgDialog_13056_Content_87 = {
    Text = "Tu n'as pas dit que notre entraînement commence l'après-midi ? Pourquoi es-tu ici si tôt ?"
  },
  AvgDialog_13056_Content_88 = {
    Text = "Lui et les autres étudiants, les Réveilleurs, ont été sur le terrain d'entraînement toute la matinée, pourtant ils ne montrent aucun signe de fatigue, vous regardant avec vénération et énergie."
  },
  AvgDialog_13056_Content_89 = {Text = "Je..."},
  AvgDialog_13056_Content_9 = {
    Text = "C'est exact, c'est clairement marqué sur la carte stratégique - voici les quartiers des femmes."
  },
  AvgDialog_13056_Content_90 = {
    Text = "... Après l'entraînement de Hannah, explorons le centre-ville de Londinium."
  },
  AvgDialog_13056_Content_91 = {Text = "Huh ?"},
  AvgDialog_13056_Content_92 = {
    Text = "Ogier ne s’attendait clairement pas à ce que vous suggériez soudainement de faire une pause, et vous non plus."
  },
  AvgDialog_13056_Content_93 = {
    Text = "Maître, veuillez me permettre de refuser. La crise de Dissolution est imminente. Je... ne suis pas encore prêt."
  },
  AvgDialog_13056_Content_94 = {
    Text = "Plutôt que de m'adonner au loisir, je souhaite me concentrer davantage sur l'amélioration de mes compétences en arts martiaux."
  },
  AvgDialog_13056_Content_95 = {
    Text = "Disons cela autrement."
  },
  AvgDialog_13056_Content_96 = {
    Text = "Cet après-midi passé avec lui dans les Chevaliers m'est soudainement revenu à l'esprit. Des souvenirs que vous pensiez s'effacer avec le rêve resurgissent."
  },
  AvgDialog_13056_Content_97 = {
    Text = "Maintenant est le moment de réaliser ton souhait, Monsieur le Chevalier."
  },
  AvgDialog_13056_Content_98 = {Text = "!?"},
  AvgDialog_13056_Content_99 = {
    Text = "Comment... Comment as-tu su cela ?!"
  },
  AvgDialog_130571_Content_1 = {
    Text = "Bam——————"
  },
  AvgDialog_130571_Content_10 = {
    Text = "Ah, ah... petit charbon, désolé... Mosk, j'ai écrasé."
  },
  AvgDialog_130571_Content_11 = {
    Text = "Ce n'est rien, c'est juste que Mosk, pourquoi es-tu entré si soudainement ?"
  },
  AvgDialog_130571_Content_12 = {
    Text = "Ah ! Mosk, chaud ! Câlin petit charbon, agréable !"
  },
  AvgDialog_130571_Content_13 = {
    Text = "Mosk, c'est étrange, car ce n'est plus froid."
  },
  AvgDialog_130571_Content_14 = {
    Text = "Mais, il fait si chaud, si chaud…"
  },
  AvgDialog_130571_Content_15 = {
    Text = "(Est-ce que c'est cassé, serait-ce l'influence de la rivière sacrée ?)"
  },
  AvgDialog_130571_Content_16 = {
    Text = "Mosk, je ne sais pas..."
  },
  AvgDialog_130571_Content_17 = {
    Text = "Le regard de Mosk devient de plus en plus flou, ses doigts fins s'insèrent dans les interstices de tes vêtements, caressant doucement ta peau."
  },
  AvgDialog_130571_Content_18 = {
    Text = "Tu es très familier avec cette sensation, dans ce rêve, «petit charbon» profite de ce service de caresses dans les bras de Mosk de temps en temps."
  },
  AvgDialog_130571_Content_19 = {
    Text = "petit charbon, serre dans ses bras, calme~"
  },
  AvgDialog_130571_Content_2 = {
    Text = "petit charbon, câlin——"
  },
  AvgDialog_130571_Content_20 = {
    Text = "petit charbon, odeur, agréable~"
  },
  AvgDialog_130571_Content_21 = {
    Text = "Mosk sent doucement sur vous, vous n'êtes pas sûr s'il s'agit du parfum restant sur vous ou si c'est votre propre singularité qui a apaisé Mosk."
  },
  AvgDialog_130571_Content_22 = {
    Text = "Mais tu comprends, tu ne peux pas laisser Mosk continuer comme ça."
  },
  AvgDialog_130571_Content_23 = {
    Text = "Le sol est dur, ton dos proteste, il manque le lit moelleux."
  },
  AvgDialog_130571_Content_24 = {
    Text = "Alors ce soir, serre-moi dans tes bras, dormons ensemble ?"
  },
  AvgDialog_130571_Content_25 = {
    Text = "Oui ! Petit charbon, j'aime ! Un câlin !"
  },
  AvgDialog_130571_Content_26 = {
    Text = "En tenant petit charbon, dors, dors ~"
  },
  AvgDialog_130571_Content_27 = {
    Text = "Tu as profité de l'occasion pour t'allonger avec Mosk sur le lit moelleux, vous vous êtes enlacés, vous vous êtes regardés dans les yeux, comme à l'époque sur le bateau."
  },
  AvgDialog_130571_Content_28 = {
    Text = "Mosk, ce n'est plus chaud~ Mosk, c'est tellement confortable~"
  },
  AvgDialog_130571_Content_29 = {
    Text = "Bonne nuit……zzz……petit charbon……zzz"
  },
  AvgDialog_130571_Content_3 = {
    Text = "Mok, Mosk ?"
  },
  AvgDialog_130571_Content_4 = {
    Text = "Mosk entre soudainement dans la pièce avec vivacité, ses mains entourant ta taille, ses longs cheveux argentés frottant sans cesse contre ta poitrine."
  },
  AvgDialog_130571_Content_5 = {
    Text = "Tu pousses un discret soupir de soulagement. Il semble qu'elle ait eu la prévoyance de rétracter l'« objet horrifique » sur sa main gauche, t'épargnant le risque d'une morsure accidentelle."
  },
  AvgDialog_130571_Content_6 = {
    Text = "petit charbon, confortable——"
  },
  AvgDialog_130571_Content_7 = {
    Text = "Mosk, attends, attends un instant, ah——"
  },
  AvgDialog_130571_Content_8 = {Text = "Dong."},
  AvgDialog_130571_Content_9 = {
    Text = "Malheureusement, comme tu le pensais, Mosk n'a pas bien contrôlé sa force, et vous êtes tombés ensemble au sol."
  },
  AvgDialog_131200_Content_1 = {
    Text = "Menottes douces"
  },
  AvgDialog_131200_Content_10 = {
    Text = "Arachne caressait la moitié restante de la joue de la fille. Alors qu'elle fermait doucement les yeux de la fille, le grand lampadaire derrière elle émettait une lueur faible."
  },
  AvgDialog_131200_Content_11 = {
    Text = "Arachne tendit la main. Un peu de cendre résiduelle dans le lampadaire tourbillonne comme du sable emporté par le vent, dansant et s'écoulant autour de ses doigts délicats, puis se répandant sur le sol."
  },
  AvgDialog_131200_Content_12 = {
    Text = "Les cendres de dimension restantes... notre perception n’a pas trompé, ici était autrefois l’endroit où Nefraea cachait ses cendres, mais maintenant, les cendres ont été emportées par elle."
  },
  AvgDialog_131200_Content_13 = {
    Text = "Emporter les cendres, tuer les pairs secrets, que veut vraiment Nefraea..."
  },
  AvgDialog_131200_Content_14 = {Text = "Hmm?"},
  AvgDialog_131200_Content_15 = {
    Text = "Il semble que quelque chose ait effrayé Arachne. Elle leva la tête et regarda à travers le vitrail peint avec le symbole de la lanterne, en direction de la plateforme non loin."
  },
  AvgDialog_131200_Content_16 = {
    Text = "Arachne ? Qu'est-ce qui t'arrive ?"
  },
  AvgDialog_131200_Content_17 = {
    Text = "Le souffle de l'entité... je ne peux plus le percevoir."
  },
  AvgDialog_131200_Content_18 = {Text = "!!!"},
  AvgDialog_131200_Content_19 = {
    Text = "Vous voulez dire que vous avez quitté le théâtre ?"
  },
  AvgDialog_131200_Content_2 = {
    Text = "Doigts, mollets, globes oculaires, côtes, crâne... Le maître a coupé son précieux jouet et l'a jeté dans la substance collante et le sang."
  },
  AvgDialog_131200_Content_20 = {
    Text = "Alors que nous cherchions des artefacts secrets, ma forme originelle traquait les serviteurs des Abîmes le long des fils de la ville. Après avoir appris la localisation de « le Souvenir », elle se rendit à l'église pour nous accueillir."
  },
  AvgDialog_131200_Content_21 = {
    Text = "Son souffle était déjà très proche... mais maintenant, ce souffle a disparu."
  },
  AvgDialog_131200_Content_22 = {
    Text = "Ne me dites pas... qu'elle a subi un accident ? Mais le « souvenir » vient à peine de mourir, comment cela pourrait-il..."
  },
  AvgDialog_131200_Content_23 = {
    Text = "Je ne sais pas exactement ce qui s'est passé. Mais avant de disparaître, elle a touché le réseau qui me permettait de communiquer avec elle. Hormis les instructions de retour, le dernier message qu'elle a laissé était un mot."
  },
  AvgDialog_131200_Content_24 = {
    Text = "«Plaisir»."
  },
  AvgDialog_131200_Content_25 = {
    Text = "Plaisir... ?"
  },
  AvgDialog_131200_Content_26 = {
    Text = "Devant toi se dessine ce visage haïssable avec un sourire."
  },
  AvgDialog_131200_Content_27 = {
    Text = "Je ne comprends pas... Vous avez la même mémoire, vous devez savoir ce qu'elle veut exprimer."
  },
  AvgDialog_131200_Content_28 = {
    Text = "Arachne secoue doucement la tête."
  },
  AvgDialog_131200_Content_29 = {
    Text = "Votre destin est un papillon que je n'ose toucher ; toute explication provoquerait des ondulations incommensurables."
  },
  AvgDialog_131200_Content_3 = {
    Text = "«Souvenir»..."
  },
  AvgDialog_131200_Content_30 = {
    Text = "Mais vous devez savoir que dans votre court avenir, « Plaisir » est une clé qui déverrouillera les mystères auxquels vous êtes confronté."
  },
  AvgDialog_131200_Content_31 = {
    Text = "Mon... avenir ? Vous voulez dire que vous pouvez réellement voir mon Fil du Destin maintenant ?!"
  },
  AvgDialog_131200_Content_32 = {
    Text = "Vous soutenez son regard. Dans ce doux sourire, vous percevez l'autorité indéniable du Destin."
  },
  AvgDialog_131200_Content_33 = {
    Text = "...Quoi qu'il arrive, fais-moi confiance, et fais-toi confiance aussi."
  },
  AvgDialog_131200_Content_34 = {
    Text = "Retournez au Théâtre du destin. La clé et la serrure vous y attendent, %player%."
  },
  AvgDialog_131200_Content_35 = {Text = "Mais..."},
  AvgDialog_131200_Content_36 = {
    Text = "La voix calme d'Arachne était comme le doux soleil du soir d'automne. Sa silhouette se transforma en un tas de toiles d'araignées, disparaissant dans la lumière silencieuse de l'église."
  },
  AvgDialog_131200_Content_37 = {
    Text = "Sous l'éclat kaléidoscopique des vitraux, seules des braises dimensionnelles dérivent au-dessus du sang et des membres tranchés."
  },
  AvgDialog_131200_Content_38 = {
    Text = "«Plaisir»..."
  },
  AvgDialog_131200_Content_39 = {
    Text = "Tu murmures ce mot incompréhensible, te retournant pour voir ces corps mutilés appelés « souvenirs »."
  },
  AvgDialog_131200_Content_4 = {
    Text = "Tu ramasses délicatement les fragments de la fille, la substance collante et le sang sur les membres mutilés imprègnent tes vêtements."
  },
  AvgDialog_131200_Content_40 = {
    Text = "Baignés dans un fluide trouble et une lumière sacrée, les fragments semblent fusionner avec la sainte cathédrale elle-même."
  },
  AvgDialog_131200_Content_41 = {Text = "新增"},
  AvgDialog_131200_Content_42 = {
    Text = "Le chemin de toile d'araignée tremble légèrement, illuminé par la lumière tamisée du théâtre. Au moment où tu poses le pied sur la toile, toutes les marionnettes s'arrêtent de jouer."
  },
  AvgDialog_131200_Content_43 = {
    Text = "Tout le monde dans toutes les dimensions te regarde. Ils sont curieux, ils sont excités, ils sont joyeux et pleins de respect."
  },
  AvgDialog_131200_Content_44 = {
    Text = "C'est une cérémonie d'accueil grandiose et silencieuse. D'innombrables acteurs sont devenus spectateurs, et le seul spectateur est devenu le protagoniste."
  },
  AvgDialog_131200_Content_45 = {
    Text = "Peut-être que suivre les conseils d'Arachne n'est pas une bonne idée..."
  },
  AvgDialog_131200_Content_46 = {
    Text = "Tu serres secrètement la clé en argent et traverses seul ce silence étrange et encombré."
  },
  AvgDialog_131200_Content_47 = {
    Text = "Le nouveau maître du théâtre vous attend, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131200_Content_48 = {
    Text = "L'ombre se rassemble sur la scène en hauteur. Presque par instinct, tu recules rapidement, levant la clé en argent devant toi."
  },
  AvgDialog_131200_Content_49 = {
    Text = "Nouveau maître ?"
  },
  AvgDialog_131200_Content_5 = {
    Text = "Peut-être... peut-être qu'il y a encore un moyen de la sauver... la force du plasmide... la correction du destin..."
  },
  AvgDialog_131200_Content_50 = {
    Text = "Bienvenue au théâtre, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131200_Content_51 = {
    Text = "Arachne, tu......"
  },
  AvgDialog_131200_Content_52 = {
    Text = "Je suis désolé, notre nouvelle histoire a besoin de ta participation."
  },
  AvgDialog_131200_Content_53 = {
    Text = "La toile d'araignée tremble doucement. Le maître du théâtre s'approche de toi lentement, sa voix est toujours aussi douce que le crépuscule."
  },
  AvgDialog_131200_Content_54 = {
    Text = "Sur la scène autour de toi, ces marionnettes identiques à la femme de chambre araignée se retournent et sautent toutes vers toi..."
  },
  AvgDialog_131200_Content_55 = {Text = "!!!"},
  AvgDialog_131200_Content_6 = {
    Text = "Nefraea a détruit ses fils... son destin est déjà terminé, Gardien {Male=Monsieur,Female=Madame}."
  },
  AvgDialog_131200_Content_7 = {
    Text = "Le son du rouet reste calme et lointain."
  },
  AvgDialog_131200_Content_8 = {
    Text = "«Le « souvenir » a aussi été tué par elle, cela signifie-t-il que..."
  },
  AvgDialog_131200_Content_9 = {
    Text = "Nefraea, a déjà le pouvoir de changer le destin de cette scène."
  },
  AvgDialog_131201_Content_1 = {
    Text = "Ouf... ces serviteurs de Nefraea sont vraiment difficiles à gérer..."
  },
  AvgDialog_131201_Content_10 = {
    Text = "Vingt jours plus tard, il commencera à étudier sérieusement ce qui est consigné dans ce livre... À partir de ce moment-là, cette scène accueillera inévitablement le destin de destruction, tout comme les autres scènes."
  },
  AvgDialog_131201_Content_100 = {
    Text = "Le prince héritier et sa femme sont assis à l'arrière d'une voiture décapotable, admirant cette vieille ville. Les gens courent derrière la voiture, se précipitant vers leur destin déjà scellé."
  },
  AvgDialog_131201_Content_11 = {
    Text = "Des souvenirs de ce monde — à la fois nouveaux et étrangement familiers — affluent dans votre esprit. Vous n'avez jamais vu un endroit si vibrant et florissant."
  },
  AvgDialog_131201_Content_12 = {
    Text = "Tu as déjà vécu trop de choses, la fusion a facilement recouvert ce monde prospère avec ce paysage désolé, envahissant ton imagination."
  },
  AvgDialog_131201_Content_13 = {
    Text = "Arachne tendit la main et caressa doucement la lumière du matin projetée à l'entrée de la ruelle. Elle pleurait pour un autre monde sur le point de mourir."
  },
  AvgDialog_131201_Content_14 = {
    Text = "Un monde qui n'a jamais attiré l'attention des dieux... Je n'avais jamais eu une telle imagination auparavant."
  },
  AvgDialog_131201_Content_15 = {
    Text = "Avons-nous encore la chance de changer cela ?"
  },
  AvgDialog_131201_Content_16 = {
    Text = "C'est exactement pourquoi nous sommes ici."
  },
  AvgDialog_131201_Content_17 = {
    Text = "Dis-moi, que dois-je faire ?"
  },
  AvgDialog_131201_Content_18 = {
    Text = "Attends !......"
  },
  AvgDialog_131201_Content_19 = {
    Text = "Vous les avez remarqués, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131201_Content_2 = {
    Text = "Vous vous adossez au mur humide d'une ruelle isolée, haletant pour reprendre votre souffle."
  },
  AvgDialog_131201_Content_20 = {
    Text = "Dehors de la ruelle, un groupe de personnes dont les fluctuations mentales sont clairement différentes de la normale s'approche de vous."
  },
  AvgDialog_131201_Content_21 = {
    Text = "Derrière, au-dessus, devant... de plus en plus d'ennemis apparaissent dans ta perception."
  },
  AvgDialog_131201_Content_22 = {
    Text = "Nous sommes encerclés !..."
  },
  AvgDialog_131201_Content_23 = {
    Text = "Depuis que je suis arrivé sur la scène, je corrige le destin qui a été altéré. Cependant, corriger le destin de tant de personnes n'est pas une tâche facile."
  },
  AvgDialog_131201_Content_24 = {
    Text = "Nefraea a laissé ces personnes pour entraver ma réparation du Destin."
  },
  AvgDialog_131201_Content_25 = {
    Text = "Peut-être que nous avons d'autres solutions..."
  },
  AvgDialog_131201_Content_26 = {
    Text = "Arachne, je suis l'un des exécutants de l'assassinat planifié ici aujourd'hui par le Rassemblement pour la restauration nationale."
  },
  AvgDialog_131201_Content_27 = {
    Text = "Ce monde sera détruit à cause de cette personne, le prince héritier, qui étudie le livre de sorcellerie. Si je réussis, peut-être pourrai-je empêcher cela de se produire"
  },
  AvgDialog_131201_Content_28 = {
    Text = "Ce n'est pas tout à fait correct..."
  },
  AvgDialog_131201_Content_29 = {
    Text = "Là ! Attrapez-les"
  },
  AvgDialog_131201_Content_3 = {
    Text = "Tu n'as pas vu Arachne courir, elle se tient calmement à tes côtés, comme si elle était destinée à se tenir ici, dans cette ruelle, à ce moment-là."
  },
  AvgDialog_131201_Content_30 = {
    Text = "Arachne pince les cordes de la lyre, préparant le serviteur mutant figé à l'entrée de la ruelle, tel une statue."
  },
  AvgDialog_131201_Content_31 = {
    Text = "Au loin, le son d'un cor et d'un saxophone résonne, accompagné du rugissement des voitures, s'approchant lentement."
  },
  AvgDialog_131201_Content_32 = {
    Text = "Le plan d'assassinat a déjà été découvert, personne d'autre ne peut faire cela... Cette personne, le prince héritier, est déjà proche d'ici, si nous ne faisons rien, il sera trop tard"
  },
  AvgDialog_131201_Content_33 = {
    Text = "Arachne te regarde avec des yeux inquiets et, après un moment d'hésitation, elle acquiesce doucement."
  },
  AvgDialog_131201_Content_34 = {
    Text = "Puisque la direction du destin est ainsi... peut-être que tenter de faire un choix pour ce monde est ce que tu devrais accomplir."
  },
  AvgDialog_131201_Content_35 = {
    Text = "Allez. Faites ce que vous devez faire, {Male=Mr.,Female=Miss} Gardien. La vérité du Destin vous sera révélée ici."
  },
  AvgDialog_131201_Content_36 = {
    Text = "Tu n'as pas le temps de réfléchir attentivement aux paroles d'Arachne, tu as hoché la tête et, avec l'aide d'Arachne, tu as foncé hors de la ruelle pour te mêler à la foule tumultueuse."
  },
  AvgDialog_131201_Content_37 = {
    Text = "C'est le Prince Flavien ? L'héritier de l'empire... Je me demande combien peut bien coûter une voiture comme celle–là."
  },
  AvgDialog_131201_Content_38 = {
    Text = "Bah ! Bâtard de voleur ! Chaque centime qu'il dépense a été arraché à notre sang et à notre sueur !"
  },
  AvgDialog_131201_Content_39 = {
    Text = "Si je n'avais pas boité, je serais sûrement mort sur le champ de bataille en chargeant contre cette bande de voleurs"
  },
  AvgDialog_131201_Content_4 = {
    Text = "Après avoir fait des préparatifs si complets... Que veut-elle vraiment faire ?"
  },
  AvgDialog_131201_Content_40 = {
    Text = "Chut ! Il y a des gardes de l'empire partout ici, tu ne veux pas vivre ?"
  },
  AvgDialog_131201_Content_41 = {Text = "新增"},
  AvgDialog_131201_Content_42 = {
    Text = "Lorsque vous parvenez enfin à vous frayer un chemin à travers la foule et arrivez au bord de la rue, une voiture décapotable flambant neuve s'approche lentement de vous."
  },
  AvgDialog_131201_Content_43 = {
    Text = "Le prince héritier, un homme approchant la soixantaine, est assis à l'arrière avec son épouse. Ils saluent gracieusement la foule tout en désignant l'architecture historique de Hewatz."
  },
  AvgDialog_131201_Content_44 = {
    Text = "Même avec vos souvenirs brouillés, vous ne connaissez que trop bien les profondes souffrances que cette maison royale a infligées à cette terre."
  },
  AvgDialog_131201_Content_45 = {
    Text = "Inquiet de l'impact négatif que cela pourrait avoir sur ce monde, tu as arrêté ta main qui s'étendait instinctivement vers la clé en argent, sortant de ta poche le pistolet qui aurait dû y être, te rapprochant de ce véhicule qui avançait lentement."
  },
  AvgDialog_131201_Content_46 = {
    Text = "Hé ! Cet étudiant ! Tu ne peux pas t'approcher..."
  },
  AvgDialog_131201_Content_47 = {
    Text = "Je suis désolé, Votre Altesse, puisque je suis déjà monté sur scène, je dois accomplir ce que ce personnage doit faire"
  },
  AvgDialog_131201_Content_48 = {
    Text = "BANG! BANG BANG!"
  },
  AvgDialog_131201_Content_49 = {
    Text = "Dans cette rue chaotique, l'héritier fier de l'empire n'a pas les mesures de sécurité aussi strictes que tu l'imaginais. Grâce à un entraînement rigoureux, tu t'approches facilement du véhicule et appuies sur la gâchette."
  },
  AvgDialog_131201_Content_5 = {
    Text = "Nefraea a laissé un prologue. Dans ce vaste Toile du destin, elle a pollué un des fils."
  },
  AvgDialog_131201_Content_50 = {
    Text = "Lorsque trois balles traversent précisément la poitrine du grand-duc, le monde entier s'arrête."
  },
  AvgDialog_131201_Content_51 = {
    Text = "Le grand duc souffrant, la princesse choquée, les gardes courant, se sont tous arrêtés de manière burlesque, comme une peinture à l'huile vivante."
  },
  AvgDialog_131201_Content_52 = {
    Text = "!!! C'est..."
  },
  AvgDialog_131201_Content_53 = {
    Text = "Après une brève pause, les couleurs de la peinture à l'huile commencent à couler et à s'entrelacer, le temps, l'espace et la gravité se joignent à cette fête chaotique, ton corps est déchiré, d'innombrables images défilent devant tes yeux."
  },
  AvgDialog_131201_Content_54 = {
    Text = "Des funérailles grandioses. La fureur d'un Roi. La guerre. Les canons. La mort. Le mugissement des cors de guerre et les cris des civils. Des Vautours fondant sur les champs écarlates de Verdun pour se repaître de quatre cent mille dépouilles mutilées."
  },
  AvgDialog_131201_Content_55 = {
    Text = "La chute de l'empire, les terres partagées, le roi déchu, le livre de sorcellerie rouvert..."
  },
  AvgDialog_131201_Content_56 = {
    Text = "Un liquide noir et collant engloutit brièvement ton champ de vision. Cette histoire que tu connais si bien se rejoue, une obscurité totale et une douleur, corrodant chacune de tes cellules..."
  },
  AvgDialog_131201_Content_57 = {
    Text = "Ne vous inquiétez pas, {Male=Mr.,Female=Miss} Gardien. Vous êtes en sécurité maintenant."
  },
  AvgDialog_131201_Content_58 = {
    Text = "Une Main se pose sur votre épaule. Les couleurs chaotiques et sanglantes ainsi que les ténèbres sans fin disparaissent."
  },
  AvgDialog_131201_Content_59 = {
    Text = "Vos yeux s'ouvrent brusquement. Le café est aussi calme que d'habitude ; le pistolet Browning a disparu de votre Main, et la Sachertorte fraîchement servie trône devant vous, exhalant un arôme irrésistible."
  },
  AvgDialog_131201_Content_6 = {
    Text = "Dans cette ligne temporelle corrompue, le prince héritier de l'Empire Féo a découvert un certain livre il y a deux mois."
  },
  AvgDialog_131201_Content_60 = {
    Text = "Arachne... c'est quoi ce qui se passe ?! Nous..."
  },
  AvgDialog_131201_Content_61 = {
    Text = "Pas de panique, nous sommes déjà revenus au moment où nous sommes entrés dans le café. La bonne nouvelle, c'est que nous avons obtenu un café gratuit."
  },
  AvgDialog_131201_Content_62 = {
    Text = "Arachne leva sa tasse de café, souriant en en prenant une gorgée. Sur le liquide brun, se reflète ton visage ahuri."
  },
  AvgDialog_131201_Content_63 = {
    Text = "Les fils du destin ne sont pas des choses que tu peux voir clairement. Les acteurs venant de l'extérieur de la scène, qui tentent de changer de force le destin de ce monde, se perdront dans le filet du destin."
  },
  AvgDialog_131201_Content_64 = {
    Text = "Passé et futur, les innombrables destins de cette scène s'entrelaçant sous vos yeux... voilà le vrai visage de la Toile du destin."
  },
  AvgDialog_131201_Content_65 = {
    Text = "L'avenir du destin... Tu veux dire que tout ce qui vient de se passer est vrai ? Toutes ces guerres, ces morts... c'est moi qui les ai causés ?"
  },
  AvgDialog_131201_Content_66 = {
    Text = "Le Destin vous a permis d'en être témoin. Après l'assassinat du Prince, c'était effectivement le chemin que le monde devait emprunter. Mais soyez rassuré, {Male=Mr.,Female=Miss} Gardien. J'ai déjà retissé le destin de cette scène."
  },
  AvgDialog_131201_Content_67 = {
    Text = "Tu as jeté un coup d'œil par la fenêtre. La foule est toujours animée, mais les citoyens et les policiers influencés par Nefraea ont depuis longtemps disparu."
  },
  AvgDialog_131201_Content_68 = {
    Text = "Si c'était selon ma méthode tout à l'heure... si tu n'avais pas réparé le destin..."
  },
  AvgDialog_131201_Content_69 = {
    Text = "Dans un mois, ce monde sera plongé dans la plus grande guerre de l'histoire à cause de la mort de cet héritier. Huit empires seront impliqués et vingt millions de personnes périront dans ce conflit."
  },
  AvgDialog_131201_Content_7 = {
    Text = "Un livre contenant des sorcelleries mystérieuses, capable de relier des dieux qui n'appartiennent pas à cette dimension."
  },
  AvgDialog_131201_Content_70 = {
    Text = "La terre sous nos pieds va se transformer en cendres, et ces personnes assises à nos côtés dans le café n'ont pas survécu à cette guerre."
  },
  AvgDialog_131201_Content_71 = {
    Text = "Arachne secoue sa tasse de café, regardant la circulation animée de la rue à l'extérieur. Elle raconte calmement, comme si elle présentait un dessert des plus ordinaires."
  },
  AvgDialog_131201_Content_72 = {
    Text = "Les voix animées dans la rue apportent une mélodie de paix et de prospérité à tes oreilles."
  },
  AvgDialog_131201_Content_73 = {
    Text = "Érosion ? Pourquoi ai-je déjà tué cet héritier, et pourtant cela attire toujours l'érosion dans ce monde..."
  },
  AvgDialog_131201_Content_74 = {
    Text = "Dans cette grande guerre, cet empire a été vaincu. Cette personne, le roi, devait initialement accepter la dure proclamation du destin. Mais maintenant, il a un nouveau choix."
  },
  AvgDialog_131201_Content_75 = {
    Text = "Une sorcellerie qui n'appartient pas à ce monde, une divinité qui transcende toute force. Qu'est-ce qui pourrait être plus attirant pour un père en deuil et un souverain déchu ?"
  },
  AvgDialog_131201_Content_76 = {
    Text = "Les paroles douces d'Arachne te firent frissonner. Le poids de deux milliards de vies pèse sur toi comme une matière tangible."
  },
  AvgDialog_131201_Content_77 = {
    Text = "<Shake:Je n'aurais jamais imaginé que l'assassinat d'un prince dégénérerait à ce point... Je pensais aider...>"
  },
  AvgDialog_131201_Content_78 = {
    Text = "Le destin te pousse à faire ce choix, afin que tu puisses le voir clairement. Tu ne peux pas voir les fils, mais tu comprends maintenant comment ces fils s'entrelacent de manière si complexe."
  },
  AvgDialog_131201_Content_79 = {
    Text = "Le fil du destin tisse un immense réseau, chaque léger tremblement de chaque fil pourrait faire basculer le filet du destin."
  },
  AvgDialog_131201_Content_8 = {
    Text = "Arachne leva la tête et regarda les fils que tu ne peux pas voir."
  },
  AvgDialog_131201_Content_80 = {
    Text = "C'est le destin—— un destin si complexe."
  },
  AvgDialog_131201_Content_81 = {
    Text = "Tu prends une profonde inspiration, apaisant ce cœur qui bat violemment à cause de la peur."
  },
  AvgDialog_131201_Content_82 = {
    Text = "Heureusement, tu as arrêté cette guerre..."
  },
  AvgDialog_131201_Content_83 = {
    Text = "Je n'ai pas empêché la guerre, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131201_Content_84 = {
    Text = "Arachne a doucement secoué la tête."
  },
  AvgDialog_131201_Content_85 = {
    Text = "Dans ce nouveau destin, le roi de l'empire verra une petite partie des miracles révélés dans le livre de sorcellerie. Ces forces deviendront son recours pour déclencher la guerre."
  },
  AvgDialog_131201_Content_86 = {
    Text = "Le roi et ses alliés ont lancé une guerre à plus grande échelle, et d'autres empires des continents ont également été entraînés dans ce conflit."
  },
  AvgDialog_131201_Content_87 = {
    Text = "Les personnes mortes dans cette guerre sont quatre fois plus nombreuses qu'à l'origine."
  },
  AvgDialog_131201_Content_88 = {
    Text = "Elle poursuit son récit calme, avec le ton d'une mère racontant une histoire au coucher à un enfant qui ne trouve pas le sommeil."
  },
  AvgDialog_131201_Content_89 = {
    Text = "<Shake:C'est... pourquoi ?>"
  },
  AvgDialog_131201_Content_9 = {
    Text = "Cette scène n'a jamais été connectée aux dieux, elle aurait pu échapper à un destin de fusion pendant longtemps."
  },
  AvgDialog_131201_Content_90 = {
    Text = "Tu as vu la complexité du filet du destin. Tenter de forcer l'évitement de certaines choses inévitables entraînera un cataclysme encore plus grave."
  },
  AvgDialog_131201_Content_91 = {
    Text = "Le Roi est toujours vaincu ; le savoir limité contenu dans ce livre n'offre à l'empire aucun salut durable."
  },
  AvgDialog_131201_Content_92 = {
    Text = "Après ce second échec, la sorcellerie sera rejetée comme une farce. Plus aucun dirigeant sur cette scène ne s'y tournera jamais."
  },
  AvgDialog_131201_Content_93 = {
    Text = "Leur regard s'est tourné vers d'autres choses. Ils croyaient en la science, étudiaient des armes capables de dévorer des planètes, profitant d'une paix éphémère sous la menace de ces armes qu'ils avaient créées, pour finalement être détruits par celles-ci."
  },
  AvgDialog_131201_Content_94 = {
    Text = "Cette scène est toujours destinée à disparaître dans quelque apocalypse future — c'est son destin inéluctable. Mais pendant un temps, ils profiteront d'une période de prospérité aussi belle qu'une œuvre d'art."
  },
  AvgDialog_131201_Content_95 = {
    Text = "Le Regard de Touva Wave sera tenu à distance, au moins pour un temps."
  },
  AvgDialog_131201_Content_96 = {
    Text = "La cuillère d'Arachne tourne lentement dans la tasse, ce tourbillon brun profond est identique à ce que vous avez vu dans la Toile du destin."
  },
  AvgDialog_131201_Content_97 = {
    Text = "Elle baissa la tête. Le soleil à l'extérieur tombait sur elle comme un voile de tristesse."
  },
  AvgDialog_131201_Content_98 = {
    Text = "Lutter, tisser, raccommoder... et pourtant rien ne change vraiment. C'est le Destin, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131201_Content_99 = {
    Text = "La musique de la trompette et du saxophone s'approche de la fenêtre, emportée par les acclamations et les insultes de la foule qui s'éloignent progressivement."
  },
  AvgDialog_131202_Content_1 = {Text = "Clac —"},
  AvgDialog_131202_Content_10 = {
    Text = "Croyant ?..."
  },
  AvgDialog_131202_Content_11 = {
    Text = "La robe violette... Je n'ai jamais... jamais vu..."
  },
  AvgDialog_131202_Content_12 = {
    Text = "Ils ont emporté le «Souvenir» jusqu'à l'autel... tousse, tousse..."
  },
  AvgDialog_131202_Content_13 = {
    Text = "Rue Saint-Vasile... une église qui leur appartient..."
  },
  AvgDialog_131202_Content_14 = {
    Text = "Les os et la chair tremblent, luttent, pressant la dernière force vitale de ce corps en lambeaux."
  },
  AvgDialog_131202_Content_15 = {
    Text = "Il sait que Mademoiselle Arachne ne peut pas voir les fils de ces personnes. Il sait que c'est une tâche qu'il doit accomplir."
  },
  AvgDialog_131202_Content_16 = {
    Text = "Mademoiselle... les malfrats dans l'ombre... nous traquent... elle a falsifié notre destin..."
  },
  AvgDialog_131202_Content_17 = {
    Text = "Ils ont emporté mon sang... Dans cette église, elle va réaliser ce rituel d'horreur..."
  },
  AvgDialog_131202_Content_18 = {
    Text = "Le vengeur du Destin, baigne-toi dans notre Sang... le dieu maléfique des ombres est sur le point de Descendre, et tous les Destins sombреront dans... le... <Shake:Toussotements...><Big:le Chaos total... !>"
  },
  AvgDialog_131202_Content_19 = {
    Text = "Les pupilles du vieillard se dilatèrent soudainement, son corps tremblait de froid et de peur, comme s'il avait vu un enfer plus terrifiant que ses pires cauchemars."
  },
  AvgDialog_131202_Content_2 = {
    Text = "Les araignées se dispersent, la dernière silhouette s'effondre dans la lumière argentée, et le maître de la tempête ne se trouve déjà plus. Toi et Arachne vous tenez devant la silhouette tombée au centre de la pièce."
  },
  AvgDialog_131202_Content_20 = {
    Text = "Il saisit fermement la manche d'Arachne, la regardant avec un regard presque suppliant."
  },
  AvgDialog_131202_Content_21 = {
    Text = "Mademoiselle... J'ai encore l'habitude de vous appeler mademoiselle... Vous avez mis beaucoup de temps à apprendre à parler, cela a beaucoup inquiété le maître et madame..."
  },
  AvgDialog_131202_Content_22 = {
    Text = "Tu me dis adieu, tout le monde se réjouit que tu puisses enfin parler, mais je sais, seulement moi sais... cette phrase est le jugement inéluctable du destin..."
  },
  AvgDialog_131202_Content_23 = {
    Text = "Je suis rentré chez moi, attendant la descente de la mort. Je ne peux pas arrêter de pleurer, non pas pour moi, mais pour vous, mademoiselle Arachne..."
  },
  AvgDialog_131202_Content_24 = {
    Text = "Je sais que vous allez porter une malédiction d'un poids si lourd..."
  },
  AvgDialog_131202_Content_25 = {
    Text = "Des larmes ont coulé sur les joues marquées par les rides du vieillard. Il a tremblé en tenant la main d'Arachne. À travers la lumière floue des larmes, il a vu devant lui la jeune Arachne."
  },
  AvgDialog_131202_Content_26 = {
    Text = "Ce visage enfantin n'a jamais pleuré à haute voix, il regarde toujours le ciel vide avec curiosité, souriant vers ces destins qu'ils ne peuvent pas voir."
  },
  AvgDialog_131202_Content_27 = {
    Text = "Mademoiselle Arachne, veuillez prendre soin d'elle, prenez soin de «Souvenir»... Veuillez surtout prendre soin de vous..."
  },
  AvgDialog_131202_Content_28 = {
    Text = "Ne... te perds pas dans... le réseau..."
  },
  AvgDialog_131202_Content_29 = {
    Text = "La voix de «bienveillance» était presque inaudible à la fin. Lorsque son souffle s'est arrêté, Arachne lui a doucement fermé les yeux."
  },
  AvgDialog_131202_Content_3 = {
    Text = "C'est toi..."
  },
  AvgDialog_131202_Content_30 = {
    Text = "«Reposez-vous maintenant, Monsieur Lawrence...»"
  },
  AvgDialog_131202_Content_31 = {
    Text = "Le coin de la bouche du vieux Edgar se leva doucement. Dans les derniers instants de sa vie, il entendit à nouveau la première phrase prononcée par Arachne dans cette vie."
  },
  AvgDialog_131202_Content_32 = {
    Text = "Il ne demande rien d'autre."
  },
  AvgDialog_131202_Content_33 = {
    Text = "Vous avez utilisé les souvenirs de votre propre majordome pour créer ce Pair secret... il ne ressemble en rien aux autres poupées que vous avez fabriquées. Pourquoi ?"
  },
  AvgDialog_131202_Content_34 = {
    Text = "Peut-être pour commémorer, ou peut-être... pour me consoler moi-même."
  },
  AvgDialog_131202_Content_35 = {
    Text = "Réconfort ?"
  },
  AvgDialog_131202_Content_36 = {
    Text = "Je me réconforte en sachant qu'ils ont toujours été à mes côtés, jamais loin de moi..."
  },
  AvgDialog_131202_Content_37 = {
    Text = "Arachne a calmement lâché le corps brisé du vieillard, sans donner plus d'explications, et tu n'as pas posé d'autres questions. Tu sais que la réponse t'attend pas loin."
  },
  AvgDialog_131202_Content_38 = {
    Text = "Dans cette Toile du destin, la force de Nefraea est liée à eux. Leur mort renforcera le lien entre Nefraea et la toile."
  },
  AvgDialog_131202_Content_39 = {
    Text = "Nous devons l'arrêter avant qu'elle n'obtienne le pouvoir de déchirer la toile. C'est tout ce qui compte maintenant, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131202_Content_4 = {
    Text = "<Shake:Mademoiselle Arachne......Étranger......euh......>"
  },
  AvgDialog_131202_Content_40 = {
    Text = "Les mains d'Arachne caressent le sommet de la tête du vieillard, touchant ce fil presque invisible. À l'autre bout éloigné de cette ville, un faible écho du fil du destin se fait entendre."
  },
  AvgDialog_131202_Content_41 = {
    Text = "Le destin t'a répondu ?"
  },
  AvgDialog_131202_Content_42 = {
    Text = "Arachne hocha la tête. Avant de se lever, elle jeta un dernier regard au visage souriant du vieillard."
  },
  AvgDialog_131202_Content_43 = {
    Text = "« le Souvenir » est encore en vie. Ces invités venus des Abîmes nous attendent."
  },
  AvgDialog_131202_Content_5 = {
    Text = "Le corps devant toi est en partie constitué de chair sanguinolente rongée et en partie de os blancs teintés de rouge."
  },
  AvgDialog_131202_Content_6 = {
    Text = "Le vieux homme a à peine réussi à expulser quelques gouttes de sang encore fraîches avec une violente toux. Un fil invisible était tenu dans la main d'Arachne, précaire comme une flamme de bougie sous une tempête."
  },
  AvgDialog_131202_Content_7 = {
    Text = "Hémostatique... Nous avons besoin de quelque chose pour arrêter le saignement..."
  },
  AvgDialog_131202_Content_8 = {
    Text = "Il est trop tard... Mademoiselle Arachne... Allez la sauver... Allez sauver «Souvenir»..."
  },
  AvgDialog_131202_Content_9 = {
    Text = "Ces croyants... l'ont emmenée..."
  },
  AvgDialog_131203_Content_1 = {
    Text = "Arachne ! Que fais-tu ? C'est ça, ta... confiance ?"
  },
  AvgDialog_131203_Content_10 = {
    Text = "Performance. Tromperie. Duperie."
  },
  AvgDialog_131203_Content_11 = {
    Text = "« Ravissement », tel est votre destin. Montez sur scène, {Male=Mr.,Female=Miss} Gardien. \nSur cette scène, vous achèverez votre propre histoire."
  },
  AvgDialog_131203_Content_12 = {
    Text = "Sur cette scène, tu réaliseras tes souhaits."
  },
  AvgDialog_131203_Content_2 = {
    Text = "William, l'Aîné... I–Il est encore en train de se remettre de ses blessures !..."
  },
  AvgDialog_131203_Content_3 = {
    Text = "Ne vous inquiétez pas, {Male=Mr.,Female=Miss} Gardien. Il n'a rien à voir avec ce fil du Destin. Je l'ai téléporté en lieu sûr."
  },
  AvgDialog_131203_Content_4 = {
    Text = "C'est un destin auquel ni vous ni moi ne pouvons échapper, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131203_Content_5 = {
    Text = "Je ne t'ai jamais raconté de mensonges. Je vais t'emmener sur la scène qui t'appartient, où tu réaliseras ta grande performance."
  },
  AvgDialog_131203_Content_6 = {
    Text = "Arachne s'approche de toi lentement. Tu regardes ses yeux brumeux, espérant y lire les informations qu'elle ne peut pas te transmettre directement."
  },
  AvgDialog_131203_Content_7 = {
    Text = "(qui m'appartient... performance...)"
  },
  AvgDialog_131203_Content_8 = {
    Text = "Une lueur spirituelle traverse ton esprit, semblable à une étoile filante éphémère, disparaissant parmi les fragments chaotiques de ta conscience."
  },
  AvgDialog_131203_Content_9 = {
    Text = "Les servantes de l'araignée froide se dispersent autour, ne s'avançant plus. Arachne lève doucement la main, effleurant les cordes vides de la guitare."
  },
  AvgDialog_131204_Content_1 = {
    Text = "L'éclat argenté tranche les fils comme une lame, profitant de cette ouverture, tu traverses rapidement la ligne de défense des servantes et arrives devant Arachne."
  },
  AvgDialog_131204_Content_10 = {
    Text = "Elle se retourne. Les fils tournent doucement, une impulsion soudaine sans avertissement s'enflamme en toi, te poussant à te lever."
  },
  AvgDialog_131204_Content_11 = {
    Text = "Tu es sûr d'être entièrement autonome, tu es le parfait représentant du libre arbitre. C'est entièrement de ton propre gré que tu suis les pas d'Arachne, marchant avec un rythme et un pas parfaitement alignés avec les siens, en direction de l'extrémité du chemin de la toile."
  },
  AvgDialog_131204_Content_12 = {Text = "新增"},
  AvgDialog_131204_Content_13 = {
    Text = "Oh, bienvenue ! {Male=Mr.,Female=Miss} %player%, mon estimé invité ! Jamais vos pas n'ont résonné de manière aussi mélodieuse."
  },
  AvgDialog_131204_Content_14 = {
    Text = "Le nouveau maître du théâtre fait son entrée, la voix exagérée de Nefraea résonne sur la scène sombre."
  },
  AvgDialog_131204_Content_15 = {
    Text = "Ce n'est pas agréable, n'est-ce pas ? De voir son destin manipulé ? Peu importe, {Male=Mr.,Female=Miss} Gardien. Cette histoire touche à sa fin."
  },
  AvgDialog_131204_Content_16 = {
    Text = "Nefraea, que veux-tu vraiment faire ?..."
  },
  AvgDialog_131204_Content_17 = {
    Text = "Le suspense, c'est exactement ce qui pousse les spectateurs à venir dans ce théâtre ! Mais ne t'inquiète pas, cher."
  },
  AvgDialog_131204_Content_18 = {
    Text = "Mesdames et messieurs ! Préparez vos acclamations... Oh, où est ma marionnette... Ah, je l'ai trouvée"
  },
  AvgDialog_131204_Content_19 = {
    Text = "Que vont offrir à cette scène les grands vengeurs du destin, ayant chassé les trois mystérieuses idoles, comme spectacle riche en imagination ?"
  },
  AvgDialog_131204_Content_2 = {Text = "Compris !"},
  AvgDialog_131204_Content_20 = {
    Text = "Maintenant, contemplez le <Big:<Red:point culminant du deuxième acte !>>"
  },
  AvgDialog_131204_Content_21 = {
    Text = "Je l'appelle « Nouveau-né » —"
  },
  AvgDialog_131204_Content_22 = {Text = "Clac —"},
  AvgDialog_131204_Content_23 = {
    Text = "Un faisceau lumineux éclatant se concentre sur la scène, brisant la brève tranquillité et les ténèbres du théâtre. Une marionnette tenant un rouet monte sur scène."
  },
  AvgDialog_131204_Content_24 = {
    Text = "Nefraea, la déesse de la mort du Gouffre, la vengeresse du Destin...<Shake:Je me suis soumis à votre grande force !>"
  },
  AvgDialog_131204_Content_25 = {
    Text = "C'est la romance, elle rend stupide. C'est la bonté, elle rend fragile. C'est le souvenir... Parmi toutes les belles qualités, le souvenir est la source de toute souffrance."
  },
  AvgDialog_131204_Content_26 = {
    Text = "Je ne peux plus les supporter... Je les offre à vous, grande Nefraea."
  },
  AvgDialog_131204_Content_27 = {
    Text = "Vraiment, grande sœur ? Ma bonne grande sœur..."
  },
  AvgDialog_131204_Content_28 = {
    Text = "Pas de problème, dans ce monde, je suis celui qui te comprend le mieux. N'aie plus de souffrance, confie-moi toutes ces douleurs."
  },
  AvgDialog_131204_Content_29 = {
    Text = "Regarde, la lanterne venue des profondeurs est déjà allumée, sa lumière nous guidera sur le chemin du retour à la maison——"
  },
  AvgDialog_131204_Content_3 = {Text = "Ding—"},
  AvgDialog_131204_Content_30 = {
    Text = "Quelle lumière chaleureuse... mais, où se trouve vraiment le chemin de notre retour ?"
  },
  AvgDialog_131204_Content_31 = {
    Text = "Vous ne comprenez toujours pas ? Ma bonne grande sœur."
  },
  AvgDialog_131204_Content_32 = {
    Text = "Ce rouet est le corps de l'Apôtre. Ces lumières sont le regard de l'Apôtre — Il nous regarde"
  },
  AvgDialog_131204_Content_33 = {
    Text = "«Nefraea» s'est levée avec excitation, les bras ouverts."
  },
  AvgDialog_131204_Content_34 = {
    Text = "Il suffit de rassembler les pouvoirs des trois plasmides, et l'Apôtre anonyme s'éveillera ici"
  },
  AvgDialog_131204_Content_35 = {
    Text = "Il nous ouvrira le passage vers la Divinité suprême... et à ce moment-là, <Big:toutes les souffrances disparaîtront, toutes les peines vaines prendront Fin !>"
  },
  AvgDialog_131204_Content_36 = {
    Text = "«Nefraea» arracha brusquement ce masque en bois, révélant le visage vivant de Nefraea."
  },
  AvgDialog_131204_Content_37 = {
    Text = "La scène en bois, la poupée en bois, le seul corps vivant se tient au milieu de la scène, les bras ouverts, profitant du regard de ce seul spectateur en bas."
  },
  AvgDialog_131204_Content_38 = {
    Text = "Le passage divin est sur le point de s'ouvrir, ta mission va être accomplie, comprends-tu, grande sœur ?"
  },
  AvgDialog_131204_Content_39 = {
    Text = "Tu n'as plus besoin de tisser ton filet sans fin, tu n'as plus besoin de te sacrifier"
  },
  AvgDialog_131204_Content_4 = {
    Text = "Une main délicate s'étend dans l'air et effleure doucement. Les cordes vibrent légèrement, une élégante ondulation se propage dans l'air."
  },
  AvgDialog_131204_Content_40 = {
    Text = "Accepte-moi à nouveau, d'accord, Arachne ? ... Laisse-moi redevenir une partie de toi ..."
  },
  AvgDialog_131204_Content_41 = {
    Text = "Les larmes emportent le maquillage, laissant des marques noires semblables à de la fusion sur son visage. Des rires fous et des pleurs forment un immense filet, enchevêtrant cette personne, le seul individu vivant sur scène.."
  },
  AvgDialog_131204_Content_42 = {
    Text = "Nefraea s'accroupit et souleva la joue lisse sans traits de « Arachne ». Des larmes coulaient le long de ce visage en pleurs, tombant sur le masque souriant de la marionnette."
  },
  AvgDialog_131204_Content_43 = {
    Text = "Elle fixait intensément Arachne en bas de la scène, ses lèvres tremblantes se posant doucement sur l'oreille de la marionnette. Sa voix était si légère, comme si elle se parlait à elle-même."
  },
  AvgDialog_131204_Content_44 = {
    Text = "Ne m'abandonne plus... d'accord ?"
  },
  AvgDialog_131204_Content_5 = {
    Text = "Des ondulations traversent la lumière argentée, la lumière argentée se dissipe, la clé d'argent, porteuse d'une puissante force spirituelle, disparaît sans laisser de trace. Les ondulations traversent ton corps, ton corps se transforme en ossements, ton sang devient de la boue. Tu es démembré, puis tu retrouves ton état initial."
  },
  AvgDialog_131204_Content_6 = {
    Text = "Toute force s'évanouit dans l'invisible, toutes les pensées se réduisent en cendres. Là où les ondulations atteignent, des milliers de mondes se transforment en fils dans ses mains. Y compris toi, toi-même."
  },
  AvgDialog_131204_Content_7 = {
    Text = "Elle est la maîtresse du théâtre. \n Elle est le destin lui-même."
  },
  AvgDialog_131204_Content_8 = {
    Text = "Arachne, tu... tu peux contrôler mon destin ?! ..."
  },
  AvgDialog_131204_Content_9 = {
    Text = "Le sourire d'Arachne est comme un lac paisible, on ne peut pas voir l'apparence du lac, sur cette surface d'eau, on ne peut voir que son propre reflet."
  },
  AvgDialog_131205_Content_1 = {
    Text = "Feu d›armes"
  },
  AvgDialog_131205_Content_10 = {
    Text = "Tu n'as pas besoin de rendre des devoirs."
  },
  AvgDialog_131205_Content_11 = {
    Text = "Maître Arachne, que signifie... ?"
  },
  AvgDialog_131205_Content_12 = {
    Text = "Te souviens-tu de qui tu es et d'où tu viens ?"
  },
  AvgDialog_131205_Content_13 = {
    Text = "Moi ? Je suis bien sûr..."
  },
  AvgDialog_131205_Content_14 = {
    Text = "%player%. Un vrai natif de Hewatz, jusqu›au bout des ongles. Étudiant en première année à l›Académie d›art dramatique. Vos parents sont de simples fonctionnaires qui vous adorent. Vous avez eu deux romances respectables. Passionné, à défaut d›être exceptionnellement talentueux, avec un faible pour la Sachertorte et les wraps de viande grillée."
  },
  AvgDialog_131205_Content_15 = {
    Text = "Des souvenirs autrefois clairs deviennent soudain flous, un autre souvenir surgit brusquement de ton esprit. Mizag, Éveilleur, Fusion, Touva Wave..."
  },
  AvgDialog_131205_Content_16 = {
    Text = "Tu ouvres brusquement les yeux et regardes la femme en face de toi qui déguste son café."
  },
  AvgDialog_131205_Content_17 = {
    Text = "Non... Ce n'est pas ça... Je suis le Gardien de Mizag... Que se passe-t-il ?"
  },
  AvgDialog_131205_Content_18 = {
    Text = "Je m'en souviens... nous sommes montés sur une scène dans ton théâtre, puis... puis..."
  },
  AvgDialog_131205_Content_19 = {
    Text = "Ensuite, tu as commandé le thé de l'après-midi au serveur. En tant que personne du cru, tu as un bon goût."
  },
  AvgDialog_131205_Content_2 = {
    Text = "Ding ding——"
  },
  AvgDialog_131205_Content_20 = {
    Text = "Arachne prit une gorgée du liquide brun dans sa tasse de café et hocha la tête avec appréciation."
  },
  AvgDialog_131205_Content_21 = {
    Text = "Messieurs, vos affaires sont prêtes."
  },
  AvgDialog_131205_Content_22 = {
    Text = "Le plateau dans les mains du serveur dégage un parfum enivrant. En se penchant pour servir, il rapproche doucement sa tête de ton oreille."
  },
  AvgDialog_131205_Content_23 = {
    Text = "Le complot d›assassinat a fuité. L›Archiduc changera probablement d›itinéraire. Le contact vous préviendra dès qu›il y aura du nouveau. Tenez-vous prêt, %player%."
  },
  AvgDialog_131205_Content_24 = {
    Text = "Un tout nouveau pistolet Browning est discrètement placé dans ta main. Lorsque tu relèves à nouveau la tête, le visage du serveur a retrouvé un sourire amical. Après vous avoir salués, il retourne à la cuisine avec son plateau."
  },
  AvgDialog_131205_Content_25 = {
    Text = "Un excès de souvenirs s'accumule dans ton esprit, et tu frottes douloureusement ton front enflé."
  },
  AvgDialog_131205_Content_26 = {
    Text = "Deux souvenirs différents coexistent dans un même cerveau, et pour ceux qui les vivent pour la première fois, cette sensation n'est effectivement pas très agréable."
  },
  AvgDialog_131205_Content_27 = {
    Text = "Ça va, comparé à faire face à Touva Wave, ce niveau de mal de tête ressemble à un massage."
  },
  AvgDialog_131205_Content_28 = {
    Text = "Ma mémoire me dit que je suis les ordres de la Main de Fer. Dans deux heures, je suis censé utiliser cette arme pour assassiner l'héritier en visite du trône de l'Empire Féo..."
  },
  AvgDialog_131205_Content_29 = {
    Text = "Tu caresses les motifs de ce pistolet, organisant dans ton esprit les souvenirs qui appartiennent à ce monde."
  },
  AvgDialog_131205_Content_3 = {
    Text = "Les roues roulent sur le sol accidenté des galets, la cloche en colère hurle vers la vaste procession, soulevant un nuage de poussière et des insultes."
  },
  AvgDialog_131205_Content_30 = {
    Text = "Avant que tu n'aies eu le temps de continuer à poser des questions, une forte lumière a inondé le café. Les bottes militaires frappent le sol en béton avec un bruit clair, se dirigeant vers le bar."
  },
  AvgDialog_131205_Content_31 = {
    Text = "Bonjour, mesdames et messieurs les agents, puis-je vous aider... ?"
  },
  AvgDialog_131205_Content_32 = {
    Text = "Avant qu'il ait fini de parler, un policier s'approcha rapidement, lui saisissant les mains derrière le dos et appuyant sa tête sur le comptoir."
  },
  AvgDialog_131205_Content_33 = {
    Text = "Dans son regard inquiet, une arme était braquée sur son front."
  },
  AvgDialog_131205_Content_34 = {
    Text = "Membre du Conseil de la Réunification, Bosant. Tu as dix secondes pour me dire où se trouve ton complice."
  },
  AvgDialog_131205_Content_35 = {
    Text = "Le serveur halète, tremblant. Dans sa lutte désespérée, ses yeux se tournent vers le coin de la pièce."
  },
  AvgDialog_131205_Content_36 = {
    Text = "Mais la table que vous occupiez à l'instant est vide. Seulement une demi-tasse de café y demeure, sa vapeur s'élevant paresseusement dans l'air."
  },
  AvgDialog_131205_Content_37 = {Text = "新增"},
  AvgDialog_131205_Content_38 = {
    Text = "Ici, ça devrait être temporairement en sécurité."
  },
  AvgDialog_131205_Content_39 = {
    Text = "Vous sortez par la porte arrière du café, comme deux gouttes d'eau insignifiantes, se mêlant à la foule bruyante."
  },
  AvgDialog_131205_Content_4 = {
    Text = "Tu fais un geste de la main, chassant la poussière qui s'infiltre à travers les rideaux du café."
  },
  AvgDialog_131205_Content_40 = {
    Text = "Quelle est cette situation maintenant... ce souvenir différent, qu'est-ce que c'est ?"
  },
  AvgDialog_131205_Content_41 = {
    Text = "Monter sur la scène du théâtre du destin, c'est devenir un personnage sur cette scène. Chaque personnage a sa propre vie."
  },
  AvgDialog_131205_Content_42 = {
    Text = "Ce monde se trouve dans une dimension lointaine, que vous n'avez jamais entendue ni explorée. Mais en tant que personnage issu de ce monde, vous en avez une connaissance approfondie."
  },
  AvgDialog_131205_Content_43 = {
    Text = "Bienvenue sur l'une de mes scènes, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131205_Content_44 = {
    Text = "Tu veux dire que... tu peux connecter d'autres mondes à travers la scène ?"
  },
  AvgDialog_131205_Content_45 = {
    Text = "Arachne a compris la signification de ton regard brûlant. Elle a levé la tasse de café qu'elle avait emportée du magasin, l'a goûtée avec sérieux et a doucement secoué la tête."
  },
  AvgDialog_131205_Content_46 = {
    Text = "Fuir avec du café et un gâteau, cette chose étrange n'a absolument pas attiré votre attention. Cela s'est produit si harmonieusement chez Arachne, comme si cela faisait naturellement partie de son destin."
  },
  AvgDialog_131205_Content_47 = {
    Text = "Dame Daffodil vous a expliqué les principes du voyage dimensionnel. Les barrières entre les mondes sont incroyablement solides. Chaque traversée exige un prix terrible ; ce n'est pas quelque chose que l'on fait à la légère."
  },
  AvgDialog_131205_Content_48 = {
    Text = "Mais nous sommes déjà ici, n'est-ce pas..."
  },
  AvgDialog_131205_Content_49 = {
    Text = "Le Théâtre du destin peut brièvement relier les destins de différents mondes."
  },
  AvgDialog_131205_Content_5 = {
    Text = "Un wrap shawarma, une Sachertorte, et deux tasses de café Hewatz. Merci."
  },
  AvgDialog_131205_Content_50 = {
    Text = "Actuellement, nous ne sommes que deux personnages perdus dans une mer de gens — des projections éphémères qui disparaîtront en un clin d'œil."
  },
  AvgDialog_131205_Content_51 = {
    Text = "Projection... même une projection suffira, tu peux m'aider à revenir de cette manière ?"
  },
  AvgDialog_131205_Content_52 = {
    Text = "Je suis vraiment désolée, %player%. La porte que vous avez fermée a bloqué le Regard de Touva Wave, mais elle a aussi rompu le Fil du destin."
  },
  AvgDialog_131205_Content_53 = {
    Text = "Si nous essayons d'exercer une influence là-bas, nous subirons un cataclysme que nous ne pouvons pas supporter."
  },
  AvgDialog_131205_Content_54 = {
    Text = "Elle te regarde avec un air déçu sur le visage, souriant en te tendant le gâteau dans l'assiette."
  },
  AvgDialog_131205_Content_55 = {
    Text = "Soyez rassuré, %player%. Une fois que nous en aurons fini avec ma sœur, le passage vers Kadath s'ouvrira à nouveau."
  },
  AvgDialog_131205_Content_56 = {
    Text = "Le destin ne décevra pas chaque attente, et nous ne pouvons pas décevoir chaque cadeau du destin. Goûte."
  },
  AvgDialog_131205_Content_57 = {
    Text = "Tu prends une profonde inspiration, prends le gâteau et en manges une bouchée. Le goût sucré te fait presque oublier l'inconfort causé par la collision de deux souvenirs différents."
  },
  AvgDialog_131205_Content_58 = {
    Text = "Hmm... On dit que le Prince Flavien ne manque jamais une occasion de goûter le gâteau local à chacune de ses visites. Pour un prince héritier, il a assurément un goût raffiné."
  },
  AvgDialog_131205_Content_59 = {
    Text = "Alors, qu'est-ce que Nefraea a influencé dans ce monde ? Comment devrions-nous corriger cela..."
  },
  AvgDialog_131205_Content_6 = {
    Text = "Tu passes le menu en parchemin au serveur, regardant avec mélancolie la rue familière à l'extérieur."
  },
  AvgDialog_131205_Content_60 = {
    Text = "Alors que tu parlais, Arachne semblait être attirée par quelque chose, levant les yeux vers ces fils dans le ciel que tu ne pouvais pas distinguer."
  },
  AvgDialog_131205_Content_61 = {
    Text = "Elle sourit, finit la dernière gorgée de café dans sa tasse, et remit quelques pièces et la tasse restante à un serveur qui passait par là et se dépêchait de retourner au café, en le remerciant doucement."
  },
  AvgDialog_131205_Content_62 = {
    Text = "Elle nous a trouvés. Le moment est parfait. Soyez prudent, %player%."
  },
  AvgDialog_131205_Content_63 = {Text = "Bang—"},
  AvgDialog_131205_Content_64 = {
    Text = "Tu te penches instinctivement, une balle passe presque en frôlant le sommet de ta tête."
  },
  AvgDialog_131205_Content_65 = {Text = "Juste là"},
  AvgDialog_131205_Content_66 = {
    Text = "Ce sont des assassins de la Ligue de la Restauration ! Attrapez-les"
  },
  AvgDialog_131205_Content_67 = {
    Text = "Menés par quelques citoyens vociférants, une nuée d'officiers se fraie un chemin à travers la foule pour vous encercler."
  },
  AvgDialog_131205_Content_68 = {
    Text = "Tandis qu'ils se rapprochent, leurs corps commencent à se déformer — des pattes d'araignée sombres et chitineuses jaillissent de leurs torses, et des griffes acérées comme des rasoirs frappent dans tous les sens."
  },
  AvgDialog_131205_Content_7 = {
    Text = "Cette rue devrait vraiment être élargie, elle était déjà comme ça quand j'étais enfant, à part qu'elle est de plus en plus en ruine, elle n'a pas du tout changé en toutes ces années."
  },
  AvgDialog_131205_Content_8 = {
    Text = "Les autorités sont incapables de construire quoi que ce soit. La seule chose qu›elles savent faire, c›est vendre les terres de Hewatz et servir du gâteau à la famille royale."
  },
  AvgDialog_131205_Content_9 = {
    Text = "Les réfugiés, la manifestation, il fallait vraiment choisir ce moment pour rendre visite au grand-duc... Professeur Arachne, puis-je rendre mon devoir de recherche sur le folklore un peu plus tard ? Les activités du Rassemblement pour la restauration nationale m'ont récemment pris trop d'énergie."
  },
  AvgDialog_131206_Content_10 = {
    Text = "Cuiii—— Cuiii—— la déesse du destin fait tourner son rouet."
  },
  AvgDialog_131206_Content_11 = {
    Text = "Cuiii—— Cuiii—— Les fils du destin se rassemblent dans sa main."
  },
  AvgDialog_131206_Content_12 = {
    Text = "Les marionnettes font la queue pour entrer, foulant le gigantesque filet du destin."
  },
  AvgDialog_131206_Content_13 = {
    Text = "Ils dansent. Ils chantent. Cui cui—— Cui cui——"
  },
  AvgDialog_131206_Content_14 = {
    Text = "Elles sont mortes avec le grand filet, silencieusement."
  },
  AvgDialog_131206_Content_15 = {Text = "新增"},
  AvgDialog_131206_Content_16 = {
    Text = "Maître, notre nouvelle pièce est déjà jouée."
  },
  AvgDialog_131206_Content_17 = {
    Text = "Le passage de retour à Kadath a été fermé à temps, cette personne {Male=monsieur, Female=mademoiselle} est déjà arrivée dans la ville."
  },
  AvgDialog_131206_Content_18 = {
    Text = "Alors, tu aimes cette nouvelle pièce ?"
  },
  AvgDialog_131206_Content_19 = {
    Text = "Hmm... c'est peut-être un peu trop compliqué ?"
  },
  AvgDialog_131206_Content_2 = {
    Text = "Cité brumeuse non éveillée"
  },
  AvgDialog_131206_Content_20 = {
    Text = "Une histoire simple est naturellement sans souci, mais pour certaines personnes, de telles histoires ne peuvent pas écrire leur destin."
  },
  AvgDialog_131206_Content_21 = {
    Text = "Tel est le destin qui appartient à un « Héros »."
  },
  AvgDialog_131206_Content_22 = {
    Text = "Allez ; c'est votre tour sur scène."
  },
  AvgDialog_131206_Content_23 = {
    Text = "Vas-y, c'est ton tour de monter sur scène."
  },
  AvgDialog_131206_Content_24 = {
    Text = "La jeune fille se prosterna en signe de révérence. À l'instant où son front toucha le sol, son corps se dispersa et se Fissura, sa Caro et sa peau se transformant entièrement en araignées violet pâle qui disparurent dans les coins de la pièce."
  },
  AvgDialog_131206_Content_25 = {Text = "新增"},
  AvgDialog_131206_Content_26 = {
    Text = "<Shake:Tousse... tousse...>"
  },
  AvgDialog_131206_Content_27 = {
    Text = "Le sol est en bitume dur. Tu te redresses en titubant, frottant vigoureusement ta tête en désordre."
  },
  AvgDialog_131206_Content_28 = {
    Text = "Juste maintenant... il s'est passé..."
  },
  AvgDialog_131206_Content_29 = {
    Text = "Ah ! Le passage de Kadath !"
  },
  AvgDialog_131206_Content_3 = {
    Text = "Ah, Kadath, la patrie de mes rêves ! Enfin, je peux y retourner !"
  },
  AvgDialog_131206_Content_30 = {
    Text = "Tu te réveilles brusquement et lèves les yeux vers le ciel."
  },
  AvgDialog_131206_Content_31 = {
    Text = "Dans le ciel bleu azur, la lumière brillante du soleil descend, sans aucune trace de l'obscurité ou des portails dimensionnels."
  },
  AvgDialog_131206_Content_32 = {
    Text = "C'est... cette personne est étrange... {Male=il,Female=elle} est-elle tombée du ciel tout juste ?"
  },
  AvgDialog_131206_Content_33 = {
    Text = "Eh bien, d'après ce que je sais, une entreprise technologique à proximité teste des aéronefs, {Male=il,Female=elle} devrait être un testeur d'aéronefs."
  },
  AvgDialog_131206_Content_34 = {
    Text = "Mmm... C'est..."
  },
  AvgDialog_131206_Content_35 = {Text = "Humain."},
  AvgDialog_131206_Content_36 = {
    Text = "Une foule dense apparaît devant vos yeux, éblouis par une lumière intense."
  },
  AvgDialog_131206_Content_37 = {
    Text = "Des rues animées, des foules rassemblées, des boutiques débordantes de couleurs partout..."
  },
  AvgDialog_131206_Content_38 = {
    Text = "Le monde de cette dimension a vu sa population chuter drastiquement à cause de la Fusion. Vous n'avez jamais été témoin d'une scène aussi vivante, pas même à Nekropolis."
  },
  AvgDialog_131206_Content_39 = {
    Text = "Le monde de cette dimension a connu une forte diminution de sa population à cause de la fusion, même dans la Nekropolis, tu n'as jamais vu un tel spectacle de prospérité."
  },
  AvgDialog_131206_Content_4 = {
    Text = "Ah, Kadath, ma patrie dans mes rêves ! Maintenant, je peux enfin retourner"
  },
  AvgDialog_131206_Content_40 = {
    Text = "Puis-je savoir... où sommes-nous ?"
  },
  AvgDialog_131206_Content_41 = {
    Text = "Ha, c'est étrange, qu'il y ait des gens qui n'ont même jamais entendu parler de Londinium ? C'est la plus grande ville du monde"
  },
  AvgDialog_131206_Content_42 = {
    Text = "<Shake:!!!>"
  },
  AvgDialog_131206_Content_43 = {
    Text = "Tu dis que cet endroit s'appelle quoi ?"
  },
  AvgDialog_131206_Content_44 = {
    Text = "Es-tu sûr d'avoir entendu ces quatre mots."
  },
  AvgDialog_131206_Content_45 = {
    Text = "Ton cerveau embrumé s'éveille immédiatement, tu te lèves brusquement et regardes autour de toi."
  },
  AvgDialog_131206_Content_46 = {
    Text = "Au carrefour de Brick, les marques ébréchées sur le panneau indicateur ressemblent exactement à celles de ta mémoire."
  },
  AvgDialog_131206_Content_47 = {
    Text = "La librairie d'occasion des plis temporels, chaque fois que tu sortais discrètement de l'école, ce que tu préférais faire, c'était te cacher ici pour lire des romans policiers."
  },
  AvgDialog_131206_Content_48 = {
    Text = "Dans l'épicerie du marché parfumé, le professeur Dexter te demande toujours de lui ramener une bouteille de liqueur. Un petit stratagème de N."
  },
  AvgDialog_131206_Content_49 = {
    Text = "La maison de fleurs de rosée du matin. Lors de la célébration de ton premier anniversaire en tant que Gardien, Ramona avait prévu de te faire un bouquet des fleurs les plus éclatantes de tout Londinium..."
  },
  AvgDialog_131206_Content_5 = {
    Text = "Mon aîné, mon compagnon, mon ami proche, mon... tout."
  },
  AvgDialog_131206_Content_50 = {Text = "新增"},
  AvgDialog_131206_Content_51 = {
    Text = "Londinium... je suis vraiment... de retour ?"
  },
  AvgDialog_131206_Content_52 = {
    Text = "Puis-je demander... comment va Mizag maintenant ?"
  },
  AvgDialog_131206_Content_53 = {
    Text = "Mizag ? Cette personne {Male=monsieur,Female=mademoiselle}, l'endroit dont vous parlez, nous ne l'avons jamais entendu."
  },
  AvgDialog_131206_Content_54 = {
    Text = "Et la corrosion, qu'en est-il ? Quelle est la situation des dégâts ici ?"
  },
  AvgDialog_131206_Content_55 = {
    Text = "Jeune {Male=sir,Female=lady}, je pense que vous êtes simplement fatigué(e) et un peu désorienté(e)... Asseyez–vous sur ce banc et mangez quelque chose. Il se trouve que j'en ai un peu sur moi."
  },
  AvgDialog_131206_Content_56 = {
    Text = "Enfant, je pense que tu es fatigué... Assieds-toi sur un banc dans le parc et mange quelque chose. J'ai justement un peu ici."
  },
  AvgDialog_131206_Content_57 = {
    Text = "Le vieillard te tend le pain et l'eau qu'il vient d'acheter au magasin."
  },
  AvgDialog_131206_Content_58 = {
    Text = "Ah, merci beaucoup... mais je n'ai pas faim en ce moment, c'est juste que... j'ai quelques questions que je n'ai pas encore comprises..."
  },
  AvgDialog_131206_Content_59 = {
    Text = "<Small:Ce n'est pas possible... Il n'y a pas de Mizag, et pas de fusion...>"
  },
  AvgDialog_131206_Content_6 = {
    Text = "Tant que je traverserai cette porte des ténèbres, je me retrouverai à nouveau avec eux"
  },
  AvgDialog_131206_Content_60 = {
    Text = "Ce n'est pas gentil de dire ça. {Male=he,Female=she} traverse peut–être une période difficile. Surveillez vos manières avec les invités qui viennent de loin."
  },
  AvgDialog_131206_Content_61 = {
    Text = "Ne dis pas n'importe quoi, {Male=il,Female=elle} a peut-être rencontré des difficultés. Sois poli envers les invités venus de loin."
  },
  AvgDialog_131206_Content_62 = {
    Text = "Une main te tapote doucement l'épaule. Tu te retournes et vois un visage inconnu."
  },
  AvgDialog_131206_Content_63 = {
    Text = "Nous sommes des patrouilleurs de la région, sous la juridiction du comité de censure. Voici mes papiers."
  },
  AvgDialog_131206_Content_64 = {
    Text = "Bonjour. Des citoyens bienveillants nous ont informés qu'un voyageur s'est perdu dans notre belle ville."
  },
  AvgDialog_131206_Content_65 = {
    Text = "Puis-je vous demander, cette personne {Male=monsieur,Female=mademoiselle}, si vous avez besoin d'aide ?"
  },
  AvgDialog_131206_Content_66 = {
    Text = "Vous prenez un bref instant pour réfléchir. Tant que vous ne comprenez pas ce qui se passe, mieux vaut attirer le moins d'attention possible."
  },
  AvgDialog_131206_Content_67 = {
    Text = "Ah... merci de vous en soucier. Je suis juste tombé dans les pommes en flânant sur le chemin, je n'ai eu aucun problème."
  },
  AvgDialog_131206_Content_68 = {
    Text = "Je vous remercie beaucoup. Nous avons encore des choses à faire, partez d'abord..."
  },
  AvgDialog_131206_Content_69 = {
    Text = "L'officier s'avance vers vous avec un sourire, époussetant la poussière de votre épaule"
  },
  AvgDialog_131206_Content_7 = {
    Text = "Mais pourquoi cette porte si proche est-elle fermée ? Pourquoi ce ciel cruel m'a-t-il abandonné ?"
  },
  AvgDialog_131206_Content_70 = {
    Text = "L'agent de police s'approcha de vous avec un sourire et vous tapota la poussière sur l'épaule."
  },
  AvgDialog_131206_Content_71 = {
    Text = "J'aimerais vous demander... êtes–vous satisfait de la cérémonie d'accueil que j'ai organisée pour vous?"
  },
  AvgDialog_131206_Content_72 = {
    Text = "Je voudrais vous demander... êtes-vous satisfait de cette cérémonie d'accueil en votre honneur ?"
  },
  AvgDialog_131206_Content_73 = {Text = "!!!"},
  AvgDialog_131206_Content_74 = {
    Text = "Un bruit de déchirure humide et nauséabond s'élève dans l'air. D'immenses pattes d'araignée jaillissent des corps des officiers et des passants, éclaboussant sur vous un sang épais à l'odeur de fer."
  },
  AvgDialog_131206_Content_75 = {
    Text = "Notre illustre invité est arrivé au théâtre. Conduisez {Male=him,Female=her} à {Male=his,Female=her} place, mes enfants."
  },
  AvgDialog_131206_Content_76 = {
    Text = "Notre hôte distingué est arrivé dans notre théâtre, guidez-{Male=他,Female=她} jusqu'à sa place, mes enfants."
  },
  AvgDialog_131206_Content_77 = {
    Text = "Attention!!"
  },
  AvgDialog_131206_Content_78 = {
    Text = "Attention !!"
  },
  AvgDialog_131206_Content_8 = {
    Text = "Ma chère clé en argent...... éclaire mon chemin...... donne-moi des bribes de réponses......"
  },
  AvgDialog_131206_Content_9 = {
    Text = "Craquement — craquement — la Déesse du Destin tourne son rouet."
  },
  AvgDialog_131207_Content_1 = {
    Text = "Reflet des divinités"
  },
  AvgDialog_131207_Content_10 = {
    Text = "Tu as encore une chance de t'arrêter, Nefraea."
  },
  AvgDialog_131207_Content_11 = {
    Text = "Que peut-on faire alors qu'elle s'est complètement dissipée ?"
  },
  AvgDialog_131207_Content_12 = {
    Text = "Nefraea sourit avec légèreté et se tourna vers les serviteurs dévoués."
  },
  AvgDialog_131207_Content_13 = {
    Text = "Dites-moi, les enfants, avez-vous peur ?"
  },
  AvgDialog_131207_Content_14 = {
    Text = "La réponse d'Arachne est un rire désespéré."
  },
  AvgDialog_131207_Content_15 = {
    Text = "Ahahahaha ! Nous sommes les abandonnés du destin, aucun cataclysme ne nous fera peur... Apportez-nous du soulagement, mon maître."
  },
  AvgDialog_131207_Content_16 = {
    Text = "Bon enfant."
  },
  AvgDialog_131207_Content_17 = {
    Text = "Nefraea a caressé la tête de son serviteur."
  },
  AvgDialog_131207_Content_18 = {
    Text = "Tu te trompes, ma chère sœur. Le destin nous a déjà condamnés à mort et à une emprisonnement éternel. Un groupe de fantômes abandonnés, ne demandera plus la clémence du destin."
  },
  AvgDialog_131207_Content_19 = {
    Text = "Nous, nous vengeons le destin."
  },
  AvgDialog_131207_Content_2 = {
    Text = "Sur une scène grandiose que vous n'avez jamais vue, la roue de fil noir de Nefraea se dresse seule au centre de la scène. Au milieu du gigantesque anneau, une lumière bleuâtre apparemment inextinguible éclaire le visage joyeux de Nefraea."
  },
  AvgDialog_131207_Content_20 = {
    Text = "Je ne sais pas si c'est par inadvertance ou intentionnellement, mais dans les fils du destin que manipule Nefraea, l'un d'eux s'est silencieusement rompu."
  },
  AvgDialog_131207_Content_21 = {
    Text = "Au moment où le fil se rompit, une scène non loin de vous se brisa soudainement, se transformant en fragments volants, s'anéantissant dans l'espace dimensionnel sans fin du théâtre."
  },
  AvgDialog_131207_Content_22 = {
    Text = "Oh là là, désolé désolé, j'ai accidentellement abîmé ton fil..."
  },
  AvgDialog_131207_Content_23 = {
    Text = "Vas-y, ma chère sœur. Bien qu'il y ait de nombreuses scènes dans le théâtre, si tu les abîmes encore, cela te fera mal au cœur, n'est-ce pas ?"
  },
  AvgDialog_131207_Content_24 = {
    Text = "Le soupir d'Arachne est à peine audible. Lorsqu'elle ouvre à nouveau les yeux, elle lève le doigt et te touche doucement au sommet de la tête."
  },
  AvgDialog_131207_Content_25 = {
    Text = "Arachne ! Ne fais pas ça... Nous pouvons certainement trouver une autre solution..."
  },
  AvgDialog_131207_Content_26 = {
    Text = "Monte sur scène. Offre l›Ordre de poids des plasmides à l›Apôtre... C›est ton destin inéluctable, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131207_Content_27 = {
    Text = "La voix irrésistible d'Arachne résonne dans ton monde spirituel. Alors que tu lèves le pied pour monter sur scène, trois forces longtemps oubliées commencent à s'agiter en toi."
  },
  AvgDialog_131207_Content_28 = {
    Text = "Elles s'entrelacent et se heurtent en toi, s'opposant aux paroles oraculaires d'Arachne."
  },
  AvgDialog_131207_Content_29 = {
    Text = "Oh là là, pas étonnant que ce soit l'un des trois plasmides... Un si petit pouvoir, à une dimension si lointaine, et il peut encore avoir de l'influence sur l'hôte."
  },
  AvgDialog_131207_Content_3 = {
    Text = "Regarde, {Male=Mr.,Female=Miss} Gardien, quelles belles lumières..."
  },
  AvgDialog_131207_Content_30 = {
    Text = "Fais-les se tenir tranquilles, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131207_Content_4 = {
    Text = "Cette lumière est un don du Destin, elle nous guidera vers ce lieu d'extase sans douleur..."
  },
  AvgDialog_131207_Content_5 = {
    Text = "Nefraea tendit la main, caressant les traces laissées par la lumière dans l'espace dimensionnel. L'ombre des doigts se resserre lentement, se mouvant sur le visage d'Arachne."
  },
  AvgDialog_131207_Content_6 = {
    Text = "Viens, grande sœur, notre protagoniste est sur le point de faire son entrée."
  },
  AvgDialog_131207_Content_7 = {
    Text = "...Le destin n'est pas quelque chose qui peut être manipulé ou altéré, Nefraea."
  },
  AvgDialog_131207_Content_8 = {
    Text = "Chaque destin est déjà scellé. Si tu éveilles cette divinité et laisses tout prendre fin... altérer le Destin de force provoquera une catastrophe au-delà de ton imagination."
  },
  AvgDialog_131207_Content_9 = {
    Text = "Que ce soit ce que tu méprises ou ce qui t›est cher, tout disparaîtra dans l›apocalypse."
  },
  AvgDialog_131208_Content_1 = {Text = "Jugement"},
  AvgDialog_131208_Content_10 = {
    Text = "La jeune fille prit une profonde inspiration et sourit, satisfaite."
  },
  AvgDialog_131208_Content_11 = {
    Text = "Les iris ont déjà commencé à fleurir... un autre printemps est vraiment arrivé."
  },
  AvgDialog_131208_Content_12 = {
    Text = "Eh, Xiaofu, je ne t'ai jamais demandé, quelle est ta saison préférée ?"
  },
  AvgDialog_131208_Content_13 = {
    Text = "......Je n'ai pas de saison préférée, Maître."
  },
  AvgDialog_131208_Content_14 = {Text = "Ennuyeux."},
  AvgDialog_131208_Content_15 = {
    Text = "Arachne a levé les yeux au ciel, tendant sa main dépourvue de fil pour attraper la lumière du soleil qui se déversait par la fenêtre."
  },
  AvgDialog_131208_Content_16 = {
    Text = "J'aime chaque saison, surtout le printemps. Cela fait si longtemps que nous avons quitté la maison... devrions-nous trouver le temps de faire une randonnée ?"
  },
  AvgDialog_131208_Content_17 = {
    Text = "À côté du manoir où je suis né, il y a un jardin de fleurs très bien entretenu, vous allez certainement l'aimer."
  },
  AvgDialog_131208_Content_18 = {
    Text = "Vous avez attendu trois jours... Il est temps de prendre une décision, maître."
  },
  AvgDialog_131208_Content_19 = {
    Text = "La servante remplit son devoir, ses paroles glaciales sont comme une pluie froide. Elles éteignent ce printemps éclatant dans les yeux d'Arachne."
  },
  AvgDialog_131208_Content_2 = {
    Text = "Cuiii—— Cuiii—— la déesse du destin fait tourner son rouet."
  },
  AvgDialog_131208_Content_20 = {
    Text = "Cric, cric..."
  },
  AvgDialog_131208_Content_21 = {
    Text = "Après une pause d'un instant, le rouet recommence à tourner. Sa fréquence est douce, claire et immuable."
  },
  AvgDialog_131208_Content_22 = {
    Text = "Le pays dans lequel nous nous trouvons vient de mettre fin à un siècle de guerre. Les gens ont reconstruit leurs villes sur les ruines, attendant ce qui les attendra : une longue paix."
  },
  AvgDialog_131208_Content_23 = {
    Text = "Regarde, là-bas..."
  },
  AvgDialog_131208_Content_24 = {
    Text = "Suivant le regard d'Arachne, la servante se tourna vers une immense peinture accrochée dans la salle. Elle n'avait jamais compris ce tableau."
  },
  AvgDialog_131208_Content_25 = {
    Text = "Parmi toutes les grandes œuvres de M. Zoss, ce tableau, bien que négligé, est celui que je préfère."
  },
  AvgDialog_131208_Content_26 = {
    Text = "Ces cerfs, peints en ocre et en formes géométriques... même en tant que symboles abstraits, ils palpitent de vie."
  },
  AvgDialog_131208_Content_27 = {
    Text = "Chaque fois que je le vois, je pense à ma pièce de théâtre préférée..."
  },
  AvgDialog_131208_Content_28 = {
    Text = "La fissure existe depuis trois jours, Maître. Le destin de cette dimension a déjà été contaminé par le regard de cette personne divine."
  },
  AvgDialog_131208_Content_29 = {
    Text = "Si cela continue ainsi, les endroits que Son regard s'apprête à détruire sont bien plus nombreux que celui-ci."
  },
  AvgDialog_131208_Content_3 = {
    Text = "Cuiii—— Cuiii—— Les fils du destin se rassemblent dans sa main."
  },
  AvgDialog_131208_Content_30 = {Text = "Cui, cui."},
  AvgDialog_131208_Content_31 = {
    Text = "La jeune fille ferme les yeux, profitant des caresses du soleil. La pièce chaleureuse tombe dans le silence, seul le rouet continue de tourner avec une fréquence immuable."
  },
  AvgDialog_131208_Content_32 = {
    Text = "Te souviens-tu combien de destins de mondes nous avons déjà tissés ?"
  },
  AvgDialog_131208_Content_33 = {
    Text = "Au total, vingt-sept, maître."
  },
  AvgDialog_131208_Content_34 = {
    Text = "Après que mon père m'a offert ce rouet, j'ai suivi ses fils pour approcher la porte de la vérité. Derrière cette porte, j'ai vu le destin qui attend ce monde..."
  },
  AvgDialog_131208_Content_35 = {
    Text = "Je sais ce qui m'attend devant moi. Je sais quel choix je devrais faire... mais je n'y arrive pas."
  },
  AvgDialog_131208_Content_36 = {
    Text = "Parents. Amis. Souvenirs. Dix-sept mille ans d'histoire grandiose. Une technologie et un art aussi nombreux que les étoiles..."
  },
  AvgDialog_131208_Content_37 = {
    Text = "Après avoir vu cette réponse, j'ai commencé à tisser le destin de ce monde... Je pense toujours que le destin m'a donné cette capacité, je peux certainement faire quelque chose pour ce monde."
  },
  AvgDialog_131208_Content_38 = {
    Text = "C'est ma maison. Mon enfant. <Shake:Je... Je ne peux pas le faire>, Xiaofu..."
  },
  AvgDialog_131208_Content_39 = {Text = "Maître..."},
  AvgDialog_131208_Content_4 = {
    Text = "Les marionnettes font la queue pour entrer, foulant le gigantesque filet du destin."
  },
  AvgDialog_131208_Content_40 = {
    Text = "La servante s'accroupit et essuie les larmes de sa maîtresse. Sous le soleil printanier, sa voix est claire et déterminée."
  },
  AvgDialog_131208_Content_41 = {
    Text = "Vous avez prévu ce jour, alors vous m'avez fait devenir votre servante."
  },
  AvgDialog_131208_Content_42 = {
    Text = "Tout le sens de ma vie, c'est de vous dire ce que vous devez faire en ce moment..."
  },
  AvgDialog_131208_Content_43 = {
    Text = "Vous êtes le maître du destin, le gardien de ces nombreuses dimensions. C'est un chemin cruel, mais vous avez déjà fait votre choix."
  },
  AvgDialog_131208_Content_44 = {
    Text = "Les trois déesses du destin, responsables de tisser, de juger... et de couper."
  },
  AvgDialog_131208_Content_45 = {
    Text = "Depuis le moment où vous avez fait votre choix, tout cela est devenu votre devoir inévitable."
  },
  AvgDialog_131208_Content_46 = {
    Text = "Arachne leva la tête, dans ses yeux flous, cette fissure que les mortels ne peuvent voir scintille à l'horizon. Elle a toujours été là, à côté de cette douce lumière du soleil printanier, comme un sourire cruel."
  },
  AvgDialog_131208_Content_47 = {
    Text = "La fissure chuchote à Arachne, lui racontant ces futurs glacials. Elle a accepté cette malédiction depuis longtemps, et lorsque l'avenir descend, son corps tremble encore de peur."
  },
  AvgDialog_131208_Content_48 = {
    Text = "Arachne s'est rasseyée devant le métier à tisser. Après la peur et le désespoir, une teinte rouge malsaine est apparue sur son visage."
  },
  AvgDialog_131208_Content_49 = {
    Text = "Elle caresse les fils denses et emmêlés comme si elle effleurait le visage d'un enfant."
  },
  AvgDialog_131208_Content_5 = {
    Text = "Ils dansent. Ils chantent. Cui cui—— Cui cui——"
  },
  AvgDialog_131208_Content_50 = {
    Text = "En l'an 804, avant même que je puisse parler, notre majordome a joué un morceau au piano."
  },
  AvgDialog_131208_Content_51 = {
    Text = "<Italic:« Les funérailles du fleuve Loas »> d'Elysion. La musique était comme une fontaine coulant devant un temple. J'ai vu même les dieux s'arrêter pour écouter..."
  },
  AvgDialog_131208_Content_52 = {
    Text = "Un fil est silencieusement coupé. Il flotte doucement dans l'air, dérivant silencieusement dans les répliques du destin."
  },
  AvgDialog_131208_Content_53 = {
    Text = "La musique dans le hall s'est évanouie, seul le phonographe continue de tourner. Les rainures du disque sont remplies, le titre de la chanson écrit en belles lettres cursives est gratté."
  },
  AvgDialog_131208_Content_54 = {
    Text = "Elihion a accueilli un autre destin. Dans ce monde solitaire, sa vie grandiose n'a jamais existé."
  },
  AvgDialog_131208_Content_55 = {
    Text = "Cassandra, l'église qu'elle a conçue est plus digne d'admiration que les divinités qui y résident..."
  },
  AvgDialog_131208_Content_56 = {
    Text = "Une autre ligne se rompt. À deux cents kilomètres, cette grande cathédrale se brise et s'effondre, les yeux compatissants de la statue se brisent, ne faisant plus qu'un avec la poussière."
  },
  AvgDialog_131208_Content_57 = {
    Text = "Les contes de Mornlin, les opéras d'Aldo, les peintures de Malmo, les poèmes de Rouvell..."
  },
  AvgDialog_131208_Content_58 = {
    Text = "Les livres se transforment en morceaux de papier, les sculptures en fragments, et les peintures en couleurs désordonnées."
  },
  AvgDialog_131208_Content_59 = {
    Text = "Elle est journaliste. Elle est exécutrice. Elle prononce le nom de chaque grand artiste de ce monde, coupant le fil qui leur appartient."
  },
  AvgDialog_131208_Content_6 = {
    Text = "Le soleil illumine leur visage, quelle joie——"
  },
  AvgDialog_131208_Content_60 = {
    Text = "Wilderbourg, une grande ville appartenant aux héros. Elle a traversé cent cinq batailles, a été détruite et reconstruite trente-sept fois, et vingt et un grands seigneurs y ont accompli des exploits, perdant leurs épées dans le sable."
  },
  AvgDialog_131208_Content_61 = {
    Text = "Les nobles chantent ici, les pauvres crient ici, les poètes laissent de beaux poèmes, et les chants au bord de la rivière Neerqin résonnent au-dessus d'elle avec le bruit des canons. Son histoire héroïque se termine aujourd'hui."
  },
  AvgDialog_131208_Content_62 = {
    Text = "Un groupe de fils coupés flotte en désordre, comme une danse de fête. À deux mille trois cents kilomètres, cette ville majestueuse s'effondre avec fracas."
  },
  AvgDialog_131208_Content_63 = {
    Text = "Une civilisation ancienne qui a survécu pendant dix-sept mille ans, se tenant fermement au milieu des fléaux et des calamités humaines, sans jamais tomber..."
  },
  AvgDialog_131208_Content_64 = {
    Text = "Faiblissant, tremblant. Arachne leva la main de toutes ses forces, saisissant les fils infinis devant elle."
  },
  AvgDialog_131208_Content_65 = {
    Text = "Le fil se rompt. À huit mille kilomètres, ce grand ancien pays, qui a transmis la civilisation humaine et n'a jamais été interrompu, disparaît ainsi de l'histoire humaine, tel un nuage de fumée."
  },
  AvgDialog_131208_Content_66 = {Text = "新增"},
  AvgDialog_131208_Content_67 = {
    Text = "Humains. Art. Ville. Nation. Civilisation."
  },
  AvgDialog_131208_Content_68 = {
    Text = "Tout s'effondre, tout disparaît."
  },
  AvgDialog_131208_Content_69 = {
    Text = "<Shake:Tu vois, Xiaofu ?> Mon premier enfant est mort... Je l'ai tué de mes propres mains."
  },
  AvgDialog_131208_Content_7 = {Text = "Cui, cui."},
  AvgDialog_131208_Content_70 = {
    Text = "Les larmes tombent paisiblement. Arachne sourit faiblement en regardant par la fenêtre. Au milieu des ruines du monde entier, il ne reste que ce manoir précaire à l'extérieur qui se tient encore debout."
  },
  AvgDialog_131208_Content_71 = {
    Text = "J'ai souvent pensé que, en tissant le destin, si je pouvais toujours regarder l'endroit où j'ai vécu autrefois, cela me rendrait ce chemin moins solitaire."
  },
  AvgDialog_131208_Content_72 = {
    Text = "C'est vraiment puéril... Pour un bourreau sans choix, je me suis infligé la punition la plus cruelle."
  },
  AvgDialog_131208_Content_73 = {
    Text = "Elle tendit la main, agitant ce fil flou au-dessus de sa tête, qu'elle ne pouvait pas distinguer, reliant une partie de celui-ci à la dernière lueur de fil dans ce monde."
  },
  AvgDialog_131208_Content_74 = {
    Text = "Maître, c'est... ?"
  },
  AvgDialog_131208_Content_75 = {
    Text = "Le romantisme engendre la stupidité, la bonté engendre la fragilité, les souvenirs engendrent la douleur..."
  },
  AvgDialog_131208_Content_76 = {
    Text = "J'ai bien réfléchi, petite Fu. Je suis l'exécuteur maudit, ces belles choses ne devraient pas exister en moi."
  },
  AvgDialog_131208_Content_77 = {
    Text = "Tu vas... éteindre une part de toi-même ? Mais ce sont les morceaux auxquels tu tiens le plus — comment peux-tu..."
  },
  AvgDialog_131208_Content_78 = {
    Text = "Quand j'étais tout petit, j'ai fait mon premier rêve."
  },
  AvgDialog_131208_Content_79 = {
    Text = "Arachne tendit la main et attrape ce rayon de soleil qui illumine les ruines sans fin."
  },
  AvgDialog_131208_Content_8 = {
    Text = "Le vieux rouet émettait un accompagnement doux, la jeune fille assise devant le rouet fredonnait une chanson à la mélodie simple."
  },
  AvgDialog_131208_Content_80 = {
    Text = "Dans le rêve, je marche sur la surface d'un lac. À mes côtés se trouvent des ruines infinies et des ossements, tandis que sous la surface du lac, le reflet de mon enfance marche dans un beau royaume."
  },
  AvgDialog_131208_Content_81 = {
    Text = "Pas de mort, pas de souffrance, pas d'oubli. Le doux soleil brille toujours là-bas, la foule chante joyeusement à ses côtés, sans jamais s'arrêter..."
  },
  AvgDialog_131208_Content_82 = {
    Text = "Je ne peux pas voir où mon fil mène, mais je pense que je comprends maintenant le destin que ce rêve préfigure."
  },
  AvgDialog_131208_Content_83 = {
    Text = "Elle s'efforça de tirer sur le coin de ses lèvres, peut-être envers sa servante, ou peut-être envers autre chose."
  },
  AvgDialog_131208_Content_84 = {
    Text = "mère a dit que si l'on inverse le nom d'Arachne, cela se prononce Nefraea. Dans la légende de ce monde, c'est le nom de la déesse du printemps."
  },
  AvgDialog_131208_Content_85 = {
    Text = "J'aime chaque saison, surtout le printemps. Le printemps est bien plus petit que le destin, beaucoup, beaucoup plus petit. Mais le destin mène toujours à la mort, alors que le printemps, le printemps n'apporte que la nouveauté..."
  },
  AvgDialog_131208_Content_86 = {
    Text = "Elle regarde par la fenêtre. Des deux côtés du rebord, le destin et le printemps se croisent une dernière fois."
  },
  AvgDialog_131208_Content_87 = {
    Text = "Pars de moi, mon reflet, ma chère sœur. Avec toutes nos belles qualités et tous nos beaux souvenirs."
  },
  AvgDialog_131208_Content_88 = {
    Text = "Destin... J'offre une part de moi-même en sacrifice total. Je parcourrai ce chemin ardu à sa place."
  },
  AvgDialog_131208_Content_89 = {
    Text = "Arachne caressait doucement le fil emmêlé. Le fil tremblait légèrement, comme s'il luttait et criait."
  },
  AvgDialog_131208_Content_9 = {
    Text = "Un rayon de soleil filtre par la fenêtre, illuminant une plaque gravée du nom « Moïra » à côté du rouet."
  },
  AvgDialog_131208_Content_90 = {
    Text = "Ses larmes traversent le fil et tombent sur la plaque gravée « Moïra »."
  },
  AvgDialog_131208_Content_91 = {
    Text = "Tu es libre, «Arachne»."
  },
  AvgDialog_131208_Content_92 = {Text = "Cric."},
  AvgDialog_131208_Content_93 = {
    Text = "Le fil se rompt. Sous le doux soleil printanier, le rouet pousse son dernier soupir."
  },
  AvgDialog_131209_Content_1 = {
    Text = "Rencontre à nouveau"
  },
  AvgDialog_131209_Content_10 = {
    Text = "Si je choisis de devenir un chanteur d'opéra, la file d'attente pour acheter des billets au théâtre s'étendra sûrement sur trois pâtés de maisons."
  },
  AvgDialog_131209_Content_11 = {
    Text = "Quel dommage que les marionnettes de Londinium n'aient pas eu la chance de voir ma performance exceptionnelle. En y réfléchissant, tu es vraiment chanceux, petit mignon."
  },
  AvgDialog_131209_Content_12 = {
    Text = "Nefraea caressa doucement le visage de la fille avec tendresse, comme une mère qui chérissait sa fille."
  },
  AvgDialog_131209_Content_13 = {
    Text = "Au centre de la nef de l'église, des clous en acier traversent la poitrine, les épaules, les tibias et les paumes de la fille, perforant chaque partie de son corps propice à la suspension et à la perception de la douleur, la clouant fermement à un immense chandelier en forme de rouet."
  },
  AvgDialog_131209_Content_14 = {
    Text = "Nefraea rapprocha ses mains couvertes de sang de son nez et ferma les yeux, fascinée."
  },
  AvgDialog_131209_Content_15 = {
    Text = "Ah... le goût de la vie, si vivant."
  },
  AvgDialog_131209_Content_16 = {
    Text = "Ces dernières années, j'ai essayé de nombreuses fois de mordre le corps des enfants, de mordre mon propre corps, mais je ne peux même pas goûter un peu de la saveur de la vie."
  },
  AvgDialog_131209_Content_17 = {
    Text = "Un destin correct. Une vie ardente. Comme c'est enviable... Mais sais-tu quoi ? Tu devrais, comme nous, être jeté dans la poubelle du destin."
  },
  AvgDialog_131209_Content_18 = {
    Text = "Tu n'as pas besoin de manger, tu ne parles jamais. À part les souvenirs que tu as gardés pour elle, tu n'as rien, tu ne sais rien."
  },
  AvgDialog_131209_Content_19 = {
    Text = "Le destin t'a déjà abandonné, pauvre petit. Tu n'es qu'une poupée pour la consoler, un gardien des souvenirs qu'elle surveille, errant seul sur cette scène hypocrite..."
  },
  AvgDialog_131209_Content_2 = {
    Text = "<Shake:La...♪ La la...♪>"
  },
  AvgDialog_131209_Content_20 = {
    Text = "Elle regardait la fille qui avait presque perdu son souffle, sa voix chuchotante tremblant de tristesse, ses doigts glacés arrangeant doucement les mèches éparpillées sur le front de la fille."
  },
  AvgDialog_131209_Content_21 = {
    Text = "Maintenant, ta mère, ce cruel destin, arrive... Quoi qu'il arrive, fais face à tout avec le plus beau des visages, tu comprends, ma chère ?"
  },
  AvgDialog_131209_Content_22 = {Text = "新增"},
  AvgDialog_131209_Content_23 = {
    Text = "Après que tes yeux se soient adaptés à la lumière sombre de l'église, ce qui attire d'abord ton regard est un ensemble de gigantesques fresques."
  },
  AvgDialog_131209_Content_24 = {
    Text = "Des teintures visqueuses sont étalées sur un mur de plusieurs dizaines de mètres de haut, s'étendant sans fin dans l'obscurité insondable. Majestueux, sacré, impur, semblable à une statue de saint sauveur se tenant dans les égouts."
  },
  AvgDialog_131209_Content_25 = {
    Text = "La maîtresse des lieux, compréhensive, a dégagé l'espace pour les visiteurs. Dans l'église vide, seuls résonnent les échos des pas et des respirations. Tu te trouves sous une immense fresque, levant la tête pour l'admirer."
  },
  AvgDialog_131209_Content_26 = {
    Text = "Une femme est assise devant le rouet, coupant le fil de soie avec des ciseaux... Cette fresque te représente ?"
  },
  AvgDialog_131209_Content_27 = {
    Text = "Il semble que ce soit le cas... Je pense que c'est ce que ma sœur voulait nous dire."
  },
  AvgDialog_131209_Content_28 = {
    Text = "Arachne ne se pressait pas de chercher le lieu des «Souvenirs». Elle suivait tes pas, observant avec intérêt ces fresques."
  },
  AvgDialog_131209_Content_29 = {
    Text = "Une silhouette identique, quittant la femme assise, tombe dans les ténèbres de la caverne..."
  },
  AvgDialog_131209_Content_3 = {
    Text = "Cuiii—— Cuiii—— la déesse du destin fait tourner son rouet."
  },
  AvgDialog_131209_Content_30 = {
    Text = "Dans la grotte obscure, une femme et d'autres créatures de la nuit exécutent une danse étrange. Elle tient... un rouet ?"
  },
  AvgDialog_131209_Content_31 = {
    Text = "Le centre brille comme une Lanterne, illuminant les ombres."
  },
  AvgDialog_131209_Content_32 = {
    Text = "Une femme portant une lanterne en forme de roue à filer est arrivée en ville... Un groupe de personnes en robes sacerdotales s'inclinent devant la femme et la lanterne. Ce qui est gravé sur leurs vêtements... est le symbole de la lanterne ?"
  },
  AvgDialog_131209_Content_33 = {
    Text = "Il y a quelques différences subtiles avec le symbole de la lanterne que tu as déjà vu, à l'extérieur de ce triangle inversé maléfique, il y a un cercle ressemblant à une roue de fil."
  },
  AvgDialog_131209_Content_34 = {
    Text = "Mais tu comprends chaque élément de ce symbole. Tu sais clairement que c'est l'emblème de l'Église de la Lanterne, c'est la naissance de l'Église de la Lanterne."
  },
  AvgDialog_131209_Content_35 = {
    Text = "Dernière œuvre..."
  },
  AvgDialog_131209_Content_36 = {
    Text = "La dernière fresque se dresse au bout du couloir, comme une porte qui sépare du destin. Des couleurs sales ondulent sur la fresque, reflétant les ombres troubles de l'église."
  },
  AvgDialog_131209_Content_37 = {
    Text = "Une femme tient une Lanterne, agenouillée devant une silhouette floue. Derrière eux se dresse quelque chose d'énorme..."
  },
  AvgDialog_131209_Content_38 = {Text = "Ugh..."},
  AvgDialog_131209_Content_39 = {
    Text = "Lorsque tu reconnais ce gigantesque globe oculaire encore fermé, une douleur aiguë familière t'assaillit, soulevant une vague déferlante dans ton espace mental."
  },
  AvgDialog_131209_Content_4 = {
    Text = "Cuiii—— Cuiii—— Les fils du destin se rassemblent dans sa main."
  },
  AvgDialog_131209_Content_40 = {
    Text = "Vous détournez rapidement le regard et prenez une profonde inspiration pour contenir la vague de nausée montante."
  },
  AvgDialog_131209_Content_41 = {
    Text = "<Shake:Huff... huff...> L'Église des Porteurs de Lumière... Touva Wave..."
  },
  AvgDialog_131209_Content_42 = {
    Text = "Dans cette Dimension, Nefraea est en fait... le créateur de l'Église de la Lanterne"
  },
  AvgDialog_131209_Content_43 = {
    Text = "Ah, je comprends !......"
  },
  AvgDialog_131209_Content_44 = {
    Text = "Vous avez vu la vérité, {Male=Mr.,Female=Miss} Gardien. Alors que la Divinité Suprême approchait de son éveil, ma sœur abandonnée s'est échappée du Gouffre."
  },
  AvgDialog_131209_Content_45 = {
    Text = "Elle a perturbé ma vue, cachant cette secte sous ma scène."
  },
  AvgDialog_131209_Content_46 = {
    Text = "Cette personne, qu'elle vénère, est l'apôtre qui relie ce dimension à cet Être suprême."
  },
  AvgDialog_131209_Content_47 = {
    Text = "Tu regardes à nouveau cette silhouette floue connectée à Touva Wave sur la fresque murale."
  },
  AvgDialog_131209_Content_48 = {
    Text = "Je comprends... Ce que Nefraea veut faire, c'est s'appuyer sur la force de cet Apôtre pour rétablir la connexion avec Touva Wave !..."
  },
  AvgDialog_131209_Content_49 = {
    Text = "Mais alors, pourquoi veut-elle chasser ces objets secrets..."
  },
  AvgDialog_131209_Content_5 = {
    Text = "Les marionnettes font la queue pour entrer, foulant le gigantesque filet du destin."
  },
  AvgDialog_131209_Content_50 = {Text = "Dong——"},
  AvgDialog_131209_Content_51 = {
    Text = "Le son trouble des cloches résonne depuis le clocher de l'église, comme un décret sale."
  },
  AvgDialog_131209_Content_52 = {
    Text = "La gigantesque église gronde sourdement. Dans la longue vibration, les murs en pierre ornés de fresques souillées s'élèvent lentement."
  },
  AvgDialog_131209_Content_53 = {Text = "C'est !!"},
  AvgDialog_131209_Content_54 = {
    Text = "Arachne... Madame..."
  },
  AvgDialog_131209_Content_55 = {
    Text = "Ah là là... Nos petites «souvenirs», leur son est vraiment faible au point d'être pitoyable."
  },
  AvgDialog_131209_Content_56 = {
    Text = "Nefraea ! Lâcher-la"
  },
  AvgDialog_131209_Content_57 = {
    Text = "Le corps de la jeune fille est suspendu à la majestueuse structure de la roue à filer, le sang écarlate s'écoule lentement sur le marbre blanc."
  },
  AvgDialog_131209_Content_58 = {
    Text = "Une lumière brillante éclaire derrière la fille, dessinant une silhouette sacrée pour ce corps ensanglanté."
  },
  AvgDialog_131209_Content_59 = {
    Text = "Nefraea, ne fais plus ces combats inutiles. Lâche-la."
  },
  AvgDialog_131209_Content_6 = {
    Text = "Ils dansent. Ils chantent. Cui cui—— Cui cui——"
  },
  AvgDialog_131209_Content_60 = {
    Text = "Oh ? Notre déesse du destin commence maintenant à se soucier de ses « souvenirs » ?"
  },
  AvgDialog_131209_Content_61 = {
    Text = "Tu ne t'es jamais soucié d'eux, tu les as abandonnés, Arachne."
  },
  AvgDialog_131209_Content_62 = {
    Text = "Nefraea, je sais que tu veux invoquer des apôtres, réveiller à nouveau Touva Wave... S'il y a quelque chose, nous pouvons en discuter, il n'est pas nécessaire de les tuer..."
  },
  AvgDialog_131209_Content_63 = {
    Text = "Votre façon de gagner du temps est adorablement puérile, %player%."
  },
  AvgDialog_131209_Content_64 = {
    Text = "Tu ne comprends rien. Je ne les ai jamais tués. Je suis juste en train de les ramener chez eux."
  },
  AvgDialog_131209_Content_65 = {
    Text = "Je vous ai amenés ici juste pour que vous puissiez témoigner de leur fin parfaite."
  },
  AvgDialog_131209_Content_66 = {
    Text = "Deuxième acte, troisième scène. Je l'ai intitulé « Réunion »."
  },
  AvgDialog_131209_Content_67 = {
    Text = "Nefraea te regarda avec mépris. Ses ongles effleurèrent le visage de «Souvenir», laissant une fine trace de Sang."
  },
  AvgDialog_131209_Content_68 = {
    Text = "Elle s'est penchée, regardant avec tendresse le visage de la fille qui tremble de faiblesse et de peur."
  },
  AvgDialog_131209_Content_69 = {
    Text = "Bon enfant, n'aie pas peur. Nous serons bientôt à la maison."
  },
  AvgDialog_131209_Content_7 = {
    Text = "Elles sont mortes avec le grand filet, silencieusement."
  },
  AvgDialog_131209_Content_70 = {
    Text = "Disons adieu à tes souvenirs désagréables, ma chère grande sœur——"
  },
  AvgDialog_131209_Content_71 = {
    Text = "Attends... Nefraea !"
  },
  AvgDialog_131209_Content_72 = {Text = "Clac —"},
  AvgDialog_131209_Content_73 = {
    Text = "Au son cristallin des claquements de doigts de Nefraea, le corps de la fille éclate comme un feu d'artifice rouge vif."
  },
  AvgDialog_131209_Content_74 = {
    Text = "La lumière de la lanterne éclaire les éclaboussures de sang, projetant sur vos visages une fleur écarlate."
  },
  AvgDialog_131209_Content_75 = {
    Text = "Des gouttes de sang éclaboussent dans les airs, s'arrêtent, puis reviennent, rampant goulûment vers le corps de Nefraea, teintant chaque pouce de son corps en rouge."
  },
  AvgDialog_131209_Content_76 = {
    Text = "Les perles de sang continuent de descendre, de descendre, s'infiltrant dans ses vêtements et sa peau, s'infiltrant dans chacune de ses veines, déferlant dans son corps frêle."
  },
  AvgDialog_131209_Content_77 = {
    Text = "La langue léchait le sang au bord des lèvres, Nefraea admirait avec plaisir ses ongles teintés de rouge, tel une hôtesse élégante, prête à accueillir un festin de rétablissement."
  },
  AvgDialog_131209_Content_78 = {
    Text = "Bienvenue chez vous, cher."
  },
  AvgDialog_131209_Content_79 = {Text = "Arrête !"},
  AvgDialog_131209_Content_8 = {
    Text = "Le chant résonne dans l'immense église. Nefraea ouvre les bras, appréciant sa réverbération."
  },
  AvgDialog_131209_Content_80 = {
    Text = "La lumière argentée s'épanouit dans ta main, tu te précipites vers Nefraea."
  },
  AvgDialog_131209_Content_81 = {
    Text = "Sous la lumière sacrée et sanglante, d'innombrables ombres noires s'étendent sur les fresques souillées, bloquant votre chemin..."
  },
  AvgDialog_131209_Content_9 = {
    Text = "Comment était mon chant ?"
  },
  AvgDialog_131210_Content_1 = {
    Text = "Je ne m'attendais pas à te revoir dans un état aussi pitoyable."
  },
  AvgDialog_131210_Content_2 = {Text = "Thais..."},
  AvgDialog_131210_Content_3 = {
    Text = "Tawil a raison. Tout va bien, Gardien."
  },
  AvgDialog_131210_Content_4 = {
    Text = "Tu as dit que tu me ferais témoigner d'une autre fin. Je crois en toi, depuis le début jusqu'à la fin."
  },
  AvgDialog_131210_Content_5 = {
    Text = "Que tu sois ici ou que tu me dépasses, je suis toujours à tes côtés."
  },
  AvgDialog_131211_Content_1 = {Text = "Cocon"},
  AvgDialog_131211_Content_10 = {
    Text = "Je ne veux pas revivre cette expérience une seconde fois..."
  },
  AvgDialog_131211_Content_11 = {
    Text = "Vous n›êtes pas sûr de le penser vraiment. Vous serrez le poing, vous réajustant au corps que vous venez de partager avec « N »."
  },
  AvgDialog_131211_Content_12 = {
    Text = "Ta vue devient progressivement claire, tu te frottes la tête douloureuse et tu t'approches de la silhouette frêle agenouillée au bord de la scène."
  },
  AvgDialog_131211_Content_13 = {
    Text = "Nefraea, ton plan est déjà..."
  },
  AvgDialog_131211_Content_14 = {Text = "Attention."},
  AvgDialog_131211_Content_16 = {
    Text = "Comme si des fils étaient doucement tirés, tes pas ralentissent d'un cran. Une griffe noire et acérée frôle presque tes yeux, passant juste devant toi."
  },
  AvgDialog_131211_Content_17 = {
    Text = "Huit énormes membres venimeux déchirent les vêtements de son dos, se balançant dans les airs, se tordant, luttant. Nefraea semble totalement indifférente à tout cela."
  },
  AvgDialog_131211_Content_18 = {
    Text = "Des fragments du canal dimensionnel flottent autour d'elle comme des feux d'artifice tombant. Ses larmes tombent, mouillant la roue de fil terne qui a perdu sa lumière."
  },
  AvgDialog_131211_Content_19 = {
    Text = "Le passage dimensionnel a disparu, vous n'avez plus d'opportunité."
  },
  AvgDialog_131211_Content_2 = {
    Text = "......Garde......"
  },
  AvgDialog_131211_Content_20 = {
    Text = "Le destin suit son cours, Nefraea. Accepte-le."
  },
  AvgDialog_131211_Content_21 = {
    Text = "Une opportunité ? ... Hehehe..."
  },
  AvgDialog_131211_Content_22 = {
    Text = "La silhouette frêle tremble de rire, traçant dans l'air des trajectoires sinistres avec ces membres empoisonnés."
  },
  AvgDialog_131211_Content_23 = {
    Text = "Je n'ai jamais eu d'opportunité, et je n'ai jamais eu besoin d'opportunité."
  },
  AvgDialog_131211_Content_24 = {
    Text = "Liberté, enfance, famille, amour, soi... Le destin nous a tout pris, je ne serai jamais, jamais comme toi, un prisonnier de celui-ci."
  },
  AvgDialog_131211_Content_25 = {
    Text = "Nefraea se leva lentement, plaçant son corps dans ce rouet sombre et brisé."
  },
  AvgDialog_131211_Content_26 = {
    Text = "Regarde bien, Arachne ! Les choses que tu désires tant mais que tu n'oses pas faire, je vais les faire à ta place"
  },
  AvgDialog_131211_Content_27 = {
    Text = "Presque dans un cri de colère, le corps de Nefraea semblait être traversé en un instant par d'innombrables épines. Du sang s'écoulait de son corps, se connectant à ce rouet brisé, comme un filet sanglant."
  },
  AvgDialog_131211_Content_28 = {
    Text = "<Shake:@2— !>"
  },
  AvgDialog_131211_Content_29 = {
    Text = "Un hurlement aigu insupportable pour les humains émanait de la tête de Nefraea. Son corps tremblait de douleur intense, des veines violettes foncées se dessinaient clairement sur son corps."
  },
  AvgDialog_131211_Content_3 = {
    Text = "{Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131211_Content_30 = {
    Text = "Les fragments du canal dimensionnel semblent avoir été attirés par quelque chose, cessant de se disperser, se rassemblant lentement vers ce filet tissé de sang. Le rouet terne a ravivé une lueur sanguinolente."
  },
  AvgDialog_131211_Content_31 = {
    Text = "Heh... Hahaha ! <Big:<Shake:S›il n›y a pas de dieux, j›en deviendrai un !>>"
  },
  AvgDialog_131211_Content_32 = {
    Text = "Mon histoire... ma scène... ne prendront jamais fin ! J›apporterai la libération à cette toile qui n›aurait jamais dû exister... <Big:<Shake:<Red:la libération !!!>>>"
  },
  AvgDialog_131211_Content_33 = {
    Text = "Dans les hurlements de douleur de Nefraea, tout le Théâtre du Destin tremble violemment. Les marionnettes sur scène se renversent et se heurtent, les fils qui les relient s'emmêlent dans le désordre..."
  },
  AvgDialog_131211_Content_34 = {
    Text = "Arachne regardait au loin la silhouette corrompue par la force et la folie des fragments de dimension. Une vague de tristesse surgit dans ses yeux, profonds comme un abîme, comme le jour où elle s'était enfin débarrassée d'elle-même."
  },
  AvgDialog_131211_Content_35 = {
    Text = "J'ai essayé de te libérer de cette malédiction... Malheureusement, j'avais tort, Nefraea."
  },
  AvgDialog_131211_Content_36 = {
    Text = "La malédiction est inévitable, la cage, nous ne pouvons jamais y échapper..."
  },
  AvgDialog_131211_Content_37 = {
    Text = "Ces fragments... ce rouet..."
  },
  AvgDialog_131211_Content_38 = {
    Text = "Nefraea est en train d'absorber la force résiduelle dans le passage dimensionnel ! Elle... elle veut se transformer en mèche !!"
  },
  AvgDialog_131211_Content_39 = {
    Text = "Un léger soupir résonne clairement dans ce théâtre précaire."
  },
  AvgDialog_131211_Content_4 = {
    Text = "<Shake:Ugh... tousse, tousse...>"
  },
  AvgDialog_131211_Content_40 = {
    Text = "Tenez bon, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131211_Content_41 = {Text = "Quoi..."},
  AvgDialog_131211_Content_42 = {
    Text = "<Shake:Boum—>"
  },
  AvgDialog_131211_Content_43 = {
    Text = "À peine le mot prononcé, tout le théâtre se déchira soudainement. Nefraea déchirait furieusement les fils du destin, tandis que dans l'horreur de la déchirure, les bâtiments de la ville s'entremêlaient avec des débris multicolores de dimension."
  },
  AvgDialog_131211_Content_44 = {
    Text = "La scène principale du théâtre se brise en plusieurs morceaux, des fragments du passé, du futur et du présent s'entrelacent de manière chaotique sur la scène brisée, reconstituant une image que tu ne peux comprendre."
  },
  AvgDialog_131211_Content_45 = {
    Text = "Arachne... ta toile..."
  },
  AvgDialog_131211_Content_46 = {
    Text = "Le rouet dans les mains d'Arachne tourne rapidement, une vaste cendre de dimension jaillit de son corps, suivant les fils du rouet pour combler les creux brisés sur la toile du destin, maintenant à grand peine la scène à l'abri d'un destin effondrant."
  },
  AvgDialog_131211_Content_47 = {
    Text = "Sous l'emprise des fils, tu te lèves difficilement."
  },
  AvgDialog_131211_Content_48 = {
    Text = "Absorber sa force éparpillée, changer le cours de toute la Toile du destin... Tu n'es pas un de ses fragments, tu ne peux pas supporter une telle pression. Tu n'as pas à disparaître aussi douloureusement, Nefraea."
  },
  AvgDialog_131211_Content_49 = {
    Text = "Douleur ? Non, je suis très heureux, grande sœur ! Dans les nombreuses années passées dans l'abîme, je fantasmais chaque instant sur ce jour."
  },
  AvgDialog_131211_Content_5 = {
    Text = "Que s'est-il passé..."
  },
  AvgDialog_131211_Content_50 = {
    Text = "C'est cette illusion qui m'a permis de tenir jusqu'à aujourd'hui..."
  },
  AvgDialog_131211_Content_51 = {
    Text = "Le rire de folie de Nefraea résonne dans l'espace brisé du théâtre. Elle lève la tête, absorbant avidement les lueurs sombres des fragments."
  },
  AvgDialog_131211_Content_52 = {
    Text = "Le dieu tombé dans un sommeil profond, l'apôtre dont le destin a été volé... ha ha ha ha... peu importe, rien ne peut m'arrêter. Puisque le dieu ne peut apporter de bénédiction, alors je vais le faire à sa place !"
  },
  AvgDialog_131211_Content_53 = {
    Text = "Vengeurs du Destin, en scène ! <Red:Cet acte vous appartient !>"
  },
  AvgDialog_131211_Content_54 = {
    Text = "Nefraea leva soudainement la main. Une immense boue noire sans fin jaillit de Nefraea, tissant une toile noire dans le vide de ce théâtre."
  },
  AvgDialog_131211_Content_55 = {
    Text = "D›innombrables rancœurs, autrefois rejetées par le Destin, prennent forme physique. Elles rampent le long de l›immense toile en une marée écrasante, déferlant vers vous."
  },
  AvgDialog_131211_Content_56 = {
    Text = "Arachne, sur nous... !"
  },
  AvgDialog_131211_Content_57 = {
    Text = "Tu découvres soudainement qu'un fil noir, que tu peux voir, apparaît vaguement du corps d'Arachne."
  },
  AvgDialog_131211_Content_58 = {
    Text = "Tu lèves la tête et vois un fil noir flou s'étendre de toi, de chaque scène, de chaque corps de marionnette, vers le rouet dans les mains de Nefraea."
  },
  AvgDialog_131211_Content_59 = {
    Text = "Salutations, Arachne ! Bénédiction à toi, déesse du Destin"
  },
  AvgDialog_131211_Content_6 = {
    Text = "Un vertige intense et des spasmes gastriques sont les débris laissés par le plaisir, tu réprimes ton malaise et te redresses lentement."
  },
  AvgDialog_131211_Content_60 = {
    Text = "Venez, tirez vos lames, soldats ! Battez-vous pour notre destin"
  },
  AvgDialog_131211_Content_61 = {
    Text = "Mademoiselle Arachne, reconnaissez votre destin... ne résistez plus inutilement..."
  },
  AvgDialog_131211_Content_62 = {
    Text = "Ne t'inquiète pas, mon cher. Ta libération arrive bientôt, très bientôt..."
  },
  AvgDialog_131211_Content_63 = {
    Text = "La roue sombre de Nefraea tourne follement, les marionnettes sur scène se transforment en ombres dans le gouffre, marchant sur le nouveau filet noir sous l'attraction des fils."
  },
  AvgDialog_131211_Content_64 = {
    Text = "Arachne ferme lentement les yeux, sa main serrant le fil tremble légèrement de douleur."
  },
  AvgDialog_131211_Content_65 = {
    Text = "Nefraea, elles ne peuvent pas t'aider à devenir ce dieu capable de détruire tous les destins... Ce que tu fais, c'est simplement leur faire connaître une nouvelle souffrance et une nouvelle disparition."
  },
  AvgDialog_131211_Content_66 = {
    Text = "Alors, qu'est-ce que ça change ? La vengeance, à part la vengeance, nous ne demandons rien d'autre ! N'est-ce pas, enfants abandonnés du destin ?"
  },
  AvgDialog_131211_Content_67 = {
    Text = "<Shake:Heh... hahaha !>"
  },
  AvgDialog_131211_Content_68 = {
    Text = "Un rire aigu, majestueux et perçant résonne à travers la toile d'araignée noire infinie, tel un chœur de douleur."
  },
  AvgDialog_131211_Content_69 = {
    Text = "Ces destins abandonnés riaient aux éclats et hurlaient, se tenant devant Nefraea."
  },
  AvgDialog_131211_Content_7 = {
    Text = "La conscience de l'Apôtre a quitté le rouet et a perdu sa connexion avec le divin, elle est maintenant complètement détruite. La force du plasmide est également revenue au calme."
  },
  AvgDialog_131211_Content_70 = {
    Text = "Maintenant, la Porte du Gouffre est complètement ouverte. Viens, Arachne, regarde ces destins que tu as créés de tes propres mains, regarde tes chers enfants"
  },
  AvgDialog_131211_Content_71 = {
    Text = "Regardez leur douleur, leur désespoir... Regardez-les, puis tuez-les à nouveau"
  },
  AvgDialog_131211_Content_72 = {
    Text = "Regarde le destin de tout tourner entre mes mains, détruis !... Regarde-moi, deviens ce dieu qui apporte la fin"
  },
  AvgDialog_131211_Content_73 = {
    Text = "Des fragments de dimension, porteurs de la force des divinités et de la volonté de frénésie, s'enfoncent un à un dans le corps de Nefraea, le sang s'écoulant sans cesse dans le rouet de Nefraea."
  },
  AvgDialog_131211_Content_74 = {
    Text = "Son visage se tord d›agonie, mais son rire ne fait que devenir plus frénétique."
  },
  AvgDialog_131211_Content_75 = {
    Text = "Elle regarde avec impatience la scène brisée, comme une dramaturge attendant la première représentation de son œuvre."
  },
  AvgDialog_131211_Content_76 = {
    Text = "Ce gouffre du destin est déjà descendu sur cette danse... Nefraea est en train de se sacrifier."
  },
  AvgDialog_131211_Content_77 = {
    Text = "Elle veut transformer tout ici, y compris nous, en ses marionnettes. Elle veut devenir cette personne divine. Elle... veut devenir le destin lui-même."
  },
  AvgDialog_131211_Content_78 = {
    Text = "Le ton calme d'Arachne semblait appartenir à une personne qui n'avait jamais été impliquée dans l'histoire. Les cendres de dimension, récupérées, flottaient autour de ses doigts comme du sable léger, sans fin."
  },
  AvgDialog_131211_Content_79 = {
    Text = "Sa roue de filage tournait difficilement, s'efforçant de maintenir les destins qui étaient détruits par Nefraea, empêchant les fils noirs de s'unir entre les mains de Nefraea."
  },
  AvgDialog_131211_Content_8 = {
    Text = "Tu as réalisé une performance brillante."
  },
  AvgDialog_131211_Content_80 = {
    Text = "Les cendres de la dimension ont été récupérées, aujourd'hui je n'ai plus de préoccupations."
  },
  AvgDialog_131211_Content_81 = {
    Text = "Veuillez m'aider, rapprochez-vous d'elle. Le rouet de Nefraea va cesser de tourner, ce destin erroné, je vais le corriger avec vous."
  },
  AvgDialog_131211_Content_82 = {
    Text = "Aidez-moi... apportez du soulagement à ces destinées abandonnées."
  },
  AvgDialog_131211_Content_9 = {
    Text = "Ouf... Je n'arrive vraiment pas à croire que ce que je viens de dire soit sorti de ma bouche."
  },
  AvgDialog_131212_Content_1 = {
    Text = "Au même moment\nde l'autre côté de la ville"
  },
  AvgDialog_131212_Content_10 = {
    Text = "Le numéro six a été choisi par le duc dans l'écurie du manoir pour être envoyé au champ de courses. Cette fois, le numéro six va sûrement gagner. Écoute-moi, parie sur le numéro six, tu ne te tromperas pas"
  },
  AvgDialog_131212_Content_11 = {
    Text = "Le bruit des bavardages dans le métro forme un ruisseau vibrant, Arachne regarde silencieusement les lumières qui s'approchent et s'éloignent par la fenêtre, souriant en écoutant ses marionnettes parler de spectacles, de courses de chevaux et de mariages."
  },
  AvgDialog_131212_Content_12 = {
    Text = "Elle fait doucement tourner le rouet qu'elle tient dans ses mains. Parmi ces milliards de fils complexes, elle savoure ce moment de paix."
  },
  AvgDialog_131212_Content_13 = {
    Text = "Maître, notre destination approche. La calèche pour le transfert est prête, et nos sœurs vous attendent là-bas."
  },
  AvgDialog_131212_Content_14 = {
    Text = "Bon enfant."
  },
  AvgDialog_131212_Content_15 = {
    Text = "Elle jeta un regard un peu réticent autour de ces marionnettes qui jouaient encore, comme un spectateur qui n'ose pas quitter son siège."
  },
  AvgDialog_131212_Content_16 = {
    Text = "Te souviens-tu combien de temps nous n'avons pas quitté le théâtre ?"
  },
  AvgDialog_131212_Content_17 = {
    Text = "Depuis le jour où je suis devenu l'araignée froide, je suis resté à vos côtés sans jamais vous quitter. Jusqu'à présent... cinquante ans ? Ou soixante ans ? Je ne m'en souviens plus très bien."
  },
  AvgDialog_131212_Content_18 = {
    Text = "Mais cette fois, le temps passé en dehors du théâtre est déjà un peu trop long."
  },
  AvgDialog_131212_Content_19 = {
    Text = "Je dois remercier Nefraea. Sans son arrivée, je n'aurais pas eu l'occasion de rester aussi longtemps devant le théâtre."
  },
  AvgDialog_131212_Content_2 = {
    Text = "Monsieur, veuillez montrer votre billet."
  },
  AvgDialog_131212_Content_20 = {
    Text = "En coordination avec les actions du Gardien du Secret, nous avons déjà éliminé des centaines de serviteurs venus des Abîmes ces derniers jours. Une fois que nous aurons sauvé « le Souvenir », nous devrons retourner au théâtre."
  },
  AvgDialog_131212_Content_21 = {
    Text = "La prochaine fois que j'aurai l'occasion de sortir, je ne sais pas quand ce sera..."
  },
  AvgDialog_131212_Content_22 = {
    Text = "Il semble que les pensées d'Arachne aient été perçues, et les lumières à l'extérieur du métro se sont assombries. Elle regardait par la fenêtre dans les ténèbres, cherchant dans les souvenirs de civilisations innombrables celles qui parlaient de ses souvenirs ordinaires."
  },
  AvgDialog_131212_Content_23 = {
    Text = "Les aiguilles de l'horloge tournent pendant deux secondes. Le maître de la ville remarque que les conversations fluides dans le métro semblent disparaître au moment où le wagon entre dans l'obscurité."
  },
  AvgDialog_131212_Content_24 = {
    Text = "Maître, il semble qu'il y ait quelque chose..."
  },
  AvgDialog_131212_Content_25 = {Text = "Karab—"},
  AvgDialog_131212_Content_26 = {
    Text = "Le sang glacé de la servante éclabousse le visage calme d'Arachne, dégageant un parfum semblable à celui des iris."
  },
  AvgDialog_131212_Content_27 = {
    Text = "La lumière s'allume dehors. Arachne voit le corps de la servante découpé, la lame qui traverse son corps et continue vers elle, ainsi que les poupées qui affluent vers elle comme une horde de bêtes."
  },
  AvgDialog_131212_Content_28 = {Text = "新增"},
  AvgDialog_131212_Content_29 = {
    Text = "Le système de freinage émet un bruit de friction fatigué, et la brise qu'il génère soulève les cheveux d'une autre servante."
  },
  AvgDialog_131212_Content_3 = {
    Text = "N'était-ce pas déjà vérifié à l'entrée ? C'est comme ça que l'argent des contribuables est gaspillé..."
  },
  AvgDialog_131212_Content_30 = {
    Text = "Ah ! Nous sommes arrivés"
  },
  AvgDialog_131212_Content_31 = {
    Text = "La porte s'ouvre, mais la foule bourdonnante n'apparaît pas. Seul un flot de sang au goût ferreux s'écoule entre chaque fissure de la porte, comme une symphonie silencieuse."
  },
  AvgDialog_131212_Content_32 = {
    Text = "En marchant sur cette rivière de sang accompagnée par la musique, Arachne sortit lentement de la voiture. Ses vêtements étaient impeccables, et son rouet continuait de tourner, sans jamais s'arrêter."
  },
  AvgDialog_131212_Content_33 = {Text = "C'est..."},
  AvgDialog_131212_Content_34 = {
    Text = "Une pièce de théâtre interactive fascinante. En tant que spectateur et acteur, l'expérience est en effet beaucoup plus passionnante que celle d'un dramaturge."
  },
  AvgDialog_131212_Content_35 = {
    Text = "Elle regarde la servante devant elle, son expression indéchiffrable."
  },
  AvgDialog_131212_Content_36 = {
    Text = "Ma servante est à mes côtés depuis de nombreuses années, je ne touche pas souvent aux fils du destin qui les relient."
  },
  AvgDialog_131212_Content_37 = {
    Text = "Dans ce théâtre ennuyeux, elles sont l'une des rares vies vivantes."
  },
  AvgDialog_131212_Content_38 = {
    Text = "Tu as tué mes deux servantes aujourd'hui. La destruction du destin a un prix, Nefraea."
  },
  AvgDialog_131212_Content_39 = {
    Text = "hahaha...<Shake:Ahahahaha !>Comme c'est noble, Arachne."
  },
  AvgDialog_131212_Content_4 = {
    Text = "Hé, Charlie, où est passée ma broche ?"
  },
  AvgDialog_131212_Content_40 = {
    Text = "Comme du beurre tombant dans une casserole de plomb brûlant, le corps de la servante commence à fondre. Sous le liquide noir bouillonnant et souillé, ce visage identique à celui d'Arachne éclate de rire."
  },
  AvgDialog_131212_Content_41 = {
    Text = "«Regarde, je suis le manipulateur du destin, le bourreau diligent ! Je choisirai les bons destins et plongerai toutes les erreurs dans l'abîme du néant...»"
  },
  AvgDialog_131212_Content_42 = {
    Text = "Tu es mon idole, ma croyance, chère grande sœur. Je ne fais que jouer le rôle que tu as assigné."
  },
  AvgDialog_131212_Content_43 = {
    Text = "Alors, en tant qu'apprenant, suis-je encore à la hauteur ?"
  },
  AvgDialog_131212_Content_44 = {
    Text = "Arachne regardait silencieusement les yeux qui se tournaient vers elle. Ils étaient ardents, brillants, pleins d'attente, semblant seulement venir d'une fille qui attendait que sa sœur l'apprécie."
  },
  AvgDialog_131212_Content_45 = {
    Text = "Sur le quai, à l'entrée des escaliers, dans les colonnes du couloir, dans le tunnel... Pendant qu'elle parlait, d'innombrables ombres apparaissaient à chaque endroit qu'elle pouvait imaginer."
  },
  AvgDialog_131212_Content_46 = {
    Text = "L'odeur trouble de l'ombre est étroitement liée, se rassemblant dans les mains de Nefraea, comme un immense filet se resserrant autour d'Arachne."
  },
  AvgDialog_131212_Content_47 = {
    Text = "Le coin de la bouche d'Arachne se leva doucement."
  },
  AvgDialog_131212_Content_48 = {
    Text = "Je n'ai jamais pensé que quelqu'un essaierait de me piéger avec un filet."
  },
  AvgDialog_131212_Content_49 = {
    Text = "As-tu déjà vu un ver à soie, sœur aînée ? C'est un insecte venant d'Extrême-Orient, qui passe ses journées à ne rien faire, ne sachant que manger sans cesse et produire de la soie... puis, attends que le cocon formé par la soie le piège et le tue."
  },
  AvgDialog_131212_Content_5 = {
    Text = "Quand tu es sorti, tu n'as pas mis tes vêtements ?"
  },
  AvgDialog_131212_Content_50 = {
    Text = "Presque tous tes serviteurs ont disparu dans les différents coins de cette ville, dans ce train. Elles t'ont accompagné et ont passé de longues années dans le vide."
  },
  AvgDialog_131212_Content_51 = {
    Text = "Tu leur as apporté une fin qui n'aurait jamais dû se produire. Le destin est inéluctable, Nefraea."
  },
  AvgDialog_131212_Content_52 = {
    Text = "Tu veux dire que leur fin devrait être de rester sagement dans cet abîme sombre, de sombrer dans un temps infini... n'est-ce pas, noble maître du destin ?"
  },
  AvgDialog_131212_Content_53 = {
    Text = "Nefraea a secoué la tête en riant."
  },
  AvgDialog_131212_Content_54 = {
    Text = "Je les aime plus que tu ne l'imagines, grande sœur. Mais elles m'ont dit que si la mort pouvait les préserver d'un destin d'emprisonnement, elles l'accueilleraient sans hésitation..."
  },
  AvgDialog_131212_Content_55 = {
    Text = "Après ce massacre dans le métro, combien de cendres te restent-il pour corriger le destin ?"
  },
  AvgDialog_131212_Content_56 = {
    Text = "Nefraea a fièrement levé la roue de fil noir qu'elle tenait dans sa main. Les innombrables fils s'étendant de la scène de la ville étaient tous connectés à cette roue de fil immobile."
  },
  AvgDialog_131212_Content_57 = {
    Text = "Le destin de cette ville est entre mes mains. Je n'ai pas la capacité de les contrôler, tant de choses intéressantes que je ne peux pas faire, quel dommage..."
  },
  AvgDialog_131212_Content_58 = {
    Text = "Cependant, heureusement, les réparer nécessite une quantité incalculable de cendres, tandis que la pollution n'en nécessite pas."
  },
  AvgDialog_131212_Content_59 = {
    Text = "Tant que je lâche doucement ma prise... ton théâtre, ta scène, deviendront le lit parfait du chaos, tout comme... tout comme l'endroit où j'ai séjourné pendant de nombreuses années."
  },
  AvgDialog_131212_Content_6 = {
    Text = "Mon dieu... J'ai préparé cette réunion pendant un mois entier ! Sans cette broche, cette robe n'est rien d'autre qu'un tissu pour recouvrir un cercueil..."
  },
  AvgDialog_131212_Content_60 = {
    Text = "Et toi, tu ne peux que regarder tout cela se produire. Rien ne peut être changé, rien ne peut être combattu..."
  },
  AvgDialog_131212_Content_61 = {
    Text = "Nefraea s'approcha d'Arachne et caressa attentivement son visage dont les émotions étaient indéfinissables."
  },
  AvgDialog_131212_Content_62 = {
    Text = "Que devrais-je faire, ma sœur... devrait-elle obéir sagement à mes ordres, ou devrions-nous ensemble admirer la façon dont ce monde est devenu un enfer ?"
  },
  AvgDialog_131212_Content_63 = {
    Text = "Tu es un destin incomplet, polluant le destin de toute la ville, tu n'as pas la capacité de..."
  },
  AvgDialog_131212_Content_64 = {
    Text = "Un bruit de filament se brisant résonna à l'oreille d'Arachne. Elle leva les yeux, et dans le regard de Nefraea, il y avait une lueur de tristesse appartenant aux spectateurs."
  },
  AvgDialog_131212_Content_65 = {
    Text = "...tu as aussi tué les «souvenirs»."
  },
  AvgDialog_131212_Content_66 = {
    Text = "C'est l'acceptation. Romance, gentillesse, souvenirs... Je ne fais que reprendre un par un ces objets que tu as abandonnés, en les ramenant chez eux."
  },
  AvgDialog_131212_Content_67 = {
    Text = "Nefraea se leva et tourna joyeusement sur elle-même."
  },
  AvgDialog_131212_Content_68 = {
    Text = "Un moi complet, un vengeur complet... Ça te plaît, sœur aînée ?"
  },
  AvgDialog_131212_Content_69 = {
    Text = "Tu peux déjà obtenir le chaos que tu désires... Alors, qu'est-ce que tu attends ?"
  },
  AvgDialog_131212_Content_7 = {
    Text = "La danse de la compagnie de danse du cygne est en effet gracieuse, mais si j'ai un conflit d'horaire, je choisirai certainement « Le Jardin Émeraude »."
  },
  AvgDialog_131212_Content_70 = {
    Text = "Ah, non non non, bonne sœur, je suis encore très loin de ce que je veux."
  },
  AvgDialog_131212_Content_71 = {
    Text = "Je prendrai soin de ta roue de filage, les cendres de dimension que tu souhaites seront inépuisables, les scènes que tu chéris, je n'en détruirai aucune."
  },
  AvgDialog_131212_Content_72 = {
    Text = "Et ce que je veux que tu fasses, c'est juste m'aider avec un petit, très petit service."
  },
  AvgDialog_131212_Content_73 = {
    Text = "Nefraea s'approcha d'Arachne, caressant le rouet qui tournait sans cesse dans ses mains, sa respiration s'accéléra à cause de l'excitation de son imagination."
  },
  AvgDialog_131212_Content_74 = {
    Text = "Contrôle le Gardien pour moi, ma chère sœur, seul le Gardien peut m'apporter ce que je désire vraiment."
  },
  AvgDialog_131212_Content_75 = {
    Text = "Tu sais bien que %player% est un fragment de l'Être Suprême. Nous ne pouvons commander {Male=his,Female=her} Destin..."
  },
  AvgDialog_131212_Content_76 = {
    Text = "Une lueur verte sombre émanait de la roue de fil noir dans les mains de Nefraea. Sous l'éclat de la lumière, un fil caché et trouble apparaissait dans le champ de vision d'Arachne."
  },
  AvgDialog_131212_Content_77 = {
    Text = "C'est... <Shake:le Fil du Destin du Gardien ?!>"
  },
  AvgDialog_131212_Content_78 = {
    Text = "<Shake:Heh...> <Big:<Shake:HAHAHAHA !>> C'est la première fois que j'entends ta voix trembler. Alors, ma sœur ? N'est-ce pas exaltant ?!"
  },
  AvgDialog_131212_Content_79 = {
    Text = "Dans l'abîme, l'Apôtre, incarnation de la volonté de cette personne divine, est contenu dans ce rouet, devenant sa mèche... C'est elle qui illumine l'abîme, nous apportant la seule lumière."
  },
  AvgDialog_131212_Content_8 = {
    Text = "Une galerie de personnages à plusieurs niveaux et une narration à travers différentes époques et espaces, quelle technique fascinante et complexe. La montée et la chute des jardins royaux ne peuvent en aucun cas être comparées à ces clichés banals..."
  },
  AvgDialog_131212_Content_80 = {
    Text = "Avec notre pouvoir et la guidance de l'Apôtre, <Big:même le destin d'un fragment divin repose entre NOS mains !>"
  },
  AvgDialog_131212_Content_81 = {
    Text = "Ce n'est pas la bonne direction du destin, Nefraea... Personne ne peut défier le destin."
  },
  AvgDialog_131212_Content_82 = {
    Text = "Ça arrive bientôt, grande sœur. Tant que tu touches le pouvoir des trois plasmides, l'apôtre pourra renaître ! Il rouvrira le passage qui relie aux dieux, et il transmettra la voix des croyants dans ce temple éternel"
  },
  AvgDialog_131212_Content_83 = {
    Text = "La Divinité Suprême s'éveillera... et tu n'auras plus jamais à élaguer un destin agonisant ni à tisser une toile vouée à se briser."
  },
  AvgDialog_131212_Content_84 = {
    Text = "Nefraea prit une profonde inspiration, une larme coula de son visage excité."
  },
  AvgDialog_131212_Content_85 = {
    Text = "Sa voix tremblait à cause du merveilleux rêve qui s'annonçait. Ses yeux pleins de larmes contemplaient profondément le visage paisible d'Arachne."
  },
  AvgDialog_131212_Content_86 = {
    Text = "Ne fais plus cette résistance douloureuse, grande sœur."
  },
  AvgDialog_131212_Content_87 = {
    Text = "Viens, viens près de moi, accueillons ensemble son Réveil, et donnons à toutes les scènes le dénouement qu'elles méritent !..."
  },
  AvgDialog_131212_Content_9 = {
    Text = "Ha, si tu achètes le numéro huit, tu vas perdre gros ! Je te le dis en secret, j'ai des informations confidentielles, quelqu'un va mettre du poison dans le fourrage du numéro huit aujourd'hui."
  },
  AvgDialog_131213_Content_1 = {
    Text = "Comédie improvisée"
  },
  AvgDialog_131213_Content_10 = {
    Text = "Maintenant, tu accueilles un nouveau croyant——"
  },
  AvgDialog_131213_Content_100 = {
    Text = "J›emprunte l›Ordre de poids de « N »... <color=#98918C>J›occupe la moitié de la conscience de %player%</color>... mais un nom est la chose la moins importante en ce moment."
  },
  AvgDialog_131213_Content_101 = {
    Text = "Il est important de collaborer agréablement, Arachne."
  },
  AvgDialog_131213_Content_102 = {
    Text = "<Shake:Vous... vous tous... vous saviez depuis le début...>"
  },
  AvgDialog_131213_Content_103 = {
    Text = "Le regard faible de Nefraea se déplaça du visage d'Arachne au vôtre. Vous goûtez avec gourmandise l'angoisse et la douleur infinies de ce regard. Ah, quelle fragrance enivrante..."
  },
  AvgDialog_131213_Content_104 = {
    Text = "Regarde bien, chère Nefraea, le petit malin qui s'est échappé du Vide."
  },
  AvgDialog_131213_Content_105 = {
    Text = "Ton jeu me procure beaucoup de plaisir. Un éclat de conscience résiduelle de Touva Wave, un fragment tombé de Touva Wave, leur rencontre est la seule façon de libérer complètement le pouvoir du plasmide, me donnant l'opportunité de ressentir cette joie que je n'ai jamais connue auparavant..."
  },
  AvgDialog_131213_Content_106 = {
    Text = "Si je le pouvais, je voudrais tellement continuer à jouer comme maintenant, ce plaisir pourrait me divertir pendant toute une semaine..."
  },
  AvgDialog_131213_Content_107 = {
    Text = "Ta gorge tremble. Tu soupires avec un regret immense."
  },
  AvgDialog_131213_Content_108 = {
    Text = "C'est vraiment dommage, si cette personne se réveille à nouveau, ce magnifique paradis va me quitter."
  },
  AvgDialog_131213_Content_109 = {
    Text = "Alors, malheureusement... le point culminant doit prendre fin. Lève les yeux, ma chère. Quoi qu›il en soit, nous pouvons au moins nous accorder sur une chose à propos de cette histoire de Destin..."
  },
  AvgDialog_131213_Content_11 = {
    Text = "Les fils du destin tirent ton corps. Tes dix doigts entrelacés, tes mains jointes sur ta poitrine, tu te mets lentement à genoux, baissant la tête vers le rouet devant toi."
  },
  AvgDialog_131213_Content_110 = {
    Text = "Tu te penches, tenant le menton élégant de Nefraea, et te rapproches de son oreille."
  },
  AvgDialog_131213_Content_111 = {
    Text = "La destruction est la plus belle image de cet univers, n'est-ce pas, mon cher ?"
  },
  AvgDialog_131213_Content_112 = {
    Text = "Un claquement net, rempli d'une joie infinie et de regrets, résonne devant l'œil de Nefraea."
  },
  AvgDialog_131213_Content_113 = {Text = "Boom—"},
  AvgDialog_131213_Content_114 = {
    Text = "Dans le tremblement de la dimension, le passage connecté aux divinités tremble soudainement. D'innombrables fissures grimpent à la surface illusoire du passage..."
  },
  AvgDialog_131213_Content_115 = {
    Text = "<Big:<Shake:NOOOON !!—>>"
  },
  AvgDialog_131213_Content_116 = {
    Text = "Nefraea criait en se précipitant vers le passage, et alors que sa main était à quelques pouces du passage, il se brisa et s'effondra."
  },
  AvgDialog_131213_Content_117 = {
    Text = "D'innombrables fragments illusoires flottent devant Nefraea, comme un kaléidoscope brisé, ces morceaux de papier coloré bon marché s'envolent dans les airs, balayant le visage de Nefraea."
  },
  AvgDialog_131213_Content_118 = {
    Text = "Tu as enlevé le chapeau haut de forme qui n'existe pas, l'as fait tourner deux fois dans l'air, puis t'es incliné devant le dos perdu de Nefraea."
  },
  AvgDialog_131213_Content_119 = {
    Text = "Destin, quelle scène intéressante... L'histoire du troisième acte prend fin ici. Ton applaudissement et tes acclamations me font ressentir un immense plaisir."
  },
  AvgDialog_131213_Content_12 = {
    Text = "Je... l'apôtre que j'admire... je suis... votre plus fidèle croyant et celui de l'Être suprême."
  },
  AvgDialog_131213_Content_120 = {
    Text = "Amusez-vous bien en regardant la pièce, chère Nefraea."
  },
  AvgDialog_131213_Content_121 = {
    Text = "Dans les cris déchirants de Nefraea, la conscience de l'Apôtre se brise avec la rupture du passage. Tu tombes sur la scène avec le dernier sourire de Plaisir."
  },
  AvgDialog_131213_Content_13 = {
    Text = "Ta trachée et tes membres ont leur propre destin. Ils ne t'appartiennent plus, et tu ne devrais plus essayer en vain de les reprendre en main."
  },
  AvgDialog_131213_Content_14 = {
    Text = "Ne contrôle pas. Ne comprends pas. Profite-en. Le chemin du plaisir est là-dedans..."
  },
  AvgDialog_131213_Content_15 = {
    Text = "Regarde, sœur ! Quel acteur remarquable tu as formé !"
  },
  AvgDialog_131213_Content_16 = {
    Text = "Arachne est assise en bas de la scène, son rouet tournant à cette fréquence éternelle. Elle regarde silencieusement les ombres sombres de la lanterne sur la scène, semblant être seulement une spectatrice respectant les rituels."
  },
  AvgDialog_131213_Content_17 = {
    Text = "Ô mon cher apôtre... nos croyants t'ont apporté l'offrande que tu désires le plus."
  },
  AvgDialog_131213_Content_18 = {
    Text = "Le fuseau sombre éclate en une déflagration soudaine, dispersant une lumière terne et visqueuse dans chaque recoin de la scène."
  },
  AvgDialog_131213_Content_19 = {Text = "Mmm !!..."},
  AvgDialog_131213_Content_2 = {
    Text = "Tapez, tapez, tapez."
  },
  AvgDialog_131213_Content_20 = {
    Text = "La douleur frappe sans prévenir. Elle ne touche ni votre chair ni vos organes, mais jaillit des recoins les plus profonds de votre Dimension mentale — du siège même de votre âme."
  },
  AvgDialog_131213_Content_21 = {
    Text = "Une grande bête se manifeste en vous. Elle se débat et rugit, sa forme massive s›étendant rapidement à l›intérieur de votre corps."
  },
  AvgDialog_131213_Content_22 = {
    Text = "La bête emplit tout votre corps, écrasant chaque organe. Elle s›étend encore, enragée, cherchant à percer votre peau. La pression intense et écrasante manque de vous faire perdre connaissance..."
  },
  AvgDialog_131213_Content_23 = {
    Text = "Hah... <Big:<Shake:AAAARGH !!—>>"
  },
  AvgDialog_131213_Content_24 = {
    Text = "Dans tes cris déchirants, trois souffles à peine perceptibles s'échappent de ce corps en souffrance, dérivant vers ce rouet émettant une lueur sombre."
  },
  AvgDialog_131213_Content_25 = {
    Text = "L›Ordre de poids converge dans la lumière tel un combustible pur versé dans un feu. Des flammes ternes jaillissent, brûlant avec férocité dans l›anneau du fuseau. L›éclat de la Lanterne s›intensifie, illuminant toute la dimension."
  },
  AvgDialog_131213_Content_26 = {
    Text = "<Shake:Hah... Hah...>"
  },
  AvgDialog_131213_Content_27 = {
    Text = "Ah, pauvre, notre fidèle petit croyant..."
  },
  AvgDialog_131213_Content_28 = {
    Text = "Nefraea s'approche de toi, caressant tendrement ta joue mouillée de sueur avec un visage plein de compassion."
  },
  AvgDialog_131213_Content_29 = {
    Text = "Tout va bien, {Male=Mr.,Female=Miss} Gardien. Tu vois ? Notre Apôtre a déjà révélé Sa forme..."
  },
  AvgDialog_131213_Content_3 = {
    Text = "Les fils du destin tirent doucement, les semelles des marionnettes heurtent la scène, produisant un son clair."
  },
  AvgDialog_131213_Content_30 = {
    Text = "Tu soulèves la tête avec douleur. La lumière du rouet commence à se rassembler, une forme illusoire changeante apparaît au-dessus de la lumière."
  },
  AvgDialog_131213_Content_31 = {
    Text = "Il n›a ni visage ni forme. Il est le héraut fidèle du Divin, scrutant le vide en direction du Dieu endormi."
  },
  AvgDialog_131213_Content_32 = {
    Text = "Son regard est une invitation. Sous cette fixité implacable, un escalier reliant le lieu de repos du Dieu prend lentement forme..."
  },
  AvgDialog_131213_Content_33 = {
    Text = "<Shake:Ça a marché... ça a marché !> Le passage vers le Plan Supérieur s›ouvre... Le Dieu est sur le point de s›éveiller..."
  },
  AvgDialog_131213_Content_34 = {
    Text = "Grande sœur, tu as vu ? Ta toile est presque terminée..."
  },
  AvgDialog_131213_Content_35 = {
    Text = "Nefraea regardait avec joie le passage de plus en plus clair, un sourire et des larmes apparaissant simultanément sur son visage."
  },
  AvgDialog_131213_Content_36 = {Text = "@2...@3..."},
  AvgDialog_131213_Content_37 = {
    Text = "Le théâtre tremble violemment. La scène s'effondre, les dimensions frémissent. Tout le destin tremble, se soumet dans cette grande descente."
  },
  AvgDialog_131213_Content_38 = {
    Text = "L›Ordre de poids en vous s›est réduit à presque rien. La puissance du plasmide a été absorbée dans le corps de l›Apôtre. Son éclat est trop intense pour être contemplé ; Son existence est absolument indéniable."
  },
  AvgDialog_131213_Content_39 = {
    Text = "Sous le regard calme d'Arachne, au milieu des frissons du destin, Il va descendre sur cette scène finale—"
  },
  AvgDialog_131213_Content_4 = {
    Text = "Ah, mes chers spectateurs, le moment tant attendu approche ! Accueillons notre protagoniste avec des applaudissements, il va faire son entrée éclatante ! Oh"
  },
  AvgDialog_131213_Content_40 = {
    Text = "Au nom de...@2... croyant...@3..."
  },
  AvgDialog_131213_Content_41 = {
    Text = "Parle, apôtre... que veux-tu me dire ? Est-ce ton désir ? Ou les paroles de cette personne divine ?"
  },
  AvgDialog_131213_Content_42 = {
    Text = "Quelle oracle a-t-il à transmettre à ce monde ? Veut-il briser ces scènes ? Ou veut-il que ces marionnettes accueillent ensemble son arrivée ?"
  },
  AvgDialog_131213_Content_43 = {
    Text = "Dis-moi, mon cher Apôtre ! Quelle bête dangereuse et adorable tu es, ne sachant qu›arracher et détruire... dis-moi ce que tu désires..."
  },
  AvgDialog_131213_Content_44 = {
    Text = "Réciter@2......mon nom......Réveiller@2......@3Primordial......"
  },
  AvgDialog_131213_Content_45 = {
    Text = "Ah, ton nom, c'est exact... Je vais réciter ton nom ! Je te ferai apporter tout ce que tu veux dévorer, juste devant ta bouche. Je vais ouvrir cette cage pour toi..."
  },
  AvgDialog_131213_Content_46 = {
    Text = "Je m'appelle...@2..."
  },
  AvgDialog_131213_Content_47 = {
    Text = "La voix de l'Apôtre était trouble, Nefraea s'avançait vers ce faisceau de lumière de plus en plus brillant, sans même jeter un regard à toi qui tremblais de douleur."
  },
  AvgDialog_131213_Content_48 = {
    Text = "La Ferveur l›emplit d›émerveillement et de rire tandis qu›elle s›approche de la grande figure. Son souffle se coupe d›exaltation."
  },
  AvgDialog_131213_Content_49 = {
    Text = "Elle caressa cette lueur vert sombre, touchant cette magnifique bête qui allait tout dévorer. Elle deviendra la première proie de la bête, sans hésitation, avec plaisir."
  },
  AvgDialog_131213_Content_5 = {
    Text = "Nefraea leva la main, comme des feux d'artifice, des toiles d'araignée volent et tombent. Tu te tiens au centre de la scène, la lumière sombre éclaire ton visage."
  },
  AvgDialog_131213_Content_50 = {
    Text = "C'est maintenant, apôtre... dis-moi, dis au monde, quel est ton nom"
  },
  AvgDialog_131213_Content_51 = {
    Text = "Je m'appelle...@2..."
  },
  AvgDialog_131213_Content_52 = {
    Text = "Mon nom est... <Red:%player%>..."
  },
  AvgDialog_131213_Content_53 = {
    Text = "Mon nom est... <Yellow:%player%> !"
  },
  AvgDialog_131213_Content_54 = {Text = "!!!"},
  AvgDialog_131213_Content_55 = {
    Text = "Le temps s'arrête à cet instant. Les fils du destin se fondent et s'effondrent dans l'œil de Nefraea, un destin effondré comme un vortex tumultueux dans l'océan, l'emportant et la dévorant."
  },
  AvgDialog_131213_Content_56 = {
    Text = "<Shake:Que... qu›est–ce qui se passe ?!!>"
  },
  AvgDialog_131213_Content_57 = {
    Text = "Le vortex s'apaise, l'immensité se recueille, les gouttes d'eau se rassemblent à nouveau en fils, et le filet qu'elles élaborent prend une forme que Nefraea n'avait jamais envisagée."
  },
  AvgDialog_131213_Content_58 = {
    Text = "Tu n'as pas compris, Nefraea ? Adore sincèrement ton Apôtre. L'Apôtre que tu as prié se tient déjà devant toi."
  },
  AvgDialog_131213_Content_59 = {
    Text = "Tu te tiens devant Nefraea, regardant ce passage qui relie le temple de Touva Wave, observant cette silhouette suprême, souriant largement."
  },
  AvgDialog_131213_Content_6 = {
    Text = "Allons, {Male=Mr.,Female=Miss} Gardien. Notre acte final commence..."
  },
  AvgDialog_131213_Content_60 = {
    Text = "Le pouvoir des trois plasmides se déchaîne en toi, mais ne te fait plus souffrir. La lumière du rouet, cette volonté suprême, afflue dans ton corps comme un océan, fusionnant avec le pouvoir des trois plasmides."
  },
  AvgDialog_131213_Content_61 = {
    Text = "Tu ressens que l'ombre de cet apôtre se superpose à ton corps. Tu te sens puissant. Tu te sens infini. Tu te sens libre. Tu ressens... une jouissance suprême."
  },
  AvgDialog_131213_Content_62 = {
    Text = "Tu... as volé le destin de l'apôtre ?!"
  },
  AvgDialog_131213_Content_63 = {
    Text = "héhéhéhé... hahaha ! La troisième scène de l'histoire, descendre ? ... Ah, haha. La troisième scène, c'est vrai. Mais ce n'est pas ton histoire, chère Nefraea."
  },
  AvgDialog_131213_Content_64 = {
    Text = "C›est moi qui écris cet acte. Et je le nomme... <Big:<color=#98918C>Ravissement</color>> !"
  },
  AvgDialog_131213_Content_65 = {
    Text = "<Shake:Vous... vous tous...>"
  },
  AvgDialog_131213_Content_66 = {
    Text = "Non, ce n'est pas possible... Je peux voir votre destin... c'est impossible..."
  },
  AvgDialog_131213_Content_67 = {
    Text = "<color=#EE4D0C><Italic:« Oh, mon cher Duc, pourquoi cette mine si longue ? Laissez votre bouffon restaurer ce précieux sourire ! »></color>"
  },
  AvgDialog_131213_Content_68 = {
    Text = "<color=#BF0909><Italic:« Regardez–moi ça — le destin cruel, la malédiction perfide... quel spectacle ridicule ! Quel doux, délicieux mensonge ! »></color>"
  },
  AvgDialog_131213_Content_69 = {
    Text = "<color=#FC1818><Italic:« Voilà comment l›histoire se termine pour le vilain... la seule récompense de la malice est le Ravissement ! »></color>"
  },
  AvgDialog_131213_Content_7 = {
    Text = "Cette scène, je l'appelle — «Descendre»"
  },
  AvgDialog_131213_Content_70 = {
    Text = "Un tonnerre d›applaudissements éclate depuis les sièges vides. Des lumières éclatantes inondent la scène en ruines. Vous êtes le pivot du monde, le maître de la Singularité.\nVous écartez les bras. Vous déclarez que le Destin s›inclinera devant vous. Vous déclarez que cette représentation est un chef–d›œuvre."
  },
  AvgDialog_131213_Content_71 = {
    Text = "Tromperie. Manipulation. Pur plaisir... <Shake:Héhé... <Big:HAHAHAHA !>> Quel spectacle délicieux, petite araignée."
  },
  AvgDialog_131213_Content_72 = {
    Text = "<Shake:Vous... vous ne pouvez pas avoir le pouvoir d›altérer le Destin...>"
  },
  AvgDialog_131213_Content_73 = {
    Text = "Aww... Non, non, non. De tels efforts sont pour les gens comme vous. Un dévot du Ravissement ne s›abaisserait jamais à un tel labeur."
  },
  AvgDialog_131213_Content_74 = {
    Text = "<Shake:J›ai vu la fin... Vous étiez censé abandonner votre Ordre de poids ! <Big:Vous étiez censé regarder le passage s›ouvrir et mourir sur cette scène ! POURQUOI ?!>>"
  },
  AvgDialog_131213_Content_75 = {
    Text = "Celui qui contrôle le destin sait tout, sauf ce qui concerne le plaisir. Car, car le plaisir n'a pas de destin, mon cher..."
  },
  AvgDialog_131213_Content_76 = {
    Text = "Tu te penches pour admirer les yeux tremblants de Nefraea. La douleur et le désespoir qui scintillent dans ces yeux nourrissent chaque parcelle de ton corps."
  },
  AvgDialog_131213_Content_77 = {
    Text = "Tout ce que nous sommes, c'est la quête du plaisir. Après avoir abandonné le plaisir, nous n'avons rien... Celui qui recherche le plaisir n'a pas de destin."
  },
  AvgDialog_131213_Content_78 = {
    Text = "Ce que vous voyez n›est qu›un tour de passe–passe. Une petite blague jouée à mon ancien moi et au Destin par le nouveau moi, celui béni par la volonté et le pouvoir d›un Dieu."
  },
  AvgDialog_131213_Content_79 = {
    Text = "Pourquoi contrôler le Destin quand on peut le ridiculiser à la place ? N›est–ce pas, Exécuteur du Destin ?"
  },
  AvgDialog_131213_Content_8 = {
    Text = "Descendre. Sur le rideau derrière la scène, une toile d'araignée visqueuse tisse ce mot énorme et horrible. Nefraea prend une profonde inspiration et ouvre les bras."
  },
  AvgDialog_131213_Content_80 = {
    Text = "Vous essayez de maintenir un ton sérieux, mais vous ne pouvez réprimer votre rire maniaque."
  },
  AvgDialog_131213_Content_81 = {
    Text = "Êtes–vous le Gardien ? Êtes–vous « N » ? Vous ne le savez pas, et vous vous en moquez. L›essence du Ravissement afflue dans la volonté de l›Apôtre, emplissant chaque cellule de votre corps."
  },
  AvgDialog_131213_Content_82 = {
    Text = "Vous voulez hurler de rire. Vous voulez acclamer. Vous voulez infliger à ce manipulateur raté l›humiliation la plus tendre et la plus dévastatrice."
  },
  AvgDialog_131213_Content_83 = {
    Text = "Tu as trouvé la clé pour déverrouiller. Tu te retournes et fais une révérence élégante à cette personne qui a organisé tout cela."
  },
  AvgDialog_131213_Content_84 = {
    Text = "Arachne, grand dramaturge ! Dès le premier instant de mon arrivée dans ce monde, tu as commencé à tisser cette scène pour moi"
  },
  AvgDialog_131213_Content_85 = {
    Text = "Montre-moi le fonctionnement du destin, fais-moi découvrir le charme de la tromperie, dis-moi le secret du « plaisir »..."
  },
  AvgDialog_131213_Content_86 = {
    Text = "Maintenant, le verrou de la «jouissance» est déjà ouvert. Alors, qu'en pensez-vous, moi l'acteur, êtes-vous satisfait ?"
  },
  AvgDialog_131213_Content_87 = {
    Text = "Je ne suis que le constructeur de la scène, l'écriture de l'histoire est à vous de décider."
  },
  AvgDialog_131213_Content_88 = {
    Text = "Tu lui ouvres la bouche. Tu es l'apôtre des dieux. Tu es l'esclave du plaisir. Tu es le maître incontesté de ce monde. Tu lèves la main et, tel un chef d'orchestre, tu appuies doucement."
  },
  AvgDialog_131213_Content_89 = {
    Text = "En retour... Maintenant, mets ton costume, Arachne. Le spectacle va bientôt être à ton tour de jouer"
  },
  AvgDialog_131213_Content_9 = {
    Text = "Apôtre de l'Être suprême, messager de la folie du Chaos. Ta lumière éclaire l'éternelle prison, j'ai entendu ta voix appelant le Chaos."
  },
  AvgDialog_131213_Content_90 = {
    Text = "Vous pincez les Fils autrefois invisibles comme si vous déplaciez des cubes dans une crèche."
  },
  AvgDialog_131213_Content_91 = {
    Text = "Tandis que la trame se remodèle, les Cendres de dimension volées reviennent vers elle."
  },
  AvgDialog_131213_Content_92 = {
    Text = "Des grains de sable d'un violet sombre et infini coulent autour d'Arachne, tournant autour d'elle. Dans ta création, ceux qui n'ont jamais été volés par les cendres de dimension."
  },
  AvgDialog_131213_Content_93 = {
    Text = "<color=#8C7E96>Dans le passé, dans le futur, elles appartiendront toujours à Arachne.</color>"
  },
  AvgDialog_131213_Content_94 = {
    Text = "Arachne te sourit en hochant la tête, intégrant ces cendres dans son corps. Son rouet ne s'arrête jamais. Son sourire n'a jamais changé."
  },
  AvgDialog_131213_Content_95 = {
    Text = "Tu secoues la tête sur scène et pousses un soupir exagéré."
  },
  AvgDialog_131213_Content_96 = {
    Text = "Sombre et sans passion... Tu aurais pu être une personne si intéressante, Arachne."
  },
  AvgDialog_131213_Content_97 = {
    Text = "Tu es, comme Tawil, un voyeur du destin et aussi un esclave du destin. La joie que je ressens maintenant, vous ne pourrez jamais la ressentir."
  },
  AvgDialog_131213_Content_98 = {
    Text = "Regarde ton visage sans vie, Arachne. Je ressens vraiment de la peine pour vous."
  },
  AvgDialog_131213_Content_99 = {
    Text = "Tout le monde fait son choix, %player%... ou devrais–je vous appeler l›Apôtre ? Ou peut–être... « N » ?"
  },
  AvgDialog_131214_Content_1 = {
    Text = "<Shake:AAAAARGH !!>"
  },
  AvgDialog_131214_Content_10 = {
    Text = "Parce que... notre vengeance n'est pas encore terminée, et elle ne le sera jamais..."
  },
  AvgDialog_131214_Content_11 = {
    Text = "Tu as instinctivement reculé d'un pas. Mais il n'y a aucune onde de danger émanant de Nefraea."
  },
  AvgDialog_131214_Content_12 = {
    Text = "Elle se contenta de balancer ses pinces, tirant le rideau qui la couvrait sur le côté, révélant la scène derrière le rideau."
  },
  AvgDialog_131214_Content_13 = {Text = "C'est... !"},
  AvgDialog_131214_Content_14 = {
    Text = "Le fil écarlate relie plusieurs scènes dans le théâtre, relie cette grande ville où se trouve le théâtre, relie les innombrables marionnettes dans la ville, se réunissant dans le corps meurtri de Nefraea."
  },
  AvgDialog_131214_Content_15 = {
    Text = "Tu... n'as pas attaché le fil au rouet ?"
  },
  AvgDialog_131214_Content_16 = {
    Text = "Elle a déjà vu la fin. Elle a vu son échec. Quand elle avait encore de la force, elle a lié ces destins à elle-même, comme..."
  },
  AvgDialog_131214_Content_17 = {
    Text = "Comme lorsque tu m'as tué pour la première fois."
  },
  AvgDialog_131214_Content_18 = {
    Text = "Nefraea sourit, pinçant devant elle un fil caché très secret."
  },
  AvgDialog_131214_Content_19 = {
    Text = "Ce fil écarlate s'étendait depuis l'arrière de sa tête, s'intégrant discrètement dans le corps d'Arachne après un long chemin soigneusement parcouru."
  },
  AvgDialog_131214_Content_2 = {Text = "Boom—"},
  AvgDialog_131214_Content_20 = {
    Text = "Cela fait longtemps que nous ne sommes pas restées aussi proches, grande sœur. C'est seulement tout à l'heure que j'ai trouvé l'occasion de te rendre ce fil."
  },
  AvgDialog_131214_Content_21 = {
    Text = "«Encore»... ?"
  },
  AvgDialog_131214_Content_22 = {
    Text = "Ce fil... est celui que j'ai coupé la première fois que j'ai détruit ma relique."
  },
  AvgDialog_131214_Content_23 = {
    Text = "Ta romance, ta gentillesse, tes souvenirs... Tout ce qui est en moi t'a été rendu."
  },
  AvgDialog_131214_Content_24 = {
    Text = "Tu es complet, Arachne."
  },
  AvgDialog_131214_Content_25 = {
    Text = "Le coin de la bouche de Nefraea se leva, comme un enfant caché derrière un rideau, regardant les adultes être piégés par ses farces."
  },
  AvgDialog_131214_Content_26 = {
    Text = "Dans ces moments où tu as la force... est-ce cela que tu veux faire ?"
  },
  AvgDialog_131214_Content_27 = {
    Text = "Alors ? C'est une idée géniale, n'est-ce pas"
  },
  AvgDialog_131214_Content_28 = {
    Text = "Viens, tue-moi ! Détruis complètement ces destins que tu as autrefois abandonnés ! Détruis cette ville où tu vis, détruis ce théâtre que tu aimes tant, détruis chaque personne ici"
  },
  AvgDialog_131214_Content_29 = {
    Text = "Viens, Arachne ! Avec toutes tes faiblesses, <Shake: tue une fois de plus tout ce que tu aimes !!!>"
  },
  AvgDialog_131214_Content_3 = {
    Text = "Les cris de douleur et les bruits de l'effondrement résonnent dans le théâtre brisé. Les fils écarlates se rompent un à un, et le rouet qui a accompagné Nefraea toute sa vie tombe devant elle."
  },
  AvgDialog_131214_Content_30 = {
    Text = "Le cri exalté et le rire de Nefraea résonnent longtemps dans le théâtre en ruines."
  },
  AvgDialog_131214_Content_31 = {
    Text = "Le corps d'Arachne semble être devenu plus lourd que jamais. Elle tourne lentement la tête, balayant tout ce qui est lié à Nefraea."
  },
  AvgDialog_131214_Content_32 = {
    Text = "À travers la fente du théâtre, elle voyait des voitures et des foules remplissant cette ville prospère. Ces visages familiers portaient des noms familiers, se trouvant dans chaque coin qu'elle connaissait."
  },
  AvgDialog_131214_Content_33 = {
    Text = "Elle voit la scène sur laquelle elle a autrefois dansé avec toi. La guerre terrible est enfin terminée, ce monde s'apprête à accueillir deux cents ans de paix longue et magnifique."
  },
  AvgDialog_131214_Content_34 = {
    Text = "Dans cette matière noire et collante, elle a vu le visage de sa mère. Elle était assise avec son père sous le bouleau dans la cour, lui faisant signe."
  },
  AvgDialog_131214_Content_35 = {
    Text = "Monsieur Lawrence se tient à leurs côtés, essuyant les couverts confectionnés spécialement pour elle."
  },
  AvgDialog_131214_Content_36 = {
    Text = "Tu appelles cela la vengeance, car tu n'as jamais compris le destin, ni jamais compris qui je suis, Nefraea."
  },
  AvgDialog_131214_Content_37 = {
    Text = "Un fil recouvert de mucus relie Arachne à la scène brisée sous les pieds de Nefraea. Traînant son corps lourd, Arachne pose le pied sur ce fil fragile."
  },
  AvgDialog_131214_Content_38 = {
    Text = "Le fil tremble comme s'il allait se rompre et précipiter le Prisonnier du Destin dans l'abîme."
  },
  AvgDialog_131214_Content_39 = {
    Text = "Arachne regardait calmement les yeux étonnés de Nefraea. Ses pas n'avaient jamais cessé un instant."
  },
  AvgDialog_131214_Content_4 = {
    Text = "Elle s'accroche fermement au rouet comme un bébé tombé à l'eau. Dans sa main, le rouet obscur s'effondre irrésistiblement, se transformant en cendres de dimension, se mêlant au sable mouvant aux côtés d'Arachne."
  },
  AvgDialog_131214_Content_40 = {
    Text = "Le moment fatidique approche..."
  },
  AvgDialog_131214_Content_41 = {
    Text = "Arachne sur le fil d'araignée leva son rouet. Vous pouvez clairement voir le monde entier s'arrêter un instant, tout l'univers lié à ce théâtre attendant son ordre."
  },
  AvgDialog_131214_Content_42 = {
    Text = "Je déclare ici, au nom du destin——"
  },
  AvgDialog_131214_Content_43 = {
    Text = "Tous les destins erronés seront ensevelis dans la poussière du temps. Le destin du monde reprendra le cours qui lui était destiné."
  },
  AvgDialog_131214_Content_44 = {
    Text = "Le mauvais destin s'achève ici. Les abandonnés trouveront le repos..."
  },
  AvgDialog_131214_Content_45 = {
    Text = "Le rouet penche, des milliers de fils tremblent avec lui."
  },
  AvgDialog_131214_Content_46 = {
    Text = "Le fil se rompt. Attendant la scène de paix, elle s'effondre et se dissipe."
  },
  AvgDialog_131214_Content_47 = {
    Text = "Le fil se rompt. Dans les fissures du théâtre, on ne voit plus la trace de la ville."
  },
  AvgDialog_131214_Content_48 = {
    Text = "Fil se rompt, se rompt, se rompt..."
  },
  AvgDialog_131214_Content_49 = {
    Text = "Tu as du mal à voir ces fils du destin, mais tu entends clairement les cris du destin."
  },
  AvgDialog_131214_Content_5 = {
    Text = "Nefraea regardait d'un air absent cet écoulement d'espoir, puis éclata soudainement de rire."
  },
  AvgDialog_131214_Content_50 = {
    Text = "Les vies antérieures et présentes d'innombrables personnes, les joies et les peines innombrables se brisent, se décomposent, se reconstruisent et s'anéantissent à vos oreilles..."
  },
  AvgDialog_131214_Content_51 = {
    Text = "... lumière ?"
  },
  AvgDialog_131214_Content_52 = {
    Text = "Les lumières de la scène s'allument, venant de nulle part. La lumière pénètre dans ce théâtre en ruine, et ceux qui se cachent dans l'ombre, les abandonnés, disparaissent au moment où la lumière tombe, comme s'ils n'avaient jamais existé."
  },
  AvgDialog_131214_Content_53 = {
    Text = "Arachne, sœur, tu......"
  },
  AvgDialog_131214_Content_54 = {
    Text = "Arachne, portant son rouet tournant, a franchi ce fil fragile pour se tenir devant elle. Nefraea leva les yeux vers elle, comme si elle regardait le destin lui-même, irréversible."
  },
  AvgDialog_131214_Content_55 = {
    Text = "Approche-toi de moi, Nefraea."
  },
  AvgDialog_131214_Content_56 = {
    Text = "Arachne prit la main de Nefraea et la posa contre sa joue."
  },
  AvgDialog_131214_Content_57 = {
    Text = "Au moment où elle toucha Arachne, une porte cachée s'ouvrit vers Nefraea. Nefraea traversa les couches de cellules et se retrouva vraiment devant Arachne pour la première fois."
  },
  AvgDialog_131214_Content_58 = {
    Text = "Dans cette cage, elle a vu trois visages familiers."
  },
  AvgDialog_131214_Content_59 = {
    Text = "Arachne!!!tu......"
  },
  AvgDialog_131214_Content_6 = {
    Text = "Son rire devient de plus en plus fort, elle n'a presque plus la force de se redresser. Du sang goutte de son corps tremblant, teintant les fragments ternes du rouet en rouge."
  },
  AvgDialog_131214_Content_60 = {
    Text = "<Shake:«Romantique», Bonté, Hommage... ils... ils...>"
  },
  AvgDialog_131214_Content_61 = {
    Text = "Je n'ai jamais pu les abandonner complètement. Je n'ai jamais pu te laisser vraiment."
  },
  AvgDialog_131214_Content_62 = {
    Text = "Mais tu as dit que tu ne pouvais pas supporter cela..."
  },
  AvgDialog_131214_Content_63 = {
    Text = "Stupide, fragile, détruis tout ce que je chéris avec douleur... tu ne pourras pas te venger de moi, Nefraea."
  },
  AvgDialog_131214_Content_64 = {
    Text = "Parce que c'est la punition que le destin a déjà prononcée pour moi."
  },
  AvgDialog_131214_Content_65 = {
    Text = "Arachne lui sourit paisiblement. Son rouet tournait, éternellement."
  },
  AvgDialog_131214_Content_66 = {
    Text = "C'est fini, Nefraea."
  },
  AvgDialog_131214_Content_67 = {
    Text = "Une corde de guitare tremble doucement. Nefraea entend un cri de héron blanc, comme lorsqu'elle était très petite, le jour où son père lui a apporté ce rouet nommé Moïra."
  },
  AvgDialog_131214_Content_68 = {
    Text = "C'est sa pièce, le bouleau à l'extérieur est son ami fidèle, un prisonnier solitaire immuable depuis des temps immémoriaux."
  },
  AvgDialog_131214_Content_69 = {
    Text = "Ils sont emprisonnés par le destin, ils dépendent l'un de l'autre ici."
  },
  AvgDialog_131214_Content_7 = {
    Text = "La fin, la fin est en effet inévitablement immuable... C'est le destin..."
  },
  AvgDialog_131214_Content_70 = {
    Text = "Creak—Yaa—"
  },
  AvgDialog_131214_Content_71 = {
    Text = "La porte en bois simple s'ouvrit, Arachne s'approcha d'elle, s'inclina et caressa doucement son visage."
  },
  AvgDialog_131214_Content_72 = {
    Text = "Grande sœur... j'ai perdu... nous avons perdu..."
  },
  AvgDialog_131214_Content_73 = {
    Text = "Nous n'avons jamais eu le droit de gagner."
  },
  AvgDialog_131214_Content_74 = {
    Text = "Te souviens-tu du vœu que nous avons fait le jour où nous avons reçu le rouet ?"
  },
  AvgDialog_131214_Content_75 = {
    Text = "« Je ne gaspillerai pas les dons du Destin... J'apporterai un beau destin à ce monde... »"
  },
  AvgDialog_131214_Content_76 = {
    Text = "Quel vœu naïf, Arachne... À l'époque, nous ne comprenions pas du tout ce que cela signifiait."
  },
  AvgDialog_131214_Content_77 = {
    Text = "Arachne tendit cette main légèrement tremblante, caressant le visage de son lointain soi-même."
  },
  AvgDialog_131214_Content_78 = {
    Text = "Destin... qui peut vraiment le voir clairement ."
  },
  AvgDialog_131214_Content_79 = {
    Text = "Mais même si je peux prévoir, mon choix ne changera pas."
  },
  AvgDialog_131214_Content_8 = {
    Text = "Cette victoire tragique, tu l'as déjà vue, n'est-ce pas, Arachne ?"
  },
  AvgDialog_131214_Content_80 = {
    Text = "<Shake:Pourquoi, Arachne ?>Tu peux partir, tu peux lâcher, tu peux..."
  },
  AvgDialog_131214_Content_81 = {
    Text = "Après avoir quitté l'abîme, tu aurais pu avoir une liberté éternelle. Tu sais que tu échoueras inévitablement, mais tu veux quand même essayer de m'apporter, ainsi qu'à ceux qui suivent ton destin, une libération."
  },
  AvgDialog_131214_Content_82 = {
    Text = "Chaque manipulateur du destin deviendra un prisonnier du destin, toi et moi y compris. N'est-ce pas, Nefraea ?"
  },
  AvgDialog_131214_Content_83 = {
    Text = "Nefraea regardait en silence le bouleau blanc à l'extérieur de la fenêtre, le cœur lourd. Elle observait cet arbre bourgeonner, grandir, puis se dessécher."
  },
  AvgDialog_131214_Content_84 = {
    Text = "Elle soupira doucement, leva la tête et caressa les larmes qui coulaient lentement sur le visage d'Arachne. Elle lui sourit."
  },
  AvgDialog_131214_Content_85 = {
    Text = "C'est vraiment bien de te revoir... grande sœur."
  },
  AvgDialog_131214_Content_86 = {
    Text = "Une larme légère tombe, se déposant sur ce visage identique à celui d'Arachne."
  },
  AvgDialog_131214_Content_87 = {
    Text = "Veuillez pardonner mon égoïsme..."
  },
  AvgDialog_131214_Content_88 = {
    Text = "Tu... es libre, <Red:«Arachne»>."
  },
  AvgDialog_131214_Content_89 = {Text = "Cric."},
  AvgDialog_131214_Content_9 = {
    Text = "Tout à l'heure, tu as également aperçu brièvement tout cela. Puisque tu connais déjà le dénouement final, pourquoi s'accrocher encore à cela ?"
  },
  AvgDialog_131214_Content_90 = {
    Text = "Quand le dernier fil se rompt, un tonnerre d'applaudissements éclate."
  },
  AvgDialog_131214_Content_91 = {
    Text = "Le dessous de scène, toujours vide, est désormais plein à craquer. Les destins abandonnés et les marionnettes mortes entre vos mains remplissent chaque fauteuil en velours déchiré."
  },
  AvgDialog_131214_Content_92 = {
    Text = "Les acteurs prennent place parmi le public, observant en silence le dénouement se jouer sur cette scène brisée."
  },
  AvgDialog_131214_Content_93 = {
    Text = "Ils ont un visage impassible, silencieux. \n Ils applaudissent avec enthousiasme. Les applaudissements résonnent, ininterrompus."
  },
  AvgDialog_131215_Content_1 = {Text = "Personnage"},
  AvgDialog_131215_Content_10 = {
    Text = "Je ne comprenais pas auparavant pourquoi Arachne voulait retirer sa sœur de la Toile du destin, et pourquoi tu devais puiser de la force dans ces trois pairs secrets."
  },
  AvgDialog_131215_Content_100 = {Text = "新增"},
  AvgDialog_131215_Content_101 = {
    Text = "Déesse du destin résiliente et vaine... Quelle désespérance, quelle scène tragique..."
  },
  AvgDialog_131215_Content_102 = {
    Text = "Que dites-vous, pourquoi fait-elle cela ?"
  },
  AvgDialog_131215_Content_103 = {
    Text = "Nefraea regardait fixement cette scène simple, sa voix si basse qu'elle semblait murmurer."
  },
  AvgDialog_131215_Content_104 = {
    Text = "Ce n'est qu'un rêve, la déesse du destin... Tu aurais pu choisir le destin le plus joyeux pour tout le monde, tu aurais pu corriger tes fantasmes irréalistes et satisfaire tous tes désirs."
  },
  AvgDialog_131215_Content_105 = {
    Text = "Mais tu n'as jamais pensé à le faire... Lorsque tu crées la perfection, tu crées aussi la souffrance. Encore et encore, tu fais descendre la douleur dans ce monde."
  },
  AvgDialog_131215_Content_106 = {
    Text = "Tu as déployé tous tes efforts pour tisser ce grand filet du destin, mais la vision derrière cette porte, le dénouement inévitable, nous l'avons tous deux déjà vu."
  },
  AvgDialog_131215_Content_107 = {
    Text = "Au moment où le filet du destin est tissé, c'est le moment où cette personne suprême se réveille complètement..."
  },
  AvgDialog_131215_Content_108 = {Text = "Quoi... ?!"},
  AvgDialog_131215_Content_109 = {
    Text = "Tu regardes Arachne, espérant obtenir une réponse négative de son visage."
  },
  AvgDialog_131215_Content_11 = {
    Text = "Au moins, je dois te remercier d'avoir répondu à mes interrogations."
  },
  AvgDialog_131215_Content_110 = {
    Text = "Vous n›y trouvez que son calme habituel, éternel. Sur la scène du Destin, la sérénité est un masque qu›elle ne peut retirer."
  },
  AvgDialog_131215_Content_111 = {
    Text = "Ma sœur, vous ne pouvez cesser de tisser, car vous ne supportez pas de voir l'univers sombrer dans le chaos. Mais le jour où votre toile sera achevée, c'est de vos propres mains que vous enterrerez tout ce que vous aimez."
  },
  AvgDialog_131215_Content_112 = {
    Text = "Quel ironie, Arachne. Pourquoi ? Pourquoi ne pas laisser cet univers accueillir avec joie la fin qui lui est destinée ?"
  },
  AvgDialog_131215_Content_113 = {
    Text = "Tout destin a une constante. Tout destin a une variable. Ces deux proverbes contradictoires sont l'essence du destin."
  },
  AvgDialog_131215_Content_114 = {
    Text = "Arachne regarda les yeux de Nefraea et répondit à cette question qu'elle s'était posée mille fois."
  },
  AvgDialog_131215_Content_115 = {
    Text = "Nefraea, dans l'infini des Dimensions, d'innombrables personnes se battent pour cette Variable."
  },
  AvgDialog_131215_Content_116 = {
    Text = "Maintenir le fonctionnement de la scène, attendre l'apparition des variables... C'est les menottes que le destin m'a imposées. C'est mon devoir inévitable."
  },
  AvgDialog_131215_Content_117 = {
    Text = "Devoirs, dangers... Tu parles de tout cela de manière grandiose, mais tu ne parles jamais de toi, Arachne, ma pauvre sœur. Mais ce n'est pas grave, ton devoir douloureux va bientôt prendre fin."
  },
  AvgDialog_131215_Content_118 = {
    Text = "Nefraea caressa tendrement le visage d'Arachne, lui offrant un doux sourire."
  },
  AvgDialog_131215_Content_119 = {
    Text = "Dans l'abîme, j'ai imaginé sans nombre les scènes de nos retrouvailles, réfléchissant à quel cadeau pourrait être à la hauteur de cette rencontre à nouveau."
  },
  AvgDialog_131215_Content_12 = {
    Text = "Pourquoi ne m'a-t-on pas dit tout cela avant ?"
  },
  AvgDialog_131215_Content_120 = {
    Text = "J'ai pensé longtemps, très longtemps. J'ai trouvé, ma chère grande sœur ! C'est le meilleur cadeau que je puisse te donner——"
  },
  AvgDialog_131215_Content_121 = {
    Text = "Je t›offre... l›<Red:Exorcisme.>"
  },
  AvgDialog_131215_Content_122 = {
    Text = "Dans les paroles douces de Nefraea, une substance noire et collante s'accumule entre les fissures de la Dimension. Au bout de la toile d'araignée, une grande scène apparaît devant vous."
  },
  AvgDialog_131215_Content_13 = {
    Text = "Tu regardes Arachne qui te guide dans tes pas à côté de toi."
  },
  AvgDialog_131215_Content_14 = {
    Text = "Une pierre qui ne provoquera aucune onde dans le lac du destin, à part perturber la paix du lac, est totalement inutile."
  },
  AvgDialog_131215_Content_15 = {
    Text = "Elle et moi sommes devenues deux personnes distinctes il y a bien longtemps, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131215_Content_16 = {
    Text = "T'avais prévu ce jour ?"
  },
  AvgDialog_131215_Content_17 = {
    Text = "Aucun prisonnier ne voit son propre destin avant que le jugement ne soit rendu."
  },
  AvgDialog_131215_Content_18 = {
    Text = "Si tu sais que ces destinées abandonnées ne disparaîtront pas, mais seront plutôt exilées dans le gouffre éternel... le ferais-tu encore, Arachne ?"
  },
  AvgDialog_131215_Content_19 = {Text = "新增"},
  AvgDialog_131215_Content_2 = {
    Text = "La la la la..."
  },
  AvgDialog_131215_Content_20 = {
    Text = "Silence. Le silence est le cataclysme éternel de l'auteur. Le silence est la défense impuissante du prisonnier. Dans le silence de la peine capitale, retentit le rire fou de Nefraea."
  },
  AvgDialog_131215_Content_21 = {
    Text = "Ah, tu y arriveras certainement, sœur. Le destin est ta doctrine, toutes les conditions, toutes, ne peuvent en changer la seule réponse."
  },
  AvgDialog_131215_Content_22 = {
    Text = "Ô déesse du destin, combien tu es insignifiante, combien tu es fragile, combien tu es cruelle..."
  },
  AvgDialog_131215_Content_23 = {
    Text = "Mais ce n'est pas grave. Quoi que tu fasses, pendant tout ce temps, je me suis toujours inquiétée pour toi, ma chère sœur."
  },
  AvgDialog_131215_Content_24 = {
    Text = "Romance, bonté, souvenirs. Un mélange d'ingrédients merveilleux, fermenté, transforme le sourire de Nefraea en un doux poison."
  },
  AvgDialog_131215_Content_25 = {
    Text = "Dans son sourire éclatant, la lumière le long du chemin de toile d'araignée éclaire la scène."
  },
  AvgDialog_131215_Content_26 = {
    Text = "Ma sœur, {Male=Mr.,Female=Miss} Gardien... ces nouvelles pièces sont un cadeau de ma part, la nouvelle maîtresse du théâtre."
  },
  AvgDialog_131215_Content_27 = {
    Text = "Avant la grande représentation du troisième acte, appréciez cette magnifique prélude... N'oubliez pas les règles de courtoisie du théâtre du destin, ne parlez pas"
  },
  AvgDialog_131215_Content_28 = {
    Text = "Nefraea ouvre les bras comme un Annonceur. La scène, aussi vaste que les étoiles, s'illumine à mesure que vous passez lentement."
  },
  AvgDialog_131215_Content_29 = {Text = "新增"},
  AvgDialog_131215_Content_3 = {
    Text = "Ils dansent. Ils chantent. Cui cui ~"
  },
  AvgDialog_131215_Content_30 = {
    Text = "Chère déesse du destin, les corps des trois épouses sacrées sont prêts pour vous."
  },
  AvgDialog_131215_Content_31 = {
    Text = "Quelle poupée délicate... Ce qui a été perdu, va se reproduire en elle..."
  },
  AvgDialog_131215_Content_32 = {
    Text = "«Arachne» quitta le métier à tisser et s'approcha de la poupée."
  },
  AvgDialog_131215_Content_33 = {
    Text = "La première, je te l'offre en tant que « romantique »."
  },
  AvgDialog_131215_Content_34 = {
    Text = "Tu es le chapitre le plus passionné de la symphonie, un rassemblement d'émotions, les fruits éclatants du printemps."
  },
  AvgDialog_131215_Content_35 = {
    Text = "Tu iras au paradis de minuit, apportant à cette ville du bon vin, des rencontres et une impulsion qui ne s'estompera jamais."
  },
  AvgDialog_131215_Content_36 = {
    Text = "Merci, grande déesse du Destin Arachne. Conformément à votre volonté, le vin et le miel couleront entre mes lèvres."
  },
  AvgDialog_131215_Content_37 = {
    Text = "Une belle femme s'inclina devant «Arachne»."
  },
  AvgDialog_131215_Content_38 = {
    Text = "Deuxième corps, je te donne le titre de «bienveillance»."
  },
  AvgDialog_131215_Content_39 = {
    Text = "Tu es le vieillard qui m'a accompagné durant mon enfance. Tu es la plume blanche tombée d'un ange, la lumière du soleil la plus sacrée."
  },
  AvgDialog_131215_Content_4 = {
    Text = "Une ancienne histoire et des pas joyeux tremblent ensemble sur la toile d'araignée. Nefraea, les mains derrière le dos, avance en sautillant avec légèreté."
  },
  AvgDialog_131215_Content_40 = {
    Text = "Tu viendras dans les rues de la ville, réchauffant tout ce que tu vois avec ta bienveillance."
  },
  AvgDialog_131215_Content_41 = {
    Text = "Merci ! Grande déesse du destin, Arachne. Ma vie vous a été donnée, je ne peux que vous rendre hommage."
  },
  AvgDialog_131215_Content_42 = {
    Text = "Je n'ai rien, à part mon amour pour tout ce qui existe dans ce monde. Je protègerai ce qui doit être protégé et j'aiderai ceux qui doivent être aidés."
  },
  AvgDialog_131215_Content_43 = {
    Text = "Tout ce que j'ai, est ouvert aux souffrants."
  },
  AvgDialog_131215_Content_44 = {
    Text = "Le vieillard bienveillant s'inclina profondément devant «Arachne»."
  },
  AvgDialog_131215_Content_45 = {
    Text = "Et toi, le troisième... je te donne le titre de « souvenir »."
  },
  AvgDialog_131215_Content_46 = {
    Text = "«Arachne» s'est approchée de la petite paire secrète, s'est accroupie et a regardé ses yeux inexistants."
  },
  AvgDialog_131215_Content_47 = {
    Text = "Tu es un orphelin du destin, enseveli sous les feuilles mortes de la neige profonde."
  },
  AvgDialog_131215_Content_48 = {
    Text = "Tu marches seul, silencieux, sans être compris par le monde."
  },
  AvgDialog_131215_Content_49 = {
    Text = "Dans ta longue et paisible vie, tu seras le seul gardien de ces souvenirs."
  },
  AvgDialog_131215_Content_5 = {
    Text = "Tu suis irrévocablement Arachne, marchant le long de la toile jusqu'à son extrémité."
  },
  AvgDialog_131215_Content_50 = {
    Text = "La fille silencieuse leva la tête et caressa doucement le visage d'«Arachne»."
  },
  AvgDialog_131215_Content_51 = {
    Text = "«Arachne» se leva et balaya doucement du regard ses pairs secrets."
  },
  AvgDialog_131215_Content_52 = {
    Text = "Allez, mes enfants. Devant le métier à tisser du destin, je vous regarderai pour toujours."
  },
  AvgDialog_131215_Content_53 = {
    Text = "Ceux qui ont été abandonnés à jamais, fleuriront un par un dans votre destin."
  },
  AvgDialog_131215_Content_54 = {Text = "新增"},
  AvgDialog_131215_Content_55 = {
    Text = "La scène s'assombrit. Au fur et à mesure de vos pas, les lumières de la prochaine scène s'allument."
  },
  AvgDialog_131215_Content_56 = {
    Text = "Le soleil n'existe pas ici. Le vent, les fleurs, les nuages... Après trois longs siècles, le calendrier n'existe plus non plus..."
  },
  AvgDialog_131215_Content_57 = {
    Text = "Maître, un nouvel abandonné est arrivé."
  },
  AvgDialog_131215_Content_58 = {
    Text = "Le hautbois joue une fanfare. Les Abandonnés en haillons apparaissent."
  },
  AvgDialog_131215_Content_59 = {
    Text = "«Nefraea» se leva et s'avança au centre de la scène."
  },
  AvgDialog_131215_Content_6 = {
    Text = "Alors, {Male=Mr.,Female=Miss} Gardien ? Le spectacle était-il grandiose ? Surtout avec ce regard en coulisses ?"
  },
  AvgDialog_131215_Content_60 = {
    Text = "Dis-moi, pauvres enfants... qui êtes-vous et d'où venez-vous ?"
  },
  AvgDialog_131215_Content_61 = {
    Text = "Déesse du destin, veuillez pardonner mon impolitesse... mais la colère m'oblige à vous poser une question."
  },
  AvgDialog_131215_Content_62 = {
    Text = "J'ai traversé des épreuves, laissant une grande ode avec mon courage et ma vie, qui aurait dû, avec ma patrie, atteindre le bout de l'univers."
  },
  AvgDialog_131215_Content_63 = {
    Text = "Pourquoi, grande déesse... pourquoi nous avoir bannis en ces terres sauvages ? <Shake:Pourquoi avoir réduit en poussière ces mélodies immortelles !>"
  },
  AvgDialog_131215_Content_64 = {
    Text = "Mes soldats viennent de passer un long hiver. Nous avons repoussé les envahisseurs sauvages et défendu notre civilisation et notre histoire."
  },
  AvgDialog_131215_Content_65 = {
    Text = "Dans les moments les plus cruels, les soldats blessés offraient volontairement leur chair pour nourrir leurs camarades... Quelle victoire si douloureuse, ma déesse."
  },
  AvgDialog_131215_Content_66 = {
    Text = "Lorsque l'ennemi s'est retiré, des larmes de joie ont rempli les yeux de tout le monde. Lors du banquet de célébration, je remplirai chaque verre de vin fort pour chaque soldat."
  },
  AvgDialog_131215_Content_67 = {
    Text = "Mais à ce moment-là, avant même que nous ayons levé nos verres pour célébrer, notre foyer est devenu un tas de ruines, nos proches se sont transformés en poussière..."
  },
  AvgDialog_131215_Content_68 = {
    Text = "<Shake:Déesse bien-aimée, ne nous accorderiez-vous pas ne serait-ce qu'un seul instant de joie ?>"
  },
  AvgDialog_131215_Content_69 = {Text = "新增"},
  AvgDialog_131215_Content_7 = {
    Text = "Nefraea s'est déjà extraite de cet état de folie sur scène, elle se retourne et te regarde avec espoir."
  },
  AvgDialog_131215_Content_70 = {
    Text = "«Nefraea» écoutait les marionnettes qui semblaient raconter sans fin, et deux lignes de larmes tombèrent sur ce visage sans traits."
  },
  AvgDialog_131215_Content_71 = {
    Text = "Je vous ai entendus, je vous ai vus..."
  },
  AvgDialog_131215_Content_72 = {
    Text = "La grande civilisation s'évanouit de vos mains ; les chefs-d'œuvre artistiques se transforment en poussière. Les êtres chers oublient tout l'un de l'autre, accueillant une destruction douloureuse dans la peur..."
  },
  AvgDialog_131215_Content_73 = {
    Text = "Seul un destin correct sera laissé, tandis que tous les innombrables erreurs qui se produisent à ce moment-là seront englouties dans cet abîme sauvage et sans fond. Aussi long que le temps suspendu, une telle histoire se joue chaque jour."
  },
  AvgDialog_131215_Content_74 = {
    Text = "Combien de temps veux-tu que je regarde, combien de temps que j'écoute, ma chère grande sœur..."
  },
  AvgDialog_131215_Content_75 = {
    Text = "«Nefraea» se tourna vers les Spectateurs et prit une profonde inspiration."
  },
  AvgDialog_131215_Content_76 = {
    Text = "Rassurez-vous, mes bons enfants... Votre souffrance, je l'ai créée, et c'est moi qui l'achèverai."
  },
  AvgDialog_131215_Content_77 = {
    Text = "Veuillez vous reposer ici un moment. Un jour, je vous emmènerai d'ici, je vous aiderai à retrouver votre destin..."
  },
  AvgDialog_131215_Content_78 = {
    Text = "Au nom de Nefraea, la vengeresse du Destin, je vous fais la promesse..."
  },
  AvgDialog_131215_Content_79 = {Text = "新增"},
  AvgDialog_131215_Content_8 = {
    Text = "En voyant ton visage silencieux, elle secoua la tête, déçue."
  },
  AvgDialog_131215_Content_80 = {
    Text = "La la la la... La la..."
  },
  AvgDialog_131215_Content_81 = {
    Text = "La scène s'éloigne progressivement, avant que les lumières ne s'éteignent, tu vois les bras ouverts de la marionnette et cette trace de larme noire sur son visage."
  },
  AvgDialog_131215_Content_82 = {
    Text = "Vous n'avez pas parlé, seule Nefraea chantait doucement la mélodie sur scène. Sa voix était rapide et claire, cette histoire jouée des milliers de fois ne lui a plus suscité aucune émotion superflue."
  },
  AvgDialog_131215_Content_83 = {
    Text = "Oh là là ! Mon scène préférée arrive ! Vite, grande sœur"
  },
  AvgDialog_131215_Content_84 = {
    Text = "La voix de Nefraea s'est excitée. Elle a pris la main d'Arachne et a couru joyeusement vers la scène devant elle."
  },
  AvgDialog_131215_Content_85 = {Text = "新增"},
  AvgDialog_131215_Content_86 = {
    Text = "Les lumières s'allument. Il n'y a ni musique, ni dialogue — seulement une marionnette solitaire devant un rouet sur une scène vide."
  },
  AvgDialog_131215_Content_87 = {
    Text = "Craquement, craquement. Le rouet tourne, comme si le jour où il s'arrêtera ne viendra jamais."
  },
  AvgDialog_131215_Content_88 = {
    Text = "...ils dansent. Ils chantent. Cuiii—— Cuiii——"
  },
  AvgDialog_131215_Content_89 = {
    Text = "Le soleil illumine leur visage, quelle joie——"
  },
  AvgDialog_131215_Content_9 = {
    Text = "Pas d'applaudissements, pas de larmes. Le silence est une humiliation... Je pensais qu'après avoir répété si longtemps dans l'abîme, cette performance était déjà parfaite, hélas hélas."
  },
  AvgDialog_131215_Content_90 = {
    Text = "La ballade s’échappe doucement du visage sans traits d'Arachne, elle tourne le rouet lentement, ni trop vite ni trop lentement."
  },
  AvgDialog_131215_Content_91 = {
    Text = "C›est un rythme envoûtant — un seul regard suffit pour comprendre qu›une fois commencé, il ne changera jamais jusqu›à la fin de toute chose."
  },
  AvgDialog_131215_Content_92 = {
    Text = "La déesse du destin est sur le point de tisser son filet."
  },
  AvgDialog_131215_Content_93 = {
    Text = "La toile du destin complète, veillant sur tous les gens... Ils dansent, ils chantent..."
  },
  AvgDialog_131215_Content_94 = {
    Text = "Une immense toile est tissée par le rouet, recouvrant toute la scène. Le surplus du filet du destin s'étend vers le bas de la scène."
  },
  AvgDialog_131215_Content_95 = {
    Text = "Chaque fois que la toile approche de son achèvement, ses bords les plus extérieurs commencent à se dissoudre."
  },
  AvgDialog_131215_Content_96 = {
    Text = "Un liquide noir, une poudre noire, qui disparaissent finalement. C'est un paysage que vous connaissez très bien."
  },
  AvgDialog_131215_Content_97 = {
    Text = "Célébrez, mes enfants, mon peuple... la déesse du destin est sur le point de tisser son filet..."
  },
  AvgDialog_131215_Content_98 = {
    Text = "La marionnette regarde les filets qui se tissent sans cesse et disparaissent."
  },
  AvgDialog_131215_Content_99 = {
    Text = "Sa voix ne tremble pas, ses gestes ne montrent aucune hésitation. Elle continue à fredonner doucement une chanson, le rouet dans ses mains tourne, sans jamais s'arrêter."
  },
  AvgDialog_131216_Content_1 = {
    Text = "Fête masquée"
  },
  AvgDialog_131216_Content_10 = {
    Text = "C'est vraiment un double standard sans aucune dissimulation, aîné."
  },
  AvgDialog_131216_Content_11 = {
    Text = "Hum... Porter des jugements conformes à la personnalité des différentes personnes est une compétence fondamentale pour un enquêteur..."
  },
  AvgDialog_131216_Content_12 = {
    Text = "William fit semblant de ne pas avoir entendu votre provocation et commença à chercher sérieusement des cibles dignes de questionnement."
  },
  AvgDialog_131216_Content_13 = {
    Text = "J'ai tout perdu dans ce combat. Mon titre, ma famille, ma jambe gauche, ma vie."
  },
  AvgDialog_131216_Content_14 = {
    Text = "Vingt ans, exactement vingt ans. C'est une torture, mon ami. Le destin m'a laissé vivre, me permettant de racheter mes erreurs avec le reste de ma vie."
  },
  AvgDialog_131216_Content_15 = {
    Text = "Ma famille a été détruite par mes propres mains, mais qu'est-ce que cela change ? Dis-moi, qu'est-ce qui est plus important que l'alcool dans la vie ?"
  },
  AvgDialog_131216_Content_16 = {Text = "新增"},
  AvgDialog_131216_Content_17 = {
    Text = "Ah, mon cher, tu te souviens du cocktail que le barman nous a préparé la dernière fois que nous sommes venus ici ?"
  },
  AvgDialog_131216_Content_18 = {
    Text = "Je parie qu'on ne trouve pas de vin meilleur que celui-là dans tout Londinium, il est si précis, si élégant, c'est presque une prédiction"
  },
  AvgDialog_131216_Content_19 = {
    Text = "Je pense qu'il serait bien d'inviter ce barman à la fête du mois prochain."
  },
  AvgDialog_131216_Content_2 = {
    Text = "« 90 minutes de minuit, 15 pouces de masque, 10 gallons de rêve, 2 onces d'alcool — la seule recette du bonheur »"
  },
  AvgDialog_131216_Content_20 = {Text = "新增"},
  AvgDialog_131216_Content_21 = {Text = "Clac —"},
  AvgDialog_131216_Content_22 = {
    Text = "Un claquement de doigts sec résonne comme un feu d'artifice près de votre oreille. Vous vous retournez pour découvrir un visage illuminé d'un sourire radieux."
  },
  AvgDialog_131216_Content_23 = {
    Text = "Permettez-moi de vous interrompre, cher invité. En entendant tant de sujets intéressants, pourquoi ne pas accompagner cela d'un verre de vin tout aussi intéressant ?"
  },
  AvgDialog_131216_Content_24 = {
    Text = "Regarde la carte des vins, William, l'Aîné."
  },
  AvgDialog_131216_Content_25 = {
    Text = "William comprit votre regard. Deux personnes en uniformes inconnus apparaissaient ici, n'ayant pas bu une goutte d'alcool, il était vraiment difficile de ne pas attirer l'attention."
  },
  AvgDialog_131216_Content_26 = {
    Text = "Voyant son regard cherchant la carte des vins, le barman secoua la tête en souriant."
  },
  AvgDialog_131216_Content_27 = {
    Text = "Carte des vins ? Ah, ennuyeux, monotone, banal."
  },
  AvgDialog_131216_Content_28 = {
    Text = "Un bistrot romantique ne devrait pas avoir de choses aussi ennuyeuses."
  },
  AvgDialog_131216_Content_29 = {
    Text = "Pas de carte des vins ? Alors comment allons-nous commander ?"
  },
  AvgDialog_131216_Content_3 = {
    Text = "Je connais par cœur le slogan du bar «Masque de Minuit». Quand j'étais à Kadath, c'était l'endroit que je voulais le plus visiter."
  },
  AvgDialog_131216_Content_30 = {
    Text = "Chaque siège du masque de minuit est un théâtre qui appartient à une personne. Vous êtes ici pour regarder, performer, déguster..."
  },
  AvgDialog_131216_Content_31 = {
    Text = "Parmi d'innombrables histoires, je vais choisir celle qui vous convient le mieux."
  },
  AvgDialog_131216_Content_32 = {
    Text = "Veuillez vous asseoir, mesdames. Le lecteur de l'histoire est déjà prêt."
  },
  AvgDialog_131216_Content_33 = {
    Text = "Vous échangez un regard avec William et vous vous asseyez hésitamment près du bar."
  },
  AvgDialog_131216_Content_34 = {
    Text = "Tout d'abord, vous, ce gentleman blond au visage sévère."
  },
  AvgDialog_131216_Content_35 = {
    Text = "Le barman s'approcha de vous. Face à ce regard attentif, William toussota doucement, détournant le regard avec un certain malaise."
  },
  AvgDialog_131216_Content_36 = {
    Text = "Ah... les entraînements rigoureux jour après jour ont donné lieu à des réalisations si remarquables. Persévérance, calme, ténacité, courage, sagesse... une légende vivante, entourée de fleurs et d'auréoles."
  },
  AvgDialog_131216_Content_37 = {
    Text = "Et pourtant, derrière les louanges et l'auréole se cache... le regret. Un regret plus profond et plus douloureux que le brouillard qui étouffe cette ville."
  },
  AvgDialog_131216_Content_38 = {
    Text = "Combien de larmes invisibles dans les nuits profondes. Ces serments murmurés à soi-même."
  },
  AvgDialog_131216_Content_39 = {
    Text = "Cette lumière qui t'a éclairé dans le couloir sombre s'est éteinte dans l'obscurité infinie, emportant avec elle ton monde, brisé, brisé..."
  },
  AvgDialog_131216_Content_4 = {
    Text = "Les règlements de Mizag ne sont-ils pas parfois un peu trop stricts ?"
  },
  AvgDialog_131216_Content_40 = {
    Text = "Vous pensez en vous–même : <Italic:Si seulement j'avais travaillé plus dur. Si seulement j'avais été plus fort... peut–être aurais–je pu tisser un destin différent pour mon cher ami.>"
  },
  AvgDialog_131216_Content_41 = {
    Text = "L'expression de William, l'Aîné reste un masque d'indifférence, mais vous remarquez les veines saillantes sur la main qui serre son verre à s'en blanchir les phalanges."
  },
  AvgDialog_131216_Content_42 = {
    Text = "J'ai entendu le bruit d'un monde qui se brise. Le petit garçon endure la douleur, ramassant les morceaux un par un, les assemblant..."
  },
  AvgDialog_131216_Content_43 = {
    Text = "Dans cette longue et cruelle mosaïque, le garçon est enfin devenu un homme."
  },
  AvgDialog_131216_Content_44 = {
    Text = "Le barman, tout en parlant d'une voix longue et douce, commença à préparer des cocktails en prenant des bouteilles de formes variées sur une étagère à vin qui semblait sans fin derrière lui."
  },
  AvgDialog_131216_Content_45 = {
    Text = "Rapidement, le liquide doré pâle dans le verre classique fut poussé devant William."
  },
  AvgDialog_131216_Content_46 = {
    Text = "2 onces de whiskey, 1 once de vin blanc, et cette couleur de fond douloureuse et résiliente - 2 gouttes d'amer."
  },
  AvgDialog_131216_Content_47 = {
    Text = "L'«Éclaireur.» Puissiez–vous guider ceux qui vous admirent vers le droit chemin — tout comme <Yellow:il> l'a fait pour vous autrefois, celui que vous estimez le plus."
  },
  AvgDialog_131216_Content_48 = {
    Text = "William, l'Aîné accepte la boisson dorée, la faisant tournoyer lentement tandis qu'il étudie la barmaid d'un regard perçant."
  },
  AvgDialog_131216_Content_49 = {
    Text = "Tout ce que tu viens de dire... comment le sais-tu ?"
  },
  AvgDialog_131216_Content_5 = {
    Text = "Je propose d'interdire aux étudiants de Mizag d'entrer dans de tels lieux sans autorisation, afin d'éviter que certains gardiens du secret, sous prétexte de missions d'enquête, ne gaspillent les fonds alloués aux missions."
  },
  AvgDialog_131216_Content_50 = {
    Text = "Un bon barman doit savoir écouter les désirs de ses clients. C'est un secret qui appartient aux barmans, cher invité."
  },
  AvgDialog_131216_Content_51 = {
    Text = "La barmaid esquive le regard de William, l'Aîné avec la grâce d'une biche. Elle presse un doigt sur ses lèvres en un geste de silence, puis pointe directement vers vous."
  },
  AvgDialog_131216_Content_52 = {
    Text = "C'est à vous, cher invité..."
  },
  AvgDialog_131216_Content_53 = {
    Text = "J'ai le pressentiment que c'est peut-être la chose la plus dangereuse que j'ai jamais essayée dans ma vie — mais peu importe, j'aime l'aventure."
  },
  AvgDialog_131216_Content_54 = {
    Text = "Elle se penche tout près, scrutant intensément vos yeux. Vous pouvez presque entendre le rythme doux de sa respiration."
  },
  AvgDialog_131216_Content_55 = {
    Text = "Hum... Ce que je regarde, c'est un invité venu de loin, ou peut-être... une divinité tombée dans le monde des mortels, ayant rencontré de nombreuses difficultés ?"
  },
  AvgDialog_131216_Content_56 = {Text = "?!!"},
  AvgDialog_131216_Content_57 = {
    Text = "Tu te lèves instinctivement et recules de deux pas."
  },
  AvgDialog_131216_Content_58 = {
    Text = "Cela ne peut pas être quelque chose qu'un simple barman sait... Qui es-tu vraiment ?"
  },
  AvgDialog_131216_Content_59 = {
    Text = "Soyez rassuré, cher invité. Dans ce bar, ce n'est pas moi qui ai de mauvaises intentions."
  },
  AvgDialog_131216_Content_6 = {
    Text = "Après tout, cette personne a un certain nombre de précédents dans sa carrière d'étudiant en tant que Gardien."
  },
  AvgDialog_131216_Content_60 = {
    Text = "Peut-être as-tu déjà remarqué qu'il y a quelques « vieux amis » derrière toi."
  },
  AvgDialog_131216_Content_61 = {
    Text = "%player%, attention derrière."
  },
  AvgDialog_131216_Content_62 = {
    Text = "Je ressens..."
  },
  AvgDialog_131216_Content_63 = {
    Text = "Sous l'avertissement du barman, tu remarques qu'une douzaine de vibrations spirituelles intenses se rapprochent rapidement de vous dans toutes les directions."
  },
  AvgDialog_131216_Content_64 = {
    Text = "William, l'Aîné se place dans votre dos en parfaite synchronie. Vous serrez fermement votre Clé d'argent, les yeux rivés sur l'énigmatique barman."
  },
  AvgDialog_131216_Content_65 = {
    Text = "Le barman lâcha le verre qu'il tenait et déposa la bouteille de vin sur un coin difficile à briser."
  },
  AvgDialog_131216_Content_66 = {
    Text = "Doucement, %player%. Ils vous suivent depuis un moment. Ici, au moins, je peux vous offrir une certaine aide."
  },
  AvgDialog_131216_Content_67 = {
    Text = "Toi ? Ils ? ..."
  },
  AvgDialog_131216_Content_68 = {
    Text = "Heh... Trouvé."
  },
  AvgDialog_131216_Content_69 = {
    Text = "Cet endroit crasseux ne convient guère à un long séjour, mes petits visiteurs venus de loin."
  },
  AvgDialog_131216_Content_7 = {
    Text = "Je me souviens que dans le dossier de Fingal, l'Aîné, il était mentionné que son plus grand hobby était de prendre un verre au Masque de Minuit après le travail..."
  },
  AvgDialog_131216_Content_70 = {
    Text = "Attention, ils arrivent"
  },
  AvgDialog_131216_Content_8 = {
    Text = "......Bien sûr, un repos occasionnel n'est pas complètement une mauvaise chose."
  },
  AvgDialog_131216_Content_9 = {
    Text = "De plus, le registre des membres du Masque de Minuit contient les célébrités de tout Londinium, ce qui en fait le lieu idéal pour collecter des informations."
  },
  AvgDialog_131217_Content_1 = {
    Text = "Le pouvoir des trois plasmides s'est apaisé en toi, mais tu n'as toujours pas ouvert les yeux."
  },
  AvgDialog_131217_Content_10 = {
    Text = "L›esprit des contrats, les principes commerciaux... un marché nécessite un levier. Tu sais comment ça fonctionne, n›est-ce pas ?"
  },
  AvgDialog_131217_Content_11 = {
    Text = "« N » secoue la tête, peinant à réprimer son rire."
  },
  AvgDialog_131217_Content_12 = {
    Text = "La bonne nouvelle, c›est que tu disposes toujours du levier parfait."
  },
  AvgDialog_131217_Content_13 = {
    Text = "Un vaillant gardien sur le point d›abandonner {Male=his,Female=her} foi, se noyant dans la toile du Destin — trompant, trichant, totalement sans principes... quel spectacle captivant !"
  },
  AvgDialog_131217_Content_14 = {
    Text = "Je ne manquerais la meilleure place pour rien au monde."
  },
  AvgDialog_131217_Content_15 = {
    Text = "Quand ai-je dit... ?"
  },
  AvgDialog_131217_Content_16 = {
    Text = "Le Fêtard n›a aucune patience pour vos questions. Il soupèse la dette que vous lui devrez à l›avenir et agite un doigt avec un sourire."
  },
  AvgDialog_131217_Content_17 = {
    Text = "Ce n'est pas un conseil, juste une petite et sincère suggestion."
  },
  AvgDialog_131217_Content_18 = {
    Text = "Pourquoi résister à Nefraea ? Pourquoi ne pas lui obéir, Gardien {Male=Monsieur,Female=Madame} ?"
  },
  AvgDialog_131217_Content_19 = {
    Text = "« N » sourit et se penche vers vous, aussi bienveillant qu›un avocat rendant visite à un client en prison."
  },
  AvgDialog_131217_Content_2 = {
    Text = "Ta conscience plonge dans l'immensité de l'océan spirituel, plonge, plonge jusqu'à ces ténèbres infinies, jusqu'à cet abîme qui t'appartient et que tu ne peux pas voir clairement."
  },
  AvgDialog_131217_Content_20 = {
    Text = "Toi... que dis-tu ? Non, je ne peux absolument pas..."
  },
  AvgDialog_131217_Content_21 = {
    Text = "Ah, c'est vrai, je ne capitulerai jamais, je n'abandonnerai jamais, je ne reconnaîtrai jamais les actes de Nefraea... un héroïsme ancien et classique."
  },
  AvgDialog_131217_Content_22 = {
    Text = "Envoie-nous à Nefraea, invoque ton cher cousin, retourne dans ce palais qui t'appartient... À part cela, que peux-tu faire maintenant, %player% ?"
  },
  AvgDialog_131217_Content_23 = {
    Text = "Je vais te révéler un secret : puisque tu ne peux plus échapper à ce filet, pourquoi ne pas ouvrir les bras et accueillir son arrivée ?"
  },
  AvgDialog_131217_Content_24 = {
    Text = "Arrête de rêver, « N ». Je ne pourrais jamais..."
  },
  AvgDialog_131217_Content_25 = {
    Text = "Chut. Ne te mets pas si facilement de limites, ma chère."
  },
  AvgDialog_131217_Content_26 = {
    Text = "N'oublie pas qu'Arachne a lié ton destin à la toile géante. Toi, tu es déjà l'un des leurs."
  },
  AvgDialog_131217_Content_27 = {
    Text = "Cette personne, la déesse du destin, t'a donné une clé appelée plaisir. Mais as-tu déjà pensé à où cette porte mène et vers quoi elle conduit ?"
  },
  AvgDialog_131217_Content_28 = {
    Text = "Là où la Porte fait face... là où elle mène... ?"
  },
  AvgDialog_131217_Content_29 = {
    Text = "Je pensais qu'Arachne était une femme travailleuse, gentille et peu remarquable, dont la seule compétence était de tisser des toiles et de sourire. Mais elle est beaucoup plus intéressante que je ne l'imaginais."
  },
  AvgDialog_131217_Content_3 = {
    Text = "Tu t'efforces d'ouvrir une bouche qui n'existe pas, criant silencieusement et avec colère dans cet abîme."
  },
  AvgDialog_131217_Content_30 = {
    Text = "Elle a tissé un immense filet pour cette scène, et dès le premier instant où tu es arrivé dans ce monde, ce filet a commencé à se déployer pour toi."
  },
  AvgDialog_131217_Content_31 = {
    Text = "Avoir une telle capacité exceptionnelle, et pourtant faire des choses aussi stupides que de maintenir le monde en fonctionnement... Quel dommage, c'est vraiment trop dommage."
  },
  AvgDialog_131217_Content_32 = {
    Text = "Monter sur la scène du théâtre du destin, c'est devenir un personnage sur cette scène. Chaque personnage a sa propre vie."
  },
  AvgDialog_131217_Content_33 = {
    Text = "Le destin te pousse à faire ce choix, afin que tu puisses le voir clairement. Tu ne peux pas voir les fils, mais tu comprends maintenant comment ces fils s'entrelacent de manière si complexe."
  },
  AvgDialog_131217_Content_34 = {
    Text = "Le fil du destin tisse un immense réseau, chaque léger tremblement de chaque fil pourrait faire basculer le filet du destin."
  },
  AvgDialog_131217_Content_35 = {
    Text = "C›est le Destin, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131217_Content_36 = {
    Text = "Performance, tromperie, plaisir... tu possèdes une telle force en toi. La scène du destin ne prépare pas d'opportunités pour tout le monde. Quand tu devras monter sur scène, ces forces t'aideront."
  },
  AvgDialog_131217_Content_37 = {
    Text = "Vous ne pouvez pas fuir les rôles que vous étiez destiné à jouer. Réfléchissez, puis jouez, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131217_Content_38 = {
    Text = "«Plaisir»."
  },
  AvgDialog_131217_Content_39 = {
    Text = "Dans ton bref avenir, « Plaisir » est une clé qui déverrouillera les secrets auxquels tu fais face."
  },
  AvgDialog_131217_Content_4 = {Text = "« N » !"},
  AvgDialog_131217_Content_40 = {
    Text = "...Quoi qu'il arrive, fais-moi confiance, et fais-toi confiance aussi."
  },
  AvgDialog_131217_Content_41 = {
    Text = "Retournez au Théâtre du destin. La clé et la serrure vous y attendent, %player%."
  },
  AvgDialog_131217_Content_42 = {
    Text = "Les paroles d'Arachne se faufilent et s'entrelacent comme des fils dans votre esprit. Enfin, elles forment une immense toile, dense et serrée."
  },
  AvgDialog_131217_Content_43 = {
    Text = "Tu comprends enfin, depuis notre première rencontre, qu'Arachne converse à travers le temps avec toi, ici et maintenant."
  },
  AvgDialog_131217_Content_44 = {
    Text = "Tu regardes avec émerveillement ce réseau complexe, comme si quelque chose de très important était en train de se former peu à peu dans ton esprit."
  },
  AvgDialog_131217_Content_45 = {
    Text = "Performance, tromper, séduire..."
  },
  AvgDialog_131217_Content_46 = {
    Text = "Ah, c'est vrai. Ne tente jamais de comprendre. Profite-en, c'est le seul secret du plaisir."
  },
  AvgDialog_131217_Content_47 = {
    Text = "Joie et tristesse, bien et mal, toutes les émotions et la morale n'existent plus. Il n'y a rien d'autre que le plaisir."
  },
  AvgDialog_131217_Content_48 = {
    Text = "Maintenant, dis-moi... comprends-tu «Plaisir», Gardien ?"
  },
  AvgDialog_131217_Content_49 = {
    Text = "Le sourire cramoisi de « N » s›efface de votre esprit. Vous voyez un miroir, et s›y reflète votre propre visage rieur."
  },
  AvgDialog_131217_Content_5 = {
    Text = "Chut... ta voix est trop forte, Gardien."
  },
  AvgDialog_131217_Content_50 = {
    Text = "Plaisir ? ... Plaisir ..."
  },
  AvgDialog_131217_Content_51 = {
    Text = "Hehehe... hahaha. C'est ça, plaisir, mon ami"
  },
  AvgDialog_131217_Content_52 = {
    Text = "Le mot le plus merveilleux de ce monde, tout le sens de l'existence de ce rêve..."
  },
  AvgDialog_131217_Content_53 = {
    Text = "Comme s›il entrevoyait la scène sur le point de se dérouler, tout le corps de N tremble de délice. Il presse un doigt enveloppé de brume sombre contre son propre front."
  },
  AvgDialog_131217_Content_54 = {
    Text = "Tu es sur le point d'arriver. Il ne reste qu'un pas, le dernier pas... Réfléchis bien, puis entre dans ce filet, Gardien."
  },
  AvgDialog_131217_Content_55 = {
    Text = "Le chemin du plaisir est là-dedans."
  },
  AvgDialog_131217_Content_6 = {
    Text = "Le phantasme de « N » persiste. Il apparaît dans votre espace mental avec aisance, tel le maître incontesté du royaume."
  },
  AvgDialog_131217_Content_7 = {
    Text = "«Plaisir» dont parle Arachne doit certainement te concerner"
  },
  AvgDialog_131217_Content_8 = {
    Text = "« N », donne-moi un indice..."
  },
  AvgDialog_131217_Content_9 = {
    Text = "Avertissement ? Hahaha... Qu'ai-je fait pour que tu m'humilies ainsi ?"
  },
  AvgDialog_131218_Content_10 = {
    Text = "Toi... vous êtes..."
  },
  AvgDialog_131218_Content_11 = {
    Text = "Homme d'âge moyen ivre, jeune femme, gentleman élégant, membre de gang dans la rue, serveur au visage fatigué, belle barmitaine..."
  },
  AvgDialog_131218_Content_12 = {
    Text = "Chaque visage dans le bar — jeune, vieux, beau ou ordinaire — se tourne vers vous à l'unisson, leurs expressions aussi identiques que des copies conformes."
  },
  AvgDialog_131218_Content_13 = {
    Text = "Ce ne sont pas des individus. Ce sont plutôt..."
  },
  AvgDialog_131218_Content_14 = {
    Text = "Ceux qui semblaient si pleins de vie il y a quelques instants se tiennent maintenant devant vous comme des mannequins de bois sans vie."
  },
  AvgDialog_131218_Content_15 = {
    Text = "...Plutôt des marionnettes, prises dans une toile."
  },
  AvgDialog_131218_Content_16 = {
    Text = "J'ai entendu parler de votre acuité, Monsieur William."
  },
  AvgDialog_131218_Content_17 = {
    Text = "Ce que vous voyez devant vous ne sont que des accessoires sur une scène — des reflets dans un miroir."
  },
  AvgDialog_131218_Content_18 = {
    Text = "Veuillez m'excuser. Je ne peux pas encore quitter ma toile. Je dois utiliser ces réceptacles pour m'adresser à vous."
  },
  AvgDialog_131218_Content_19 = {
    Text = "Bienvenue sur ma scène, M. William, l'Aîné... et vous, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131218_Content_2 = {
    Text = "C'est réglé, de quoi s'agit-il exactement..."
  },
  AvgDialog_131218_Content_20 = {
    Text = "Chaque mot est prononcé avec une précision troublante ; vingt voix distinctes se tissent ensemble en un seul fil de voix, froid et glacial."
  },
  AvgDialog_131218_Content_21 = {
    Text = "Tout le monde dans la pièce s'incline en parfaite unisson. L'angle de leurs dos et le placement de leurs mains se reflètent avec une exactitude surnaturelle."
  },
  AvgDialog_131218_Content_22 = {
    Text = "Ta... scène ? Qui es-tu vraiment ?"
  },
  AvgDialog_131218_Content_23 = {
    Text = "C'est le maître ici, et aussi un prisonnier."
  },
  AvgDialog_131218_Content_24 = {
    Text = "Je pense que vous devez avoir beaucoup de questions."
  },
  AvgDialog_131218_Content_25 = {
    Text = "Ici, ce n'est pas sûr, leurs hommes vont vite arriver. Ma servante viendra vous accueillir, après l'avoir rencontrée, ne vous inquiétez pas."
  },
  AvgDialog_131218_Content_26 = {
    Text = "Après la rencontre, je répondrai à toutes vos questions."
  },
  AvgDialog_131218_Content_27 = {
    Text = "À l'instant où ces mots quittent ses lèvres, la conscience de la foule semble se dissiper en un instant."
  },
  AvgDialog_131218_Content_28 = {
    Text = "Le verre en cristal d'un gentleman se fige à ses lèvres ; l'éventail ouvert d'une dame s'immobilise juste sous son menton ; la barmaid reste figée, le verre levé en l'air."
  },
  AvgDialog_131218_Content_29 = {
    Text = "Semblant que leurs fils ont été coupés d'un seul coup, tous conservent leur pose finale — des figures de cire figées sur place."
  },
  AvgDialog_131218_Content_3 = {
    Text = "Attention derrière toi !!..."
  },
  AvgDialog_131218_Content_30 = {
    Text = "Vous inspirez lentement et regardez autour de vous avec inquiétude cette mer de «marionnettes», chacune figée avec ce même sourire immuable."
  },
  AvgDialog_131218_Content_31 = {
    Text = "Bien qu'ils m'aient vraiment aidé tout à l'heure, je ne peux vraiment pas y croire complètement..."
  },
  AvgDialog_131218_Content_32 = {
    Text = "William, l'Aîné, ce que nous voulons savoir, cette personne « Maître » est peut-être le meilleur répondant."
  },
  AvgDialog_131218_Content_33 = {
    Text = "Même s'il y a des dangers, je pense que je dois y aller, juste..."
  },
  AvgDialog_131218_Content_34 = {
    Text = "Je comprends."
  },
  AvgDialog_131218_Content_35 = {
    Text = "William comprit votre regard et hocha la tête."
  },
  AvgDialog_131218_Content_36 = {
    Text = "Je vais enquêter sur les mouvements de ces ombres à l'extérieur, elles te cherchent, je serai en sécurité à l'extérieur plus que toi."
  },
  AvgDialog_131218_Content_37 = {
    Text = "Cette personne «maître» est d'origine inconnue, si elle rencontre un danger..."
  },
  AvgDialog_131218_Content_38 = {
    Text = "William toucha légèrement l'insigne sur sa poitrine. Dans ce monde, vous êtes la seule personne avec qui l'insigne de l'autre peut entrer en contact."
  },
  AvgDialog_131218_Content_39 = {
    Text = "Je comprends... Toi aussi, William, l'Aîné."
  },
  AvgDialog_131218_Content_4 = {
    Text = "Un fort sentiment de crise te réveille instantanément. Tu te retournes brusquement et vois la lame d'ombre à quelques centimètres devant toi."
  },
  AvgDialog_131218_Content_40 = {
    Text = "«Maître», je comprends votre prudence. Monsieur William, cette scène comporte actuellement de nombreux dangers, veuillez agir avec précaution. Dans la mesure de nos capacités, nous vous fournirons l'aide nécessaire."
  },
  AvgDialog_131218_Content_41 = {
    Text = "Des araignées d'un violet pâle convergent de chaque recoin du bar, et une servante aux traits d'araignée apparaît silencieusement derrière vous tous. Après vous avoir poliment salué d'une révérence, elle se dirige vers la porte."
  },
  AvgDialog_131218_Content_42 = {
    Text = "{Male=Mr.,Female=Miss} Gardien, veuillez me suivre. La Dame vous attend."
  },
  AvgDialog_131218_Content_5 = {Text = "Ssss—"},
  AvgDialog_131218_Content_6 = {
    Text = "Tu retires lentement ton bras qui te protège les yeux. L'ombre est tranchée par la personne derrière toi, un liquide noir éclabousse, te couvrant de la tête aux pieds."
  },
  AvgDialog_131218_Content_7 = {
    Text = "Désolé de vous avoir fait peur."
  },
  AvgDialog_131218_Content_8 = {
    Text = "Ils ont toujours recherché vos traces. Ici, ma force peut encore vous apporter une certaine aide."
  },
  AvgDialog_131218_Content_9 = {
    Text = "Sans votre consentement, je vous ai conduits ici à votre insu, j'espère que cela ne vous dérange pas."
  },
  AvgDialog_131219_Content_1 = {
    Text = "Est-ce que... c'est fini ?"
  },
  AvgDialog_131219_Content_2 = {
    Text = "Soyez prudent, Gardien... le fuseau qui démêle le destin a déjà commencé à tourner derrière elle..."
  },
  AvgDialog_131219_Content_3 = {
    Text = "Heh... hahahaha... !"
  },
  AvgDialog_131220_Content_1 = {
    Text = "Cygne en vol"
  },
  AvgDialog_131220_Content_10 = {
    Text = "Tu te souviens de cette grande porte rouillée qui émet un bruit sourd à chaque mouvement, comme le souffle bienveillant de ton grand-père."
  },
  AvgDialog_131220_Content_11 = {
    Text = "L'Université Miskatonic..."
  },
  AvgDialog_131220_Content_12 = {
    Text = "Dans cet environnement familier, tu effleures le nom complètement différent sur la plaque de la place."
  },
  AvgDialog_131220_Content_13 = {
    Text = "Chaque acteur a sa scène préférée. Même un campus répliqué par la mémoire est irremplaçable pour toi."
  },
  AvgDialog_131220_Content_14 = {
    Text = "Pourquoi créer un endroit identique à Mizag... ?"
  },
  AvgDialog_131220_Content_15 = {
    Text = "Je ne l'ai pas créé, il doit simplement exister ici. Comme cette ville et ce monde, ils font tous partie du filet du destin."
  },
  AvgDialog_131220_Content_16 = {
    Text = "Ne regardez pas si loin devant vous, %player%. Si vous êtes sur une scène, c'est qu'il y a une raison à votre présence ici."
  },
  AvgDialog_131220_Content_17 = {
    Text = "En parlant de cela, après avoir passé tant de temps avec Liz, je n'ai jamais vu son spectacle en direct..."
  },
  AvgDialog_131220_Content_18 = {
    Text = "Tu regardes autour de cette place familière, tes mains glissant doucement sur l'herbe en dessous de toi."
  },
  AvgDialog_131220_Content_19 = {
    Text = "Le moment le plus merveilleux de la vie est celui où l'on ne se rend pas compte que l'on sourit."
  },
  AvgDialog_131220_Content_2 = {
    Text = "C'est vraiment rare, le prix des billets pour cette troupe au théâtre, le moins cher me coûtera deux mois de salaire."
  },
  AvgDialog_131220_Content_20 = {
    Text = "Ah... désolé..."
  },
  AvgDialog_131220_Content_21 = {
    Text = "Tu te souviens de ce qui s'est passé à Mizag ?"
  },
  AvgDialog_131220_Content_22 = {
    Text = "Sur cette place, nous avons organisé de nombreuses représentations sur le campus. À l'époque, tout comme maintenant, les étudiants de Mizag remplissaient la place."
  },
  AvgDialog_131220_Content_23 = {
    Text = "Il y a de nombreux Éveilleurs qui ont une grande maîtrise artistique. Beaucoup de gens étaient initialement réticents à se produire dans ce genre d'événements, alors mes collègues et moi avons réfléchi à toutes sortes de méthodes..."
  },
  AvgDialog_131220_Content_24 = {
    Text = "Plus tard, beaucoup d'entre eux ont également commencé à vouloir faire des démonstrations pour leurs camarades ici."
  },
  AvgDialog_131220_Content_25 = {
    Text = "La danse de Liz, la chanson de Tinct, la symphonie de Hamelin, la poésie de Horla, la sculpture de Sanga..."
  },
  AvgDialog_131220_Content_26 = {
    Text = "Je ne sais pas si la vie à Mizag est revenue à la normale après mon départ..."
  },
  AvgDialog_131220_Content_27 = {
    Text = "Le rideau bouge ! Le rideau bouge ! Mademoiselle Liz va bientôt entrer en scène !"
  },
  AvgDialog_131220_Content_28 = {
    Text = "Tu secoues la tête, chassant ces émotions mélancoliques de ton esprit."
  },
  AvgDialog_131220_Content_29 = {
    Text = "Quoi qu'il en soit, pouvoir voir à nouveau la danse de Liz dans ce monde lointain est une chose à célébrer."
  },
  AvgDialog_131220_Content_3 = {
    Text = "On dit que c'est une représentation caritative parrainée par Madame Sorel en son nom personnel ! Quel bonheur ce serait si chaque gentleman et dame de cette ville avait autant de bonté"
  },
  AvgDialog_131220_Content_30 = {
    Text = "Quand cette affaire sera complètement réglée, si j'ai le temps, j'aimerais bien discuter avec eux."
  },
  AvgDialog_131220_Content_31 = {
    Text = "Mesdames et messieurs... bienvenue dans notre spectacle"
  },
  AvgDialog_131220_Content_32 = {
    Text = "La compagnie de danse du cygne, quel nom sacré et inaccessible ! Ce plus élégant des cygnes blancs de Londinium va aujourd'hui se poser pour la première fois devant le public de Londinium"
  },
  AvgDialog_131220_Content_33 = {
    Text = "Merci de votre patience. Nos acteurs sont prêts. Un spectacle exceptionnel va bientôt vous être présenté"
  },
  AvgDialog_131220_Content_34 = {
    Text = "Avec le claquement de doigts clair de l'annonceur, toutes les lumières environnantes s'éteignent, et plusieurs projecteurs se concentrent au centre de l'écran."
  },
  AvgDialog_131220_Content_35 = {
    Text = "Ensuite, veuillez apprécier la danse présentée par Mademoiselle Liz, le cygne — s'envoler !"
  },
  AvgDialog_131220_Content_36 = {
    Text = "Dans les applaudissements chaleureux et les cris de la foule, le rideau se lève lentement——"
  },
  AvgDialog_131220_Content_37 = {
    Text = "<Big:<Red:!!!!>>"
  },
  AvgDialog_131220_Content_38 = {
    Text = "Tu as vu Liz à de nombreuses reprises."
  },
  AvgDialog_131220_Content_39 = {
    Text = "Sur la scène de la salle de cérémonie de Mizag, elle tourne rien que pour toi."
  },
  AvgDialog_131220_Content_4 = {
    Text = "Bien que je ne comprenne pas, une telle opportunité ne doit pas être manquée."
  },
  AvgDialog_131220_Content_40 = {
    Text = "Sous le ciel étoilé de Londinium, elle se mit sur la pointe des pieds et toucha les lucioles dansant dans la nuit."
  },
  AvgDialog_131220_Content_41 = {
    Text = "Dans la brise de Charing Cross, sa jupe se lève haut, telle une flamme ardente."
  },
  AvgDialog_131220_Content_42 = {
    Text = "Et aujourd'hui, sur la scène d'un pays lointain, elle apparaît devant toi dans une posture que tu n'as jamais vue."
  },
  AvgDialog_131220_Content_43 = {
    Text = "La première étoile de la compagnie de danse du cygne, le feu d'artifice le plus éclatant de toute la ville. Des épines noires percent sa trachée, ses bras, son abdomen, ses pieds en pointes, perçant son corps qui maîtrise la danse."
  },
  AvgDialog_131220_Content_44 = {
    Text = "Le sang éclabousse, dessinant une paire d'ailes écarlates sur le panneau derrière elle, laissant sur son visage souriant quelques marques sinistres."
  },
  AvgDialog_131220_Content_45 = {
    Text = "La foule est silencieuse, le vent souffle à travers la vaste place, la jupe noire et verte danse dans les airs, comme une flamme éternelle brûlant."
  },
  AvgDialog_131220_Content_46 = {
    Text = "—— À cet instant, tu comprends parfaitement que si la mort est inévitable, alors c'est ainsi que Liz désire le plus mourir."
  },
  AvgDialog_131220_Content_47 = {
    Text = "Elle a achevé un dernier salut avec son sang et sa vie. Sa danse s'est figée dans le plus beau des sauts, tel un cygne noir en vol."
  },
  AvgDialog_131220_Content_48 = {
    Text = "Quelle grâce, quelle beauté dans la danse de Mademoiselle Liz"
  },
  AvgDialog_131220_Content_49 = {
    Text = "Appréciez en silence, mes chers amis spectateurs ! Être témoin de cette scène est votre unique privilège dans cette vie."
  },
  AvgDialog_131220_Content_5 = {
    Text = "Trente ans... cela fait trente ans que je n'ai pas pu retourner au théâtre pour voir un spectacle..."
  },
  AvgDialog_131220_Content_50 = {
    Text = "Tu vois le visage de l'annonceur déchiré en deux. Le visage de l'homme d'âge moyen, sans vie, fond comme une mucosité, révélant les yeux de Nefraea remplis d'excitation."
  },
  AvgDialog_131220_Content_51 = {
    Text = "Dans les cris et la fuite chaotiques de la foule, son rire perçant te transperce les tympans comme une aiguille empoisonnée."
  },
  AvgDialog_131220_Content_52 = {
    Text = "<Big:Liz !!>"
  },
  AvgDialog_131220_Content_53 = {
    Text = "Tu écartes la foule en panique et cours devant la scène."
  },
  AvgDialog_131220_Content_54 = {
    Text = "Ah, ce client intelligent, comment savez-vous qu'il y a un deuxième acte dans ce spectacle de danse ?"
  },
  AvgDialog_131220_Content_55 = {
    Text = "Autour de la scène, certains spectateurs qui n'ont pas fui se rapprochent rapidement de toi. Leurs corps éclatent en courant, laissant surgir ces serviteurs noirs araignées qui ne cessent de tuer."
  },
  AvgDialog_131220_Content_56 = {
    Text = "Sur la scène devant toi, le corps de Liz s'est détaché des épines. Une œuvre d'art fabriquée par des païens, remplie de vides cruels et de sang éclatant."
  },
  AvgDialog_131220_Content_57 = {
    Text = "Des empreintes de pas ensanglantées s'étendent depuis le centre de la scène. Liz marche vers vous, le visage peint d'un masque macabre et saisissant de sang qui vous coupe le souffle."
  },
  AvgDialog_131220_Content_58 = {
    Text = "Elle leva les yeux vers toi. Ses yeux vides et ensanglantés te rappellent toutes les œuvres d'art dignes d'être transmises au monde."
  },
  AvgDialog_131220_Content_59 = {
    Text = "Maintenant, il est temps de danser avec votre vieille amie... {Male=Mr.,Female=Miss} Gardien !"
  },
  AvgDialog_131220_Content_6 = {
    Text = "Le ballet, la danse la plus pure de ce monde, n'est compris que par ceux qui l'ont vraiment pratiqué, et ils savent à quel point cette élégance cruelle est belle"
  },
  AvgDialog_131220_Content_7 = {
    Text = "C'est quelque chose que je n'aurais jamais imaginé, pouvoir voir la performance de Mlle Liz en direct..."
  },
  AvgDialog_131220_Content_8 = {
    Text = "Les bruits ambiants qui auraient dû être assourdissants se mêlent dans tes oreilles en un lointain bruit blanc."
  },
  AvgDialog_131220_Content_9 = {
    Text = "Tu te souviens de cette pelouse, de ce lac. Tu te souviens de ces bâtiments scolaires de hauteurs variées, tu te souviens de cette sculpture au regard déterminé tournée vers l'horizon."
  },
  AvgDialog_131221_Content_1 = {
    Text = "Deuxième acte"
  },
  AvgDialog_131221_Content_10 = {
    Text = "Je suis le prisonnier du destin, ce n'est qu'un devoir que je dois accomplir."
  },
  AvgDialog_131221_Content_11 = {
    Text = "Une personne capable de contrôler le destin de nombreux mondes, peut-être serait-il plus approprié de se qualifier de juge du destin ou de directeur de prison ?"
  },
  AvgDialog_131221_Content_12 = {
    Text = "Dans la prison du destin, le geôlier et le prisonnier ne font pas de différence."
  },
  AvgDialog_131221_Content_13 = {
    Text = "Monsieur William, cela va-t-il sur ce chemin ?"
  },
  AvgDialog_131221_Content_14 = {
    Text = "Grâce à votre servante, si je devais me fier uniquement à moi-même pour me débarrasser de ces serviteurs dans l'ombre, il me faudrait probablement payer un prix encore plus élevé."
  },
  AvgDialog_131221_Content_15 = {
    Text = "Nefraea... tu as encore rencontré quelqu'un d'elle ?"
  },
  AvgDialog_131221_Content_16 = {
    Text = "William hocha la tête gravement."
  },
  AvgDialog_131221_Content_17 = {
    Text = "Quand nous avons été séparés, j'ai croisé des passants qui semblaient... étranges. Je les ai suivis un moment et j'ai capté des bribes de leur conversation."
  },
  AvgDialog_131221_Content_18 = {
    Text = "Elles cherchent quelque chose appelé « Pair secrets »."
  },
  AvgDialog_131221_Content_19 = {
    Text = "Je pense que... la pollution du destin de la scène dont vous parliez tout à l'heure n'est peut-être qu'un moyen préliminaire."
  },
  AvgDialog_131221_Content_2 = {
    Text = "Quel spectacle..."
  },
  AvgDialog_131221_Content_20 = {
    Text = "Ces «Pair secrets » sont en réalité leur véritable objectif."
  },
  AvgDialog_131221_Content_21 = {
    Text = "Ma sœur a dissimulé son propre Fil du destin ainsi que celui de ses écuyers ; je ne peux pas les percevoir facilement. C'est un renseignement crucial, M. William, l'Aîné."
  },
  AvgDialog_131221_Content_22 = {
    Text = "La prochaine action, je vais être avec vous..."
  },
  AvgDialog_131221_Content_23 = {Text = "Non !"},
  AvgDialog_131221_Content_24 = {
    Text = "Non, vous devez rester ! Se séparer tout à l'heure était une nécessité, mais je ne prendrai pas le risque de revivre ce qui s'est passé à Lemvahi."
  },
  AvgDialog_131221_Content_25 = {
    Text = "Le Gardien a raison. Ma servante traitera les toxines dans votre organisme. Jusqu'à votre rétablissement complet, veuillez rester dans le théâtre pour vous reposer."
  },
  AvgDialog_131221_Content_26 = {
    Text = "Bientôt, nous accueillerons ce jour où nous aurons besoin de ton aide."
  },
  AvgDialog_131221_Content_27 = {
    Text = "Les paroles d'Arachne ressemblent à un jugement doux, perçant facilement le corps et l'âme, tombant doucement dans le destin de William."
  },
  AvgDialog_131221_Content_28 = {
    Text = "William jeta un coup d'œil au sang qui s'écoulait de son abdomen et hocha doucement la tête."
  },
  AvgDialog_131221_Content_29 = {
    Text = "Si j'y allais maintenant, je ne serais qu'un fardeau. Soyez rassurée, je m'assurerai d'être prêt le jour venu."
  },
  AvgDialog_131221_Content_3 = {
    Text = "<Shake:Tousse tousse...>"
  },
  AvgDialog_131221_Content_30 = {
    Text = "Arachne sourit en tendant la main. Une, deux... d'innombrables araignées sortirent de ses manches et tombèrent au sol le long des fils."
  },
  AvgDialog_131221_Content_31 = {
    Text = "Les araignées tombent comme la pluie, convergeant et grouillant ensemble. La masse d'arachnides se superpose pour former une silhouette humaine tandis que couleur et lumière s'accrochent à la forme mouvante."
  },
  AvgDialog_131221_Content_32 = {
    Text = "Rapidement, une nouvelle Arachne identique se tient devant vous."
  },
  AvgDialog_131221_Content_33 = {
    Text = "Suivez–moi, {Male=Mr.,Female=Miss} Gardien. Je crois que le moment d'une rencontre en face à face avec ma sœur est venu."
  },
  AvgDialog_131221_Content_34 = {Text = "新增"},
  AvgDialog_131221_Content_35 = {
    Text = "Il y a beaucoup de boutiques que j'adore dans cette ville, mais tout comme toi, c'est aussi l'un de mes endroits préférés."
  },
  AvgDialog_131221_Content_36 = {
    Text = "Masque de minuit, tu es assis à la même place que la dernière fois, fronçant les sourcils en regardant Arachne qui observe les lieux."
  },
  AvgDialog_131221_Content_37 = {
    Text = "Alors, que es-tu exactement maintenant... une marionnette ? Un clone ? Une mystérieuse machine faite de plusieurs araignées qui t'aide à t'échapper ?"
  },
  AvgDialog_131221_Content_38 = {
    Text = "En essence, le moi ici et le moi dans le théâtre sont le destin de deux expériences différentes au même moment."
  },
  AvgDialog_131221_Content_39 = {
    Text = "La plupart de ma force doit rester dans le théâtre, continuant à tisser la grande toile du destin. En dehors de cela, nous n'avons aucune différence. Il n'est pas nécessaire de gâcher l'humeur de ce moment à cause de doutes, Gardien."
  },
  AvgDialog_131221_Content_4 = {
    Text = "Le son tira sur la blessure, William se couvrit le ventre enveloppé de bandages et ne put s'empêcher de tousser."
  },
  AvgDialog_131221_Content_40 = {
    Text = "Arachne sourit calmement, les glaçons tintant doucement dans le verre à vin qui tremble."
  },
  AvgDialog_131221_Content_41 = {
    Text = "Savez-vous que cette taverne organise chaque mois un bal masqué, et que chaque client qui entre doit porter son masque le plus amusant ."
  },
  AvgDialog_131221_Content_42 = {
    Text = "Les interactions de la haute société rendent souvent cet endroit ennuyeux, mais ce jour-là, il deviendra le lieu le plus incontournable de cette ville."
  },
  AvgDialog_131221_Content_43 = {
    Text = "Peut-être que lors du prochain bal masqué, je devrais aussi tout lâcher et ressentir sérieusement une fois."
  },
  AvgDialog_131221_Content_44 = {
    Text = "Je pensais qu'une personne capable de voir le développement du destin n'aurait plus aucun intérêt pour l'avenir."
  },
  AvgDialog_131221_Content_45 = {
    Text = "C'est vrai, %player%. Cependant, j'ai découvert un moyen de chasser l'ennui il y a bien longtemps."
  },
  AvgDialog_131221_Content_46 = {
    Text = "Parfois, je viens de l'arrière-scène à l'avant-scène, je pénètre sur la scène que j'ai créée, et je deviens moi-même l'un des personnages."
  },
  AvgDialog_131221_Content_47 = {
    Text = "Masque ton regard sur le destin, place-toi entièrement sur scène, pour percevoir avec précision le flux du temps, le basculement du destin..."
  },
  AvgDialog_131221_Content_48 = {
    Text = "C'est une pause précieuse. De telles occasions ne sont pas fréquentes, chaque fois, je les considère comme une fête inestimable."
  },
  AvgDialog_131221_Content_49 = {
    Text = "Arachne parlait tout en regardant avec intérêt les invités flamboyants et les doux serveurs, la lumière ambigüe de la taverne dansait dans ses yeux."
  },
  AvgDialog_131221_Content_5 = {
    Text = "William, l'Aîné ?! Tu es blessé"
  },
  AvgDialog_131221_Content_50 = {
    Text = "Même comme ça... Nous ne sommes pas censés chercher ces « artefacts secrets » ? Pourquoi sommes-nous ici ?"
  },
  AvgDialog_131221_Content_51 = {
    Text = "Une personne est ici. Vous l'avez bientôt... ah non, vous l'avez déjà rencontrée."
  },
  AvgDialog_131221_Content_52 = {
    Text = "Bonjour, chers clients."
  },
  AvgDialog_131221_Content_53 = {
    Text = "Le son du miel mariné. Des doigts sculptés en porcelaine. Sur le cou nu, un parfum éclatant de jasmin et de fleur de mimosa. Et ces yeux, scintillants comme des néons, capables de voir à travers tout."
  },
  AvgDialog_131221_Content_54 = {
    Text = "Ah, je me souviens de vous, l'élégant %player%."
  },
  AvgDialog_131221_Content_55 = {
    Text = "Les monstres dans l'ombre, une lumière argentée éblouissante... Quelle histoire de héros fascinante"
  },
  AvgDialog_131221_Content_56 = {
    Text = "Pour être honnête, pendant ton absence, le bar des masques de minuit a gagné pas mal d'argent grâce à ton histoire, nous devrions te payer des droits d'auteur — au moins, permettez-nous de t'offrir un verre."
  },
  AvgDialog_131221_Content_57 = {
    Text = "C'était toi... Je vais m'abstenir de boire pour l'instant, pourrais-tu d'abord servir un verre à cette personne ici, s'il te plaît ?"
  },
  AvgDialog_131221_Content_58 = {
    Text = "J'ai déjà pensé au nom, ça s'appellera Mise en scène et jeu soi-même."
  },
  AvgDialog_131221_Content_59 = {
    Text = "C'est un bon nom. Quant à savoir s'il convient à votre ami, je dois encore y réfléchir..."
  },
  AvgDialog_131221_Content_6 = {
    Text = "Sous l'emprise d'Arachne, tu franchis le mur peu remarquable à côté du café Hewatz."
  },
  AvgDialog_131221_Content_60 = {
    Text = "Cette personne nommée «romantique» est venue au bar, regardant sérieusement les yeux d'Arachne."
  },
  AvgDialog_131221_Content_61 = {
    Text = "Le créateur discret est immergé dans la scène qu'il a créée. Arachne sourit en croisant son regard."
  },
  AvgDialog_131221_Content_62 = {
    Text = "Ah, quelle profondeur dans cette paire d'yeux, mademoiselle."
  },
  AvgDialog_131221_Content_63 = {
    Text = "Un océan si profond et si vaste, dont le fond, invisible à tous, renferme des secrets inconnus."
  },
  AvgDialog_131221_Content_64 = {
    Text = "Ces vagues déferlantes sont toutes accueillies par cet océan, peu importe l'intensité des secousses, il maintient toujours une paix éternelle."
  },
  AvgDialog_131221_Content_65 = {
    Text = "Le temps s'écoule, l'océan des étoiles se déplace. Les montagnes deviennent des champs, les océans se transforment en prairies..."
  },
  AvgDialog_131221_Content_66 = {
    Text = "Mais sous ces changements, que cette mer a-t-elle abandonné..."
  },
  AvgDialog_131221_Content_67 = {
    Text = "Le barman s'est assis en face d'Arachne, lui soulevant le menton. Ses longs ongles reposaient naturellement sur l'artère carotidienne d'Arachne."
  },
  AvgDialog_131221_Content_68 = {Text = "C'est"},
  AvgDialog_131221_Content_69 = {
    Text = "Dieu du Destin, grande Arachne. La manière dont tu manipules le destin est tellement élégante. Je suis vraiment jaloux, jaloux de ceux que tu choisis, de ceux que tu laisses derrière."
  },
  AvgDialog_131221_Content_7 = {
    Text = "Lorsque tu es revenu sur la scène du théâtre, tu as immédiatement aperçu William assis seul dans le public."
  },
  AvgDialog_131221_Content_70 = {
    Text = "Malheureusement... nous sommes nés pour être la partie abandonnée."
  },
  AvgDialog_131221_Content_71 = {
    Text = "...Il semble que je ne goûterai pas cette boisson aujourd'hui, finalement."
  },
  AvgDialog_131221_Content_72 = {
    Text = "Arachne n'a pas essayé de se libérer de cette main dangereuse. Elle soupira doucement, semblant regretter ces souvenirs lointains, comme si elle regrettait ce verre de mélange qu'elle ne pouvait pas boire."
  },
  AvgDialog_131221_Content_73 = {
    Text = "Tu peux polluer les fils du destin de ces paires secrètes, m'empêchant de voir clairement, mais cela n'a aucun sens. Tu n'as pas le pouvoir de contrôler le destin, Nefraea."
  },
  AvgDialog_131221_Content_74 = {
    Text = "Telle une poupée faite de crème noire fondante, la peau de la barmaid se détache de son corps en un amas boueux."
  },
  AvgDialog_131221_Content_75 = {
    Text = "Sous cette boue, un visage familier apparaît devant toi."
  },
  AvgDialog_131221_Content_76 = {
    Text = "C'est toi ?"
  },
  AvgDialog_131221_Content_77 = {
    Text = "Ma chère sœur. Les cendres de la dimension, il ne t'en reste presque plus."
  },
  AvgDialog_131221_Content_78 = {
    Text = "J'aimerais vraiment discuter avec toi à nouveau, mais pour l'instant, laissons mes petites araignées te souhaiter la bienvenue."
  },
  AvgDialog_131221_Content_79 = {
    Text = "Attention derrière toi"
  },
  AvgDialog_131221_Content_8 = {
    Text = "Petite blessure."
  },
  AvgDialog_131221_Content_9 = {
    Text = "J'ai vu le destin qui se déroule sur cette scène. Je pense qu'il devrait y avoir quelqu'un pour vous remercier de vos efforts, Madame Arachne."
  },
  AvgDialog_131222_Content_1 = {
    Text = "Invitation du manoir"
  },
  AvgDialog_131222_Content_10 = {
    Text = "Invitation ? Je n'ai jamais montré d'invitation de ma vie jusqu'à présent."
  },
  AvgDialog_131222_Content_100 = {
    Text = "Sorel plisse légèrement les yeux, une rare colère s'allumant dans ses yeux élégants."
  },
  AvgDialog_131222_Content_101 = {
    Text = "Je ne sais pas ce que tu as fait à Karen, mais peu importe. Quoi qu'il en soit, le prix que tu devras payer est déjà déterminé."
  },
  AvgDialog_131222_Content_102 = {
    Text = "Ah, une réunion d'affaires ratée... Je suis désolé, Madame Sorel. Il semble que je n'aie d'autre choix que de laisser votre corps me le dire."
  },
  AvgDialog_131222_Content_103 = {
    Text = "Sorel fronça les sourcils, percevant les puissantes fluctuations de la force spirituelle de l'autre. Une ombre noire s'approcha rapidement, bloquant chacun de ses chemins d'évasion."
  },
  AvgDialog_131222_Content_105 = {
    Text = "Lorsque la lame dans l'ombre s'est soudainement dirigée vers Sorel, une intense lumière argentée a jailli dans la pièce comme une météore."
  },
  AvgDialog_131222_Content_106 = {
    Text = "Sorel, recule"
  },
  AvgDialog_131222_Content_11 = {
    Text = "Écartez-vous."
  },
  AvgDialog_131222_Content_12 = {
    Text = "Désolé, monsieur. Pour le banquet d'aujourd'hui, une invitation est nécessaire pour y participer."
  },
  AvgDialog_131222_Content_13 = {
    Text = "Espèce de gars sans discernement, sais-tu qui je suis ?"
  },
  AvgDialog_131222_Content_14 = {
    Text = "Ce n'est pas ma responsabilité, Monsieur."
  },
  AvgDialog_131222_Content_15 = {
    Text = "En entendant votre accent, je pense que vous êtes une personne du cru, vous devriez pouvoir comprendre ce que je dis."
  },
  AvgDialog_131222_Content_16 = {
    Text = "Toi !! D'accord, je vais te faire payer, ainsi qu'au maître de ce manoir"
  },
  AvgDialog_131222_Content_17 = {
    Text = "Arachne regarda le dos en colère de la noblesse et secoua la tête."
  },
  AvgDialog_131222_Content_18 = {
    Text = "Il semble que pénétrer dans ce manoir n'est pas aussi facile qu'on pourrait le penser."
  },
  AvgDialog_131222_Content_19 = {
    Text = "Si nous pouvons trouver cette servante qui vend de l'eau de bain, nous pourrions peut-être acheter deux invitations..."
  },
  AvgDialog_131222_Content_2 = {
    Text = "Domaine du duc Cadlin, le lieu de socialisation le plus célèbre de l'ancien Londinium."
  },
  AvgDialog_131222_Content_20 = {
    Text = "Des sels de bain de mer rares provenant de l'île de Sira, des lavandes, des agrumes, des clous de girofle, ainsi que des pétales de rose envoyés depuis le sud de Constan..."
  },
  AvgDialog_131222_Content_21 = {
    Text = "L'eau de bain est plus précieuse et plus rare que l'invitation."
  },
  AvgDialog_131222_Content_22 = {Text = "???"},
  AvgDialog_131222_Content_23 = {
    Text = "Je comptais simplement parler à moi-même... Comment sais-tu même ce qui s'est passé dans mon rêve ?"
  },
  AvgDialog_131222_Content_24 = {
    Text = "Bien que je ne puisse pas voir votre destin, je garde un œil sur le destin des personnes qui vous entourent."
  },
  AvgDialog_131222_Content_25 = {
    Text = "Puisque le destin de ces personnes peut être contrôlé par toi, même si la modification est complexe, obtenir deux invitations, c'est sûrement à ta portée, non ?"
  },
  AvgDialog_131222_Content_26 = {
    Text = "Les réactions en chaîne provoquées par la modification du destin, vous les avez déjà témoins. Le destin n'est pas un jouet que je manipule à ma guise, mais une maison en verre que je dois entretenir avec soin."
  },
  AvgDialog_131222_Content_27 = {
    Text = "Je dois faire chaque choix avec prudence, en dépensant beaucoup d'énergie et de cendres dimensionnelles. Toute imprudence et erreur entraîneront l'effondrement et la destruction."
  },
  AvgDialog_131222_Content_28 = {
    Text = "D'autant plus que... Comme je l'ai dit précédemment, être un spectateur est souvent beaucoup plus intéressant que d'être un dramaturge."
  },
  AvgDialog_131222_Content_29 = {
    Text = "J'ai hâte de voir votre performance, %player%."
  },
  AvgDialog_131222_Content_3 = {
    Text = "La première moitié de la vie du duc, le premier ministre et les hauts fonctionnaires du cabinet ont écrit sur la table basse de la pelouse des lettres décisives pour le destin de l'empire."
  },
  AvgDialog_131222_Content_30 = {
    Text = "Mais je ne comprends rien ici......"
  },
  AvgDialog_131222_Content_31 = {
    Text = "Performance, tromperie, plaisir... tu possèdes une telle force en toi. La scène du destin ne prépare pas d'opportunités pour tout le monde. Quand tu devras monter sur scène, ces forces t'aideront."
  },
  AvgDialog_131222_Content_32 = {
    Text = "Vous ne pouvez pas fuir les rôles que vous étiez destiné à jouer. Réfléchissez, puis jouez, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131222_Content_33 = {
    Text = "Derrière le sourire poli d'Arachne se cache une gravité difficile à ignorer. Elle semble te raconter quelque chose, et ce regard semble te traverser, dialoguant avec un avenir lointain."
  },
  AvgDialog_131222_Content_34 = {
    Text = "C'est un ordre que le destin ne peut refuser. Tu baisses la tête, réfléchissant aux paroles d'Arachne."
  },
  AvgDialog_131222_Content_35 = {
    Text = "Jouer, se moquer, divertir... Tu parles du pouvoir de N ?"
  },
  AvgDialog_131222_Content_36 = {
    Text = "Mais après cette bataille décisive contre Touva Wave, j'ai perdu le lien avec la puissance des trois plasmides..."
  },
  AvgDialog_131222_Content_37 = {
    Text = "Leur force est encore endormie, mais le pouvoir n'est pas seulement une force."
  },
  AvgDialog_131222_Content_38 = {
    Text = "Pouvoir, pas seulement force..."
  },
  AvgDialog_131222_Content_39 = {
    Text = "Alors que tu essaies de réfléchir à cette phrase, une lueur spirituelle apparaît dans ton monde spirituel."
  },
  AvgDialog_131222_Content_4 = {
    Text = "La seconde moitié de la vie du duc, son dos voûté était escorté par le manoir vendu vers le lieu d'exécution."
  },
  AvgDialog_131222_Content_40 = {
    Text = "Tu ramasses deux feuilles d'érable tombées par terre et caresses leurs motifs semblables à des lettres."
  },
  AvgDialog_131222_Content_41 = {
    Text = "Je me souviens que tu as dit auparavant que tout le monde dans ce monde possède un Cœur d'argent. Cela signifie donc que le Monde spirituel de chacun peut être influencé par la Clé d'argent... n'est-ce pas ?"
  },
  AvgDialog_131222_Content_42 = {
    Text = "Arachne te sourit, se tenant à tes côtés, marchant vers la porte du manoir."
  },
  AvgDialog_131222_Content_43 = {
    Text = "Bonjour, veuillez montrer..."
  },
  AvgDialog_131222_Content_44 = {
    Text = "C'est un beau manoir. Nous sommes très honorés de recevoir l'invitation de Madame Sorel."
  },
  AvgDialog_131222_Content_45 = {
    Text = "En tendant deux feuilles d'érable au garde, ta clé en argent émet une faible lueur dans ton sein. Tu as facilement capté le point lumineux du garde."
  },
  AvgDialog_131222_Content_46 = {
    Text = "En même temps, un autre point lumineux s'allume dans ton monde spirituel. À l'intersection des deux points lumineux, l'illusion de Clémentine oscille le pendule qu'elle tient dans sa main."
  },
  AvgDialog_131222_Content_47 = {
    Text = "Chut... Comte Huey..."
  },
  AvgDialog_131222_Content_48 = {
    Text = "Ah, Comte Huey, Comtesse, le manoir de Cadrelin vous souhaite la bienvenue."
  },
  AvgDialog_131222_Content_49 = {
    Text = "Sous le regard respectueux du garde, vous avez emprunté le chemin de galets lisses du manoir."
  },
  AvgDialog_131222_Content_5 = {
    Text = "Après une brève période de silence, ce manoir s'est de nouveau rempli de précieux invités, son nouveau maître annonçant son retour par une série de salons."
  },
  AvgDialog_131222_Content_50 = {
    Text = "Qu'est-ce que ça fait, {Male=Mr.,Female=Miss} Gardien ?"
  },
  AvgDialog_131222_Content_51 = {
    Text = "Bien que je ne comprenne toujours pas le sens de ce que tu appelles pouvoir, j'ai effectivement ressenti quelque chose de différent tout à l'heure..."
  },
  AvgDialog_131222_Content_52 = {
    Text = "Cette sensation de plaisir qui naît après avoir été dupé, je ne l'ai jamais ressentie... C'est comme... une émotion qui ne m'appartient pas du tout..."
  },
  AvgDialog_131222_Content_53 = {
    Text = "Tu lèves la main, deux belles feuilles d'érable quittent le bout de tes doigts, tournoyant joyeusement dans le vent."
  },
  AvgDialog_131222_Content_54 = {
    Text = "Alors que tu entrais dans le manoir avec un sourire approprié envers Arachne, tu pouvais être sûr d'avoir entendu un rire de plaisir provenant des profondeurs de ton corps."
  },
  AvgDialog_131222_Content_55 = {Text = "新增"},
  AvgDialog_131222_Content_56 = {
    Text = "C'est vraiment remarquable de voir quelqu'un accomplir autant à un si jeune âge."
  },
  AvgDialog_131222_Content_57 = {
    Text = "Après la fin de cette négociation commerciale, les liens entre le monde des affaires et le monde politique de cette ville connaîtront une disruption sans précédent. C'est une occasion rare..."
  },
  AvgDialog_131222_Content_58 = {
    Text = "C'était difficile pour le rédacteur en chef d'obtenir l'invitation, cette fois nous devons absolument capturer quelques moments mémorables. Tout à l'heure, tu vas nous suivre avec l'équipement, nous allons essayer d'avancer un peu, plus près..."
  },
  AvgDialog_131222_Content_59 = {
    Text = "Sors ! Sors"
  },
  AvgDialog_131222_Content_6 = {
    Text = "Bonjour, voici mon invitation."
  },
  AvgDialog_131222_Content_60 = {
    Text = "Avec le cri des jeunes, tout le monde se précipita vers la grande porte ouverte."
  },
  AvgDialog_131222_Content_61 = {
    Text = "La robe longue rouge, telle une rose ardente, rend toutes les décorations et la foule dans la pièce ternes."
  },
  AvgDialog_131222_Content_62 = {
    Text = "Sorel arbore un sourire impeccable et maîtrisé, saluant les invités avec une aisance naturelle."
  },
  AvgDialog_131222_Content_63 = {
    Text = "Alors, c'est elle l'actuelle propriétaire du manoir..."
  },
  AvgDialog_131222_Content_64 = {
    Text = "Mesdames et messieurs, bienvenue. Lors du salon d'aujourd'hui, plusieurs quartiers commerciaux de notre ville trouveront leurs nouveaux maîtres."
  },
  AvgDialog_131222_Content_65 = {
    Text = "Et, bien entendu, nos nobles amis recevront les avantages qu'ils méritent si justement."
  },
  AvgDialog_131222_Content_66 = {
    Text = "J'ai confiance que cette soirée sera des plus splendides et délicieuses."
  },
  AvgDialog_131222_Content_67 = {
    Text = "Le chef du manoir a préparé des pâtisseries et du champagne de premier choix pour tout le monde, veuillez prendre un moment de repos. Bientôt, notre dîner commencera officiellement."
  },
  AvgDialog_131222_Content_68 = {
    Text = "Le regard de Sorel sourit en balayant la salle, puis elle se retourna et monta à l'étage."
  },
  AvgDialog_131222_Content_69 = {
    Text = "Sorel... Sorel !... Karen"
  },
  AvgDialog_131222_Content_7 = {
    Text = "......Ah, bienvenue, Monsieur Fugen. Le maître vous attend à l'intérieur, entrez s'il vous plaît."
  },
  AvgDialog_131222_Content_70 = {
    Text = "Ton cri est noyé dans les discussions et les cris de la foule."
  },
  AvgDialog_131222_Content_71 = {
    Text = "Madame Sorel ! Madame Sorel ! Comment avez-vous prévu la délimitation de la zone commerciale ? Cela va-t-il toucher à..."
  },
  AvgDialog_131222_Content_72 = {
    Text = "Chut, monsieur le journaliste. Je viens de revenir après avoir réglé des affaires dehors, je répondrai à toutes les questions que vous voulez savoir après m'être changé."
  },
  AvgDialog_131222_Content_73 = {
    Text = "Sorel fit un signe de la main aux journalistes et entra dans la zone des chambres à l'étage du manoir."
  },
  AvgDialog_131222_Content_74 = {
    Text = "On dirait qu'on doit attendre qu'elle sorte pour lui poser des questions."
  },
  AvgDialog_131222_Content_75 = {
    Text = "As-tu remarqué la servante qui se trouve à côté de Sorel ?"
  },
  AvgDialog_131222_Content_76 = {
    Text = "Karen ? Bien sûr, elle n'a probablement pas entendu non plus... Attends, tu veux dire que..."
  },
  AvgDialog_131222_Content_77 = {
    Text = "Tu te souviens de l'odeur de Karen. Cette odeur est complètement différente de celle que tu connais, même dans des dimensions différentes, elles ne peuvent pas appartenir à la même personne."
  },
  AvgDialog_131222_Content_78 = {
    Text = "J'ai ressenti sur elle une trajectoire de destin qui ne lui appartient pas sur cette scène... Son destin a été pollué."
  },
  AvgDialog_131222_Content_79 = {
    Text = "Madame Sorel est en danger"
  },
  AvgDialog_131222_Content_8 = {
    Text = "Hum, même un marchand aussi puant que Fugen peut entrer dans le manoir du vieux duc, le raffinement de Londinium a complètement disparu..."
  },
  AvgDialog_131222_Content_80 = {
    Text = "Tu te frayes un chemin à travers la foule et trouves un escalier caché à l'arrière du bâtiment."
  },
  AvgDialog_131222_Content_81 = {
    Text = "Mes excuses, {Male=sir,Female=lady}, mais ici c'est la résidence privée de Madame Sorel. Aucune personne non autorisée —"
  },
  AvgDialog_131222_Content_82 = {
    Text = "Madame Sorel m'invite à venir discuter de choses importantes avec elle."
  },
  AvgDialog_131222_Content_83 = {
    Text = "Tu sors une serviette arrachée au hasard. Un éclat argenté, une carte de police de l'audience de révision est posée devant le garde."
  },
  AvgDialog_131222_Content_84 = {
    Text = "Désolé, je ne vous ai pas reconnu... Madame Sorel est dessus, je peux vous..."
  },
  AvgDialog_131222_Content_85 = {
    Text = "Mission confidentielle, ne laisse pas les autres savoir ce que je fais."
  },
  AvgDialog_131222_Content_86 = {
    Text = "Avant que l'agent ne puisse parler, tu as rapidement couru dans les escaliers."
  },
  AvgDialog_131222_Content_87 = {Text = "新增"},
  AvgDialog_131222_Content_88 = {
    Text = "Vos vêtements sont prêts, Madame Sorel"
  },
  AvgDialog_131222_Content_89 = {
    Text = "Londinium est une terre sauvage et originale, où les politiciens et les marchands sont les hyènes de cette ville..."
  },
  AvgDialog_131222_Content_9 = {
    Text = "Bonjour, veuillez présenter votre invitation."
  },
  AvgDialog_131222_Content_90 = {
    Text = "Sorel prend la tenue que Karen a préparée. La lumière du soleil filtre à travers la gaze rouge, projetant une ombre cramoisie éclatante à travers la somptueuse chambre."
  },
  AvgDialog_131222_Content_91 = {
    Text = "Les hyènes ont aussi leur côté adorable. Un morceau de chair en décomposition peut les rendre folles. Gourmandes, aiguisées, cruelles, puériles. Il n'y a pas d'arme plus efficace qu'elles."
  },
  AvgDialog_131222_Content_92 = {
    Text = "Ils s'impatientent dehors. Vous êtes apparue bien trop tard aujourd'hui, et cette robe hors de prix a été tachée."
  },
  AvgDialog_131222_Content_93 = {
    Text = "Vous auriez dû revenir plus tôt, madame."
  },
  AvgDialog_131222_Content_94 = {
    Text = "L'action de Sorel s'arrêta un instant. Elle abaissa lentement sa jupe teintée de sang et regarda le visage calme de Karen."
  },
  AvgDialog_131222_Content_95 = {
    Text = "Il devrait y avoir quelqu'un pour t'apprendre comment un serviteur doit parler à son maître. Qu'est-ce qui t'arrive aujourd'hui ?"
  },
  AvgDialog_131222_Content_96 = {
    Text = "Madame Sorel, vous avez des taches venant du District de l'Est sur vous. Je me demande où vous avez envoyé cette bonne personne ?"
  },
  AvgDialog_131222_Content_97 = {
    Text = "La pièce lumineuse s'assombrit un instant. Plusieurs araignées noires se transformèrent en formes humaines depuis l'ombre, entourant Sorel au centre."
  },
  AvgDialog_131222_Content_98 = {
    Text = "Vous avez une très fidèle servante, Madame Sorel. Bien qu'elle soit passionnée par le vol et la vente de vos biens, sa loyauté en ce qui concerne la protection de votre sécurité est indiscutable."
  },
  AvgDialog_131222_Content_99 = {
    Text = "Même maintenant, sa volonté lutte férocement contre moi. C'est dommage, vraiment — aucun mortel ne peut résister au pouvoir du Destin."
  },
  AvgDialog_131223_Content_1 = {
    Text = "Destin. Destin sauvage, creux, pitoyable. Les Destins abandonnés ne savent ni d›où ils viennent, ni où ils vont."
  },
  AvgDialog_131223_Content_10 = {
    Text = "La voix de Nefraea devint soudain aigüe. Une lueur sombre s'illumina, des fils écarlates l'enchaînèrent fermement, et les flammes résiduelles de la lanterne brûlaient son corps."
  },
  AvgDialog_131223_Content_11 = {
    Text = "De grandes pinces se déplacent dans les airs, une paire d'yeux composés géants, dégoulinant de mucus noir, vous regardent avec un sourire. Des fils écarlates s'enroulent autour de son corps, flottant dans le vortex du destin."
  },
  AvgDialog_131223_Content_12 = {
    Text = "À ses côtés, ce rouet brisé qui rassemblait des fils tournait lentement et inéluctablement, étranglant toutes les danses, étranglant Nefraea elle-même."
  },
  AvgDialog_131223_Content_13 = {Text = "Hmm—"},
  AvgDialog_131223_Content_14 = {
    Text = "Tu te tiens la tête avec douleur. Sous le mouvement du rouet, ton monde spirituel commence à s'agiter. Tu respires profondément, apaisant la douleur intense."
  },
  AvgDialog_131223_Content_15 = {
    Text = "À côté de Nefraea, il ne reste presque plus de fragments des passages dimensionnels. Les fils sur vous, ces motifs de marionnettes, deviennent de plus en plus clairs."
  },
  AvgDialog_131223_Content_16 = {
    Text = "La force du canal dimensionnel... Elle est sur le point d'absorber complètement"
  },
  AvgDialog_131223_Content_17 = {
    Text = "Des cendres d'un violet pâle s'échappent en continu du corps d'Arachne, se précipitant comme des papillons vers la Toile du destin presque complètement brisée."
  },
  AvgDialog_131223_Content_18 = {
    Text = "Arachne tremblait des mains à un rythme immuable, faisant tourner le rouet qu'elle tenait. Sa voix était toujours aussi calme que lorsque vous l'avez rencontrée pour la première fois."
  },
  AvgDialog_131223_Content_19 = {
    Text = "Tu as déjà vu. C'est le point de croisement du destin, Nefraea."
  },
  AvgDialog_131223_Content_2 = {
    Text = "Ils sont attirés par des fils de soie, déferlant vers vous, pour se dissoudre en flaques de boue noire dans votre éclat argenté."
  },
  AvgDialog_131223_Content_20 = {
    Text = "Toutes les erreurs prendront fin ici."
  },
  AvgDialog_131223_Content_21 = {
    Text = "Quelle déclaration pleine de confiance, Madame la prisonnière. Laissez-moi donc voir sur quoi vous comptez vous appuyer pour stopper un dieu, pour arrêter le destin lui-même..."
  },
  AvgDialog_131223_Content_22 = {
    Text = "Le sourire fou s'épanouit sur le visage de Nefraea. Les fils qui la lient la soulèvent, sur la scène brisée, elle est la seule lumière."
  },
  AvgDialog_131223_Content_23 = {
    Text = "« Venez, fidèles rampants du monde ! Baissez la tête et prosternez–vous devant moi ! »"
  },
  AvgDialog_131223_Content_24 = {
    Text = "« L›Exalté est descendu du trône céleste ! La Fin Inéluctable se révèle ici et maintenant ! »"
  },
  AvgDialog_131223_Content_25 = {
    Text = "« Ce faux destin — accueillons sa destruction, ensemble ! »"
  },
  AvgDialog_131223_Content_3 = {
    Text = "Boue sauvage, vide, pathétique, comme leur destin lui-même."
  },
  AvgDialog_131223_Content_4 = {
    Text = "Nefraea n'a pas prêté attention à tout cela, la scène devant elle s'est jouée pendant de nombreuses années, elle y est déjà habituée."
  },
  AvgDialog_131223_Content_5 = {
    Text = "J'ai vu clair. Les images que tu as vues, tout ce que tu as vu, j'ai enfin vu clair..."
  },
  AvgDialog_131223_Content_6 = {
    Text = "La douleur causée par les fragments était déjà engourdie, elle souriait en regardant les vides chaotiques dans le théâtre."
  },
  AvgDialog_131223_Content_7 = {
    Text = "Un sourire hautain, compatissant et indifférent, il y a un instant où vous ne pouviez presque pas distinguer elle et Arachne."
  },
  AvgDialog_131223_Content_8 = {
    Text = "Seulement ceux qui se trouvent dans une cage peuvent vraiment ouvrir la cage. Le chaos et la destruction que vous voyez ne sont pas le destin réel, Nefraea..."
  },
  AvgDialog_131223_Content_9 = {
    Text = "Héhéhéhé ! ... C'est comme ça que tu t'es trompée pendant toutes ces années, Arachne ?"
  },
  AvgDialog_131224_Content_1 = {
    Text = "Spectateur, acteur, auteur"
  },
  AvgDialog_131224_Content_10 = {Text = "C'est... !"},
  AvgDialog_131224_Content_100 = {
    Text = "Allez, mes enfants. Trouvez %player%."
  },
  AvgDialog_131224_Content_101 = {
    Text = "Emparez-vous du pouvoir de {Male=his,Female=her}, tranchez chaque fil du Destin, et réduisez la Grande Toile en lambeaux ! Que chaque âme qui se dresse sur notre chemin y périsse !"
  },
  AvgDialog_131224_Content_102 = {
    Text = "Nous utiliserons le sang de ce fragment pour réveiller à nouveau le grand Primordial."
  },
  AvgDialog_131224_Content_103 = {
    Text = "Quand tu verras ta précieuse Toile du destin brisée et réduite à un bourbier immonde, sombreras-tu dans le vide sans fin, tout comme nous ?"
  },
  AvgDialog_131224_Content_104 = {
    Text = "Déesse du Destin, ma chère sœur, ma chère <Red:Arachne> ?"
  },
  AvgDialog_131224_Content_105 = {
    Text = "La frontière entre la scène et le public semble s›évanouir ; l›espace lui-même perd tout sens."
  },
  AvgDialog_131224_Content_106 = {
    Text = "Dans un rire perçant, la poupée semble se tenir devant vous, fixant droit dans les yeux d'Arachne."
  },
  AvgDialog_131224_Content_107 = {
    Text = "La lumière s'éteint, le rideau tombe. La marionnette et son rire disparaissent, dans le théâtre vide, il ne reste que le doux bruit du rouet qui tourne."
  },
  AvgDialog_131224_Content_108 = {
    Text = "Désolé, je n'ai pas tout à fait compris... Que signifie le destin abandonné ?"
  },
  AvgDialog_131224_Content_109 = {
    Text = "Comme vous pouvez le voir, le destin est un enchevêtrement de fils chaotiques. Si personne ne les tisse, cet univers sombrera dans un chaos sans fin. Je pense que c'est une vision que nous ne voulons pas voir."
  },
  AvgDialog_131224_Content_11 = {
    Text = "Au moment où tu franchis la porte, celle-ci disparaît derrière toi."
  },
  AvgDialog_131224_Content_110 = {
    Text = "Bien sûr..."
  },
  AvgDialog_131224_Content_111 = {
    Text = "Tisser les fils pour former le filet du destin, maintenir le bon fonctionnement de cet univers est mon devoir éternel."
  },
  AvgDialog_131224_Content_112 = {
    Text = "À chaque instant, le Destin recèle des possibilités infinies. À chaque instant, je suis contrainte de faire un choix."
  },
  AvgDialog_131224_Content_113 = {
    Text = "Les destins justes sont tissés dans la Grande Toile ; les erronés sont rejetés. C›est ainsi que la toile fonctionne. C›est inévitable."
  },
  AvgDialog_131224_Content_114 = {
    Text = "Ma sœur, qui est aussi une partie de ces destins erronés que j'ai abandonnés."
  },
  AvgDialog_131224_Content_115 = {
    Text = "Arachne sourit, dans son récit calme, tu ne perçois aucune fluctuation émotionnelle."
  },
  AvgDialog_131224_Content_116 = {
    Text = "Ces destins abandonnés... seront-ils envoyés dans le « Gouffre » ?"
  },
  AvgDialog_131224_Content_117 = {
    Text = "Le rêve de cette divinité suprême a constitué cet univers, cet endroit nommé « abîme » est le subconscient des dieux, le lieu de rassemblement de toutes les choses non réalisées, de tous les destins inexistants."
  },
  AvgDialog_131224_Content_118 = {
    Text = "Elles auraient dû se dissiper complètement dans ce vide, mais sous la conduite de ma sœur, elles ont réussi à survivre d'une manière ou d'une autre."
  },
  AvgDialog_131224_Content_119 = {
    Text = "Arachne regardait le grand rideau, regardant derrière le rideau, la marionnette représentant Nefraea."
  },
  AvgDialog_131224_Content_12 = {
    Text = "À l'intérieur de la petite boutique que tu imaginais, se trouve un vaste espace dimensionnel infini."
  },
  AvgDialog_131224_Content_120 = {
    Text = "Elle n'a pas le pouvoir de contrôler le destin, mais comme moi, elle peut voir les fils du destin, les obscurcir, les polluer, détruire la trajectoire que j'ai tissée pour eux, les mener vers la mort..."
  },
  AvgDialog_131224_Content_121 = {
    Text = "Donc, elle veut me trouver, utiliser ma force pour réveiller à nouveau Touva Wave ?"
  },
  AvgDialog_131224_Content_122 = {
    Text = "Je ne sais pas quels sont ses plans précis, mais il semble que ce soit le cas. Quoi qu'il en soit, elle est une erreur que je dois corriger."
  },
  AvgDialog_131224_Content_123 = {
    Text = "Elle a fermé le passage entre les dimensions, c'était aussi pour cela, n'est-ce pas..."
  },
  AvgDialog_131224_Content_124 = {
    Text = "Le passage dimensionnel que j'ai fermé. Elle attendait, attendant ce moment où elle irait avec toi à Kadath."
  },
  AvgDialog_131224_Content_125 = {
    Text = "Kadath est une dimension que ma force n'a jamais touchée, et c'est l'endroit où la connexion avec cet Être suprême est la plus étroite."
  },
  AvgDialog_131224_Content_126 = {
    Text = "Si elle te suivait, le destin du cataclysme deviendrait complètement irréversible."
  },
  AvgDialog_131224_Content_127 = {
    Text = "Pardonnez-moi d›avoir pris de telles libertés, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131224_Content_128 = {
    Text = "Je comprends, Arachne. Si ce que tu dis est vrai, ce n'est pas non plus la vision que je veux voir."
  },
  AvgDialog_131224_Content_129 = {
    Text = "Donc, si je veux retourner à Kadath, je dois d'abord me débarrasser d'elle..."
  },
  AvgDialog_131224_Content_13 = {
    Text = "D›innombrables scènes flottent comme des étoiles dans cette étendue obscure, des marionnettes sur chacune d›elles récitant leurs répliques."
  },
  AvgDialog_131224_Content_130 = {
    Text = "Maître, il y a une anomalie sur la scène de la zone GI-9849. C'est le troisième cas aujourd'hui."
  },
  AvgDialog_131224_Content_131 = {
    Text = "Après avoir volé les matériaux du Tisseur de destin, elle ne se lasse jamais de détruire le destin."
  },
  AvgDialog_131224_Content_132 = {
    Text = "Mes excuses, %player%, mais je dois m›occuper de ces perturbations. Veuillez me suivre, s›il vous plaît. Il y a des choses essentielles que vous devez voir."
  },
  AvgDialog_131224_Content_133 = {
    Text = "Arachne a souri en secouant la tête. Elle vous a fait un geste d'invitation, se levant avec le rouet."
  },
  AvgDialog_131224_Content_134 = {Text = "新增"},
  AvgDialog_131224_Content_135 = {
    Text = "Ici... c'est la scène détruite ?..."
  },
  AvgDialog_131224_Content_136 = {
    Text = "Suivant le chemin tissé par les toiles d'araignée, vous arrivez à une scène délabrée. Dans le café rudimentaire sur scène, quelques personnes ayant l'apparence d'étudiants discutent à voix basse."
  },
  AvgDialog_131224_Content_137 = {
    Text = "Pendant cette période, elle a constamment envoyé ses serviteurs détruire le destin de ces mondes. Mes servantes sont en train de les chercher partout, et leur combat a coûté la vie à de nombreux bons enfants."
  },
  AvgDialog_131224_Content_138 = {
    Text = "Le destin de tous les mondes est connecté sur un même grand filet, chaque effondrement d'un monde déchire l'ensemble du filet du destin, plongeant tout dans un désordre total et mortel."
  },
  AvgDialog_131224_Content_139 = {
    Text = "Nefraea a volé les matériaux pour tisser le destin, je ne peux pas utiliser ma force facilement. Gardien {Male=Monsieur,Female=Madame}, je pense que vous pourriez peut-être m'aider à réparer le destin de ce monde ?"
  },
  AvgDialog_131224_Content_14 = {
    Text = "Les mots vous parviennent de loin, comme le murmure d›innombrables dévots en prière."
  },
  AvgDialog_131224_Content_140 = {
    Text = "Si ce que tu dis est vrai, c'est aussi un problème que je dois résoudre."
  },
  AvgDialog_131224_Content_141 = {
    Text = "Arachne hocha la tête en s'excusant. Elle leva la main et toucha doucement l'air vide, ces fils cachés."
  },
  AvgDialog_131224_Content_142 = {Text = "Dong——"},
  AvgDialog_131224_Content_143 = {
    Text = "Après le son clair des instruments, la voix mélodieuse du présentateur s'élève, telle un courant éternel se déversant sans fin dans une profonde mare."
  },
  AvgDialog_131224_Content_144 = {
    Text = "La trompette joue une fleur. Un étudiant et un érudit, en haut——"
  },
  AvgDialog_131224_Content_145 = {
    Text = "Arachne fait un geste d'invitation."
  },
  AvgDialog_131224_Content_146 = {
    Text = "Il est temps pour nous d›entrer en scène, %player%."
  },
  AvgDialog_131224_Content_147 = {
    Text = "Tu hoches la tête. Dans le son mélodieux de l'annonce, deux marionnettes montent sur leur scène."
  },
  AvgDialog_131224_Content_15 = {
    Text = "Des fils d'araignée s'étendent des marionnettistes et de la scène, se rassemblant avec ce chemin tissé de fils d'araignée sous tes pieds vers la scène au centre de cet espace."
  },
  AvgDialog_131224_Content_16 = {
    Text = "Tu te retournes, la servante à côté de toi s'est déjà avancée."
  },
  AvgDialog_131224_Content_17 = {
    Text = "C'est vraiment une cérémonie d'accueil étrange..."
  },
  AvgDialog_131224_Content_18 = {
    Text = "Tu hésites et te diriges vers la scène centrale en suivant le chemin de toile d'araignée. Alors que tu passes devant les scènes suspendues, des fragments de conversation flottent jusqu'à tes oreilles."
  },
  AvgDialog_131224_Content_19 = {
    Text = "Cette personne, j'ai vu de la perplexité dans vos yeux."
  },
  AvgDialog_131224_Content_2 = {
    Text = "J'ai encore une question..."
  },
  AvgDialog_131224_Content_20 = {
    Text = "L'accident qui s'est produit tout à l'heure dans le magasin ne vous a pas effrayé, n'est-ce pas ?"
  },
  AvgDialog_131224_Content_21 = {
    Text = "Une structure à base de gin, avec des notes de hibiscus, doit correspondre à votre état d'esprit actuel."
  },
  AvgDialog_131224_Content_22 = {Text = "新增"},
  AvgDialog_131224_Content_23 = {
    Text = "Ah ! Un enfant sans foyer, si petit, si pauvre."
  },
  AvgDialog_131224_Content_24 = {
    Text = "Avec ces vêtements légers, comment comptes-tu passer cet hiver ?"
  },
  AvgDialog_131224_Content_25 = {
    Text = "Venez avec moi. Laissez-moi vous trouver un endroit pour vous abriter de la tempête..."
  },
  AvgDialog_131224_Content_26 = {Text = "新增"},
  AvgDialog_131224_Content_27 = {
    Text = "Ces... ces gens que j'ai rencontrés tout à l'heure ?"
  },
  AvgDialog_131224_Content_28 = {
    Text = "Comment peuvent-ils être sur ces scènes..."
  },
  AvgDialog_131224_Content_29 = {
    Text = "Policier en patrouille, employé lisant le journal, chauffeur admirant le paysage urbain, amoureux achetant des fleurs, nobles en conversation..."
  },
  AvgDialog_131224_Content_3 = {
    Text = "C›est déjà votre vingt-troisième question, %player%."
  },
  AvgDialog_131224_Content_30 = {
    Text = "Ceux que tu as rencontrés et ceux que tu n'as pas rencontrés jouent leurs propres histoires sur ces innombrables scènes. Sur leurs propres scènes, ils sont tous les protagonistes de leur propre récit."
  },
  AvgDialog_131224_Content_31 = {
    Text = "Ave, %player% ! Béni soit l›enfant d›Akute !"
  },
  AvgDialog_131224_Content_32 = {
    Text = "Ave, %player% ! Béni soit le Gardien de Mizag !"
  },
  AvgDialog_131224_Content_33 = {
    Text = "Ave, %player% ! Béni soit le dieu de la destruction !"
  },
  AvgDialog_131224_Content_34 = {
    Text = "Après que vous vous soyez approchés de la scène centrale, trois marionnettes de formes variées montent sur scène et s'inclinent en votre direction."
  },
  AvgDialog_131224_Content_35 = {
    Text = "La Dame vous attend à l›intérieur. Veuillez entrer — {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131224_Content_36 = {
    Text = "Lorsque la porte de la loge s'ouvre, il semble que l'image et le son de tout le théâtre se figent un instant."
  },
  AvgDialog_131224_Content_37 = {
    Text = "Vous franchissez la porte et soulevez le rideau——"
  },
  AvgDialog_131224_Content_38 = {
    Text = "Ils apparaissent sur ces scènes parce que le nom de ce théâtre est Destin."
  },
  AvgDialog_131224_Content_39 = {
    Text = "Une voix fraîche et posée vous parvient avant toute couleur."
  },
  AvgDialog_131224_Content_4 = {
    Text = "Comparé aux énigmes de cet endroit, mes questions sont encore loin d'être suffisantes."
  },
  AvgDialog_131224_Content_40 = {
    Text = "Dans une loge qui semble dépourvue de murs, les fils reliant chaque scène et chaque marionnette convergent vers un fuseau doucement lumineux. Une femme est assise au point où tous les fils se rejoignent, le tournant d›une main délicate."
  },
  AvgDialog_131224_Content_41 = {
    Text = "Vous percevez chaque détail d›elle avec une clarté parfaite. Pourtant, à chaque clignement d›yeux, toute impression s›efface de votre esprit, ne laissant rien derrière elle."
  },
  AvgDialog_131224_Content_42 = {
    Text = "Son image refuse de se fixer. Quand elle tourne la tête vers vous, votre cœur — tendu par la vigilance tout ce temps — se met à battre violemment."
  },
  AvgDialog_131224_Content_43 = {
    Text = "C›est vous ?!!"
  },
  AvgDialog_131224_Content_44 = {
    Text = "Sur Le Parades... et ces attaques... !"
  },
  AvgDialog_131224_Content_45 = {
    Text = "Au moment où tu es prêt à infuser ta puissance spirituelle dans la clé en argent, le maître du théâtre tend la main et fait un geste dans l'air. Son mouvement est doux et élégant, comme si elle effleurait délicatement une corde."
  },
  AvgDialog_131224_Content_46 = {Text = "!!!"},
  AvgDialog_131224_Content_47 = {
    Text = "La force mentale arrive au bout de tes doigts, mais elle recule comme un flot retenu par un barrage. Lorsque tu lèves la main en l'air, tu réalises soudain qu'à un moment donné, ta main est vide."
  },
  AvgDialog_131224_Content_48 = {
    Text = "Clé en argent...... la clé en argent est toujours dans ma main...... pourquoi......"
  },
  AvgDialog_131224_Content_49 = {
    Text = "La dame esquisse un faible sourire et adresse un petit signe de tête à sa servante."
  },
  AvgDialog_131224_Content_5 = {
    Text = "Je ne suis pas le répondant que vous cherchez. La personne capable de répondre à vos questions vous attend ici."
  },
  AvgDialog_131224_Content_50 = {
    Text = "Sous votre regard stupéfait, la servante s›avance et replace respectueusement la Clé d›argent dans votre main."
  },
  AvgDialog_131224_Content_51 = {
    Text = "Impossible... elle ne peut pas avoir volé la clé en argent !..."
  },
  AvgDialog_131224_Content_52 = {
    Text = "Avant d›entrer dans le théâtre, vous serriez cette clé fermement, maintenant un lien spirituel constant."
  },
  AvgDialog_131224_Content_53 = {
    Text = "Votre entraînement à Mizag vous a conféré un niveau de vigilance si élevé que personne ne pourrait jamais espérer vous l›arracher."
  },
  AvgDialog_131224_Content_54 = {
    Text = "Pourquoi..."
  },
  AvgDialog_131224_Content_55 = {
    Text = "Personne ne peut le laisser partir, mais le destin peut."
  },
  AvgDialog_131224_Content_56 = {
    Text = "Pardonnez-moi, %player%. Je comprends votre anxiété et je respecte votre pouvoir."
  },
  AvgDialog_131224_Content_57 = {
    Text = "Afin d›éviter tout dommage involontaire à mon théâtre, je n›ai eu d›autre choix que d›altérer brièvement le destin de la clé dans votre main. J›espère que vous pourrez pardonner cette liberté."
  },
  AvgDialog_131224_Content_58 = {
    Text = "Elle fait un geste de la main, et un rayon de lumière transperce l›espace entre vous. En regardant de plus près, vous apercevez un fil ténu, presque imperceptible, s›étendant depuis la Clé d›argent jusqu›au rouet à ses côtés."
  },
  AvgDialog_131224_Content_59 = {
    Text = "Ces fils sont... ?"
  },
  AvgDialog_131224_Content_6 = {
    Text = "Vous vous arrêtez devant une porte de théâtre d'une seule largeur. Pas de panneau, pas de clients, comme une toile d'araignée insignifiante dans les boutiques élégantes de Londinium."
  },
  AvgDialog_131224_Content_60 = {
    Text = "Il existe de nombreuses explications sur les fils, certaines étant trop complexes pour le moment. Vous pouvez simplement les comprendre comme... le destin."
  },
  AvgDialog_131224_Content_61 = {
    Text = "Le rouet tourne doucement de lui-même. Elle se lève et offre un gracieux signe de tête en guise de salut."
  },
  AvgDialog_131224_Content_62 = {
    Text = "Arachne, maîtresse du Théâtre du Destin. Enchanté de vous rencontrer, Gardien."
  },
  AvgDialog_131224_Content_63 = {
    Text = "Pas de souci, vous êtes en sécurité ici."
  },
  AvgDialog_131224_Content_64 = {
    Text = "En effet, si tu veux me tuer, j'avais probablement aucune chance de survivre tout à l'heure."
  },
  AvgDialog_131224_Content_65 = {
    Text = "Alors qu'Arachne tirait sur le fil, la lumière provenant des rouets s'éteignait dans la loge. Tu regardais d'un air complexe la clé d'argent que la servante avait rendue, fronçant les sourcils en la fixant."
  },
  AvgDialog_131224_Content_66 = {
    Text = "Sur Le Parades, vous m›avez aidé. Mais depuis que je suis dans cette ville, vous m›avez attaqué deux fois."
  },
  AvgDialog_131224_Content_67 = {
    Text = "Je comprends votre méfiance. Mais croyez-moi quand je vous dis que je n›ai jamais levé le petit doigt pour vous nuire."
  },
  AvgDialog_131224_Content_68 = {
    Text = "Tu as bloqué mon lien avec Kadath et m'as attaqué plusieurs fois... Tu veux dire que ce ne sont pas des choses que tu as faites ?"
  },
  AvgDialog_131224_Content_69 = {
    Text = "Cette personne qui vous dérange, bien qu'elle ait le même visage que moi, n'est pas moi."
  },
  AvgDialog_131224_Content_7 = {
    Text = "La servante pousse doucement la porte, sa silhouette s'enfonçant dans les ténèbres de l'intérieur. Une lumière provenant de nulle part scintille faiblement dans l'obscurité, comme une invitation cachée."
  },
  AvgDialog_131224_Content_70 = {
    Text = "Quant à votre lien avec Kadath... c›est un piège dangereux, %player%."
  },
  AvgDialog_131224_Content_71 = {
    Text = "Un piège ?"
  },
  AvgDialog_131224_Content_72 = {
    Text = "Un enfant né de ma propre existence vous a causé des tourments inutiles, et j›en suis sincèrement désolée. Cette situation a commencé avec moi, et je fais tout ce qui est en mon pouvoir pour réparer cette erreur."
  },
  AvgDialog_131224_Content_73 = {
    Text = "Je n'ai pas compris..."
  },
  AvgDialog_131224_Content_74 = {
    Text = "C'est une histoire quelque peu longue, liée au destin. Une histoire est toujours plus facile à comprendre qu'une simple déclaration."
  },
  AvgDialog_131224_Content_75 = {
    Text = "Veuillez prendre place, {Male=Mr.,Female=Miss} Gardien. Ce nouvel acte de notre pièce n›a commencé que depuis peu."
  },
  AvgDialog_131224_Content_76 = {
    Text = "Arachne agite doucement la main. Le rideau se lève, une scène vide flottante apparaît devant vous."
  },
  AvgDialog_131224_Content_77 = {
    Text = "Il semble y avoir un miroir fugace sur scène, reflétant vos silhouettes."
  },
  AvgDialog_131224_Content_78 = {
    Text = "Les trompettes sonnent une fanfare. Entrée en scène : le Destin abandonné."
  },
  AvgDialog_131224_Content_79 = {
    Text = "Bientôt, ton reflet disparaît dans le miroir, et la silhouette d'Arachne se transforme en une poupée."
  },
  AvgDialog_131224_Content_8 = {
    Text = "Vous hésitez un peu, puis vous entrez dans la pièce."
  },
  AvgDialog_131224_Content_80 = {
    Text = "La marionnette reste assise, mais sa douce contenance s›est évaporée."
  },
  AvgDialog_131224_Content_81 = {
    Text = "Elle fait tournoyer un gobelet empli d›un cru rouge sang comme si elle trônait sur un siège de carnage. Ses yeux, innocents mais absolument impitoyables, balaient l›audience."
  },
  AvgDialog_131224_Content_82 = {
    Text = "Derrière la marionnette, quatre paires de pattes d›araignée acérées comme des lames se balancent paresseusement, leurs pointes effleurant les joues des serviteurs se tenant à proximité."
  },
  AvgDialog_131224_Content_83 = {
    Text = "Ah, l'air de la liberté..."
  },
  AvgDialog_131224_Content_84 = {
    Text = "Depuis combien d'années sommes-nous enfermés dans cet abîme, mon cher serviteur ?"
  },
  AvgDialog_131224_Content_85 = {
    Text = "Je ne sais pas, mon maître."
  },
  AvgDialog_131224_Content_86 = {
    Text = "Nom, temps, émotions... J'ai tout oublié... Je me souviens seulement de vous, mon maître, la respectée Nefraea."
  },
  AvgDialog_131224_Content_87 = {
    Text = "Je me souviens seulement que vous m'avez dit que vous nous emmèneriez d'ici, que vous nous mèneriez à agiter la lame de la vengeance contre le destin."
  },
  AvgDialog_131224_Content_88 = {
    Text = "Je me souviens, mon enfant. Je vous ai fait quatre-vingt-dix mille promesses, maintenant, laissez-moi vous dire la quatre-vingt-dix mille et une."
  },
  AvgDialog_131224_Content_89 = {
    Text = "À chaque instant, il ne peut exister qu'un seul destin. L'exécuteur de ce destin éliminera d'innombrables destins erronés et ne laissera que le seul destin correct."
  },
  AvgDialog_131224_Content_9 = {Text = "新增"},
  AvgDialog_131224_Content_90 = {
    Text = "Nous, nous sommes ce destin abandonné. Ahahahaha... Mon cher serviteur, tu es une erreur, tout comme moi."
  },
  AvgDialog_131224_Content_91 = {
    Text = "Dans le subconscient de cet univers, dans cet abîme de néant qui n'existe pas, nous sommes exilés et emprisonnés. Nous errons ici, oubliés, pour l'éternité. Notre peine est plus longue que le temps lui-même..."
  },
  AvgDialog_131224_Content_92 = {
    Text = "La femme nommée Nefraea se leva de son siège, se pencha et sourit en croisant le regard d'Arachne dans le public."
  },
  AvgDialog_131224_Content_93 = {
    Text = "Mais pourquoi, ô déesse du destin ? Pourquoi devrions-nous être ceux qui sont exclus ?"
  },
  AvgDialog_131224_Content_94 = {
    Text = "Le suprême et unique dieu des innombrables univers s'est enfin réveillé un instant. Il est retombé dans le sommeil, mais la prison de sa conscience, cet abîme éternel, s'est finalement ouverte pour nous."
  },
  AvgDialog_131224_Content_95 = {
    Text = "J'avais déjà oublié et disparu. Mais pourquoi, pourquoi devrais-je me souvenir de toute cette douleur ?"
  },
  AvgDialog_131224_Content_96 = {
    Text = "Nefraea but son verre, poussant un soupir de satisfaction. Le jus rouge vif coulait le long de ses lèvres pâles, gouttant sur son rouet terne dans sa main."
  },
  AvgDialog_131224_Content_97 = {
    Text = "Peut-être que c'est ainsi que le destin est arrangé... un destin que même toi tu ne peux pas contrôler."
  },
  AvgDialog_131224_Content_98 = {
    Text = "Le dieu primordial s'est de nouveau endormi, mais ses fragments sont arrivés dans notre demeure."
  },
  AvgDialog_131224_Content_99 = {
    Text = "Je n'ai pas la capacité de contrôler le destin comme toi. Je ne suis que le correcteur du destin, l'exécuteur venu du vide. Les péchés dans le fleuve du destin seront punis par moi au nom du primordial."
  },
  AvgDialog_131225_Content_1 = {
    Text = "Ombre du passé"
  },
  AvgDialog_131225_Content_10 = {
    Text = "Contrairement à l'immensité que tu as imaginée grâce à ton expérience, l'intérieur de cette villa semble exceptionnellement encombré, Nefraea semble avoir décidé de tout écrire à sa manière dans son scénario."
  },
  AvgDialog_131225_Content_11 = {
    Text = "Les armoires et les étagères s'étendent silencieusement et sont encombrées, remplies de bocaux de toutes tailles qui occupent chaque recoin de leur espace."
  },
  AvgDialog_131225_Content_12 = {
    Text = "Miroirs en argent, œufs d'araignée, chaussures de danse rampées par des insectes étranges... Une variété d'objets trempe dans un liquide inconnu, comme autant de bouches silencieuses criant."
  },
  AvgDialog_131225_Content_13 = {
    Text = "Tu te tiens devant ces bocaux variés et murmures les mots sur les étiquettes."
  },
  AvgDialog_131225_Content_14 = {
    Text = "À deux ans, il a prononcé sa première phrase de la vie. Il n'a pas appelé sa famille, mais a dit adieu au vieux majordome qui s'était occupé de sa famille pendant plusieurs générations."
  },
  AvgDialog_131225_Content_15 = {
    Text = "Cette nuit-là, le vieux majordome est mort d'une maladie cardiaque. Tenant les reliques du majordome, il pleure devant la porte de celui-ci..."
  },
  AvgDialog_131225_Content_16 = {
    Text = "C'était une vieille broche de famille."
  },
  AvgDialog_131225_Content_17 = {
    Text = "Cinq ans, dans les acclamations gênantes des invités du dîner, elle se met à danser le valse timidement en imitant sa mère..."
  },
  AvgDialog_131225_Content_18 = {
    Text = "C'étaient des chaussures de danse rouges vives."
  },
  AvgDialog_131225_Content_19 = {
    Text = "À sept ans, j'ai reçu un cadeau d'anniversaire offert par mon père, un rouet nommé « Moïra »."
  },
  AvgDialog_131225_Content_2 = {
    Text = "Brick Lane, tu te souviens de la scène lors de l'enquête dans cette zone de Londinium."
  },
  AvgDialog_131225_Content_20 = {
    Text = "Dans les fils du rouet, je vois le reflet du destin..."
  },
  AvgDialog_131225_Content_21 = {
    Text = "C'était une poignée de fils cassés."
  },
  AvgDialog_131225_Content_22 = {
    Text = "La première fois que je suis allé à l'opéra avec mes parents... La première fois que j'ai rencontré un ami proche... La première fois que j'ai enterré mon chien..."
  },
  AvgDialog_131225_Content_23 = {
    Text = "Les mots sur l'étiquette du pot s'imprègnent un à un dans vos yeux. Chaque fois que vous les touchez, un souvenir flou émerge dans votre esprit. Vous vous retournez et regardez Arachne avec curiosité."
  },
  AvgDialog_131225_Content_24 = {
    Text = "Ça... ce sont tous tes souvenirs ?"
  },
  AvgDialog_131225_Content_25 = {
    Text = "C'est un souvenir de moi. Il y a longtemps, ils appartenaient à cette personne appelée « Souvenir »."
  },
  AvgDialog_131225_Content_26 = {
    Text = "Ce sont tous des souvenirs précieux... Pourquoi les mettre sur un objet secret ?"
  },
  AvgDialog_131225_Content_27 = {
    Text = "Dans la vie de chaque personne, il est nécessaire de faire des choix. Chaque choix a un prix."
  },
  AvgDialog_131225_Content_28 = {
    Text = "Pour atteindre le bout du chemin, il faut toujours abandonner quelque chose. Je pense que vous comprenez cela mieux que quiconque, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131225_Content_29 = {
    Text = "Arachne n'a pas directement répondu à ta question, elle regardait ces armoires, passant doucement sa main sur les jarres remplies de liquide."
  },
  AvgDialog_131225_Content_3 = {
    Text = "Sale, chaos, l'air est rempli de fumée de charbon et d'odeur d'égouts, ces odeurs ont accompagné Mason et Jenkin pendant toute leur vie."
  },
  AvgDialog_131225_Content_30 = {
    Text = "Ses mouvements étaient légers et lents, comme ceux d'un vieillard en fin de vie, caressant les jouets chéris de son enfance."
  },
  AvgDialog_131225_Content_31 = {
    Text = "Sorte ces souvenirs du Pair secret, en les manifestant sous cette forme. C'est le paysage que tu as préparé pour moi, Nefraea."
  },
  AvgDialog_131225_Content_32 = {
    Text = "Tu veux me dire, j'ai compris..."
  },
  AvgDialog_131225_Content_33 = {
    Text = "<Big:<Shake:AAAHHHH ! —>>"
  },
  AvgDialog_131225_Content_34 = {
    Text = "Un cri perçant résonne dans la pièce, les bocaux emplis de souvenirs vibrent doucement, comme une foule de spectateurs riant silencieusement."
  },
  AvgDialog_131225_Content_35 = {
    Text = "!!Dans la pièce derrière le couloir"
  },
  AvgDialog_131225_Content_36 = {Text = "Bang—"},
  AvgDialog_131225_Content_37 = {
    Text = "Tu cours rapidement dans le couloir et enfonces la porte de la chambre..."
  },
  AvgDialog_131225_Content_38 = {
    Text = "Tu es au milieu d'une averse."
  },
  AvgDialog_131225_Content_39 = {
    Text = "Il n'y a ni tonnerre, ni vent, ni pluie. Il n'y a que des araignées, tombant du plafond vide comme une pluie torrentielle."
  },
  AvgDialog_131225_Content_4 = {
    Text = "Et à ce moment-là, une villa éclatante de dorures apparaît soudainement entre deux maisons de fortune, comme une boîte à bijoux posée sur un tas de déchets."
  },
  AvgDialog_131225_Content_40 = {
    Text = "Des arthropodes noirs et visqueux se rassemblent en une marée déferlante, dévorant tous les objets et toute la lumière dans la maison."
  },
  AvgDialog_131225_Content_41 = {
    Text = "Au centre de la tempête sombre et pluvieuse, ces araignées grimpant et dévorant comme des folles se rassemblent en une forme humaine à peine reconnaissable. Là où la marée d'araignées n'a pas encore recouvert, apparaît un visage de vieillard que tu as déjà vu."
  },
  AvgDialog_131225_Content_42 = {
    Text = "Arachne......mademoiselle......"
  },
  AvgDialog_131225_Content_43 = {
    Text = "Vite... fuis ! ..."
  },
  AvgDialog_131225_Content_44 = {
    Text = "Chut... Il n'y a pas de réplique pour vous ici, monsieur « Bienveillant »."
  },
  AvgDialog_131225_Content_45 = {
    Text = "La vengeance du destin, deuxième acte, deuxième scène. Je l'ai intitulé « Pluie battante »."
  },
  AvgDialog_131225_Content_46 = {
    Text = "Baignons-nous bien dans cette merveilleuse pluie, mes chers spectateurs."
  },
  AvgDialog_131225_Content_47 = {
    Text = "L'eau stagnante soulève des vagues, les araignées noires entendent l'ordre suprême et se dirigent vers chaque coin de la pièce."
  },
  AvgDialog_131225_Content_48 = {
    Text = "Dans les acclamations de Nefraea, les gardes et serviteurs formés par des araignées, ainsi que des créatures répugnantes, se précipitent vers vous —"
  },
  AvgDialog_131225_Content_5 = {
    Text = "Les vagabonds et les travailleurs fatigués passaient devant cette magnifique boîte, sans qu'aucune personne ne lui jette un regard de trop, comme si elle avait toujours été là depuis leur naissance."
  },
  AvgDialog_131225_Content_6 = {
    Text = "Il semble que même le destin de cette ville soit affecté... La force de Nefraea, en effet, est en train de s'intensifier."
  },
  AvgDialog_131225_Content_7 = {
    Text = "Vous vous approchez prudemment, prêt à frapper à la porte, mais lorsque votre main se pose sur la porte, celle-ci s'ouvre silencieusement."
  },
  AvgDialog_131225_Content_8 = {
    Text = "Il semble que notre maître attentionné nous ait réservé une porte."
  },
  AvgDialog_131225_Content_9 = {Text = "C'est..."},
  AvgDialog_131226_Content_1 = {
    Text = "Tue...... un meurtre!"
  },
  AvgDialog_131226_Content_10 = {
    Text = "J'ai tout vu. Vous n'avez pas traversé ce portail, %player%. Ce n'est pas ici que nous devons être."
  },
  AvgDialog_131226_Content_11 = {
    Text = "Je trouve cela étrange aussi... La fusion et Mizag, ces fléaux, ils ne les connaissent même pas."
  },
  AvgDialog_131226_Content_12 = {
    Text = "Mais l'apparence de cette ville est exactement la même qu'avant la catastrophe, comme dans mes souvenirs. Peut-être que nous devrions retourner à l'école maintenant, on pourrait peut-être découvrir quelque chose..."
  },
  AvgDialog_131226_Content_13 = {
    Text = "J'en viens à l'instant. Il n'y a pas de Mizag ici, %player%."
  },
  AvgDialog_131226_Content_14 = {Text = "Non... ?"},
  AvgDialog_131226_Content_15 = {
    Text = "La carte du monde dans le magasin est d'une apparence que je n'ai jamais vue, et toutes les années indiquées sur les calendriers sont complètement différentes de l'ère Aluviion."
  },
  AvgDialog_131226_Content_16 = {
    Text = "La chose la plus étrange est... cette ville n'a pas de fin."
  },
  AvgDialog_131226_Content_17 = {
    Text = "Pas de... fin ?"
  },
  AvgDialog_131226_Content_18 = {
    Text = "En continuant vers le nord depuis la direction de Mizag, vous pourrez quitter la zone de Londinium."
  },
  AvgDialog_131226_Content_19 = {
    Text = "J'ai également été attaqué par ces araignées en chemin. Pour les éviter, j'ai avancé le long de ce chemin, mais finalement... je suis revenu près de l'endroit où tu te trouves, au sud de Londinium."
  },
  AvgDialog_131226_Content_2 = {
    Text = "La foule hurle et se disperse. Avant même que vous ne vous en rendiez compte, William est là, à vos côtés, sa chevelure dorée toujours aussi reconnaissable."
  },
  AvgDialog_131226_Content_20 = {
    Text = "Ce n'est pas Lentini, ce n'est pas Kadath."
  },
  AvgDialog_131226_Content_21 = {
    Text = "Il semble que ma mémoire ne me fasse pas défaut... Ce passage s'est effectivement fermé avant que j'entre..."
  },
  AvgDialog_131226_Content_22 = {
    Text = "Vous levez les yeux vers les paysages familiers au–delà du passage et soupirez, un sentiment de vide s'installant en vous."
  },
  AvgDialog_131226_Content_23 = {
    Text = "Un lieu identique à Londinium, une ville sans fin, des araignées noires surgissant de nulle part... et la Dame à qui elles obéissent..."
  },
  AvgDialog_131226_Content_24 = {
    Text = "Il est trop tôt pour en être certain, mais je ne crois pas que la fermeture du portail et notre arrivée ici soient une coïncidence. Quelqu'un a orchestré tout cela délibérément — celui qui commande ces araignées."
  },
  AvgDialog_131226_Content_25 = {
    Text = "Nous ne comprenons toujours rien. Nous devons d'abord rassembler des informations..."
  },
  AvgDialog_131226_Content_26 = {Text = "Deux..."},
  AvgDialog_131226_Content_27 = {Text = "Qui ?!"},
  AvgDialog_131226_Content_28 = {
    Text = "L'éclat argenté brille dans la paume mécanique de William, tel une lame prête à sortir de son fourreau."
  },
  AvgDialog_131226_Content_29 = {
    Text = "Dans cette lumière argentée dangereuse, tu vois le vieillard qui voulait tout juste te tendre de la nourriture."
  },
  AvgDialog_131226_Content_3 = {
    Text = "William, l'Aîné... tu es arrivé quand... que se passe-t-il ?"
  },
  AvgDialog_131226_Content_30 = {
    Text = "Oui... c'est moi..."
  },
  AvgDialog_131226_Content_31 = {
    Text = "C'est... à vous ?"
  },
  AvgDialog_131226_Content_32 = {
    Text = "Le vieillard ouvrit la main. L'emblème de Mizag utilisé pour la communication reposait tranquillement dans la paume rugueuse de sa main."
  },
  AvgDialog_131226_Content_33 = {
    Text = "Ah ! C'est ce qui est tombé tout à l'heure pendant le combat..."
  },
  AvgDialog_131226_Content_34 = {
    Text = "Cela compte énormément pour moi... merci infiniment!"
  },
  AvgDialog_131226_Content_35 = {
    Text = "Sous le regard vigilant de William, tu as récupéré l'écusson et l'as soigneusement conservé."
  },
  AvgDialog_131226_Content_36 = {
    Text = "Vieillard... n'avez-vous pas peur de ce qui vient de se passer ?"
  },
  AvgDialog_131226_Content_37 = {
    Text = "C'est la peur... J'ai vécu ici toute ma vie, je n'ai jamais vu ça..."
  },
  AvgDialog_131226_Content_38 = {
    Text = "Mais je vois que cette chose est importante pour toi. Tu viens d'arriver ici, et si tu l'avais perdue, tu ne saurais même pas où chercher, alors je te l'ai apportée."
  },
  AvgDialog_131226_Content_39 = {
    Text = "Vraiment, merci beaucoup à vous..."
  },
  AvgDialog_131226_Content_4 = {
    Text = "Ce n'est pas un endroit pour parler. Va"
  },
  AvgDialog_131226_Content_40 = {
    Text = "Nous venons d'arriver ici, il y a beaucoup de choses que nous ne savons pas, puis-je vous poser quelques questions ?"
  },
  AvgDialog_131226_Content_41 = {
    Text = "Cela ne me dérange pas de passer un peu plus de temps avec vous deux, mais j'ai bien peur de savoir très peu de choses sur ce que vous cherchez."
  },
  AvgDialog_131226_Content_42 = {
    Text = "Un endroit avec plus de monde vous serait sans doute plus utile, je suppose."
  },
  AvgDialog_131226_Content_43 = {
    Text = "C'est bon, les affaires sont livrées, je rentre d'abord."
  },
  AvgDialog_131226_Content_44 = {
    Text = "Le vieillard agita la main, ne prêtant plus attention à vos supplications, et quitta la ruelle."
  },
  AvgDialog_131226_Content_45 = {
    Text = "Ce vieillard n'a pas l'air malveillant. Il a raison, nous devons trouver un endroit où les nouvelles circulent plus rapidement."
  },
  AvgDialog_131226_Content_46 = {
    Text = "Je connais l'endroit idéal!"
  },
  AvgDialog_131226_Content_47 = {
    Text = "Si cette ville ressemble exactement à Londinium, ce sera sûrement l'endroit le plus approprié."
  },
  AvgDialog_131226_Content_48 = {
    Text = "Tandis que vous partez, une araignée d'un violet pâle se tapit juste au bord de votre champ de vision, rampant le long de son fil et se glissant dans une fissure du mur, disparaissant sans laisser de trace."
  },
  AvgDialog_131226_Content_5 = {
    Text = "William, l'Aîné vous saisit et se dirige dans la direction opposée à la foule."
  },
  AvgDialog_131226_Content_6 = {Text = "新增"},
  AvgDialog_131226_Content_7 = {
    Text = "Il ne devrait y avoir personne dans les environs."
  },
  AvgDialog_131226_Content_8 = {
    Text = "Que se passe–t–il? Pourquoi Londinium est–elle devenue ainsi..."
  },
  AvgDialog_131226_Content_9 = {
    Text = "Ces araignées qui nous ont attaqués, et cette personne... pourrait–elle être liée à la femme que nous avons rencontrée sur Le Parades?"
  },
  AvgDialog_131227_Content_1 = {
    Text = "Tawil ! Je..."
  },
  AvgDialog_131227_Content_2 = {
    Text = "Je comprends, Gardien."
  },
  AvgDialog_131227_Content_3 = {
    Text = "Ton destin a été modifié. Tu ne peux pas t'arrêter, et tu ne devrais pas t'arrêter."
  },
  AvgDialog_131227_Content_4 = {
    Text = "Arachne ne peut pas prononcer le destin du futur... S'il vous plaît, dites-moi ce que je devrais faire..."
  },
  AvgDialog_131227_Content_5 = {
    Text = "Je ne peux pas te parler de ce qui se trouve derrière la porte. Il y a des personnes plus appropriées que moi pour t'aider dans cette affaire."
  },
  AvgDialog_131227_Content_6 = {
    Text = "Avance, Gardien. Ton destin doit être éclairci par toi-même."
  },
  AvgDialog_131228_Content_1 = {
    Text = "Hmm... héros et bouffons, marionnettes du destin... un bon spectacle."
  },
  AvgDialog_131228_Content_2 = {
    Text = "Arachne m'a dit que la clé pour déverrouiller le verrou est « plaisir »... C'est ton domaine, N."
  },
  AvgDialog_131228_Content_3 = {
    Text = "Chut ! Ne sois pas si pressé. Détruire une bonne performance est le péché le plus impardonnable de cet univers."
  },
  AvgDialog_131228_Content_4 = {
    Text = "Venez, Gardien. Ça fait longtemps, laissez-moi voir si vous avez eu de nouvelles perceptions sur le plaisir ?"
  },
  AvgDialog_131229_Content_10 = {
    Text = "Réponds-moi... Liz !..."
  },
  AvgDialog_131229_Content_11 = {
    Text = "Ses fils de destin sont déjà coupés... sa vie est désormais terminée."
  },
  AvgDialog_131229_Content_12 = {
    Text = "<Shake:Non... nous ne pouvons pas laisser Nefraea s'en tirer comme ça>, elle doit payer le prix de ses actes imprudents"
  },
  AvgDialog_131229_Content_13 = {
    Text = "Le prix à payer est déjà préparé par le destin pour elle. Les indices ne s'arrêteront pas ici."
  },
  AvgDialog_131229_Content_14 = {
    Text = "Mais tu viens de dire que Liz est déjà..."
  },
  AvgDialog_131229_Content_15 = {
    Text = "La mort n'est qu'une partie du Destin. Ceci est ma scène, {Male=Mr.,Female=Miss} Gardien. Tous les destins sont des fils entre mes mains, et moi seule en tisse le cours."
  },
  AvgDialog_131229_Content_16 = {Text = "!!!"},
  AvgDialog_131229_Content_17 = {
    Text = "<Shake:Attendez, vous voulez dire...>"
  },
  AvgDialog_131229_Content_18 = {
    Text = "Le visage d'Arachne était sans tristesse ni joie. Elle s'approcha de l'annonceur qui avait été brièvement parasité par Nefraea. La lumière douce du crépuscule dessinait son ombre floue et stable, semblable au destin lui-même."
  },
  AvgDialog_131229_Content_19 = {
    Text = "Ah... hahahaha... Arachne, tu es toujours aussi, aussi vaniteux ! hahahaha..."
  },
  AvgDialog_131229_Content_2 = {
    Text = "Les ennemis tout autour sont tombés, mais ton attaque n'a pas cessé."
  },
  AvgDialog_131229_Content_20 = {
    Text = "Nefraea semble avoir vu quelque chose de très amusant, riant aux éclats jusqu'à tomber par terre."
  },
  AvgDialog_131229_Content_21 = {
    Text = "Pollution du destin de Liz, la conduisant à une fin mortelle... Chaque acte que tu as accompli sera gravé dans le réseau du destin."
  },
  AvgDialog_131229_Content_22 = {
    Text = "Le destin erroné sera corrigé. Devant ton destin, un prix t'attend naturellement."
  },
  AvgDialog_131229_Content_23 = {
    Text = "Arachne tendit la main et effleure doucement le sommet de ce cadavre. Le fuseau dans sa main tourne lentement, tout autour de vous semble se distordre et se recomposer dans cette rotation..."
  },
  AvgDialog_131229_Content_24 = {
    Text = "Les fils du destin, écoute l'appel du filet. Suivant ce chemin unique, remonte sur scène..."
  },
  AvgDialog_131229_Content_25 = {
    Text = "Son corps... a disparu ?"
  },
  AvgDialog_131229_Content_26 = {
    Text = "Avec le mouvement des doigts d'Arachne, le corps de Liz au-dessus de la scène semble vivre une brûlure silencieuse, se transformant en cendres et se dissipant dans l'air."
  },
  AvgDialog_131229_Content_27 = {
    Text = "Sous ces cendres tombées, un nouveau corps apparaît devant toi."
  },
  AvgDialog_131229_Content_28 = {
    Text = "C'est... ce présentateur ?"
  },
  AvgDialog_131229_Content_29 = {
    Text = "Les épines transpercent le corps du crieur, la suspendant au-dessus de la scène, tous les mouvements et amplitudes étant identiques à ceux de Liz."
  },
  AvgDialog_131229_Content_3 = {
    Text = "Tu hurles, piétinant comme un fou le visage souriant de l'annonceur sur les planches de la scène."
  },
  AvgDialog_131229_Content_30 = {
    Text = "L'annonceur laisse derrière lui un sourire hideux, et il n'y a plus de son."
  },
  AvgDialog_131229_Content_31 = {
    Text = "Arachne, tu......"
  },
  AvgDialog_131229_Content_32 = {
    Text = "Désolé, je suis arrivé trop tard, je viens juste de... ah"
  },
  AvgDialog_131229_Content_33 = {
    Text = "La silhouette familière soulève le rideau et monte sur scène. Son regard parcourt vos silhouettes, s'attardant sur le cadavre suspendu dans les airs."
  },
  AvgDialog_131229_Content_34 = {
    Text = "Ses mouvements... sont vraiment beaux..."
  },
  AvgDialog_131229_Content_35 = {
    Text = "Liz semblait avoir oublié les cadavres étalés au sol et le public qui se tenait debout. Elle s'approcha du centre de la scène, sa main glissant au-dessus des jambes du cadavre suspendu, comme si elle était en train d'explorer cette courbe élégante."
  },
  AvgDialog_131229_Content_36 = {
    Text = "Arachne, tu... as échangé le destin de l'annonceur et de Liz ?"
  },
  AvgDialog_131229_Content_37 = {
    Text = "Mais tu as dit que cette consommation est difficile à supporter..."
  },
  AvgDialog_131229_Content_38 = {
    Text = "La consommation n'a rien à voir avec le choix. Dans mon destin, c'est aussi le prix que je dois payer."
  },
  AvgDialog_131229_Content_39 = {
    Text = "Allez, %player%. Ne faites pas attendre Mademoiselle Liz."
  },
  AvgDialog_131229_Content_4 = {
    Text = "C'est ça... comme ça... colère, défoulement ! Quelle expression magnifique..."
  },
  AvgDialog_131229_Content_40 = {
    Text = "Yeux éthérés et respiration. La jupe flottante, parsemée de légères flammes vertes. Chaque vibration des doigts est comme une danse soigneusement chorégraphiée."
  },
  AvgDialog_131229_Content_41 = {
    Text = "La silhouette ensanglantée qui s'est ruée vers vous il y a quelques instants se superpose à la femme devant vous maintenant. Liz se tient là, vivante et bien réelle — le retissage complexe du destin n'a laissé aucune marque sur elle."
  },
  AvgDialog_131229_Content_42 = {
    Text = "Après un long moment, Liz revint de son admiration pour le corps et se tourna vers toi qui étais à ses côtés."
  },
  AvgDialog_131229_Content_43 = {
    Text = "J'ai dormi tout l'après-midi chez moi aujourd'hui et j'ai manqué le spectacle. C'est quelque chose qui ne m'est jamais arrivé..."
  },
  AvgDialog_131229_Content_44 = {
    Text = "Il semble que j'ai manqué quelque chose de très important ?"
  },
  AvgDialog_131229_Content_45 = {
    Text = "Les yeux de Liz balayent les corps et les taches de sang au sol qu'elle a ignorés."
  },
  AvgDialog_131229_Content_46 = {
    Text = "Non, tu n'as rien manqué, Liz."
  },
  AvgDialog_131229_Content_47 = {
    Text = "Toi... ça va ? Tu as des douleurs ?"
  },
  AvgDialog_131229_Content_48 = {
    Text = "Je me sens bien. Mais dites-moi, {Male=sir,Female=miss}, nous sommes-nous déjà rencontrés ? Vous me semblez étrangement familier..."
  },
  AvgDialog_131229_Content_49 = {
    Text = "C'est peut-être parce qu'en tant que ton Suiveur, j'ai regardé beaucoup de tes performances."
  },
  AvgDialog_131229_Content_5 = {
    Text = "Ce visage comme de la boue sourit, une voix faible s'échappe de sa trachée brisée."
  },
  AvgDialog_131229_Content_50 = {
    Text = "Tu la regardes en souriant. Cette scène a ses propres histoires, et tu n'as pas l'intention de lui parler de ces choses anciennes."
  },
  AvgDialog_131229_Content_51 = {
    Text = "Nous venons pour «la bonté»."
  },
  AvgDialog_131229_Content_52 = {
    Text = "L'ami de Madame Sorel est enfin arrivé, j'avais peur d'être en retard à la représentation et de négliger cette « bonne » personne... Veuillez me suivre, ma résidence est située non loin de la troupe de danse."
  },
  AvgDialog_131229_Content_53 = {
    Text = "Liz jette un regard prolongé sur le cadavre accroché au mur avant de vous guider derrière le rideau."
  },
  AvgDialog_131229_Content_54 = {Text = "新增"},
  AvgDialog_131229_Content_55 = {
    Text = "Alors... c'était mon cadavre qui devait être suspendu sur scène..."
  },
  AvgDialog_131229_Content_56 = {
    Text = "Il est trop tard pour pleurer mes partenaires de danse disparus, et j'ai oublié de remercier ceux qui m'ont permis de revenir à la vie."
  },
  AvgDialog_131229_Content_57 = {
    Text = "Dans votre récit, les yeux de Liz scintillent comme des flammes dansantes. Elle tend la main et adopte la même posture que le cadavre."
  },
  AvgDialog_131229_Content_58 = {
    Text = "Cette scène, est-elle belle ?"
  },
  AvgDialog_131229_Content_59 = {
    Text = "La beauté suprême du monde ne se manifeste qu'à deux moments : la naissance et la mort. C'est une image inégalée, Mademoiselle Liz."
  },
  AvgDialog_131229_Content_6 = {
    Text = "Nefraea n'est pas ici, ce n'est qu'une illusion laissée par elle. Ne vous laissez pas tromper par la colère, Gardien {Male=Monsieur,Female=Madame}."
  },
  AvgDialog_131229_Content_60 = {
    Text = "Merci, Madame Arachne. Vous êtes la tisseuse du Destin, alors je pense que vous devez souvent être entourée de ces beautés. C'est vraiment... enviable."
  },
  AvgDialog_131229_Content_61 = {
    Text = "Trop de trésors deviendront une punition."
  },
  AvgDialog_131229_Content_62 = {
    Text = "Si c'est votre punition, quelle récompense demandez-vous ?"
  },
  AvgDialog_131229_Content_63 = {
    Text = "Liz n'a pas remarqué la brève pause d'Arachne et a ouvert la porte de la chambre d'amis dans la cour."
  },
  AvgDialog_131229_Content_64 = {
    Text = "Voici le logement temporaire de monsieur « Bienveillant ». Monsieur « Bienveillant », vos amis sont venus vous chercher."
  },
  AvgDialog_131229_Content_65 = {
    Text = "«Monsieur Bienveillant» ?"
  },
  AvgDialog_131229_Content_66 = {
    Text = "Une pièce simple, sans aucun meuble qui n'appartienne à cet endroit, sans aucune personne qui n'appartienne à cet endroit."
  },
  AvgDialog_131229_Content_67 = {
    Text = "Dans la maison vide, un simple morceau de papier repose silencieusement sur l'étagère."
  },
  AvgDialog_131229_Content_68 = {
    Text = "«Je suis désolé de partir sans prévenir. Madame Sorel s'inquiète que vous soyez impliqué, donc elle a fait de nouveaux arrangements, je vais me réfugier dans la villa des souvenirs.»"
  },
  AvgDialog_131229_Content_69 = {
    Text = "«Je vous suis extrêmement reconnaissant pour vos soins. Je vous rembourserai cette faveur sérieusement.»"
  },
  AvgDialog_131229_Content_7 = {
    Text = "<Shake:Hou... Hou...>"
  },
  AvgDialog_131229_Content_70 = {
    Text = "Madame Sorel nous informera si elle change de plan..."
  },
  AvgDialog_131229_Content_71 = {
    Text = "Tu regardes les yeux sans vagues d'Arachne. Dans ce sourire calme qui semble ne jamais disparaître, tu aperçois une ombre fugace."
  },
  AvgDialog_131229_Content_72 = {
    Text = "«Le souvenir» est une errante. Elle n'a pas de foyer."
  },
  AvgDialog_131229_Content_73 = {
    Text = "Quoi ? !! C'était..."
  },
  AvgDialog_131229_Content_74 = {
    Text = "«Souvenir» du Destin, il est à craindre qu'il ait déjà été altéré par Nefraea. Tous deux sont maintenant plongés dans le danger."
  },
  AvgDialog_131229_Content_75 = {
    Text = "Désolé, je ne m'attendais pas à..."
  },
  AvgDialog_131229_Content_76 = {
    Text = "Ce n'est pas votre responsabilité, mademoiselle Liz."
  },
  AvgDialog_131229_Content_77 = {
    Text = "Puisque Nefraea peut altérer ton destin, trouver les personnes autour de toi n'est pas une tâche difficile. Ce sont là les problèmes que nous devons traiter."
  },
  AvgDialog_131229_Content_78 = {
    Text = "Les traces d'encre au-dessus ne sont pas encore complètement sèches, le moment où Nefraea agira n'est pas loin, nous devrions nous dépêcher, peut-être que nous avons encore le temps..."
  },
  AvgDialog_131229_Content_79 = {
    Text = "Liz, il y a des choses que je ne peux pas dire cette fois-ci..."
  },
  AvgDialog_131229_Content_8 = {
    Text = "Quand ce visage souriant ne peut plus être reconnu, tu t'arrêtes enfin."
  },
  AvgDialog_131229_Content_80 = {
    Text = "Il y aura d'autres occasions, {Male=Mr.,Female=Miss} Gardien. J'espère que ma prochaine danse vous touchera tout autant."
  },
  AvgDialog_131229_Content_81 = {
    Text = "Après vous avoir dit au revoir avec un simple sourire, Liz ne s'intéresse plus à vos histoires compliquées."
  },
  AvgDialog_131229_Content_82 = {
    Text = "Elle leva son bras, adoptant la même courbe que celle du cadavre, essayant de recréer cette danse qui hantait son esprit."
  },
  AvgDialog_131229_Content_83 = {
    Text = "La brise fait danser sa jupe, comme un cygne en plein vol."
  },
  AvgDialog_131229_Content_9 = {
    Text = "Le corps contrôlé de Liz a perdu toute vitalité. Tu déposes doucement son corps meurtri sur le sol et ouvres le canal spirituel lié à elle."
  },
  AvgDialog_131230_Content_1 = {
    Text = "Chute du rideau"
  },
  AvgDialog_131230_Content_10 = {
    Text = "Puisque cette ville a été recréée... Je pensais que tu ramènerais ici les choses qui ont disparu."
  },
  AvgDialog_131230_Content_11 = {
    Text = "...Ça te manque, n'est-ce pas ?"
  },
  AvgDialog_131230_Content_12 = {
    Text = "Plutôt qu'une tasse de café, je préfère voir la scène se présenter par elle-même."
  },
  AvgDialog_131230_Content_13 = {
    Text = "J'ai recréé cet endroit avec des souvenirs, mais je ne peux toujours pas changer le fait que c'est une toute nouvelle scène."
  },
  AvgDialog_131230_Content_14 = {
    Text = "Le nouveau café ici a aussi son goût unique, n'est-ce pas ?"
  },
  AvgDialog_131230_Content_15 = {
    Text = "Arachne sourit et prit doucement une gorgée de ce liquide amer."
  },
  AvgDialog_131230_Content_16 = {
    Text = "Nefraea... que s'est-il passé à la fin ?"
  },
  AvgDialog_131230_Content_17 = {
    Text = "Vos fils du destin ont été retissés ensemble. Cela signifie-t-il... que vous êtes de nouveau la même personne ?"
  },
  AvgDialog_131230_Content_18 = {
    Text = "Les choses qui appartenaient autrefois à Nefraea, ses qualités, sa nature originelle, sont de nouveau revenues dans mon destin. Ou plutôt, comme vous le savez — elles ne sont jamais parties."
  },
  AvgDialog_131230_Content_19 = {
    Text = "Mais la Toile du destin est unique. Cette personne que vous connaissez, Nefraea, cette vengeresse qui se perd dans le Gouffre et a été abandonnée par le destin, n'a pas de fil qui lui appartient dans cette toile."
  },
  AvgDialog_131230_Content_2 = {
    Text = [[
<Italic:Lascia ch'io pianga / Laissez-moi pleurer sur
mia cruda sorte, / mon cruel destin,>]]
  },
  AvgDialog_131230_Content_20 = {
    Text = "Elle... s'est évanouie, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131230_Content_21 = {
    Text = "Le rouet tourne doucement, sans jamais s'arrêter. Arachne ferme les yeux, lève doucement la tête et sent le faible parfum des fleurs dans le vent."
  },
  AvgDialog_131230_Content_22 = {
    Text = "Le destin abandonné, il n'y a que l'emprisonnement éternel et la disparition totale à affronter. C'est vraiment une chose cruelle..."
  },
  AvgDialog_131230_Content_23 = {
    Text = "À chaque instant, le Destin exige un Choix. Les bons chemins demeurent, tandis que les mauvais sont écartés. Tant que nous n'avons pas trouvé le Vrai Chemin, c'est aussi inévitable que l'effondrement de l'univers lui-même."
  },
  AvgDialog_131230_Content_24 = {
    Text = "Tant que nous n'avons pas trouvé le Vrai Chemin, c'est aussi inévitable que l'effondrement de l'univers lui-même."
  },
  AvgDialog_131230_Content_25 = {
    Text = "Dites-moi, {Male=Mr.,Female=Miss} Gardien, si vous aviez le pouvoir de contrôler le Destin, le laisseriez-vous sombrer dans le chaos ? Ou feriez-vous le choix à la place des autres, même si cela signifiait porter le nom d'un meurtrier ?"
  },
  AvgDialog_131230_Content_26 = {
    Text = "Ça... je..."
  },
  AvgDialog_131230_Content_27 = {
    Text = "Ce n'est qu'un débat pour votre divertissement, pas une question à laquelle vous devez répondre. Vous portez déjà bien trop de fardeaux ; vous n'avez pas besoin de celui-ci en plus."
  },
  AvgDialog_131230_Content_28 = {
    Text = "Arachne a secoué la tête en riant."
  },
  AvgDialog_131230_Content_29 = {
    Text = "Le choix est une forme de pouvoir, et pourtant beaucoup choisissent d'y renoncer même lorsqu'il est à leur portée."
  },
  AvgDialog_131230_Content_3 = {
    Text = "<Italic:E che sospiri la libertà! / et soupirer pour ma liberté !>"
  },
  AvgDialog_131230_Content_30 = {
    Text = "Choisir, c'est en assumer les conséquences, et ce n'est pas chose aisée, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131230_Content_31 = {
    Text = "Je suis le manipulateur du destin, toutes les conséquences du destin seront à ma charge."
  },
  AvgDialog_131230_Content_32 = {
    Text = "C'est la première fois que je frappe aux portes de Chokmah-Da'at, et ce sont les paroles qu'Il m'a accordées. À cela, j'accepte avec joie."
  },
  AvgDialog_131230_Content_33 = {
    Text = "Alors tu... bien que tu ne puisses pas voir ton destin, tout cela qui se passe maintenant... tu le sais en réalité."
  },
  AvgDialog_131230_Content_34 = {
    Text = "Le soleil chaud éclaire cette rue, mais en regardant le visage calme d'Arachne et en imaginant ce que cette personne doit affronter chaque jour, même vous ne pouvez vous empêcher de frissonner."
  },
  AvgDialog_131230_Content_35 = {
    Text = "Le romantisme engendre la stupidité, la bonté engendre la fragilité, les souvenirs engendrent la douleur..."
  },
  AvgDialog_131230_Content_36 = {
    Text = "Même si vous vous y étiez préparée depuis longtemps, vous ne les avez jamais vraiment laissés partir. Pourquoi ?"
  },
  AvgDialog_131230_Content_37 = {
    Text = "Pour toi, les abandonner devrait te rendre la vie un peu plus facile."
  },
  AvgDialog_131230_Content_38 = {
    Text = "Avez-vous déjà été en prison ? Les prisonniers qui ont été enfermés pendant des années doivent toujours avoir avec eux quelques objets précieux à leurs yeux."
  },
  AvgDialog_131230_Content_39 = {
    Text = "Une médaille gagnée au combat, une montre de famille, une photo de famille..."
  },
  AvgDialog_131230_Content_4 = {
    Text = "Le chant mélodieux résonne dans les rues, flottant avec le vent doux. Les passants s'arrêtent ou marchent au rythme de cette chanson, profitant de leur vie paisible sous ce printemps."
  },
  AvgDialog_131230_Content_40 = {
    Text = "Pour les prisonniers, ces désirs qui leur causent de la douleur sont la motivation qui leur permet de continuer à vivre."
  },
  AvgDialog_131230_Content_41 = {
    Text = "Ils gardent précieusement ces objets les plus précieux jusqu'à l'instant proche de la mort, remettant un à un ces choses sans valeur."
  },
  AvgDialog_131230_Content_42 = {
    Text = "...Dans la cage du Destin, nous n'avons rien d'autre, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131230_Content_43 = {
    Text = "<Italic:Il duolo infranga / Que la douleur brise\nqueste ritorte / ces chaînes>"
  },
  AvgDialog_131230_Content_44 = {
    Text = "<Italic:de miei martiri / de mes tourments\nsol per pietà. / par pitié seule>"
  },
  AvgDialog_131230_Content_45 = {
    Text = "L'opéra au bord de la route chante le fleuve du destin qui coule dans cette ville. Arachne sirote un café, écoutant attentivement. Du début à la fin, l'angle de son sourire n'a jamais changé."
  },
  AvgDialog_131230_Content_46 = {
    Text = "Vous savez, {Male=Mr.,Female=Miss} Gardien, je rêve souvent de la même scène, encore et encore."
  },
  AvgDialog_131230_Content_47 = {
    Text = "C'était un magnifique théâtre, où il n'y avait que Nefraea et moi. C'est dans cette belle chanson que je lui ai dit adieu."
  },
  AvgDialog_131230_Content_48 = {
    Text = "Vous voyez, même si nous ne pouvons pas voir notre destin, son jugement est omniprésent."
  },
  AvgDialog_131230_Content_49 = {
    Text = "<Italic:E che sospiri la libertà! / Et soupirer pour ma liberté !\nE che sospiri la libertà! / Et soupirer pour ma liberté !>"
  },
  AvgDialog_131230_Content_5 = {
    Text = "Tu prends une gorgée de café."
  },
  AvgDialog_131230_Content_50 = {
    Text = "La voix de l'opéra ne s'arrête jamais, le fil du rouet tourne éternellement. Arachne lâche le verre qu'elle tenait et applaudit sincèrement avec les spectateurs qui s'arrêtent."
  },
  AvgDialog_131230_Content_51 = {
    Text = "Quoi qu'il en soit, une performance est terminée, et cette scène va connaître une courte pause. Nous, les acteurs, allons bientôt nous rendre sur la prochaine scène."
  },
  AvgDialog_131230_Content_52 = {
    Text = "L'influence de Nefraea a disparu, il devrait maintenant être possible de rouvrir le passage vers Kadath ?"
  },
  AvgDialog_131230_Content_53 = {
    Text = "Le passage reliant Kadath se trouve au sein du destin de ce monde. Tu as déjà essayé de traverser les dimensions."
  },
  AvgDialog_131230_Content_54 = {
    Text = "Le danger en fait partie, tu en es déjà conscient."
  },
  AvgDialog_131230_Content_55 = {
    Text = "En effet... Je ne veux plus jamais faire face à ces regards de Touva Wave..."
  },
  AvgDialog_131230_Content_56 = {
    Text = "Arachne, tu peux contrôler le destin de ce monde, peut-être as-tu un moyen de m'aider ?"
  },
  AvgDialog_131230_Content_57 = {
    Text = "Je suis ravi de servir, mais dans ce monde, seule cette ville est ma scène. Le Maître du destin de ce monde n'est pas moi."
  },
  AvgDialog_131230_Content_58 = {
    Text = "Incroyable !..."
  },
  AvgDialog_131230_Content_59 = {
    Text = "Le Maître de ce monde possède des capacités qui dépassent même ma portée. Ce monde n'existe que parce qu'Il l'a voulu."
  },
  AvgDialog_131230_Content_6 = {
    Text = "Ça n'arrive pas à la cheville du café bosniaque."
  },
  AvgDialog_131230_Content_60 = {
    Text = "À moins que le passage ne soit délibérément ouvert, cet endroit reste caché même au regard du Primordial... C'est précisément pour cela que j'ai choisi d'y demeurer."
  },
  AvgDialog_131230_Content_61 = {
    Text = "Est-ce que... ouvrir le passage va causer des dangers ici ?"
  },
  AvgDialog_131230_Content_62 = {
    Text = "Comme je l'ai dit, le destin a sa propre trajectoire. Se cantonnant ici, c'est juste attendre lentement la mort. T'aider à retourner à Kadath est également le vœu de ce monde."
  },
  AvgDialog_131230_Content_63 = {
    Text = "Pour la lumière qui nous attend au bout du chemin du destin, c'est un danger que nous sommes plus que disposés à assumer."
  },
  AvgDialog_131230_Content_64 = {
    Text = "Je vois... Je comprends."
  },
  AvgDialog_131230_Content_65 = {
    Text = "Où puis-je le trouver ?"
  },
  AvgDialog_131230_Content_66 = {
    Text = "Le fil de son destin est vaste comme une mer d'étoiles, et aussi insignifiant que la poussière. En me basant uniquement sur la capture du destin, je ne peux pas te désigner directement sa position."
  },
  AvgDialog_131230_Content_67 = {
    Text = "Mais peut-être que cela pourra t'aider."
  },
  AvgDialog_131230_Content_68 = {
    Text = "Arachne te tend une page de pamphlet. Tu fronces les sourcils en regardant ces belles lettres calligraphiées pleines de religiosité."
  },
  AvgDialog_131230_Content_69 = {
    Text = "Avis de recrutement :"
  },
  AvgDialog_131230_Content_7 = {
    Text = "La dernière fois que je suis allé goûter sur cette scène, j'ai aussi trouvé le goût plutôt bon. Malheureusement, sur cette scène, la famille qui a inventé ce café a disparu il y a longtemps."
  },
  AvgDialog_131230_Content_70 = {
    Text = "Le Grand Prêtre, Élu(e) du dieu, Exécuteur du Dieu suprême, héritier légitime du grand culte, sauveur des souffrances, ami proche du roi divin est descendu sur le continent du Nord terminal, le culte se développe rapidement, les croyants peuvent venir ici en hâte pour le rencontrer."
  },
  AvgDialog_131230_Content_71 = {
    Text = "Les douze premiers croyants qui arriveront seront consacrés saints, suivant éternellement la fée, sous la protection éternelle des divinités..."
  },
  AvgDialog_131230_Content_72 = {
    Text = "C'est quoi ce truc ?"
  },
  AvgDialog_131230_Content_73 = {
    Text = "Comme vous pouvez le voir, c'est un dépliant soigneusement fabriqué."
  },
  AvgDialog_131230_Content_74 = {
    Text = "Pourquoi ce contenu ici est-il si étrange... Arachne, tu peux voir le cours du destin, es-tu sûr que ce n'est pas une arnaque ?"
  },
  AvgDialog_131230_Content_75 = {
    Text = "Sur son fil, j'ai vu ton ombre. Je suis sûr que c'est le destin que tu es sur le point d'accueillir."
  },
  AvgDialog_131230_Content_76 = {
    Text = "C'est de l'aide ou un danger, je ne peux le dire. Mais je sais que c'est le seul lien entre toi et ce maître du monde."
  },
  AvgDialog_131230_Content_77 = {
    Text = "La main d'Arachne s'étendit au-dessus de ce pamphlet absurde, saisissant un objet invisible que tu places dans ta paume."
  },
  AvgDialog_131230_Content_78 = {
    Text = "Et ceci est... ?"
  },
  AvgDialog_131230_Content_79 = {
    Text = "Bientôt, un mince fil scintille d'un éclat ténu dans votre main."
  },
  AvgDialog_131230_Content_8 = {
    Text = "Tu regardes autour de cette ville. Le carrefour de Brick, la librairie d'occasion des plis temporels, l'épicerie parfumée du marché..."
  },
  AvgDialog_131230_Content_80 = {
    Text = "Ceci est le catalyseur qui vous lie à ce destin. Il vous guidera là où vous êtes destiné à être."
  },
  AvgDialog_131230_Content_81 = {
    Text = "Je comprends. Une fois que William, l'Aîné se sera rétabli, nous..."
  },
  AvgDialog_131230_Content_82 = {
    Text = "Dans le bref aperçu que j'ai eu de vos fils, j'ai vu une histoire intéressante."
  },
  AvgDialog_131230_Content_83 = {
    Text = "Je n'ai pas pu voir votre fin, et j'en suis heureuse. Cela signifie que j'ai encore l'honneur d'être spectatrice de votre destin."
  },
  AvgDialog_131230_Content_84 = {
    Text = "Je crois qu'aucune histoire ne mérite de rester inécoutée... Alors je vous en prie, nul besoin de se presser. Écoutons cet opéra jusqu'à la fin, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131230_Content_85 = {
    Text = "La voix de l'opéra résonne à nouveau dans la rue. Arachne ferme les yeux, le soleil tombe sur son visage paisible, doux comme les printemps qu'elle a déjà perdus."
  },
  AvgDialog_131230_Content_86 = {
    Text = "Le fuseau tourne. Le chant ne s'arrête jamais. Les gens passent, et d'innombrables fils invisibles se rassemblent et se tissent autour d'elle."
  },
  AvgDialog_131230_Content_87 = {
    Text = "Tu regardes le visage souriant d'Arachne. Tu vois qu'il n'y a rien autour d'elle."
  },
  AvgDialog_131230_Content_9 = {
    Text = "Tout semble inchangé, même les rouilles ébréchées sur les enseignes des boutiques sont identiques à celles de tes souvenirs."
  },
  AvgDialog_131231_Content_1 = {
    Text = "Ouf... Heureusement, juste à temps..."
  },
  AvgDialog_131231_Content_10 = {
    Text = "Sorel plissa légèrement les yeux en scrutant Arachne. Elle réalisa que son art de lire les gens, dont elle était si fière, avait complètement échoué. Elle ne parvenait pas à discerner le passé de la personne devant elle, ni à deviner ses désirs."
  },
  AvgDialog_131231_Content_11 = {
    Text = "Elle oublia tous les détails du visage qu'elle avait mémorisés en un clin d'œil. Les coins de la bouche de Sorel se soulevèrent avec amusement."
  },
  AvgDialog_131231_Content_12 = {
    Text = "Mesdames et messieurs, vos invités fascinants. Ce salon restera gravé dans ma mémoire pour toujours. Veuillez vous asseoir."
  },
  AvgDialog_131231_Content_13 = {
    Text = "Sorel se retourne et s'assoit sur le canapé, levant la main pour vous faire signe."
  },
  AvgDialog_131231_Content_14 = {
    Text = "J'ai eu plusieurs occasions de croiser «la bonté», il est venu me trouver pour demander mon refuge."
  },
  AvgDialog_131231_Content_15 = {
    Text = "Vous m'avez sauvé. Je ne peux pas vous voir clairement, mais je peux dire que vous n'avez aucune mauvaise intention."
  },
  AvgDialog_131231_Content_16 = {
    Text = "C'est exact, Madame Sorel. Nous sommes venus le sauver."
  },
  AvgDialog_131231_Content_17 = {
    Text = "Il n'est pas dans ce manoir."
  },
  AvgDialog_131231_Content_18 = {
    Text = "Mais tu viens de dire..."
  },
  AvgDialog_131231_Content_19 = {
    Text = "Comme tu peux le voir, mon manoir n'est pas sûr non plus."
  },
  AvgDialog_131231_Content_2 = {
    Text = "Après avoir confirmé l'état de Karen, tu te lèves et essuies la sueur froide de ton front."
  },
  AvgDialog_131231_Content_20 = {
    Text = "Sorel leva les bras, regardant les corps en désordre dans la pièce magnifique et bien rangée comme si elle exposait des trésors précieux."
  },
  AvgDialog_131231_Content_21 = {
    Text = "C'est un homme de bon cœur mais pas idiot. Je peux voir qu'il fait face à une situation très critique."
  },
  AvgDialog_131231_Content_22 = {
    Text = "Mon amitié avec lui n'est pas un secret pour beaucoup de gens. Le cacher dans le manoir n'est pas une décision judicieuse."
  },
  AvgDialog_131231_Content_23 = {
    Text = "Où est-il maintenant ?"
  },
  AvgDialog_131231_Content_24 = {
    Text = "Sorel se lève et se dirige vers une peinture à l'huile. Vous la suivez, contemplant l'image."
  },
  AvgDialog_131231_Content_25 = {Text = "C'est... !"},
  AvgDialog_131231_Content_26 = {
    Text = "Il y a quelques années, je suis allé au théâtre de Londinium pour voir une performance de la compagnie de danse du cygne. C'était à l'origine un simple engagement, mais j'ai été profondément frappé par sa danse."
  },
  AvgDialog_131231_Content_27 = {
    Text = "Ces dernières années, j'ai parfois visité les coulisses lors des représentations de la troupe de danse invitée. Nous n'avons pas de véritable relation, c'est pourquoi la troupe de danse à laquelle elle appartient est l'endroit le plus approprié pour placer cette « bonne » personne."
  },
  AvgDialog_131231_Content_28 = {
    Text = "Dans le tableau, Liz est vêtue d'une tenue de danse éthérée, bondissant haut dans les airs tel un cygne en plein vol."
  },
  AvgDialog_131231_Content_29 = {
    Text = "Liz... où est sa troupe de danse maintenant ?"
  },
  AvgDialog_131231_Content_3 = {
    Text = "Karen ne devrait pas avoir de problèmes, elle a été un peu affectée, après un certain temps de repos, elle devrait aller mieux."
  },
  AvgDialog_131231_Content_30 = {
    Text = "Suivant le fil du destin qui devenait progressivement clair, Arachne regarda par la fenêtre, vers cet endroit connecté au fil, caché par la forêt dense."
  },
  AvgDialog_131231_Content_31 = {
    Text = "Dans un endroit que tu connais parfaitement."
  },
  AvgDialog_131231_Content_4 = {
    Text = "Je me souviens clairement de chaque visage que j'ai vu, mais tu me donnes une impression étrange. Je ne peux pas être sûr de t'avoir déjà vu... Cela ne m'est jamais arrivé."
  },
  AvgDialog_131231_Content_5 = {
    Text = "Sorel prit la bouteille de vin sur la table basse qui n'avait pas été renversée et la versa dans le verre, traversant la pièce remplie de cadavres en fusion, avant de tendre le verre devant vous."
  },
  AvgDialog_131231_Content_6 = {
    Text = "Quarante ans de porto vieilli, ma collection personnelle, les hyènes en bas n'ont pas le droit de le goûter. Peu importe qui vous êtes et pourquoi vous êtes ici, je pense que ce vin devrait vous appartenir."
  },
  AvgDialog_131231_Content_7 = {
    Text = "Nous sommes venus pour «la bonté», Madame Sorel."
  },
  AvgDialog_131231_Content_8 = {
    Text = "Arachne prit le verre et fit un signe de tête en souriant à Sorel."
  },
  AvgDialog_131231_Content_9 = {
    Text = "Lorsqu'elle ne parle pas, elle est aussi discrète qu'une toile d'araignée dans la lumière du matin. Une fois qu'elle commence à parler, toute la brillance de la pièce semble se concentrer sur elle."
  },
  AvgDialog_131232_Content_1 = {
    Text = "Quelle bataille magnifique, grande sœur !."
  },
  AvgDialog_131232_Content_10 = {
    Text = "Toi et ton serviteur êtes des perdus du destin, je ne peux pas saisir le fil de votre destin. Mais tes capacités viennent de moi, je ne peux pas voir mon propre destin, et il en est de même pour toi."
  },
  AvgDialog_131232_Content_11 = {
    Text = "Toi et moi... c'est une guerre futile qui est vouée à l'impasse. Elle n'aurait pas dû se produire."
  },
  AvgDialog_131232_Content_12 = {
    Text = "Bien sûr, bien sûr. Pour toi, ces choses que nous avons été abandonnées devraient disparaître dans le cimetière du destin, être décomposées, s'évanouir ici, jusqu'à l'éternité, l'éternité."
  },
  AvgDialog_131232_Content_13 = {
    Text = "Hélas, tu ne peux pas le voir... Peu importe la puissance que tu possèdes, comment pourrais-tu rivaliser avec cette personne suprême ?"
  },
  AvgDialog_131232_Content_14 = {
    Text = "Tu le sais. Tu sais très bien que tout cela est vain. Mais tu ne peux pas arrêter de tisser des filets..."
  },
  AvgDialog_131232_Content_15 = {
    Text = "Puisque tu as déjà vu, tu ne peux pas supporter ces lignes enchevêtrées. Puisque tu as ce pouvoir, tu ne peux pas rester les bras croisés pendant que ces mondes plongent dans un chaos sans fin."
  },
  AvgDialog_131232_Content_16 = {
    Text = "Tu leur apportes une fausse paix, et tu les conduis sur un chemin qui mènera inévitablement à la destruction."
  },
  AvgDialog_131232_Content_17 = {
    Text = "Quel homme pathétique, Arachne."
  },
  AvgDialog_131232_Content_18 = {
    Text = "C'est notre destin, Nefraea."
  },
  AvgDialog_131232_Content_19 = {
    Text = "Ah... il semble que je sois un peu fatigué. Débattre avec un imbécile est la chose la plus ennuyeuse au monde."
  },
  AvgDialog_131232_Content_2 = {
    Text = "Le bar animé est devenu silencieux, les corps renversés se transforment en un liquide noir collant et en poudre, se dissipant dans la lumière douce."
  },
  AvgDialog_131232_Content_20 = {
    Text = "Bienvenue dans le deuxième acte de cette histoire. C'est ta scène, mais à partir de maintenant, cette histoire sera écrite par moi."
  },
  AvgDialog_131232_Content_21 = {
    Text = "Le petit passage d'ouverture est le plus important, n'est-ce pas ? Quel nom devrions-nous lui donner... Ah, appelons-le « Rencontre à nouveau », qu'en pensez-vous ?"
  },
  AvgDialog_131232_Content_22 = {
    Text = "Nefraea était très satisfaite de son nom, elle trempa ses membres dans le vin vieux du verre avant de le porter à sa bouche, poussant un soupir d'extase."
  },
  AvgDialog_131232_Content_23 = {
    Text = "Enfin ce jour est arrivé, pour lequel je me suis préparé depuis si longtemps. Je vais vraiment profiter de cette histoire avec toi, ma chère grande sœur."
  },
  AvgDialog_131232_Content_24 = {
    Text = "Il n'y a plus d'occasion de vous interroger. Les griffes aiguisées de Nefraea glissent doucement sur le bord de la joue d'Arachne, puis elle tombe au sol avec son corps."
  },
  AvgDialog_131232_Content_25 = {
    Text = "Attends... !"
  },
  AvgDialog_131232_Content_26 = {
    Text = "Elle n'est pas ici, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131232_Content_27 = {
    Text = "Un bruit de bouillonnement s'élève, et le liquide noir glisse à nouveau du visage du cadavre."
  },
  AvgDialog_131232_Content_28 = {
    Text = "«Romantique», ses yeux fascinants gardent toujours la courbure d'un sourire, une araignée noire se déplace de manière désordonnée dans son corps, apparaissant et disparaissant dans ses orbites brillantes. Ses lèvres élégantes ne produisent plus aucun son."
  },
  AvgDialog_131232_Content_29 = {Text = "C'est..."},
  AvgDialog_131232_Content_3 = {
    Text = "Nefraea et Arachne sont toujours assises l'une en face de l'autre, elle renverse un verre de vin et le pousse vers Arachne."
  },
  AvgDialog_131232_Content_30 = {
    Text = "Elle a tué cet automate, laissant une marque sur elle, polluant son destin, lui permettant d'exister brièvement en elle."
  },
  AvgDialog_131232_Content_31 = {
    Text = "Arachne se présenta devant le Pair secret, tendit la main vers le sommet de la tête «romantique» et fixa le fil qui avait presque disparu."
  },
  AvgDialog_131232_Content_32 = {
    Text = "... Tu as vu quelque chose ?"
  },
  AvgDialog_131232_Content_33 = {
    Text = "D'autres énigmes secrètes ont également été polluées, je ne peux pas percevoir leur existence à travers le filet du destin... mais le destin de «romantique» est lié à eux."
  },
  AvgDialog_131232_Content_34 = {
    Text = "Elle m'a parlé de l'emplacement de «la bonté»."
  },
  AvgDialog_131232_Content_35 = {
    Text = "Arachne lâche le fil du Destin, en arrangeant cette belle frange pour «romantique»."
  },
  AvgDialog_131232_Content_36 = {
    Text = "Les capacités de Nefraea proviennent de moi, un destin pollué par elle, que je ne peux pas voir, et de nombreuses capacités sont également limitées par cela."
  },
  AvgDialog_131232_Content_37 = {
    Text = "Vous êtes un fragment du Divin — quelqu'un dont le destin nous est invisible. C'est pourquoi j'ai besoin de votre aide, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_131232_Content_38 = {
    Text = "Soyez sans souci, même juste pour retourner à Kadath, je dois la résoudre."
  },
  AvgDialog_131232_Content_39 = {
    Text = "Pourquoi elle cherche ces objets secrets ?"
  },
  AvgDialog_131232_Content_4 = {
    Text = "Bien que mademoiselle «Romantique» ne soit plus là, le vin ici ne devrait pas être gaspillé."
  },
  AvgDialog_131232_Content_40 = {
    Text = "Ces secrets deviendront la source de sa force."
  },
  AvgDialog_131232_Content_41 = {
    Text = "Alors, nous devons nous dépêcher de partir... Trouver ces pairs secrets, ainsi que ces cendres de dimension qui peuvent t'aider à tisser ton destin..."
  },
  AvgDialog_131232_Content_42 = {
    Text = "Où est ce secret appelé « bienveillance » maintenant ?"
  },
  AvgDialog_131232_Content_43 = {
    Text = "«Romantique» a réussi à le prévenir du danger avant de tomber. Il se cache désormais, protégé par un vieil ami à vous."
  },
  AvgDialog_131232_Content_44 = {
    Text = "Vieux ami ?..."
  },
  AvgDialog_131232_Content_45 = {
    Text = "Suivez-moi, {Male=Mr.,Female=Miss} Gardien. Le grand salon de Madame Sorel est sur le point de commencer."
  },
  AvgDialog_131232_Content_5 = {
    Text = "Tu veux essayer ? Je suis celui qui te comprend vraiment, bien plus que ce « Pair secret » que tu as mis en scène."
  },
  AvgDialog_131232_Content_6 = {
    Text = "Arachne n'hésita pas, elle sourit en levant son verre et en prenant une petite gorgée."
  },
  AvgDialog_131232_Content_7 = {
    Text = "Tu n'es pas faite pour ce métier, Nefraea. À part l'amertume et l'acidité, il n'a plus aucun goût."
  },
  AvgDialog_131232_Content_8 = {
    Text = "Je l'appelle « Destin ». Aimez–vous son goût ?"
  },
  AvgDialog_131232_Content_9 = {
    Text = "Arachne n'a pas prêté attention au regard plein d'attente de Nefraea. Elle a lentement bu le vin dans sa coupe et a doucement reposé le verre sur la table."
  },
  AvgDialog_132684_Content_1 = {
    Text = "<Small:<LightGray:zi......? (hum......?)>>"
  },
  AvgDialog_132684_Content_10 = {
    Text = "C'est vrai, et étant donné que Mizag a déjà une tradition de taquiner les gens aujourd'hui pour communiquer des émotions, l'école ne punira pas ce genre de « blague » qui n'est pas excessive."
  },
  AvgDialog_132684_Content_11 = {
    Text = "Cui ! Cui, Cui — !<Small:<LightGray:(Monsieur Doll, tu es en train de pincer ma main et mon visage, n'est-ce pas ?)>>"
  },
  AvgDialog_132684_Content_12 = {
    Text = "Bien que le ton soit aussi froid que d'habitude, voire légèrement acerbe, tu es très sûr que les coins des lèvres de Doll se sont au moins relevés de 2 millimètres."
  },
  AvgDialog_132684_Content_13 = {
    Text = "Désolé, Gardien. Le traducteur de Cœur d'argent semble avoir un petit problème, mais ce n'est pas grave, le réactif inverse pourra être synthétisé demain matin."
  },
  AvgDialog_132684_Content_14 = {
    Text = "Tu regardes Doll avec un visage choqué, même si tu n'as qu'un cerveau de loutre en ce moment, tu peux clairement voir que le réactif derrière elle est en état terminé."
  },
  AvgDialog_132684_Content_15 = {
    Text = "Professeur, chercher Mosk ?"
  },
  AvgDialog_132684_Content_16 = {
    Text = "!!!petit charbon—"
  },
  AvgDialog_132684_Content_17 = {
    Text = "Ji—<Small:<LightGray:(Chef——)>>"
  },
  AvgDialog_132684_Content_18 = {
    Text = "Étant donné que nous avons des personnes expérimentées concernant ce groupe, je pense qu'une journée passée avec elles devrait aider notre Gardien à mieux se souvenir."
  },
  AvgDialog_132684_Content_19 = {
    Text = "Mosk, occupe-toi de la tâche de %player%."
  },
  AvgDialog_132684_Content_2 = {Text = "*rebond"},
  AvgDialog_132684_Content_20 = {
    Text = "*Hourra ! Petit charbon, jouons ensemble"
  },
  AvgDialog_132684_Content_21 = {
    Text = "Cui !<Small:<LightGray:(Jouons ensemble !)>>"
  },
  AvgDialog_132684_Content_22 = {
    Text = "Ji—<Small:<LightGray:(Non, Ramona, sauve-moi—)>>"
  },
  AvgDialog_132684_Content_23 = {Text = "Toux."},
  AvgDialog_132684_Content_24 = {
    Text = "Partenaire, il n'y a rien d'important aujourd'hui, ne t'inquiète pas."
  },
  AvgDialog_132684_Content_25 = {
    Text = "Je vais également libérer du temps aujourd'hui pour assurer ta sécurité."
  },
  AvgDialog_132684_Content_26 = {
    Text = "Bien que ce soit dit, il est évident qu'elle a également été complètement contrôlée par tes peluches incroyablement douces, tout comme Mosk."
  },
  AvgDialog_132684_Content_27 = {
    Text = "Tic, tic tic tic...<Small:<LightGray: (Y a-t-il encore quelqu'un pour sauver, William, l'Aîné...)>>"
  },
  AvgDialog_132684_Content_28 = {
    Text = "Au fait, William est allé en mission aujourd'hui, il ne rentrera que très tard."
  },
  AvgDialog_132684_Content_29 = {
    Text = "*Boire du thé <Small:<LightGray:(Ouf, une occasion rare, mon étudiant le plus préoccupant et le plus important, profitons de cette journée pour tout laisser de côté et se détendre.)>>"
  },
  AvgDialog_132684_Content_3 = {
    Text = "*frotter le visage"
  },
  AvgDialog_132684_Content_30 = {
    Text = "À ce moment-là, un certain aîné au loin."
  },
  AvgDialog_132684_Content_31 = {Text = "Atchoum"},
  AvgDialog_132684_Content_32 = {
    Text = "Étrange, j'ai inexplicablement un mauvais pressentiment."
  },
  AvgDialog_132684_Content_33 = {
    Text = "Il vaut mieux rentrer à l'école plus tôt aujourd'hui."
  },
  AvgDialog_132684_Content_34 = {
    Text = "Mizag du poisson d'avril est aussi très pacifique."
  },
  AvgDialog_132684_Content_35 = {
    Text = "Félicitations, félicitations."
  },
  AvgDialog_132684_Content_4 = {Text = "???!!!"},
  AvgDialog_132684_Content_5 = {
    Text = "Cui Cui Cui Cui Cui ! Yiyi Yiyi Yiyi Yiyi !!!<Small:<LightGray:(Je suis devenu un loutre ! Ramona, sauvez-moi !)>>"
  },
  AvgDialog_132684_Content_6 = {Text = "新增"},
  AvgDialog_132684_Content_7 = {
    Text = "Bonne nouvelle, l'effet de ce spray n'est pas irréversible, et la préparation de l'antidote est également très simple, il est clair que l'autre partie n'a pas de mauvaises intentions."
  },
  AvgDialog_132684_Content_8 = {
    Text = "Une meilleure nouvelle, oser utiliser le cadeau de ce petit menteur qui ne pense même pas, échanger temporairement pour le cerveau d'une loutre pourrait vraiment t'aider à te réveiller."
  },
  AvgDialog_132684_Content_9 = {
    Text = "Donc, cette conversion temporaire ne causera aucun dommage au Gardien ?"
  },
  AvgDialog_13733_Content_1 = {
    Text = "Rite sacrificiel rouge"
  },
  AvgDialog_13733_Content_10 = {
    Text = "Heh, tu ne peux jamais compter sur l'intuition des Lemwahsians. Garde les yeux grands ouverts et regarde..."
  },
  AvgDialog_13733_Content_11 = {
    Text = "Prine sortit un couteau rituel de sa manche et, sans hésitation, s'entailla le poignet."
  },
  AvgDialog_13733_Content_12 = {
    Text = "Du sang écarlate goutte sur le cercle magique tracé au soufre, et comme par enchantement, un miracle se produit —"
  },
  AvgDialog_13733_Content_13 = {
    Text = "Telle une goutte d'eau dans le désert, le cercle magique absorba le sang frais, irradiant des anneaux de lumière rouge sombre"
  },
  AvgDialog_13733_Content_14 = {
    Text = "Ils sont comme des flammes sous le ciel obscur, léchant avidement les sables balayés par le vent, comme s'ils dévoraient la terre entière."
  },
  AvgDialog_13733_Content_15 = {
    Text = "Vous avez vu ça ? Voilà le véritable instant magique ! Hahaha !"
  },
  AvgDialog_13733_Content_16 = {
    Text = "Hahaha...<Big:Urgh !!!>"
  },
  AvgDialog_13733_Content_17 = {
    Text = "Prine « plouf » tomba à genoux, agrippant sa gorge de manière incontrôlable."
  },
  AvgDialog_13733_Content_18 = {
    Text = "Les chaînes qui le relient à Uvhash se tendent brusquement, liant étroitement leur chair et leurs âmes."
  },
  AvgDialog_13733_Content_19 = {
    Text = "Hmm... Quoi... ?"
  },
  AvgDialog_13733_Content_2 = {
    Text = "L'Edge du Désert Kuxi\nSite Rituel"
  },
  AvgDialog_13733_Content_20 = {
    Text = "Uvhash ne pouvait plus maintenir sa posture décontractée."
  },
  AvgDialog_13733_Content_21 = {
    Text = "Il fut soudainement renversé par une force invisible, fixant d'un regard hébété le cercle magique devenu incontrôlable devant lui"
  },
  AvgDialog_13733_Content_22 = {Text = "Ugh..."},
  AvgDialog_13733_Content_23 = {
    Text = "<Big:AHHH !>"
  },
  AvgDialog_13733_Content_24 = {
    Text = "Prinn gisait au sol, fixant d'un regard haineux Uvhash qui se débattait, et se mit à rire."
  },
  AvgDialog_13733_Content_25 = {
    Text = "C'est douloureux... ? Bien, ça devrait l'être."
  },
  AvgDialog_13733_Content_26 = {
    Text = "En cet instant, nos consciences sont étroitement liées l'une à l'autre..."
  },
  AvgDialog_13733_Content_27 = {
    Text = "As-tu vu comment les chiens Lemwash ont massacré ma famille et profané ma femme... l'as-tu ressenti..."
  },
  AvgDialog_13733_Content_28 = {
    Text = "<Big:Réponds–moi, espèce de @1 d'imbécile !>"
  },
  AvgDialog_13733_Content_29 = {Text = "Heh heh..."},
  AvgDialog_13733_Content_3 = {
    Text = "Bien, d›abord saupoudrer une couche de soufre, puis de la poudre de charbon..."
  },
  AvgDialog_13733_Content_30 = {
    Text = "Ne t'emballe pas trop... vieil homme."
  },
  AvgDialog_13733_Content_31 = {
    Text = "Dès que je me libérerai de ces chaînes, la première personne que je mettrai en pièces, ce sera toi — ugh !!"
  },
  AvgDialog_13733_Content_32 = {
    Text = "Malheureusement, il semble que ton souhait ne se réalisera pas cette fois..."
  },
  AvgDialog_13733_Content_33 = {
    Text = "Pulin haletait lourdement, tremblant tandis qu'il agrippait la chaîne invisible, puis la tira d'un coup sec —"
  },
  AvgDialog_13733_Content_34 = {
    Text = "Les chaînes autrefois incassables se sont à présent brisées."
  },
  AvgDialog_13733_Content_35 = {
    Text = "Hehe@3 Ah@1 Ah !!"
  },
  AvgDialog_13733_Content_36 = {
    Text = "Prin laisse échapper un cri d'agonie tandis que la chair de son visage se putréfie et se détache comme de l'écorce, révélant la chair vive en dessous."
  },
  AvgDialog_13733_Content_37 = {
    Text = "Le cercle magique ouvre ses mâchoires sombres et béantes, dévorant sa chair morceau par morceau jusqu'à ce que le sorcier soit réduit à un squelette creux."
  },
  AvgDialog_13733_Content_38 = {
    Text = "J'ai sacrifié ma chair, mon âme, et tout le reste... et toi ?"
  },
  AvgDialog_13733_Content_39 = {
    Text = "Vous n'atteindrez jamais la véritable liberté tant que vous n'aurez pas tué 10 000 chiens Lermvahi !"
  },
  AvgDialog_13733_Content_4 = {
    Text = "Non, voyons ce que dit le livre..."
  },
  AvgDialog_13733_Content_40 = {
    Text = "Uvhash se releva lentement."
  },
  AvgDialog_13733_Content_41 = {
    Text = "Son visage fut brûlé en cendres noires par des flammes invisibles, s'effritant au moindre souffle de vent."
  },
  AvgDialog_13733_Content_42 = {Text = "Heh..."},
  AvgDialog_13733_Content_43 = {
    Text = "« La vraie liberté »...? Qu'est–ce que c'est ?"
  },
  AvgDialog_13733_Content_44 = {
    Text = "Le guerrier calciné se tient au milieu des flammes ardentes. Ses yeux sont rouge sang, et seul un tremblement rauque s'échappe de sa gorge."
  },
  AvgDialog_13733_Content_45 = {
    Text = "Moi, Uvhash, je n'ai véritablement jamais eu qu'une seule préoccupation —"
  },
  AvgDialog_13733_Content_46 = {
    Text = "Il se rua à la vitesse de l'éclair, plaquant le sorcier au sol."
  },
  AvgDialog_13733_Content_47 = {
    Text = "Puis il découvrit ses crocs acérés et mordit sauvagement la gorge du sorcier."
  },
  AvgDialog_13733_Content_48 = {
    Text = "<Red:C'est du sang !>"
  },
  AvgDialog_13733_Content_49 = {Text = "M. Prinn !"},
  AvgDialog_13733_Content_5 = {
    Text = "À moins de cinquante mètres du champ de bataille, Pulin s›affaire avec ardeur."
  },
  AvgDialog_13733_Content_50 = {
    Text = "<Shake:Cette vie, pour toi... vengeance@2 aide–moi...>"
  },
  AvgDialog_13733_Content_51 = {
    Text = "T'aider ? Vieil homme, tu te trompes...?"
  },
  AvgDialog_13733_Content_52 = {
    Text = "Une proie n'a pas le droit d'exiger quoi que ce soit d›Uvhash."
  },
  AvgDialog_13733_Content_53 = {
    Text = "Je t›écoute non pas à cause de ce maudit contrat, mais parce que je peux briser ton jouet de chaîne en fer à tout moment."
  },
  AvgDialog_13733_Content_54 = {
    Text = "Le temps du jeu est terminé. Maintenant, je veux que tu regardes bien—"
  },
  AvgDialog_13733_Content_55 = {
    Text = "Voici comment j›ai massacré tes ennemis, tes semblables, et chaque créature vivante dont tu as été témoin..."
  },
  AvgDialog_13733_Content_56 = {
    Text = "<Change>Démon... espèce de démon..."
  },
  AvgDialog_13733_Content_57 = {
    Text = "Le sang de Prinn coula abondamment dans le cercle magique, rendant la lumière cramoisie terne"
  },
  AvgDialog_13733_Content_58 = {
    Text = "Il a sacrifié sa propre vie en échange de la liberté d'Uvhash."
  },
  AvgDialog_13733_Content_59 = {
    Text = "Héhé... Aah@4..."
  },
  AvgDialog_13733_Content_6 = {
    Text = "Uvhash était assis au centre du cercle magique tracé avec de la poudre de soufre, à la demande de Pulin."
  },
  AvgDialog_13733_Content_60 = {
    Text = "Uvhash releva lentement la tête, du sang s›attardant encore sur ses lèvres, ses yeux déjà consumés par les ténèbres."
  },
  AvgDialog_13733_Content_61 = {
    Text = "Il se transforma en une véritable bête. Ou plutôt, c›était sa forme originelle."
  },
  AvgDialog_13733_Content_62 = {
    Text = "<Red:C›est revenu, tout est revenu...>"
  },
  AvgDialog_13733_Content_7 = {
    Text = "Huff... huff..."
  },
  AvgDialog_13733_Content_8 = {
    Text = "Impressionnant, tu arrives encore à t›endormir même dans cette situation..."
  },
  AvgDialog_13733_Content_9 = {
    Text = "Il y a une question technique que j›aimerais vous poser, M. Pulin.\nLa poudre que vous avez répandue ne sera-t-elle pas emportée par le vent?"
  },
  AvgDialog_13734_Content_1 = {
    Text = "Huff... Je t›ai enfin rattrapé.\nJe te préviens, Uvhash. Tu connais les conséquences d›un départ sans permission, n›est-ce pas?"
  },
  AvgDialog_13734_Content_10 = {
    Text = "Vous avez enfin atteint la fin de votre voyage. Prinn laissa échapper quelques rires étranges, son corps tremblant sous les flammes de la vengeance."
  },
  AvgDialog_13734_Content_11 = {
    Text = "<Shake:Allons-y, Uvhash...>"
  },
  AvgDialog_13734_Content_12 = {
    Text = "<Red:Va et tue à cœur joie.>"
  },
  AvgDialog_13734_Content_2 = {Text = "Chut !!"},
  AvgDialog_13734_Content_3 = {
    Text = "Uvhash était accroupi sur une haute dune, émettant un sifflement impatient par les narines, comme une bête de chasse importunée par des insectes."
  },
  AvgDialog_13734_Content_4 = {
    Text = "Ses lèvres légèrement entrouvertes, ses narines frémissant faiblement, et la lueur rouge sang dans ses yeux devint plus intense que jamais."
  },
  AvgDialog_13734_Content_5 = {
    Text = "<RedShake:Je l'ai trouvé, je l'ai trouvé...>"
  },
  AvgDialog_13734_Content_6 = {
    Text = "Vous suivez son regard vers le bas—"
  },
  AvgDialog_13734_Content_7 = {
    Text = "D›innombrables petits points noirs sont éparpillés sur les dunes ondulantes, comme des fourmis grouillant sur une table de sable."
  },
  AvgDialog_13734_Content_8 = {
    Text = "Le fracas des armes, les rugissements et le bruit des sabots emplissent l›air, déployant devant vous une grandiose scène de guerre."
  },
  AvgDialog_13734_Content_9 = {
    Text = "Les Lemwashiens, Les Léoniens... Bien, très bien."
  },
  AvgDialog_13735_Content_1 = {
    Text = "Expédition solaire"
  },
  AvgDialog_13735_Content_10 = {
    Text = "Il restait lié par des chaînes invisibles, assis maladroitement sur le sol, se fondant presque dans l'obscurité."
  },
  AvgDialog_13735_Content_11 = {
    Text = "...Je ne m'attendais pas à ce que vous soyez éveillé."
  },
  AvgDialog_13735_Content_12 = {
    Text = "Le <Yellow:Golem> n'a pas besoin de dormir."
  },
  AvgDialog_13735_Content_13 = {Text = "Golem...?"},
  AvgDialog_13735_Content_14 = {
    Text = "Heh... Arrête de faire semblant."
  },
  AvgDialog_13735_Content_15 = {
    Text = "Tu peux voir les chaînes sur moi, donc tu dois savoir ce qu'est un Golem."
  },
  AvgDialog_13735_Content_16 = {
    Text = "Tu ne t'attendais pas à ce qu'il remarque ton regard en apparence nonchalant.\nIl possède véritablement l'instinct d'une bête."
  },
  AvgDialog_13735_Content_17 = {
    Text = "Mon enseignant m'a dit un jour..."
  },
  AvgDialog_13735_Content_18 = {
    Text = "Dans la Rome antique, un alchimiste fou a créé le tout premier Golem au prix de nombreux Sacrifices humains."
  },
  AvgDialog_13735_Content_19 = {
    Text = "C'est aussi l'existence la plus proche d'un Éveilleur dans les textes anciens."
  },
  AvgDialog_13735_Content_2 = {
    Text = "Désert de Kusi Nord, Nuit"
  },
  AvgDialog_13735_Content_20 = {
    Text = "Ce Golem, c'est toi, n'est-ce pas?"
  },
  AvgDialog_13735_Content_21 = {
    Text = "C'est exact... C'est moi. Je suis devenu l'homme de main de <Blue:Caligula> et j'ai tué beaucoup de gens pour lui."
  },
  AvgDialog_13735_Content_22 = {
    Text = "Ensuite, ils n'ont plus eu besoin de moi et m'ont enfermé dans un endroit souterrain si sombre que je ne pouvais même pas voir ma main devant mon visage, jusqu'à ce que cette personne me libère."
  },
  AvgDialog_13735_Content_23 = {
    Text = "Uvhash parle, ses yeux se tournant vers Prine, qui ronfle encore dans la tente."
  },
  AvgDialog_13735_Content_24 = {
    Text = "—Quelle est la condition?"
  },
  AvgDialog_13735_Content_25 = {
    Text = "La condition est de lui servir comme un chien et de tuer de nombreux Lemvashi sur le champ de bataille."
  },
  AvgDialog_13735_Content_26 = {
    Text = "Ensuite, chacun part de son côté et vit sa propre vie."
  },
  AvgDialog_13735_Content_27 = {
    Text = "Uvhash s'étira confortablement, s'étalant sur la dune, les jambes écartées."
  },
  AvgDialog_13735_Content_28 = {
    Text = "Ces chaînes ne peuvent pas te retenir. Pourquoi ne pas simplement tuer le sorcier et partir?"
  },
  AvgDialog_13735_Content_29 = {
    Text = "Parce qu'il a dit : « Il y a beaucoup de gens sur le champ de bataille. »"
  },
  AvgDialog_13735_Content_3 = {
    Text = "Rrron... Rrron... Pfff..."
  },
  AvgDialog_13735_Content_30 = {
    Text = "<Red:Là où il y a beaucoup de gens, il y aura beaucoup de sang.>"
  },
  AvgDialog_13735_Content_31 = {
    Text = "<RedShake:Tu sais, ça fait presque mille ans que je n'ai pas goûté à ce sang...>"
  },
  AvgDialog_13735_Content_32 = {Text = "新增"},
  AvgDialog_13735_Content_33 = {
    Text = "Ce type n'a pas l'air de quelqu'un qui tient ses promesses. Et s'il te trompait ?"
  },
  AvgDialog_13735_Content_34 = {
    Text = "Seulement le tuer. Simple, non ?"
  },
  AvgDialog_13735_Content_35 = {Text = "新增"},
  AvgDialog_13735_Content_36 = {
    Text = "Il y a à admettre qu'il a marqué un point."
  },
  AvgDialog_13735_Content_37 = {
    Text = "La brise du soir souffle doucement, les dunes ondulantes s'étendent à perte de vue devant vous, ne laissant que deux silhouettes minuscules sous l'immensité du ciel."
  },
  AvgDialog_13735_Content_38 = {
    Text = "Vous levez les yeux vers le ciel étoilé."
  },
  AvgDialog_13735_Content_39 = {
    Text = "Pour passer cette longue nuit, vous décidez d'échanger quelques expériences avec le Golem devant vous."
  },
  AvgDialog_13735_Content_4 = {
    Text = "Dans le silence de la nuit, les ronflements tonitruants de Prin indiquent que le petit incident de la journée n'a pas affecté son sommeil profond."
  },
  AvgDialog_13735_Content_40 = {
    Text = "Être enfermé sous terre, ça doit être dur.\nUne fois la promesse tenue, tu retrouveras ta liberté. Comment te sens-tu maintenant ?"
  },
  AvgDialog_13735_Content_41 = {
    Text = "Et toi ?\nTu es libre de l'esclavage depuis longtemps, errant dans le désert pour gagner ta vie. Qu'est-ce que ça fait ?"
  },
  AvgDialog_13735_Content_42 = {Text = "新增"},
  AvgDialog_13735_Content_43 = {
    Text = "Pas bien du tout. On ne voit même pas le soleil dans cet endroit maudit..."
  },
  AvgDialog_13735_Content_44 = {
    Text = "Tu dois être vraiment aveugle. Tu ne vois pas l'énorme soleil dans le désert ?"
  },
  AvgDialog_13735_Content_45 = {
    Text = "Tu ne comprends pas. Je parle du soleil doux, lumineux et chaleureux... Tu ne verras pas ça dans le désert."
  },
  AvgDialog_13735_Content_46 = {
    Text = "Vous laissez échapper un bâillement, la somnolence vous gagnant peu à peu.\nÀ mesure que votre garde se relâchait, la conversation devenait plus décontractée."
  },
  AvgDialog_13735_Content_47 = {
    Text = "À votre grande surprise, Uvhash est un auditeur plutôt convenable."
  },
  AvgDialog_13735_Content_48 = {
    Text = "Tu ne vas peut-être pas le croire, mais j'ai en fait une mission à accomplir..."
  },
  AvgDialog_13735_Content_49 = {
    Text = "Quand j'aurai fini tout ce que j'ai à faire, je trouverai sans faute un endroit pour me prélasser au soleil et manger plein, plein de petits gâteaux..."
  },
  AvgDialog_13735_Content_5 = {
    Text = "Vous n'en pouvez plus et finissez par sortir de la tente."
  },
  AvgDialog_13735_Content_50 = {
    Text = "...difficile à comprendre."
  },
  AvgDialog_13735_Content_51 = {
    Text = "Le Golem est né des ténèbres et craint naturellement la lumière du soleil. Près d'un millénaire d'emprisonnement a renforcé son aversion pour la lumière."
  },
  AvgDialog_13735_Content_52 = {
    Text = "Je te plains sincèrement ; se prélasser au soleil est la chose la plus agréable au monde..."
  },
  AvgDialog_13735_Content_53 = {
    Text = "C'est dommage que même un tel souhait soit difficile à réaliser pour moi..."
  },
  AvgDialog_13735_Content_54 = {
    Text = "Le vent se lève.\nLe sable fin flotte, tissant des voiles jaune pâle qui dérivent doucement sous le ciel étoilé de la nuit."
  },
  AvgDialog_13735_Content_55 = {
    Text = "Vous entendez le vent pur venu de loin et finissez par sombrer dans le sommeil."
  },
  AvgDialog_13735_Content_56 = {Text = "新增"},
  AvgDialog_13735_Content_57 = {
    Text = "Nord du désert de Kusi, journée"
  },
  AvgDialog_13735_Content_58 = {
    Text = "C'est quoi ce délire ! Tu n'avais pas juré il y a quelques jours qu'il n'y aurait pas de tempêtes de sable ?!"
  },
  AvgDialog_13735_Content_59 = {
    Text = "Pulin lança un regard furieux et pointa du doigt la tempête de sable qui approchait depuis l'horizon."
  },
  AvgDialog_13735_Content_6 = {Text = "Si beau..."},
  AvgDialog_13735_Content_60 = {
    Text = "Maintenant dis-moi, <Big:Qu'est-ce que c'est que ça@1 ?>"
  },
  AvgDialog_13735_Content_61 = {Text = "Uh"},
  AvgDialog_13735_Content_62 = {
    Text = "Avant que vous n'«entriez dans le rêve», le propriétaire d'origine avait en effet fait quelques promesses peu sincères pour plumer ce gros pigeon."
  },
  AvgDialog_13735_Content_63 = {
    Text = "Ce n'est pas le moment de discuter ; une tempête de sable arrive. Courir !"
  },
  AvgDialog_13735_Content_64 = {
    Text = "Après avoir parlé, vous avez foncé à toute vitesse, laissant Pulin loin derrière."
  },
  AvgDialog_13735_Content_65 = {
    Text = "<Big:Hé... Arrête-toi !>"
  },
  AvgDialog_13735_Content_66 = {
    Text = "Tempête de sable ? C'est quoi ça ? Le paysage est joli."
  },
  AvgDialog_13735_Content_67 = {
    Text = "Uvhash courut nonchalamment à vos côtés, les yeux rivés sans faillir sur le lointain."
  },
  AvgDialog_13735_Content_68 = {
    Text = "Vous n'avez jamais vu de tempête de sable ?"
  },
  AvgDialog_13735_Content_69 = {
    Text = "Uvhash a haussé les épaules."
  },
  AvgDialog_13735_Content_7 = {
    Text = "Bonsoir, M. Guide."
  },
  AvgDialog_13735_Content_70 = {
    Text = "Mes activités passées se limitaient à l'intérieur de la ville de Rome, il y a donc beaucoup de choses que je n'ai jamais vues."
  },
  AvgDialog_13735_Content_71 = {
    Text = "<Shake:Euh... Argh...>"
  },
  AvgDialog_13735_Content_72 = {
    Text = "Tiré par les chaînes, Prin, qui traînait loin derrière vous tous, fut projeté dans les airs."
  },
  AvgDialog_13735_Content_73 = {
    Text = "<Shake:Plus lentement... plus lentement... Je vais mourir...>"
  },
  AvgDialog_13735_Content_74 = {
    Text = "Tss. Presque oublié ce vieil homme."
  },
  AvgDialog_13735_Content_75 = {
    Text = "Uvhash fit demi-tour, soulevant sans effort le corps dodu du magicien."
  },
  AvgDialog_13735_Content_76 = {
    Text = "Que... qu'est-ce que tu comptes faire ?"
  },
  AvgDialog_13735_Content_77 = {
    Text = "Rien du tout, juste vous aider à courir un peu plus vite."
  },
  AvgDialog_13735_Content_78 = {
    Text = "En disant cela, Uvhash cala facilement le magicien sous son bras, fit un pas en avant et courba son corps comme un arc."
  },
  AvgDialog_13735_Content_79 = {
    Text = "Hé... je te préviens, c›est pas le moment de jouer—<Big:Sifflement!!!>"
  },
  AvgDialog_13735_Content_8 = {Text = "!!"},
  AvgDialog_13735_Content_80 = {
    Text = "Uvhash s›élança brusquement, filant comme une flèche."
  },
  AvgDialog_13735_Content_81 = {
    Text = "Moi, toi... bon sang @1, pose-moi!"
  },
  AvgDialog_13735_Content_82 = {
    Text = "\nUvhash éclate d›un rire franc.\nLe son chevauche le vent, se mêlant aux sables dorés et à la poussière, filant joyeusement vers l›horizon."
  },
  AvgDialog_13735_Content_83 = {
    Text = "Ça, pas question. J›ai encore besoin de toi vivant pour m›aider à retrouver ma liberté!"
  },
  AvgDialog_13735_Content_9 = {
    Text = "Uvhash surgit soudain du coin, vous adressant un large sourire."
  },
  AvgDialog_13736_Content_1 = {
    Text = "Guide, Magicien et Esclave"
  },
  AvgDialog_13736_Content_10 = {
    Text = "Calcinées et sèches, avec des lignes de la paume rugueuses et sauvages — ce sont les mains d'un guerrier."
  },
  AvgDialog_13736_Content_100 = {
    Text = "Désolé, je n'ai rien à vous dire."
  },
  AvgDialog_13736_Content_101 = {
    Text = "Les mercenaires sont un groupe d'individus sans foi. Quant aux esclaves, ils ne peuvent pas comprendre la dignité et l'honneur."
  },
  AvgDialog_13736_Content_102 = {
    Text = "Vous et ce type, il n'y a aucune différence fondamentale entre vous deux."
  },
  AvgDialog_13736_Content_103 = {
    Text = "Mais j'ai bien dépassé l'âge de l'impulsivité."
  },
  AvgDialog_13736_Content_104 = {
    Text = "Premièrement, je ne peux pas vous vaincre.\nDeuxièmement, vous m'êtes encore quelque peu utile."
  },
  AvgDialog_13736_Content_105 = {
    Text = "Peu importe d'où vous venez, en cet instant précis, continuez à mener l'équipe, mon guide."
  },
  AvgDialog_13736_Content_11 = {
    Text = "<Gray:Jamila, 32 ans, ancienne mercenaire Mamulu, désormais guide du désert...>"
  },
  AvgDialog_13736_Content_12 = {
    Text = "Vous assimilez silencieusement votre nouvelle identité."
  },
  AvgDialog_13736_Content_13 = {
    Text = "On dirait que vous êtes «entré dans un rêve» à nouveau."
  },
  AvgDialog_13736_Content_14 = {
    Text = "Hé, qu'est–ce que vous marmonnez ? Si vous êtes réveillé, levez–vous vite. Mon <Blue:esclave> et moi avons des affaires urgentes à régler."
  },
  AvgDialog_13736_Content_15 = {
    Text = "L'homme petit et trapu en tenue singulière est votre employeur pour cette mission, <Blue:Ludwig Prin>."
  },
  AvgDialog_13736_Content_16 = {
    Text = "Il fit un geste impatient derrière lui avec un fouet."
  },
  AvgDialog_13736_Content_17 = {Text = "Hiss..."},
  AvgDialog_13736_Content_18 = {
    Text = "Uvhash—?!"
  },
  AvgDialog_13736_Content_19 = {
    Text = "Vous avez alors remarqué l'homme dissimulé derrière les dunes de sable."
  },
  AvgDialog_13736_Content_2 = {
    Text = "@An 2, le Pape perdit le pouvoir, et la monarchie s'éleva.\nLa ville sainte d'Acre devint une terre disputée.\n\nPar crainte des forces mameloukes menées par Baybars,\nle prince appela chacun à rejoindre la croisade et à reprendre la ville sainte d'Acre."
  },
  AvgDialog_13736_Content_20 = {
    Text = "Il maintenait une posture accroupie, ses longs bras reposant nonchalamment sur le sol, comme une bête prête à bondir."
  },
  AvgDialog_13736_Content_21 = {
    Text = "Voyant votre expression choquée, il sourit, révélant une rangée de dents blanches et acérées."
  },
  AvgDialog_13736_Content_22 = {
    Text = "Quoi ? Vous me connaissez ?"
  },
  AvgDialog_13736_Content_24 = {
    Text = "Avant que vous puissiez dire un mot, le sorcier fouetta violemment Youwu avec le long fouet qu'il tenait en main."
  },
  AvgDialog_13736_Content_25 = {
    Text = "L'ami, je vous conseille de ne pas lui parler."
  },
  AvgDialog_13736_Content_26 = {
    Text = "Ne vous laissez pas tromper par ses yeux et son nez d'apparence humaine ; c'est toujours une bête non civilisée, ou peut–être..."
  },
  AvgDialog_13736_Content_28 = {
    Text = "Un autre coup de fouet s'abattit violemment sur Youwu."
  },
  AvgDialog_13736_Content_29 = {
    Text = "C'est un <Red:démon>."
  },
  AvgDialog_13736_Content_3 = {
    Text = "À ce moment, la grande <Yellow:Expédition Orientale> reprend une fois encore..."
  },
  AvgDialog_13736_Content_30 = {
    Text = "Fouetté à de multiples reprises, Uvhash n'a même pas cillé."
  },
  AvgDialog_13736_Content_31 = {
    Text = "Il essuya le sang qui coulait de sa tempe, renifla sa main, puis lécha lentement le sang du bout de ses doigts."
  },
  AvgDialog_13736_Content_32 = {
    Text = "Regardez, vous voyez ça ? Même mon chien de garde est plus raisonnable que lui ! Il est pire qu'un animal, hahaha !"
  },
  AvgDialog_13736_Content_33 = {
    Text = "Hé... vieil homme, ta force est plus faible aujourd'hui.\nQuoi, tu n'arrives même plus à tenir le fouet ?"
  },
  AvgDialog_13736_Content_34 = {Text = "Hmph..."},
  AvgDialog_13736_Content_35 = {
    Text = "Les Bêtes sont des Bêtes parce qu'elles sont incapables de fermer leur gueule ou de reconnaître leur place."
  },
  AvgDialog_13736_Content_36 = {
    Text = "T'en fais pas, je vais <BigItalic:bien t'apprendre>—"
  },
  AvgDialog_13736_Content_37 = {
    Text = "La barbe de Prinn se hérissa de colère, puis il fonça vers Uvhash comme une balle rebondissante."
  },
  AvgDialog_13736_Content_38 = {Text = "Attends."},
  AvgDialog_13736_Content_39 = {
    Text = "Vous avez attrapé le poignet de Prin et l'avez tiré en arrière."
  },
  AvgDialog_13736_Content_4 = {Text = "新增"},
  AvgDialog_13736_Content_40 = {
    Text = "Donnez-moi le fouet."
  },
  AvgDialog_13736_Content_41 = {
    Text = "Lâchez-moi ! Laissez-moi donner une leçon à cette Bête..."
  },
  AvgDialog_13736_Content_42 = {
    Text = "M. Jamila, je suis désormais votre employeur. Pas besoin de vous expliquer ce qu'est un employeur, n'est-ce pas ?"
  },
  AvgDialog_13736_Content_43 = {
    Text = "Désolé, je sais seulement que je suis le Guide de ce voyage.\nPuisque je suis le Guide, vous devrez m'écouter."
  },
  AvgDialog_13736_Content_44 = {
    Text = "Sinon, je pars maintenant, et vous vous rendrez sur le <Blue:champ de bataille> par vous-mêmes."
  },
  AvgDialog_13736_Content_45 = {
    Text = "<Shake:Hé, hé...! Discutons-en calmement...>"
  },
  AvgDialog_13736_Content_46 = {
    Text = "Une chose de plus."
  },
  AvgDialog_13736_Content_47 = {
    Text = "Vous froncez les sourcils en regardant Uvhash."
  },
  AvgDialog_13736_Content_48 = {
    Text = "Vous et lui vous croisiez rarement sur le campus, mais vous connaissiez un peu ses divers exploits."
  },
  AvgDialog_13736_Content_49 = {
    Text = "Il n'est certainement pas du genre à se laisser contrôler par autrui."
  },
  AvgDialog_13736_Content_5 = {
    Text = "Vous vous éveillez d'un profond sommeil pour vous retrouver dans un vaste désert sans fin."
  },
  AvgDialog_13736_Content_50 = {
    Text = "Qu'avez-vous fait à ce type ? Comment pourrait-il vous obéir ?"
  },
  AvgDialog_13736_Content_51 = {
    Text = "Quoi ? Vous remettez en question mes compétences en tant que <Blue:Sorcier en Chef de Levante> ?"
  },
  AvgDialog_13736_Content_52 = {
    Text = "C'est une technique secrète exclusive dans notre métier, ainsi que ma vie privée en tant qu'employeur. S'il vous plaît, Guide, mêlez-vous de vos affaires..."
  },
  AvgDialog_13736_Content_53 = {
    Text = "Vous ne parlez pas, hein ?\nAlors je vais vous frapper jusqu'à ce que vous parliez."
  },
  AvgDialog_13736_Content_54 = {
    Text = "Hé, attendez... <Big:Roar !>"
  },
  AvgDialog_13736_Content_56 = {
    Text = "<Shake:Sss, ça fait mal... Vous n'êtes certainement pas un guide ordinaire !>"
  },
  AvgDialog_13736_Content_57 = {
    Text = "Parle, es-tu un espion envoyé par <Blue:Remvashi> pour m'intercepter ?"
  },
  AvgDialog_13736_Content_58 = {
    Text = "Vous ne répondez pas à la question de Pulin, car votre attention a déjà été attirée ailleurs—"
  },
  AvgDialog_13736_Content_59 = {
    Text = "Une chaîne fine scintille faiblement à la lumière du jour, émettant un éclat inhabituel."
  },
  AvgDialog_13736_Content_6 = {
    Text = "Réveillé(e) ? Incroyable, le guide s'est évanoui d'insolation après seulement quelques pas. Quelle catastrophe !"
  },
  AvgDialog_13736_Content_60 = {
    Text = "Elle s'étend du poignet de Prin jusqu'au cou d'Uvhash."
  },
  AvgDialog_13736_Content_61 = {
    Text = "<Gray:Cette technique me semble familière... Il me semble avoir entendu quelqu'un en parler auparavant...>"
  },
  AvgDialog_13736_Content_62 = {
    Text = "Les désobéissants devraient simplement être tenus en laisse."
  },
  AvgDialog_13736_Content_63 = {
    Text = "C'est illégal à Londinium, Mademoiselle Agrippa. J'ai bien peur que nous devions vous enseigner quelques notions juridiques de base..."
  },
  AvgDialog_13736_Content_64 = {
    Text = "Hehe, je ne suis pas idiote."
  },
  AvgDialog_13736_Content_65 = {
    Text = "Connaissez-vous @1 ?"
  },
  AvgDialog_13736_Content_66 = {
    Text = "C'est un art arcanique ancien, permettant au lanceur de contrôler autrui avec une chaîne invisible..."
  },
  AvgDialog_13736_Content_67 = {
    Text = "Quant au coût..."
  },
  AvgDialog_13736_Content_68 = {
    Text = "Quel était le coût ? Oh non, je ne m'en souviens plus..."
  },
  AvgDialog_13736_Content_69 = {
    Text = "Vous êtes perdu dans vos souvenirs quand soudain le masque enroulé autour de votre visage est arraché."
  },
  AvgDialog_13736_Content_7 = {
    Text = "Heureusement que je ne visite ce trou infernal qu'une seule fois dans ma vie, @1 !"
  },
  AvgDialog_13736_Content_70 = {
    Text = "Trois rivières sinueuses... Vous êtes l'<Blue:esclave mercenaire de Mamlio> ?!"
  },
  AvgDialog_13736_Content_71 = {
    Text = "Alors que Prinn finissait de parler, Uvhash, qui avait semblé indifférent, se tourna soudain pour vous regarder."
  },
  AvgDialog_13736_Content_72 = {
    Text = "Intéressant..."
  },
  AvgDialog_13736_Content_73 = {
    Text = "Non, non, ce n'est pas possible. Les hommes de Mamulu devraient être sur le champ de bataille en ce moment..."
  },
  AvgDialog_13736_Content_74 = {
    Text = "Je vois, vous êtes un déserteur."
  },
  AvgDialog_13736_Content_75 = {
    Text = "Vous avez instinctivement touché votre visage."
  },
  AvgDialog_13736_Content_76 = {
    Text = "<Gray:Alors il y a un tatouage sur mon visage...>"
  },
  AvgDialog_13736_Content_77 = {
    Text = "Bien sûr, je suis un déserteur. Ma ville natale est <Blue:Lemwashi>, mais je ne veux pas y retourner..."
  },
  AvgDialog_13736_Content_78 = {
    Text = "Les déserteurs doivent manger aussi, alors je gagne maintenant ma vie comme guide.\nNe vous inquiétez pas, ma plus grande force est mon approche méticuleuse du travail."
  },
  AvgDialog_13736_Content_79 = {
    Text = "M›assurer de vous amener sur le champ de bataille—"
  },
  AvgDialog_13736_Content_8 = {
    Text = "Guide ? Cet... où est-ce qu'on est..."
  },
  AvgDialog_13736_Content_80 = {Text = "Pfft."},
  AvgDialog_13736_Content_81 = {
    Text = "En ayant assez de la farce devant lui, Uvhash s›étire et s›avance nonchalamment vers vous."
  },
  AvgDialog_13736_Content_82 = {
    Text = "Il saisit votre épaule et tourne doucement votre menton jusqu›à ce que votre regard croise celui du magicien silencieux devant vous."
  },
  AvgDialog_13736_Content_83 = {
    Text = "Étant donné que nous sommes, ou étions, des esclaves, laissez-moi vous donner un indice—"
  },
  AvgDialog_13736_Content_84 = {
    Text = "Si j›étais vous, je me tairais tout de suite.\nSavez-vous quel genre de personnes ce type déteste le plus ?"
  },
  AvgDialog_13736_Content_85 = {
    Text = "...Le sentiment d›être incité à la prudence par ce type est vraiment particulier."
  },
  AvgDialog_13736_Content_86 = {
    Text = "...J›aimerais en entendre davantage."
  },
  AvgDialog_13736_Content_87 = {
    Text = "Troisièmement, les mercenaires Mamuliu."
  },
  AvgDialog_13736_Content_88 = {
    Text = "Deuxième, les Lemwashians.\nQuant au premier..."
  },
  AvgDialog_13736_Content_89 = {
    Text = "Une douleur intense traverse votre épaule — Uvhash rit en vous frappant violemment l›épaule."
  },
  AvgDialog_13736_Content_9 = {
    Text = "Le soleil brûlant vous donne le vertige tandis que vous baissez les yeux vers vos mains."
  },
  AvgDialog_13736_Content_90 = {
    Text = "<Big:Bien sûr, ce sont les mercenaires Mamulu de Lemwash !>"
  },
  AvgDialog_13736_Content_91 = {
    Text = "<Gray:...Bien. Personne d›autre ne devrait pouvoir rire aux éclats à part lui.>"
  },
  AvgDialog_13736_Content_92 = {
    Text = "<Gray:Le talent de ce type pour offenser les gens est vraiment inégalé.>"
  },
  AvgDialog_13736_Content_93 = {Text = "Heh..."},
  AvgDialog_13736_Content_94 = {
    Text = "Quand les mercenaires Mamlu ont massacré des dizaines de milliers de mes compatriotes, ma femme, mes camarades et mon mentor... tous ont péri."
  },
  AvgDialog_13736_Content_95 = {
    Text = "Bien, j›ai fini de raconter mon histoire tragique. Vous pouvez continuer à rire maintenant."
  },
  AvgDialog_13736_Content_96 = {
    Text = "Désolé, M. Prin. Permettez-moi de m'expliquer. Bien qu'il y a un... enfin, un passé pas très honorable."
  },
  AvgDialog_13736_Content_97 = {
    Text = "Mais tout ça, c'est du passé et ça n'a plus rien à voir avec moi maintenant."
  },
  AvgDialog_13736_Content_98 = {
    Text = "Prin vous fit signe de la main."
  },
  AvgDialog_13736_Content_99 = {
    Text = "Son visage rond, cuit par le soleil brûlant, ressemblait à une pomme bien mûre — malheureusement, cette pomme n'était pas d'humeur très joyeuse en ce moment."
  },
  AvgDialog_13737_Content_1 = {
    Text = "Le rideau de la tragédie"
  },
  AvgDialog_13737_Content_10 = {
    Text = "<RedShake:Marche...>"
  },
  AvgDialog_13737_Content_11 = {
    Text = "Uvhash écrasa sans effort le cerveau du bloqueur, puis s'approcha lentement d'un autre soldat."
  },
  AvgDialog_13737_Content_12 = {
    Text = "<RedShake:Du sang... Il me faut plus de sang...>"
  },
  AvgDialog_13737_Content_13 = {
    Text = "Il a lentement levé la main."
  },
  AvgDialog_13737_Content_15 = {Text = "新增"},
  AvgDialog_13737_Content_16 = {
    Text = "C'est toi..."
  },
  AvgDialog_13737_Content_17 = {
    Text = "Oui, c'est moi."
  },
  AvgDialog_13737_Content_18 = {
    Text = "Vous vous interposez entre les deux, vous retournant pour regarder le soldat agenouillé de peur derrière vous."
  },
  AvgDialog_13737_Content_19 = {
    Text = "Dépêche-toi. Cours aussi loin que tu peux."
  },
  AvgDialog_13737_Content_2 = {
    Text = "Bordure du désert de Kuxi, Champ de bataille"
  },
  AvgDialog_13737_Content_20 = {
    Text = "<Big:Dégage !!>"
  },
  AvgDialog_13737_Content_21 = {
    Text = "<Shake:D'accord, d'accord... Je me tire...>"
  },
  AvgDialog_13737_Content_22 = {
    Text = "Les soldats s'enfuirent en toute hâte."
  },
  AvgDialog_13737_Content_23 = {
    Text = "Pourquoi m'arrêter ? Je commençais tout juste à savourer l'ivresse du sang et du combat..."
  },
  AvgDialog_13737_Content_24 = {
    Text = "Tu veux juste te battre, pas vrai ? Je vais jouer le jeu."
  },
  AvgDialog_13737_Content_25 = {
    Text = "Toi ? Hahaha, qu'est-ce que tu—"
  },
  AvgDialog_13737_Content_27 = {
    Text = "Vous pressez le cimeterre contre le cou d'Uvhash, fixant calmement ses yeux hagards."
  },
  AvgDialog_13737_Content_28 = {
    Text = "On ne le saura jamais sans essayer."
  },
  AvgDialog_13737_Content_3 = {
    Text = "Hé, tu as entendu ? Un autre est devenu fou, il tue tous ceux qu›il croise."
  },
  AvgDialog_13737_Content_4 = {
    Text = "Ils disent qu'il n'est ni Leorian ni Lemwashian... personne ne sait d'où il vient."
  },
  AvgDialog_13737_Content_5 = {
    Text = "Bref, partez vite—"
  },
  AvgDialog_13737_Content_6 = {Text = "新增"},
  AvgDialog_13737_Content_7 = {
    Text = "<Shake:Quand est-ce que tu... es apparu...?>"
  },
  AvgDialog_13737_Content_8 = {
    Text = "Ahhh ! Dépêche-toi—"
  },
  AvgDialog_13737_Content_9 = {Text = "—!!"},
  AvgDialog_13738_Content_1 = {
    Text = "Bien, la tempête de sable s›est déplacée de l›autre côté. Maintenant, nous..."
  },
  AvgDialog_13738_Content_10 = {Text = "新增"},
  AvgDialog_13738_Content_11 = {
    Text = "Tu ne veux pas aller sur le champ de bataille? Alors, bien sûr, tu devrais te diriger vers la <Red:direction du sang>."
  },
  AvgDialog_13738_Content_12 = {
    Text = "La direction du sang...?"
  },
  AvgDialog_13738_Content_13 = {
    Text = "Vous pointez le dos d›Uvhash qui s›éloigne."
  },
  AvgDialog_13738_Content_14 = {
    Text = "Sa direction."
  },
  AvgDialog_13738_Content_2 = {Text = "Ugh—!!"},
  AvgDialog_13738_Content_3 = {
    Text = "Pulin s›appuya contre le tronc d›arbre nu et se mit à vomir violemment."
  },
  AvgDialog_13738_Content_4 = {
    Text = "Je jure, une fois cet accord conclu. Je jure..."
  },
  AvgDialog_13738_Content_5 = {
    Text = "Cette fois, la malédiction de faiblesse du magicien ne reçut aucune réponse."
  },
  AvgDialog_13738_Content_6 = {
    Text = "Les pupilles d›Uvhash se contractèrent soudainement, comme s›il avait découvert quelque chose."
  },
  AvgDialog_13738_Content_7 = {
    Text = "<Red:...du sang.>"
  },
  AvgDialog_13738_Content_8 = {
    Text = "Après avoir dit cela, il partit sans se retourner."
  },
  AvgDialog_13738_Content_9 = {
    Text = "Attends...! Tu ne peux aller nulle part sans ma permission!"
  },
  AvgDialog_13739_Content_1 = {
    Text = "Le vautour crie bruyamment dans le crépuscule rouge sang ; le champ de bataille est déjà désert."
  },
  AvgDialog_13739_Content_10 = {
    Text = "Pendant le combat, tu sens clairement l'état d'Uvhash se détériorer à une vitesse alarmante."
  },
  AvgDialog_13739_Content_11 = {
    Text = "Quoi que ce soit, que ce soit un effet secondaire du Contrat, il a atteint ses limites."
  },
  AvgDialog_13739_Content_12 = {
    Text = "Le combat n'est intéressant que lorsqu'il est équilibré, alors ça ne me dérange pas de m'affaiblir dans une certaine mesure."
  },
  AvgDialog_13739_Content_13 = {
    Text = "Je ne me soucie jamais des pensées des humains, tout comme les humains ne se soucient pas des fourmis."
  },
  AvgDialog_13739_Content_14 = {
    Text = "Mais tu es différent. Tu possèdes une puissante force intérieure, et tu comprends la retenue."
  },
  AvgDialog_13739_Content_15 = {
    Text = "Continue ainsi, guerrier. Tes souhaits ordinaires — comme le soleil, les petits gâteaux, et tout ça — pourraient bien se réaliser."
  },
  AvgDialog_13739_Content_16 = {
    Text = "<Gray:C'étaient juste des bêtises que j'avais dites au hasard, et il s'en est vraiment souvenu...>"
  },
  AvgDialog_13739_Content_17 = {
    Text = "Allons... à l'endroit que tu as mentionné, là où le soleil brille."
  },
  AvgDialog_13739_Content_18 = {Text = "?!"},
  AvgDialog_13739_Content_19 = {Text = "Et toi ?"},
  AvgDialog_13739_Content_2 = {
    Text = "Vous et Uvhash vous teniez silencieusement à moins de dix mètres l'un de l'autre, vous regardant mutuellement."
  },
  AvgDialog_13739_Content_20 = {
    Text = "Moi...? Le vieil homme s'est retenu. Je ne tiendrai plus longtemps. Heh..."
  },
  AvgDialog_13739_Content_21 = {
    Text = "Le vieil homme et moi devons mourir tous les deux... C'est le véritable prix de la rupture du contrat."
  },
  AvgDialog_13739_Content_22 = {
    Text = "Il avance lentement vers toi d'un pas lourd."
  },
  AvgDialog_13739_Content_23 = {
    Text = "Il mordit alors son propre poignet."
  },
  AvgDialog_13739_Content_24 = {
    Text = "Le sang écarlate et âcre se déverse à flots, tombant sur ta tête, tes paupières, et coulant le long de l'arête de ton nez jusqu'à tes lèvres desséchées."
  },
  AvgDialog_13739_Content_25 = {
    Text = "Ce sang... considère-le comme mon cadeau d'adieu."
  },
  AvgDialog_13739_Content_26 = {
    Text = "Des Vautours tournoyaient au-dessus de lui, lorgnant clairement leur proie mourante."
  },
  AvgDialog_13739_Content_27 = {
    Text = "Je suis né de myriade de chairs et j'erre dans ce monde depuis près d'un millier d'années..."
  },
  AvgDialog_13739_Content_28 = {
    Text = "Il y a des feuilles d'or voltigeant dans les défilés de victoire, et des palais dorés brûlant férocement dans les flammes."
  },
  AvgDialog_13739_Content_29 = {
    Text = "J'ai goûté le sang le plus délicieux et vécu les batailles les plus brutales."
  },
  AvgDialog_13739_Content_3 = {
    Text = "Hé... ça fait combien de temps qu'on se bat ?"
  },
  AvgDialog_13739_Content_30 = {
    Text = "J'ai massacré des humains, j'ai été enchaîné et utilisé par eux, et finalement je suis mort de leurs mains, sans surprise."
  },
  AvgDialog_13739_Content_31 = {
    Text = "Maintenant, il est temps pour moi de partir..."
  },
  AvgDialog_13739_Content_32 = {
    Text = "Il baisse les yeux vers vous, son regard dénué de toute émotion."
  },
  AvgDialog_13739_Content_33 = {
    Text = "Un sang épais goutte de la pointe de votre nez jusqu'au sol."
  },
  AvgDialog_13739_Content_34 = {
    Text = "Vous êtes comme un novice désorienté, ignorant de tout ce qui se déroule devant vous."
  },
  AvgDialog_13739_Content_35 = {
    Text = "Je te rends toute ma chair, à toi et à ce monde."
  },
  AvgDialog_13739_Content_36 = {
    Text = "Elle appartient au ciel, à la terre... à vous, mais pas à moi."
  },
  AvgDialog_13739_Content_37 = {
    Text = "Maintenant vous pouvez déguerpir... Ne vous retournez pas."
  },
  AvgDialog_13739_Content_38 = {
    Text = "La vue est finalement engloutie dans une vaste mer de brume sanglante. \nVous fermez les yeux, ressentant des vagues de vertige comme si le sol s'enfonçait sans cesse."
  },
  AvgDialog_13739_Content_39 = {
    Text = "Vous ne vous souvenez plus très bien de la suite de l'histoire."
  },
  AvgDialog_13739_Content_4 = {Text = "新增"},
  AvgDialog_13739_Content_40 = {
    Text = "Peut-être êtes-vous parti depuis longtemps, ou peut-être êtes-vous mort avec lui dans ce désert."
  },
  AvgDialog_13739_Content_41 = {
    Text = "Cela n'a pas d'importance. Car vous vous souviendrez à jamais de l'instant précédant sa mort."
  },
  AvgDialog_13739_Content_42 = {
    Text = "À cet instant, une nuée de vautours noirs passa, masquant la lueur du crépuscule derrière lui."
  },
  AvgDialog_13739_Content_43 = {
    Text = "La lumière continue de faiblir, les ombres s'étendent alentour, et il s'agenouille parmi elles, le regard posé sur vous."
  },
  AvgDialog_13739_Content_44 = {
    Text = "Il a dit—"
  },
  AvgDialog_13739_Content_45 = {
    Text = "Déguerpis."
  },
  AvgDialog_13739_Content_46 = {
    Text = "Va trouver ce trou infernal baigné de soleil."
  },
  AvgDialog_13739_Content_5 = {
    Text = "Qui sait... une heure, un jour ?"
  },
  AvgDialog_13739_Content_6 = {Text = "新增"},
  AvgDialog_13739_Content_7 = {
    Text = "Mille ans... Je n'ai pas connu un combat aussi exaltant depuis près d'un millénaire."
  },
  AvgDialog_13739_Content_8 = {
    Text = "Vous êtes un guerrier né."
  },
  AvgDialog_13739_Content_9 = {
    Text = "Surprenant, depuis quand as-tu appris à faire des compliments aux humains ?"
  },
  AvgDialog_138765_Content_1 = {
    Text = "Les braises des dimensions sont en mouvement. La roue du destin, Moirai, tourne déjà en ce lieu."
  },
  AvgDialog_138765_Content_2 = {
    Text = "Lancez-vous, Gardien du Secret{Male=先生,Female=小姐}. Je vous aiderai à corriger les destins erronés et à briser les cocons qui n›auraient jamais dû exister."
  },
  AvgDialog_138765_Content_3 = {
    Text = "Le cours du destin n'a jamais été tissé par les mains d'autrui."
  },
  AvgDialog_138766_Content_1 = {
    Text = "Est-ce que c'est... est-ce que c'est fini ?"
  },
  AvgDialog_138766_Content_2 = {
    Text = "Attention, Gardien... le fuseau qui défait le destin a déjà commencé à tourner derrière elle..."
  },
  AvgDialog_138766_Content_3 = {
    Text = "Heh... hahahaha... !"
  },
  AvgDialog_138766_Content_4 = {
    Text = "« Regardez, fidèles aveugles du Destin ! Le glas qui devait toujours sonner pour vous a enfin retenti ! »"
  },
  AvgDialog_138766_Content_5 = {
    Text = "« Je suis la fin — je suis le Destin — je suis @4 ! »"
  },
  AvgDialog_138766_Content_6 = {
    Text = "« À présent, je vous accorde la fin ultime. Je vous offre la libération que vous avez si désespérément désirée !! »"
  },
  AvgDialog_13946_Content_1 = {
    Text = "Mer à la dérive"
  },
  AvgDialog_13946_Content_10 = {
    Text = "Ils t'ont envoyé pour m'« escorter » jusqu'à la sorcière ?\nC'est risible. Leurs intentions ne pourraient pas être plus évidentes..."
  },
  AvgDialog_13946_Content_11 = {
    Text = "Goliath laisse échapper un gémissement de douleur. Sous lui, une mare de sang rouge sombre s'étend lentement, coulant jusqu'à vos pieds."
  },
  AvgDialog_13946_Content_12 = {
    Text = "<Red:Ils veulent que nous mourions ensemble en mer.>"
  },
  AvgDialog_13946_Content_13 = {
    Text = "Maître, vous êtes grièvement blessé ! Que s'est-il passé... ?"
  },
  AvgDialog_13946_Content_14 = {
    Text = "Des souvenirs chaotiques inondent ton esprit."
  },
  AvgDialog_13946_Content_15 = {
    Text = "Lors de la dernière bataille décisive, le Chef Goliath a perdu face à la tribu rivale pour les avoir sous-estimés."
  },
  AvgDialog_13946_Content_16 = {
    Text = "Les Périshites n'acceptent pas l'échec. Goliath, grièvement blessé, fut exilé, accompagné seulement d'un petit bateau délabré et de vous—"
  },
  AvgDialog_13946_Content_17 = {
    Text = "Le plus faible des Périshites pourrait même perdre un combat de lutte contre un enfant de dix ans."
  },
  AvgDialog_13946_Content_18 = {
    Text = "Je me souviens que le chef <Blue:Glen> a mentionné une sorcière mystérieuse dans les eaux voisines qui utilise une sorte de substance noire visqueuse..."
  },
  AvgDialog_13946_Content_19 = {
    Text = "Seulement l'appliquer sur la blessure, et elle guérira à coup sûr!"
  },
  AvgDialog_13946_Content_2 = {
    Text = "Lamentation pour l'Apôtre des Mers.\nLamentation pour notre lumière, notre espoir.\n\nNous gémissons, pleurons et versons des larmes sur notre sort d'exilés vers l'océan."
  },
  AvgDialog_13946_Content_20 = {
    Text = "Vous avez évoqué par réflexe la légende de la sorcière, pour réaliser ensuite que quelque chose clochait."
  },
  AvgDialog_13946_Content_21 = {
    Text = "<Gray:Attendez, c'est du D-slime...?>"
  },
  AvgDialog_13946_Content_22 = {
    Text = "Chef, c'est Glen?"
  },
  AvgDialog_13946_Content_23 = {
    Text = "Un lent sourire se dessina sur le visage froid de Goliath."
  },
  AvgDialog_13946_Content_24 = {
    Text = "On dirait qu'il est devenu votre nouveau chef. Très efficace, mes chers compagnons de clan."
  },
  AvgDialog_13946_Content_25 = {
    Text = "Éclaboussure !!"
  },
  AvgDialog_13946_Content_26 = {
    Text = "Le bateau en décomposition ne pouvait plus résister à l'impact des vagues, laissant s'ouvrir un large trou par lequel l'eau de mer s'engouffrait sans cesse."
  },
  AvgDialog_13946_Content_27 = {
    Text = "Tss, comme je m'y attendais."
  },
  AvgDialog_13946_Content_28 = {
    Text = "Oh non, nous allons nous noyer! Il faut trouver quelque chose pour boucher le trou..."
  },
  AvgDialog_13946_Content_29 = {Text = "...Oh."},
  AvgDialog_13946_Content_3 = {
    Text = "Oh, protégez les affligés !\nPosez sur nous votre regard miséricordieux et accordez-nous la fontaine noire de vie."
  },
  AvgDialog_13946_Content_30 = {
    Text = "Goliath s'adossa nonchalamment au pont, laissant le sang sous lui teinter de rouge l'eau de mer qui s'infiltrait."
  },
  AvgDialog_13946_Content_31 = {
    Text = "Lâcher prise. Même si on répare le navire, ils ont encore dix mille façons de me tuer dans cette mer."
  },
  AvgDialog_13946_Content_32 = {
    Text = "Mon conseil: Laissez-moi tranquille. Quittez le bateau et nagez pour rentrer par vous-même."
  },
  AvgDialog_13946_Content_33 = {
    Text = "Dites-leur que vous m'avez tué. Avec un peu de chance, vous pourriez seulement survivre."
  },
  AvgDialog_13946_Content_34 = {
    Text = "Et vous...?"
  },
  AvgDialog_13946_Content_35 = {Text = "Moi ?"},
  AvgDialog_13946_Content_36 = {
    Text = "Goliath contemple tranquillement la vue sur la mer et vous adresse un léger sourire."
  },
  AvgDialog_13946_Content_37 = {
    Text = "Assis ici à admirer la mer, en attendant de mourir."
  },
  AvgDialog_13946_Content_38 = {Text = "...?"},
  AvgDialog_13946_Content_39 = {
    Text = "<Gray:Si pessimiste, est-ce vraiment le Goliath que je connais ?>"
  },
  AvgDialog_13946_Content_4 = {
    Text = "<Red:Grâce, grâce, grâce...>"
  },
  AvgDialog_13946_Content_40 = {
    Text = "Au fait, il y a encore une chose dont je dois te prévenir."
  },
  AvgDialog_13946_Content_41 = {
    Text = "Il y a un trou à l'arrière. D'après mon expérience, ce navire va se briser en deux bientôt. Il ne te reste plus beaucoup de temps pour réfléchir."
  },
  AvgDialog_13946_Content_42 = {
    Text = "Éclaboussure !!"
  },
  AvgDialog_13946_Content_43 = {
    Text = "Semblant confirmer les paroles de Goliath, une vague massive s'abattit, brisant le bateau en bois en deux instantanément."
  },
  AvgDialog_13946_Content_44 = {
    Text = "<Shake:Aaaah—!!>"
  },
  AvgDialog_13946_Content_45 = {
    Text = "L'eau de mer salée ne cesse d'envahir vos poumons. Vous ouvrez la bouche, mais davantage d'eau vous engloutit tout entier."
  },
  AvgDialog_13946_Content_46 = {
    Text = "Le corps ne cesse de couler, et respirer devient de plus en plus difficile..."
  },
  AvgDialog_13946_Content_47 = {
    Text = "Dans un état second, vous semblez entendre un soupir d'impuissance."
  },
  AvgDialog_13946_Content_48 = {
    Text = "Avant que vous ne puissiez réagir, une force puissante vous attrape par les cheveux et vous extirpe sans effort de la mer."
  },
  AvgDialog_13946_Content_49 = {
    Text = "Tousse... Ugh !"
  },
  AvgDialog_13946_Content_5 = {Text = "新增"},
  AvgDialog_13946_Content_50 = {
    Text = "Accroche-toi bien, c'est notre seule planche de salut."
  },
  AvgDialog_13946_Content_51 = {
    Text = "Vous regardez autour de vous et réalisez que vous et Goliath êtes serrés ensemble sur une planche de bois branlante."
  },
  AvgDialog_13946_Content_52 = {
    Text = "Bon sang... Comment les Périshites, maîtres de la mer, peuvent-ils ne pas savoir nager ?"
  },
  AvgDialog_13946_Content_53 = {
    Text = "Es-tu vraiment un Périshite ?"
  },
  AvgDialog_13946_Content_54 = {
    Text = "<SmallShake:Désolé, mon corps est fragile depuis l'enfance...>"
  },
  AvgDialog_13946_Content_55 = {
    Text = "Merci, mon seigneur. Sans vous, je serais mort ici..."
  },
  AvgDialog_13946_Content_56 = {
    Text = "...Il semblerait que vous n'ayez pas été envoyé par eux pour me tuer."
  },
  AvgDialog_13946_Content_57 = {
    Text = "Votre instinct de survie à l'instant semblait sincère, pas feint."
  },
  AvgDialog_13946_Content_58 = {
    Text = "Goliath essuya les mèches humides de son front et contempla la mer brumeuse devant lui."
  },
  AvgDialog_13946_Content_59 = {
    Text = "Quand tu es tombé dans la mer, tu t›es accroché à moi comme un crabe géant, en refusant de lâcher prise. Pourquoi ?"
  },
  AvgDialog_13946_Content_6 = {
    Text = "Réveillez-vous ?"
  },
  AvgDialog_13946_Content_60 = {
    Text = "Hein ? Pour survivre, évidemment..."
  },
  AvgDialog_13946_Content_61 = {
    Text = "Survivre... mais même en vie, tu es inutile. Tu ne sais même pas nager."
  },
  AvgDialog_13946_Content_62 = {
    Text = "Pourquoi est-ce que tu vis ?"
  },
  AvgDialog_13946_Content_63 = {
    Text = "La voix de Goliath faiblit peu à peu, comme s›il vous posait la question, ou peut-être se la posait à lui-même."
  },
  AvgDialog_13946_Content_64 = {
    Text = "Exilé par sa tribu et grièvement blessé, le chemin devant lui, comme la mer enveloppée d›un brouillard épais, est empli d›une incertitude sans fin."
  },
  AvgDialog_13946_Content_65 = {Text = "新增"},
  AvgDialog_13946_Content_66 = {
    Text = "Tu disais que tu étais prêt à mourir, mais quand les vagues sont arrivées, non seulement tu as trouvé cette planche et tu es monté dessus, mais tu m›as aussi sauvé."
  },
  AvgDialog_13946_Content_67 = {
    Text = "...C›est parce que tu n›arrêtes pas de me harceler."
  },
  AvgDialog_13946_Content_68 = {
    Text = "Rien de tout cela n›a d›importance. Ce qui compte, c›est que grâce à toi, Maître, nous sommes tous les deux en vie."
  },
  AvgDialog_13946_Content_69 = {
    Text = "Pourquoi penses-tu cela ?"
  },
  AvgDialog_13946_Content_7 = {
    Text = "La mer soulève des vagues brûlées par le soleil, portant jusqu'à vos narines une brise salée à la forte odeur de poisson."
  },
  AvgDialog_13946_Content_70 = {
    Text = "Goliath secoua la tête."
  },
  AvgDialog_13946_Content_71 = {
    Text = "Pour être honnête, je ne sais pas non plus. Mais j›ai réalisé une chose..."
  },
  AvgDialog_13946_Content_72 = {
    Text = "Goliath baisse la tête, vous observant d›un air pensif."
  },
  AvgDialog_13946_Content_73 = {
    Text = "Je comprends pourquoi tu es un tel incapable et pourtant encore en vie aujourd›hui."
  },
  AvgDialog_13946_Content_8 = {
    Text = "<Gray:Est-ce... un rêve ?>"
  },
  AvgDialog_13946_Content_9 = {
    Text = "Comme on pouvait s'y attendre du membre le plus fragile du clan, une seule grosse vague suffit à vous laisser inconscient pendant une demi-journée."
  },
  AvgDialog_13947_Content_1 = {
    Text = "Chroniques des Géants"
  },
  AvgDialog_13947_Content_10 = {
    Text = "Seulement les imbéciles confieraient leur vie à autrui."
  },
  AvgDialog_13947_Content_11 = {
    Text = "<Gray:Sorcière...>"
  },
  AvgDialog_13947_Content_12 = {
    Text = "Selon le dossier de Réveilleur de Goliath, cette soi-disant \"sorcière\" est sans aucun doute Miryam."
  },
  AvgDialog_13947_Content_13 = {
    Text = "Bien que les événements qui suivirent ne se soient pas déroulés comme prévu, Miryam a bel et bien sauvé la vie de Goliath."
  },
  AvgDialog_13947_Content_14 = {
    Text = "Vous êtes gravement blessé, monseigneur. Je crains qu'il n'y ait pas d'autre solution. Trouvons la sorcière ensemble—"
  },
  AvgDialog_13947_Content_15 = {Text = "BANG!!"},
  AvgDialog_13947_Content_16 = {
    Text = "Avec une force colossale, votre gorge fragile est fermement agrippée, vous soulevant du sol pour vous retrouver face à face avec le géant."
  },
  AvgDialog_13947_Content_17 = {
    Text = "Je ne le dirai qu'une seule fois: ne me regarde pas avec ce genre de regard, et ne me parle pas sur ce ton."
  },
  AvgDialog_13947_Content_18 = {
    Text = "La dernière chose dont moi, Goliath, ai besoin, c'est la pitié des faibles."
  },
  AvgDialog_13947_Content_19 = {
    Text = "Goliath parlait calmement, son expression inchangée, comme s'il discutait de la météo avec vous."
  },
  AvgDialog_13947_Content_2 = {
    Text = "La lumière du soleil brûle la surface de la mer, comme pour consumer toute vie dans une chaleur sans fin."
  },
  AvgDialog_13947_Content_20 = {
    Text = "Mais vous êtes si proche que vous pouvez clairement voir ses yeux, rougis par la douleur et la frustration."
  },
  AvgDialog_13947_Content_21 = {
    Text = "À cet instant, il semblait se défaire de sa gloire de seigneur des mers, devenant simplement un autre poisson perdu dans l'océan infini, tout comme vous."
  },
  AvgDialog_13947_Content_22 = {
    Text = "Pardon... euh, monseigneur..."
  },
  AvgDialog_13947_Content_23 = {
    Text = "<Shake:Ouuuu—>"
  },
  AvgDialog_13947_Content_24 = {
    Text = "Le son grave d'une corne résonne au loin."
  },
  AvgDialog_13947_Content_25 = {
    Text = "Le poids sur le cou se relâcha soudainement. Goliath desserra sa prise et tourna le regard vers la direction d'où provenait le son de la corne."
  },
  AvgDialog_13947_Content_26 = {
    Text = "<Gray:Tousse... Ouf, je suis sauvé...>"
  },
  AvgDialog_13947_Content_27 = {
    Text = "Intéressant... Vous craignez que je ne meure pas assez vite, alors vous êtes tous venus ensemble pour m'accompagner?"
  },
  AvgDialog_13947_Content_28 = {
    Text = "Peu après, l'immense flotte vous encercla, ne laissant que les planches de bois vacillantes comme seule île dans cette vaste mer."
  },
  AvgDialog_13947_Content_29 = {
    Text = "Vous êtes déjà encerclé."
  },
  AvgDialog_13947_Content_3 = {
    Text = "Goliath et vous vous accrochez à la planche, seule île dans l›immensité de la mer. Sous le soleil brûlant, vous vous sentez à nouveau pris de vertiges."
  },
  AvgDialog_13947_Content_30 = {
    Text = "Permettez-moi de présenter à tous le chef le plus vaillant de l'histoire philistine ! Le géant inébranlable à la puissance immense ! L'imposant, l'incomparable héros tribal—"
  },
  AvgDialog_13947_Content_31 = {
    Text = "<BigShake:Seigneur Goliath !>"
  },
  AvgDialog_13947_Content_32 = {
    Text = "La lumière du soleil se reflétant sur la mer est trop intense ; vous ne pouvez qu'entrevoir une silhouette noire se tenant à la proue, vous regardant de haut."
  },
  AvgDialog_13947_Content_33 = {
    Text = "Les frères nouvellement arrivés ne le savent peut-être pas, mais ce seigneur a été grièvement blessé lors d'un duel et a failli être capturé, poussant notre clan tout entier au bord d'une crise sans précédent !"
  },
  AvgDialog_13947_Content_34 = {
    Text = "La catastrophe imminente a dévoré la plupart des nôtres ! Louange à vous, mon très cher Seigneur Goliath !"
  },
  AvgDialog_13947_Content_35 = {
    Text = "Héhé... Comment pourrais-je oser m'attribuer tout le mérite d'un tel exploit, Glen ?"
  },
  AvgDialog_13947_Content_36 = {
    Text = "Qui se cachait derrière moi, trop effrayé pour combattre, et qui a été le premier à lâcher son arme et à rentrer en pleurant ?"
  },
  AvgDialog_13947_Content_37 = {Text = "Vous...!"},
  AvgDialog_13947_Content_38 = {
    Text = "Le visage de Glen devint cramoisi, ses yeux troubles tremblant avant de finalement se fixer sur vous."
  },
  AvgDialog_13947_Content_39 = {
    Text = "Oh, même si la tribu se disperse, le chef a toujours un... suivant très adorable."
  },
  AvgDialog_13947_Content_4 = {
    Text = "<Shake:Désolé, je ne me sens pas bien... Je vais me reposer un peu...>"
  },
  AvgDialog_13947_Content_40 = {
    Text = "La honte des Perishites — un bon à rien qui ne peut même pas encaisser un seul coup au sein de la tribu, et qui cherche pourtant à vous suivre pour devenir un guerrier..."
  },
  AvgDialog_13947_Content_41 = {
    Text = "Hahaha... !!"
  },
  AvgDialog_13947_Content_42 = {
    Text = "Goliath lève les yeux, surpris de vous apercevoir à travers les rires de la foule."
  },
  AvgDialog_13947_Content_43 = {
    Text = "Hé, petit, tu es venu me suivre de ton propre gré ?"
  },
  AvgDialog_13947_Content_44 = {
    Text = "<Gray:Euh... C'est comme ça que je m'en souviens...>"
  },
  AvgDialog_13947_Content_45 = {
    Text = "N'est-ce pas touchant ? J'ai juste mentionné la sorcière en passant, et ce petit idiot l'a pris au sérieux, voulant à tout prix vous suivre jusqu'ici..."
  },
  AvgDialog_13947_Content_46 = {
    Text = "Impossible de l'arrêter, haha—"
  },
  AvgDialog_13947_Content_47 = {
    Text = "Éclaboussure !!"
  },
  AvgDialog_13947_Content_48 = {
    Text = "Les rires cessèrent brusquement. Un vent violent hurla, et une jambe tranchée roula devant tout le monde."
  },
  AvgDialog_13947_Content_49 = {
    Text = "Aaaah... ma jambe, ma jambe !!"
  },
  AvgDialog_13947_Content_5 = {
    Text = "Une chemise tachée de sueur et de sang est jetée sur votre tête, vous faisant bondir immédiatement à cause de la puanteur."
  },
  AvgDialog_13947_Content_50 = {
    Text = "L›ancien seigneur dominant des mers se dresse comme une montagne devant Glen, dégageant une aura qui glace le cœur."
  },
  AvgDialog_13947_Content_51 = {
    Text = "Cette mouche bourdonne autour de mon oreille depuis un moment maintenant..."
  },
  AvgDialog_13947_Content_52 = {
    Text = "Goliath essuya tranquillement le sang de sa lame, puis leva les yeux et adressa à Glen un sourire glacial."
  },
  AvgDialog_13947_Content_53 = {
    Text = "Glenn, est-ce que je ne viens pas de te poser une question?"
  },
  AvgDialog_13947_Content_6 = {
    Text = "Tousse... Ugh !"
  },
  AvgDialog_13947_Content_7 = {
    Text = "Tu souffres d›une insolation. Place ça sur ta tête pour te protéger du soleil, et ne l›enlève pas."
  },
  AvgDialog_13947_Content_8 = {
    Text = "Comme on pouvait s'y attendre des vêtements portés par le Maître, vraiment revigorant...\nOù devrions–nous aller ensuite? Trouver la sorcière?"
  },
  AvgDialog_13947_Content_9 = {
    Text = "Quelles bêtises à propos de sorcières? Tu ne crois quand même pas à leurs mensonges?"
  },
  AvgDialog_13948_Content_1 = {
    Text = "Refrain doré"
  },
  AvgDialog_13948_Content_10 = {
    Text = "Le calme blafard de la mer est brisé lorsqu'un serpent de mer d'un noir violacé surgit soudainement, enlaçant tout le monde dans son étreinte."
  },
  AvgDialog_13948_Content_11 = {
    Text = "Hmm... Aaaahhh !!"
  },
  AvgDialog_13948_Content_12 = {
    Text = "Avec un léger sifflement, le corps du serpent se transforme en une lame d'un noir de jais, transperçant la personne de part en part."
  },
  AvgDialog_13948_Content_13 = {
    Text = "<Big:Hors de mon chemin>... Hein ?"
  },
  AvgDialog_13948_Content_15 = {
    Text = "Une sensation douce et glaciale émane du cou autour duquel le serpent noir s›enroule, guérissant progressivement la blessure."
  },
  AvgDialog_13948_Content_16 = {
    Text = "Mes blessures... ont toutes guéri ?"
  },
  AvgDialog_13948_Content_17 = {
    Text = "Le serpent noir vous quitte sans hésitation et s›enroule rapidement autour de Glenn."
  },
  AvgDialog_13948_Content_18 = {
    Text = "Courir, la sorcière... arrive..."
  },
  AvgDialog_13948_Content_19 = {
    Text = "Les serpents d›un noir de jais se sont glissés hors des yeux et de la bouche de Glen. Il s›est effondré avant de pouvoir prononcer une phrase complète."
  },
  AvgDialog_13948_Content_2 = {
    Text = "Lamentation pour l'Apôtre des Mers.\nLamentation pour notre lumière, notre espoir.\n\nNous gémissons, pleurons et versons des larmes sur notre sort d'exilés vers l'océan."
  },
  AvgDialog_13948_Content_20 = {
    Text = "En un rien de temps, d›innombrables cadavres brisés flottaient sur la mer."
  },
  AvgDialog_13948_Content_21 = {
    Text = "C›est un massacre silencieux."
  },
  AvgDialog_13948_Content_22 = {
    Text = "<Gray:C›est fini ? Impressionnant, comme on pouvait s›y attendre de la part de Miryam.>"
  },
  AvgDialog_13948_Content_23 = {
    Text = "Vous nous avez aidés... Qui êtes-vous ?"
  },
  AvgDialog_13948_Content_24 = {
    Text = "La femme au voile noir reste silencieuse. Elle se tient à la proue, un brouillard dense vous séparant d›elle."
  },
  AvgDialog_13948_Content_25 = {
    Text = "Si proche en apparence, et pourtant si lointaine."
  },
  AvgDialog_13948_Content_26 = {
    Text = "La femme contempla Goliath, stupéfait, un léger sourire se dessinant sur ses lèvres. Elle tendit son doigt vers le lointain, comme pour lancer une invitation silencieuse."
  },
  AvgDialog_13948_Content_27 = {
    Text = "Elle tourna ensuite la proue et s›éloigna tranquillement."
  },
  AvgDialog_13948_Content_28 = {
    Text = "Attendez, ne partez pas...<Big:Ne partez pas !>"
  },
  AvgDialog_13948_Content_29 = {
    Text = "La brume se dissipe, et un rayon de soleil perce à travers les nuages, projetant une teinte dorée sur les vagues."
  },
  AvgDialog_13948_Content_3 = {
    Text = "Le Champ de vision s'assombrit soudainement ; la lumière aveuglante du soleil disparaît peu à peu, et un épais brouillard recouvre toute la surface de la mer."
  },
  AvgDialog_13948_Content_30 = {
    Text = "Vous avez cligné des yeux, et l›horizon marin était déjà vide."
  },
  AvgDialog_13948_Content_31 = {
    Text = "La tempête s›apaise, et vous et Goliath vous agrippez à la seule planche intacte, haletants."
  },
  AvgDialog_13948_Content_32 = {
    Text = "La mer autrefois azurée est depuis longtemps teintée de rouge par le sang, et vous dérivez comme des lentilles d›eau flottantes."
  },
  AvgDialog_13948_Content_33 = {
    Text = "Je n'ai toujours pas pu obtenir le navire... Maintenant, je ne sais même plus comment rentrer chez moi."
  },
  AvgDialog_13948_Content_34 = {
    Text = "On ne rentre pas."
  },
  AvgDialog_13948_Content_35 = {
    Text = "Goliath releva une jambe, fixant d›un regard vide la direction dans laquelle Miryam était partie."
  },
  AvgDialog_13948_Content_36 = {
    Text = "J›ai pris ma décision. Je vais retrouver cette sorcière. Tu viens avec moi ?"
  },
  AvgDialog_13948_Content_37 = {
    Text = "Hum, « Seulement un imbécile confierait sa vie à quelqu›un d›autre. »"
  },
  AvgDialog_13948_Content_38 = {
    Text = "Vous baissez délibérément la voix, imitant le ton précédent de Goliath et répétant ce qu›il a dit."
  },
  AvgDialog_13948_Content_39 = {
    Text = "Hmph, c›est parce que les enjeux n›étaient pas assez élevés. Je n›ai jamais vu un pouvoir capable de tout écraser en un instant."
  },
  AvgDialog_13948_Content_4 = {
    Text = "Oh, protégez ceux que le malheur accable.\nPosez sur nous votre regard compatissant..."
  },
  AvgDialog_13948_Content_40 = {
    Text = "De plus, elle vient de nous aider et m›a même adressé une invitation..."
  },
  AvgDialog_13948_Content_41 = {
    Text = "Mais que se passerait-il si... c'était un piège ?"
  },
  AvgDialog_13948_Content_42 = {
    Text = "Un piège..."
  },
  AvgDialog_13948_Content_43 = {
    Text = "Tu te souviens de la question que tu m›as posée avant ?"
  },
  AvgDialog_13948_Content_44 = {
    Text = "...L›important, c›est que grâce à vous, mon seigneur, nous sommes tous les deux en vie maintenant."
  },
  AvgDialog_13948_Content_45 = {
    Text = "Pourquoi penses-tu cela ?"
  },
  AvgDialog_13948_Content_46 = {
    Text = "Maintenant, je connais la réponse."
  },
  AvgDialog_13948_Content_47 = {
    Text = "Quelle est la réponse ?"
  },
  AvgDialog_13948_Content_48 = {
    Text = "Une nuée d›oiseaux marins s›envola soudain ensemble. Leurs ailes blanches battaient comme des nuages en vol, dérivant librement dans la brise marine."
  },
  AvgDialog_13948_Content_49 = {
    Text = "Goliath ne se souciait pas de la nuée d›oiseaux. Il fixait droit devant lui, les yeux brillants d›excitation."
  },
  AvgDialog_13948_Content_5 = {
    Text = "Des chants anciens et sinistres résonnent au loin. La silhouette d'une femme apparaît et disparaît à la proue, telle un fantôme errant dans la brume."
  },
  AvgDialog_13948_Content_50 = {
    Text = "Parce que je suis Goliath."
  },
  AvgDialog_13948_Content_51 = {
    Text = "Goliath, le chef au plus long règne de l›histoire philistine, un géant indomptable et un héros tribal légendaire."
  },
  AvgDialog_13948_Content_52 = {
    Text = "Même s›il ne reste qu›un seul disciple, tant qu›il y a une lueur d›espoir, je peux me relever."
  },
  AvgDialog_13948_Content_53 = {
    Text = "Cette sorcière est ma dernière chance. Seulement elle peut m›accorder le Pouvoir absolu."
  },
  AvgDialog_13948_Content_54 = {
    Text = "Même si c›est un piège, j›irai."
  },
  AvgDialog_13948_Content_55 = {
    Text = "Pourquoi me sauver, alors ? Un « bon à rien » comme moi ne peut probablement pas vous être d›une quelconque aide..."
  },
  AvgDialog_13948_Content_56 = {
    Text = "Vous avez délibérément accentué la prononciation d›un mot, faisant éclater de rire Goliath."
  },
  AvgDialog_13948_Content_57 = {
    Text = "La lumière du soleil perce les nuages, projetant une lueur dorée. Des mèches de cheveux dansent doucement sous le ciel azur."
  },
  AvgDialog_13948_Content_58 = {
    Text = "Un commandant sans troupes ne peut pas réussir dans ce monde."
  },
  AvgDialog_13948_Content_59 = {
    Text = "Petit, tu n›es pas inutile.\nTu es l›unique disciple du géant Goliath, et personne ne peut te remplacer."
  },
  AvgDialog_13948_Content_6 = {
    Text = "Hein, quelqu'un chante ?"
  },
  AvgDialog_13948_Content_60 = {
    Text = "Quand j›aurai établi ma domination, au minimum, je te nommerai chef de tribu !"
  },
  AvgDialog_13948_Content_61 = {
    Text = "...Ce n›est pas nécessaire."
  },
  AvgDialog_13948_Content_62 = {
    Text = "Le ciel s›assombrit progressivement. La lueur du crépuscule ressemblait à des rivières dorées scintillantes coulant à travers l›horizon."
  },
  AvgDialog_13948_Content_63 = {
    Text = "Hé, tu sais quoi ? Les héros ne peuvent être des héros que grâce à des gens comme nous."
  },
  AvgDialog_13948_Content_64 = {
    Text = "<Small:Alors je suis important moi aussi, compris...>"
  },
  AvgDialog_13948_Content_65 = {
    Text = "<Small:Hmm...>"
  },
  AvgDialog_13948_Content_66 = {
    Text = "Des mots fragmentés se dispersent comme des pissenlits dans la brise marine, emportés loin, très loin."
  },
  AvgDialog_13948_Content_67 = {
    Text = "Vous et Goliath étiez assis sur une fine planche de bois, ressemblant à de minuscules feuilles dérivant dans une mer dorée."
  },
  AvgDialog_13948_Content_68 = {
    Text = "Personne ne sait vers où vous naviguerez finalement."
  },
  AvgDialog_13948_Content_7 = {
    Text = "<Shake:La sorcière, c'est la sorcière !>"
  },
  AvgDialog_13948_Content_8 = {
    Text = "Comment est–ce possible... La légende serait–elle donc vraie..."
  },
  AvgDialog_13948_Content_9 = {
    Text = "<Red:Pitié.\n         Pitié.\n                  Pitié...>"
  },
  AvgDialog_139656_Content_1 = {Text = "Au revoir"},
  AvgDialog_139656_Content_10 = {
    Text = "Telle que je suis maintenant...? Hmm. Il vaudrait mieux que tu ne la voies pas."
  },
  AvgDialog_139656_Content_11 = {
    Text = "Après le lien de tout à l'heure... beaucoup de choses ont changé."
  },
  AvgDialog_139656_Content_12 = {
    Text = "À ce propos... j'ai fait un rêve."
  },
  AvgDialog_139656_Content_13 = {
    Text = "Dans le rêve, Ramona était devenue..."
  },
  AvgDialog_139656_Content_14 = {
    Text = "Peu importe combien de fois vous l'avez retourné dans votre esprit, l'image résiste toujours aux mots. Votre corps recule avant même que vos pensées ne puissent suivre."
  },
  AvgDialog_139656_Content_15 = {
    Text = "Je sais. Tu étais terrifié. Révulsé."
  },
  AvgDialog_139656_Content_16 = {
    Text = "Le Domaine fait partie de mon Paysage Mental — donc je pouvais le ressentir."
  },
  AvgDialog_139656_Content_17 = {
    Text = "Je suis vraiment désolée, pour ce que je t'ai fait subir."
  },
  AvgDialog_139656_Content_18 = {
    Text = "Non — ce n'est pas ce que je voulais dire."
  },
  AvgDialog_139656_Content_19 = {
    Text = "Je veux dire... à ce moment-là, je ne savais pas si cette chose enveloppée de chair était vraiment elle."
  },
  AvgDialog_139656_Content_2 = {
    Text = "Le monde est redevenu « normal ». Normal selon les standards de votre monde."
  },
  AvgDialog_139656_Content_20 = {
    Text = "Mais maintenant je le sais. C'était la Ramona que je connais. Alors, je n'ai plus peur."
  },
  AvgDialog_139656_Content_21 = {
    Text = "Les mots vous stabilisent. Votre voix devient progressivement plus assurée."
  },
  AvgDialog_139656_Content_22 = {
    Text = "L'apparence n'a pas d'importance. Ce qui compte, c'est uniquement le lien entre moi et mes Corps éveillés — ceux qui passent à travers les Cœurs d'argent."
  },
  AvgDialog_139656_Content_23 = {
    Text = "J'ai vu trop de choses comme ça pour être ébranlé par les apparences seules."
  },
  AvgDialog_139656_Content_24 = {
    Text = "J'ai vu un cœur d'or pur naître de la fange la plus immonde du monde ;"
  },
  AvgDialog_139656_Content_25 = {
    Text = "J'ai vu l'amour — un amour vrai, tendre — prendre racine dans le désir de procréation le plus fiévreux. Alors —"
  },
  AvgDialog_139656_Content_26 = {
    Text = "Tout devient silencieux."
  },
  AvgDialog_139656_Content_27 = {
    Text = "Après une longue pause, un sourire ondule de l'autre côté du lien — calme et serein."
  },
  AvgDialog_139656_Content_28 = {
    Text = "...Je suis si heureuse de t'avoir rencontré."
  },
  AvgDialog_139656_Content_29 = {
    Text = "… Puis, dans le Labyrinthe ébranlé, vous avez de nouveau sombré dans ce Rêve."
  },
  AvgDialog_139656_Content_3 = {
    Text = "Du sable jaune noyé sous la boue de dissolution s'étend en une étendue hurlante et sans fin."
  },
  AvgDialog_139656_Content_30 = {
    Text = "Bｸi&Eｨnｴv0ﾋeNｺuEｸ à3 l缮›UｱnﾉiｲvEｸrS巛iT龠ｻéｦ dｭeｲsｲ %player%."
  },
  AvgDialog_139656_Content_31 = {
    Text = "Le son visqueux et guttural rampe hors d'une masse de chair putréfiée et grouillante."
  },
  AvgDialog_139656_Content_32 = {
    Text = "Dans un monde recouvert de sang et de boue, Ramona — luisante de fluide — tend la main. Ses doigts effleurent à peine votre auriculaire."
  },
  AvgDialog_139656_Content_33 = {
    Text = "Je n'oublierai jamais cet instant."
  },
  AvgDialog_139656_Content_34 = {
    Text = "Vous murmurez doucement dans votre cœur."
  },
  AvgDialog_139656_Content_35 = {
    Text = "Qｸu&Eｨ lｴaﾋ Cｺl3éEｸ dｱ›AﾉrｲgEｸnT巛 éCｻlｦAｭiRｲeｲ vｸOtRe cHeMiN."
  },
  AvgDialog_139656_Content_36 = {
    Text = "Au milieu de la chair et de la désolation, vous saisissez fermement la main de Ramona, plongeant votre regard droit dans ses yeux creux et sa silhouette maculée de sang."
  },
  AvgDialog_139656_Content_37 = {
    Text = ": Que la clé d'argent nous guide"
  },
  AvgDialog_139656_Content_38 = {
    Text = "L'éclat de la Clé d'argent se diffuse à travers le monde entier."
  },
  AvgDialog_139656_Content_39 = {
    Text = "Une silhouette d'un blanc pur apparaît dans votre esprit. C'est Saya, souriante."
  },
  AvgDialog_139656_Content_4 = {
    Text = "Seule la petite cabane dans les bois est baignée de la couleur crue et charnelle des entrailles. Et à travers le lien, vous sentez Saya à l'intérieur. Vous savez que sa fin n'est plus qu'à quelques battements de cœur."
  },
  AvgDialog_139656_Content_40 = {
    Text = "Quelque chose semblable à de magnifiques ailes palpite dans le vent."
  },
  AvgDialog_139656_Content_41 = {
    Text = "Des pissenlits s'envolent, se dispersant dans le ciel azuré."
  },
  AvgDialog_139656_Content_42 = {
    Text = "À l'instant où chaque graine se détache de la tige, le monde brumeux et onirique s'efface pour laisser place à la réalité."
  },
  AvgDialog_139656_Content_43 = {
    Text = "Vous vous éveillez du rêve, et toutes choses révèlent leur véritable forme."
  },
  AvgDialog_139656_Content_44 = {Text = "Merci..."},
  AvgDialog_139656_Content_45 = {
    Text = "Vous semblez entendre un adieu murmuré à votre oreille. Est-ce une illusion ?"
  },
  AvgDialog_139656_Content_46 = {
    Text = "À un moment donné, un Cœur d'argent apparaît dans votre paume."
  },
  AvgDialog_139656_Content_47 = {
    Text = "C'est le même cœur que Tinct avait autrefois trouvé, celui imprégné d'une nostalgie éternelle."
  },
  AvgDialog_139656_Content_48 = {
    Text = "Le moment venu, vous pourrez l'utiliser — pour réveiller son « amour » éternel."
  },
  AvgDialog_139656_Content_49 = {
    Text = "—L'amour de Saya... le Corps éveillé."
  },
  AvgDialog_139656_Content_5 = {
    Text = "Je crois que nos âmes sont liées désormais. Et avec cela... la barrière disparaîtra complètement."
  },
  AvgDialog_139656_Content_6 = {
    Text = "Pouvoir ressentir cela en mes derniers instants... je suis comblée. ...Merci."
  },
  AvgDialog_139656_Content_7 = {
    Text = "Maintenant — quittez cet endroit. Marchez dans le sable. Au bord de cette mer de dunes, vous retrouverez votre passé."
  },
  AvgDialog_139656_Content_8 = {
    Text = "Tout va bien. Même quand j'aurai quitté ce monde, nos consciences resteront connectées à travers les Cœurs d'argent."
  },
  AvgDialog_139656_Content_9 = {
    Text = "Avant la fin — me laisseras-tu voir ta vraie forme ?"
  },
  AvgDialog_139657_Content_1 = {
    Text = "«Raison d'Être»"
  },
  AvgDialog_139657_Content_10 = {
    Text = "Quelque chose approche. Je le sens aux confins..."
  },
  AvgDialog_139657_Content_11 = {
    Text = "Saya fronce les sourcils, le visage crispé et blême."
  },
  AvgDialog_139657_Content_12 = {
    Text = "Tu arraches la chair de son poignet et l'aides à se relever."
  },
  AvgDialog_139657_Content_13 = {
    Text = "Je veux voir le champ de pissenlits. Tu veux bien marcher un peu avec moi ?"
  },
  AvgDialog_139657_Content_14 = {
    Text = "Tu devrais te reposer..."
  },
  AvgDialog_139657_Content_15 = {
    Text = "Ça va. Vraiment..."
  },
  AvgDialog_139657_Content_16 = {
    Text = "Saya pousse doucement la porte de la cabane. Le monde extérieur envahit ton champ de vision."
  },
  AvgDialog_139657_Content_17 = {
    Text = "La couleur du champ a changé."
  },
  AvgDialog_139657_Content_18 = {
    Text = "La verdure luxuriante d'hier est désormais recouverte d'une ombre d'un rouge–noir profond. Les brins épars ne tiennent plus, déformés et dévorés par la décomposition."
  },
  AvgDialog_139657_Content_19 = {
    Text = "C'est la <Red:Dissolution>... !"
  },
  AvgDialog_139657_Content_2 = {
    Text = "Des rêves grotesques déferlent sur vous comme une marée."
  },
  AvgDialog_139657_Content_20 = {
    Text = "Tu as l'air... triste ?"
  },
  AvgDialog_139657_Content_21 = {
    Text = "Hier, c'était un magnifique champ de pissenlits."
  },
  AvgDialog_139657_Content_22 = {
    Text = "Aujourd'hui, la Dissolution l'a trouvé, englouti tout entier. Dans quelques jours, il aura complètement disparu."
  },
  AvgDialog_139657_Content_23 = {
    Text = "Et avec assez de temps, même le souvenir s'effacera — même du tien."
  },
  AvgDialog_139657_Content_24 = {
    Text = "Cela ne t'afflige pas ?"
  },
  AvgDialog_139657_Content_25 = {
    Text = "Hmm, c'est ce que tu ressens... ?"
  },
  AvgDialog_139657_Content_26 = {
    Text = "Tu vois les choses différemment ?"
  },
  AvgDialog_139657_Content_27 = {
    Text = "Mm. Il y a toujours tellement de choses différentes dans ce monde..."
  },
  AvgDialog_139657_Content_28 = {
    Text = "Et les plus forts s›emparent de ce que possèdent les plus faibles et les pillent."
  },
  AvgDialog_139657_Content_29 = {
    Text = "C›est comme ça, non ?"
  },
  AvgDialog_139657_Content_3 = {
    Text = "La silhouette de Ramona vacille, apparaissant et disparaissant—sa voix déchirée aux coutures, râpant comme de l'air forcé à travers un soufflet brisé."
  },
  AvgDialog_139657_Content_30 = {
    Text = "Non. C›est précisément pour cela que le Mizag existe."
  },
  AvgDialog_139657_Content_31 = {
    Text = "Nous nous dressons entre la Dissolution et tout ce qu›elle voudrait engloutir — des vies et des souvenirs qui ne sont peut-être pas puissants, mais qui portent encore leur propre lumière."
  },
  AvgDialog_139657_Content_32 = {
    Text = "Et cela t›inclut, Saya."
  },
  AvgDialog_139657_Content_33 = {
    Text = "...C›est donc ça."
  },
  AvgDialog_139657_Content_34 = {
    Text = "Elle le murmure pour elle-même."
  },
  AvgDialog_139657_Content_35 = {
    Text = "Dans ce cas... peut-être que tu as raison..."
  },
  AvgDialog_139657_Content_36 = {
    Text = "Vous traversez ce paysage qui se répète pendant ce qui semble une éternité, jusqu›à ce qu›un fragment de quelque chose de différent brise enfin la monotonie."
  },
  AvgDialog_139657_Content_37 = {
    Text = "Encore un champ de pissenlits... ?"
  },
  AvgDialog_139657_Content_38 = {
    Text = "Saya a la tête baissée, respirant doucement. Vous ne pouvez pas voir son visage."
  },
  AvgDialog_139657_Content_39 = {
    Text = "C›est... la cabane d›où nous sommes partis. Regarde là-bas."
  },
  AvgDialog_139657_Content_4 = {
    Text = "Vous vous réveillez en sursaut."
  },
  AvgDialog_139657_Content_40 = {
    Text = "Vous pointez du doigt le coin de la pièce — le morceau de chair que vous aviez arraché du poignet de Saya et jeté ce matin."
  },
  AvgDialog_139657_Content_41 = {
    Text = "...Nous avons tourné en rond."
  },
  AvgDialog_139657_Content_42 = {
    Text = "Il n›y a rien dans ce Domaine à part la désolation."
  },
  AvgDialog_139657_Content_43 = {
    Text = "C›est aussi bien. Nous pouvons... nous reposer un moment."
  },
  AvgDialog_139657_Content_44 = {
    Text = "Elle sourit comme si de rien n›était. Mais sa voix s›effiloche sur les bords, tremblant légèrement, d›une manière qu›elle ne peut tout à fait contenir."
  },
  AvgDialog_139657_Content_45 = {
    Text = "Saya, ton corps..."
  },
  AvgDialog_139657_Content_46 = {
    Text = "Je suis juste un peu fatiguée..."
  },
  AvgDialog_139657_Content_47 = {
    Text = "Sous vos yeux, ses genoux cèdent — elle s'effondre sur place, comme si tout ce qui la maintenait debout venait simplement de lâcher."
  },
  AvgDialog_139657_Content_48 = {Text = "Saya !"},
  AvgDialog_139657_Content_49 = {
    Text = "Au cœur de la nuit, Saya brûle de fièvre. En suivant ses instructions, vous allumez un feu avec des matériaux dont vous seriez bien incapable de donner le nom."
  },
  AvgDialog_139657_Content_5 = {
    Text = "*Tousse, tousse...*"
  },
  AvgDialog_139657_Content_50 = {
    Text = "Si j'avais su que vous étiez aussi malade, jamais je ne vous aurais laissée marcher toute la journée..."
  },
  AvgDialog_139657_Content_51 = {
    Text = "Ce n'est rien. Je ne pense pas que ce soit la marche qui m'ait rendue malade.\nEn tout cas — on peut discuter un peu ?"
  },
  AvgDialog_139657_Content_52 = {
    Text = "Bien sûr. De quoi aimeriez-vous parler ?"
  },
  AvgDialog_139657_Content_53 = {
    Text = "Ce matin, vous avez dit que Mizag et vous vouliez combattre la Dissolution. Pour protéger les autres. Pour me protéger."
  },
  AvgDialog_139657_Content_54 = {
    Text = "Vous le pensiez vraiment ?"
  },
  AvgDialog_139657_Content_55 = {
    Text = "Chaque mot. J'en ai fait le serment le jour où l'on m'a confié la Clé d'argent."
  },
  AvgDialog_139657_Content_56 = {
    Text = "Votre voix sort plus assurée que vous ne l'auriez cru. À l'instant où les mots franchissent vos lèvres, la cérémonie resurgit dans votre esprit —"
  },
  AvgDialog_139657_Content_57 = {
    Text = "Le poids frais de la Clé d'argent se dépose dans votre paume. Les regards solennels de l'assemblée. La détermination brûlante dans votre cœur lorsque vos doigts se sont refermés dessus."
  },
  AvgDialog_139657_Content_58 = {
    Text = "Saya se tait un instant. La lueur du feu nimbe la courbe délicate de sa silhouette d'un éclat chaud et ambré."
  },
  AvgDialog_139657_Content_59 = {
    Text = "Alors — si un jour vous perdiez votre pouvoir de Gardien... si vous deveniez une personne ordinaire,"
  },
  AvgDialog_139657_Content_6 = {
    Text = "Saya est adossée à la porte de la cabine, toussant doucement."
  },
  AvgDialog_139657_Content_60 = {
    Text = "et que vous ne pouviez plus assumer le devoir de lutter contre la Dissolution... que feriez-vous ?"
  },
  AvgDialog_139657_Content_61 = {
    Text = "Eh bien, j'y ai déjà réfléchi."
  },
  AvgDialog_139657_Content_62 = {
    Text = "Vous vous adossez en arrière, les mains posées dans l'herbe derrière vous, le visage levé vers les étoiles."
  },
  AvgDialog_139657_Content_63 = {
    Text = "Je passerais le reste de ma vie avec les gens que j'aime. Tranquillement. Simplement."
  },
  AvgDialog_139657_Content_64 = {
    Text = "Quand nous serons vieux et grisonnants, trop fatigués pour courir encore, nous nous installerons autour du foyer pour raconter les mêmes petites mésaventures de jeunesse jusqu'à ce que tout le monde les connaisse par cœur."
  },
  AvgDialog_139657_Content_65 = {
    Text = "Ramona serait encore en train de corriger chaque nom que le Seigneur Dexter prononçait mal. William aurait ce même air parfaitement composé sur le visage, tenant un livre comme s'il lisait pendant que ses oreilles sont dressées..."
  },
  AvgDialog_139657_Content_66 = {
    Text = "La professeure Czort serait toujours agrippée à sa vodka, entraînant tout le monde dans une chanson dès qu'elle serait lancée."
  },
  AvgDialog_139657_Content_67 = {
    Text = "Vous tournez la tête. Saya vous observe en silence. La lueur du feu danse dans ses yeux comme de minuscules étoiles captives."
  },
  AvgDialog_139657_Content_68 = {
    Text = "Ça a l›air merveilleux."
  },
  AvgDialog_139657_Content_69 = {Text = "Mais..."},
  AvgDialog_139657_Content_7 = {
    Text = "Saya ! Ta main !"
  },
  AvgDialog_139657_Content_70 = {
    Text = "Sa voix se brise. Elle détourne le regard, les yeux voilés, fixés sur le vide d›un coin sombre."
  },
  AvgDialog_139657_Content_71 = {
    Text = "Si tu étais séparé d›eux — s›il ne restait plus personne à tes côtés — que ferais-tu alors ?"
  },
  AvgDialog_139657_Content_72 = {
    Text = "Sont-ils partis ? Ou n›ont-ils jamais existé ?"
  },
  AvgDialog_139657_Content_73 = {
    Text = "Si... tu avais encore les souvenirs. De votre rencontre, du temps passé ensemble..."
  },
  AvgDialog_139657_Content_74 = {
    Text = "Mais trop de temps a passé. Les souvenirs sont en morceaux. Et tu ne sais même pas s›ils sont réels..."
  },
  AvgDialog_139657_Content_75 = {
    Text = "Tant que je peux encore m›en souvenir, j›irai les chercher."
  },
  AvgDialog_139657_Content_76 = {
    Text = "Où qu›ils soient. Quoi qu›il en coûte."
  },
  AvgDialog_139657_Content_77 = {
    Text = "Il n›y a pas la moindre hésitation dans votre regard."
  },
  AvgDialog_139657_Content_78 = {
    Text = "Si... je veux dire, si tu ne les trouves pas ?"
  },
  AvgDialog_139657_Content_79 = {
    Text = "Je continuerais à chercher malgré tout — sur chaque route, par-delà chaque montagne, à travers chaque mer..."
  },
  AvgDialog_139657_Content_8 = {
    Text = "De la chair parcourue de boue noire s'est faufilée par les interstices de la porte et s'est enroulée autour de son poignet."
  },
  AvgDialog_139657_Content_80 = {
    Text = "Jusqu›à ce que la quête elle-même m›accompagne jusqu›au dernier de mes jours."
  },
  AvgDialog_139657_Content_81 = {
    Text = "Et quand ce dernier instant viendrait, quand mes yeux se fermeraient enfin, je crois que je me sentirais en paix."
  },
  AvgDialog_139657_Content_82 = {
    Text = "Car j›aurais vécu avec des souvenirs qui méritaient d›être gardés, et une destination que j›étais destiné à atteindre, quel qu›en soit le prix."
  },
  AvgDialog_139657_Content_83 = {
    Text = "La quête elle-même est le sens."
  },
  AvgDialog_139657_Content_84 = {
    Text = "Le silence retombe tandis que vos paroles se posent. Seul demeure le doux bruissement des pissenlits dans la brise."
  },
  AvgDialog_139657_Content_85 = {Text = "...Saya ?"},
  AvgDialog_139657_Content_86 = {
    Text = "Saya a fermé les yeux. Son visage est pâle, presque translucide. Votre cœur se serre."
  },
  AvgDialog_139657_Content_87 = {Text = "Saya..."},
  AvgDialog_139657_Content_88 = {
    Text = "Vous vous penchez—et constatez que sa respiration est lente et régulière, sa poitrine se soulevant et s'abaissant dans un rythme à peine perceptible, comme la plus infime ondulation sur un lac immobile."
  },
  AvgDialog_139657_Content_89 = {
    Text = "Hmm, tu dors, c'est tout..."
  },
  AvgDialog_139657_Content_9 = {
    Text = "Ce genre de changements... ce n'est pas ce qui m'inquiète."
  },
  AvgDialog_139657_Content_90 = {
    Text = "Je suis... un peu fatiguée aussi..."
  },
  AvgDialog_139657_Content_91 = {
    Text = "Le soulagement vous frappe d'un coup, et avec lui, l'épuisement de la journée et la fatigue visuelle de ce paysage infernal finissent par vous submerger."
  },
  AvgDialog_139657_Content_92 = {
    Text = "Avant que la fin n'arrive, cette nuit, elle aussi, glisse silencieusement entre vos doigts."
  },
  AvgDialog_139658_Content_1 = {
    Text = "Après la Pluie"
  },
  AvgDialog_139658_Content_10 = {
    Text = "Comme c'est agréable... de sentir le soleil."
  },
  AvgDialog_139658_Content_11 = {
    Text = "Elle sourit, tendant la main vers l'endroit où tombe la lumière, comme une plante se penchant vers le soleil."
  },
  AvgDialog_139658_Content_12 = {
    Text = "Tu veux bien m'aider à sortir ?"
  },
  AvgDialog_139658_Content_13 = {
    Text = "Vous la guidez pour qu'elle s'assoie contre le mur de la cabane. Même ce court trajet la laisse haletante, sa respiration courte et laborieuse."
  },
  AvgDialog_139658_Content_14 = {
    Text = "Saya, ton corps..."
  },
  AvgDialog_139658_Content_15 = {
    Text = "Ne t'en fais pas. Je crois que mon heure est presque venue."
  },
  AvgDialog_139658_Content_16 = {
    Text = "Tu le sens aussi, n'est-ce pas ? La barrière qui bloque notre lien... elle s'effrite."
  },
  AvgDialog_139658_Content_17 = {
    Text = "Il ne faudra plus longtemps avant qu'elle ne s'effondre entièrement.\nQuand ce sera le cas... nous devrions pouvoir établir le lien dont vous avez parlé."
  },
  AvgDialog_139658_Content_18 = {Text = "Mais..."},
  AvgDialog_139658_Content_19 = {
    Text = "Une fois le lien formé, Saya pourrait disparaître. Cette barrière est son dernier bouclier — et elle ne s'amincit que parce que ses forces l'abandonnent."
  },
  AvgDialog_139658_Content_2 = {
    Text = "Quand vous vous réveillez, la lumière a changé."
  },
  AvgDialog_139658_Content_20 = {
    Text = "S'il te plaît, ne te retiens pas. T'avoir ici avec moi, pouvoir parler comme ça... je suis vraiment heureuse."
  },
  AvgDialog_139658_Content_21 = {
    Text = "Elle plisse les yeux face à la lumière, offrant un sourire sincère mais fragile. Tu peux à peine te résoudre à regarder, mais tu te forces à graver chaque détail dans ta mémoire."
  },
  AvgDialog_139658_Content_22 = {
    Text = "Je resterai avec toi. Jusqu'à la toute fin."
  },
  AvgDialog_139658_Content_23 = {
    Text = "Allez, ne fais pas cette tête. Reprenons là où nous nous sommes arrêtés hier."
  },
  AvgDialog_139658_Content_24 = {
    Text = "Tu as dit que même sans ton pouvoir, même sans personne à tes côtés, tu continuerais."
  },
  AvgDialog_139658_Content_25 = {
    Text = "Je veux savoir pourquoi."
  },
  AvgDialog_139658_Content_26 = {
    Text = "Pourquoi ? La lumière du soleil après la pluie est assez vive pour faire piquer les yeux de larmes retenues."
  },
  AvgDialog_139658_Content_27 = {
    Text = "Tu inspires lentement, posément."
  },
  AvgDialog_139658_Content_28 = {
    Text = "Parce que j'aime Ramona. J'aime tout le monde à l'Université de Misargh.\nEt je sais — avec certitude — qu'ils m'aiment aussi."
  },
  AvgDialog_139658_Content_29 = {
    Text = "Mais vous êtes si loin l'un de l'autre. Vous ne pouvez pas vous toucher. Vous ne pouvez pas confirmer ce que l'autre ressent."
  },
  AvgDialog_139658_Content_3 = {
    Text = "L'air humide porte un parfum pur et lavé. Ce qui s'infiltre par les interstices de la porte n'est plus le vent, mais un rayon de lumière silencieux."
  },
  AvgDialog_139658_Content_30 = {
    Text = "Et dans un monde où existe quelque chose comme la Fusion—comment pouvez-vous être sûr que les gens qui vous manquent ne vous ont pas déjà oublié ?"
  },
  AvgDialog_139658_Content_31 = {
    Text = "Sa voix est douce, presque comme un rêve murmuré au bord du sommeil."
  },
  AvgDialog_139658_Content_32 = {
    Text = "La Dissolution peut effacer la présence — mais les Cœurs d'argent lient Ramona et moi à travers la mer du subconscient."
  },
  AvgDialog_139658_Content_33 = {
    Text = "Tu regardes au loin. L'horizon après la pluie est d'une clarté impossible. Le vent déchire une brèche dans les nuages, et un pilier de lumière dorée s'y déverse, frappant la crête lointaine."
  },
  AvgDialog_139658_Content_34 = {
    Text = "Je peux sentir sa présence. Même maintenant, même dispersés à travers différents mondes — cela n'a pas changé."
  },
  AvgDialog_139658_Content_35 = {
    Text = "Et aussi..."
  },
  AvgDialog_139658_Content_36 = {Text = "Hmm?"},
  AvgDialog_139658_Content_37 = {
    Text = "Elle incline légèrement la tête."
  },
  AvgDialog_139658_Content_38 = {
    Text = "Les vrais amants n'ont pas besoin d'être côte à côte pour ressentir leur lien... ni pour confirmer leur amour."
  },
  AvgDialog_139658_Content_39 = {
    Text = "Peu importe combien de fois le monde prend fin et recommence, je retrouverai toujours Ramona. Et elle fera toujours le même choix."
  },
  AvgDialog_139658_Content_4 = {
    Text = "...C'est si calme dehors."
  },
  AvgDialog_139658_Content_40 = {
    Text = "Je le sais, c›est tout. Les pensées et les sentiments que nous partageons dans la mer de conscience... ne seront jamais rompus."
  },
  AvgDialog_139658_Content_41 = {
    Text = "Saya reste silencieuse un long moment. Le vent lavé par la pluie traverse la cabine, effleurant sa joue exsangue."
  },
  AvgDialog_139658_Content_42 = {
    Text = "Puis elle sourit."
  },
  AvgDialog_139658_Content_43 = {
    Text = "Une confiance si farouche, si inébranlable... Un si grand amour..."
  },
  AvgDialog_139658_Content_44 = {
    Text = "Quand elle prononce ce mot — amour — il n›y a nulle envie dans sa voix. Nulle tristesse. Nulle trace de désir."
  },
  AvgDialog_139658_Content_45 = {
    Text = "Seulement une profonde tendresse."
  },
  AvgDialog_139658_Content_46 = {
    Text = "Comme une voyageuse ayant marché seule à travers une longue nuit d›hiver, et qui aperçoit enfin la première lueur de l›aube au lointain bord de l›horizon — peut–être ne l›atteindra–t–elle jamais. Mais savoir simplement que cette lumière existe lui suffit."
  },
  AvgDialog_139658_Content_47 = {
    Text = "Saya sourit, perdue dans une rêverie."
  },
  AvgDialog_139658_Content_48 = {
    Text = "Puis elle tend la main vers vous."
  },
  AvgDialog_139658_Content_49 = {
    Text = "...Prends ma main."
  },
  AvgDialog_139658_Content_5 = {
    Text = "La pluie... elle s'est arrêtée ?"
  },
  AvgDialog_139658_Content_50 = {
    Text = "Sa main est pâle, fine, et tremble légèrement. Elle ne peut pas vous voir, pourtant sa main se tend infailliblement dans votre direction —"
  },
  AvgDialog_139658_Content_51 = {
    Text = "comme guidée par quelque chose de plus ancien que la vue, de plus profond que le langage."
  },
  AvgDialog_139658_Content_52 = {
    Text = "Vous tendez la main et prenez la sienne."
  },
  AvgDialog_139658_Content_53 = {
    Text = "Et à l›instant où vos paumes se rencontrent —"
  },
  AvgDialog_139658_Content_54 = {
    Text = "Une douleur aiguë explose derrière vos yeux."
  },
  AvgDialog_139658_Content_55 = {
    Text = "Quelque chose de bien plus vif que cela — brûlant, incandescent — se plante comme un éclair à travers votre crâne, frappant droit au cœur le plus profond de votre esprit."
  },
  AvgDialog_139658_Content_56 = {
    Text = "Votre vision vacille violemment."
  },
  AvgDialog_139658_Content_57 = {
    Text = "Vous voyez des pissenlits humides scintillant au soleil. Le profil pâle et serein de Saya. Le sourire qui ourle ses lèvres craquelées —"
  },
  AvgDialog_139658_Content_58 = {
    Text = "Et puis tout bascule dans un univers de chair. Le ciel vire au rouge sang. La terre vire au rouge sang. Même la Saya juste devant vous —"
  },
  AvgDialog_139658_Content_59 = {Text = "Non—"},
  AvgDialog_139658_Content_6 = {
    Text = "Saya regarde vers la fenêtre, le regard voilé et flou."
  },
  AvgDialog_139658_Content_60 = {
    Text = "Deux mondes clignotent, se superposent et fusionnent dans votre vision. Deux rivières qui n'auraient jamais dû se rencontrer entrent violemment en collision à une jonction impossible."
  },
  AvgDialog_139658_Content_61 = {
    Text = "Le lien entre vous et Saya est complet."
  },
  AvgDialog_139658_Content_7 = {
    Text = "La lumière du soleil tombe dans ses yeux comme une pierre tombe dans une eau immobile—et ne soulève aucune ondulation."
  },
  AvgDialog_139658_Content_8 = {Text = "Oui."},
  AvgDialog_139658_Content_9 = {
    Text = "Les mots sortent rauques."
  },
  AvgDialog_139659_Content_1 = {Text = "«Amour»"},
  AvgDialog_139659_Content_10 = {
    Text = "Saya se tient dans le champ de pissenlits, baignée par la lumière du matin."
  },
  AvgDialog_139659_Content_11 = {
    Text = "La pluie a arraché d›innombrables graines de leurs tiges. Elles sont tombées sur la terre rouge–noire — et certaines, contre toute attente, ont déjà commencé à germer."
  },
  AvgDialog_139659_Content_12 = {
    Text = "Nées en une nuit, poussées en une nuit..."
  },
  AvgDialog_139659_Content_13 = {
    Text = "À voir votre expression... quelque chose vous est revenu en mémoire ?"
  },
  AvgDialog_139659_Content_14 = {
    Text = "Oui. J›ai vu un spectacle similaire dans les déserts d›Aran."
  },
  AvgDialog_139659_Content_15 = {
    Text = "La terre là–bas est bénie par l›Arbre–Mère. Les descendants de sa lignée prennent racine où qu›ils tombent, grandissant avec le vent."
  },
  AvgDialog_139659_Content_16 = {
    Text = "Ça a l›air agréable, non ?"
  },
  AvgDialog_139659_Content_17 = {
    Text = "...Mais à la façon dont vous l›avez dit, vous ne semblez pas le penser."
  },
  AvgDialog_139659_Content_18 = {
    Text = "Ce n'est pas à moi de juger. Je suis une étrangère dans cette histoire."
  },
  AvgDialog_139659_Content_19 = {
    Text = "C'est juste que... je pense que pour la plupart des gens, chaque étape de la vie compte."
  },
  AvgDialog_139659_Content_2 = {
    Text = "Saya et vous vous blottissez chacun dans un coin de la cabane. La nuit passe en silence."
  },
  AvgDialog_139659_Content_20 = {
    Text = "Néferure, par exemple. Il n'a jamais eu de vraie enfance. Il n'a jamais su ce que c'était d'être choyé par un parent. Il a été jeté dans la guerre contre le Mur de tempête avant que tout cela puisse arriver..."
  },
  AvgDialog_139659_Content_21 = {
    Text = "Saya hoche la tête, pas tout à fait certaine de comprendre."
  },
  AvgDialog_139659_Content_22 = {
    Text = "Alors pour les humains, la durée d'une vie compte aussi ?"
  },
  AvgDialog_139659_Content_23 = {
    Text = "Plus que ça. Chaque expérience, chaque personne que tu rencontres — tout cela fait partie des souvenirs que tu portes en toi."
  },
  AvgDialog_139659_Content_24 = {
    Text = "Ces souvenirs, accumulés au fil du temps, sont ce qui fait d'une personne ce qu'elle est."
  },
  AvgDialog_139659_Content_25 = {
    Text = "On pourrait même dire que les humains sont des réceptacles de mémoire.\nMême après la disparition du corps, la mémoire perdure — transmise, jusqu'à ce que la dernière personne qui la porte l'oublie."
  },
  AvgDialog_139659_Content_26 = {
    Text = "Je vois... Je crois que je comprends."
  },
  AvgDialog_139659_Content_27 = {
    Text = "Alors — si je meurs un jour, est-ce que le souvenir d'aujourd'hui, d'être ici avec toi comme ça, deviendra une part de ce que tu es ?"
  },
  AvgDialog_139659_Content_28 = {Text = "Oui."},
  AvgDialog_139659_Content_29 = {
    Text = "Dans l'ombre du fragile sourire de Saya, tu hoches fermement la tête."
  },
  AvgDialog_139659_Content_3 = {
    Text = "À un moment donné, l›épuisement vous entraîne dans un lourd sommeil."
  },
  AvgDialog_139659_Content_30 = {
    Text = "La journée passe entre exploration et arpentage le long de la frontière."
  },
  AvgDialog_139659_Content_31 = {
    Text = "Au-delà du champ de pissenlits, le même paysage désolé se répète dans toutes les directions. La terre est ensevelie sous la chair, méconnaissable sous des couches de rouge et de noir."
  },
  AvgDialog_139659_Content_32 = {
    Text = "Un malaise prend racine dans ta poitrine, s'infiltrant dans tes pensées. Tu le refoules de force."
  },
  AvgDialog_139659_Content_33 = {
    Text = "(S'il n'y a rien ici, alors le cœur de ce Domaine ne peut être que...)"
  },
  AvgDialog_139659_Content_34 = {
    Text = "La nuit tombe à nouveau."
  },
  AvgDialog_139659_Content_35 = {
    Text = "Repose-toi. Je me sens un peu fatiguée."
  },
  AvgDialog_139659_Content_36 = {
    Text = "Bien. J'aimerais me coucher tôt — plus nous pourrons explorer demain, mieux ce sera."
  },
  AvgDialog_139659_Content_37 = {
    Text = "Sur ces mots, vous sombrez tous les deux dans le sommeil."
  },
  AvgDialog_139659_Content_38 = {Text = "新增"},
  AvgDialog_139659_Content_39 = {
    Text = "Quelque chose vous réveille. Un son—ou une chaleur. Une chaleur qui s'insinue sous votre peau—comme si vous étiez de retour dans le désert."
  },
  AvgDialog_139659_Content_4 = {
    Text = "(Si froid... J›espère que demain je pourrai dormir dans un vrai lit...)"
  },
  AvgDialog_139659_Content_40 = {Text = "?!!"},
  AvgDialog_139659_Content_41 = {
    Text = "Votre tête tourne. Vous ne savez pas si c'est la scène étrange devant vous, ou la brume qui flotte dans l'air."
  },
  AvgDialog_139659_Content_42 = {
    Text = "Ou l'influence de la Rivière sacrée."
  },
  AvgDialog_139659_Content_43 = {
    Text = "Quel dommage. N'étais-je pas celle que vous attendiez ?"
  },
  AvgDialog_139659_Content_44 = {
    Text = "Reine d'Aran—Thais a soulevé le rideau et est entrée. Elle s'est approchée sans hésitation, le mince voile s'accrochant à votre avant-bras, présentant une invitation franche."
  },
  AvgDialog_139659_Content_45 = {
    Text = "Viens, accepte la lignée d'Arlan et deviens l'un d'entre nous."
  },
  AvgDialog_139659_Content_46 = {
    Text = "Approche, embrasse-moi... Donne-moi ton sang, ton essence..."
  },
  AvgDialog_139659_Content_47 = {
    Text = "Les flammes dansent dans ses pupilles ferventes, ses joues rougies révélant un désir morbide."
  },
  AvgDialog_139659_Content_48 = {
    Text = "Juste une goutte suffit. Tant que notre chair osseuse fusionne, Il nous accordera l'avenir que nous désirons..."
  },
  AvgDialog_139659_Content_49 = {
    Text = "Portons... des descendants pour la tribu, partageant l'éternité..."
  },
  AvgDialog_139659_Content_5 = {
    Text = "Quelque chose se pose sur vous dans l›obscurité."
  },
  AvgDialog_139659_Content_50 = {
    Text = "Vous extirpez votre raison des profondeurs, luttant contre l'attraction de ses paroles. La cloche qui vous a éveillé pour la première fois en tant que Gardien reste silencieuse."
  },
  AvgDialog_139659_Content_51 = {
    Text = "Et puis—une voix différente perce le voile."
  },
  AvgDialog_139659_Content_52 = {
    Text = "Pourquoi ? Pourquoi continuez-vous à refuser ?"
  },
  AvgDialog_139659_Content_53 = {
    Text = "Elle est apparue depuis un coin de la tente sans un bruit."
  },
  AvgDialog_139659_Content_54 = {
    Text = "Sa voix est différente de d'habitude. Quelque chose de plus lourd persiste sous ses mots, quelque chose que vous ne parvenez pas tout à fait à nommer."
  },
  AvgDialog_139659_Content_55 = {
    Text = "La reproduction... Je pense que c'est une bonne chose. La raison d'être de tous les êtres vivants..."
  },
  AvgDialog_139659_Content_56 = {
    Text = "Mais pourquoi refusez-vous de l'accepter ?"
  },
  AvgDialog_139659_Content_57 = {
    Text = "Pourquoi ? Pourquoi continuez-vous à refuser ?"
  },
  AvgDialog_139659_Content_58 = {
    Text = "Parce que cela n'a rien à voir avec l'amour. Ce n'est que tentation."
  },
  AvgDialog_139659_Content_59 = {
    Text = "La tentation n'est pas l'amour. Le devoir n'est pas l'amour. Le désir n'est pas l'amour."
  },
  AvgDialog_139659_Content_6 = {Text = "...Hmm?"},
  AvgDialog_139659_Content_60 = {
    Text = "L'amour, c'est —"
  },
  AvgDialog_139659_Content_61 = {
    Text = "L'amour, c'est —"
  },
  AvgDialog_139659_Content_62 = {
    Text = "Le monde s'éteint."
  },
  AvgDialog_139659_Content_63 = {
    Text = "Tout sombre dans une longue obscurité sans lumière."
  },
  AvgDialog_139659_Content_7 = {
    Text = "Une fine couverture a été drapée sur vous."
  },
  AvgDialog_139659_Content_8 = {
    Text = "Le ciel s›est dégagé."
  },
  AvgDialog_139659_Content_9 = {
    Text = "Il est temps de sortir."
  },
  AvgDialog_139660_Content_1 = {
    Text = "«Souvenirs»"
  },
  AvgDialog_139660_Content_10 = {
    Text = "Et vous avez raison, je ne suis pas vraiment ordinaire. Je suis un enquêteur de l›Université de Misargh."
  },
  AvgDialog_139660_Content_11 = {
    Text = "Saya affiche un air perplexe — ces termes ne lui évoquent visiblement rien."
  },
  AvgDialog_139660_Content_12 = {
    Text = "C›est une longue histoire. Pour l›instant, j›ai quelque chose de plus urgent à régler."
  },
  AvgDialog_139660_Content_13 = {
    Text = "Ma partenaire, Ramona. J›ai vu quelque chose la consumer. Elle est devenue —"
  },
  AvgDialog_139660_Content_14 = {
    Text = "Vous ne finissez pas. Vous ne pouvez pas."
  },
  AvgDialog_139660_Content_15 = {
    Text = "Les mots ne sont que des symboles creux. Ils ne peuvent pas porter ce que vous avez ressenti à cet instant — la peur qui a rampé depuis la base de votre colonne vertébrale."
  },
  AvgDialog_139660_Content_16 = {
    Text = "La peur de perdre Ramona pour toujours."
  },
  AvgDialog_139660_Content_17 = {
    Text = "Elle est irremplaçable pour moi."
  },
  AvgDialog_139660_Content_18 = {
    Text = "Le regard de Saya se perd dans le vague un instant."
  },
  AvgDialog_139660_Content_19 = {
    Text = "Irremplaçable... Je vois."
  },
  AvgDialog_139660_Content_2 = {
    Text = "Avant même que vous puissiez mettre de l›ordre dans vos questions, elle prend la parole en premier."
  },
  AvgDialog_139660_Content_20 = {
    Text = "Je crois que j'ai eu... quelqu'un comme ça moi aussi."
  },
  AvgDialog_139660_Content_21 = {
    Text = "Elle baisse les yeux, les sourcils froncés, murmurant pour elle-même."
  },
  AvgDialog_139660_Content_22 = {
    Text = "Il y avait quelqu'un. Une personne très importante. Je devrais me souvenir de son visage... Je dois m'en souvenir. Mais quand j'essaie de me le représenter maintenant, tout ce que je vois c'est—"
  },
  AvgDialog_139660_Content_23 = {
    Text = "—juste un contour. Comme si je regardais à travers un verre dépoli. Je sais qu'il était là. Je sais qu'il comptait. Mais tous les détails ont été... effacés."
  },
  AvgDialog_139660_Content_24 = {
    Text = "Ce n'est pas que lui. Tout le reste est pareil. Je sais qu'il y a quelque chose que je dois faire—quelque chose d'important."
  },
  AvgDialog_139660_Content_25 = {
    Text = "Mais les souvenirs n'arrêtent pas de se contredire. L'un dit qu'il était doux ; le suivant dit que j'étais quelque part dans un endroit très sombre pendant longtemps. L'un dit que j'attendais que quelqu'un vienne me chercher ; un autre dit que je devais faire quelque chose... qui effraierait les gens."
  },
  AvgDialog_139660_Content_26 = {
    Text = "Chaque fragment semble réel. Mais ils ne s'assemblent tout simplement pas."
  },
  AvgDialog_139660_Content_27 = {
    Text = "Chaque fragment semble réel. Mais ils ne s'assemblent tout simplement pas."
  },
  AvgDialog_139660_Content_28 = {
    Text = "Vous avez déjà vu cette condition auparavant."
  },
  AvgDialog_139660_Content_29 = {
    Text = "Je ne sais pas quelles parties se sont réellement passées. Je ne sais pas quels souvenirs sont vraiment les miens..."
  },
  AvgDialog_139660_Content_3 = {
    Text = "Je suis... hmm, vous pouvez m›appeler Saya.\nSavez-vous où nous sommes ?"
  },
  AvgDialog_139660_Content_30 = {
    Text = "Je ne sais pas quelles parties se sont vraiment produites. Je ne sais pas quels souvenirs sont vraiment les miens..."
  },
  AvgDialog_139660_Content_31 = {
    Text = "Les doigts de Saya se replient vers l'intérieur, comme s'ils essayaient de saisir quelque chose qui n'existe plus."
  },
  AvgDialog_139660_Content_32 = {
    Text = "Tandis qu'elle vacille, le monde autour de vous commence à changer."
  },
  AvgDialog_139660_Content_33 = {
    Text = "Attention !"
  },
  AvgDialog_139660_Content_34 = {
    Text = "Vous regardez vers le bord du champ de pissenlits. La membrane de chair, trempée de boue noire, avance centimètre par centimètre. La frontière semble moins certaine qu'avant."
  },
  AvgDialog_139660_Content_4 = {
    Text = "Pourquoi suis-je dans un endroit pareil...\nHmm — il y a tant de choses dont je n›arrive pas à me souvenir."
  },
  AvgDialog_139660_Content_5 = {
    Text = "...Vous n›êtes pas quelqu›un d›ordinaire, n›est-ce pas ?\nAvez-vous une sorte de pouvoir spécial... ?"
  },
  AvgDialog_139660_Content_6 = {
    Text = "Vous ne répondez pas tout de suite. La fille nommée Saya lâche votre main, recule d›un demi-pas, les yeux plissés tandis qu›elle vous jauge."
  },
  AvgDialog_139660_Content_7 = {
    Text = "Vous m›avez vue et n›avez rien ressenti ? Pourquoi êtes-vous venu ici ?"
  },
  AvgDialog_139660_Content_8 = {
    Text = "Attendez, une question à la fois."
  },
  AvgDialog_139660_Content_9 = {
    Text = "D›après ce que je peux voir, il s›agit très probablement d›un Domaine."
  },
  AvgDialog_139661_Content_1 = {
    Text = "Paysage Mental"
  },
  AvgDialog_139661_Content_10 = {
    Text = "Une belle jeune fille, et un jeune homme."
  },
  AvgDialog_139661_Content_11 = {
    Text = "Main dans la main, ils marchent ensemble à travers les étendues désolées et hurlantes."
  },
  AvgDialog_139661_Content_12 = {Text = "新增"},
  AvgDialog_139661_Content_13 = {
    Text = "Elle rit doucement, ouvrant grand les bras pour embrasser le vent."
  },
  AvgDialog_139661_Content_14 = {
    Text = "Le jeune homme à ses côtés se penche, écoutant attentivement chacune de ses douces paroles."
  },
  AvgDialog_139661_Content_15 = {
    Text = "Le ciel est dégagé, pourtant teinté d'une mélancolie silencieuse."
  },
  AvgDialog_139661_Content_16 = {
    Text = "Mais dans leur silhouette partagée, vous percevez une lueur de joie tranquille et spontanée."
  },
  AvgDialog_139661_Content_17 = {
    Text = "Même s'il n'y avait personne d'autre autour, même s'ils ne recevaient ni compréhension ni bénédiction de quiconque, leur amour malgré tout —"
  },
  AvgDialog_139661_Content_18 = {
    Text = "Puis le rêve s'interrompt. La tempête de sable emporte tout."
  },
  AvgDialog_139661_Content_19 = {
    Text = "Le monde sombre dans un noir de néant."
  },
  AvgDialog_139661_Content_2 = {
    Text = "Le monde est fait de sable."
  },
  AvgDialog_139661_Content_20 = {
    Text = "— Il y avait autrefois une chanteuse, cheminant parmi les étoiles."
  },
  AvgDialog_139661_Content_21 = {
    Text = "Dans un univers aride et désolé, elle trouva un Cœur d'argent gisant dans la poussière."
  },
  AvgDialog_139661_Content_22 = {
    Text = "À l'instant où elle le toucha, « Je » m'éveillai."
  },
  AvgDialog_139661_Content_23 = {
    Text = "« Je » avais perdu toute mémoire. Mais « Je » savais une chose : je devais trouver cette « personne irremplaçable »."
  },
  AvgDialog_139661_Content_24 = {
    Text = "« Je » demandai à la chanteuse si nous pouvions voyager ensemble, mais la requête fut refusée."
  },
  AvgDialog_139661_Content_25 = {
    Text = "Je vais retrouver celle qui compte plus que tout pour moi — ma sœur."
  },
  AvgDialog_139661_Content_26 = {
    Text = "C'est ce qu'elle dit."
  },
  AvgDialog_139661_Content_27 = {
    Text = "J'espère que tu trouveras ton amour toi aussi, Saya. Je te souhaite sincèrement une fin heureuse."
  },
  AvgDialog_139661_Content_28 = {
    Text = "Sur ces mots, la chanteuse s'en alla."
  },
  AvgDialog_139661_Content_29 = {
    Text = "Et ainsi, privée de mon passé et désormais sans la chanteuse,"
  },
  AvgDialog_139661_Content_3 = {
    Text = "Au milieu des vents qui balaient ce désert depuis des éternités, vous vous tenez là, à la dérive, contemplant l'ensemble."
  },
  AvgDialog_139661_Content_30 = {
    Text = "j'emportai sa bénédiction avec moi tandis que je marchais seule à travers ce monde."
  },
  AvgDialog_139661_Content_31 = {
    Text = "Pour trouver celle qui fut autrefois irremplaçable... pour reconstituer ce que j'avais perdu..."
  },
  AvgDialog_139661_Content_32 = {
    Text = "Je continuai d'avancer, persuadée que ce que je cherchais m'attendait juste devant."
  },
  AvgDialog_139661_Content_33 = {
    Text = "Jusqu'à ce qu'enfin... je te rencontre."
  },
  AvgDialog_139661_Content_4 = {
    Text = "Ici, c'est..."
  },
  AvgDialog_139661_Content_5 = {
    Text = "Aucune boue de Dissolution. Aucune masse grouillante de chair."
  },
  AvgDialog_139661_Content_6 = {
    Text = "Le paysage ici est solitaire, pur et magnifique."
  },
  AvgDialog_139661_Content_7 = {
    Text = "Voici mon Paysage Mental."
  },
  AvgDialog_139661_Content_8 = {
    Text = "Un fragment de mon existence — quelque chose d'irremplaçable, quelque chose qui ne devrait jamais être oublié..."
  },
  AvgDialog_139661_Content_9 = {
    Text = "Le sable se déplace et ondule, et dans le coin lointain du désert, deux silhouettes émergent."
  },
  AvgDialog_139662_Content_10 = {
    Text = "Je serai votre assistant, vous accompagnant jusqu'à la fin de ce chemin... <Yellow:Que la Clé d'Argent éclaire votre chemin.>"
  },
  AvgDialog_139662_Content_11 = {
    Text = "Tu vas bien, %player% ? Tu es un peu pâle. On devrait passer à l'infirmerie ?"
  },
  AvgDialog_139662_Content_12 = {Text = "Ramona..."},
  AvgDialog_139662_Content_13 = {
    Text = "Le nom reste coincé dans votre gorge. Vous n'arrivez pas à prononcer son nom — le nom que vous connaissez si bien."
  },
  AvgDialog_139662_Content_14 = {
    Text = "<Shake:<Red:Eｦ,ﾋbien5険ｸk,Q connectons-nousﾃ plutôt爨 avecｨ moiﾑ鑷9ｴﾅ.>>"
  },
  AvgDialog_139662_Content_15 = {
    Text = "<Shake:<Red:Légèｷrementz(enﾉ avanceｲ驫ｲ de8ﾃP peuｬ,ﾗ maisｸﾎ関靇ﾑ,w pasｦ graveJ ?>>"
  },
  AvgDialog_139662_Content_16 = {
    Text = "<Red:Non non non non. Rien ne va. Absolument rien.>"
  },
  AvgDialog_139662_Content_17 = {
    Text = "<Shake:<Red:ﾒDepuisｩﾇ龥 desｯ années7開ﾘ,L,ﾝ j'attendaisQ ceｱ jour齉月ﾏ avecr impatience今ｮ麤.>>"
  },
  AvgDialog_139662_Content_18 = {
    Text = "Non. Ça ne peut pas être Ramona. Ramona n'est pas une masse hideuse et grouillante de chair putréfiée. Elle ne pousse pas de gémissements graves et nauséabonds. Elle ne suinte pas de Lave corrodée par chaque pore de son corps."
  },
  AvgDialog_139662_Content_19 = {
    Text = "<Red:Il ne me fixerait pas de ses Yeux noirs et vides, en me dévisageant sans relâche —>"
  },
  AvgDialog_139662_Content_2 = {
    Text = "Blo0ﾝdiｲwoRｮ"
  },
  AvgDialog_139662_Content_20 = {Text = "Non —!"},
  AvgDialog_139662_Content_21 = {
    Text = "Était-ce... un rêve ?"
  },
  AvgDialog_139662_Content_22 = {
    Text = "Vous vous réveillez en sursaut, trempé de sueur froide."
  },
  AvgDialog_139662_Content_23 = {
    Text = "Quel rêve étrange. Même éveillé, il persiste encore dans mon champ de vision."
  },
  AvgDialog_139662_Content_24 = {
    Text = "Ce que vous voyez... c'est..."
  },
  AvgDialog_139662_Content_25 = {Text = "C'est..."},
  AvgDialog_139662_Content_26 = {
    Text = "<Shake:<Red:Des morceaux de chair, d'énormes morceaux de chair empilés et superposés.>>"
  },
  AvgDialog_139662_Content_27 = {
    Text = "Des entrailles écarlates et grouillantes recouvrant les murs, étranglant les piliers, rampant sur les fenêtres.\nEt entre les interstices de la chair—"
  },
  AvgDialog_139662_Content_28 = {
    Text = "Un liquide noir suinte."
  },
  AvgDialog_139662_Content_29 = {
    Text = "Dissolution."
  },
  AvgDialog_139662_Content_3 = {
    Text = "Pain. Une douleur brûlante. Un rouge cramoisi sombre inonde vos rétines."
  },
  AvgDialog_139662_Content_30 = {
    Text = "Vous avez déjà vu la Dissolution. Trop de fois. Mais jamais comme ça—deux maux distincts déchirant un seul corps en même temps."
  },
  AvgDialog_139662_Content_31 = {Text = "Ramona..."},
  AvgDialog_139662_Content_32 = {
    Text = "L'image revient en flash. Des orbites noires et vides. Une silhouette gonflée et déformée au-delà de toute reconnaissance. Ses doigts réduits à des appendices irréguliers contre ta paume—"
  },
  AvgDialog_139662_Content_33 = {
    Text = "Non—arrêtez. Arrêtez de penser—"
  },
  AvgDialog_139662_Content_34 = {
    Text = "Elle est encore là-bas—elle doit être quelque part—"
  },
  AvgDialog_139662_Content_35 = {
    Text = "Un léger tremblement ondule dans votre esprit. Presque imperceptible."
  },
  AvgDialog_139662_Content_36 = {
    Text = "Instinctivement, vous cherchez la source—ce n'est pas Ramona. Vous pourriez reconnaître Ramona les yeux fermés ; ses ondes spirituelles sont calmes et douces, comme la surface d'un lac immobile."
  },
  AvgDialog_139662_Content_37 = {
    Text = "Allez vers l'est..."
  },
  AvgDialog_139662_Content_38 = {Text = "Qui ?"},
  AvgDialog_139662_Content_39 = {
    Text = "Pas de réponse."
  },
  AvgDialog_139662_Content_4 = {
    Text = "Ma tête..."
  },
  AvgDialog_139662_Content_40 = {
    Text = "Sans autre indice, vous vous dirigez vers le son."
  },
  AvgDialog_139662_Content_41 = {
    Text = "Vous traversez une rivière qui empeste la rouille et la putréfaction. Vous enjambez un sol membraneux infesté de tendons rouge sombre."
  },
  AvgDialog_139662_Content_42 = {
    Text = "Votre respiration devient laborieuse ; vos nerfs palpitent sous l'empiètement de ces couleurs indicibles."
  },
  AvgDialog_139662_Content_43 = {
    Text = "Quelqu'un... n'importe qui... sortez-moi de ce rêve..."
  },
  AvgDialog_139662_Content_44 = {
    Text = "Ce doit être un rêve. La sensation est trop réelle—mais vous devez y croire. Vous le devez."
  },
  AvgDialog_139662_Content_45 = {
    Text = "Quelque chose de doux et blanc se pose sur le bout de votre nez."
  },
  AvgDialog_139662_Content_46 = {
    Text = "Un pissenlit...?"
  },
  AvgDialog_139662_Content_47 = {
    Text = "Vous posez le pied sur une frontière. Une frontière visible—une ligne nette et indéniable séparant deux mondes."
  },
  AvgDialog_139662_Content_48 = {
    Text = "Au-delà : de la chair nauséabonde et une boue noire déferlante."
  },
  AvgDialog_139662_Content_49 = {
    Text = "À l›intérieur : un petit champ de pissenlits. En son centre, une petite cabane en bois."
  },
  AvgDialog_139662_Content_5 = {
    Text = "Une lumière vacillante et tamisée, un bourdonnement résonnant dans vos tympans. Ce monde n'est pas digne de confiance. Tout ce qui est visible n'est qu'illusion."
  },
  AvgDialog_139662_Content_50 = {
    Text = "Quelque chose remue dans le carré de pissenlits."
  },
  AvgDialog_139662_Content_51 = {
    Text = "Vous suivez le mouvement. Une touffe blanche est écartée, révélant un coin de tissu pâle."
  },
  AvgDialog_139662_Content_52 = {
    Text = "Puis elle se lève."
  },
  AvgDialog_139662_Content_53 = {
    Text = "Une fille, frêle et légère comme un pissenlit."
  },
  AvgDialog_139662_Content_54 = {
    Text = "Elle penche la tête, observant votre expression."
  },
  AvgDialog_139662_Content_55 = {
    Text = "Vous n›avez pas peur de moi?"
  },
  AvgDialog_139662_Content_56 = {
    Text = "C›est presque ironique. Après tout ce que vous avez traversé, elle est le seul être humain normal que vous ayez vu. La seule existence qui ne soit pas effrayante."
  },
  AvgDialog_139662_Content_57 = {
    Text = "Alors... voulez-vous qu›on se serre la main?"
  },
  AvgDialog_139662_Content_58 = {
    Text = "Hein? Pourquoi?"
  },
  AvgDialog_139662_Content_59 = {
    Text = "Hmm... j›ai juste l›impression que je devrais."
  },
  AvgDialog_139662_Content_6 = {
    Text = "Réveille–toi. Réveille–toi maintenant..."
  },
  AvgDialog_139662_Content_60 = {
    Text = "Quant à pourquoi... je ne m›en souviens plus très bien."
  },
  AvgDialog_139662_Content_61 = {Text = "Et puis..."},
  AvgDialog_139662_Content_62 = {
    Text = "La fille penche la tête, un sourire espiègle se dessinant sur ses lèvres."
  },
  AvgDialog_139662_Content_63 = {
    Text = "Vous voulez me toucher aussi, n›est-ce pas?"
  },
  AvgDialog_139662_Content_64 = {
    Text = "C›est vrai. Bien sûr que oui."
  },
  AvgDialog_139662_Content_65 = {
    Text = "Après tout cela — l›obscurité, la puanteur, l›agression sensorielle répugnante — comment pourriez-vous ne pas vouloir toucher la première personne vivante que vous avez trouvée?"
  },
  AvgDialog_139662_Content_66 = {
    Text = "Vous tendez la main, touchant ses doigts fins et doux."
  },
  AvgDialog_139662_Content_67 = {
    Text = "Quelle sensation étrange..."
  },
  AvgDialog_139662_Content_68 = {
    Text = "Oui. Tu le ressens aussi. En plus de la chaleur humaine, il y a une légère sensation, comme un faible courant électrique qui vous relie."
  },
  AvgDialog_139662_Content_69 = {
    Text = "C›est la résonance des Cœurs d›argent."
  },
  AvgDialog_139662_Content_7 = {
    Text = "Bienvenue à l'Université Mythag, %player%."
  },
  AvgDialog_139662_Content_8 = {
    Text = "Ou plutôt... bienvenue, tu as officiellement pénétré le côté caché du monde."
  },
  AvgDialog_139662_Content_9 = {
    Text = "(Est–ce que je suis... de retour ?)"
  },
  AvgDialog_139663_Content_1 = {
    Text = "Ces choses sont..."
  },
  AvgDialog_139663_Content_10 = {
    Text = "Si elle est ordinaire... elle ne pourra probablement pas me parler."
  },
  AvgDialog_139663_Content_11 = {
    Text = "Puisque tu es un Corps éveillé, je pourrais être en mesure d›établir un lien avec toi. Par résonance onirique, tu pourrais voir à quoi ressemble Ramona."
  },
  AvgDialog_139663_Content_12 = {
    Text = "Peut-être qu›elle peut être la piste pour retrouver tes souvenirs."
  },
  AvgDialog_139663_Content_13 = {
    Text = "Tu reprends la main de Saya. Tu te concentres, traçant la silhouette de Ramona dans ton esprit — sa voix, son visage — espérant que le faible lien entre vous puisse transmettre tout cela."
  },
  AvgDialog_139663_Content_14 = {
    Text = "<Italic:Clac>. Le lien se brise."
  },
  AvgDialog_139663_Content_15 = {
    Text = "On dirait qu›un mur informe bloque notre lien..."
  },
  AvgDialog_139663_Content_16 = {
    Text = "On dirait qu'un mur sans forme bloque notre lien..."
  },
  AvgDialog_139663_Content_17 = {
    Text = "C'est peut-être lié à ce que je dois faire. J'ai le sentiment... que c'est quelque chose d'interdit. Quelque chose que je ne peux pas dire à tout le monde."
  },
  AvgDialog_139663_Content_18 = {
    Text = "On dirait qu›un orage approche. Reposons-nous à l›intérieur un moment."
  },
  AvgDialog_139663_Content_19 = {
    Text = "Par les fissures des planches de bois, une substance noire et visqueuse flotte parfois vers le haut, défiant la gravité."
  },
  AvgDialog_139663_Content_2 = {
    Text = "Je ne sais pas non plus. Mais j'ai le sentiment... que la réponse se trouve quelque part dans mes souvenirs."
  },
  AvgDialog_139663_Content_20 = {
    Text = "Saya se recroqueville dans un coin, le bas de son visage enfoui contre ses bras. Elle demande doucement —"
  },
  AvgDialog_139663_Content_21 = {
    Text = "C›est ce que tu appelles la « Dissolution », n›est-ce pas ?"
  },
  AvgDialog_139663_Content_22 = {
    Text = "Vous hochez la tête."
  },
  AvgDialog_139663_Content_23 = {
    Text = "C›est ça qui m›a pris mes souvenirs ?"
  },
  AvgDialog_139663_Content_24 = {
    Text = "Oui. Et pas seulement toi, d›innombrables personnes ont perdu des souvenirs importants à cause de la Dissolution."
  },
  AvgDialog_139663_Content_25 = {
    Text = "Certains ont oublié le visage de leurs proches. Ils ont passé des années à chercher — et parfois, dans cette quête, ils ont fini par blesser ceux-là mêmes qui leur manquent."
  },
  AvgDialog_139663_Content_26 = {
    Text = "Certains ont oublié les villes où ils sont nés. Ils ont erré seuls à travers l›océan, poursuivant un passé vers lequel ils ne pourront jamais retourner."
  },
  AvgDialog_139663_Content_27 = {
    Text = "...Perdre des souvenirs précieux doit être très douloureux."
  },
  AvgDialog_139663_Content_28 = {
    Text = "Saya regarde la pluie tomber en lignes fines et régulières — comme si l›eau pouvait laver la souillure noire."
  },
  AvgDialog_139663_Content_29 = {
    Text = "Je me demande... quelles sont les choses importantes cachées dans mes souvenirs ?"
  },
  AvgDialog_139663_Content_3 = {
    Text = "Je trouverai un moyen de vous sortir de ce Domaine. Nous récupérerons vos souvenirs."
  },
  AvgDialog_139663_Content_30 = {
    Text = "Je me demande... quelles sont les choses importantes cachées dans mes souvenirs ?"
  },
  AvgDialog_139663_Content_31 = {
    Text = "Vous restez silencieux."
  },
  AvgDialog_139663_Content_32 = {
    Text = "Dehors, la pluie continue de tomber, régulière et douce."
  },
  AvgDialog_139663_Content_4 = {Text = "Mais..."},
  AvgDialog_139663_Content_5 = {
    Text = "Vous voulez d'abord trouver Ramona, n'est-ce pas ?"
  },
  AvgDialog_139663_Content_6 = {
    Text = "Pour être honnête... je crois me souvenir avoir rencontré quelqu'un une fois, et ensuite..."
  },
  AvgDialog_139663_Content_7 = {
    Text = "À vrai dire... je crois me souvenir d'avoir rencontré quelqu'un une fois, et ensuite..."
  },
  AvgDialog_139663_Content_8 = {
    Text = "Bref. Cette Ramona—est-elle... différente, comme vous l'êtes ?"
  },
  AvgDialog_139663_Content_9 = {
    Text = "Si elle est ordinaire... elle ne pourra probablement pas me parler."
  },
  AvgDialog_141373_Content_1 = {
    Text = "Ce n'est pas votre première visite à Ebwynnos, mais jamais ces créatures sans visage n'avaient été aussi agitées qu'aujourd'hui."
  },
  AvgDialog_141373_Content_10 = {
    Text = "Attendez, vous êtes... pourquoi êtes-vous ici, déjà ?"
  },
  AvgDialog_141373_Content_11 = {
    Text = "Un bruit blanc strident engloutit votre conscience, et une marée ancienne et invisible vous força à lever péniblement la tête vers la seule chose que vous pouviez distinguer."
  },
  AvgDialog_141373_Content_12 = {
    Text = "C'est exact, tout cela n'a pas d'importance : qui vous êtes, ce que vous voulez faire, la raison de votre venue ici."
  },
  AvgDialog_141373_Content_13 = {
    Text = "Une voix grave dissipa le bruit des vagues, et l'aîné resserra la Chasse en cercle de haut en bas."
  },
  AvgDialog_141373_Content_14 = {
    Text = "Vous êtes en sécurité, bienvenue à nouveau."
  },
  AvgDialog_141373_Content_15 = {
    Text = "Oh... c'est vrai, Ebwynnos, je suis revenu à Ebwynnos."
  },
  AvgDialog_141373_Content_16 = {
    Text = "Vous murmurez en répétant ces mots, un sourire se dessine inconsciemment sur vos lèvres, et tout ce qui suit semble aller de soi."
  },
  AvgDialog_141373_Content_17 = {
    Text = "Bon, j'admets que c'est un peu irrégulier, mais ne vous inquiétez pas, je vous ramènerai à Mizag."
  },
  AvgDialog_141373_Content_18 = {
    Text = "L'abîsse vous a déjà enveloppé, et votre intellect Fragile, ballotté de soubresaut en soubresaut, est totalement incapable de comprendre tout ce que l'autre expose."
  },
  AvgDialog_141373_Content_19 = {Text = "Quoi ?"},
  AvgDialog_141373_Content_2 = {
    Text = "Hé, Hé ! Arrêtez, je ne suis pas un enne..."
  },
  AvgDialog_141373_Content_20 = {
    Text = "Un rire rauque et bref."
  },
  AvgDialog_141373_Content_21 = {
    Text = "Juste pas maintenant."
  },
  AvgDialog_141373_Content_22 = {
    Text = "Humidité, Chaos, promiscuité — ils vous remplissent à ras bord, puis vous font Enliséré dans un flot incessant, vous perdez tout contrôle."
  },
  AvgDialog_141373_Content_23 = {
    Text = "Il ne reste à votre oreille que des murmures mêlés de souffles haletants."
  },
  AvgDialog_141373_Content_24 = {
    Text = "Désormais, vous appartenez à cet endroit, à moi, à Ebwynnos."
  },
  AvgDialog_141373_Content_25 = {
    Text = "Vous ne comprenez pas, vous vous abandonnez simplement, dans la joie, au courant de cette mer antique."
  },
  AvgDialog_141373_Content_26 = {
    Text = "Il ne montre aucun signe de vouloir s'arrêter."
  },
  AvgDialog_141373_Content_3 = {
    Text = "*Son de sifflet de chasse"
  },
  AvgDialog_141373_Content_4 = {
    Text = "L'Attaque cessa, mais les ténèbres vous enveloppèrent soudainement. En Presque un instant, une torpeur figée vous précipita dans un abîme indicible."
  },
  AvgDialog_141373_Content_5 = {Text = "Hmm?"},
  AvgDialog_141373_Content_6 = {Text = "Ah..."},
  AvgDialog_141373_Content_7 = {
    Text = "Comme Si elle voulait vérifier quelque chose, ignorant le frisson que l'impulsion soudaine avait fait éclater en vous, le seigneur de ces lieux effleura d'un geste impérieux votre arcade sourcilière, le coin de vos yeux, jusqu'au côté de votre cou."
  },
  AvgDialog_141373_Content_8 = {
    Text = "Visiter Ebwynnos en ce moment n'est pas une bonne idée, %player%."
  },
  AvgDialog_141373_Content_9 = {
    Text = "<Small:Je voulais Juste...>"
  },
  AvgDialog_142850_Content_1 = {
    Text = "Première section"
  },
  AvgDialog_142850_Content_10 = {
    Text = "Varo... Vous, Vous devriez abandonner ! Nous sommes si nombreux, Vous ne pouvez pas quitter cette forêt vivant !"
  },
  AvgDialog_142850_Content_100 = {
    Text = "C'était une vitesse et une Force auxquelles il ne pouvait résister. Varo leva les yeux, emplis de confusion, et regarda Lotan sans comprendre."
  },
  AvgDialog_142850_Content_101 = {
    Text = "Vous... aviez promis..."
  },
  AvgDialog_142850_Content_102 = {
    Text = "J'avais promis de vous laisser rejoindre mon équipe. Mais je n'ai pas dit que vous seriez en vie."
  },
  AvgDialog_142850_Content_103 = {
    Text = "La faiblesse n'est pas ta faute. Mais ton cœur n'est pas pur, guerrier."
  },
  AvgDialog_142850_Content_104 = {
    Text = "Lotan prend les deux Sigils d'Os des mains de Varro et jette son cadavre — le visage encore figé dans la confusion — sur le tas des douze chevaliers morts, comme de vulgaires déchets."
  },
  AvgDialog_142850_Content_105 = {
    Text = "Elle jette un regard vers les broussailles, levant sa grande épée, prête à trancher le Sigil supplémentaire..."
  },
  AvgDialog_142850_Content_106 = {
    Text = "Attendez !! —"
  },
  AvgDialog_142850_Content_107 = {
    Text = "La lame de Lotan s'immobilise en plein élan. Avec une froide indifférence, elle te regarde ramper hors des buissons."
  },
  AvgDialog_142850_Content_108 = {
    Text = "Les adversaires trop faibles ne m'intéressent pas."
  },
  AvgDialog_142850_Content_109 = {
    Text = "Petit Écuyer de l'ordre des Chevaliers, si j'étais vous, je fuirais avant que l'on change d'avis, le plus vite possible."
  },
  AvgDialog_142850_Content_11 = {
    Text = "Remettez-nous votre empreinte osseuse, nous vous garantissons, nous vous garantissons que Vous pourrez partir en sécurité !"
  },
  AvgDialog_142850_Content_110 = {
    Text = "Le seigneur Élian a ordonné à l'ordre des Chevaliers de lui rapporter la Couronne. Si... s'il découvre que j'ai fui, toute ma famille mourra..."
  },
  AvgDialog_142850_Content_111 = {
    Text = "Vous rassemblâtes tout votre courage et fîtes un pas en direction de Lotan."
  },
  AvgDialog_142850_Content_112 = {
    Text = "Vous avez encore une empreinte osseuse... Je vous en supplie, laissez-moi aller aux Arènes de la Baleine Céleste, s'il vous plaît ? Il me suffit d'y arriver et ma mission sera accomplie... Vous êtes si puissante, je ne représenterai aucune menace pour vous..."
  },
  AvgDialog_142850_Content_113 = {Text = "Vous ?"},
  AvgDialog_142850_Content_114 = {
    Text = "Lotan haussa un sourcil et vous regarda avec Provocation."
  },
  AvgDialog_142850_Content_115 = {
    Text = "Votre Force est même inférieure à celle des incapables tués par Varo. À la seconde où vous mettrez les pieds dans ces Arènes, vous mourrez comme un insecte."
  },
  AvgDialog_142850_Content_116 = {
    Text = "Partez maintenant, et vous avez encore une chance de survivre."
  },
  AvgDialog_142850_Content_117 = {
    Text = "Vous regardâtes les cadavres jonchant le sol, puis cette silhouette qui vous inspirait une Peur viscérale, et avalâtes péniblement votre salive."
  },
  AvgDialog_142850_Content_118 = {
    Text = "Tu sais que la victoire n'a jamais été à ta portée. Chaque instinct te crie de fuir ce monstre, de t'éloigner le plus possible."
  },
  AvgDialog_142850_Content_119 = {
    Text = "Tu veux oublier ta mère sacrifiée vivante au Cétus Astral. Tu veux oublier tes frères et sœurs parqués comme du bétail dans les écuries. Tu veux simplement survivre."
  },
  AvgDialog_142850_Content_12 = {
    Text = "Il a raison, Varo ! Même si Vous êtes le mercenaire le plus puissant des six nations, encerclé par nos treize hommes, Vous n'avez aucun avantage."
  },
  AvgDialog_142850_Content_120 = {
    Text = "Mais rien n'y faisait, vous ne pouviez pas oublier. Tout comme votre participation à cette lutte vouée à vous réduire en chair à canon, vous n'avez jamais eu le droit de choisir."
  },
  AvgDialog_142850_Content_121 = {
    Text = "Je suis le guide de l'équipe, je connais le Chemin vers les Arènes. J'ai été Écuyer pendant de très, très nombreuses années, je sais comment servir un guerrier ! Je suis très utile, Vous aurez besoin de moi..."
  },
  AvgDialog_142850_Content_122 = {
    Text = "Vous inspirez profondément, ramassez le Sigil et utilisez un chiffon pour essuyer la crasse de l'armure de Lotan, comme vous le faisiez autrefois pour les chevaliers."
  },
  AvgDialog_142850_Content_123 = {
    Text = "Veuillez passer par ici, Ceci... Ceci... Euh ?"
  },
  AvgDialog_142850_Content_124 = {
    Text = "Vous vous tenez courbé devant Elle, sa respiration calme vous oppresse au point que vous n'osez pas lever la tête, les yeux rivés au sol à ses pieds. Vous sentez que Le Regard tranchant comme une Lame qu'Elle pose sur vous s'y attarde quelques secondes."
  },
  AvgDialog_142850_Content_125 = {
    Text = "Si vous rencontrez un danger, ne comptez pas sur moi pour vous aider."
  },
  AvgDialog_142850_Content_126 = {
    Text = "Sans suffixe. Vous pouvez m'appeler Lotan."
  },
  AvgDialog_142850_Content_127 = {
    Text = "Lotan rengaine son épée colossale et se dirige dans la direction que vous lui avez indiquée."
  },
  AvgDialog_142850_Content_128 = {
    Text = "Le Sang a entièrement imprégné le sol. Dans les profondeurs du ciel rouge sombre, une ombre immense et lente apparaît et disparaît."
  },
  AvgDialog_142850_Content_129 = {
    Text = "Vous frissonnez et vous empressez de suivre les pas de Lotan."
  },
  AvgDialog_142850_Content_13 = {
    Text = "Nous pouvons coopérer, n'est-ce pas ?"
  },
  AvgDialog_142850_Content_130 = {
    Text = "C'est... Dame Lotan !"
  },
  AvgDialog_142850_Content_14 = {
    Text = "Coopérer ?"
  },
  AvgDialog_142850_Content_15 = {
    Text = "La Baleine Céleste des Étoiles ne choisira qu'une seule personne pour devenir son Exécuteur, et cela ne peut se faire seul !"
  },
  AvgDialog_142850_Content_16 = {
    Text = "Il suffit de Lâcher l'empreinte osseuse, nous vous garantissons de quitter cet endroit en sécurité, et d'obtenir tout ce que Vous pouvez obtenir..."
  },
  AvgDialog_142850_Content_17 = {
    Text = "C'est ça ?"
  },
  AvgDialog_142850_Content_18 = {
    Text = "Je sais, Varo, Vous avez survécu aux hordes de bêtes de l'île déserte, Vous avez tué devant le Miroir la personne que Vous aimiez le plus — peut-être vos parents, votre enfant, ou autre chose."
  },
  AvgDialog_142850_Content_19 = {
    Text = "Vous avez survécu un demi-mois dans cette forêt primitive. Vous ne voulez certainement pas rentrer comme ça..."
  },
  AvgDialog_142850_Content_2 = {
    Text = "Des feuilles se détachèrent des branches, traversèrent le ciel rouge sombre et tombèrent dans une mare de sang au sol, y soulevant une faible ondulation."
  },
  AvgDialog_142850_Content_20 = {
    Text = "Mais pensez-y, pensez à ce qui Vous Attendre devant !"
  },
  AvgDialog_142850_Content_21 = {
    Text = "Vous devez percer notre encerclement, esquiver les dangers sur le Chemin, trouver les Arènes de la Baleine Céleste des Étoiles, et là y livrer un Match à Mort contre les personnes les plus dangereuses de ce monde."
  },
  AvgDialog_142850_Content_22 = {
    Text = "Même si cette empreinte osseuse peut Vous conduire aux Arènes, pouvez-vous être certain d'être le dernier survivant ?"
  },
  AvgDialog_142850_Content_23 = {
    Text = "Tant Que Vous abandonnez, une fois que le seigneur Élian sera au pouvoir, Vous deviendrez un mérite fondateur du royaume... Réfléchissez bien, Varo !"
  },
  AvgDialog_142850_Content_24 = {
    Text = "Votre proposition est séduisante. Mais malheureusement, Seulement les incapables ont besoin de se serrer les coudes. Vous ne comprenez pas du tout ce que signifie être fort."
  },
  AvgDialog_142850_Content_25 = {
    Text = "Inutile de perdre du temps en paroles, attaquez tous ensemble, racailles de l'Ordre des Chevaliers."
  },
  AvgDialog_142850_Content_26 = {Text = "Vous..."},
  AvgDialog_142850_Content_27 = {
    Text = "Varo ! Vous paierez pour votre manque de respect !"
  },
  AvgDialog_142850_Content_28 = {
    Text = "Ordre des Chevaliers ! Chargez !!!"
  },
  AvgDialog_142850_Content_29 = {
    Text = "Quelle bande de déchets..."
  },
  AvgDialog_142850_Content_3 = {
    Text = "L'ancienne forêt était imprégnée d'une odeur douceâtre et ferrugineuse impossible à dissiper. Les corps qui avaient nourri la terre de leur sang gisaient sur la mousse écarlate, les yeux grands ouverts dans un regard de résignation, depuis longtemps silencieux."
  },
  AvgDialog_142850_Content_30 = {
    Text = "Un torrent d'armures déferla comme une marée rugissante vers la silhouette isolée au centre. La charge d'une dizaine d'hommes écrasa la mousse et les ossements, faisant trembler la Terre sous leurs pas."
  },
  AvgDialog_142850_Content_31 = {
    Text = "Un violent fracas métallique retentit dans la forêt dense, faisant s'envoler une nuée d'oiseaux noirs, telle une écaille sombre arrachée de la cime des arbres."
  },
  AvgDialog_142850_Content_32 = {
    Text = "Les branches et les feuilles de votre cachette frémirent. Vous vous recroquevillez derrière les buissons, retenant votre souffle, observant ce massacre à travers les interstices des lianes."
  },
  AvgDialog_142850_Content_33 = {Text = "新增"},
  AvgDialog_142850_Content_34 = {
    Text = "Le cimeterre fracassait les lames, perçait la Chair Fragile sous les armures, tranchant membres et têtes dans les interstices des plaques. Chaque coup était précis, brutal, sans le moindre geste superflu."
  },
  AvgDialog_142850_Content_35 = {
    Text = "Force, vitesse, technique... Face à ce guerrier, les Chevaliers d'Élite tombaient un à un comme des agneaux conduits à l'abattoir."
  },
  AvgDialog_142850_Content_36 = {Text = "新增"},
  AvgDialog_142850_Content_37 = {
    Text = "Ce... cet individu..."
  },
  AvgDialog_142850_Content_38 = {
    Text = "La charge et les cris de guerre s'apaisèrent rapidement. Varo arracha un morceau de tissu propre sur le corps d'un Chevalier mort et essuya le Sang de son cimeterre."
  },
  AvgDialog_142850_Content_39 = {
    Text = "Il examina la lame immaculée et hocha la tête avec satisfaction. Puis il fouilla le cadavre du Chevalier en chef et en tira le sceau d'os donnant accès aux Arènes."
  },
  AvgDialog_142850_Content_4 = {
    Text = "Soufflez... calmez-vous... personne ne devrait m'avoir découvert..."
  },
  AvgDialog_142850_Content_40 = {
    Text = "Un, deux, trois... onze, douze."
  },
  AvgDialog_142850_Content_41 = {
    Text = "Douze, douze..."
  },
  AvgDialog_142850_Content_42 = {
    Text = "Il regarda autour de lui, sans trouver de treizième cadavre."
  },
  AvgDialog_142850_Content_43 = {
    Text = "Mauvais signe ! Il m'a découvert... Je dois partir au plus vite..."
  },
  AvgDialog_142850_Content_44 = {Text = "*Snap*—"},
  AvgDialog_142850_Content_45 = {
    Text = "Une souche morte surgit au mauvais moment sur votre chemin de retraite. Varo se retourna brusquement, les yeux rivés sur les buissons où Vous vous cachiez."
  },
  AvgDialog_142850_Content_46 = {Text = "!!!"},
  AvgDialog_142850_Content_47 = {
    Text = "Je me demandais pourquoi j'avais l'impression d'en avoir raté un... Il y en avait donc un autre caché ici."
  },
  AvgDialog_142850_Content_48 = {
    Text = "Sortez donc, mon ami, je vous ferai une mort rapide."
  },
  AvgDialog_142850_Content_49 = {
    Text = "Varo contemplait son propre reflet dans la lame de son cimeterre, s'avançant vers Vous d'un pas tranquille et mesuré."
  },
  AvgDialog_142850_Content_5 = {
    Text = "Un Rêve intense. Vous vous cachez dans les buissons, cherchant à apaiser votre souffle haletant, scrutant l'extérieur à travers les interstices du feuillage."
  },
  AvgDialog_142850_Content_50 = {
    Text = "Vous regardâtes autour de Vous, cherchant anxieusement une voie de fuite convenable."
  },
  AvgDialog_142850_Content_51 = {
    Text = "Impossible... Partout des fourrés... Dans ce corps d'enfant, je ne pourrai jamais le distancer à la course..."
  },
  AvgDialog_142850_Content_52 = {
    Text = "Que faire..."
  },
  AvgDialog_142850_Content_53 = {
    Text = "Vous fermâtes les yeux, vous efforçant de réprimer la Peur qui bouillonnait en Vous, l'esprit vide..."
  },
  AvgDialog_142850_Content_54 = {
    Text = "<Red:Chuintement. Chuintement. Chuintement.>"
  },
  AvgDialog_142850_Content_55 = {Text = "Hmm?"},
  AvgDialog_142850_Content_56 = {
    Text = "Des pas foulant les feuilles mortes et le lichen, venant d'une autre direction."
  },
  AvgDialog_142850_Content_57 = {
    Text = "Ils étaient calmes, réguliers, comme une promenade tranquille de l'après-midi."
  },
  AvgDialog_142850_Content_58 = {
    Text = "Un auxiliaire de l'ordre des Chevaliers... Ne pas choisir de Fuir, voilà du courage — et de la stupidité."
  },
  AvgDialog_142850_Content_59 = {
    Text = "Lorsque les pas s'arrêtèrent, le vent et le chant des oiseaux disparurent entièrement, et même le Sang qui suintait des cadavres derrière Vous sembla cesser de couler — toute la forêt sombra dans un silence étrange et mortel."
  },
  AvgDialog_142850_Content_6 = {
    Text = "Un cimeterre fut retiré d'une poitrine d'un geste net et précis, produisant un crissement qui faisait grincer les dents. Le guerrier épousseta la poussière sur son armure et leva les yeux vers les Environs."
  },
  AvgDialog_142850_Content_60 = {
    Text = "Une femme entre dans le champ de vision. Une armure légère noire ornementale couvre sa silhouette, et dans ses mains elle tient nonchalamment deux grandes épées massives, totalement disproportionnées par rapport à sa stature."
  },
  AvgDialog_142850_Content_61 = {
    Text = "Ses Yeux balayèrent les cadavres jonchant le sol, Le Regard s'attardant un instant sur leurs blessures."
  },
  AvgDialog_142850_Content_62 = {
    Text = "Chacun a été tué en moins de cinq coups, ciblant précisément les jointures de l'armure, avec un angle et une force parfaits... Ces hommes, c'est Vous qui les avez tués ?"
  },
  AvgDialog_142850_Content_63 = {
    Text = "Heh heh heh... En effet. Dommage, je n'avais pas encore eu mon content, et ils étaient déjà tombés."
  },
  AvgDialog_142850_Content_64 = {
    Text = "Douze hommes, et Vous n'avez aucune blessure. Pas mal."
  },
  AvgDialog_142850_Content_65 = {
    Text = "La femme en armure noire hocha la tête avec satisfaction, et ses pas réguliers continuèrent de se diriger vers lui."
  },
  AvgDialog_142850_Content_66 = {
    Text = "Varro Attendait. Il cherchait la Peur dans les Yeux de cette femme, mais n'y trouvait qu'un calme exaspérant."
  },
  AvgDialog_142850_Content_67 = {
    Text = "Peu importe qui Vous êtes, je peux Vous accorder trois minutes pour Fuir. Après ces trois minutes, savoir si Vous survivrez dépendra de..."
  },
  AvgDialog_142850_Content_68 = {
    Text = "Je dis, Vous êtes sourd ? Vous n'entendez pas ce que je dis ?"
  },
  AvgDialog_142850_Content_69 = {
    Text = "La femme en armure noire ne répondit pas, ses pas toujours aussi tranquilles que lors d'une promenade. La colère enflamma instantanément Varro — sa main se referma sur le manche de sa lame, et il dégaina son tranchant cimeterre."
  },
  AvgDialog_142850_Content_7 = {
    Text = "Le prochain, à qui le tour ?"
  },
  AvgDialog_142850_Content_70 = {
    Text = "J'allais t'épargner la vie, mais puisque tu tiens tant à mourir, je ne vais pas me gêner..."
  },
  AvgDialog_142850_Content_71 = {Text = "Clang—"},
  AvgDialog_142850_Content_72 = {
    Text = "Le son de métal entrechoqué le plus cristallin que Varro eût jamais entendu de sa vie retentit à son oreille, puis disparut en un éclair."
  },
  AvgDialog_142850_Content_73 = {
    Text = "La femme qui aurait dû se trouver devant Varro était apparue, on ne sait comment, derrière lui. Elle tenait d'une seule main une épée colossale, dont la lame reposait nonchalamment contre le côté de son cou."
  },
  AvgDialog_142850_Content_74 = {
    Text = "Varro baissa les yeux. Le cimeterre forgé par les artisans les plus habiles des six royaumes, celui qui avait tranché d'innombrables ennemis, était suspendu à quelques centimètres hors du fourreau — sectionné net à la garde."
  },
  AvgDialog_142850_Content_75 = {
    Text = "La magnifique lame dont il était si fier tournoya avant de se planter dans la terre imbibée de sang, telle une froide pierre tombale."
  },
  AvgDialog_142850_Content_76 = {
    Text = "C'est... vous..."
  },
  AvgDialog_142850_Content_77 = {
    Text = "Quelqu'un capable d'anéantir un ordre de Chevaliers entier... je pensais que cela m'intéresserait au moins un peu."
  },
  AvgDialog_142850_Content_78 = {
    Text = "La femme en armure noire laissait transparaître une déception non dissimulée dans sa voix."
  },
  AvgDialog_142850_Content_79 = {
    Text = "Le sceau osseux, vous l'avez ?"
  },
  AvgDialog_142850_Content_8 = {
    Text = "Il lécha le Sang sur son cimeterre, parcourut du regard la dizaine de personnes qui l'encerclaient, et posa sa question avec un intérêt non dissimulé."
  },
  AvgDialog_142850_Content_80 = {
    Text = "<Shake:Oui ! Oui, oui, oui !>"
  },
  AvgDialog_142850_Content_81 = {
    Text = "Varo avait côtoyé bien des gens et des situations ; il savait quoi faire en toutes circonstances. Ses jambes se dérobèrent sous lui et il tomba à genoux devant elle."
  },
  AvgDialog_142850_Content_82 = {
    Text = "Milady, milady, veuillez m'écouter... La Baleine Céleste ne choisit qu'une seule personne pour devenir son Exécuteur, et c'est une chose qu'on ne peut accomplir seul !"
  },
  AvgDialog_142850_Content_83 = {
    Text = "La Couronne ! Cette Couronne dont tout le monde rêve... Tu la veux aussi, n'est-ce pas ?!"
  },
  AvgDialog_142850_Content_84 = {
    Text = "Vous possédez une Force aussi redoutable — si nous formions une équipe, nous remporterions assurément la victoire finale !"
  },
  AvgDialog_142850_Content_85 = {
    Text = "Je serai votre serviteur le plus loyal, dévoué à vous pour toujours, et je vous aiderai à obtenir la Force de la Baleine Céleste ! ..."
  },
  AvgDialog_142850_Content_86 = {
    Text = "Milady... je vous en prie, considérez ma proposition..."
  },
  AvgDialog_142850_Content_87 = {
    Text = "Proposition intéressante. J'accepte."
  },
  AvgDialog_142850_Content_88 = {
    Text = "Toi... toi..."
  },
  AvgDialog_142850_Content_89 = {
    Text = "Varo avait préparé un long discours, mais il découvrit qu'il n'en avait nullement besoin."
  },
  AvgDialog_142850_Content_9 = {
    Text = "Lorsqu'il leva son cimeterre, Tout le monde recula d'un pas à l'unisson."
  },
  AvgDialog_142850_Content_90 = {
    Text = "Rassurez-vous. Je ne reviens jamais sur ma parole."
  },
  AvgDialog_142850_Content_91 = {
    Text = "<Shake:C'est... c'est merveilleux !>"
  },
  AvgDialog_142850_Content_92 = {
    Text = "Tel un homme arraché au bord du gouffre, Varro fouille fébrilement ses affaires, présentant finalement les Sigils d'Os à Lotan avec des mains tremblantes en coupe."
  },
  AvgDialog_142850_Content_93 = {
    Text = "Le voilà ! C'est celui-ci !"
  },
  AvgDialog_142850_Content_94 = {
    Text = "Ces chevaliers ont saisi deux Sigils. Avec ceux-ci, nous pouvons entrer dans l'arène ensemble !"
  },
  AvgDialog_142850_Content_95 = {
    Text = "Le moment venu, personne ne pourra nous vaincre..."
  },
  AvgDialog_142850_Content_96 = {Text = "Chhh—"},
  AvgDialog_142850_Content_97 = {Text = "ARGH !!"},
  AvgDialog_142850_Content_98 = {
    Text = "Le tranchant de la grande épée glissa aisément à travers l'armure, ouvrant une plaie béante Presque Perçante de part en part, s'étendant de la hanche droite à l'épaule gauche de Varo."
  },
  AvgDialog_142850_Content_99 = {
    Text = "Du sang chaud gicla sur les buissons devant Vous, se figeant en gouttelettes rouge sombre sur les feuilles."
  },
  AvgDialog_142851_Content_1 = {
    Text = "Quatrième section"
  },
  AvgDialog_142851_Content_10 = {
    Text = "Au centre des colonnes brisées, une fissure menant vers un autre espace Déchira la réalité, telle une pupille verticale s'ouvrant lentement."
  },
  AvgDialog_142851_Content_100 = {
    Text = "La paroi de chair sous ses pieds se contracta violemment en spasme, une âcre odeur de rouille envahit ses narines. L'espace lui-même commençait à s'emplir d'Excitation."
  },
  AvgDialog_142851_Content_101 = {
    Text = "Bien... Bien !"
  },
  AvgDialog_142851_Content_102 = {
    Text = "Douze mille ans, Lotan... J'ai attendu dans ce vide, Attendre quelqu'un qui me ferait sentir que l'existence n'est pas un supplice."
  },
  AvgDialog_142851_Content_103 = {
    Text = "Des rois, des saints, des guerriers, des créatures démoniaques... Ils se sont présentés devant moi, portant leurs désirs qu'ils croyaient grandioses, s'agenouillant, implorant."
  },
  AvgDialog_142851_Content_104 = {
    Text = "Puis, ils ont été peu à peu rongés par la Corrosion de la Force que je leur avais accordée, devenant un visage de plus flottant dans l'abîsse."
  },
  AvgDialog_142851_Content_105 = {
    Text = "Je croyais que c'était là tout ce qu'était l'éternité."
  },
  AvgDialog_142851_Content_106 = {
    Text = "Jusqu'à ce que Vous vous teniez ici, me regardant avec ces Yeux qui ne désirent rien, me disant que Vous voulez... hihihihi... que Vous voulez me tuer ?!!"
  },
  AvgDialog_142851_Content_107 = {
    Text = "Un rouge sombre, pur, épais et lourd jaillit de la fissure du cœur, engloutissant toutes les veines de lumière et les visages dans l'abîsse."
  },
  AvgDialog_142851_Content_108 = {
    Text = "Dans cette obscurité pourpre et corrompue, la silhouette du colossal Léviathan des étoiles apparut à l'horizon."
  },
  AvgDialog_142851_Content_109 = {
    Text = "Sa masse, plus grande que ce monde lui-même, déforma le vide de sa forme, le plan sous vos pieds commença à se courber comme du papier, et les ténèbres au loin commencèrent à s'effondrer vers l'intérieur."
  },
  AvgDialog_142851_Content_11 = {
    Text = "Il s'avère donc qu'il n'est pas nécessaire de tuer l'adversaire pour que la Porte s'ouvre... Vous avez de la chance."
  },
  AvgDialog_142851_Content_110 = {
    Text = "Cette planète avait grandi sur son corps, et les humains des six nations existaient grâce à lui. Il était la divinité qui dévorait la Force des planètes, le maître incontestable de ce monde. Il était cet espace lui-même."
  },
  AvgDialog_142851_Content_111 = {
    Text = "L'Illusion disparut complètement, et le Léviathan ouvrit brusquement ses yeux majestueux."
  },
  AvgDialog_142851_Content_112 = {
    Text = "Une Force capable de détruire ciel et terre jaillit du corps du Léviathan des étoiles. L'espace dimensionnel tout entier commença à s'effondrer, une Force invisible vous projeta dans les airs et vous fit tomber lourdement sur le bord du plan."
  },
  AvgDialog_142851_Content_113 = {
    Text = "Vos doigts s'agrippèrent à la fissure, luttant désespérément pour ne pas glisser dans l'abîsse."
  },
  AvgDialog_142851_Content_114 = {
    Text = "Tu me rends très, très heureuse, Lotan !"
  },
  AvgDialog_142851_Content_115 = {
    Text = "Après ta mort, je ferai en sorte que tous les serviteurs de ce monde te sculptent la plus grandiose des statues !"
  },
  AvgDialog_142851_Content_116 = {
    Text = "Au cœur de ces ténèbres qui engloutissaient tout, face à cette présence colossale et indicible, Lotan serra son épée gigantesque à deux mains et s'avança vers ces deux pupilles terrifiantes."
  },
  AvgDialog_142851_Content_117 = {
    Text = "Ses pas s'accélérèrent, de plus en plus vite, jusqu'à se transformer en une tempête qui n'avançait que vers l'avant. Sur son visage brillait un sourire de Ferveur que vous n'aviez jamais vu auparavant."
  },
  AvgDialog_142851_Content_118 = {
    Text = "Viens donc ! Léviathan !!!"
  },
  AvgDialog_142851_Content_119 = {
    Text = "Un rugissement aussi puissant que la marée retentit, brisant les derniers vestiges de votre conscience. Vos mains agrippées à la pierre n'eurent plus la Force de tenir, et dans ce vent hurlant, vous revîntes dans les Arènes à travers cette fissure."
  },
  AvgDialog_142851_Content_12 = {
    Text = "Lotan détourna Le Regard, Elle n'avait jamais eu le moindre intérêt pour Vous. Cette silhouette élancée, grande épée en main, se dirigea vers la fissure."
  },
  AvgDialog_142851_Content_120 = {
    Text = "Dans les dernières lueurs de votre regard, vous vîtes Lotan saisir ses deux épées colossales et s'élancer vers cette divinité plus majestueuse que les étoiles."
  },
  AvgDialog_142851_Content_121 = {
    Text = "La tempête se brisa en mille morceaux.\nLa tempête ne regarda jamais en arrière."
  },
  AvgDialog_142851_Content_13 = {
    Text = "Ce n'est qu'une fois sa silhouette entièrement disparue dans la fissure que Vous vous redressâtes enfin, reprenant votre souffle à grandes goulées."
  },
  AvgDialog_142851_Content_14 = {
    Text = "Ouf... j'ai failli mourir de peur..."
  },
  AvgDialog_142851_Content_15 = {
    Text = "Là-bas... c'est bien la demeure de la Baleine Céleste..."
  },
  AvgDialog_142851_Content_16 = {
    Text = "Vous vouliez fuir cet endroit, mais une attraction irrésistible émanait de la fissure, tel un fil invisible noué à vos os, vous tirant doucement et sans relâche."
  },
  AvgDialog_142851_Content_17 = {
    Text = "Vos pieds se dirigèrent malgré Vous vers la fissure. Celle-ci frémissait légèrement, comme un Œil bienveillant posant son regard sur Vous."
  },
  AvgDialog_142851_Content_18 = {
    Text = "Juste un coup d'œil, un seul. Pour voir à quoi ressemble vraiment ce grand maître qui Dévore les étoiles... Vous vous approchâtes furtivement de la fissure et vous y glissâtes..."
  },
  AvgDialog_142851_Content_19 = {Text = "新增"},
  AvgDialog_142851_Content_2 = {
    Text = "Lo... Dame Lotan ! ......"
  },
  AvgDialog_142851_Content_20 = {
    Text = "Aucune lumière, aucun son, Vous ne pouviez même pas entendre les battements de votre propre cœur. Vous n'étiez pas certain de posséder encore un corps, ou si Vous étiez déjà devenu quelque fragment de conscience flottant dans le Vide."
  },
  AvgDialog_142851_Content_21 = {
    Text = "Le sens du toucher revint dans votre corps ; sous vos pieds, Vous perçûtes un mouvement doux, chaud et rythmé. Cela se contractait légèrement sous vos plantes, comme une immense langue vous léchant."
  },
  AvgDialog_142851_Content_22 = {
    Text = "Qu'est-ce que c'est ?! ......"
  },
  AvgDialog_142851_Content_23 = {
    Text = "Des étoiles obscures dérivaient dans le ciel étoilé, et une pulsation aux couleurs sans cesse changeantes illuminait l'espace où Vous vous trouviez."
  },
  AvgDialog_142851_Content_24 = {
    Text = "Des amas de Chair s'étendaient à perte de vue sous vos pieds, ondulant comme une immense langue ou un estomac."
  },
  AvgDialog_142851_Content_25 = {
    Text = "Vous inspirâtes profondément et croisâtes le regard de cette pulsation lointaine, scintillante, semblable à un globe oculaire. En une fraction de seconde, un violent vertige vous submergea, et un flot de Festin de sang chaud jaillit de vos narines. Vous détournâtes aussitôt Le Regard."
  },
  AvgDialog_142851_Content_26 = {
    Text = "Dans les dernières lueurs de votre conscience, vous voyez cette masse pulsante et changeante se solidifier, une Illusion du Vide apparaît devant Lotan. Lorsqu'Elle prit la parole, un vaste chant de baleine résonna dans cet espace."
  },
  AvgDialog_142851_Content_27 = {
    Text = "Bienvenue, quatrième millième challenger à se présenter devant moi ! Bienvenue dans ma demeure."
  },
  AvgDialog_142851_Content_28 = {
    Text = "C'est bien vous."
  },
  AvgDialog_142851_Content_29 = {
    Text = "Un tel affrontement spectaculaire, quel plaisir y aurait-il à ne pas y assister en personne."
  },
  AvgDialog_142851_Content_3 = {
    Text = "Je... je n'ai jamais... jamais eu l'intention de vous disputer la Couronne..."
  },
  AvgDialog_142851_Content_30 = {
    Text = "J'ai observé chacun de vos combats, enfant au glaive."
  },
  AvgDialog_142851_Content_31 = {
    Text = "Gracchus, les Sœurs Vaughan, Sanchi, Elian, Alish... Dans cette grande arène, vous avez vaincu tous les êtres les plus puissants de cette planète."
  },
  AvgDialog_142851_Content_32 = {
    Text = "Votre épée ne fait aucun geste superflu. Votre âme ne porte aucun fardeau inutile. Votre victoire est pleinement méritée, Lotan."
  },
  AvgDialog_142851_Content_33 = {
    Text = "L'Illusion hocha la tête avec satisfaction."
  },
  AvgDialog_142851_Content_34 = {
    Text = "Les êtres qui viennent ici n'ont que trois raisons : la connaissance, le pouvoir, la vie."
  },
  AvgDialog_142851_Content_35 = {
    Text = "Le roi avide veut un trône immortel, la Mère désespérée veut la Résurrection de son enfant mort, le sorcier Fou veut Voyeur les savoirs interdits... Ils veulent tant, tant de choses."
  },
  AvgDialog_142851_Content_36 = {
    Text = "Alors, ils causent des Dommages, tuent, Sacrifient tout. Ils s'agenouillent devant moi et me supplient avec des formules que j'entends depuis des millénaires."
  },
  AvgDialog_142851_Content_37 = {
    Text = "Mais tout cela en valait la peine... En fin de compte, chacun a obtenu ce qu'il cherchait si ardemment."
  },
  AvgDialog_142851_Content_38 = {
    Text = "Alors, vaillant guerrier... qu'est-ce que vous, vous désirez ?"
  },
  AvgDialog_142851_Content_39 = {Text = "La Force."},
  AvgDialog_142851_Content_4 = {
    Text = "Je... je Juste..."
  },
  AvgDialog_142851_Content_40 = {
    Text = "La Force n'est qu'un outil, un échelon, et au-dessus de cet échelon, quelque chose vous Attend encore."
  },
  AvgDialog_142851_Content_41 = {
    Text = "Dites-moi, qu'est-ce que vous désirez vraiment ?"
  },
  AvgDialog_142851_Content_42 = {
    Text = "Je l'ai déjà dit... Ce que je veux, c'est Seulement la Force. Une Force toujours plus grande, sans jamais de limite."
  },
  AvgDialog_142851_Content_43 = {
    Text = "Tout ce qui n'est pas la Force ne m'intéresse pas."
  },
  AvgDialog_142851_Content_44 = {
    Text = "La Baleine Céleste observa Lotan avec amusement, et un rire semblable à un grondement retentit dans cet espace."
  },
  AvgDialog_142851_Content_45 = {
    Text = "Hé hé hé hé..."
  },
  AvgDialog_142851_Content_46 = {
    Text = "Ces paroles, je les ai entendues bien des fois. Chacun de ceux qui les ont prononcées a fini par se Perdre dans le désir qu'engendre la Force."
  },
  AvgDialog_142851_Content_47 = {
    Text = "Ils ont obtenu ma Force, mais ne pouvaient en supporter le poids. Elle grandissait dans leur moelle, Dévorant leur âme, le désir de tuer et de conquérir engloutissant leur conscience une à une..."
  },
  AvgDialog_142851_Content_48 = {
    Text = "Ce genre d'histoire, je l'ai vue quatre mille fois, et je ne m'en lasse jamais."
  },
  AvgDialog_142851_Content_49 = {
    Text = "Au son d'un chant de baleine, un immense cœur de baleine apparut dans cet espace. Une colonne de Sang jaillit du cœur, se rassemblant devant Lotan en une multitude de runes serrées."
  },
  AvgDialog_142851_Content_5 = {
    Text = "Vous aviez depuis longtemps oublié la blessure sur votre épaule, sans le courage de croiser ces Yeux calmes."
  },
  AvgDialog_142851_Content_50 = {
    Text = "Elles s'arrangèrent en une figure impossible à comprendre ; chaque fois que Lotan tentait d'en percevoir la forme entière, elle se transformait en une autre forme entièrement différente."
  },
  AvgDialog_142851_Content_51 = {
    Text = "Rien qu'en l'effleurant du coin de l'œil, vous sentez un flot de Sang brûlant se déchaîner dans votre corps, frappant chacun de vos organes, vous poussant à saisir votre épée pour la plonger dans le cœur de la personne devant vous... Vous détournez aussitôt le regard."
  },
  AvgDialog_142851_Content_52 = {
    Text = "Signez-le. Et vous recevrez ce que vous avez tant désiré — ma force."
  },
  AvgDialog_142851_Content_53 = {Text = "Le prix ?"},
  AvgDialog_142851_Content_54 = {
    Text = "Aucun prix, Seulement une promesse."
  },
  AvgDialog_142851_Content_55 = {
    Text = "Ma Force sera partagée avec vous, mon Destin sera lié au vôtre. Dès l'instant où Le Testament sera signé, vous serez le maître de cette planète, le représentant de ma volonté."
  },
  AvgDialog_142851_Content_56 = {
    Text = "Vous posséderez tout ce que les six nations ont à offrir, jusqu'à — jusqu'à ce que, trois ans plus tard, une nouvelle joute Commence, et qu'Un nouveau roi naisse."
  },
  AvgDialog_142851_Content_57 = {
    Text = "Vous m'accompagnerez, observant ces âmes fascinantes, vous observant vous-même, avancer pas à pas vers l'abîme. Tout comme les rois qui vous ont précédé."
  },
  AvgDialog_142851_Content_58 = {
    Text = "Mais je sais que, même en connaissant les conséquences, vous ne résisterez pas."
  },
  AvgDialog_142851_Content_59 = {
    Text = "Vous pensez être différent des quatre mille challengers qui vous ont précédé. Vous possédez une volonté capable de Surmonter toute chose, vous ne sombrez jamais dans l'abîme de la Force et du désir..."
  },
  AvgDialog_142851_Content_6 = {
    Text = "Lotan ne dit mot, se contentant de s'avancer vers Vous, lame en main, sans hâte ni lenteur. Votre front pressé contre le sol, votre corps tremblait devant cette silhouette qui approchait."
  },
  AvgDialog_142851_Content_60 = {
    Text = "Ce testament, comment le signe-t-on ?"
  },
  AvgDialog_142851_Content_61 = {
    Text = "Le sourire de la Baleine des Étoiles portait une lassitude ancestrale. Elle avait vu trop souvent la même histoire. Cette fois-ci, rien n'était différent."
  },
  AvgDialog_142851_Content_62 = {
    Text = "... Gourmandise. Détermination. Vous ne vous souciez guère des convenances, mais au moins, vous possédez une qualité qui me plaît."
  },
  AvgDialog_142851_Content_63 = {
    Text = "Tendez votre main et posez-la sur Le Testament."
  },
  AvgDialog_142851_Content_64 = {
    Text = "Sans hésiter, Lotan tendit la main et la posa sur cette figure formée de Sang."
  },
  AvgDialog_142851_Content_65 = {
    Text = "Des caractères liquides et vivants rampèrent hors du bassin de Sang. Ils grimpèrent le long du bras de Lotan, s'infiltrèrent et s'enfoncèrent sous sa peau."
  },
  AvgDialog_142851_Content_66 = {
    Text = "Là où ces caractères passaient, la Chair de Lotan se corrompit et se Décomposa rapidement, ne laissant que des os blanchâtres et du Sang écarlate."
  },
  AvgDialog_142851_Content_67 = {
    Text = "Le corps de Lotan tremblait de douleur, mais elle ne laissa échapper aucun son du début à la fin. Elle écarquilla ses yeux à moitié brisés et témoigna de tout cela avec attention."
  },
  AvgDialog_142851_Content_68 = {
    Text = "Les caractères se propagèrent le long du réseau de vaisseaux sanguins jusqu'au cœur, pour finalement atteindre ses deux yeux. En un instant, les pupilles de Lotan se transformèrent en Moskstraumen identique à celui de la Baleine Céleste."
  },
  AvgDialog_142851_Content_69 = {
    Text = "Puis le Moskstraumen disparut, et la couleur des pupilles de la Baleine Céleste demeura à jamais dans ses yeux, tandis qu'une armure d'os blancs recouvrait son corps nouveau-né."
  },
  AvgDialog_142851_Content_7 = {
    Text = "Un challenger a choisi la soumission, un challenger a choisi la fuite, quinze challengers ont choisi la mort... Il semblerait que notre dernier vainqueur soit désormais désigné."
  },
  AvgDialog_142851_Content_70 = {
    Text = "Tout le vide émit une Résonance grave et sourde, et les visages suspendus dans l'abîsse, ceux qui étaient morts dans les Arènes, ouvrirent tous la bouche en même temps, laissant échapper des hurlements silencieux."
  },
  AvgDialog_142851_Content_71 = {
    Text = "Ils accueillaient leur Nouveau roi."
  },
  AvgDialog_142851_Content_72 = {
    Text = "C'est ça... la Force de la Baleine Céleste..."
  },
  AvgDialog_142851_Content_73 = {
    Text = "Lotan serra le poing, ressentant la Force de l'antique divinité qui déferlait en elle, ressentant son Lien avec ce monde."
  },
  AvgDialog_142851_Content_74 = {
    Text = "Les mondes dévorés par la Baleine Céleste pulsaient dans sa perception, et toutes les vies créées et asservies par la Baleine Céleste étaient comme de minuscules flammes de bougie — une seule pensée suffirait à les éteindre toutes."
  },
  AvgDialog_142851_Content_75 = {
    Text = "Ce bassin de Sang se rassembla en une couronne L'Écarlate, resplendissant devant elle."
  },
  AvgDialog_142851_Content_76 = {
    Text = "Le Testament est conclu. Nos Destins ne font plus qu'un, de manière irréversible. Autant d'ères que j'ai traversées, autant de leur poids tu hériteras."
  },
  AvgDialog_142851_Content_77 = {
    Text = "Profites-en bien, Lotan. J'ai vu trop d'âmes semblables à la tienne. Pures, ardentes, indomptables."
  },
  AvgDialog_142851_Content_78 = {
    Text = "J'attendrai... j'attendrai le jour où tu sombres dans l'abîsse. Je plongerai dans un nouveau long sommeil... À présent, tu peux aller faire tout ce que tu désires."
  },
  AvgDialog_142851_Content_79 = {
    Text = "L'Illusion de la Baleine Céleste laissa un Adieu ennuyeux et rouvrit la fissure."
  },
  AvgDialog_142851_Content_8 = {
    Text = "La voix déferlait de toutes parts, empreinte d'une joie dérangeante. Les innombrables Illusions dans les gradins se levèrent simultanément, un sourire identique se dessinant sur leurs visages sans cesse changeants."
  },
  AvgDialog_142851_Content_80 = {
    Text = "Vous avez fini de parler ?"
  },
  AvgDialog_142851_Content_81 = {
    Text = "La demeure de la Baleine Céleste sombra dans un bref silence. Elle n'obtint pas les prières et la soumission qu'elle espérait — ce qu'elle obtint, ce fut une paire d'yeux de guerrière brûlant d'un désir irrépressible."
  },
  AvgDialog_142851_Content_82 = {
    Text = "Alors maintenant... c'est à Vous de passer à l'action."
  },
  AvgDialog_142851_Content_83 = {
    Text = "Vous n'auriez jamais imaginé voir de la confusion dans les yeux d'une divinité."
  },
  AvgDialog_142851_Content_84 = {
    Text = "Toi... que dis-tu ?"
  },
  AvgDialog_142851_Content_85 = {
    Text = "Vous avez dit que je pouvais faire tout ce que je désirais... Je n'ai qu'une seule chose à faire. Vous tuer, ou être tuée par Vous."
  },
  AvgDialog_142851_Content_86 = {
    Text = "J'ai l'habitude de laisser mon adversaire frapper en premier. Alors, c'est à Vous de passer à l'action, Léviathan."
  },
  AvgDialog_142851_Content_87 = {
    Text = "Vous venez tout juste de signer Le Testament..."
  },
  AvgDialog_142851_Content_88 = {
    Text = "J'ai promis de devenir le Gardien de cette planète, l'exécuteur de votre volonté."
  },
  AvgDialog_142851_Content_89 = {
    Text = "Vous êtes le maître esclavagiste de cette planète. Les combattre en votre nom, c'est aussi accomplir mon devoir."
  },
  AvgDialog_142851_Content_9 = {
    Text = "Un bruit sourd retentit. Les colonnes de pierre des Arènes s'effondrèrent derrière Vous, des éclats de roche fusèrent vers le ciel avant de disparaître dans les profondeurs de ce ciel rouge sombre semblable à un marécage."
  },
  AvgDialog_142851_Content_90 = {
    Text = "Vous êtes le dévoreur d'étoiles, synonyme de massacre et de guerre. Le combat est votre volonté."
  },
  AvgDialog_142851_Content_91 = {
    Text = "Quelle belle plaisanterie, Lotan. Partez maintenant, et Vous pourrez encore obtenir tout ce que Tout le monde désire posséder. Restez ici, et Vous n'obtiendrez rien."
  },
  AvgDialog_142851_Content_92 = {
    Text = "Mes paroles sont on ne peut plus claires."
  },
  AvgDialog_142851_Content_93 = {
    Text = "Le Testament a lié votre Destin au mien. Ma mort est votre mort."
  },
  AvgDialog_142851_Content_94 = {
    Text = "Je m'en moque."
  },
  AvgDialog_142851_Content_95 = {
    Text = "Votre Force ne représente même pas la moitié de la mienne. Vous venez tout juste de l'acquérir, vous ne comprenez absolument pas la Force que vous prétendez maîtriser... Vous n'avez pas la capacité de me défier, Lotan."
  },
  AvgDialog_142851_Content_96 = {
    Text = "J'aimerais essayer."
  },
  AvgDialog_142851_Content_97 = {
    Text = "Hihihihi... Hahahaha !!!"
  },
  AvgDialog_142851_Content_98 = {
    Text = "La Baleine Céleste éclata d'un rire frénétique. Cela faisait plus de dix mille ans qu'Elle n'avait pas ri avec une telle allégresse."
  },
  AvgDialog_142851_Content_99 = {
    Text = "Le rire jaillit des profondeurs les plus obscures du vide, faisant vibrer chaque veine de lumière, chaque écaille, chaque visage flottant dans l'abîsse."
  },
  AvgDialog_142852_Content_1 = {
    Text = "La troisième section"
  },
  AvgDialog_142852_Content_10 = {
    Text = "Vous vous retournez, et apercevez juste à temps deux ombres fondant rapidement sur vous —"
  },
  AvgDialog_142852_Content_100 = {
    Text = "Alish contempla avec stupeur la jeune femme devant lui. Une lueur rouge sang, sombre et terne, éclairait sa silhouette. Dans les derniers instants de sa vie, il vit la foi elle-même."
  },
  AvgDialog_142852_Content_101 = {
    Text = "Ha... hahahaha ! Quelle satisfaction !"
  },
  AvgDialog_142852_Content_102 = {
    Text = "J'ai imaginé ma mort bien des fois... Aucune ne m'a jamais satisfait autant que ce qui se passe aujourd'hui."
  },
  AvgDialog_142852_Content_103 = {
    Text = "Merci à vous, Dame Lotan."
  },
  AvgDialog_142852_Content_104 = {
    Text = "Le général Alish ouvrit grand les bras, se baignant dans la lumière du soleil couleur de Sang."
  },
  AvgDialog_142852_Content_106 = {
    Text = "Un éclair de lame trancha net, et la tête du vieux Alish roula aux côtés du cheval mort et des étendards brisés."
  },
  AvgDialog_142852_Content_107 = {
    Text = "Sur ce visage marqué par les épreuves se dessinait un sourire de contentement. Pour ce qui était de sa fin, le vieux Alish n'avait rien à redire."
  },
  AvgDialog_142852_Content_108 = {
    Text = "Après lui avoir fermé les yeux, Lotan se retourna et aperçut le noble vêtu des habits de Premier ministre, ainsi que l'enfant sous sa lame tremblante."
  },
  AvgDialog_142852_Content_109 = {
    Text = "Lo... Dame Lotan..."
  },
  AvgDialog_142852_Content_11 = {Text = "!!!"},
  AvgDialog_142852_Content_110 = {
    Text = "Vira ? Vira !"
  },
  AvgDialog_142852_Content_111 = {
    Text = "Guidée par la voix d'Elian, Lotan se retourna et jeta un regard vers la silhouette dissimulée dans les ténèbres derrière Elle."
  },
  AvgDialog_142852_Content_112 = {
    Text = "Après quelques secondes de lutte intérieure, l'empoisonneur de la résidence du Premier ministre rangea sa main tremblante et prit la fuite hors des Arènes. Face à la mort, la plupart des gens savent quel choix faire."
  },
  AvgDialog_142852_Content_113 = {
    Text = "Il semblerait que votre emprise sur votre entourage soit bien limitée."
  },
  AvgDialog_142852_Content_114 = {
    Text = "Dame Lotan, nous sommes alliés ! Vous vous en souvenez ?"
  },
  AvgDialog_142852_Content_115 = {
    Text = "Laissez-moi vivre, laissez-moi aller voir la Baleine Céleste... Je vous donnerai tout ce que vous désirez !"
  },
  AvgDialog_142852_Content_116 = {
    Text = "Et cet enfant... vous ne voulez pas que {Male=him,Female=her} meure, n'est-ce pas ? Je le sens... Vous avez protégé {Male=him,Female=her} tout au long de ce combat brutal..."
  },
  AvgDialog_142852_Content_117 = {
    Text = "La mort continuait d'avancer inexorablement vers Elian. Sa voix commença à trembler."
  },
  AvgDialog_142852_Content_118 = {
    Text = "Ah !!!——"
  },
  AvgDialog_142852_Content_119 = {
    Text = "La dague acérée s'enfonce profondément dans votre épaule. Votre cri d'agonie résonne à travers l'arène."
  },
  AvgDialog_142852_Content_12 = {Text = "新增"},
  AvgDialog_142852_Content_120 = {
    Text = "Lotan ! Si vous faites un pas de plus, cet homme mourra à cause de vous !"
  },
  AvgDialog_142852_Content_121 = {
    Text = "Vous ne tuez jamais les innocents... Vous ne voulez jamais que des innocents meurent à cause de vous ! C'est bien ça, c'est bien ça !! Je ne me suis pas trompé sur vous !!"
  },
  AvgDialog_142852_Content_122 = {
    Text = "La dague se tord en vous, accompagnée de vos cris incessants."
  },
  AvgDialog_142852_Content_123 = {
    Text = "Lotan semblait n'entendre rien, d'un calme absolu. Elle avança vers Elian, sa grande épée à la main, d'un pas aussi tranquille que lors d'une promenade d'après-midi."
  },
  AvgDialog_142852_Content_124 = {
    Text = "J'admire la pureté. La pureté de l'instinct meurtrier, la pureté de la Force, la pureté de la gloire, la pureté de l'intelligence et de la ruse."
  },
  AvgDialog_142852_Content_125 = {
    Text = "Mais vous, Elian..."
  },
  AvgDialog_142852_Content_126 = {
    Text = "Lotan secoua la tête avec mépris."
  },
  AvgDialog_142852_Content_127 = {
    Text = "Vous n'avez même pas compris ce qui m'importe."
  },
  AvgDialog_142852_Content_128 = {
    Text = "Vous n'êtes rien."
  },
  AvgDialog_142852_Content_13 = {
    Text = "Deux souffles de vent vous frôlent, et un liquide chaud vous éclabousse."
  },
  AvgDialog_142852_Content_130 = {
    Text = "Un coup de lame net et précis passa comme un éclair. Cet homme politique qui avait manœuvré à travers six nations accueillit sa fin, les yeux emplis de stupeur et d'impuissance."
  },
  AvgDialog_142852_Content_131 = {
    Text = "Il ne restait plus que deux êtres encore capables de respirer dans les Arènes. La grande épée de Lotan ruisselait de Sang, et Le Regard dépourvu de toute chaleur se posa sur Vous."
  },
  AvgDialog_142852_Content_14 = {
    Text = "Vous ne ressentez aucune douleur, et la mort ne semble pas encore Descendre. Vous écartez les mains qui couvraient vos Yeux et découvrez deux têtes fraîchement coupées, vous fixant de leurs regards remplis de regrets."
  },
  AvgDialog_142852_Content_15 = {Text = "ARGH !!"},
  AvgDialog_142852_Content_16 = {
    Text = "Vous reculez précipitamment de deux pas, manquant de trébucher sur la moitié du cadavre de Gracchus."
  },
  AvgDialog_142852_Content_17 = {
    Text = "Ha, les sœurs Vaughn, deux chasseuses de primes si renommées. Les rois des six royaumes ont tenté d'innombrables stratagèmes pour les recruter, sans jamais y parvenir."
  },
  AvgDialog_142852_Content_18 = {
    Text = "Aujourd'hui, elles ont connu leur unique et ultime échec de chasse."
  },
  AvgDialog_142852_Content_19 = {
    Text = "Sous les clameurs et les acclamations tonitruantes de L'Audience d'Illusions, Elian enjamba les cadavres avec satisfaction."
  },
  AvgDialog_142852_Content_2 = {
    Text = "Les murs circulaires des Arènes s'élèvent haut, les gradins bondés d'Illusions attentives."
  },
  AvgDialog_142852_Content_20 = {
    Text = "L'ordre n'est pas celui que j'avais prévu, mais peu importe. Nos ennemis ne sont plus que quelques-uns. À présent, je crois que vous avez besoin de Repos..."
  },
  AvgDialog_142852_Content_21 = {
    Text = "Un violent martèlement de sabots accompagné d'un vent hurlant interrompit les paroles d'Elian, surgissant brusquement derrière Elian et vous."
  },
  AvgDialog_142852_Content_22 = {
    Text = "Avant même que vous ayez pu réagir, Lotan vous saisit et vous projeta sur le côté."
  },
  AvgDialog_142852_Content_23 = {
    Text = "<RedBigShake:Meurs — !>"
  },
  AvgDialog_142852_Content_24 = {
    Text = "Le hennissement éclatant du destrier résonna à travers les Arènes. Dans la poussière, Un général vêtu d'une vieille armure retint son cheval au galop et planta l'Épine de l'étendard qu'il tenait dans la poitrine d'un Chevalier qui n'avait pu esquiver à temps."
  },
  AvgDialog_142852_Content_25 = {
    Text = "La fumée se dissipait lentement, révélant une silhouette qui n'avait rien d'imposant. Il tira doucement sur les rênes, faisant pivoter son destrier, et ses yeux — habitués aux montagnes de cadavres et aux mers de Sang — vous regardèrent avec calme."
  },
  AvgDialog_142852_Content_26 = {
    Text = "Vous croisâtes par inadvertance ce regard. Une puissante oppression vous fit fléchir les genoux, Presque incapable de rester debout."
  },
  AvgDialog_142852_Content_27 = {
    Text = "La fumée se dissipa. Vous aperçûtes cette vieille armure légendaire marquée de soixante-dix fissures, ainsi que ce destrier cuirassé qui avait jadis foulé les terres de six royaumes, soufflant fièrement de la vapeur par les naseaux."
  },
  AvgDialog_142852_Content_28 = {
    Text = "Quatre têtes dégoulinant de Sang pendaient aux flancs du destrier — une habitude que le vieillard avait cultivée depuis son plus jeune âge."
  },
  AvgDialog_142852_Content_29 = {
    Text = "Général Alish."
  },
  AvgDialog_142852_Content_3 = {
    Text = "Dans les profondeurs d'un ciel rouge sombre semblable à un marécage, une ombre immense en forme de baleine se déplaçait lentement."
  },
  AvgDialog_142852_Content_30 = {
    Text = "Vous remarquâtes que le ton de Lotan changea pour la première fois de manière perceptible. Sa voix était rauque et pleine d'Excitation, telle une lionne ayant flairé sa proie."
  },
  AvgDialog_142852_Content_31 = {
    Text = "Dites-moi, quel est le nom de mon adversaire."
  },
  AvgDialog_142852_Content_32 = {
    Text = "Vous pouvez m'appeler Lotan."
  },
  AvgDialog_142852_Content_33 = {
    Text = "Lotan... La plupart de ceux qui méritent qu'on les affronte en ce monde, je les connais, mais ce nom ne me dit rien."
  },
  AvgDialog_142852_Content_34 = {
    Text = "C'est peut-être parce que la plupart de ceux qui ont entendu ce nom sont déjà morts. Peu importe. Dans cinq minutes, vous vous souviendrez de mon nom."
  },
  AvgDialog_142852_Content_35 = {
    Text = "Ha... Ce monde ne cesse de changer d'une façon qui me laisse du mal à m'y Adapter, et peut-être que les jeunes d'aujourd'hui ont de quoi me faire hésiter."
  },
  AvgDialog_142852_Content_36 = {
    Text = "La course d'élimination a commencé il y a déjà une demi-heure. Pour avoir survécu jusqu'à présent, vous devez posséder une puissance à la hauteur de votre arrogance."
  },
  AvgDialog_142852_Content_37 = {
    Text = "Vous faites erreur, général Alish, nous ne sommes pas vos ennemis."
  },
  AvgDialog_142852_Content_38 = {
    Text = "Écartez-vous, Elian."
  },
  AvgDialog_142852_Content_39 = {
    Text = "(À voix basse) Madame Lotan, veuillez ne pas oublier le plan que nous avons établi. Nous devrions d'abord éliminer les autres ennemis. Alish est vieux et affaibli, quand il sera à bout de forces..."
  },
  AvgDialog_142852_Content_4 = {
    Text = "A-t-Il toujours aimé regarder le spectacle ainsi ?"
  },
  AvgDialog_142852_Content_40 = {
    Text = "J'ai dit, écartez-vous."
  },
  AvgDialog_142852_Content_41 = {
    Text = "Elian avait côtoyé bien des individus dangereux, et la voix de Lotan n'était en rien plus véhémente que la leur, mais ces paroles froides lui inspirèrent une Peur d'une intensité qu'il n'avait jamais connue."
  },
  AvgDialog_142852_Content_42 = {
    Text = "Il ne réfléchit pas longtemps et s'écarta du chemin, Le Visage impassible."
  },
  AvgDialog_142852_Content_43 = {
    Text = "Il ne reste plus beaucoup de monde dans ces Arènes. Parmi les adversaires qui méritent que je les défie, il n'y en a qu'un Seulement."
  },
  AvgDialog_142852_Content_44 = {
    Text = "Lotan posa la main sur la garde de son épée colossale et se dirigea vers Alish."
  },
  AvgDialog_142852_Content_45 = {
    Text = "Les Apparitions dans les gradins se taisent complètement, leurs visages sans traits se tournant à l'unisson pour suivre les pas de Lotan."
  },
  AvgDialog_142852_Content_46 = {
    Text = "Le bourdonnement grave dans l'air devint encore plus distinct, semblable à une attente ancienne et Gourmande."
  },
  AvgDialog_142852_Content_47 = {
    Text = "J'ai vu comment vous combattez, jeune homme. En soixante-dix ans de campagnes, je n'ai jamais rencontré un adversaire aussi fort que vous."
  },
  AvgDialog_142852_Content_48 = {
    Text = "Dans ces Arènes se trouvent les ennemis les plus puissants du monde, chacun cherche à frapper en premier, mais pas vous. Vous attendez toujours que votre adversaire dégaine son épée en premier..."
  },
  AvgDialog_142852_Content_49 = {
    Text = "Pouvez-vous me dire pourquoi ?"
  },
  AvgDialog_142852_Content_5 = {
    Text = "Lotan secoua la tête et retira son épée géante du cadavre à ses pieds."
  },
  AvgDialog_142852_Content_50 = {
    Text = "Parce que... un ennemi qui a dégainé son épée est un peu plus fort."
  },
  AvgDialog_142852_Content_51 = {
    Text = "Un peu... plus fort ?"
  },
  AvgDialog_142852_Content_52 = {
    Text = "Je ne m'intéresse qu'à ce qui est plus fort. Levez votre étendard, Alish."
  },
  AvgDialog_142852_Content_53 = {
    Text = "Les paroles de Lotan n'avaient pas la moindre trace de provocation. Elle posa sa main sur son épée colossale, les Yeux rivés sur Cela vieux général décrépit, ses pas aussi solennels que ceux d'un pèlerin."
  },
  AvgDialog_142852_Content_54 = {
    Text = "Heh... Ha ha ha ha !"
  },
  AvgDialog_142852_Content_55 = {
    Text = "Le vieux général rejeta la tête en arrière et éclata de rire. Son destrier resta immobile, homme et cheval debout seuls au centre des Arènes, l'étendard rouge Désordonné dans le vent."
  },
  AvgDialog_142852_Content_56 = {
    Text = "Tellement semblable. Vraiment tellement semblable... Si nous avions été un peu plus jeunes, nous aurions peut-être pu voir un autre nous-mêmes en ce monde."
  },
  AvgDialog_142852_Content_57 = {
    Text = "Quoi qu'il en soit... j'espère que nous ne nous décevrons pas mutuellement !"
  },
  AvgDialog_142852_Content_58 = {
    Text = "La voix d'Alish s'élève soudainement, ses jambes guidant habilement sa monture. Le destrier qui l'a porté à travers d'innombrables campagnes s'élance en avant, son hennissement perçant résonnant à travers la vaste arène —"
  },
  AvgDialog_142852_Content_59 = {
    Text = "L'étendard s'envola, tel un éclair rouge déchirant la poussière au centre des Arènes, fonçant droit sur Lotan."
  },
  AvgDialog_142852_Content_6 = {
    Text = "Les os transpercés raclèrent la lame dans un crissement insupportable, le corps massif fut déchiré en deux, et ces yeux remplis de regrets roulèrent avec la moitié du corps dans le caniveau ruisselant de Sang."
  },
  AvgDialog_142852_Content_60 = {
    Text = "Vous voyez les commissures des lèvres de Lotan se relever irrépressiblement. C'est la première fois que vous voyez le sourire de Lotan."
  },
  AvgDialog_142852_Content_61 = {
    Text = "Elle dégaina son épée colossale et se rua violemment à la rencontre de cet éclair rouge —"
  },
  AvgDialog_142852_Content_62 = {Text = "新增"},
  AvgDialog_142852_Content_63 = {
    Text = "BOUM !!! —"
  },
  AvgDialog_142852_Content_64 = {
    Text = "La grande épée blanche et l'étendard rouge s'entrechoquèrent, un son aigu et strident faisant vibrer les tympans de chacun."
  },
  AvgDialog_142852_Content_65 = {
    Text = "Les sabots de fer du destrier soulevèrent un nuage de poussière, les silhouettes de Lotan et d'Alish se croisant dans l'obscurité du champ de bataille."
  },
  AvgDialog_142852_Content_66 = {
    Text = "À chaque collision, l'ombre de l'immense baleine dans le ciel frémissait violemment, Comme Si elle savourait de rares Délices Macabres."
  },
  AvgDialog_142852_Content_67 = {Text = "新增"},
  AvgDialog_142852_Content_68 = {
    Text = "Général Alish... Dame Lotan..."
  },
  AvgDialog_142852_Content_69 = {
    Text = "Quel combat stupéfiant..."
  },
  AvgDialog_142852_Content_7 = {
    Text = "Il venait de dire son nom... comment s'appelait-il déjà ?"
  },
  AvgDialog_142852_Content_70 = {
    Text = "Vous vous efforcez de capturer les silhouettes des deux combattants avec vos Yeux, mais cela vous est extrêmement difficile."
  },
  AvgDialog_142852_Content_71 = {
    Text = "Vira, passez à l'action."
  },
  AvgDialog_142852_Content_72 = {
    Text = "Oui, Seigneur Elian."
  },
  AvgDialog_142852_Content_73 = {Text = "!!!"},
  AvgDialog_142852_Content_74 = {
    Text = "C'est... le sorcier empoisonneur de la résidence du Premier ministre ?! Dame Lotan ! Attention..."
  },
  AvgDialog_142852_Content_75 = {
    Text = "Vous n'avez pas fini votre phrase qu'une sensation glacée effleure votre peau."
  },
  AvgDialog_142852_Content_76 = {
    Text = "Chut... petit moineau. Vous m'avez toujours été fidèle, et maintenant, voudriez-vous me trahir pour quelqu'un que vous ne connaissez pas ?"
  },
  AvgDialog_142852_Content_77 = {
    Text = "Je... mais..."
  },
  AvgDialog_142852_Content_78 = {
    Text = "Je vous l'ai dit, une fois que j'aurai obtenu la Couronne de la Baleine Céleste et que je serai devenu le roi suprême des six nations, votre famille et vous-même recevrez les récompenses qui vous sont dues."
  },
  AvgDialog_142852_Content_79 = {
    Text = "Mais pour l'instant, taisez-vous."
  },
  AvgDialog_142852_Content_8 = {
    Text = "Gracchus... le Gladiateur le plus célèbre de tout le Nord, n'ayant jamais connu la défaite dans les Arènes des six royaumes..."
  },
  AvgDialog_142852_Content_80 = {
    Text = "La gorge se serre. Seulement celui qui a été esclave sait à quel point ces paroles d'Elian sont d'une tentation irrésistible."
  },
  AvgDialog_142852_Content_81 = {
    Text = "Vous regardez l'empoisonneur se dissimuler, se glissant dans la poussière tourbillonnante. Vous ne dites plus rien."
  },
  AvgDialog_142852_Content_82 = {Text = "Hmm?"},
  AvgDialog_142852_Content_83 = {
    Text = "Le général, lancé au galop, aperçut une silhouette se fondre dans la fumée et fronça les sourcils. Cela ralentit légèrement sa réaction."
  },
  AvgDialog_142852_Content_84 = {
    Text = "Lorsque l'immense épée féroce s'abattit de nouveau sur lui, il ne put que saisir son étendard militaire pour parer tant bien que mal."
  },
  AvgDialog_142852_Content_85 = {Text = "新增"},
  AvgDialog_142852_Content_86 = {
    Text = "Un choc d'une Force Musculaire colossale fit trébucher le destrier, qui s'effondra brusquement au sol. L'étendard écarlate se brisa en deux, et une immense épée se posa sur sa gorge."
  },
  AvgDialog_142852_Content_87 = {
    Text = "Vous avez ralenti, Alish."
  },
  AvgDialog_142852_Content_88 = {
    Text = "... Votre allié vous a trahi."
  },
  AvgDialog_142852_Content_89 = {
    Text = "Est-ce vraiment important ?"
  },
  AvgDialog_142852_Content_9 = {
    Text = "Vous avez vu bien des morts, mais le spectacle devant vous vous retourne quand même l'estomac."
  },
  AvgDialog_142852_Content_90 = {
    Text = "Que dis-tu… ?"
  },
  AvgDialog_142852_Content_91 = {
    Text = "Lotan poussa un léger soupir, empreint de regret."
  },
  AvgDialog_142852_Content_92 = {
    Text = "Vous étiez proche, Alish, mais pas assez. Au-delà de la Force et du combat, vous aspirez à autre chose — l'honneur."
  },
  AvgDialog_142852_Content_93 = {
    Text = "Vous accordez trop d'importance à ces choses futiles. Vous n'êtes pas assez pur."
  },
  AvgDialog_142852_Content_94 = {
    Text = "Lotan ouvrit les yeux, secoua la tête, ignorant totalement l'ombre tapie derrière Elle."
  },
  AvgDialog_142852_Content_95 = {
    Text = "Vous pensez que, avec l'aide d'Elian, vous attaquer à moi à plusieurs serait une victoire sans mérite."
  },
  AvgDialog_142852_Content_96 = {
    Text = "N'est-ce pas ainsi que cela devrait être ? Deux personnes aux capacités et aux pensées similaires, un duel équitable..."
  },
  AvgDialog_142852_Content_97 = {
    Text = "Voyez combien de mots vous utilisez. Honneur, équité, dignité... autant de chaînes que les faibles forgent pour eux-mêmes."
  },
  AvgDialog_142852_Content_98 = {
    Text = "Le guerrier est né pour se battre, et rien d'autre. Le combat... n'est que combat. Cela n'a rien à voir avec quoi que ce soit d'autre."
  },
  AvgDialog_142852_Content_99 = {
    Text = "L'ombre dans le ciel s'immobilisa, laissant échapper un grondement de satisfaction."
  },
  AvgDialog_142853_Content_1 = {
    Text = "La deuxième section"
  },
  AvgDialog_142853_Content_10 = {
    Text = "Je disais... Seigneur Lotan... pourriez-vous marcher un peu moins vite..."
  },
  AvgDialog_142853_Content_100 = {
    Text = "Madame Lotan... ne croyez pas ses paroles ! C'est Un Mensonge... À ses côtés, j'ai vu commettre d'innombrables crimes..."
  },
  AvgDialog_142853_Content_101 = {
    Text = "Je suis certain que Vous ne collaboreriez pas avec quelqu'un comme lui..."
  },
  AvgDialog_142853_Content_102 = {
    Text = "Vous faites de grands gestes de la main en direction de Lotan. Vous voulez l'avertir à quel point Elian est un homme rusé."
  },
  AvgDialog_142853_Content_103 = {
    Text = "D'esclave à Marchand, de Marchand à noble, de noble à Premier ministre, Elian a semé d'innombrables traces sur son difficile chemin, et chacune de ces traces est imprégnée de mensonges et de Festin de sang."
  },
  AvgDialog_142853_Content_104 = {
    Text = "Mais Lotan ne vous regardait pas. Elle détourna la tête vers la voûte céleste rouge sombre. L'immense ombre en forme de baleine continuait de se déplacer lentement, sa silhouette hérissée d'épines apparaissant et disparaissant dans l'obscurité."
  },
  AvgDialog_142853_Content_105 = {
    Text = "Écartez-vous."
  },
  AvgDialog_142853_Content_106 = {
    Text = "Vous vous écartez machinalement. Lotan passa à vos côtés, baissant les yeux vers le Premier ministre devant elle. La lumière rouge sombre dessinait dans son dos une silhouette tranchante."
  },
  AvgDialog_142853_Content_107 = {
    Text = "Vous êtes bien plus intéressant que votre ordre de Chevaliers, Elian. Peu m'importe ce que vous êtes, ni quand vous me trahirez. Vous pouvez m'être utile, cela suffit."
  },
  AvgDialog_142853_Content_108 = {
    Text = "J'accepte votre requête. Ne perturbez pas mes combats — c'est ma seule exigence."
  },
  AvgDialog_142853_Content_109 = {
    Text = "Madame Lotan... Vous..."
  },
  AvgDialog_142853_Content_11 = {
    Text = "Tout au long du Chemin, vous n'avez presque rien dit, vous contentant de tuer et d'avancer sans jamais vous reposer..."
  },
  AvgDialog_142853_Content_110 = {
    Text = "La soif de pouvoir qui flotte dans l'air vous submerge comme une marée. Un sourire amer se dessine sur votre visage. Tout le monde ici est pareil — vous n'auriez pas dû vous attendre à autre chose."
  },
  AvgDialog_142853_Content_111 = {
    Text = "Elian esquissa un large sourire, sans la moindre trace de joie inattendue sur son visage, Comme Si cette négociation était une victoire assurée d'avance."
  },
  AvgDialog_142853_Content_112 = {
    Text = "Il se retourna et se dirigea vers les tribunes bordant les Arènes."
  },
  AvgDialog_142853_Content_113 = {
    Text = "Les informations sur Tout le monde, les équipes qu'ils formeront, le moment où elles se briseront, ainsi que l'ordre des défis le plus susceptible de vous combler — j'ai déjà tout prévu pour vous."
  },
  AvgDialog_142853_Content_114 = {
    Text = "Savourez ce combat, Madame Lotan."
  },
  AvgDialog_142853_Content_12 = {
    Text = "Vous préférez vous taire de vous-même, ou voulez-vous que je vous enfonce mon épée dans la bouche ?"
  },
  AvgDialog_142853_Content_13 = {Text = "新增"},
  AvgDialog_142853_Content_14 = {
    Text = "Vous plaquéz fermement votre main sur votre bouche. Le Regard de Lotan ne s'attarde pas sur Vous. Elle observe les Environs, sa main effleurant un pilier de pierre brisé."
  },
  AvgDialog_142853_Content_15 = {
    Text = "La section du pilier est couverte de veines noires semblables à des vaisseaux sanguins, comme si les tissus d'un être vivant y proliféraient."
  },
  AvgDialog_142853_Content_16 = {Text = "C'est..."},
  AvgDialog_142853_Content_17 = {
    Text = "Vous collez votre oreille contre le pilier de pierre et percevez vaguement un battement extrêmement sourd, comme si une immense créature respirait lentement dans les profondeurs de la pierre."
  },
  AvgDialog_142853_Content_18 = {
    Text = "Une nausée soudaine et une impulsion meurtrière envahissent votre corps ; vous reculez précipitamment."
  },
  AvgDialog_142853_Content_19 = {
    Text = "Cette chose... est vivante ?!"
  },
  AvgDialog_142853_Content_2 = {
    Text = "C'est le Chemin que vous avez tracé ?"
  },
  AvgDialog_142853_Content_20 = {
    Text = "Selon la légende, la Baleine Céleste a créé ce monde de Son propre corps, et les peuples des six nations existent sur Sa chair."
  },
  AvgDialog_142853_Content_21 = {
    Text = "Il semblerait que nous en soyons désormais très proches."
  },
  AvgDialog_142853_Content_22 = {
    Text = "Lotan se dirige vers une table de pierre au centre de la place. Cette table, taillée dans du lapis-lazuli, détonne dans ce lieu désolé par la finesse de son travail et la richesse de ses matériaux."
  },
  AvgDialog_142853_Content_23 = {
    Text = "La surface de la table est recouverte d'une couche d'écailles fines et humides qui s'ouvrent et se ferment lentement dans la faible lumière, au même rythme que la respiration que vous venez d'entendre."
  },
  AvgDialog_142853_Content_24 = {
    Text = "Lotan y dépose les deux Sigils d'Os. À l'instant où les écailles touchent les Sigils, elles se referment comme d'innombrables doigts saisissant une proie et dévorent les deux Sigils en entier."
  },
  AvgDialog_142853_Content_25 = {
    Text = "Nos sceaux d'os !!!"
  },
  AvgDialog_142853_Content_26 = {
    Text = "Ah ! Deux nouveaux challengers !"
  },
  AvgDialog_142853_Content_27 = {
    Text = "Alors que vous vous précipitez vers la table de pierre, une silhouette humanoïde émerge lentement du centre de celle-ci."
  },
  AvgDialog_142853_Content_28 = {
    Text = "Son visage ne cesse de changer : tantôt un roi, tantôt un Chevalier, tantôt quelque chose que vous ne parvenez pas à identifier."
  },
  AvgDialog_142853_Content_29 = {
    Text = "Sa voix semble provenir des profondeurs d'une mare de Sang, chaque syllabe portant une étrange Résonance."
  },
  AvgDialog_142853_Content_3 = {
    Text = "Nous cherchons les Arènes, pas des ruines. Cet endroit semble abandonné depuis de nombreuses années."
  },
  AvgDialog_142853_Content_30 = {
    Text = "Je suis l'Illusion de la Baleine Céleste, Son serviteur le plus fidèle, ainsi que le gestionnaire et L'Audience de ces Arènes."
  },
  AvgDialog_142853_Content_31 = {
    Text = "Vous avez traversé maintes épreuves et êtes parvenus en ce lieu par votre propre Force et votre intelligence. Vous êtes la fierté des six nations, les plus puissants et les plus tenaces..."
  },
  AvgDialog_142853_Content_32 = {
    Text = "Épargnez-moi les bavardages."
  },
  AvgDialog_142853_Content_33 = {
    Text = "...Vous êtes bien impoli, challenger. Heureusement, la Baleine Céleste ne s'en soucie guère."
  },
  AvgDialog_142853_Content_34 = {
    Text = "Ce qui L'importe, c'est une seule chose : la Force. Une Force pure, sans la moindre once d'impureté."
  },
  AvgDialog_142853_Content_35 = {
    Text = "Bienvenue, bienvenue dans les Arènes de la Baleine Céleste, bienvenue sur la scène de la Force pure —"
  },
  AvgDialog_142853_Content_36 = {
    Text = "L'Illusion leva les deux bras, et un son grave et lointain, semblable au chant de la baleine, s'éleva de son corps, traversa vos os et résonna dans votre crâne."
  },
  AvgDialog_142853_Content_37 = {
    Text = "!!! C'est..."
  },
  AvgDialog_142853_Content_38 = {
    Text = "Le chant se propage en ondulations. Partout où il balaye, le ciel se teinte d'un rouge sombre. Les ruines en miettes, collées par une substance visqueuse non identifiable, se fondent en une grande arène antique."
  },
  AvgDialog_142853_Content_39 = {
    Text = "Tout autour, d'immenses sculptures de divinités adoptaient différentes postures, regardant de leurs yeux empreints de compassion ou de colère les êtres insignifiants à leurs pieds."
  },
  AvgDialog_142853_Content_4 = {
    Text = "Je connais la carte par cœur, c'est bien censé être ici... Mais pourquoi cet endroit ne correspond-il pas aux Enregistrements ?"
  },
  AvgDialog_142853_Content_40 = {
    Text = "Une douzaine de challengers se tiennent éparpillés sur la plateforme, vous jaugeant du regard."
  },
  AvgDialog_142853_Content_41 = {
    Text = "Un, deux, trois... quinze, seize."
  },
  AvgDialog_142853_Content_42 = {
    Text = "Il y a vingt Sigils d'Os en tout — deux autres personnes devraient encore arriver..."
  },
  AvgDialog_142853_Content_43 = {
    Text = "Il n'y en a plus, challengers. Ces deux Sigils ont déjà été détruits lors du tour précédent."
  },
  AvgDialog_142853_Content_44 = {
    Text = "Félicitations. En tant que dernier arrivé, vous avez l'honneur de retenir toute l'attention de chacun —"
  },
  AvgDialog_142853_Content_45 = {
    Text = "Dans le rire léger de l'Illusion, seize regards malveillants se tournèrent vers vous."
  },
  AvgDialog_142853_Content_46 = {
    Text = "Cette personne me semble si familière... Je crois l'avoir vue sur une affiche promotionnelle d'une arène quelconque ?"
  },
  AvgDialog_142853_Content_47 = {
    Text = "Cette tenue... on dirait qu'elle appartient à cette organisation d'assassins appelée le Petit Doigt ! Je ne m'attendais pas à croiser l'un des leurs ici..."
  },
  AvgDialog_142853_Content_48 = {
    Text = "Vous en savez plus qu'il n'y paraît."
  },
  AvgDialog_142853_Content_49 = {
    Text = "Je ne pouvais pas prendre la parole lors des réunions du Chevalier, mais j'y ai assisté en auditeur libre de nombreuses fois. Seigneur Elian nous a raconté beaucoup de choses..."
  },
  AvgDialog_142853_Content_5 = {
    Text = "Vous regardez les murs effondrés et érodés par des années de vent qui vous Entourent, et vous grattez la tête."
  },
  AvgDialog_142853_Content_50 = {
    Text = "Ah ! Regardez là-bas ! ! Cet homme en vieille armure !"
  },
  AvgDialog_142853_Content_51 = {
    Text = "C'est le général le plus valeureux des six nations ! Il a jadis tué seul le roi d'un pays ennemi sur le champ de bataille, j'ai grandi en entendant ses histoires !"
  },
  AvgDialog_142853_Content_52 = {
    Text = "Une légende vivante ! Je n'aurais jamais imaginé... jamais imaginé le rencontrer ici !"
  },
  AvgDialog_142853_Content_53 = {
    Text = "Lotan n'a pas prêté attention à vos cris d'Excitation que vous ne pouviez réprimer. Elle a balayé les participants du regard, puis s'est adossée à un pilier de pierre en fermant les yeux."
  },
  AvgDialog_142853_Content_54 = {
    Text = "Avant que l'ordre des Chevaliers ne participe à cette Conquête, j'ai Parié avec Madame sur qui serait la personne à entrer dans le palais de la Baleine Céleste."
  },
  AvgDialog_142853_Content_55 = {
    Text = "Vous avez très bien fait, petit moineau. Une fois ce jeu ennuyeux terminé, Madame devra me rembourser une belle somme."
  },
  AvgDialog_142853_Content_56 = {Text = "!!!"},
  AvgDialog_142853_Content_57 = {
    Text = "É... Seigneur Élian..."
  },
  AvgDialog_142853_Content_58 = {
    Text = "Une Voix douce, un pas assuré, une large robe faite de précieux tissus, le parfum de genièvre qui l'enveloppe... Même réduit en Cendres, vous pourriez le reconnaître."
  },
  AvgDialog_142853_Content_59 = {
    Text = "Vous... comment avez-vous pu venir en personne... je veux dire..."
  },
  AvgDialog_142853_Content_6 = {
    Text = "Le roi écrivait dans son journal que les murs ici étaient faits d'Or, que des messagers divins à six ailes planaient dans le ciel, que les rivières coulaient de miel et de vin..."
  },
  AvgDialog_142853_Content_60 = {
    Text = "Vous avez demandé à l'ordre des Chevaliers de Conquérir la Couronne en votre nom, je pensais..."
  },
  AvgDialog_142853_Content_61 = {
    Text = "Vous pensiez que je placerais tout mon espoir dans un ordre de Chevaliers incapable de battre de simples mercenaires ? Je vous l'ai enseigné, petit moineau, ne mettez jamais tous vos œufs dans le même panier."
  },
  AvgDialog_142853_Content_62 = {
    Text = "Ayez un peu confiance en le bon Élian, la grande Baleine Céleste accorde toujours sa Bénédiction aux gens de bien."
  },
  AvgDialog_142853_Content_63 = {
    Text = "Le noble sourit avec élégance. Le Regard ne quitta jamais Lotan."
  },
  AvgDialog_142853_Content_64 = {
    Text = "Ceci est... votre amie ?"
  },
  AvgDialog_142853_Content_65 = {
    Text = "Euh, pas vraiment..."
  },
  AvgDialog_142853_Content_66 = {
    Text = "Lotan. Une guerrière."
  },
  AvgDialog_142853_Content_67 = {
    Text = "Ravi de vous rencontrer, Dame Lotan. J'espère que mes serviteurs ne vous ont pas causé de désagréments."
  },
  AvgDialog_142853_Content_68 = {
    Text = "Le Premier ministre ?"
  },
  AvgDialog_142853_Content_69 = {
    Text = "Le Regard de Lotan parcourut les ornements de ses vêtements et de l'épée à sa ceinture. Même pour quelqu'un qui ne s'intéresse guère à la politique des six nations, la Marque du Premier ministre reste très facile à distinguer."
  },
  AvgDialog_142853_Content_7 = {
    Text = "Mais qu'est-ce que c'est que cette place qui ressemble à des ruines... Et personne pour vérifier les sceaux d'os non plus."
  },
  AvgDialog_142853_Content_70 = {
    Text = "Un simple titre honorifique, dont le seul intérêt est de m'éviter de me présenter."
  },
  AvgDialog_142853_Content_71 = {
    Text = "Élian sourit et s'assit sur le pilier de pierre devant Lotan."
  },
  AvgDialog_142853_Content_72 = {
    Text = "Vous avez amené mon serviteur jusqu'ici, mais mon ordre de Chevaliers a disparu. Je crois que je comprends à peu près ce qui s'est passé en Chemin."
  },
  AvgDialog_142853_Content_73 = {
    Text = "Votre ordre de Chevaliers est mort de façon bien pitoyable. Douze hommes, sans même avoir effleuré l'armure d'un guerrier de bas étage."
  },
  AvgDialog_142853_Content_74 = {
    Text = "Et vous, vous avez très facilement remporté ce combat."
  },
  AvgDialog_142853_Content_75 = {
    Text = "Leur mort semble ne vous intéresser absolument pas."
  },
  AvgDialog_142853_Content_76 = {
    Text = "Ah, non non non, vous vous méprenez sur mon compte, Madame Lotan..."
  },
  AvgDialog_142853_Content_77 = {
    Text = "Elian éclata d'un grand rire et secoua la tête."
  },
  AvgDialog_142853_Content_78 = {
    Text = "Mes Chevaliers sont de bons enfants, loyaux, assidus... mais voici les Arènes de la Baleine Céleste. Les faibles ont connu la fin qui leur était réservée, et cela ne me préoccupe guère."
  },
  AvgDialog_142853_Content_79 = {
    Text = "Ce qui me préoccupe, c'est vous, Madame Lotan. Une guerrière redoutable, éprise de lames, de carnage et de Sang, prête à tout sacrifier pour cette Couronne forgée dans le Festin de sang..."
  },
  AvgDialog_142853_Content_8 = {
    Text = "Hé ! Attendez-moi..."
  },
  AvgDialog_142853_Content_80 = {
    Text = "Le débit d'Elian s'accélérait de plus en plus. L'odeur de carnage et la soif de pouvoir qui flottaient dans l'air l'imprégnaient, faisant battre son cœur endurci par les épreuves d'une manière qu'il ne pouvait réprimer."
  },
  AvgDialog_142853_Content_81 = {
    Text = "Semblant prendre conscience de son manque de retenue, il inspira profondément et recula d'un demi-pas."
  },
  AvgDialog_142853_Content_82 = {
    Text = "Je pense que nous pourrions collaborer."
  },
  AvgDialog_142853_Content_83 = {
    Text = "Vous croyez que je suis quelqu'un qui aime collaborer ?"
  },
  AvgDialog_142853_Content_84 = {
    Text = "Les faibles ont toujours l'habitude de se regrouper, vous n'êtes bien sûr pas de ceux-là. Mais tout le monde a besoin de collaborer à un moment ou un autre, et vous n'êtes pas une exception."
  },
  AvgDialog_142853_Content_85 = {
    Text = "Lotan n'avait pas encore répondu que d'innombrables Illusions identiques apparurent sur les gradins des Arènes, envahissant les travées bondées, et une voix semblable au chant de la baleine résonna à nouveau dans ces Arènes désertes."
  },
  AvgDialog_142853_Content_86 = {
    Text = "Bien, challengers, nous n'en pouvons plus d'attendre. L'épreuve finale est sur le point de commencer dans ces magnifiques Arènes !"
  },
  AvgDialog_142853_Content_87 = {
    Text = "Lorsque le dernier vainqueur se démarquera, une Porte menant au palais de la Baleine Céleste s'ouvrira pour lui !"
  },
  AvgDialog_142853_Content_88 = {
    Text = "Derrière cette Porte, une gloire infinie, des richesses, du pouvoir — tout !"
  },
  AvgDialog_142853_Content_89 = {
    Text = "Désigner un vainqueur... quelles sont les règles ?"
  },
  AvgDialog_142853_Content_9 = {
    Text = "Pendant que vous parliez seul face à l'antique socle de pierre, Lotan s'était dirigée vers le centre de la vaste place."
  },
  AvgDialog_142853_Content_90 = {
    Text = "Les règles ? Hihihi... Hahahahaha ! Les règles ?! ..."
  },
  AvgDialog_142853_Content_91 = {
    Text = "Le rire exagéré des Illusions fit vibrer douloureusement les tympans de tous ceux présents dans les Arènes. Dans ce rire de Folie, elles cessèrent de parler et regardèrent avec impatience le centre vide des Arènes."
  },
  AvgDialog_142853_Content_92 = {
    Text = "Mais... il n'a pas encore dit quelles étaient les règles..."
  },
  AvgDialog_142853_Content_93 = {
    Text = "Il l'a déjà dit. «Le dernier vainqueur», Seulement Un. C'est la seule règle, petit moineau."
  },
  AvgDialog_142853_Content_94 = {
    Text = "Massacres, défis, alliances, trahisons... Dix-huit participants, et seul celui qui reste debout peut franchir cette Porte."
  },
  AvgDialog_142853_Content_95 = {
    Text = "Le sourire familier réapparut sur le visage d'Elian."
  },
  AvgDialog_142853_Content_96 = {
    Text = "Vous devrez affronter certains des individus les plus puissants de ce monde."
  },
  AvgDialog_142853_Content_97 = {
    Text = "Ne vous méprenez pas, je ne Doute pas un instant de votre Force, Madame Lotan."
  },
  AvgDialog_142853_Content_98 = {
    Text = "Mais je suppose que vous ne souhaiteriez pas voir votre plaisir gâché par des individus ennuyeux, au beau milieu de vos délicieux massacres ?"
  },
  AvgDialog_142853_Content_99 = {
    Text = "Lotan leva la tête sérieusement pour la première fois. Elle vit un visage souriant avec douceur, et sur ce Le Visage, ces Yeux qui semblaient tout percevoir."
  },
  AvgDialog_142854_Content_1 = {
    Text = "La cinquième section"
  },
  AvgDialog_142854_Content_10 = {
    Text = "Lo... Lotan ?"
  },
  AvgDialog_142854_Content_11 = {
    Text = "Vous ne pouvez pas distinguer si la personne couverte de Sang devant vous est Lotan ou non."
  },
  AvgDialog_142854_Content_12 = {
    Text = "Un Sang sale et de pourriture recouvre son corps, sans que l'on sache s'il provient d'elle-même ou d'autre chose."
  },
  AvgDialog_142854_Content_13 = {
    Text = "Sous ce Sang souillé et cette armure brisée, la moitié de son corps n'est plus que des ossements blanchis."
  },
  AvgDialog_142854_Content_14 = {
    Text = "La guerrière, dont il ne reste que la moitié du corps, sort de cette fissure imprégnée d'une odeur de Sang. Ses pas sont lents, épuisés, et son épée brisée traîne sur le sol, creusant un sillon peu profond dans la mare de Sang."
  },
  AvgDialog_142854_Content_15 = {
    Text = "Dans son autre main, la Couronne formée de Festin de sang laisse tomber des gouttes de Sang souillé."
  },
  AvgDialog_142854_Content_16 = {
    Text = "Ses Yeux brillent d'un éclat jamais vu auparavant."
  },
  AvgDialog_142854_Content_17 = {
    Text = "Lo... Lotan... la Baleine Céleste... Elle..."
  },
  AvgDialog_142854_Content_18 = {
    Text = "Elle a perdu."
  },
  AvgDialog_142854_Content_19 = {
    Text = "La voix de Lotan ne tremble pas le moins du monde, Comme Si elle énonçait simplement un fait inévitable."
  },
  AvgDialog_142854_Content_2 = {
    Text = "Tousse... Tousse, tousse..."
  },
  AvgDialog_142854_Content_20 = {
    Text = "Vous avez signé Le Testament avec Elle... Si Elle subit des Dommages, vous aussi..."
  },
  AvgDialog_142854_Content_21 = {
    Text = "Vous n'avez pas besoin de poser d'autres questions. Les blessures sur le corps de Lotan disent tout."
  },
  AvgDialog_142854_Content_22 = {
    Text = "Dame Lotan, vous avez vaincu tous les challengers... même le Cétus Astral !"
  },
  AvgDialog_142854_Content_23 = {
    Text = "Désormais, vous êtes le souverain incontesté de cette planète... C'est le moment le plus glorieux de votre vie ! Maintenant..."
  },
  AvgDialog_142854_Content_24 = {
    Text = "C'est aussi le moment où Elle est la plus Fragile."
  },
  AvgDialog_142854_Content_25 = {
    Text = "L'odeur de Sang qui s'échappe de la fissure vous enveloppe, et le Chuchotement semblable au chant de la baleine devient de plus en plus distinct à vos oreilles."
  },
  AvgDialog_142854_Content_26 = {
    Text = "Regardez, la Couronne formée de Festin de sang..."
  },
  AvgDialog_142854_Content_27 = {
    Text = "Les trônes de six royaumes, la soumission de millions d'âmes, des richesses et une gloire intarissables... Cette Couronne peut tout offrir à son maître."
  },
  AvgDialog_142854_Content_28 = {
    Text = "Chaque personne dans les Arènes la convoite. Ces Chevaliers qui vous Réprimandent chaque jour, Gracchus, les sœurs Vorn, le général Alish, le tout-puissant seigneur Elian..."
  },
  AvgDialog_142854_Content_29 = {
    Text = "Et vous aussi, petit moineau. Vous la convoitez aussi..."
  },
  AvgDialog_142854_Content_3 = {Text = "C'est..."},
  AvgDialog_142854_Content_30 = {
    Text = "Vous regardez la Couronne L'Écarlate dans les mains de Lotan. À chaque goutte de Sang qui tombe, le Chuchotement de la Baleine des Étoiles devient plus distinct."
  },
  AvgDialog_142854_Content_31 = {
    Text = "Vous ne serez plus jamais une esclave, petit moineau."
  },
  AvgDialog_142854_Content_32 = {
    Text = "Vous ferez construire un grand mausolée pour votre mère. Vous sortirez vos frères et sœurs des écuries pour vivre avec vous dans un palais splendide."
  },
  AvgDialog_142854_Content_33 = {
    Text = "Ceux qui vous ont jadis humiliés s'agenouilleront devant vous et baiseront le dessus de vos pieds."
  },
  AvgDialog_142854_Content_34 = {
    Text = "Le pouvoir. Le pouvoir suprême."
  },
  AvgDialog_142854_Content_35 = {
    Text = "Ces noms qui coulent dans les légendes, tous sont morts pour lui... et maintenant, il se trouve devant vous, à portée de main."
  },
  AvgDialog_142854_Content_36 = {
    Text = "Allez, petit moineau. Dans toute votre vie, c'est votre unique chance !"
  },
  AvgDialog_142854_Content_37 = {
    Text = "Les murmures se transformèrent en grondement, une impulsion violente Surge dans votre esprit. Votre gorge sèche se contracte, et votre main tremblante soulève la dague ornée de joyaux laissée par Elian. Sur la lame de la dague, il y a encore votre propre Sang."
  },
  AvgDialog_142854_Content_38 = {
    Text = "Vous avez déjà atteint cet endroit, pourquoi ne pas faire un pas de plus ? Elle vous appartient... la Couronne vous appartient de droit..."
  },
  AvgDialog_142854_Content_39 = {
    Text = "Vous avez déjà atteint cet endroit, pourquoi ne pas faire un pas de plus ? Elle vous appartient... la Couronne vous appartient de droit..."
  },
  AvgDialog_142854_Content_4 = {
    Text = "Vous vous relevâtes de la poussière qui couvrait le sol, secouâtes les graviers de vos vêtements, et pris quelques secondes pour vous rappeler où vous vous trouviez."
  },
  AvgDialog_142854_Content_40 = {
    Text = "<Red:La tuer ?... La tuer... La tuer... La tuer !!!>"
  },
  AvgDialog_142854_Content_41 = {
    Text = "Trois pas. Seulement trois pas vous séparent de cette gloire suprême..."
  },
  AvgDialog_142854_Content_42 = {
    Text = "Au moment où vous rassemblez votre courage pour faire le premier pas, Lotan se retourne. Ces Yeux fatigués vous regardent avec calme."
  },
  AvgDialog_142854_Content_43 = {
    Text = "Au moment où vous rassemblez votre courage pour faire le premier pas, Lotan se retourne. Ces Yeux fatigués vous regardent avec calme."
  },
  AvgDialog_142854_Content_44 = {
    Text = "À l'instant où Le Regard se pose sur vous, tous les murmures qui vous soutenaient disparaissent simultanément, et votre Sang bouillonnant se refroidit instantanément."
  },
  AvgDialog_142854_Content_45 = {
    Text = ": Je... : Je..."
  },
  AvgDialog_142854_Content_46 = {
    Text = "Les Yeux de Lotan ne portent pas la moindre intention meurtrière. En regardant ces Yeux, vous comprenez soudain que si ce n'était pour rencontrer la Baleine des Étoiles, personne ici ne méritait qu'Elle lève la main."
  },
  AvgDialog_142854_Content_47 = {
    Text = "Les Yeux de Lotan ne portent pas la moindre intention meurtrière. En regardant ces Yeux, vous comprenez soudain que si ce n'était pour rencontrer la Baleine des Étoiles, personne ici ne méritait qu'Elle lève la main."
  },
  AvgDialog_142854_Content_48 = {
    Text = "C'était Le Regard de quelqu'un qui observe de haut des fourmis se battre pour un morceau de sucre. Rien de plus, aucune autre émotion."
  },
  AvgDialog_142854_Content_49 = {
    Text = "L'histoire des fourmis n'a jamais changé. Elle leva cette main déjà réduite à l'os et posa négligemment ce qu'Elle tenait sur votre tête."
  },
  AvgDialog_142854_Content_5 = {
    Text = "Les murs de pierre des Arènes s'effondrèrent comme du papier, d'énormes blocs de pierre s'écrasèrent depuis les gradins, et les dernières traces fantomatiques de L'Audience illusoire avaient depuis longtemps disparu."
  },
  AvgDialog_142854_Content_50 = {
    Text = "!!! C'est..."
  },
  AvgDialog_142854_Content_51 = {
    Text = "Du Sang chaud et souillé coule de votre tête. Vous tendez la main et, sur votre propre tête, vous touchez la Couronne formée de Sang, froide et poisseuse."
  },
  AvgDialog_142854_Content_52 = {
    Text = "D'innombrables héros ont tué pour elle, d'innombrables humanités ont sombré pour elle. Le pouvoir et la richesse de six royaumes, la noblesse et la gloire suprêmes, reposent en ce moment légèrement sur votre tête."
  },
  AvgDialog_142854_Content_53 = {
    Text = "Le vainqueur ultime vous la jeta négligemment, comme on glisse un bonbon dans la bouche Gourmandise d'un enfant — désormais, vous possédez tout."
  },
  AvgDialog_142854_Content_54 = {
    Text = "Seigneur Lotan... Vous... Vous..."
  },
  AvgDialog_142854_Content_55 = {
    Text = "Rendez-moi un service."
  },
  AvgDialog_142854_Content_56 = {
    Text = "Je pars à la recherche d'un nouvel adversaire. Avant cela, j'ai besoin d'une nouvelle paire d'épées."
  },
  AvgDialog_142854_Content_57 = {
    Text = "Lotan contempla la paire de grandes épées qui l'avait accompagnée pendant tant d'années, et rangea leurs dépouilles brisées dans leurs fourreaux."
  },
  AvgDialog_142854_Content_58 = {
    Text = "Elle se retourna et, traînant son corps meurtri, avança avec fatigue et lenteur, vers une destination que vous ne sauriez comprendre."
  },
  AvgDialog_142854_Content_59 = {
    Text = "Dans la fissure derrière vous, les anciennes runes s'éteignirent une à une, et cette divinité en pleine désintégration et corruption laissa apparaître un sourire de soulagement que vous n'aviez jamais vu."
  },
  AvgDialog_142854_Content_6 = {
    Text = "Vous étiez allongé sur le sol jonché de débris, les oreilles bourdonnant sans cesse. La Fissure dimensionnelle était suspendue au centre des Arènes, ses bords se contractant violemment, semblable à une blessure béante et hideuse."
  },
  AvgDialog_142854_Content_60 = {
    Text = "En mon nom... Enregistrement de son nom."
  },
  AvgDialog_142854_Content_61 = {
    Text = "Vous étiez agenouillé dans une mare de Sang, regardant cette silhouette s'éloigner peu à peu, incapable de vous relever pendant un long moment."
  },
  AvgDialog_142854_Content_62 = {
    Text = "La Couronne sur votre tête est lourde, si lourde. Le poids de douze millénaires de désir vous fait tomber à genoux dans le bassin de sang. Vous regardez sa silhouette qui s'éloigne, incapable de vous relever pendant un long, très long moment."
  },
  AvgDialog_142854_Content_63 = {
    Text = "La Couronne au-dessus de sa tête était si légère, si légère, qu'elle semblait n'avoir jamais existé."
  },
  AvgDialog_142854_Content_7 = {
    Text = "Un gémissement grave et prolongé s'échappa de la blessure, traversa votre crâne pour atteindre les profondeurs de votre esprit, aussi lourd que le soupir d'une planète entière."
  },
  AvgDialog_142854_Content_8 = {
    Text = "Ce son... c'est le Léviathan des étoiles ?!"
  },
  AvgDialog_142854_Content_9 = {
    Text = "Une forte odeur de Sang nauséabonde émanait de la fissure. Alors que vous vous apprêtiez à vous en approcher lentement, un pied réduit à l'état de squelette émergea de la fissure."
  },
  AvgDialog_142888_Content_1 = {
    Text = "Un Mensonge"
  },
  AvgDialog_142888_Content_10 = {
    Text = "Tu es incapable de répondre, tes souvenirs sont en ce moment aussi embrouillés qu'un chien à poil long qui aurait roulé trois fois dans la boue."
  },
  AvgDialog_142888_Content_100 = {
    Text = "Il déborde sur ta poitrine, sur tes oreilles, sur..."
  },
  AvgDialog_142888_Content_101 = {
    Text = "Mon Seigneur !"
  },
  AvgDialog_142888_Content_102 = {
    Text = "Vous revenez soudainement à la réalité. Au loin, Ogier, Lotan et Ramona marchent vers vous, ayant terminé leur entraînement. Les marionnettes divisées de Doll analysent leurs données d'entraînement."
  },
  AvgDialog_142888_Content_103 = {
    Text = "La personne à tes côtés pousse un soupir empreint de regret."
  },
  AvgDialog_142888_Content_104 = {
    Text = "Ne vous inquiétez pas, je garderai toujours ce choix ouvert pour vous."
  },
  AvgDialog_142888_Content_105 = {
    Text = "Personne ne reste à vos côtés. L'horizon où le soleil couchant est sur le point de sombrer réfracte une lueur nacrée douce, légèrement psychédélique."
  },
  AvgDialog_142888_Content_106 = {Text = "Ah..."},
  AvgDialog_142888_Content_107 = {
    Text = "Tu as encore tant de choses à dire. À propos de cette catastrophe qui n'avait rien de ciblé, provoquée simplement par N qui, par espièglerie, avait manipulé ses fidèles."
  },
  AvgDialog_142888_Content_108 = {
    Text = "À propos du rôle du Sanctuaire de la Lanterne dans l›attisement des flammes, à propos des divers actes de représailles insensés de Pontos au cours du siècle suivant environ."
  },
  AvgDialog_142888_Content_109 = {
    Text = "À propos de... s'il y a eu un instant où lui aussi a été ébranlé par une autre possibilité, au point de laisser le temps graver des marques sur lui."
  },
  AvgDialog_142888_Content_11 = {
    Text = "Leisha, épuisée elle aussi par les combats précédents, rassembla ses forces pour se redresser et s'interposer entre toi et Pontos."
  },
  AvgDialog_142888_Content_110 = {
    Text = "À propos de Jago et Leisha — sont-ils encore en train de faire la fête à Ebwynnos en ce moment ?"
  },
  AvgDialog_142888_Content_111 = {
    Text = "... Finalement, tu ne veux que prier pour qu'il n'aille pas causer des ennuis au professeur Dexter à l'école."
  },
  AvgDialog_142888_Content_112 = {
    Text = "Vous secouez la tête et marchez vers vos amis sans hésitation."
  },
  AvgDialog_142888_Content_12 = {
    Text = "Pontos, c'est terminé."
  },
  AvgDialog_142888_Content_13 = {
    Text = "Les vivants qui restent à Ebwynnos devront en payer le prix : oublier tous leurs souvenirs du monde extérieur."
  },
  AvgDialog_142888_Content_14 = {
    Text = "Et pour ceux comme moi, déjà morts et refaçonnés en cauchemar, tous les souvenirs finissent par être lentement rongés par la Corrosion."
  },
  AvgDialog_142888_Content_15 = {
    Text = "Jago a fait son choix, et moi j'ai fait le mien...\\nPartons d'ici."
  },
  AvgDialog_142888_Content_16 = {
    Text = "Les lèvres de Pontos se pincèrent en une ligne froide et indifférente, ses mâchoires crispées."
  },
  AvgDialog_142888_Content_17 = {
    Text = "Tu t'en souviens sûrement : tu existes grâce à Ebwynnos. Si tu quittes Ebwynnos, tu mourras."
  },
  AvgDialog_142888_Content_18 = {
    Text = "Oui, mais mes souvenirs d'autrefois me reviendront. Je mourrai en tant qu'être humain — c'est la seule façon."
  },
  AvgDialog_142888_Content_19 = {
    Text = "Je ne me souviens déjà... plus de ce à quoi vous ressembliez, toi et Jago, quand vous étiez enfants. Au moins, avant que je vous oublie tous les deux entièrement."
  },
  AvgDialog_142888_Content_2 = {
    Text = "L'Intimidation suffocante se retire comme une marée, ton cerveau est traversé d'une douleur lancinante et ta vision se brouille par intermittence."
  },
  AvgDialog_142888_Content_20 = {
    Text = "Pontos se figea sur place. Pour la première fois, tu vis apparaître sur son visage une expression d'une telle tristesse."
  },
  AvgDialog_142888_Content_21 = {
    Text = "...J'aurais vraiment voulu pouvoir dire que cette Force me contrôlait encore."
  },
  AvgDialog_142888_Content_22 = {
    Text = "Il ferma les yeux, comme pour fuir ce qu'il ne voulait pas affronter. Puis, il esquissa un sourire amer et résigné."
  },
  AvgDialog_142888_Content_23 = {
    Text = "Ainsi, j'aurais pu bafouer votre volonté en toute bonne conscience et vous faire du mal."
  },
  AvgDialog_142888_Content_24 = {Text = "新增"},
  AvgDialog_142888_Content_25 = {
    Text = "Pontos cède en silence. Le chariot qui l'avait autrefois porté vers sa vengeance contre ses ennemis emporte désormais Leisha sur son chemin."
  },
  AvgDialog_142888_Content_26 = {
    Text = "Alors que le chariot, irradiant une lueur nacrée indescriptible, glisse au-delà des cieux d'Ebwynnos, une expression de soulagement apparaît sur le visage de Leisha. Elle se retourne pour vous faire face à tous les deux..."
  },
  AvgDialog_142888_Content_27 = {
    Text = "Puis disparut complètement dans la brise nocturne de la mer."
  },
  AvgDialog_142888_Content_28 = {
    Text = "Aucun de vous ne prit la parole ; vous contemplâtes longuement ce Vide, jusqu'à ce que Pontos brise le silence."
  },
  AvgDialog_142888_Content_29 = {
    Text = "Comment était votre vie après avoir quitté Ebwynnos, la vie de « Vous » ?"
  },
  AvgDialog_142888_Content_3 = {
    Text = "Aïe, ça fait vraiment mal !"
  },
  AvgDialog_142888_Content_30 = {
    Text = "Tu ne t'attendais pas à ce que ce soit sa première phrase. Tu demeuras interdit un instant, puis commenças à démêler le fil de tes souvenirs épars."
  },
  AvgDialog_142888_Content_31 = {
    Text = "Quelque chose semble avoir mal tourné dans ce Labyrinthe. Ni les souvenirs de Jago ni les vôtres ne sont entièrement intacts."
  },
  AvgDialog_142888_Content_32 = {
    Text = "...Je ne m›en souviens pas clairement. Mon esprit contient maintenant à la fois des souvenirs d›être Jago et des souvenirs d›être quelqu›un d›autre, dans un endroit lointain. Tous les souvenirs sont mélangés."
  },
  AvgDialog_142888_Content_33 = {
    Text = "Instinctivement, tu glissas la main dans ta poche pour caresser la sauterelle de paille."
  },
  AvgDialog_142888_Content_34 = {
    Text = "Mais même ainsi — simple, ordinaire, occupée, les mêmes routines jour après jour — c'était une vie heureuse."
  },
  AvgDialog_142888_Content_35 = {
    Text = "Assez heureuse pour faire de moi ce que je suis. Assez heureuse pour que, quoi qu'il arrive, je veuille y retourner."
  },
  AvgDialog_142888_Content_36 = {
    Text = "Il plonge son regard dans le vôtre, calme et immobile. C'est presque comme... comme la façon dont Leisha vous regardait autrefois."
  },
  AvgDialog_142888_Content_37 = {
    Text = "<Red:Il ne fait pas que regarder Jago.>"
  },
  AvgDialog_142888_Content_38 = {
    Text = "Vous vous trompez, Jago... <Red:%player%>."
  },
  AvgDialog_142888_Content_39 = {Text = "!!!???"},
  AvgDialog_142888_Content_4 = {
    Text = "Pontos se tient seul à sa place, tu n'arrives pas à distinguer son expression."
  },
  AvgDialog_142888_Content_40 = {Text = "Quoi ?!"},
  AvgDialog_142888_Content_41 = {
    Text = "Un frisson vous traverse. Comment peut-il connaître <Red:«votre»> nom ? N'est-ce pas seulement un Labyrinthe ?"
  },
  AvgDialog_142888_Content_42 = {
    Text = "Il retrouve ce calme froid et aristocratique, comme si rien ne lui avait jamais échappé, et vous adresse un sourire serein."
  },
  AvgDialog_142888_Content_43 = {
    Text = "Je sais que <Red:« Vous »> avez toujours été ici, je sais que <Red:« Vous »> êtes « Lui », depuis que <Red:« Vous »> étiez enfant, je savais que <Red:« Vous »> étiez différent des autres."
  },
  AvgDialog_142888_Content_44 = {
    Text = "Le bruit sourd et pesant de l'eau de mer envahit à nouveau tes oreilles."
  },
  AvgDialog_142888_Content_45 = {
    Text = "Vous êtes encore trop jeunes, trop ignorants, vous croyez à tort que cette médiocrité s'appelle le bonheur."
  },
  AvgDialog_142888_Content_46 = {
    Text = "Cette fois, je ne commettrai pas l'<Red:erreur> de laisser le choix entre vos mains à nouveau."
  },
  AvgDialog_142888_Content_47 = {
    Text = "Vous aviez tort. Il n'a jamais cédé. Il ne lâchera pas prise, et n'avait jamais eu l'intention de le faire. Il n'a fait que poser un leurre lumineux."
  },
  AvgDialog_142888_Content_48 = {
    Text = "Il avait depuis longtemps découvert l'autre partie de «vous». \nIl allait vous trouver. Il ne laisserait plus place à aucune surprise."
  },
  AvgDialog_142888_Content_49 = {
    Text = "Trop facile. Cette bataille, cette victoire. \nC'était un piège pour attirer <Italic:toi> hors de ta cachette."
  },
  AvgDialog_142888_Content_5 = {
    Text = "Mais de toute évidence, quelque chose l'avait déjà quitté."
  },
  AvgDialog_142888_Content_50 = {
    Text = "Quel que soit le prix à payer, quelle que soit l'existence à laquelle je dois jurer allégeance..."
  },
  AvgDialog_142888_Content_51 = {
    Text = "Je ferai en sorte que la fête d'Ebwynnos dure éternellement."
  },
  AvgDialog_142888_Content_52 = {
    Text = "Personne ne savait pourquoi il avait soudainement laissé le vieillissement s›emparer de lui."
  },
  AvgDialog_142888_Content_53 = {
    Text = "Tout Ebwynnos tremble avec lui. Les médiums autour de lui et l'eau de mer qui jaillit de sa poitrine se mêlent, indissociables les uns des autres."
  },
  AvgDialog_142888_Content_54 = {
    Text = "Peut-être des amis, peut-être des ennemis. D'innombrables bras noirs s'étendent depuis sa poitrine, griffant sa peau, la caressant."
  },
  AvgDialog_142888_Content_55 = {
    Text = "Comme s'ils cherchaient à fuir. Comme s'ils aspiraient à rester avec lui pour toujours."
  },
  AvgDialog_142888_Content_56 = {
    Text = "Je suis sur une route sans retour. Et je n'en ai pas besoin."
  },
  AvgDialog_142888_Content_57 = {
    Text = "Les années que tu n'as jamais vécues ne signifient rien. Ici, à Ebwynnos, elles sont apprivoisées. Contrôlables. Elles ne peuvent pas te blesser."
  },
  AvgDialog_142888_Content_58 = {
    Text = "C'est vraiment dommage. Je ne peux pas encore te garder ici. Notre temps est écoulé, <Red:%player%>."
  },
  AvgDialog_142888_Content_59 = {Text = "!!!"},
  AvgDialog_142888_Content_6 = {
    Text = "Donne-moi une raison."
  },
  AvgDialog_142888_Content_60 = {
    Text = "Une apesanteur te prend par surprise, t'arrachant vers le haut et hors de l'espace déchiré. Des Thrall-Décharnés obscurcissant le ciel déploient leurs ailes membraneuses et se précipitent vers toi dans un doux élan."
  },
  AvgDialog_142888_Content_61 = {
    Text = "Ne t'inquiète pas. Nous nous reverrons bientôt."
  },
  AvgDialog_142888_Content_62 = {
    Text = "Ebwynnos et moi attendrons ton retour. Pour toujours."
  },
  AvgDialog_142888_Content_63 = {
    Text = "Les marques du temps s'étendent sur le corps de Pontos comme une érosion."
  },
  AvgDialog_142888_Content_64 = {
    Text = "Il éclate de rire et, depuis Ebwynnos qui s'éloigne rapidement de toi, lève son verre en ta direction."
  },
  AvgDialog_142888_Content_65 = {
    Text = "Dans ton dernier regard avant que l'obscurité ne l'engloutisse, tu aperçois deux silhouettes se tenant à ses côtés."
  },
  AvgDialog_142888_Content_66 = {
    Text = "Il n'a laissé partir personne. Il les a tous gardés — jusqu'au dernier."
  },
  AvgDialog_142888_Content_67 = {
    Text = "<Red:C'est Leisha, et Jago jeune.>"
  },
  AvgDialog_142888_Content_68 = {Text = "新增"},
  AvgDialog_142888_Content_69 = {
    Text = "Hein ?! Et ensuite, et ensuite ? Le Gardien ne s'est pas écrasé au sol, j'espère !"
  },
  AvgDialog_142888_Content_7 = {
    Text = "Sa voix est rauque, mais son corps reste tendu, comme une bête acculée au bout du chemin."
  },
  AvgDialog_142888_Content_70 = {
    Text = "L'oncle Pontos est vraiment méchant ! Il ne peut pas te faire ça !!"
  },
  AvgDialog_142888_Content_71 = {
    Text = "Ouais, comment tu peux être aussi méchant, Pontos !"
  },
  AvgDialog_142888_Content_72 = {
    Text = "Tu es en train de raconter avec fougue tes aventures dans le Rêve à Aurita, quand tu te retournes..."
  },
  AvgDialog_142888_Content_73 = {
    Text = "Et tu sursautes en découvrant quelqu'un, les mains dans les poches, appuyé contre la Porte avec le même enthousiasme, qui écoutait depuis on ne sait combien de temps."
  },
  AvgDialog_142888_Content_74 = {
    Text = "Après cela, le petit Jago s'en sortit sain et sauf. Il ouvrit les yeux et se réveilla du rêve."
  },
  AvgDialog_142888_Content_75 = {
    Text = "Il se retrouva allongé dans son propre lit chez lui, entouré des gens qu'il aimait."
  },
  AvgDialog_142888_Content_76 = {
    Text = "L'autre personnage principal de l'histoire s'appuie contre le mur de la chambre d'Aurita et, d'une voix basse et posée, fournit la conclusion."
  },
  AvgDialog_142888_Content_77 = {
    Text = "Il se remémora tous les souvenirs de sa vie, ferma paisiblement les yeux, et partit vers un lieu de bonheur."
  },
  AvgDialog_142888_Content_78 = {
    Text = "Aurita pousse un petit soupir satisfait et s'endort peu à peu dans un demi-sommeil, tout comme Vera dans tes souvenirs."
  },
  AvgDialog_142888_Content_79 = {
    Text = "Pontos incline la tête vers la porte et fait un geste d'invitation."
  },
  AvgDialog_142888_Content_8 = {
    Text = "Pourquoi, pourquoi toi aussi tu pars, pourquoi préférer te jeter dans la mort plutôt que —"
  },
  AvgDialog_142888_Content_80 = {
    Text = "J'imagine que vous souhaitez me parler ?"
  },
  AvgDialog_142888_Content_81 = {Text = "新增"},
  AvgDialog_142888_Content_82 = {
    Text = "Retrouvailles après une longue séparation — quelle belle expression."
  },
  AvgDialog_142888_Content_83 = {
    Text = "Tu n'as pas dit à Aurita comment ça s'est vraiment terminé. Tu as menti, n'est-ce pas ?"
  },
  AvgDialog_142888_Content_84 = {
    Text = "Tu n'as jamais laissé partir Leisha. Et le seul à avoir pu quitter Ebwynnos, c'est moi, pas Jago."
  },
  AvgDialog_142888_Content_85 = {
    Text = "Interrompu aussi abruptement, Pontos n'est pas du tout agacé. Il sourit et hausse un sourcil."
  },
  AvgDialog_142888_Content_86 = {
    Text = "Bien sûr, évidemment. Certaines histoires ne sont pas faites pour être racontées aux Enfants, n'est-ce pas ?"
  },
  AvgDialog_142888_Content_87 = {
    Text = "Alors j'imagine que cette... <Italic:apparence> que tu arbores maintenant... c'est juste pour montrer à tout le monde que vieillir — cette seule chose qui t'a manqué — ne signifie rien pour toi."
  },
  AvgDialog_142888_Content_88 = {
    Text = "Pour montrer que tu as tout sous contrôle, hein ? Le temps. Le vieillissement. Même la vie des autres..."
  },
  AvgDialog_142888_Content_89 = {
    Text = "L'hostilité dans vos mots est probablement trop évidente pour passer inaperçue. Pontos ne répond pas directement ; il vous adresse simplement un sourire qui vous exaspère au plus haut point."
  },
  AvgDialog_142888_Content_9 = {
    Text = "Et non « Je »."
  },
  AvgDialog_142888_Content_90 = {
    Text = "Qui sait ? Peut-être que je voulais simplement essayer quelque chose de nouveau."
  },
  AvgDialog_142888_Content_91 = {
    Text = "Quoi qu'il en soit, je suis heureux que vous vous en souveniez. Depuis la toute première fois que je suis venu à Mizag, j'attendais ce jour avec impatience."
  },
  AvgDialog_142888_Content_92 = {
    Text = "Ebwynnos vous attend encore, %player%."
  },
  AvgDialog_142888_Content_93 = {
    Text = "... Si tu as besoin d'un rappel, Mizag dispose d'un système de sécurité complet."
  },
  AvgDialog_142888_Content_94 = {
    Text = "Ne sois pas si tendu."
  },
  AvgDialog_142888_Content_95 = {
    Text = "À ce propos, je suis plutôt curieux. Mon petit de Mizag, vous n'êtes plus Jago. Avez-vous une réponse pour moi maintenant ?"
  },
  AvgDialog_142888_Content_96 = {
    Text = "Pontos tourne légèrement la tête, et tu croises son regard bleu profond."
  },
  AvgDialog_142888_Content_97 = {
    Text = "Si je vous donnais une chance de plus de choisir, choisiriez-vous la vie éternelle avec une jeunesse perpétuelle, ou les souvenirs créés au fil d'une vie entière ?"
  },
  AvgDialog_142888_Content_98 = {
    Text = "Le bruit des vagues, le frémissement des ailes."
  },
  AvgDialog_142888_Content_99 = {
    Text = "Ce bruit blanc familier et lointain imprègne à nouveau lentement ton corps."
  },
  AvgDialog_142889_Content_1 = {
    Text = "La Meilleure Chose au Monde"
  },
  AvgDialog_142889_Content_10 = {
    Text = "Quand tu seras grande, tu comprendras. Nous nous reverrons toujours, et quand nous serons séparés, je penserai à toi tout le temps."
  },
  AvgDialog_142889_Content_100 = {
    Text = "Il soupire. Avec un sourire parfaitement naturel, il achève alors le reste de la phrase en même temps qu'une autre voix."
  },
  AvgDialog_142889_Content_101 = {
    Text = "De quoi parles–tu ? Ici, c›est Ebwynnos. Il n›y a pas de vieillissement ici. Nous festoierons pour toujours, éternellement jeunes."
  },
  AvgDialog_142889_Content_102 = {
    Text = "<Italic:Quelqu'un> sort de derrière Orney. Il parle d'une voix basse et rauque, comme le plus magnanime et le plus digne des anciens."
  },
  AvgDialog_142889_Content_103 = {
    Text = "Ce n'est pas la voix de Pontos."
  },
  AvgDialog_142889_Content_104 = {
    Text = "Elle est si ancienne qu'elle balaie toute trace de familiarité, ne laissant que les <Red:profondeurs> les plus abyssales de l'océan, l'écho de l'eau de mer qui traverse votre esprit une fois de plus."
  },
  AvgDialog_142889_Content_105 = {
    Text = "Oui, oui, ici c›est Ebwynnos. Je suis revenu à Ebwynnos."
  },
  AvgDialog_142889_Content_106 = {
    Text = "<Shake:<Red:Nous ferons la fête pour toujours.>>"
  },
  AvgDialog_142889_Content_107 = {
    Text = "<Red:Nous serons jeunes pour toujours.>"
  },
  AvgDialog_142889_Content_108 = {
    Text = "Tu es si heureux, si insouciant. Tu es à Ebwynnos."
  },
  AvgDialog_142889_Content_109 = {
    Text = "En dehors de cela, toutes les pensées sans importance se sont dissipées."
  },
  AvgDialog_142889_Content_11 = {
    Text = "<Red:Clac —>"
  },
  AvgDialog_142889_Content_110 = {
    Text = "Cependant, sans savoir pourquoi, tu n'as montré à personne cette sauterelle dont tu avais oublié le nom."
  },
  AvgDialog_142889_Content_12 = {
    Text = "Au moment même où la boussole venait de quitter vos mains, une série de légers bruits rapprochés retentit depuis l'extérieur de la fenêtre."
  },
  AvgDialog_142889_Content_13 = {
    Text = "Puis, un petit rire."
  },
  AvgDialog_142889_Content_14 = {
    Text = "Voyons voir qui est ce beau petit bonhomme—"
  },
  AvgDialog_142889_Content_15 = {
    Text = "Sous l›effet d›une force invisible et immense, la fenêtre s›est ouverte en grand. Dans l›obscurité profonde et cacophonique, la lune argentée scintillait à travers les interstices."
  },
  AvgDialog_142889_Content_16 = {
    Text = "Bonjour, Jago."
  },
  AvgDialog_142889_Content_17 = {
    Text = "Tant de... tant d›ailes, Grand-père !!"
  },
  AvgDialog_142889_Content_18 = {
    Text = "D›innombrables ailes membraneuses noires et immenses, obscurcissant le ciel, ont déferlé vers toi. Tes pupilles tremblaient tandis que tu fixais le centre sombre, incapable de bouger."
  },
  AvgDialog_142889_Content_19 = {
    Text = "<Red:Oncle Pontos...>"
  },
  AvgDialog_142889_Content_2 = {
    Text = "Le souvenir s'estompe. Tu gardes le silence un long moment."
  },
  AvgDialog_142889_Content_20 = {
    Text = "Squish... glourp... <LightGray:*bruit visqueux d'écrasement>"
  },
  AvgDialog_142889_Content_21 = {
    Text = "La petite main de Vera s'agrippe désespérément à toi, ne laissant finalement qu'une profonde marque de griffure.\nEnveloppement, suffocation, engloutissement."
  },
  AvgDialog_142889_Content_22 = {
    Text = "Serein. Calme. Familier. Agréable..."
  },
  AvgDialog_142889_Content_23 = {
    Text = "Des vagues de bruit blanc ont envahi vos oreilles."
  },
  AvgDialog_142889_Content_24 = {
    Text = "<Red:Chute.>"
  },
  AvgDialog_142889_Content_25 = {Text = "新增"},
  AvgDialog_142889_Content_26 = {
    Text = "Jago, réveille-toi. Arrête de dormir."
  },
  AvgDialog_142889_Content_27 = {
    Text = "Les festivités du jour sont sur le point de commencer. Tout le monde t›attend."
  },
  AvgDialog_142889_Content_28 = {
    Text = "Un bruit blanc perçant envoie une douleur aiguë à travers tes tympans, et tu te redresses instinctivement dans le lit."
  },
  AvgDialog_142889_Content_29 = {
    Text = "Je vous avais dit qu›il reviendrait vite à lui. Mon Jago est un petit bonhomme remarquable."
  },
  AvgDialog_142889_Content_3 = {
    Text = "Appelle ça l'égoïsme d'un vieil homme, penses-tu — car tu es peut-être la dernière personne à se souvenir d'eux, et tu ne veux pas qu'ils soient oubliés."
  },
  AvgDialog_142889_Content_30 = {
    Text = "Pontos sourit et donne un coup de coude à Leisha. Orney, Oncle White, et de nombreux visages familiers sont tous rassemblés autour de ton lit."
  },
  AvgDialog_142889_Content_31 = {
    Text = "Ta conscience semble submergée dans les profondeurs de l›eau. Tu as le sentiment tenace d›avoir oublié quelque chose, et l›agilité de ton corps te semble subtilement anormale."
  },
  AvgDialog_142889_Content_32 = {
    Text = "Oncle Pontos, Maman ? Que s›est-il passé ? Pourquoi tout le monde est là ?"
  },
  AvgDialog_142889_Content_33 = {
    Text = "Oh, vous avez fait un long voyage, petit, j'ai mis très, très longtemps à vous retrouver."
  },
  AvgDialog_142889_Content_34 = {
    Text = "Maintenant, je vous ramène à la maison."
  },
  AvgDialog_142889_Content_35 = {
    Text = "Le soleil couchant perce à travers les nuages, découpant la mer en ondulations scintillantes comme de l›or éparpillé se reflétant sur les vitres. Tu es de retour dans l›auberge en bord de mer où tu as grandi."
  },
  AvgDialog_142889_Content_36 = {
    Text = "Ah, c›est vrai. Cet endroit, c›est... @4"
  },
  AvgDialog_142889_Content_37 = {Text = "??!!!"},
  AvgDialog_142889_Content_38 = {
    Text = "ABYSSABYSSABYSSABYSSABYSSABYSSABYSSABYSS\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1\n@1B@1S@2Y@2@2y@1sa@1y@2@4@2Y@1\na@1y@2A@4ss@2ysssssAb@3abyss@2@3\n厄@2@3波@1@3厄@2yssSS@2YA@4\n@1B@1S@2Y@2@2y@1sa@1y@2@4@2Y@1\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1\n@1@2@3扬@1@3斯@2y!!ab@2YA@4\nABYssABySSabySSAByssabYSSa@2SAByssabyssABYSS@2\nABYSSABYSSABYSS@4@3SSABYSS@2@3\n@3@2@4@3@1@3@3!!!!!!!\na@1y@2A@4ss@2ysssssAb@3abyss@2@3\n@3@4YssAby!!!!!!!ABYSSABYSSABy@1\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1@1\n@1B@1S@2Y@2@2y@1sa@1y@2@4<Red:!!!!!!>"
  },
  AvgDialog_142889_Content_39 = {
    Text = "Une douleur lancinante, une pression oppressante — le nom de la ville reste coincé sur le bout de ta langue."
  },
  AvgDialog_142889_Content_4 = {
    Text = "Tu regardes Vera avec tendresse. Ta famille, attentionnée, vous a laissés seuls tous les deux pour que tu ne te fatigues pas."
  },
  AvgDialog_142889_Content_40 = {
    Text = "Un crissement strident comme du fer raclant du verre s›écrase depuis l›intérieur de ton crâne jusque dans ta gorge, transformant ton cerveau en une pâte épaisse et visqueuse."
  },
  AvgDialog_142889_Content_41 = {
    Text = "Jusqu›à ce que cette paume chaude et rugueuse berce l›arrière de votre tête, et comme toujours, il rit et presse son front contre le vôtre."
  },
  AvgDialog_142889_Content_42 = {
    Text = "Hé, revenez à moi. Qu›est–ce qui ne va pas ?"
  },
  AvgDialog_142889_Content_43 = {
    Text = "Vous ouvrez lentement la bouche, cherchant votre voix à tâtons."
  },
  AvgDialog_142889_Content_44 = {
    Text = "Pontos vous observe attentivement, et vous ne comprenez pas — la façon dont il vous regarde, c›est la façon dont on regarde quelque chose que l›on croyait avoir perdu pour toujours."
  },
  AvgDialog_142889_Content_45 = {
    Text = "Comme si vous étiez la chose la plus précieuse au monde."
  },
  AvgDialog_142889_Content_46 = {
    Text = "Bienvenue à Ebwynnos, Jago."
  },
  AvgDialog_142889_Content_47 = {
    Text = "La conscience revient en flots. Vous regardez fixement toutes les choses familières autour de vous, la lumière du soleil faisant suer les planchers jusqu›à en extraire des grains de sel..."
  },
  AvgDialog_142889_Content_48 = {
    Text = "Un bonheur étrange et serein noie toute autre pensée. Un sourire remonte lentement sur votre visage."
  },
  AvgDialog_142889_Content_49 = {
    Text = "Je me souviens maintenant. Ebwynnos. C›est Ebwynnos — l›endroit où j›ai grandi..."
  },
  AvgDialog_142889_Content_5 = {
    Text = "Je n›ai jamais revu Maman ni Oncle Pontos. Sans cette boussole, j›aurais probablement cru que tout n›était qu›une hallucination causée par l›explosion."
  },
  AvgDialog_142889_Content_50 = {
    Text = "C›est ça. Ça faisait longtemps !"
  },
  AvgDialog_142889_Content_51 = {
    Text = "Tu es enfin rentré à la maison, Jago."
  },
  AvgDialog_142889_Content_52 = {Text = "新增"},
  AvgDialog_142889_Content_53 = {
    Text = "Vos pensées semblent avoir été trempées dans un sirop appelé bonheur. Tout le monde autour de vous paraît aussi jeune que lorsque vous vous êtes séparés..."
  },
  AvgDialog_142889_Content_54 = {
    Text = "Oh... séparés."
  },
  AvgDialog_142889_Content_55 = {
    Text = "Quand avez–vous quitté Ebwynnos, et comment êtes–vous revenu ? Il vous semble que vous étiez allongé dans un autre lit il n›y a pas si longtemps. Vous avez une petite–fille, qui s›appelle..."
  },
  AvgDialog_142889_Content_56 = {
    Text = "À quoi pensez–vous, petit ?"
  },
  AvgDialog_142889_Content_57 = {
    Text = "Pontos était appuyé contre la fenêtre, le soleil couchant s›enfonçant déjà dans la mer, ses derniers rayons de lumière dissimulés derrière lui."
  },
  AvgDialog_142889_Content_58 = {
    Text = "Oncle Pontos, j›ai l›impression d›avoir oublié quelque chose de très important. Qu›est–ce que c›était..."
  },
  AvgDialog_142889_Content_59 = {
    Text = "Ha ha ha, si vous n'arrivez pas à vous en souvenir pour l'instant, c'est que ce n'est pas si important. Ne vous pressez pas, à Ebwynnos, nous avons tout le temps qu'il nous faut."
  },
  AvgDialog_142889_Content_6 = {
    Text = "Alors, Vera, c'est pour ça que grand-père voulait te raconter cette histoire."
  },
  AvgDialog_142889_Content_60 = {
    Text = "Allez ! Vous êtes encore jeune, vous avez de belles années devant vous, autant les consacrer à faire la fête."
  },
  AvgDialog_142889_Content_61 = {
    Text = "Il passa son bras autour de vos épaules et se dirigea vers la salle nouvellement décorée en bas, où la foule en liesse vous entraîna ensemble sur la piste de danse."
  },
  AvgDialog_142889_Content_62 = {
    Text = "C›est seulement maintenant que vous remarquez que l›auberge est devenue une salle d›une splendeur éblouissante."
  },
  AvgDialog_142889_Content_63 = {
    Text = "Des visages familiers rient à travers la piste de danse, levant leurs coupes et vous faisant signe, des tasses en bois et en verre s›entrechoquant dans un brouhaha épars."
  },
  AvgDialog_142889_Content_64 = {
    Text = "Je suis encore jeune, je suis encore... jeune ?"
  },
  AvgDialog_142889_Content_65 = {
    Text = "Un lourd vertige vous envahit à nouveau. Cet étrange bonheur vous étreint, sans vous lâcher."
  },
  AvgDialog_142889_Content_66 = {
    Text = "Vous levez le bras et voyez deux mains jeunes et fortes ;"
  },
  AvgDialog_142889_Content_67 = {
    Text = "vous regardez dans le verre, et le visage d›un jeune homme arbore le même rire que tout le monde."
  },
  AvgDialog_142889_Content_68 = {
    Text = "Amis, levons nos verres — à Ebwynnos !"
  },
  AvgDialog_142889_Content_69 = {
    Text = "Avant que vous puissiez vous ressaisir, Pontos passe par–dessus votre épaule et lève son verre vers la foule."
  },
  AvgDialog_142889_Content_7 = {
    Text = "Ils planent peut-être encore quelque part dans le ciel nocturne. Et si un jour je disparais, c'est peut-être qu'ils sont venus me ramener à la maison."
  },
  AvgDialog_142889_Content_70 = {
    Text = "À Ebwynnos !"
  },
  AvgDialog_142889_Content_71 = {
    Text = "Dans une allégresse immense et confuse, vous levez votre verre avec les autres, et la vague de voix vous entraîne vers le cœur de la foule."
  },
  AvgDialog_142889_Content_72 = {
    Text = "Vous fêtez, vous dansez, vous buvez sans retenue."
  },
  AvgDialog_142889_Content_73 = {
    Text = "Les rayons de lumière de la haute maison percent la brume qui monte de la mer, scintillant toute la nuit."
  },
  AvgDialog_142889_Content_74 = {
    Text = "Ce n›est que lorsqu›une faible lueur pâle apparut à l›horizon et que les gens s›effondrèrent les uns contre les autres dans le sommeil que vous, légèrement éméché vous–même, fredonnâtes une chanson et vous laissâtes aller contre les coussins doublés de velours."
  },
  AvgDialog_142889_Content_75 = {Text = "新增"},
  AvgDialog_142889_Content_76 = {
    Text = "Vous êtes presque en train de vous assoupir lorsque vous apercevez soudain le visage de Leisha dans un coin de la salle. Vous vous précipitez vers elle."
  },
  AvgDialog_142889_Content_77 = {
    Text = "Maman ! Attends-moi, où es-tu allée ? Je ne t'ai pas vue de toute la soirée."
  },
  AvgDialog_142889_Content_78 = {
    Text = "Une panique inexplicable saisit votre cœur, et vous ne pouvez vous empêcher de murmurer pour vous–même."
  },
  AvgDialog_142889_Content_79 = {
    Text = "Comme c›est étrange — n›étais–je pas simplement parti en voyage ? Pourquoi ai–je l›impression que nous ne nous sommes pas vus depuis si longtemps ?"
  },
  AvgDialog_142889_Content_8 = {
    Text = "Mais... je ne veux pas être séparée de Grand-père. Tu peux m'emmener avec toi ?"
  },
  AvgDialog_142889_Content_80 = {
    Text = "Vos pas s›arrêtèrent brusquement — à cause de l›expression de totale impuissance et de chagrin sur le visage de Leisha."
  },
  AvgDialog_142889_Content_81 = {
    Text = "Il t›a trouvé. Mon pauvre Jago, tu n›aurais jamais dû venir ici."
  },
  AvgDialog_142889_Content_82 = {
    Text = "Réfléchis, vite — tant que tu n›as pas encore oublié. Souviens–toi de la vie que tu as vécue."
  },
  AvgDialog_142889_Content_83 = {
    Text = "Les larmes de Mère tombèrent sur ta main, si froides que tu reculais instinctivement. L›air glacial envoya des frissons parcourir tout ton corps en un instant."
  },
  AvgDialog_142889_Content_84 = {
    Text = "Regardez les gens autour de vous. Regardez-moi. Regardez ce que nous devrions être."
  },
  AvgDialog_142889_Content_85 = {
    Text = "Plongez la main dans votre poche, Jago."
  },
  AvgDialog_142889_Content_86 = {
    Text = "Maladroit, grossier, un peu piquant — il y avait là une <Red:sauterelle>."
  },
  AvgDialog_142889_Content_87 = {
    Text = "Une sauterelle faite par <Red:Vera>, qui s'appelait <Red:Vera>."
  },
  AvgDialog_142889_Content_88 = {
    Text = "<Shake:<Red:Vera>... non, j'ai déjà... cela fait longtemps...>"
  },
  AvgDialog_142889_Content_89 = {
    Text = "<Shake:Je suis en train de mourir, je suis allongé dans mon lit, j'avais des amis, j'avais l'amour de ma vie, j'avais des enfants, j'étais...>"
  },
  AvgDialog_142889_Content_9 = {
    Text = "Vous ne pouvez retenir un sourire, et sortez de votre sein cette boussole qui ne vous a pas quitté depuis des dizaines d'années, pour la déposer dans la paume de Vera."
  },
  AvgDialog_142889_Content_90 = {
    Text = "Tout ce qui vous entoure tourbillonne dans un désordre chaotique, deux trains de pensée totalement différents s'entremêlent."
  },
  AvgDialog_142889_Content_91 = {
    Text = "Vous vous prenez la tête entre les mains, plié en deux de douleur, haletant."
  },
  AvgDialog_142889_Content_92 = {
    Text = "Grands dieux, Jago, qu›est–ce qui t›arrive ? Tu as une mine affreuse !"
  },
  AvgDialog_142889_Content_93 = {
    Text = "Orney vous percute de nulle part, et le bourdonnement dans vos oreilles disparaît d'un coup."
  },
  AvgDialog_142889_Content_94 = {
    Text = "Vous levez les yeux, et Leisha a déjà disparu."
  },
  AvgDialog_142889_Content_95 = {
    Text = "Orney, Orney, non, non, je me souviens maintenant !"
  },
  AvgDialog_142889_Content_96 = {
    Text = "On a grandi ensemble, n'est-ce pas ? J'étais à ta remise de diplôme, à ton mariage. Tu ne devrais pas être si jeune ! On a le même âge, on a tous les deux vieilli..."
  },
  AvgDialog_142889_Content_97 = {
    Text = "Orney vous fixe avec une expression que vous ne reconnaissez absolument pas, et il vous fixe pendant un long, très long moment, au point que vous avez presque envie de fuir."
  },
  AvgDialog_142889_Content_98 = {Text = "Alors..."},
  AvgDialog_142889_Content_99 = {
    Text = "Ah, Jago..."
  },
  AvgDialog_142890_Content_1 = {
    Text = "Elle et Lui"
  },
  AvgDialog_142890_Content_10 = {
    Text = "Merci pour ton Cadeau, oncle Pontos, mais..."
  },
  AvgDialog_142890_Content_11 = {
    Text = "Ce dut être une vie très longue et précieuse — pour cela, je suis prêt à renoncer à une jeunesse éternelle et à mes PV."
  },
  AvgDialog_142890_Content_12 = {
    Text = "Les gens cessent de parler. À l'unisson, tout le monde se tourne pour te regarder."
  },
  AvgDialog_142890_Content_13 = {
    Text = "Tes tympans sont douloureux au point de sembler sur le point d'éclater, le clapotis de l'eau de mer fore à l'intérieur de ton crâne."
  },
  AvgDialog_142890_Content_14 = {
    Text = "À travers les eaux profondes et étouffantes, tu entends un soupir."
  },
  AvgDialog_142890_Content_15 = {
    Text = "<Red:Encore ça.>"
  },
  AvgDialog_142890_Content_16 = {
    Text = "<Shake:<Red:Grinc... muh, glouglou, grou...>>"
  },
  AvgDialog_142890_Content_17 = {
    Text = "Les quatre murs tremblent, tout s'écoule en gouttes dans un mucus humide."
  },
  AvgDialog_142890_Content_18 = {
    Text = "Même si je vous ai extrait, la vieillesse vous fera quand même dire ces <Red:sottises pitoyables>, tout comme Leisha."
  },
  AvgDialog_142890_Content_19 = {
    Text = "Vous ressentez soudainement qu'il <Red:n'est plus> Pontos."
  },
  AvgDialog_142890_Content_2 = {
    Text = "En regardant cette main familière et chaleureuse, vous avez finalement — reculé d'un pas."
  },
  AvgDialog_142890_Content_20 = {
    Text = "Devant vous se tient un être si ancien qu'il en a été oublié — vaste, majestueux, impossible à regarder en face. Une peur profonde et glaciale vous fige sur place et vous arrache un cri silencieux."
  },
  AvgDialog_142890_Content_21 = {
    Text = "ABYSSABYSSABYSSABYSSABYSSABYSSABYSSABYSS\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1\n@1B@1S@2Y@2@2y@1sa@1y@2@4@2Y@1\na@1y@2A@4ss@2ysssssAb@3abyss@2@3\n厄@2@3波@1@3厄@2yssSS@2YA@4\n@1B@1S@2Y@2@2y@1sa@1y@2@4@2Y@1\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1\n@1@2@3扬@1@3斯@2y!!ab@2YA@4\nABYssABySSabySSAByssabYSSa@2SAByssabyssABYSS@2\nABYSSABYSSABYSS@4@3SSABYSS@2@3\n@3@2@4@3@1@3@3!!!!!!!\na@1y@2A@4ss@2ysssssAb@3abyss@2@3\n@3@4YssAby!!!!!!!ABYSSABYSSABy@1\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1@1\n@1B@1S@2Y@2@2y@1sa@1y@2@4<Red:!!!!!!>"
  },
  AvgDialog_142890_Content_22 = {
    Text = "Tu te souvenais — ce son, quand tu es arrivé à Ebwynnos, quand tu as quitté Ebwynnos, quand tu es revenu à Ebwynnos."
  },
  AvgDialog_142890_Content_23 = {
    Text = "Peau, côtes, se décollant vers l'extérieur, se déployant, et puis..."
  },
  AvgDialog_142890_Content_24 = {
    Text = [[
Le vide, d'innombrables mains, le vide, le vide, le vide, le vide, le vide, @2y@2, @4@4@2@4
@3@2@4@3@1@3@3 !!!!!!]]
  },
  AvgDialog_142890_Content_25 = {
    Text = "Reste ici, reste à Ebwynnos."
  },
  AvgDialog_142890_Content_26 = {
    Text = "<Change>Écouter l'abîme, se jeter dans l'abîme."
  },
  AvgDialog_142890_Content_27 = {Text = "Lune."},
  AvgDialog_142890_Content_28 = {
    Text = "La Lune éclatante de blancheur, suspendue au loin dans un ciel distant."
  },
  AvgDialog_142890_Content_29 = {
    Text = "Ses côtes sa peau ses bras sa poitrine ses bras qui enlacent\nSes bras qui enlacent ses bras qui enlacent ses bras qui enlacent ses bras qui enlacent ses bras qui enlacent\nSes bras qui enlacent ses bras qui enlacent ses bras qui enlacent ses bras qui enlacent ses bras qui enlacent\nEb@3@4wynnos@3@2\nEbwyn@4@3@2nos@4@3@2\nSon étreinte ses côtes sa peau ses bras sa poitrine\nPour toujours pour toujours pour toujours pour toujours pour toujours pour toujours pour toujours\nPour toujours pour toujours pour toujours pour toujours pour toujours pour toujours pour toujours <Red:Ebwynnos>"
  },
  AvgDialog_142890_Content_3 = {
    Text = "...Si, il y en a."
  },
  AvgDialog_142890_Content_30 = {
    Text = "<Red:Ebwynnos dans ses bras ouverts.>"
  },
  AvgDialog_142890_Content_31 = {
    Text = "Des ailes superposées en couches infinies, enveloppant en leur sein une étreinte dense et inébranlable, une absorption à laquelle rien ne peut résister."
  },
  AvgDialog_142890_Content_32 = {
    Text = "Tu es bousculée, tu es enveloppée, tu es accueillie, tu tombes dans un calme sans fin."
  },
  AvgDialog_142890_Content_33 = {Text = "Arrête !"},
  AvgDialog_142890_Content_34 = {
    Text = "Une silhouette fendit avec force la foule glaciale et ignorante, se précipitant vers le tourbillon de <Red:« Pontos »>."
  },
  AvgDialog_142890_Content_35 = {
    Text = "Sans causer aucun dommage, mais avec une stupeur on ne peut plus évidente, les pupilles de <Red:« Pontos »> tressaillirent, fixant son visage avec intensité."
  },
  AvgDialog_142890_Content_36 = {
    Text = "J'avais toujours cru... que je n'avais fait que remodeler une Coquille vide."
  },
  AvgDialog_142890_Content_37 = {
    Text = "Tout comme les choses que Jago a oubliées mais qui continuent de l'influencer, une partie de moi existe encore."
  },
  AvgDialog_142890_Content_38 = {
    Text = "Laisse-le partir, Pontos, il n'est pas à sa place ici."
  },
  AvgDialog_142890_Content_39 = {
    Text = "Oh, Leisha."
  },
  AvgDialog_142890_Content_4 = {Text = "Quoi ?"},
  AvgDialog_142890_Content_40 = {
    Text = "Je l'aime, comme toi tu l'aimes."
  },
  AvgDialog_142890_Content_41 = {
    Text = "Orney, White."
  },
  AvgDialog_142890_Content_42 = {
    Text = "Tous les habitants d'Ebwynnos."
  },
  AvgDialog_142890_Content_43 = {
    Text = "Ils s'approchent de toi en silence, aux côtés du cauchemar, tels un mur qui se referme et t'écrase."
  },
  AvgDialog_142890_Content_44 = {
    Text = "Non, non non non ! Non !!"
  },
  AvgDialog_142890_Content_45 = {
    Text = "Leisha te regarde, regarde Jago, et regarde aussi... toi."
  },
  AvgDialog_142890_Content_46 = {
    Text = "Je sais pourquoi tu les veux tant. Il n'y a pas que Jago là-dedans, il y a plus d'une âme."
  },
  AvgDialog_142890_Content_47 = {
    Text = "Ah... ils oublieront tout, ils resteront ici."
  },
  AvgDialog_142890_Content_48 = {
    Text = "Leisha est à nouveau piégée. Elle tord son corps de toutes ses forces et vous fixe du regard—non pas votre visage, mais à travers lui, comme si elle cherchait à voir au plus profond de votre âme."
  },
  AvgDialog_142890_Content_49 = {
    Text = "S'il vous plaît. Qui que vous soyez — je sais que vous êtes là. Ramenez Jago. \nRamenez-le à la vie que vous étiez censés vivre !"
  },
  AvgDialog_142890_Content_5 = {
    Text = "Comme s'il n'avait pas compris ta question, il fronce légèrement les sourcils, incrédule."
  },
  AvgDialog_142890_Content_50 = {
    Text = "Des membranes noires et denses se déploient. Tout cela est si calme, si... envoûtant, que tu es presque sur le point de t'avancer vers Eux."
  },
  AvgDialog_142890_Content_51 = {
    Text = "Puis vous entendîtes... la voix de <Red:« Vous »>."
  },
  AvgDialog_142890_Content_52 = {
    Text = "Je crois que <Red:« Je »> ai déjà fait mon choix."
  },
  AvgDialog_142890_Content_53 = {
    Text = "Des profondeurs de la mer de la conscience, un esprit se débat pour s'en échapper."
  },
  AvgDialog_142890_Content_54 = {
    Text = "Ayant survécu à la grande explosion d'Akute, « Vous », en tant que <Red:« Gardien de Mizag »>, avez pris possession de ce corps."
  },
  AvgDialog_142890_Content_55 = {
    Text = "Une radiance d'Argent vacilla dans ta paume."
  },
  AvgDialog_142890_Content_56 = {
    Text = "Les souvenirs épars de Jago sont rassemblés, pièce par pièce."
  },
  AvgDialog_142890_Content_57 = {
    Text = "Vous savez, oncle Pontos... la première chose dont je viens de me souvenir était quelque chose de si infime. Quelque chose qui n'aurait pas dû avoir d'importance du tout."
  },
  AvgDialog_142890_Content_58 = {Text = "新增"},
  AvgDialog_142890_Content_59 = {
    Text = "« Pontos » ne parle pas. Il vous observe en silence."
  },
  AvgDialog_142890_Content_6 = {
    Text = "Elles ont un sens, ces souvenirs."
  },
  AvgDialog_142890_Content_60 = {
    Text = "Quand « Je » ai eu dix-huit ans, Orney et moi nous sommes faufilés à bord du vapeur le plus proche et avons supplié les marins de nous laisser travailler sur le pont inférieur en échange du passage. Une croisière gratuite, comme ça."
  },
  AvgDialog_142890_Content_61 = {
    Text = "Le lendemain matin, nous avons vu le plus beau lever de soleil que l'un ou l'autre d'entre nous ait jamais vu. Orney a dit qu'il souhaitait que le soleil ne se couche jamais. Mais pas moi."
  },
  AvgDialog_142890_Content_62 = {
    Text = "Parce que le soleil se couche bel et bien. Parce que chaque jour se termine. C'est ce qui donne un sens aux choses que nous traversons."
  },
  AvgDialog_142890_Content_63 = {
    Text = "Assez de ces sottises. À Ebwynnos, je peux faire lever et coucher le soleil à votre guise, si c'est ce que vous désirez."
  },
  AvgDialog_142890_Content_64 = {
    Text = "Il ferme les yeux, épuisé, sa patience enfin à bout. Vous secouez fermement la tête."
  },
  AvgDialog_142890_Content_65 = {
    Text = "Ce qui compte, c'est le temps que nous traversons. Pas un soleil qui reste là pour toujours."
  },
  AvgDialog_142890_Content_66 = {
    Text = "Désolé, Pontos."
  },
  AvgDialog_142890_Content_67 = {
    Text = "Il lève la main. Le mur de Thrall-Décharnés se resserre autour de vous."
  },
  AvgDialog_142890_Content_68 = {
    Text = "Allez, mes serviteurs."
  },
  AvgDialog_142890_Content_7 = {
    Text = "Pas pour les autres, mais pour moi-même."
  },
  AvgDialog_142890_Content_8 = {
    Text = "Je veux savoir quelle vie j'ai vécue — après avoir perdu la mémoire, pourquoi toute joie me laisse un sentiment de manque."
  },
  AvgDialog_142890_Content_9 = {
    Text = "Les épines de la sauterelle piquent légèrement le bout de tes doigts, et tu penses sans raison à la silhouette de cet enfant qui pleurait au bord du lit."
  },
  AvgDialog_142891_Content_1 = {
    Text = "Secret de Famille"
  },
  AvgDialog_142891_Content_10 = {
    Text = "Elle s'appelle — hm, elle s'appelle Vera, parce que c'est grand-père qui a choisi ce nom, et c'est le plus beau des noms."
  },
  AvgDialog_142891_Content_100 = {
    Text = "Sa colère vous consumera, seul le Plaisir peut... @1 !"
  },
  AvgDialog_142891_Content_101 = {Text = "Pfft."},
  AvgDialog_142891_Content_102 = {
    Text = "Du Sang gicla, et vous regardâtes, stupéfait, Leisha et plusieurs habitués de l'auberge se battre à dos des mêmes créatures que vous montiez."
  },
  AvgDialog_142891_Content_103 = {
    Text = "Pourquoi ces maudites créatures ont-elles débarqué ici...\nBah, c'était sûrement la dernière."
  },
  AvgDialog_142891_Content_104 = {
    Text = "Espérons qu'ils ne font que passer..."
  },
  AvgDialog_142891_Content_105 = {
    Text = "Leisha et ses compagnons partirent. Vous et Pontos restiez dans l'ombre. Vous vous seriez effondré sur le sol s'il n'avait pas tenu vos épaules."
  },
  AvgDialog_142891_Content_106 = {
    Text = "Vous vous accrochátes au bas de ses vêtements. Sa voix était calme et douce, comme s'il faisait de son mieux pour ne pas vous effrayer davantage."
  },
  AvgDialog_142891_Content_107 = {
    Text = "Jago, c'est exactement ce que vous avez vu... ces créatures qui nous ont portés ici à l'instant, elles s'appellent des Thrall-Décharnés. Nous les menons au combat pour nous."
  },
  AvgDialog_142891_Content_108 = {
    Text = "Il marqua une pause, sa main posée contre le flanc du Thrall-Décharné, faisant craquer ses articulations, comme s'il hésitait sur la façon d'expliquer."
  },
  AvgDialog_142891_Content_109 = {
    Text = "Eh bien, nous sommes les héros d'une histoire d'aventure — ceux qui apprivoisent les dragons, sauf que nous, nous apprivoisons ces Thrall-Décharnés."
  },
  AvgDialog_142891_Content_11 = {
    Text = "Vera... Grand-père a besoin de Repos, viens voir papa."
  },
  AvgDialog_142891_Content_110 = {
    Text = "Q-quoi... De quoi parlez-vous, oncle Pontos ?! Notre famille tient juste une auberge..."
  },
  AvgDialog_142891_Content_111 = {
    Text = "Après... après l'accident, il ne restait plus beaucoup d'entre nous. Leisha a fait beaucoup pour tout le monde, et les gens se sont appuyés sur elle."
  },
  AvgDialog_142891_Content_112 = {
    Text = "Mais elle ne voulait pas que nous, et surtout vous, ayons quoi que ce soit à voir avec tout cela. Cette vie tranquille et anonyme est exactement celle qu'elle voulait pour nous."
  },
  AvgDialog_142891_Content_113 = {
    Text = "Mais il y a encore tant de choses mauvaises et laides dans ce monde, comme celles que vous avez vues aujourd'hui. Je ne comprends pas..."
  },
  AvgDialog_142891_Content_114 = {
    Text = "Une lueur de frustration traversa le visage de Pontos — chose rare pour lui — et il repoussa ses cheveux dorés et détachés de son front vers l'arrière de sa tête."
  },
  AvgDialog_142891_Content_115 = {
    Text = "Dernièrement, les Thrall-Décharnés m'ont trouvé. Et je peux sentir quelque chose de bien plus puissant derrière eux. Il m'a choisi, Il m'appelle."
  },
  AvgDialog_142891_Content_116 = {
    Text = "Je pourrais faire tellement plus. Mais Leisha pense que tant que nous nous cachons bien, tout ira bien."
  },
  AvgDialog_142891_Content_117 = {
    Text = "Le poids de tout cela vous laissa à cligner des yeux, hébété. Pour la première fois, vous connaissiez chaque mot et ne parveniez toujours pas à donner un sens à l'ensemble."
  },
  AvgDialog_142891_Content_118 = {
    Text = "Pontos sembla se reprendre, revint au moment présent, et vous adressa un sourire."
  },
  AvgDialog_142891_Content_119 = {
    Text = "Désolé, Jago. Vous ai-je trop accablé d'un coup ?"
  },
  AvgDialog_142891_Content_12 = {
    Text = "Ton fils s'inquiète un peu pour ta santé et veut emmener ta petite-fille, elle fait la moue, sur le point d'éclater en sanglots."
  },
  AvgDialog_142891_Content_120 = {
    Text = "Rentrons avant que Leisha découvre que nous nous sommes esquivés. Nous aurons tout le temps du monde pour en parler."
  },
  AvgDialog_142891_Content_121 = {
    Text = "Au loin, Leisha sembla jeter un coup d'œil dans votre direction. L'oncle Pontos vous fit à nouveau le geste de <Italic:chut>."
  },
  AvgDialog_142891_Content_122 = {Text = "新增"},
  AvgDialog_142891_Content_123 = {
    Text = "La fenêtre s'ouvrit et se referma, sans un bruit."
  },
  AvgDialog_142891_Content_124 = {
    Text = "Comme si le vent avait simplement fait s'ouvrir la fenêtre. Dehors, les vagues s'écrasaient puis se retiraient. Vous avez entendu le bruit de Leisha montant les escaliers depuis le rez-de-chaussée."
  },
  AvgDialog_142891_Content_125 = {
    Text = "Vous enfouissez vos visages dans les oreillers, respirant calmement, faisant comme si c'était encore une nuit ordinaire."
  },
  AvgDialog_142891_Content_13 = {
    Text = "Vous souriez en toussant quelques fois, faisant un effort pour redresser cette Fragile carcasse, appuyé contre la tête du lit."
  },
  AvgDialog_142891_Content_14 = {
    Text = "Vera, ne pleure pas. Le clair de lune est si beau dehors, baisse un peu la lumière."
  },
  AvgDialog_142891_Content_15 = {
    Text = "Grand-père a encore le temps de te raconter une histoire, laisse-moi réfléchir..."
  },
  AvgDialog_142891_Content_16 = {
    Text = "Votre regard se pose sur la boussole en laiton qui ne vous a jamais quitté. Intacte par les années, elle arbore un doux liseré argenté dans le clair de lune."
  },
  AvgDialog_142891_Content_17 = {
    Text = "Vous faites lentement glisser votre pouce sur sa surface, plein de nostalgie, et votre voix se fait rauque tandis que vous vous enfoncez dans vos souvenirs."
  },
  AvgDialog_142891_Content_18 = {
    Text = "C'était... il y a plus de soixante ans, quand j'étais encore un enfant."
  },
  AvgDialog_142891_Content_19 = {
    Text = "Leisha, le navire est sur le point de quitter le port. Il n'est toujours pas revenu?"
  },
  AvgDialog_142891_Content_2 = {Text = "Lune."},
  AvgDialog_142891_Content_20 = {
    Text = "On dirait qu'on ne pourra vraiment pas se dire au revoir en personne. Prends au moins cette broche, s'il te plaît..."
  },
  AvgDialog_142891_Content_21 = {
    Text = "Le sifflet du port retentit. Les propriétaires des babioles laissèrent derrière eux un tas cliquetant de bijoux personnels, le visage empli de regret, avant de retourner au navire."
  },
  AvgDialog_142891_Content_22 = {
    Text = "Mon Dieu, pour l'amour de @3, ma chérie, quand est-ce que ton oncle va enfin apprendre à ne pas avoir autant d'«amis» ?"
  },
  AvgDialog_142891_Content_23 = {
    Text = "Ta mère Leisha te regarda avec une expression à la fois amusée et désemparée, soupira, et fourra les bijoux dans la petite boîte qui serait rendue au capitaine pour livraison la prochaine fois que le navire accosterait."
  },
  AvgDialog_142891_Content_24 = {
    Text = "Ta famille tenait une petite auberge tout à fait ordinaire dans une ville côtière. Une seule chose était un peu spéciale..."
  },
  AvgDialog_142891_Content_25 = {
    Text = "Voyons voir qui est ce beau petit bonhomme—"
  },
  AvgDialog_142891_Content_26 = {
    Text = "La grande Porte s'ouvre à nouveau sur un vent chargé de sel, et «cette chose particulière» éclate de rire en te saisissant à bras-le-corps pour te faire tournoyer dans les airs."
  },
  AvgDialog_142891_Content_27 = {
    Text = "Pontos! Combien de fois t'ai–je dit que tu allais lui arracher les bras!"
  },
  AvgDialog_142891_Content_28 = {
    Text = "Oncle Pontos!"
  },
  AvgDialog_142891_Content_29 = {
    Text = "Hé, petit Jago, regarde ce que je t'ai rapporté!"
  },
  AvgDialog_142891_Content_3 = {
    Text = "La pleine lune la plus brillante que vous ayez jamais vue est suspendue dans le ciel. Vos membres sont Affaiblir et sans force, et votre esprit est quelque peu engourdi."
  },
  AvgDialog_142891_Content_30 = {
    Text = "Il claqua des doigts, ouvrit sa main en l'air, et une lourde boussole plaquée de cuivre tomba dans ta paume."
  },
  AvgDialog_142891_Content_31 = {
    Text = "J'espère que tu as obtenu ça honnêtement. Cette maison ne peut plus accueillir de «gages d'amour» et de «cœurs brisés»."
  },
  AvgDialog_142891_Content_32 = {
    Text = "Leisha lui relança la boîte à bijoux avec un sourire narquois et inclina le menton vers la fenêtre, par laquelle le navire emportant l'autre moitié de ces «cœurs brisés» venait de quitter le port."
  },
  AvgDialog_142891_Content_33 = {
    Text = "Allez... tu me connais. Je n'ai jamais su dire non."
  },
  AvgDialog_142891_Content_34 = {
    Text = "Souriant, Pontos inclina la tête et esquiva une gifle vigoureuse de Leisha, puis vous posa à terre."
  },
  AvgDialog_142891_Content_35 = {
    Text = "Au fait, je me suis fait de nouveaux amis. Il faudrait qu'on parle, Leisha."
  },
  AvgDialog_142891_Content_36 = {
    Text = "Des choses dont tu ne veux pas parler."
  },
  AvgDialog_142891_Content_37 = {
    Text = "Trop occupé à examiner votre nouveau trésor, vous ne remarquâtes pas l'expression assombrie de Leisha. Pontos vous ébouriffa les cheveux."
  },
  AvgDialog_142891_Content_38 = {
    Text = "Ta mère et moi avons quelques choses à nous dire. Si mon jeune homme préféré accepte de monter jouer un moment, je lui raconterai de merveilleuses histoires de mes voyages. Marché conclu ?"
  },
  AvgDialog_142891_Content_39 = {
    Text = "Il tendit la main, et pour la boussole vous la prîtes — c'était la «Poignée de main du marché» qui n'appartenait qu'à vous deux."
  },
  AvgDialog_142891_Content_4 = {
    Text = "En levant la main, vous constatez que des rides, symboles de vieillesse, ont déjà envahi votre peau."
  },
  AvgDialog_142891_Content_40 = {Text = "新增"},
  AvgDialog_142891_Content_41 = {
    Text = "Allongé sur le sol de la chambre à l'étage, vous sortîtes une carte et vous mîtes, avec grande concentration, à utiliser la boussole pour retrouver les caps de ces récits de marins."
  },
  AvgDialog_142891_Content_42 = {
    Text = "Cependant, cette maison était trop vieille, et l'océan et le vent l'usaient sans cesse. Quelques mots épars parvenaient encore à monter à travers les interstices du plancher."
  },
  AvgDialog_142891_Content_43 = {
    Text = "...déjà... dire... on peut pas juste... se cacher n'est pas une solution."
  },
  AvgDialog_142891_Content_44 = {
    Text = "...Ces <Italic:êtres>... je peux... Mon talent..."
  },
  AvgDialog_142891_Content_45 = {
    Text = "Le ton d'oncle Pontos se faisait de plus en plus pressant. Alors que tu t'apprêtais à coller ton oreille plus près par curiosité—"
  },
  AvgDialog_142891_Content_46 = {
    Text = "CRAC! BOUM!"
  },
  AvgDialog_142891_Content_47 = {
    Text = "La Porte s'ouvrit avec fracas, Pontos fut jeté à l'intérieur par le col, Leisha arborant une expression signifiant «pas question de discuter»."
  },
  AvgDialog_142891_Content_48 = {
    Text = "Je ne suis pas d'accord, Pontos. Mon seul souhait est que vous restiez tous sains et saufs... Éloigne–toi de tes nouveaux amis."
  },
  AvgDialog_142891_Content_49 = {
    Text = "Si les choses deviennent vraiment incontrôlables, je vous emmènerai tous loin d'ici."
  },
  AvgDialog_142891_Content_5 = {
    Text = "Ah, je réalise que j'ai atteint cet âge... Ce soir est peut-être le dernier."
  },
  AvgDialog_142891_Content_50 = {
    Text = "Hé, Leisha, je ne suis plus un gamin ! On ne peut pas continuer à fuir éternellement."
  },
  AvgDialog_142891_Content_51 = {
    Text = "Apprends d'abord à m'aider à gérer le commerce. Arrête de traîner dehors toute la journée avant de parler de ça."
  },
  AvgDialog_142891_Content_52 = {
    Text = "Vous aviez rarement entendu Leisha parler avec une telle dureté. Elle prit une inspiration et vous adressa un sourire forcé."
  },
  AvgDialog_142891_Content_53 = {
    Text = "Jago, rends service à maman. Surveille ton oncle, au moins cette nuit, ne le laisse plus traîner dehors."
  },
  AvgDialog_142891_Content_54 = {
    Text = "Elle laissa ces mots derrière elle et se dépêcha de descendre retrouver les livres de comptes qui ne semblaient jamais finir, comme si elle avait hâte de mettre fin à la conversation au plus vite."
  },
  AvgDialog_142891_Content_55 = {
    Text = "Pontos haussa un sourcil et vous fit un haussement d'épaules."
  },
  AvgDialog_142891_Content_56 = {
    Text = "Eh bien, Jago, on dirait qu'on peut avancer un petit peu l'heure des histoires."
  },
  AvgDialog_142891_Content_57 = {Text = "新增"},
  AvgDialog_142891_Content_58 = {
    Text = "Peut–être que ces récits qui s'échappaient des cabines de navires avec la cargaison étaient trop palpitants et fantastiques. Même à minuit, tu ne dormais pas profondément."
  },
  AvgDialog_142891_Content_59 = {
    Text = "Le clair de lune derrière la fenêtre projetait un éclat argenté sur tes paupières. Quelque chose le bloqua."
  },
  AvgDialog_142891_Content_6 = {
    Text = "Les souvenirs reviennent peu à peu, mais étrangement, il n›y a aucune Peur de la mort dans votre cœur. Au contraire, vous souriez, empli d›une paix intérieure profonde."
  },
  AvgDialog_142891_Content_60 = {
    Text = "Un clic — le loquet de la fenêtre. Vous ouvrîtes les yeux. La fenêtre avait déjà été grande ouverte."
  },
  AvgDialog_142891_Content_61 = {Text = "!"},
  AvgDialog_142891_Content_62 = {
    Text = "Oncle Pontos, tu ne peux pas sortir par la fenêtre ! Maman va se fâcher !"
  },
  AvgDialog_142891_Content_63 = {
    Text = "Pontos était à moitié sorti par le rebord de la fenêtre, Vous vous élancez sans réfléchir pour le rattraper, oubliant même de vous demander pourquoi il semblait... suspendu dans les airs."
  },
  AvgDialog_142891_Content_64 = {
    Text = "Attends, fais attention !"
  },
  AvgDialog_142891_Content_65 = {
    Text = "Une sensation d'apesanteur s'empara de Vous, puis —"
  },
  AvgDialog_142891_Content_66 = {Text = "WHOOSH !"},
  AvgDialog_142891_Content_67 = {
    Text = "Crrrrac— !"
  },
  AvgDialog_142891_Content_69 = {
    Text = "...! ...!!!!"
  },
  AvgDialog_142891_Content_7 = {
    Text = "Tes proches se pressent autour de toi, la plus jeune de tes petites-filles, Vera, ne comprend pas encore ce qui se passe et se blottit affectueusement contre ta main."
  },
  AvgDialog_142891_Content_70 = {
    Text = "Tu fus soulevé par le tissu à ta taille, l'étrange sensation d'une fourrure lisse effleurant ton visage."
  },
  AvgDialog_142891_Content_71 = {
    Text = "Quand vous ouvrîtes les yeux, un frisson d'horreur vous parcourut l'échine."
  },
  AvgDialog_142891_Content_72 = {Text = "Pon—"},
  AvgDialog_142891_Content_73 = {
    Text = "La queue d'une créature informe et innommable était accrochée dans votre dos, sa pointe grouillant d'horribles crochets."
  },
  AvgDialog_142891_Content_74 = {
    Text = "Vous n'eûtes pas le temps de réaliser que cette chose terrifiante venait manifestement de vous sauver — irrépressiblement, un cri étouffé vous monta à la gorge."
  },
  AvgDialog_142891_Content_75 = {Text = "Chut !"},
  AvgDialog_142891_Content_76 = {
    Text = "Pontos, allongé sur cette créature sans visage, Vous saisit et Vous hissa sur elle, couvrant fermement votre bouche de sa main ; la créature déploya ses immenses ailes semblables à celles d'une chauve-souris et glissa silencieusement dans la nuit."
  },
  AvgDialog_142891_Content_77 = {
    Text = "N'ayez pas peur. Ils ne vous feront pas de mal."
  },
  AvgDialog_142891_Content_78 = {
    Text = "Il n'y a pas de temps, Jago. Restez silencieux — je vous expliquerai tout plus tard."
  },
  AvgDialog_142891_Content_79 = {
    Text = "Pontos passa un bras autour de vos épaules pour vous réconforter, vous plaçant entre lui et la créature, son corps abaissé, les yeux fixés sur les récifs rocheux dans un coin reculé du port."
  },
  AvgDialog_142891_Content_8 = {
    Text = "Grand-père, quand pourras-tu rejouer avec moi ? Regarde, j'ai déjà appris ce que tu m'as enseigné la dernière fois."
  },
  AvgDialog_142891_Content_80 = {
    Text = "Avant que vous puissiez poser la moindre question, un son sinistre s'éleva de la mer, comme des vers rampant à la surface."
  },
  AvgDialog_142891_Content_81 = {
    Text = "<Shake:<Red:Frou-frou, frou-frou...>>"
  },
  AvgDialog_142891_Content_82 = {
    Text = "<Shake:<Red:Splatch, splatch... Plouf —>>"
  },
  AvgDialog_142891_Content_83 = {
    Text = "!... Urgh..."
  },
  AvgDialog_142891_Content_84 = {
    Text = "D›abord vinrent des pieds griffus couverts d›écailles, puis des bras — ou peut–être de souples membres d›arthropodes tordus — des corps incrustés de bernacles et une vase blasphématoirement abominable..."
  },
  AvgDialog_142891_Content_85 = {
    Text = "Vous ne connaissiez la mer que comme une source inépuisable de nourriture. Vous n'auriez jamais imaginé qu'elle pût aussi abriter de telles abominations. Leurs yeux globuleux et terrifiants étaient emplis de malveillance tandis qu'ils fixaient les bâtiments de la ville."
  },
  AvgDialog_142891_Content_86 = {
    Text = "<Change>@4Tipu... partout où il passe..."
  },
  AvgDialog_142891_Content_87 = {
    Text = "<Change>... doit traverser ce lieu... nourrir la Dissolution, s'abandonner à la Dissolution ! De la chair, de la chair !!"
  },
  AvgDialog_142891_Content_88 = {
    Text = "<Small:<Shake:Tonton, un mon... un monstre !!>>"
  },
  AvgDialog_142891_Content_89 = {
    Text = "La seconde suivante, la créature ailée sans visage sous vous plongea vers le sol. Pontos écarta ses doigts osseux, et une lumière obscure déferla vers les deux monstres misérables."
  },
  AvgDialog_142891_Content_9 = {
    Text = "Elle tient dans ses mains une sauterelle en herbe toute de travers et la pose sur la couverture."
  },
  AvgDialog_142891_Content_90 = {
    Text = "Ngh, mmph !"
  },
  AvgDialog_142891_Content_91 = {
    Text = "Ils s›effondrèrent sans vie au sol, comme deux statues de pierre tranchées."
  },
  AvgDialog_142891_Content_92 = {
    Text = "Tap — un contact léger."
  },
  AvgDialog_142891_Content_93 = {
    Text = "Puis les deux moitiés du corps s'abattirent sur le sol, se dissolvant en une fine poussière grise emportée par le vent marin."
  },
  AvgDialog_142891_Content_94 = {
    Text = "Pfff, je savais bien qu'il y aurait toujours un ou deux qui passeraient à travers les mailles du filet, Leisha et les autres sont vraiment trop négligents."
  },
  AvgDialog_142891_Content_95 = {
    Text = "<Shake:Maman et les autres ? Oncle Pontos, qu'est-ce qui se passe au juste ?!>"
  },
  AvgDialog_142891_Content_96 = {
    Text = "La frayeur faillit vous faire fléchir les jambes, et vous avez failli glisser du dos lisse de la créature."
  },
  AvgDialog_142891_Content_97 = {
    Text = "Tenez encore un peu. Je dois d'abord m'assurer qu'ils vont bien."
  },
  AvgDialog_142891_Content_98 = {
    Text = "Pontos vous tapota l'épaule, puis guida la créature pour vous porter tous les deux vers le littoral de l'autre côté de la ville."
  },
  AvgDialog_142891_Content_99 = {Text = "新增"},
  AvgDialog_142892_Content_1 = {
    Text = "Quand Tu Étais Parti"
  },
  AvgDialog_142892_Content_10 = {
    Text = "Du sable jaune."
  },
  AvgDialog_142892_Content_11 = {
    Text = "Des Champs de neige."
  },
  AvgDialog_142892_Content_12 = {Text = "Le vide."},
  AvgDialog_142892_Content_13 = {
    Text = "Et puis retour à la nuit."
  },
  AvgDialog_142892_Content_14 = {
    Text = "Ce n›est ni un voyage ni une trajectoire que les humains peuvent comprendre. Le temps et l›espace ont perdu tout sens. Vous ne cessez de traverser, de patrouiller. Vous faites l›expérience de tout, puis êtes détruit par tout."
  },
  AvgDialog_142892_Content_15 = {
    Text = "Puisqu›Ils ont osé s›introduire, bannissez-Les du monde des mortels!! Faites-Leur craindre notre nom!! Faites-Leur se souvenir de mon nom!!"
  },
  AvgDialog_142892_Content_16 = {
    Text = "Pontos dépense sans retenue le pouvoir qu›il a acquis, et les êtres qui l›ont gagné déchirent désormais ses ennemis également."
  },
  AvgDialog_142892_Content_17 = {
    Text = "D›innombrables monstres tordus et répugnants sont traqués par les Thrall-Décharnés et les Gardiens-Décharnés."
  },
  AvgDialog_142892_Content_18 = {
    Text = "Ils sont transpercés, intégrés aux festivités, suscitant des sifflements et des rires de célébration sans fin."
  },
  AvgDialog_142892_Content_19 = {
    Text = "Non, non, pas encore, nonnononnonnon!!!!!!"
  },
  AvgDialog_142892_Content_2 = {
    Text = "L›étrange sensation d›une fourrure lisse, le dard acéré au bout de sa queue, d›immenses ailes membraneuses fendant silencieusement le ciel nocturne."
  },
  AvgDialog_142892_Content_20 = {
    Text = "Vous avez vu de vos propres yeux le rayon que Pontos a déchaîné réduire le fanatique en poussière, mais aussitôt après, Leur corps s›est reconstitué une fois de plus, un hurlement de Peur jaillissant de Leur bouche."
  },
  AvgDialog_142892_Content_21 = {
    Text = "C›était le plus fervent de tous les cultistes. Et il a déjà enduré la mort et la reconstitution dans l›agonie, plus de fois que quiconque pourrait les compter."
  },
  AvgDialog_142892_Content_22 = {
    Text = "Oncle Pontos, cette... <Italic:chose>... est en train de revenir à la vie ?"
  },
  AvgDialog_142892_Content_23 = {
    Text = "Non. Il meurt et revient simplement, encore et encore, pour goûter à la souffrance qui lui avait été promise."
  },
  AvgDialog_142892_Content_24 = {
    Text = "Parfois, je les laisse mourir, à condition qu›ils renoncent à leur dévotion envers ces dieux blasphématoires et immondes."
  },
  AvgDialog_142892_Content_25 = {
    Text = "Mais si leur foi est trop inébranlable, alors même la mort ne peut les délivrer de la souffrance."
  },
  AvgDialog_142892_Content_26 = {
    Text = "Parlant avec autant de désinvolture que s›il s›agissait d›une broutille, Pontos leva la paume. Une force invisible écarta les bras du fanatique, courba son buste vers l›avant et le força à s›agenouiller, prosterné devant Pontos."
  },
  AvgDialog_142892_Content_27 = {
    Text = "Maintenant, dis-moi encore une fois — vénères-tu toujours ton dieu immonde?"
  },
  AvgDialog_142892_Content_28 = {
    Text = "<LightGray:*sanglots>Non... non, je vous en supplie, laissez-moi mourir, Tant Que vous me laissez mourir !"
  },
  AvgDialog_142892_Content_29 = {
    Text = "<Shake:Ha ha ha, ha ha ha ha ha ha, pas de sauveur, il n'y a absolument pas de sauveur, Seulement AB@2S, Seulement @2@3 !!>"
  },
  AvgDialog_142892_Content_3 = {
    Text = "Pontos vous emmène avec lui lors de la chasse qui précède les festivités nocturnes d›Ebwynnos."
  },
  AvgDialog_142892_Content_30 = {
    Text = "Très bien, proie. Lève la tête. Offre ta gorge."
  },
  AvgDialog_142892_Content_31 = {
    Text = "Le fanatique, l'esprit en crash, émet des sanglots distordus et des rires frénétiques, avance à genoux, relevant le cou dans une posture grotesque."
  },
  AvgDialog_142892_Content_32 = {
    Text = "Je vais t›accorder la mort."
  },
  AvgDialog_142892_Content_33 = {
    Text = "La lumière transperça Sa gorge comme un couteau chaud dans du beurre. Son corps s›effondra soudain en cendres et en poussière, emporté par le vent dans l›océan."
  },
  AvgDialog_142892_Content_34 = {
    Text = "Cette fois, le pitoyable cultiste ne revient pas."
  },
  AvgDialog_142892_Content_35 = {
    Text = "Où vont les autres ? Les monstres qui se font capturer ?"
  },
  AvgDialog_142892_Content_36 = {
    Text = "Ils sont dans Ebwynnos aussi."
  },
  AvgDialog_142892_Content_37 = {
    Text = "Un Ebwynnos tout aussi éternel, mais sans la joie."
  },
  AvgDialog_142892_Content_38 = {
    Text = "Là-bas, rien n›existe. Même la douleur serait considérée comme une grâce."
  },
  AvgDialog_142892_Content_39 = {
    Text = "Vous comprenez à moitié. Le clair de lune brille. Les Thrall-Décharnés vous gardent tandis que cet étrange voyage touche à sa fin."
  },
  AvgDialog_142892_Content_4 = {
    Text = "À travers d›innombrables médiums au-delà de toute compréhension, les gens d›Ebwynnos traquent leurs «proies» à travers d›innombrables dimensions."
  },
  AvgDialog_142892_Content_40 = {
    Text = "Ferme les yeux, Jago."
  },
  AvgDialog_142892_Content_41 = {
    Text = "Une obscurité humide, familière et intime t›enveloppa, t›engloutit tout entier."
  },
  AvgDialog_142892_Content_42 = {
    Text = "Tu retournas à la Grande Demeure. Pontos descendit du chariot, dévoilant le prélude d›une nouvelle festivité."
  },
  AvgDialog_142892_Content_43 = {
    Text = "Cet enfant semble s›être bien attaché à toi."
  },
  AvgDialog_142892_Content_44 = {
    Text = "Près du rebord de la fenêtre donnant sur la terrasse, Pontos se détourna de la foule animée et tendit la main vers le Cauchemar qui tournoyait à l›extérieur de la fenêtre."
  },
  AvgDialog_142892_Content_45 = {
    Text = "Je n›arrive pas à me souvenir clairement de beaucoup de choses pour une raison quelconque, mais... Oncle Pontos, tu n›es plus humain, et ce n›est plus le monde tel que je le connais, n›est–ce pas ?"
  },
  AvgDialog_142892_Content_46 = {
    Text = "Suis–je déjà mort ?"
  },
  AvgDialog_142892_Content_47 = {
    Text = "Ne s›attendant apparemment pas à ce que tu poses la question aussi directement, Pontos haussa les sourcils de surprise, puis — éclata de rire."
  },
  AvgDialog_142892_Content_48 = {
    Text = "Mon cher petit ami, bien sûr que non."
  },
  AvgDialog_142892_Content_49 = {
    Text = "Reste à Ebwynnos, et tu vivras la vie grandiose et extraordinaire dont tu rêvais en lisant des livres d›histoires quand tu étais enfant. Tu ne seras plus jamais usé par le monde."
  },
  AvgDialog_142892_Content_5 = {
    Text = "D›inquiétantes lueurs dansaient encore dans les vitres de la maison."
  },
  AvgDialog_142892_Content_50 = {
    Text = "Nous partirons à l›aventure, nous échapperons au monde ordinaire. Ces ennemis qui ont semé le chaos et le désastre dans nos vies seront finalement abattus jusqu›à ce qu›ils n›osent plus jamais montrer leur visage."
  },
  AvgDialog_142892_Content_51 = {
    Text = "Vous avez pris une profonde inspiration. Vous avez senti cette sauterelle à nouveau — grossière, rugueuse, légèrement piquante."
  },
  AvgDialog_142892_Content_52 = {
    Text = "Oui, tout cela semble merveilleux."
  },
  AvgDialog_142892_Content_53 = {
    Text = "Mais quel prix dois–je payer, Oncle Pontos ?"
  },
  AvgDialog_142892_Content_54 = {
    Text = "Son front se plissa avec une lenteur atroce, portant une sorte d›arrogance hautaine qui vous était inconnue."
  },
  AvgDialog_142892_Content_55 = {
    Text = "Le prix n'est que... quelque chose qui n'a aucune importance, quelque chose dont vous n'avez pas besoin et dont vous ne vous souviendrez pas. <Red:Donnez-le-moi>, Jago."
  },
  AvgDialog_142892_Content_56 = {
    Text = "À l›instant où il finit de parler, la queue barbelée du cauchemar descendit de l›extérieur de la fenêtre vers votre poche."
  },
  AvgDialog_142892_Content_57 = {
    Text = "Vers la sauterelle bancale que vous avez cachée."
  },
  AvgDialog_142892_Content_58 = {Text = "Non !"},
  AvgDialog_142892_Content_59 = {
    Text = "Vous avez instinctivement reculé en trébuchant, mais le mouvement sembla irriter Pontos, et il vous saisit le bras."
  },
  AvgDialog_142892_Content_6 = {
    Text = "Des Thrall-Décharnés tournoyaient dans les airs, jusqu›à ce que Pontos — debout à vos côtés dans un char qui irradiait d›un indescriptible éclat nacré — pousse un cri retentissant."
  },
  AvgDialog_142892_Content_60 = {
    Text = "Tu ne comprends tout simplement pas, enfant. Sais–tu combien d›efforts j›ai déployés pour te trouver..."
  },
  AvgDialog_142892_Content_61 = {
    Text = "Rou–rou, rou–rou..."
  },
  AvgDialog_142892_Content_62 = {
    Text = "Vous vous êtes figé sur place. Ce n›étaient pas seulement les doigts de Pontos pressés contre votre peau — une Peur sans nom vous a fait lever les yeux, et les pupilles bleu profond de Pontos pesaient lourdement sur vous."
  },
  AvgDialog_142892_Content_63 = {
    Text = "Puisque tu veux voir, alors regarde — exactement de quel genre de chose je t›ai sauvé."
  },
  AvgDialog_142892_Content_64 = {
    Text = "Vous êtes à nouveau <Red:englouti>."
  },
  AvgDialog_142892_Content_65 = {Text = "新增"},
  AvgDialog_142892_Content_66 = {
    Text = "Hé, hé, vieux camarade, tu as entendu ce que j›ai dit ? Tu es encore dans la lune ! Attention !"
  },
  AvgDialog_142892_Content_67 = {
    Text = "Splash ! De l›eau boueuse vous a frappé le visage, et vous êtes revenu à la réalité, fixant d›un regard vide la personne à côté de vous. Âgé, voûté, et bavardant sans fin — mais vous l›avez reconnu. C›était indubitablement un Orney âgé."
  },
  AvgDialog_142892_Content_68 = {
    Text = "Ces maudits Matelots, absolument incontrôlables ! Si vous voulez mon avis, tous ces voyages leur ont rendu le cœur sauvage. Ils sont incapables de se concentrer sur quoi que ce soit de concret !"
  },
  AvgDialog_142892_Content_69 = {
    Text = "Orney ? ...De quoi parles-tu ? Tu as toujours rêvé d'être marin quand on était enfants, de voir tous les continents !"
  },
  AvgDialog_142892_Content_7 = {
    Text = "Emparez-vous d›Eux, assurez-vous qu›Ils ne puissent plus jamais repartir, faites-Les souffrir ici pour l›éternité!!"
  },
  AvgDialog_142892_Content_70 = {
    Text = "J›ai vraiment dit quelque chose comme ça ? Ne sois pas ridicule. À notre âge, tu devrais savoir que la stabilité, c›est ce qu›il y a de mieux."
  },
  AvgDialog_142892_Content_71 = {
    Text = "Vous avez oublié, mon vieux, depuis la deuxième année d'université on ne parle plus de ça. On parle des nouvelles du journal, de ces maudits rapports un par un, des retraites, des repas de famille tous les quinze jours."
  },
  AvgDialog_142892_Content_72 = {
    Text = "Il vous a tapé sur l›épaule et a récupéré en tremblant deux sacs en papier au guichet de la pharmacie."
  },
  AvgDialog_142892_Content_73 = {
    Text = "Tu n'es pas comme moi ? Après avoir obtenu ton diplôme et être revenu ici, Dieu merci, on n'a même plus le courage de faire un long voyage."
  },
  AvgDialog_142892_Content_74 = {
    Text = "Cette maudite arthrite. Dieu merci — en dehors de toi et de ces analgésiques, il n'y a rien d'autre qui m'oblige à quitter la maison."
  },
  AvgDialog_142892_Content_75 = {
    Text = "La solitude, ha ! Quand on était jeunes, on pensait que c'était aussi réel que le monstre du Loch Ness."
  },
  AvgDialog_142892_Content_76 = {
    Text = "Orney continuait à parler de quelque chose. Tu fixais ses lèvres qui s'ouvraient et se fermaient, et une soudaine vague de vertige t'arracha à la routine banale."
  },
  AvgDialog_142892_Content_77 = {Text = "新增"},
  AvgDialog_142892_Content_78 = {
    Text = "Tu as vu ce que ces jours banals ont fait d'Orney ? Va regarder encore une fois — ce contre quoi tu as échangé."
  },
  AvgDialog_142892_Content_79 = {
    Text = "Tu te vois, allongé dans un lit, flétri et consumé."
  },
  AvgDialog_142892_Content_8 = {
    Text = "Des nuages."
  },
  AvgDialog_142892_Content_80 = {
    Text = "Bien sûr, ils seront tristes au début, ils verseront quelques larmes pour toi."
  },
  AvgDialog_142892_Content_81 = {
    Text = "Tu vois un couple et leur petite fille sortir se promener, se réconfortant mutuellement."
  },
  AvgDialog_142892_Content_82 = {
    Text = "Mais en une semaine, voire quelques jours, ils s'en remettront bien assez tôt."
  },
  AvgDialog_142892_Content_83 = {
    Text = "Des dîners, des promenades, l'université, qui sait ? Les enfants tiendront peut-être un peu plus longtemps. Pas beaucoup, bien sûr."
  },
  AvgDialog_142892_Content_84 = {
    Text = "Au bout du compte, il ne restera rien. Personne ne se souviendra de vous."
  },
  AvgDialog_142892_Content_85 = {
    Text = "Hiver, printemps, un autre hiver. Vous regardez la poussière se déposer lentement dans la maison."
  },
  AvgDialog_142892_Content_86 = {
    Text = "Tu comprends maintenant, Jago ? J'ai simplement amené les parties intéressantes de vous tous... les parties vibrantes... à Ebwynnos."
  },
  AvgDialog_142892_Content_87 = {
    Text = "Votre enveloppe corporelle est sur le point de mourir. Avec ou sans vous, tous ceux que vous avez jamais connus continueront de vivre leur propre vie, des vies qui n'ont rien à voir avec vous."
  },
  AvgDialog_142892_Content_88 = {
    Text = "La voix de Pontos résonne dans tes oreilles, et la seconde suivante, tu réapparais dans la grande salle de la Haute Demeure d'Ebwynnos."
  },
  AvgDialog_142892_Content_89 = {
    Text = "Maintenant, Jago, réfléchis — réfléchis bien. Abandonne cette enveloppe, débarrasse-toi de ces souvenirs insignifiants, et reste avec nous."
  },
  AvgDialog_142892_Content_9 = {
    Text = "Une terre anéantie."
  },
  AvgDialog_142892_Content_90 = {
    Text = "Orney, Oncle White, et tous ceux qui se pressent dans la salle de bal d'Ebwynnos semblent soudain remarquer quelque chose."
  },
  AvgDialog_142892_Content_91 = {
    Text = "Hé, pourquoi vous faites cette tête tous les deux ? On vient de remporter une grande victoire !"
  },
  AvgDialog_142892_Content_92 = {
    Text = "Allez, Jago, viens boire un bon coup avec nous. Il n'y a rien qui vaille la peine de s'inquiéter à Ebwynnos !"
  },
  AvgDialog_142892_Content_93 = {
    Text = "Ils rient de bon cœur, vous accueillant parmi eux."
  },
  AvgDialog_142892_Content_94 = {
    Text = "Les gens se passent maintenant leurs butins. Les marées résonnent à nouveau dans vos oreilles."
  },
  AvgDialog_142892_Content_95 = {
    Text = "Pontos tend la main, attendant que vous la preniez."
  },
  AvgDialog_142892_Content_96 = {
    Text = "Tout comme cette «poignée de main pour sceller un accord» que vous aviez convenue étant enfants."
  },
  AvgDialog_142893_Content_1 = {Text = "La Raison"},
  AvgDialog_142893_Content_10 = {
    Text = "<Red:Ce n'est pas censé se passer ainsi.>"
  },
  AvgDialog_142893_Content_11 = {
    Text = "Tu aurais dû découvrir ta lignée par accident, Maman aurait été convaincue par Oncle Pontos de te guider, et ensemble vous seriez partis en voyage, vivant toutes sortes d'aventures palpitantes, excitantes et merveilleuses."
  },
  AvgDialog_142893_Content_12 = {
    Text = "<Shake:Et puis tu deviendras un grand <Red:héros>, c'est comme ça que ça se passe dans les romans d'aventure.>"
  },
  AvgDialog_142893_Content_13 = {
    Text = "Jago ! Reprends-toi, tout va bien, ta mère est la plus puissante des Gauntwards que j'aie jamais vue, tout va s'arranger !"
  },
  AvgDialog_142893_Content_14 = {
    Text = "Je... Oncle Pontos, Maman..."
  },
  AvgDialog_142893_Content_15 = {
    Text = "La ville autrefois paisible était entièrement engloutie par les flammes."
  },
  AvgDialog_142893_Content_16 = {
    Text = "Juste une journée s'était écoulée, et des fanatiques surgis de nulle part, en nombre écrasant, avaient submergé tout ce que ton regard pouvait atteindre."
  },
  AvgDialog_142893_Content_17 = {
    Text = "Parmi Eux se trouvaient aussi bien des humains que des monstres dans toute leur horreur, et leurs attaques indiscriminées plongeaient toute la ville dans les flammes."
  },
  AvgDialog_142893_Content_18 = {
    Text = "Du sang au goût saumâtre et métallique vous éclaboussa le visage et le corps. Pontos canalisait désespérément le sifflet de chasse dans sa main, ouvrant un chemin de force aux côtés de son Cauchemar."
  },
  AvgDialog_142893_Content_19 = {
    Text = "Pontos, prends Jago et fuyez !"
  },
  AvgDialog_142893_Content_2 = {
    Text = "Cette nuit-là, épuisé par trop de frayeur et trop de pensées, vous vous êtes vite endormi."
  },
  AvgDialog_142893_Content_20 = {
    Text = "Leisha, qui s'efforçait avec les autres Gauntwards d'arrêter la vague de monstres, aperçut que tu étais sain et sauf ; ses Yeux s'illuminèrent et elle hurla à pleins poumons en direction de Pontos."
  },
  AvgDialog_142893_Content_21 = {Text = "Screeee !"},
  AvgDialog_142893_Content_22 = {
    Text = "Une autre tête semblable à une anémone de mer fut déchiquetée par les griffes acérées du Cauchemar. Leisha projeta nonchalamment un trait de la même lumière blanche cryptique que Pontos, l'empêchant de charger vers elle."
  },
  AvgDialog_142893_Content_23 = {
    Text = "On ne peut pas gagner celle-ci, mais on peut encore vous faire gagner du temps. Fuyez, aussi loin que possible !"
  },
  AvgDialog_142893_Content_24 = {
    Text = "Tu plaisantes, tu as déjà vaincu des ennemis bien plus nombreux sans effort, il ne t'arrivera rien ! Et puis, tu le sais, nous avons toujours un moyen."
  },
  AvgDialog_142893_Content_25 = {
    Text = "Vous ne saviez pas ce qu'Oncle Pontos entendait par « une issue ». Vous ne vîtes que son regard se poser sur ce sifflet de chasse, celui qu'il n'avait pas lâché depuis le jour de son retour."
  },
  AvgDialog_142893_Content_26 = {
    Text = "Non, <Red:jamais.>"
  },
  AvgDialog_142893_Content_27 = {
    Text = "<Shake:Je sais ce que tu penses, <Red:mon frère ne doit absolument pas rester piégé dans cet endroit maudit pour toujours !>   >"
  },
  AvgDialog_142893_Content_28 = {
    Text = "Embrassez la Liesse@1, nourrissez l'Érosion !"
  },
  AvgDialog_142893_Content_29 = {Text = "Leisha !!!"},
  AvgDialog_142893_Content_3 = {
    Text = "Vous et Pontos pensiez avoir encore de nombreuses occasions d'en parler."
  },
  AvgDialog_142893_Content_30 = {
    Text = "Dans un craquement d'écailles fracassées, un fanatique dont la moitié du corps avait été arrachée fit saillir ses globes oculaires L'Écarlate et se rua sur Leisha en grognant avec Fureur."
  },
  AvgDialog_142893_Content_31 = {
    Text = "...Le grincement insupportable de la peau et des muscles se déchirant."
  },
  AvgDialog_142893_Content_32 = {
    Text = "Le bruit de deux corps s'écrasant sur la route pavée."
  },
  AvgDialog_142893_Content_33 = {
    Text = "Le bruit des entrailles se répandant au sol."
  },
  AvgDialog_142893_Content_34 = {
    Text = "Puis, le monde sombra dans le silence en un instant. On n'entendait plus rien, on ne voyait plus rien."
  },
  AvgDialog_142893_Content_35 = {
    Text = "Du sang, le ciel nocturne, la lune."
  },
  AvgDialog_142893_Content_36 = {
    Text = "Une lune couleur de sang, suspendue au loin dans le ciel lointain."
  },
  AvgDialog_142893_Content_37 = {
    Text = "Ah... ahhh."
  },
  AvgDialog_142893_Content_38 = {
    Text = "AAAAAAAAHHHHH !!!!!"
  },
  AvgDialog_142893_Content_39 = {
    Text = "Après un bref gémissement étouffé, arraché du plus profond de sa gorge, Pontos poussa un cri comme vous n'en aviez jamais entendu de toute votre vie."
  },
  AvgDialog_142893_Content_4 = {
    Text = "<Red:Mais non.>"
  },
  AvgDialog_142893_Content_40 = {
    Text = "Une lamentation totalement inhumaine."
  },
  AvgDialog_142893_Content_41 = {
    Text = "Sœu— Sœurette... Leisha, LEISHA !!!"
  },
  AvgDialog_142893_Content_42 = {
    Text = "Un bourdonnement perçant transperça votre cerveau, et une vague écrasante de stupeur s'abattit sur vous comme un raz-de-marée. Non, non, non, non, non non non non non non..."
  },
  AvgDialog_142893_Content_43 = {
    Text = "Personne ne survécut. Les Thrall-Décharnés, qui de jour n'avaient semblé être que de sympathiques voisins, tombaient les uns après les autres. Les habitants ordinaires hurlaient dans la mer de feu et le flot de monstres."
  },
  AvgDialog_142893_Content_44 = {
    Text = "Mais vous n'entendiez plus rien de tout cela. Votre corps vous avait totalement trahi, et il gémissait avec eux, un cri brut et perçant."
  },
  AvgDialog_142893_Content_45 = {
    Text = "<Change>Sacrifice ! Sacrifiez-les tous à <Red:l'Extase> !"
  },
  AvgDialog_142893_Content_46 = {
    Text = "Les autres cultistes vous repérèrent sans la moindre difficulté, et juste au moment où ces griffes écailleuses, dégoulinantes de limon blasphématoire, se tendirent vers vous..."
  },
  AvgDialog_142893_Content_47 = {
    Text = "Pontos souffla dans le sifflet de chasse."
  },
  AvgDialog_142893_Content_48 = {
    Text = "Vous n'aviez jamais entendu un son aussi strident et aussi ancien. Une puissance irrationnelle traversa vos tympans de part en part et martela chaque dernier fragment de raison dans votre esprit."
  },
  AvgDialog_142893_Content_49 = {
    Text = "Une pression incomparable et immense s'abattit sur la terre !"
  },
  AvgDialog_142893_Content_5 = {Text = "Hisss— !"},
  AvgDialog_142893_Content_50 = {
    Text = "Une force invisible et colossale plaqua Pontos au sol, mais il ne semblait pas le ressentir du tout, les yeux écarquillés à en se fendre tandis qu'il récitait une prière incompréhensible."
  },
  AvgDialog_142893_Content_51 = {
    Text = "Ô @2, @4,@3 Seigneur de l›Abîme, je t›invoque au nom de @3..."
  },
  AvgDialog_142893_Content_52 = {
    Text = "D'innombrables présences semblables à des bras noirs émergèrent des fissures plus profondes que le plus ancien des océans, tendues vers leur unique <Red:proie> convoitée."
  },
  AvgDialog_142893_Content_53 = {
    Text = "<Shake:Tendues vers le <Red:maître >qu'Ils avaient élu.>"
  },
  AvgDialog_142893_Content_54 = {
    Text = "<Change>Prends ma chair, prends mon âme, prends tout !"
  },
  AvgDialog_142893_Content_55 = {
    Text = "Sur ce visage qui arborait toujours un sourire désinvolte apparut alors une expression de résolution tragique et d›abandon téméraire."
  },
  AvgDialog_142893_Content_56 = {
    Text = "Tandis que quelque chose de bien plus grand et de plus torrentiel fusionnait en lui, des ailes occultant le ciel s'élevèrent, formant couche après couche de barrières d'un noir d'encre."
  },
  AvgDialog_142893_Content_57 = {
    Text = "<Change>Exauce la prière de ton Exécuteur — réduis-les tous en poussière !!"
  },
  AvgDialog_142893_Content_58 = {
    Text = "Désormais, personne ne pouvait distinguer ce son grave et insondable de la voix qui avait jadis été celle de Pontos."
  },
  AvgDialog_142893_Content_59 = {
    Text = "Ils ne faisaient plus qu'un, indissociables, comme Ils le souhaitaient."
  },
  AvgDialog_142893_Content_6 = {
    Text = "<Shake:<Italic:Non, ce n'était pas ainsi que cela devait se passer,> pensiez-vous. <Italic:L'histoire du héros n'était pas censée se dérouler ainsi !>>"
  },
  AvgDialog_142893_Content_60 = {
    Text = "Tandis que le sifflement strident résonnait le long du littoral, chaque cultiste s'effondra en cendres blanches."
  },
  AvgDialog_142893_Content_61 = {Text = "新增"},
  AvgDialog_142893_Content_62 = {
    Text = "Ahhh ! ...Que s'est-il passé ensuite ? Oncle Pontos, et la mère de grand-père... ils..."
  },
  AvgDialog_142893_Content_63 = {
    Text = "Vera, qui avait retenu son souffle tout au long du récit, ne put finalement s'empêcher de s'écrier, les larmes au bord des yeux."
  },
  AvgDialog_142893_Content_64 = {
    Text = "Ce qui s›est passé après, j›ai beau essayer, je n›arrive tout simplement pas à m›en souvenir. Tout ce dont je me rappelle, c›est..."
  },
  AvgDialog_142893_Content_65 = {Text = "新增"},
  AvgDialog_142893_Content_66 = {
    Text = "*Sanglot*... Jago... Jago ! Dieu merci, tu es enfin réveillé."
  },
  AvgDialog_142893_Content_67 = {
    Text = "Papa, tante Leisa, tout le monde, notre ville, tout a été... Ouaaaaaah !!"
  },
  AvgDialog_142893_Content_68 = {
    Text = "À travers le récit entrecoupé de sanglots d›Orney, ton amie d›enfance, tu appris que la ville entière avait été anéantie dans une explosion massive."
  },
  AvgDialog_142893_Content_69 = {
    Text = "Seule une poignée de personnes survécut dans les ruines et fut recueillie par des proches ou des amis dans les villes voisines. Tu étais resté inconscient pendant quatre jours entiers."
  },
  AvgDialog_142893_Content_7 = {
    Text = "Jago, ferme les yeux et suis-moi !"
  },
  AvgDialog_142893_Content_70 = {
    Text = "Non, ce n›était pas une explosion. Je me souviens clairement... Argh ! J›ai tellement mal à la tête."
  },
  AvgDialog_142893_Content_71 = {
    Text = "Le bruit blanc perçant dans ton esprit te fit replonger dans le sommeil. Quand tu te réveillas à nouveau, tu te retrouvas bercé dans les bras de quelqu›un, l›esprit embrumé."
  },
  AvgDialog_142893_Content_72 = {
    Text = "Maman... Maman ?!"
  },
  AvgDialog_142893_Content_73 = {
    Text = "Ne bouge pas trop. Tes blessures ne sont pas encore guéries."
  },
  AvgDialog_142893_Content_74 = {
    Text = "Tu vis de tes propres yeux que Leisha — dont le ventre avait été déchiré par les fanatiques — était assise au bord du lit, complètement indemne. La joie immense fit s›écarquiller tes yeux tandis que les larmes ruisselaient sur ton visage."
  },
  AvgDialog_142893_Content_75 = {
    Text = "Maman ! C'était un rêve ? Je savais que tu allais bien, tu es toujours en vie."
  },
  AvgDialog_142893_Content_76 = {
    Text = "Chut, écoute–moi, Jago. Maman doit te quitter et partir très, très loin."
  },
  AvgDialog_142893_Content_77 = {
    Text = "La famille d›Orney prendra bien soin de toi. Demain matin, ils trouveront assez d›argent sur la table. Tu dois bien vivre."
  },
  AvgDialog_142893_Content_78 = {
    Text = "Attends, me quitter ? Maman, pourquoi ? Et Oncle Pontos ? Où est–il ?"
  },
  AvgDialog_142893_Content_79 = {
    Text = "Leisha se tut soudainement. Après un instant, elle serra ta main fermement, pressa la boussole en cuivre que tu avais laissé tomber dans ta paume, et se pencha pour embrasser ton front."
  },
  AvgDialog_142893_Content_8 = {
    Text = "Roar ! Roar !"
  },
  AvgDialog_142893_Content_80 = {
    Text = "Jago, garde ceci. Jure-moi que tu vivras en sécurité, quelque part."
  },
  AvgDialog_142893_Content_81 = {
    Text = "Tu voulais désespérément secouer la tête, mais Leisha ne t›en a pas laissé le temps."
  },
  AvgDialog_142893_Content_82 = {
    Text = "Souviens-toi, ne viens jamais nous chercher, ni moi ni ton oncle. Jamais."
  },
  AvgDialog_142893_Content_83 = {Text = "Maman !..."},
  AvgDialog_142893_Content_84 = {
    Text = "Vous vous redressez d'un bond."
  },
  AvgDialog_142893_Content_85 = {
    Text = "Une brise légère agitait les feuilles. La nuit était tombée sans que vous vous en rendiez compte."
  },
  AvgDialog_142893_Content_86 = {
    Text = "Était-ce un rêve ? Votre mère Leisha n'était nulle part en vue. Orney, qui sommeillait à votre chevet pour veiller sur vous, semblait avoir sursauté."
  },
  AvgDialog_142893_Content_87 = {
    Text = "Jago ?! Qu›est-ce qui se passe ?"
  },
  AvgDialog_142893_Content_88 = {
    Text = "Tu as fixé la fenêtre d›un regard vide. La lune était toujours suspendue au loin dans le ciel."
  },
  AvgDialog_142893_Content_89 = {
    Text = "Au-delà, il n›y avait rien."
  },
  AvgDialog_142893_Content_9 = {
    Text = "Pontos vous serre fort et court vers l'intérieur des terres, loin de la côte, son dos vous protégeant. Vous regardez avec terreur les flammes partout et les gens se débattant dans le chaos."
  },
  AvgDialog_145231_Content_1 = {Text = "Bang—"},
  AvgDialog_145231_Content_10 = {
    Text = "Aujourd'hui, je n'arrivais pas à me concentrer sur ma lame ni sur mon adversaire."
  },
  AvgDialog_145231_Content_11 = {
    Text = "Quelque chose d'autre n'arrêtait pas de me distraire."
  },
  AvgDialog_145231_Content_12 = {
    Text = "Quelque chose d'autre ? Comme quoi ?"
  },
  AvgDialog_145231_Content_13 = {Text = "Vous."},
  AvgDialog_145231_Content_14 = {
    Text = "??? Vous voulez dire..."
  },
  AvgDialog_145231_Content_15 = {
    Text = "Oui. Cette folle de Thais, et sa rivière de folie."
  },
  AvgDialog_145231_Content_16 = {
    Text = "Ce n'est pas grave de perdre un combat pour une fois. Repose-toi ici pour l'instant, je vais t'apporter des médicaments..."
  },
  AvgDialog_145231_Content_17 = {Text = "新增"},
  AvgDialog_145231_Content_18 = {
    Text = "Vous tentez de quitter la pièce discrètement, mais Lotan ne vous en laisse pas l'occasion."
  },
  AvgDialog_145231_Content_19 = {
    Text = "Deux claquements secs retentissent près de vos oreilles. Les lames d'os de Lotan transpercent le lit, leurs poignées d'os clouant vos mains sur le matelas. Vous ne pouvez plus bouger."
  },
  AvgDialog_145231_Content_2 = {
    Text = "La porte s'ouvre en grand avec un fracas semblable à un tambour de guerre. Dégageant une odeur de sang, quelqu'un fait irruption et s'effondre sur votre lit, haletant."
  },
  AvgDialog_145231_Content_20 = {
    Text = "Je ne suis pas venue ici pour guérir. Je suis venue pour régler un problème. Et vous... vous êtes le problème."
  },
  AvgDialog_145231_Content_21 = {
    Text = "Hé ! Lotan... qu'est... qu'est-ce que tu fais..."
  },
  AvgDialog_145231_Content_22 = {
    Text = "Je déteste ne pas pouvoir me concentrer sur le combat. Ça m'irrite."
  },
  AvgDialog_145231_Content_23 = {
    Text = "J—J'ai une idée ! Tu pourrais aller trouver Thais... mmph..."
  },
  AvgDialog_145231_Content_24 = {
    Text = "Une main ensanglantée se plaque sur ta mâchoire, étouffant ta voix en gémissements incohérents."
  },
  AvgDialog_145231_Content_25 = {
    Text = "Mon esprit n'a jamais contenu autre chose que le combat. Mais avoir une exception... ce n'est pas si mal."
  },
  AvgDialog_145231_Content_26 = {
    Text = "J'aime me concentrer sur une chose à la fois. Que ce soit un combat... ou autre chose."
  },
  AvgDialog_145231_Content_27 = {
    Text = "Lotan te fixe du regard comme si elle clouait au sol une rivale qui lui procure un plaisir ultime, l'ardeur combative dans ses yeux se muant en une faim à nu."
  },
  AvgDialog_145231_Content_28 = {
    Text = "J'ai versé tout ce sang à cause de toi. Tu vas devoir payer pour ça, n'est-ce pas ?"
  },
  AvgDialog_145231_Content_29 = {
    Text = "Les griffes de fer de ses gantelets tracent le long de ta mâchoire, glissant le long de ta gorge, ta poitrine et ta taille... Tu te débats frénétiquement, laissant échapper des sons sans signification, mais les lames te retiennent fermement, immobiles comme la pierre."
  },
  AvgDialog_145231_Content_3 = {
    Text = "Ah ! Qui—"
  },
  AvgDialog_145231_Content_30 = {
    Text = "Lotan se penche, admirant ton visage rougi par l'effort du combat."
  },
  AvgDialog_145231_Content_31 = {
    Text = "Elle sourit, laissant son sang goutter de ses lèvres sur ton visage."
  },
  AvgDialog_145231_Content_32 = {
    Text = "Débats-toi tant que tu veux. Voyons si tu peux te libérer... mon «adversaire»."
  },
  AvgDialog_145231_Content_4 = {
    Text = "...Lotan ? Tu es blessée ?!"
  },
  AvgDialog_145231_Content_5 = {
    Text = "Vous la regardez, incrédule, dans son état pitoyable."
  },
  AvgDialog_145231_Content_6 = {
    Text = "Juste des égratignures. Rien de grave."
  },
  AvgDialog_145231_Content_7 = {
    Text = "Que s'est-il passé... Qui a pu te mettre dans cet état ?"
  },
  AvgDialog_145231_Content_8 = {
    Text = "Un Ver de la Mer Astrale. Ça aurait dû être facile à tuer. Mais aujourd'hui..."
  },
  AvgDialog_145231_Content_9 = {
    Text = "Elle fronce les sourcils, une lueur d'irritation dans les yeux."
  },
  AvgDialog_14530_Content_10 = {
    Text = "Lèvres entrouvertes, un léger goût salé se répand.\nCe n'est pas de la pluie."
  },
  AvgDialog_14530_Content_11 = {
    Text = "<Gray:...Des larmes?>"
  },
  AvgDialog_14530_Content_12 = {
    Text = "Comme si tout avait été lavé par la pluie, la vue devient progressivement plus claire."
  },
  AvgDialog_14530_Content_14 = {
    Text = "Ra... Mona..."
  },
  AvgDialog_14530_Content_15 = {
    Text = "Votre appel se termine soudainement sur une note abrupte."
  },
  AvgDialog_14530_Content_16 = {
    Text = "Un stress accablant vient de toutes directions, et des marées noires t'englobent."
  },
  AvgDialog_14530_Content_17 = {Text = "新增"},
  AvgDialog_14530_Content_18 = {
    Text = "L'horloge tic-tac, et le bruit du chant des oiseaux filtre à travers la fenêtre à moitié ouverte."
  },
  AvgDialog_14530_Content_19 = {
    Text = "La suffocation persistante vous fait instinctivement vous taper la poitrine. En vous redressant lentement, il faut un moment avant que vous vous sentiez vraiment éveillé."
  },
  AvgDialog_14530_Content_2 = {
    Text = "Larmes de la Pluie"
  },
  AvgDialog_14530_Content_20 = {
    Text = "<Gray:J'ai eu tant de rêves étranges, mais c'est la première fois que je rêve de ma propre mort.>"
  },
  AvgDialog_14530_Content_21 = {
    Text = "On se sent étrange."
  },
  AvgDialog_14530_Content_22 = {
    Text = "Assez intéressant."
  },
  AvgDialog_14530_Content_23 = {
    Text = "Bing Bing—"
  },
  AvgDialog_14530_Content_24 = {
    Text = "Vous éteignez le réveil, vous vous levez et vous vous étirez."
  },
  AvgDialog_14530_Content_25 = {
    Text = "D'accord, peu importe. Je me souviens que je dois y aller aujourd'hui—"
  },
  AvgDialog_14530_Content_26 = {
    Text = "Entraînement spécial demain à 8 heures dans la Salle de Réveil. Ne soyez pas en retard"
  },
  AvgDialog_14530_Content_27 = {
    Text = "Salle de Réveil ? Est-ce pour l'entraînement lié au réveil ?"
  },
  AvgDialog_14530_Content_28 = {
    Text = "Tester la stabilité de <Yellow:Domaine Artificiel>."
  },
  AvgDialog_14530_Content_29 = {
    Text = "Qu'est-ce que cela ?"
  },
  AvgDialog_14530_Content_3 = {Text = "Tomber."},
  AvgDialog_14530_Content_30 = {
    Text = "Un petit projet sur lequel je travaille, plus comme un passe-temps—utiliser l'amplification du dispositif d'éveil pour améliorer la conscience et l'esprit pendant le sommeil"
  },
  AvgDialog_14530_Content_31 = {
    Text = "En théorie, un esprit suffisamment grand peut former un domaine, et un domaine stabilisé peut exister indépendamment des dimensions de réalité et de l'esprit."
  },
  AvgDialog_14530_Content_32 = {
    Text = "Ce royaume est assez similaire au <Yellow:Domaine>, donc je l'appelle un Domaine Artificiel."
  },
  AvgDialog_14530_Content_33 = {
    Text = "Contrairement aux domaines naturels qui s'infiltrent dans la réalité depuis la dimension spirituelle, les domaines artificiels sont non agressifs, plus stables et contrôlables, et peuvent <Yellow:recréer un moment d'un temps qui n'existe pas dans le présent>."
  },
  AvgDialog_14530_Content_34 = {
    Text = "\"Le présent n'existe pas\"—Vous dites donc qu'il peut montrer les souvenirs de quelqu'un ?"
  },
  AvgDialog_14530_Content_35 = {
    Text = "Cela peut <Yellow:présenter un souvenir basé sur la compréhension du Maître Esprit>, et cela permet également à d'autres d'entrer dans ce souvenir."
  },
  AvgDialog_14530_Content_36 = {
    Text = "Comme entrer dans le Domaine...?"
  },
  AvgDialog_14530_Content_37 = {
    Text = "Pas mal. Oui, après la formation d'un Domaine artificiel, d'autres individus peuvent y entrer physiquement et interagir avec la conscience de l'entité spirituelle—le propriétaire du Domaine."
  },
  AvgDialog_14530_Content_38 = {
    Text = "À ce moment, que l'esprit reconnaisse le visiteur et quelle attitude il adopte... Ha, rien que d'y penser est intéressant."
  },
  AvgDialog_14530_Content_39 = {
    Text = "Si le Domaine Artificiel fonctionne, ce sera le meilleur moyen pour les Enquêteurs, les Gardiens, et leurs Réveilleurs respectifs de créer des liens et d'approfondir la compréhension."
  },
  AvgDialog_14530_Content_4 = {
    Text = "Vous tombez."
  },
  AvgDialog_14530_Content_40 = {
    Text = "En pensant aux yeux ardents de la Poupée, tu as ressenti un frisson parcourir ton cuir chevelu."
  },
  AvgDialog_14530_Content_41 = {
    Text = "Ils appellent cela un entraînement spécial, mais nous ne sommes que des cobayes...\nJ'espère que rien ne va mal aujourd'hui."
  },
  AvgDialog_14530_Content_42 = {
    Text = "Vous rassemblez votre esprit et poussez la porte dans le passage souterrain."
  },
  AvgDialog_14530_Content_43 = {
    Text = "Avant que vous ne puissiez réagir, une lumière éblouissante vous engloutit complètement."
  },
  AvgDialog_14530_Content_5 = {
    Text = "La sensation de chute vous tire, entraînant doucement votre conscience hors du rêve noir comme du charbon."
  },
  AvgDialog_14530_Content_6 = {
    Text = "Une lumière floue apparaît devant vos yeux. Après un moment de confusion, vous réalisez que vous semblez avoir ouvert les yeux."
  },
  AvgDialog_14530_Content_7 = {
    Text = "<Gray:Comment... ne peux pas voir clairement...>"
  },
  AvgDialog_14530_Content_8 = {
    Text = "Une goutte, deux gouttes... Un liquide frais tombe sur votre front, roulant le long de votre joue."
  },
  AvgDialog_14530_Content_9 = {Text = "Pluie...?"},
  AvgDialog_145510_Content_10 = {
    Text = "Au pied des montagnes enneigées, un marché chaotique a poussé hors du permafrost. Baraques en bois, tentes, étals de fortune en peau de yak s'entassent de part et d'autre d'un chemin de montagne boueux."
  },
  AvgDialog_145510_Content_11 = {
    Text = "Le Continent du Nord de la Fin est vraiment trop froid, j'ai un peu la nostalgie du thé chaud de Mme Sylvia…"
  },
  AvgDialog_145510_Content_12 = {
    Text = "C'est peut-être un peu tôt pour le dire, mais une fois de retour à Mizag, je demanderai à Mme Sylvia de vous fournir du thé chaud en Cycle continu 24 heures sur 24."
  },
  AvgDialog_145510_Content_13 = {
    Text = "Pour l'instant, concentrons-nous sur la mission en cours."
  },
  AvgDialog_145510_Content_14 = {
    Text = "Vous sortez la brochure publicitaire froissée par les bagages et la faites pivoter face au soleil pour la comparer."
  },
  AvgDialog_145510_Content_15 = {
    Text = "La ligne de jonction des montagnes part du bord de la brochure et s'aligne parfaitement avec le profil des sommets sous le ciel maussade."
  },
  AvgDialog_145510_Content_16 = {
    Text = "C'est bien ici, mais comment trouver ce mystérieux maître dont les titres s'empilent plus haut que l'Everest…"
  },
  AvgDialog_145510_Content_17 = {
    Text = "<Shake:Tout le monde, écouteeez bien !>"
  },
  AvgDialog_145510_Content_18 = {
    Text = "En suivant la direction de l'Appel, une jeune fille vêtue de blanc se tient seule devant une tente sur une colline, surplombant la foule clairsemée."
  },
  AvgDialog_145510_Content_19 = {
    Text = "Je suis l'Exécuteur du dieu suprême, la grande Fée de la secte Caraboo, incarnation de la déesse des neiges Umapati égarée parmi les hommes."
  },
  AvgDialog_145510_Content_2 = {
    Text = "Les Prisonniers de la Neige"
  },
  AvgDialog_145510_Content_20 = {
    Text = "(C'est un peu différent de ce qui est écrit dans la brochure…)"
  },
  AvgDialog_145510_Content_21 = {
    Text = "Oh, si vous êtes la déesse des neiges, montrez-nous donc un sort !"
  },
  AvgDialog_145510_Content_22 = {
    Text = "La Provocation de l'homme suscita quelques rires épars."
  },
  AvgDialog_145510_Content_23 = {
    Text = "Non, je n'en suis pas encore capable."
  },
  AvgDialog_145510_Content_24 = {
    Text = "La jeune fille sortit nonchalamment une Pomme rouge vif et en croqua une bouchée."
  },
  AvgDialog_145510_Content_25 = {
    Text = "Car j'ai perdu sept artefacts magiques, sept trésors qui me sont chers."
  },
  AvgDialog_145510_Content_26 = {
    Text = "Ce sont la Pomme d'or d'Éris, le Miroir de Yata, la Plume de Ma'at, la Clé de Salomon, l'Œil de Balor..."
  },
  AvgDialog_145510_Content_27 = {
    Text = "Ces artefacts magiques que tu possèdes viennent de civilisations vraiment nombreuses et variées !"
  },
  AvgDialog_145510_Content_28 = {
    Text = "Un nouvel éclat de rire général retentit, mais la jeune fille n'en avait cure."
  },
  AvgDialog_145510_Content_29 = {
    Text = "Il y a aussi le Fil de Moïra, et la Couronne d'Ariane."
  },
  AvgDialog_145510_Content_3 = {
    Text = [[
Le plus grand mensonge de ce monde,
sorti de la bouche de celui qui ne ment jamais.]]
  },
  AvgDialog_145510_Content_30 = {
    Text = "Le Fil de Moïra… le métier à tisser des Trois Destins…"
  },
  AvgDialog_145510_Content_31 = {
    Text = "Ne serait-ce pas là ce qu'Arachne appelait, «le Destin que nous devons accueillir» ?"
  },
  AvgDialog_145510_Content_32 = {
    Text = "Vous sortez ce petit rouleau de Fil de la doublure de votre poche, et le Fil lumineux scintille entre vos doigts de couleurs mouvantes presque imperceptibles à l'œil nu."
  },
  AvgDialog_145510_Content_33 = {
    Text = "Attendons encore un peu, agissons avec prudence."
  },
  AvgDialog_145510_Content_34 = {
    Text = "Bien que le Destin nous ait guidés jusqu'ici, il ne nous a pas révélé le rôle que joue le propriétaire du manuel dans cette histoire."
  },
  AvgDialog_145510_Content_35 = {
    Text = "*Tousse, tousse!*"
  },
  AvgDialog_145510_Content_36 = {
    Text = "Si vous avez bien tout compris, laissez ici vos Offrandes !"
  },
  AvgDialog_145510_Content_37 = {
    Text = "Pas plus, pas moins, Tant Que cinquante Billets Rose Dorée ! Cela suffira à faire ressentir à la déesse des neiges Umapati votre sincérité !"
  },
  AvgDialog_145510_Content_38 = {
    Text = "En tant que déesse des neiges, une fois que j'aurai rassemblé les sept grands artefacts et que je serai ressuscitée sous la nouvelle lune, je répondrai à vos prières au centuple et au millième !"
  },
  AvgDialog_145510_Content_39 = {
    Text = "Après tout ce charabia, c'est donc pour quêter des dons que tu es venue !"
  },
  AvgDialog_145510_Content_4 = {
    Text = "– Altitude 4 000 m –"
  },
  AvgDialog_145510_Content_40 = {
    Text = "Depuis que la déesse des neiges s'est manifestée, les expéditions venues gravir la montagne se comptent par milliers, et chacune apporte ses propres provisions."
  },
  AvgDialog_145510_Content_41 = {
    Text = "Toi qui ne penses qu'à profiter sans rien faire, tu ferais mieux de déguerpit au plus vite et d'apprendre à réaliser tes vœux par le travail de tes propres mains !"
  },
  AvgDialog_145510_Content_42 = {
    Text = "Les badauds se dispersèrent dans un brouhaha."
  },
  AvgDialog_145510_Content_43 = {
    Text = "Vous en profitâtes pour vous frayer un chemin à contre-courant de la foule et vous approcher de la jeune fille désolée pour l'interroger."
  },
  AvgDialog_145510_Content_44 = {
    Text = "Excusez-moi… Puis-je vous demander si c'est vous qui avez envoyé cette brochure ?"
  },
  AvgDialog_145510_Content_45 = {
    Text = "Vous sortez cette brochure tape-à-l'œil et tapotez sur les mots «Grand Maître, Élu(e) de la Divinité, Ami proche du Roi des Dieux»."
  },
  AvgDialog_145510_Content_46 = {
    Text = "Les yeux de la jeune fille s'illuminèrent instantanément."
  },
  AvgDialog_145510_Content_47 = {
    Text = "<Shake:Ohhhh ! Vous avez vraiment eu ma brochure de recrutement !>"
  },
  AvgDialog_145510_Content_48 = {
    Text = "Alors, où sont vos douze apôtres et les autres fidèles ?"
  },
  AvgDialog_145510_Content_49 = {
    Text = "C'est une longue histoire… Mon illustre secte a été victime d'une sombre machination. Parmi les douze apôtres, l'un d'eux nourrissait de noires intentions, cherchant à s'accaparer seul la gloire suprême."
  },
  AvgDialog_145510_Content_5 = {
    Text = "Nous sommes arrivés"
  },
  AvgDialog_145510_Content_50 = {
    Text = "Les autres fidèles ont été montés les uns contre les autres jusqu'à l'éclatement total. Il ne reste plus que moi, le Maître, seul à entreprendre ce long et pénible voyage pour faire renaître la secte."
  },
  AvgDialog_145510_Content_51 = {
    Text = "Il vous suffit maintenant de sponsoriser mille Billets Rose Dorée pour accéder au rang de premier des nouveaux Douze Apôtres et devenir mon disciple numéro un…"
  },
  AvgDialog_145510_Content_52 = {
    Text = "Mais tout à l'heure, quand vous faisiez votre spectacle dans la rue, vous disiez être Uma Pati, la déesse de la montagne de Neige."
  },
  AvgDialog_145510_Content_53 = {
    Text = "C'est ce qu'on appelle : en dehors de chez soi, l'Identité, on se la donne soi-même, c'est ça ?"
  },
  AvgDialog_145510_Content_54 = {
    Text = "Pfft, découverte."
  },
  AvgDialog_145510_Content_55 = {
    Text = "La jeune fille bondit d'un coup et disparut en quelques mouvements derrière une tente."
  },
  AvgDialog_145510_Content_56 = {
    Text = "Vous vous apprêtiez à rattraper la jeune fille lorsque quelqu'un vous tapa soudainement dans le dos."
  },
  AvgDialog_145510_Content_57 = {
    Text = "Messieurs, vous venez pour l'ascension ?"
  },
  AvgDialog_145510_Content_58 = {
    Text = "Hein, nous ?"
  },
  AvgDialog_145510_Content_59 = {
    Text = "Eh oui, rien qu'à vous voir, vous avez une prestance remarquable. Vous n'êtes pas des Personnes du cru, n'est-ce pas ?"
  },
  AvgDialog_145510_Content_6 = {
    Text = "C'est ici le dernier point de ravitaillement sur la route de l'Everest."
  },
  AvgDialog_145510_Content_60 = {
    Text = "Ces derniers temps, tous ceux qui arrivent dans ces terres désolées ne viennent-ils pas pour la déesse au sommet de la montagne, celle qui peut exaucer tous les vœux ?"
  },
  AvgDialog_145510_Content_61 = {
    Text = "Vous n'avez pas beaucoup d'équipement, on dirait que vous comptez profiter des ressources des autres. Quelle coïncidence, dites-moi."
  },
  AvgDialog_145510_Content_62 = {
    Text = "<Yellow:Je m'appelle Naraka. Je suis un guide Sherpa local.>"
  },
  AvgDialog_145510_Content_63 = {
    Text = "Notre équipe d'alpinisme est financée par la Fondation Green. Les provisions sont déjà prêtes, il ne manque plus que «l'élu du destin» pour rejoindre le sommet."
  },
  AvgDialog_145510_Content_64 = {
    Text = "Une âme prédestinée ?"
  },
  AvgDialog_145510_Content_65 = {
    Text = "Hm, j'ai vécu au pied de cette montagne enneigée pendant de nombreuses années. Ceux qui ont la capacité d'atteindre le sommet —"
  },
  AvgDialog_145510_Content_66 = {
    Text = "Il pointa ses yeux du doigt."
  },
  AvgDialog_145510_Content_67 = {
    Text = "Ces yeux peuvent le voir au premier coup d'œil."
  },
  AvgDialog_145510_Content_68 = {
    Text = "Oh ? Dites-moi donc ?"
  },
  AvgDialog_145510_Content_69 = {
    Text = "Tout d'abord, bien sûr, un âge approprié, une constitution robuste, et une Énergie Spirituelle stable."
  },
  AvgDialog_145510_Content_7 = {
    Text = "Plus haut, les véhicules ne peuvent plus avancer."
  },
  AvgDialog_145510_Content_70 = {
    Text = "En dehors de cela, ce qui importe davantage, c'est la volonté et la détermination d'atteindre le sommet — la détermination de ne pas rendre son dernier souffle Tant Que l'on n'a pas gravi la cime."
  },
  AvgDialog_145510_Content_71 = {
    Text = "Rendre son dernier souffle au sommet — on dirait que vous ne comptez pas nous laisser redescendre vivants ?"
  },
  AvgDialog_145510_Content_72 = {
    Text = "Eh, il ne faut pas voir les choses ainsi. Au sommet, en rencontrant la déesse de la montagne enneigée, tous les vœux peuvent être exaucés. À ce moment-là, redescendre, une si petite chose — vaut-il vraiment la peine de s'en inquiéter ?"
  },
  AvgDialog_145510_Content_73 = {
    Text = "Allez, suivez-moi au camp de montagne. Je vous garantis que vous serez satisfaits."
  },
  AvgDialog_145510_Content_74 = {
    Text = "Vous jetez un coup d'œil à William, lui demandant silencieusement son avis."
  },
  AvgDialog_145510_Content_75 = {
    Text = "Allons-y. Cette jeune fille de tout à l'heure, on ne sait pas où elle est passée."
  },
  AvgDialog_145510_Content_76 = {
    Text = "Si l'on veut vraiment gravir la montagne, un guide local et des provisions complètes sont indispensables."
  },
  AvgDialog_145510_Content_77 = {
    Text = "Allons-y, voyons le camp."
  },
  AvgDialog_145510_Content_79 = {
    Text = "Quelle belle voix…"
  },
  AvgDialog_145510_Content_8 = {
    Text = "Vous ouvrez la portière du véhicule, et l'air s'engouffre aussitôt dans vos narines — l'odeur brûlée du thé au beurre, le fumet des bêtes, et ce froid propre aux hauts plateaux, mince et vif comme une lame."
  },
  AvgDialog_145510_Content_80 = {
    Text = "Elle me semble familière."
  },
  AvgDialog_145510_Content_81 = {
    Text = "Comme si elle se déversait depuis les confins d'une galaxie lointaine, ou comme si elle remontait paisiblement des profondeurs de l'Aequor infini."
  },
  AvgDialog_145510_Content_83 = {
    Text = "Le chant venait de la direction du camp, s'élevant brin par brin, de plus en plus distinct, tel un brouillard qui se dissipe pour laisser apparaître la clarté d'une pleine lune."
  },
  AvgDialog_145510_Content_85 = {
    Text = "Sur un terrain dégagé à l'écart du camp, une jeune fille au visage empreint de tristesse chantait à pleine voix."
  },
  AvgDialog_145510_Content_86 = {
    Text = "Tous les passants ralentirent instinctivement le pas et retinrent leur souffle — de peur de troubler cette voix qui coulait comme un clair de lune."
  },
  AvgDialog_145510_Content_88 = {
    Text = "Ce n'est qu'à la fin du morceau qu'elle émergea du monde dans lequel elle s'était plongée, pour découvrir votre présence."
  },
  AvgDialog_145510_Content_89 = {
    Text = "Il y a de nouveaux membres ?"
  },
  AvgDialog_145510_Content_9 = {
    Text = "Un ciel de plomb s'écrase sur le bout du monde. Les sommets enneigés se dressent comme une rangée de divinités silencieuses, à la frontière du crépuscule et des nuages."
  },
  AvgDialog_145511_Content_1 = {
    Text = "Quelque chose ne va pas."
  },
  AvgDialog_145511_Content_10 = {
    Text = "Non, pas seulement la cape ; dans son sillage, autre chose se déploya également."
  },
  AvgDialog_145511_Content_11 = {
    Text = "Une paire d'ailes."
  },
  AvgDialog_145511_Content_12 = {
    Text = "Une paire d'ailes noires — un noir dense, profond, qui inspirait un funeste pressentiment à quiconque les regardait."
  },
  AvgDialog_145511_Content_13 = {
    Text = "<BigShake:Par ce corps impérissable, je repousse tout Cataclysme !>"
  },
  AvgDialog_145511_Content_14 = {
    Text = "Castor déploya ses Ailes Déployées, et la Neige accumulée explosa derrière lui en un arc blanc lumineux, Presque vertical."
  },
  AvgDialog_145511_Content_15 = {
    Text = "Il s'élance depuis la pente enneigée, franchissant une distance qu'il n'aurait jamais pu traverser autrement—"
  },
  AvgDialog_145511_Content_16 = {
    Text = "Puis il s'interposa entre le Wendigo et Evelyn."
  },
  AvgDialog_145511_Content_17 = {
    Text = "Ses ailes se déploient largement, formant une immense barrière d'un noir absolu derrière lui."
  },
  AvgDialog_145511_Content_18 = {
    Text = "La gueule du Wendigo, qui allait se refermer, mordit son aile droite, arrachant d'un coup une touffe de Plumes à la racine."
  },
  AvgDialog_145511_Content_19 = {
    Text = "<Shake:Ugh !!>"
  },
  AvgDialog_145511_Content_2 = {
    Text = "Du coin de l'œil, dans un recoin de la horde, le Wendigo le plus grand et le plus maigre n'avait pas encore attaqué depuis le début du combat."
  },
  AvgDialog_145511_Content_20 = {
    Text = "Castor laisse échapper un grognement étouffé, mais il ne recule pas."
  },
  AvgDialog_145511_Content_21 = {
    Text = "Ne gaspillez pas l'opportunité que Castor a créée — maintenant !"
  },
  AvgDialog_145511_Content_3 = {
    Text = "Il attendait, observant le maillon le plus faible de l'équipe d'alpinistes."
  },
  AvgDialog_145511_Content_4 = {
    Text = "Il contourne vos trois compagnons et se jette sur Evelyn."
  },
  AvgDialog_145511_Content_5 = {
    Text = "Evelyn — !"
  },
  AvgDialog_145511_Content_6 = {
    Text = "Caraboo était trop loin ; au moment où il cria, il savait déjà qu'il n'arriverait pas à temps."
  },
  AvgDialog_145511_Content_7 = {
    Text = "— Mais quelqu'un, lui, en avait le temps."
  },
  AvgDialog_145511_Content_8 = {
    Text = "Castor se mit à Courir à toute vitesse et défit d'un geste les lacets de sa cape."
  },
  AvgDialog_145511_Content_9 = {
    Text = "La cape claqua dans son sillage —"
  },
  AvgDialog_145512_Content_1 = {
    Text = "C'est terminé, vaincu."
  },
  AvgDialog_145512_Content_10 = {
    Text = "Votre maître vous a dit quelque chose comme : mon petit chéri, vous avez travaillé dur, voici la récompense de vos efforts passés."
  },
  AvgDialog_145512_Content_11 = {
    Text = "Qu'il vous suffisait de gravir vous-même le sommet enneigé, de repousser vos adversaires et de reprendre votre couronne ?"
  },
  AvgDialog_145512_Content_12 = {
    Text = "Malheureusement, <BigShake:VOUS—AVEZ—ÉTÉ—BER—NÉ(E) !!>"
  },
  AvgDialog_145512_Content_13 = {
    Text = "Un pion restera toujours un pion, et au moment opportun, il deviendra un pion sacrifié."
  },
  AvgDialog_145512_Content_14 = {
    Text = "Quand la valeur que vous pouvez apporter a été entièrement exploitée, quand vous commencez à ressentir du mécontentement… c'est le moment d'offrir votre tête."
  },
  AvgDialog_145512_Content_15 = {
    Text = "En tant que l'une des sept Offrandes sur l'autel, avez-vous des dernières paroles à prononcer ?"
  },
  AvgDialog_145512_Content_16 = {
    Text = "Il ne fallait pas… ne faire confiance à personne…"
  },
  AvgDialog_145512_Content_17 = {
    Text = "Dès le début, croire en la faveur de cette dame… Plus Tard… désirer la vengeance de mes semblables…"
  },
  AvgDialog_145512_Content_18 = {
    Text = "Et maintenant, poussé par la promesse de quelqu'un…"
  },
  AvgDialog_145512_Content_19 = {
    Text = "Bon, bon, le temps accordé pour vos dernières paroles n'est qu'une politesse — personne ne se soucie vraiment de votre pitoyable vie ratée."
  },
  AvgDialog_145512_Content_2 = {
    Text = "Caraboo enjambe Helot agenouillé au sol et saisit délicatement le globe oculaire posé sur le cercle magique."
  },
  AvgDialog_145512_Content_20 = {
    Text = "Ce que vous ne pouvez pas gagner par vous-même, volez-le, escroquez-le, arrachez-le — à quoi bon attendre que les autres vous fassent l'aumône."
  },
  AvgDialog_145512_Content_21 = {
    Text = "Il n'y a plus assez de temps pour cela — quant au reste de vos réflexions, attendez la prochaine vie pour les poursuivre."
  },
  AvgDialog_145512_Content_22 = {
    Text = "Caraboo leva la main et lança doucement l'œil, qui s'enfonça dans le corps d'Helot."
  },
  AvgDialog_145512_Content_23 = {
    Text = "Puis retentit un craquement, craquement, le son de l'Ingestion."
  },
  AvgDialog_145512_Content_24 = {
    Text = "Mange, mange."
  },
  AvgDialog_145512_Content_25 = {
    Text = "Le corps d'Helot s'effondra rapidement, laissant derrière lui une mare de Sang."
  },
  AvgDialog_145512_Content_26 = {
    Text = "C'est bien ça, ils vont te dévorer, jusqu'à ce qu'il ne reste plus rien…"
  },
  AvgDialog_145512_Content_27 = {
    Text = "Vous percevez sur Le Visage de Caraboo une certaine joie cruelle."
  },
  AvgDialog_145512_Content_28 = {
    Text = "Regardez, votre triste sort est la Source de votre stupidité, la Source de votre crédulité envers Un Mensonge."
  },
  AvgDialog_145512_Content_29 = {Text = "Caraboo…"},
  AvgDialog_145512_Content_3 = {
    Text = "Ton vœu aussi deviendra l'engrais qui nourrira la montagne de Neige."
  },
  AvgDialog_145512_Content_30 = {
    Text = "Hmm? Qu'est-ce qui se passe?"
  },
  AvgDialog_145512_Content_31 = {
    Text = "Elle se retourna et observa attentivement votre expression."
  },
  AvgDialog_145512_Content_32 = {
    Text = "Elle afficha son air espiègle et câlin habituel, mais Vous lûtes tout de même dans un coin de ses yeux une arrogance qui trahissait sa haine Cachée."
  },
  AvgDialog_145512_Content_33 = {
    Text = "Puis-je voir ces six artefacts ?"
  },
  AvgDialog_145512_Content_34 = {
    Text = "Bien sûr !"
  },
  AvgDialog_145512_Content_35 = {
    Text = "Caraboo s'écarta, vous laissant la place face au cercle magique."
  },
  AvgDialog_145512_Content_36 = {
    Text = "Le Fil de Moïra — un cadeau d'Arachne."
  },
  AvgDialog_145512_Content_37 = {
    Text = "Le Miroir de Yata, trouvé sur les rives du lac de glace où errait Tinct."
  },
  AvgDialog_145512_Content_38 = {
    Text = "La Plume de Ma'at, tombée du vent de Neige après le départ de Castor."
  },
  AvgDialog_145512_Content_39 = {
    Text = "L'Œil de Balor, cristallisé dans la mare de Sang d'Helot."
  },
  AvgDialog_145512_Content_4 = {
    Text = "Le globe oculaire prit soudain une apparence terrifiante, sa pupille rouge sang s'écarquillant d'une lueur sanglante."
  },
  AvgDialog_145512_Content_40 = {
    Text = "la Pomme d'Or, Caraboo l'a sortie d'on ne sait quel bagage."
  },
  AvgDialog_145512_Content_41 = {
    Text = "La Clé de Salomon, c'est en réalité la Clé d'argent que vous portez sur vous."
  },
  AvgDialog_145512_Content_42 = {
    Text = "Et aussi, ce que l'expédition précédente a trouvé, la Couronne d'Ariane…"
  },
  AvgDialog_145512_Content_43 = {
    Text = "Vous êtes stupéfait."
  },
  AvgDialog_145512_Content_44 = {
    Text = "La Couronne d'Ariane… quelle Couronne d'Ariane, ce n'est pas <Yellow:la Couronne de Tulu> !"
  },
  AvgDialog_145512_Content_45 = {
    Text = "Qu'est-ce qu'il y a de si surprenant ? la Pomme d'Or n'est pas dorée non plus ?"
  },
  AvgDialog_145512_Content_46 = {
    Text = "Mais, pourquoi la Couronne de Tulu se trouverait-elle ici ?"
  },
  AvgDialog_145512_Content_47 = {
    Text = "Parce que c'est Son artefact, Son offrande, Son ingrédient préféré."
  },
  AvgDialog_145512_Content_48 = {
    Text = "Au moment où les paroles de Caraboo retombèrent, la Terre trembla soudainement."
  },
  AvgDialog_145512_Content_49 = {
    Text = "Que se passe-t-il ?"
  },
  AvgDialog_145512_Content_5 = {
    Text = "Non, comment est-ce possible... !"
  },
  AvgDialog_145512_Content_50 = {Text = "Elle rit !"},
  AvgDialog_145512_Content_51 = {
    Text = "… Elle rit ?"
  },
  AvgDialog_145512_Content_52 = {
    Text = "Le sommet de la montagne tremblait par vagues, Comme Si une jeune fille en fleur, ayant été témoin de quelque chose d'amusant, riait aux éclats, secouée de tremblements."
  },
  AvgDialog_145512_Content_53 = {
    Text = "La Neige accumulée se détacha."
  },
  AvgDialog_145512_Content_54 = {
    Text = "Ce pic n'était pas un sommet montagneux, mais un immense ver tapi sur la cime, semblable à un gigantesque serpent capable d'engloutir ciel et terre."
  },
  AvgDialog_145512_Content_55 = {
    Text = "En raison de la faiblesse des humains, incapables d'affronter la réalité, ils ont choisi de croire en Un Mensonge, confiant leurs vœux à une Divinité du Vide."
  },
  AvgDialog_145512_Content_56 = {
    Text = "Ils n'ont jamais imaginé — que la soi-disant Divinité pouvait aussi mentir. Car la Divinité a elle aussi des vœux qu'elle souhaite réaliser."
  },
  AvgDialog_145512_Content_57 = {
    Text = "Le vœu de la Divinité, c'est — de les dévorer."
  },
  AvgDialog_145512_Content_58 = {
    Text = "La Couronne, le Fil, la Clé d'Argent, le fruit défendu, la plume ailée, le miroir lumineux, l'Œil magique. Sept artefacts, telles des Offrandes façonnées par la vie de ces humains pleins de Gourmandise."
  },
  AvgDialog_145512_Content_59 = {
    Text = "Tout ce que vous êtes n'est qu'un repas copieux pour Elle."
  },
  AvgDialog_145512_Content_6 = {
    Text = "L'Œil de Balor, l'œil démoniaque du dieu maléfique. Capable de détruire tout ce qu'il regarde, et pourtant l'unique point faible de cette divinité."
  },
  AvgDialog_145512_Content_60 = {
    Text = "Maintenant, Il a obtenu ce qu'Il voulait, Il devrait bien sûr sourire !"
  },
  AvgDialog_145512_Content_61 = {
    Text = "Les choses en étant là, il est temps de nous dire la vérité, n'est-ce pas ?"
  },
  AvgDialog_145512_Content_62 = {
    Text = "Vous n'avez pas simplement profité de ce voyage comme vous le laissiez paraître."
  },
  AvgDialog_145512_Content_63 = {
    Text = "Bien au contraire, c'est sous votre guidance que toute l'équipe d'alpinisme en est arrivée là."
  },
  AvgDialog_145512_Content_64 = {
    Text = "La rencontre fortuite dans la grotte au début avec Castor, le choix de Tinct d'aller contempler le lac de glace…"
  },
  AvgDialog_145512_Content_65 = {
    Text = "Et cet Helot qui nous a suivis tout ce temps — en réalité, vous aviez tout prévu depuis longtemps."
  },
  AvgDialog_145512_Content_66 = {
    Text = "Qui êtes-vous vraiment ?"
  },
  AvgDialog_145512_Content_7 = {
    Text = "Votre maître ne vous l'a pas dit ? Cet œil, Seulement imprégné de votre Festin de sang, mérite d'être appelé «Œil de Balor»."
  },
  AvgDialog_145512_Content_8 = {
    Text = "Il a dit..."
  },
  AvgDialog_145512_Content_9 = {
    Text = "Chut, laissez-moi deviner."
  },
  AvgDialog_145513_Content_1 = {
    Text = "Pacte des Menteurs"
  },
  AvgDialog_145513_Content_10 = {
    Text = "<Yellow:C'est toi qui as brûlé mon colis> ? Je vais arracher le masque humain de ce personnage —"
  },
  AvgDialog_145513_Content_11 = {
    Text = "Elle agrippa fermement les joues de Naraka et tira de chaque côté."
  },
  AvgDialog_145513_Content_12 = {
    Text = "<Shake:ATTENDEZ !>"
  },
  AvgDialog_145513_Content_13 = {
    Text = "Crrrrac —"
  },
  AvgDialog_145513_Content_14 = {
    Text = "L'enveloppe connue sous le nom de «Naraka» est déchirée en deux, comme une poupée en caoutchouc entre les mains d'un enfant espiègle."
  },
  AvgDialog_145513_Content_15 = {
    Text = "Ce qui s'écoulait à flots de la fissure était une fumée noire appelée «Chaos»."
  },
  AvgDialog_145513_Content_16 = {
    Text = "La fumée tourbillonna, s'enroula, se condensa, puis tendit avec légèreté une rose."
  },
  AvgDialog_145513_Content_17 = {
    Text = "On se retrouve, vieil ami."
  },
  AvgDialog_145513_Content_18 = {
    Text = "Avant de se remémorer le passé, que diriez-vous d'un petit échauffement pour apaiser notre petite escroc hors d'elle ?"
  },
  AvgDialog_145513_Content_2 = {
    Text = "Au bout du Fil, la jeune fille émergea de l'obscurité."
  },
  AvgDialog_145513_Content_3 = {
    Text = "Oh, petite menteuse, tu t'es mise toi-même en jeu ?"
  },
  AvgDialog_145513_Content_4 = {
    Text = "Les paroles de Naraka ne font qu'aiguiser la colère d'une fille qui baissait déjà la tête de frustration."
  },
  AvgDialog_145513_Content_5 = {
    Text = "Vous, vous avez l'air bien à l'aise."
  },
  AvgDialog_145513_Content_6 = {
    Text = "Caraboo leva la tête, ses yeux brûlant de colère fixés sur Naraka."
  },
  AvgDialog_145513_Content_7 = {
    Text = "Arrêtez de faire semblant. Un guide Sherpa, avalé par la montagne, et vous avez encore le cœur à plaisanter ?"
  },
  AvgDialog_145513_Content_8 = {
    Text = "Dès la première fois que je vous ai vu, j'ai su que vous étiez un imposteur, vous aussi."
  },
  AvgDialog_145513_Content_9 = {
    Text = "Caraboo se jeta sur elle. Cette fois, elle ne laissa pas Naraka s'esquiver."
  },
  AvgDialog_145514_Content_1 = {
    Text = "Le dernier Wendigo se dissipa dans l'ombre de Castor."
  },
  AvgDialog_145514_Content_10 = {
    Text = "Peut-être que les liens entre les gens commencent justement par le partage d'un petit secret, non ?"
  },
  AvgDialog_145514_Content_11 = {
    Text = "Sans que vous sachiez quand, Caraboo s'était approché et prononçait devant vous, avec un sourire malicieux, les mots qui vous traversaient l'esprit."
  },
  AvgDialog_145514_Content_12 = {
    Text = "L'échange de secrets ne doit pas être à sens unique."
  },
  AvgDialog_145514_Content_13 = {
    Text = "Cette Tante Rosa que vous avez appelée tant de fois — c'est quelqu'un d'important pour vous ?"
  },
  AvgDialog_145514_Content_14 = {
    Text = "Bien sûr que je l'ai inventé. Vous n'y avez quand même pas vraiment cru ?"
  },
  AvgDialog_145514_Content_15 = {
    Text = "Hehe, tromper un idiot n'a rien d'extraordinaire, mais vous tromper, vous, c'est une autre affaire."
  },
  AvgDialog_145514_Content_16 = {
    Text = "Convaincre le Wendigo que vous étiez envoûté était bien plus difficile que de vous tromper."
  },
  AvgDialog_145514_Content_17 = {
    Text = "Ils peuvent entendre la voix au fond de votre cœur, puis la restituer par le vent."
  },
  AvgDialog_145514_Content_18 = {
    Text = "Mais qui pourrait le savoir ? Peut-être que la déesse de la montagne de Neige a tant d'histoires en elle que chacune semble vraie ?"
  },
  AvgDialog_145514_Content_19 = {
    Text = "Caraboo esquiva la question avec légèreté, d'une pirouette espiègle."
  },
  AvgDialog_145514_Content_2 = {
    Text = "Puis le vent qui effleurait les oreilles devint soudainement limpide. Il ne portait plus aucun son."
  },
  AvgDialog_145514_Content_20 = {
    Text = "Puisque vous ne souhaitez pas en parler, nous ne vous forcerons certainement pas à répondre."
  },
  AvgDialog_145514_Content_21 = {
    Text = "Mais la sincérité est quelque chose de précieux — même si vous êtes un imposteur, il vaut mieux ne pas décevoir les attentes de tout le monde."
  },
  AvgDialog_145514_Content_22 = {
    Text = "C'est mon conseil sincère, à vous de décider si vous l'écoutez ou non."
  },
  AvgDialog_145514_Content_23 = {
    Text = "William dit cela, puis se dirigea vers l'avant du groupe."
  },
  AvgDialog_145514_Content_24 = {Text = "Hmph."},
  AvgDialog_145514_Content_25 = {
    Text = "Bienfaiteur, vous ne seriez pas aussi insensible que lui, n'est-ce pas ?"
  },
  AvgDialog_145514_Content_26 = {
    Text = "J'ai passé beaucoup de temps à travailler avec William. Ce n'est pas un homme qui dit quoi que ce soit d'inutile."
  },
  AvgDialog_145514_Content_27 = {
    Text = "Dans mon souvenir, chaque conseil qu'il a donné s'est révélé efficace."
  },
  AvgDialog_145514_Content_28 = {
    Text = "<Shake:Snif, bienfaiteur, il s'avère que vous êtes tout aussi cruel...>"
  },
  AvgDialog_145514_Content_29 = {
    Text = "Caraboo s'éloigna en faisant semblant d'être triste, tandis que vous rejoignîtes William qui était en train de discuter avec Naraka."
  },
  AvgDialog_145514_Content_3 = {
    Text = "Le silence signifiait la sécurité, mais cette sécurité laissait un vague sentiment de mélancolie."
  },
  AvgDialog_145514_Content_30 = {
    Text = "Il vous indiqua du regard de vous écarter de quelques pas, jusqu'à ce que les personnes à côté ne puissent plus entendre vos Chuchotements."
  },
  AvgDialog_145514_Content_31 = {
    Text = "Le combat contre le Wendigo tout à l'heure, avez-vous trouvé cela étrange ?"
  },
  AvgDialog_145514_Content_32 = {Text = "Où ?"},
  AvgDialog_145514_Content_33 = {Text = "Naraka."},
  AvgDialog_145514_Content_34 = {
    Text = "Repensez-y — depuis que ces voix ont retenti dans le vent, jusqu'à l'apparition du Wendigo, jusqu'à l'encerclement tout à l'heure —"
  },
  AvgDialog_145514_Content_35 = {
    Text = "Naraka, y a-t-il eu, à un seul instant, un seul Wendigo qui s'est approché de vous ?"
  },
  AvgDialog_145514_Content_36 = {
    Text = "Caraboo a été attaquée par un Wendigo lorsqu'elle jouait le rôle de la victime, Evelyn a été renversée par le plus grand des Wendigos, Castor s'est fait arracher un morceau de Plume…"
  },
  AvgDialog_145514_Content_37 = {
    Text = "Y compris lors de la fois précédente où ils ont été ensorcelés par le Wendigo, Naraka ne semble pas non plus avoir été affectée."
  },
  AvgDialog_145514_Content_38 = {
    Text = "Tu veux dire..."
  },
  AvgDialog_145514_Content_39 = {
    Text = "Je ne sous-entends rien."
  },
  AvgDialog_145514_Content_4 = {
    Text = "Evelyn jeta un coup d'œil aux ailes de Castor, mais son expression resta impassible, Comme Si chaque personne sur terre cachait naturellement une paire d'ailes."
  },
  AvgDialog_145514_Content_40 = {
    Text = "Il reste encore quatre ou cinq jours de marche vers le haut, nous n'avons pas d'autre guide à remplacer."
  },
  AvgDialog_145514_Content_41 = {
    Text = "J'espère que je me fais trop de souci, mais nous devons rester vigilants."
  },
  AvgDialog_145514_Content_42 = {
    Text = "Tout au long de ce Chemin, Nous avons déjà perdu un Tinct. Je ne veux plus, par ma négligence, laisser quiconque sur cette montagne."
  },
  AvgDialog_145514_Content_43 = {
    Text = "Le vent contournait le bord extérieur de la crête rocheuse."
  },
  AvgDialog_145514_Content_44 = {
    Text = "Contourner la silhouette accroupie au loin, en train de frapper la glace."
  },
  AvgDialog_145514_Content_45 = {
    Text = "La pointe du pic de Naraka heurtait les éclats de glace sous ses semelles, produisant un son régulier et cadencé, comme un balancier."
  },
  AvgDialog_145514_Content_46 = {
    Text = "–Altitude 6 500 m–"
  },
  AvgDialog_145514_Content_5 = {
    Text = "Je vais te faire un bandage."
  },
  AvgDialog_145514_Content_6 = {
    Text = "Désolé… d'avoir caché cela tout ce temps."
  },
  AvgDialog_145514_Content_7 = {
    Text = "Ce n'est pas grave. Nous sommes tous ici pour chercher un Miracle extraordinaire capable de ressusciter les morts… Dans un tel moment, découvrir une existence qui brise les conventions, c'est plutôt une bonne nouvelle."
  },
  AvgDialog_145514_Content_8 = {
    Text = "Et puis, tu refuses même d'enlever cette cape pour dormir — tout le monde savait bien que tu cachais un secret."
  },
  AvgDialog_145514_Content_9 = {
    Text = "Malgré le ton légèrement plaintif, vous sentez clairement que, après ce combat, tout le monde commence à baisser sa garde et à se rapprocher."
  },
  AvgDialog_145515_Content_1 = {
    Text = "Sept Fils du Destin"
  },
  AvgDialog_145515_Content_10 = {
    Text = "<Shake:Regardez là-bas — !>"
  },
  AvgDialog_145515_Content_11 = {
    Text = "Avant même que ses mots ne s'éteignent, Elle s'élança vers le versant en pente douce de l'autre côté."
  },
  AvgDialog_145515_Content_12 = {
    Text = "C'était un autel hexagonal."
  },
  AvgDialog_145515_Content_13 = {
    Text = "Au centre de l'autel, une Couronne avait déjà été déposée."
  },
  AvgDialog_145515_Content_14 = {
    Text = "La femme enchaînée inventoriait les trésors dérobés. %player%La Clé d'Argent et le Fil dans sa poche, le miroir, la Plume Noire et la Pomme dorée dans le baluchon de Caraboo."
  },
  AvgDialog_145515_Content_15 = {
    Text = "Le globe oculaire de Balor ?"
  },
  AvgDialog_145515_Content_16 = {
    Text = "Helot ricana, puis enfonça ses ongles acérés dans le boulet de chaîne à ses côtés."
  },
  AvgDialog_145515_Content_17 = {
    Text = "Un bruit visqueux et sourd s'échappa du boulet de chaîne."
  },
  AvgDialog_145515_Content_18 = {
    Text = "Elle remua, fouilla… jusqu'à en extraire un globe oculaire ensanglanté."
  },
  AvgDialog_145515_Content_19 = {
    Text = "Tout est pour toi, espèce de glouton."
  },
  AvgDialog_145515_Content_2 = {
    Text = "– Altitude 8800 mètres –"
  },
  AvgDialog_145515_Content_20 = {
    Text = "Elle déposa les six trésors chacun dans un coin de l'autel."
  },
  AvgDialog_145515_Content_21 = {
    Text = "À présent, il est temps d'exaucer mon vœu."
  },
  AvgDialog_145515_Content_22 = {
    Text = "Elle ferma les yeux et se tut."
  },
  AvgDialog_145515_Content_23 = {
    Text = "Fais-la revivre… permets-moi d'abattre mes ennemis de ma propre main, et accomplis ma vengeance si longtemps attendue."
  },
  AvgDialog_145515_Content_24 = {
    Text = "Un vent cinglant souffla sur les cimes des Prisonniers de la Neige. Son vœu ne reçut aucune réponse."
  },
  AvgDialog_145515_Content_25 = {
    Text = "Pourquoi ? Ne t'ai-je pas déjà remis les sept Offrandes ?"
  },
  AvgDialog_145515_Content_26 = {
    Text = "La voix indignée d'Helot résonna entre les lointains sommets, déclenchant vague après vague de petites avalanches."
  },
  AvgDialog_145515_Content_27 = {
    Text = "Parce que l'une des offrandes est fausse, voyons ?"
  },
  AvgDialog_145515_Content_28 = {Text = "Qui ?!"},
  AvgDialog_145515_Content_29 = {
    Text = "Caraboo s'avança en sautillant d'un pas léger, Comme Si Helot ne comptait absolument pas pour elle."
  },
  AvgDialog_145515_Content_3 = {
    Text = "C'est un lieu où les pas de l'humanité ne se sont jamais aventurés."
  },
  AvgDialog_145515_Content_30 = {
    Text = "Vous autres, vous n'avez en tête que vos propres vœux, sans jamais vous demander ce que la Divinité désire vraiment comme offrande."
  },
  AvgDialog_145515_Content_31 = {
    Text = "la Pomme d'Or, la Pomme d'Or — tu ne crois tout de même pas que Tant Que c'est une Pomme dorée, tu as fait le bon choix ?"
  },
  AvgDialog_145515_Content_32 = {
    Text = "Elle prit la Pomme Dorée posée sur l'autel et y mordit délicatement."
  },
  AvgDialog_145515_Content_33 = {
    Text = "Mhm, c'est bien toi, comme je le pensais."
  },
  AvgDialog_145515_Content_34 = {
    Text = "Le papier doré se détacha alors, révélant ce qui se cachait à l'intérieur."
  },
  AvgDialog_145515_Content_35 = {
    Text = "Friandise, bonbon, tablette de cacao — peu importe le nom qu'on lui donne, c'était du chocolat des plus ordinaires qui soit."
  },
  AvgDialog_145515_Content_36 = {
    Text = "<BigShake:Ta-da ! La Bénédiction des fées, un délice suprême !>"
  },
  AvgDialog_145515_Content_37 = {
    Text = "Vous... imposteur..."
  },
  AvgDialog_145515_Content_38 = {
    Text = "Un brigand ne vaut guère mieux qu'un imposteur, non ?"
  },
  AvgDialog_145515_Content_39 = {
    Text = "Assez de bavardages, rendez la véritable Pomme Dorée !"
  },
  AvgDialog_145515_Content_4 = {
    Text = "Debout au sommet du pic enneigé, contemplant au loin les montagnes immaculées, ce qui Réverbération dans la poitrine n'était pas la fierté d'avoir atteint le sommet."
  },
  AvgDialog_145515_Content_40 = {
    Text = "Il faudra d'abord leur demander s'ils sont d'accord."
  },
  AvgDialog_145515_Content_41 = {
    Text = "Caraboo se retourne, et l'équipe d'alpinistes franchit la dernière falaise."
  },
  AvgDialog_145515_Content_5 = {
    Text = "Mais la Peur."
  },
  AvgDialog_145515_Content_6 = {
    Text = "La Peur de s'éloigner du monde des hommes, la Peur d'être séparé de tout ce qui est familier."
  },
  AvgDialog_145515_Content_7 = {
    Text = "Ici, il n'y a plus de cime plus haute à l'horizon ; celui qui a atteint le sommet ne peut que s'agenouiller face au ciel."
  },
  AvgDialog_145515_Content_8 = {
    Text = "Mesdames et messieurs, nous avons atteint le sommet."
  },
  AvgDialog_145515_Content_9 = {
    Text = "Parmi les membres de l'expédition, une seule personne n'était pas du tout impressionnée par le spectacle au sommet."
  },
  AvgDialog_145516_Content_1 = {
    Text = "Le Précurseur"
  },
  AvgDialog_145516_Content_10 = {
    Text = "Il nous manque donc encore la <Blue:Clé de Salomon> et l'<Blue:Œil de Balor>."
  },
  AvgDialog_145516_Content_11 = {
    Text = "Caraboo compte sur ses doigts en marmonnant."
  },
  AvgDialog_145516_Content_12 = {
    Text = "Vous pensez que l'Œil de Balor pourrait tomber du ciel comme la Plume de Ma'at ?"
  },
  AvgDialog_145516_Content_13 = {
    Text = "Cette plaisanterie n'est pas drôle du tout."
  },
  AvgDialog_145516_Content_14 = {
    Text = "Vous ne savez pas ce qui est arrivé à Castor, mais cette plume d'un noir d'encre porte encore son empreinte."
  },
  AvgDialog_145516_Content_15 = {
    Text = "C'est juste devant, plus très loin."
  },
  AvgDialog_145516_Content_16 = {
    Text = "Avant d'atteindre le sommet, nous ne pouvons pas faire demi-tour."
  },
  AvgDialog_145516_Content_17 = {
    Text = "William vous tapote l'épaule. De toute évidence, il sait ce que vous pensez."
  },
  AvgDialog_145516_Content_18 = {
    Text = "Tu sais ? J'ai une intuition."
  },
  AvgDialog_145516_Content_19 = {
    Text = "Castor a sûrement trouvé ce qu'il voulait poursuivre, c'est pour ça qu'il a quitté l'équipe."
  },
  AvgDialog_145516_Content_2 = {
    Text = "C'est le dernier point de repos avant l'assaut final du sommet."
  },
  AvgDialog_145516_Content_20 = {
    Text = "Et si c'est lui, il réalisera certainement son vœu."
  },
  AvgDialog_145516_Content_21 = {
    Text = "Evelyn toussa légèrement, comme pour donner plus de poids à ses paroles, et ajouta une phrase."
  },
  AvgDialog_145516_Content_22 = {
    Text = "Tant Que l'on vit assez longtemps, on peut Épier la tendance du Destin des autres même à travers de brèves rencontres."
  },
  AvgDialog_145516_Content_23 = {
    Text = "Chez Castor, qu'as-tu vu ?"
  },
  AvgDialog_145516_Content_24 = {
    Text = "Simplicité, et ténacité."
  },
  AvgDialog_145516_Content_25 = {
    Text = "Jusqu'à obtenir cette unique réponse, il ne s'arrêtera pas.\nIl n'hésitera pas, et n'abandonnera pas non plus."
  },
  AvgDialog_145516_Content_26 = {
    Text = "Et toi, Evelyn ? Où se trouve Ta réponse ?"
  },
  AvgDialog_145516_Content_27 = {
    Text = "Là-haut, sur la montagne."
  },
  AvgDialog_145516_Content_28 = {
    Text = "Quelle coïncidence, nous faisons le même Chemin !"
  },
  AvgDialog_145516_Content_29 = {
    Text = "Caraboo sortit de nulle part une autre Pomme, la lança en l'air et la rattrapa."
  },
  AvgDialog_145516_Content_3 = {
    Text = "En regardant en arrière vers les montagnes lointaines, à vos pieds s'étend une immensité de glace et de Neige, se fondant dans un horizon lointain entre les brumes du col."
  },
  AvgDialog_145516_Content_30 = {
    Text = "Si tout le monde est prêt, alors Commençons la dernière étape."
  },
  AvgDialog_145516_Content_31 = {
    Text = "Ne relâchez pas vos efforts. Beaucoup d'accidents surviennent dans les derniers mille mètres."
  },
  AvgDialog_145516_Content_32 = {
    Text = "Devant vous se dresse une paroi de glace quasi verticale."
  },
  AvgDialog_145516_Content_33 = {
    Text = "#N/ANaraka balance le piolet, enfonçant la pointe en diagonale dans la neige dure avec un bruit sourd, puis déplace son poids vers le haut, ses pointes avant s'enfonçant précisément dans le petit trou laissé par la pointe."
  },
  AvgDialog_145516_Content_34 = {
    Text = "Étrange, il semblerait que quelqu'un soit passé par ici récemment."
  },
  AvgDialog_145516_Content_35 = {
    Text = "Regardez, il y a quelques trous ici, qui ressemblent un peu à ceux creusés par un piolet."
  },
  AvgDialog_145516_Content_36 = {
    Text = "Serait-ce des traces laissées par l'expédition précédente ?"
  },
  AvgDialog_145516_Content_37 = {
    Text = "Peu probable. Trop de temps s'est écoulé, les traces d'alors auraient déjà été recouvertes par la glace depuis longtemps."
  },
  AvgDialog_145516_Content_38 = {
    Text = "Laissons tomber, inutile d'y penser davantage. Si quelqu'un est passé par là, c'est bon signe — cela signifie que ce chemin est praticable."
  },
  AvgDialog_145516_Content_39 = {
    Text = "Il détacha une broche à glace de son baudrier, la fit tournoyer et la planta dans la couche de glace, produisant un craquement désagréable qui faisait grincer les dents."
  },
  AvgDialog_145516_Content_4 = {
    Text = "Ce spectacle grandiose apporte un peu de légèreté à votre groupe, pourtant quelque peu épuisé."
  },
  AvgDialog_145516_Content_40 = {
    Text = "Une fois la broche enfoncée jusqu'à la garde, Naraka y accrocha un mousqueton à vis, y passa la corde principale et serra le verrou à fond."
  },
  AvgDialog_145516_Content_41 = {
    Text = "Premier point d'ancrage."
  },
  AvgDialog_145516_Content_42 = {
    Text = "Tout le monde, bloquez vos bloqueurs sur la corde principale. Utilisez les crampons de vos chaussures d'alpinisme pour vous accrocher dans les encoches que j'ai taillées, et avancez lentement."
  },
  AvgDialog_145516_Content_43 = {
    Text = "Vous cherchez un point d'appui solide au-dessus de votre tête avec votre piolet, plantez fermement la pointe, puis levez le pied droit et enfoncez violemment les pointes avant dans la glace, laissant les deux dents d'acier mordre la surface."
  },
  AvgDialog_145516_Content_44 = {
    Text = "Transférez le poids sur vos pieds, ne vous collez pas contre la paroi de glace."
  },
  AvgDialog_145516_Content_45 = {
    Text = "Vous inspirez profondément l'air raréfié qui brûle les poumons, écartez légèrement votre corps de la paroi de glace pour laisser les crampons supporter votre poids. Le pied gauche suit, un autre coup de crampon."
  },
  AvgDialog_145516_Content_46 = {
    Text = "Le bloqueur glisse lentement avec vous vers le haut, cliquetant à vide à chaque petit déplacement."
  },
  AvgDialog_145516_Content_47 = {
    Text = "À mi-chemin, vous êtes déjà trempé de sueur, et votre concentration, jusqu'alors soutenue, commence à se dissiper malgré vous."
  },
  AvgDialog_145516_Content_48 = {
    Text = "Restez concentré, ce passage ne tolère aucun imprévu."
  },
  AvgDialog_145516_Content_49 = {
    Text = "Juste au moment où ses mots s'éteignirent, l'imprévu survint."
  },
  AvgDialog_145516_Content_5 = {
    Text = "<Shake:At-, attendez.>"
  },
  AvgDialog_145516_Content_50 = {Text = "新增"},
  AvgDialog_145516_Content_51 = {
    Text = "Un filet de lumière rouge jaillit de l'obscurité, et le nez de William frémit —"
  },
  AvgDialog_145516_Content_52 = {
    Text = "<BigShake:À plat ventre — !>"
  },
  AvgDialog_145516_Content_53 = {
    Text = "Avant même que les mots ne s'éteignent, il se jeta brusquement sur vous, son corps entier vous clouant sur place, seule la corde de sécurité vous retenant tous les deux, se balançant contre la paroi de glace."
  },
  AvgDialog_145516_Content_54 = {
    Text = "Un mince filet de sang apparut sur sa joue."
  },
  AvgDialog_145516_Content_55 = {
    Text = "Tss, tu réagis vite."
  },
  AvgDialog_145516_Content_56 = {
    Text = "Dans les profondeurs des ténèbres, de lourdes chaînes raclaient le sol, le frottement du métal contre le plancher produisant un son sourd et traînant."
  },
  AvgDialog_145516_Content_57 = {
    Text = "C'est toi, le type qui nous a suivis tout ce chemin."
  },
  AvgDialog_145516_Content_58 = {
    Text = "Suivi tout ce chemin ?"
  },
  AvgDialog_145516_Content_59 = {
    Text = "En effet, quand nous avons rencontré Castor, je vous avais prévenus que quelqu'un nous suivait."
  },
  AvgDialog_145516_Content_6 = {
    Text = "Evelyn reprend son souffle à grandes inspirations. La basse pression due à l'altitude élevée affecte manifestement son corps de façon importante."
  },
  AvgDialog_145516_Content_60 = {
    Text = "Ce que je ne sais pas, c'est quand elle a réussi à nous devancer."
  },
  AvgDialog_145516_Content_61 = {
    Text = "Pas étonnant que cette présence me soit si familière."
  },
  AvgDialog_145516_Content_62 = {
    Text = "Je me souviens de ton nom —"
  },
  AvgDialog_145516_Content_63 = {
    Text = "Parfait, cela nous évite les présentations."
  },
  AvgDialog_145516_Content_64 = {
    Text = "À la frontière entre lumière et ombre, une silhouette s'avance lentement."
  },
  AvgDialog_145516_Content_65 = {
    Text = "Ses deux poignets sont tranchés, et dans son sillage traînent deux lourdes boules enchaînées, sur lesquelles deux immenses yeux couleur de sang fixent le monde d'un regard féroce."
  },
  AvgDialog_145516_Content_66 = {
    Text = "… Helot : Enchaînée."
  },
  AvgDialog_145516_Content_67 = {
    Text = "Dans le monde précédent, elle était la dernière personne que j'aie vue."
  },
  AvgDialog_145516_Content_68 = {
    Text = "Autrement dit — elle est celle qui m'a tué."
  },
  AvgDialog_145516_Content_69 = {
    Text = "À cette époque, elle obéissait à Herbert, elle obéissait à l'Association des Sculpteurs."
  },
  AvgDialog_145516_Content_7 = {
    Text = "Derrière elle, la petite fille avance d'un pas étonnamment léger."
  },
  AvgDialog_145516_Content_70 = {
    Text = "Et maintenant ? <Yellow:Qui> t'a envoyée ici ?"
  },
  AvgDialog_145516_Content_71 = {
    Text = "Seuls les chiens s'inquiètent de savoir qui est leur maître."
  },
  AvgDialog_145516_Content_72 = {
    Text = "Je n'ai qu'une seule chose à faire — vous enterrer ici pour l'éternité."
  },
  AvgDialog_145516_Content_73 = {
    Text = "D'innombrables Pustules surgissent du sol, vous encerclant de toutes parts."
  },
  AvgDialog_145516_Content_8 = {
    Text = "On a le <Blue:Miroir de Yata> et la <Blue:Plume de Ma'at>. La <Blue:Couronne d'Ariane> devrait être au sommet."
  },
  AvgDialog_145516_Content_9 = {
    Text = "Quant au <Blue:Fil de Moïra>… Hehe, certains d'entre vous ne me le diront pas, mais je sais où il est. Et je peux nous procurer une <Blue:Pomme Dorée>."
  },
  AvgDialog_145517_Content_1 = {
    Text = "Aujourd'hui les Oiseaux Partent"
  },
  AvgDialog_145517_Content_10 = {
    Text = "Sortez donc, vous me suivez depuis le début, n'est-ce pas ?"
  },
  AvgDialog_145517_Content_11 = {
    Text = "Je suis déjà isolé, et la distance est trop courte pour appeler à l'aide."
  },
  AvgDialog_145517_Content_12 = {
    Text = "<Shake:Laissons-nous... nous faire... face...>"
  },
  AvgDialog_145517_Content_13 = {
    Text = "L'homme qui surgit de la forêt semblait tout droit sorti de son Rêve."
  },
  AvgDialog_145517_Content_14 = {
    Text = "<Shake:Non… vous êtes…>"
  },
  AvgDialog_145517_Content_15 = {
    Text = "Cette silhouette élancée et noble paraissait encore plus amaigrie qu'au moment de leur séparation."
  },
  AvgDialog_145517_Content_16 = {
    Text = "Je me nomme Pollux. Sur ordre du Maître, je suis venu pour la Poursuite du fugitif Castor."
  },
  AvgDialog_145517_Content_17 = {
    Text = "Le contenu n'avait plus d'importance ; sa voix bourdonnait aux oreilles de Castor, tels des Murmures dans un Rêve."
  },
  AvgDialog_145517_Content_18 = {
    Text = "<SmallShake:Un Wendigo ?>"
  },
  AvgDialog_145517_Content_19 = {
    Text = "Non, ce n'était pas un Wendigo. Même la plus belle des illusions ne pouvait contrefaire la texture du réel."
  },
  AvgDialog_145517_Content_2 = {
    Text = "Le jeune homme filait à toute allure dans la Neige."
  },
  AvgDialog_145517_Content_20 = {
    Text = "Pécheur… Castor… la Lumière Sacrée révélera tes fautes."
  },
  AvgDialog_145517_Content_21 = {
    Text = "Réelle, rugueuse, glaciale, cruelle, terrifiante."
  },
  AvgDialog_145517_Content_22 = {Text = "Pollux…"},
  AvgDialog_145517_Content_23 = {
    Text = "Cette douleur lancinante qui lui montait au cœur."
  },
  AvgDialog_145517_Content_24 = {
    Text = "Combien de temps encore pourrait-il Esquiver ? Combien de temps lui restait-il pour Esquiver ?"
  },
  AvgDialog_145517_Content_25 = {
    Text = "Castor avançait dans la Neige, pas après pas, en direction de Pollux."
  },
  AvgDialog_145517_Content_26 = {
    Text = "<Red:<Shake:Agenouillez-vous devant la Lanterne, et je vous absoudrai de vos péchés, vous accordant une renaissance sous une nouvelle forme sur la terre sainte sans péché !>"
  },
  AvgDialog_145517_Content_27 = {
    Text = "Castor n'obéit pas. Il continua simplement d'avancer vers Pollux."
  },
  AvgDialog_145517_Content_28 = {
    Text = "Même si c'était un Wendigo, cela lui était égal. Il avançait, c'est tout."
  },
  AvgDialog_145517_Content_29 = {
    Text = "Pollux leva son couteau. Un couteau familier. Lors de la dernière Poursuite, Castor en avait été Percé en pleine poitrine."
  },
  AvgDialog_145517_Content_3 = {
    Text = "Plus rien ne pouvait l'arrêter."
  },
  AvgDialog_145517_Content_30 = {
    Text = "<Big:Un pas de plus, et la lumière sainte vous foudroyera !>"
  },
  AvgDialog_145517_Content_4 = {
    Text = "Le Chemin de descente… aussi léger que de voler portés par le vent."
  },
  AvgDialog_145517_Content_5 = {
    Text = "Un Chemin sans le poids d'Un Mensonge, qui faisait s'envoler son âme avec légèreté."
  },
  AvgDialog_145517_Content_6 = {
    Text = "Pardonnez-moi, je n'aurais pas dû Vous tromper."
  },
  AvgDialog_145517_Content_7 = {
    Text = "Heureusement, il est encore temps de tout arranger."
  },
  AvgDialog_145517_Content_8 = {
    Text = "Chaque fois qu'il s'arrêtait un instant, un son semblable à celui de la Neige qui tombe se propageait depuis la forêt derrière lui."
  },
  AvgDialog_145517_Content_9 = {
    Text = "C'était le bruit de pas s'immobilisant brusquement."
  },
  AvgDialog_145518_Content_1 = {
    Text = "La Lune Non Gelée"
  },
  AvgDialog_145518_Content_10 = {
    Text = "Vous acceptez volontiers."
  },
  AvgDialog_145518_Content_100 = {
    Text = "Ah, les rusés imposteurs, qui apparaissent toujours sous les traits des victimes les plus innocentes…"
  },
  AvgDialog_145518_Content_101 = {
    Text = "Elle fredonnait un petit air et rejoignit l'avant de la troupe."
  },
  AvgDialog_145518_Content_102 = {
    Text = "Que voulait-elle dire par là ?"
  },
  AvgDialog_145518_Content_103 = {
    Text = "Je ne comprenais pas non plus."
  },
  AvgDialog_145518_Content_104 = {
    Text = "Hé~ Suivez le mouvement, ne restez pas à la traîne~"
  },
  AvgDialog_145518_Content_105 = {
    Text = "Les deux, perplexes, n'eurent d'autre choix que d'avancer."
  },
  AvgDialog_145518_Content_106 = {
    Text = "– Altitude 6 000 m –"
  },
  AvgDialog_145518_Content_11 = {
    Text = "Je sais que c'est difficile à croire, mais je viens d'une étoile très, très lointaine. J'ai dérivé si longtemps que tout ce dont je me souviens, c'est que dans ses derniers jours, nous l'appelions <Blue:l'Étoile Maléfique.>"
  },
  AvgDialog_145518_Content_12 = {
    Text = "J'ai traversé un temps si long qu'il est impossible à mesurer, avant d'arriver ici."
  },
  AvgDialog_145518_Content_13 = {
    Text = "Je te fais confiance."
  },
  AvgDialog_145518_Content_14 = {
    Text = "Ce que je veux dire, c'est que… l'Étoile Maléfique est si lointaine qu'il est même Difficile de l'imaginer ou de la décrire."
  },
  AvgDialog_145518_Content_15 = {
    Text = "Mais tout à l'heure, dans les eaux du lac… j'ai cru voir ma sœur, Faint."
  },
  AvgDialog_145518_Content_16 = {
    Text = "Tinct mordit légèrement sa lèvre."
  },
  AvgDialog_145518_Content_17 = {
    Text = "Non, en fait, ce n'est pas vraiment ça… Juste que j'ai ressenti une sorte de présage, et l'ombre dans le lac venait elle aussi de l'Étoile Maléfique…"
  },
  AvgDialog_145518_Content_18 = {
    Text = "Je sais que c'est impossible, mais j'ai l'impression que... <Shake:ce n'était pas une hallucination...>"
  },
  AvgDialog_145518_Content_19 = {
    Text = "Vous semblez très fatigué."
  },
  AvgDialog_145518_Content_2 = {
    Text = "La tempête de neige s'était arrêtée sans qu'on sache quand, ne laissant qu'un silence si vaste qu'il en était vertigineux. Au-dessus, un bleu profond sans le moindre nuage, et même les sommets enneigés au loin se révélaient dans leurs moindres détails."
  },
  AvgDialog_145518_Content_20 = {
    Text = "Evelyn afficha une expression soucieuse."
  },
  AvgDialog_145518_Content_21 = {
    Text = "Si vous vous sentez épuisé, il faut vous reposer à temps."
  },
  AvgDialog_145518_Content_22 = {
    Text = "Nous venons à peine de partir, descendre seul la montagne ne serait pas dangereux."
  },
  AvgDialog_145518_Content_23 = {
    Text = "<Yellow:<Big:Non...! Je ne suis pas fatiguée ! JE NE PARS PAS !>>"
  },
  AvgDialog_145518_Content_24 = {
    Text = "À la surprise générale, Tinct poussa un cri comme sous l'effet d'un choc."
  },
  AvgDialog_145518_Content_25 = {
    Text = "Réalisant que tous les regards étaient posés sur elle, Tinct tenta de se ressaisir, mais sa poitrine qui se soulevait trahissait encore ses véritables sentiments."
  },
  AvgDialog_145518_Content_26 = {
    Text = "Je me suis laissé emporter. Merci de votre sollicitude, <Yellow:je ne suis pas fatiguée.>"
  },
  AvgDialog_145518_Content_27 = {
    Text = "Mentir ne sert à rien."
  },
  AvgDialog_145518_Content_28 = {
    Text = "Je suis déterminée. Je ne resterai pas à la traîne."
  },
  AvgDialog_145518_Content_29 = {
    Text = "Tinct pinça de nouveau les lèvres, jeta un dernier regard au lac de glace, puis se mit en marche pour Partir."
  },
  AvgDialog_145518_Content_3 = {
    Text = "Sous ce ciel dégagé à perte de vue, vous marchez jusqu'au bord d'un lac de glace."
  },
  AvgDialog_145518_Content_30 = {
    Text = "Sur la surface gelée du lac, Seulement son ombre floue se reflétait."
  },
  AvgDialog_145518_Content_31 = {
    Text = "Après une demi-journée de marche, vous trouvâtes un terrain plat pour dresser le camp. Naraka demanda à tous les alpinistes de collecter de la Neige fondue pour faire bouillir de l'eau avec un réchaud de haute altitude."
  },
  AvgDialog_145518_Content_32 = {
    Text = "Mais à votre retour avec la neige ramassée, vous découvrîtes une épaisse fumée s'élevant près du campement."
  },
  AvgDialog_145518_Content_33 = {
    Text = "Hé, à qui appartiennent ces bagages en feu là-bas !"
  },
  AvgDialog_145518_Content_34 = {
    Text = "Hein… ? Non ! ! !"
  },
  AvgDialog_145518_Content_35 = {
    Text = "Les flammes léchaient le petit sac en tissu que Caraboo avait toujours chéri comme un trésor."
  },
  AvgDialog_145518_Content_36 = {
    Text = "Attendez, ce sac de pièces d'or dans votre sac ?"
  },
  AvgDialog_145518_Content_37 = {
    Text = "Sous la morsure des flammes, les pièces d'or s'affaissèrent mollement."
  },
  AvgDialog_145518_Content_38 = {
    Text = "Non ! Ce n'est rien ! Je vais les sauver !"
  },
  AvgDialog_145518_Content_39 = {
    Text = "Non, laissez-moi voir !"
  },
  AvgDialog_145518_Content_4 = {
    Text = "Tinct fixait les eaux du lac, perdue dans ses pensées."
  },
  AvgDialog_145518_Content_40 = {
    Text = "Sous les déchirures, toutes les pièces de chocolat à moitié fondues roulèrent sur le sol."
  },
  AvgDialog_145518_Content_41 = {
    Text = "L'une d'elles roula aux pieds de William, qui se pencha pour la ramasser."
  },
  AvgDialog_145518_Content_42 = {
    Text = "<Blue:Debauve & Gallais, chocolat Pistoles de Marie...>"
  },
  AvgDialog_145518_Content_43 = {
    Text = "Du chocolat ?!"
  },
  AvgDialog_145518_Content_44 = {
    Text = "<Shake:Ha, haha…> Ça… même si ce n'est que du chocolat, c'est quand même très cher !"
  },
  AvgDialog_145518_Content_45 = {
    Text = "Arrête tes bêtises, si tu ne peux pas payer les frais de guide, dégage de mon groupe !"
  },
  AvgDialog_145518_Content_46 = {
    Text = "<Shake:Non, je t'en supplie, je ne connais pas le Chemin toute seule…>"
  },
  AvgDialog_145518_Content_47 = {
    Text = "<Shake:Si tu me chasses du groupe, je mourrai sûrement en descendant la montagne !>"
  },
  AvgDialog_145518_Content_48 = {
    Text = "Va te faire voir, à quoi ça sert de pleurer et de gémir maintenant ? Quand on trompe les gens, il faut assumer d'être démasqué !"
  },
  AvgDialog_145518_Content_49 = {
    Text = "Voyant que Naraka ne cédait ni à la douceur ni à la force, Caraboo regarda autour d'elle, puis Comme Si elle s'agrippait à une bouée de sauvetage, s'effondra à genoux avec un bruit sourd et s'accrocha désespérément à vos jambes."
  },
  AvgDialog_145518_Content_5 = {
    Text = "Il y a quelque chose dans le lac ?"
  },
  AvgDialog_145518_Content_50 = {
    Text = "<Shake:Je vous en supplie, grande âme charitable, vous ne pouvez pas laisser une petite fille descendre la montagne toute seule et abandonnée, n'est-ce pas ?>"
  },
  AvgDialog_145518_Content_51 = {
    Text = "<Shake:Snif, snif, c'est toujours comme ça, je suis toujours abandonnée, où que j'aille, tout le monde me méprise parce que je n'ai rien…>"
  },
  AvgDialog_145518_Content_52 = {
    Text = "<Shake:Bonne personne, grande âme charitable, vous êtes sûrement différent des autres, vous allez m'aider, n'est-ce pas ?>"
  },
  AvgDialog_145518_Content_53 = {
    Text = "Elle leva la tête et vous fixa avec des yeux baignés de larmes."
  },
  AvgDialog_145518_Content_54 = {
    Text = "…Bon, laissez tomber. Ses frais de guide, je vous les paierai une fois en bas."
  },
  AvgDialog_145518_Content_55 = {
    Text = "Incapable de résister à son regard insistant, vous acceptâtes."
  },
  AvgDialog_145518_Content_56 = {
    Text = "<Big:Merci, merci infiniment, mon bienfaiteur !!> Vous êtes le sauveur le plus grand et le plus magnifique que Caraboo ait jamais connu !!"
  },
  AvgDialog_145518_Content_57 = {
    Text = "Caraboo ravala aussitôt ses larmes et bondit en souriant de toutes ses dents."
  },
  AvgDialog_145518_Content_58 = {
    Text = "Bienfaiteur, une fois que j'aurai retrouvé mon pouvoir en tant que déesse de la montagne, je vous rendrai votre bonté au centuple !"
  },
  AvgDialog_145518_Content_59 = {
    Text = "Le moment venu, ne parlons pas de trente pièces d'or, même trois cents, trois mille, je pourrai les payer !"
  },
  AvgDialog_145518_Content_6 = {
    Text = "Non, non, rien, il n'y a rien du tout…"
  },
  AvgDialog_145518_Content_60 = {
    Text = "Bien sûr, bien sûr."
  },
  AvgDialog_145518_Content_61 = {
    Text = "Vous répondez évasivement."
  },
  AvgDialog_145518_Content_62 = {
    Text = "Nous devons tous gravir la montagne ensemble, Tant Que cette affaire se règle rapidement."
  },
  AvgDialog_145518_Content_63 = {
    Text = "La situation se calme enfin, et chacun reprend ses occupations ou se repose."
  },
  AvgDialog_145518_Content_64 = {
    Text = "William vous tire à l'écart et vous parle à voix basse."
  },
  AvgDialog_145518_Content_65 = {
    Text = "C'est étrange, je me souviens que le sac de Caraboo n'était pas à cet endroit avant."
  },
  AvgDialog_145518_Content_66 = {
    Text = "<Red:Qui l'a déplacé près du feu de camp ?>"
  },
  AvgDialog_145518_Content_67 = {
    Text = "L'eau est bouillante. Buvez tous un peu pour vous réchauffer."
  },
  AvgDialog_145518_Content_68 = {
    Text = "Vous avez de la soupe à l'ail ?"
  },
  AvgDialog_145518_Content_69 = {
    Text = "Vous me demandez à moi ? Il n'y a rien de tel. Contentez-vous d'un peu d'eau chaude."
  },
  AvgDialog_145518_Content_7 = {
    Text = "Tinct revint à elle, l'air de vouloir dire quelque chose sans oser le faire."
  },
  AvgDialog_145518_Content_70 = {
    Text = "Hmph, pas d'ail… Vous qui vous prétendez le meilleur guide Sherpa, vous n'êtes pas si impressionnant que ça, et vous prenez des honoraires si élevés en plus."
  },
  AvgDialog_145518_Content_71 = {
    Text = "Voyant que la tension allait de nouveau monter, Evelyn s'empressa d'intervenir."
  },
  AvgDialog_145518_Content_72 = {
    Text = "Si vous voulez quelque chose de chaud, j'ai du chocolat chaud ici."
  },
  AvgDialog_145518_Content_73 = {
    Text = "Et vous, petit, vos provisions ne sont-elles pas un peu insuffisantes ? Je remarque que vous ne mangez pas grand-chose."
  },
  AvgDialog_145518_Content_74 = {
    Text = "Moi ? Ce n'est pas grave, lors de nos retraites spirituelles, nous ne mangeons qu'un repas par jour."
  },
  AvgDialog_145518_Content_75 = {
    Text = "Lors d'une ascension, il est indispensable de reconstituer suffisamment ses forces."
  },
  AvgDialog_145518_Content_76 = {
    Text = "Mon mari, quand il faisait de l'alpinisme, aimait lui aussi toujours porter Les Sacs à Dos les plus légers, tout comme vous."
  },
  AvgDialog_145518_Content_77 = {
    Text = "Depuis qu'il a été bloqué par une tempête de neige pendant plusieurs jours, il a toujours opté pour une stratégie plus prudente."
  },
  AvgDialog_145518_Content_78 = {
    Text = "Votre mari… lui aussi était Alpiniste ?"
  },
  AvgDialog_145518_Content_79 = {
    Text = "Hmm, c'est un excellent Alpiniste, il a déjà tenté l'ascension de l'Everest et du K2."
  },
  AvgDialog_145518_Content_8 = {
    Text = "Après un long silence, elle se tourna vers vous et dit à voix basse."
  },
  AvgDialog_145518_Content_80 = {
    Text = "Et ensuite quoi ?"
  },
  AvgDialog_145518_Content_81 = {Text = "Et alors ?"},
  AvgDialog_145518_Content_82 = {
    Text = "Votre mari, il n'escalade plus les montagnes ?"
  },
  AvgDialog_145518_Content_83 = {
    Text = "<Shake:Hein ? Pourquoi tu me tires par le bras ?>"
  },
  AvgDialog_145518_Content_84 = {
    Text = "Tout le monde suivit son regard vers le côté. Caraboo arborait un sourire sur le visage, mais sa main tirait discrètement la manche de Castor."
  },
  AvgDialog_145518_Content_85 = {
    Text = "Voyant son Action découverte, elle retira sa main avec une légère gêne et marmonna à voix basse."
  },
  AvgDialog_145518_Content_86 = {
    Text = "<Small:Idiot>."
  },
  AvgDialog_145518_Content_87 = {
    Text = "Ce n'est rien…"
  },
  AvgDialog_145518_Content_88 = {
    Text = "Mon mari… il a disparu lors de sa dernière tentative pour atteindre le sommet de l'Everest. Personne ne sait où il est allé. Son corps n'a jamais été retrouvé."
  },
  AvgDialog_145518_Content_89 = {
    Text = "Avant, je l'accompagnais toujours, Juste en attendant aux alentours du camp C2."
  },
  AvgDialog_145518_Content_9 = {
    Text = "Pardonnez-moi, je ne sais pas pourquoi, mais j'ai toujours l'impression de vous connaître depuis longtemps. Alors… pourriez-vous m'écouter un moment ?"
  },
  AvgDialog_145518_Content_90 = {
    Text = "Maintenant qu'il est parti, je veux voir les paysages qu'il a vus…"
  },
  AvgDialog_145518_Content_91 = {
    Text = "Evelyn contemplait la crête des montagnes au loin. Les montagnes de Neige éternelle gardaient le silence, répondant par le Sifflement du vent."
  },
  AvgDialog_145518_Content_92 = {
    Text = "Cette fois, nous atteindrons certainement le sommet."
  },
  AvgDialog_145518_Content_93 = {
    Text = "C'est ce en quoi je crois."
  },
  AvgDialog_145518_Content_94 = {
    Text = "Peu après la conversation, Caraboo retrouva son air détendu et se promena çà et là, les mains dans le dos."
  },
  AvgDialog_145518_Content_95 = {
    Text = "Elle s'approcha de Castor d'un air mystérieux."
  },
  AvgDialog_145518_Content_96 = {
    Text = "Hé, l'idiot, tu n'as pas l'impression que quelqu'un nous suit ?"
  },
  AvgDialog_145518_Content_97 = {
    Text = "Il me semble que non. Tout au long de ce Chemin, j'ai été sur mes gardes contre la surveillance de l'Église des Porteurs de Lumière. Mais vous êtes les premiers que j'ai rencontrés…"
  },
  AvgDialog_145518_Content_98 = {
    Text = "Je n'en ai pas l'impression non plus."
  },
  AvgDialog_145518_Content_99 = {
    Text = "Ah bon ? Alors considérons que j'ai trop imaginé."
  },
  AvgDialog_145519_Content_1 = {Text = "新增"},
  AvgDialog_145519_Content_10 = {
    Text = "Le Miroir de Yata, avec l'épée Kusanagi et le joyau Yasakani no Magatama, est l'un des trois trésors sacrés de la mythologie japonaise. Dans les représentations courantes, le Miroir de Yata est fabriqué en métal, avec des motifs de style japonais gravés au dos."
  },
  AvgDialog_145519_Content_11 = {
    Text = "Mais regardez ce Miroir…"
  },
  AvgDialog_145519_Content_12 = {
    Text = "La surface du Miroir est fine, lisse et polie, de forme parfaitement ronde, semblable à la pleine lune suspendue haut dans le ciel."
  },
  AvgDialog_145519_Content_13 = {
    Text = "Sous la surface froide du verre, on distingue vaguement des particules de lumière colorée qui tourbillonnent."
  },
  AvgDialog_145519_Content_14 = {
    Text = "Quoi qu'il en soit, sortons-le d'abord pour l'examiner."
  },
  AvgDialog_145519_Content_15 = {
    Text = "Naraka souleva un pic à glace et brisa facilement la couche de glace, extrayant le Miroir."
  },
  AvgDialog_145519_Content_16 = {
    Text = "Caraboo bondit en avant, l'arracha d'un geste vif et le glissa rapidement dans son sac à dos."
  },
  AvgDialog_145519_Content_17 = {
    Text = "<Shake:Qu'est-ce que vous faites ! Qu'est-ce que vous regardez, ne me regardez pas !>"
  },
  AvgDialog_145519_Content_18 = {
    Text = "Ce trésor appartient à la déesse de la montagne enneigée, il est donc tout naturel que la découverte me revienne !"
  },
  AvgDialog_145519_Content_19 = {
    Text = "Personne ne tenta de lui disputer la propriété."
  },
  AvgDialog_145519_Content_2 = {
    Text = "Vous errez au bord du lac glacé. La surface du lac est comme un miroir, lisse et immaculée, la vue dégagée à perte de vue — aucune trace de Tinct."
  },
  AvgDialog_145519_Content_20 = {
    Text = "Comparée à un Miroir d'apparence tout à fait ordinaire, la disparition de Tinct méritait manifestement bien plus d'attention."
  },
  AvgDialog_145519_Content_21 = {
    Text = "Pourtant, personne n'aborda plus le sujet. Seulement son ombre pesait encore inévitablement, lourde comme du plomb, sur le cœur de chacun."
  },
  AvgDialog_145519_Content_3 = {
    Text = "Dans le vent qui résonne en Réverbération entre les montagnes enneigées, Comme Si se mêlaient le chant de Tinct et de légers sanglots — présents et absents à la fois, impossible de distinguer le vent de l'Illusion."
  },
  AvgDialog_145519_Content_4 = {
    Text = "Tinct… Elle ne reviendra plus, n'est-ce pas ?"
  },
  AvgDialog_145519_Content_5 = {
    Text = "Personne ne dit le contraire."
  },
  AvgDialog_145519_Content_6 = {
    Text = "Étrange, est-ce que cette chose était là hier ?"
  },
  AvgDialog_145519_Content_7 = {
    Text = "À la surface du lac gelé, enchâssé dans la glace transparente, reposait silencieusement un Miroir parfaitement rond."
  },
  AvgDialog_145519_Content_8 = {
    Text = "<Shake:Le Miroir de Yata ! C'est le Miroir de Yata qui doit être offert à la déesse de la montagne !>"
  },
  AvgDialog_145519_Content_9 = {
    Text = "William, vous semblez avoir quelque chose à dire mais vous retenez vos mots."
  },
  AvgDialog_145520_Content_1 = {
    Text = "Septième Voyageur"
  },
  AvgDialog_145520_Content_10 = {
    Text = "Ces prochains jours, il n'y a pas d'autres expéditions, vous pouvez vous reposer ici tranquillement, personne ne viendra vous déranger —"
  },
  AvgDialog_145520_Content_100 = {
    Text = "Attention ! Quelque chose remonte à la surface !"
  },
  AvgDialog_145520_Content_11 = {
    Text = "Avant même que Naraka ait fini de parler, un bruissement se fit soudainement entendre dans un coin de la grotte."
  },
  AvgDialog_145520_Content_12 = {
    Text = "… Hein, quelqu'un ?"
  },
  AvgDialog_145520_Content_13 = {
    Text = "La voix de William résonna dans la grotte, sans obtenir de réponse."
  },
  AvgDialog_145520_Content_14 = {
    Text = "Nous faisons partie d'une expédition, nous venons ici pour nous abriter du vent et de la neige, nous n'avons pas de mauvaises intentions."
  },
  AvgDialog_145520_Content_15 = {
    Text = "Vous émettez des signaux amicaux et vous avancez derrière les rochers en tenant votre lampe."
  },
  AvgDialog_145520_Content_16 = {
    Text = "Attention !"
  },
  AvgDialog_145520_Content_17 = {
    Text = "La silhouette derrière les rochers se raidit brusquement. Sans laisser le temps aux autres d'expliquer, une attaque féroce surgit des ténèbres."
  },
  AvgDialog_145520_Content_19 = {
    Text = "Peut-être parce qu'il faisait face à plusieurs adversaires, l'assaillant lança une embuscade avant de se fondre à nouveau dans l'ombre en un instant. Mais vous aviez tout de même reconnu cette silhouette lors du bref affrontement."
  },
  AvgDialog_145520_Content_2 = {
    Text = "Après que Naraka vous a guidés un moment, une fissure noire apparaît dans la montagne."
  },
  AvgDialog_145520_Content_20 = {
    Text = "<Shake:Castor ?!>"
  },
  AvgDialog_145520_Content_21 = {
    Text = "Après un moment, une cape noire émergea de l'ombre, et derrière elle, la moitié d'un visage à l'expression méfiante se montra."
  },
  AvgDialog_145520_Content_22 = {
    Text = "… Vous me connaissez ?"
  },
  AvgDialog_145520_Content_23 = {
    Text = "Non, c'est une très longue histoire à raconter…"
  },
  AvgDialog_145520_Content_24 = {
    Text = "Alors, pourquoi êtes-vous seul ici ?"
  },
  AvgDialog_145520_Content_25 = {Text = "新增"},
  AvgDialog_145520_Content_26 = {Text = "新增"},
  AvgDialog_145520_Content_27 = {
    Text = "Eh bien, mon frère — Pollux et moi avions convenu de fuir l'Église des Porteurs de Lumière chacun à notre manière, l'un après l'autre. Mais j'ai attendu un mois à l'endroit convenu, et il n'est pas apparu."
  },
  AvgDialog_145520_Content_28 = {
    Text = "Je pense que mon départ a dû pousser Madame Juliette à renforcer la surveillance. Depuis lors, je cherche sans cesse un moyen de le sauver."
  },
  AvgDialog_145520_Content_29 = {
    Text = "<Yellow:Heureusement, je me suis bien cachée et j'ai réussi à échapper à leurs traqueurs.>"
  },
  AvgDialog_145520_Content_3 = {Text = "Entrons."},
  AvgDialog_145520_Content_30 = {
    Text = "Finalement, j'ai entendu dire qu'au sommet de la montagne de Neige résidait une Divinité capable d'exaucer tous les vœux."
  },
  AvgDialog_145520_Content_31 = {
    Text = "Mais je ne peux rejoindre aucune expédition… Les espions de l'Église sont partout, et si je me montre trop souvent, je risque d'être découverte."
  },
  AvgDialog_145520_Content_32 = {Text = "Idiote."},
  AvgDialog_145520_Content_33 = {Text = "Ah… ?"},
  AvgDialog_145520_Content_34 = {
    Text = "Je n'ai jamais vu quelqu'un d'aussi stupide que vous."
  },
  AvgDialog_145520_Content_35 = {
    Text = "Même si tu escalades la montagne seule, où comptes-tu trouver les sept artefacts ?"
  },
  AvgDialog_145520_Content_36 = {Text = "新增"},
  AvgDialog_145520_Content_37 = {
    Text = "Je n'y avais pas réfléchi…"
  },
  AvgDialog_145520_Content_38 = {
    Text = "Exactement ! Et maintenant, tu as besoin de l'aide de la déesse de la Neige."
  },
  AvgDialog_145520_Content_39 = {
    Text = "Allez, tant que tu rejoins L'Ordre Sacré, je te promets qu'une fois au sommet, je t'aiderai à mettre fin à ta Séparation d'avec ton frère !"
  },
  AvgDialog_145520_Content_4 = {
    Text = "Vous vous soutenez mutuellement pour descendre les rochers escarpés, et vous vous retournez vers l'entrée de la grotte."
  },
  AvgDialog_145520_Content_40 = {Text = "Vraiment ?"},
  AvgDialog_145520_Content_41 = {
    Text = "Bien sûr que c'est vrai ! On ne peut pas faire plus vrai !"
  },
  AvgDialog_145520_Content_42 = {
    Text = "Mais pour témoigner de ta sincérité envers L'Ordre Sacré, tous les trésors que tu portes sur toi devront être remis à la fée pour qu'elle les garde à ta place."
  },
  AvgDialog_145520_Content_43 = {
    Text = "...D'accord."
  },
  AvgDialog_145520_Content_44 = {
    Text = "Castor hésita longuement, puis sortit quelques pièces de monnaie et un Livre de Contes tout usé à force d'avoir été feuilleté."
  },
  AvgDialog_145520_Content_45 = {
    Text = "C'est tout ce que j'ai. Est-ce que je peux quand même rejoindre ?"
  },
  AvgDialog_145520_Content_46 = {
    Text = "William vous donna une tape sur le bras."
  },
  AvgDialog_145520_Content_47 = {
    Text = "Vous en avez assez vu comme spectacle ?"
  },
  AvgDialog_145520_Content_48 = {
    Text = "Euh, bon, Castor, bienvenue dans notre équipe d'exploration."
  },
  AvgDialog_145520_Content_49 = {
    Text = "Caraboo plaisantait, tant que tu apportes tes propres provisions, tu n'as rien d'autre à remettre."
  },
  AvgDialog_145520_Content_5 = {
    Text = "La fissure est étroite et régulière, semblable à un œil mi-clos, tenant à l'écart le vent et la neige."
  },
  AvgDialog_145520_Content_50 = {
    Text = "Hmph, même la déesse des neiges ne daignerait pas regarder cette maigre Offrande. Gardez-la pour vous."
  },
  AvgDialog_145520_Content_51 = {
    Text = "Castor lissa soigneusement les plis du Livre de Contes avec précaution, puis le rangea délicatement contre sa poitrine."
  },
  AvgDialog_145520_Content_52 = {
    Text = "Puis il jeta un coup d'œil aux quelques pièces, son regard errant parmi vous tous."
  },
  AvgDialog_145520_Content_53 = {
    Text = "Si personne n'en veut, alors je les accepte avec plaisir."
  },
  AvgDialog_145520_Content_54 = {
    Text = "Naraka fit un geste de la main, et la pierre fut instantanément vide."
  },
  AvgDialog_145520_Content_55 = {
    Text = "Les frais de guide de ce jeune homme sont bien moins chers que ceux des autres."
  },
  AvgDialog_145520_Content_56 = {
    Text = "Si je ne me trompe pas, nous avons déjà payé vos frais de guide."
  },
  AvgDialog_145520_Content_57 = {
    Text = "S'il faut absolument en payer une part supplémentaire, je m'en chargerai pour lui."
  },
  AvgDialog_145520_Content_58 = {
    Text = "Ce n'est pas nécessaire, nous ne nous connaissons pas, je ne voudrais pas vous déranger…"
  },
  AvgDialog_145520_Content_59 = {
    Text = "La main tendue d'Evelyn interrompit les paroles de Castor ; ce dernier hésita une demi-seconde, puis lui rendit sa poignée de main."
  },
  AvgDialog_145520_Content_6 = {
    Text = "Intérieur… tellement chaud…"
  },
  AvgDialog_145520_Content_60 = {
    Text = "Evelyn, je m'appelle Evelyn, je suis archéologue."
  },
  AvgDialog_145520_Content_61 = {
    Text = "Maintenant, on ne peut plus dire qu'on ne se connaît pas, n'est-ce pas ?"
  },
  AvgDialog_145520_Content_62 = {Text = "新增"},
  AvgDialog_145520_Content_63 = {
    Text = "La tempête de neige vous retient tous dans l'étroite caverne. Sans feu pour l'instant, la conversation est votre seule défense contre le froid."
  },
  AvgDialog_145520_Content_64 = {
    Text = "Vous avez dit tout à l'heure que vous cherchiez votre frère jumeau, c'est bien ça ?"
  },
  AvgDialog_145520_Content_65 = {Text = "Bien."},
  AvgDialog_145520_Content_66 = {
    Text = "Castor hocha la tête avec prudence."
  },
  AvgDialog_145520_Content_67 = {
    Text = "Quelle coïncidence, moi aussi je cherche ma sœur jumelle."
  },
  AvgDialog_145520_Content_68 = {
    Text = "Faint et moi, nous sommes très différentes. Ma sœur aînée, bien que de santé fragile, est en réalité quelqu'un de courageux et de fort."
  },
  AvgDialog_145520_Content_69 = {
    Text = "En évoquant sa sœur jumelle, Tinct, qui semblait toujours perdue dans ses pensées, parut soudain s'animer, laissant apparaître un léger sourire."
  },
  AvgDialog_145520_Content_7 = {
    Text = "Hah, hah, moi qui suis la déesse de la montagne enneigée, comment se fait-il que j'ignore l'existence d'un tel endroit ?"
  },
  AvgDialog_145520_Content_70 = {
    Text = "Et Celui-là, Pollux ? Quel genre de personne est-il ?"
  },
  AvgDialog_145520_Content_71 = {
    Text = "<Shake:Pollux…>"
  },
  AvgDialog_145520_Content_72 = {
    Text = "Il n'est pas vraiment comme moi non plus. Il est intelligent, vif, et très perspicace. Depuis l'enfance, le Maître et les professeurs l'ont toujours préféré…"
  },
  AvgDialog_145520_Content_73 = {
    Text = "Ne t'inquiète pas. Tu as aussi tes qualités. Par exemple, tu ne viens pas de dire que tu as réussi à échapper aux traqueurs de l'Église ? C'est déjà très impressionnant."
  },
  AvgDialog_145520_Content_74 = {
    Text = "Castor rougit légèrement, toussa une fois, et ramena la conversation sur Tinct."
  },
  AvgDialog_145520_Content_75 = {
    Text = "Toi et ta sœur, pourquoi vous êtes-vous séparées ?"
  },
  AvgDialog_145520_Content_76 = {
    Text = "Au moment de fuir, elle m'a laissé le dernier billet de bateau."
  },
  AvgDialog_145520_Content_77 = {
    Text = "Sa voix était très douce, Comme Si le moindre effort aurait suffi à disperser ce souvenir dans le vent et la neige."
  },
  AvgDialog_145520_Content_78 = {
    Text = "Espérons qu'à la fin, nous pourrons tous les retrouver."
  },
  AvgDialog_145520_Content_79 = {
    Text = "Castor garda le Silence un moment, Le Regard dépassant Elle, se posant sur la tempête blanche qui tourbillonnait sans cesse à l'entrée de la caverne."
  },
  AvgDialog_145520_Content_8 = {
    Text = "C'est bien normal, les frais de guide d'un Sherpa ne sont pas payés pour rien."
  },
  AvgDialog_145520_Content_80 = {
    Text = "Au fil de la conversation, le temps s'écoula seconde après seconde."
  },
  AvgDialog_145520_Content_81 = {Text = "新增"},
  AvgDialog_145520_Content_82 = {
    Text = "À la septième heure, la tempête atteint un pic presque malveillant."
  },
  AvgDialog_145520_Content_83 = {
    Text = "Il semblerait que nous allons passer la nuit dans cette caverne."
  },
  AvgDialog_145520_Content_84 = {
    Text = "Naraka écarta les restes déjà humides au centre de la caverne et tenta d'allumer un nouveau feu avec du bois mort."
  },
  AvgDialog_145520_Content_85 = {
    Text = "Des ténèbres au fond de la caverne provenait un bruit ténu et frêle, comme si quelque chose grattait la paroi rocheuse avec ses ongles."
  },
  AvgDialog_145520_Content_86 = {
    Text = "Des souris ?"
  },
  AvgDialog_145520_Content_87 = {
    Text = "À cette altitude, il ne devrait pas y avoir de souris…"
  },
  AvgDialog_145520_Content_88 = {
    Text = "Le bruit s'arrêta soudainement. Le Silence à l'intérieur de la caverne était oppressant."
  },
  AvgDialog_145520_Content_89 = {
    Text = "Des ténèbres si épaisses qu'aucun rayon de lumière ne pouvait les traverser, une malveillance surgit Face à soi."
  },
  AvgDialog_145520_Content_9 = {
    Text = "Les anciens disent que cette fissure est apparue soudainement après une avalanche."
  },
  AvgDialog_145520_Content_90 = {
    Text = "Naraka leva sa torche et l'orienta vers les Profondeurs de la caverne en suivant le son. La lueur n'avança que de quelques pas avant d'être engloutie par les ténèbres devant elle."
  },
  AvgDialog_145520_Content_91 = {
    Text = "N'y va pas."
  },
  AvgDialog_145520_Content_92 = {
    Text = "Je veux juste jeter un coup d'œil."
  },
  AvgDialog_145520_Content_93 = {
    Text = "Naraka s'appuya contre la paroi rocheuse et se pencha prudemment en avant."
  },
  AvgDialog_145520_Content_94 = {
    Text = "La lueur vacillante des flammes dépassa le rebord de pierre sous ses pieds, révélant une mare d'un noir absolu en contrebas. La surface de l'eau était si lisse qu'elle ne formait pas la moindre ride, se fondant Presque avec les ombres environnantes."
  },
  AvgDialog_145520_Content_95 = {
    Text = "En Dessous, il y a de l'eau. <Shake:On dirait que c'est très profond —>"
  },
  AvgDialog_145520_Content_96 = {
    Text = "Avant même que les mots ne s'éteignent, cette «surface d'eau» d'un noir absolu s'affaissa soudainement."
  },
  AvgDialog_145520_Content_97 = {
    Text = "Naraka perdit l'équilibre, et la moitié d'un pied avait déjà glissé dans la brèche qui s'était brusquement élargie."
  },
  AvgDialog_145520_Content_98 = {
    Text = "<Shake:Attrapez-moi — !>"
  },
  AvgDialog_145520_Content_99 = {
    Text = "Vous le saisîtes brusquement par le col et le tirâtes violemment en arrière."
  },
  AvgDialog_145521_Content_1 = {
    Text = "Au Coin du Feu, Après la Nuit Tombée"
  },
  AvgDialog_145521_Content_10 = {
    Text = "Dans un coin s'entassaient quelques caisses en bois moisies, et plus loin sur la paroi rocheuse, un tronçon de chaîne en fer brisée avait été cloué."
  },
  AvgDialog_145521_Content_100 = {
    Text = "Il ferma les Yeux, sentant sous ses doigts les contours qu'il parcourait."
  },
  AvgDialog_145521_Content_101 = {
    Text = "<Small:<Italic:...«Le villain jeta un sort et transforma son petit frère en corbeau.»>>"
  },
  AvgDialog_145521_Content_102 = {
    Text = "<Small:<Italic:...«Mais le frère aîné connaissait la couleur de ses ailes.»>>"
  },
  AvgDialog_145521_Content_103 = {
    Text = "La flamme vacilla un instant, puis s'éteignit."
  },
  AvgDialog_145521_Content_104 = {
    Text = "Puis-je vous ramener ?"
  },
  AvgDialog_145521_Content_105 = {
    Text = "La prochaine fois que nous nous reverrons, serez-vous encore capable de me reconnaître ?"
  },
  AvgDialog_145521_Content_106 = {Text = "新增"},
  AvgDialog_145521_Content_107 = {
    Text = "Longtemps après, il ferma le livre, se leva, et se dirigea silencieusement vers l'entrée de la grotte pour dégager les fissures de ventilation obstruées par la neige nocturne."
  },
  AvgDialog_145521_Content_108 = {
    Text = "La neige s'écoula entre ses doigts et tomba sur le petit tas déjà accumulé, sans le moindre bruit."
  },
  AvgDialog_145521_Content_109 = {
    Text = "L'aube n'était pas encore levée."
  },
  AvgDialog_145521_Content_11 = {
    Text = "Quelqu'un a vécu ici autrefois ?"
  },
  AvgDialog_145521_Content_110 = {
    Text = "Vous fûtes réveillé par la faible lueur qui filtrait à travers l'entrée de la grotte."
  },
  AvgDialog_145521_Content_111 = {
    Text = "Castor avait déjà rassemblé Les Sacs à Dos et se tenait à l'entrée de la grotte, attendant que vous vous réveilliez."
  },
  AvgDialog_145521_Content_112 = {
    Text = "Désolé, je suis sur le point de partir."
  },
  AvgDialog_145521_Content_113 = {
    Text = "Mon souhait est différent du vôtre."
  },
  AvgDialog_145521_Content_114 = {
    Text = "Je veux retrouver mon frère, et je peux y parvenir par mes propres mains."
  },
  AvgDialog_145521_Content_115 = {
    Text = "Mais ce chemin est bien trop dangereux, seul vous—"
  },
  AvgDialog_145521_Content_116 = {
    Text = "…Il y a encore une chose, j'hésitais à vous la dire. Mais il est temps d'être honnête—"
  },
  AvgDialog_145521_Content_117 = {
    Text = "Castor inspira profondément, comme s'il prenait une grande décision."
  },
  AvgDialog_145521_Content_118 = {
    Text = "Lors de notre première rencontre, Tinct a dit que, même si je n'étais pas aussi sympathique que Pollux, j'avais mes propres qualités : je pouvais échapper seul aux traqueurs de l'Église des Porteurs de Lumière."
  },
  AvgDialog_145521_Content_119 = {
    Text = "Mais c'était faux. C'était pour vous tromper."
  },
  AvgDialog_145521_Content_12 = {
    Text = "C'était un point de refuge pour une vieille équipe d'alpinistes, abandonné depuis de nombreuses années. L'emplacement du feu de camp est par là, je vais le dégager."
  },
  AvgDialog_145521_Content_120 = {
    Text = "Je suis bien plus faible que vous ne le pensez, et je n'y suis pas parvenu."
  },
  AvgDialog_145521_Content_121 = {
    Text = "Les fidèles sont constamment à mes trousses. Si je reste, je vous serai un fardeau à tous."
  },
  AvgDialog_145521_Content_122 = {
    Text = "Il leva la tête et regarda vers le fond de la grotte, là où les autres dormaient encore."
  },
  AvgDialog_145521_Content_123 = {
    Text = "Le symbole abîmé dans la grotte, je l'ai reconnu — c'est le symbole de l'Église des Porteurs de Lumière."
  },
  AvgDialog_145521_Content_124 = {
    Text = "C'est leur base Temporaire."
  },
  AvgDialog_145521_Content_125 = {
    Text = "Plus on monte, plus c'est dégagé. Ils finiraient par me découvrir. Autant partir maintenant et me fondre dans la foule — c'est la meilleure façon d'échapper à leur Poursuite."
  },
  AvgDialog_145521_Content_126 = {
    Text = "Il se retourna et s'enfonça dans la tempête de Neige et de vent."
  },
  AvgDialog_145521_Content_127 = {
    Text = "Vous restâtes immobile à le regarder longtemps, jusqu'à ce que sa silhouette disparaisse complètement."
  },
  AvgDialog_145521_Content_128 = {
    Text = "De légers pas se firent entendre derrière vous."
  },
  AvgDialog_145521_Content_129 = {
    Text = "Caraboo s'était levée sans qu'on s'en aperçoive, appuyée contre l'entrée de la grotte, regardant dans la direction où Castor était parti."
  },
  AvgDialog_145521_Content_13 = {
    Text = "Il se dirigea d'un pas assuré vers une dalle de pierre noircie par la fumée au centre de la caverne, s'accroupit et Commença à déblayer les vieilles Cendres."
  },
  AvgDialog_145521_Content_130 = {Text = "…Idiot."},
  AvgDialog_145521_Content_131 = {
    Text = "Dans sa voix, il n'y avait pas l'Épine habituelle."
  },
  AvgDialog_145521_Content_132 = {
    Text = "L'équipe d'alpinisme était passée de cinq à quatre membres."
  },
  AvgDialog_145521_Content_14 = {
    Text = "Le Regard de Castor s'attarda brièvement sur les gravures murales. Il ne dit rien, Juste détourna les yeux."
  },
  AvgDialog_145521_Content_15 = {
    Text = "Avant même d'avoir eu le temps de poser une question, l'Appel de Caraboo attira le regard de tous."
  },
  AvgDialog_145521_Content_16 = {
    Text = "<Big:Une grotte bien chaude ! Un feu de camp ! Un long Repos !>"
  },
  AvgDialog_145521_Content_17 = {
    Text = "Caraboo débordait d'Excitation."
  },
  AvgDialog_145521_Content_18 = {
    Text = "Bien que tout le monde fît semblant de tenir le coup, Vous pouviez voir que chacun était épuisé par le combat contre le Wendigo."
  },
  AvgDialog_145521_Content_19 = {
    Text = "Une grotte parfaitement adaptée. Un repos parfaitement mérité."
  },
  AvgDialog_145521_Content_2 = {
    Text = "La tempête de neige ne s'était pas calmée. Vous longez les fissures dans la glace à la recherche d'un abri, et finissez par trouver une cavité dans la neige, à l'abri du vent, au pied d'une paroi rocheuse."
  },
  AvgDialog_145521_Content_20 = {
    Text = "Quels que soient les dangers qui se tapissent devant vous, rien ne peut vous empêcher de profiter d'un moment de tranquillité."
  },
  AvgDialog_145521_Content_21 = {
    Text = "Le feu brûle à l'intérieur de l'entrée de la grotte, près du bord. La fumée est emportée vers l'extérieur par un vent oblique."
  },
  AvgDialog_145521_Content_22 = {
    Text = "Evelyn sortit de son sac à dos un tapis isolant, pressa d'abord une fine couche de neige sur le sol, puis étendit le tapis par-dessus."
  },
  AvgDialog_145521_Content_23 = {
    Text = "Tout le monde ôta ses vêtements extérieurs gelés et rigides, se rassembla autour du feu, tendant les mains le plus près possible des flammes."
  },
  AvgDialog_145521_Content_24 = {
    Text = "Ce serait bien s'il faisait toujours aussi chaud sur la montagne."
  },
  AvgDialog_145521_Content_25 = {Text = "Pfft."},
  AvgDialog_145521_Content_26 = {
    Text = "De quoi ris-tu ?"
  },
  AvgDialog_145521_Content_27 = {
    Text = "Je ris de toi, espèce d'idiot, qui ne sais pas peser tes mots. Et si la déesse de la montagne de neige prenait ça pour ton vœu le plus cher et l'exauçait ?"
  },
  AvgDialog_145521_Content_28 = {
    Text = "Ce serait bien aussi. Dans ce cas, les alpinistes seraient bien plus en sécurité."
  },
  AvgDialog_145521_Content_29 = {
    Text = "La lueur du feu de camp se reflétait dans les yeux sérieux de Castor."
  },
  AvgDialog_145521_Content_3 = {
    Text = "L'entrée était étroite, mais l'intérieur s'avérait étonnamment spacieux."
  },
  AvgDialog_145521_Content_30 = {
    Text = "Laisse tomber, c'est sans intérêt de te taquiner, espèce d'idiot."
  },
  AvgDialog_145521_Content_31 = {
    Text = "Caraboo, toi, tu as un vœu ?"
  },
  AvgDialog_145521_Content_32 = {
    Text = "Caraboo sembla ne pas s'attendre à être interrogée si soudainement ; après un moment de surprise, ses yeux se mirent à rouler."
  },
  AvgDialog_145521_Content_33 = {
    Text = "Je suis la déesse de la montagne de neige, c'est moi qui suis chargée d'exaucer vos vœux !"
  },
  AvgDialog_145521_Content_34 = {
    Text = "Si je devais formuler un vœu, ce serait de récupérer mon sceptre."
  },
  AvgDialog_145521_Content_35 = {
    Text = "Oui ! Exactement ! Une fois mon sceptre récupéré, je vais réorganiser L'Ordre Sacré ! Et faire venir tout le continent pour rendre Offrande à la déesse de la montagne de neige !"
  },
  AvgDialog_145521_Content_36 = {
    Text = "Evelyn laisse échapper un doux rire. La lueur des flammes vacille dans ses yeux sombres."
  },
  AvgDialog_145521_Content_37 = {
    Text = "Que dire des autres ?"
  },
  AvgDialog_145521_Content_38 = {
    Text = "Elle se tourna vers vous, son regard dépourvu de toute curiosité, exprimant seulement la sollicitude d'un Bavardage ordinaire."
  },
  AvgDialog_145521_Content_39 = {
    Text = "Je suis curieuse aussi ! Quel genre de vœu devrais-je exaucer pour mon bienfaiteur ?"
  },
  AvgDialog_145521_Content_4 = {
    Text = "N'entrez pas encore."
  },
  AvgDialog_145521_Content_40 = {
    Text = "Quelqu'un m'a indiqué un Chemin pour rentrer à Notre Foyer. Pour y retourner, je dois retrouver quelqu'un."
  },
  AvgDialog_145521_Content_41 = {
    Text = "Vous êtes aussi un idiot. Pourquoi ne pas simplement faire un vœu pour rentrer ?"
  },
  AvgDialog_145521_Content_42 = {
    Text = "Quelqu'un a écrit une Prédiction pour moi."
  },
  AvgDialog_145521_Content_43 = {
    Text = "<Yellow:Le Destin est une trame dont les mailles s'enchaînent les unes aux autres. Celui qui tente de sauter un nœud pour atteindre directement la fin devra endurer la souffrance du fil rompu.>"
  },
  AvgDialog_145521_Content_44 = {
    Text = "Je comprends. Et ce monsieur William à vos côtés ?"
  },
  AvgDialog_145521_Content_45 = {
    Text = "L'histoire de William est un peu complexe à raconter."
  },
  AvgDialog_145521_Content_46 = {
    Text = "Du moins pour l'instant, la chose la plus importante pour moi est d'accompagner %player% jusqu'à Mizag, pour retrouver Ramona."
  },
  AvgDialog_145521_Content_47 = {
    Text = "Vous regardez William avec stupéfaction. Son visage est serein, et vous ne trouvez pas la moindre trace de mensonge dans ses micro-expressions."
  },
  AvgDialog_145521_Content_48 = {
    Text = "Inutile de me dévisager ainsi."
  },
  AvgDialog_145521_Content_49 = {
    Text = "<Yellow:Mes autres obligations en ce monde ont temporairement pris fin.>"
  },
  AvgDialog_145521_Content_5 = {
    Text = "Il leva son piolet et frappa centimètre par centimètre le long du plafond à l'intérieur de l'entrée."
  },
  AvgDialog_145521_Content_50 = {
    Text = "En prononçant ces mots, William leva délibérément la main pour écarter les mèches qui lui couvraient les yeux, dissimulant ainsi la majeure partie de son expression."
  },
  AvgDialog_145521_Content_51 = {
    Text = "Et vous, l'idiot ?"
  },
  AvgDialog_145521_Content_52 = {Text = "Moi ?"},
  AvgDialog_145521_Content_53 = {
    Text = "Castor regardait fixement le feu de camp, l'air absent."
  },
  AvgDialog_145521_Content_54 = {
    Text = "Je veux que Pollux… revienne."
  },
  AvgDialog_145521_Content_55 = {
    Text = "Caraboo leva les yeux vers Castor, et cette petite touche de cynisme habituel dans son regard disparut brièvement."
  },
  AvgDialog_145521_Content_56 = {
    Text = "Vous venez de dire que vous voulez qu'il revienne."
  },
  AvgDialog_145521_Content_57 = {
    Text = "Mais lors de notre première rencontre, vous avez dit que vous vouliez le sauver."
  },
  AvgDialog_145521_Content_58 = {
    Text = "Il y a une subtile différence entre ces deux formulations… mais il n'est pas impossible de les concilier."
  },
  AvgDialog_145521_Content_59 = {
    Text = "Castor, votre frère, a-t-il vraiment été emprisonné par ce fameux chef de secte ?"
  },
  AvgDialog_145521_Content_6 = {
    Text = "Ce bloc est Lâche, évitez de camper juste en dessous."
  },
  AvgDialog_145521_Content_60 = {
    Text = "Un bref Silence. Caraboo reprit la Pomme et en croqua une nouvelle bouchée, changeant de sujet comme si de rien n'était."
  },
  AvgDialog_145521_Content_61 = {
    Text = "En fait, réaliser un vœu, c'est très simple."
  },
  AvgDialog_145521_Content_62 = {
    Text = "Vous voyez, parmi ces sept trésors, il y a bien une plume, n'est-ce pas ? Peut-être que la plume que vous portez est la <Yellow:Plume de Ma'at>."
  },
  AvgDialog_145521_Content_63 = {
    Text = "Ma'at, déesse de la vérité, de l'ordre et de la justice, coiffée d'une plume d'autruche."
  },
  AvgDialog_145521_Content_64 = {
    Text = "Lors du jugement des morts, Anubis place le cœur du défunt sur une balance face à cette plume. Si le cœur est plus lourd que la plume, il est dévoré par le monstre Ammit ; si le cœur est aussi léger que la plume, le défunt peut entrer dans le Champ des Roseaux."
  },
  AvgDialog_145521_Content_65 = {
    Text = "La plume représente «l'innocence» dans la mythologie égyptienne."
  },
  AvgDialog_145521_Content_66 = {
    Text = "La plume de l'innocence… quelle ironie."
  },
  AvgDialog_145521_Content_67 = {
    Text = "Castor esquissa un sourire légèrement résigné."
  },
  AvgDialog_145521_Content_68 = {
    Text = "Ces ailes, c'est Juliette, la grande prêtresse de l'Église des Porteurs de Lumière, qui les a implantées à mon frère et à moi afin de créer sa divinité."
  },
  AvgDialog_145521_Content_69 = {
    Text = "Dans son récit, vous entendîtes une voix. La voix d'une douleur impossible à réprimer."
  },
  AvgDialog_145521_Content_7 = {
    Text = "Il se courba et s'avança vers le fond de la caverne, s'accroupit pour coller son oreille au sol un moment, puis testa l'humidité de la paroi rocheuse avec le dos de la main."
  },
  AvgDialog_145521_Content_70 = {
    Text = "Plus Tard, elle arracha aussi les ailes de Pollux. À présent, je suis le seul à porter encore ces ailes de Profanation."
  },
  AvgDialog_145521_Content_71 = {
    Text = "Castor caressait doucement les plumes à l'extrémité de ses ailes, et vous eûtes soudain l'impression qu'elles étaient maculées de Sang."
  },
  AvgDialog_145521_Content_72 = {
    Text = "Alors, parler d'innocence… ces ailes sont peut-être ce qui en est le plus éloigné."
  },
  AvgDialog_145521_Content_73 = {
    Text = "Le silence s'installa, troublé seulement par le crépitement du feu de camp."
  },
  AvgDialog_145521_Content_74 = {
    Text = "Naraka, et vous, quel est votre vœu ?"
  },
  AvgDialog_145521_Content_75 = {
    Text = "William se tourna brusquement vers Naraka, qui se réchauffait près du feu et ne semblait pas avoir l'intention de se joindre à la conversation."
  },
  AvgDialog_145521_Content_76 = {
    Text = "Je suis Juste un guide, je n'ai pas l'intention de formuler un vœu avec vous."
  },
  AvgDialog_145521_Content_77 = {
    Text = "S'il fallait absolument parler du <Yellow:vœu de Naraka>, il souhaiterait peut-être que le nom des guides Sherpa figure lui aussi dans les annales des alpinistes."
  },
  AvgDialog_145521_Content_78 = {
    Text = "Mais réaliser un tel vœu par un miracle serait bien trop ennuyeux, n'est-ce pas ?"
  },
  AvgDialog_145521_Content_79 = {
    Text = "Falsifier et réécrire des livres pour fabriquer des mensonges à travers l'Historique, c'est trop simple, trop facile — si facile que cela en perd toute valeur."
  },
  AvgDialog_145521_Content_8 = {
    Text = "Entrez, l'Intérieur devrait être sûr."
  },
  AvgDialog_145521_Content_80 = {
    Text = "Atteindre le sommet, cela doit se faire avec ses propres jambes."
  },
  AvgDialog_145521_Content_81 = {
    Text = "Par soi-même…"
  },
  AvgDialog_145521_Content_82 = {
    Text = "Castor sembla ressentir quelque chose."
  },
  AvgDialog_145521_Content_83 = {
    Text = "Hé — vous ne ressemblez vraiment pas à quelqu'un qui tient ce genre de discours sensé."
  },
  AvgDialog_145521_Content_84 = {
    Text = "Caraboo se pinça le nez en agitant la main, Comme Si elle avait senti une mauvaise odeur."
  },
  AvgDialog_145521_Content_85 = {
    Text = "Place aux aveux sincères, arrêtez de jouer la comédie, parlons franchement ?"
  },
  AvgDialog_145521_Content_86 = {
    Text = "Elle fixa les Yeux de Naraka avec un sourire amusé. Naraka détourna Le Regard, alors Elle se pencha en avant, Le Regard rivé sur lui sans le lâcher."
  },
  AvgDialog_145521_Content_87 = {
    Text = "<Shake:Allez, montre-moi ton vrai visage !>"
  },
  AvgDialog_145521_Content_88 = {
    Text = "Caraboo bondit en avant, cherchant à attraper Naraka comme un aigle fondant sur sa proie, mais Naraka esquiva simplement d'un léger mouvement de côté."
  },
  AvgDialog_145521_Content_89 = {
    Text = "Arrêtez de vous agiter, demain il faut reprendre le Chemin. Je ne voudrais pas que vous n'atteigniez pas le sommet."
  },
  AvgDialog_145521_Content_9 = {
    Text = "Des motifs décolorés subsistaient sur la paroi rocheuse, semblables aux contours d'une sorte de symbole dont la peinture s'était depuis longtemps écaillée, rendant toute identification impossible."
  },
  AvgDialog_145521_Content_90 = {
    Text = "Caraboo manqua sa cible et profita de son élan pour s'asseoir dans la Neige, souriant de toutes ses dents."
  },
  AvgDialog_145521_Content_91 = {
    Text = "Puisque vous voulez aussi nous voir atteindre le sommet, je suis rassurée."
  },
  AvgDialog_145521_Content_92 = {Text = "新增"},
  AvgDialog_145521_Content_93 = {
    Text = "Le feu de camp brûle jusqu'au cœur de la nuit, réduit à quelques braises de lumière rouge éparpillées."
  },
  AvgDialog_145521_Content_94 = {
    Text = "Naraka organisa les tours de garde nocturnes, deux heures par personne.\nLes uns après les autres, tout le monde s'endormit. De légers ronflements étouffés s'échappaient des sacs de couchage."
  },
  AvgDialog_145521_Content_95 = {
    Text = "Castor prit naturellement le premier tour. Il s'adossa à la paroi de la grotte et, depuis les profondeurs de Les Sacs à Dos, sortit un petit livre dont les coins étaient usés jusqu'à blanchir."
  },
  AvgDialog_145521_Content_96 = {
    Text = "C'était un Livre de Contes."
  },
  AvgDialog_145521_Content_97 = {
    Text = "Ses doigts effleurèrent les deux noms inscrits sur la page de garde."
  },
  AvgDialog_145521_Content_98 = {
    Text = "L'écriture soignée d'un enfant était la sienne ; l'autre était tracée en zigzag au crayon de cire rouge, sa couleur s'estompant peu à peu sous les caresses du temps."
  },
  AvgDialog_145521_Content_99 = {Text = "Pollux…"},
  AvgDialog_145522_Content_1 = {
    Text = "Ne Pas Répondre"
  },
  AvgDialog_145522_Content_10 = {
    Text = "Castor marchait en queue de convoi, plus silencieux qu'à l'ordinaire."
  },
  AvgDialog_145522_Content_11 = {
    Text = "Hé, l'idiot. Tu as froid ?"
  },
  AvgDialog_145522_Content_12 = {
    Text = "Je vais bien."
  },
  AvgDialog_145522_Content_13 = {
    Text = "Pareil pour moi. C'est étrange."
  },
  AvgDialog_145522_Content_14 = {
    Text = "Alors, à qui appartient cette respiration si lourde et si bruyante ?"
  },
  AvgDialog_145522_Content_15 = {
    Text = "Le groupe s'arrêta. Tout le monde se retourna d'un même mouvement. Derrière eux, il n'y avait que leurs propres empreintes, plus ou moins profondes."
  },
  AvgDialog_145522_Content_16 = {
    Text = "Aux bords des empreintes, la Neige était immaculée. Immaculée, comme si quelque chose l'avait doucement effacée."
  },
  AvgDialog_145522_Content_17 = {
    Text = "Silence. Seulement le vent. Le vent soufflait de très loin, contournait la crête et s'infiltrait dans le col de chacun."
  },
  AvgDialog_145522_Content_18 = {
    Text = "Dans le vent se mêlait un son Presque imperceptible. Ce n'était pas un chant. C'était un Appel."
  },
  AvgDialog_145522_Content_19 = {
    Text = "<Change>...Eve...lyn..."
  },
  AvgDialog_145522_Content_2 = {
    Text = "La tempête de Neige s'était calmée, mais le ciel était encore plus menaçant qu'au plus fort de la tourmente."
  },
  AvgDialog_145522_Content_20 = {Text = "?!"},
  AvgDialog_145522_Content_21 = {
    Text = "Elle se retourna brusquement. Le Champ de neige était vaste et vide, il n'y avait rien. Mais la voix revint, cette fois plus proche, empreinte d'une tendresse presque cruelle."
  },
  AvgDialog_145522_Content_22 = {
    Text = "<Change>...Evelyn... J'ai froid..."
  },
  AvgDialog_145522_Content_23 = {Text = "C'est..."},
  AvgDialog_145522_Content_24 = {
    Text = "<Shake:Impossible…>"
  },
  AvgDialog_145522_Content_25 = {
    Text = "Le Visage d'Elle perdit instantanément toute couleur. Ses lèvres étaient pâles, sa voix tremblait, comme si le moment qu'Elle avait imaginé plus d'une fois était enfin arrivé."
  },
  AvgDialog_145522_Content_26 = {
    Text = "Vous… Vous avez tous entendu ?!"
  },
  AvgDialog_145522_Content_27 = {Text = "C'est lui."},
  AvgDialog_145522_Content_28 = {
    Text = "<Shake:C'est sa voix……>"
  },
  AvgDialog_145522_Content_29 = {
    Text = "Madame Evelyn, quelle que soit la voix que vous entendez, ne lui répondez pas."
  },
  AvgDialog_145522_Content_3 = {
    Text = "Des nuages gris plomb pesaient bas sur la crête des montagnes, comme une couche de vieux Rêves lourds et obstinés qui refusaient de se dissiper."
  },
  AvgDialog_145522_Content_30 = {
    Text = "Vous retenez votre souffle. Le vent du Champ de neige vous effleure les oreilles, puis— \nVous l'entendez tous, vous aussi."
  },
  AvgDialog_145522_Content_31 = {
    Text = "Le vent se transforme en d'innombrables voix, d'innombrables Appels lancinants. Chacun souffle depuis une direction que vous avez jadis connue, puis perdue."
  },
  AvgDialog_145522_Content_32 = {
    Text = "Une voix. Une voix vous appelle. Glaciale et cristalline."
  },
  AvgDialog_145522_Content_33 = {
    Text = "<Change>Je t'attends, partenaire..."
  },
  AvgDialog_145522_Content_34 = {
    Text = "<Change>Ne prends pas de retard. Nous atteindrons la fin ensemble."
  },
  AvgDialog_145522_Content_35 = {Text = "Ramona..."},
  AvgDialog_145522_Content_36 = {
    Text = "Vous serrez les dents, Compteur au désir de suivre cette voix."
  },
  AvgDialog_145522_Content_37 = {
    Text = "Vos pieds semblent gelés dans la neige, refusant d'obéir. Vous sentez une force infime, d'une douceur extrême, venant de la direction de la voix, tirer lentement, si lentement, votre centre de gravité vers l'avant."
  },
  AvgDialog_145522_Content_38 = {
    Text = "C'est une Invitation. Une Invitation à laquelle il est impossible de résister."
  },
  AvgDialog_145522_Content_39 = {
    Text = "Tant Que vous acceptez de faire un pas en avant, vous pourrez revenir à n'importe quel instant de chaleur du passé—"
  },
  AvgDialog_145522_Content_4 = {
    Text = "Personne ne parlait. Les chiens guides marchaient en tête, et même eux avaient étouffé dans leur gorge ces gémissements habituels."
  },
  AvgDialog_145522_Content_40 = {Text = "Gardien—"},
  AvgDialog_145522_Content_41 = {
    Text = "La voix de William vous parvient de très loin. C'est alors seulement que vous réalisez avoir déjà avancé d'un demi-pas sans vous en rendre compte."
  },
  AvgDialog_145522_Content_42 = {
    Text = "Quelques chiens guides gisaient morts sur le sol à côté de vous, la gorge sauvagement déchirée, avec du sang cramoisi éclaboussé en taches criardes et tranchantes sur la neige immaculée."
  },
  AvgDialog_145522_Content_43 = {Text = "Reculez."},
  AvgDialog_145522_Content_44 = {
    Text = "Donnez-moi votre main."
  },
  AvgDialog_145522_Content_45 = {
    Text = "Le visage de William est blanc comme un linge, sa main agrippant votre bras tremble malgré lui."
  },
  AvgDialog_145522_Content_46 = {
    Text = "Vous sentez qu'il fait un effort considérable pour se Compter, pour résister à l'envoûtement de cette voix."
  },
  AvgDialog_145522_Content_47 = {
    Text = "Cette voix est fausse. Vous devez vous réveiller."
  },
  AvgDialog_145522_Content_48 = {
    Text = "Il prononce ces mots d'une voix très basse, comme s'il rendait un Jugement."
  },
  AvgDialog_145522_Content_49 = {
    Text = "<Shake:<Small:Hou… Tante Rosa…>>"
  },
  AvgDialog_145522_Content_5 = {
    Text = "Avancez lentement, le terrain est irrégulier."
  },
  AvgDialog_145522_Content_50 = {
    Text = "Caraboo se réveilla comme d'un rêve, murmurant encore quelque chose."
  },
  AvgDialog_145522_Content_51 = {
    Text = "Mais tout le monde ne peut pas se réveiller."
  },
  AvgDialog_145522_Content_52 = {
    Text = "Pollux… ! Pollux… ! Où es-tu ?!"
  },
  AvgDialog_145522_Content_53 = {
    Text = "<Shake:<Big:Pollux… !!!>>"
  },
  AvgDialog_145522_Content_54 = {
    Text = "<Italic:…Grand frère, j'ai froid…>"
  },
  AvgDialog_145522_Content_55 = {
    Text = "<Italic:Grand frère, la cellule est si sombre, j'ai si peur… je t'en supplie… laisse-moi sortir… Sa Sainteté, elle…>"
  },
  AvgDialog_145522_Content_56 = {
    Text = "<Shake:<Italic:…Grand frère, pourquoi tu ne viens pas me chercher…>>"
  },
  AvgDialog_145522_Content_57 = {
    Text = "Pollux !! Attends-moi, j'arrive —"
  },
  AvgDialog_145522_Content_58 = {
    Text = "<Shake:Hé, l'idiot, arrête-toi !>"
  },
  AvgDialog_145522_Content_59 = {
    Text = "Ignorant votre Appel, Castor s'élança en avant."
  },
  AvgDialog_145522_Content_6 = {
    Text = "Cette section était autrefois une pente droite, mais maintenant des ravines transversales l'ont fendue."
  },
  AvgDialog_145522_Content_60 = {
    Text = "<Shake:Attrapez-le !>"
  },
  AvgDialog_145522_Content_61 = {
    Text = "Ne laissez pas cet idiot se faire entraîner !"
  },
  AvgDialog_145522_Content_7 = {
    Text = "Ce sont de nouvelles fissures formées après la dernière avalanche… elles ne devraient pas être aussi profondes."
  },
  AvgDialog_145522_Content_8 = {
    Text = "La forme de la montagne est en train de changer."
  },
  AvgDialog_145522_Content_9 = {
    Text = "William ne continua pas. Ses yeux d'un vert éclatant fixaient le lointain, ses sourcils légèrement froncés."
  },
  AvgDialog_145523_Content_1 = {
    Text = "Le Sommet Sans Désir"
  },
  AvgDialog_145523_Content_10 = {
    Text = "William s'accroupit lentement, ses doigts effleurant les sculptures complexes entre les socles, que vous aviez prises pour de simples décorations."
  },
  AvgDialog_145523_Content_100 = {
    Text = "<Shake:Arrête ! Éteins ça ! <Red:Je vais pourrir avant même que le vœu soit exaucé !>>"
  },
  AvgDialog_145523_Content_101 = {
    Text = "Cela ne faisait jamais partie de notre accord."
  },
  AvgDialog_145523_Content_102 = {
    Text = "Ouais, il avait seulement promis de lancer le rituel pour toi. Il n'a jamais promis que tu y survivrais."
  },
  AvgDialog_145523_Content_103 = {
    Text = "Je vois… Chaque mot que William a prononcé était l'absolue vérité… et pourtant, assemblés, ils formaient un mensonge parfait."
  },
  AvgDialog_145523_Content_104 = {
    Text = "Le sixième anneau de lumière s'élève."
  },
  AvgDialog_145523_Content_105 = {
    Text = "Toute la montagne tremble comme quelque chose qui agonise. D'innombrables masses de chair pâle surgissent des rochers qui se fendent et déferlent vers l'autel comme une vague."
  },
  AvgDialog_145523_Content_106 = {
    Text = "Non ! Tout cela m'appartient ! Ma Chair ! Ma Force ! Mes désirs !"
  },
  AvgDialog_145523_Content_107 = {
    Text = "Ou peut-être ne t'ont-ils jamais appartenu. Ce pouvoir ne t'appartient pas. Ce sont les vœux volés des innombrables pèlerins que tu as attirés et enterrés ici."
  },
  AvgDialog_145523_Content_108 = {
    Text = "Ce pouvoir appartient à tous ceux que tu as trompés, dévorés et abandonnés. Tu n'as aucun droit de le revendiquer..."
  },
  AvgDialog_145523_Content_109 = {
    Text = "...Et maintenant, ils retournent simplement là où ils appartiennent."
  },
  AvgDialog_145523_Content_11 = {
    Text = "Impossible... comment cela peut-il se trouver ici... Ces marques à côté des gravures de l'autel... je les reconnais."
  },
  AvgDialog_145523_Content_110 = {
    Text = "Tinct, Castor, Evelyn et Fingal, que tu n'as jamais eu l'occasion de rencontrer en personne..."
  },
  AvgDialog_145523_Content_111 = {
    Text = "Visage après visage, nom après nom remonte à la surface de votre esprit, avant de sombrer dans le silence obscur de la mémoire."
  },
  AvgDialog_145523_Content_112 = {
    Text = "<BigShake:Ne t'y risque pas ! N'OSE PAS !>"
  },
  AvgDialog_145523_Content_113 = {
    Text = "<Big:<Red:Je vais d'abord détruire l'autel, puis vous réduire tous en miettes !>"
  },
  AvgDialog_145523_Content_114 = {
    Text = "William vous fait un signe de tête."
  },
  AvgDialog_145523_Content_115 = {
    Text = "Faisons chacun notre part. Je maintiendrai le rituel en marche."
  },
  AvgDialog_145523_Content_116 = {
    Text = "Laisse-moi faire. Je vais arrêter le ver !"
  },
  AvgDialog_145523_Content_12 = {
    Text = "C'est l'œuvre de Fingal."
  },
  AvgDialog_145523_Content_13 = {Text = "Fingal ?"},
  AvgDialog_145523_Content_14 = {
    Text = "Vous connaissez ce nom. Le partenaire de William, l'Enquêteur qui a disparu de «ce monde» avant lui."
  },
  AvgDialog_145523_Content_15 = {
    Text = "Je vois, la Clé de Salomon… la raison pour laquelle le Ver ne peut pas lancer le rituel… et le but pour lequel Fingal est venu dans ce monde…"
  },
  AvgDialog_145523_Content_16 = {
    Text = "Hahaha... Je vois ! Je comprends maintenant ! C'est hilarant !"
  },
  AvgDialog_145523_Content_17 = {
    Text = "Alors c'est ce que ce tisserand acharné voulait me montrer. Vous avoir emmenés jusqu'ici en valait vraiment la peine !"
  },
  AvgDialog_145523_Content_18 = {
    Text = "Que veux-tu dire ?"
  },
  AvgDialog_145523_Content_19 = {
    Text = "N hausse simplement les épaules."
  },
  AvgDialog_145523_Content_2 = {
    Text = "C'était un autel immense, Comme Si il était aussi vieux que toute la chaîne de montagnes."
  },
  AvgDialog_145523_Content_20 = {
    Text = "Eh bien, je ne suis pas votre traducteur. Vous voyez ce M. William ici présent ? Demandez-lui. Tu m'as bien laissé sortir de ton ventre, mais est-ce que j'ai l'air de quelqu'un qui compte te rendre la «pareille» ?"
  },
  AvgDialog_145523_Content_21 = {
    Text = "Je vais expliquer."
  },
  AvgDialog_145523_Content_22 = {
    Text = "«La Clé de Salomon» n'est pas réellement une clé, mais un grimoire."
  },
  AvgDialog_145523_Content_23 = {
    Text = "Et le contenu le plus crucial consigné dans ce grimoire est la méthode d'Invocation des soixante-douze démons de Salomon. En d'autres termes, c'est la méthode pour relier les mondes."
  },
  AvgDialog_145523_Content_24 = {
    Text = "Il leva la tête et regarda au centre exact des sept socles — une serrure étroite, Presque fondue dans l'ombre."
  },
  AvgDialog_145523_Content_25 = {
    Text = "Ces marques sont un code secret que Seulement lui et moi pouvons déchiffrer."
  },
  AvgDialog_145523_Content_26 = {
    Text = "William s'agenouille devant le cercle magique, sa main traçant soigneusement les gravures sur le sol. Peu à peu, les mots silencieux commencent à s'assembler dans son esprit, formant une voix familière."
  },
  AvgDialog_145523_Content_27 = {
    Text = "C'est bien William ? Je savais que tu arriverais jusque-là.\n\nLe cercle magique ici contient trois anciens scripts différents. Je parierais que parmi notre cercle, toi seul, l'élève studieux, pourrais tout lire d'un seul coup.\nCe sont des sorts d'invocation et de scellement. Tu devrais comprendre ce que cela signifie."
  },
  AvgDialog_145523_Content_28 = {
    Text = "Il contrôle l'ouverture et la fermeture d'une certaine « Porte »."
  },
  AvgDialog_145523_Content_29 = {
    Text = "#N/ABref, ce cercle magique utilise la « Couronne » comme médium, reliant à l'origine de ce monde. Par conséquent, dans ce monde uniquement, il peut en effet exaucer n'importe quel vœu.\n\nVous vous êtes sûrement demandé pourquoi vous aviez été projeté dans ce monde inconnu, je présume ?\n\nJe peux maintenant vous donner la réponse.\n\nVous êtes ce vœu... mon vœu."
  },
  AvgDialog_145523_Content_3 = {
    Text = "Des marches circulaires s'élevaient en couches successives, au sommet desquelles se dressaient sept socles vides disposés en cercle. Entre les socles, dans d'anciennes rainures, se figeait une lumière dorée sombre, depuis longtemps desséchée."
  },
  AvgDialog_145523_Content_30 = {
    Text = "Malheureusement, le pouvoir que j'ai offert n'était pas suffisant. Je n'ai pu qu'entrouvrir une fissure pour que votre Cœur d'argent puisse passer.\n\nLa destination que je ne pouvais atteindre... vous devez l'atteindre à ma place.\n\nAprès tout, vous êtes le légendaire Enquêteur William, n'est-ce pas ?"
  },
  AvgDialog_145523_Content_31 = {
    Text = "J'espère que vous avez toujours ma Clé d'Argent.\n\nUtilisez-la pour activer le cercle magique, puis formulez votre vœu, et Il vous guidera vers la terre promise.\n\nLa route à venir — je vous la confie.\n\nCordialement,\nFingal"
  },
  AvgDialog_145523_Content_32 = {
    Text = "Les doigts de William s'immobilisèrent."
  },
  AvgDialog_145523_Content_33 = {
    Text = "Il ne dit pas un mot. Vous n'avez jamais vu cette expression sur son visage."
  },
  AvgDialog_145523_Content_34 = {Text = "%player%."},
  AvgDialog_145523_Content_35 = {
    Text = "Je suis ici."
  },
  AvgDialog_145523_Content_36 = {
    Text = "À l'époque, ne m'aviez-vous pas demandé pourquoi j'avais été le premier à me réveiller sous l'Appel du Wendigo ?"
  },
  AvgDialog_145523_Content_37 = {
    Text = "Parce que j'étais le seul parmi nous à avoir vu ses ossements."
  },
  AvgDialog_145523_Content_38 = {
    Text = "Son corps était entièrement décomposé, impossible d'identifier qui c'était. Mais j'ai reconnu la moitié de la Clé d'argent qu'il portait sur lui."
  },
  AvgDialog_145523_Content_39 = {
    Text = "Numéro I-1021, le chiffre appartenant à Fingal. Chaque fois qu'un numéro disparaît des registres, nous savons qu'un autre aîné a été oublié par le monde."
  },
  AvgDialog_145523_Content_4 = {
    Text = "C'est ici le terminus où le Ver de la montagne, usant des vœux comme appâts, a attiré d'innombrables alpinistes."
  },
  AvgDialog_145523_Content_40 = {
    Text = "Depuis lors, j'ai toujours gardé cette Clé d'argent sur moi."
  },
  AvgDialog_145523_Content_41 = {
    Text = "Il ferma les yeux. Quand il les rouvrit, dans ces yeux d'un vert émeraude, il ne restait plus qu'une chose sereine et inébranlable."
  },
  AvgDialog_145523_Content_42 = {
    Text = "…Fingal, merci pour la confiance que tu m'accordes."
  },
  AvgDialog_145523_Content_43 = {
    Text = "Ver de la Montagne, je vais te dire comment activer le rituel."
  },
  AvgDialog_145523_Content_44 = {
    Text = "Ceux qui offrent leurs vœux à la montagne abandonnent leur âme même pour alimenter le cercle magique. Par leur intermédiaire, un pont est construit vers l'Origine du monde."
  },
  AvgDialog_145523_Content_45 = {
    Text = "L'Origine du monde ?"
  },
  AvgDialog_145523_Content_46 = {
    Text = "Si mon hypothèse est correcte, c'est le Soleil Noir suspendu dans le ciel."
  },
  AvgDialog_145523_Content_47 = {
    Text = "Le Soleil Noir existe à l'image de la « Mare Noire » de Mizag — englobant tout, une suspension des ruines de tout ce qui est passé et à venir, noyé dans une marée corrosive."
  },
  AvgDialog_145523_Content_48 = {
    Text = "L'ampleur du vœu exaucé dépend entièrement de la quantité de cette marée que celui qui formule le vœu ose puiser dans le Soleil Noir."
  },
  AvgDialog_145523_Content_49 = {
    Text = "Petite fille, garde les yeux rivés sur lui. Assure-toi qu'il ne raconte pas de mensonges."
  },
  AvgDialog_145523_Content_5 = {
    Text = "Personne n'a jamais quitté cet endroit vivant. Tous les grimpeurs du passé... ils sont tous là. Sous nos pieds. Dans le ventre de la montagne."
  },
  AvgDialog_145523_Content_50 = {
    Text = "À contrecœur, Caraboo s'avance et plonge son regard dans les yeux de William."
  },
  AvgDialog_145523_Content_51 = {Text = "<Shake:!!>"},
  AvgDialog_145523_Content_52 = {
    Text = "William ferme les yeux et secoue doucement la tête."
  },
  AvgDialog_145523_Content_53 = {
    Text = "Chaque mot qu'il vient de prononcer est vrai."
  },
  AvgDialog_145523_Content_54 = {
    Text = "<Shake:Ne me mens pas ! Tu as hésité à l'instant, petit imposteur !>"
  },
  AvgDialog_145523_Content_55 = {
    Text = "Est-ce que je mens ? Tu devrais le savoir mieux que moi."
  },
  AvgDialog_145523_Content_56 = {
    Text = "Le Ver laisse échapper un rire froid et moqueur, déclenchant une cascade de neige qui dévale les falaises."
  },
  AvgDialog_145523_Content_57 = {
    Text = "Hmph. Seul le rituel compte. Une fois cela terminé, je m'occuperai de toi moi-même, traître."
  },
  AvgDialog_145523_Content_58 = {
    Text = "Dis-moi alors, Ver de la Montagne — quelle est l'ampleur du vœu que tu désires ?"
  },
  AvgDialog_145523_Content_59 = {
    Text = "Hihihi... tu as vraiment besoin de poser la question ? Plus c'est grand, mieux c'est ! Je veux avaler le monde entier dans mon ventre — un festin sans fin, inépuisable !"
  },
  AvgDialog_145523_Content_6 = {
    Text = "Assez parlé. Dis-moi comment fonctionne ce cercle magique."
  },
  AvgDialog_145523_Content_60 = {
    Text = "Quelle créature avide et stupide. Tu aurais peut-être dû apprendre la beauté de la retenue."
  },
  AvgDialog_145523_Content_61 = {
    Text = "Comment une parasite du Chaos comme toi pourrait-elle comprendre ? Si j'avais suivi les règles, je n'aurais jamais atteint ces sommets."
  },
  AvgDialog_145523_Content_62 = {
    Text = "Et par «sommets», tu veux dire traîner ton corps bouffi et frétillant sur un pic gelé ?"
  },
  AvgDialog_145523_Content_63 = {
    Text = "Pfff... laisse tomber. De toute façon, personne n'écoute jamais mes excellents conseils."
  },
  AvgDialog_145523_Content_64 = {Text = "Compris."},
  AvgDialog_145523_Content_65 = {
    Text = "William hocha la tête."
  },
  AvgDialog_145523_Content_66 = {
    Text = "Pour exiger un vœu de la plus grande envergure, tu dois sacrifier chaque offrande sans exception."
  },
  AvgDialog_145523_Content_67 = {
    Text = "<BigShake:Prenez-les ! Prenez-les tous ! Ils existent pour ce moment précis !>"
  },
  AvgDialog_145523_Content_68 = {
    Text = "%player%, donnez-moi les Offrandes."
  },
  AvgDialog_145523_Content_69 = {
    Text = "Vous ouvrez la mallette."
  },
  AvgDialog_145523_Content_7 = {
    Text = "La voix du Ver de la Montagne monta du sol. Cette fois, son ton ne contenait plus seulement de la moquerie, mais aussi une urgence réprimée depuis de longues années."
  },
  AvgDialog_145523_Content_70 = {
    Text = "La Pomme Dorée, le Miroir de Yata, la Plume de Ma'at, l'Œil de Balor, le Fil des Moires, la Couronne d'Ariane… et la Clé d'Argent elle-même."
  },
  AvgDialog_145523_Content_71 = {
    Text = "Les sept offrandes trouvent chacune leur place sur les socles, et à travers les rainures ancestrales, une lumière dorée sombre s'écoule et jaillit de nouveau, se rejoignant en un anneau complet."
  },
  AvgDialog_145523_Content_72 = {
    Text = "<Shake:Haha... Enfin... ENFIN !>"
  },
  AvgDialog_145523_Content_73 = {
    Text = "La Montagne aura Son festin. La Montagne dépensera l'intégralité de Son trésor."
  },
  AvgDialog_145523_Content_74 = {
    Text = "La Montagne a souffert de cette faim pendant si, si longtemps."
  },
  AvgDialog_145523_Content_75 = {
    Text = "William saisit cette clé unique en son genre et l'introduisit dans la serrure."
  },
  AvgDialog_145523_Content_76 = {
    Text = "Au nom de Fingal —"
  },
  AvgDialog_145523_Content_77 = {
    Text = "<Red:J'initie ce rituel.>"
  },
  AvgDialog_145523_Content_78 = {Text = "Clic."},
  AvgDialog_145523_Content_79 = {
    Text = "Dans un son doux et tranchant, les sept offrandes éclatent en une lumière aveuglante."
  },
  AvgDialog_145523_Content_8 = {
    Text = "Tous les regards se tournent vers l'autel, attirés par les inscriptions mystérieuses et serrées qui en couvrent la surface."
  },
  AvgDialog_145523_Content_80 = {
    Text = "Le premier anneau de lumière s'élève au-dessus de l'autel. Puis le deuxième, et le troisième. Les vœux assoupis dans les sept artefacts vibrent en résonance, comme sept rivières se précipitant vers une mer unique et sombre."
  },
  AvgDialog_145523_Content_81 = {
    Text = "Si la Montagne avait des mains, elle grifferait le ciel pour saisir cet anneau brillant, consumée par une faim désespérée."
  },
  AvgDialog_145523_Content_82 = {
    Text = "<Shake:Ce jour est enfin arrivé !>"
  },
  AvgDialog_145523_Content_83 = {
    Text = "Elle arracherait l'anneau aux cieux et le presserait profondément contre Sa poitrine, l'enfouissant dans Sa chair bouffie jusqu'à ce que chaque goutte de sa puissance soit dévorée."
  },
  AvgDialog_145523_Content_84 = {
    Text = "Tu fixes d'un regard vide le ciel en tourmente. Lorsque le vœu de la Montagne sera exaucé, que deviendront vos vies ? Votre voyage s'achèvera-t-il simplement dans ce désert gelé ?"
  },
  AvgDialog_145523_Content_85 = {
    Text = "En une fraction de seconde, tu aperçois l'éclair du monoculaire de William."
  },
  AvgDialog_145523_Content_86 = {
    Text = "Aussitôt après, le quatrième anneau de lumière s'embrase."
  },
  AvgDialog_145523_Content_87 = {
    Text = "La roche solide sous tes pieds gronde d'un sourd et lourd grondement — un frisson qui n'appartient pas à la pierre, mais à de la chair vivante. De faibles lueurs malsaines commencent à saigner des couches de glace qui se fissurent en dessous."
  },
  AvgDialog_145523_Content_88 = {
    Text = "<Shake:...Qu'est-ce que c'est ?>"
  },
  AvgDialog_145523_Content_89 = {
    Text = "<Shake:Pourquoi... mes forces... me quittent-elles ?>"
  },
  AvgDialog_145523_Content_9 = {
    Text = "Attendez… ces motifs…"
  },
  AvgDialog_145523_Content_90 = {
    Text = "C'est le prix du rituel que tu désirais si ardemment."
  },
  AvgDialog_145523_Content_91 = {
    Text = "Après avoir payé ce prix, qu'en adviendra-t-il ?"
  },
  AvgDialog_145523_Content_92 = {
    Text = "Le rituel puisera «toute» la Force de l'Offrande, donc je suppose qu'il redeviendra ce qu'il était avant de vous rencontrer, voire plus faible encore."
  },
  AvgDialog_145523_Content_93 = {
    Text = "Alors... assez faible pour n'être qu'un minuscule et misérable asticot se tortillant dans une pomme pourrie ? Que l'on pourrait écraser d'une simple pression ?"
  },
  AvgDialog_145523_Content_94 = {
    Text = "<BigShake:Tu m'as trompé ! Espèce de menteur misérable !>"
  },
  AvgDialog_145523_Content_95 = {
    Text = "Je t'avais promis d'initier pleinement le rituel, et tu avais accepté de céder <Italic:toutes> les offrandes."
  },
  AvgDialog_145523_Content_96 = {
    Text = "Tout ce que tu as englouti dans ton ventre, toute la force vitale de cette montagne, sera offert à l'autel — sacrifié au dieu qui a gravé cette formation."
  },
  AvgDialog_145523_Content_97 = {
    Text = "Le cinquième anneau de lumière s'élève."
  },
  AvgDialog_145523_Content_98 = {
    Text = "Les rochers sous vos pieds se fissurent et s'effritent, révélant en dessous une couche humide et blafarde — une Chair qui se contracte violemment."
  },
  AvgDialog_145523_Content_99 = {
    Text = "D'immenses pans de neige s'effondrent dans un fracas assourdissant, et le ciel est englouti, morceau par morceau, par une ombre inimaginable."
  },
  AvgDialog_145524_Content_1 = {
    Text = "Vous… n'approchez pas !"
  },
  AvgDialog_145524_Content_10 = {
    Text = "<Change>Te souviens-tu de ta mission ?"
  },
  AvgDialog_145524_Content_11 = {
    Text = "<Small:Éliminer... le traître... Je dois...>"
  },
  AvgDialog_145524_Content_12 = {
    Text = "Le Chaos dans les yeux de Pollux disparut peu à peu, remplacé par une sorte d'hébétude, une hébétude que seule la Voix dans l'esprit pouvait animer."
  },
  AvgDialog_145524_Content_13 = {
    Text = "Oui, c'est exact, je suis un traître. Je suis celui qui t'a trahi et s'est enfui."
  },
  AvgDialog_145524_Content_14 = {
    Text = "Mais maintenant, je ne partirai plus."
  },
  AvgDialog_145524_Content_15 = {
    Text = "<Shake:Traître, Castor...>"
  },
  AvgDialog_145524_Content_16 = {
    Text = "Il était perdu, il voulait résister à quelque chose, s'accrocher à quelque chose, mais la voix dans sa tête ne cessait de se débattre."
  },
  AvgDialog_145524_Content_17 = {
    Text = "Pollux, tu nous as suivis tout ce temps, tu as forcément rencontré le Wendigo toi aussi."
  },
  AvgDialog_145524_Content_18 = {
    Text = "Dans l'Illusion du Wendigo, qu'as-tu entendu ?"
  },
  AvgDialog_145524_Content_19 = {
    Text = "Les pupilles de Pollux se dilatèrent instantanément, puis se dispersèrent peu à peu. Il sombra dans une méditation semblable à des Murmures dans un Rêve."
  },
  AvgDialog_145524_Content_2 = {
    Text = "Pollux écarquilla les Yeux. Il ne comprenait pas ce que ce forcené avait en tête."
  },
  AvgDialog_145524_Content_20 = {
    Text = "J'ai entendu... quelqu'un m'appelait..."
  },
  AvgDialog_145524_Content_21 = {
    Text = "Il disait que nous pourrions devenir de grands chevaliers."
  },
  AvgDialog_145524_Content_22 = {
    Text = "Nous chevauchions, franchissions les montagnes, traversions les fleuves et les mers, terrassant les dragons..."
  },
  AvgDialog_145524_Content_23 = {
    Text = "Et puis, et puis, à la fin du Rêve…"
  },
  AvgDialog_145524_Content_24 = {Text = "新增"},
  AvgDialog_145524_Content_25 = {
    Text = "<BigShake:Non, non… !>"
  },
  AvgDialog_145524_Content_26 = {
    Text = "C'est douloureux, Juliette, <Shake:Sauvez-moi, Sauvez-moi…>"
  },
  AvgDialog_145524_Content_27 = {
    Text = "<Shake:Je suis… le noble… l'unique… Fils Saint… Sauvez-moi… <Small:Je ne peux pas…>>"
  },
  AvgDialog_145524_Content_28 = {
    Text = "Ce n'est rien… Tu n'as pas besoin de t'en souvenir."
  },
  AvgDialog_145524_Content_29 = {
    Text = "Les souffrances insupportables, laisse-moi les porter. Comme quand on était petits."
  },
  AvgDialog_145524_Content_3 = {
    Text = "Sur le visage de Castor, il n'y avait ni révérence pour les dogmes, ni peur face à l'hostilité."
  },
  AvgDialog_145524_Content_30 = {
    Text = "Après tout, je suis ton grand frère."
  },
  AvgDialog_145524_Content_31 = {
    Text = "Castor enlaça Pollux, l'apaisant d'une voix douce comme on réconforte un enfant."
  },
  AvgDialog_145524_Content_32 = {
    Text = "La respiration de Pollux se calma, son visage posé contre l'épaule de Castor, ses paupières s'abaissant peu à peu."
  },
  AvgDialog_145524_Content_33 = {
    Text = "<Shake:Castor…>"
  },
  AvgDialog_145524_Content_34 = {
    Text = "C'est moi, je suis, Castor…"
  },
  AvgDialog_145524_Content_35 = {
    Text = "<Shake:Castor, Castor…>"
  },
  AvgDialog_145524_Content_36 = {
    Text = "<Shake:<Small:...Frère ?>>"
  },
  AvgDialog_145524_Content_37 = {
    Text = "Ses pupilles autrefois vides s'éclaircirent en un instant, la voix de Pollux si légère qu'elle faillit être emportée par le vent, mais elle parvint tout de même à atteindre les oreilles de Castor."
  },
  AvgDialog_145524_Content_38 = {
    Text = "L'Appel qu'il avait tracé d'innombrables fois dans son imagination résonna enfin de nouveau à son oreille."
  },
  AvgDialog_145524_Content_39 = {Text = "Ah—"},
  AvgDialog_145524_Content_4 = {
    Text = "Il s'avança simplement, franchissant cette lame, franchissant tous les obstacles qui auraient dû exister mais n'existaient plus."
  },
  AvgDialog_145524_Content_40 = {
    Text = "Il voulait pleurer, voulait crier, voulait rugir."
  },
  AvgDialog_145524_Content_41 = {
    Text = "Même si autour de lui ne s'étendait qu'un Champ de neige vaste et infini, il voulait proclamer au monde entier, sans raison aucune, que son petit frère était revenu."
  },
  AvgDialog_145524_Content_42 = {
    Text = "Mais il ne dit rien, comme à son habitude, comme lorsque Pollux se moquait de lui en le traitant de bûche, et Caraboo de benêt."
  },
  AvgDialog_145524_Content_43 = {
    Text = "<Shake:Pollux…>"
  },
  AvgDialog_145524_Content_44 = {
    Text = "— À cet instant précis, en haut de la montagne enneigée — quelque part encore plus haut, là où le sommet se dérobait au regard —"
  },
  AvgDialog_145524_Content_45 = {
    Text = "Le Regard du Jugement se posa."
  },
  AvgDialog_145524_Content_46 = {
    Text = "<Change>Rebut."
  },
  AvgDialog_145524_Content_47 = {
    Text = "Castor serra brusquement son frère contre lui —"
  },
  AvgDialog_145524_Content_48 = {
    Text = "Mais cela ne servit à rien. La lumière jaillit de la poitrine de Pollux."
  },
  AvgDialog_145524_Content_49 = {
    Text = "La lumière transperça d'un trait la poitrine des deux frères, traversa la cape usée de Castor, traversa les Ailes que Castor avait refermées autour d'eux —"
  },
  AvgDialog_145524_Content_5 = {
    Text = "Il serra Pollux tendrement dans ses bras."
  },
  AvgDialog_145524_Content_50 = {
    Text = "Telle une chaîne d'une blancheur pure, elle les liait étroitement l'un à l'autre, scellant le serment qu'ils ne connaîtraient plus jamais la Séparation."
  },
  AvgDialog_145524_Content_51 = {
    Text = "Grand frère… pardonne-moi…"
  },
  AvgDialog_145524_Content_52 = {
    Text = "Après ces dernières paroles, Pollux s'appuya sur l'épaule de Castor et sombra dans un profond sommeil."
  },
  AvgDialog_145524_Content_53 = {
    Text = "Ainsi… c'est bien… nous ne serons plus jamais séparés…"
  },
  AvgDialog_145524_Content_54 = {
    Text = "C'est aussi… un peu d'égoïsme de ma part…"
  },
  AvgDialog_145524_Content_55 = {
    Text = "Il jeta un regard en arrière vers les hauteurs de la montagne, imaginant ses anciens compagnons d'ascension se soutenant mutuellement pour grimper."
  },
  AvgDialog_145524_Content_56 = {
    Text = "Un Mensonge avait pris fin, ce voyage ne lui appartenait plus."
  },
  AvgDialog_145524_Content_57 = {
    Text = "Échanger un mensonge contre un autre mensonge…"
  },
  AvgDialog_145524_Content_58 = {
    Text = "Adieu… à tous… que votre voyage… vous mène enfin à la terre promise…"
  },
  AvgDialog_145524_Content_59 = {
    Text = "Une Plume noire se détacha des Ailes de Castor, emportée vers les hauteurs par le vent de Neige."
  },
  AvgDialog_145524_Content_6 = {
    Text = "Comme autrefois, dans le liquide amniotique."
  },
  AvgDialog_145524_Content_60 = {
    Text = "Qu'elle nous représente, et se rende en notre nom vers cette terre pure et innocente que tu as souhaitée…"
  },
  AvgDialog_145524_Content_61 = {
    Text = "Une fissure s'ouvrit sous leurs pieds, engloutissant lentement tout ce poids dans la glace et la Neige des entrailles de la montagne."
  },
  AvgDialog_145524_Content_62 = {
    Text = "Bonne nuit, Pollux."
  },
  AvgDialog_145524_Content_63 = {
    Text = "Vous gravîtes un nouveau sentier de montagne, réorganisant votre lourde équipement."
  },
  AvgDialog_145524_Content_64 = {
    Text = "Un vent de Neige, Comme Si animé d'une volonté propre, tourbillonna au-dessus de vous."
  },
  AvgDialog_145524_Content_65 = {Text = "C'est..."},
  AvgDialog_145524_Content_66 = {
    Text = "Dans le vent de Neige, une Plume d'un noir d'encre descendit lentement en voltigeant."
  },
  AvgDialog_145524_Content_67 = {
    Text = "Vous levez la main, et elle vient se poser doucement au creux de votre paume."
  },
  AvgDialog_145524_Content_68 = {
    Text = "Comme une Bénédiction Venir de loin."
  },
  AvgDialog_145524_Content_69 = {
    Text = "Altitude -7000 mètres-"
  },
  AvgDialog_145524_Content_7 = {
    Text = "Reviens, Pollux. Comme quand nous étions enfants."
  },
  AvgDialog_145524_Content_8 = {
    Text = "L'esprit de Pollux était plein de confusion, plein d'incompréhension. Mais sans savoir pourquoi, il ne put repousser cette étreinte chaleureuse."
  },
  AvgDialog_145524_Content_9 = {
    Text = "Une voix sévère et réprobatrice retentit soudainement à son oreille."
  },
  AvgDialog_145525_Content_1 = {
    Text = "Un calme étrange revint dans la caverne, et les membres du groupe, encore sous le choc, échangèrent des regards interdits."
  },
  AvgDialog_145525_Content_10 = {
    Text = "Juste qu'il existe dans cette montagne une certaine présence autre que la déesse, qui cherche à vous dérober vos vœux."
  },
  AvgDialog_145525_Content_11 = {
    Text = "Arrête d'effrayer tout le monde, Caraboo."
  },
  AvgDialog_145525_Content_12 = {
    Text = "Croyez-le ou non, c'est votre affaire. La déesse de la Neige peut la percevoir — elle est près de notre groupe, à nous suivre de près…"
  },
  AvgDialog_145525_Content_13 = {
    Text = "Vous ne pouvez pas distinguer à son ton si elle fait semblant de ressentir quelque chose ou si elle perçoit vraiment quelque chose."
  },
  AvgDialog_145525_Content_14 = {
    Text = "La tempête de neige se calme peu à peu."
  },
  AvgDialog_145525_Content_15 = {
    Text = "C'est dans cette lourdeur que vous vous remettez en route."
  },
  AvgDialog_145525_Content_2 = {
    Text = "Étrange, j'ai accompagné des équipes d'alpinistes à cette altitude à de nombreuses reprises, et c'est la première fois que je rencontre ce genre de…"
  },
  AvgDialog_145525_Content_3 = {
    Text = "Cela prouve que les dangers de cette montagne enneigée ne se limitent pas aux températures de moins trente degrés et au manque d'oxygène dû à la haute altitude."
  },
  AvgDialog_145525_Content_4 = {
    Text = "Caraboo baissa la voix et énonça lentement, d'un ton qui donnait froid dans le dos."
  },
  AvgDialog_145525_Content_5 = {
    Text = "La déesse de la Neige existe vraiment."
  },
  AvgDialog_145525_Content_6 = {
    Text = "<Red:La déesse de la montagne ne vous accueille pas. Elle n'accueille pas ceux qui manquent de dévotion.>"
  },
  AvgDialog_145525_Content_7 = {
    Text = "L'air se figea."
  },
  AvgDialog_145525_Content_8 = {
    Text = "Je vous faisais marcher ! Vous n'y avez quand même pas cru !"
  },
  AvgDialog_145525_Content_9 = {
    Text = "Je suis la déesse de la Neige la plus bienveillante qui soit — avec mes prières, la montagne vous accueillera et vous mènera jusqu'au sommet."
  },
  AvgDialog_145526_Content_1 = {
    Text = "Le Jour de l'Envol"
  },
  AvgDialog_145526_Content_10 = {
    Text = "Nous venons Seulement de repousser une attaque, mais ses assauts ne cesseront pas."
  },
  AvgDialog_145526_Content_11 = {
    Text = "Dans un endroit aussi périlleux que cette montagne, il est inévitable que les gens laissent parfois transparaître leur Fragile et leur faiblesse…"
  },
  AvgDialog_145526_Content_12 = {
    Text = "Dans ces moments-là, mieux vaut tromper."
  },
  AvgDialog_145526_Content_13 = {
    Text = "Caraboo sortit une Pomme de nulle part, en croqua un morceau avec un craquement, arborant l'air désinvolte de quelqu'un qui dirait «ce n'est pas moi qui viens de dire ça»."
  },
  AvgDialog_145526_Content_14 = {
    Text = "… Vous n'avez pas tort."
  },
  AvgDialog_145526_Content_15 = {
    Text = "En tout cas, nous devons le trouver, puis le capturer."
  },
  AvgDialog_145526_Content_16 = {
    Text = "Mais ils ne laissent aucune trace en marchant sur la Neige, comment allons-nous…"
  },
  AvgDialog_145526_Content_17 = {
    Text = "Laissez-moi faire. Je suis le meilleur pour démasquer les imposteurs, n'est-ce pas ?"
  },
  AvgDialog_145526_Content_18 = {
    Text = "Regardez, ils arrivent bientôt."
  },
  AvgDialog_145526_Content_19 = {
    Text = "Caraboo désigne le dernier chien guide qu'il vous reste. Il s'est accroupi, gémissant doucement."
  },
  AvgDialog_145526_Content_2 = {Text = "Wendigo."},
  AvgDialog_145526_Content_20 = {
    Text = "Ne bougez pas, et ne dites rien."
  },
  AvgDialog_145526_Content_21 = {
    Text = "Elle vous lance la Pomme dans laquelle elle a mordu."
  },
  AvgDialog_145526_Content_22 = {
    Text = "Dans l'entaille se cache un petit bout de papier : Quoi que je dise ensuite, ne me croyez pas."
  },
  AvgDialog_145526_Content_23 = {
    Text = "Caraboo se calme, elle ferme les yeux, puis les rouvre."
  },
  AvgDialog_145526_Content_24 = {
    Text = "En cet instant, son regard a changé. Hébétée, anxieuse, perdue, des émotions complexes se lisent dans ses petits yeux."
  },
  AvgDialog_145526_Content_25 = {
    Text = "<Shake:Tante Rosa, c'est vous ?>"
  },
  AvgDialog_145526_Content_26 = {
    Text = "<Shake:Vous êtes encore en train de faire une tarte aux pommes ? J'en sens le parfum.>"
  },
  AvgDialog_145526_Content_27 = {
    Text = "<Shake:Tante Rosa, je ne me plaindrai plus jamais que la croûte de la tarte aux pommes est trop épaisse. Depuis ce jour-là, je n'ai plus jamais mangé une tarte aussi délicieuse. Cette odeur dorée et caramélisée me manque.>"
  },
  AvgDialog_145526_Content_28 = {
    Text = "<Shake:Tante Rosa. Je viens vous rejoindre maintenant, attendez-moi.>"
  },
  AvgDialog_145526_Content_29 = {
    Text = "Caraboo avance en titubant."
  },
  AvgDialog_145526_Content_3 = {
    Text = "William récite le mot, syllabe par syllabe."
  },
  AvgDialog_145526_Content_30 = {
    Text = "Sur la neige, derrière Caraboo, deux monticules de neige de la hauteur d'un homme et demi surgissent brusquement."
  },
  AvgDialog_145526_Content_31 = {
    Text = "Il se jette sur Caraboo. Au moment où il bondit, elle se baisse vivement."
  },
  AvgDialog_145526_Content_32 = {
    Text = "<Big:William, préparez-vous !!>"
  },
  AvgDialog_145526_Content_4 = {
    Text = "<Italic:«Ses pattes sont forgées de feu — lorsqu'il court, la Neige Brûle sous ses pas.»>"
  },
  AvgDialog_145526_Content_5 = {
    Text = "Il est écrit dans le tome VII des «Chroniques étranges du Grand Nord» : <Italic:Quiconque entend le Chuchotement des nuits d'hiver ne doit jamais répondre.>"
  },
  AvgDialog_145526_Content_6 = {
    Text = "<Italic:Répondez une fois, il se souviendra de votre nom ; répondez deux fois, il reconnaîtra votre ombre ; répondez une troisième fois — vous deviendrez lui.>"
  },
  AvgDialog_145526_Content_7 = {
    Text = "Ne pouvons-nous pas l'éviter ?"
  },
  AvgDialog_145526_Content_8 = {
    Text = "Inutile. Tant Que le vent et la Neige s'étendent, ces terres sont le domaine où rôde le Wendigo."
  },
  AvgDialog_145526_Content_9 = {
    Text = "Ils étaient autrefois des humains. Ayant dévoré leurs semblables, ils se sont métamorphosés — leurs lèvres et leurs dents se sont putréfiées, condamnés à une Faim éternelle — avaler une forêt entière ne les rassasierait pas."
  },
  AvgDialog_145527_Content_1 = {
    Text = "Les Sacs à Dos"
  },
  AvgDialog_145527_Content_10 = {Text = "Non."},
  AvgDialog_145527_Content_100 = {
    Text = "Il approcha ses propres branches du foyer pour les allumer, puis rejoignit votre groupe."
  },
  AvgDialog_145527_Content_101 = {
    Text = "Les flammes se propagèrent de branche en branche, le Clignotement du feu illuminant tour à tour chaque visage levé."
  },
  AvgDialog_145527_Content_102 = {
    Text = "Dans le silence absolu, Comme Si l'on entendait au loin des voix graves récitant des sutras, des tintements de clochettes et des battements de tambour."
  },
  AvgDialog_145527_Content_103 = {
    Text = "Criez Lha Gyalo, puis jetez-les dans le bûcher."
  },
  AvgDialog_145527_Content_104 = {
    Text = "Une voix rauque mais puissante résonnait dans l'air raréfié, et les branches tombaient une à une dans le bûcher au rythme des cris."
  },
  AvgDialog_145527_Content_105 = {
    Text = "Merci à l'esprit de la montagne de nous pardonner l'irrévérence de notre intrusion dans son domaine sacré."
  },
  AvgDialog_145527_Content_106 = {
    Text = "Des branches de pin et de cyprès crépitent dans le feu, envoyant une fumée grise monter tout droit avant d'être déchirée par les vents violents."
  },
  AvgDialog_145527_Content_107 = {
    Text = "Et vous y percevez une légère odeur de mauvais augure."
  },
  AvgDialog_145527_Content_108 = {Text = "新增"},
  AvgDialog_145527_Content_109 = {
    Text = "Bien, les dangers de cette ascension et les plans d'urgence vous ont tous été expliqués."
  },
  AvgDialog_145527_Content_11 = {
    Text = "Hein !!! Pourquoi !!!"
  },
  AvgDialog_145527_Content_110 = {
    Text = "Au cours de la semaine écoulée, vous vous êtes tous adaptés aux déplacements avec gants, chaussures de montagne et lunettes de neige, et vous avez appris et maîtrisé l'utilisation des cordes et des broches à glace."
  },
  AvgDialog_145527_Content_111 = {
    Text = "D'après la surveillance étroite de ces derniers jours, les 5 à 7 prochains jours constituent la fenêtre météorologique la plus favorable à l'ascension — c'est le bon moment pour partir."
  },
  AvgDialog_145527_Content_112 = {
    Text = "Veuillez vérifier vos cartes d'itinéraire, vivres, carburant, bouteilles d'oxygène, trousses médicales et autres provisions que vous portez sur vous."
  },
  AvgDialog_145527_Content_113 = {
    Text = "Je le rappelle une fois de plus : pendant l'ascension, vous devez <Yellow:obéir entièrement aux instructions du guide>, et à l'exception des membres qui se retirent en avance, il est <Yellow:strictement interdit de quitter le groupe>."
  },
  AvgDialog_145527_Content_114 = {
    Text = "Si tout le monde est prêt, alors en route !"
  },
  AvgDialog_145527_Content_115 = {Text = "新增"},
  AvgDialog_145527_Content_116 = {Text = "新增"},
  AvgDialog_145527_Content_117 = {
    Text = "Vous n'avez progressé dans la montagne que pendant une demi-journée lorsque le beau temps se couvre soudainement."
  },
  AvgDialog_145527_Content_118 = {
    Text = "Le vent et la neige s'intensifient brusquement ; même les crêtes des montagnes sont à peine distinguables, et les chiens guides gémissent, refusant d'avancer."
  },
  AvgDialog_145527_Content_119 = {
    Text = "Étrange, d'après nos relevés de surveillance, des conditions météorologiques anormales n'auraient pas dû apparaître aussi vite."
  },
  AvgDialog_145527_Content_12 = {
    Text = "Ces deux-là ne viennent pas de rejoindre le groupe eux aussi ?"
  },
  AvgDialog_145527_Content_120 = {
    Text = "Avez-vous déjà rencontré une situation similaire ?"
  },
  AvgDialog_145527_Content_121 = {
    Text = "Jamais. Même en cas d'écart dans les relevés, cela survient généralement trois jours après les prévisions."
  },
  AvgDialog_145527_Content_122 = {
    Text = "<Shake:Une tempête de neige contre nature… on dirait… <Yellow:que la montagne nous repousse>.>"
  },
  AvgDialog_145527_Content_123 = {
    Text = "Impossible ! Comment cela pourrait-il être, alors que moi, la grande déesse de la montagne, suis ici ?"
  },
  AvgDialog_145527_Content_124 = {
    Text = "Il n'y a pas lieu de trop s'inquiéter, il arrive aussi de rencontrer des tempêtes de neige inattendues lors de la descente."
  },
  AvgDialog_145527_Content_125 = {
    Text = "Il y a un refuge tout près, il y a même quelques provisions supplémentaires là-bas. Allons nous reposer un moment, attendons que la tempête se calme, puis nous repartirons."
  },
  AvgDialog_145527_Content_126 = {
    Text = "Qu'est-ce qu'on attend alors, dépêchons-nous !"
  },
  AvgDialog_145527_Content_13 = {
    Text = "Caraboo, l'air mécontent, tendit le doigt vers vous et William."
  },
  AvgDialog_145527_Content_14 = {
    Text = "C'est simple. Ces deux-là sont des adultes, capables de prendre soin d'eux-mêmes."
  },
  AvgDialog_145527_Content_15 = {
    Text = "L'alpinisme n'est pas un jeu d'enfant, petite."
  },
  AvgDialog_145527_Content_16 = {
    Text = "Ici, vous pouvez vous proclamer père, mère, déesse des Neiges ou Volonté Suprême, peu importe."
  },
  AvgDialog_145527_Content_17 = {
    Text = "Mais une fois au-delà de cinq mille mètres d'altitude, tous les mensonges seront mis à nu par la tempête de neige et le mal des montagnes."
  },
  AvgDialog_145527_Content_18 = {
    Text = "Mais j'ai de l'argent, j'en ai <Italic:ÉNORMÉMENT> !"
  },
  AvgDialog_145527_Content_19 = {
    Text = "Tu n'es qu'une enfant, qu'est-ce que tu peux bien avoir comme—"
  },
  AvgDialog_145527_Content_2 = {
    Text = "Sous la conduite de Naraka, vous et les membres de l'équipe d'escalade vous présentez les uns aux autres."
  },
  AvgDialog_145527_Content_20 = {Text = "<Big:!>"},
  AvgDialog_145527_Content_21 = {
    Text = "Les mots de Naraka s'arrêtèrent net."
  },
  AvgDialog_145527_Content_22 = {
    Text = "La fille sort une lourde bourse en tissu, saisit une grande poignée de pièces d'or et les laisse retomber dans le sac avec un tintement en cascade. Elle n'en garde qu'une seule, la faisant tournoyer et voltiger entre ses doigts."
  },
  AvgDialog_145527_Content_23 = {
    Text = "Je vous ai dit que j'étais une fée, comment pourrais-je manquer d'un Objet extérieur tel que l'argent !"
  },
  AvgDialog_145527_Content_24 = {
    Text = "<Small:Mais vous venez juste de dire que vous étiez une déesse... ?>"
  },
  AvgDialog_145527_Content_25 = {
    Text = "Peu importe, qui s'en soucie !"
  },
  AvgDialog_145527_Content_26 = {
    Text = "Caraboo lança la pièce d'or d'un geste nonchalant. Naraka se pencha précipitamment pour l'attraper, trébucha et faillit tomber dans la Neige."
  },
  AvgDialog_145527_Content_27 = {
    Text = "Il tint la pièce entre ses mains, la mordit, et ne put cacher sa joie."
  },
  AvgDialog_145527_Content_28 = {
    Text = "<Shake:C'est authentique... !>"
  },
  AvgDialog_145527_Content_29 = {
    Text = "Hmph, une pièce d'or entre les mains d'une fée, comment pourrait-elle être fausse ?"
  },
  AvgDialog_145527_Content_3 = {
    Text = "Tinct, une chanteuse mystérieuse et distante, qui dit vouloir retrouver sa sœur."
  },
  AvgDialog_145527_Content_30 = {
    Text = "Bref, vous pouvez m'emmener avec l'expédition maintenant, non ?"
  },
  AvgDialog_145527_Content_31 = {
    Text = "<Shake:<Small:C'est vrai, laisser une enfant rejoindre l'expédition serait un peu irresponsable pour votre sécurité…>>"
  },
  AvgDialog_145527_Content_32 = {
    Text = "<BigShake:Hm ?>"
  },
  AvgDialog_145527_Content_33 = {
    Text = "Mais d'un autre côté, notre expédition possède une riche Expérience en alpinisme et des provisions amplement suffisantes — vous protéger, c'est <Big:largement à notre portée> !"
  },
  AvgDialog_145527_Content_34 = {
    Text = "Cela dit, je vous préviens : si vous décidez de faire demi-tour en cours de route, nous vous laisserons de quoi redescendre en toute sécurité, mais les frais de guide seront <Big:non remboursables>."
  },
  AvgDialog_145527_Content_35 = {
    Text = "Oui, oui, une fée se soucierait-elle vraiment d'une si petite somme ?"
  },
  AvgDialog_145527_Content_36 = {
    Text = "<Shake:<Small:Comme c'est étrange, elle ne faisait pas la manche il y a un instant ?>>"
  },
  AvgDialog_145527_Content_37 = {
    Text = "Ne croyez pas que je n'entends pas !"
  },
  AvgDialog_145527_Content_38 = {
    Text = "Je vous l'ai dit, c'était une Offrande ! Ce que la déesse reçoit, c'est la sincérité de chacun, vous comprenez ?"
  },
  AvgDialog_145527_Content_39 = {
    Text = "<Shake:<Small:Quand ce n'est pas nécessaire, l'ouïe est vraiment trop fine…>>"
  },
  AvgDialog_145527_Content_4 = {
    Text = "Evelyn, archéologue, venue dans ce monde post-apocalyptique pour des recherches scientifiques."
  },
  AvgDialog_145527_Content_40 = {
    Text = "<BigShake:JE L'ENTENDS AUSSI, CELLE-LÀ !>"
  },
  AvgDialog_145527_Content_41 = {
    Text = "Votre groupe fait l'inventaire des provisions, et la conversation dérive bientôt vers le rituel."
  },
  AvgDialog_145527_Content_42 = {
    Text = "Croyez-vous vraiment qu'il existe une déesse au sommet de la montagne capable d'exaucer tous les vœux ?"
  },
  AvgDialog_145527_Content_43 = {
    Text = "William demande d'un air faussement détaché."
  },
  AvgDialog_145527_Content_44 = {
    Text = "Les personnes du cru y croient, en tout cas. À cause de l'expédition précédente."
  },
  AvgDialog_145527_Content_45 = {
    Text = "L'expédition précédente ?"
  },
  AvgDialog_145527_Content_46 = {
    Text = "Oui. Depuis que la rumeur de la Déesse de la Montagne s'est répandue, le Continent du Nord de la Fin est devenu une terre entièrement gouvernée par la quête des vœux, avec toute une société construite autour de l'ascension. Cette équipe d'alpinistes était la plus disciplinée et la mieux entraînée de toutes celles qui avaient jamais tenté l'aventure ; elles avaient les meilleures chances d'atteindre le sommet."
  },
  AvgDialog_145527_Content_47 = {
    Text = "Ils étaient sept au départ. Mais au cours de l'ascension, les membres de l'équipe sont morts les uns après les autres."
  },
  AvgDialog_145527_Content_48 = {
    Text = "L'un a quitté la tente en pleine nuit, marchant pieds nus dans la tempête de neige ; un autre a coupé sa corde de sécurité et a sauté d'une falaise de glace ;"
  },
  AvgDialog_145527_Content_49 = {
    Text = "Un autre encore a disparu pendant plusieurs jours, pour finalement être retrouvé mort de froid en avant de l'équipe —"
  },
  AvgDialog_145527_Content_5 = {
    Text = "Alors que vous discutiez des plans pour Partir le lendemain, une tête blanche surgit soudainement à l'entrée du camp."
  },
  AvgDialog_145527_Content_50 = {
    Text = "Comme s'il avait continué à gravir la montagne après sa mort."
  },
  AvgDialog_145527_Content_51 = {
    Text = "Sans se concerter, tout le groupe ralentit ses gestes en faisant l'inventaire."
  },
  AvgDialog_145527_Content_52 = {
    Text = "Au final, un seul est revenu vivant au pied de la montagne."
  },
  AvgDialog_145527_Content_53 = {
    Text = "Mais on ne peut pas vraiment dire qu'il est «revenu vivant»."
  },
  AvgDialog_145527_Content_54 = {
    Text = "Que veux-tu dire ?"
  },
  AvgDialog_145527_Content_55 = {
    Text = "Ses dix doigts étaient entièrement gelés et gangrenés, ses oreilles remplies de Neige mêlée de Sang. Quoi qu'on lui demande, il ne faisait que répéter en boucle les mêmes quelques phrases."
  },
  AvgDialog_145527_Content_56 = {
    Text = "Naraka baisse la voix, imitant le ton des Murmures dans un Rêve du survivant."
  },
  AvgDialog_145527_Content_57 = {
    Text = "<Shake:«La légende est vraie. Le vœu au sommet est réel.»>"
  },
  AvgDialog_145527_Content_58 = {
    Text = "<Shake:<Red:«Bouchez-vous les oreilles, n'écoutez pas.»>>"
  },
  AvgDialog_145527_Content_59 = {
    Text = "<Shake:«Ceux qui entendent le chant seront attirés, Dévorés… puis s'élèveront vers le ciel pour devenir la <Red:Lune>.»>"
  },
  AvgDialog_145527_Content_6 = {
    Text = "Dites-moi~ c'est bien l'équipe d'alpinisme de Naraka ici ?"
  },
  AvgDialog_145527_Content_60 = {
    Text = "Et ensuite quoi ?"
  },
  AvgDialog_145527_Content_61 = {
    Text = "Plus Tard…"
  },
  AvgDialog_145527_Content_62 = {
    Text = "Naraka esquissa un sourire étrange, à mi-chemin entre l'amusement et l'ironie."
  },
  AvgDialog_145527_Content_63 = {
    Text = "Les habitants pensaient qu'ils avaient profané la déesse de la montagne. Craignant que ces étrangers n'attirent la colère de la déesse sur leurs villages…"
  },
  AvgDialog_145527_Content_64 = {
    Text = "Alors, ils choisirent une nuit sans lune et venteuse pour le jeter dans une crevasse de glace aux profondeurs insondables."
  },
  AvgDialog_145527_Content_65 = {
    Text = "C'est là la fin de l'histoire ?"
  },
  AvgDialog_145527_Content_66 = {Text = "Non."},
  AvgDialog_145527_Content_67 = {
    Text = "Depuis lors, à chaque pleine lune, ceux qui passaient près de cette crevasse entendaient encore quelqu'un chanter En Dessous."
  },
  AvgDialog_145527_Content_68 = {
    Text = "Ainsi, tout le monde sut qu'il disait vrai. Il devait exister quelque chose sur cette montagne."
  },
  AvgDialog_145527_Content_69 = {
    Text = "Naraka baissa de nouveau la tête et enroula la corde en cercles dans Les Sacs à Dos, Comme Si ce qu'il venait de raconter n'était qu'une vieille histoire sans importance."
  },
  AvgDialog_145527_Content_7 = {
    Text = "Vous me cherchez ?"
  },
  AvgDialog_145527_Content_70 = {
    Text = "Dans le bref silence, Seulement le vent balayait la tente, laissant échapper un gémissement long et sourd."
  },
  AvgDialog_145527_Content_71 = {
    Text = "J'ai aussi entendu dire que, lors de leur ascension, ils avaient entendu le chant des Sirènes."
  },
  AvgDialog_145527_Content_72 = {
    Text = "Vous racontez encore n'importe quoi — les Sirènes sont des monstres marins, comment pourraient-elles apparaître sur une montagne ?"
  },
  AvgDialog_145527_Content_73 = {
    Text = "Caraboo fit la moue avec mécontentement et émit un petit grognement."
  },
  AvgDialog_145527_Content_74 = {
    Text = "S'il y a des monstres chanteurs dans la mer, pourquoi n'y en aurait-il pas dans les montagnes ?"
  },
  AvgDialog_145527_Content_75 = {
    Text = "Croyez-le ou non, c'est votre affaire. Quand vous entendrez le chant, pensez à vous boucher les oreilles."
  },
  AvgDialog_145527_Content_76 = {
    Text = "Vous vouliez poser d'autres questions, mais vous découvrîtes que Caraboo s'était déjà retourné pour rentrer dans la cabane, sans intention de poursuivre la discussion."
  },
  AvgDialog_145527_Content_77 = {Text = "新增"},
  AvgDialog_145527_Content_78 = {
    Text = "Sept jours plus tard"
  },
  AvgDialog_145527_Content_79 = {
    Text = "L'entraînement d'aujourd'hui est terminé. Demain, c'est le grand jour de l'ascension."
  },
  AvgDialog_145527_Content_8 = {
    Text = "Hé hé, j'ai entendu dire que tu étais le meilleur guide d'alpinisme de tout le peuple Sherpa !"
  },
  AvgDialog_145527_Content_80 = {
    Text = "Caraboo s'avança soudainement et intercepta Naraka qui s'apprêtait à partir."
  },
  AvgDialog_145527_Content_81 = {
    Text = "Vous ne pratiquez pas <Yellow:le Rituel Lhasang> ?"
  },
  AvgDialog_145527_Content_82 = {
    Text = "Le Rituel Lhasang, qu'est-ce que c'est ?"
  },
  AvgDialog_145527_Content_83 = {
    Text = "Avant chaque ascension, dix Sherpas sur dix accomplissent ce rituel de Prière. N'avez-vous donc aucun respect pour la Divinité ?"
  },
  AvgDialog_145527_Content_84 = {
    Text = "Naraka se frappa le front."
  },
  AvgDialog_145527_Content_85 = {
    Text = "<Yellow:Ah, avec tout ce qui se passe, cela m'était sorti de l'esprit.>"
  },
  AvgDialog_145527_Content_86 = {
    Text = "Comment peut-on oublier une telle chose ?"
  },
  AvgDialog_145527_Content_87 = {
    Text = "Ce n'est pas grave, demain matin je ferai rapidement une version simplifiée."
  },
  AvgDialog_145527_Content_88 = {Text = "新增"},
  AvgDialog_145527_Content_89 = {
    Text = "Vous faites rouler vos épaules endolories et poussez la Porte de la chambre ; un mince filet de fumée s'est déjà glissé dans le couloir."
  },
  AvgDialog_145527_Content_9 = {
    Text = "Par la Bénédiction de la déesse des Neiges, tu pourrais m'emmener gravir la montagne ?"
  },
  AvgDialog_145527_Content_90 = {
    Text = "William se tient à quelques pas devant le miroir en cuivre, lissant un à un les plis de son col."
  },
  AvgDialog_145527_Content_91 = {
    Text = "Bonjour, Gardien."
  },
  AvgDialog_145527_Content_92 = {
    Text = "Vous humez l'air. Il porte une odeur de bois brûlé et d'herbes, avec un parfum frais et glacé en dessous."
  },
  AvgDialog_145527_Content_93 = {
    Text = "En poussant la grande Porte, le froid et l'épaisse fragrance de fumée vous envahissent ensemble."
  },
  AvgDialog_145527_Content_94 = {
    Text = "Au milieu de la cour, un petit brûloir à encens est allumé. Une fumée bleu-blanc s'élève des branches de pin et de cyprès mêlées aux herbes aromatiques, montant tout droit vers le ciel gris-bleu."
  },
  AvgDialog_145527_Content_95 = {
    Text = "Les Sherpas considèrent les sommets comme des divinités, et l'Everest est la demeure de la déesse Mère du Monde."
  },
  AvgDialog_145527_Content_96 = {
    Text = "Avant la première ascension officielle, les Sherpas construisent un autel, hissent des drapeaux de prières, récitent des écritures et accomplissent « le Rituel Lhasang » près de l'autel, laissant la fumée porter les offrandes et les Prières aux esprits."
  },
  AvgDialog_145527_Content_97 = {
    Text = "Le rituel de bénédiction est assez complexe ; une cérémonie officielle peut même durer de trois à quatre heures."
  },
  AvgDialog_145527_Content_98 = {
    Text = "Naraka sortit d'un sac en tissu une botte de branches de pin et de cyprès, et en distribua une à chaque personne."
  },
  AvgDialog_145527_Content_99 = {
    Text = "Levez-les haut, rapprochez-les."
  },
  AvgDialog_145528_Content_1 = {
    Text = "Vous vous jetez sur lui et serrez de toutes vos forces la taille de Castor par derrière. Castor se débat encore, ses cordes vocales Presque Déchirées à force de hurler dans le vent et la Neige."
  },
  AvgDialog_145528_Content_10 = {
    Text = "Evelyn s'approcha pas à pas. Elle s'accroupit pour se retrouver à la hauteur du jeune homme que Vous et William mainteniez ensemble dans la neige."
  },
  AvgDialog_145528_Content_11 = {
    Text = "Castor, écoute-moi. Moi aussi, j'ai cru autrefois que le Wendigo n'était qu'une créature de légende."
  },
  AvgDialog_145528_Content_12 = {
    Text = "Mais tout à l'heure… je l'ai <Yellow:entendu>."
  },
  AvgDialog_145528_Content_13 = {
    Text = "J'ai entendu… <Yellow:mon mari m'appeler>."
  },
  AvgDialog_145528_Content_14 = {
    Text = "Depuis le jour de sa disparition, j'entends cet Appel chaque jour, mais jamais aussi clairement, jamais aussi réel…"
  },
  AvgDialog_145528_Content_15 = {
    Text = "La voix d'Evelyn se fait légèrement rauque un instant."
  },
  AvgDialog_145528_Content_16 = {
    Text = "<Shake:Mais Castor… tu sais…>"
  },
  AvgDialog_145528_Content_17 = {
    Text = "Cela fait plus de quatre-vingt-dix jours que mon mari a disparu dans les montagnes enneigées, le délai optimal pour le secourir est largement dépassé."
  },
  AvgDialog_145528_Content_18 = {
    Text = "Dans le meilleur des cas, je ne pourrais que tomber sur ses ossements quelque part sur un sentier de montagne."
  },
  AvgDialog_145528_Content_19 = {
    Text = "Il ne sera pas vivant… ici. Ton frère, encore moins."
  },
  AvgDialog_145528_Content_2 = {
    Text = "Castor, ce n'est pas lui."
  },
  AvgDialog_145528_Content_20 = {
    Text = "Nous devons continuer à monter, jusqu'au sommet de la montagne."
  },
  AvgDialog_145528_Content_21 = {
    Text = "C'est notre seule chance de Rencontre à nouveau avec eux."
  },
  AvgDialog_145528_Content_22 = {
    Text = "Castor, apaisé par Evelyn, se calma peu à peu."
  },
  AvgDialog_145528_Content_23 = {
    Text = "Tu as raison… il ne peut pas y avoir de cellule d'isolement sur une montagne enneigée… il n'est pas dans un endroit pareil."
  },
  AvgDialog_145528_Content_24 = {
    Text = "Je vais tenir bon… jusqu'à ce que je le retrouve."
  },
  AvgDialog_145528_Content_25 = {
    Text = "Derrière vous, quelqu'un frappa deux coups secs sur le rocher avec son piolet."
  },
  AvgDialog_145528_Content_26 = {
    Text = "Si tout le monde a retrouvé son calme, nous devons nous préparer à faire face à la véritable menace."
  },
  AvgDialog_145528_Content_27 = {
    Text = "<Yellow:Wendigo>."
  },
  AvgDialog_145528_Content_3 = {
    Text = "<Shake:Comment savez-vous que ce n'est pas lui ?! Vous ne le connaissez même pas !>"
  },
  AvgDialog_145528_Content_4 = {
    Text = "Vous ne le connaissez aucun de vous ! Seulement moi je le connais, je connais sa voix !! C'est moi qui l'ai abandonné là-bas !"
  },
  AvgDialog_145528_Content_5 = {
    Text = "C'est la première fois qu'il élève la voix contre William. Puis il se surprend lui-même de sa propre voix."
  },
  AvgDialog_145528_Content_6 = {
    Text = "Castor, calme-toi, c'est un <Yellow:Wendigo>."
  },
  AvgDialog_145528_Content_7 = {
    Text = "Le Wendigo, monstre des montagnes… il fouille les ombres les plus profondes de ton cœur…"
  },
  AvgDialog_145528_Content_8 = {
    Text = "Puis, il emprunte la voix de ceux qui te manquent pour attirer les Égarés dans ses pièges."
  },
  AvgDialog_145528_Content_9 = {
    Text = "<Shake:Non, de quel droit es-tu si certain —>"
  },
  AvgDialog_145529_Content_1 = {
    Text = "Un Autre Printemps"
  },
  AvgDialog_145529_Content_10 = {
    Text = "<Shake:Ici… où suis-je ?>"
  },
  AvgDialog_145529_Content_100 = {
    Text = "Une vie paisible, un aîné bienveillant."
  },
  AvgDialog_145529_Content_101 = {
    Text = "Et même ce petit lapin."
  },
  AvgDialog_145529_Content_102 = {
    Text = "Le lièvre des champs se retourna, ses deux grands Yeux ronds croisant le regard d'Elle."
  },
  AvgDialog_145529_Content_103 = {
    Text = "Puis il fit volte-face, donna un coup de pattes dans la terre et disparut dans son terrier."
  },
  AvgDialog_145529_Content_11 = {
    Text = "D'après les dernières paroles de Caraboo, nous nous trouvons en ce moment, en Position normale, dans les entrailles de la montagne."
  },
  AvgDialog_145529_Content_12 = {
    Text = "La priorité absolue est de trouver un Chemin pour Échapper."
  },
  AvgDialog_145529_Content_13 = {
    Text = "Je ne suis jamais venu ici non plus, je crains de ne pouvoir vous servir de guide."
  },
  AvgDialog_145529_Content_14 = {
    Text = "Ne vous inquiétez pas, nous avons vécu des moments bien plus difficiles que celui-ci."
  },
  AvgDialog_145529_Content_15 = {
    Text = "%player%, qu'est-ce que vous avez dans la main ?"
  },
  AvgDialog_145529_Content_16 = {
    Text = "Oh, c'est… le Fil d'Arachne…"
  },
  AvgDialog_145529_Content_17 = {
    Text = "Sans que l'on sache quand, ce Fil s'est discrètement enroulé autour de votre petit doigt."
  },
  AvgDialog_145529_Content_18 = {
    Text = "Ce Fil, autrefois plongé dans le Silence et d'une douceur apaisante, brille à présent d'un éclat envoûtant et mouvant, son extrémité s'étendant naturellement vers les ténèbres lointaines."
  },
  AvgDialog_145529_Content_19 = {
    Text = "Est-ce là le guide du Destin ? Suivons-le pour voir où il mène."
  },
  AvgDialog_145529_Content_2 = {
    Text = "ténèbres. Des ténèbres sans fin."
  },
  AvgDialog_145529_Content_20 = {
    Text = "Caraboo suivit le Fil, sans savoir combien de temps elle avança. Au bout du Fil, une lueur apparut."
  },
  AvgDialog_145529_Content_21 = {
    Text = "De la lumière… ?"
  },
  AvgDialog_145529_Content_22 = {
    Text = "La lumière et les ombres se transformèrent soudainement."
  },
  AvgDialog_145529_Content_23 = {
    Text = "Ici, c'est... ?"
  },
  AvgDialog_145529_Content_24 = {
    Text = "Hé, Caraboo, doucement !"
  },
  AvgDialog_145529_Content_25 = {
    Text = "Regardez, Tante Rosa, il y a un lapin là-bas !"
  },
  AvgDialog_145529_Content_26 = {
    Text = "Il s'est enfui dans un terrier !"
  },
  AvgDialog_145529_Content_27 = {
    Text = "Elle attendit du jour jusqu'à la nuit, mais le lapin ne sortit jamais."
  },
  AvgDialog_145529_Content_28 = {
    Text = "Tante Rosa, je l'ai vu de mes propres yeux ! Le lapin est entré directement dans ce terrier !"
  },
  AvgDialog_145529_Content_29 = {
    Text = "Tante Rosa caressa doucement les cheveux de Caraboo."
  },
  AvgDialog_145529_Content_3 = {
    Text = "Aïe, aïe, aïe… Où suis-je ?"
  },
  AvgDialog_145529_Content_30 = {
    Text = "Petite sotte, les lapins ne sont pas des animaux si simples que ça."
  },
  AvgDialog_145529_Content_31 = {
    Text = "Les terriers sous ces champs sont comme un immense réseau enchevêtré de tunnels. Ils sont tous reliés."
  },
  AvgDialog_145529_Content_32 = {
    Text = "Le petit lapin blanc que tu avais repéré s'est enfui depuis longtemps par l'un de ces terriers, on ne sait lequel."
  },
  AvgDialog_145529_Content_33 = {
    Text = "Alors qu'est-ce qu'on fait ?"
  },
  AvgDialog_145529_Content_34 = {
    Text = "On ne fait rien, petite Caraboo."
  },
  AvgDialog_145529_Content_35 = {
    Text = "Nous semons dans les champs, nous Arrosons, nous Attendons que les récoltes mûrissent, nous cueillons et savourons les fruits que la Divinité nous a accordés."
  },
  AvgDialog_145529_Content_36 = {
    Text = "Mais, et si je voulais ce lapin ?"
  },
  AvgDialog_145529_Content_37 = {
    Text = "Ma chère petite Caraboo, nous ne convoitons pas ce lapin. Si tu veux manger de la viande, nous pouvons aller au marché en échangeant des fruits et légumes."
  },
  AvgDialog_145529_Content_38 = {
    Text = "Mais, et si je voulais quand même ce lapin ?"
  },
  AvgDialog_145529_Content_39 = {
    Text = "<Red:Pourquoi… Pourquoi ne puis-je pas avoir ce lapin ?>"
  },
  AvgDialog_145529_Content_4 = {
    Text = "Inutile de poser la question, Elle savait déjà. Elle se trouvait dans le ventre du ver."
  },
  AvgDialog_145529_Content_40 = {Text = "新增"},
  AvgDialog_145529_Content_41 = {Text = "新增"},
  AvgDialog_145529_Content_42 = {
    Text = "Pourquoi, en ce moment, est-ce que je vois des souvenirs de mon enfance… ?"
  },
  AvgDialog_145529_Content_43 = {
    Text = "Du calme. C'est peut-être parce que j'ai marché trop longtemps dans les ténèbres, j'ai des Illusions."
  },
  AvgDialog_145529_Content_44 = {
    Text = "Ce n'est pas une Illusion, tu sais ?"
  },
  AvgDialog_145529_Content_45 = {
    Text = "<Shake:Aaah ! Un fantôme ! !>"
  },
  AvgDialog_145529_Content_46 = {
    Text = "Vous souvenez-vous de l'un des sept artefacts sacrés, le Fil du Destin ? Ce que vous voyez, c'est la Trajectoire du Destin."
  },
  AvgDialog_145529_Content_47 = {
    Text = "À présent, la Trajectoire du Destin vous révélera une autre possibilité, ainsi que son point de divergence."
  },
  AvgDialog_145529_Content_48 = {
    Text = "En quoi tout cela me concerne-t-il, moi qui suis coincée dans le ventre d'un monstre en ce moment ?"
  },
  AvgDialog_145529_Content_49 = {
    Text = "Parce que c'est votre vœu. Les vœux sont des mèches qui guident chacun vers sa fin prédestinée."
  },
  AvgDialog_145529_Content_5 = {
    Text = "Maudite bête, m'avoir attirée ici pour finalement me dévorer."
  },
  AvgDialog_145529_Content_50 = {
    Text = "Arrête les devinettes ! Tu ne pourrais pas utiliser ce souffle pour me dire comment sortir d'ici ?! <BigShake:HÉ—>"
  },
  AvgDialog_145529_Content_51 = {
    Text = "L'ombre disparut sans faire le moindre bruit."
  },
  AvgDialog_145529_Content_52 = {
    Text = "Pfff, quel rabat-joie. Tant pis, de toute façon il n'y a pas d'autre embranchement dans la cavité abdominale du ver, continuons d'avancer."
  },
  AvgDialog_145529_Content_53 = {Text = "新增"},
  AvgDialog_145529_Content_54 = {Text = "新增"},
  AvgDialog_145529_Content_55 = {
    Text = "Tante Rosa ! Ne vous inquiétez pas, j'arrive vous aider !"
  },
  AvgDialog_145529_Content_56 = {
    Text = "C'est… moi ?"
  },
  AvgDialog_145529_Content_57 = {
    Text = "Ma bonne petite, ta tante est Juste venue te voir."
  },
  AvgDialog_145529_Content_58 = {
    Text = "Tante, vous avez du mal à marcher, vous n'avez pas besoin de venir tout le temps à la plantation. Je finis de cueillir ce basilic, et je rentre avec vous pour nourrir les lapins."
  },
  AvgDialog_145529_Content_59 = {
    Text = "Vous les avez vus ? Laitue a eu une portée la nuit dernière ! Plein de petits lapins, de toutes les couleurs !"
  },
  AvgDialog_145529_Content_6 = {
    Text = "Attendez, qu'est-ce que c'est ? Un Fil… ?"
  },
  AvgDialog_145529_Content_60 = {
    Text = "Notre Caraboo est devenue une grande demoiselle."
  },
  AvgDialog_145529_Content_61 = {
    Text = "Tante, qu'est-ce que vous dites. Ces travaux agricoles, je pouvais déjà les faire seule à treize ans."
  },
  AvgDialog_145529_Content_62 = {
    Text = "La meilleure décision que ta tante ait prise de toute sa vie, c'est de t'avoir prise auprès de moi en te retirant à tes parents."
  },
  AvgDialog_145529_Content_63 = {
    Text = "Quand vous m'avez dit que votre père vous frappait lorsqu'il était ivre, j'ai hésité toute une nuit, puis Tôt le Matin, j'ai pris le premier train."
  },
  AvgDialog_145529_Content_64 = {
    Text = "J'ai failli me battre avec votre père avant de réussir à vous ramener."
  },
  AvgDialog_145529_Content_65 = {
    Text = "Depuis lors, cela fait presque dix ans, n'est-ce pas ?"
  },
  AvgDialog_145529_Content_66 = {
    Text = "Maintenant, sans vous, avec ces jambes qui sont les miennes, je ne saurais vraiment pas comment vivre seul—"
  },
  AvgDialog_145529_Content_67 = {
    Text = "Ah— Ah—"
  },
  AvgDialog_145529_Content_68 = {
    Text = "C'est, cette nuit-là— cette nuit-là— une autre possibilité—"
  },
  AvgDialog_145529_Content_69 = {
    Text = "Ce soir-là, la nuit où elle rencontra «le Ver de la Montagne», la nuit où elle décida de se libérer du Destin de ses propres mains."
  },
  AvgDialog_145529_Content_7 = {
    Text = "Un Fil cristallin et lumineux surgit des ténèbres lointaines et s'immobilisa devant Caraboo."
  },
  AvgDialog_145529_Content_70 = {
    Text = "Appartenant au monde réel, la nuit qu'elle avait vécue."
  },
  AvgDialog_145529_Content_71 = {
    Text = "Au crépitement des flammes dans la cheminée, elle se tenait devant le lit de son père ivre, hésitant longuement, très longuement."
  },
  AvgDialog_145529_Content_72 = {
    Text = "Vas-y, fais ce que tu as toujours voulu faire."
  },
  AvgDialog_145529_Content_73 = {
    Text = "Elle leva le couteau—"
  },
  AvgDialog_145529_Content_74 = {
    Text = "C'est ça, exactement."
  },
  AvgDialog_145529_Content_75 = {
    Text = "Tue-le, et tout le monde pourra être heureux."
  },
  AvgDialog_145529_Content_76 = {
    Text = "Puis lentement, lentement, Elle le reposa."
  },
  AvgDialog_145529_Content_77 = {
    Text = "Désolée, je n'en suis toujours pas capable."
  },
  AvgDialog_145529_Content_78 = {
    Text = "Pars, Tant Que tu fuis loin d'ici, tu n'auras plus à endurer la souffrance."
  },
  AvgDialog_145529_Content_79 = {
    Text = "Petite inutile."
  },
  AvgDialog_145529_Content_8 = {
    Text = "Peu importe, peu importe, tu as intérêt à ne pas me tromper !"
  },
  AvgDialog_145529_Content_80 = {
    Text = "Peu importe, c'est autre chose en toi qui m'intéresse."
  },
  AvgDialog_145529_Content_81 = {
    Text = "Allons-y, avec ta langue rusée, nous pourrons tout de même obtenir le trésor le plus précieux."
  },
  AvgDialog_145529_Content_82 = {
    Text = "Le lendemain matin, je me cachai en secret dans la paille d'une charrette à bœufs et me glissai jusqu'à la ville la plus proche."
  },
  AvgDialog_145529_Content_83 = {
    Text = "Puis, grâce à une Identité et des billets falsifiés, je montai dans le train en direction de l'Est."
  },
  AvgDialog_145529_Content_84 = {
    Text = "Depuis lors, j'ai eu de nombreuses Identités : la nièce du chef de train, l'amie du Garde, la Fée de la secte, la déesse de la montagne de Neige…"
  },
  AvgDialog_145529_Content_85 = {
    Text = "J'ai laissé tout mon passé derrière moi, abandonné dans cette nuit de grande neige où je fuyais."
  },
  AvgDialog_145529_Content_86 = {
    Text = "Plus Tard, bien longtemps après, c'est par la bouche d'un compatriote croisé sur le champ de bataille que j'appris —"
  },
  AvgDialog_145529_Content_87 = {
    Text = "Monsieur Hans ?"
  },
  AvgDialog_145529_Content_88 = {
    Text = "Un jour de grande neige, il s'était saoulé jusqu'à l'ivresse."
  },
  AvgDialog_145529_Content_89 = {
    Text = "Le feu dans la cheminée avait été éteint par la neige fondue qui s'infiltrait par le plafond, et d'habitude, c'était sa petite fille qui allait le rallumer."
  },
  AvgDialog_145529_Content_9 = {
    Text = "Vous émergez de votre torpeur, et devant Vous s'étend un vide doux, humide et oppressant."
  },
  AvgDialog_145529_Content_90 = {
    Text = "Juste ce jour-là, cette petite fille n'était plus à la maison, sans que l'on sache pourquoi."
  },
  AvgDialog_145529_Content_91 = {
    Text = "Il mourut de froid cette nuit de neige."
  },
  AvgDialog_145529_Content_92 = {
    Text = "Nous n'avons plus jamais revu cette petite fille non plus."
  },
  AvgDialog_145529_Content_93 = {
    Text = "Au fait, grande Fée, pourquoi vous renseignez-vous soudainement là-dessus ? Ma Bénédiction, pouvez-vous me l'accorder ?"
  },
  AvgDialog_145529_Content_94 = {
    Text = "Caraboo prit une grande poignée de bonbons et les tendit au jeune homme devant elle."
  },
  AvgDialog_145529_Content_95 = {
    Text = "Par la Fée des cieux, un par jour — une fois ces bonbons bénis terminés, votre blessure à la jambe sera guérie."
  },
  AvgDialog_145529_Content_96 = {
    Text = "Même si elle savait pertinemment qu'aucun bonbon ne pourrait jamais guérir les deux jambes déjà amputées du jeune homme."
  },
  AvgDialog_145529_Content_97 = {Text = "新增"},
  AvgDialog_145529_Content_98 = {Text = "新增"},
  AvgDialog_145529_Content_99 = {
    Text = "Quelle ironie, vraiment quelle ironie. Il s'avère que ce soir-là, Tant Que je ne faisais rien, j'aurais pu obtenir le bonheur que je désirais tant."
  },
  AvgDialog_145530_Content_1 = {
    Text = "Le Long Rêve"
  },
  AvgDialog_145530_Content_10 = {
    Text = "Dans ce cas, je vous soutiens."
  },
  AvgDialog_145530_Content_11 = {
    Text = "Je vous soutiens pour retrouver la part de vous-même qui avait été abandonnée."
  },
  AvgDialog_145530_Content_12 = {
    Text = "Après tout, nous sommes les personnes les plus égoïstes qui soient."
  },
  AvgDialog_145530_Content_13 = {
    Text = "La montagne de Neige est morte."
  },
  AvgDialog_145530_Content_14 = {
    Text = "<Shake:C'est terminé…>"
  },
  AvgDialog_145530_Content_15 = {
    Text = "Au centre de la montagne de Neige s'ouvrit une blessure saisissante, allant du sommet de la tête du ver jusqu'à l'extrémité de sa cavité abdominale."
  },
  AvgDialog_145530_Content_16 = {
    Text = "Le corps du ver, le long de cette blessure, s'effondrait lentement, lentement, vers les deux côtés."
  },
  AvgDialog_145530_Content_17 = {
    Text = "Vous aussi, avec l'effondrement du sommet, vous tombâtes en chute libre."
  },
  AvgDialog_145530_Content_18 = {
    Text = "<Shake:Attention, la montagne va s'effondrer !>"
  },
  AvgDialog_145530_Content_19 = {
    Text = "Dans le sifflement du vent de la chute, vous entendîtes, sans vous y attendre, un Murmure."
  },
  AvgDialog_145530_Content_2 = {
    Text = "Vous avez pris votre décision ?"
  },
  AvgDialog_145530_Content_20 = {
    Text = "Ce n'est pas fini."
  },
  AvgDialog_145530_Content_21 = {
    Text = "Caraboo tendit la main."
  },
  AvgDialog_145530_Content_22 = {
    Text = "Sur Le Visage d'Elle, strié de larmes, apparut un sourire nonchalant."
  },
  AvgDialog_145530_Content_23 = {
    Text = "Puis, dans la gravité que vous ne pouviez maîtriser, les sept anneaux de lumière s'illuminèrent."
  },
  AvgDialog_145530_Content_24 = {
    Text = "Ce qui est mort… Seulement la montagne enneigée… Le rituel… fonctionne encore !"
  },
  AvgDialog_145530_Content_25 = {
    Text = "En cet instant, le ciel et la terre semblèrent perdre toute voix. Comme Si le monde entier s'était tu."
  },
  AvgDialog_145530_Content_26 = {
    Text = "Vous ne voyiez que ses lèvres bouger légèrement, laissant échapper des mots qui ne commencèrent à résonner entre ciel et terre que de longues secondes plus tard."
  },
  AvgDialog_145530_Content_27 = {
    Text = "Mon vœu, c'est qu'il n'y ait plus jamais Un Mensonge en ce monde."
  },
  AvgDialog_145530_Content_28 = {
    Text = "Au moment même où ses mots franchirent ses lèvres, le monde devant Elle se désintégra."
  },
  AvgDialog_145530_Content_29 = {
    Text = "Une cendre argentée et abondante tombait depuis les hauteurs lointaines, avec une légèreté et une lenteur extrêmes."
  },
  AvgDialog_145530_Content_3 = {
    Text = "Oui, j'ai déjà décidé."
  },
  AvgDialog_145530_Content_30 = {
    Text = "C'était un effondrement silencieux, un crash lent, la Chute du rideau d'un Rêve aussi ancien qu'éternel."
  },
  AvgDialog_145530_Content_31 = {
    Text = "Les sommets."
  },
  AvgDialog_145530_Content_32 = {
    Text = "La Neige accumulée."
  },
  AvgDialog_145530_Content_33 = {Text = "Le ciel."},
  AvgDialog_145530_Content_34 = {Text = "La Terre."},
  AvgDialog_145530_Content_35 = {
    Text = "Tout ce qui avait existé, comme Un Mensonge démasqué, se réduisit au Vide."
  },
  AvgDialog_145530_Content_36 = {
    Text = "......Pourquoi ?"
  },
  AvgDialog_145530_Content_37 = {
    Text = "Une connaissance que Vous n'auriez pas dû posséder, mêlée à de lointains souvenirs, s'enfonça comme une Épine dans votre esprit."
  },
  AvgDialog_145530_Content_38 = {
    Text = "Ce navire est un rêve, mais lorsque le voile du mensonge se lève..."
  },
  AvgDialog_145530_Content_39 = {
    Text = "Le monde entier est aussi le rêve de quelqu'un, c'est juste que ce rêve est plus grand, plus illusoire et plus lointain..."
  },
  AvgDialog_145530_Content_4 = {
    Text = "C'est un mensonge, une trahison."
  },
  AvgDialog_145530_Content_40 = {
    Text = "Même le soleil, la lune et les étoiles sont nés de sa fiction ; seuls les êtres enchevêtrés avec son esprit peuvent…"
  },
  AvgDialog_145530_Content_41 = {
    Text = "<Italic:Le monde entier n'est qu'un énorme mensonge.>"
  },
  AvgDialog_145530_Content_42 = {
    Text = "Accompagnée de cette prise de conscience, la désintégration s'accéléra. Du ciel tomba une pluie dense et argentée."
  },
  AvgDialog_145530_Content_43 = {
    Text = "La pluie tombe dans l'eau. Ces fragments qui avaient jadis formé le «monde» se transformèrent en gouttes argentées, descendant lentement vers les profondeurs insondables d'une mer sans fond."
  },
  AvgDialog_145530_Content_44 = {
    Text = "Et Vous étiez là, au sein de cette mer."
  },
  AvgDialog_145530_Content_45 = {
    Text = "Sombrant, sombrant."
  },
  AvgDialog_145530_Content_46 = {
    Text = "Jusqu'à ce que le long Rêve illusoire prenne fin, et que Vous rouvriez les yeux."
  },
  AvgDialog_145530_Content_47 = {
    Text = "Pour faire face au réel de ce monde."
  },
  AvgDialog_145530_Content_48 = {
    Text = "Au plus profond des abysses d'Aequor."
  },
  AvgDialog_145530_Content_49 = {
    Text = "Le majestueux Royaume Divin, depuis longtemps anéanti, révéla enfin sa véritable apparence."
  },
  AvgDialog_145530_Content_5 = {
    Text = "Tout le monde a pris soin de vous, ils ont aussi des vœux qu'ils souhaitent réaliser."
  },
  AvgDialog_145530_Content_6 = {
    Text = "Mais l'occasion de faire un vœu, il n'y en a qu'une seule."
  },
  AvgDialog_145530_Content_7 = {
    Text = "Même ainsi, vous voulez quand même formuler <Yellow:«ce»> vœu ?"
  },
  AvgDialog_145530_Content_8 = {
    Text = "Il n'y a pas de vœu plus important que celui-ci."
  },
  AvgDialog_145530_Content_9 = {
    Text = "L'ombre sourit."
  },
  AvgDialog_145531_Content_1 = {Text = "Bonne Nuit"},
  AvgDialog_145531_Content_10 = {
    Text = "Dans son dos, quelqu'un ouvrit silencieusement un Œil, Épiant sa silhouette qui s'éloignait."
  },
  AvgDialog_145531_Content_11 = {
    Text = "Tinct suivit lentement le Chemin d'où provenait le chant, les éclats de glace et le sol gelé crissant sous ses chaussures à semelles fines."
  },
  AvgDialog_145531_Content_12 = {
    Text = "(C'est ici… le lac de glace de tout à l'heure…)"
  },
  AvgDialog_145531_Content_13 = {
    Text = "(Mais quelque chose est différent…)"
  },
  AvgDialog_145531_Content_14 = {
    Text = "Le lac, gelé en plein jour, s'était Réveillé pour une raison inconnue."
  },
  AvgDialog_145531_Content_15 = {
    Text = "La surface de l'eau, calme et sans rides, Ouvrit les yeux vers le ciel, tel un miroir limpide reflétant silencieusement la Lune éternelle."
  },
  AvgDialog_145531_Content_16 = {
    Text = "Faint, c'est toi ?"
  },
  AvgDialog_145531_Content_17 = {
    Text = "(L'eau du lac… d'une clarté inhabituelle…)"
  },
  AvgDialog_145531_Content_18 = {
    Text = "Elle plongea son regard vers le fond du lac."
  },
  AvgDialog_145531_Content_19 = {
    Text = "Les eaux du lac étaient d'une profondeur insondable, Comme Si elles Perçaient la Terre, menant vers un endroit bien plus lointain que les Étoiles."
  },
  AvgDialog_145531_Content_2 = {
    Text = "À minuit, Tinct est réveillé par un son lointain et ténu."
  },
  AvgDialog_145531_Content_20 = {
    Text = "Une chanson dérive sur le vent. Rauque, ancienne, comme si elle avait traversé un passage du temps inimaginablement long et ne s'était toujours pas tue."
  },
  AvgDialog_145531_Content_21 = {
    Text = "<Italic:La—la la~ la~ ♪>"
  },
  AvgDialog_145531_Content_22 = {
    Text = "Tinct ferma les yeux et inspira profondément."
  },
  AvgDialog_145531_Content_23 = {
    Text = "(Une mélodie familière… une atmosphère… nostalgique…)"
  },
  AvgDialog_145531_Content_24 = {
    Text = "La texture de cette voix évoquait un lit de rivière asséché, des couches de grès érodées par cent mille ans de vent, le cri de ces forêts anciennes comprimées en charbon sous le poids des ères géologiques."
  },
  AvgDialog_145531_Content_25 = {
    Text = "(On dirait… une mélodie… venue de l'Étoile Maléfique…)"
  },
  AvgDialog_145531_Content_26 = {
    Text = "Les souvenirs d'il y a mille ans commencèrent peu à peu leur Renaissance, et Elle commença à fredonner, tentant de suivre ce chant insaisissable."
  },
  AvgDialog_145531_Content_27 = {
    Text = "<Shake:La la~ la la la~♪>"
  },
  AvgDialog_145531_Content_28 = {
    Text = "Elle le sentit, elle le saisit."
  },
  AvgDialog_145531_Content_29 = {
    Text = "Sur Le Visage d'Elle se dessina une joie sincère."
  },
  AvgDialog_145531_Content_3 = {
    Text = "(Dehors… c'est… du chant ?)"
  },
  AvgDialog_145531_Content_30 = {
    Text = "Sa tessiture s'élargit, vers le haut. Une voix limpide comme celle d'un rossignol vint s'Entrelacér avec grâce et légèreté à la mélodie de fond rauque."
  },
  AvgDialog_145531_Content_31 = {
    Text = "Les deux voix Commencèrent à se tirer, s'enchevêtrer, se rapprocher."
  },
  AvgDialog_145531_Content_32 = {
    Text = "<Change>La la la la la la~♪"
  },
  AvgDialog_145531_Content_33 = {
    Text = "La couche de glace se referma pouce par pouce ; dans les profondeurs du lac, d'innombrables visages blêmes levèrent la tête, guidés par le chant."
  },
  AvgDialog_145531_Content_34 = {
    Text = "Mais Tinct n'en avait aucune conscience."
  },
  AvgDialog_145531_Content_35 = {
    Text = "Seul le chant existait. Le chant traversait Les Prisonniers de la Neige et les terres gelées, traversait l'univers et les mers d'étoiles, traversait les âges éternels, se muant en une présence que chacun devrait considérer comme éternelle."
  },
  AvgDialog_145531_Content_36 = {
    Text = "Oui, je ne devrais plus me mentir à moi-même…"
  },
  AvgDialog_145531_Content_37 = {
    Text = "Je n'ai plus… envie de chercher… L'espoir n'existe nulle part… Elle est dans ma mémoire, et seulement dans ma mémoire…"
  },
  AvgDialog_145531_Content_38 = {
    Text = "L'ancien ami dans l'eau lui tendit la main."
  },
  AvgDialog_145531_Content_39 = {
    Text = "Une voix chantante et vieillie l'appelait doucement, l'appelant par son nom d'il y a mille ans."
  },
  AvgDialog_145531_Content_4 = {
    Text = "Le son est extrêmement doux, remontant depuis une profondeur insondable à travers d'innombrables couches de glace, de neige et de roche."
  },
  AvgDialog_145531_Content_41 = {
    Text = "Je devrais abandonner…"
  },
  AvgDialog_145531_Content_42 = {
    Text = "Ce voyage est trop long, bien trop long, je suis déjà, depuis longtemps, épuisée…"
  },
  AvgDialog_145531_Content_43 = {
    Text = "L'Appel vibrait contre ses os, lui offrant le réconfort qu'elle désirait. Son tourment sans refuge, sa tristesse sans exutoire, étaient enfin pleinement connus et acceptés par une présence."
  },
  AvgDialog_145531_Content_44 = {
    Text = "<Shake:Enlace-moi, Faint… ombre de ma mémoire… enlace-moi, comme autrefois…>"
  },
  AvgDialog_145531_Content_45 = {
    Text = "<Shake:Accorde-moi la Ning que je désire…>"
  },
  AvgDialog_145531_Content_46 = {
    Text = "Elle avança doucement, tout doucement, dans les eaux silencieuses du lac."
  },
  AvgDialog_145531_Content_47 = {
    Text = "Le lac ne frémit pas d'un seul frisson. Comme une langue froide, il lèche tendrement sa taille, ses épaules, sa gorge."
  },
  AvgDialog_145531_Content_48 = {
    Text = "<Change>La la…"
  },
  AvgDialog_145531_Content_49 = {
    Text = "Elle chantait encore."
  },
  AvgDialog_145531_Content_5 = {
    Text = "Elle est rauque et lente, chaque syllabe ressemble à du sable balayé par le vent roulant sur la terre. Tenace et incessante, elle se poursuit comme une rivière souterraine coulant à jamais."
  },
  AvgDialog_145531_Content_50 = {
    Text = "Sa silhouette, son corps, son existence se dissipaient au rythme du chant, se fondant et se dispersant dans la lumière de la lune."
  },
  AvgDialog_145531_Content_51 = {
    Text = "Une pensée, une pensée si ténue qu'elle était Presque impossible à saisir, s'insinua à cet instant, inexplicablement, dans la conscience de Tinct."
  },
  AvgDialog_145531_Content_52 = {
    Text = "(Étrange… aujourd'hui… c'était censé être la nouvelle Lune…)"
  },
  AvgDialog_145531_Content_53 = {
    Text = "Puis — la surface du lac s'effondra soudainement vers l'intérieur."
  },
  AvgDialog_145531_Content_54 = {
    Text = "Pas d'éclaboussures, pas de cris. Seulement le chant qui flottait et s'attardait."
  },
  AvgDialog_145531_Content_55 = {
    Text = "La Lune dans le ciel avait disparu, on ne savait depuis quand."
  },
  AvgDialog_145531_Content_56 = {
    Text = "Il ne restait plus que les eaux du lac ondulant sous la lune, reflétant clairement le reflet de Tinct."
  },
  AvgDialog_145531_Content_57 = {Text = "新增"},
  AvgDialog_145531_Content_58 = {
    Text = "Le lendemain matin."
  },
  AvgDialog_145531_Content_59 = {
    Text = "Quelqu'un a vu Tinct ?"
  },
  AvgDialog_145531_Content_6 = {
    Text = "(Si lointaine, et pourtant si familière…)"
  },
  AvgDialog_145531_Content_60 = {
    Text = "Tout le monde secoua la tête."
  },
  AvgDialog_145531_Content_61 = {
    Text = "Hmm… Hier soir, j'ai entendu du bruit à côté de moi, mais je me suis rendormi très vite."
  },
  AvgDialog_145531_Content_62 = {
    Text = "J'ai fouillé toutes les tentes, elle n'est nulle part."
  },
  AvgDialog_145531_Content_63 = {
    Text = "Elle a peut-être abandonné en cours de route ?"
  },
  AvgDialog_145531_Content_64 = {
    Text = "Hier, quand elle était au bord du lac glacé, son État semblait vraiment bizarre…"
  },
  AvgDialog_145531_Content_65 = {
    Text = "Evelyn marmonnait, Énervée."
  },
  AvgDialog_145531_Content_66 = {
    Text = "Elle n'a même pas emporté de bouteille d'oxygène en sortant."
  },
  AvgDialog_145531_Content_67 = {
    Text = "Nous sommes à six mille mètres d'altitude, chacun doit — et ne peut que — répondre de sa propre PV."
  },
  AvgDialog_145531_Content_68 = {
    Text = "Au moins… au moins allons voir au bord du lac glacé."
  },
  AvgDialog_145531_Content_69 = {
    Text = "Vous y allez ?"
  },
  AvgDialog_145531_Content_7 = {
    Text = "Les membres de l'équipe dans les tentes voisines étaient plongés dans un profond sommeil, épuisés par l'ascension du jour. Même les chiens guides ronflaient."
  },
  AvgDialog_145531_Content_70 = {
    Text = "Vous souhaitez partir à la recherche de Tinct, sans vouloir abandonner la moindre possibilité. Mais Vous savez également que chaque choix que Vous faites engage la vie de toute l'équipe."
  },
  AvgDialog_145531_Content_71 = {
    Text = "Allons-y, l'altitude ici et celle du lac glacé sont Presque identiques, le temps aller-retour reste dans des limites contrôlables."
  },
  AvgDialog_145531_Content_72 = {
    Text = "La seule chose à surveiller, ce sont les bêtes sauvages sur le chemin."
  },
  AvgDialog_145531_Content_8 = {
    Text = "Il est temps de sortir."
  },
  AvgDialog_145531_Content_9 = {
    Text = "Elle dégagea son sac de couchage, souleva la toile de la tente et se glissa lentement dehors."
  },
  AvgDialog_145532_Content_1 = {
    Text = "Il S'est Retourné"
  },
  AvgDialog_145532_Content_10 = {
    Text = "Puis vint le tour d'Evelyn. William fermait la marche, Le Regard calme et concentré veillant sur tout le monde."
  },
  AvgDialog_145532_Content_11 = {
    Text = "Attendez…"
  },
  AvgDialog_145532_Content_12 = {
    Text = "Le Regard d'Evelyn se pose, en Regard fixe, sur un bout de corde accroché à la paroi brisée."
  },
  AvgDialog_145532_Content_13 = {
    Text = "C'est… leur mousqueton ! Je reconnais cette marque !"
  },
  AvgDialog_145532_Content_14 = {
    Text = "L'angle formé par la corniche de Neige ! L'angle formé par la corniche de Neige crée une zone sûre, empêchant la Neige tombante de la recouvrir !"
  },
  AvgDialog_145532_Content_15 = {
    Text = "Vous plongez Le Regard en direction d'Evelyn. Seulement un instant, et l'Illusion de la chute vous donne le vertige."
  },
  AvgDialog_145532_Content_16 = {
    Text = "Je dois aller le trouver !"
  },
  AvgDialog_145532_Content_17 = {
    Text = "Evelyn détacha son mousqueton et descendit lentement."
  },
  AvgDialog_145532_Content_18 = {
    Text = "C'est trop dangereux, Evelyn !"
  },
  AvgDialog_145532_Content_19 = {
    Text = "Ça va, c'est pour ça que je suis venue ! Si on parle de danger, l'escalade elle-même est déjà suffisamment dangereuse !"
  },
  AvgDialog_145532_Content_2 = {
    Text = "Quatre personnes, comme quatre dés, suspendues sur l'échiquier nommé falaise de glace."
  },
  AvgDialog_145532_Content_20 = {
    Text = "Ne vous occupez pas de moi ! Je vous rejoindrai dans un moment !"
  },
  AvgDialog_145532_Content_21 = {
    Text = "Dans les profondeurs de la crevasse glaciaire, Comme Si quelque chose l'attirait."
  },
  AvgDialog_145532_Content_22 = {
    Text = "Evelyn, vous ne pouvez pas — !"
  },
  AvgDialog_145532_Content_23 = {
    Text = "Vous tendez la main vers votre mousqueton, inspirez profondément, prêt à vous laisser tomber."
  },
  AvgDialog_145532_Content_24 = {
    Text = "%player%..."
  },
  AvgDialog_145532_Content_25 = {
    Text = "William retient votre main et secoue doucement la tête."
  },
  AvgDialog_145532_Content_26 = {
    Text = "Personne ne sait si Helot reviendra ou non, nous ne pouvons pas rester tous suspendus dans le vide."
  },
  AvgDialog_145532_Content_27 = {
    Text = "Regarde en haut."
  },
  AvgDialog_145532_Content_28 = {
    Text = "Caraboo a déjà franchi en tête la dernière falaise de glace."
  },
  AvgDialog_145532_Content_29 = {
    Text = "Vers le haut se trouve la destination de ce voyage, la terre promise où tous les vœux se réalisent."
  },
  AvgDialog_145532_Content_3 = {
    Text = "Chacun s'accroche fermement à la corde de sécurité dans sa main, cherchant désespérément le prochain point d'appui."
  },
  AvgDialog_145532_Content_30 = {
    Text = "Vers le bas, un abîme de ténèbres sans fond."
  },
  AvgDialog_145532_Content_31 = {
    Text = "Mais nous ne pouvons plus perdre de coéquipiers — !"
  },
  AvgDialog_145532_Content_32 = {Text = "Je sais."},
  AvgDialog_145532_Content_33 = {
    Text = "Alors, laissez-moi faire."
  },
  AvgDialog_145532_Content_34 = {
    Text = "Avant même que les mots ne vous parviennent, William détache son baudrier et plonge droit dans l'abîsse."
  },
  AvgDialog_145532_Content_35 = {
    Text = "La paroi de glace verticale qui vous a demandé toutes vos forces à l'ascension est franchie en quelques secondes à la descente. En un instant, William et Evelyn ne sont plus que deux minuscules points lointains, engloutis par les mâchoires étroites de la crevasse."
  },
  AvgDialog_145532_Content_36 = {
    Text = "Vous regardez ainsi Evelyn et William descendre de plus en plus bas, en direction de la crevasse."
  },
  AvgDialog_145532_Content_37 = {
    Text = "Puis vous levez la tête et enfoncez le prochain piton dans la roche."
  },
  AvgDialog_145532_Content_38 = {Text = "新增"},
  AvgDialog_145532_Content_39 = {Text = "新增"},
  AvgDialog_145532_Content_4 = {
    Text = "Au-dessus, il y a un rocher que nous devons franchir."
  },
  AvgDialog_145532_Content_40 = {
    Text = "La crevasse glaciaire était sans fond, et lorsqu'ils posèrent à nouveau le pied sur un sol plat, c'était une obscurité totale où l'on ne voyait pas à un centimètre devant soi."
  },
  AvgDialog_145532_Content_41 = {
    Text = "Attendez, Evelyn…"
  },
  AvgDialog_145532_Content_42 = {
    Text = "La lumière de la lampe frontale Danse en s'avançant."
  },
  AvgDialog_145532_Content_43 = {
    Text = "Sous la crevasse semblait se trouver une grotte de stalactites, à l'atmosphère différente des autres endroits. Froide, humide, le vent portait une étrange odeur indéfinissable."
  },
  AvgDialog_145532_Content_44 = {
    Text = "Faites attention où vous mettez les pieds, il y a un affaissement ici…"
  },
  AvgDialog_145532_Content_45 = {
    Text = "Ses mots restèrent coincés dans sa gorge, se transformant en un souffle de froid retenu."
  },
  AvgDialog_145532_Content_46 = {
    Text = "Là où la lumière balayait, se trouvaient des dizaines de squelettes saponifiés."
  },
  AvgDialog_145532_Content_47 = {
    Text = "Ils conservaient la posture dans laquelle ils étaient tombés — certains recroquevillés, d'autres enlacés — recouvrant silencieusement le sol en couches superposées."
  },
  AvgDialog_145532_Content_48 = {
    Text = "C'est… l'uniforme de l'expédition Green."
  },
  AvgDialog_145532_Content_49 = {
    Text = "Ils sont tous là."
  },
  AvgDialog_145532_Content_5 = {
    Text = "Vous vous déplacez avec précaution autour du rocher, vérifiant si le sol sous vos pieds est de la roche solide ou de la neige meuble."
  },
  AvgDialog_145532_Content_50 = {
    Text = "Après un long silence, Evelyn se retourna et regarda les yeux de William avec sérieux."
  },
  AvgDialog_145532_Content_51 = {
    Text = "Il semblerait qu'il n'y ait pas grand-chose ici dont vous auriez besoin, n'est-ce pas ?"
  },
  AvgDialog_145532_Content_52 = {
    Text = "Dans ce cas, pourriez-vous me laisser seule ici un moment ? Je voudrais chercher s'il est là."
  },
  AvgDialog_145532_Content_53 = {
    Text = "Si possible, j'aimerais lui dire quelques mots."
  },
  AvgDialog_145532_Content_54 = {
    Text = "Ces corps pourraient être porteurs de bactéries dangereuses…"
  },
  AvgDialog_145532_Content_55 = {
    Text = "Evelyn exprima sa détermination par le regard."
  },
  AvgDialog_145532_Content_56 = {Text = "Compris."},
  AvgDialog_145532_Content_57 = {
    Text = "Mais promettez-moi que vous en ressortirez saine et sauve."
  },
  AvgDialog_145532_Content_58 = {
    Text = "Oui, d'accord, je vous le promets. J'atteindrai certainement le sommet."
  },
  AvgDialog_145532_Content_59 = {
    Text = "William hocha la tête."
  },
  AvgDialog_145532_Content_6 = {
    Text = "Après l'avoir enfin contourné, avant même que vous puissiez reprendre votre souffle, une fissure aux profondeurs insondables apparaît sous vos pieds."
  },
  AvgDialog_145532_Content_60 = {
    Text = "Je vous attends à l'entrée de la grotte."
  },
  AvgDialog_145532_Content_61 = {Text = "新增"},
  AvgDialog_145532_Content_62 = {Text = "新增"},
  AvgDialog_145532_Content_63 = {
    Text = "Après un très, très long moment — si long que William ressentait Presque l'envie irrépressible d'aller voir à l'intérieur — un froissement de vêtements se fit enfin entendre depuis la grotte."
  },
  AvgDialog_145532_Content_64 = {
    Text = "Puis Evelyn apparut."
  },
  AvgDialog_145532_Content_65 = {
    Text = "Vous… l'avez trouvé ?"
  },
  AvgDialog_145532_Content_66 = {
    Text = "Oui, je l'ai trouvé."
  },
  AvgDialog_145532_Content_67 = {
    Text = "Evelyn hocha la tête, le ton posé, sans la moindre inflexion perceptible."
  },
  AvgDialog_145532_Content_68 = {
    Text = "Toutes mes condoléances."
  },
  AvgDialog_145532_Content_69 = {
    Text = "Non, merci."
  },
  AvgDialog_145532_Content_7 = {
    Text = "Faites attention, ne regardez pas en bas."
  },
  AvgDialog_145532_Content_70 = {
    Text = "Evelyn eut un léger sourire."
  },
  AvgDialog_145532_Content_71 = {
    Text = "Je savais depuis longtemps que ce serait ainsi."
  },
  AvgDialog_145532_Content_72 = {
    Text = "Vous aussi, n'est-ce pas ?"
  },
  AvgDialog_145532_Content_73 = {
    Text = "Vous aussi, vous cherchez quelqu'un qui ne reviendra jamais."
  },
  AvgDialog_145532_Content_74 = {
    Text = "C'est toujours comme ça."
  },
  AvgDialog_145532_Content_75 = {
    Text = "Au début, on garde espoir, en se disant qu'il reviendra peut-être demain."
  },
  AvgDialog_145532_Content_76 = {
    Text = "Puis un lendemain…"
  },
  AvgDialog_145532_Content_77 = {
    Text = "…puis encore un autre lendemain."
  },
  AvgDialog_145532_Content_78 = {
    Text = "L'espoir s'amenuise peu à peu, et la pierre au fond du cœur pèse de plus en plus lourd."
  },
  AvgDialog_145532_Content_79 = {
    Text = "Elle chute, jour après jour, toujours plus bas."
  },
  AvgDialog_145532_Content_8 = {
    Text = "Vous suivez de près Naraka, tenant la corde pour franchir la fissure à grand-peine."
  },
  AvgDialog_145532_Content_80 = {
    Text = "Jusqu'au jour où vous découvrez que vous n'y pensez plus."
  },
  AvgDialog_145532_Content_81 = {
    Text = "Vous mangez, dormez, travaillez, voyagez, parlez aux autres, riez… comme d'habitude."
  },
  AvgDialog_145532_Content_82 = {
    Text = "Et puis, pendant très, très longtemps, vous n'en parlez plus."
  },
  AvgDialog_145532_Content_83 = {
    Text = "La voix d'Evelyn changea légèrement de ton."
  },
  AvgDialog_145532_Content_84 = {
    Text = "Mais vous savez que vous n'avez pas oublié, vous n'avez jamais oublié."
  },
  AvgDialog_145532_Content_85 = {
    Text = "Vous n'oublierez jamais."
  },
  AvgDialog_145532_Content_86 = {
    Text = "Il suffit d'une légende, d'une étincelle, et cela commence à brûler…"
  },
  AvgDialog_145532_Content_87 = {
    Text = "Elle vous engloutira tout entier…"
  },
  AvgDialog_145532_Content_88 = {
    Text = "…et vous réduira en cendres."
  },
  AvgDialog_145532_Content_89 = {
    Text = "William releva brusquement la tête et croisa Le Regard d'Evelyn."
  },
  AvgDialog_145532_Content_9 = {
    Text = "Du coin de l'œil, vous apercevez au fond de la fissure une obscurité absolue qui donne la chair de poule, sans qu'on sache où elle prend fin."
  },
  AvgDialog_145532_Content_90 = {
    Text = "Celle-ci se contenta de le regarder avec douceur en retour ; ce qui emplissait ces Yeux — des flammes ou un vide — il ne pouvait le distinguer, le reflet des lunettes de protection l'en empêchant."
  },
  AvgDialog_145532_Content_91 = {
    Text = "Cessez de rêvasser, allons-y. Je vous ai promis que je monterais au sommet avec vous, n'est-ce pas ?"
  },
  AvgDialog_145532_Content_92 = {
    Text = "Sans savoir pourquoi, William avait toujours l'impression que, malgré Le Regard échangé, l'interlocutrice ne s'adressait pas vraiment à lui."
  },
  AvgDialog_145532_Content_93 = {
    Text = "Evelyn n'attendait déjà plus. Elle se retourna et se dirigea vers l'extérieur de la grotte, se penchant pour vérifier la corde de traction avec des gestes si précis que le Soliloque de tout à l'heure semblait n'avoir jamais eu lieu."
  },
  AvgDialog_145532_Content_94 = {
    Text = "William reste cloué sur place, les mots qu'il n'arrivait pas à prononcer coincés dans sa gorge. Il la regarde disparaître au loin, puis se retourne vers la gueule sombre et béante de la grotte derrière lui."
  },
  AvgDialog_145532_Content_95 = {
    Text = "Il ne trouvait aucune raison de s'attarder une seconde de plus. Il détourna Le Regard et, en Silence, emboîta le pas à Evelyn."
  },
  AvgDialog_145534_Content_1 = {
    Text = "La farce est terminée. À présent, la montagne de neige va vous engloutir."
  },
  AvgDialog_145534_Content_10 = {
    Text = "Le sommet se Déchira brusquement en son centre, s'ouvrant de plus en plus large, se transformant en une gueule béante qui fendait le ciel et la Terre ; une bave écarlate se déversait en torrents le long des rangées de crocs, s'abattant comme une pluie."
  },
  AvgDialog_145534_Content_11 = {
    Text = "La gueule se referma brusquement —"
  },
  AvgDialog_145534_Content_12 = {
    Text = "Avant même que la foule n'ait pu pousser le moindre cri, elle avait déjà été engloutie dans les profondeurs insondables de son ventre."
  },
  AvgDialog_145534_Content_13 = {
    Text = "La Terre cessa de trembler, et dans la Neige qui tombait doucement, un petit chapeau pointu se dressa."
  },
  AvgDialog_145534_Content_14 = {
    Text = "Caraboo secoua la Neige qui la couvrait de partout et inspecta avec satisfaction le fruit de ses efforts —"
  },
  AvgDialog_145534_Content_15 = {
    Text = "Pourquoi ? Pourquoi êtes-vous encore là ?"
  },
  AvgDialog_145534_Content_16 = {
    Text = "Une silhouette solitaire qui n'aurait pas dû exister, celle d'une autre personne."
  },
  AvgDialog_145534_Content_17 = {
    Text = "Je voudrais bien savoir moi aussi pourquoi je suis encore là."
  },
  AvgDialog_145534_Content_18 = {
    Text = "Vous venez de dire que les visiteurs offrent leurs vœux à la montagne, et que la montagne exauce les prières de ceux qui la supplient."
  },
  AvgDialog_145534_Content_19 = {
    Text = "C'est peut-être parce que, comparée à vous tous, je n'ai aucun vœu particulier. Je suis trop ordinaire, trop banale, pas assez savoureuse ?"
  },
  AvgDialog_145534_Content_2 = {
    Text = "Caraboo se retourna, face aux montagnes s'étendant à l'infini, face à la tempête de vent et de Neige."
  },
  AvgDialog_145534_Content_20 = {
    Text = "Non, ce n'est pas possible. Vous n'avez aucun vœu à confier à la montagne ?"
  },
  AvgDialog_145534_Content_21 = {
    Text = "Caraboo écarquilla les Yeux, son interrogation teintée d'une pointe d'incrédulité et d'irritation."
  },
  AvgDialog_145534_Content_22 = {
    Text = "Non. Le seul vœu qui m'avait amenée ici a déjà été exaucé."
  },
  AvgDialog_145534_Content_23 = {
    Text = "Au pied de la dernière falaise, j'ai trouvé ses restes. Quelle chance — il était coincé dans une fissure rocheuse, non enseveli sous la Neige."
  },
  AvgDialog_145534_Content_24 = {
    Text = "La chair a sombré dans la pourriture, mais la Plaque est encore là. Je peux encore le reconnaître, encore confirmer son existence."
  },
  AvgDialog_145534_Content_25 = {
    Text = "Comment est-ce possible, comment peut-on être satisfaite aussi facilement !"
  },
  AvgDialog_145534_Content_26 = {
    Text = "C'est pourtant la réalité. Les vœux des mortels ne devraient pas être des choses qui nécessitent l'intervention d'une puissance divine pour s'accomplir."
  },
  AvgDialog_145534_Content_27 = {
    Text = "Et il y a encore de bonnes nouvelles. D'après l'équipement qu'il portait, ils ont rencontré le malheur lors de leur descente."
  },
  AvgDialog_145534_Content_28 = {
    Text = "Ainsi, de son vivant, il avait déjà accompli son vœu d'atteindre le sommet le plus haut."
  },
  AvgDialog_145534_Content_29 = {
    Text = "Bien qu'à des moments différents, c'est ici même que nous mourrons tous deux en paix."
  },
  AvgDialog_145534_Content_3 = {
    Text = "Ô véritable fée de la montagne de Neige, ô grand dieu des vers, je vous apporte vos Offrandes !"
  },
  AvgDialog_145534_Content_30 = {
    Text = "<Shake:Non, vous vous mentez à vous-même… Ce n'est pas vrai, vous devez vouloir davantage…>"
  },
  AvgDialog_145534_Content_31 = {
    Text = "La voix de Caraboo devenait de plus en plus aiguë, des larmes coulant au coin de ses Yeux."
  },
  AvgDialog_145534_Content_32 = {
    Text = "Evelyn la regardait Juste avec Le Regard empreint de pitié."
  },
  AvgDialog_145534_Content_33 = {
    Text = "La Neige continuait de tomber."
  },
  AvgDialog_145534_Content_34 = {
    Text = "Après un long moment, Evelyn s'avança et épousseta la Neige tombée sur les épaules de Caraboo."
  },
  AvgDialog_145534_Content_35 = {
    Text = "Réfléchissez-y encore. Je vais rejoindre mon mari."
  },
  AvgDialog_145534_Content_36 = {
    Text = "Sur ces mots, elle fredonnait doucement quelque chose, avançant pas à pas vers le bas de la falaise."
  },
  AvgDialog_145534_Content_37 = {
    Text = "Sans corde de sécurité fixée, elle ne craignait pas la chute. La fissure de glace au pied du rocher, c'était là sa destination."
  },
  AvgDialog_145534_Content_38 = {
    Text = "<Shake:Ne pars pas, Evelyn, ne pars pas —>"
  },
  AvgDialog_145534_Content_39 = {
    Text = "Celle qui la refusait n'était pas Evelyn."
  },
  AvgDialog_145534_Content_4 = {
    Text = "Elle était en extase, Elle riait à gorge déployée. Elle se délectait du succès de sa supercherie."
  },
  AvgDialog_145534_Content_40 = {
    Text = "Celle qui la retenait n'était pas non plus quelqu'un d'autre qu'Evelyn."
  },
  AvgDialog_145534_Content_41 = {Text = "Pourquoi"},
  AvgDialog_145534_Content_42 = {
    Text = "Pourquoi… la montagne tremble-t-elle ?…"
  },
  AvgDialog_145534_Content_43 = {Text = "新增"},
  AvgDialog_145534_Content_44 = {
    Text = "Dans les montagnes réside la chose la plus terrifiante qui soit."
  },
  AvgDialog_145534_Content_45 = {
    Text = "Il s'étend sur des milliers de kilomètres, s'enroulant sur les terres qu'il revendique. Il se repaît des cœurs des hommes et dévore leurs illusions."
  },
  AvgDialog_145534_Content_46 = {
    Text = "À présent, Il vient capturer Sa proie."
  },
  AvgDialog_145534_Content_47 = {
    Text = "<Change>Un désir… un désir… un désir ardent…"
  },
  AvgDialog_145534_Content_48 = {
    Text = "Non ! Je les ai tous attirés ici pour toi, tu avais promis de ne pas me manger !"
  },
  AvgDialog_145534_Content_49 = {
    Text = "<Change>Qui respecterait… la promesse… d'un menteur…"
  },
  AvgDialog_145534_Content_5 = {
    Text = "Ô hommes avides, ô hommes stupides."
  },
  AvgDialog_145534_Content_50 = {
    Text = "Le ver sur la Pomme leva lui aussi la voix, éclatant d'un rire strident."
  },
  AvgDialog_145534_Content_51 = {
    Text = "Et d'ailleurs, n'est-ce pas depuis le tout début que vous saviez que l'une des Offrandes était «la Pomme d'Or» ?"
  },
  AvgDialog_145534_Content_52 = {
    Text = "Non, je suis la déesse de la montagne de neige, la Pomme Dorée est mon artefact sacré, je ne peux pas être une Offrande !"
  },
  AvgDialog_145534_Content_53 = {
    Text = "As-tu oublié qui tu es ? Laisse-moi te le rappeler, Caraboo, tu n'es personne."
  },
  AvgDialog_145534_Content_54 = {
    Text = "Vous n'êtes ni une déesse, ni une princesse, ni une fée.\nVous n'êtes qu'une épave née sur un champ de bataille, une réfugiée qui a oublié jusqu'au visage de ses parents."
  },
  AvgDialog_145534_Content_55 = {
    Text = "Vous auriez dû le savoir depuis longtemps… ces Identités que vous vous êtes forgées, ces honneurs obtenus par la tromperie… un jour viendrait où tout cela vous serait rendu, durement, au centuple."
  },
  AvgDialog_145534_Content_56 = {
    Text = "Ce jour, c'est aujourd'hui."
  },
  AvgDialog_145534_Content_57 = {
    Text = "La montagne ouvrit une gueule béante de Sang."
  },
  AvgDialog_145534_Content_58 = {
    Text = "<Change>Entrez… dans mon ventre… et devenez… ma Force…"
  },
  AvgDialog_145534_Content_59 = {Text = "新增"},
  AvgDialog_145534_Content_6 = {
    Text = "Confiez vos désirs à la montagne, confiez vos aspirations à la montagne."
  },
  AvgDialog_145534_Content_60 = {
    Text = "La pente douce devint soudainement abrupte, et Evelyn, à quelques dizaines de mètres seulement de la crevasse glaciaire, abandonna tout ce qui l'encombrait."
  },
  AvgDialog_145534_Content_61 = {
    Text = "Elle arracha les attaches de sa bouteille d'oxygène, ôta ses lourdes chaussures à crampons, puis trancha sans hésitation la corde principale qui la retenait."
  },
  AvgDialog_145534_Content_62 = {
    Text = "Plus rien ne pouvait la retenir désormais."
  },
  AvgDialog_145534_Content_63 = {
    Text = "Elle s'élança, légère, presque joyeuse, vers l'être aimé qui dormait au fond de la crevasse."
  },
  AvgDialog_145534_Content_64 = {
    Text = "Mon amour, je viens te rejoindre."
  },
  AvgDialog_145534_Content_65 = {
    Text = "Dans un nouveau tremblement, Evelyn, avec tendresse, étreignit les ossements de son être aimé."
  },
  AvgDialog_145534_Content_66 = {
    Text = "Dans le champ de vision de sa chute, la montagne enneigée ouvrait une gueule immense, engloutissant cette petite silhouette semblable à un gâteau à la crème et aux cerises."
  },
  AvgDialog_145534_Content_67 = {
    Text = "D'une seule bouchée, au creux des entrailles des montagnes."
  },
  AvgDialog_145534_Content_7 = {
    Text = "<BigShake:La montagne vous écoutera, puis vous «répondra» !>"
  },
  AvgDialog_145534_Content_8 = {
    Text = "En un instant, la montagne se mit soudainement à bouger depuis ses fondations — la Neige immaculée s'effritait et tombait, le corps annelé se tordait, s'enroulait, se dressant segment par segment comme un glacier qui s'effondre."
  },
  AvgDialog_145534_Content_9 = {
    Text = "La «montagne» tout entière se dressa dans un fracas assourdissant, se penchant vers eux, chaque rampement broyant le Champ de neige sous ses pieds en poussière fine."
  },
  AvgDialog_145535_Content_1 = {
    Text = "Invités au Festin"
  },
  AvgDialog_145535_Content_10 = {
    Text = "Tromper ? Et alors, qui ne trompe pas ?"
  },
  AvgDialog_145535_Content_11 = {
    Text = "Tu peux le sentir, n'est-ce pas, %player% ? Je sais que tu peux flairer les mensonges comme moi."
  },
  AvgDialog_145535_Content_12 = {
    Text = "<Yellow:Heureusement, je me suis bien cachée et j'ai réussi à échapper à leurs traqueurs.>"
  },
  AvgDialog_145535_Content_13 = {
    Text = "<Yellow:<Big:Non...! Je ne suis pas fatiguée ! JE NE PARS PAS !>>"
  },
  AvgDialog_145535_Content_14 = {
    Text = "<Yellow:Mes autres obligations en ce monde ont temporairement pris fin.>"
  },
  AvgDialog_145535_Content_15 = {
    Text = "Tinct n'aurait clairement pas survécu à cette nuit-là, mais Elle a choisi de dissimuler sa Maladie — n'est-Elle pas une menteuse ?"
  },
  AvgDialog_145535_Content_16 = {
    Text = "Castor, depuis le moment où il nous a rencontrés, a caché le fait qu'il portait des Ailes — n'est-il pas un menteur ?"
  },
  AvgDialog_145535_Content_17 = {
    Text = "William voulait clairement autre chose. Quelque chose de personnel. Mais il ne voulait pas nous le dire. C'est aussi un menteur, n'est-ce pas ?"
  },
  AvgDialog_145535_Content_18 = {
    Text = "Tout le monde trompe, tout le monde est menteur — pourquoi m'accuser moi en particulier ?"
  },
  AvgDialog_145535_Content_19 = {
    Text = "Mais Tinct voulait juste continuer encore un peu. Quant aux ailes de Castor et au vœu secret de William... c'est leur vie privée."
  },
  AvgDialog_145535_Content_2 = {
    Text = "Qui êtes-vous vraiment ?"
  },
  AvgDialog_145535_Content_20 = {
    Text = "Ils n'ont pas dit la vérité, mais ils n'avaient pas non plus l'intention de causer des Dommages à qui que ce soit."
  },
  AvgDialog_145535_Content_21 = {
    Text = "Comment ne comprenez-Vous toujours pas — les gens, en vivant dans ce monde, ce qu'ils désirent, que ce soit la Force ou un vœu, c'est comme cette Pomme —"
  },
  AvgDialog_145535_Content_22 = {
    Text = "Tout le monde en veut, tout le monde la cherche désespérément…"
  },
  AvgDialog_145535_Content_23 = {
    Text = "Caraboo lança la Pomme au loin d'un geste désinvolte, fit mine de la poursuivre, puis s'effondra théâtralement dans un tas de neige."
  },
  AvgDialog_145535_Content_24 = {Text = "Mais..."},
  AvgDialog_145535_Content_25 = {
    Text = "Toujours, toujours, seul un nombre limité de personnes peut la détenir."
  },
  AvgDialog_145535_Content_26 = {
    Text = "Et moi, je veux en être l'unique et éternelle maîtresse."
  },
  AvgDialog_145535_Content_27 = {
    Text = "Mais le moyen que vous employez pour atteindre ce but, c'est Un Mensonge."
  },
  AvgDialog_145535_Content_28 = {
    Text = "En effet, Un Mensonge ne suffit-il pas ?"
  },
  AvgDialog_145535_Content_29 = {
    Text = "Ce qui vous a attirés ici, ce n'est pas le Destin, ni un dieu-roi, ni quoi que ce soit de grand ou de majestueux — Juste un mensonge, rien qu'un mensonge !"
  },
  AvgDialog_145535_Content_3 = {
    Text = "Caraboo eut un léger rire."
  },
  AvgDialog_145535_Content_30 = {
    Text = "Vous offrez vos Offrandes à la montagne, et la montagne répond à vos vœux selon son humeur. Cela n'est guère différent des Divinités du monde des hommes."
  },
  AvgDialog_145535_Content_31 = {
    Text = "Seulement cette fois, ce que la montagne exige de vous, c'est… votre <RedItalic:tout.>"
  },
  AvgDialog_145535_Content_32 = {
    Text = "Ne croyez pas y parvenir… !"
  },
  AvgDialog_145535_Content_4 = {
    Text = "Qui suis-je vraiment ?"
  },
  AvgDialog_145535_Content_5 = {
    Text = "Ne vous l'ai-je pas dit dès le début ? Je suis la déesse de la montagne de Neige, la fée marraine, l'incarnation de la volonté de la montagne de Neige."
  },
  AvgDialog_145535_Content_6 = {
    Text = "C'est le Guide le plus important, le plus adorable, Caraboo, qui va Vous nourrir à Lui en ce moment même."
  },
  AvgDialog_145535_Content_7 = {
    Text = "Caraboo… vous nous avez trompés."
  },
  AvgDialog_145535_Content_8 = {
    Text = "Vous avez trompé Evelyn qui prenait soin de Vous tout au long du Chemin, vous avez trompé %player% qui a plaidé pour Vous laisser une chance lors de la dispute."
  },
  AvgDialog_145535_Content_9 = {
    Text = "Est-ce là le résultat que vous recherchiez ?"
  },
  AvgDialog_145862_Content_1 = {Text = "Caraboo…"},
  AvgDialog_145862_Content_2 = {
    Text = "Ce que vous venez de dire… c'était vrai ?"
  },
  AvgDialog_145862_Content_3 = {
    Text = "Que penses-tu ?"
  },
  AvgDialog_145862_Content_4 = {
    Text = "Je ne sais pas..."
  },
  AvgDialog_145862_Content_5 = {
    Text = "Alors n'y pensez plus. Faites attention, des ennemis arrivent par là !"
  },
  AvgDialog_146405_Content_1 = {
    Text = "Laissez-moi passer, laissez-moi aller le chercher !"
  },
  AvgDialog_146405_Content_2 = {
    Text = "Pollux m'appelle !"
  },
  AvgDialog_146516_Content_1 = {
    Text = "Maudit soit-il, ces Pustules ne peuvent donc pas être gelées ?"
  },
  AvgDialog_146516_Content_10 = {
    Text = "Jusqu'alors, personne ne prêtait attention aux trésors dont parlait Caraboo."
  },
  AvgDialog_146516_Content_11 = {
    Text = "Après tout, aucune légende ne mentionnait un tel élément."
  },
  AvgDialog_146516_Content_12 = {
    Text = "On disait seulement qu'une fois au sommet, vos vœux seraient exaucés."
  },
  AvgDialog_146516_Content_13 = {
    Text = "Affaire réglée."
  },
  AvgDialog_146516_Content_14 = {
    Text = "Ainsi, lorsque la chaîne d'Helot passa en sifflant au-dessus de vous tous pour accrocher vos sacs, personne ne l'avait vu venir."
  },
  AvgDialog_146516_Content_15 = {
    Text = "Seulement d'innombrables chocolats en forme de pièces d'or s'envolèrent par les déchirures des sacs, se déversant le long de la falaise."
  },
  AvgDialog_146516_Content_16 = {
    Text = "Telle une pluie d'or étincelante."
  },
  AvgDialog_146516_Content_17 = {
    Text = "<Shake:Tinct… Castor…>"
  },
  AvgDialog_146516_Content_18 = {
    Text = "Vous ne savez pas ce que vous avez perdu.\nMais vous avez certainement perdu quelque chose, quelque chose de très important."
  },
  AvgDialog_146516_Content_19 = {
    Text = "Ne abandonnez pas ! Elle se dirige encore vers l'autel au sommet !"
  },
  AvgDialog_146516_Content_2 = {
    Text = "Hmph, ce sont des enfants qui ont grandi dans la neige depuis leur plus jeune âge."
  },
  AvgDialog_146516_Content_20 = {
    Text = "Avant la fin du rituel, il reste encore une chance !"
  },
  AvgDialog_146516_Content_21 = {
    Text = "Caraboo fut la première à reprendre courage et à commencer l'ascension, sans oublier de baisser la tête pour vous appeler."
  },
  AvgDialog_146516_Content_22 = {
    Text = "Sans savoir pourquoi, vous aperçûtes dans ses yeux une joie d'origine inexplicable."
  },
  AvgDialog_146516_Content_23 = {
    Text = "Suivez Caraboo."
  },
  AvgDialog_146516_Content_24 = {
    Text = "Rendez-vous au sommet… avec Helot : Enchaînée."
  },
  AvgDialog_146516_Content_25 = {
    Text = "Au loin, le contour du sommet enneigé apparaissait et disparaissait entre les nuages."
  },
  AvgDialog_146516_Content_26 = {
    Text = "-Altitude 7950 m-"
  },
  AvgDialog_146516_Content_3 = {
    Text = "Les boules enchaînées virevoltent dans les airs, tandis que vous et William protégez Evelyn et Naraka, peinant à tenir sur tous les fronts."
  },
  AvgDialog_146516_Content_4 = {
    Text = "Caraboo se cache derrière un tas de neige, sa silhouette dissimulée par la blancheur immaculée de la neige accumulée."
  },
  AvgDialog_146516_Content_5 = {
    Text = "Vous ne trouvez pas cela étrange ? Elle nous suit depuis le début de l'ascension."
  },
  AvgDialog_146516_Content_6 = {
    Text = "Pourquoi lancer une attaque aussi soudainement ?"
  },
  AvgDialog_146516_Content_7 = {
    Text = "<Shake:Si son but n'est pas de nous tuer, mais plutôt —>"
  },
  AvgDialog_146516_Content_8 = {
    Text = "Trop tard. Les chaînes tourbillonnantes ont séparé tout le monde, vous laissant sans le temps de vous soucier de vos lourds bagages."
  },
  AvgDialog_146516_Content_9 = {
    Text = "<Big:— Nos précieux trésors !>"
  },
  AvgDialog_147080_Content_1 = {Text = "新增"},
  AvgDialog_147080_Content_10 = {
    Text = "Oui, oui, oui, je sais. Mais je ne peux pas vous le dire."
  },
  AvgDialog_147080_Content_100 = {
    Text = "Thésée sortit du labyrinthe grâce au fil d'Ariane, mais leur amour ne reçut pas la Bénédiction de la déesse du Destin…"
  },
  AvgDialog_147080_Content_101 = {
    Text = "Finalement, le dieu Dionysos offrit à Ariane une somptueuse couronne ornée de sept joyaux étincelants."
  },
  AvgDialog_147080_Content_102 = {
    Text = "William jeta un coup d'œil à Caraboo."
  },
  AvgDialog_147080_Content_103 = {
    Text = "Bien qu'ils aient cheminé ensemble et surmonté les épreuves côte à côte, Thésée et Ariane n'étaient peut-être pas destinés à suivre le même Chemin."
  },
  AvgDialog_147080_Content_104 = {
    Text = "Caraboo détourna le regard de William."
  },
  AvgDialog_147080_Content_105 = {
    Text = "Échanger une Coquille vide ayant déjà accompli sa mission contre un vœu capable de Réécrire le Destin — ne trouvez-vous pas que c'est vous qui y perdez ?"
  },
  AvgDialog_147080_Content_106 = {
    Text = "Notre but en gravissant la montagne était précisément de retrouver la propriétaire de la Couronne grâce à cette Couronne."
  },
  AvgDialog_147080_Content_107 = {
    Text = "Vous pouvez lire directement la conscience de Caraboo, et Elle peut observer si nous disons Un Mensonge."
  },
  AvgDialog_147080_Content_108 = {
    Text = "Donc, vous pouvez être certain que ce que je dis en ce moment est la vérité, n'est-ce pas ?"
  },
  AvgDialog_147080_Content_109 = {
    Text = "<Yellow:Mon atout, c'est de dévoiler mon atout>."
  },
  AvgDialog_147080_Content_11 = {
    Text = "Vous répondez par un regard furieux."
  },
  AvgDialog_147080_Content_110 = {Text = "新增"},
  AvgDialog_147080_Content_111 = {
    Text = "<Shake:Ha ha, ha ha ha ha !> Exactement, on peut même exploiter ce mécanisme en sens inverse. Faire des affaires avec des gens intelligents, c'est si simple."
  },
  AvgDialog_147080_Content_112 = {
    Text = "<Big:Préparez-vous à retrouver la liberté !>"
  },
  AvgDialog_147080_Content_113 = {
    Text = "<Shake:Compte à rebours, trois, deux, un —>"
  },
  AvgDialog_147080_Content_114 = {Text = "— Zéro."},
  AvgDialog_147080_Content_115 = {
    Text = "Les parois de Chair de toutes parts se referment sur Vous simultanément, et le mucus suintant des replis se transforme en d'innombrables tentacules effilés qui s'enroulent autour de vos poignets, de vos chevilles et de votre taille."
  },
  AvgDialog_147080_Content_116 = {
    Text = "Attendez, n'est-ce pas un peu différent de la liberté promise —"
  },
  AvgDialog_147080_Content_117 = {
    Text = "J'ai seulement promis de vous faire sortir. Je n'ai jamais promis que le voyage serait confortable."
  },
  AvgDialog_147080_Content_118 = {
    Text = "Une Force irrésistible surgit depuis le sol."
  },
  AvgDialog_147080_Content_119 = {
    Text = "Vous êtes repoussés comme un corps étranger avalé remontant l'œsophage, montant rapidement dans un couloir de Chair étroit et glissant."
  },
  AvgDialog_147080_Content_12 = {
    Text = "Ne vous mettez pas en colère, ne vous mettez pas en colère, je commence à expliquer maintenant."
  },
  AvgDialog_147080_Content_120 = {
    Text = "Le Champ de vision est englouti par les ténèbres. À vos oreilles ne subsistent plus que le son visqueux de la Chair qui frotte, ainsi que les battements de cœur sourds et prolongés de toute la montagne."
  },
  AvgDialog_147080_Content_121 = {Text = "Dong."},
  AvgDialog_147080_Content_122 = {Text = "Dong."},
  AvgDialog_147080_Content_123 = {
    Text = "<Red:Boum —>"
  },
  AvgDialog_147080_Content_124 = {
    Text = "Au dernier battement de cœur, une lumière blanche aveuglante se fend devant Vous."
  },
  AvgDialog_147080_Content_125 = {
    Text = "Un vent violent chargé de Neige et de glace arrive Face à soi."
  },
  AvgDialog_147080_Content_126 = {
    Text = "Vous êtes violemment projetés par cette Force et tombez lourdement dans une neige accumulée jusqu'aux genoux."
  },
  AvgDialog_147080_Content_127 = {
    Text = "Toussotement… Ce type se venge clairement."
  },
  AvgDialog_147080_Content_128 = {
    Text = "Au moins, Il ne Vous a pas facturé de frais de nettoyage au départ. Pour Ses standards d'hospitalité, c'est déjà faire preuve de générosité."
  },
  AvgDialog_147080_Content_129 = {
    Text = "Vous Vous relevez en prenant appui sur la neige. L'odeur de Sang tenace qui persistait dans vos poumons est enfin dissipée par le vent glacial."
  },
  AvgDialog_147080_Content_13 = {
    Text = "Pour discuter de la façon de quitter cet endroit, nous devons d'abord savoir où nous sommes et pourquoi nous nous trouvons ici."
  },
  AvgDialog_147080_Content_130 = {
    Text = "Ce n'est plus la crête de montagne par laquelle Vous étiez arrivés."
  },
  AvgDialog_147080_Content_131 = {
    Text = "À perte de vue, tous les sommets plus bas sont engloutis sous une mer de nuages. Le ciel noir est si proche qu'il semble presque à portée de main, tandis que les Étoiles scintillent par intermittence derrière le rideau de neige soulevé par le vent violent."
  },
  AvgDialog_147080_Content_132 = {
    Text = "Vous vous tenez au sommet le plus élevé de toute la chaîne de montagnes."
  },
  AvgDialog_147080_Content_133 = {
    Text = "Ici, c'est..."
  },
  AvgDialog_147080_Content_134 = {
    Text = "Le véritable sommet."
  },
  AvgDialog_147080_Content_135 = {
    Text = "Une voix s'élève depuis sous la Neige accumulée."
  },
  AvgDialog_147080_Content_136 = {
    Text = "La couche de glace frémit légèrement d'un tremblement, Comme Si ce pic enneigé n'était qu'un fragment d'ossature d'une créature colossale, exposé à l'air libre."
  },
  AvgDialog_147080_Content_137 = {
    Text = "Le site du rituel se trouve devant vous. Replacez les sept artefacts à leur emplacement respectif, et le cercle magique vous indiquera naturellement la marche à suivre."
  },
  AvgDialog_147080_Content_138 = {
    Text = "Vous ne venez pas avec nous ?"
  },
  AvgDialog_147080_Content_139 = {
    Text = "Je suis partout."
  },
  AvgDialog_147080_Content_14 = {
    Text = "Nous sommes dans le ventre du Ver de la Montagne, et la raison pour laquelle le Ver de la Montagne a utilisé le rituel du vœu pour vous attirer tous ici..."
  },
  AvgDialog_147080_Content_140 = {
    Text = "Un rire grave et sourd monte depuis le sol sous vos pieds."
  },
  AvgDialog_147080_Content_141 = {
    Text = "Toute cette montagne est mon enveloppe. Chaque pas que vous faites, vous le posez sur ma Chair."
  },
  AvgDialog_147080_Content_142 = {
    Text = "Alors, ne vous avisez pas de jouer à de ridicules tours."
  },
  AvgDialog_147080_Content_143 = {
    Text = "Avancez. Laissez-moi voir quelle Porte vous m'ouvrirez en fin de compte, vous qui portez tant de vœux."
  },
  AvgDialog_147080_Content_144 = {
    Text = "La Neige s'écarte lentement devant vous."
  },
  AvgDialog_147080_Content_145 = {
    Text = "Un antique escalier de pierre, enseveli sous le vent et la Neige depuis des années innombrables, se révèle, serpentant jusqu'au sommet."
  },
  AvgDialog_147080_Content_146 = {
    Text = "Au bout de l'escalier, sept lueurs dorées et ternes s'allument l'une après l'autre, tels des Yeux endormis depuis des millénaires qui Attendent enfin celui venu les Réveiller."
  },
  AvgDialog_147080_Content_147 = {
    Text = "William monte le premier sur l'escalier de pierre."
  },
  AvgDialog_147080_Content_148 = {
    Text = "Sa main reste posée à l'intérieur de sa veste — Comme Si elle apaisait un vœu auquel il avait renoncé."
  },
  AvgDialog_147080_Content_149 = {
    Text = "En cet instant, personne ne remarque que la Clé, silencieuse depuis des années, émet un tremblement imperceptible à travers le tissu."
  },
  AvgDialog_147080_Content_15 = {
    Text = "C'est pour Dévorer votre Force."
  },
  AvgDialog_147080_Content_150 = {
    Text = "Comme Si quelque chose, au sommet de la montagne, l'Attendait."
  },
  AvgDialog_147080_Content_16 = {
    Text = "Une explication claire et simple."
  },
  AvgDialog_147080_Content_17 = {
    Text = "Alors, la Force des autres alpinistes…"
  },
  AvgDialog_147080_Content_18 = {
    Text = "Elle se trouve dans ces quelques Offrandes."
  },
  AvgDialog_147080_Content_19 = {
    Text = "Le mécanisme de coopération entre Caraboo et le Ver de la Montagne consiste en ceci : elle sélectionne des Offrandes dotées de désirs ardents et d'une nature spirituelle, puis attire ces personnes à pénétrer dans les montagnes."
  },
  AvgDialog_147080_Content_2 = {
    Text = "Alors, cher seigneur, quelle fantaisie vous a donc poussé à incarner un guide Sherpa d'alpinisme ? Ce ne peut tout de même pas être par amour des sports extrêmes humains ?"
  },
  AvgDialog_147080_Content_20 = {
    Text = "La question se pose : pourquoi le Ver de la Montagne a-t-il rompu cette coopération de son propre chef ?"
  },
  AvgDialog_147080_Content_21 = {
    Text = "Parce qu'il savait que j'avais été Ébranlée."
  },
  AvgDialog_147080_Content_22 = {
    Text = "Caraboo évoqua la dernière conversation sur la crête."
  },
  AvgDialog_147080_Content_23 = {
    Text = "Je croyais autrefois que personne ne pouvait Compter la cupidité, que pour réaliser ses vœux, on ne pouvait que s'en remettre à des « choses non humaines ». Mais elle m'a fait comprendre que se contenter de l'ordinaire peut aussi mener au bonheur."
  },
  AvgDialog_147080_Content_24 = {
    Text = "En cet instant, j'ai éprouvé un « vœu » superflu."
  },
  AvgDialog_147080_Content_25 = {
    Text = "Le « vœu » est un appât, une mèche."
  },
  AvgDialog_147080_Content_26 = {
    Text = "Depuis le début, j'étais la « Pomme Dorée » destinée à être Dévorée."
  },
  AvgDialog_147080_Content_27 = {
    Text = "Comment pouvons-nous être sûrs que vous ne nous trompez pas encore ?"
  },
  AvgDialog_147080_Content_28 = {
    Text = "Croyez-le ou non. En ce moment, parmi vous tous, c'est moi qui hais le plus le Ver de la Montagne."
  },
  AvgDialog_147080_Content_29 = {
    Text = "Si ce n'était pas cette nuit de Neige où le Ver de la Montagne m'a piégée et où j'ai conclu Le Testament avec lui… je n'aurais jamais emprunté le Chemin que je suis aujourd'hui."
  },
  AvgDialog_147080_Content_3 = {
    Text = "Si je vous dis que c'est pour défendre la cause des Sherpas, me croirez-vous ?"
  },
  AvgDialog_147080_Content_30 = {
    Text = "<Small:Maudit imposteur>."
  },
  AvgDialog_147080_Content_31 = {
    Text = "Dans le bref Silence, seul le souffle nauséabond des parois de Chair se soulevant et s'abaissant se faisait entendre."
  },
  AvgDialog_147080_Content_32 = {
    Text = "Compris. Tant Que vous ne commettez aucun acte déplacé, nous ne reviendrons pas sur les problèmes passés pour l'instant."
  },
  AvgDialog_147080_Content_33 = {
    Text = "Ce qui est plus urgent maintenant, c'est de trouver un moyen de quitter l'estomac de cette Divinité… de préférence sans avoir recours à la Force de ce monsieur N."
  },
  AvgDialog_147080_Content_34 = {
    Text = "Oh là là, vous gâchez ainsi la bonne volonté du si beau et si généreux monsieur N ?"
  },
  AvgDialog_147080_Content_35 = {
    Text = "Ou croyez-vous vraiment que sortir de Son ventre est aussi simple que de quitter une pièce d'hôtel dont on n'est pas satisfait ?"
  },
  AvgDialog_147080_Content_36 = {
    Text = "Vous avez dit que vous ne pouviez pas nous le dire."
  },
  AvgDialog_147080_Content_37 = {
    Text = "Vous pensez que je vous cache intentionnellement quelque chose ? Comme vous me faites du tort."
  },
  AvgDialog_147080_Content_38 = {
    Text = "N jouait avec la rose apparue du néant entre ses doigts, posant Le Regard sur Caraboo avec une lenteur calculée."
  },
  AvgDialog_147080_Content_39 = {
    Text = "Quelle que soit la méthode que j'aie, je ne peux pas vous la faire connaître. N'est-ce pas, petite menteuse ?"
  },
  AvgDialog_147080_Content_4 = {
    Text = "Je vous crois, et pas seulement sur ce point — je crois aussi que Madame Sorel prône le laisser-faire, que Ryker a raccroché pour ne plus jamais Parier, qu'Erica est d'une sagesse infinie et d'un esprit brillant…"
  },
  AvgDialog_147080_Content_40 = {
    Text = "Caraboo ne réfuta pas. Elle se mordit Seulement la lèvre inférieure de toutes ses forces, évitant le regard de tous."
  },
  AvgDialog_147080_Content_41 = {Text = "Caraboo ?"},
  AvgDialog_147080_Content_42 = {
    Text = "… Il peut m'entendre."
  },
  AvgDialog_147080_Content_43 = {
    Text = "Ce n'est pas une métaphore. À l'âge de six ans, quand je l'ai suivi pour quitter cette nuit de Neige, j'ai mis mon âme en gage auprès de lui."
  },
  AvgDialog_147080_Content_44 = {
    Text = "C'est Le Testament entre lui et moi. Il m'a prêté la Force du «Mensonge», me permettant de tromper tous les gens de ce monde ; et en contrepartie —"
  },
  AvgDialog_147080_Content_45 = {
    Text = "Je ne peux lui cacher aucune de mes pensées."
  },
  AvgDialog_147080_Content_46 = {
    Text = "… Donc, en ce moment, chaque mot que nous prononçons —"
  },
  AvgDialog_147080_Content_47 = {
    Text = "Tant que cela entre dans mes oreilles, dans mon esprit, il sait tout."
  },
  AvgDialog_147080_Content_48 = {
    Text = "La Chair tout autour se tendit brusquement un instant, puis se relâcha lentement. Comme si quelque chose d'immense se cachait derrière le rideau, écoutant tout cela avec un vif intérêt."
  },
  AvgDialog_147080_Content_49 = {
    Text = "Vous comprenez maintenant ?"
  },
  AvgDialog_147080_Content_5 = {
    Text = "Ce n'est pas le moment de se chamailler."
  },
  AvgDialog_147080_Content_50 = {
    Text = "Il y a toujours eu un moyen. Mais si cela venait à parvenir aux oreilles de cette jeune demoiselle, autant jouer au Texas Hold'em avec vos atouts face visible."
  },
  AvgDialog_147080_Content_51 = {
    Text = "Quand nous discutons du plan, demander à Caraboo d'Esquiver un moment ?"
  },
  AvgDialog_147080_Content_52 = {
    Text = "Même si je n'entends pas votre plan, je pourrais percevoir quelque chose d'anormal lors de son exécution."
  },
  AvgDialog_147080_Content_53 = {
    Text = "Je ne peux pas voir vos micro-expressions, vos petits gestes. Sinon, je saurais quelle phrase est Un Mensonge."
  },
  AvgDialog_147080_Content_54 = {
    Text = "Peut-être pourriez-vous ne pas regarder ?"
  },
  AvgDialog_147080_Content_55 = {
    Text = "Non, le mensonge est une atmosphère fluide… et je m'y suis baignée bien trop longtemps."
  },
  AvgDialog_147080_Content_56 = {
    Text = "Parfois, même sans que personne ne parle, je peux sentir l'existence d'Un Mensonge dans l'air figé."
  },
  AvgDialog_147080_Content_57 = {
    Text = "Laissez-moi essayer."
  },
  AvgDialog_147080_Content_58 = {
    Text = "Au son d'un claquement de doigts cristallin, une fumée noire grimpa sur les paupières de Caraboo."
  },
  AvgDialog_147080_Content_59 = {
    Text = "Bien, Ouvrir les yeux maintenant."
  },
  AvgDialog_147080_Content_6 = {
    Text = "Arachne nous a conduits ici, elle a sûrement ses raisons. Et vous, vous devez être un maillon du Destin."
  },
  AvgDialog_147080_Content_60 = {
    Text = "Caraboo Ouvrit les yeux. Tout ce qu'Elle voyait était enveloppé d'une fumée de Distorsion, et même les sons devenaient flous et lointains."
  },
  AvgDialog_147080_Content_61 = {
    Text = "William, quant à lui, baissa soudainement les yeux, les phalanges contre le menton, comme s'il effectuait une Déduction sur une partie d'échecs que lui seul pouvait voir."
  },
  AvgDialog_147080_Content_62 = {Text = "Arrête."},
  AvgDialog_147080_Content_63 = {Text = "Hmm?"},
  AvgDialog_147080_Content_64 = {
    Text = "Inutile de couvrir ses Yeux."
  },
  AvgDialog_147080_Content_65 = {
    Text = "Bien au contraire, à partir de maintenant, j'espère que Caraboo sera sur le qui-vive pour discerner la vérité ou le mensonge de chacune de mes paroles."
  },
  AvgDialog_147080_Content_66 = {
    Text = "Écoutez bien, Caraboo — ou plutôt, le Ver de la Montagne derrière Caraboo. Je veux conclure un marché avec vous."
  },
  AvgDialog_147080_Content_67 = {
    Text = "Les parois de chair frémissent d'un rire moqueur."
  },
  AvgDialog_147080_Content_68 = {
    Text = "Quelle plaisanterie. Vous êtes dans mon ventre. Qu'avez-vous à m'offrir en échange ?"
  },
  AvgDialog_147080_Content_69 = {Text = "Un vœu."},
  AvgDialog_147080_Content_7 = {
    Text = "Vous savez forcément comment sortir d'ici, n'est-ce pas, N ?"
  },
  AvgDialog_147080_Content_70 = {
    Text = "Soudain, le silence s'installe tout autour."
  },
  AvgDialog_147080_Content_71 = {
    Text = "Le cercle des vœux au sommet de la montagne <Yellow:n'a pas été créé par vous>, mais par quelque chose de plus ancien que vous, n'est-ce pas ?"
  },
  AvgDialog_147080_Content_72 = {Text = "新增"},
  AvgDialog_147080_Content_73 = {
    Text = "Le Ver de la Montagne se tut un instant, puis laissa échapper un petit rire non-committal."
  },
  AvgDialog_147080_Content_74 = {
    Text = "Intéressant. Continuez."
  },
  AvgDialog_147080_Content_75 = {
    Text = "Avant cette ascension, la légende que Caraboo a racontée différait quelque peu de celle qui circule parmi les montagnards. En résumé, les montagnards savent seulement qu'atteindre le sommet exauce les vœux, mais ignorent l'existence des sept artefacts."
  },
  AvgDialog_147080_Content_76 = {
    Text = "C'est logique. Si le seul but est d'attirer les humains à gravir la montagne pour les Dévorer ensuite, il n'est pas nécessaire de tisser la légende des sept artefacts."
  },
  AvgDialog_147080_Content_77 = {
    Text = "Il suffit de dire à tout le monde qu'atteindre le sommet exauce les vœux."
  },
  AvgDialog_147080_Content_78 = {
    Text = "Plus la difficulté est grande, moins il y a de prétendants — cette logique élémentaire, vous ne pouvez l'ignorer, à moins que —"
  },
  AvgDialog_147080_Content_79 = {
    Text = "À moins que —"
  },
  AvgDialog_147080_Content_8 = {
    Text = "Je sais… ou peut-être que non… Oh là là, voilà une question bien intéressante."
  },
  AvgDialog_147080_Content_80 = {
    Text = "Le Ver de la Montagne étira sa voix d'un ton sarcastique."
  },
  AvgDialog_147080_Content_81 = {
    Text = "À moins que les sept artefacts existent réellement, et que le rituel pour exaucer les vœux existe réellement lui aussi."
  },
  AvgDialog_147080_Content_82 = {
    Text = "Et si vous vous tapissez près du cercle, ce n'est pas seulement pour Dévorer les alpinistes.\nVous attendez également une occasion d'activer le rituel."
  },
  AvgDialog_147080_Content_83 = {
    Text = "Le monde de Chair retint son souffle."
  },
  AvgDialog_147080_Content_84 = {
    Text = "Puisque vous gardez le rituel depuis si longtemps, pourquoi ne l'activez-vous pas vous-même ?"
  },
  AvgDialog_147080_Content_85 = {
    Text = "Humain, vous posez trop de questions."
  },
  AvgDialog_147080_Content_86 = {
    Text = "Il semble que j'aie posé les bonnes."
  },
  AvgDialog_147080_Content_87 = {
    Text = "Laissez-moi deviner."
  },
  AvgDialog_147080_Content_88 = {
    Text = "Il existe un noyau dans le cercle magique que vous ne pouvez pas déchiffrer, n'est-ce pas ? C'est pourquoi, toutes ces années, vous avez accumulé lot après lot d'offrandes, sans jamais parvenir à ouvrir cette dernière Porte."
  },
  AvgDialog_147080_Content_89 = {
    Text = "Les parois de chair se resserrèrent brusquement, Presque au point d'écraser tout le monde."
  },
  AvgDialog_147080_Content_9 = {
    Text = "Ne tournez pas autour du pot, dites-le directement."
  },
  AvgDialog_147080_Content_90 = {
    Text = "Je sais pourquoi vous ne pouvez pas le déchiffrer. Je viens de jeter un coup d'œil au cercle magique, et les runes qui y sont gravées contiennent du latin et d'autres écritures anciennes."
  },
  AvgDialog_147080_Content_91 = {
    Text = "Et votre… petit Exécuteur, à en juger par le temps écoulé depuis qu'Elle a quitté Notre Foyer, n'a manifestement pas bénéficié d'une bonne éducation académique…"
  },
  AvgDialog_147080_Content_92 = {
    Text = "<Shake:Et alors, si je ne sais pas lire ! Et quoi ?!>"
  },
  AvgDialog_147080_Content_93 = {
    Text = "Le temps était compté, et je n'avais pas eu le temps de le lire en détail avant que vous ne m'avaliez ici. Mais je suppose que ce qui y est consigné concerne en grande partie les connaissances relatives à l'activation du cercle magique."
  },
  AvgDialog_147080_Content_94 = {
    Text = "La déesse du Destin nous a guidés jusqu'ici, les sept artefacts sont réunis. Vous devez savoir que c'est la fois où vous êtes le plus proche de réaliser votre vœu."
  },
  AvgDialog_147080_Content_95 = {
    Text = "Et nous, nous pouvons <Yellow:renoncer volontairement à notre chance de formuler un vœu à la montagne>."
  },
  AvgDialog_147080_Content_96 = {
    Text = "Le Ver de la montagne sombra dans un long Silence. Au moment où vous pensiez qu'il ne répondrait plus, il émit un léger grognement."
  },
  AvgDialog_147080_Content_97 = {
    Text = "Renoncer à un vœu… quel Sacrifice remarquable. Ce que vous voulez ne se limite sûrement pas à ce que je vous laisse partir, n'est-ce pas ?"
  },
  AvgDialog_147080_Content_98 = {
    Text = "Après le rituel, tous les autres artefacts pourront vous revenir, mais nous devons emporter la <Blue:Couronne d'Ariane>."
  },
  AvgDialog_147080_Content_99 = {
    Text = "La Couronne d'Ariane…"
  },
  AvgDialog_147095_Content_1 = {
    Text = "Dans la salle vide, seuls vos pas et ceux de Murphy résonnent."
  },
  AvgDialog_149752_Content_1 = {
    Text = "Repaire du Dragon"
  },
  AvgDialog_149752_Content_10 = {
    Text = "Tu n'as plus rien, tu ne peux plus supporter l'oubli."
  },
  AvgDialog_149752_Content_11 = {
    Text = "Les flammes ardentes ont été éteintes par la pluie, tu franchis une porte sans gardien et tu vois le chaos qui règne partout."
  },
  AvgDialog_149752_Content_12 = {
    Text = "Le château se dresse dans le silence — bidons vides, sacs éventrés, boucliers fracassés, lances brisées, flèches courbées dans le vent comme des touffes de roseaux, l'odeur âcre de la boue humide mêlée à un relent tenace de brûlé."
  },
  AvgDialog_149752_Content_13 = {
    Text = "Il y avait eu ici un combat, et maintenant il ne reste plus que des ombres."
  },
  AvgDialog_149752_Content_14 = {
    Text = "Les ombres se répandent librement dans les ténèbres, escaladent les hauts murs, rampent sur les créneaux, engloutissent les cadavres épars en émettant des gargouillis. Tu t'efforces de ne pas penser à ce que cela signifie."
  },
  AvgDialog_149752_Content_15 = {
    Text = "Suis les ombres… il suffit de suivre les ombres…"
  },
  AvgDialog_149752_Content_16 = {
    Text = "Heu, heu… au sec… au secours…"
  },
  AvgDialog_149752_Content_17 = {
    Text = "Des gémissements douloureux s'échappent d'un heaume déformé, les ombres s'y blottissent comme un amant intime, et tu rassembles ton courage pour t'approcher."
  },
  AvgDialog_149752_Content_18 = {
    Text = "Celui qui a amené les ombres — où est-il allé ?"
  },
  AvgDialog_149752_Content_19 = {
    Text = "<Shake:Les om… bres ? Non, non, c'est un monstre ! Du sang noir… creux à l'intérieur… un chevalier de la mort… c'est vrai, tout est vrai !>"
  },
  AvgDialog_149752_Content_2 = {
    Text = "Qu'est-ce qu'une promesse ? Une magie qui ne devient réelle que si l'on y croit."
  },
  AvgDialog_149752_Content_20 = {
    Text = "<Shake:Fuis… heu… fuis vite ! Un monstre immortel… vengeance… destruction… glouglou… glouglou glouglou…>"
  },
  AvgDialog_149752_Content_21 = {
    Text = "Une voix visqueuse monte de la gorge du monstre, il se convulse comme un poisson échoué, mais son bras se lève lentement, tendant la main vers le paquet que tu tiens dans tes bras, une boue grouillante suintant des jointures de son armure."
  },
  AvgDialog_149752_Content_22 = {
    Text = "Ce sont les ombres. Elles veulent le Graal."
  },
  AvgDialog_149752_Content_23 = {
    Text = "Non, impossible, c'est quelque chose d'important, je ne peux pas te le donner."
  },
  AvgDialog_149752_Content_24 = {
    Text = "Le refus ne sert à rien — les ombres dégoulinent le long des murs et se précipitent vers toi, tu serres le paquet contre toi dans la panique et tu t'enfuis en courant vers les profondeurs du château."
  },
  AvgDialog_149752_Content_25 = {
    Text = "Le porche, la grande salle, la chapelle, un escalier de pierre qui s'enroule en spirale vers les entrailles de la terre — le château est un repaire de dragon plein de dangers. L'air se fait de plus en plus froid, ton souffle et tes pas sont amplifiés couche après couche par les murs de pierre, comme s'ils appartenaient à quelqu'un d'autre."
  },
  AvgDialog_149752_Content_26 = {
    Text = "Des flammes s'allument au bout de l'escalier en spirale, et tu aperçois une silhouette familière."
  },
  AvgDialog_149752_Content_27 = {Text = "O——"},
  AvgDialog_149752_Content_28 = {
    Text = "Tu t'apprêtes à l'appeler avec joie, quand tu réalises soudain que vous n'êtes pas seuls. Le monstre prend la parole avant toi."
  },
  AvgDialog_149752_Content_29 = {
    Text = "<Shake:Toussotements… Ogier… >"
  },
  AvgDialog_149752_Content_3 = {
    Text = "Qu'est-ce que la séparation ? L'instant qui suit l'arrivée."
  },
  AvgDialog_149752_Content_30 = {
    Text = "Comment as-tu pu en arriver là ?"
  },
  AvgDialog_149752_Content_31 = {
    Text = "Mon… apparence ?"
  },
  AvgDialog_149752_Content_32 = {
    Text = "Sur la table étaient disposés vins fins et mets délicats, la vaisselle d'argent scintillant à la lueur des bougies. Sans le froid mordant qui s'infiltrait par les fissures de la roche, cet agencement soigné aurait presque fait oublier qu'on se trouvait dans les profondeurs obscures de la terre."
  },
  AvgDialog_149752_Content_33 = {
    Text = "Le seigneur émacié était assis seul derrière la table, les orbites creuses, les pommettes saillantes, enfoui sous d'épaisses couches de soie, tel un dragon tapi au milieu de ses trésors d'or et d'argent."
  },
  AvgDialog_149752_Content_34 = {
    Text = "Ton chevalier s'avance vers lui pas à pas, traînant derrière lui une longue ombre. Peut-être était-il lui-même une ombre. Ses vêtements étaient en lambeaux, son visage défiguré, ses pas ne faisaient aucun bruit."
  },
  AvgDialog_149752_Content_35 = {
    Text = "Ah oui, si je ne l'avais pas vu de mes propres yeux, j'aurais peine à le croire… toussotements… le plus jeune chevalier de la principauté, réduit à l'état de monstre."
  },
  AvgDialog_149752_Content_36 = {
    Text = "La principauté… est déjà détruite."
  },
  AvgDialog_149752_Content_37 = {
    Text = "À cause de toi."
  },
  AvgDialog_149752_Content_38 = {
    Text = "À cause de la guerre, de la peste, de la cupidité des nations voisines, de notre propre faiblesse. Les raisons qui font tomber une principauté sont nombreuses, je ne suis que, toussotements, la plus insignifiante d'entre elles."
  },
  AvgDialog_149752_Content_39 = {
    Text = "<Shake:Tu… as trahi la principauté… tu t'es allié à l'ennemi… tu as vendu… tes sujets…>"
  },
  AvgDialog_149752_Content_4 = {
    Text = "Qu'est-ce que la mort ? Un lendemain sans adieu."
  },
  AvgDialog_149752_Content_40 = {
    Text = "<Shake:Traître… tu mérites la mort.>"
  },
  AvgDialog_149752_Content_41 = {
    Text = "Oui, oui, comme tu peux le constater, les mauvais fruits sont déjà tombés sur moi. Il ne me reste plus beaucoup de temps, toussotements."
  },
  AvgDialog_149752_Content_42 = {
    Text = "La peste ne m'a pas épargné, Ogier. La mort, elle ne fait pas de distinction, elle attend patiemment à l'autre bout du pont, personne n'y échappe… sauf toi."
  },
  AvgDialog_149752_Content_43 = {
    Text = "Dis-moi, quel pacte as-tu conclu avec le diable ?"
  },
  AvgDialog_149752_Content_44 = {Text = "新增"},
  AvgDialog_149752_Content_45 = {
    Text = "Le prix pour fuir la mort ne peut être que plus lourd que la mort elle-même. Chevalier de la mort… devenir son bourreau, était-ce là ton vœu, ou ta punition ?"
  },
  AvgDialog_149752_Content_46 = {
    Text = "Ogier, le chevalier le plus loyal, le plus pieux de la principauté, ha, <Shake:toussotements…>"
  },
  AvgDialog_149752_Content_47 = {
    Text = "Je suis un maudit traître, et toi, tu ne l'es pas ?"
  },
  AvgDialog_149752_Content_48 = {Text = "!!"},
  AvgDialog_149752_Content_49 = {
    Text = "Un éclair invisible frappe ton chevalier, le clouant sur place. Les ombres dans l'obscurité frémissent violemment, de joie ou de colère — elles ne peuvent plus attendre."
  },
  AvgDialog_149752_Content_5 = {
    Text = "Qu'est-ce que l'oubli ?"
  },
  AvgDialog_149752_Content_50 = {
    Text = "J'ai trahi le Grand Duc, mais toi — toi et ta princesse — vous avez trahi les dieux."
  },
  AvgDialog_149752_Content_51 = {
    Text = "Tu t'en souviens encore… tu oses encore en parler…"
  },
  AvgDialog_149752_Content_52 = {
    Text = "<Red:La princesse sorcière>, toussotement, quelle ironie — ses tours ont finalement été démasqués, et pourtant plus personne ne se souvient même de son nom. Je l'avais dit depuis longtemps : livrez-la, et les flammes de la guerre s'éteindraient, la principauté n'aurait pas à périr."
  },
  AvgDialog_149752_Content_53 = {
    Text = "Tu sais ce qu'elle a attiré, tu le sais très bien. La malédiction… la guerre a commencé à cause d'elle, et s'est terminée à cause d'elle. Grâce à elle, @3 la principauté est devenue un lieu oublié."
  },
  AvgDialog_149752_Content_54 = {
    Text = "Tais-toi ! Tu… tu n'es pas… digne… de parler d'elle !"
  },
  AvgDialog_149752_Content_55 = {
    Text = "Une lance informe fend la longue table en deux, coupes et assiettes s'écrasent au sol, le festin hypocrite vole en éclats, révélant son vrai visage de désolation."
  },
  AvgDialog_149752_Content_56 = {
    Text = "Les ombres étendent leurs pseudopodes visqueux, dévorant avidement tout ce qu'ils touchent, le marécage jaillit de l'obscurité, et le monde commence à sombrer."
  },
  AvgDialog_149752_Content_57 = {
    Text = "La mort… puis l'oubli… comme si rien ne s'était passé. Voilà le sort de ceux qui trahissent les dieux."
  },
  AvgDialog_149752_Content_58 = {
    Text = "C'est elle qui t'a rendu ainsi… entraînant toute la principauté dans le néant, ne laissant derrière elle qu'une marionnette de haine pour répandre une mort bien réelle sur la terre. Accomplir une telle mission — tu appelles ça de la loyauté ?"
  },
  AvgDialog_149752_Content_59 = {
    Text = "Ogier… pour qui es-tu vraiment loyal ?"
  },
  AvgDialog_149752_Content_6 = {Text = "新增"},
  AvgDialog_149752_Content_60 = {
    Text = "<Shake:Non… non… la princesse n'est pas… glouglou… glouglouglouglou…>"
  },
  AvgDialog_149752_Content_61 = {
    Text = "Ton chevalier serre sa tête entre ses mains dans la douleur, les ombres jaillissent de sa poitrine, de ses oreilles, des coins de ses yeux. Les tourments incessants du démon l'ont affaibli, il ne peut plus émettre un son, comme une poupée d'argile qui se dissout dans les eaux noires d'un fleuve."
  },
  AvgDialog_149752_Content_62 = {
    Text = "Sans que vous vous en aperceviez, le seigneur a pivoté son fauteuil roulant — dans le mur de pierre derrière lui se cachait une meurtrière de la taille d'un poing. Une ombre noire semblable à un serpent passe en un éclair, accompagnée d'un bruit sourd, et une lance de fer transperce la poitrine de ton chevalier."
  },
  AvgDialog_149752_Content_63 = {
    Text = "<Big:Ogier ! ! !>"
  },
  AvgDialog_149752_Content_64 = {
    Text = "<Shake:Toussotement toussotement…> Un monstre sorti de sa tombe ferait mieux d'y retourner au plus vite."
  },
  AvgDialog_149752_Content_65 = {
    Text = "Toi et ton petit monstre, vous serez enterrés ici ensemble."
  },
  AvgDialog_149752_Content_66 = {
    Text = "Plusieurs gardes en armure complète surgissent d'un passage secret, boucliers et épées luisant d'un éclat sinistre — le dernier piège vient enfin de se révéler."
  },
  AvgDialog_149752_Content_7 = {Text = "新增"},
  AvgDialog_149752_Content_8 = {
    Text = "<Red:Une malédiction.>"
  },
  AvgDialog_149752_Content_9 = {
    Text = "Malédiction. Fléau. Châtiment. Un vide rongé par les vers. Un lit de rivière brisé. Pourrir dans le silence. S'effriter. Sombrer. Un regard épuisé. Passer de personnage à ombre dans le récit. La dernière mort."
  },
  AvgDialog_149753_Content_1 = {Text = "Calice"},
  AvgDialog_149753_Content_10 = {
    Text = "Rien de ce que j'ai fait n'est digne d'un chevalier, tu l'as vu toi-même."
  },
  AvgDialog_149753_Content_11 = {
    Text = "Pourquoi ? Un chevalier doit combattre les monstres, c'est ton devoir, et tu t'en acquittes très bien."
  },
  AvgDialog_149753_Content_12 = {
    Text = "Et tu cherches quelque chose, n'est-ce pas ? Je l'ai remarqué. Tu fouilles endroit après endroit, depuis ton arrivée en ville, cela fait déjà plusieurs jours. Les monstres t'ont aussi volé quelque chose ?"
  },
  AvgDialog_149753_Content_13 = {Text = "新增"},
  AvgDialog_149753_Content_14 = {
    Text = "\"Nous sommes ici.\""
  },
  AvgDialog_149753_Content_15 = {
    Text = "Une lumière de bougies chaude et dorée baignait les quatre murs, la porte en chêne tenait le vent froid à l'écart ; pour les vagabonds sans abri, l'entrepôt du monastère ouvert par une nuit de pluie pouvait même sauver des vies."
  },
  AvgDialog_149753_Content_16 = {
    Text = "Mais tu ne te laisses pas tromper par les apparences, tu t'en souviens. Ces bourreaux qui se disaient pasteurs, déambulant avec leurs chandeliers, leurs longues robes noires et leurs pendentifs en laiton — ce sont des monstres parmi les monstres."
  },
  AvgDialog_149753_Content_17 = {
    Text = "<Small:Pourquoi sommes-nous venus ici… ce que tu cherches est-il là ?>"
  },
  AvgDialog_149753_Content_18 = {
    Text = "Reste ici et attends-moi, ne me suis pas."
  },
  AvgDialog_149753_Content_19 = {
    Text = "<Big:Quoi ?! Non ! Absolument pas !>"
  },
  AvgDialog_149753_Content_2 = {
    Text = "<Shake:Je ne savais pas, je ne savais pas que c'était — non, non non non, je vous en supplie, je vous en supplie, faites grâce —>"
  },
  AvgDialog_149753_Content_20 = {
    Text = "<Big:Je ne reste pas ici, je refuse de rester ici ! Je veux partir avec toi !>"
  },
  AvgDialog_149753_Content_21 = {
    Text = "Que se passe-t-il ? Mon enfant, as-tu besoin d'aide ?"
  },
  AvgDialog_149753_Content_22 = {
    Text = "Oui, je vous prie de veiller sur elle et de ne pas la laisser s'enfuir."
  },
  AvgDialog_149753_Content_23 = {
    Text = "Oh… il est si tard, et la pluie tombe à verse, où es-tu si pressé d'aller ? Attends que le soleil se lève, ne laisse pas ta petite sœur seule."
  },
  AvgDialog_149753_Content_24 = {
    Text = "Je viendrai la chercher à l'aube."
  },
  AvgDialog_149753_Content_25 = {
    Text = "Si tu y tiens, soit, soit. Pauvre enfant, tu es trempée jusqu'aux os, viens, approche, laisse-moi t'essuyer le visage."
  },
  AvgDialog_149753_Content_26 = {
    Text = "Tu es coincée, incapable de bouger, un tissu de lin sec frotte tes joues, et tu ignores à quel moment il pourrait étouffer ta bouche et ton nez."
  },
  AvgDialog_149753_Content_27 = {
    Text = "La peur écrase ta poitrine, tu ne peux pas respirer, tu ne peux que crier."
  },
  AvgDialog_149753_Content_28 = {
    Text = "<Shake:Reviens ! Tu es mon chevalier, tu dois me protéger, tu ne peux pas m'abandonner — tu me l'avais promis !>"
  },
  AvgDialog_149753_Content_29 = {
    Text = "<Shake:Je t'en supplie, je ne ferai pas de bêtises, laisse-moi venir avec toi !> !"
  },
  AvgDialog_149753_Content_3 = {Text = "Ah !!"},
  AvgDialog_149753_Content_30 = {
    Text = "Tes cris désespérés ont attiré de nombreux regards, certains comme des scarabées, d'autres comme des chèvres, d'autres encore comme des hiboux."
  },
  AvgDialog_149753_Content_31 = {
    Text = "Ils te fixent sans détourner les yeux, comme si tu étais la seule à ne pas en avoir."
  },
  AvgDialog_149753_Content_32 = {
    Text = "<SmallShake:Non… ne pars pas… tu m'avais pourtant promis…>"
  },
  AvgDialog_149753_Content_33 = {
    Text = "<SmallShake:Je t'en supplie, ne m'abandonne pas…>"
  },
  AvgDialog_149753_Content_34 = {
    Text = "J'ai changé d'avis, laisse-la venir avec moi."
  },
  AvgDialog_149753_Content_35 = {
    Text = "Tu relèves brusquement la tête — ton chevalier est revenu sans que tu saches quand, interposant son corps entre toi et les regards des monstres."
  },
  AvgDialog_149753_Content_36 = {
    Text = "Mais où comptes-tu l'emmener ? Les endroits où s'abriter de la pluie en ville se font rares, et aucun n'est vraiment approprié pour une enfant."
  },
  AvgDialog_149753_Content_37 = {
    Text = "L'endroit où je vais n'est pas en ville."
  },
  AvgDialog_149753_Content_38 = {
    Text = "Hors de la ville, il y a encore moins de — Ah ! Ne me dis pas que tu veux aller à ce manoir ?"
  },
  AvgDialog_149753_Content_39 = {
    Text = "Qu'est-ce qu'il a, ce manoir ?"
  },
  AvgDialog_149753_Content_4 = {
    Text = "Les cris furent noyés par la pluie torrentielle, se mêlant au sang qui ruisselait dans les caniveaux au pied des murs, pourrissant avec la boue, le crottin de cheval et les feuilles de légumes, jusqu'à être engloutis par les ruelles sombres."
  },
  AvgDialog_149753_Content_40 = {
    Text = "Là-bas, là-bas… Hélas, vous fuyez aussi, n'est-ce pas ? Enfant, n'approche pas de cet endroit."
  },
  AvgDialog_149753_Content_41 = {
    Text = "Ce seigneur, c'était autrefois un homme bon, mais la guerre, la peste, les calamités se sont succédé comme des marées, et il a fini par ne plus ressembler à un homme. Tout le monde dit qu'il est devenu fou. La ville se vide peu à peu, et ceux qui sont allés mendier du pain ne sont jamais revenus."
  },
  AvgDialog_149753_Content_42 = {
    Text = "Que le Seigneur leur pardonne… Tout le monde dit qu'il mange des gens en secret."
  },
  AvgDialog_149753_Content_43 = {
    Text = "Les monstres mangent les gens, tu le sais depuis longtemps, alors tu n'es pas surprise, tu n'as pas peur… du moins, pas autant. Tu as ton chevalier."
  },
  AvgDialog_149753_Content_44 = {
    Text = "Reste près de moi, quelque chose ne va pas ici."
  },
  AvgDialog_149753_Content_45 = {
    Text = "D'accord, d'accord."
  },
  AvgDialog_149753_Content_46 = {
    Text = "Le vaste manoir est vide et silencieux, sans gardes ni domestiques, comme abandonné depuis longtemps, et dans les longs couloirs étroits ne résonnent que vos pas volontairement étouffés."
  },
  AvgDialog_149753_Content_47 = {
    Text = "Alors… qu'est-ce que tu cherches exactement ? C'est important pour toi ? Dis-moi à quoi ça ressemble, je peux t'aider à le trouver."
  },
  AvgDialog_149753_Content_48 = {
    Text = "Une coupe en or."
  },
  AvgDialog_149753_Content_49 = {
    Text = "Une coupe en or ? Tu veux dire faite en or ? Wow, elle est grande comment, haute comment ? On y met quoi dedans ? L'or, c'est comment, est-ce que ça brille comme la lune la nuit ?"
  },
  AvgDialog_149753_Content_5 = {
    Text = "Le cadavre s'effondra mollement sur le sol, l'éclat froid du métal brilla un instant puis disparut, le meurtrier resserra sa cape et s'éloigna d'un pas rapide, ses pas se perdant eux aussi dans la pluie."
  },
  AvgDialog_149753_Content_50 = {
    Text = "...Je ne sais pas."
  },
  AvgDialog_149753_Content_51 = {
    Text = "Hein ? Ce n'est pas à toi ?"
  },
  AvgDialog_149753_Content_52 = {
    Text = "Non, mais c'est très important pour moi."
  },
  AvgDialog_149753_Content_53 = {
    Text = "Oh ! Je comprends, c'est le Saint Graal, n'est-ce pas ? J'en ai entendu parler dans des histoires — un trésor magique que seul un chevalier ayant surmonté les épreuves peut obtenir. Pas étonnant que tu le cherches depuis si longtemps."
  },
  AvgDialog_149753_Content_54 = {
    Text = "Hum hum, en tant que ta princesse, si tu parviens à obtenir le Saint Graal, cela me sera bénéfique à moi aussi, alors…"
  },
  AvgDialog_149753_Content_55 = {
    Text = "Il s'arrête soudainement, lève l'index et te fait signe de te taire."
  },
  AvgDialog_149753_Content_56 = {
    Text = "Tu t'immobilises aussitôt, retenant ton souffle sans t'en rendre compte. La Lanterne s'éteint, et l'obscurité se referme sur toi, t'enveloppant hermétiquement."
  },
  AvgDialog_149753_Content_57 = {
    Text = "Au quatorzième battement de cœur, un bruit sourd retentit au bout du couloir, accompagné du fracas d'objets qui se brisent en tombant, et quelques cris incontrôlés brisent le silence."
  },
  AvgDialog_149753_Content_58 = {
    Text = "Une lumière apparaît, vacillante, comme les silhouettes de nombreuses personnes se battant violemment. Tu t'élances en courant, mais une vague de chaleur te repousse. C'est du feu — un feu bleu."
  },
  AvgDialog_149753_Content_59 = {
    Text = "Lâ— hum hum — lâchez-moi ! J'étais sur le point de réussir ! Il s'en fallait de si peu, de si peu !"
  },
  AvgDialog_149753_Content_6 = {
    Text = "Tu enfiles à la hâte ta capuche et cours sous la pluie pour réussir tant bien que mal à le suivre."
  },
  AvgDialog_149753_Content_60 = {
    Text = "Une odeur âcre emplit la chambre secrète. Un liquide rouge sombre s'écoule lentement dans des tubes de verre. Les bougies ont enflammé le liquide clair répandu sur le sol, et des flammes bleu pâle brûlent en silence. Au cœur du manoir se cachait une salle d'alchimie secrète."
  },
  AvgDialog_149753_Content_61 = {
    Text = "Au centre de nombreux récipients en verre, une coupe à pied en or pur rayonnait d'un éclat plus vif que la mèche d'une lampe — c'était assurément le Saint Graal."
  },
  AvgDialog_149753_Content_62 = {
    Text = "Qu'est-ce que tu y as mis ?"
  },
  AvgDialog_149753_Content_63 = {
    Text = "Lâchez-moi ! Vous ne comprenez pas ! C'est presque là, ça arrive… Se frayant un chemin à travers les tentures en décomposition, se répandant le long du chemin de l'oubli. Les vivants, les morts, personne n'y échappe… personne n'y échappe…"
  },
  AvgDialog_149753_Content_64 = {Text = "Ça ?"},
  AvgDialog_149753_Content_65 = {
    Text = "Ça… une nuit éternelle sans fin, l'anéantissement ultime… c'est une malédiction… <Shake:La malédiction arrive ! La malédiction qui dévore tout, la malédiction de la <Red:princesse sorcière> !!>"
  },
  AvgDialog_149753_Content_66 = {
    Text = "Que disais-tu ?!"
  },
  AvgDialog_149753_Content_67 = {
    Text = "L'ombre derrière lui frémit violemment. Les flammes se reflètent dans ses yeux écarquillés par la terreur — qu'ont-elles allumé ? La peur, ou l'espoir ?"
  },
  AvgDialog_149753_Content_68 = {
    Text = "Ces mots devaient renfermer un puissant sortilège, car ton chevalier se figea soudain comme une statue de pierre, comme s'il s'éveillait à la vie pour la première fois. Son ombre ne cessait de trembler."
  },
  AvgDialog_149753_Content_69 = {
    Text = "T… toi… tu te souviens d'elle ? De quoi d'autre te souviens-tu ?"
  },
  AvgDialog_149753_Content_7 = {
    Text = "Que cherches-tu ?"
  },
  AvgDialog_149753_Content_70 = {
    Text = "<Shake:Vanité, vanité des vanités, tout est vanité… Les hommes peinent comme poussière sur la pierre, sans passé, sans avenir…>"
  },
  AvgDialog_149753_Content_71 = {
    Text = "Non… la Coupe d'or ! La Coupe d'or est la seule rédemption ! Laisse-moi boire la vérité, laisse-moi— je dois continuer !"
  },
  AvgDialog_149753_Content_72 = {
    Text = "<Big:Réponds à ma question !@1@2Princesse, combien te souviens-tu de ce qui la concerne ?!>"
  },
  AvgDialog_149753_Content_73 = {
    Text = "Les ombres rampent, les ombres déferlent, les ombres dansent frénétiquement, les ombres se resserrent en cercles autour du cou du monstre, dont les deux lèvres s'ouvrent et se ferment en vain."
  },
  AvgDialog_149753_Content_74 = {
    Text = "<Shake:Je me souviens… de la peste… du philtre… de la malédiction… kha, kha… je me souviens, je me souviens de toi…>"
  },
  AvgDialog_149753_Content_75 = {
    Text = "<Shake:<Red:O… Gil>… mon chevalier… toi… fuis…>"
  },
  AvgDialog_149753_Content_76 = {Text = "« Kha. »"},
  AvgDialog_149753_Content_77 = {
    Text = "La phrase n'était pas terminée qu'il ne pouvait déjà plus continuer — les ombres lui brisèrent la nuque. Sa tête bouffie, pareille à un sac de toile grossièrement noué, tomba mollement sur le côté, et deux globes oculaires rouillés apparurent dans les cavités béantes, fixant toujours le vide avec une intensité implacable."
  },
  AvgDialog_149753_Content_78 = {Text = "新增"},
  AvgDialog_149753_Content_79 = {
    Text = "O… Gil ? Serait-ce là… ton nom ?"
  },
  AvgDialog_149753_Content_8 = {
    Text = "Je ne t'ai pas dit que tu pouvais me suivre."
  },
  AvgDialog_149753_Content_80 = {
    Text = "Il se retourna brusquement, tel un spectre dont on aurait percé le secret, son expression oscillant entre l'hébétude et la haine. Les ombres sur le mur vacillaient, dansant d'un pas joyeux, vous enveloppant tous deux en leur centre."
  },
  AvgDialog_149753_Content_81 = {
    Text = "Non, ce n'est pas ça ? Peu importe… de toute façon, quel que soit ton nom, tu es mon chevalier."
  },
  AvgDialog_149753_Content_82 = {
    Text = "Le Graal a été trouvé. Où allons-nous maintenant ?"
  },
  AvgDialog_149753_Content_83 = {
    Text = "Rappelé à lui par tes paroles, il tourna lentement la tête vers la coupe d'or posée sur la table, puis s'arracha péniblement aux ombres et saisit la demi-coupe restante d'antidote — ou de poison, tu ne savais pas."
  },
  AvgDialog_149753_Content_84 = {
    Text = "Tu le vis seulement renverser la tête et avaler d'un trait."
  },
  AvgDialog_149753_Content_85 = {
    Text = "<Big:Hé !!>"
  },
  AvgDialog_149753_Content_9 = {
    Text = "Si je ne te suis pas, que se passera-t-il si tu trahis ta princesse ? Tu n'as même pas voulu le jurer."
  },
  AvgDialog_149754_Content_1 = {
    Text = "Un grondement assourdissant retentit, comme si toute la tour principale tremblait, des briques et des pierres brisées tombent en crépitant, et les monstres restants encerclent étroitement le seigneur au centre, l'escortant en retraite vers le passage secret."
  },
  AvgDialog_149754_Content_10 = {
    Text = "Impossible de savoir combien de chemin vous avez parcouru, mais un vent vous souffle au visage. Salé. La mer."
  },
  AvgDialog_149754_Content_11 = {
    Text = "On est… on est sortis ! Nous nous sommes échappés ! Ogier, tu m'entends ? Nous sommes sauvés !!"
  },
  AvgDialog_149754_Content_12 = {
    Text = "… Ogier ?"
  },
  AvgDialog_149754_Content_13 = {
    Text = "Il ne fait aucun bruit, tu ne sens même pas son souffle. Les vagues frappent les rochers, l'eau glacée de la mer mêlée de pluie te fouette le visage. C'est comme si tu ressentais le froid pour la première fois — tu ne peux t'empêcher de trembler."
  },
  AvgDialog_149754_Content_14 = {
    Text = "<SmallShake:… Toussote… toussote…>"
  },
  AvgDialog_149754_Content_15 = {
    Text = "Ogier ! Dieu merci, je savais que tu ne mourrais pas !"
  },
  AvgDialog_149754_Content_16 = {
    Text = "<Shake:Je… n'ai pas… promis… de te suivre.>"
  },
  AvgDialog_149754_Content_17 = {
    Text = "Je sais, combien de fois vas-tu le répéter. Une princesse a-t-elle besoin de la permission de son chevalier pour aller où bon lui semble ?"
  },
  AvgDialog_149754_Content_18 = {Text = "新增"},
  AvgDialog_149754_Content_19 = {
    Text = "<Shake:J'avais… autrefois… une… princesse.>"
  },
  AvgDialog_149754_Content_2 = {
    Text = "Ton chevalier tient bon de toutes ses forces, sa poitrine brisée laissant échapper un rugissement rauque, mais les ombres déferlent comme une marée. Plutôt que les ennemis, elles semblent vouloir le dévorer vivant."
  },
  AvgDialog_149754_Content_20 = {
    Text = "<Shake:Je n'ai pas… su la protéger.>"
  },
  AvgDialog_149754_Content_21 = {
    Text = "Son murmure faible ressemblait à des paroles de rêve, emporté sans peine par le vent marin. Tu dois retenir ton souffle pour l'entendre."
  },
  AvgDialog_149754_Content_22 = {
    Text = "Avant que la guerre… n'éclate… elle m'a ordonné… de partir…"
  },
  AvgDialog_149754_Content_23 = {
    Text = "J'ai… obéi."
  },
  AvgDialog_149754_Content_24 = {
    Text = "Je n'avais pas prévu… que l'ennemi… arrive si vite… Je n'ai pas pu, toussote, pas pu arriver à temps…"
  },
  AvgDialog_149754_Content_25 = {
    Text = "Le massacre… les cadavres… la peste noire… <Shake:La princesse, elle… elle s'est, toussote toussote toussote toussote !>"
  },
  AvgDialog_149754_Content_26 = {
    Text = "Ne sachant quels douloureux souvenirs lui reviennent en mémoire, tu sens qu'il se recroqueville sur lui-même, comme une limace couverte de sel."
  },
  AvgDialog_149754_Content_27 = {
    Text = "<Shake:C'est moi… je n'ai pas su protéger… tout a disparu… tout disparaîtra…>"
  },
  AvgDialog_149754_Content_28 = {
    Text = "<Shake:Autrefois… je voulais devenir chevalier…>"
  },
  AvgDialog_149754_Content_29 = {
    Text = "<Shake:Mais… maintenant… qui suis-je… donc…>"
  },
  AvgDialog_149754_Content_3 = {
    Text = "Arrêtez ! C'est vous les monstres ! Ne fuyez pas !!"
  },
  AvgDialog_149754_Content_30 = {
    Text = "Le passé est le passé, le présent est le présent. Tu as une princesse maintenant, et tu dois encore me protéger."
  },
  AvgDialog_149754_Content_31 = {
    Text = "Il resta longtemps sans répondre, puis se débattit légèrement."
  },
  AvgDialog_149754_Content_32 = {
    Text = "<Shake:Pose-moi, toussote toussote toussote, par terre.>"
  },
  AvgDialog_149754_Content_33 = {
    Text = "Je suis le plus faible… le plus incapable…"
  },
  AvgDialog_149754_Content_34 = {
    Text = "Celui qui devrait le plus… rester… demeurer… dans un passé… oublié…"
  },
  AvgDialog_149754_Content_35 = {
    Text = "Impossible ! Ta promesse n'est pas encore accomplie, tu veux te rétracter ?"
  },
  AvgDialog_149754_Content_36 = {
    Text = "L'eau de la marée montante dépasse tes genoux, tu avances péniblement dans l'obscurité, les récifs acérés t'entaillent les mollets, tes plaies s'engourdissent sous l'eau salée, tu serres les dents sans laisser échapper un cri de douleur."
  },
  AvgDialog_149754_Content_37 = {
    Text = "Tes paroles sont déchirées par un souffle haletant, tu forces chaque mot à sortir de ta gorge, et à chaque phrase achevée, tu fais un pas en avant, comme si elles te soutenaient pour continuer."
  },
  AvgDialog_149754_Content_38 = {
    Text = "Tu es mon, chevalier, choisi. Si je te laisse rester, comment la princesse pourrait-elle, seule, vaincre les monstres, et accomplir l'aventure ?"
  },
  AvgDialog_149754_Content_39 = {
    Text = "… Ce n'est qu'une histoire."
  },
  AvgDialog_149754_Content_4 = {
    Text = "Prise de panique et de colère, tu lances violemment le paquet que tu tenais dans les bras. Il était bien rempli, et le nœud lâche se défait dans les airs — les affaires de quelqu'un se dispersent alors : des bougies, un peigne, une petite figurine de pierre… et le calice."
  },
  AvgDialog_149754_Content_40 = {
    Text = "Toutes les choses, sont des histoires."
  },
  AvgDialog_149754_Content_41 = {
    Text = "Hier, est l'histoire d'aujourd'hui, aujourd'hui est, l'histoire de demain. Certaines, ont disparu, d'autres, continueront. Mais on ne peut pas, être sans histoire."
  },
  AvgDialog_149754_Content_42 = {
    Text = "Alors, va trouver, l'île aux pommes. Va, souffle, souffle… aller accomplir, notre histoire."
  },
  AvgDialog_149754_Content_5 = {
    Text = "La lumière dorée tourbillonne, s'envole haut au-dessus du marais d'ombres, heurte la paroi rocheuse, rebondit deux fois sur le sol, et finit par rouler exactement aux pieds du seigneur."
  },
  AvgDialog_149754_Content_6 = {
    Text = "Tu le vois lever la main pour arrêter ses gardes, puis se pencher lui-même pour ramasser la petite coupe dorée. Il en caresse les motifs du pouce, comme si quelque chose lui revenait en mémoire, et tourne la tête vers toi avec un regard plein de moquerie."
  },
  AvgDialog_149754_Content_7 = {
    Text = "Puis ce regard se transforme rapidement en terreur."
  },
  AvgDialog_149754_Content_8 = {
    Text = "… Avant que le château ne s'effondre entièrement en ruines, ensevelissant ombres, dragon et reliques, ton chevalier t'a entraînée dans un passage secret."
  },
  AvgDialog_149754_Content_9 = {
    Text = "Il était épuisé, incapable de se tenir debout. Tu t'agrippais à son bras de toutes tes forces, avançant péniblement, comme si tu portais un sac de blé bien lourd."
  },
  AvgDialog_149755_Content_1 = {Text = "Île Pomme"},
  AvgDialog_149755_Content_10 = {
    Text = "La blessure sur ta jambe ne guérissait pas — elle empirait même avec les jours de pluie incessante. En dessous du genou, tout avait enflé comme une carotte, et tu ne pouvais plus faire un seul pas. Ces derniers jours, c'est Ogier qui te portait sur son dos à travers monts et vallées."
  },
  AvgDialog_149755_Content_100 = {
    Text = "Princesse, ne pleurez pas pour moi. Il y a déjà bien trop de monstres. La seule chose que je puisse faire pour vous, c'est protéger ce paradis qui appartient aux hommes, qui vous appartient. C'est mon devoir, et c'est mon expiation."
  },
  AvgDialog_149755_Content_101 = {
    Text = "Je ne marche pas vers ma fin — je la franchirai, car j'ai déjà obtenu l'aube."
  },
  AvgDialog_149755_Content_102 = {
    Text = "Je continuerai à veiller sur vous là où le soleil se lève."
  },
  AvgDialog_149755_Content_103 = {
    Text = "Des ombres jaillirent à la place du sang. Quand un homme s'engouffrait dans ce torrent mugissant, il disparaissait en un clin d'œil — pourtant, les ombres, elles, ne s'effacèrent pas."
  },
  AvgDialog_149755_Content_104 = {
    Text = "Les ombres s'agitent, les ombres déferlent, les ombres se condensent en bouclier, en mur, puis finalement en une immense digue. Tu fixes intensément les ténèbres les plus profondes, jusqu'à ce que la charrette à bœufs tourne au coin d'un virage et que la surface du fleuve disparaisse à ta vue."
  },
  AvgDialog_149755_Content_105 = {
    Text = "Ton chevalier disparut dès lors sans laisser de traces. Il n'avait tenu que la moitié de sa promesse, mais il avait laissé derrière lui des dernières paroles d'une ruse consommée, si bien que même en t'endormant en pleurs, tu attendais le lendemain avec espoir."
  },
  AvgDialog_149755_Content_106 = {
    Text = "Car alors un nouveau soleil se lèverait, jour après jour, immuablement."
  },
  AvgDialog_149755_Content_11 = {
    Text = "Tiens, je viens de les cueillir."
  },
  AvgDialog_149755_Content_12 = {
    Text = "Comme pour te réconforter, il glissa un fruit dans ta main. Tu en pris une bouchée dans un demi-sommeil, et ce n'est qu'en sentant une acidité âpre se répandre à la racine de tes dents que tu réalisas ce que c'était."
  },
  AvgDialog_149755_Content_13 = {
    Text = "… Une pomme ?"
  },
  AvgDialog_149755_Content_14 = {
    Text = "Oui, nous sommes passés devant un verger de pommiers tout à l'heure."
  },
  AvgDialog_149755_Content_15 = {
    Text = "Des pommes… l'Île aux Pommes, y sommes-nous arrivés ?"
  },
  AvgDialog_149755_Content_16 = {Text = "Bientôt."},
  AvgDialog_149755_Content_17 = {
    Text = "Il défit les bandages, appliqua les herbes médicinales sur la plaie, puis les enroula à nouveau, tour après tour. Tu observais son expression et tu sentais que ce n'était pas de l'impatience."
  },
  AvgDialog_149755_Content_18 = {
    Text = "Tu allais insister pour en savoir plus, mais des aboiements au loin, se rapprochant rapidement, t'interrompirent."
  },
  AvgDialog_149755_Content_19 = {
    Text = "Attends — ne cours pas si vite ! Où vas-tu ? Ce n'est pas le chemin du village — Ah !"
  },
  AvgDialog_149755_Content_2 = {
    Text = "……réveil……"
  },
  AvgDialog_149755_Content_20 = {
    Text = "Un chien de berger à l'air menaçant bondit hors des buissons, aboyant bruyamment pour chasser les intrus. La jeune fille qui le poursuivait vous aperçut et ne put s'empêcher de pousser un cri, son panier en osier tombant à terre."
  },
  AvgDialog_149755_Content_21 = {
    Text = "C'était Ogier — de vilaines cicatrices noires couvraient son visage, comme une poupée de chiffon déchirée puis recousue à la va-vite, évoquant d'innombrables légendes terrifiantes."
  },
  AvgDialog_149755_Content_22 = {
    Text = "Il échangea un regard silencieux avec la jeune fille, puis se leva et remit sa capuche."
  },
  AvgDialog_149755_Content_23 = {
    Text = "Nous partons maintenant."
  },
  AvgDialog_149755_Content_24 = {
    Text = "Non… non, ce n'est pas — attendez !"
  },
  AvgDialog_149755_Content_25 = {
    Text = "Ogier venait à peine de faire quelques pas en vous portant sur son dos que la jeune fille se précipita anxieusement à votre suite."
  },
  AvgDialog_149755_Content_26 = {
    Text = "Ne partez pas ! Ce n'est pas ce que je voulais dire, il y a encore beaucoup de malades dans le village, je vais vous y conduire !"
  },
  AvgDialog_149755_Content_27 = {
    Text = "Des malades ?"
  },
  AvgDialog_149755_Content_28 = {
    Text = "Oui, ce sont tous des lépreux. Au début, il n'y avait que des lépreux, puis l'armée est arrivée, elle a détruit d'innombrables villages, mais n'a jamais approché le village des lépreux, alors des gens sans foyer ont fui jusqu'ici, moi y compris."
  },
  AvgDialog_149755_Content_29 = {
    Text = "Ne vous inquiétez pas, tout le monde s'y est habitué. En réalité, mis à part l'apparence, nous ne sommes pas si différents, on mange pareil, on dort pareil, on travaille pareil… La lèpre est bien moins terrifiante que l'armée, on finit par s'y faire."
  },
  AvgDialog_149755_Content_3 = {
    Text = "……il pleut……repose-toi……réveille-toi……"
  },
  AvgDialog_149755_Content_30 = {
    Text = "Pardon, je n'avais pas peur de vous, c'est juste que je n'avais jamais vu… Désolée ! Voici un panier de pommes bleues pour vous, je les ai triées moi-même, je vous garantis les plus grosses et les plus sucrées !"
  },
  AvgDialog_149755_Content_31 = {
    Text = "À quoi devrait ressembler le paradis ?"
  },
  AvgDialog_149755_Content_32 = {
    Text = "Sans monstres, sans désespoir, sans cette panique indicible, sans ces yeux tapis dans l'obscurité, sans craindre de ne plus se réveiller avant de s'endormir, avec une soupe chaude à boire chaque jour."
  },
  AvgDialog_149755_Content_33 = {
    Text = "Tu ne sais pas s'il existe un endroit qui ressemble davantage au paradis que celui-ci."
  },
  AvgDialog_149755_Content_34 = {
    Text = "…C'est bon."
  },
  AvgDialog_149755_Content_35 = {
    Text = "Un petit couteau tranchant incise l'abcès, excisant peu à peu la chair pourrie et nécrosée, un fer chauffé à blanc est appliqué sur la plaie qui saigne sans cesse, la douleur atroce vous arrache des cris étouffés, vous trempant de sueur."
  },
  AvgDialog_149755_Content_36 = {
    Text = "C'est terminé. Le chiffon coincé dans votre bouche est retiré, vous respirez de toutes vos forces, avalant l'air presque jusqu'à l'estomac."
  },
  AvgDialog_149755_Content_37 = {
    Text = "Cette fois c'est différent, vous le savez. Ils sont là pour vous sauver, et votre chevalier est à vos côtés."
  },
  AvgDialog_149755_Content_38 = {
    Text = "Le médicament, repartez le faire bouillir dans de l'eau. Une fois au lever du jour, une fois à la tombée de la nuit."
  },
  AvgDialog_149755_Content_39 = {
    Text = "Bien, merci."
  },
  AvgDialog_149755_Content_4 = {
    Text = "Quelqu'un te réveille doucement d'une légère poussée. Dans ta torpeur, tu entends le murmure de la pluie."
  },
  AvgDialog_149755_Content_40 = {
    Text = "Il sortit quelques pièces en guise de paiement, mais le barbier les refusa d'un geste de la main. Dans cet endroit coupé du monde, les tarifs de l'extérieur n'avaient aucune utilité, les gens d'ici ne vivaient pas pour cela."
  },
  AvgDialog_149755_Content_41 = {
    Text = "<Small:Le ciel s'est éclairci…>"
  },
  AvgDialog_149755_Content_42 = {
    Text = "<Small:Ogier, je veux aller dans le verger de pommiers.>"
  },
  AvgDialog_149755_Content_43 = {
    Text = "Tu as besoin de repos."
  },
  AvgDialog_149755_Content_44 = {
    Text = "Emmène-moi là-bas, j'ai une grande découverte… à te révéler."
  },
  AvgDialog_149755_Content_45 = {
    Text = "Nous y sommes. Quelle grande découverte ?"
  },
  AvgDialog_149755_Content_46 = {
    Text = "Ah… j'ai découvert que cet endroit est bien l'Île aux Pommes, nous l'avons trouvée."
  },
  AvgDialog_149755_Content_47 = {
    Text = "Ton chevalier te dépose sur un tronc d'arbre couché en travers, s'agenouille et redresse délicatement ta jambe blessée. Son regard est attentif et inquiet — de toute évidence, la vérité que tu viens de réaliser ne l'a pas ébranlé."
  },
  AvgDialog_149755_Content_48 = {
    Text = "Mais ce n'est pas une île."
  },
  AvgDialog_149755_Content_49 = {
    Text = "Personne n'a dit qu'une île devait forcément se trouver en mer, n'est-ce pas ? Du moment qu'elle n'est pas reliée à l'extérieur, c'est une île."
  },
  AvgDialog_149755_Content_5 = {
    Text = "La pluie s'est remise à tomber — elle n'avait jamais vraiment cessé."
  },
  AvgDialog_149755_Content_50 = {
    Text = "Et qui plus est, il y a des fées ici."
  },
  AvgDialog_149755_Content_51 = {
    Text = "Des fées ?"
  },
  AvgDialog_149755_Content_52 = {
    Text = "Oui, il y a beaucoup de fées dans le village. Certaines ont le visage d'un lion, d'autres les écailles d'un poisson, et d'autres encore muent comme des serpents — ce sont des fées qui vivent dans un monde enchanté."
  },
  AvgDialog_149755_Content_53 = {
    Text = "Des fées… pas des monstres ?"
  },
  AvgDialog_149755_Content_54 = {
    Text = "Bien sûr que non ! Des fées et des monstres, comment pourraient-ils être pareils ?"
  },
  AvgDialog_149755_Content_55 = {
    Text = "Les monstres dévorent les humains, ils cherchent par tous les moyens à les manger — parfois ils les tuent directement au couteau, parfois ils inventent des mensonges pour les piéger et les découper en morceaux."
  },
  AvgDialog_149755_Content_56 = {
    Text = "Non seulement ils mangent eux-mêmes, mais ils font aussi des soupes, des viandes salées, des bouillies qu'ils donnent à manger aux autres. De la chair humaine partout — ne pas en manger, c'est mourir de faim, mais quiconque en a mangé devient un monstre, si bien que les monstres se multiplient."
  },
  AvgDialog_149755_Content_57 = {
    Text = "Les humains ne mangent pas les humains, et les fées non plus. Sur l'Île aux Pommes, ils sont purs."
  },
  AvgDialog_149755_Content_58 = {
    Text = "Et moi ? Je ne suis ni humain, ni fée. Mes mains sont couvertes de sang, un démon loge en moi — tu as vu de tes propres yeux à quoi il ressemble."
  },
  AvgDialog_149755_Content_59 = {
    Text = "Pourquoi n'as-tu pas peur ?"
  },
  AvgDialog_149755_Content_6 = {
    Text = "La forêt dissimulait les fugitifs en fuite. La nouvelle du massacre perpétré par les monstres au château était parvenue aux oreilles des dirigeants, des avis de recherche tapissaient chaque ville, les chevaliers de l'Église et les mercenaires avaient été mobilisés — vous n'aviez d'autre choix que de marcher jour et nuit."
  },
  AvgDialog_149755_Content_60 = {
    Text = "Pourquoi aurais-tu peur ? Dès la première fois que tu l'as vu, tu savais qu'il était forcément un chevalier. À travers les ombres qui l'enveloppaient sans se dissiper, tu pouvais encore voir en lui la figure du chevalier — si nette, si certaine, comme si tu l'avais déjà rencontré quelque part."
  },
  AvgDialog_149755_Content_61 = {
    Text = "Que faut-il pour devenir un vrai chevalier ? La loyauté, la bravoure, la compassion, le sacrifice, et encore…"
  },
  AvgDialog_149755_Content_62 = {
    Text = "L'adoubement du seigneur."
  },
  AvgDialog_149755_Content_63 = {
    Text = "Hem, hem… Alors, je déclare, au nom de la princesse, que je te fais chevalier."
  },
  AvgDialog_149755_Content_64 = {
    Text = "Tu as vaincu le monstre, obtenu le Graal, repoussé le démon et protégé ma personne. Tu as tenu ta promesse et conduit ta princesse jusqu'à l'île aux Pommes."
  },
  AvgDialog_149755_Content_65 = {
    Text = "Peu importe qui tu étais autrefois, dans notre histoire, tu es un chevalier, et nulle princesse ne craint son propre chevalier."
  },
  AvgDialog_149755_Content_66 = {
    Text = "Tu seras mon chevalier pour toujours."
  },
  AvgDialog_149755_Content_67 = {
    Text = "Son chevalier resta pétrifié, une main crispée sur sa cape, comme s'il cherchait à se dissimuler dans l'ombre de ses larges plis. La cape masquait les traces de l'obscurité, et lui seul savait à quel point ce déguisement cachait sa misère."
  },
  AvgDialog_149755_Content_68 = {
    Text = "Les branches frêles, encore humides de pluie, se posèrent doucement sur ses épaules. Un espoir si lointain qu'il en était presque oublié se réalisa soudain, et ce qui fit frémir son âme n'était pas la joie."
  },
  AvgDialog_149755_Content_69 = {
    Text = "Mais la Peur."
  },
  AvgDialog_149755_Content_7 = {
    Text = "Il y a un village devant. Je vais aller échanger quelques vivres et des médicaments. Repose-toi ici, nous repartirons quand la pluie s'arrêtera."
  },
  AvgDialog_149755_Content_70 = {
    Text = "Les flammes de la terreur s'élevaient du gouffre sans fond, sous ses pieds, au-dessus de sa tête, dans les yeux affolés derrière les fissures. Brûlantes, tièdes, jaillissant d'un cou brisé, déferlant d'une poitrine ouverte. Les flammes se tordaient si violemment que les ombres elles-mêmes devenaient folles. Le feu et l'ombre ne font qu'un."
  },
  AvgDialog_149755_Content_71 = {
    Text = "C'était un massacre, sans honneur, sans justice, pour quiconque. Un dénouement sanglant qui déchirait le vernis des belles paroles — la mort n'était que la mort. Il ne se souvenait pas comment il avait survécu ; peut-être n'avait-il pas survécu du tout."
  },
  AvgDialog_149755_Content_72 = {
    Text = "Monstre déchu, spectre de vengeance, sa quête ressemblait à verser de l'huile sur le feu. L'Âme Perdue glissait inexorablement vers sa fin, n'ayant jamais cru pouvoir être sauvée."
  },
  AvgDialog_149755_Content_73 = {
    Text = "<Shake:Mais… mais…>"
  },
  AvgDialog_149755_Content_74 = {
    Text = "Ogier, Ogier ? Hé, tu écoutes ? J'ai fini, c'est ton tour."
  },
  AvgDialog_149755_Content_75 = {Text = "新增"},
  AvgDialog_149755_Content_76 = {
    Text = "Oui, je le veux."
  },
  AvgDialog_149755_Content_77 = {
    Text = "Au nom de ma patrie perdue, moi, Ogier, fils de la Famille Dansk, vous jure loyauté et respect."
  },
  AvgDialog_149755_Content_78 = {
    Text = "Je vous offre mon bouclier et ma lance, ainsi que ma foi souillée par mes fautes, ma peur éternelle et mon cœur brisé. J'avais perdu mon nom dans la longue nuit, et c'est votre appel qui a allumé l'aube."
  },
  AvgDialog_149755_Content_79 = {
    Text = "Celui qui a trahi ses serments n'est plus digne de foi, mais si votre regard consent encore à se poser sur moi, alors je vous appartiendrai jusqu'au dernier souffle de ma vie."
  },
  AvgDialog_149755_Content_8 = {
    Text = "<Small:D'accord… reviens vite.>"
  },
  AvgDialog_149755_Content_80 = {
    Text = "Les histoires ne commencent pas toujours dans la splendeur — elles peuvent aussi naître sur l'autre rive du désespoir."
  },
  AvgDialog_149755_Content_81 = {
    Text = "Même si la fin se dresse pour l'éternité, projetant son ombre pesante sur toutes choses, avant d'y parvenir, vous avez encore la liberté de choisir ce qui deviendra votre destin."
  },
  AvgDialog_149755_Content_82 = {
    Text = "La brise légère, le soleil, le parfum des pommes mûres, la brume s'élevant de la forêt comme des nuages — le monde est beau comme un tableau, et tu ris de bonheur, comme si tu touchais enfin à une fin heureuse."
  },
  AvgDialog_149755_Content_83 = {
    Text = "Mais tu sais que l'histoire continuera, elle continue toujours."
  },
  AvgDialog_149755_Content_84 = {
    Text = "<Big:Combien de personnes ne sont pas encore réveillées ? Allez vite les appeler, les inondations arrivent !>"
  },
  AvgDialog_149755_Content_85 = {
    Text = "La nuit décuplait la fureur de la tempête. Les gouttes de pluie s'écrasaient comme des pierres avec fracas, les eaux boueuses de la rivière rugissaient en débordant sur les deux rives, et les eaux accumulées avaient déjà dépassé les genoux."
  },
  AvgDialog_149755_Content_86 = {
    Text = "Des silhouettes couraient en tous sens, criaient à tue-tête, frappaient de toutes leurs forces chaque porte et chaque fenêtre, mais les esprits se déplaçaient lentement, et une fois tombés, ils ne pouvaient plus se relever, incapables de traverser seuls les creux et les bosses des flaques."
  },
  AvgDialog_149755_Content_87 = {
    Text = "« Boum !! » Un fracas retentissant fit tressaillir ton cœur. Mais sous le voile de la nuit, les gens regardaient autour d'eux, hébétés, sans savoir ce qui était sur le point de s'effondrer."
  },
  AvgDialog_149755_Content_88 = {
    Text = "<Big:C'est la digue !! Catastrophe !>"
  },
  AvgDialog_149755_Content_89 = {
    Text = "<Big:Fuyez ! Tous ceux qui peuvent marcher, fuyez, il n'y a plus de temps !>"
  },
  AvgDialog_149755_Content_9 = {
    Text = "Même si tu n'avais aucune envie de rester, ton corps brûlait de fièvre et tu n'avais plus la force de le suivre."
  },
  AvgDialog_149755_Content_90 = {
    Text = "Supplications, gémissements, cris — le paradis de tes rêves vacillait, sur le point d'être englouti par une pluie sans fin, ne laissant derrière lui que des ruines désolées. Et toi, tu n'étais même pas capable de marcher seul, condamné à regarder, impuissant."
  },
  AvgDialog_149755_Content_91 = {
    Text = "Ton chevalier te hissa sur le bord du chariot, détacha sa cape et t'en enveloppa soigneusement."
  },
  AvgDialog_149755_Content_92 = {
    Text = "Princesse, je vous supplie de m'accorder la permission de partir pour contenir la fureur de cette inondation."
  },
  AvgDialog_149755_Content_93 = {
    Text = "Peux-tu arrêter les eaux ?"
  },
  AvgDialog_149755_Content_94 = {
    Text = "Je ferai tout ce qui est en mon pouvoir."
  },
  AvgDialog_149755_Content_95 = {
    Text = "Pourras-tu revenir ?"
  },
  AvgDialog_149755_Content_96 = {
    Text = "… Je ferai tout ce qui est en mon pouvoir."
  },
  AvgDialog_149755_Content_97 = {
    Text = "<Big:Non, non, je refuse ! Je ne le permets pas !>"
  },
  AvgDialog_149755_Content_98 = {
    Text = "Partons, partons maintenant… Il y en aura un autre, l'île aux Pommes, l'île aux Citrouilles, n'importe quoi, il y en aura un autre !"
  },
  AvgDialog_149755_Content_99 = {
    Text = "Tu agrippas de toutes tes forces le pan de sa veste, sachant pourtant au fond de toi que c'était peine perdue — il avait déjà fait son choix. Il s'inclina devant toi, comme le héros le plus doux et le chevalier le plus loyal de tous les contes."
  },
  AvgDialog_149756_Content_1 = {Text = "Princesse"},
  AvgDialog_149756_Content_10 = {
    Text = "Tu veux crier ta réfutation, ricaner, maudire, hurler, mais un chiffon imbibé d'huile te bouche la bouche. Cette chose grasse et nauséabonde presse ta langue au fond de ta gorge — hormis des haut-le-cœur, tu ne peux émettre aucun son."
  },
  AvgDialog_149756_Content_11 = {
    Text = "Regardez, elle tremble — le démon se débat en elle, voilà son vrai visage hideux."
  },
  AvgDialog_149756_Content_12 = {
    Text = "Seigneur miséricordieux, je Vous supplie de délier sa bouche scellée par le diable, afin qu'elle confesse elle-même ses péchés de ses propres lèvres, si tant est qu'il lui reste encore en elle un désir de rédemption."
  },
  AvgDialog_149756_Content_13 = {
    Text = "Le chiffon qui lui bouchait la bouche fut brutalement arraché ; tu toussas et t'étouffas deux fois, puis tu te mis à haleter, la salive coulant au coin de tes lèvres."
  },
  AvgDialog_149756_Content_14 = {
    Text = "Les monstres formaient un cercle autour de toi, brandissant haches et fourches, te fixant avec méfiance. Plus loin, sur les talus des champs, entre les branches, derrière les fenêtres entrouvertes, d'autres yeux encore se cachaient."
  },
  AvgDialog_149756_Content_15 = {
    Text = "Parle, enfant ! Proclame ton repentir devant le Seigneur — c'est ton dernier instant pour échapper à la damnation éternelle !"
  },
  AvgDialog_149756_Content_16 = {
    Text = "<Small:… Monstres.>"
  },
  AvgDialog_149756_Content_17 = {
    Text = "Quoi ? Qu'a-t-elle dit ?"
  },
  AvgDialog_149756_Content_18 = {
    Text = "<BigShake:Monstres ! Monstres ! Mons— toussez toussez toussez !>"
  },
  AvgDialog_149756_Content_19 = {
    Text = "Ton stratagème soigneusement ourdi démasqué, les monstres arborèrent des expressions de panique, et tu ressentis une joie cruelle et sauvage."
  },
  AvgDialog_149756_Content_2 = {
    Text = "Les monstres ont dévoré ma famille, et maintenant, ils s'apprêtent à me dévorer moi."
  },
  AvgDialog_149756_Content_20 = {
    Text = "Une malédiction, c'est une malédiction ! Maudite sorcière !"
  },
  AvgDialog_149756_Content_21 = {
    Text = "Vite, bouchez-lui la bouche !"
  },
  AvgDialog_149756_Content_22 = {
    Text = "Seigneur… protégez-nous…"
  },
  AvgDialog_149756_Content_23 = {
    Text = "<Big:Brûlez-la ! Brûlez-la !>"
  },
  AvgDialog_149756_Content_24 = {
    Text = "<Big:Gobelins ! Créatures des marais ! Goules ! Monstres ! Vous êtes tous des mons-ouhouhouhou— !!>"
  },
  AvgDialog_149756_Content_25 = {
    Text = "Le diable a déjà emporté son âme — pour préserver notre village des sortilèges maléfiques, il faut éliminer cette impureté."
  },
  AvgDialog_149756_Content_26 = {
    Text = "Que le feu sacré consume ses péchés, que le Seigneur nous accorde la paix."
  },
  AvgDialog_149756_Content_27 = {
    Text = "Fagot après fagot, le petit bois s'entasse à vos pieds, les ronces lacèrent votre peau nue, la douleur vous fait vous débattre, les chaînes cliquètent."
  },
  AvgDialog_149756_Content_28 = {
    Text = "Ce qui vous vaut davantage d'insultes, et une corde de chanvre nouée encore plus serré."
  },
  AvgDialog_149756_Content_29 = {
    Text = "Le feu s'embrase."
  },
  AvgDialog_149756_Content_3 = {
    Text = "Le crépuscule est le signe d'un réveil quelconque ; le soleil couchant ressemble à une tache rouge morbide, et le ciel est gonflé d'ecchymoses."
  },
  AvgDialog_149756_Content_30 = {
    Text = "Nous te chassons… âme impure, hérétique apostat… comme la fumée dispersée par le vent, comme la cire fondue par le feu…"
  },
  AvgDialog_149756_Content_31 = {
    Text = "Être déchu, persécuteur, banni, au nom de Sa Sainteté, je t'ordonne, tremble, soumets-toi, fuis—"
  },
  AvgDialog_149756_Content_32 = {
    Text = "Sa voix s'interrompit net, comme tranchée en son milieu par une paire de ciseaux."
  },
  AvgDialog_149756_Content_33 = {
    Text = "Vous forcez vos yeux brûlants à s'ouvrir, et à travers les épais tourbillons de fumée, vous apercevez une silhouette inconnue se tenir aux côtés du prêtre."
  },
  AvgDialog_149756_Content_34 = {
    Text = "Depuis quand était-il là ? Vous l'ignorez. Vous regardez les monstres restants — ils ne bougent pas, pareils à un groupe de grenouilles bouche bée."
  },
  AvgDialog_149756_Content_35 = {
    Text = "Le prêtre fut pris de convulsions nerveuses, les deux mains crispées sur son cou, le sang débordant entre ses doigts, jaillissant de sa bouche, son visage de la même couleur que le ciel. Il s'effondra."
  },
  AvgDialog_149756_Content_36 = {
    Text = "<Big:Ah— !! >"
  },
  AvgDialog_149756_Content_37 = {
    Text = "Des cris, plus stridents qu'un sifflet, et les langues de feu frémissent avec eux."
  },
  AvgDialog_149756_Content_38 = {
    Text = "Du sang… tant de sang… Il a tué quelqu'un ! Au secours, le monstre a tué quelqu'un !"
  },
  AvgDialog_149756_Content_39 = {
    Text = "Non, non… Un démon, c'est un démon ! Cette sorcière a invoqué quelque chose des enfers ! Seigneur, pardonnez-nous…"
  },
  AvgDialog_149756_Content_4 = {
    Text = "Le feu n'est pas encore allumé, mais les arbres morts se sont déjà tordus, dans une posture de désespoir, comme si la lumière du jour qui revient inlassablement était elle aussi une brûlure insupportable."
  },
  AvgDialog_149756_Content_40 = {
    Text = "Votre cœur bat à tout rompre — vous savez qui il est, vous savez que votre vie ne s'achèvera pas aujourd'hui, que tout ceci n'est qu'un prélude, un intermède, pour accueillir sa venue."
  },
  AvgDialog_149756_Content_41 = {
    Text = "Empli d'un ardent espoir, vous vous tordez de toutes vos forces, poussant des gémissements, brûlant de le faire se tourner vers vous, oubliant presque les chaînes brûlantes."
  },
  AvgDialog_149756_Content_43 = {
    Text = "Une main gantée vous arrache du bûcher, vos jambes se dérobent sous vous, vous tombez à terre sans pouvoir vous en empêcher, toussant et vomissant à la fois, les larmes et la morve mêlées."
  },
  AvgDialog_149756_Content_44 = {
    Text = "<Shake:Touss, touss, touss, touss— !! Atten— touss touss touss touss— attendez ! Ne partez pas ! >"
  },
  AvgDialog_149756_Content_45 = {
    Text = "Avant qu'il ne se retourne pour partir, vous agrippez précipitamment sa cape."
  },
  AvgDialog_149756_Content_46 = {
    Text = "Comme s'il n'avait pas prévu votre geste, sa capuche glissa à moitié, révélant le visage d'un jeune homme."
  },
  AvgDialog_149756_Content_47 = {
    Text = "Lâche-moi."
  },
  AvgDialog_149756_Content_48 = {
    Text = "Tu es perspicace, tu sais faire la différence entre une menace et un avertissement. En te rappelant la mort récente du prêtre, tu frissonnes."
  },
  AvgDialog_149756_Content_49 = {
    Text = "Mais tu aperçois son visage, et sans aucun doute, le noble chevalier des histoires devrait être exactement ainsi. Il est sûrement venu pour toi, et tu as même l'impression que ces sourcils et ces yeux te sont familiers."
  },
  AvgDialog_149756_Content_5 = {
    Text = "<BigShake:Ne vous laissez pas tromper par son apparence !> Le visage d'enfant n'est qu'un déguisement — c'est un démon qui habite ce corps. Ses péchés, le Seigneur les a tous vus."
  },
  AvgDialog_149756_Content_50 = {
    Text = "Bien sûr, tu l'as forcément vu quelque part, dans un rêve, une malédiction, ou une prophétie. Sinon, comment expliquer ce courage soudain qui t'envahit ?"
  },
  AvgDialog_149756_Content_51 = {
    Text = "<Shake:Non… toussote, toussote, tu ne peux pas partir.>"
  },
  AvgDialog_149756_Content_52 = {Text = "Pourquoi ?"},
  AvgDialog_149756_Content_53 = {
    Text = "Parce que, toussote, parce que tu es venu me sauver, comment peux-tu me laisser ici ?"
  },
  AvgDialog_149756_Content_54 = {
    Text = "Tu es déjà sauvée, retourne à ta vie."
  },
  AvgDialog_149756_Content_55 = {
    Text = "Il n'y a pas de vie pour moi ici, il y a des monstres partout, qui ne font qu'attraper et dévorer les gens, tu l'as bien vu."
  },
  AvgDialog_149756_Content_56 = {
    Text = "Cela ne me concerne pas."
  },
  AvgDialog_149756_Content_57 = {
    Text = "Comment cela ne te concernerait-il pas ? Je t'attendais depuis si longtemps."
  },
  AvgDialog_149756_Content_58 = {
    Text = "Tu m'attendais ? Tu… tu me connais ?"
  },
  AvgDialog_149756_Content_59 = {
    Text = "Bien sûr, tu es mon chevalier."
  },
  AvgDialog_149756_Content_6 = {
    Text = "Elle est voleuse, menteuse, servante des ténèbres. Le malheur coule de sa bouche, son poison a souillé puits et rivières, et les bœufs et les moutons sont tombés morts dans leurs enclos, les gens pieux ont été frappés de maladies."
  },
  AvgDialog_149756_Content_60 = {
    Text = "Stupéfaction, confusion, affolement, douleur — mille expressions envahissent son visage à la fois. Il te repousse brusquement, comme pour fuir un serpent venimeux, et la lame courte tachée de sang se pose contre ta gorge."
  },
  AvgDialog_149756_Content_61 = {
    Text = "Qui es-tu !"
  },
  AvgDialog_149756_Content_62 = {
    Text = "Je, je suis une princesse ! C'est vrai, je suis une princesse, j'ai été enlevée par des monstres et je t'attendais pour venir me sauver !"
  },
  AvgDialog_149756_Content_63 = {
    Text = "Ne doute pas de moi, si je n'étais pas une princesse, pourquoi le ciel aurait-il envoyé un chevalier pour me sauver ?"
  },
  AvgDialog_149756_Content_64 = {Text = "新增"},
  AvgDialog_149756_Content_65 = {
    Text = "Il rengaine sa lame courte, se lève et s'enfonce dans la forêt dense, sans t'adresser un seul mot de plus."
  },
  AvgDialog_149756_Content_66 = {
    Text = "Attends, où vas-tu, je, toussote, je viens avec toi."
  },
  AvgDialog_149756_Content_67 = {
    Text = "<Shake:Arrête-toi ! Toussote, toussote, au nom de la princesse, je t'ordonne de t'arrêter !>"
  },
  AvgDialog_149756_Content_68 = {
    Text = "Bien qu'il soit d'une agilité déconcertante, tu as l'avantage de connaître cette forêt comme ta poche."
  },
  AvgDialog_149756_Content_69 = {
    Text = "Et de toute façon, tu n'as nulle part où aller, sinon courir, courir encore, quitte à t'effondrer ici même dans la forêt et devenir la pâture des bêtes."
  },
  AvgDialog_149756_Content_7 = {
    Text = "Vous en êtes tous témoins — combien de fois l'avez-vous vue entrer dans la forêt, disparaître, puis revenir comme si de rien n'était ? C'est là la preuve même qu'elle pratique la sorcellerie !"
  },
  AvgDialog_149756_Content_70 = {
    Text = "<Shake:Hah… hah… attends, je… je connais les règles.>"
  },
  AvgDialog_149756_Content_71 = {
    Text = "J'ai un endroit où aller. Accompagne-moi là-bas et tu recevras honneur et récompense."
  },
  AvgDialog_149756_Content_72 = {
    Text = "Je n'en ai pas besoin."
  },
  AvgDialog_149756_Content_73 = {
    Text = "Si, tu en as besoin. Du moins pour l'instant, tu as besoin de quelqu'un pour te guider hors d'ici, n'est-ce pas ?"
  },
  AvgDialog_149756_Content_74 = {
    Text = "Il ne répondit pas, mais ralentit peu à peu le pas jusqu'à s'arrêter."
  },
  AvgDialog_149756_Content_75 = {
    Text = "Où vas-tu ?"
  },
  AvgDialog_149756_Content_76 = {
    Text = "Hmm… ah oui, l'Île aux Pommes, tu en as entendu parler ? Un paradis où l'on n'a pas besoin de cultiver, où l'on ne tombe jamais malade, et où l'hiver n'existe pas — c'est là que je vais."
  },
  AvgDialog_149756_Content_77 = {
    Text = "Je n'en ai jamais entendu parler. Elle se trouve où ?"
  },
  AvgDialog_149756_Content_78 = {
    Text = "La fée ne m'a pas indiqué la direction, mais elle m'a dit que je la trouverais un jour, tout comme elle. Nous pouvons marcher et chercher en même temps — après tout, les grandes aventures sont toujours pleines de défis, non ?"
  },
  AvgDialog_149756_Content_79 = {
    Text = "La cape noire se fondait dans l'obscurité de la nuit. Il se tenait derrière les buissons emmêlés, son visage indistinct dans l'ombre."
  },
  AvgDialog_149756_Content_8 = {
    Text = "<SmallShake:La peste… une sorcière… oui, c'est à cause de la sorcière… la malédiction de la sorcière…>"
  },
  AvgDialog_149756_Content_80 = {
    Text = "Tu t'avançais vers lui très lentement, avec une prudence extrême, comme si tu craignais d'effaroucher un loup sauvage."
  },
  AvgDialog_149756_Content_81 = {
    Text = "Arrête. Reste là où tu es. N'approche pas d'un seul pas de plus."
  },
  AvgDialog_149756_Content_82 = {
    Text = "Montre le chemin."
  },
  AvgDialog_149756_Content_83 = {
    Text = "Cela signifie-t-il que tu acceptes, vaillant chevalier ?"
  },
  AvgDialog_149756_Content_84 = {Text = "新增"},
  AvgDialog_149756_Content_85 = {
    Text = "Je ne suis pas un chevalier."
  },
  AvgDialog_149756_Content_86 = {
    Text = "Si, tu l'es. À partir de maintenant, tu es mon loyal chevalier."
  },
  AvgDialog_149756_Content_87 = {
    Text = "Un chevalier tient ses promesses — jusqu'à ce que nous atteignions l'Île aux Pommes, tu devras me protéger. Tu marcheras devant moi, tu dégageras les ronces et les lianes sur mon passage, et si des monstres nous poursuivent, tu les chasseras. Et aussi…"
  },
  AvgDialog_149756_Content_88 = {
    Text = "Tu vas où ? Tu n'as pas encore prêté serment ! Si tu oses mentir et tromper ta princesse, les monstres viendront te dévorer. Jure d'abord."
  },
  AvgDialog_149756_Content_89 = {
    Text = "Hé ! Ne pars pas, attends-moi — je connais le chemin !"
  },
  AvgDialog_149756_Content_9 = {
    Text = "Une sorcière de moins de dix ans ? Même un fou ne pourrait inventer un tel mensonge."
  },
  AvgDialog_149757_Content_1 = {Text = "Tombeau"},
  AvgDialog_149757_Content_10 = {
    Text = "<Shake:Hah, hah… Mais où es-tu… mon chevalier…>"
  },
  AvgDialog_149757_Content_11 = {
    Text = "Tu te souviens de cette rumeur, et ton inquiétude redouble. Il ne faut pas laisser ton unique chevalier être vaincu par le démon. Tu te souviendras de son nom, tu t'en souviens déjà."
  },
  AvgDialog_149757_Content_12 = {
    Text = "Ogier… c'est ça, Ogier ! Où es-tu ! <Big:O — gier — !>"
  },
  AvgDialog_149757_Content_13 = {
    Text = "Un rugissement de douleur perce le rideau de pluie, plus proche d'une bête blessée que d'un homme. Tu t'élances aussitôt vers la source du son."
  },
  AvgDialog_149757_Content_14 = {
    Text = "Arrête de te cacher ! Je t'ai déjà vu !"
  },
  AvgDialog_149757_Content_15 = {
    Text = "Va-t'en ! Ne — ha — n'approche pas ! !!"
  },
  AvgDialog_149757_Content_16 = {
    Text = "La flamme de la lanterne vacille, incapable de dissiper les ténèbres qui se resserrent de toutes parts. Ton chevalier est acculé, son dos tendu comme un arc bandé."
  },
  AvgDialog_149757_Content_17 = {
    Text = "Tais-toi ! Je n'ai pas oublié ! Ce n'est pas — non, je n'ai jamais — je n'oublierai pas !"
  },
  AvgDialog_149757_Content_18 = {
    Text = "<Shake:Je les vengerai… je dois les venger… œil pour œil, dent pour dent…>"
  },
  AvgDialog_149757_Content_19 = {
    Text = "Non, non, tu mens ! La princesse ne dirait jamais ça, la princesse, la princesse elle —"
  },
  AvgDialog_149757_Content_2 = {
    Text = "Tu as entendu dire, de la bouche de quelqu'un, que le nom de chaque personne est un sortilège."
  },
  AvgDialog_149757_Content_20 = {
    Text = "<Big:Aaah — ! !>"
  },
  AvgDialog_149757_Content_21 = {
    Text = "Ses paroles décousues sont interrompues par un cri de douleur. Comme transpercé en pleine poitrine, il trébuche et tombe à genoux, tandis que l'ombre derrière lui demeure immobile, telle une armure, telle une cage."
  },
  AvgDialog_149757_Content_22 = {
    Text = "Tu ressens une vague de panique. Tu sais que si tu n'interviens pas maintenant, l'ombre deviendra l'homme, et l'homme sombrera pour devenir l'ombre."
  },
  AvgDialog_149757_Content_23 = {
    Text = "Réveille-toi ! Cesse de l'écouter, ta princesse est là ! !"
  },
  AvgDialog_149757_Content_24 = {
    Text = "<Shake:… @1@2Princesse… vous ai-je déçue ?>"
  },
  AvgDialog_149757_Content_25 = {
    Text = "<Shake:Je n'ai pas fui, c'est vous qui m'avez demandé de —> Non… ce n'est pas ce que je voulais dire, c'est moi qui vous ai trahie, je n'ai pas le droit d'implorer votre pardon."
  },
  AvgDialog_149757_Content_26 = {
    Text = "<Shake:La honte… la honte la honte la honte la honte la honte la honte la honte la honte, la honte est la seule chose qui m'appartienne…>"
  },
  AvgDialog_149757_Content_27 = {
    Text = "<Shake:Je ne suis pas un chevalier, je suis… je suis…>"
  },
  AvgDialog_149757_Content_28 = {
    Text = "<Red:Qui ?>"
  },
  AvgDialog_149757_Content_29 = {
    Text = "Dans un instant de confusion, il leva le visage vers toi — si tant est que cela puisse encore être appelé un visage."
  },
  AvgDialog_149757_Content_3 = {
    Text = "Si l'on vient à perdre son nom — que ce soit soi-même qui l'oublie, ou que les autres l'oublient — on devient comme une brebis égarée du troupeau, sans protection, et le diable vous prend en ligne de mire."
  },
  AvgDialog_149757_Content_30 = {
    Text = "L'ombre avait rongé sa chair, laissant des traces semblables au sillage d'un escargot. Son visage était marbré et putréfié, et des plaies béantes laissaient sourdre une boue noire et visqueuse."
  },
  AvgDialog_149757_Content_31 = {
    Text = "Attendait-il la réponse de quelqu'un ? La pluie glaciale avait engourdi tes lèvres et ta langue. Tu te tenais, hébété, dans la boue, un frisson tardif parcourant tes membres."
  },
  AvgDialog_149757_Content_32 = {
    Text = "…At-attends, je sais ! Tu es —"
  },
  AvgDialog_149757_Content_33 = {
    Text = "<BigShake:Non ! Ogier ! !>"
  },
  AvgDialog_149757_Content_34 = {
    Text = "La boue noire jaillit de sa poitrine. Ton chevalier épuisa ses forces dans le silence, s'effondrant misérablement, tel une enveloppe abandonnée. Les ombres tourbillonnaient autour de lui, riant et pleurant à la fois."
  },
  AvgDialog_149757_Content_35 = {
    Text = "Tu fus témoin de la façon dont un être peut se désintégrer."
  },
  AvgDialog_149757_Content_36 = {
    Text = "Ogier ! Tu es Ogier ! Je sais, je m'en souviens ! Le démon ne peut pas te blesser, je m'en souviens maintenant !"
  },
  AvgDialog_149757_Content_37 = {
    Text = "Réveille-toi ! Tu m'entends ? Réveille-toi vite, nous ne sommes pas encore arrivés ! Tu vas t'en sortir, l'Île aux Pommes — le démon ne peut pas y aller, tout ira bien une fois là-bas ! Lève-toi, lève-toi vite !"
  },
  AvgDialog_149757_Content_38 = {
    Text = "La tempête avait transformé la forêt en un marécage putride. Tu criais de toutes tes forces, tu tirais, tu pleurais, ne faisant que t'enfoncer davantage. Tu ne savais plus où fuir."
  },
  AvgDialog_149757_Content_39 = {
    Text = "Alors c'était donc cela, la cause de la mort du monde… enterré vivant par le désespoir."
  },
  AvgDialog_149757_Content_4 = {
    Text = "Peut-être que ton chevalier, tout comme toi, s'est vu dépouillé de tout par le monstre — il a même perdu davantage que toi, sans avoir pu conserver jusqu'à son nom."
  },
  AvgDialog_149757_Content_40 = {
    Text = "<SmallShake:Toussez… toussez toussez…>"
  },
  AvgDialog_149757_Content_41 = {
    Text = "<SmallShake:Quand la pluie s'arrêtera… aller au cimetière…>"
  },
  AvgDialog_149757_Content_42 = {
    Text = "Ogier ! Tu es encore en vie !"
  },
  AvgDialog_149757_Content_43 = {
    Text = "Non, attends, pourquoi aller au cimetière ? Tu… tu es vraiment encore en vie ?"
  },
  AvgDialog_149757_Content_44 = {
    Text = "<Shake:Aller au cimetière… enterrer… il n'y a plus de temps… il faut aller enterrer…>"
  },
  AvgDialog_149757_Content_45 = {
    Text = "Qui ? Qui veux-tu aller enterrer ?"
  },
  AvgDialog_149757_Content_46 = {Text = "新增"},
  AvgDialog_149757_Content_47 = {
    Text = "Il ne dit plus rien, regardant droit vers le haut, là où finissent tous les marécages, là où tout souvenir et tout oubli se dissoudront, là où la pluie tombe, rendant l'air de plus en plus rare."
  },
  AvgDialog_149757_Content_48 = {
    Text = "Mais vous ne pouvez pas atteindre le ciel, alors vous n'avez d'autre choix que de vous diriger vers le cimetière. C'est l'endroit qui s'en approche le plus."
  },
  AvgDialog_149757_Content_49 = {
    Text = "Dépenser autant d'argent pour un simple bout de terrain vide…"
  },
  AvgDialog_149757_Content_5 = {
    Text = "Alors le <Red:démon> tapi dans l'ombre montra ses griffes."
  },
  AvgDialog_149757_Content_50 = {
    Text = "Si tu avais su plus tôt combien coûte l'endroit où les monstres s'enterrent, tu ne serais certainement pas venue."
  },
  AvgDialog_149757_Content_51 = {
    Text = "La pluie a duré trois jours entiers avant de s'accorder une brève pause. Ton chevalier, grièvement blessé dans son combat contre le démon, t'a envoyée à sa place au cimetière pour y enterrer le paquet qu'il portait sur lui. Il a dit que c'étaient les reliques de quelqu'un."
  },
  AvgDialog_149757_Content_52 = {
    Text = "La pierre tombale est entièrement vierge, sans nom gravé. Tu ne sais pas pour qui elle a été érigée."
  },
  AvgDialog_149757_Content_53 = {
    Text = "Une bougie, un peigne, une petite figurine de pierre, du parchemin…"
  },
  AvgDialog_149757_Content_54 = {
    Text = "Le paquet est léger, il ne contient pas grand-chose, et pourtant tout est très abîmé. Tu as beau te creuser la tête, tu ne trouves pas de réponse. Ton chevalier est lui aussi une page blanche pour toi — tu ne sais rien de lui."
  },
  AvgDialog_149757_Content_55 = {
    Text = "… On enterre même le calice ?"
  },
  AvgDialog_149757_Content_56 = {
    Text = "Hé, toi là-bas, le petit bout, tu es de quelle famille ? Qu'est-ce que tu fabriques à rôder par ici ?"
  },
  AvgDialog_149757_Content_57 = {
    Text = "Des monstres en armure traversaient le cimetière. L'un d'eux s'arrêta soudainement, puis toute la colonne s'immobilisa. Ils étaient alignés avec une parfaite régularité, tous identiques les uns aux autres, semblables à un immense mille-pattes aux nombreux segments."
  },
  AvgDialog_149757_Content_58 = {
    Text = "Tu es sourde ? Je te demande d'où tu — hé, pourquoi tu cours ? Attrapez-la !"
  },
  AvgDialog_149757_Content_59 = {
    Text = "Lâchez-moi ! Lâchez-moi ! Je n'ai rien fait, ce terrain, c'est moi qui l'ai acheté !"
  },
  AvgDialog_149757_Content_6 = {
    Text = "Où… où… ce n'est pas dans cette direction ?"
  },
  AvgDialog_149757_Content_60 = {
    Text = "Tu l'as acheté ? Ha, alors dis-moi, la pierre n'a même pas de nom — c'est la tombe de qui ?"
  },
  AvgDialog_149757_Content_61 = {
    Text = "Je... Je..."
  },
  AvgDialog_149757_Content_62 = {
    Text = "Messieurs, ceci est le cimetière de la paroisse. Cette enfant a bien acheté un emplacement, c'est consigné dans le registre."
  },
  AvgDialog_149757_Content_63 = {
    Text = "Quant au nom, la peste est déjà là. Chaque jour des gens disparaissent — les pierres tombales sans nom, ça ne manque pas."
  },
  AvgDialog_149757_Content_64 = {
    Text = "Le visage des monstres changea. Ils échangèrent quelques regards, puis s'éloignèrent précipitamment, comme s'ils craignaient d'être contaminés par quelque chose. Dans ces yeux-là, tu reconnus une peur familière."
  },
  AvgDialog_149757_Content_65 = {Text = "Peste ?"},
  AvgDialog_149757_Content_66 = {
    Text = "Oui, la cruelle peste, la terrible peste. Faire oublier les hommes ne demande qu'un peu de temps, mais faire oublier la pierre exige de la réduire en sable."
  },
  AvgDialog_149757_Content_67 = {
    Text = "Les pierres qui oublient se multiplient, les vieillards deviennent aussi vides que des enfants, nous n'avons plus d'histoires."
  },
  AvgDialog_149757_Content_68 = {
    Text = "Toi… tu ne penses pas que c'est une malédiction ? À cause d'une sorcière, ou de quelque chose d'autre."
  },
  AvgDialog_149757_Content_69 = {
    Text = "Malédiction, peste, châtiment divin, ou vengeance du chevalier de la mort, quelle différence ? Nous n'y pouvons rien, mon enfant, nous ne pouvons que regarder le présent, le présent est tout ce que nous pouvons avoir, il en a toujours été ainsi."
  },
  AvgDialog_149757_Content_7 = {
    Text = "La nuit sans lune est d'un noir profond, et la forêt dense semble sans fond. Tu serres la Lanterne contre toi, cherchant partout les traces d'une fuite éperdue."
  },
  AvgDialog_149757_Content_70 = {
    Text = "Rentre à la maison, la nuit tombe bientôt."
  },
  AvgDialog_149757_Content_71 = {
    Text = "Attends, le chevalier de la mort ? Qu'est-ce que c'est ?"
  },
  AvgDialog_149757_Content_72 = {
    Text = "Une légende. Cette guerre était une erreur, ils criaient à l'éradication de la peste, et n'ont fait qu'en hâter l'arrivée, ils ont créé un monstre."
  },
  AvgDialog_149757_Content_73 = {
    Text = "Il se cache dans l'ombre des arbres, des bateaux, des murs de pierre et des oiseaux en vol, se déplaçant d'un endroit à un autre, là où la lumière du soleil ne peut l'atteindre."
  },
  AvgDialog_149757_Content_74 = {
    Text = "Son sang est d'un noir de jais, son cœur brûle d'un feu spectral, ses yeux brillent comme une lueur au fond des marécages, et partout où il passe, il laisse des ombres qui fendent le jour."
  },
  AvgDialog_149757_Content_75 = {
    Text = "Il est le prolongement de cette guerre, l'incarnation du ressentiment des morts, il n'apparaît que la nuit pour anéantir ses ennemis. Il n'oublie jamais, il ne néglige jamais rien, la raison de sa venue est évidente — notre seigneur, le pays qui lui appartenait autrefois."
  },
  AvgDialog_149757_Content_76 = {
    Text = "Quoi ? Tu veux dire que le seigneur est son ennemi, et qu'il est venu ici… pour se venger ?"
  },
  AvgDialog_149757_Content_77 = {
    Text = "Bien sûr, nous le savons tous, le seigneur aussi. Sinon pourquoi y aurait-il soudainement autant de soldats en patrouille dans la ville ?"
  },
  AvgDialog_149757_Content_78 = {
    Text = "Ils l'attendent tous."
  },
  AvgDialog_149757_Content_79 = {
    Text = "La pluie s'est remise à tomber, les rues ressemblent à une rivière en crue."
  },
  AvgDialog_149757_Content_8 = {
    Text = "Avant d'être englouti par l'ombre, il t'avait demandé de partir, mais comment une princesse pourrait-elle se passer de son chevalier ? Tu avais tenté de le sauver, mais il t'avait repoussé, avait défoncé la fenêtre pour sauter du grenier et avait disparu dans la forêt sauvage au-delà du domaine."
  },
  AvgDialog_149757_Content_80 = {
    Text = "Tu serres contre toi toutes les reliques et tu cours à toutes jambes dans les ruelles étroites, esquivant de justesse patrouille après patrouille de gardes, fonçant droit vers la cabane où vous vous cachez."
  },
  AvgDialog_149757_Content_81 = {
    Text = "<Shake:Vite, vite, rentre lui dire…>"
  },
  AvgDialog_149757_Content_82 = {
    Text = "Le monstre parmi les monstres, sans aucun doute ton chevalier — ses meurtres au grand jour ont finalement atteint les oreilles du seigneur, et il paraît que les gardes fouilleront ce soir chaque recoin de la ville."
  },
  AvgDialog_149757_Content_83 = {
    Text = "Il reste du temps, les portes de la ville ne sont pas encore fermées, il suffit d'aller encore un peu plus vite…"
  },
  AvgDialog_149757_Content_84 = {
    Text = "<Big:Ogier ! Pars vite, ils arrivent —>"
  },
  AvgDialog_149757_Content_85 = {
    Text = "L'étroite cahute était construite au fond d'une impasse, entourée de sacs de toile empilés qui ne parvenaient toujours pas à contenir la boue qui coulait de partout. Tu te précipites vers la silhouette allongée au fond et attrapes sa cape d'un coup — tu n'as saisi qu'une cape."
  },
  AvgDialog_149757_Content_86 = {
    Text = "À l'intérieur de la cabane, il n'y avait que de la paille, ton chevalier avait disparu sans laisser de trace."
  },
  AvgDialog_149757_Content_9 = {
    Text = "La tempête a effacé les branches brisées et les empreintes de pas, le paysage alentour est identique en tout point, tes pas se font de plus en plus lents, jusqu'à ce que tu t'arrêtes, perdue."
  },
  AvgDialog_15363_Content_1 = {
    Text = "Décès de Mme Coral"
  },
  AvgDialog_15363_Content_10 = {
    Text = "La foule se pressait tout autour, d'innombrables flashs d'appareils photo crépitaient, des discussions bruyantes se chevauchaient dans l'air, jusqu'à ce qu'un membre du personnel soulève soudain le voile."
  },
  AvgDialog_15363_Content_11 = {
    Text = "C›est... Oh mon Dieu."
  },
  AvgDialog_15363_Content_12 = {
    Text = "...Incroyable."
  },
  AvgDialog_15363_Content_13 = {
    Text = "Comme si un interrupteur avait été actionné ; la foule se tut automatiquement, rendant la salle autrefois animée étrangement vide."
  },
  AvgDialog_15363_Content_14 = {
    Text = "Vous luttez pour vous frayer un chemin à travers la foule et apercevez enfin l›œuvre d›art entourée au centre."
  },
  AvgDialog_15363_Content_15 = {Text = "新增"},
  AvgDialog_15363_Content_16 = {
    Text = "C›est Sanga. Elle a perdu toute sa couleur et ses émotions, transformée en une sculpture de corail d›un blanc pur."
  },
  AvgDialog_15363_Content_17 = {
    Text = "La lumière vive du jour se réfractait à travers le dôme de verre immaculé, l›enveloppant d›une douce lueur dorée."
  },
  AvgDialog_15363_Content_18 = {
    Text = "Vous baissez les yeux vers la plaque en laiton sur le socle de la sculpture, où son nom est gravé en lettres élégantes : <Red:«Fille Sans Nom du Corail»>."
  },
  AvgDialog_15363_Content_19 = {
    Text = "Corail Sans Nom..."
  },
  AvgDialog_15363_Content_2 = {
    Text = "Cher M. Claude :\n\nBeaucoup de choses se sont passées récemment ; veuillez pardonner ma réponse tardive.\n\nDepuis le départ de Mlle Sanga, M. Auguste n'a pas été en mesure de créer d'œuvres remarquables.\nSous la pression de l'opinion publique, il a annoncé une suspension indéfinie de sa carrière de sculpteur.\nIl a reçu la punition qu'il méritait, et pourtant je ne parviens pas à m'en réjouir — <Yellow:Mlle Sanga est toujours portée disparue.>"
  },
  AvgDialog_15363_Content_20 = {
    Text = "Vous contemplez le texte dans un état second, votre conscience oscillant et se tordant au gré des traits élégants..."
  },
  AvgDialog_15363_Content_21 = {
    Text = "Il leva la main pour se frotter les yeux, pour découvrir des couches de blanc terne et rugueux se répandant entre ses doigts."
  },
  AvgDialog_15363_Content_22 = {Text = "?!"},
  AvgDialog_15363_Content_23 = {
    Text = "Une brume de corail White se répandit depuis le bout de vos doigts, recouvrant progressivement tout votre corps, emplissant rapidement la salle entière, puis—"
  },
  AvgDialog_15363_Content_24 = {Text = "—!!"},
  AvgDialog_15363_Content_25 = {
    Text = "Vous et la salle d›exposition vous brisez en d›innombrables Fragments White, tombant dans les profondeurs infinies de l›océan."
  },
  AvgDialog_15363_Content_26 = {
    Text = "Parmi d›innombrables sculptures et coraux White, baignées dans la lumière tranquille du matin, les ruines d›un palais White se dressent majestueusement."
  },
  AvgDialog_15363_Content_27 = {
    Text = "Des poissons colorés nagent à travers les arches et les couloirs tordus des ruines, profitant de leurs moments de quiétude."
  },
  AvgDialog_15363_Content_28 = {
    Text = "Les ruines tout entières semblaient abandonnées dans l'ombre du temps, loin de la Corrosion du monde, à l'écart de l'Agitation de la foule."
  },
  AvgDialog_15363_Content_29 = {
    Text = "Quand vous aurez été témoin de ces miracles... vous me comprendrez."
  },
  AvgDialog_15363_Content_3 = {
    Text = "<Yellow:Demain, je me rendrai au Salon de la Cité pour trouver la «réponse» que Mlle Sanga a mentionnée.>\nSouhaitez-moi bonne chance.\n\nCamille@1\nA.F.2@1 Sep"
  },
  AvgDialog_15363_Content_30 = {
    Text = "Est-ce... le miracle que vous avez vu, Mme Sanga ?"
  },
  AvgDialog_15363_Content_31 = {
    Text = "Vous dérivez dans la mer tiède, fasciné et pourtant déconcerté par tout ce qui s›offre à vous."
  },
  AvgDialog_15363_Content_32 = {
    Text = "Écartez-vous, laissez-moi passer !!"
  },
  AvgDialog_15363_Content_33 = {
    Text = "<Big:Laisse-moi passer !!>"
  },
  AvgDialog_15363_Content_34 = {
    Text = "Le tumulte bruyant vous ramène à la réalité."
  },
  AvgDialog_15363_Content_35 = {
    Text = "Un vieil homme en haillons franchit les barrières de sécurité et se jette sur vous, agrippant fermement votre main."
  },
  AvgDialog_15363_Content_36 = {
    Text = "Tu l'as vu toi aussi, n'est-ce pas ? Les profondeurs de la mer, le palais, toutes ces illusions chaotiques..."
  },
  AvgDialog_15363_Content_37 = {Text = "?!"},
  AvgDialog_15363_Content_38 = {
    Text = "Cette femme diabolique est une voleuse..."
  },
  AvgDialog_15363_Content_39 = {
    Text = "Le vieil homme marmonnait pour lui-même. Vous avez scruté le visage dissimulé sous le large bord du chapeau et l›épaisse barbe, remarquant soudain quelque chose d›inhabituel."
  },
  AvgDialog_15363_Content_4 = {
    Text = "Exposition du Salon de la Cité\nJour d'ouverture"
  },
  AvgDialog_15363_Content_40 = {
    Text = "...M. Auguste ?!"
  },
  AvgDialog_15363_Content_41 = {
    Text = "Hiss, c'est vraiment lui... Mon Dieu ! Que lui est-il arrivé ?"
  },
  AvgDialog_15363_Content_42 = {
    Text = "Il est en faillite depuis longtemps, tu n'as pas entendu ? Après le fiasco de « Tragic Muse », il a investi massivement dans plusieurs projets, mais aucun d'eux n'a été vendu"
  },
  AvgDialog_15363_Content_43 = {
    Text = "Le gouvernement se méfie désormais de sa réputation et ne lui passe plus de commandes. Peut-être que le stress l›a rendu fou..."
  },
  AvgDialog_15363_Content_44 = {
    Text = "Les gens étaient à la fois choqués et effrayés, observant Auguste à distance prudente."
  },
  AvgDialog_15363_Content_45 = {
    Text = "Auguste arrache sa main de la vôtre et boitille vers la sculpture, les yeux débordant d›une haine incontrôlable."
  },
  AvgDialog_15363_Content_46 = {
    Text = "Hmph... Tu crois que la mort peut racheter tout ce que tu as fait ?"
  },
  AvgDialog_15363_Content_47 = {
    Text = "Tu as dupé tout le monde... Tu m›as pris tout mon talent, mon inspiration et ma renommée."
  },
  AvgDialog_15363_Content_48 = {
    Text = "Je suis ruiné, complètement ruiné. Et toi ? Assise ici tranquillement, savourant l›admiration de tous, attendant qu›on te couronne comme un classique..."
  },
  AvgDialog_15363_Content_49 = {Text = "新增"},
  AvgDialog_15363_Content_5 = {
    Text = "Vous avez entendu ? M. Auguste expose à nouveau ses sculptures."
  },
  AvgDialog_15363_Content_50 = {
    Text = "Face aux malédictions hystériques de l›ancien maître, la sculpture se dresse en silence, son expression indifférente inébranlable."
  },
  AvgDialog_15363_Content_51 = {
    Text = "Auguste ne pouvait plus le supporter ; il se jeta sur la sculpture avec fureur."
  },
  AvgDialog_15363_Content_52 = {
    Text = "La même expression, la même moquerie..."
  },
  AvgDialog_15363_Content_53 = {
    Text = "Diablesse... diablesse ! <Big:Je vais t›arracher ton masque !>"
  },
  AvgDialog_15363_Content_6 = {
    Text = "Auguste, le sculpteur ? N'avait-il pas disparu après avoir été accusé de plagiat ? Je pensais qu'il ne montrerait plus jamais son visage."
  },
  AvgDialog_15363_Content_7 = {
    Text = "Je suis assez curieux — sans cette disciple, que pourrait-il bien accomplir maintenant..."
  },
  AvgDialog_15363_Content_8 = {
    Text = "La cérémonie d'ouverture de l'exposition du salon était noire de monde."
  },
  AvgDialog_15363_Content_9 = {
    Text = "L'œuvre d'Auguste est placée au centre de la salle d'exposition, recouverte de lourds draps, suscitant une curiosité sans fin."
  },
  AvgDialog_15364_Content_1 = {Text = "Hmm !!"},
  AvgDialog_15364_Content_10 = {
    Text = "Exposition du Salon de la Cité\nLa nuit du jour d'ouverture"
  },
  AvgDialog_15364_Content_11 = {
    Text = "Lorsque le dernier verrou claqua, la salle d'exposition sombra dans un silence de mort."
  },
  AvgDialog_15364_Content_12 = {
    Text = "Vous sortez de l'ombre dans le coin et vous tenez à nouveau devant elle."
  },
  AvgDialog_15364_Content_13 = {
    Text = "Ici, loin de la clameur du jour, c'est le moment idéal pour parler."
  },
  AvgDialog_15364_Content_14 = {
    Text = "Mlle Sanga, M. Auguste a été emmené aujourd'hui. Il a dit...\nVous avez trompé tout le monde."
  },
  AvgDialog_15364_Content_15 = {
    Text = "Est-ce que « tout le monde » ici m'inclut également ?"
  },
  AvgDialog_15364_Content_16 = {Text = "新增"},
  AvgDialog_15364_Content_17 = {
    Text = "Avez-vous promis de rentrer avec moi ? Est-ce vrai ?"
  },
  AvgDialog_15364_Content_18 = {Text = "新增"},
  AvgDialog_15364_Content_19 = {
    Text = "La sculpture reste silencieuse. Même si la vie de chacun a été altérée par elle, elle ne baisse jamais son regard vers le lointain."
  },
  AvgDialog_15364_Content_2 = {
    Text = "Lâchez-moi ! Celle que vous cherchez, c›est elle, c›est elle —"
  },
  AvgDialog_15364_Content_20 = {
    Text = "Le clair de Lune transperce la verrière de la galerie, l'enveloppant dans une brume de lumière blanche."
  },
  AvgDialog_15364_Content_21 = {
    Text = "<Red:Suivez mon regard...>"
  },
  AvgDialog_15364_Content_22 = {
    Text = ": Suivez le regard... Cela pourrait-il être ?!"
  },
  AvgDialog_15364_Content_23 = {
    Text = "Vous vous dressez sur la pointe des pieds et remarquez que, sous le clair de Lune, les yeux autrefois indifférents et vagues de la sculpture ont changé, désormais emplis d'une émotion précise et intense."
  },
  AvgDialog_15364_Content_24 = {
    Text = "Elle continue de contempler le lointain."
  },
  AvgDialog_15364_Content_25 = {
    Text = "Vous suivez son regard et vous retournez."
  },
  AvgDialog_15364_Content_26 = {
    Text = "L'instant où votre regard s'est détourné, la salle d'exposition sous vos pieds a miraculeusement disparu."
  },
  AvgDialog_15364_Content_27 = {
    Text = "À la place, il y a une mer sans fin et une vaste plage d'un blanc immaculé."
  },
  AvgDialog_15364_Content_28 = {
    Text = "Le tonnerre gronde au loin, la marée déferle violemment, se précipitant vers vous."
  },
  AvgDialog_15364_Content_29 = {
    Text = "C'est la mer que Sanga et vous avez visitée autrefois."
  },
  AvgDialog_15364_Content_3 = {
    Text = "M. Auguste, nous avons reçu des signalements indiquant que vos agissements ont gravement perturbé l'ordre de l'exposition du salon. Veuillez nous suivre."
  },
  AvgDialog_15364_Content_4 = {
    Text = "Non, non..."
  },
  AvgDialog_15364_Content_5 = {
    Text = "La scène est chaotique, et l'afflux de personnes venant de toutes les directions vous a complètement séparé d'Auguste. Vous ne pouvez que regarder, impuissant, tandis qu'il est traîné de force par la police."
  },
  AvgDialog_15364_Content_6 = {
    Text = "Ne vous réjouissez pas trop vite... Un jour, vous finirez exactement comme moi..."
  },
  AvgDialog_15364_Content_7 = {
    Text = "Heh... Hehehe..."
  },
  AvgDialog_15364_Content_8 = {
    Text = "La salle d'exposition a enfin retrouvé son calme."
  },
  AvgDialog_15364_Content_9 = {
    Text = "Le dernier rire tremblant et névrotique d'Auguste résonnait faiblement dans la galerie vide, comme des ondulations qui s'estompent."
  },
  AvgDialog_15365_Content_1 = {
    Text = "Milieu de mer"
  },
  AvgDialog_15365_Content_10 = {
    Text = "Comme prévu, c'est vous.\nDésolée, est-ce que je vous ai dérangée en me levant la nuit ?"
  },
  AvgDialog_15365_Content_11 = {
    Text = "Au lieu de me réveiller, vous devriez plutôt vous inquiéter de savoir si vous allez déranger ces <Blue:vieux compagnons qui dorment sous terre>."
  },
  AvgDialog_15365_Content_12 = {
    Text = "Vous avez relevé le menton et désigné la tombe devant elle, qui avait été creusée sur près d'un pied de profondeur."
  },
  AvgDialog_15365_Content_13 = {
    Text = "Vous cherchez quelque chose ? Avez-vous besoin d'aide ?"
  },
  AvgDialog_15365_Content_14 = {
    Text = "C'est bon, je l'ai déjà trouvé."
  },
  AvgDialog_15365_Content_15 = {
    Text = "Sanga sourit et vous montra sa main, couverte d'un liquide noir et collant—"
  },
  AvgDialog_15365_Content_16 = {
    Text = "C'est de la Lave corrodée. Vous la connaissez extrêmement bien."
  },
  AvgDialog_15365_Content_17 = {
    Text = "Vous avez vu ? Sous le clair de lune, elle émet une étrange lueur bleue. Pendant la journée, elle prend une apparence complètement différente..."
  },
  AvgDialog_15365_Content_18 = {
    Text = "C'est le matériau de sculpture le plus parfait que j'aie jamais vu."
  },
  AvgDialog_15365_Content_19 = {Text = "新增"},
  AvgDialog_15365_Content_2 = {
    Text = "Cher M. Claudel,\n\nMlle Sanga n'a pas refusé de rentrer mais a demandé un peu de temps.\nElle a dit : <Yellow:«Je rentrerai après l'exposition du salon.»>\n\nCependant, l'état récent de Mlle Sanga est préoccupant.\nElle se faufile dehors tard la nuit et rentre à l'aube."
  },
  AvgDialog_15365_Content_20 = {
    Text = "Vous vous faufilez dehors chaque nuit juste pour collecter de la Lave corrodée ici ?"
  },
  AvgDialog_15365_Content_21 = {
    Text = "Vous connaissez leur nom ? Vous les connaissez très bien."
  },
  AvgDialog_15365_Content_22 = {
    Text = "Ce... n'est pas quelque chose de rare. Il y en a pas mal à Besançon."
  },
  AvgDialog_15365_Content_23 = {
    Text = "Je vois... Je pensais que c'était ma propre découverte unique et merveilleuse."
  },
  AvgDialog_15365_Content_24 = {
    Text = "Fusion... Quel nom approprié."
  },
  AvgDialog_15365_Content_25 = {
    Text = "Ce n'est pas le moment de plaisanter, Sanga."
  },
  AvgDialog_15365_Content_26 = {
    Text = "Vous allez mourir. Ce n'est pas quelque chose dans lequel des gens ordinaires comme nous devraient se mêler."
  },
  AvgDialog_15365_Content_27 = {
    Text = "Je comprends, vraiment... La beauté attire inévitablement le danger."
  },
  AvgDialog_15365_Content_28 = {
    Text = "On pourrait dire que le danger lui-même est une forme de beauté, n'est-ce pas ?\nPour moi, la mort n'est pas quelque chose à craindre."
  },
  AvgDialog_15365_Content_29 = {
    Text = "Ce qui est véritablement terrifiant, c'est..."
  },
  AvgDialog_15365_Content_3 = {
    Text = "Étrangement, ce mode de vie nocturne continu l'a rendue plus énergique,\net même M. Auguste est satisfait de son efficacité au travail récemment.\n\n<Yellow:Elle me semble si étrangère.>\n\nPlusieurs nuits, je me suis réveillée de cauchemars pour la trouver debout près de mon lit...\nElle me fixait avec des yeux emplis de quelque chose d'effrayant, quelque chose que je ne pouvais comprendre."
  },
  AvgDialog_15365_Content_30 = {
    Text = "Une douce brise emporta les mots suivants de Sanga. La lune perça à travers les nuages superposés, projetant sa lumière froide sur vous deux."
  },
  AvgDialog_15365_Content_31 = {
    Text = "C'est alors que vous remarquâtes la cicatrice sur le cou de Sanga."
  },
  AvgDialog_15365_Content_32 = {
    Text = "Comme des vrilles de corail, elles grimpaient vers le haut, scintillant d'une lumière froide, gris-bleu, dans les interstices du clair de lune changeant."
  },
  AvgDialog_15365_Content_33 = {
    Text = "Mademoiselle Sanga, avez-vous déjà été infectée... ?!"
  },
  AvgDialog_15365_Content_34 = {
    Text = "Même si vous savez que ce n'est qu'un rêve, votre cœur ressent tout de même un léger pincement l'espace d'un instant."
  },
  AvgDialog_15365_Content_35 = {
    Text = "Après tout, vous possédez désormais tous les souvenirs et émotions de la propriétaire originelle. Cette servante de la campagne de Besançon nourrit une profonde affection pour sa maîtresse."
  },
  AvgDialog_15365_Content_36 = {
    Text = "Est–ce à cause de M. Auguste? Ses paroles vous ont mis trop de pression, alors..."
  },
  AvgDialog_15365_Content_37 = {
    Text = "Sanga secoua la tête."
  },
  AvgDialog_15365_Content_38 = {
    Text = "Du début à la fin, cela n›avait rien à voir avec lui.\nAllons–y. Je vais vous emmener quelque part."
  },
  AvgDialog_15365_Content_39 = {
    Text = "Enfin — ma base secrète."
  },
  AvgDialog_15365_Content_4 = {
    Text = "<Yellow:J'ai décidé de la suivre en secret cette nuit pour voir ce qu'elle fait vraiment.>\nSouhaitez-moi bonne chance.\n\nCamille@1\nA.F.2@An 1, Septembre"
  },
  AvgDialog_15365_Content_40 = {
    Text = "C›est un entrepôt abandonné en bord de mer, rempli de diverses études de sculptures bizarres et tordues."
  },
  AvgDialog_15365_Content_41 = {
    Text = "Corail, coquillages, tentacules, et bâtiments et créatures ornés de sculptures étranges... Leur seule commune caractéristique est leur lien étroit avec l'océan."
  },
  AvgDialog_15365_Content_42 = {
    Text = "La texture de ces sculptures..."
  },
  AvgDialog_15365_Content_43 = {
    Text = "Ce n›est ni du marbre ni du granit. Où les avez–vous trouvées?"
  },
  AvgDialog_15365_Content_44 = {
    Text = "Sanga vous fit un clin d›œil espiègle."
  },
  AvgDialog_15365_Content_45 = {
    Text = "C›est mon secret. Un jour, vous saurez."
  },
  AvgDialog_15365_Content_46 = {
    Text = "Au centre de la cabane se dresse une sculpture humanoïde inachevée."
  },
  AvgDialog_15365_Content_47 = {
    Text = "Son corps était enveloppé dans de sinistres Tentacules, tordu en des angles impossibles. Les veines de son cou saillaient, Comme Si un serpent sinueux s'y était lové."
  },
  AvgDialog_15365_Content_48 = {
    Text = "Magnifique, n›est–ce pas?\nIls m›appellent tous «La Bouchère» parce que je suis toujours impitoyable avec mes modèles."
  },
  AvgDialog_15365_Content_49 = {
    Text = "C›est précisément pour cela que je peux capturer l›essence de la douleur qui s›entrelace et se tapit sous la chair."
  },
  AvgDialog_15365_Content_5 = {
    Text = "Septembre dans la Cité est déjà amèrement froid.\nVous marchez silencieusement dans la rue, essayant de vous cacher dans l'ombre."
  },
  AvgDialog_15365_Content_50 = {
    Text = "Mon professeur était toujours trop prudent avec les modèles, c›est pourquoi il n›a pu devenir qu›un sculpteur de second rang."
  },
  AvgDialog_15365_Content_51 = {
    Text = "Vous contemplez la sculpture devant vous. Elle est indéniablement belle, mais aussi cruelle."
  },
  AvgDialog_15365_Content_52 = {
    Text = "Est–ce l›œuvre que vous comptez présenter à l›exposition?"
  },
  AvgDialog_15365_Content_53 = {
    Text = "Sanga secoua la tête."
  },
  AvgDialog_15365_Content_54 = {
    Text = "Seulement des pièces d›entraînement. Avant de rencontrer cette... Lave corrodée, ma compréhension de la sculpture était assez superficielle."
  },
  AvgDialog_15365_Content_55 = {
    Text = "Maintenant je suis comme un nouveau–né, forcée de redécouvrir le monde devant mes yeux..."
  },
  AvgDialog_15365_Content_56 = {
    Text = "<Yellow:Apprendre à vous connaître à nouveau.>"
  },
  AvgDialog_15365_Content_57 = {Text = "Moi... ?"},
  AvgDialog_15365_Content_58 = {
    Text = "Oui, toi. Je vois de nouvelles possibilités dans tes yeux et ton attitude."
  },
  AvgDialog_15365_Content_59 = {
    Text = "Sanga traça légèrement les contours de votre visage du bout des doigts."
  },
  AvgDialog_15365_Content_6 = {
    Text = "La silhouette élancée de Sanga se trouve juste devant.\nVous maintenez une distance modérée mais respectueuse, comme si vous étiez subtilement reliées par un fil invisible."
  },
  AvgDialog_15365_Content_60 = {
    Text = "Contrairement aux autres dames choyées, ses doigts portent une fine couche de callosités, leur conférant une texture distinctement rugueuse."
  },
  AvgDialog_15365_Content_61 = {
    Text = "Tu as peur. Ne t'inquiète pas, je ne te forcerai à rien contre ta volonté."
  },
  AvgDialog_15365_Content_62 = {
    Text = "Tu te souviens encore de quand nous étions enfants ?"
  },
  AvgDialog_15365_Content_63 = {
    Text = "Quand j'étais enfant ?"
  },
  AvgDialog_15365_Content_64 = {
    Text = "Vous suivez ses paroles, plongeant plus profondément dans les pensées chaotiques de l'hôte originel, les explorant..."
  },
  AvgDialog_15365_Content_65 = {
    Text = "Pour finalement rester bloqué dans cet été sombre et brumeux."
  },
  AvgDialog_15365_Content_66 = {
    Text = "Bien sûr, je m'en souviens. À l'âge de 5 ans, tu étais capable de modeler un squelette humain avec de la boue."
  },
  AvgDialog_15365_Content_67 = {
    Text = "J'allais à la plage rassembler divers matériaux pour toi, et Monsieur Paul Claude était chargé de jeter ces modèles dans le four pour la cuisson."
  },
  AvgDialog_15365_Content_68 = {
    Text = "Oui, c'était un petit secret entre nous trois."
  },
  AvgDialog_15365_Content_69 = {
    Text = "Une personne fois, tu as été surprise par ton père. Tu as pris toute la faute sur toi et tu as été punie à rester debout toute une nuit."
  },
  AvgDialog_15365_Content_7 = {
    Text = "Ce fil vous guide à travers les bâtiments imposants et le long givre lugubre, vous menant finalement à votre destination commune—"
  },
  AvgDialog_15365_Content_70 = {
    Text = "Les yeux gris de Sanga étaient voilés d'une fine brume de tristesse."
  },
  AvgDialog_15365_Content_71 = {
    Text = "Elle vous étreint doucement."
  },
  AvgDialog_15365_Content_72 = {
    Text = "Vous êtes tous ma famille pour toujours. Est-ce que Paul t'a envoyé me chercher ?"
  },
  AvgDialog_15365_Content_73 = {
    Text = "Oui. Le jeune maître... est souffrant et ne peut pas venir en personne."
  },
  AvgDialog_15365_Content_74 = {
    Text = "Vous soufflez légèrement dans le cou de Sanga, son parfum emplissant vos narines.\nUn soupçon de brise marine."
  },
  AvgDialog_15365_Content_75 = {
    Text = "Ne t'inquiète pas. Puisque j'ai promis de rentrer avec toi, je tiendrai parole."
  },
  AvgDialog_15365_Content_76 = {
    Text = "Cependant, je dois te quitter pour le moment."
  },
  AvgDialog_15365_Content_77 = {
    Text = "Me quitter... ? Où allez-vous ?"
  },
  AvgDialog_15365_Content_78 = {
    Text = "Sanga ne dit rien, mais se tourna pour regarder la mer grise au-dehors."
  },
  AvgDialog_15365_Content_79 = {
    Text = "C'est une nuit brumeuse, avec de douces vagues qui clapotent en rythme, comme le pouls battant au cou de Sanga."
  },
  AvgDialog_15365_Content_8 = {
    Text = "Une tombe abandonnée"
  },
  AvgDialog_15365_Content_80 = {
    Text = "Je ne sais pas. Peut-être les profondeurs de l'océan, ou peut-être @1..."
  },
  AvgDialog_15365_Content_81 = {
    Text = "Après ce jour-là, Mlle Sanga disparut."
  },
  AvgDialog_15365_Content_82 = {
    Text = "Je suis allée partout où je pouvais et j'ai interrogé tous ceux que je pouvais, mais en vain.\n\nElle nous a quittés comme une rafale de vent.\nMême aujourd'hui, je me remémore sans cesse cette nuit au bord de la mer."
  },
  AvgDialog_15365_Content_83 = {
    Text = "À l'époque, Mlle Sanga me serrait fort dans ses bras.\nElle a peut-être dit quelque chose après, ou peut-être pas ; je ne sais pas.\n\nMa mémoire est floue depuis ce jour-là.\n\n<Red:Du corail blanc, des coquillages, un mystérieux palais sous-marin...>\nMême aujourd'hui, ces images chaotiques tourmentent mon esprit la nuit."
  },
  AvgDialog_15365_Content_84 = {
    Text = "<Yellow:«Rendez-vous à l'exposition du salon pour trouver des réponses.»>\n\nMlle Sanga m'a dit cela. Elle a aussi dit —"
  },
  AvgDialog_15365_Content_85 = {
    Text = "Une fois que vous aurez été témoin de ces miracles, vous me comprendrez."
  },
  AvgDialog_15365_Content_86 = {
    Text = "Seulement suivez mon regard..."
  },
  AvgDialog_15365_Content_87 = {
    Text = "Je te le promets."
  },
  AvgDialog_15365_Content_9 = {
    Text = "Mademoiselle Sanga."
  },
  AvgDialog_15367_Content_1 = {
    Text = "Éloigne-toi, ne me touche pas... !!"
  },
  AvgDialog_15367_Content_10 = {
    Text = "Je sais que vous avez récemment ouvert un <Yellow:atelier> par vous-même, mais je crois devoir vous rappeler quelque chose."
  },
  AvgDialog_15367_Content_11 = {
    Text = "N›espérez pas que vos <Yellow:créations d›amateur blasphématoires et abjectes> remportent la faveur des fonctionnaires du gouvernement."
  },
  AvgDialog_15367_Content_12 = {
    Text = "J›admets que vous êtes talentueuse et que vous avez beaucoup aidé l›atelier. Mais dans un endroit comme la Cité, faire de l›art exige bien plus que du talent."
  },
  AvgDialog_15367_Content_13 = {
    Text = "Si tu me mets en colère..."
  },
  AvgDialog_15367_Content_14 = {
    Text = "M. August, veuillez faire attention à vos paroles."
  },
  AvgDialog_15367_Content_15 = {
    Text = "Tout va bien, Camille."
  },
  AvgDialog_15367_Content_16 = {
    Text = "Sanga vous tint doucement par derrière. Face au questionnement d'Auguste, son expression resta calme."
  },
  AvgDialog_15367_Content_17 = {
    Text = "Elle s'accroupit, ramassa les morceaux brisés du visage de la sculpture et les jeta dans le tas d'ordures à proximité."
  },
  AvgDialog_15367_Content_18 = {
    Text = "Si vous me mettez en colère, votre œuvre ne sera ni exposée ni vendue. En tant qu'artiste, vous ne réussirez jamais, et au final..."
  },
  AvgDialog_15367_Content_19 = {
    Text = "Vous mourrez de froid dans la rue ou serez envoyée dans un asile."
  },
  AvgDialog_15367_Content_2 = {
    Text = "Grâce aux efforts conjugués de tous, ils parvinrent enfin à maîtriser le maître sculpteur en furie."
  },
  AvgDialog_15367_Content_20 = {
    Text = "Bien sûr, je sais tout cela, Maître."
  },
  AvgDialog_15367_Content_3 = {
    Text = "Ne soyez pas imprudent, mon cher professeur."
  },
  AvgDialog_15367_Content_4 = {
    Text = "Une œuvre aussi médiocre ruine non seulement mon humeur, mais aussi votre réputation."
  },
  AvgDialog_15367_Content_5 = {
    Text = "Heh... Ne soyez pas si maligne. Avec moins d›un semestre avant l›exposition du salon, pouvez-vous en créer une meilleure par magie?"
  },
  AvgDialog_15367_Content_6 = {Text = "Un mois."},
  AvgDialog_15367_Content_7 = {Text = "...Quoi ?"},
  AvgDialog_15367_Content_8 = {
    Text = "Donnez-moi un mois, et je vous offrirai une véritable <Yellow:surprise>."
  },
  AvgDialog_15367_Content_9 = {Text = "...Hmph."},
  AvgDialog_15368_Content_1 = {
    Text = "En lisant cette lettre, c'est comme si nous nous rencontrions en personne."
  },
  AvgDialog_15368_Content_10 = {
    Text = "Tes tempes battent. Tu essayes de bouger ton corps, mais—"
  },
  AvgDialog_15368_Content_11 = {Text = "...!"},
  AvgDialog_15368_Content_12 = {
    Text = "<Shake:Mes jambes... sont engourdies...>"
  },
  AvgDialog_15368_Content_13 = {
    Text = "Hmm, est–ce que c'était mon imagination? L'espace d'un instant quand vous avez ouvert les yeux, j'ai cru voir un éclat que je n'avais jamais vu auparavant."
  },
  AvgDialog_15368_Content_14 = {
    Text = "Non, ce n'est pas une illusion. Votre expression a changé également..."
  },
  AvgDialog_15368_Content_15 = {
    Text = "Les yeux d'une jeune apprentie sculptrice brillaient d'excitation tandis qu'elle se penchait soudainement vers vous."
  },
  AvgDialog_15368_Content_16 = {
    Text = ": Qui êtes-vous ?"
  },
  AvgDialog_15368_Content_17 = {
    Text = "Votre servante"
  },
  AvgDialog_15368_Content_18 = {
    Text = "<Shake:J–je suis votre servante Camille@1, vous ne vous souvenez pas? Haha...>"
  },
  AvgDialog_15368_Content_19 = {
    Text = "Souvenez–vous de votre identité."
  },
  AvgDialog_15368_Content_2 = {
    Text = "Cher M. Claude,\n\nJe suis arrivée à la Cité.\nContrairement à la tranquillité de Besançon, il y a ici des nuisances bruyantes partout.\nLe tintement des cloches, le grondement des attelages, et la clameur des foules...\nL'idée que Mlle Sanga vive dans un tel environnement me trouble profondément."
  },
  AvgDialog_15368_Content_20 = {
    Text = "Cette fois, vous êtes une servante qui a grandi avec Sanga et qui a été envoyée par Monsieur Paul pour la ramener à la maison."
  },
  AvgDialog_15368_Content_21 = {
    Text = "«Assurez–vous de sauver son âme de ce démon qui ne fait qu'exploiter et plagier les autres.»"
  },
  AvgDialog_15368_Content_23 = {
    Text = "<Gray:Non, ce n'est pas ça...>"
  },
  AvgDialog_15368_Content_24 = {
    Text = "Souvenez–vous de votre identité."
  },
  AvgDialog_15368_Content_25 = {
    Text = "Cette fois, vous êtes une servante qui a grandi avec Sanga et avez été envoyée par Maître @1·Claudel pour la ramener chez elle."
  },
  AvgDialog_15368_Content_26 = {
    Text = "«Assurez-vous de sauver son âme de ce diable qui ne fait qu'exploiter et plagier ses subordonnés.»"
  },
  AvgDialog_15368_Content_27 = {
    Text = "Je, je suis votre servante, Camille@1. Vous ne vous souvenez pas ? Haha..."
  },
  AvgDialog_15368_Content_28 = {
    Text = "<Shake:Cela fait tellement d'années que nous sommes séparées, nous avons toutes les deux changé, n'est-ce pas ?>"
  },
  AvgDialog_15368_Content_29 = {Text = "新增"},
  AvgDialog_15368_Content_3 = {
    Text = "Des rumeurs se sont répandues. \nOn dit que Mlle Sanga passe tout son temps avec un homme de plus de 20 ans son aîné, « pour l'art ». \nC'est absurde. Demain, je me rendrai à l'atelier pour en avoir le cœur net. \n\nCette fois, je remplirai votre requête —\n<Yellow:Ramener votre sœur, notre Mlle Sanga, à Besançon.>\n\nCamille@1\nA.F.2@1 Année 8"
  },
  AvgDialog_15368_Content_30 = {
    Text = "Vous êtes vraiment différente maintenant, bien plus vivante qu'avant.\nC'est comme si... vous aviez soudainement pris vie."
  },
  AvgDialog_15368_Content_31 = {
    Text = "<Gray:Est-ce l'intuition de l'artiste ? Il faudra que je sois plus prudente à l'avenir.>"
  },
  AvgDialog_15368_Content_32 = {
    Text = "<Shake:Si cela ne vous dérange pas, pourriez-vous m'aider ? Je ne peux pas me lever pour l'instant...>"
  },
  AvgDialog_15368_Content_33 = {
    Text = "Sanga prend doucement votre main, une lueur d'inquiétude passant dans ses yeux tranquilles."
  },
  AvgDialog_15368_Content_34 = {
    Text = "Pardon, j'étais trop absorbée par ma création tout à l'heure. Vous devez vous sentir mal à l'aise maintenant. Laissez-moi regarder."
  },
  AvgDialog_15368_Content_35 = {Text = "Oh—!!"},
  AvgDialog_15368_Content_36 = {
    Text = "La porte de l'atelier fut ouverte d'un coup sec."
  },
  AvgDialog_15368_Content_37 = {
    Text = "Un homme grand et sombre entra, suivi de plusieurs visages inconnus."
  },
  AvgDialog_15368_Content_38 = {
    Text = "Sans avoir besoin d'accéder aux souvenirs de l'hôte d'origine, vous avez reconnu l'homme grâce à sa barbe distinctive—"
  },
  AvgDialog_15368_Content_39 = {
    Text = "Le célèbre sculpteur <Blue:Auguste>."
  },
  AvgDialog_15368_Content_4 = {
    Text = "Mademoiselle Sanga, revenez avec moi. Il n'y a pas d'endroit pour se réchauffer ici—"
  },
  AvgDialog_15368_Content_40 = {
    Text = "Encore aujourd'hui, ses sculptures sont toujours acclamées comme des chefs-d'œuvre et très recherchées aux enchères de Londinium."
  },
  AvgDialog_15368_Content_41 = {
    Text = "En vous voyant, vous et Sanga, main dans la main, Auguste fronça les sourcils. Mais bientôt, son attention fut attirée par la sculpture devant lui."
  },
  AvgDialog_15368_Content_42 = {
    Text = "C'est... <Big:Un chef-d'œuvre, sans aucun doute !!>"
  },
  AvgDialog_15368_Content_43 = {
    Text = "Les autres se rassemblèrent autour, regardant avec curiosité la sculpture fraîchement réalisée et s'exclamant d'admiration."
  },
  AvgDialog_15368_Content_44 = {
    Text = "Bien, très bien... Contactez quelqu'un du ministère de la Culture et dites-leur que nous avons progressé sur les pièces pour l'exposition de la Cité de cette année."
  },
  AvgDialog_15368_Content_45 = {
    Text = "J'ai hâte de voir ces critiques en rester bouche bée... Hahaha !"
  },
  AvgDialog_15368_Content_46 = {
    Text = "Le rire tonitruant d'Auguste résonne dans l'atelier vide. Il vous pousse sur le côté et serre fermement la main de Sanga."
  },
  AvgDialog_15368_Content_47 = {
    Text = "Je savais que tu ne me décevrais pas, Sanga."
  },
  AvgDialog_15368_Content_48 = {
    Text = "Sanga retira lentement sa main et s'approcha de la sculpture."
  },
  AvgDialog_15368_Content_49 = {
    Text = "Un... chef-d'œuvre incontestable?"
  },
  AvgDialog_15368_Content_5 = {
    Text = "Ne bougez pas, et ne parlez pas. Seulement restez comme ça.\nOui, exactement comme ça..."
  },
  AvgDialog_15368_Content_50 = {
    Text = "Que penses-tu, Camille ?"
  },
  AvgDialog_15368_Content_51 = {
    Text = "Euh, moi...?"
  },
  AvgDialog_15368_Content_52 = {
    Text = "Tu contemples la sculpture devant toi qui te ressemble presque trait pour trait, perdue dans tes pensées..."
  },
  AvgDialog_15368_Content_53 = {Text = "Normale"},
  AvgDialog_15368_Content_54 = {
    Text = "Eh bien, des expressions figées, une structure chaotique et un manque de tension..."
  },
  AvgDialog_15368_Content_55 = {
    Text = "Tu commentes d'un ton affecté. En réalité, tu as toujours été déconnectée de l'art ; tu n'as dit cela que parce que tu ne supportais pas l'attitude autoritaire d'Auguste."
  },
  AvgDialog_15368_Content_56 = {
    Text = "Vous ne l'aimez pas."
  },
  AvgDialog_15368_Content_57 = {
    Text = "Sanga te sourit, comme une mère aimante face à un enfant qui babille."
  },
  AvgDialog_15368_Content_58 = {
    Text = "Hmm... Bien que nos raisons diffèrent, nous sommes arrivées à la même conclusion."
  },
  AvgDialog_15368_Content_59 = {
    Text = "Chef-d'œuvre!"
  },
  AvgDialog_15368_Content_6 = {
    Text = "Soyez un bon modèle pour moi et laissez–moi finir cette pièce... Ensuite nous pourrons parler de rentrer à la maison."
  },
  AvgDialog_15368_Content_60 = {
    Text = "Véritablement sans pareil. Je n'y trouve aucun défaut."
  },
  AvgDialog_15368_Content_61 = {
    Text = "Toi, comme tous les autres, tu as été entièrement captivée par cette sculpture qui semble fluide et pourtant est méticuleusement travaillée."
  },
  AvgDialog_15368_Content_62 = {
    Text = "Bien sûr, cela est aussi lié à une mauvaise circulation sanguine causée par le maintien de la même posture pendant longtemps."
  },
  AvgDialog_15368_Content_63 = {
    Text = "Un cerveau privé d'oxygène ne peut percevoir les choses clairement, mais la flatterie est toujours bienvenue."
  },
  AvgDialog_15368_Content_64 = {
    Text = "Tu as tout à fait raison. Son plus grand problème, c'est qu'elle n'a aucun défaut."
  },
  AvgDialog_15368_Content_65 = {
    Text = "Maintenant... Que devrais-je faire de toi?"
  },
  AvgDialog_15368_Content_66 = {
    Text = "Sanga posa son menton sur sa main, contemplant la sculpture devant elle. Puis, elle tapota nonchalamment le front de la sculpture de son index—"
  },
  AvgDialog_15368_Content_67 = {
    Text = "Splash—!!"
  },
  AvgDialog_15368_Content_68 = {
    Text = "La sculpture traça un arc gracieux, puis s'écrasa au sol avec un bruit sourd."
  },
  AvgDialog_15368_Content_69 = {
    Text = "Camille — ou plutôt, votre visage anxieux se brise en d›innombrables morceaux."
  },
  AvgDialog_15368_Content_7 = {
    Text = "Qu›est-ce que c›est...?"
  },
  AvgDialog_15368_Content_70 = {Text = "新增"},
  AvgDialog_15368_Content_71 = {
    Text = "Mademoiselle Claudel, êtes-vous devenue folle?!"
  },
  AvgDialog_15368_Content_72 = {
    Text = "Auguste se jeta sur vous, furieux."
  },
  AvgDialog_15368_Content_73 = {
    Text = "<Big:C›est du marbre de Petachi de la plus pure qualité, tout droit venu de Palos—>"
  },
  AvgDialog_15368_Content_8 = {
    Text = "Une maison en désordre."
  },
  AvgDialog_15368_Content_9 = {
    Text = "Des sculptures faites de divers types d'argile, de marbre et de granit sont posées négligemment, transformant cet espace en un simple atelier de sculpture."
  },
  AvgDialog_15370_Content_1 = {
    Text = "Tête dorée"
  },
  AvgDialog_15370_Content_10 = {
    Text = "La pluie redouble d'intensité, et votre gorge devient de plus en plus sèche.\nDans une telle tempête, vous devez crier pour entendre votre propre voix."
  },
  AvgDialog_15370_Content_11 = {
    Text = "Ici... Je suis ici..."
  },
  AvgDialog_15370_Content_12 = {
    Text = "@1 Héhé, ici, ici @2 ici, ici, ici..."
  },
  AvgDialog_15370_Content_13 = {
    Text = "D'innombrables voix vous assaillent de toutes parts. Vous ne pouvez plus tenir et vous effondrez finalement à genoux sur la plage."
  },
  AvgDialog_15370_Content_14 = {
    Text = "Peut–être que tout n'est que votre fantasme... Peut–être que Mlle Sanga est partie pour toujours."
  },
  AvgDialog_15370_Content_15 = {
    Text = "<Shake:Mlle Sanga, sortez... Je sais que vous êtes ici...>"
  },
  AvgDialog_15370_Content_16 = {
    Text = "Sans vous en rendre compte, la conscience de la servante vous a progressivement dévoré. Ses espoirs et ses souffrances ont profondément remué votre cœur."
  },
  AvgDialog_15370_Content_17 = {
    Text = "Vous pressez votre front contre le sable humide, un étrange gémissement s'échappant de votre gorge."
  },
  AvgDialog_15370_Content_18 = {
    Text = "<Shake:Mademoiselle Sanga...>"
  },
  AvgDialog_15370_Content_19 = {
    Text = "<Red:Je suis là... Je suis juste là...>"
  },
  AvgDialog_15370_Content_2 = {
    Text = "Cher M. Claude,\n\nLe « Décès de Mme Coral » a connu un succès retentissant à la Cité, et tout le monde en parle.\nQuand je regarde cette sculpture, je ne peux m'empêcher de penser à vous.\n\nElle est faite d'un matériau blanc terne, semblable aux pierres qui vous recouvrent et vous laissent immobile.\nMais ils ne me laissent pas toucher la sculpture@1\nJe trouverai un moyen."
  },
  AvgDialog_15370_Content_20 = {
    Text = "...Qu'est-ce que c'est ?"
  },
  AvgDialog_15370_Content_21 = {
    Text = "Une sensation froide touche le bout de mes doigts."
  },
  AvgDialog_15370_Content_22 = {
    Text = "La brume blanche se répand à nouveau depuis le bout de mes doigts, comme des lianes vivantes..."
  },
  AvgDialog_15370_Content_23 = {
    Text = "Lentement et régulièrement..."
  },
  AvgDialog_15370_Content_24 = {
    Text = "Enfin... le moment est arrivé."
  },
  AvgDialog_15370_Content_25 = {
    Text = "Une délicate paire de chaussures de femme s'immobilisa devant vous.\nSanga tenait un ciseau, son expression aussi calme et détachée que toujours."
  },
  AvgDialog_15370_Content_26 = {
    Text = "Mademoiselle Sanga... vous êtes bel et bien encore en vie..."
  },
  AvgDialog_15370_Content_27 = {
    Text = "Cela dépend de comment vous définissez «être en vie»."
  },
  AvgDialog_15370_Content_28 = {
    Text = "La douce lueur des lumières lointaines enveloppe doucement le corps de Sanga. Elle vous sourit silencieusement."
  },
  AvgDialog_15370_Content_29 = {
    Text = "Je suis de retour, Camille. Tu as dû m'attendre longtemps, n'est-ce pas ?"
  },
  AvgDialog_15370_Content_3 = {
    Text = "Mlle Sanga a finalement réalisé son souhait. Elle a échangé sa vie contre un art immortel.\nMais elle nous a aussi quittés pour toujours.\nCela fait presque un mois que l'exposition s'est terminée, et elle me manque encore profondément.\n\n<Yellow:Je la retrouverai et la ramènerai à la maison.>\n\nCamille@1\nA.F.2@Année 8 Mois"
  },
  AvgDialog_15370_Content_30 = {
    Text = "Pain, choc, extase..."
  },
  AvgDialog_15370_Content_31 = {
    Text = "Votre poitrine est emplie d'innombrables émotions. Vous ouvrez la bouche, mais vous vous trouvez incapable de prononcer une seule syllabe complète."
  },
  AvgDialog_15370_Content_32 = {
    Text = "Sanga@1...pas@2..."
  },
  AvgDialog_15370_Content_33 = {Text = "Chut..."},
  AvgDialog_15370_Content_34 = {
    Text = "Le saviez-vous ? Le corps humain est comme un monde tremblant et pulsant."
  },
  AvgDialog_15370_Content_35 = {
    Text = "Lorsque le corps et l'âme ont subi une trempe suffisante, ils se transforment en la sculpture parfaite au paroxysme de l'explosion émotionnelle..."
  },
  AvgDialog_15370_Content_36 = {
    Text = "Des doigts froids effleurent votre visage qui se raidit progressivement."
  },
  AvgDialog_15370_Content_37 = {
    Text = "Sanga vous regarda avec amour, son regard vous consumant presque."
  },
  AvgDialog_15370_Content_38 = {
    Text = "Seulement comme vous l'êtes maintenant..."
  },
  AvgDialog_15370_Content_39 = {
    Text = "Je suis comme ça maintenant...? Mlle Sanga, est–ce le D–slime...?"
  },
  AvgDialog_15370_Content_4 = {
    Text = "Vous avez titubé jusqu'au bord de la mer. Il n'y a personne ici, seules la mer sombre et silencieuse et l'horizon brumeux vous tiennent compagnie."
  },
  AvgDialog_15370_Content_40 = {
    Text = "Chh... Silence."
  },
  AvgDialog_15370_Content_41 = {
    Text = "Pour moi, la mort n'a jamais été quelque chose à craindre. Ce qui me terrifie vraiment, c'est..."
  },
  AvgDialog_15370_Content_42 = {
    Text = "<Yellow:Perdre la beauté, ou fermer les yeux dessus.>"
  },
  AvgDialog_15370_Content_43 = {
    Text = "<Shake:Laissez... moi... tranquille...>"
  },
  AvgDialog_15370_Content_44 = {
    Text = "Ne dis pas de sottises, Camille."
  },
  AvgDialog_15370_Content_45 = {
    Text = "<Red:Tu étais déjà morte, tu te souviens?>"
  },
  AvgDialog_15370_Content_46 = {
    Text = "<Red:Morte...>"
  },
  AvgDialog_15370_Content_47 = {Text = "新增"},
  AvgDialog_15370_Content_48 = {
    Text = "Vous plongez une fois de plus dans les profondeurs de l'océan sans fin."
  },
  AvgDialog_15370_Content_49 = {
    Text = "Ces fragments scellés dans la mémoire sont comme de l'écume blanche dérivant alentour, émergeant et se brisant sans cesse..."
  },
  AvgDialog_15370_Content_5 = {
    Text = "Vous êtes tous ma famille éternelle."
  },
  AvgDialog_15370_Content_50 = {
    Text = "Dans l'ultime instant avant la mort, vous devez affronter ces vérités brutales —"
  },
  AvgDialog_15370_Content_51 = {
    Text = "C'est entièrement ma faute, Camille. C'est entièrement ma faute... Laisse–moi te serrer dans mes bras, pour que la blessure ne fasse plus mal."
  },
  AvgDialog_15370_Content_52 = {
    Text = "Ma sœur est un vrai génie. Elle deviendra sans aucun doute une grande artiste immortalisée dans les livres!"
  },
  AvgDialog_15370_Content_53 = {
    Text = "Ahem... Arrête de te mentir à toi–même, Camille..."
  },
  AvgDialog_15370_Content_54 = {
    Text = "Ramenez–la–moi@2. Il y a quelque chose que je veux lui demander en personne..."
  },
  AvgDialog_15370_Content_55 = {
    Text = "Édition spéciale, Édition spéciale!!"
  },
  AvgDialog_15370_Content_56 = {
    Text = "L'effroyable <Yellow:Affaire du Meurtre à la Sculpture> a fait une nouvelle victime!"
  },
  AvgDialog_15370_Content_57 = {
    Text = "À ce jour, il y a eu 54 cas de <Yellow:vertiges et d'hystérie> causés par la visite de « Décès de Mme Coral »..."
  },
  AvgDialog_15370_Content_58 = {
    Text = "<Red:Parmi eux, 23 personnes se sont déjà suicidées...>"
  },
  AvgDialog_15370_Content_59 = {Text = "新增"},
  AvgDialog_15370_Content_6 = {
    Text = "Ne t'inquiète pas. Puisque j'ai promis de rentrer avec toi, je tiendrai parole."
  },
  AvgDialog_15370_Content_60 = {
    Text = "Alors je... savais tout..."
  },
  AvgDialog_15370_Content_61 = {
    Text = "Vous revoyez le palais océanique blanc. Le plancton se rassemble sur le carbonate de calcium blanc, étirant paresseusement ses membres."
  },
  AvgDialog_15370_Content_62 = {
    Text = "Vous avez aussi vu ces sculptures blanches dérivant sans but dans l'eau de mer."
  },
  AvgDialog_15370_Content_63 = {
    Text = "Certains visages familiers se trouvent parmi elles, comme M. Auguste, affichant encore la colère et le désespoir de son élan vers la sculpture."
  },
  AvgDialog_15370_Content_64 = {
    Text = "Par exemple, Monsieur Paul, avec ses orbites creuses emplies de mélancolie, semblait avoir depuis longtemps pressenti son destin."
  },
  AvgDialog_15370_Content_65 = {
    Text = "L'eau de mer tiède enveloppe votre corps, son rythme ondulant semblable à une ballade fluide."
  },
  AvgDialog_15370_Content_66 = {
    Text = "Avant d'ouvrir les yeux, le bébé agite ses petites mains,\nTenant de l'argile, ressentant une joie semblable à l'amour maternel.\nL'art de la création et du contrôle se répand à travers ses doigts.\n\n<Red:Ouvrez les yeux, et contemplez tout ce qui naît de la beauté...>"
  },
  AvgDialog_15370_Content_67 = {
    Text = "Des mains froides vous enlacent doucement. Sanga enfouit sa joue douce dans votre épaule raide."
  },
  AvgDialog_15370_Content_68 = {
    Text = "Tu les entends ? Ces chants ne cessent de résonner dans mon esprit."
  },
  AvgDialog_15370_Content_69 = {
    Text = "C'est l'appel d'<Yellow:Eux>, un destin auquel je suis destinée à ne jamais échapper..."
  },
  AvgDialog_15370_Content_7 = {
    Text = "Elle ne brisera pas sa promesse... Elle ne la brisera pas."
  },
  AvgDialog_15370_Content_70 = {
    Text = "J'ai suivi les chants et je suis finalement arrivée ici."
  },
  AvgDialog_15370_Content_71 = {
    Text = "Miracles et beauté des profondeurs océaniques... Je n'ai rien d'autre à Lui offrir que toi."
  },
  AvgDialog_15370_Content_72 = {Text = "Moi... ?"},
  AvgDialog_15370_Content_73 = {
    Text = "Oui, il n'y a que toi — %player%."
  },
  AvgDialog_15370_Content_74 = {
    Text = "Elle a prononcé clairement et distinctement votre véritable nom."
  },
  AvgDialog_15370_Content_75 = {
    Text = "Dès l'instant où tu as ouvert les yeux, je savais."
  },
  AvgDialog_15370_Content_76 = {
    Text = "<Yellow:Tu es le véritable « Décès de Mme Coral. »>"
  },
  AvgDialog_15370_Content_77 = {
    Text = "La conscience s'est progressivement brouillée, et le corail blanc s'était déjà répandu sur tout le corps."
  },
  AvgDialog_15370_Content_78 = {
    Text = "Vous sentez votre sang et votre chair s'alourdir, mais étrangement, vos corps ne cessent de s'élever parmi l'écume et le corail."
  },
  AvgDialog_15370_Content_79 = {
    Text = "<Shake:Non... maison... rentrer à la maison...>"
  },
  AvgDialog_15370_Content_8 = {
    Text = "Vous relevez votre jupe et courez le long du littoral sans vous arrêter."
  },
  AvgDialog_15370_Content_80 = {
    Text = "C'est votre maison, %player%."
  },
  AvgDialog_15370_Content_81 = {Text = "Non..."},
  AvgDialog_15370_Content_82 = {
    Text = "Tu fixes intensément le visage de Sanga jusqu'à ce que tes pupilles soient recouvertes de corail blanc grisâtre."
  },
  AvgDialog_15370_Content_83 = {
    Text = "Vous sombrez dans un vide sans fond."
  },
  AvgDialog_15370_Content_84 = {
    Text = "Tous les océans, les coraux et les sculptures s'effacent ; seule sa voix demeure."
  },
  AvgDialog_15370_Content_85 = {
    Text = "Comme toujours, une voix douce mais indifférente."
  },
  AvgDialog_15370_Content_86 = {
    Text = "Je t'avais promis que je te ramènerais chez toi..."
  },
  AvgDialog_15370_Content_87 = {
    Text = "Je te le promets."
  },
  AvgDialog_15370_Content_9 = {
    Text = "Mlle Sanga — Mlle Sanga —"
  },
  AvgDialog_15605_Content_1 = {
    Text = "Commencer le test"
  },
  AvgDialog_15605_Content_10 = {
    Text = "Es-tu de nouveau entré dans le passé du Corps éveillé ? Tu te souviens avoir lu un document..."
  },
  AvgDialog_15605_Content_11 = {
    Text = "Pourquoi n'y a-t-il aucune réponse ? Le module auditif est-il défaillant ?"
  },
  AvgDialog_15605_Content_12 = {
    Text = "Ça dépend. Tu as bricolé le module en cachette après mon départ hier ?"
  },
  AvgDialog_15605_Content_13 = {
    Text = [[
Non, non, vraiment, pas cette fois, je le jure !
Et si j'essayais encore ? Personne de TikTok, tu m'entends ?]]
  },
  AvgDialog_15605_Content_14 = {Text = "Oui."},
  AvgDialog_15605_Content_15 = {
    Text = "Regarde, regarde ! Sa bouche bouge. Je t'avais dit que tout allait bien !"
  },
  AvgDialog_15605_Content_16 = {
    Text = "La toute première poupée mécanique entièrement automatique au monde qui obéit aux commandes vocales ! La première ! Entièrement automatique !\nCher Père, emmenez–moi maintenant, car je n'ai aucun regret dans ma vie !"
  },
  AvgDialog_15605_Content_17 = {
    Text = "Il y a beaucoup de regrets, comme ne pas avoir terminé le test de réponse aux commandes, le test de mobilité, le test de durée opérationnelle..."
  },
  AvgDialog_15605_Content_18 = {
    Text = "Mae—Yi—tu n'es vraiment pas intéressante du tout."
  },
  AvgDialog_15605_Content_19 = {
    Text = "...Test de coordination générale, test d'Équilibre, test de charge..."
  },
  AvgDialog_15605_Content_2 = {
    Text = "Engrenages : bon état ; système hydraulique : aucune fuite de pression ; moteur MF311000 : fonctionnement normal, température élevée mais dans les limites."
  },
  AvgDialog_15605_Content_20 = {
    Text = "D'accord, j'ai compris ! <Small:Tu es plus mécanique qu'un Tik–Tokien.>"
  },
  AvgDialog_15605_Content_21 = {
    Text = "Que disais-tu ?"
  },
  AvgDialog_15605_Content_22 = {
    Text = "Ah—ensuite, nous allons effectuer un test basique de réception et de compréhension des commandes !\nHomme Dida, cligne des yeux."
  },
  AvgDialog_15605_Content_23 = {Text = "Clignoter"},
  AvgDialog_15605_Content_24 = {
    Text = "Suis mon doigt, très bien.\nOuvre la bouche ? Très bien, tu es mon bon enfant."
  },
  AvgDialog_15605_Content_25 = {Text = "...Ugh."},
  AvgDialog_15605_Content_26 = {
    Text = "Quoi ! Je t'ai créé petit à petit, alors il est tout à fait raisonnable de m'appeler Maman."
  },
  AvgDialog_15605_Content_27 = {
    Text = "Oui, oui, Maman Folle d'Engrenages, apporte le bras gauche de ton cher bébé d'acier. C'est l'heure du test des membres."
  },
  AvgDialog_15605_Content_28 = {
    Text = "Un bras composé d'engrenages complexes et de structures mécaniques incompréhensibles apparaît brièvement dans votre champ de vision, puis disparaît à votre gauche, suivi de votre droite."
  },
  AvgDialog_15605_Content_29 = {
    Text = "L'installation des membres s'est bien passée. Suivant les instructions, vous levez les bras et les jambes, et le sourire d'Erica s'élargit."
  },
  AvgDialog_15605_Content_3 = {
    Text = "Énergie spéciale S, état stable."
  },
  AvgDialog_15605_Content_30 = {
    Text = "Très bien, ensuite—Ah !"
  },
  AvgDialog_15605_Content_31 = {
    Text = "Une épaisse fumée noire s'élève sous votre ligne de vision : quelque chose brûle.\nVous baissez les yeux et voyez des étincelles et de l'électricité crépiter depuis votre abdomen."
  },
  AvgDialog_15605_Content_32 = {
    Text = "Extincteur, Mei, Mei !"
  },
  AvgDialog_15605_Content_33 = {
    Text = "Écartez-vous !"
  },
  AvgDialog_15605_Content_34 = {
    Text = "L'extincteur a projeté de la mousse blanche, dissipant l'odeur de brûlé avec le flux d'air.\nErica s'est approchée, ignorant la chaleur du moteur, et l'a démonté."
  },
  AvgDialog_15605_Content_35 = {Text = "Erica !"},
  AvgDialog_15605_Content_36 = {
    Text = "Le moteur carbonisé reposait sur l'établi. Erica prit une grande inspiration et souffla tardivement sur sa main couverte de mousse."
  },
  AvgDialog_15605_Content_37 = {
    Text = "Ça me brûle, ça me brûle."
  },
  AvgDialog_15605_Content_38 = {
    Text = "L›Énergie S, regarde l›Énergie S !"
  },
  AvgDialog_15605_Content_39 = {
    Text = "Erica se pencha près du moteur, ses doigts légèrement rougis effleurant doucement son boîtier métallique."
  },
  AvgDialog_15605_Content_4 = {
    Text = "Ouf — tu es prêt ?\nAutomate Tik-Tok, test n°13, on commence."
  },
  AvgDialog_15605_Content_40 = {
    Text = "On dirait qu›un circuit externe a court-circuité et pris feu, mais l›intérieur devrait être intact."
  },
  AvgDialog_15605_Content_41 = {
    Text = "Ne t›inquiète pas, je vais vérifier dans un instant."
  },
  AvgDialog_15605_Content_42 = {
    Text = "...Tu me chasses encore ?"
  },
  AvgDialog_15605_Content_43 = {Text = "Mae..."},
  AvgDialog_15605_Content_44 = {
    Text = "J›ai eu tort d›expérimenter avec l›Énergie S sans permission, mais tu connais notre situation financière. Utiliser S comme percée peut nous faire gagner du temps et des matériaux."
  },
  AvgDialog_15605_Content_45 = {
    Text = "Laisse-moi la voir, juste une fois. Je jure que je ne divulguerai aucune information à son sujet.\nS›il te plaît."
  },
  AvgDialog_15605_Content_46 = {
    Text = "Je t›ai dit, il n›y a rien à l›intérieur."
  },
  AvgDialog_15605_Content_47 = {
    Text = "...Tu ne prends même pas la peine de trouver une excuse. Tu as vraiment besoin d›être aussi méfiante envers moi ?\nEst-ce que je n›ai pas toujours pensé à notre avenir ?"
  },
  AvgDialog_15605_Content_48 = {Text = "新增"},
  AvgDialog_15605_Content_49 = {
    Text = "Laisse tomber.\nJe vais m›asseoir un moment au resto de Joey. Fais ce que tu veux."
  },
  AvgDialog_15605_Content_5 = {
    Text = "Ouvre les yeux"
  },
  AvgDialog_15605_Content_50 = {
    Text = "La porte se referma, les pas s›éloignèrent, et Erica soupira."
  },
  AvgDialog_15605_Content_51 = {
    Text = "Elle est encore... Mais cette personne m›a mise en garde au sujet de l›Énergie S...\nJe ne peux pas laisser Mae prendre ce risque avec moi."
  },
  AvgDialog_15605_Content_52 = {
    Text = "Elle se retourna vers le moteur, semblant retrouver une énergie nouvelle."
  },
  AvgDialog_15605_Content_53 = {
    Text = "Je vais trouver une solution. Attends-moi, Mae."
  },
  AvgDialog_15605_Content_54 = {
    Text = "Elle dévissa le capuchon et en sortit un cylindre noir."
  },
  AvgDialog_15605_Content_55 = {
    Text = "À cet instant, ton monde fut plongé dans les ténèbres."
  },
  AvgDialog_15605_Content_6 = {
    Text = "Personne tic-tac, tu m'entends ?"
  },
  AvgDialog_15605_Content_7 = {Text = "...Erica ?"},
  AvgDialog_15605_Content_8 = {
    Text = "Un visage familier affiche une expression naturelle complètement différente de celle dont tu te souviens. Comparée à un automate, elle ressemble davantage à une personne vivante."
  },
  AvgDialog_15605_Content_9 = {
    Text = "...Que se passe-t-il ici ?"
  },
  AvgDialog_15606_Content_1 = {
    Text = "Ainsi parla la voix"
  },
  AvgDialog_15606_Content_10 = {
    Text = "Elle marmonna en sortant, vous laissant seul avec le moteur et les pièces sur l'établi."
  },
  AvgDialog_15606_Content_11 = {
    Text = "Vous regardez votre main."
  },
  AvgDialog_15606_Content_12 = {
    Text = "Une coque de porcelaine élancée, robuste et finement ouvragée, soigneusement polie et entretenue. Malgré sa froideur, elle semble vivante sous la lumière tamisée."
  },
  AvgDialog_15606_Content_13 = {
    Text = "C'est la main d'Erica, la main de l'<Blue:Automate Erica> que vous connaissez.\nVous semblez habiter son corps ultérieur, devenant l'automate qu'elle a créé."
  },
  AvgDialog_15606_Content_14 = {
    Text = "La personne que vous venez de voir était clairement humaine.\nQuelle expérience a bien pu la transformer en ce qu'elle est devenue ?"
  },
  AvgDialog_15606_Content_15 = {Text = "Erica ?"},
  AvgDialog_15606_Content_16 = {
    Text = "Vous clignez des yeux, et Mae est entrée sans que vous ne vous en rendiez compte.\nSon regard balaye la pièce et se pose finalement sur le moteur à côté de vous."
  },
  AvgDialog_15606_Content_17 = {Text = "新增"},
  AvgDialog_15606_Content_18 = {
    Text = "Après avoir scruté la pièce une seconde fois, elle ferma la porte et se précipita vers le générateur."
  },
  AvgDialog_15606_Content_19 = {
    Text = "Désolée, Erica."
  },
  AvgDialog_15606_Content_2 = {
    Text = "Tic-Tac, ma chère, tu m›entends ?"
  },
  AvgDialog_15606_Content_20 = {
    Text = "Le couvercle se dévissa, et Mae pinça l'objet à l'intérieur. Cette fois, vous le vîtes clairement : un cylindre métallique de moins de 5 cm de diamètre, avec la lettre «S» gravée sur le côté."
  },
  AvgDialog_15606_Content_21 = {
    Text = "Une fois qu'elle aura entièrement retiré le cylindre, vous perdrez à nouveau conscience.\nAlors avant cela, vous devez—"
  },
  AvgDialog_15606_Content_22 = {
    Text = "Attraper sa main"
  },
  AvgDialog_15606_Content_23 = {Text = "Aïe !!"},
  AvgDialog_15606_Content_24 = {
    Text = "Qu›est–ce qui se passe—"
  },
  AvgDialog_15606_Content_25 = {
    Text = "Erica se précipita dans la pièce, son inquiétude se figeant à l›instant où elle vit le cylindre dans la main de Mae."
  },
  AvgDialog_15606_Content_26 = {
    Text = "Mei, que fais-tu ?"
  },
  AvgDialog_15606_Content_27 = {
    Text = "Que fais-tu !"
  },
  AvgDialog_15606_Content_28 = {
    Text = "J›essaie juste... cette énergie... ça marche vraiment..."
  },
  AvgDialog_15606_Content_29 = {
    Text = "Face au petit cylindre qui alimentait tout le moteur et l›ensemble des équipements connectés, les yeux de Mae s›écarquillèrent."
  },
  AvgDialog_15606_Content_3 = {
    Text = "Vous éveillant des ténèbres éternelles, vous vous trouvez toujours dans l'atelier. Le moteur carbonisé repose encore sur l'établi, relié à votre Corps par plusieurs câbles d'épaisseurs variées."
  },
  AvgDialog_15606_Content_30 = {
    Text = "Savez-vous ce que cela signifie, Erica ?"
  },
  AvgDialog_15606_Content_31 = {
    Text = "Ça signifie que c›est dangereux, Mae. Je t›avais dit de ne pas toucher à ça—"
  },
  AvgDialog_15606_Content_32 = {
    Text = "Non, non, écoute, Erica— ce truc, ce minuscule truc, peut fournir de l›énergie sans perte, sans émission, pendant longtemps. Tu ne comprends pas ?"
  },
  AvgDialog_15606_Content_33 = {
    Text = "Le charbon et le pétrole ne sont rien en comparaison. Si on peut le produire en masse, on réécrira la structure énergétique de l›humanité et on entrera dans l›histoire !"
  },
  AvgDialog_15606_Content_34 = {
    Text = "Tu dois me dire comment tu as réussi à faire ça, tu dois !"
  },
  AvgDialog_15606_Content_35 = {
    Text = "Erica, où vas–tu ? Comment ça tu ne sais pas quoi faire, Erica !"
  },
  AvgDialog_15606_Content_36 = {
    Text = "L›investisseur a dit que dès qu›il verra l›échantillon, il est prêt à nous fournir un financement conséquent et même un studio dédié."
  },
  AvgDialog_15606_Content_37 = {
    Text = "Pourquoi tu n›écoutes pas— je ne sais pas comment fabriquer ce truc, je ne peux pas !"
  },
  AvgDialog_15606_Content_38 = {
    Text = "J›ai passé l›âge de croire aux contes de fées, Erica. Quel <Blue:Vendeur Mystérieux> ? Si tu veux te débarrasser de moi, trouve au moins une meilleure excuse."
  },
  AvgDialog_15606_Content_39 = {
    Text = "Si tu peux créer des choses aussi incroyables, pourquoi n›as–tu pas une vision à plus long terme ?"
  },
  AvgDialog_15606_Content_4 = {
    Text = "Peut être entendu."
  },
  AvgDialog_15606_Content_40 = {
    Text = "Pourquoi te confiner ici, à bricoler avec ces rebuts ?"
  },
  AvgDialog_15606_Content_41 = {
    Text = "La voix de Mae frappa Erica comme une gifle en plein visage. Elle fixa sa partenaire et compagne, incapable de croire ce qu›elle venait d›entendre."
  },
  AvgDialog_15606_Content_42 = {
    Text = "...Des rebuts, c›est vraiment ce que tu penses ?"
  },
  AvgDialog_15606_Content_43 = {
    Text = "Je pensais que nous partagions les mêmes idéaux."
  },
  AvgDialog_15606_Content_44 = {
    Text = "Mae se mordit la lèvre et resserra sa prise sur le cylindre."
  },
  AvgDialog_15606_Content_45 = {
    Text = "Regarde les choses en face, Erica. Plus personne ne veut dépenser d'argent pour des automates. La nouvelle énergie, c'est notre avenir."
  },
  AvgDialog_15606_Content_46 = {
    Text = "...pose cette source d'énergie spéciale."
  },
  AvgDialog_15606_Content_47 = {
    Text = "Pense à tout ce que nous pourrions avoir : plus de fonds, plus de ressources.\nAvec ça, tu pourras poursuivre tes rêves. Avec ça, tu pourras—"
  },
  AvgDialog_15606_Content_48 = {
    Text = "J'ai dit, «Lâche ça !»"
  },
  AvgDialog_15606_Content_49 = {
    Text = "Erica se jeta en avant pour s'en emparer, mais Mae ne parvint pas à esquiver à temps et percuta une armoire à proximité."
  },
  AvgDialog_15606_Content_5 = {
    Text = "Désolée, je promets de me concentrer sur le module vocal ensuite ! Supporte ça encore un peu, d'accord ?"
  },
  AvgDialog_15606_Content_50 = {Text = "!!"},
  AvgDialog_15606_Content_51 = {
    Text = "Des flacons remplis de divers réactifs et combustibles se renversent. Vous vous précipitez pour protéger les deux personnes devant vous. La seconde d'après—"
  },
  AvgDialog_15606_Content_6 = {
    Text = "Hochement de tête."
  },
  AvgDialog_15606_Content_7 = {
    Text = "Dieu merci, c'est formidable. J'avais vraiment peur qu'un fil ait grillé."
  },
  AvgDialog_15606_Content_8 = {
    Text = "Elle poussa un soupir de soulagement, puis bâilla largement comme si la fatigue ne la rattrapait que maintenant."
  },
  AvgDialog_15606_Content_9 = {
    Text = "Il faut que j'aille prendre un café et dîner..."
  },
  AvgDialog_15607_Content_1 = {
    Text = "Le canon à plasma frappa la main géante, faisant se détacher l'Argent de la paume pour tomber silencieusement au sol."
  },
  AvgDialog_15607_Content_10 = {
    Text = "Quoi... qu'ai-je... fait..."
  },
  AvgDialog_15607_Content_11 = {
    Text = "Vous ne comprenez toujours pas. Mais peu importe—vous avez déjà allumé cette révolution de la vie et de l'âme—cette <Red:«Transcendance»>.\nMourez en paix. Je veillerai à ce que le monde entier se souvienne de votre contribution."
  },
  AvgDialog_15607_Content_12 = {
    Text = "Erica ferma les yeux."
  },
  AvgDialog_15607_Content_13 = {
    Text = "Tu as... raison, tu as toujours eu raison..."
  },
  AvgDialog_15607_Content_14 = {
    Text = "Des larmes noires glissèrent du coin de ses yeux tandis qu›elle plissait le nez et se tournait soudain pour vous regarder."
  },
  AvgDialog_15607_Content_15 = {
    Text = "J›aurais dû... t›écouter... depuis le tout début... Je... n›aurais pas dû prendre cette chose..."
  },
  AvgDialog_15607_Content_16 = {
    Text = "Ma santé mentale... mon... aide-moi... cette dernière fois..."
  },
  AvgDialog_15607_Content_17 = {
    Text = "Y a-t-il vraiment une troisième conscience dans ce <Corps>, ou n›êtes-vous que l›incarnation de sa culpabilité sous l›influence de la <Fusion> ? Vous ne pouvez pas le dire."
  },
  AvgDialog_15607_Content_18 = {
    Text = "Elle tend la main vers vous."
  },
  AvgDialog_15607_Content_19 = {
    Text = "Aide... moi... sauve..."
  },
  AvgDialog_15607_Content_2 = {
    Text = "Après un moment d'immobilité, la main géante se désintégra, et une boue noire se déversa comme une pluie torrentielle. Elle vous traversa mais tacha le fantôme d'Erica."
  },
  AvgDialog_15607_Content_20 = {
    Text = "Vous savez seulement que vous l›aiderez et serez témoin de son destin en tant qu›«humaine»."
  },
  AvgDialog_15607_Content_21 = {
    Text = "Prendre sa main"
  },
  AvgDialog_15607_Content_22 = {
    Text = "Elle vous regarde avec surprise, comme si elle n›avait jamais imaginé pouvoir réellement toucher sa propre «raison»."
  },
  AvgDialog_15607_Content_23 = {
    Text = "Inclinaison"
  },
  AvgDialog_15607_Content_24 = {
    Text = "Elle vous regarde avec surprise, comme si elle ne s›attendait jamais à ce que sa «conscience» réponde."
  },
  AvgDialog_15607_Content_25 = {Text = "Merci..."},
  AvgDialog_15607_Content_26 = {
    Text = "Le fantôme éclata comme une bulle, ne laissant derrière lui qu›un orbe vacillant qui émettait encore sa dernière lumière."
  },
  AvgDialog_15607_Content_27 = {
    Text = "Vous tenez l›orbe de lumière rétréci dans vos bras, contemplant le Cœur d›argent brisé non loin de là."
  },
  AvgDialog_15607_Content_28 = {
    Text = "Vous réussirez."
  },
  AvgDialog_15607_Content_3 = {
    Text = "C'est... fini..."
  },
  AvgDialog_15607_Content_4 = {
    Text = "Le penses-tu vraiment ?"
  },
  AvgDialog_15607_Content_5 = {Text = "!?"},
  AvgDialog_15607_Content_6 = {
    Text = "Je vous l'ai dit, il suffit d'entrer dans ce Cœur d'argent pour atteindre la véritable immortalité."
  },
  AvgDialog_15607_Content_7 = {
    Text = "Vous avez beau vous débattre, la matière noire finira par vous effacer, et alors j'apporterai la véritable <Red:« Métamorphose »> au monde — l'immortalité pour tous, la vie éternelle pour chacun."
  },
  AvgDialog_15607_Content_8 = {
    Text = "C›est... la mort... non..."
  },
  AvgDialog_15607_Content_9 = {
    Text = "La couleur noire consumait de plus en plus son corps. Erica se plia de douleur, son esprit au bord de l›effondrement."
  },
  AvgDialog_15608_Content_1 = {
    Text = "C'est... un espace spirituel ?"
  },
  AvgDialog_15608_Content_2 = {
    Text = "Mon dieu, mais qu'est-ce que c'est que ça..."
  },
  AvgDialog_15608_Content_3 = {
    Text = "Une voix... Erica !"
  },
  AvgDialog_15609_Content_1 = {
    Text = "Non, Erica, n'y crois pas !"
  },
  AvgDialog_15609_Content_10 = {
    Text = "Le corps de Chair n'est qu'une cage pour l'âme ; seulement en libérant l'âme peut-elle nous rejoindre.\nSeulement les corps et les esprits de métal nous accordent l'éternité."
  },
  AvgDialog_15609_Content_11 = {
    Text = "Les doigts se resserrant, le visage de Mae se tordit de douleur."
  },
  AvgDialog_15609_Content_12 = {
    Text = "<Shake:Vous... êtes folles...>"
  },
  AvgDialog_15609_Content_13 = {
    Text = "Une autre main tremblante apparaît à l'écran. Erica saisit son propre poignet, le tord et détache la main incontrôlable, la jetant de côté."
  },
  AvgDialog_15609_Content_14 = {
    Text = "La main géante a marqué une pause un instant, comme si elle était quelque peu perplexe."
  },
  AvgDialog_15609_Content_15 = {
    Text = "Pourquoi me résister ? Je lui offre une nouvelle vie."
  },
  AvgDialog_15609_Content_16 = {
    Text = "Ce ne sont que des phantasmes, des phantasmes."
  },
  AvgDialog_15609_Content_17 = {
    Text = "Erica aida Mae, inconsciente, à se relever lentement."
  },
  AvgDialog_15609_Content_18 = {
    Text = "Je l'emmène à l'hôpital. Je... dois la maintenir en vie."
  },
  AvgDialog_15609_Content_19 = {
    Text = "Elle hissa Mae sur son épaule et se fraya un chemin à travers le studio, réduit en miettes, en direction de la porte la plus proche."
  },
  AvgDialog_15609_Content_2 = {
    Text = "Erica, Erica !"
  },
  AvgDialog_15609_Content_3 = {
    Text = "Tandis que tu combats l'ennemi devant toi, une créature visqueuse se faufile par derrière et se jette sur la lumière représentant l'esprit d'Erica."
  },
  AvgDialog_15609_Content_4 = {
    Text = "Comme de la peinture se dissolvant dans l'eau, les ténèbres se répandent à l'intérieur de l'orbe de lumière, recouvrant tout ce qu'il contient.\nL'orbe de lumière commence à vaciller."
  },
  AvgDialog_15609_Content_5 = {
    Text = "Que se passe-t-il ? Ma main... elle bouge toute seule..."
  },
  AvgDialog_15609_Content_6 = {
    Text = "C'était toi ? Arrête, <Big:Arrête !>"
  },
  AvgDialog_15609_Content_7 = {
    Text = "Pourquoi ? Tu ne veux pas la sauver ?"
  },
  AvgDialog_15609_Content_8 = {
    Text = ": Tu essaies de l'étrangler ! Lâche !"
  },
  AvgDialog_15609_Content_9 = {
    Text = "Alors que les ténèbres et la lumière s'entrelacent, vous voyez une main mécanique s'étendre lentement vers le cou de Mae."
  },
  AvgDialog_15610_Content_1 = {
    Text = "La ligne de défense d'une seule personne est quasiment inexistante, peu importe combien de monstres vous écrasez. Les corps formés de boue se regroupent rapidement, vous contournent et bondissent droit dans la sphère de lumière."
  },
  AvgDialog_15610_Content_10 = {
    Text = "Du plasma doré crépitait sur les ombres, rendant la forme d'Erica de plus en plus solide."
  },
  AvgDialog_15610_Content_11 = {
    Text = "Elle lève la main et disperse le monstre devant vous avec du plasma. La main géante tressaille légèrement et laisse échapper un soupir."
  },
  AvgDialog_15610_Content_12 = {
    Text = "Je souhaitais simplement vous remercier de m'avoir ramené et de m'avoir accordé un nouveau corps. Pourquoi me faire du mal ?"
  },
  AvgDialog_15610_Content_13 = {
    Text = "Ramené ? Que voulez-vous dire par « ramené » ? Je n'ai jamais..."
  },
  AvgDialog_15610_Content_14 = {
    Text = "Est-ce que ça peut alimenter ma poupée ?"
  },
  AvgDialog_15610_Content_15 = {
    Text = "Erica tenait le tube métallique noir avec suspicion, l'examinant sous tous les angles."
  },
  AvgDialog_15610_Content_16 = {
    Text = "Si vous craignez qu'il ne puisse pas soutenir le fonctionnement prolongé de la marionnette, ne vous inquiétez pas. \nCet objet est suffisant pour alimenter des mécanismes encore plus complexes et plus grands."
  },
  AvgDialog_15610_Content_17 = {
    Text = "Êtes–vous en train de dire que d'autres utilisent aussi cette énergie ?"
  },
  AvgDialog_15610_Content_18 = {
    Text = "Des choses similaires existent, mais identiques ? Absolument impossible."
  },
  AvgDialog_15610_Content_19 = {
    Text = "Ce que vous cherchez, c'est une « énergie unique en son genre », et la boutique de Daffodil ne déçoit jamais ses clients."
  },
  AvgDialog_15610_Content_2 = {
    Text = "C-c'est agaçant..."
  },
  AvgDialog_15610_Content_20 = {
    Text = "Au fait, un petit conseil amical — ne soyez pas curieuse quant à sa structure et ses principes.\nUne fois la boîte de Pandore ouverte, vous devrez en assumer les conséquences vous–même."
  },
  AvgDialog_15610_Content_21 = {
    Text = "Je ne voudrais pas qu'un génie comme vous meure jeune. En plus du projecteur, il y a bien d'autres idées que je souhaite réaliser."
  },
  AvgDialog_15610_Content_22 = {
    Text = "En attendant ta prochaine visite, Erica."
  },
  AvgDialog_15610_Content_23 = {
    Text = "Non, impossible. Il ne devrait y avoir que — dans l'Énergie S."
  },
  AvgDialog_15610_Content_24 = {
    Text = "Un minuscule <Yellow:fragment d'argent>, n'est–ce pas ?\nUne chose magique capable de faire fonctionner des machines et de préserver les âmes des êtres vivants."
  },
  AvgDialog_15610_Content_25 = {
    Text = "Votre esprit a fusionné avec ce corps grâce à la matière noire. Entrez dans le <Yellow:Cœur d'argent> avant d'être corrompue, et vous deviendrez véritablement immortelle — vous et moi.\n\nEn tant que « mère » de cette vie, vous avez le droit de le partager avec moi.\nC'est dommage que vous soyez si obstinée."
  },
  AvgDialog_15610_Content_26 = {
    Text = "Tout ce que je peux faire, c'est laisser la <Yellow:substance noire> vous dévorer."
  },
  AvgDialog_15610_Content_27 = {
    Text = "La main géante bougea soudainement, écartant ses doigts pour révéler un Argent fissuré mais encore brillant dans sa paume."
  },
  AvgDialog_15610_Content_28 = {
    Text = "Adieu, mon éphémère créatrice."
  },
  AvgDialog_15610_Content_3 = {
    Text = "L'orbe vacille à nouveau, et vous voyez les jambes d'Erica trembler de manière incontrôlable."
  },
  AvgDialog_15610_Content_4 = {
    Text = "Les engrenages s'emboîtent étroitement, et un arc électrique jaune vif jaillit entre les tuyaux et les supports."
  },
  AvgDialog_15610_Content_5 = {
    Text = "Cessez de résister. Abandonnez-moi le contrôle de votre corps."
  },
  AvgDialog_15610_Content_6 = {
    Text = "Ne voulez-vous pas la sauver ? Ne souhaitez-vous pas qu'elle obtienne l'éternité avec vous ?"
  },
  AvgDialog_15610_Content_7 = {
    Text = "D'autres éclairs apparaissent sur l'écran."
  },
  AvgDialog_15610_Content_8 = {
    Text = "Des particules de lumière s'échappèrent de l'orbe, se rassemblant pour former une silhouette humanoïde."
  },
  AvgDialog_15610_Content_9 = {Text = "E-Erica ?!"},
  AvgDialog_15611_Content_1 = {
    Text = "Pourquoi la sauver ?\nElle a troqué tes rêves contre son avenir. Tu ne ressens aucune rancœur ?"
  },
  AvgDialog_15611_Content_10 = {
    Text = "Mais j'ai vite réalisé : ce n'est pas un désastre, ni un fantasme, mais une opportunité pour l'humanité."
  },
  AvgDialog_15611_Content_11 = {
    Text = "Pas de douleur ni de mort dans les machines ; dans les machines, nous pouvons créer un vrai Royaume Divin, mieux que le vôtre, faux.\n\nNous pouvons transcender la vie de Caro."
  },
  AvgDialog_15611_Content_12 = {
    Text = "De la boue noire s'écoule à nouveau de la main géante. Tremblante et se tordant, elle rampe vers l'avant, fusionnant avec elle-même, excitée par la scène sinistre dépeinte par la voix."
  },
  AvgDialog_15611_Content_13 = {
    Text = "La voix s'amplifie, la main géante tremble, projetant davantage de boue et de monstres."
  },
  AvgDialog_15611_Content_14 = {
    Text = "Nous pouvons devenir des dieux nous-mêmes."
  },
  AvgDialog_15611_Content_15 = {
    Text = "La boue accélère soudainement et se jette une fois de plus sur l'orbe de lumière derrière vous."
  },
  AvgDialog_15611_Content_2 = {
    Text = "Elle a seulement... pris une mauvaise décision.\nQuand elle se réveillera, on en discutera et tout sera résolu."
  },
  AvgDialog_15611_Content_3 = {
    Text = "La cabine téléphonique la plus proche est à un kilomètre ; elle ne peut pas se permettre d'attendre."
  },
  AvgDialog_15611_Content_4 = {
    Text = "Désolée, je préfère faire confiance à l'instinct de survie de l'humanité plutôt qu'à vos absurdités sur la « libération des âmes »."
  },
  AvgDialog_15611_Content_5 = {
    Text = "Si je mens, comment expliques-tu ton état actuel ?\nTon corps de Chair a été réduit en morceaux, et pourtant ton esprit persiste, contrôlant même ce corps pour continuer à vivre.\n\nCela ne prouve-t-il pas ce que j'avance ?"
  },
  AvgDialog_15611_Content_6 = {
    Text = "<Big:Vous ne pouvez pas être sûr que c'est la raison pour laquelle je suis devenue comme ça !>"
  },
  AvgDialog_15611_Content_7 = {
    Text = "Erica marqua une pause, semblant vouloir inspirer, mais n'ayant plus les organes pour le faire."
  },
  AvgDialog_15611_Content_8 = {
    Text = "Qu'est-ce que je fais, à discuter avec un phantasme... Ne pas écouter, ne pas réfléchir. C'est un phantasme, né du gaz toxique—"
  },
  AvgDialog_15611_Content_9 = {
    Text = "Tu as peur, alors tu essaies de fuir.\nJe comprends. Tout comme toi, j'étais empli de peur juste après la <Red:« Métamorphose »>."
  },
  AvgDialog_15612_Content_1 = {
    Text = "Des rythmes invisibles vous entourent et vous enveloppent, avec de faibles lueurs apparaissant au loin, fragiles et hors de portée."
  },
  AvgDialog_15612_Content_10 = {
    Text = "<Gray:Impossible... Pourrait-il...>"
  },
  AvgDialog_15612_Content_11 = {
    Text = "Est-ce que toi et Erica partagez le même corps en ce moment ?\nEst-ce pour cela qu'elle s'est transformée en marionnette mécanique ?"
  },
  AvgDialog_15612_Content_12 = {
    Text = "<Gray:Mais comment une simple explosion pourrait-elle avoir un tel effet ?>"
  },
  AvgDialog_15612_Content_13 = {
    Text = "Veux-tu la sauver ?"
  },
  AvgDialog_15612_Content_14 = {Text = "?!"},
  AvgDialog_15612_Content_15 = {
    Text = "Une voix surgit de nulle part, omniprésente et pourtant insaisissable.\nTu regardes autour de toi, et une silhouette commence à prendre forme dans le vaste espace mental."
  },
  AvgDialog_15612_Content_16 = {
    Text = "Qui, qui est là ?"
  },
  AvgDialog_15612_Content_17 = {
    Text = "Je suis la volonté qui te répond, la vie à qui tu as accordé un nouveau corps."
  },
  AvgDialog_15612_Content_18 = {
    Text = "On peut me considérer comme ta Relique, et toi, ma « mère » dans cette vie."
  },
  AvgDialog_15612_Content_19 = {
    Text = "Une main gigantesque se matérialise derrière l'orbe représentant l'esprit d'Erica, ses doigts tressaillant et dégoulinant de substance noire."
  },
  AvgDialog_15612_Content_2 = {
    Text = "Mei, Mei ! Réveille-toi, Mei !"
  },
  AvgDialog_15612_Content_20 = {
    Text = "...Des Tic-Taciens... ?"
  },
  AvgDialog_15612_Content_21 = {
    Text = "J'aime ce nom, oui, appelle-moi l'Homme Tic-Tac.\nEn gage de ma renaissance, je peux t'aider à la sauver.\nTu n'as qu'à lâcher prise."
  },
  AvgDialog_15612_Content_22 = {
    Text = "Lâche prise, et laisse-moi tout gérer."
  },
  AvgDialog_15612_Content_23 = {
    Text = "La substance visqueuse entassée au sol s'est soudain agitée, fusionnant en formes tordues qui rampaient vers la lumière."
  },
  AvgDialog_15612_Content_3 = {
    Text = "Vous vous approchez rapidement de la source du son."
  },
  AvgDialog_15612_Content_4 = {
    Text = "C'est un orbe de lumière flottant. À travers lui, vous apercevez un visage couvert de sang et de sable — le visage de Mae."
  },
  AvgDialog_15612_Content_5 = {
    Text = "Elle semblait évanouie, ne réagissant même pas à une légère tape d'une main pâle."
  },
  AvgDialog_15612_Content_6 = {
    Text = "<Gray:Cette main...>"
  },
  AvgDialog_15612_Content_7 = {
    Text = "Vous baissez la tête, confirmant votre soupçon : la main dans la sphère de lumière est identique à la vôtre. \nC'est la main d'un automate, désormais mue par la volonté d'un autre."
  },
  AvgDialog_15612_Content_8 = {
    Text = "Merde, Mei ! Nous devons sortir d'ici, Mei !"
  },
  AvgDialog_15612_Content_9 = {
    Text = "La main mécanique se posa sur l'épaule de Mae, et l'image dans la sphère de lumière changea, révélant un atelier encore englouti par les flammes, comme si quelqu'un regardait autour de lui."
  },
  AvgDialog_15613_Content_1 = {
    Text = "Conclusion brillante"
  },
  AvgDialog_15613_Content_10 = {
    Text = "Pied droit."
  },
  AvgDialog_15613_Content_11 = {
    Text = "Erica tomba à genoux. Les courts-circuits fréquents avaient rendu sa jambe gauche inerte, la forçant à se soutenir avec son bras droit, dépourvu de main."
  },
  AvgDialog_15613_Content_12 = {
    Text = "Elle adossa délicatement Mae contre la cabine téléphonique, puis rampa à l'intérieur en s'aidant de ses quatre membres. \nLe courant électrique activa la cabine, et elle appuya sur le bouton d'appel d'urgence, indiquant la localisation de la cabine."
  },
  AvgDialog_15613_Content_13 = {
    Text = "De cette manière... elle... sera en sécurité..."
  },
  AvgDialog_15613_Content_14 = {
    Text = "Et ensuite...? Qu'est-ce que... ça pourrait être...?"
  },
  AvgDialog_15613_Content_15 = {
    Text = "Tu sais ce que c'est."
  },
  AvgDialog_15613_Content_16 = {
    Text = "Tu te rappelles le contenu du dossier que tu as lu avant d'entrer ici."
  },
  AvgDialog_15613_Content_17 = {
    Text = "Le A.F. 297 @1@1 03:47, une explosion inexpliquée s'est produite au sud-est de la République d'Agro @3 État @1@2@1 Ville. L'onde de choc a provoqué un séisme de magnitude 3,8 dans la zone, avec des secousses perceptibles atteignant les villages situés à 5 kilomètres de @1@2@1 Ville.\n\n......\n\nLe A.F. 297 @1@1, 13 composants ont été récupérés dans les bois au sud-est de la République d'Agro @3 État @1@2@1 Ville, numérotés A101 à A114. Parmi eux, les composants A108, A109 et A113 étaient gravement endommagés et ont été confiés à Doll pour restauration de conception.\nUne série de plans de conception correspondant aux vestiges du site de l'explosion a été récupérée par l'équipe d'investigation au @2 Route @1, suspectés d'être des plans de dispositifs explosifs, qui ont également été soumis à Doll pour analyse."
  },
  AvgDialog_15613_Content_18 = {
    Text = "Tu entends le vent bruisser dans les feuilles."
  },
  AvgDialog_15613_Content_19 = {
    Text = "L'orbe de lumière s'est assombri, se fondant presque dans l'obscurité environnante."
  },
  AvgDialog_15613_Content_2 = {
    Text = "Pied gauche."
  },
  AvgDialog_15613_Content_20 = {
    Text = "Même si tu sauves son Corps de Chair, et après ? \nLa mort finira par venir ; quand elle arrivera, te remerciera-t-elle, ou t'en voudra-t-elle de lui avoir ôté sa chance d'immortalité ? \n\nLâche prise, Erica, et laisse-moi prendre le contrôle de ce Corps. \nJe la ferai <Red:« Transformer »>, lui permettant d'avoir un meilleur avenir."
  },
  AvgDialog_15613_Content_21 = {
    Text = "J'ai... toujours pensé... que je mourrais dans une explosion...\nPardon... de... t'avoir entraînée là-dedans..."
  },
  AvgDialog_15613_Content_22 = {
    Text = "...Qu'est-ce que tu comptes faire ?"
  },
  AvgDialog_15613_Content_23 = {
    Text = "Tais-toi... Démon... Je ne... te parle pas... à toi..."
  },
  AvgDialog_15613_Content_24 = {
    Text = "L›image dans l›orbe montre une main mécanique carbonisée laissant encore fuir du plasma."
  },
  AvgDialog_15613_Content_25 = {
    Text = "À un moment donné, plusieurs fils se trouvaient dans leurs mains, couverts d›une substance noire et visqueuse."
  },
  AvgDialog_15613_Content_26 = {
    Text = "Désolée, peuple Tik-Tok... Au final... Il faut que je vous détruise moi-même..."
  },
  AvgDialog_15613_Content_27 = {
    Text = "Le Silence tomba parmi vous.\nVous n›êtes toujours pas sûr de votre rôle dans ce rêve, et elle ne semble pas attendre de réponse."
  },
  AvgDialog_15613_Content_28 = {
    Text = "*soupir*..."
  },
  AvgDialog_15613_Content_29 = {
    Text = "Quel... dommage..."
  },
  AvgDialog_15613_Content_3 = {
    Text = "Pied droit."
  },
  AvgDialog_15613_Content_30 = {
    Text = "Elle tira de toutes ses forces."
  },
  AvgDialog_15613_Content_32 = {
    Text = "Vous vous redressez soudainement et vous retrouvez dans votre chambre familière."
  },
  AvgDialog_15613_Content_33 = {
    Text = "Quelqu›un frappe à votre porte."
  },
  AvgDialog_15613_Content_34 = {Text = "Entre."},
  AvgDialog_15613_Content_35 = {
    Text = "Bon après-midi, Gardien. Vous avez un message de Poupée. Souhaitez-vous le recevoir ?"
  },
  AvgDialog_15613_Content_36 = {
    Text = "Doll a ajouté une nouvelle fonctionnalité pour vous... Réception."
  },
  AvgDialog_15613_Content_37 = {
    Text = "Bip—Vous souvenez-vous quel jour nous sommes, %player% ? Deux mots : Évaluation."
  },
  AvgDialog_15613_Content_38 = {Text = "...Oh non."},
  AvgDialog_15613_Content_39 = {
    Text = "Je vous suggère de vous présenter en classe dans les cinq prochaines minutes, sinon je ne peux pas garantir ce que sera votre entraînement pendant les 30 prochains jours. Peut-être que l›entraînement physique sera doublé ?"
  },
  AvgDialog_15613_Content_4 = {
    Text = "Chaque pas fait jaillir des étincelles, et chaque mouvement résonne du grincement strident des mécanismes."
  },
  AvgDialog_15613_Content_40 = {
    Text = "Bip—Fin du message. Souhaitez-vous répondre ?"
  },
  AvgDialog_15613_Content_41 = {
    Text = "Pourquoi répondre ? Seulement filez d›ici !!"
  },
  AvgDialog_15613_Content_42 = {
    Text = "La silhouette du Gardien disparut au bout du couloir. Erica se retourna et regarda les dossiers éparpillés sur la table."
  },
  AvgDialog_15613_Content_43 = {
    Text = "An 298@Jan@2, Département de l›Éveil de l›Université de Misargh, @3\nRestauration du torse de l›Automate E achevée selon les plans T-38, Série EA301881.\nIl s›agit de notre 10e tentative de restauration. Je dois exprimer mon admiration pour le concepteur et créateur original de cet automate—il est complexe et élégant, avec des centaines d›engrenages et de roulements interconnectés formant une symphonie mécanique. Même à l›arrêt, il émane une vitalité unique.\nMalheureusement, il nous manque toujours le plan de la machine clé—un cylindre d›un diamètre de 5 cm et d›une longueur de 10 cm. Il devrait s›agir du noyau énergétique de l›automate, et pourtant je n›ai jamais rencontré quelque chose d›aussi petit capable d›alimenter un dispositif aussi complexe...\nJ›espère que le Professeur Doll aura des idées. J›ai hâte de le voir pleinement opérationnel."
  },
  AvgDialog_15613_Content_44 = {
    Text = "An 298@Jan@2, Département de l›Éveil de l›Université de Misargh, @3\nRestauration de la machine électrique achevée, Série MF311028.\nMalgré de nombreux obstacles (Par le Père, nous avons essayé 28 fois, 28 fois !), la conception finale du Professeur Doll s›est avérée correcte—le noyau énergétique est un Cœur d›argent.\nParmi plusieurs Cœurs d›argent testés, seule l›unité E-1929 a permis le fonctionnement normal de la machine. Je ne peux m›empêcher de penser qu›une intention persistante du concepteur a influencé cela, bien que l›on ignore actuellement où il se trouve."
  },
  AvgDialog_15613_Content_45 = {
    Text = "An 300 de l'Alluvion, @2 mois, @1 jour, Université de Misargh, Département d'Éveil, Doll\nLa Doll automatique Erica a été éveillée avec succès.\nLe Corps éveillé fait preuve d'une agressivité extrême et de pulsions destructrices. Même avec l'enquêteur maintenant son esprit, elle montre une nette inclination à attaquer et émet de manière incontrôlable des courants électriques, attaquant les objets environnants sans discrimination.\nAlistair a déterminé que E-1929 contient deux esprits : l'un est fou et puissant, l'autre est faible mais plus rationnel. Des tentatives devraient être faites pour les séparer ou inhiber la folie à un niveau contrôlable.\n......\nAn 300 de l'Alluvion, @2 mois, @2 jour, Université de Misargh, Département d'Éveil, Doll\nImpossible de séparer les esprits, la seconde option est activement envisagée.\nUn dispositif d'inhibition spirituelle est une bonne idée.\n......\nAn 303 de l'Alluvion, @1 mois, @2 jour, Université de Misargh, Département d'Éveil, Doll\nDispositif d'inhibition achevé et installé avec succès.\nLa folie du Corps éveillé est contenue, l'état général se stabilise, mais il y a encore des cas de brèves défaillances de l'inhibition.\nLa personnalité, les préférences, etc. du Corps éveillé sont complètement perdues, se comportant davantage comme une poupée que comme un être humain.\nAu moins, elle n'est plus au bord de l'explosion à chaque instant.\n......"
  },
  AvgDialog_15613_Content_46 = {
    Text = "Erica pencha la tête, rangea les dossiers soigneusement et quitta la pièce."
  },
  AvgDialog_15613_Content_5 = {
    Text = "Sous un réverbère proche, une cabine téléphonique publique se dresse silencieusement."
  },
  AvgDialog_15613_Content_6 = {
    Text = "Pied gauche."
  },
  AvgDialog_15613_Content_7 = {
    Text = "Pied droit."
  },
  AvgDialog_15613_Content_8 = {
    Text = "Remarquant ta détermination, la vase étendue au sol continue d'attaquer l'esprit d'Erica, te teignant entièrement en noir."
  },
  AvgDialog_15613_Content_9 = {
    Text = "Pied gauche."
  },
  AvgDialog_18708_Content_1 = {Text = "!!!"},
  AvgDialog_18708_Content_10 = {
    Text = "Accompagné de gémissements douloureux, les traits du Chasseur de Crânes se tordent à un degré incroyable, avec des kystes remplis de pus se tordant sous la peau, prêts à éclater."
  },
  AvgDialog_18708_Content_11 = {
    Text = "Qu›est-ce que c›est...?"
  },
  AvgDialog_18708_Content_13 = {
    Text = "Votre tête est impitoyablement tranchée, la D-Slime noire gicle du cou, éclaboussant presque votre visage."
  },
  AvgDialog_18708_Content_14 = {
    Text = "Être trop curieux n'est pas une bonne habitude, Gardien."
  },
  AvgDialog_18708_Content_15 = {
    Text = "Son crâne était rempli de D-Slime accumulé. Je te conseille de garder tes distances."
  },
  AvgDialog_18708_Content_16 = {
    Text = "Dame Daffodil !"
  },
  AvgDialog_18708_Content_17 = {
    Text = "Bonsoir, ma petite rose."
  },
  AvgDialog_18708_Content_18 = {
    Text = "Pourquoi est-ce encore toi... ?"
  },
  AvgDialog_18708_Content_19 = {
    Text = "J'ai suivi la trace du Chasseur de crânes ici et repris ma fleur."
  },
  AvgDialog_18708_Content_2 = {
    Text = "Le Chasseur de Crânes s'effondre lourdement au sol, émettant un faible gémissement."
  },
  AvgDialog_18708_Content_20 = {
    Text = "Daffodil a marché sans effort sur le sol taché de sang et de D-Slime, a cueilli un narcisse du lit, et l'a légèrement senti."
  },
  AvgDialog_18708_Content_21 = {
    Text = "C'est mon Narcisse Marron, que j'ai soigneusement cultivé pendant trois ans. Il a un effet apaisant et calmant."
  },
  AvgDialog_18708_Content_22 = {
    Text = "Souhaitez-vous prendre une inspiration ?"
  },
  AvgDialog_18708_Content_23 = {
    Text = "<LightGray:Pas étonnant que j'aie dormi si profondément tout à l'heure...>"
  },
  AvgDialog_18708_Content_24 = {
    Text = "Vous avez irrité en écartant le narcisse en fleurs et humide qu'elle tenait dans sa main."
  },
  AvgDialog_18708_Content_25 = {
    Text = "Vous semblez en savoir beaucoup sur le Chasseur de Crânes."
  },
  AvgDialog_18708_Content_26 = {
    Text = "Comment savez-vous que son cerveau allait dégouliner de D-boue ?"
  },
  AvgDialog_18708_Content_27 = {
    Text = "Si vous aviez vécu aussi longtemps que moi et vu suffisamment de patients en Dissolution, vous comprendriez naturellement plus."
  },
  AvgDialog_18708_Content_28 = {
    Text = "La Piste du Chasseur de Crânes ?"
  },
  AvgDialog_18708_Content_29 = {
    Text = "\"Suivant la trace du Chasseur de Crânes\" — Pouvez-vous sentir sa position ?"
  },
  AvgDialog_18708_Content_3 = {
    Text = "Vous entendez un \"thud, thud, thud\" venant des escaliers. La porte en bois derrière vous s'ouvre soudainement."
  },
  AvgDialog_18708_Content_30 = {
    Text = "J'ai mes méthodes. Cependant... pour éviter d'effrayer les enfants, je ferais mieux de ne pas les révéler."
  },
  AvgDialog_18708_Content_31 = {Text = "新增"},
  AvgDialog_18708_Content_32 = {
    Text = "Veuillez partir pour l'instant, Dame Jonquille. Ne pas interférer avec l'enquête du Gardien."
  },
  AvgDialog_18708_Content_33 = {
    Text = "Hein, tu ne doutes plus de moi ?"
  },
  AvgDialog_18708_Content_34 = {
    Text = "Je ne peux pas complètement exclure ton suspicion pour l'instant. Mais mon intuition me dit..."
  },
  AvgDialog_18708_Content_35 = {
    Text = "Si vous étiez le \"Chasseur de Crânes\", vous géreriez cela de manière plus claire et efficace, ne laissant aucune trace évidente derrière vous."
  },
  AvgDialog_18708_Content_36 = {
    Text = "Oh mon, est-ce vraiment un compliment pour moi ?\nPour être précis, c'est un fait, pas juste une intuition."
  },
  AvgDialog_18708_Content_37 = {
    Text = "...Ne change pas de sujet."
  },
  AvgDialog_18708_Content_38 = {
    Text = "Puisque tu es seulement arrivé en ville aujourd'hui, qui était cette personne que j'ai vue la nuit dernière ?"
  },
  AvgDialog_18708_Content_39 = {
    Text = "Avez-vous une sœur jumelle ?"
  },
  AvgDialog_18708_Content_4 = {
    Text = "{Male=Mr.,Female=Miss} %player%, je viens d'entendre un bruit, que s'est–il passé ?"
  },
  AvgDialog_18708_Content_40 = {Text = "新增"},
  AvgDialog_18708_Content_41 = {
    Text = "Daffodil semblait troublée par ses pensées, puis a soudainement tendu la main vers vous."
  },
  AvgDialog_18708_Content_42 = {
    Text = "Des doigts doux effleurent votre visage un instant, puis glissent vers votre cou, s'arrêtant pour sentir le pouls au fond de vos vaisseaux sanguins."
  },
  AvgDialog_18708_Content_43 = {
    Text = "<Shake:...?>"
  },
  AvgDialog_18708_Content_44 = {
    Text = "J'ai toujours pensé que les humains étaient des créatures douées pour le déguisement."
  },
  AvgDialog_18708_Content_45 = {
    Text = "Vous vous enveloppez dans un Caro similaire, prononçant des mots similaires, avec des pulsations et des battements de cœur similaires..."
  },
  AvgDialog_18708_Content_46 = {
    Text = "Pendant longtemps, je n'ai pas pu te distinguer, tout comme tu ne pouvais pas me distinguer."
  },
  AvgDialog_18708_Content_47 = {
    Text = "Donc... tu veux dire que vous n'êtes pas des jumeaux, mais que vous partagez une sorte de relation spéciale ?"
  },
  AvgDialog_18708_Content_48 = {
    Text = "C'est possible. Veux-tu faire une supposition ? Tu as trois chances."
  },
  AvgDialog_18708_Content_49 = {
    Text = "...Je refuse."
  },
  AvgDialog_18708_Content_5 = {
    Text = "C-C'est... ?!"
  },
  AvgDialog_18708_Content_50 = {
    Text = "Même si je devine juste, vous ne me direz toujours pas la vraie réponse. Ai-je raison ?"
  },
  AvgDialog_18708_Content_51 = {
    Text = "Jonquille traça distraitement les veines sur ton cou avec ses doigts, ses yeux remplis d'un sourire encore plus profond."
  },
  AvgDialog_18708_Content_52 = {
    Text = "Vous apprenez vraiment à mieux me connaître, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_18708_Content_53 = {
    Text = "Vous reculez d'un demi-pas, sortant de portée de Daffodil, et lui lancez un regard d'avertissement."
  },
  AvgDialog_18708_Content_54 = {
    Text = "Dans vos yeux, est-ce que le fait de se ressembler exactement fait d'eux des jumeaux ?"
  },
  AvgDialog_18708_Content_55 = {
    Text = "En général, c'est probablement la seule possibilité."
  },
  AvgDialog_18708_Content_56 = {
    Text = "Mais toi et moi savons tous les deux que le monde dans lequel nous vivons n'est en rien \"ordinaire.\""
  },
  AvgDialog_18708_Content_57 = {
    Text = "Bien sûr. Le plus regrettable dans ce monde est son \"inconventionalité.\""
  },
  AvgDialog_18708_Content_58 = {
    Text = "Être une paire de sœurs insouciantes semble bien aussi."
  },
  AvgDialog_18708_Content_6 = {
    Text = "Vous avancez et tirez le capuchon noir du Chasseur de Crânes, révélant le visage en dessous"
  },
  AvgDialog_18708_Content_7 = {
    Text = "Pommettes saillantes, nez crochu et joues creuses—un visage complètement inconnu."
  },
  AvgDialog_18708_Content_8 = {
    Text = "Vous savez vraiment choisir vos cibles, me poursuivant jusqu'ici. Qui êtes-vous exactement ?"
  },
  AvgDialog_18708_Content_9 = {
    Text = "Ugh... Ah..."
  },
  AvgDialog_18709_Content_1 = {
    Text = "Pluie amère"
  },
  AvgDialog_18709_Content_10 = {
    Text = "Tu te soutiens contre la tête de lit, des souvenirs d'événements récents défilant devant tes yeux. De nombreuses questions restent à résoudre."
  },
  AvgDialog_18709_Content_11 = {
    Text = "Demandons d'abord à Mademoiselle Horla ce qu'elle sait."
  },
  AvgDialog_18709_Content_12 = {
    Text = "Demande à Old Freeman"
  },
  AvgDialog_18709_Content_13 = {
    Text = "Vieux Freeman ? Alors il est encore vivant..."
  },
  AvgDialog_18709_Content_14 = {
    Text = "J'ai entendu les villageois dire qu'il était une personne optimiste et joyeuse quand il était jeune, et que tout le monde l'aimait."
  },
  AvgDialog_18709_Content_15 = {
    Text = "Après le <Yellow:plague>, il a quitté la ville de Reny et est revenu en tant que personne complètement différente."
  },
  AvgDialog_18709_Content_16 = {Text = "Peste ?"},
  AvgDialog_18709_Content_17 = {
    Text = "Il y a trois ans, une catastrophe de Dissolution s'est produite au nord de la ville de Ryker. Les habitants l'appelaient une peste."
  },
  AvgDialog_18709_Content_18 = {
    Text = "Cela s'est maintenant complètement transformé en terre morte."
  },
  AvgDialog_18709_Content_19 = {
    Text = "Demande à Daffodil"
  },
  AvgDialog_18709_Content_2 = {Text = "新增"},
  AvgDialog_18709_Content_20 = {
    Text = "Miss Horla, le ton que tu as utilisé en parlant de Jonquille tout à l'heure... est-ce que vous deux vous connaissiez avant ?"
  },
  AvgDialog_18709_Content_21 = {
    Text = "Dame Jonquille..."
  },
  AvgDialog_18709_Content_22 = {
    Text = "Horla regardait la page du livre dans sa main, un léger sourire se dessinant sur son visage."
  },
  AvgDialog_18709_Content_23 = {
    Text = "Dame Jonquille, elle... m'a aidé."
  },
  AvgDialog_18709_Content_24 = {
    Text = "Année 15@1, San Pedro"
  },
  AvgDialog_18709_Content_25 = {
    Text = "Cette collection de poèmes de Longsa est unique. Assurez-vous de la chérir."
  },
  AvgDialog_18709_Content_26 = {
    Text = "Merci beaucoup, Dame Jonquille. Je ne peux pas croire que vous l'ayez vraiment trouvé..."
  },
  AvgDialog_18709_Content_27 = {
    Text = "\"Puisse-tu conserver à jamais la beauté éclatante d'une rose.\""
  },
  AvgDialog_18709_Content_28 = {
    Text = "Belle poésie. Vous avez un excellent goût."
  },
  AvgDialog_18709_Content_29 = {
    Text = "Oui, mais je préfère \"J'honore ce moment avec du lait et des fleurs...\""
  },
  AvgDialog_18709_Content_3 = {
    Text = "Vous vous êtes enfin réveillé, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_18709_Content_30 = {
    Text = "Ah... Désolé, je me suis encore laissé distraire."
  },
  AvgDialog_18709_Content_31 = {
    Text = "Je connais les règles de la \"Boutique d'Échange\". Alors, que veux-tu de moi ?"
  },
  AvgDialog_18709_Content_32 = {
    Text = "Hmm... Je devrai t'observer de près, ma petite rose."
  },
  AvgDialog_18709_Content_33 = {
    Text = "Le regard balayait tout le corps de Horla sans émotion. La fille a involontairement redressé son dos."
  },
  AvgDialog_18709_Content_34 = {
    Text = [[
Peux-tu partager un souvenir avec moi ? 
Douloureux, triste... n'importe quel souvenir malheureux fera l'affaire.]]
  },
  AvgDialog_18709_Content_35 = {
    Text = "Des souvenirs malheureux ? Th-Ce n'est pas une bonne chose. Que prévois-tu d'en faire...?"
  },
  AvgDialog_18709_Content_36 = {
    Text = "Je prévois de l'utiliser pour une petite expérience. Vous le saurez alors."
  },
  AvgDialog_18709_Content_37 = {
    Text = "Des jours d'épuisement incessant érodent vos nerfs ; vous sombrez dans le sommeil aux doux mots du Horla."
  },
  AvgDialog_18709_Content_38 = {Text = "新增"},
  AvgDialog_18709_Content_39 = {
    Text = "Après une durée inconnue, une légère bruine a commencé à tomber à l'extérieur de la fenêtre."
  },
  AvgDialog_18709_Content_4 = {
    Text = "Je me souviens que j'ai semblé m'évanouir, et puis..."
  },
  AvgDialog_18709_Content_40 = {
    Text = "Quelqu'un traîne lentement et sans fin sur le chemin boueux sous la pluie."
  },
  AvgDialog_18709_Content_41 = {
    Text = "Ils n'apparaissent que lors des nuits pluvieuses, leurs pas dissimulés par la pluie, s'approchant furtivement derrière vous..."
  },
  AvgDialog_18709_Content_42 = {
    Text = "Les Chasseurs de Crânes ne sont ni une personne ni deux. Les Chasseurs de Crânes sont une organisation."
  },
  AvgDialog_18709_Content_43 = {
    Text = "Une nuit pluvieuse, seul... <Red: N'est-ce pas votre situation actuelle ?>"
  },
  AvgDialog_18709_Content_44 = {
    Text = "<Red: Zzz... Krr...>"
  },
  AvgDialog_18709_Content_45 = {
    Text = "<RedBig: Snap !>"
  },
  AvgDialog_18709_Content_46 = {Text = "?!"},
  AvgDialog_18709_Content_47 = {
    Text = "Un pâle éclair de lumière fend le calme de la nuit. Vous ouvrez brusquement les yeux dans l'obscurité."
  },
  AvgDialog_18709_Content_48 = {
    Text = "Quelqu'un se tient à côté de votre lit."
  },
  AvgDialog_18709_Content_49 = {
    Text = "Le regard lourd ressemble à une faux froide et humide traçant vos membres, votre dos, et..."
  },
  AvgDialog_18709_Content_5 = {
    Text = "Oui, c'était la Dame Jonquille qui vous a ramené et m'a demandé de bien prendre soin de vous."
  },
  AvgDialog_18709_Content_50 = {
    Text = "Un cou non protégé."
  },
  AvgDialog_18709_Content_51 = {
    Text = "Tête@1 Crâne@4"
  },
  AvgDialog_18709_Content_54 = {Text = "Hmm... !!"},
  AvgDialog_18709_Content_55 = {
    Text = "Vous tombez soudainement du lit et couvrez instinctivement votre cou."
  },
  AvgDialog_18709_Content_56 = {
    Text = "Une silhouette ombragée tenant une faux se tient près du lit, se fondant presque dans la nuit noire derrière."
  },
  AvgDialog_18709_Content_57 = {
    Text = "L'air est empli de l'odeur de la pluie et de la rouille. Du sang rouge sombre goutte de la lame froide et blanche, formant une flaque sur le sol."
  },
  AvgDialog_18709_Content_58 = {
    Text = "—C'est le Chasseur de crânes."
  },
  AvgDialog_18709_Content_6 = {
    Text = "Daffodil... ?"
  },
  AvgDialog_18709_Content_7 = {
    Text = "Vous attrapez une odeur familière."
  },
  AvgDialog_18709_Content_8 = {
    Text = "Un vase à cou mince est apparu sur la table de nuit, avec des fleurs de narcisse blanches étirant leurs pétales vers la lumière du soleil."
  },
  AvgDialog_18709_Content_9 = {
    Text = "C'est son odeur..."
  },
  AvgDialog_18710_Content_1 = {
    Text = "Royaume des bêtes"
  },
  AvgDialog_18710_Content_10 = {
    Text = "C'était une nuit d'été claire, et je transportais diligemment mes \"butins\" comme d'habitude."
  },
  AvgDialog_18710_Content_11 = {
    Text = "<Shake:Des têtes... encore des têtes...>"
  },
  AvgDialog_18710_Content_12 = {
    Text = "Tap. Tap. Tap."
  },
  AvgDialog_18710_Content_13 = {
    Text = "Le son de pas légers s'approcha silencieusement, et une voix douce se fit entendre d'en haut."
  },
  AvgDialog_18710_Content_14 = {
    Text = "Heh... Regarde ce que j'ai trouvé ? Une petite bête errante."
  },
  AvgDialog_18710_Content_15 = {
    Text = "Cette nuit-là, une femme est venue vers moi."
  },
  AvgDialog_18710_Content_16 = {
    Text = "Lorsque elle s'est approchée de moi, j'ai capté un parfum agréable.\nC'était l'odeur des fleurs et de la brume."
  },
  AvgDialog_18710_Content_17 = {
    Text = "C'est le parfum d'un autre monde, aussi différent de mon royaume que le jour l'est de la nuit, jamais destiné à se croiser."
  },
  AvgDialog_18710_Content_18 = {
    Text = "Mais elle a quand même traversé la boue malodorante, a parcouru les ombres de la ville et m'a tendu la main."
  },
  AvgDialog_18710_Content_19 = {
    Text = "Elle a dit..."
  },
  AvgDialog_18710_Content_2 = {
    Text = "Je suis une bête... Je suis un patient.\n\nJe suis au-delà du rachat."
  },
  AvgDialog_18710_Content_20 = {
    Text = "Souhaitez-vous venir avec moi, petite bête ?"
  },
  AvgDialog_18710_Content_21 = {
    Text = "5:00, au nord de la ville de Reni"
  },
  AvgDialog_18710_Content_22 = {
    Text = "Cet endroit est... vraiment désolé."
  },
  AvgDialog_18710_Content_23 = {
    Text = "Il y a trois ans, un <Yellow:S-Class D-Rift> est apparu ici. L'eau, la végétation... tout l'écosystème a subi des dommages sévères."
  },
  AvgDialog_18710_Content_24 = {
    Text = "Heureusement, il y a eu peu de victimes et les résidents ont été évacués sous l'arrangement du Comité."
  },
  AvgDialog_18710_Content_25 = {
    Text = "Vous contemplez les murs désolés et les arbres pâles et fanés devant vous."
  },
  AvgDialog_18710_Content_26 = {
    Text = "Si ce n'avait été pour la Dissolution, cela aurait été un champ vert en pleine floraison avec des lilas. Quand le vent souffle, l'herbe ondule comme des vagues, ressemblant à un océan vert."
  },
  AvgDialog_18710_Content_27 = {
    Text = "Es-tu sûr que le Chasseur de Crânes est ici, Dame Jonquille ?"
  },
  AvgDialog_18710_Content_28 = {
    Text = "La seule réponse est le croassement rauque des corbeaux."
  },
  AvgDialog_18710_Content_29 = {
    Text = "Oh, la Dame Jonquille est portée disparue ?"
  },
  AvgDialog_18710_Content_3 = {
    Text = "Pendant la journée, je me cache dans les ombres de la ville, allongé sur le dos avec le ventre en l'air, dormant paisiblement."
  },
  AvgDialog_18710_Content_30 = {
    Text = "Eh bien, les conséquences de la confiance envers les autres."
  },
  AvgDialog_18710_Content_31 = {
    Text = "Ahem. Elle est toujours si imprévisible dans ses mouvements ; je m'y suis depuis longtemps habitué."
  },
  AvgDialog_18710_Content_32 = {
    Text = "Pas de soucis, je peux enquêter moi-même. Je trouverai certainement quelque chose ici..."
  },
  AvgDialog_18710_Content_33 = {
    Text = "<Big:Boom— !!>"
  },
  AvgDialog_18710_Content_34 = {
    Text = "Le tonnerre gronde dans les nuages bas, et les feuilles sèches bruissent dans le vent d'automne."
  },
  AvgDialog_18710_Content_35 = {
    Text = "C'est un signe de pluie."
  },
  AvgDialog_18710_Content_36 = {
    Text = "Pourquoi cela n'apparaît-il que les jours de pluie ?"
  },
  AvgDialog_18710_Content_37 = {
    Text = "Parce que quand il pleut, le sang et la pluie se mélangent et s'écoulent dans les égouts."
  },
  AvgDialog_18710_Content_38 = {
    Text = "Oui, ça s'écoule dans les égouts, les cercueils et les petites gouttières autour de vous..."
  },
  AvgDialog_18710_Content_39 = {
    Text = "<Red: Zzz... Krr...>"
  },
  AvgDialog_18710_Content_4 = {
    Text = "La nuit, je vagabonde dans les rues comme un fantôme, cherchant une tête après l'autre."
  },
  AvgDialog_18710_Content_40 = {
    Text = "Une nuit sombre et pluvieuse... Non, je suis encore en train de rêvasser."
  },
  AvgDialog_18710_Content_41 = {
    Text = "Vous avez vigoureusement secoué la tête, essayant d'éclaircir le chaos dans votre esprit."
  },
  AvgDialog_18710_Content_42 = {
    Text = "Le temps est compté. Vous devez agir rapidement."
  },
  AvgDialog_18710_Content_5 = {
    Text = "<Red: Crâne. Crâne. Crâne.>"
  },
  AvgDialog_18710_Content_6 = {
    Text = "<RedBig: Têtes.\n        Têtes.\n                Têtes.\n                        Têtes.\n                                Têtes.\n                                        Têtes...>"
  },
  AvgDialog_18710_Content_7 = {
    Text = "Mon esprit ne peut plus contempler la survie, l'amour et la dignité.\n\nIl est depuis longtemps rempli à ras bord de ces fantasmes insatiables."
  },
  AvgDialog_18710_Content_8 = {
    Text = "Je suis au-delà de la rédemption."
  },
  AvgDialog_18710_Content_9 = {
    Text = "Année 15@1, Ville de San Pedro"
  },
  AvgDialog_18711_Content_1 = {
    Text = "Ahhhh— !!"
  },
  AvgDialog_18711_Content_10 = {
    Text = "Elle a ignoré la boue sale et le sang au sol, s'est accroupie et a fixé la créature qui luttait devant elle."
  },
  AvgDialog_18711_Content_11 = {
    Text = "Arrête de chercher. Ils sont partis et ne reviendront jamais."
  },
  AvgDialog_18711_Content_12 = {
    Text = "Ce dont vous avez besoin, ce ne sont pas ces choses."
  },
  AvgDialog_18711_Content_13 = {
    Text = "Pas besoin...? Non, Head@1, donne-le-moi."
  },
  AvgDialog_18711_Content_14 = {Text = "新增"},
  AvgDialog_18711_Content_15 = {
    Text = [[
Savais-tu ? En fait... nous sommes pareils.
Je comprends ta douleur.]]
  },
  AvgDialog_18711_Content_16 = {
    Text = "Année 15@1, Ville de San Pedro"
  },
  AvgDialog_18711_Content_17 = {
    Text = "Viendras-tu avec moi, petite bête ? Tu as besoin d'aide."
  },
  AvgDialog_18711_Content_18 = {
    Text = "Année 15@1 Au cours de l'été de la première année, une femme m'a tendu la main."
  },
  AvgDialog_18711_Content_19 = {
    Text = "Peut-être que c'est son parfum agréable, ou peut-être qu'elle semble simplement douce."
  },
  AvgDialog_18711_Content_2 = {
    Text = "Une masse de chair s'effondre, déversant de la D-Slime et du mucus gris, révélant le corps frêle d'Harriet."
  },
  AvgDialog_18711_Content_20 = {
    Text = "En bref, je ne l'ai pas refusée."
  },
  AvgDialog_18711_Content_21 = {
    Text = "J'ai naïvement saisi sa main, et avec elle, mon destin futur."
  },
  AvgDialog_18711_Content_22 = {
    Text = "Tousse... Tousse..."
  },
  AvgDialog_18711_Content_23 = {
    Text = "Tu es en train de mourir, Jonquille."
  },
  AvgDialog_18711_Content_24 = {
    Text = "Enfant idiot... Après toutes ces années, tu n'as toujours pas appris à parler correctement."
  },
  AvgDialog_18711_Content_25 = {
    Text = "Ne pleure pas... *tousse*..."
  },
  AvgDialog_18711_Content_26 = {
    Text = "<Shake:Je... je n'ai pas...>"
  },
  AvgDialog_18711_Content_27 = {
    Text = "Prenez ma tête. Je vous confie mon identité, mon apparence, et ce petit magasin."
  },
  AvgDialog_18711_Content_28 = {Text = "?!"},
  AvgDialog_18711_Content_29 = {
    Text = "Je sais, toussotements... tu as toujours rêvé de parcourir le monde comme un humain ordinaire."
  },
  AvgDialog_18711_Content_3 = {
    Text = "Des crânes grisâtres surgissaient, pour disparaître en un clin d'œil."
  },
  AvgDialog_18711_Content_30 = {
    Text = "Vous vous cachez dans le coin, observant comment je parle et je marche. Quand je suis loin, vous portez secrètement mes vêtements et faites même semblant d'être moi pour vous faire des amis..."
  },
  AvgDialog_18711_Content_31 = {
    Text = "J'ai toujours su."
  },
  AvgDialog_18711_Content_32 = {
    Text = "Désolé, Jonquille, je ne voulais pas..."
  },
  AvgDialog_18711_Content_33 = {
    Text = "Maintenant, je réaliserai ton souhait, hum... mais tu dois me promettre..."
  },
  AvgDialog_18711_Content_34 = {
    Text = "À l'avenir, ne coupe pas sans discernement les têtes des innocents. Si tu rencontres quelqu'un comme toi, tu dois l'aider."
  },
  AvgDialog_18711_Content_35 = {
    Text = "Juste comme je t'aide maintenant."
  },
  AvgDialog_18711_Content_36 = {
    Text = "<Shake:Sauve-moi, sauve-moi...>"
  },
  AvgDialog_18711_Content_37 = {
    Text = "Harriet pousse un cri bestial et tend la main tremblante vers Lady Jonquille."
  },
  AvgDialog_18711_Content_38 = {Text = "新增"},
  AvgDialog_18711_Content_39 = {
    Text = "À l'époque... quand tu as vu ton mari au cimetière, tu as dû te sentir complètement désespérée, n'est-ce pas ?"
  },
  AvgDialog_18711_Content_4 = {
    Text = "Tête@1 Non..."
  },
  AvgDialog_18711_Content_40 = {
    Text = "Freeman... Hein.@2..."
  },
  AvgDialog_18711_Content_41 = {
    Text = "Nous portons la même malédiction, mais j'ai beaucoup plus de chance que vous."
  },
  AvgDialog_18711_Content_42 = {
    Text = "Lorsque je ne savais pas encore faire la différence entre le bien et le mal, c'était cette dame qui m'a tendu la main."
  },
  AvgDialog_18711_Content_43 = {
    Text = "Jonquille s'agenouilla devant Mme Harriet, tenant doucement sa main marquée et couverte de D-Slime."
  },
  AvgDialog_18711_Content_44 = {
    Text = "J'ai appris à parler et à marcher comme elle, me façonnant à son image."
  },
  AvgDialog_18711_Content_45 = {
    Text = "Attention, Dame Jonquille ! Les mains d'Harriet sont couvertes de D-boue—"
  },
  AvgDialog_18711_Content_46 = {
    Text = "Chut... J'ai encore quelque chose à lui dire."
  },
  AvgDialog_18711_Content_47 = {
    Text = "Jonquille continua de regarder Harriet. Une connexion secrète coulait entre elles, les isolant de toutes distractions."
  },
  AvgDialog_18711_Content_48 = {
    Text = "Maintenant, je peux enfin tendre la main aux autres, tout comme elle l'a fait... Mais il est trop tard."
  },
  AvgDialog_18711_Content_49 = {
    Text = "Une fumée violette pâle s'élève progressivement, dérivant lentement dans la pièce sombre."
  },
  AvgDialog_18711_Content_5 = {
    Text = "Harriet, sans tête et inquiète, se tordait alors que les veines de son cou pulsaient rapidement, émettant un léger bourdonnement."
  },
  AvgDialog_18711_Content_50 = {
    Text = "Vous sentez à nouveau cette odeur florale familière, mêlée à l'humidité de la brume de minuit, diluant l'odeur de sang lourde de la pièce."
  },
  AvgDialog_18711_Content_51 = {
    Text = "Jonquille plaça doucement sa main à côté de Mme Harriet."
  },
  AvgDialog_18711_Content_52 = {
    Text = "Rassurez-vous, Dame Harriet. Vous ne ressentirez aucune douleur."
  },
  AvgDialog_18711_Content_53 = {
    Text = "Une déchirure s'ouvre rapidement de sa paume, englobant lentement Harriet..."
  },
  AvgDialog_18711_Content_54 = {
    Text = "<Shake:...>"
  },
  AvgDialog_18711_Content_55 = {
    Text = "Dis à mon mari@2 d'arrêter de boire."
  },
  AvgDialog_18711_Content_56 = {
    Text = "Il y a plus..."
  },
  AvgDialog_18711_Content_57 = {
    Text = "La gorge exposée d'Harriet tremble légèrement, mais finit par tomber silencieusement comme une feuille flétrie."
  },
  AvgDialog_18711_Content_58 = {
    Text = "Elle relâcha la main de Jonquille et tomba silencieusement dans un gouffre dimensionnel insondable."
  },
  AvgDialog_18711_Content_59 = {
    Text = "<Change> Adieu, adieu..."
  },
  AvgDialog_18711_Content_6 = {
    Text = "Donnez-moi@2 têtes, donnez-moi..."
  },
  AvgDialog_18711_Content_60 = {
    Text = "Enfin... est-ce fini ? Où l'as-tu emmenée, Dame Jonquille ?"
  },
  AvgDialog_18711_Content_61 = {
    Text = "L'Océan Primordial. Elle aura beaucoup de temps pour se souvenir... ou oublier tout ce qui s'est passé."
  },
  AvgDialog_18711_Content_62 = {
    Text = "Dame Harriet..."
  },
  AvgDialog_18711_Content_63 = {
    Text = "Avant que vous ne puissiez rassembler vos pensées éparpillées, de faibles bruits de pas résonnent à l'extérieur de la maison."
  },
  AvgDialog_18711_Content_64 = {
    Text = "Qui est là ? Suivons et regardons."
  },
  AvgDialog_18711_Content_65 = {
    Text = "Oui, c'est moi... hic."
  },
  AvgDialog_18711_Content_66 = {
    Text = "Ça fait longtemps, petit détective ! Te souviens-tu de moi, le gardien de tombes Old Freeman ?"
  },
  AvgDialog_18711_Content_67 = {
    Text = "Vieux Freeman, tenant une bouteille de brandy, continuait à roter avec un sourire maladroit sur le visage."
  },
  AvgDialog_18711_Content_68 = {
    Text = "Vieux Freeman ?! Que fais-tu ici... As-tu tout entendu ?"
  },
  AvgDialog_18711_Content_69 = {Text = "Je..."},
  AvgDialog_18711_Content_7 = {
    Text = "Elle se traînait anxieusement au sol, ses bras osseux s'agitant. Comme une bête acculée, elle laissa échapper des gémissements désespérés de sa gorge."
  },
  AvgDialog_18711_Content_70 = {
    Text = "Je ne sais pas ce qui s'est passé non plus. J'ai dormi comme une souche après avoir bu."
  },
  AvgDialog_18711_Content_71 = {
    Text = "Je ne me souviens pas de ce qui s'est passé au milieu, mais d'une manière ou d'une autre, je me suis retrouvé ici dans un état d'égarement."
  },
  AvgDialog_18711_Content_72 = {
    Text = "Puis j'ai entendu un bruit à l'intérieur... Ne vous inquiétez pas, je n'ai pas jeté un seul coup d'œil !"
  },
  AvgDialog_18711_Content_73 = {
    Text = "Vieux Freeman se pencha soudainement et vous fit un clin d'œil mystérieux.\nVous n'avez pas pu esquiver à temps et avez reçu une forte odeur piquante de fumée et d'alcool."
  },
  AvgDialog_18711_Content_74 = {
    Text = "Vous avez tué ce Chasseur de Crâne, n'est-ce pas ?"
  },
  AvgDialog_18711_Content_75 = {
    Text = "Pas génial, mais suffisamment proche. Personne ne dérangera ton sommeil à partir de maintenant."
  },
  AvgDialog_18711_Content_76 = {
    Text = "Vous pincez votre nez, faites trois pas en arrière et hochez la tête de manière désinvolte."
  },
  AvgDialog_18711_Content_77 = {Text = "Oh..."},
  AvgDialog_18711_Content_78 = {
    Text = "Vieux Freeman se frotta les cheveux en désordre, une lueur de confusion apparut dans ses yeux."
  },
  AvgDialog_18711_Content_79 = {
    Text = "Assez bon, assez bon..."
  },
  AvgDialog_18711_Content_8 = {Text = "新增"},
  AvgDialog_18711_Content_80 = {
    Text = "M. Freeman. À partir de maintenant... plus d'alcool."
  },
  AvgDialog_18711_Content_81 = {
    Text = "Arrêter de boire ? Non, non, non... Je préférais mourir."
  },
  AvgDialog_18711_Content_82 = {
    Text = "C'est une demande d'une amie. Elle est allée très, très loin... mais elle se soucie toujours de vous."
  },
  AvgDialog_18711_Content_83 = {
    Text = "Amis ? Heh, ne te fais pas d'illusions. Le vieux Freeman n'a pas d'amis..."
  },
  AvgDialog_18711_Content_84 = {
    Text = "Il vous fit un signe de la main de manière désinvolte, murmurant en s'éloignant en titubant."
  },
  AvgDialog_18711_Content_85 = {
    Text = [[
Il a l'air si abattu. Quel dommage...
Il ne saura jamais pourquoi il se sent ainsi.]]
  },
  AvgDialog_18711_Content_86 = {
    Text = "C'est comme s'il ne comprenait pas pourquoi il était ici."
  },
  AvgDialog_18711_Content_87 = {
    Text = "Cela doit être ce que Mère Harriet espérait."
  },
  AvgDialog_18711_Content_88 = {
    Text = "Ne lui dis rien... Il peut continuer à boire, chanter, et dériver ainsi dans la vie."
  },
  AvgDialog_18711_Content_89 = {
    Text = "D'une certaine manière, c'est aussi une sorte de chance. La vie d'un humain est très courte..."
  },
  AvgDialog_18711_Content_9 = {
    Text = "Jonquille laissa échapper un doux soupir, ses yeux brillant d'une tristesse inexprimée."
  },
  AvgDialog_18711_Content_90 = {
    Text = "Vous regardez le vieux Freeman s'en aller."
  },
  AvgDialog_18711_Content_91 = {
    Text = "Une silhouette courbée tremble dans le vent austère, devenant de plus en plus petite, de plus en plus loin..."
  },
  AvgDialog_18711_Content_92 = {
    Text = "Jusqu'à ce qu'il soit complètement englouti par l'horizon lointain."
  },
  AvgDialog_18711_Content_93 = {
    Text = "Alors tu vois un faible rayon de l'aube percer à travers la brume, illuminant progressivement le ciel."
  },
  AvgDialog_18711_Content_94 = {
    Text = "La pluie s'est arrêtée... Jonquille."
  },
  AvgDialog_18712_Content_1 = {
    Text = "Hymne d'ombre"
  },
  AvgDialog_18712_Content_10 = {
    Text = "Donnez-le-moi... <Big:Retournez-le-moi> !"
  },
  AvgDialog_18712_Content_11 = {
    Text = "Les filaments noirs s'étendent continuellement de son cou, absorbant avidement les têtes tombées dans son corps."
  },
  AvgDialog_18712_Content_12 = {
    Text = "Avec chaque crâne qu'il dévore, sa taille augmente encore."
  },
  AvgDialog_18712_Content_13 = {
    Text = "La dernière chose qui se tient devant vous est un énorme tas de chair empilée."
  },
  AvgDialog_18712_Content_14 = {
    Text = "<Bold:—!!!>"
  },
  AvgDialog_18712_Content_15 = {
    Text = "Ces têtes... Je les ai déjà vues."
  },
  AvgDialog_18712_Content_16 = {
    Text = "Vous en avez vu certains dans les dossiers que la police vous a remis, dans ces photos froides de victimes alignées."
  },
  AvgDialog_18712_Content_17 = {
    Text = "Vous les avez vus."
  },
  AvgDialog_18712_Content_18 = {
    Text = "Maintenant tu comprends, il n'y avait jamais eu d'organisation de Chasseurs de Crâne."
  },
  AvgDialog_18712_Content_19 = {
    Text = "<Yellow:Du début à la fin, le Chasseur de Crâne a toujours été seul.>"
  },
  AvgDialog_18712_Content_2 = {
    Text = "Dame Daffodil... ?!"
  },
  AvgDialog_18712_Content_20 = {
    Text = "<RedShake:Pas assez...>"
  },
  AvgDialog_18712_Content_21 = {
    Text = "<RedShake:Pas assez... pas assez...>"
  },
  AvgDialog_18712_Content_22 = {
    Text = "Un corps enflé encastré avec d'innombrables têtes exprimant la douleur et gémissant, montant et descendant avec la douce graisse..."
  },
  AvgDialog_18712_Content_23 = {
    Text = "Des ondes spirituelles si familières... Pourrait-il s'agir de la Millénaire Mirage ?!"
  },
  AvgDialog_18712_Content_24 = {
    Text = "C'est une puissance qui provient de la même source que le Mille Mirage, c'est pourquoi je peux sentir sa position."
  },
  AvgDialog_18712_Content_25 = {
    Text = "Maintenant, c'est complètement hors de contrôle et continue de croître.\nNous devons agir rapidement."
  },
  AvgDialog_18712_Content_26 = {Text = "Alors..."},
  AvgDialog_18712_Content_27 = {
    Text = "Daffodil s'est soudain penchée, saisissant la Clé en Argent sur votre poitrine."
  },
  AvgDialog_18712_Content_28 = {
    Text = "Souhaitez-vous faire équipe avec moi, %player% ?"
  },
  AvgDialog_18712_Content_29 = {
    Text = "Oh, tu veux te Lier avec moi ?"
  },
  AvgDialog_18712_Content_3 = {
    Text = "Désolé... Je vous ai délibérément laissé ici pour l'attirer. Vous devez me blâmer dans votre cœur, n'est-ce pas ?"
  },
  AvgDialog_18712_Content_30 = {
    Text = "Après tout ce temps à travailler ensemble, je pensais que nous aurions une certaine compréhension maintenant"
  },
  AvgDialog_18712_Content_31 = {
    Text = "Ou... n'êtes-vous pas sûr de pouvoir me gérer ?"
  },
  AvgDialog_18712_Content_32 = {
    Text = "Heh... Allons-nous essayer ?"
  },
  AvgDialog_18712_Content_33 = {
    Text = "Vous fermez les yeux et vous concentrez, incitant la Clé Argent sur votre poitrine."
  },
  AvgDialog_18712_Content_34 = {
    Text = "Bientôt, la clé argentée commença à émettre une vibration continue et faible, et le froid éclat blanc engloutit rapidement tout le laboratoire sombre."
  },
  AvgDialog_18712_Content_35 = {
    Text = "Vous avez l'impression d'être dans une immense mer de temps."
  },
  AvgDialog_18712_Content_36 = {
    Text = "Une énergie étrange monte dans ta poitrine, un torrent traversant les dimensions."
  },
  AvgDialog_18712_Content_37 = {
    Text = "À travers la vaste mer du temps, la Jonquille vous regarde silencieusement.\nEn ce moment, une expression subtile et inconnue apparaît sur son visage."
  },
  AvgDialog_18712_Content_38 = {
    Text = "C'est une confiance absolue et indiscutable, perfectionnée au cours de centaines d'années à travers d'innombrables confrontations et batailles."
  },
  AvgDialog_18712_Content_39 = {
    Text = "Partons, %player%. Je suis prêt."
  },
  AvgDialog_18712_Content_4 = {Text = "新增"},
  AvgDialog_18712_Content_5 = {
    Text = "Nous règlerons cela une fois sortis."
  },
  AvgDialog_18712_Content_6 = {
    Text = "<Shake:Ma tête... Rends-la moi...>"
  },
  AvgDialog_18712_Content_7 = {
    Text = "\"Harriet\" avança chancelante de deux pas, atteignant vainement au-dessus de son cou."
  },
  AvgDialog_18712_Content_8 = {
    Text = "Un coup, deux coups..."
  },
  AvgDialog_18712_Content_9 = {
    Text = "Réaliser que sa tête était déjà partie, elle a poussé une série de cris perçants."
  },
  AvgDialog_18713_Content_1 = {Text = "Ça pleut."},
  AvgDialog_18713_Content_10 = {
    Text = "Vous essuyez rapidement la pluie de votre visage et clignez des yeux, seulement pour réaliser que quelqu'un vous parle réellement."
  },
  AvgDialog_18713_Content_11 = {
    Text = "Je pensais que plus personne ne vivait ici."
  },
  AvgDialog_18713_Content_12 = {
    Text = "La plupart des gens se sont éloignés."
  },
  AvgDialog_18713_Content_13 = {
    Text = "Ceux qui étaient malades ou âgés ont choisi de rester, tandis que certains sont sortis puis revenus..."
  },
  AvgDialog_18713_Content_14 = {
    Text = "Tout le monde ne peut pas s'adapter à la vie à l'extérieur."
  },
  AvgDialog_18713_Content_15 = {
    Text = "Je vois. Mais je n'ai vu personne à l'instant."
  },
  AvgDialog_18713_Content_16 = {
    Text = "...Ils détestent traiter avec des étrangers."
  },
  AvgDialog_18713_Content_17 = {
    Text = "Vous regardez autour de vous les maisons rares et en ruine."
  },
  AvgDialog_18713_Content_18 = {
    Text = "À travers les fenêtres d'un noir d'encre, des regards silencieux peuvent être faiblement vus, débordant de prudence et d'hostilité."
  },
  AvgDialog_18713_Content_19 = {
    Text = "Bonjour, madame. Puis-je vous demander—"
  },
  AvgDialog_18713_Content_2 = {
    Text = "Vous marchez seul sous la pluie, le froid et l'eau mouillant vos vêtements et adhérant à votre peau."
  },
  AvgDialog_18713_Content_20 = {
    Text = "Avez-vous vu quelque chose d'étrange ?"
  },
  AvgDialog_18713_Content_21 = {
    Text = "Choses étranges... ?"
  },
  AvgDialog_18713_Content_22 = {
    Text = "Euh... que ce soit une personne ou une bête, elle se déplace extrêmement vite."
  },
  AvgDialog_18713_Content_23 = {
    Text = "La femme secoua la tête."
  },
  AvgDialog_18713_Content_24 = {
    Text = "Cela fait longtemps que personne n'est venu ici ; même les vautours refusent de s'en approcher."
  },
  AvgDialog_18713_Content_25 = {
    Text = "Avez-vous vu la Jonquille ?"
  },
  AvgDialog_18713_Content_26 = {
    Text = "Avez-vous vu une belle dame en robe longue violette ?"
  },
  AvgDialog_18713_Content_27 = {
    Text = "La femme secoua la tête."
  },
  AvgDialog_18713_Content_28 = {
    Text = "Cela fait longtemps que personne n'est venu ici ; même les vautours refusent de s'en approcher."
  },
  AvgDialog_18713_Content_29 = {
    Text = "<Big:Boom—>"
  },
  AvgDialog_18713_Content_3 = {
    Text = "Vous traversez une maison abandonnée après l'autre, passant devant une tombe après l'autre."
  },
  AvgDialog_18713_Content_30 = {
    Text = "La pluie tombe de plus en plus fort, transformant tout en gris."
  },
  AvgDialog_18713_Content_31 = {
    Text = "La silhouette de la femme commence à s'estomper et à perdre de son objectif, et même sa voix devient de plus en plus faible..."
  },
  AvgDialog_18713_Content_32 = {
    Text = "Entrez, {Male=sir,Female=miss}. Vous allez attraper froid sous cette pluie battante..."
  },
  AvgDialog_18713_Content_33 = {Text = "新增"},
  AvgDialog_18713_Content_34 = {
    Text = "Avec plaisir."
  },
  AvgDialog_18713_Content_4 = {
    Text = "Où qu'ils aillent, il n'y a que des cicatrices et la désolation."
  },
  AvgDialog_18713_Content_5 = {
    Text = "Il n'y a que de la pluie. Une pluie froide et incessante t'accompagne tout le long."
  },
  AvgDialog_18713_Content_6 = {Text = "Gardien..."},
  AvgDialog_18713_Content_7 = {
    Text = "Une vieille femme se tient devant la cabane, vous faisant signe."
  },
  AvgDialog_18713_Content_8 = {
    Text = "Elle portait une robe terne, son visage dissimulé dans la pluie grise, se fondant parfaitement avec la maison en ruine derrière elle."
  },
  AvgDialog_18713_Content_9 = {
    Text = "{Male=Sir,Female=Miss}, vous avez l'air d'avoir très froid... Voulez-vous entrer vous asseoir un moment ?"
  },
  AvgDialog_18714_Content_1 = {
    Text = "Fracture de tempête"
  },
  AvgDialog_18714_Content_10 = {
    Text = "Une seule personne ?!"
  },
  AvgDialog_18714_Content_11 = {
    Text = "Oh là là, tu as l'air terrible. As-tu besoin d'aide ?"
  },
  AvgDialog_18714_Content_12 = {
    Text = "Vous vous reculez. J'ai quelque chose à te demander."
  },
  AvgDialog_18714_Content_13 = {
    Text = "C'est vraiment blessant. Quoi, je dégage une odeur désagréable ?"
  },
  AvgDialog_18714_Content_14 = {
    Text = "Je ne sais pas... Peut-être l'odeur des morts ?"
  },
  AvgDialog_18714_Content_15 = {
    Text = "Beren Stock, Dwight Williams... Ces noms vous semblent-ils familiers ?"
  },
  AvgDialog_18714_Content_16 = {Text = "新增"},
  AvgDialog_18714_Content_17 = {
    Text = "Je vois, tu soupçonnes que je suis le Chasseur de Crânes."
  },
  AvgDialog_18714_Content_18 = {
    Text = "Et tu connais clairement les noms des victimes du Chasseur de Crânes."
  },
  AvgDialog_18714_Content_19 = {Text = "新增"},
  AvgDialog_18714_Content_2 = {
    Text = "Daffodil s'approche de vous avec une élégance décontractée, comme si elle était ici en vacances."
  },
  AvgDialog_18714_Content_20 = {
    Text = "Je pensais qu'en passant du temps avec Lai, nous pourrions établir un peu de confiance."
  },
  AvgDialog_18714_Content_21 = {
    Text = "Le Chasseur de Crânes m'a volé un <Yellow:crâne précieux>, donc je fais juste une petite enquête. C'est aussi simple que ça."
  },
  AvgDialog_18714_Content_22 = {
    Text = "À qui cette précieuse tête... pourrait-elle être ?"
  },
  AvgDialog_18714_Content_23 = {Text = "新增"},
  AvgDialog_18714_Content_24 = {
    Text = "Daffodil vous sourit. Elle affiche toujours ce sourire quand elle ne veut pas répondre aux questions des autres."
  },
  AvgDialog_18714_Content_25 = {
    Text = "Si je me souviens bien, tu as toujours eu l'habitude de collectionner des têtes. Renny est à moins de 15 miles en ligne droite de Rai, ce qui rend l'aller-retour assez pratique."
  },
  AvgDialog_18714_Content_26 = {
    Text = "Désolé, je ne collecte que des têtes, je ne les produis pas."
  },
  AvgDialog_18714_Content_27 = {
    Text = "Il y a une subtile différence entre les deux... Je suis sûre que vous pouvez comprendre, notre astucieux Gardien?"
  },
  AvgDialog_18714_Content_28 = {
    Text = "Bien sûr, je comprends.\nAlors, où étais-tu et que faisais-tu à 8h15 hier soir ?"
  },
  AvgDialog_18714_Content_29 = {
    Text = "Laisse-moi réfléchir... Le magasin a reçu un nouveau lot de sels de bain, alors je les ai essayés dans la baignoire."
  },
  AvgDialog_18714_Content_3 = {
    Text = "C'est toi...?"
  },
  AvgDialog_18714_Content_30 = {
    Text = "Eh bien, tu veux entendre les détails de mon procès ?"
  },
  AvgDialog_18714_Content_31 = {
    Text = "Est-ce que c'est ça ? Mais quand je vous ai vu hier soir, vous étiez debout seul sous le réverbère, tenant une tête humaine."
  },
  AvgDialog_18714_Content_32 = {
    Text = "Cela ne ressemble absolument pas à des sels de bain."
  },
  AvgDialog_18714_Content_33 = {Text = "新增"},
  AvgDialog_18714_Content_34 = {
    Text = ": Tu dis... que tu as vu quelqu'un qui me ressemble exactement hier soir ?"
  },
  AvgDialog_18714_Content_35 = {
    Text = "Vous vous rappelez avoir vu la Jonquille la nuit dernière."
  },
  AvgDialog_18714_Content_36 = {
    Text = "Sans aucun doute, leurs apparences sont presque identiques, mais leur comportement et leur aura sont très différents."
  },
  AvgDialog_18714_Content_37 = {
    Text = "Ou plutôt, j'ai vu <Yellow:toi>, pas quelqu'un qui te ressemble exactement."
  },
  AvgDialog_18714_Content_38 = {
    Text = "Tous les éléments défavorables pointent maintenant vers toi, et j'ai toutes les raisons de te suspecter."
  },
  AvgDialog_18714_Content_39 = {
    Text = "Hmm, ton doute est en effet bien fondé."
  },
  AvgDialog_18714_Content_4 = {
    Text = "Oh là là, quelqu'un semble ne pas vouloir me voir ?"
  },
  AvgDialog_18714_Content_40 = {Text = "新增"},
  AvgDialog_18714_Content_41 = {
    Text = "Tu n'as rien à expliquer ?"
  },
  AvgDialog_18714_Content_42 = {
    Text = "Jonquille te regarda avec surprise, comme si tu avais posé une question ridicule."
  },
  AvgDialog_18714_Content_43 = {
    Text = "Expliquer ? Désolé, je n'ai besoin d'expliquer quoi que ce soit à personne."
  },
  AvgDialog_18714_Content_44 = {
    Text = "Elle s'avance gracieusement vers vous."
  },
  AvgDialog_18714_Content_45 = {
    Text = "La large jupe froisse les feuilles mortes, tandis que la fumée violette s'enroule comme des tendrils autour."
  },
  AvgDialog_18714_Content_46 = {
    Text = "Au moment suivant, elle disparaît dans les airs devant vos yeux."
  },
  AvgDialog_18714_Content_47 = {
    Text = "Les nuages bas bloquent complètement la lumière du soleil, te faisant sentir comme si tu étais dans un rêve gris, avec les murmures de Jonquille restant dans tes oreilles—"
  },
  AvgDialog_18714_Content_48 = {
    Text = "Puisque tu penses que je suis le \"Chasseur de Crânes\"... quelle est la suite ? Que prévois-tu de me faire ?"
  },
  AvgDialog_18714_Content_49 = {
    Text = "Ou plutôt... que peux-tu me faire ?"
  },
  AvgDialog_18714_Content_5 = {
    Text = "Le vent automnal désolé souffle derrière toi. Tu te retournes, mais il n'y a rien devant toi ; le vieux Freeman a disparu depuis longtemps."
  },
  AvgDialog_18714_Content_6 = {
    Text = "En repensant à tout ce qui vient de se passer, c'était comme un cauchemar."
  },
  AvgDialog_18714_Content_7 = {
    Text = "Monsieur Freeman... ?"
  },
  AvgDialog_18714_Content_8 = {
    Text = "Hmm, tu as amené un compagnon ? Est-ce cette fille qui a toujours l'air si sérieuse ?"
  },
  AvgDialog_18714_Content_9 = {
    Text = "Juste maintenant, tu étais debout ici seul, complètement immobile, comme possédé."
  },
  AvgDialog_18715_Content_1 = {
    Text = "Je concède, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_18715_Content_10 = {
    Text = "Vous plongez dans une mer d'essence primordiale grise."
  },
  AvgDialog_18715_Content_11 = {
    Text = "La lumière du jour pique tes yeux, révélant une vaste étendue d'océan gris sans fin."
  },
  AvgDialog_18715_Content_12 = {
    Text = "Les vagues grises en furie scintillent d'une lumière brillante, parsemées d'innombrables taches noires."
  },
  AvgDialog_18715_Content_13 = {
    Text = "Alors que votre vision s'ajuste progressivement, vous réalisez que ce n'est pas une tache noire, mais juste un crâne."
  },
  AvgDialog_18715_Content_14 = {
    Text = "Des têtes innombrables sont immergées dans la mer grise, montant et descendant avec les vagues. Elles crient et se lamentent, se noyant dans une immense tristesse et peur."
  },
  AvgDialog_18715_Content_15 = {
    Text = "<Change>Des cristaux, des cristaux..."
  },
  AvgDialog_18715_Content_16 = {
    Text = "<Shake:Ne touche pas à ce carnet, ne le touche pas...>"
  },
  AvgDialog_18715_Content_17 = {
    Text = "<Shake:San Pedro, laisse-moi revenir, laisse-moi revenir...>"
  },
  AvgDialog_18715_Content_18 = {
    Text = "Des voix innombrables hurlent à vos oreilles, vous forçant à les couvrir, comme si des milliers d'aiguilles perçaient votre esprit."
  },
  AvgDialog_18715_Content_19 = {
    Text = "Hmm... <Big: Aaaah... !!>"
  },
  AvgDialog_18715_Content_2 = {
    Text = "Puisque je ne peux pas supporter de vous voir blessé, continuer ce combat ne serait qu'une perte de temps pour tout le monde."
  },
  AvgDialog_18715_Content_20 = {
    Text = "Du sang chaud s'écoule de vos oreilles et de vos narines, créant de massives vagues au moment où il touche l'eau."
  },
  AvgDialog_18715_Content_21 = {
    Text = "La marée se soulève avec colère et peur, portant d'innombrables têtes flottant sur ses vagues, se précipitant vers toi."
  },
  AvgDialog_18715_Content_22 = {
    Text = "<Change>Non, non..."
  },
  AvgDialog_18715_Content_23 = {
    Text = "<Shake:Intrus... Intrus !!>"
  },
  AvgDialog_18715_Content_24 = {
    Text = "Vous n'avez pas de sortie. Fermez simplement les yeux."
  },
  AvgDialog_18715_Content_25 = {Text = "Hmm...!"},
  AvgDialog_18715_Content_26 = {
    Text = "Tousse... Tousse..."
  },
  AvgDialog_18715_Content_27 = {
    Text = "Jonquille se tint le front et te regarda avec un froncement de sourcils."
  },
  AvgDialog_18715_Content_28 = {
    Text = "Déjà parti...? Je pensais pouvoir vous garder piégé au moins une journée entière."
  },
  AvgDialog_18715_Content_29 = {
    Text = "On dirait que nous sommes destinés à être liés ensemble, n'est-ce pas ?"
  },
  AvgDialog_18715_Content_3 = {
    Text = "Étant donné les différences irréconciliables entre nous, je te suggère de cesser de me déranger."
  },
  AvgDialog_18715_Content_30 = {
    Text = "Tête... ça fait mal..."
  },
  AvgDialog_18715_Content_31 = {
    Text = "Qu'était-ce que ça vient juste d'être...? Quel genre de chose était-ce...?"
  },
  AvgDialog_18715_Content_32 = {
    Text = "C'est mon espace ultra-dimensionnel. Je l'ai nommé <Yellow:Mirage des Mille>.\nQue penses-tu ? N'est-ce pas fascinant ?"
  },
  AvgDialog_18715_Content_33 = {Text = "新增"},
  AvgDialog_18715_Content_34 = {
    Text = "%player%, tu as un saignement de nez. Attends, même tes oreilles saignent..."
  },
  AvgDialog_18715_Content_35 = {
    Text = "<Shake:Je vais bien... Reste loin...>"
  },
  AvgDialog_18715_Content_36 = {
    Text = "Ce n'est pas sage de faire le dur maintenant ; tu peux à peine te tenir debout."
  },
  AvgDialog_18715_Content_37 = {
    Text = "*Tousse, tousse*... ne vous approchez pas..."
  },
  AvgDialog_18715_Content_38 = {
    Text = "Votre vision devient noire, et vous vous effondrez lourdement au sol."
  },
  AvgDialog_18715_Content_39 = {
    Text = "Dans l'obscurité, vous semblez entendre une voix familière."
  },
  AvgDialog_18715_Content_4 = {
    Text = "Daffodil, avec une expression froide, a rapidement dessiné une série de runes violettes lumineuses dans l'air."
  },
  AvgDialog_18715_Content_40 = {
    Text = "Doux, indifférent, enveloppé d'un bourdonnement électrique légèrement agressif, apparaissant éloigné et flou."
  },
  AvgDialog_18715_Content_41 = {
    Text = "%player%, peux-tu m'entendre maintenant...<Red:Direction d'enquête incorrecte>..."
  },
  AvgDialog_18715_Content_42 = {
    Text = "Le Chasseur de Crânes frappe à nouveau...\nTrois victimes, toutes décapitées..."
  },
  AvgDialog_18715_Content_43 = {
    Text = "Juste il y a un instant..."
  },
  AvgDialog_18715_Content_5 = {
    Text = "<Change>Mille Mirage, active."
  },
  AvgDialog_18715_Content_6 = {
    Text = "Le monde devant vos yeux se transforme soudainement en reflets fragmentés dans l'eau, scintillant doucement devant vous."
  },
  AvgDialog_18715_Content_7 = {
    Text = "Vous vous étendez instinctivement, mais êtes tiré dans un profond vortex au moment où vous touchez les Fragments d'Ombre."
  },
  AvgDialog_18715_Content_8 = {Text = "Aaaah...!!"},
  AvgDialog_18715_Content_9 = {Text = "C'est..."},
  AvgDialog_18716_Content_1 = {Text = "Aaahh—!!"},
  AvgDialog_18716_Content_10 = {
    Text = "Les fils se sont soudainement contractés, brisant la porte de la chambre alors que d'innombrables têtes sortaient."
  },
  AvgDialog_18716_Content_11 = {
    Text = "Lorsque vous reprenez vos esprits, une tête quelque peu familière est déjà attachée au cou vide de Harriet."
  },
  AvgDialog_18716_Content_12 = {
    Text = "Cette tête... Ce visage..."
  },
  AvgDialog_18716_Content_13 = {
    Text = "Beren Stock, la précédente victime... Que se passe-t-il ?!"
  },
  AvgDialog_18716_Content_14 = {
    Text = "Le crâne blafard émet un bruit de craquement rigide et finit par ouvrir ses yeux flous."
  },
  AvgDialog_18716_Content_15 = {
    Text = "La \"Harriet\" réincarnée sourit et se précipite vers vous à une vitesse incroyable."
  },
  AvgDialog_18716_Content_16 = {
    Text = "Aaaahhh—!!"
  },
  AvgDialog_18716_Content_18 = {
    Text = "La froide lame tranche impitoyablement à travers l'obscurité."
  },
  AvgDialog_18716_Content_19 = {
    Text = "Au moment suivant, la tête de \"Harriet\" s'envole gracieusement et roule à côté de sa large jupe."
  },
  AvgDialog_18716_Content_2 = {
    Text = "Harriet s'est effondrée au sol, émettant un cri perçant venant du fond de sa gorge."
  },
  AvgDialog_18716_Content_20 = {
    Text = "Ouf... Il semble que je ne sois pas trop en retard."
  },
  AvgDialog_18716_Content_21 = {
    Text = "Tu as l'air en forme, %player%."
  },
  AvgDialog_18716_Content_3 = {
    Text = "Vous vous avancez et la saisissez par le col."
  },
  AvgDialog_18716_Content_4 = {
    Text = "Parle, qui sont tes complices et où sont-ils ? Old Freeman en fait-il partie ?"
  },
  AvgDialog_18716_Content_5 = {
    Text = "Freeman...? Hé... Hehehe..."
  },
  AvgDialog_18716_Content_6 = {
    Text = "Son visage se tordait violemment, avec d'innombrables pustules enflant sous sa peau fine, sur le point d'éclater."
  },
  AvgDialog_18716_Content_7 = {
    Text = "Zzzzap—!!"
  },
  AvgDialog_18716_Content_8 = {
    Text = "La tête d'Harriet a été réduite en pulpe chaude."
  },
  AvgDialog_18716_Content_9 = {
    Text = "Son cou se tordait continuellement, avec de la D-boue mélangée à du sang formant de fins fils qui s'étendaient jusqu'au plafond, aux murs et au sol..."
  },
  AvgDialog_18717_Content_1 = {
    Text = "Muse féline"
  },
  AvgDialog_18717_Content_10 = {
    Text = "C'était une expérience plutôt intéressante."
  },
  AvgDialog_18717_Content_11 = {
    Text = "Les souvenirs initialement tristes, réinterprétés à travers des images, ont acquis de manière inattendue un charme comique."
  },
  AvgDialog_18717_Content_12 = {
    Text = "J'ai entendu dire que vous avez ensuite formé un club de cinéma appelé <Yellow:\"Société de Poésie Philin\"> ?"
  },
  AvgDialog_18717_Content_13 = {
    Text = "Oui... Parfois, j'aide à écrire des scénarios, bien que j'ai toujours été un terrible dramaturge."
  },
  AvgDialog_18717_Content_14 = {
    Text = "C'était la Dame Jonquille qui m'a aidé à avancer en dépit de ses véritables intentions."
  },
  AvgDialog_18717_Content_15 = {
    Text = "J'ai toujours été reconnaissant envers Dame Jonquille."
  },
  AvgDialog_18717_Content_16 = {
    Text = "Je vois, c'est donc ce qu'elle vous a dit."
  },
  AvgDialog_18717_Content_17 = {
    Text = "Je suis également profondément reconnaissant envers Mademoiselle Horla. C'était une belle rencontre."
  },
  AvgDialog_18717_Content_18 = {
    Text = "Alors, pour le bien de Mademoiselle Horla, je te fais confiance cette fois-ci."
  },
  AvgDialog_18717_Content_19 = {
    Text = "<LightGray:De plus, les personnes envoyées par l'école sont déjà en route.>"
  },
  AvgDialog_18717_Content_2 = {
    Text = "2:15, Rue Kenting"
  },
  AvgDialog_18717_Content_20 = {
    Text = "<LightGray:Si je suis parti trop longtemps, ils ne resteront pas là à ne rien faire...>"
  },
  AvgDialog_18717_Content_21 = {
    Text = "Alors mettons-nous en route, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_18717_Content_22 = {
    Text = "Jonquille acquiesça avec joie, tendant sa main vers toi."
  },
  AvgDialog_18717_Content_23 = {Text = "新增"},
  AvgDialog_18717_Content_24 = {
    Text = "Vous tenez délicatement la main de Jonquille. Contrairement aux attentes, sa main est douce et chaude."
  },
  AvgDialog_18717_Content_25 = {
    Text = "Tenez bon, Gardien."
  },
  AvgDialog_18717_Content_26 = {
    Text = "Votre équilibre fléchit, et vous êtes tiré dans une dimension profonde."
  },
  AvgDialog_18717_Content_27 = {
    Text = "Bienvenue de nouveau à mon \"Mille Mirage\""
  },
  AvgDialog_18717_Content_28 = {
    Text = "Voici de nouveau cette familiarité de la Mer d'Essence Primordiale, avec des têtes encore en train de bobber avec les vagues."
  },
  AvgDialog_18717_Content_29 = {
    Text = "Contrairement à la dernière fois, les têtes semblent beaucoup plus silencieuses maintenant. Leurs orbites vides se tournent toutes vers vous, mais elles continuent à chuchoter entre elles."
  },
  AvgDialog_18717_Content_3 = {
    Text = "Je ne m'attendais pas à ce que tu acceptes de venir avec moi si facilement. N'as-tu pas peur que je t'emmène quelque part de étrange ?"
  },
  AvgDialog_18717_Content_30 = {
    Text = "Daffodil agita doucement sa main, et deux têtes tremblent alors qu'elles flottent à son niveau des yeux."
  },
  AvgDialog_18717_Content_31 = {
    Text = "<Change>Mon maître..."
  },
  AvgDialog_18717_Content_32 = {
    Text = "<Change> Ça fait longtemps..."
  },
  AvgDialog_18717_Content_33 = {
    Text = "<Change>Aide-moi à trouver quelqu'un..."
  },
  AvgDialog_18717_Content_34 = {
    Text = "Jonquille et le crâne chuchotent dans une langue que tu ne peux pas comprendre. Quoi qu'ils aient discuté, cela l'a fait rire joyeusement."
  },
  AvgDialog_18717_Content_35 = {
    Text = "Vous ne l'avez jamais vue sourire ainsi ; cela semble déplacé."
  },
  AvgDialog_18717_Content_36 = {
    Text = "Au lieu de cela, cela a traversé des centaines d'années et atterri dans un coin d'une histoire inconnue de vous."
  },
  AvgDialog_18717_Content_37 = {Text = "新增"},
  AvgDialog_18717_Content_38 = {
    Text = "Quel est le problème ? Y a-t-il quelque chose sur mon visage ?"
  },
  AvgDialog_18717_Content_39 = {
    Text = "Vous avez l'air ravi."
  },
  AvgDialog_18717_Content_4 = {
    Text = "Alors, vas-tu... me conduire dans des endroits étranges ?"
  },
  AvgDialog_18717_Content_40 = {
    Text = "Ce sont toutes mes collections chéries."
  },
  AvgDialog_18717_Content_41 = {
    Text = "Cela fait longtemps que je suis revenu. Ils me manquent énormément."
  },
  AvgDialog_18717_Content_42 = {
    Text = "De quoi parles-tu ?"
  },
  AvgDialog_18717_Content_43 = {
    Text = "Passé, présent et futur."
  },
  AvgDialog_18717_Content_44 = {
    Text = "Chacune de ces têtes est une <Yellow:projection from reality>. Leur vision et leur mémoire transcendent les dimensions du temps et de l'espace, m'aidant à découvrir de nombreuses choses inattendues."
  },
  AvgDialog_18717_Content_45 = {
    Text = "Alors c'est pourquoi ta boutique a tant d'objets étranges et inhabituels... ?"
  },
  AvgDialog_18717_Content_46 = {
    Text = "Jonquille cligna des yeux, acquiesçant tacitement à ta supposition."
  },
  AvgDialog_18717_Content_47 = {
    Text = "D'où viennent toutes ces têtes ?"
  },
  AvgDialog_18717_Content_48 = {
    Text = "Échange, cadeaux, et un peu de chance.\nBien sûr, j'en ai aussi pris une partie moi-même."
  },
  AvgDialog_18717_Content_49 = {
    Text = "On dit que vous avez traqué jusqu'à @1 têtes—c'est seulement le nombre officiellement enregistré."
  },
  AvgDialog_18717_Content_5 = {Text = "Bien sûr."},
  AvgDialog_18717_Content_50 = {
    Text = "Jonquille prit lentement une profonde bouffée de sa longue pipe, puis expira un nuage de fumée blanche."
  },
  AvgDialog_18717_Content_51 = {
    Text = "Désolée de te décevoir, {Male=Mr.,Female=Miss} Gardien, mais les reproches moraux n'ont aucun effet sur moi."
  },
  AvgDialog_18717_Content_52 = {
    Text = "Les règles créées par les humains ne s'appliquent pas à nous. Ce que vous voyez maintenant c'est moi, avec des yeux et un nez comme les vôtres..."
  },
  AvgDialog_18717_Content_53 = {
    Text = "Daffodil a ramassé la Clé en Argent sur votre poitrine, traçant légèrement ses motifs intriqués."
  },
  AvgDialog_18717_Content_54 = {
    Text = "Des bourdonnements chaotiques et des vibrations remplissent sa poitrine, se heurtant violemment comme une guerre silencieuse."
  },
  AvgDialog_18717_Content_55 = {
    Text = "Ressentez-vous cela ? Nous ne sommes pas humains. Nous sommes des \"bêtes\", ou comme certains nous appelleraient..."
  },
  AvgDialog_18717_Content_56 = {
    Text = "Nous sommes <Yellow:êtres supérieurs>."
  },
  AvgDialog_18717_Content_57 = {
    Text = "Nous tolérons les humains ignorants, nous suivons des règles en constante évolution, nous obéissons à des Lien fragiles, tout cela par peur..."
  },
  AvgDialog_18717_Content_58 = {
    Text = "Elle stroka doucement votre visage."
  },
  AvgDialog_18717_Content_59 = {
    Text = "Et une promesse."
  },
  AvgDialog_18717_Content_6 = {Text = "新增"},
  AvgDialog_18717_Content_60 = {Text = "新增"},
  AvgDialog_18717_Content_61 = {
    Text = "Alors tu es devenu l'un des rares Réveilleurs enregistrés sans aucun Lien."
  },
  AvgDialog_18717_Content_62 = {
    Text = "Personne n'est né pour apprécier d'être contrôlé ; la plupart des créatures aspirent inhérente à la liberté."
  },
  AvgDialog_18717_Content_63 = {
    Text = "Personnellement, je n'aime pas désavouer le soi-disant \"Lien\"... Tant que cela est mutuellement bénéfique, pourquoi se soucier des apparences ?"
  },
  AvgDialog_18717_Content_64 = {
    Text = "Le problème ne vient peut-être pas de moi.\nPersonne ne se connecte avec moi parce qu'ils ne sont pas qualifiés. Compris ?"
  },
  AvgDialog_18717_Content_65 = {Text = "Euh..."},
  AvgDialog_18717_Content_66 = {
    Text = "Que dire de moi ? Suis-je aussi l'un de ceux \"non qualifiés\"... ?"
  },
  AvgDialog_18717_Content_67 = {
    Text = "Jonquille éclata de rire, mais s'étouffa avec la fumée et ne put s'empêcher de tousser plusieurs fois."
  },
  AvgDialog_18717_Content_68 = {
    Text = "Ne vous inquiétez pas, enfant... Vous connaîtrez bientôt la réponse."
  },
  AvgDialog_18717_Content_69 = {
    Text = "<LightGray: Une autre réponse ambiguë...>"
  },
  AvgDialog_18717_Content_7 = {
    Text = "En fait... Mademoiselle Horla m'a parlé de votre première rencontre cet après-midi. Elle a dit—"
  },
  AvgDialog_18717_Content_70 = {
    Text = "Oups, j'ai peut-être un peu trop parlé."
  },
  AvgDialog_18717_Content_71 = {
    Text = "Daffodil a levé la main et a tapoté chaque front, les faisant flotter docilement."
  },
  AvgDialog_18717_Content_72 = {
    Text = "<Change>Merci à tous."
  },
  AvgDialog_18717_Content_73 = {
    Text = "D'accord. Allons-y, Gardien."
  },
  AvgDialog_18717_Content_74 = {
    Text = "Je connais déjà l'emplacement du Chasseur de Crâne."
  },
  AvgDialog_18717_Content_8 = {
    Text = "J'ai découvert plus tard qu'elle avait transformé ce souvenir en quelque chose appelé un \"film.\""
  },
  AvgDialog_18717_Content_9 = {
    Text = "Je me suis assis dans le public et j'ai regardé le premier film de ma vie."
  },
  AvgDialog_18718_Content_1 = {
    Text = "Une Réunion Solitaire"
  },
  AvgDialog_18718_Content_10 = {
    Text = "C'est ma maison.\nJe n'ai pas d'autre endroit où aller en dehors d'ici."
  },
  AvgDialog_18718_Content_11 = {
    Text = "Pour des gens comme nous venant de la campagne, peu importe où nous allons, c'est toujours la même chose."
  },
  AvgDialog_18718_Content_12 = {
    Text = "Dame Harriet..."
  },
  AvgDialog_18718_Content_13 = {
    Text = "L'atmosphère à l'intérieur de la maison est devenue quelque peu lourde."
  },
  AvgDialog_18718_Content_14 = {
    Text = "La pluie continue de tomber doucement alors que vous et elle regardez le rideau infini de pluie."
  },
  AvgDialog_18718_Content_15 = {
    Text = "L'extérieur est enveloppé d'une brume grise, avec de la vapeur d'eau t'enveloppant étroitement, donnant l'impression que tu es la seule vie restante entre le ciel et la terre."
  },
  AvgDialog_18718_Content_16 = {
    Text = "<LightGray:Où est la Dame jonquille maintenant...>"
  },
  AvgDialog_18718_Content_17 = {
    Text = "Veuillez patienter un instant, {Male=sir,Female=miss}. Je vais préparer du thé chaud dans la cuisine."
  },
  AvgDialog_18718_Content_18 = {
    Text = "Bien que ce soit humble ici, je peux tout de même te proposer une tasse de thé."
  },
  AvgDialog_18718_Content_19 = {
    Text = "Mme Harriet traînait ses pas lentement vers la cuisine."
  },
  AvgDialog_18718_Content_2 = {
    Text = "Vous suivez la femme dans la cabane en bois.\nL'intérieur est très simple, et vous sentez une odeur de bois humide."
  },
  AvgDialog_18718_Content_20 = {
    Text = "Jusqu'à ce que sa silhouette soit engloutie par les ombres profondes du couloir, tu as finalement repris tes esprits."
  },
  AvgDialog_18718_Content_21 = {
    Text = "On dirait qu'il faudra un moment avant que la pluie ne s'arrête. Jetons un coup d'œil autour."
  },
  AvgDialog_18718_Content_3 = {
    Text = "La femme se pencha lentement, ramassa quelques morceaux de bois de chauffage dans le coin et les jeta dans la petite cuisinière sombre."
  },
  AvgDialog_18718_Content_4 = {
    Text = "Mettez vos mains ici, réchauffez-les un peu plus longtemps, et vous n’aurez plus froid."
  },
  AvgDialog_18718_Content_5 = {
    Text = "Merci beaucoup..."
  },
  AvgDialog_18718_Content_6 = {
    Text = "Je m›appelle Harriet : @1, {Male=sir,Female=miss}. Vous pouvez m›appeler Harriet."
  },
  AvgDialog_18718_Content_7 = {
    Text = "Bien sûr, Madame Harriet. Pour être honnête, je suis curieux—pourquoi restes-tu ici ?"
  },
  AvgDialog_18718_Content_8 = {
    Text = "Cette zone ne semble pas très habitable."
  },
  AvgDialog_18718_Content_9 = {
    Text = "Mme Harriet était accroupie, jouant avec le bois de chauffage. Les flammes vacillantes dansaient sur son visage émacié et fatigué."
  },
  AvgDialog_18719_Content_1 = {
    Text = "Rassemblement du chasse-crâne"
  },
  AvgDialog_18719_Content_10 = {
    Text = "La nuit dernière, vous n'avez pas réussi à rattraper la Jonquille et n'avez pu suivre que l'adresse fournie par Ramona jusqu'à la résidence d'Horla."
  },
  AvgDialog_18719_Content_11 = {
    Text = "B-Bon matin, Mademoiselle Horla."
  },
  AvgDialog_18719_Content_12 = {
    Text = "Bonjour, {Male=Mr.,Female=Miss} %player%."
  },
  AvgDialog_18719_Content_13 = {Text = "新增"},
  AvgDialog_18719_Content_14 = {Text = "新增"},
  AvgDialog_18719_Content_15 = {
    Text = "Un silence gênant remplit l'air. Vous réalisez que cet Réveiller ne semble pas très doué pour socialiser."
  },
  AvgDialog_18719_Content_16 = {
    Text = "Miss Horla, je suis ici concernant l'événement Skull Hunter. \nPuisque tu vis ici depuis longtemps, as-tu des pistes ou des informations ?"
  },
  AvgDialog_18719_Content_17 = {
    Text = "\"Chasseur de Crânes\"... Veuillez patienter un moment."
  },
  AvgDialog_18719_Content_18 = {
    Text = "Horla se tourna et commença à chercher dans la grande bibliothèque."
  },
  AvgDialog_18719_Content_19 = {
    Text = "Je l'ai trouvé ! *Toux, toux...*"
  },
  AvgDialog_18719_Content_2 = {Text = "Daffodil !"},
  AvgDialog_18719_Content_20 = {
    Text = "Horla balaya la poussière flottante et mit le carnet jauni dans ta main."
  },
  AvgDialog_18719_Content_21 = {
    Text = "Il y a un mois, Mademoiselle Poupée a demandé mon aide."
  },
  AvgDialog_18719_Content_22 = {
    Text = "Je n'ai pas de compétences particulières, mais j'ai documenté tous les cas récents. J'espère que cela pourra être utile."
  },
  AvgDialog_18719_Content_23 = {
    Text = "Vous ouvrez le carnet, et dans une écriture élégante, il enregistre le temps et le lieu de découverte de chaque cas, incluant même des croquis des corps et des scènes de crime."
  },
  AvgDialog_18719_Content_24 = {
    Text = "<Shake:Je suis désolé, mes compétences en dessin sont assez pauvres. Tu peux simplement l'ignorer...>"
  },
  AvgDialog_18719_Content_25 = {
    Text = "Non, c'est très impressionnant.\nMerci, Mademoiselle Horla. Cette note est cruciale pour nous."
  },
  AvgDialog_18719_Content_26 = {
    Text = "Peu importe quoi, je suis heureux d'aider. Ces pauvres gens..."
  },
  AvgDialog_18719_Content_27 = {
    Text = "Horla laissa échapper un doux soupir et se tourna pour contempler le ciel sombre à l'extérieur."
  },
  AvgDialog_18719_Content_28 = {
    Text = "La Ville Pluvieuse (Pluvieuse) est un endroit où il pleut toute l'année. Cependant, après la pluie, ce à quoi elle est souvent confrontée n'est pas une récolte abondante mais d'innombrables inondations et fléaux."
  },
  AvgDialog_18719_Content_29 = {
    Text = "Les jeunes travaillent dans de grandes villes comme Londinium, laissant derrière eux uniquement les personnes âgées et les enfants."
  },
  AvgDialog_18719_Content_3 = {
    Text = "Huh... Où est cet endroit ?"
  },
  AvgDialog_18719_Content_30 = {
    Text = "Maintenant, même les anciens commencent à partir un par un..."
  },
  AvgDialog_18719_Content_31 = {
    Text = "J'ai assisté à quelques funérailles locales. Chaque fois qu'un être cher s'éteint, les Reenians chantent une chanson ancienne..."
  },
  AvgDialog_18719_Content_32 = {
    Text = "Horla commença à fredonner doucement, et la mélodie mélancolique se mua bientôt en paroles aussi sombres que l'encre."
  },
  AvgDialog_18719_Content_33 = {
    Text = "<RedItalic:Nous écrivons avec le sang comme plume et la boue comme papier.>\n<RedItalic:Nous inscrivons la douleur et la peur avec des corps trempés de pluie...>"
  },
  AvgDialog_18719_Content_34 = {
    Text = "Ces mots ont lentement circulé autour d'Horla, puis ont formé une lettre jaunit qui l'a enveloppée."
  },
  AvgDialog_18719_Content_35 = {
    Text = "Elle laissa échapper un léger soupir, des larmes brillant dans ses yeux."
  },
  AvgDialog_18719_Content_36 = {
    Text = "Tout ce qui se passe maintenant n'est-il pas le chagrin que les Renier ont écrit avec leurs corps trempés de pluie"
  },
  AvgDialog_18719_Content_37 = {
    Text = "L'air est rempli d'un sentiment silencieux et épais de dépression, vous étouffant presque."
  },
  AvgDialog_18719_Content_38 = {
    Text = "<Shake:Toux, Mademoiselle Horla...>"
  },
  AvgDialog_18719_Content_39 = {Text = "新增"},
  AvgDialog_18719_Content_4 = {
    Text = "Le chant joyeux des oiseaux vous ramène à la réalité de vos rêves."
  },
  AvgDialog_18719_Content_40 = {
    Text = "Ah ! Désolé, j'ai encore recommencé..."
  },
  AvgDialog_18719_Content_41 = {
    Text = "Horla reprit ses esprits et prit deux profondes respirations."
  },
  AvgDialog_18719_Content_42 = {
    Text = "Les émotions oppressives se sont enfin dissipées, et le poids lourd sur votre poitrine a considérablement diminué."
  },
  AvgDialog_18719_Content_43 = {Text = "新增"},
  AvgDialog_18719_Content_44 = {Text = "新增"},
  AvgDialog_18719_Content_45 = {
    Text = "Ah, d'accord, d'accord."
  },
  AvgDialog_18719_Content_46 = {
    Text = "J'ai préparé une théière de thé à la rose avec des pétales fraîchement cueillis. Voudrais-tu te joindre à moi pour une dégustation ?"
  },
  AvgDialog_18719_Content_47 = {
    Text = ": Dans une demi-heure"
  },
  AvgDialog_18719_Content_48 = {
    Text = "Dans une main, vous tenez une tasse en porcelaine fine remplie de thé à la rose, tandis qu'avec l'autre, vous feuilletez les notes d'Horla, à la recherche d'une éventuelle percée."
  },
  AvgDialog_18719_Content_49 = {
    Text = "Où sont les gens du poste de police ?"
  },
  AvgDialog_18719_Content_5 = {
    Text = "Vous contemplez la chambre propre et simple avec confusion, puis soulevez la couverture et reniflez."
  },
  AvgDialog_18719_Content_50 = {
    Text = "Dans la rue Norwich, l'endroit que vous avez passé la nuit dernière."
  },
  AvgDialog_18719_Content_51 = {Text = "新增"},
  AvgDialog_18719_Content_52 = {
    Text = "Pluie. Sang. Jonquille.\nEn rappelant la rencontre de la nuit dernière, vous ne pouvez pas dire si c'était un rêve ou la réalité."
  },
  AvgDialog_18719_Content_53 = {
    Text = "Vous avez l'air faible... N'avez-vous pas bien dormi la nuit dernière ?"
  },
  AvgDialog_18719_Content_54 = {
    Text = "Non, c'est juste..."
  },
  AvgDialog_18719_Content_55 = {
    Text = "Vous avez secoué la tête, essayant d'éclaircir les pensées confuses dans votre esprit."
  },
  AvgDialog_18719_Content_56 = {Text = "新增"},
  AvgDialog_18719_Content_57 = {
    Text = "L'enquête dans la ville de Lai vient de se terminer il y a deux jours, et vos blessures ne sont pas encore complètement guéries."
  },
  AvgDialog_18719_Content_58 = {
    Text = "Soupir, il ne peut pas être aidé que les autres Enquêteurs soient également pris, n'est-ce pas ?"
  },
  AvgDialog_18719_Content_59 = {
    Text = "À ce stade, concluons rapidement cette affaire. Je veux prendre des vacances."
  },
  AvgDialog_18719_Content_6 = {
    Text = "Bien. Sec et doux, sans odeur de pluie ou de sang."
  },
  AvgDialog_18719_Content_60 = {
    Text = "Hein, c'est..."
  },
  AvgDialog_18719_Content_61 = {
    Text = "Le son du tournement des pages s'est arrêté brusquement."
  },
  AvgDialog_18719_Content_62 = {
    Text = "Vous vous concentrez sur la page gelée, commençant à formuler votre prochain plan d'investigation"
  },
  AvgDialog_18719_Content_63 = {
    Text = "Ramona... Avant de retrouver le détective, je veux d'abord aller quelque part."
  },
  AvgDialog_18719_Content_7 = {
    Text = "Bonjour, {Male=Mr.,Female=Miss} %player%. Bienvenue dans mon humble demeure..."
  },
  AvgDialog_18719_Content_8 = {
    Text = "Mademoiselle Horla ?!"
  },
  AvgDialog_18719_Content_9 = {
    Text = "La Mémoire commence à se rétablir progressivement."
  },
  AvgDialog_18720_Content_1 = {
    Text = "11:00, Cimetière de Highgate"
  },
  AvgDialog_18720_Content_10 = {
    Text = "N'attends pas trop de l'expertise des détectives dans les zones reculées."
  },
  AvgDialog_18720_Content_11 = {
    Text = "...Ça a du sens."
  },
  AvgDialog_18720_Content_12 = {
    Text = "Vous sortez votre loupe et continuez à observer le squelette."
  },
  AvgDialog_18720_Content_13 = {
    Text = "Il y a une <Red:coupure dentelée> sur l'os du cou..."
  },
  AvgDialog_18720_Content_14 = {
    Text = "Cependant, c'est assez en désordre avec de nombreuses coupures qui se chevauchent, complètement différent de ce que nous avons vu dans les photos plus tôt."
  },
  AvgDialog_18720_Content_15 = {
    Text = "Toujours assez inexpérimenté, première fois à commettre un crime ?"
  },
  AvgDialog_18720_Content_16 = {
    Text = "Commencez l'enquête centrée autour du Cimetière.\nLes novices inexpérimentés ne s'éloignent généralement pas de chez eux lors de leur premier crime."
  },
  AvgDialog_18720_Content_17 = {
    Text = "Compris. J'ai confiance cette fois-ci ; le coupable sera bientôt attrapé !"
  },
  AvgDialog_18720_Content_18 = {
    Text = "Meurtrier ? Comment osez-vous supposer, *hic*, qu'il n'y a qu'un seul meurtrier ?"
  },
  AvgDialog_18720_Content_19 = {
    Text = "Des profondeurs de la dense forêt émergea un vieil homme, empestant l'alcool et avec les joues rouges."
  },
  AvgDialog_18720_Content_2 = {
    Text = "Vous marchez seul à travers les tumulus désolés."
  },
  AvgDialog_18720_Content_20 = {
    Text = "Désolé, je ne voulais pas écouter votre monologue."
  },
  AvgDialog_18720_Content_21 = {
    Text = "Je suis le gardien de ce cimetière. Tu peux m'appeler... euh, <Blue:Old Freeman>."
  },
  AvgDialog_18720_Content_22 = {
    Text = "Bon après-midi, M. Freeman.\nAvez-vous juste insinué qu'il y a plus d'un tueur ?"
  },
  AvgDialog_18720_Content_23 = {
    Text = "Vieux Freeman saisit la bouteille et enchaîna les gorgées d'alcool, sa grosse pomme d'Adam se soulevant et s'abaissant."
  },
  AvgDialog_18720_Content_24 = {
    Text = "Rends-toi ! Cette forêt misérable ne voit jamais âme qui vive toute la journée. Puisque tu es ici, laisse-moi te raconter une histoire..."
  },
  AvgDialog_18720_Content_25 = {
    Text = "C'était probablement plus tôt cette année...? Je ne me souviens plus très bien."
  },
  AvgDialog_18720_Content_26 = {
    Text = "Comme d'habitude, j'ai bu et je me suis assoupi dans un coin ombragé."
  },
  AvgDialog_18720_Content_27 = {
    Text = "Et puis j'ai entendu des bruits étranges, presque comme..."
  },
  AvgDialog_18720_Content_28 = {
    Text = "<RedItalic:Zzz... Crack...>"
  },
  AvgDialog_18720_Content_29 = {
    Text = "Bruit étrange. Que se passe-t-il ensuite ?"
  },
  AvgDialog_18720_Content_3 = {
    Text = "Les corbeaux glissent à travers le ciel sombre tandis que le vent automnal désolé hurle."
  },
  AvgDialog_18720_Content_30 = {
    Text = "Ne t'inquiète pas, petit détective.\nJ'ai ouvert les yeux... hic, devine ce que j'ai vu ?"
  },
  AvgDialog_18720_Content_31 = {
    Text = "Pas question, c'est juste le Chasseur de Crânes, n'est-ce pas ?"
  },
  AvgDialog_18720_Content_32 = {
    Text = "Bien sûr, c'est un Chasseur de Crânes ! Ou, tu pourrais dire que c'est une femme..."
  },
  AvgDialog_18720_Content_33 = {
    Text = "Une femme coupe la tête de Pinocchio !"
  },
  AvgDialog_18720_Content_34 = {
    Text = "Alors elle me vit—hic—comme si elle avait vu un fantôme, et courut plus vite que quiconque !"
  },
  AvgDialog_18720_Content_35 = {
    Text = "Ma pauvre Pinoko, son cou est à peine maintenu par un fil !"
  },
  AvgDialog_18720_Content_36 = {
    Text = "Haha, <Big:Hahahaha...>"
  },
  AvgDialog_18720_Content_37 = {
    Text = "Vieux Freeman éclata d'un rire tonitruant, allant même jusqu'à verser des larmes de joie."
  },
  AvgDialog_18720_Content_38 = {
    Text = "<SmallShake:Patience, patience...>"
  },
  AvgDialog_18720_Content_39 = {
    Text = "Hic, hic ! Ça fait environ un mois, et j'ai encore entendu cette voix..."
  },
  AvgDialog_18720_Content_4 = {
    Text = "Je l'ai trouvé."
  },
  AvgDialog_18720_Content_40 = {
    Text = "<RedItalic:Zzz... Craquement... Craquement...>"
  },
  AvgDialog_18720_Content_41 = {
    Text = "Cette fois, ce n'est pas la femme qui est revenue, mais un homme très mince."
  },
  AvgDialog_18720_Content_42 = {
    Text = "C'est un ouvrier qualifié ! D'un seul coup..."
  },
  AvgDialog_18720_Content_43 = {
    Text = "<RedBig: Whoosh !> La tête de Pinoko a disparu !"
  },
  AvgDialog_18720_Content_44 = {
    Text = "On dirait qu'il y avait deux Chasseurs de Crânes. Que s'est-il passé ensuite ?"
  },
  AvgDialog_18720_Content_45 = {
    Text = "Plus tard ? Il n'y a pas de plus tard. C'est toute l'histoire du vieux Freeman et des Crabes de tête, hic."
  },
  AvgDialog_18720_Content_46 = {
    Text = "Vieux Freeman laissa échapper un roch encore satisfait, plissant ses yeux jaunes troubles et vous détaillant de haut en bas."
  },
  AvgDialog_18720_Content_47 = {
    Text = "Vous semblez complètement perdu, pauvre petit détective. Avez-vous déjà entendu parler de <Red:La Légende du Chasseur de Crânes> ?"
  },
  AvgDialog_18720_Content_48 = {
    Text = "La Légende du Chasseur de Crânes ? Racontez-moi."
  },
  AvgDialog_18720_Content_49 = {
    Text = "Vieux Freeman s'appuya tranquillement contre la pierre tombale, prit quelques gorgées pour finir le reste d'alcool dans la bouteille, et la lança négligemment au sol."
  },
  AvgDialog_18720_Content_5 = {
    Text = "Vous vous arrêtez devant une tombe solitaire, le couvercle de cercueil en décomposition déjà soulevé en dessous."
  },
  AvgDialog_18720_Content_50 = {
    Text = "Du liquide s'égouttait de la bouteille cassée, laissant une traînée sinueuse sur le sol. Comme des larmes, ou peut-être du sang."
  },
  AvgDialog_18720_Content_51 = {
    Text = "Certains disent que le Chasseur de Crânes est un monstre né de l'<Yellow:Epidemic>."
  },
  AvgDialog_18720_Content_52 = {
    Text = "Certains disent que le Chasseur de Crânes n'est ni une personne ni deux personnes."
  },
  AvgDialog_18720_Content_53 = {
    Text = "<Red: Les Chasseurs de Crânes est une organisation.>"
  },
  AvgDialog_18720_Content_54 = {
    Text = "Organisation ?"
  },
  AvgDialog_18720_Content_55 = {
    Text = "Oui, une organisation."
  },
  AvgDialog_18720_Content_56 = {
    Text = "Ils n'apparaissent que lors des nuits pluvieuses, leurs pas dissimulés par la pluie, s'approchant silencieusement derrière vous..."
  },
  AvgDialog_18720_Content_57 = {
    Text = "<RedBig: Snap !>"
  },
  AvgDialog_18720_Content_58 = {Text = "!!"},
  AvgDialog_18720_Content_59 = {
    Text = "Hahaha ! Qu'est-ce que c'est ? Déjà peur, mon petit détective ?"
  },
  AvgDialog_18720_Content_6 = {
    Text = "Un squelette sans tête gît dans le cercueil, désormais un paradis pour la mousse et les insectes."
  },
  AvgDialog_18720_Content_60 = {
    Text = "Il se penche plus près, ses yeux jaunes troubles roulant, presque brûlant en vous."
  },
  AvgDialog_18720_Content_61 = {
    Text = "Cette personne semble étrange. Quitte rapidement cet endroit."
  },
  AvgDialog_18720_Content_62 = {
    Text = "Désolé, Monsieur Freeman. Il se fait tard. Je pense que je dois partir..."
  },
  AvgDialog_18720_Content_63 = {
    Text = "Vous avez pris une légère inspiration et vous êtes éloigné sans regarder en arrière."
  },
  AvgDialog_18720_Content_64 = {
    Text = "Un rire moqueur vient de derrière, mais tu ne peux pas t'en préoccuper maintenant. Tout ce que tu veux, c'est partir."
  },
  AvgDialog_18720_Content_65 = {
    Text = "Le ciel s'est progressivement assombri, avec des nuages sombres suspendus bloquant la lumière du soleil pâle. Le vent agitait les feuilles, les faisant onduler comme des vagues."
  },
  AvgDialog_18720_Content_66 = {
    Text = "À la fin du cimetière, vous voyez une silhouette à la fois familière et étrange."
  },
  AvgDialog_18720_Content_67 = {
    Text = "C'est Jonquille. La majorité de son visage est cachée sous le bord de son chapeau abaissé, avec des cheveux gris-blancs se balançant doucement dans le vent."
  },
  AvgDialog_18720_Content_68 = {
    Text = "En te voyant dans un tel état ébouriffé, Daffodil rit joyeusement."
  },
  AvgDialog_18720_Content_69 = {
    Text = "Ça faisait longtemps, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_18720_Content_7 = {
    Text = "La note enregistre la date de découverte comme étant il y a six mois ; l'heure du décès doit être encore plus tôt..."
  },
  AvgDialog_18720_Content_8 = {
    Text = "En d'autres termes, il s'agit probablement de la première victime connue du \"Chasseur de Crânes\". Cependant, les dossiers de la police ne l'ont jamais mentionné..."
  },
  AvgDialog_18720_Content_9 = {
    Text = "Il n'y a pas d'hôpital approprié ou de salon funéraire ici, et personne ne prête beaucoup d'attention aux morts."
  },
  AvgDialog_18721_Content_1 = {
    Text = "Peut-être essayez d'utiliser Trace d'Esprit pour trouver le Chasseur de Crânes ?"
  },
  AvgDialog_18721_Content_2 = {
    Text = "Cette méthode a peu d'effet sur les créatures du Royaume Ultra."
  },
  AvgDialog_18721_Content_3 = {
    Text = "La rétrospection spirituelle n'est pas omnipotente non plus."
  },
  AvgDialog_18722_Content_1 = {
    Text = "Jusqu'à ce que nous nous rencontrions à nouveau"
  },
  AvgDialog_18722_Content_10 = {
    Text = "<LightGray:Un crâne précieux ? À qui pourrait-il appartenir...>"
  },
  AvgDialog_18722_Content_11 = {Text = "新增"},
  AvgDialog_18722_Content_12 = {
    Text = "Vous avez l'air troublé, %player%. Il semblerait que vous vouliez vraiment connaître la réponse ?"
  },
  AvgDialog_18722_Content_13 = {
    Text = "C'est juste moyen."
  },
  AvgDialog_18722_Content_14 = {
    Text = "Ahem, je ne suis pas du genre à fouiller dans la vie privée des autres."
  },
  AvgDialog_18722_Content_15 = {
    Text = "Est-ce que c'est ça ? Mais votre expression vous a déjà trahi."
  },
  AvgDialog_18722_Content_16 = {
    Text = "Bien sûr, je veux savoir."
  },
  AvgDialog_18722_Content_17 = {
    Text = "Je veux juste en savoir plus sur toi, Dame Jonquille."
  },
  AvgDialog_18722_Content_18 = {
    Text = "Oh ? Quelqu'un semble devenir plus avide."
  },
  AvgDialog_18722_Content_19 = {
    Text = "Voici un indice : <Yellow: C'est quelque chose que tu as déjà vu.>"
  },
  AvgDialog_18722_Content_2 = {
    Text = "Les troupes de soutien et le Comité sont en route. Reste ici et sécurise la zone."
  },
  AvgDialog_18722_Content_20 = {
    Text = "Avez-vous déjà vu ça...?"
  },
  AvgDialog_18722_Content_21 = {
    Text = "Vous réfléchissez profondément, l'histoire des deux derniers jours et les personnes que vous avez rencontrées défilent devant vos yeux comme une lanterne tournante."
  },
  AvgDialog_18722_Content_22 = {Text = "新增"},
  AvgDialog_18722_Content_23 = {Text = "!!"},
  AvgDialog_18722_Content_24 = {
    Text = "Pourrait-il s'agir de celui de la rue Norwich qui te ressemble exactement... ?"
  },
  AvgDialog_18722_Content_25 = {
    Text = "Très intelligent."
  },
  AvgDialog_18722_Content_26 = {
    Text = "Mais pourquoi... Je ne comprends pas."
  },
  AvgDialog_18722_Content_27 = {
    Text = "Jonquille regarda l'aube brumeuse à l'horizon lointain, le vent froid soulevant ses longs cheveux."
  },
  AvgDialog_18722_Content_28 = {
    Text = "C'est un \"spécimen.\" Il appartenait à mon ancien maître."
  },
  AvgDialog_18722_Content_29 = {
    Text = "Voici un secret : Mon visage actuel est modélisé d'après lui."
  },
  AvgDialog_18722_Content_3 = {
    Text = "Ne t'inquiète pas, cette fois je vais être sage et attendre ici. Je ne vais pas courir partout."
  },
  AvgDialog_18722_Content_30 = {Text = "?!"},
  AvgDialog_18722_Content_31 = {
    Text = "<LightGray:Donc ce n'est pas la véritable apparence de la Dame jonquille...>"
  },
  AvgDialog_18722_Content_32 = {
    Text = "Vous m'avez vraiment aidé cette fois. \nJe ne peux toujours pas me pardonner d'avoir utilisé un Gardien si inexpérimenté comme appât."
  },
  AvgDialog_18722_Content_33 = {
    Text = "...Cela n'a pas d'importance. Tant que l'enquête est complétée, je ne me soucie pas d'être utilisé une fois."
  },
  AvgDialog_18722_Content_34 = {
    Text = "Est-ce que c'est ça ? Mais je me sens vraiment mal à ce sujet. Donc..."
  },
  AvgDialog_18722_Content_35 = {
    Text = "En guise d'excuse, je peux vous accorder une demande."
  },
  AvgDialog_18722_Content_36 = {
    Text = "C'est gratuit~"
  },
  AvgDialog_18722_Content_37 = {Text = "!!"},
  AvgDialog_18722_Content_38 = {
    Text = "La personne devant vous est un marchand avisé et impitoyable, possédant des renseignements, des connaissances taboues et des objets de collection précieux que beaucoup désirent."
  },
  AvgDialog_18722_Content_39 = {
    Text = "Et maintenant, elle peut te faire une demande gratuitement."
  },
  AvgDialog_18722_Content_4 = {
    Text = "Je ne m'attendais pas à ce que l'enquête soit terminée si rapidement.\nExcellent travail, %player%."
  },
  AvgDialog_18722_Content_40 = {
    Text = "<LightGray:Non... Mademoiselle Poupée serait contrariée si elle découvrait que je faisais des affaires avec d'autres dehors.>"
  },
  AvgDialog_18722_Content_41 = {
    Text = "Un flot de possibilités traverse votre esprit—reliques d'or perdues, les gâteaux les plus délicieux, un immense Croc de Léon..."
  },
  AvgDialog_18722_Content_42 = {
    Text = "Des pensées conflictuelles s'entrelacent et se heurtent, mais finissent par se retirer comme la marée — vous décidez de suivre vos instincts."
  },
  AvgDialog_18722_Content_43 = {
    Text = "As-tu décidé de ta demande ? Ne sois pas trop avide."
  },
  AvgDialog_18722_Content_44 = {
    Text = "J'ai pris ma décision. Mes exigences sont simples."
  },
  AvgDialog_18722_Content_45 = {
    Text = "Laisse-moi voir ta véritable forme."
  },
  AvgDialog_18722_Content_46 = {Text = "新增"},
  AvgDialog_18722_Content_47 = {
    Text = "Est-ce vraiment si simple ? Réfléchis-y. Je peux te donner beaucoup de choses, chacune valant plus que cela."
  },
  AvgDialog_18722_Content_48 = {
    Text = "La valeur est déterminée par mon jugement. C'est ma seule exigence."
  },
  AvgDialog_18722_Content_49 = {
    Text = "Comme on pouvait l›attendre d›un Gardien de {Male=Mr.,Female=Miss}, vous me surprenez toujours. Alors..."
  },
  AvgDialog_18722_Content_5 = {
    Text = "Tousse, merci à la Dame jonquille cette fois."
  },
  AvgDialog_18722_Content_50 = {
    Text = "Daffodil s'est dirigée vers vous. Le vent a soulevé ses longs cheveux, les faisant flotter comme des vagues grises."
  },
  AvgDialog_18722_Content_51 = {
    Text = "Tu es si proche que tu peux presque voir ton reflet dans ses yeux."
  },
  AvgDialog_18722_Content_52 = {
    Text = "Souviens-toi de garder cela secret, %player%."
  },
  AvgDialog_18722_Content_53 = {
    Text = "À peine avait-elle parlé que ses traits commencèrent à s'estomper et à se dissoudre, comme des peintures à l'huile dans l'eau..."
  },
  AvgDialog_18722_Content_54 = {
    Text = "Enfin, vous avez enfin vu son visage clairement."
  },
  AvgDialog_18722_Content_55 = {
    Text = "C'était un visage @2, vous rappelant de nombreuses choses."
  },
  AvgDialog_18722_Content_56 = {
    Text = "Comme la brume humide après la pluie, la jonquille fleurissant silencieusement dans un coin, ou le petit animal enroulé dans l'obscurité..."
  },
  AvgDialog_18722_Content_57 = {
    Text = "Avant que vous ne puissiez examiner de plus près, le visage disparut comme une goutte d'eau se mêlant à l'eau."
  },
  AvgDialog_18722_Content_58 = {
    Text = "Donc... c'est ta véritable forme."
  },
  AvgDialog_18722_Content_59 = {
    Text = "Comment ça ? C'est moche, n'est-ce pas ?"
  },
  AvgDialog_18722_Content_6 = {
    Text = "C'est juste un petit effort, et j'ai aussi récupéré ce qui a été perdu."
  },
  AvgDialog_18722_Content_60 = {
    Text = "Vous secouez la tête."
  },
  AvgDialog_18722_Content_61 = {
    Text = "Inattendu... mais si typique de toi."
  },
  AvgDialog_18722_Content_62 = {
    Text = "La lumière du matin balaie l'humidité de la pluie, enveloppant son corps d'un doux halo."
  },
  AvgDialog_18722_Content_63 = {
    Text = "Pour être honnête... j'avais un peu peur tout à l'heure, et ensuite j'ai été surpris par ma propre peur."
  },
  AvgDialog_18722_Content_64 = {
    Text = "Dix ans, cinquante ans ? Je ne me souviens même pas de la dernière fois que j'ai ressenti la peur."
  },
  AvgDialog_18722_Content_65 = {
    Text = "Peur...? Est-il possible que tu crains que je te trouve peu attrayant ?"
  },
  AvgDialog_18722_Content_66 = {
    Text = "Jonquille ne répondit pas, se contentant de te froisser doucement les cheveux."
  },
  AvgDialog_18722_Content_67 = {
    Text = "%player%, tu es maintenant la seule personne au monde à m'avoir vu \"moi\"."
  },
  AvgDialog_18722_Content_68 = {
    Text = "Heh, j'ai un peu de levier sur toi maintenant."
  },
  AvgDialog_18722_Content_69 = {
    Text = "Avant de perdre ma mémoire, je dois rapidement dessiner ton visage sur papier."
  },
  AvgDialog_18722_Content_7 = {
    Text = "Du point de vue du marchand, c'était un \"accord\" parfait"
  },
  AvgDialog_18722_Content_70 = {
    Text = "Daffodil a souri, ses yeux formant un arc magnifique."
  },
  AvgDialog_18722_Content_71 = {
    Text = "Quel enfant sillonne."
  },
  AvgDialog_18722_Content_72 = {
    Text = "Eh bien, ton Comité et tes amis policiers devraient être en route maintenant, n'est-ce pas ?"
  },
  AvgDialog_18722_Content_73 = {
    Text = "<Shake:Alors tu savais depuis le début...>"
  },
  AvgDialog_18722_Content_74 = {
    Text = "Je n'ai pas la patience pour ces interrogatoires ennuyeux.\nLa prochaine fois, trouvons un endroit calme et prenons une tasse de café."
  },
  AvgDialog_18722_Content_75 = {
    Text = "Adieu, mon {Male=Mr.,Female=Miss} Gardien."
  },
  AvgDialog_18722_Content_76 = {
    Text = "Huh ? Oh... Adieu, Dame Jonquille."
  },
  AvgDialog_18722_Content_77 = {
    Text = "Daffodil vous a fait un signe et est partie."
  },
  AvgDialog_18722_Content_78 = {
    Text = "En l'observant d'un air détendu au loin, tu sens ton humeur s'alléger."
  },
  AvgDialog_18722_Content_79 = {
    Text = "La brume persistante s'est complètement dissipée, et le ciel s'est enfin éclairci. La lumière du soleil filtre à travers les nuages paresseux, réchauffant tout votre corps."
  },
  AvgDialog_18722_Content_8 = {
    Text = "Choses perdues..."
  },
  AvgDialog_18722_Content_80 = {
    Text = "Pour une raison quelconque, vous avez une prémonition—"
  },
  AvgDialog_18722_Content_81 = {
    Text = "Vous continuerez à vous rencontrer à travers différents temps et dimensions."
  },
  AvgDialog_18722_Content_9 = {
    Text = "Le Chasseur de Crânes m'a pris un <Yellow:crâne précieux>, donc je suis ici pour faire un petit enquête. C'est aussi simple que ça."
  },
  AvgDialog_18723_Content_1 = {
    Text = "Toux, tousse, les Réveilleurs du Royaume Ultra sont vraiment difficiles à poursuivre..."
  },
  AvgDialog_18723_Content_10 = {
    Text = "Répondre... ?"
  },
  AvgDialog_18723_Content_11 = {
    Text = "Il s'est enfui pendant que vous étiez temporairement absent, et Mme Horla et moi étions en train de discuter."
  },
  AvgDialog_18723_Content_12 = {
    Text = "Mais il n'y a pas lieu de s'inquiéter. Si vous me suivez, vous le verrez bientôt."
  },
  AvgDialog_18723_Content_13 = {
    Text = "Est-ce dans le <Blue:Désert au nord de la ville de Reny> ?"
  },
  AvgDialog_18723_Content_14 = {
    Text = "Oh ? Il semble que notre petit détective est assez perspicace. Comment as-tu réussi à le découvrir ?"
  },
  AvgDialog_18723_Content_15 = {
    Text = "Ce gars présente le phénomène D, qui est probablement lié à la peste qui s'est produite dans le nord il y a trois ans."
  },
  AvgDialog_18723_Content_16 = {
    Text = "Maintenant que c'est gravement blessé et qu'il est attaqué à la fois par nous et par la police, il ne lui reste plus beaucoup d'endroits où aller."
  },
  AvgDialog_18723_Content_17 = {
    Text = "Peu importe si c'est caché dans le désert, c'est une percée qui vaut la peine d'être explorée."
  },
  AvgDialog_18723_Content_18 = {
    Text = "Pas mal, assez intelligent. Mais sais-tu à quel point ce désert est vaste ?"
  },
  AvgDialog_18723_Content_19 = {
    Text = "Environ 50 miles carrés.\nVous ne voudriez pas gaspiller vos précieuses vacances en exploration géologique et en travail de recensement, n'est-ce pas ?"
  },
  AvgDialog_18723_Content_2 = {
    Text = "Vous titubez jusqu'à un carrefour."
  },
  AvgDialog_18723_Content_20 = {
    Text = [[
Et je sais par hasard son emplacement exact.
Voudriez-vous venir avec moi ?]]
  },
  AvgDialog_18723_Content_21 = {
    Text = "Ne sois pas d'accord. Elle est extrêmement dangereuse ; ne te laisse pas tromper par elle."
  },
  AvgDialog_18723_Content_22 = {
    Text = "Je vais compter jusqu'à trois. Trois, deux..."
  },
  AvgDialog_18723_Content_23 = {Text = "新增"},
  AvgDialog_18723_Content_24 = {
    Text = "Je vais avec toi."
  },
  AvgDialog_18723_Content_25 = {Text = "新增"},
  AvgDialog_18723_Content_26 = {
    Text = "Hmm, quel enfant obéissant."
  },
  AvgDialog_18723_Content_27 = {
    Text = "Dame Daffodil, puis-je vous accompagner ?"
  },
  AvgDialog_18723_Content_28 = {
    Text = "Une fragile fille sort de l'ombre des arbres derrière vous, ses yeux remplis d'inquiétude."
  },
  AvgDialog_18723_Content_29 = {
    Text = "Je sais que vous êtes inquiet pour %player%."
  },
  AvgDialog_18723_Content_3 = {
    Text = "Plus de chasseurs ici, seulement Jonquille et son ombre allongée."
  },
  AvgDialog_18723_Content_30 = {
    Text = "Mais je suis désolé, ma petite rose. Cette fois, je ne peux prendre qu'une seule personne."
  },
  AvgDialog_18723_Content_31 = {
    Text = "Le vent froid hurle à travers les rues nocturnes. Horla s'enveloppe étroitement dans la lettre coupe-vent et chauffante, son visage pâle levé alors qu'elle regarde Jonquille avec une expression sérieuse."
  },
  AvgDialog_18723_Content_32 = {
    Text = "Pourquoi ? Je ne suis peut-être pas bon en combat, mais une main supplémentaire est toujours utile, n'est-ce pas ?"
  },
  AvgDialog_18723_Content_33 = {
    Text = "Je ne peux en prendre qu'un. Désolé, Petite Rose, j'ai mes raisons."
  },
  AvgDialog_18723_Content_34 = {Text = "新增"},
  AvgDialog_18723_Content_35 = {
    Text = "Dame Daffodil, vous ramènerez sûrement {Male=Mr.,Female=Miss} %player% sain et sauf, n'est-ce pas ?"
  },
  AvgDialog_18723_Content_36 = {
    Text = "Daffodil regardait les papillons voler sous le lampadaire et soufflait tranquillement un cercle de fumée de sa bouche."
  },
  AvgDialog_18723_Content_37 = {
    Text = "Bien sûr, ne t'inquiète pas."
  },
  AvgDialog_18723_Content_4 = {
    Text = "Pour une raison quelconque, vous avez l'impression qu'elle se tient là depuis très longtemps."
  },
  AvgDialog_18723_Content_5 = {
    Text = "Il semble que, depuis les temps anciens, elle se tienne ici seule, regardant silencieusement au loin sans prononcer un mot."
  },
  AvgDialog_18723_Content_6 = {Text = "Tu es ici."},
  AvgDialog_18723_Content_7 = {
    Text = "Daffodil s'est retournée, son expression restant encore floue."
  },
  AvgDialog_18723_Content_8 = {
    Text = "Où est le Chasseur de Crânes ? As-tu perdu sa trace ?"
  },
  AvgDialog_18723_Content_9 = {
    Text = "Oui, nous avons perdu le fil. Mais... je pense que je connais déjà la réponse."
  },
  AvgDialog_18724_Content_1 = {Text = "De loin"},
  AvgDialog_18724_Content_10 = {
    Text = "D'après l'état des corps et les témoignages des témoins, les deux sont morts dans un intervalle d'une demi-heure l'un de l'autre."
  },
  AvgDialog_18724_Content_11 = {
    Text = "Le lieu de la mort est-il proche ?"
  },
  AvgDialog_18724_Content_12 = {
    Text = "Ramona secoua la tête."
  },
  AvgDialog_18724_Content_13 = {
    Text = "Même en voiture, cela prend plus d'une heure, sans parler du fait que très peu de gens dans la ville possèdent des voitures."
  },
  AvgDialog_18724_Content_14 = {
    Text = "... Peut-être que le vieux Freeman avait raison."
  },
  AvgDialog_18724_Content_15 = {
    Text = "Les Chasseurs de Crânes forment une organisation. Mais quel est leur véritable but ?"
  },
  AvgDialog_18724_Content_16 = {
    Text = "Têtes@2 Plus de têtes..."
  },
  AvgDialog_18724_Content_17 = {
    Text = "Un vent froid soudain souffla venant de derrière."
  },
  AvgDialog_18724_Content_18 = {
    Text = "Vous vous retournez, seulement pour voir le cadavre décapité se précipiter vers vous à une vitesse incroyable."
  },
  AvgDialog_18724_Content_19 = {Text = "?!"},
  AvgDialog_18724_Content_2 = {
    Text = "00:15, Cabane de Horla"
  },
  AvgDialog_18724_Content_20 = {
    Text = "Donnez-moi la tête@3 donne@1 tête@4"
  },
  AvgDialog_18724_Content_21 = {
    Text = "Vous vous écartez rapidement. Le cadavre brise le verre devant lui, disparaissant dans la vaste nuit."
  },
  AvgDialog_18724_Content_22 = {
    Text = "Une telle vitesse incroyable... Pourrait-il s'agir d'un Réveilleur du Royaume Ultra ?"
  },
  AvgDialog_18724_Content_23 = {
    Text = "Tout comme tu es perplexe, une forte odeur de narcisse t'enveloppe complètement."
  },
  AvgDialog_18724_Content_24 = {
    Text = "Une jupe violette passa rapidement à côté de vous, puis disparut sous vos yeux."
  },
  AvgDialog_18724_Content_25 = {
    Text = "Dame Daffodil... ?"
  },
  AvgDialog_18724_Content_26 = {
    Text = "Vite, rattrapez ! Ne laissez pas l'indice important s'échapper."
  },
  AvgDialog_18724_Content_3 = {
    Text = "Vous avez trouvé un coin tranquille et expliqué ce qui venait de se passer à Ramona."
  },
  AvgDialog_18724_Content_4 = {
    Text = "Bien sûr, passe la partie où tu as presque eu la gorge tranchée."
  },
  AvgDialog_18724_Content_5 = {Text = "新增"},
  AvgDialog_18724_Content_6 = {
    Text = "Je t'ai appelé <Red:35> fois depuis cet après-midi, mais il n'y a pas eu de réponse."
  },
  AvgDialog_18724_Content_7 = {
    Text = "Désolé, cela s'est produit si soudainement..."
  },
  AvgDialog_18724_Content_8 = {
    Text = "...Cela ne se reproduira pas."
  },
  AvgDialog_18724_Content_9 = {
    Text = "Les identités des victimes trouvées pendant la journée ont été confirmées.\nCarpenter Damon Mendes, 35 ans ; Jeune homme sans emploi Thomas Quillen, 23 ans."
  },
  AvgDialog_18725_Content_1 = {
    Text = "Un cadre photo à l'envers attire votre attention."
  },
  AvgDialog_18725_Content_10 = {
    Text = "<RedItalic: Il a bu dix bouteilles d'alcool dimanche, a perdu son emploi et sa femme.>"
  },
  AvgDialog_18725_Content_11 = {
    Text = "Quelqu'un fredonne doucement une comptine sans rythme."
  },
  AvgDialog_18725_Content_12 = {
    Text = "La mélodie sèche ressemble à une main humide et invisible caressant doucement les poils déjà dressés sur la nuque."
  },
  AvgDialog_18725_Content_13 = {
    Text = "<RedItalic:L'Ancien Freeman a pleuré et a bu encore onze bouteilles de liqueur lundi...>"
  },
  AvgDialog_18725_Content_14 = {
    Text = "Accompagnée du grincement des planches de bois, Harriet se tenait silencieusement devant le couloir faiblement éclairé."
  },
  AvgDialog_18725_Content_15 = {
    Text = "C'est exact, le vieux Freeman est mon mari."
  },
  AvgDialog_18725_Content_16 = {Text = "Quoi ?!"},
  AvgDialog_18725_Content_17 = {
    Text = "À ce moment-là, tout le monde pensait que j'étais morte, y compris mon mari."
  },
  AvgDialog_18725_Content_18 = {
    Text = "Plus tard, après une durée indéterminée, je suis revenu à la vie... mais quelque chose en moi avait changé."
  },
  AvgDialog_18725_Content_19 = {
    Text = "Vous restez silencieux, devinant déjà le reste de l'histoire."
  },
  AvgDialog_18725_Content_2 = {
    Text = "De la cuisine provenant le bruit du bouillonnement de l'eau ; Mme Harriet était encore occupée à l'intérieur."
  },
  AvgDialog_18725_Content_20 = {
    Text = "Les humains infectés par la dissolution souffrent de dommages mentaux irréversibles, entraînant diverses complications"
  },
  AvgDialog_18725_Content_21 = {
    Text = "Ce n'est pas surprenant que Lady Harriet ait terminé de cette façon."
  },
  AvgDialog_18725_Content_22 = {
    Text = "J'ai commencé à désirer des têtes, beaucoup de têtes... Alors je me suis faufilé dans un cimetière."
  },
  AvgDialog_18725_Content_23 = {
    Text = "Je me suis penché sur le corps de vieux Pinoco, utilisant une faux rouillée pour essayer de lui couper la tête.\nMais j'étais trop faible à ce moment-là, et je ne pouvais même pas maintenir la faux stable..."
  },
  AvgDialog_18725_Content_24 = {
    Text = "Et devinez qui j'ai rencontré ?"
  },
  AvgDialog_18725_Content_25 = {Text = "新增"},
  AvgDialog_18725_Content_26 = {
    Text = "J'ai rencontré mon mari."
  },
  AvgDialog_18725_Content_27 = {
    Text = "Il est devenu plus gros, plus vieux, et s'est transformé en ivrogne."
  },
  AvgDialog_18725_Content_28 = {
    Text = "Heh... Ce monde trouve toujours de nouvelles façons de tourmenter nos pauvres âmes."
  },
  AvgDialog_18725_Content_29 = {
    Text = "Il tenait sa boisson et me regardait comme un chien errant."
  },
  AvgDialog_18725_Content_3 = {
    Text = "Vous retournez délicatement le cadre de la photo."
  },
  AvgDialog_18725_Content_30 = {
    Text = "Il a ri tout le temps. Oui, je sais que je devais avoir l'air à la fois pitoyable et ridicule à l'époque."
  },
  AvgDialog_18725_Content_31 = {
    Text = "Mais il... ne me reconnaît pas du tout."
  },
  AvgDialog_18725_Content_32 = {
    Text = "...Alors, tu es le chasseur de crânes dont il a parlé."
  },
  AvgDialog_18725_Content_33 = {
    Text = "Harriet incline mécaniquement sa tête sur la droite, produisant un son « crépitant » provenant de son cou."
  },
  AvgDialog_18725_Content_34 = {
    Text = "Ouais. Même si je sais qu'il ne se souvient pas de moi, je ne peux m'empêcher de le regarder discrètement."
  },
  AvgDialog_18725_Content_35 = {
    Text = "Alors tu as entendu notre conversation, appris que je menais une enquête sur les meurtres, et décidé de me suivre et de me tendre une embuscade ?"
  },
  AvgDialog_18725_Content_36 = {Text = "新增"},
  AvgDialog_18725_Content_37 = {
    Text = "Vous êtes vraiment différent d'eux. J'ai tellement dit, et pourtant vous restez calme."
  },
  AvgDialog_18725_Content_38 = {
    Text = "Vous laissez échapper un soft soupir, regardant la porte verrouillée à côté de vous."
  },
  AvgDialog_18725_Content_39 = {
    Text = "Du sang rouge foncé suinte comme un sirop épais de la fissure de la porte, rampante lentement vers tes pieds."
  },
  AvgDialog_18725_Content_4 = {
    Text = "C'est une vieille photo de famille. Les visages de l'épouse et de l'enfant sont depuis longtemps flous, ne laissant que le mari debout à l'extrême gauche."
  },
  AvgDialog_18725_Content_40 = {
    Text = "Savais-tu..."
  },
  AvgDialog_18725_Content_41 = {
    Text = "Le sol, le plafond, les armoires... tout empeste le sang et la puanteur de la mort."
  },
  AvgDialog_18725_Content_42 = {
    Text = "Depuis le moment où je suis entré, je savais tout."
  },
  AvgDialog_18725_Content_5 = {
    Text = "Il se tient droit et détendu devant sa maison nouvellement construite, affichant un sourire rayonnant à la caméra."
  },
  AvgDialog_18725_Content_6 = {
    Text = "Vous contemplez son front et ses yeux quelque peu familiers, et une pensée ridicule traverse soudainement votre esprit."
  },
  AvgDialog_18725_Content_7 = {
    Text = "Le vieux Freeman... ?!"
  },
  AvgDialog_18725_Content_8 = {
    Text = "Pourrait-il être le mari de Mme Harriet ?"
  },
  AvgDialog_18725_Content_9 = {
    Text = "<RedItalic:L'Ancien Freeman, L'Ancien Freeman, le pauvre et fou ivrogne L'Ancien Freeman...>"
  },
  AvgDialog_18726_Content_1 = {
    Text = "Vous marchez plus profondément dans la ruelle, votre manteau déjà trempé par la pluie."
  },
  AvgDialog_18726_Content_10 = {
    Text = "Tapez, tapez, tapez."
  },
  AvgDialog_18726_Content_11 = {
    Text = "Le son de pas délibérés résonnait depuis la rue à l'extérieur de la ruelle, et une silhouette floue apparut sous le lampadaire."
  },
  AvgDialog_18726_Content_12 = {
    Text = "C'est dangereux ici, partez immédiatement —"
  },
  AvgDialog_18726_Content_13 = {
    Text = "C'est une femme."
  },
  AvgDialog_18726_Content_14 = {
    Text = "Elle se tient seule sous le lampadaire, tenant une tête bien ronde qui s'imbrique parfaitement dans le cou du corps décapité derrière vous."
  },
  AvgDialog_18726_Content_15 = {
    Text = "Du sang coule du cou, s'écoulant lentement le long des fissures des carreaux du sol."
  },
  AvgDialog_18726_Content_16 = {
    Text = "Reste là.\nQui es-tu ?"
  },
  AvgDialog_18726_Content_17 = {
    Text = "Les lampadaires ternes scintillent, émettant un bourdonnement électrique irritant."
  },
  AvgDialog_18726_Content_18 = {
    Text = "La femme lève la tête, et vous parvenez enfin à distinguer ses traits."
  },
  AvgDialog_18726_Content_19 = {Text = "新增"},
  AvgDialog_18726_Content_2 = {
    Text = "Du sang rouge foncé s'écoule du <Shadow>, étendant des tentacules menaçants, t'invitant silencieusement."
  },
  AvgDialog_18726_Content_20 = {
    Text = "<Gray:Daphne... Dame Delf?>"
  },
  AvgDialog_18726_Content_3 = {
    Text = "C'est calme ici ; on peut seulement entendre le bruit de la pluie, des pas et de la respiration."
  },
  AvgDialog_18726_Content_4 = {
    Text = "Ils ressemblent à un rythme de tambour chaotique, grandissant plus vite et plus fort, jusqu'à ce que vous atteigniez la fin de la ruelle."
  },
  AvgDialog_18726_Content_5 = {
    Text = "Le cadavre gonflé gît inanimé dans le tas d'ordures, jeté négligemment."
  },
  AvgDialog_18726_Content_6 = {
    Text = "L'incision sur le cou est floue, avec du sang rouge foncé jaillissant des vaisseaux."
  },
  AvgDialog_18726_Content_7 = {
    Text = "Vous n'avez pas besoin de le toucher pour savoir que le sang est chaud."
  },
  AvgDialog_18726_Content_8 = {
    Text = "Tête manquante, blessures dentelées sur le cou..."
  },
  AvgDialog_18726_Content_9 = {
    Text = "C'est \"Chasseur de Crânes.\""
  },
  AvgDialog_18727_Content_1 = {
    Text = "Sérendipité"
  },
  AvgDialog_18727_Content_10 = {
    Text = "Si elle n'a pas menti ou mal jugé, alors oui."
  },
  AvgDialog_18727_Content_11 = {
    Text = "<Blue:Avant-garde> est arrivé à Rini Town il y a une semaine et a détecté des signes d'un Argent actif sur le site de la mort."
  },
  AvgDialog_18727_Content_12 = {
    Text = "Y compris les trois dernières, il s'agit du huitième <Blue:Événement Prédateur Cérébral> dans la Ville de Rennie."
  },
  AvgDialog_18727_Content_13 = {
    Text = "Chasseur de crâne ? C'est ce que les gens ici appellent le meurtrier ?"
  },
  AvgDialog_18727_Content_14 = {
    Text = "Très vivant, n'est-ce pas ? Grâce à lui, personne n'ose sortir après la tombée de la nuit ici."
  },
  AvgDialog_18727_Content_15 = {
    Text = "Vous contemplez la rue désolée devant vous."
  },
  AvgDialog_18727_Content_16 = {
    Text = "À 20h, toutes les portes et fenêtres voisines sont hermétiquement verrouillées. La peur s'infiltre à travers les fenêtres noirâtres, enveloppant silencieusement les environs."
  },
  AvgDialog_18727_Content_17 = {
    Text = "À part quelques aboiements de chien prolongés, il fait étrangement silence ici."
  },
  AvgDialog_18727_Content_18 = {Text = "Tic-tac..."},
  AvgDialog_18727_Content_19 = {
    Text = "Hmm, est-ce qu'il pleut ?"
  },
  AvgDialog_18727_Content_2 = {
    Text = "Belen Stock, 46 ans, est décédée chez elle dans la cuisine le 12 septembre.\n<Red: Tête manquante>, corps intact excepté une coupure déchiquetée au cou."
  },
  AvgDialog_18727_Content_20 = {
    Text = "Une belle pluie fraîche tombe du ciel nocturne, jetant un voile blanc devant vous."
  },
  AvgDialog_18727_Content_21 = {
    Text = "J'entends de la pluie de ton côté. As-tu un parapluie ?"
  },
  AvgDialog_18727_Content_22 = {
    Text = "<Shake:Oh non. Tu es toujours celui qui apporte un parapluie, alors...>"
  },
  AvgDialog_18727_Content_23 = {
    Text = "Il semble que je dois encore m'habituer à la vie sans toi."
  },
  AvgDialog_18727_Content_24 = {Text = "新增"},
  AvgDialog_18727_Content_25 = {
    Text = "Désolé, je ne pouvais pas venir avec vous cette fois-ci."
  },
  AvgDialog_18727_Content_26 = {
    Text = "Mademoiselle Poupée insiste pour que je reste faire des recherches sur la Dissolution soi-disant \"importantes\" avec elle..."
  },
  AvgDialog_18727_Content_27 = {
    Text = "<Small:Ramona, pourrais-tu me passer l'échantillon d'argent sur l'étagère trois de la cinquième rangée, code SI-3007...>"
  },
  AvgDialog_18727_Content_28 = {Text = "新增"},
  AvgDialog_18727_Content_29 = {
    Text = "Prenez soin de vous, %player%. En ce qui concerne l'hébergement... <Blue:Miss Horla> s'occupera de tout."
  },
  AvgDialog_18727_Content_3 = {
    Text = "Dwight Williams, 56 ans, est décédé à l'intersection de Deman Street le 13 septembre.\n<Red:Head Missing>, corps intact avec une coupure irrégulière au cou."
  },
  AvgDialog_18727_Content_30 = {
    Text = "Mademoiselle Horla ? Pas étonnant qu'on ne la voit que rarement à l'école ; elle vit à l'extérieur ?"
  },
  AvgDialog_18727_Content_31 = {
    Text = "Mythag n'est pas un camp à sens unique."
  },
  AvgDialog_18727_Content_32 = {
    Text = "Les Éveilleurs à faible risque peuvent partir en vacances, rester pour la nuit ou rendre visite à leur famille.\nLa condition est simple : faire une demande à l'avance et éviter de causer des problèmes."
  },
  AvgDialog_18727_Content_33 = {
    Text = "Uh... Donc mademoiselle Horla participera également à l'enquête ?"
  },
  AvgDialog_18727_Content_34 = {
    Text = "Tous les Réveilleurs ne sont pas intéressés par les missions de terrain. Si tu penses que c'est nécessaire, demande-lui son avis."
  },
  AvgDialog_18727_Content_35 = {
    Text = "La situation actuelle est stable et gérable, pas besoin de—"
  },
  AvgDialog_18727_Content_36 = {Text = "Chhh—"},
  AvgDialog_18727_Content_37 = {
    Text = "Soudain, le bruit du Caro éclaboussant provenait de l'allée devant, suivi de pas chaotiques, brisant abruptement le silence de la nuit."
  },
  AvgDialog_18727_Content_38 = {Text = "?!"},
  AvgDialog_18727_Content_39 = {
    Text = "En ce moment, ce son... Pourrait-il s'agir de...?"
  },
  AvgDialog_18727_Content_4 = {
    Text = "Décedé No. 012, identité et âge inconnus, décédé près du lac Knerl dans le nord au petit matin du 16 septembre..."
  },
  AvgDialog_18727_Content_40 = {
    Text = "Suivons et jetons un coup d'œil. N'oubliez pas de rester en contact."
  },
  AvgDialog_18727_Content_41 = {
    Text = "Que la Clé d'argent éclaire mon chemin."
  },
  AvgDialog_18727_Content_5 = {
    Text = [[
20:00, Rue de Norwich
Ville de Renny]]
  },
  AvgDialog_18727_Content_6 = {
    Text = "Tête manquante, cicatrices dentelées..."
  },
  AvgDialog_18727_Content_7 = {
    Text = "Et tous sont morts soit en sortant seul, soit chez eux."
  },
  AvgDialog_18727_Content_8 = {
    Text = "De plus, une semaine après la mort de Dwight Williams, sa femme a déclaré l'avoir vu courir rapidement dans la forêt."
  },
  AvgDialog_18727_Content_9 = {
    Text = "...Résucité ?"
  },
  AvgDialog_18764_Content_1 = {
    Text = "Non, ne fais pas ça..."
  },
  AvgDialog_18764_Content_10 = {
    Text = "Tousse, tousse... Toi, comment as-tu pu tricher !"
  },
  AvgDialog_18764_Content_11 = {
    Text = "<SmallShake:Ce n›est qu›un jeu de devinettes, qu›est-ce qui t›inquiète tant...>"
  },
  AvgDialog_18764_Content_12 = {
    Text = "Où est la sortie du labyrinthe ?"
  },
  AvgDialog_18764_Content_13 = {
    Text = "Héhé, curieux ? Alors mets-toi à genoux, présente-moi tes excuses correctement, et ensuite..."
  },
  AvgDialog_18764_Content_14 = {
    Text = "Vous levez lentement votre main."
  },
  AvgDialog_18764_Content_15 = {
    Text = "<Shake:Attends, attends ! Je veux dire...>"
  },
  AvgDialog_18764_Content_16 = {
    Text = "La fille ouvrit la bouche et baissa la tête, frustrée."
  },
  AvgDialog_18764_Content_17 = {
    Text = "En fait... je ne sais pas non plus. Je suis emprisonnée ici depuis près de mille ans..."
  },
  AvgDialog_18764_Content_18 = {
    Text = "À part dormir et rêvasser, gérer ma progéniture me rend folle d›ennui !"
  },
  AvgDialog_18764_Content_19 = {Text = "新增"},
  AvgDialog_18764_Content_20 = {
    Text = "Tu n›es pas la maîtresse du labyrinthe ? Comment pourrais-tu ne pas savoir où se trouve la sortie ?"
  },
  AvgDialog_18764_Content_21 = {
    Text = "<SmallShake:Tu devrais demander à la personne qui m›a jetée ici. Comment pourrais-je savoir ce qu›elle a en tête...>"
  },
  AvgDialog_18764_Content_22 = {
    Text = "Comment est-ce possible...?"
  },
  AvgDialog_18764_Content_23 = {
    Text = "Alors, disons, hypothétiquement parlant —"
  },
  AvgDialog_18764_Content_24 = {
    Text = "Ceux qui entrent dans le labyrinthe ne sont pas des entités physiques mais existent sous une forme d›idéologie."
  },
  AvgDialog_18764_Content_25 = {
    Text = "Est-ce qu'il pourrait, euh, genre... ignorer les règles de ce labyrinthe ?"
  },
  AvgDialog_18764_Content_26 = {
    Text = "Agrippa vous a lancé un regard étrange."
  },
  AvgDialog_18764_Content_27 = {
    Text = "Bien sûr que non."
  },
  AvgDialog_18764_Content_28 = {
    Text = "Tu veux deviner pourquoi tu vois autant de visages et de lieux familiers dans le labyrinthe ?"
  },
  AvgDialog_18764_Content_29 = {
    Text = "Une Illusion ? Non, c'est la mémoire..."
  },
  AvgDialog_18764_Content_3 = {
    Text = "Vous avez enfin éliminé la dernière « Charlotte »."
  },
  AvgDialog_18764_Content_30 = {
    Text = "Agrippa secoua la tête."
  },
  AvgDialog_18764_Content_31 = {
    Text = "Ni l'un ni l'autre. Pour être précis, c'est la <Yellow:conscience>."
  },
  AvgDialog_18764_Content_32 = {
    Text = "<Yellow:Seulement votre conscience est piégée dans le labyrinthe.>"
  },
  AvgDialog_18764_Content_4 = {
    Text = "Le Tombeau de la Clé s›estompe progressivement, et vous vous retrouvez à votre point de départ."
  },
  AvgDialog_18764_Content_5 = {
    Text = "Sors de là, je sais où tu es."
  },
  AvgDialog_18764_Content_6 = {
    Text = "Un bourdonnement tremblant résonne depuis les profondeurs souterraines, suivi par le sol qui se fissure progressivement."
  },
  AvgDialog_18764_Content_7 = {Text = "BOUM !!"},
  AvgDialog_18764_Content_8 = {
    Text = "Pfft... beurk beurk beurk !!"
  },
  AvgDialog_18764_Content_9 = {
    Text = "Agrippa jaillit soudainement du sol, couverte de poussière."
  },
  AvgDialog_18765_Content_1 = {
    Text = "Esprit–ruche"
  },
  AvgDialog_18765_Content_10 = {
    Text = "Tu as fait les devoirs de cette semaine ? L'examen d'« Introduction à la Fusion » approche. Où en sont tes révisions ?"
  },
  AvgDialog_18765_Content_11 = {
    Text = "Ramona ?! Non, je n'ai pas... attendez..."
  },
  AvgDialog_18765_Content_12 = {
    Text = "%player%, tu avais 5 minutes de retard en cours aujourd'hui. Ton retard total ce mois–ci a atteint 30 minutes et 15 secondes."
  },
  AvgDialog_18765_Content_13 = {
    Text = "Viens à mon bureau après les cours."
  },
  AvgDialog_18765_Content_14 = {Text = "—!!"},
  AvgDialog_18765_Content_15 = {
    Text = "Pfft. <Big:Hahahahaha !>"
  },
  AvgDialog_18765_Content_16 = {
    Text = "Tu as peur, hein ? Tu devrais vraiment te regarder dans un miroir et voir de quoi tu as l'air maintenant."
  },
  AvgDialog_18765_Content_17 = {Text = "新增"},
  AvgDialog_18765_Content_18 = {
    Text = "Où as-tu appris ces... tours de transformation ?"
  },
  AvgDialog_18765_Content_19 = {
    Text = "Tu as vu le dossier d'Agrippa dans la Bibliothèque des Éveilleurs ; il ne mentionnait rien à propos de « transformation »."
  },
  AvgDialog_18765_Content_2 = {Text = "%player%"},
  AvgDialog_18765_Content_20 = {
    Text = "Étudier ? Je suis le maître de ce labyrinthe. Dans mon domaine, je fais ce que bon me semble."
  },
  AvgDialog_18765_Content_21 = {
    Text = "Ne te contente pas d'une seule transformation... Je peux t'en montrer dix, voire une centaine."
  },
  AvgDialog_18765_Content_22 = {
    Text = "Après avoir parlé, Agrippa disparut à nouveau."
  },
  AvgDialog_18765_Content_23 = {
    Text = "En un rien de temps, une, deux... d'autres Charlotte apparaissent devant vous."
  },
  AvgDialog_18765_Content_24 = {
    Text = "Devinez lequel est le vrai moi, hehe..."
  },
  AvgDialog_18765_Content_25 = {
    Text = "Bouhouhou... Quelle Charlotte est Agrippa ?"
  },
  AvgDialog_18765_Content_26 = {
    Text = "Seulement une fois, une seule chance..."
  },
  AvgDialog_18765_Content_27 = {
    Text = "D'innombrables voix perçantes s'entremêlent en une mélodie chaotique, persistant dans votre esprit."
  },
  AvgDialog_18765_Content_28 = {
    Text = "Allez... Allez-vous-en... !!"
  },
  AvgDialog_18765_Content_29 = {
    Text = "Vous prenez une profonde inspiration et parvenez enfin à stabiliser votre esprit."
  },
  AvgDialog_18765_Content_3 = {
    Text = "Charlotte, comment es-tu arrivée ici ?"
  },
  AvgDialog_18765_Content_30 = {
    Text = "Désolé. Vous êtes toutes identiques ; je ne peux pas faire la différence."
  },
  AvgDialog_18765_Content_31 = {
    Text = "Hein ? Tu abandonnes déjà ? Comme c'est ennuyeux."
  },
  AvgDialog_18765_Content_33 = {
    Text = "La seconde suivante, « Charlotte » fut projetée au sol.\nVous vous frottâtes les tempes et déclarâtes calmement —"
  },
  AvgDialog_18765_Content_34 = {
    Text = "Mais ce n'est pas grave."
  },
  AvgDialog_18765_Content_35 = {
    Text = "Je peux toutes vous mettre à terre et vous interroger une par une."
  },
  AvgDialog_18765_Content_4 = {
    Text = "« Charlotte » tord la tête, émettant un bourdonnement glaçant du fond de sa gorge."
  },
  AvgDialog_18765_Content_5 = {
    Text = "<Shake:Héhé, surpris ? Ton soi–disant ami est depuis longtemps devenu mon descendant !>"
  },
  AvgDialog_18765_Content_6 = {
    Text = "Cette voix... C'est toi, Agrippa ?"
  },
  AvgDialog_18765_Content_7 = {
    Text = "C'est touchant que tu te souviennes encore de ma voix.\nAttends, laisse–moi te montrer quelque chose d'incroyable !"
  },
  AvgDialog_18765_Content_8 = {
    Text = "Un rire étouffé s'échappa de la gorge de Charlotte, puis elle tordit le cou, changeant instantanément d'apparence."
  },
  AvgDialog_18765_Content_9 = {
    Text = "%player%, tu chipes encore des cupcakes !"
  },
  AvgDialog_18766_Content_1 = {Text = "Porte"},
  AvgDialog_18766_Content_10 = {
    Text = "Êtes-vous prêt, @1? Poussons ensemble."
  },
  AvgDialog_18766_Content_11 = {Text = "Creak—"},
  AvgDialog_18766_Content_12 = {Text = "<Big:!!!>"},
  AvgDialog_18766_Content_13 = {
    Text = "Où... est–ce qu›on est...?"
  },
  AvgDialog_18766_Content_14 = {
    Text = "C›est ici que tu resteras bien sagement pour le reste de ta vie."
  },
  AvgDialog_18766_Content_15 = {
    Text = "La fille est assise sur la plateforme creuse, les mains en coupe sur ses joues, sa jambe droite se balançant nonchalamment tandis qu›elle sourit."
  },
  AvgDialog_18766_Content_16 = {
    Text = "Bienvenue dans mon labyrinthe."
  },
  AvgDialog_18766_Content_17 = {
    Text = "Tu dormais si profondément ; j›étais sur le point de te faire avaler quelques insectes pour te raviver l›esprit."
  },
  AvgDialog_18766_Content_18 = {
    Text = "<LightGray: Agrippa...?>"
  },
  AvgDialog_18766_Content_19 = {
    Text = "Tu baisses les yeux sur ta tenue inconnue et réalises que tu es entrée dans un rêve une fois de plus."
  },
  AvgDialog_18766_Content_2 = {
    Text = "On dit que dans «Son» labyrinthe, ce qui se perd, ce n'est pas seulement la direction."
  },
  AvgDialog_18766_Content_20 = {
    Text = "Cette fois, tu as presque perdu tous les souvenirs de l›hôte d›origine.\nQui est–elle ? D›où vient–elle ?"
  },
  AvgDialog_18766_Content_21 = {
    Text = "Vous ne savez rien."
  },
  AvgDialog_18766_Content_22 = {
    Text = "<Shake:Que se passe–t–il... La propriétaire d›origine ? Non, qui suis–je...>"
  },
  AvgDialog_18766_Content_23 = {
    Text = "Bon, arrête de réfléchir. Tu ne te souviendras de rien."
  },
  AvgDialog_18766_Content_24 = {
    Text = "Même après 1 jour, 100 jours, ou 1000 jours, ton esprit restera aussi pur que celui d›un nouveau–né."
  },
  AvgDialog_18766_Content_25 = {
    Text = "Maintenant, je vais te donner deux choix."
  },
  AvgDialog_18766_Content_26 = {
    Text = "<Red:Une personne : Passe un contrat avec moi et deviens mon enfant.>"
  },
  AvgDialog_18766_Content_27 = {
    Text = "<Red:Deux : Meurs de faim dans le labyrinthe, puis deviens ma progéniture.>"
  },
  AvgDialog_18766_Content_28 = {
    Text = "Agrippa clarifie habilement la situation pour toi et te présente des options, comme si ce processus avait été répété d›innombrables fois."
  },
  AvgDialog_18766_Content_29 = {
    Text = "Descendants ? Qu'est-ce que c'est ?"
  },
  AvgDialog_18766_Content_3 = {
    Text = "Nom, ville natale, amant... Tout ce qui est important et sans importance sera laissé derrière."
  },
  AvgDialog_18766_Content_30 = {
    Text = "Rassure–toi, c›est non toxique, indolore et inoffensif. Quant aux effets secondaires ? Tu ne remarqueras même pas leur présence."
  },
  AvgDialog_18766_Content_31 = {
    Text = "Alors, comparé à ces dieux maléfiques qui exigent constamment que vous offriez votre vie en Offrande ou que vous tuiez vos proches, ne diriez-vous pas que je suis bien plus doux ?"
  },
  AvgDialog_18766_Content_32 = {Text = "新增"},
  AvgDialog_18766_Content_33 = {
    Text = "Maintenant, je vous donne trois secondes pour choisir. Signer le contrat ou mourir de faim ?"
  },
  AvgDialog_18766_Content_34 = {Text = "Trois —"},
  AvgDialog_18766_Content_35 = {Text = "Deux—"},
  AvgDialog_18766_Content_36 = {
    Text = "Très bien, j›ai pris ma décision."
  },
  AvgDialog_18766_Content_37 = {Text = "Euh... ?"},
  AvgDialog_18766_Content_38 = {
    Text = "Vous êtes décisif... pas mal. Alors, dites-moi votre choix."
  },
  AvgDialog_18766_Content_39 = {
    Text = "Vous hochez la tête et reculez discrètement votre pied droit."
  },
  AvgDialog_18766_Content_4 = {
    Text = "Désormais, vous n'avez plus qu'une seule identité : <Red:Sa Progéniture>."
  },
  AvgDialog_18766_Content_40 = {
    Text = "Mon choix est—"
  },
  AvgDialog_18766_Content_41 = {
    Text = "Vous vous êtes retourné sans hésiter et avez foncé à toute vitesse."
  },
  AvgDialog_18766_Content_42 = {
    Text = "<BigShake:Courez !!>"
  },
  AvgDialog_18766_Content_43 = {
    Text = "Très, très longtemps après..."
  },
  AvgDialog_18766_Content_44 = {
    Text = "Huff... huff..."
  },
  AvgDialog_18766_Content_45 = {
    Text = "Vous courez le long du couloir jusqu›à ce qu›une porte vous barre le chemin."
  },
  AvgDialog_18766_Content_46 = {
    Text = "Le Musée de cire ? Encore..."
  },
  AvgDialog_18766_Content_47 = {
    Text = "Si je me souviens bien, c'est la 23e fois que je le vois."
  },
  AvgDialog_18766_Content_48 = {
    Text = "Oui, il y a d›innombrables portes menant à d›innombrables espaces."
  },
  AvgDialog_18766_Content_49 = {
    Text = "Elles apparaissent devant vous de manière si répétée et si fréquente que cela pourrait rendre fou même l›Enquêteur le plus calme."
  },
  AvgDialog_18766_Content_5 = {
    Text = "<Shake:Enfant, héritier?>"
  },
  AvgDialog_18766_Content_50 = {
    Text = "Vous poussez la porte et continuez dans le couloir."
  },
  AvgDialog_18766_Content_51 = {
    Text = "Encore ce couloir... 15 fois."
  },
  AvgDialog_18766_Content_52 = {
    Text = "Vous avez instinctivement touché les boutons de manchette en argent incrustés dans votre manche."
  },
  AvgDialog_18766_Content_53 = {
    Text = "L'ancien emblème scolaire de Mizag... Il semble que je sois devenue une prédécesseure du passé cette fois ?"
  },
  AvgDialog_18766_Content_54 = {
    Text = "Mais comment est–elle entrée dans le labyrinthe ?"
  },
  AvgDialog_18766_Content_55 = {
    Text = "Tandis que vous réfléchissez, une autre porte bloque votre chemin."
  },
  AvgDialog_18766_Content_56 = {
    Text = "Vous vous tenez maintenant devant cette porte, @1. Ouvrez–la."
  },
  AvgDialog_18766_Content_57 = {
    Text = "Qui parle ?!"
  },
  AvgDialog_18766_Content_58 = {
    Text = "Tête... ça fait mal. Sont-ce les souvenirs de Senpai ?"
  },
  AvgDialog_18766_Content_59 = {
    Text = "Respirez profondément, %player%. Videz votre esprit..."
  },
  AvgDialog_18766_Content_6 = {
    Text = "Oui. La progéniture envahit le labyrinthe comme une marée blafarde, affluant de toutes les directions."
  },
  AvgDialog_18766_Content_60 = {
    Text = "Vous vous forcez à vous calmer, tournez la poignée en laiton et tirez doucement la porte."
  },
  AvgDialog_18766_Content_61 = {
    Text = "...Tombe de la Clé ?"
  },
  AvgDialog_18766_Content_62 = {
    Text = "À travers la brume, vous remarquez une silhouette à la fois familière et étrange."
  },
  AvgDialog_18766_Content_63 = {
    Text = "Charlotte... <Big:Charlotte !>"
  },
  AvgDialog_18766_Content_64 = {
    Text = "Vous vous souvenez de la fille nommée Charlotte. C'était l'amie qui avait conduit « vous » dans le labyrinthe."
  },
  AvgDialog_18766_Content_65 = {
    Text = "<Big:Attends-moi, Charlotte !>"
  },
  AvgDialog_18766_Content_66 = {
    Text = "Vous vous précipitez en avant et attrapez le poignet de Charlotte."
  },
  AvgDialog_18766_Content_67 = {
    Text = "À l'instant où nos peaux sont entrées en contact, d'innombrables fragments chaotiques ont traversé mon esprit."
  },
  AvgDialog_18766_Content_68 = {
    Text = "Ouvrez la porte, @1."
  },
  AvgDialog_18766_Content_69 = {
    Text = "<Shake:Non, je–je viens de me rappeler que je n'ai pas fini mes devoirs. Je veux —>"
  },
  AvgDialog_18766_Content_7 = {
    Text = "Les Entrées du labyrinthe sont partout : dans les murs, dans les égouts, et même là où nous sommes maintenant..."
  },
  AvgDialog_18766_Content_70 = {
    Text = "<Big:Ahhh !!>"
  },
  AvgDialog_18766_Content_71 = {
    Text = "<Shake:Charlotte, ton visage...>"
  },
  AvgDialog_18766_Content_72 = {
    Text = "Porte... Porte..."
  },
  AvgDialog_18766_Content_73 = {
    Text = "@1 Porte @2 Ouvrir @4"
  },
  AvgDialog_18766_Content_74 = {
    Text = "<RedBig:Ouvrir la porte...>"
  },
  AvgDialog_18766_Content_75 = {
    Text = "Je vois. C'est donc toi qui as piégé « moi » dans le labyrinthe..."
  },
  AvgDialog_18766_Content_76 = {
    Text = "Instinctivement, vous avez lâché le poignet de Charlotte et reculé de quelques pas."
  },
  AvgDialog_18766_Content_77 = {
    Text = "La brume se dissipe peu à peu. Avec difficulté, Charlotte se retourne et vous regarde avec tristesse."
  },
  AvgDialog_18766_Content_78 = {
    Text = "...@4 Porte@4@1"
  },
  AvgDialog_18766_Content_79 = {
    Text = "—Avec ses orbites d'un noir d'encre."
  },
  AvgDialog_18766_Content_8 = {
    Text = "La <Blue:Bibliothèque municipale> derrière la porte cachée souterraine."
  },
  AvgDialog_18766_Content_9 = {
    Text = "<Shake:Je n'arrive pas à croire qu'un tel endroit existe vraiment... Les légendes sont vraies...>"
  },
  AvgDialog_18767_Content_1 = {
    Text = "La fin du labyrinthe"
  },
  AvgDialog_18767_Content_10 = {
    Text = "Chut... Ferme les yeux, vide ton esprit, et ne pense à rien."
  },
  AvgDialog_18767_Content_11 = {
    Text = "Ne fais rien..."
  },
  AvgDialog_18767_Content_12 = {Text = "Hmm !!"},
  AvgDialog_18767_Content_13 = {
    Text = "Ma tête est sur le point d›exploser... Je ferais mieux de ne pas utiliser cette méthode trop souvent..."
  },
  AvgDialog_18767_Content_14 = {
    Text = "<Shake:Hors de mon chemin, vous tous !>"
  },
  AvgDialog_18767_Content_15 = {
    Text = "Quiconque ose faire du mal à ma famille, je serai le premier à tuer ce porc !!"
  },
  AvgDialog_18767_Content_16 = {
    Text = "Une lame tremblante se presse instantanément contre ta gorge."
  },
  AvgDialog_18767_Content_17 = {Text = "...?"},
  AvgDialog_18767_Content_18 = {
    Text = "Entrée dans le rêve réussie — mais pas de la manière que tu imaginais."
  },
  AvgDialog_18767_Content_19 = {
    Text = "Devant toi se tient une foule dense d›esclaves torse nu. Leur docilité habituelle a depuis longtemps disparu, remplacée par une haine brûlante dans leurs yeux."
  },
  AvgDialog_18767_Content_2 = {
    Text = "Tu veux dire que tu peux infiltrer mon esprit et changer le passé ?"
  },
  AvgDialog_18767_Content_20 = {
    Text = "Face à la menace d›Agrippa, ils se sont d›abord tus, puis ont éclaté de rire."
  },
  AvgDialog_18767_Content_21 = {
    Text = "Pfft. Hahahaha !"
  },
  AvgDialog_18767_Content_22 = {
    Text = "Eh bien, notre petite princesse a du courage !"
  },
  AvgDialog_18767_Content_23 = {
    Text = "Heh. Vous ne me croyez pas, n›est-ce pas... ?"
  },
  AvgDialog_18767_Content_24 = {
    Text = "Un coup de lame rapide, et votre cou est instantanément envahi par la douleur."
  },
  AvgDialog_18767_Content_25 = {
    Text = "Hmm ! C›est du sérieux !!"
  },
  AvgDialog_18767_Content_26 = {
    Text = "<Big:Taisez-vous !> Vous êtes clairement de mèche avec eux. C›est vous qui avez volé la clé de ma maison et le contrat de servitude !"
  },
  AvgDialog_18767_Content_27 = {Text = "...?"},
  AvgDialog_18767_Content_28 = {
    Text = "Et vous tous ! Si quelqu›un rit encore, je ferai une autre entaille sur le cou de {Male=his,Female=her} !"
  },
  AvgDialog_18767_Content_29 = {
    Text = "Pose le couteau, Agrippa... <Big:Cours !>"
  },
  AvgDialog_18767_Content_3 = {
    Text = "Si tu es vraiment si puissant, comment ai–je réussi à te piéger ?"
  },
  AvgDialog_18767_Content_31 = {
    Text = "Le fouet frappa violemment la femme, la rendant inconsciente avant qu›elle ne puisse émettre un son."
  },
  AvgDialog_18767_Content_32 = {
    Text = "<Big:Mère!!>"
  },
  AvgDialog_18767_Content_33 = {
    Text = "Range tes pitreries ridicules ; nous ne sommes plus tes esclaves."
  },
  AvgDialog_18767_Content_34 = {
    Text = "Comment n›as-tu pas pensé à ce jour quand tu faisais ta fière sur le terrain d›entraînement à l›époque ?"
  },
  AvgDialog_18767_Content_35 = {
    Text = "Ouvre les yeux et regarde bien, « Petite Princesse ». Regarde comment nous allons t›humilier..."
  },
  AvgDialog_18767_Content_36 = {
    Text = "<Shake:Lâches, une bande de lâches ! Comment osez-vous...>"
  },
  AvgDialog_18767_Content_37 = {
    Text = "<Shake:C›est moi qui vous ai maltraités, pas eux... Non, j›ai été trop stupide. Je n›aurais pas dû vous traiter ainsi...>"
  },
  AvgDialog_18767_Content_38 = {
    Text = "<Shake:Prenez-vous-en à moi, faites ce que vous voulez ! Seulement laissez ma mère partir...>"
  },
  AvgDialog_18767_Content_39 = {
    Text = "La fille était déjà si paniquée qu›elle ne pouvait plus parler de manière cohérente, sa dague tremblant violemment et manquant de glisser de sa main."
  },
  AvgDialog_18767_Content_4 = {
    Text = "Ahem... Pour être précis, c'est l'influence, pas le changement."
  },
  AvgDialog_18767_Content_40 = {
    Text = "Vous laissez échapper un léger soupir et prenez doucement la dague de sa main."
  },
  AvgDialog_18767_Content_41 = {
    Text = "N'aie pas peur, Agrippa. Je vais t'aider."
  },
  AvgDialog_18767_Content_42 = {
    Text = "Aidez-moi ? N'êtes-vous pas..."
  },
  AvgDialog_18767_Content_43 = {
    Text = "Vous vous tenez devant Agrippa, regardant directement les esclaves face à vous."
  },
  AvgDialog_18767_Content_44 = {
    Text = "Très bien, la récréation est terminée.\nVous avez obtenu ce que vous vouliez, alors vous pouvez partir maintenant."
  },
  AvgDialog_18767_Content_45 = {
    Text = "Hé, y en a un qui joue au chef et nous fait la leçon."
  },
  AvgDialog_18767_Content_46 = {
    Text = "Cress, tu n'es pas censé être de notre côté ?"
  },
  AvgDialog_18767_Content_47 = {
    Text = "Vous secouez la tête."
  },
  AvgDialog_18767_Content_48 = {
    Text = "J'ai toujours respecté votre cause de résistance, mais personne n'a le droit de tuer des innocents."
  },
  AvgDialog_18767_Content_49 = {
    Text = "\"Innocent\"...?"
  },
  AvgDialog_18767_Content_5 = {
    Text = "Ne te sous–estime pas ; ton labyrinthe est bien plus complexe que je ne le pensais..."
  },
  AvgDialog_18767_Content_50 = {
    Text = "Héhé, ce type nous a complètement trahis. Inutile de perdre davantage de mots."
  },
  AvgDialog_18767_Content_51 = {
    Text = "<Big:Tuez-le !>"
  },
  AvgDialog_18767_Content_6 = {
    Text = "Agrippa te regarde avec suspicion."
  },
  AvgDialog_18767_Content_7 = {
    Text = "D›accord, de toute façon il n›y a pas d›autre solution.\nQue dois–je faire ?"
  },
  AvgDialog_18767_Content_8 = {
    Text = "Tu essaies de te remémorer ton état à chaque fois que tu entres dans un rêve, en prenant doucement la main d›Agrippa."
  },
  AvgDialog_18767_Content_9 = {
    Text = "Hé, toi ! Tu essaies de profiter de moi ?"
  },
  AvgDialog_18768_Content_1 = {
    Text = "Tousse... Tousse..."
  },
  AvgDialog_18768_Content_10 = {
    Text = "Le son lointain d'un cor grave vous parvient ; les rebelles sont toujours à votre poursuite."
  },
  AvgDialog_18768_Content_11 = {
    Text = "Vous et Agrippa courez main dans la main sous le ciel d'un noir d'encre."
  },
  AvgDialog_18768_Content_12 = {
    Text = "Sa famille n'est pas loin de vous. Poussés par la peur et l'espoir, ils courent vers un horizon sans fin visible."
  },
  AvgDialog_18768_Content_13 = {
    Text = ": Qui êtes-vous ? Pourquoi m'avez-vous sauvé ?"
  },
  AvgDialog_18768_Content_14 = {
    Text = "Hmm... pour être précis, c›est pour me sauver moi-même."
  },
  AvgDialog_18768_Content_15 = {
    Text = "Oh... quelle que soit la raison, tu... as fait du bon travail."
  },
  AvgDialog_18768_Content_16 = {
    Text = "Quand on sera secourus, je te donnerai tout l›argent et les bijoux que j›ai mis de côté au fil des années."
  },
  AvgDialog_18768_Content_17 = {
    Text = "Vous n›avez pas pu vous empêcher de rire."
  },
  AvgDialog_18768_Content_18 = {
    Text = "Je n›ai pas besoin de ton argent. Cependant... si tu souhaites me remercier, j›ai une requête."
  },
  AvgDialog_18768_Content_19 = {
    Text = "Dis-moi, je suis sûre que je peux le faire."
  },
  AvgDialog_18768_Content_2 = {
    Text = "Par respect pour le passé, les frères se sont abstenus d'utiliser la force létale."
  },
  AvgDialog_18768_Content_20 = {
    Text = "Une étoile filante traverse le ciel nocturne — c›est le moment parfait pour faire un vœu."
  },
  AvgDialog_18768_Content_21 = {
    Text = "Ma requête est simple. Continue de sourire et souviens-toi de ce que tu ressens en ce moment."
  },
  AvgDialog_18768_Content_22 = {
    Text = "Les sentiments actuels ? Hmm... Heureuse, soulagée, inquiète ? Lequel tu veux dire !"
  },
  AvgDialog_18768_Content_23 = {
    Text = "Comme tu voudras. Je suis curieux de savoir vers quel Agrippa ils me mèneront."
  },
  AvgDialog_18768_Content_24 = {Text = "?"},
  AvgDialog_18768_Content_25 = {
    Text = "<SmallShake:Ce type est quelqu›un de bien, mais il parle un peu bizarrement...>"
  },
  AvgDialog_18768_Content_26 = {
    Text = "Le son des cors finit par s›estomper, et la tranquillité de la nuit revint."
  },
  AvgDialog_18768_Content_27 = {
    Text = "Enfin... c'est terminé."
  },
  AvgDialog_18768_Content_28 = {
    Text = "La jeune fille gravit le sommet de la dune en quelques pas rapides, serra les poings et cria en direction de l›endroit où le cor avait disparu."
  },
  AvgDialog_18768_Content_29 = {
    Text = "Vous ne vous y attendiez pas, bande de @2, j›ai tenu jusqu›au bout !"
  },
  AvgDialog_18768_Content_3 = {
    Text = "Puisque tu insistes pour les aider, ne nous reproche pas d'être impolis —"
  },
  AvgDialog_18768_Content_30 = {
    Text = "Hahaha, @2 !"
  },
  AvgDialog_18768_Content_31 = {
    Text = "<Shake:Agrippa ! Madame, madame... !>"
  },
  AvgDialog_18768_Content_32 = {
    Text = "J›entends pas !!!"
  },
  AvgDialog_18768_Content_33 = {
    Text = "Au diable les bonnes manières et l›étiquette, je suis enfin libre !!"
  },
  AvgDialog_18768_Content_34 = {
    Text = "Avec une déclaration puissante, la jeune fille étendit grand les bras, soulevant le vaste ciel étoilé au-dessus de sa tête comme si elle le tenait entre ses mains."
  },
  AvgDialog_18768_Content_35 = {
    Text = "<Big:La liberté—!!>"
  },
  AvgDialog_18768_Content_36 = {
    Text = "Splash—!!"
  },
  AvgDialog_18768_Content_37 = {Text = "...Hein ?"},
  AvgDialog_18768_Content_38 = {
    Text = "Le ciel disparut, et le labyrinthe s'évanouit."
  },
  AvgDialog_18768_Content_39 = {
    Text = "La Gorge Cambrienne apparaît directement sous leurs yeux."
  },
  AvgDialog_18768_Content_4 = {Text = "Boum !"},
  AvgDialog_18768_Content_40 = {
    Text = "Le lac profond, tel un miroir, s'écoule paisiblement, le vent soufflant à la surface de l'eau et créant des ondulations de lumière."
  },
  AvgDialog_18768_Content_41 = {
    Text = "Agrippa était assis, hébété, sur l'herbe, contemplant d'un regard vide tout ce qui s'offrait à lui."
  },
  AvgDialog_18768_Content_42 = {
    Text = "%player%, est-ce qu'on est... sortis ?"
  },
  AvgDialog_18768_Content_43 = {
    Text = "Bienvenue de nouveau dans le monde réel, Agrippa."
  },
  AvgDialog_18768_Content_44 = {Text = "...Oh."},
  AvgDialog_18768_Content_45 = {
    Text = "Alors c'est ça, la Gorge. C'est cent fois plus beau que ce qu'on raconte, non, mille fois plus beau."
  },
  AvgDialog_18768_Content_46 = {
    Text = "La faible lueur de l'aube perce la brume et vient se poser sur votre corps."
  },
  AvgDialog_18768_Content_47 = {
    Text = "Agrippa ferma les yeux, savourant avidement ces parfums si longtemps oubliés."
  },
  AvgDialog_18768_Content_48 = {
    Text = "Je sens tant de choses. La terre, l'herbe, le freesia, et le soleil..."
  },
  AvgDialog_18768_Content_49 = {
    Text = "Est-ce que la lumière du soleil a un goût ?"
  },
  AvgDialog_18768_Content_5 = {
    Text = "Vous profitez du chaos pour renverser le pilier devant vous, faisant vaciller dangereusement tout le bâtiment."
  },
  AvgDialog_18768_Content_50 = {
    Text = "Hmm. Ce parfum donne envie de s'assoupir."
  },
  AvgDialog_18768_Content_51 = {
    Text = "Merci, %player%."
  },
  AvgDialog_18768_Content_52 = {
    Text = "Elle s'étira et fredonna doucement une ancienne mélodie romaine."
  },
  AvgDialog_18768_Content_53 = {
    Text = "Une mélodie légère tourbillonnait dans l'air, répandant la bonne humeur de sa propriétaire dans chaque recoin de la gorge."
  },
  AvgDialog_18768_Content_54 = {
    Text = "Après plus d'un millier d'années, elle revoyait enfin la lumière du soleil."
  },
  AvgDialog_18768_Content_55 = {
    Text = "Et découvrait enfin la gorge pour la première fois."
  },
  AvgDialog_18768_Content_6 = {
    Text = "Maintenant, suivez–moi vite !"
  },
  AvgDialog_18768_Content_7 = {
    Text = "Vous saisissez la main d'Agrippa et partez précipitamment avec sa famille."
  },
  AvgDialog_18768_Content_8 = {
    Text = "Cette cour autrefois incroyablement magnifique s'effondra telle une bête géante et silencieuse."
  },
  AvgDialog_18768_Content_9 = {
    Text = "16 ans avant le Déluge @1, périphérie de Kapua"
  },
  AvgDialog_18769_Content_1 = {
    Text = "Barrière de mémoire"
  },
  AvgDialog_18769_Content_10 = {
    Text = "Toi@1, qu›est-ce que tu dis—"
  },
  AvgDialog_18769_Content_11 = {
    Text = "Laisse tomber, ne te mêle pas à ce type. C›est juste un fou..."
  },
  AvgDialog_18769_Content_12 = {
    Text = "Les esclaves se bousculèrent en partant, et la cellule sombre retrouva enfin le silence."
  },
  AvgDialog_18769_Content_13 = {
    Text = "La fille sortit de l›ombre dans le coin de sa cellule, la tête baissée."
  },
  AvgDialog_18769_Content_14 = {
    Text = "Pourquoi ne pas partir avec eux ? Ce soir est ta chance de retrouver la liberté."
  },
  AvgDialog_18769_Content_15 = {
    Text = "Je me plais ici. Pourquoi partir ?"
  },
  AvgDialog_18769_Content_16 = {
    Text = "Tu te plais...? Haha, impressionnant. Tu préfères te faire insulter, ou tu aimes la caresse de mon fouet ?"
  },
  AvgDialog_18769_Content_17 = {
    Text = "Le gladiateur bâilla et s›étira confortablement."
  },
  AvgDialog_18769_Content_18 = {
    Text = "J›aime le sang, et j›aime encore plus tuer. Pour moi, tuer, c›est la liberté."
  },
  AvgDialog_18769_Content_19 = {
    Text = "Quant au titre d›esclave, peu m›importe combien vous m›en donnez. Pourquoi partir ?"
  },
  AvgDialog_18769_Content_2 = {
    Text = "16 ans avant le Grand Déluge, An 1, Capoue"
  },
  AvgDialog_18769_Content_20 = {Text = "新增"},
  AvgDialog_18769_Content_21 = {
    Text = "Heh... Maintenant je te vois sous un autre jour. Tu es un véritable fou."
  },
  AvgDialog_18769_Content_22 = {
    Text = "Agrippa leva les yeux vers la sortie du cachot, son expression extrêmement calme."
  },
  AvgDialog_18769_Content_23 = {
    Text = "Une vague cramoisie de feu déferla vers le ciel, accompagnée de rires, de pleurs et de hurlements... une symphonie de sons divers venus de l'Enfer."
  },
  AvgDialog_18769_Content_24 = {
    Text = "Bientôt, ils me trouveront, me @1, et me trancheront la tête, tout comme ils l'ont fait à mes parents."
  },
  AvgDialog_18769_Content_25 = {
    Text = "Je ne veux pas de ces créatures viles près de moi. Mais toi..."
  },
  AvgDialog_18769_Content_26 = {
    Text = "Tu es différent d'eux.\nJe sais que nous avons eu quelques «problèmes» auparavant, mais cette fois, tu ne refuseras certainement pas ma requête."
  },
  AvgDialog_18769_Content_27 = {
    Text = "Oh ? Dis-moi."
  },
  AvgDialog_18769_Content_28 = {Text = "新增"},
  AvgDialog_18769_Content_29 = {Text = "Tuez-moi."},
  AvgDialog_18769_Content_3 = {
    Text = "Bon sang, la femme a disparu."
  },
  AvgDialog_18769_Content_30 = {
    Text = "<RedBig:Tue-moi...>"
  },
  AvgDialog_18769_Content_31 = {
    Text = "Agrippa... ?"
  },
  AvgDialog_18769_Content_32 = {
    Text = "<RedBig:Tue-moi... tue-moi... tue-moi...>"
  },
  AvgDialog_18769_Content_33 = {Text = "Agrippa !"},
  AvgDialog_18769_Content_34 = {Text = "!!"},
  AvgDialog_18769_Content_35 = {
    Text = "<Shake:Ugh...>"
  },
  AvgDialog_18769_Content_36 = {
    Text = "J'ai fait un si long, si long rêve..."
  },
  AvgDialog_18769_Content_37 = {
    Text = "Écoute, il semble que nous ayons négligé certains problèmes tout à l'heure."
  },
  AvgDialog_18769_Content_38 = {
    Text = "N'importe quoi ! Je suis le puissant Seigneur du Labyrinthe, et tout est sous mon contrôle —"
  },
  AvgDialog_18769_Content_39 = {
    Text = "Premièrement, pourquoi ta progéniture peut-elle entrer et sortir librement du labyrinthe, mais pas toi et moi ?"
  },
  AvgDialog_18769_Content_4 = {
    Text = "Heh, alors maintenant tu te caches, c›est ça ? Une fois qu›on l›aura trouvée, on lui coupera les jambes d›abord..."
  },
  AvgDialog_18769_Content_40 = {
    Text = "Tu ne peux pas partager ta conscience ?"
  },
  AvgDialog_18769_Content_41 = {
    Text = "Qu'est-ce que tu en sais ? En tant que maître du labyrinthe, je dois toujours rester mystérieux."
  },
  AvgDialog_18769_Content_42 = {
    Text = "De plus, tant que je le souhaite, ils doivent tous revenir docilement. C'est ce que tu appelles un «libre accès» ?"
  },
  AvgDialog_18769_Content_43 = {
    Text = "Vous hochez la tête et sortez votre carnet une fois de plus."
  },
  AvgDialog_18769_Content_44 = {
    Text = "Encore une question."
  },
  AvgDialog_18769_Content_45 = {
    Text = "J'ai noté tous les endroits que j'ai rencontrés dans le labyrinthe : l'école, le musée de cire, et les rues de Londinium..."
  },
  AvgDialog_18769_Content_46 = {
    Text = "Aucun endroit que vous n'avez pas vécu. Pas un seul."
  },
  AvgDialog_18769_Content_47 = {
    Text = "Pourquoi, vous n'êtes pas piégé ici vous aussi ?"
  },
  AvgDialog_18769_Content_48 = {
    Text = "Pourquoi tant de « pourquoi » ? Parce que ce grand roi ne veut pas se souvenir ! Pourquoi s'embêter à penser à des choses désagréables ?"
  },
  AvgDialog_18769_Content_49 = {
    Text = "Oui, <Yellow:tu ne veux pas te souvenir>."
  },
  AvgDialog_18769_Content_5 = {
    Text = "Hé, Uvhash, as-tu vu Agrippa ?"
  },
  AvgDialog_18769_Content_50 = {
    Text = "Se pourrait-il que..."
  },
  AvgDialog_18769_Content_51 = {
    Text = "C'est précisément à cause de votre résistance — le rejet de la conscience partagée par le Maître du Labyrinthe — que ce labyrinthe, formé à partir des esprits des prisonniers, reste à jamais incomplet."
  },
  AvgDialog_18769_Content_52 = {
    Text = "Alors nous ne pourrons jamais sortir."
  },
  AvgDialog_18769_Content_53 = {Text = "新增"},
  AvgDialog_18769_Content_54 = {
    Text = "J'ai déjà réfléchi à ces questions. C'est mon labyrinthe."
  },
  AvgDialog_18769_Content_55 = {
    Text = "Rien que de penser au passé me rend fou..."
  },
  AvgDialog_18769_Content_56 = {
    Text = "Agrippa se prit la tête entre les mains, marmonnant rapidement comme dans un rêve."
  },
  AvgDialog_18769_Content_57 = {
    Text = "Ces misérables... Comment osent-ils me traiter ainsi..."
  },
  AvgDialog_18769_Content_58 = {
    Text = "Seulement une bande d'esclaves, pas même dignes d'être appelés humains, destinés à être piétinés par nous pour l'éternité."
  },
  AvgDialog_18769_Content_59 = {
    Text = "Rébellion ? Quelle fantaisie."
  },
  AvgDialog_18769_Content_6 = {
    Text = "Le gladiateur dans l›ombre ouvrit lentement les yeux."
  },
  AvgDialog_18769_Content_60 = {
    Text = "Mais ils ne se sont pas arrêtés là. Ils ont accroché les têtes de mes parents sur les remparts de la ville, m'ont attrapé par les cheveux et m'ont forcé à regarder chaque détail de près sans en manquer un seul."
  },
  AvgDialog_18769_Content_61 = {
    Text = "Et ma sœur, Yulia. Quand je l'ai trouvée, elle était couverte de @3, et elle était si petite..."
  },
  AvgDialog_18769_Content_62 = {
    Text = "Comme c'est ridicule... Vous pensiez vraiment que j'allais pleurer ?"
  },
  AvgDialog_18769_Content_63 = {
    Text = "Non, impossible. Je préférerais mourir plutôt que de verser une seule larme devant eux."
  },
  AvgDialog_18769_Content_64 = {
    Text = "Nous sommes les descendants des loups gris. Nous mourrons avec dignité, comme de vrais loups — quelque chose que ces chiens ne comprendront jamais."
  },
  AvgDialog_18769_Content_65 = {Text = "Hahaha..."},
  AvgDialog_18769_Content_66 = {
    Text = "Agrippa se tenait le ventre, riant jusqu'aux larmes."
  },
  AvgDialog_18769_Content_67 = {
    Text = "Ils ont dû être tellement déçus en voyant mon cadavre... Haha..."
  },
  AvgDialog_18769_Content_68 = {
    Text = "Agrippa...? Agrippa !"
  },
  AvgDialog_18769_Content_69 = {
    Text = "Vous agrippez fermement l'épaule d'Agrippa, essayant de la ramener des cauchemars du passé."
  },
  AvgDialog_18769_Content_7 = {
    Text = "... Dégagez."
  },
  AvgDialog_18769_Content_70 = {
    Text = "Tout ça, c'est du passé. Inutile d'en parler."
  },
  AvgDialog_18769_Content_71 = {Text = "新增"},
  AvgDialog_18769_Content_72 = {
    Text = "Désolé, Agrippa. Je ne savais pas avant... Laissons ces choses désagréables derrière nous."
  },
  AvgDialog_18769_Content_73 = {
    Text = "Tu es la maîtresse du labyrinthe ; rien ne peut véritablement te faire de mal."
  },
  AvgDialog_18769_Content_74 = {Text = "...Hmm."},
  AvgDialog_18769_Content_75 = {
    Text = "Agrippa est restée inhabituellement silencieuse ; il semble qu'elle ne soit pas encore sortie des ombres du passé."
  },
  AvgDialog_18769_Content_76 = {
    Text = "<LightGray:Si seulement nous pouvions changer le passé... Alors nous pourrions l'aider et échapper à cette situation.>"
  },
  AvgDialog_18769_Content_77 = {
    Text = "<LightGray:Non, ne perdons pas espoir. Essayons de trouver un autre moyen...>"
  },
  AvgDialog_18769_Content_78 = {
    Text = "Vous cherchez désespérément des informations utiles dans vos souvenirs fragmentés."
  },
  AvgDialog_18769_Content_79 = {
    Text = "Le Rêve ne peut pas changer le passé, mais il peut influencer le futur. C'est pourquoi les Gardiens du secret doivent apprendre à faire preuve de retenue lorsqu'ils rêvent."
  },
  AvgDialog_18769_Content_8 = {
    Text = "Heh, alors que tous les autres se battent pour une noble cause, tu es le seul à vouloir rester et jouer au chien fidèle."
  },
  AvgDialog_18769_Content_80 = {
    Text = "Influencer le futur ?"
  },
  AvgDialog_18769_Content_81 = {
    Text = "Par exemple, la mémoire humaine est comme un lac tranquille."
  },
  AvgDialog_18769_Content_82 = {
    Text = "Entrer dans un rêve, c'est comme jeter une pierre dans l'eau ; les ondulations disparaissent bientôt."
  },
  AvgDialog_18769_Content_83 = {
    Text = "Mais la pierre est toujours là."
  },
  AvgDialog_18769_Content_84 = {
    Text = "C'est exact. Même si la personne qui est entrée dans le rêve ne se souvient de rien après son réveil..."
  },
  AvgDialog_18769_Content_85 = {
    Text = "La pierre s›enfoncera à jamais dans son subconscient, affectant son présent."
  },
  AvgDialog_18769_Content_86 = {Text = "!!!"},
  AvgDialog_18769_Content_87 = {
    Text = "Agrippa, je connais la sortie."
  },
  AvgDialog_18769_Content_9 = {
    Text = "J›ai dit, « Dégagez. » Vous ne comprenez pas ?"
  },
  AvgDialog_18770_Content_1 = {
    Text = "Son Royaume"
  },
  AvgDialog_18770_Content_10 = {
    Text = "Inutile, inutile ! Même les mathématiciens, ces esprits brillants, ont été piégés dans le labyrinthe à l'époque !"
  },
  AvgDialog_18770_Content_11 = {
    Text = "Ne gaspille pas tes efforts sur des énigmes que personne ne peut résoudre."
  },
  AvgDialog_18770_Content_12 = {
    Text = "Si tu veux mon avis, puisque ni l'un ni l'autre ne peut tuer l'autre, autant bien s'entendre."
  },
  AvgDialog_18770_Content_13 = {
    Text = "Discutons ! Ou jouons aux cartes. Quels jeux de cartes connaissez-vous ?"
  },
  AvgDialog_18770_Content_14 = {
    Text = "Ne te fie pas à mon temps passé sous terre ; j'ai maîtrisé les jeux de cartes comme personne !"
  },
  AvgDialog_18770_Content_15 = {
    Text = "Tu dois admettre que ses mots t'ont un peu blessé."
  },
  AvgDialog_18770_Content_16 = {
    Text = "Si personne n'a résolu ce labyrinthe depuis tant d'années, qu'est-ce qui te fait croire que tu peux y arriver ?"
  },
  AvgDialog_18770_Content_17 = {
    Text = "Tu n'as pas l'esprit vif de Ramona."
  },
  AvgDialog_18770_Content_18 = {
    Text = "En pensant cela, tu t'effondres sur le coussin moelleux."
  },
  AvgDialog_18770_Content_19 = {
    Text = "Je ne suis pas très doué aux cartes. Et si on discutait plutôt ?\nComment as-tu fini piégé dans ce labyrinthe ?"
  },
  AvgDialog_18770_Content_2 = {
    Text = "39, 40, 41..."
  },
  AvgDialog_18770_Content_20 = {Text = "Euh..."},
  AvgDialog_18770_Content_21 = {
    Text = "Semblant ne pas s'attendre à ta question, les yeux multifacettes dans les orbites de la fille se figèrent tous un instant."
  },
  AvgDialog_18770_Content_22 = {
    Text = "Comme tu l'as dit, nous devons bien nous entendre. Ainsi, être honnête est la première étape."
  },
  AvgDialog_18770_Content_23 = {
    Text = "D'accord, d'accord... ! C'est juste une histoire banale."
  },
  AvgDialog_18770_Content_24 = {
    Text = "À l'époque, ma famille était la plus riche de Kapua, avec une file de serviteurs derrière moi à perte de vue..."
  },
  AvgDialog_18770_Content_25 = {
    Text = "Ensuite, ces imbéciles ont lancé une révolution, parlant de « libération » et de « liberté » — des choses que je ne comprends pas de toute façon."
  },
  AvgDialog_18770_Content_26 = {
    Text = "Je refuse de mourir de leurs mains ; qu'un gladiateur soit celui qui me tue."
  },
  AvgDialog_18770_Content_27 = {
    Text = "Agrippa parla, écartant les mains vers toi."
  },
  AvgDialog_18770_Content_28 = {
    Text = "...Quand je me suis réveillé, je me suis retrouvé ici."
  },
  AvgDialog_18770_Content_29 = {
    Text = "J'ai entendu parler de cette révolution en cours d'histoire. On dit que —"
  },
  AvgDialog_18770_Content_3 = {
    Text = "Vous notez rapidement dans le carnet de l'Aîné : <Blue:Dortoir des étudiants : 41>"
  },
  AvgDialog_18770_Content_30 = {
    Text = "Pas intéressé. Ce sujet est vraiment ennuyeux ! Change, change."
  },
  AvgDialog_18770_Content_31 = {
    Text = "Une heure plus tard..."
  },
  AvgDialog_18770_Content_32 = {
    Text = "La conversation sans intérêt se poursuivit jusqu'à ce qu'Agrippa ramène finalement le sujet sur lui-même."
  },
  AvgDialog_18770_Content_33 = {
    Text = "Tu savais ? J'ai maintenant plus d'un millier de descendants sous mes ordres..."
  },
  AvgDialog_18770_Content_34 = {
    Text = "Ils peuvent entrer et sortir librement du labyrinthe, recueillir des histoires du monde extérieur pour moi, et ramener des âmes malchanceuses aptes à devenir des rejetons."
  },
  AvgDialog_18770_Content_35 = {
    Text = "Sans eux, je serais mort d'ennui."
  },
  AvgDialog_18770_Content_36 = {
    Text = "Vous écoutez ses plaintes incessantes, et pour une raison quelconque, une scène vous vient à l'esprit—"
  },
  AvgDialog_18770_Content_37 = {
    Text = "Le roi vieillissant s'appuie sur sa canne, s'enfonçant profondément dans le trône décrépit et pesant."
  },
  AvgDialog_18770_Content_38 = {
    Text = "Son domaine est sans limites, et son autorité est incontestable."
  },
  AvgDialog_18770_Content_39 = {
    Text = "Il envoya de nombreux émissaires rapporter des récits de contrées lointaines : des yeux de chat émeraude, des éléphants disparus, et des arcs-en-ciel après la pluie..."
  },
  AvgDialog_18770_Content_4 = {
    Text = "Arrête de perdre du temps et viens jouer avec moi !"
  },
  AvgDialog_18770_Content_40 = {
    Text = "Quand l'émissaire arrive à un passage palpitant, il agite joyeusement les bras. Le roi, cependant, reste silencieux, tel une sculpture couverte de mousse."
  },
  AvgDialog_18770_Content_41 = {
    Text = "Il ne peut rien faire, car il ne peut plus quitter le trône, ne serait-ce que d'un seul pas."
  },
  AvgDialog_18770_Content_42 = {
    Text = "Agrippa, vous avez entendu tant d'histoires du monde extérieur... Y a-t-il un endroit où vous aimeriez aller ?"
  },
  AvgDialog_18770_Content_43 = {
    Text = "L'endroit où je voudrais aller..."
  },
  AvgDialog_18770_Content_44 = {
    Text = "La <Blue:Gorge Cambrienne> en fait partie."
  },
  AvgDialog_18770_Content_45 = {
    Text = "Agrippa répondit presque sans réfléchir."
  },
  AvgDialog_18770_Content_46 = {
    Text = "Ma progéniture m'a dit que le centre de ce labyrinthe semble se trouver sous une vallée appelée Cambrienne."
  },
  AvgDialog_18770_Content_47 = {
    Text = "J'ai entendu dire que c'est un endroit magnifique, avec des lacs aussi clairs que des miroirs."
  },
  AvgDialog_18770_Content_48 = {
    Text = "Chaque printemps, une fleur appelée freesia fleurit partout..."
  },
  AvgDialog_18770_Content_49 = {
    Text = "Agrippa pose son menton sur sa main, le regard perdu au loin."
  },
  AvgDialog_18770_Content_5 = {Text = "新增"},
  AvgDialog_18770_Content_50 = {
    Text = "Il y a aussi un beau lac dans ma ville natale, mais je ne l'ai jamais vu."
  },
  AvgDialog_18770_Content_51 = {
    Text = "Pourquoi ne pas aller y jeter un œil ?"
  },
  AvgDialog_18770_Content_52 = {
    Text = "Agrippa vous jeta un regard hautain, levant son petit menton pointu."
  },
  AvgDialog_18770_Content_53 = {
    Text = "Je suis une dame romaine de noble naissance, et une dame ne devrait pas se promener librement."
  },
  AvgDialog_18770_Content_54 = {
    Text = "Ainsi, vous pouvez commander de nombreux esclaves, et pourtant vous n'êtes pas entièrement libre vous-même."
  },
  AvgDialog_18770_Content_55 = {
    Text = "Vos paroles transpercent la réalité, et le visage de la jeune fille se décompose instantanément, comme une aubergine frappée par le gel."
  },
  AvgDialog_18770_Content_56 = {
    Text = "À cette époque, j'étais plus mal loti que ces esclaves. Sans parler de maintenant..."
  },
  AvgDialog_18770_Content_6 = {
    Text = "Désolé, tu pourrais changer de visage avant de me parler ?"
  },
  AvgDialog_18770_Content_7 = {
    Text = "Tss, quel radin !"
  },
  AvgDialog_18770_Content_8 = {
    Text = "William leva les yeux au ciel, puis disparut dans les airs avec un « bang »."
  },
  AvgDialog_18770_Content_9 = {
    Text = "Vous gardez la tête baissée, plongé dans les notes denses, essayant de trouver un moyen de percer le labyrinthe."
  },
  AvgDialog_18779_Content_1 = {
    Text = "C'est ça l'embryon ?"
  },
  AvgDialog_18779_Content_10 = {
    Text = "Il absorbe l'énergie de Nymiryam ?!\n Veut-il revenir encore une fois ?"
  },
  AvgDialog_18779_Content_11 = {
    Text = "C'est inutile. \n Il est protégé par le « placenta », et la puissance fournie par Miryam peut encore réparer le placenta au moins trois fois"
  },
  AvgDialog_18779_Content_12 = {
    Text = "Pour le détruire complètement, il faut attaquer directement le cœur"
  },
  AvgDialog_18779_Content_13 = {Text = "Noyau ?"},
  AvgDialog_18779_Content_14 = {
    Text = "Un cœur pâle incrusté dans un cocon transparent, à travers la lumière de la lune, l'ombre de «Lui» est vaguement visible"
  },
  AvgDialog_18779_Content_15 = {
    Text = "C'est le «faux» lui-même ?"
  },
  AvgDialog_18779_Content_16 = {Text = "Oui et non"},
  AvgDialog_18779_Content_17 = {
    Text = "Oui... Murphy ?"
  },
  AvgDialog_18779_Content_18 = {
    Text = "Ouais. Exactement!"
  },
  AvgDialog_18779_Content_19 = {
    Text = "Miryam a forcé l'accélération du rituel, mais « Il » naquit des mensonges et des désirs, et tant que les étoiles n'étaient pas en position, son existence ne serait pas reconnue par la réalité"
  },
  AvgDialog_18779_Content_2 = {
    Text = "Il semble s'être calmé"
  },
  AvgDialog_18779_Content_20 = {
    Text = "Avant la naissance, le noyau est toujours elle"
  },
  AvgDialog_18779_Content_3 = {
    Text = "Ce n'est pas fini."
  },
  AvgDialog_18779_Content_4 = {
    Text = "«Le cœur» a cessé de battre, mais le faible gémissement apporté par le vent marin est impossible à ignorer"
  },
  AvgDialog_18779_Content_5 = {
    Text = "Avez-vous entendu des pleurs ?"
  },
  AvgDialog_18779_Content_6 = {
    Text = "Les vagues se précipitent, le cocon géant s'élève soudainement sous le soutien de Miryam, s'élevant à la surface de la mer"
  },
  AvgDialog_18779_Content_7 = {
    Text = "Oui, comme ça"
  },
  AvgDialog_18779_Content_8 = {
    Text = "Prendre tout ce que vous voulez, pour votre naissance, pour punir ces infidèles"
  },
  AvgDialog_18779_Content_9 = {
    Text = "La voix de Miryam devient de plus en plus faible, mais l'entité dans le cocon dormant devient de plus en plus concrète"
  },
  AvgDialog_18784_Content_10 = {
    Text = "Quelle pitié, la simple perte du Lien d'Argent vous a réduite à un tel état."
  },
  AvgDialog_18784_Content_11 = {
    Text = "Le monstre des boules de pus ignore les moqueries de Lotan, se précipitant simplement vers l'ennemi en hurlant"
  },
  AvgDialog_18784_Content_12 = {
    Text = "<Change> Donne-la... à... moi..."
  },
  AvgDialog_18784_Content_13 = {
    Text = "Tant que je peux attraper cette fille... et devenir les Saintes Jumelles avec elle"
  },
  AvgDialog_18784_Content_14 = {
    Text = "Elle ne serait pas abandonnée, n'aurait pas à se lamenter sur ses origines, ni à devenir un pion manipulé par les autres"
  },
  AvgDialog_18784_Content_17 = {
    Text = "<Change>Remets-la... à moi!"
  },
  AvgDialog_18784_Content_18 = {
    Text = "As–tu aussi perdu la capacité de communiquer ?"
  },
  AvgDialog_18784_Content_19 = {
    Text = "Puisque c'est ainsi, mets tes mots et tes sentiments dans ton épée.\nFais-moi entendre ta colère !"
  },
  AvgDialog_18784_Content_2 = {
    Text = "<BigShake:GRRR——>"
  },
  AvgDialog_18784_Content_3 = {
    Text = "Après avoir avancé un moment dans l'obscurité, un monstre visqueux sort d'un trou de bridge, son énorme corps traînant de nombreuses boules collantes, tombant brusquement devant vous"
  },
  AvgDialog_18784_Content_4 = {
    Text = "Le monstre lève son torse à peine humanoïde et vous scrute, ses yeux se posant sur Lily, son expression devenant progressivement folle"
  },
  AvgDialog_18784_Content_6 = {
    Text = "Laissez-la... à moi !"
  },
  AvgDialog_18784_Content_7 = {
    Text = "Lotan s'est interposé devant vous, défiant le regard du monstre avec fierté"
  },
  AvgDialog_18784_Content_8 = {
    Text = "Les chaînes se brisent, les membres gonflent et se déforment, mais le visage sale sous les cheveux emmêlés prouve encore l'identité du corps"
  },
  AvgDialog_18784_Content_9 = {
    Text = ": Tu es... Hilote"
  },
  AvgDialog_18785_Content_1 = {
    Text = "Réalité tordue"
  },
  AvgDialog_18785_Content_10 = {
    Text = "À la lumière, elle voit que la peau lisse de la «mère» est couverte de nombreuses blessures noires"
  },
  AvgDialog_18785_Content_11 = {
    Text = "\"Je suis désolé...\""
  },
  AvgDialog_18785_Content_12 = {
    Text = "Le mucus noir bouillonnait, perturbant la tranquillité du fond"
  },
  AvgDialog_18785_Content_13 = {
    Text = "«La 'Mère' a poussé un cri aigu, ses tentacules se sont agités, insérant quelque chose dans la poitrine de l'oisillon.»"
  },
  AvgDialog_18785_Content_14 = {
    Text = "Les tentacules froids et glissants l'enveloppent, l'eau noire ne bloque plus son nez et sa bouche, mais, semblable au liquide amniotique, soutient sa vie"
  },
  AvgDialog_18785_Content_15 = {
    Text = "<Change>«Désolé......»\n«Je ne veux pas... mourir......»"
  },
  AvgDialog_18785_Content_16 = {
    Text = "La surface de l'eau reste calme pendant longtemps, même le vent hurlant de l'Arctique ne peut faire onduler l'eau épaisse"
  },
  AvgDialog_18785_Content_17 = {
    Text = "Miryam-sama, la Sainte a-t-elle déjà"
  },
  AvgDialog_18785_Content_18 = {
    Text = "Elle est née lors du dernier alignement des étoiles, elle est l'enfant «visible»"
  },
  AvgDialog_18785_Content_19 = {
    Text = "Personne ne mérite plus qu'elle la reconnaissance du sang divin"
  },
  AvgDialog_18785_Content_2 = {
    Text = "L'oisillon aux ailes brisées est tombé dans l'étang noir"
  },
  AvgDialog_18785_Content_20 = {
    Text = "La femme maigre est entourée, se tenant au sommet, dominant tout le monde.\nUn voile fin cache son visage, même ses proches ne peuvent lire ses pensées"
  },
  AvgDialog_18785_Content_21 = {Text = "Murphy..."},
  AvgDialog_18785_Content_3 = {
    Text = "Les prières murmurées du Grand Prêtre étaient flottantes mais solides, ses paroles ferventes perçaient le liquide noir, devenant des lames qui ouvraient la poitrine de l'oisillon"
  },
  AvgDialog_18785_Content_4 = {
    Text = "Un liquide écarlate monta de sa poitrine, s'épanouissant sombrement sur la surface calme de l'eau noire"
  },
  AvgDialog_18785_Content_5 = {
    Text = "Elle continuait de sombrer, les racines ensanglantées s'enfonçant dans les profondeurs, dans une étreinte douce et glaciale"
  },
  AvgDialog_18785_Content_6 = {Text = "新增"},
  AvgDialog_18785_Content_7 = {Text = "新增"},
  AvgDialog_18785_Content_8 = {
    Text = "Elle a vu.\nElle lève les yeux, et «mère» abaisse trois paires de stalks oculaires pour la regarder"
  },
  AvgDialog_18785_Content_9 = {
    Text = "C'était une énorme créature cramoisie, avec des zones transparentes là où le sang avait coulé. «Mother» émettait une faible lueur, éclairant temporairement un petit espace"
  },
  AvgDialog_18786_Content_1 = {
    Text = "Vidéo fondu en ouverture"
  },
  AvgDialog_18786_Content_2 = {
    Text = "Vidéo en boucle 1"
  },
  AvgDialog_18786_Content_3 = {
    Text = "Vidéo en boucle 2"
  },
  AvgDialog_18786_Content_4 = {
    Text = "Vidéo fondu"
  },
  AvgDialog_18786_Content_5 = {Text = "Rien"},
  AvgDialog_18787_Content_1 = {
    Text = "Mais il y a quelque chose de plus urgent maintenant"
  },
  AvgDialog_18787_Content_10 = {
    Text = "C'est la fille que Herbert poursuit, elle pourrait avoir des indices liés à votre enquête"
  },
  AvgDialog_18787_Content_11 = {
    Text = "Allons-y, qu'attendez-vous ?\nVous aimez vraiment passer la nuit dehors à hurler avec les loups ?"
  },
  AvgDialog_18787_Content_12 = {
    Text = "Si tu veux vivre à la dure, je suis toujours prêt, mais je crains que ton frêle corps ne le supporte pas"
  },
  AvgDialog_18787_Content_13 = {
    Text = "Lotan a tapé sur l'épaule arrière de Ramona, qui a affiché une expression comme si elle avait mangé une mouche, mais n'a rien dit"
  },
  AvgDialog_18787_Content_14 = {
    Text = "Dame Jonquille... ça sonne comme une personne riche qui fait preuve de bienveillance, n'est-ce pas ?"
  },
  AvgDialog_18787_Content_2 = {Text = "?"},
  AvgDialog_18787_Content_3 = {
    Text = "Si tu ne comptes pas utiliser la neige comme couverture, tu devrais réfléchir à où nous allons passer la nuit, Gardien"
  },
  AvgDialog_18787_Content_4 = {
    Text = "<Italic:Grand frère, grande sœur, venez-vous de très loin ?>"
  },
  AvgDialog_18787_Content_5 = {
    Text = "Une voix jeune interrompt votre conversation"
  },
  AvgDialog_18787_Content_6 = {
    Text = "Qui est là ?"
  },
  AvgDialog_18787_Content_7 = {
    Text = "La neige sur le mur reflète la lumière de la lune, et au centre se trouve une jeune fille plus blanche que la lumière de la lune"
  },
  AvgDialog_18787_Content_8 = {
    Text = "Si vous ne pouvez pas trouver d'endroit où rester, vous pouvez temporairement séjourner dans la chambre de <Blue:Dame jonquille>.\nC'est juste au coin de la rue."
  },
  AvgDialog_18787_Content_9 = {
    Text = "Tu fais un signe à Ramona, elle te répond par un regard affirmatif"
  },
  AvgDialog_18790_Content_1 = {
    Text = "Vous avez percé jusqu'à la proue du navire, mais avant de pouvoir regarder la mer, une nouvelle secousse a incliné le bateau"
  },
  AvgDialog_18790_Content_2 = {
    Text = "Le cargo monte et descend avec les vagues, quelque chose émerge de l'eau—"
  },
  AvgDialog_18790_Content_3 = {Text = "Murphy !"},
  AvgDialog_18790_Content_4 = {
    Text = "La tête de serpent s'accroche au corps de la jeune fille, Miryam ne peut que prier d'une voix rauque et indistincte"
  },
  AvgDialog_18790_Content_5 = {
    Text = "Ph'nglui mglw'nafh @3..."
  },
  AvgDialog_18790_Content_6 = {
    Text = "Elle a levé Murphy dans la lumière de la lune, et de petites mains noires et délicates ont émergé de la poitrine de la jeune fille, se tortillant et tissant, enveloppant son corps en un cocon noir géant"
  },
  AvgDialog_18790_Content_7 = {
    Text = "Dans un grondement sourd, les mains et les fils noirs prenaient Miryam comme support, enroulant le cocon étroitement autour de son immense corps"
  },
  AvgDialog_18790_Content_8 = {
    Text = "La coquille du cocon est devenue transparente à cause de l'expansion, des mains innombrables s'entrelacent pour former un trône, élevant un cœur pâle"
  },
  AvgDialog_18790_Content_9 = {
    Text = "Ph'nglui mglw'nafh @1'@2 wgah'nagl fhtagn!"
  },
  AvgDialog_18792_Content_1 = {
    Text = "Elle n'est qu'une gamine des bas-quartiers, elle ne sait rien et ne représente aucune menace pour vous..."
  },
  AvgDialog_18792_Content_10 = {
    Text = "Ennuyeux, j'ai mal aux mains. Tu veux mourir ici, 24 ?"
  },
  AvgDialog_18792_Content_11 = {
    Text = "Perdre un esclave obéissant comme toi, ça me fait pleurer~"
  },
  AvgDialog_18792_Content_12 = {
    Text = ": Désolé... Je ne quitterai pas cet endroit"
  },
  AvgDialog_18792_Content_14 = {Text = "Paf—!"},
  AvgDialog_18792_Content_15 = {
    Text = "Bientôt, le corps entier de 24 n'est plus qu'un amas ensanglanté. Pourtant, elle ne bouge pas d'un pouce, répétant les mêmes mots encore et encore."
  },
  AvgDialog_18792_Content_16 = {
    Text = "<Shake:Laissez-la partir...>"
  },
  AvgDialog_18792_Content_17 = {
    Text = "<Shake:Laisse-la partir...>"
  },
  AvgDialog_18792_Content_18 = {
    Text = "Si tu es capable, viens m'affronter, bande de déchets! Ne"
  },
  AvgDialog_18792_Content_19 = {
    Text = "<Bold:Ne frappe pas ma sœur...>"
  },
  AvgDialog_18792_Content_2 = {Text = "Paf—!"},
  AvgDialog_18792_Content_20 = {
    Text = "Mlle 24 ! Arrêtez... Ugh"
  },
  AvgDialog_18792_Content_21 = {
    Text = "<Small:Impossible... Je ne peux pas du tout bouger. Je dois trouver un moyen de sortir la clé en argent...>"
  },
  AvgDialog_18792_Content_22 = {
    Text = "Tellement maladroit ! Ne m'en veux pas d'être impitoyable~"
  },
  AvgDialog_18792_Content_23 = {
    Text = "Leigh, c'est le moment pour toi de briller"
  },
  AvgDialog_18792_Content_3 = {
    Text = "Le fouet s'abattit sans pitié, laissant une marque rouge sur le visage de 24"
  },
  AvgDialog_18792_Content_4 = {Text = "Hngh—!"},
  AvgDialog_18792_Content_5 = {
    Text = "24 se tenait devant Jenkins, ses omoplates maigres tremblant comme des ailes de papillon"
  },
  AvgDialog_18792_Content_6 = {
    Text = "Elle force un sourire, mais il est plus triste qu'un pleur"
  },
  AvgDialog_18792_Content_7 = {
    Text = "Mon seigneur, ayez pitié... Libérez-la, et je ferai tout..."
  },
  AvgDialog_18792_Content_8 = {Text = "Paf—!"},
  AvgDialog_18792_Content_9 = {
    Text = "Des coups innombrables tombent comme des gouttes de pluie."
  },
  AvgDialog_18795_Content_1 = {
    Text = "La pointe de l'épée perce l'énergie en forme d'écailles de serpent et frappe le point vital du serpent géant"
  },
  AvgDialog_18795_Content_10 = {
    Text = "King... Mon Seigneurs... Murphy... Murphy..."
  },
  AvgDialog_18795_Content_12 = {
    Text = "Maintenant... il y a encore une chance.\nRetourne à l'ordre, tu seras toujours la « Mère divine »"
  },
  AvgDialog_18795_Content_13 = {
    Text = "Votre enterrement sera la plus grande cérémonie de l'histoire du Royaume de Dieu, admirée par des dizaines de milliers... Votre nom sera également gravé dans les annales de l'histoire, transmis à travers les âges."
  },
  AvgDialog_18795_Content_14 = {
    Text = "Reviens à moi, ensemble... nous exécuterons cet <Blue:irrévérencieux>"
  },
  AvgDialog_18795_Content_15 = {
    Text = "Exécution... cet être impur déguisé en notre Seigneur !"
  },
  AvgDialog_18795_Content_16 = {
    Text = "Le grand serpent se dissipe puis se regroupe, sous l'impact de la force de Miryam, l'espace commence à se déformer et à se transformer"
  },
  AvgDialog_18795_Content_17 = {
    Text = "Miryam ! Je t'ordonne de t'arrêter !"
  },
  AvgDialog_18795_Content_18 = {
    Text = ": Faux dieux, imposteurs, blasphémateurs... sans @1@2... interdiction d'utiliser @3@4 !"
  },
  AvgDialog_18795_Content_19 = {
    Text = "À un moment donné, l'ombre couvrant la salle de puissance s'est solidifiée.  \nBâtiments déformés indescriptibles ont surgi du sol"
  },
  AvgDialog_18795_Content_2 = {
    Text = "Eh, eh ! Quelqu'un va tomber !"
  },
  AvgDialog_18795_Content_20 = {
    Text = "<Change>Personne impie... personne impie...... impie impie impie ▼▼▼▼▼▼▼▼!"
  },
  AvgDialog_18795_Content_21 = {
    Text = "Émettant des bruits aigus inintelligibles, miryam se tient les mains autour du cou, son corps se transforme et s'étire"
  },
  AvgDialog_18795_Content_22 = {
    Text = "Attention ! Elle perd le contrôle !"
  },
  AvgDialog_18795_Content_3 = {
    Text = "Tu tombes aussi dans le rugissement du serpent géant"
  },
  AvgDialog_18795_Content_4 = {
    Text = "——Puis, tu es tombé dans une étreinte tremblante et chaleureuse"
  },
  AvgDialog_18795_Content_5 = {
    Text = "...%player%."
  },
  AvgDialog_18795_Content_6 = {
    Text = "Suis-je au paradis ?"
  },
  AvgDialog_18795_Content_7 = {
    Text = "Désolé, nous sommes toujours sur le Sonaniel. Et le danger est imminent"
  },
  AvgDialog_18795_Content_8 = {
    Text = "<Small:Impardonnable...>"
  },
  AvgDialog_18795_Content_9 = {
    Text = "Attention ! Miryam a un mouvement suspect !"
  },
  AvgDialog_18796_Content_1 = {
    Text = "Ahem, ahem, salut tout le monde ! Aujourd'hui, nous allons tester l'effet de transition de Z1~"
  },
  AvgDialog_18796_Content_10 = {
    Text = "Convient pour passer rapidement à des scènes plus sombres."
  },
  AvgDialog_18796_Content_11 = {
    Text = "Ouf... Épuisé, pas besoin de le dire. Après le numéro 4, c'est bien sûr le numéro 5 !"
  },
  AvgDialog_18796_Content_12 = {
    Text = "Mmm... en gros, la transition numéro 5 est la plus utilisée, elle convient à de nombreuses situations"
  },
  AvgDialog_18796_Content_13 = {
    Text = "D'accord, passons à la dernière transition—numéro 6, s'il vous plaît !"
  },
  AvgDialog_18796_Content_14 = {
    Text = "C'est la plus longue transition de toutes~"
  },
  AvgDialog_18796_Content_15 = {
    Text = "Voilà tous les effets de transition. Tout le monde a compris ?"
  },
  AvgDialog_18796_Content_16 = {
    Text = "À la prochaine fois ♡"
  },
  AvgDialog_18796_Content_2 = {
    Text = "Maintenant, le changement de scène numéro 1 - changement de scène gauche-droite~ !!"
  },
  AvgDialog_18796_Content_3 = {
    Text = "Tada tada tada ! N'est-ce pas magnifique ?"
  },
  AvgDialog_18796_Content_4 = {
    Text = "Cette transition est généralement utilisée pour passer d'une scène à une autre dans le même environnement"
  },
  AvgDialog_18796_Content_5 = {
    Text = "Ensuite, transition numéro 2—"
  },
  AvgDialog_18796_Content_6 = {
    Text = "Cette transition est généralement utilisée pour passer à une scène plus lumineuse"
  },
  AvgDialog_18796_Content_7 = {
    Text = "Puis... Scène 3 !"
  },
  AvgDialog_18796_Content_8 = {
    Text = "La 3e transition convient aussi aux scènes lumineuses, mais le rythme est un peu plus lent, hihi"
  },
  AvgDialog_18796_Content_9 = {
    Text = "Le prochain à venir est——scène 4 !"
  },
  AvgDialog_18797_Content_1 = {
    Text = "Mi...@1... ouh"
  },
  AvgDialog_18797_Content_10 = {
    Text = "Tu n'es pas le «Roi-Dieu» !"
  },
  AvgDialog_18797_Content_11 = {
    Text = "Après tout, vous êtes celui que Miryam sert, cette prophétie de la résurrection du dieu est donc de votre fait, non ?"
  },
  AvgDialog_18797_Content_12 = {Text = "Vous..."},
  AvgDialog_18797_Content_13 = {
    Text = "Je viens de voir... à travers le lien, j'ai vu tes souvenirs"
  },
  AvgDialog_18797_Content_14 = {Text = "...Oui."},
  AvgDialog_18797_Content_15 = {
    Text = "C'est ma prophétie, mais il n'y a pas de «divination»"
  },
  AvgDialog_18797_Content_16 = {Text = "Quoi ?"},
  AvgDialog_18797_Content_17 = {
    Text = "Bien avant l'arrivée de ce déluge, j'avais perdu la capacité d'entrevoir l'avenir à travers les rêves divins.\nJe ne sais pas où Il est parti, peut-être qu’Il s’est réveillé, ou peut-être qu’Il est parti"
  },
  AvgDialog_18797_Content_18 = {
    Text = "Et ta prophétie"
  },
  AvgDialog_18797_Content_19 = {
    Text = "Miryam est une croyante dévouée, née pour le Royaume Divin et poussée par Ma volonté."
  },
  AvgDialog_18797_Content_2 = {
    Text = "Murphy laissa échapper un gémissement de douleur, ses murmures étaient incohérents"
  },
  AvgDialog_18797_Content_20 = {
    Text = "Je n'avais espéré que mes mots lui apportent du réconfort dans ses derniers moments, sans jamais m'attendre à ce qu'elle les prenne pour l'Évangile et cherche à reconstruire le Royaume Divin."
  },
  AvgDialog_18797_Content_21 = {Text = "Tout cela"},
  AvgDialog_18797_Content_22 = {
    Text = "Oui, tout cela est de ma faute"
  },
  AvgDialog_18797_Content_23 = {
    Text = "Compte à rebours 60 minutes"
  },
  AvgDialog_18797_Content_3 = {
    Text = "! Qu'est-ce que c'est ?!"
  },
  AvgDialog_18797_Content_4 = {
    Text = "Des marques effrayantes bleu-noir apparaissent sur le visage de Murphy, s'enfonçant dans sa peau comme des racines de plantes"
  },
  AvgDialog_18797_Content_5 = {
    Text = "Il commence à bloquer le flux sanguin de l'hôte"
  },
  AvgDialog_18797_Content_6 = {
    Text = "N'avez-vous pas dit qu'il suffisait de s'éloigner des corps célestes ?"
  },
  AvgDialog_18797_Content_7 = {
    Text = "Je veux dire, elle pourrait se sentir moins mal"
  },
  AvgDialog_18797_Content_8 = {
    Text = "Le corps céleste est en orbite, il n'y a plus de retour possible"
  },
  AvgDialog_18797_Content_9 = {
    Text = "N'y a-t-il vraiment aucun moyen ?"
  },
  AvgDialog_18798_Content_1 = {
    Text = "Ouf... Ouf... Rien en haut, rien en bas"
  },
  AvgDialog_18798_Content_10 = {
    Text = "Murphy s'effondra contre le bastingage, glissant sur le pont, oubliant toute posture de dame"
  },
  AvgDialog_18798_Content_11 = {
    Text = "Elle chercha un appui pour ne pas tomber, et après quelques tâtonnements, se reposa sur ton épaule"
  },
  AvgDialog_18798_Content_12 = {
    Text = "Juste un moment..."
  },
  AvgDialog_18798_Content_13 = {
    Text = "Quelques secondes plus tard, une respiration rapide et régulière se fit entendre.\nMurphy perdit à nouveau connaissance"
  },
  AvgDialog_18798_Content_14 = {
    Text = "Elle s'affaiblit..."
  },
  AvgDialog_18798_Content_15 = {
    Text = "Le dieu que je connecte vient des étoiles innombrables, même une imitation ne peut être résistée par les humains"
  },
  AvgDialog_18798_Content_16 = {
    Text = "N'y a-t-il pas de remède ?"
  },
  AvgDialog_18798_Content_17 = {
    Text = "......Emmenez-la"
  },
  AvgDialog_18798_Content_18 = {
    Text = "Éviter les astres pourrait lui faire du bien"
  },
  AvgDialog_18798_Content_2 = {
    Text = "Ils... où sont-ils ?"
  },
  AvgDialog_18798_Content_3 = {
    Text = "<Small:Je déteste ça... ce bateau est si grand...>"
  },
  AvgDialog_18798_Content_4 = {Text = "Ça va ?"},
  AvgDialog_18798_Content_5 = {
    Text = "Je vais très bien ! Tousse, tousse..."
  },
  AvgDialog_18798_Content_6 = {
    Text = "Murphy répondit à haute voix, mais s'étouffa et se mit à tousser violemment"
  },
  AvgDialog_18798_Content_7 = {
    Text = "Mais je suis très fatigué, et j'ai un peu mal à la tête"
  },
  AvgDialog_18798_Content_8 = {
    Text = "En parlant, vous vous assîtes"
  },
  AvgDialog_18798_Content_9 = {
    Text = "Repose-toi un peu... juste un peu"
  },
  AvgDialog_18802_Content_1 = {
    Text = "Si j'étais plus fort, si je pouvais toujours lui résister...\nMais je ne peux pas, je ne peux pas"
  },
  AvgDialog_18802_Content_10 = {
    Text = "Désolé... désolé... c'est ma faute"
  },
  AvgDialog_18802_Content_11 = {
    Text = "Je suis un monstre inutile, j'ai tué tant de gens et je n'ai pas pu sauver la sœur de Jenkins"
  },
  AvgDialog_18802_Content_12 = {
    Text = "Elle a été emmenée, elle a été emmenée, mais je ne sais même pas où elle est allée...\nJe ne sais même pas qui nous contrôle"
  },
  AvgDialog_18802_Content_13 = {
    Text = "Ramona s'agenouilla devant Aigis et prit doucement la fille dans ses bras"
  },
  AvgDialog_18802_Content_14 = {
    Text = "Tu as déjà fait beaucoup d'efforts, Aigis. Ce n'est pas de ta faute"
  },
  AvgDialog_18802_Content_15 = {
    Text = "C'était le véritable Jack l'Éventreur, celui qui vous manipulait pour commettre ces crimes.\nCe n'était jamais ta faute"
  },
  AvgDialog_18802_Content_16 = {
    Text = "La fille se jeta dans les bras de Ramona en pleurant, mais sa main droite ne quitta pas son œil"
  },
  AvgDialog_18802_Content_17 = {
    Text = "Nous allons trouver cette personne."
  },
  AvgDialog_18802_Content_18 = {
    Text = [[
Nous le trouverons et il paiera.
Je te le jure]]
  },
  AvgDialog_18802_Content_19 = {
    Text = "Merci, merci à vous... Merci à vous"
  },
  AvgDialog_18802_Content_2 = {
    Text = "La dernière fois que j'ai résisté, c'était... c'était... je ne pouvais pas, snif snif"
  },
  AvgDialog_18802_Content_20 = {
    Text = "Les rayons dorés du coucher de soleil traversaient la grande horloge transparente du clocher, illuminant la fille"
  },
  AvgDialog_18802_Content_21 = {
    Text = "Aigis se tourne sur le côté, pose une main sur la vitre et plisse les yeux face au soleil chaleureux"
  },
  AvgDialog_18802_Content_22 = {
    Text = "Aujourd'hui, on peut voir le soleil"
  },
  AvgDialog_18802_Content_24 = {
    Text = "Comme excitée par le rare beau temps, elle se leva et marcha en titubant vers une vitre plus propre"
  },
  AvgDialog_18802_Content_25 = {
    Text = "La vision floue devient enfin claire. Elle regarde les rues familières ou étrangères, et entend un murmure à son oreille"
  },
  AvgDialog_18802_Content_26 = {
    Text = "Regarde, cette voix disait qu'on verrait un ciel étoilé ce soir"
  },
  AvgDialog_18802_Content_28 = {
    Text = "La fille baisse la tête, affichant un sourire nostalgique"
  },
  AvgDialog_18802_Content_29 = {
    Text = "Avant, chaque jour ensoleillé, Tiyoug me faisait monter la nuit en cachette"
  },
  AvgDialog_18802_Content_3 = {
    Text = "Arrête ça, ne me force plus à faire ça"
  },
  AvgDialog_18802_Content_30 = {
    Text = "Mademoiselle Sarah ne nous a jamais permis de venir ici, elle disait que c'était trop dangereux et que nous pourrions facilement nous blesser. Mais Tiyug s'en moque"
  },
  AvgDialog_18802_Content_31 = {
    Text = "Il a une excellente vue, même dans l'obscurité, il voit clairement le chemin"
  },
  AvgDialog_18802_Content_32 = {
    Text = "Comme Jenkins, il est malin et courageux, connaissant toujours les chemins et mécanismes secrets"
  },
  AvgDialog_18802_Content_33 = {
    Text = "Tant qu'il est avec nous, Mlle Sarah ne nous découvrira pas"
  },
  AvgDialog_18802_Content_34 = {
    Text = "Tant qu'il me guide, cet endroit reste notre base secrète"
  },
  AvgDialog_18802_Content_35 = {
    Text = "Il m'a dit que je devais me connecter davantage aux étoiles pour renforcer ma magie.\nMais ici, on ne voit aucune étoile"
  },
  AvgDialog_18802_Content_36 = {
    Text = "À ce moment-là, il était le seul à me croire.\nIl croyait que je pouvais voir ces choses noires, me disant que c'était un don de sorcière"
  },
  AvgDialog_18802_Content_37 = {
    Text = "Plus tard, il... après cela, les médecins ont commencé à emmener les patients à l'extérieur et ont cessé de consulter à l'hôpital de charité. Je n'avais aucun moyen de recueillir des preuves, aucun moyen de venger Tiyug"
  },
  AvgDialog_18802_Content_38 = {
    Text = "Si j'étais aussi intelligent que lui, aussi courageux que Jenkins, j'aurais probablement découvert la vérité depuis longtemps"
  },
  AvgDialog_18802_Content_39 = {
    Text = "Mais je ne suis pas une sorcière"
  },
  AvgDialog_18802_Content_4 = {
    Text = ": Je ne veux blesser personne, je ne veux pas tuer"
  },
  AvgDialog_18802_Content_40 = {
    Text = "Je suis juste un lâche"
  },
  AvgDialog_18802_Content_41 = {Text = "Un monstre"},
  AvgDialog_18802_Content_42 = {
    Text = "Un... meurtrier."
  },
  AvgDialog_18802_Content_43 = {
    Text = "Savez-vous combien de fois j'ai été manipulé ?\nSavez-vous combien de sang j'ai sur les mains ?"
  },
  AvgDialog_18802_Content_44 = {
    Text = "J'ai terriblement peur de ce que je vais devenir"
  },
  AvgDialog_18802_Content_46 = {
    Text = "Mes yeux et mon corps me faisaient mal, mais maintenant je ne ressens plus rien, comme si j'étais fait de pierre"
  },
  AvgDialog_18802_Content_48 = {
    Text = "Merde, où sont-ils tous passés"
  },
  AvgDialog_18802_Content_49 = {Text = "C'est..."},
  AvgDialog_18802_Content_5 = {
    Text = "<Shake:<AvgNormalFont:Non ! Ne le fais pas !\nNe laisse pas Little Mac faire ça, il est trop petit, comment pourrait-il...<Shake:Je t'en supplie...>>>"
  },
  AvgDialog_18802_Content_50 = {
    Text = "Aigis ?! Aigis— !"
  },
  AvgDialog_18802_Content_51 = {
    Text = "La voix de Jenkins retentit soudainement sous le clocher, elle est apparue dans la cour"
  },
  AvgDialog_18802_Content_52 = {
    Text = "Elle cria désespérément le nom d'Aigis, levant les bras vers le ciel"
  },
  AvgDialog_18802_Content_53 = {
    Text = "Le petit corps de la fille disparaît à jamais dans la nuit en tombant"
  },
  AvgDialog_18802_Content_54 = {
    Text = "Un oiseau vole à travers le ciel nocturne, disparaissant dans le brouillard épais sans laisser de trace."
  },
  AvgDialog_18802_Content_55 = {
    Text = "Jenkins tendit les bras, tenant simplement avec confusion les robes vides d'Aigis, et des morceaux de papier carré tombèrent comme des flocons de neige"
  },
  AvgDialog_18802_Content_56 = {
    Text = [[
Euh... Aigis... ? 
Comment... cela peut-il]]
  },
  AvgDialog_18802_Content_57 = {
    Text = "Un papillon doré est dessiné sur le papier, les bords froissés sont soigneusement aplatis, et en tombant, il dégage une douce odeur de bonbon"
  },
  AvgDialog_18802_Content_58 = {
    Text = "Ouh... Aigis"
  },
  AvgDialog_18802_Content_59 = {
    Text = "Un ruban ensanglanté tombe dans la main de la fille avec un papier de bonbon, flottant doucement comme une caresse"
  },
  AvgDialog_18802_Content_6 = {
    Text = "Je n'entends pas, je n'entends pas, je n'entends pas, je n'entends pas, je n'entends pas—"
  },
  AvgDialog_18802_Content_60 = {
    Text = "La fille cligna des yeux, les larmes brouillant sa vue tombèrent de ses cils, silencieusement recueillies par le rouge vif"
  },
  AvgDialog_18802_Content_61 = {
    Text = "Cette couleur familière, cette texture familière... Il ne manque qu'une boucle argentée pour correspondre parfaitement à ses souvenirs"
  },
  AvgDialog_18802_Content_62 = {
    Text = "...Sœur... ?"
  },
  AvgDialog_18802_Content_7 = {
    Text = "Réussi ?\nCours, vite, mais s'il te plaît, ne dis rien à personne"
  },
  AvgDialog_18802_Content_8 = {
    Text = "<Shake:<AvgNormalFont:Attends, non, c'est quoi ça ! Ma tête, ma tête... \nAh... Ahhh... ! <Shake:Ahhh—!!>>>"
  },
  AvgDialog_18802_Content_9 = {
    Text = "Désolé... désolé"
  },
  AvgDialog_18804_Content_1 = {
    Text = "Un gardien digne de ce nom, dépouillé par quelques enfants ordinaires. Une année d'entraînement gâchée. Même les nouveaux élèves des écoles publiques sont plus malins que toi"
  },
  AvgDialog_18804_Content_2 = {
    Text = "Heureusement que le voleur était aussi sur le lieu de la mission, sinon, tu aurais été malchanceux. Je ne te permettrai pas de perdre du temps de mission pour des affaires personnelles"
  },
  AvgDialog_18804_Content_3 = {
    Text = "Ce n'est pas si grave, poupée, donnez un peu confiance à %player%"
  },
  AvgDialog_18804_Content_4 = {
    Text = "Et ne perturbe pas l'enquête des gardiens du secret"
  },
  AvgDialog_18805_Content_1 = {
    Text = "Un gardien digne de ce nom, dépouillé par quelques enfants ordinaires. Une année d'entraînement gâchée. Même les nouveaux élèves des écoles publiques sont plus malins que toi"
  },
  AvgDialog_18805_Content_2 = {
    Text = "Heureusement que le voleur était aussi sur le lieu de la mission, sinon, tu aurais été malchanceux. Je ne te permettrai pas de perdre du temps de mission pour des affaires personnelles"
  },
  AvgDialog_18805_Content_3 = {
    Text = "Ce n'est pas si grave, poupée, donnez un peu confiance à %player%"
  },
  AvgDialog_18805_Content_4 = {
    Text = "Et ne perturbe pas l'enquête des gardiens du secret"
  },
  AvgDialog_18808_Content_1 = {
    Text = "C'est un test de dialogue sans contexte 1"
  },
  AvgDialog_18808_Content_2 = {
    Text = "C'est un test de dialogue sans contexte 2"
  },
  AvgDialog_18809_Content_1 = {
    Text = "Murphy ne fit pas de manières, tirant Ramona à l'écart et commençant à se déshabiller.\nAvec le dernier bouton défait, Ramona vit le «dieu» en elle"
  },
  AvgDialog_18809_Content_2 = {
    Text = "Il y a une peau transparente sur la poitrine, tirant la peau et les muscles environnants, rendant toute la cavité thoracique grisâtre et dégradée"
  },
  AvgDialog_18809_Content_3 = {
    Text = "Une telle anomalie révélant les organes dans la poitrine, Ramona a vu un jeune cœur rouge pâle et un «œuf» blanc laiteux"
  },
  AvgDialog_18809_Content_4 = {
    Text = "Des centaines de filaments s'étendent de « l'œuf », s'enroulant étroitement autour des vaisseaux sanguins de Murphy, dépendants les uns des autres"
  },
  AvgDialog_18809_Content_5 = {
    Text = "Si son existence n'avait pas déjà comprimé le cœur de Murphy, il semblerait même faire partie intégrante de la cage thoracique transparente, comme s'il n'était pas un corps étranger"
  },
  AvgDialog_18809_Content_6 = {
    Text = "Il est chaotique et silencieux, l'inversion triangulaire noire gravée en lui se fige aussi, tel une étrange œuvre d'art"
  },
  AvgDialog_18809_Content_7 = {
    Text = "Érosion... Cet objet est déjà érodé"
  },
  AvgDialog_18809_Content_8 = {
    Text = "Vous en avez assez vu ?"
  },
  AvgDialog_18809_Content_9 = {
    Text = "Désolé, c'était impoli de ma part, remets tes vêtements"
  },
  AvgDialog_18810_Content_1 = {
    Text = "Compte à rebours 20 minutes"
  },
  AvgDialog_18810_Content_10 = {
    Text = "Attention ! Ne tombe pas à l'eau !"
  },
  AvgDialog_18810_Content_11 = {
    Text = "Un énorme serpent émergea de la mer, manquant de renverser le navire.\nPlusieurs têtes de serpent se tordaient, projetant des ombres terrifiantes sur le pont"
  },
  AvgDialog_18810_Content_12 = {
    Text = "Usurpateur... Impoli... Imbécile !"
  },
  AvgDialog_18810_Content_13 = {
    Text = "Mère divine... Mère divine...@3!"
  },
  AvgDialog_18810_Content_14 = {
    Text = "Oh non, c'est Miryam !"
  },
  AvgDialog_18810_Content_15 = {
    Text = "Emmène Murphy !"
  },
  AvgDialog_18810_Content_16 = {Text = "Ah !!"},
  AvgDialog_18810_Content_17 = {
    Text = "Vous regardez à nouveau le pont ; Murphy n'est plus là. Une énorme tête de serpent a saisi la fille et l'a traînée dans Aequor."
  },
  AvgDialog_18810_Content_2 = {
    Text = "Lien ? Est-ce que cela signifie qu'elle doit compter sur toi pour vivre par la suite ?"
  },
  AvgDialog_18810_Content_3 = {
    Text = "C'est juste une mesure temporaire, nous n'avons pas l'intention de prendre Mademoiselle Céleste de vos mains"
  },
  AvgDialog_18810_Content_4 = {
    Text = "Ce n'est pas à moi de décider"
  },
  AvgDialog_18810_Content_5 = {
    Text = "Céleste, es-tu prête ?"
  },
  AvgDialog_18810_Content_6 = {
    Text = "Comme si le mot-clef avait été activé, Céleste a levé la tête, mais a regardé la mer derrière elle, et la navigation s'est également arrêtée"
  },
  AvgDialog_18810_Content_7 = {
    Text = "Le bateau ne bouge plus"
  },
  AvgDialog_18810_Content_8 = {
    Text = "Quelque chose m'a attrapé"
  },
  AvgDialog_18810_Content_9 = {
    Text = "À peine avait-elle fini de parler que le sol a commencé à trembler violemment, le navire s'inclinant à un angle incroyable"
  },
  AvgDialog_18812_Content_1 = {
    Text = "Même vous... Une bande d'adultes égoïstes"
  },
  AvgDialog_18812_Content_10 = {
    Text = "Une lumière trop éblouissante blesse les yeux, provoquant des larmes incontrôlables"
  },
  AvgDialog_18812_Content_11 = {
    Text = "Ça... c'est ?!"
  },
  AvgDialog_18812_Content_12 = {
    Text = "Le liquide trouble s'est écoulé, les yeux peuvent enfin se concentrer à nouveau sur la jeune fille"
  },
  AvgDialog_18812_Content_13 = {
    Text = "La lame s'enfonce profondément dans la poitrine, la jeune fille baignée de lumière lunaire ouvre les yeux"
  },
  AvgDialog_18812_Content_14 = {
    Text = "La pleine lune symbolisant la mort est proche, mais le visage jeune ne montre aucune peur"
  },
  AvgDialog_18812_Content_15 = {
    Text = "Je... l'ai percé... Il ne naîtra pas..."
  },
  AvgDialog_18812_Content_16 = {Text = "Ainsi"},
  AvgDialog_18812_Content_17 = {
    Text = "La main serrant le manche du couteau tomba mollement, un liquide rouge, visqueux et noir s'écoulant de la lame et se répandant dans la mer"
  },
  AvgDialog_18812_Content_18 = {
    Text = "Le sang s'écoulait rapidement de son corps, la peau pâle mais dégageant une étrange vitalité"
  },
  AvgDialog_18812_Content_19 = {
    Text = "Non... non, non, non, non ah ah ah—"
  },
  AvgDialog_18812_Content_2 = {
    Text = "Personne ne m'a jamais demandé mon avis... Hmph"
  },
  AvgDialog_18812_Content_20 = {
    Text = "Dieu tout-puissant, pardonnez-moi, pardonnez cet enfant, pardonnez votre fidèle croyant"
  },
  AvgDialog_18812_Content_21 = {
    Text = "Le moment d'alignement, le moment d'alignement arrivera, arrivera"
  },
  AvgDialog_18812_Content_22 = {
    Text = "«Placenta» se brise, le « cœur » s'effondre - d'innombrables mains émergent, écrasant la poitrine de la jeune fille"
  },
  AvgDialog_18812_Content_23 = {
    Text = "La main difforme serre les restes méconnaissables, se superposant, gonflant, se superposant, gonflant——"
  },
  AvgDialog_18812_Content_24 = {
    Text = "Ah... Vous m'avez entendu... Vous m'avez répondu..."
  },
  AvgDialog_18812_Content_25 = {
    Text = "Ils ont poussé une existence difforme sous la lumière de la lune"
  },
  AvgDialog_18812_Content_26 = {
    Text = "Mon grand Dieu... !"
  },
  AvgDialog_18812_Content_3 = {
    Text = "Une vie obtenue par le sacrifice... qui en voudrait ?"
  },
  AvgDialog_18812_Content_4 = {
    Text = "Non, le placenta est trop trouble.\nPeut-on voir à l'intérieur avec la «rétrovision mentale» ?"
  },
  AvgDialog_18812_Content_5 = {
    Text = "Tu as serré la clé en argent tremblante, replongeant à nouveau dans l'espace de ta conscience"
  },
  AvgDialog_18812_Content_6 = {
    Text = "Dans l'espace couvert par la d-boue, la lueur symbolisant la vie et l'intelligence devient particulièrement éclatante"
  },
  AvgDialog_18812_Content_7 = {
    Text = "——C'était un couteau rituel reflétant la lumière froide de la lune"
  },
  AvgDialog_18812_Content_8 = {
    Text = "——Mm !!"
  },
  AvgDialog_18812_Content_9 = {
    Text = "La lumière a éclaté soudainement, vous expulsant de force du monde des esprits"
  },
  AvgDialog_18813_Content_1 = {
    Text = "Ce qui va suivre est un effet de transition, ralentissement du temps, test"
  },
  AvgDialog_18813_Content_10 = {
    Text = "Tempête de sable 2"
  },
  AvgDialog_18813_Content_11 = {
    Text = "Fin du test"
  },
  AvgDialog_18813_Content_12 = {
    Text = "Ensuite, test de l'effet d'écran secousse continue"
  },
  AvgDialog_18813_Content_13 = {
    Text = "Début du test"
  },
  AvgDialog_18813_Content_16 = {
    Text = "Fin du test"
  },
  AvgDialog_18813_Content_17 = {
    Text = "Ensuite, test de l'effet d'écran activation de la clé d'argent"
  },
  AvgDialog_18813_Content_18 = {
    Text = "Début du test"
  },
  AvgDialog_18813_Content_19 = {
    Text = "Fin du test, mais je vais commencer directement l'effet spécial de la clé d'argent [effet d'écran] Test"
  },
  AvgDialog_18813_Content_2 = {
    Text = "Début du test"
  },
  AvgDialog_18813_Content_20 = {
    Text = "Début du test"
  },
  AvgDialog_18813_Content_21 = {Text = "En cours"},
  AvgDialog_18813_Content_22 = {
