  },
  AvgDialog_18813_Content_26 = {Text = "Terminé"},
  AvgDialog_18813_Content_3 = {
    Text = "Fin du test"
  },
  AvgDialog_18813_Content_4 = {
    Text = "Ensuite, test de la transition rapide du temps"
  },
  AvgDialog_18813_Content_5 = {
    Text = "Début du test"
  },
  AvgDialog_18813_Content_6 = {
    Text = "Fin du test"
  },
  AvgDialog_18813_Content_7 = {
    Text = "Ensuite, test de l'effet d'écran tempête de sable"
  },
