  },
  AvgDialog_62169_Content_1 = {
    Text = "La statue se relâche... Je vais utiliser la musique pour t'aider à te connecter avec Ramona. Ferme les yeux et appelle-la avec ton esprit."
  },
  AvgDialog_62169_Content_10 = {
    Text = "Ramona, attends-moi !"
  },
